module Runtime_retirement = struct
  type outcome =
    ((unit, Agent_protocol.Error.t) result, exn * Stdlib.Printexc.raw_backtrace) result

  type t = outcome Eio.Promise.t

  let is_finished t = Option.is_some (Eio.Promise.peek t)

  let is_successful t =
    match Eio.Promise.peek t with
    | Some (Ok (Ok ())) -> true
    | None | Some (Ok (Error _) | Error _) -> false
  ;;

  let await t =
    match Eio.Promise.await t with
    | Ok result -> result
    | Error (exn, backtrace) -> Exn.raise_with_original_backtrace exn backtrace
  ;;
end

(* Immutable observations contain no mutable target or execution authority. *)
module Retirement_cleanup_observation = struct
  module Failure = struct
    type t =
      | Protocol of Agent_protocol.Error.t
      | Raised of exn * Stdlib.Printexc.raw_backtrace

    let capture f =
      match f () with
      | Ok value -> Ok value
      | Error failure -> Error (Protocol failure)
      | exception exn -> Error (Raised (exn, Stdlib.Printexc.get_raw_backtrace ()))
    ;;

    let of_reply = function
      | Actor_reply.Returned result -> Result.map_error result ~f:(fun e -> Protocol e)
      | Actor_reply.Raised (exn, backtrace) -> Error (Raised (exn, backtrace))
    ;;
  end

  module Status = struct
    type t =
      | Deferred
      | Pending of Failure.t list
      | Retryable of Failure.t list
      | Terminal of Failure.t list
      | Joined

    let failures = function
      | Pending failures | Retryable failures | Terminal failures -> failures
      | Deferred | Joined -> []
    ;;
  end

  module Snapshot = struct
    type progress =
      | Pending
      | Retryable
      | Terminal
      | Joined
    [@@deriving equal, sexp_of]

    type t =
      { identity : unit ref
      ; progress : progress
      ; failures : Failure.t list
      }

    let create ~progress ~failures = { identity = ref (); progress; failures }
    let same (t : t) (other : t) = phys_equal t.identity other.identity
    let progress t = t.progress
    let failures t = t.failures
  end

  module Reservation = struct
    type t =
      | Available
      | Advancing
  end
end

module Operation_completion = struct
  type phase =
    | Pending
    | Returned of Runtime_retirement.outcome

  type t =
    { operation : Agent_protocol.Operation.t
    ; callback_cleanup : Callback_cleanup_data.Operation.t
    ; mutable phase : phase
    }

  let create ~issuer ~domain ~operation =
    { operation
    ; callback_cleanup = Callback_cleanup_data.Host.operation ~issuer ~domain ~operation
    ; phase = Pending
    }
  ;;

  let matches t ~(operation : Agent_protocol.Operation.t) =
    Agent_protocol.Id.Operation.equal t.operation.id operation.id
    && Int.equal t.operation.generation operation.generation
    && Agent_protocol.Operation.equal_kind t.operation.kind operation.kind
  ;;

  let record t ~outcome =
    match t.phase with
    | Pending ->
      Callback_cleanup_data.Host.record_operation_terminal t.callback_cleanup outcome;
      t.phase <- Returned outcome;
      outcome
    | Returned retained -> retained
  ;;

  let outcome t =
    match t.phase with
    | Pending -> None
    | Returned outcome -> Some outcome
  ;;
end

module Foreground_publication = struct
  module P = Agent_protocol
  module Scope = P.Recovery_window.Scope

  type t =
    { launch : unit ref
    ; session : P.Id.Session.t
    ; generation : int
    ; window : Scope.t option
    ; operation : P.Operation.t
    ; live : bool Atomic.t
    ; completion : Operation_completion.t option
    ; mutable finished_root : Inference_runtime.Attempt.t option
    }

  let scope (state : Session_state.t) =
    Option.map state.recovery_windows ~f:(fun ledger ->
      Recovery_window_ledger.(Window.scope (active ledger)))
  ;;

  let capture (state : Session_state.t) ~operation ~completion =
    { launch = ref ()
    ; session = state.identity.session_id
    ; generation = state.identity.generation
    ; window = scope state
    ; operation
    ; live = Atomic.make true
    ; completion
    ; finished_root = None
    }
  ;;

  let matches t ~(selected : t option) ~(state : Session_state.t) =
    Option.exists selected ~f:(fun current -> phys_equal t.launch current.launch)
    && P.Id.Session.equal t.session state.identity.session_id
    && Int.equal t.generation state.identity.generation
    && Option.equal Scope.equal t.window (scope state)
    && Option.exists state.active_operation ~f:(fun operation ->
      P.Id.Operation.equal t.operation.id operation.id
      && Int.equal t.operation.generation operation.generation
      && P.Operation.equal_kind t.operation.kind operation.kind)
  ;;
end

module Foreground_rollover = struct
  module P = Agent_protocol

  type t =
    { id : P.Id.Operation.t
    ; publication : Foreground_publication.t
    ; check : unit -> (P.Principal.t, P.Error.t) result
    ; authorize_force : (Session_state.t -> (unit, P.Error.t) result) option
    }
end

module Worker_readiness = struct
  type t =
    | Foreground of Foreground_publication.t
    | Compaction of Agent_protocol.Id.Operation.t
end

module Pending_runtime_operation = struct
  type t =
    { operation_id : Agent_protocol.Id.Operation.t
    ; completion : Operation_completion.t option
    }
