(* One ended callback, not a second execution owner. Concrete attempts remain
   reachable from this SAME borrow after the callback and Init finalizers exit. *)
module Callback_retirement_data = struct
  module Attempt = struct
    type t =
      { previous : Session_state.t
      ; candidate : Session_transition.t
      ; observation : Session_commit_observation.Owner.t
      }
  end

  type t =
    { issuing_actor : unit ref
    ; domain : int
    ; executing : Agent_protocol.Moderator_execution.t
    ; exit : Queued_callback_exit.t
    ; terminal : Agent_protocol.Moderator_execution.t option
    ; run_scope : Run_scope.t option
    ; sample : Recurrence_runtime.Completion.sample option
    ; constructor : Initialization_scope_data.t option
    ; mutable constructor_basis : Session_state.t option
    ; source : Agent_protocol.Run_source.t option
    ; children : Agent_protocol.Invocation.t list
    ; permissions : (Agent_protocol.Permission.t * Agent_protocol.Permission.t) list
    ; lifecycle : (Session_state.Lifecycle.t * Session_state.Lifecycle.t) option
    ; mutable attempt : Attempt.t option
    }
end

(* Factual completion of this SAME callback. Producer exit is independent of
   control retirement, which can release bookkeeping while the callback runs. *)
module Callback_completion_data = struct
  module Outcome = Callback_cleanup_data.Outcome
  module Attempt = Callback_cleanup_data.Attempt

  module Actual_exit = struct
    type t =
      | Not_returned
      | Returned of Queued_callback_exit.t
  end

  module Released = struct
    type t = { selection : Callback_retirement_data.t }
  end

  module Bookkeeping = struct
    type t =
      | Unselected
      | Selected of Callback_retirement_data.t
      | Released of Released.t
  end

  type t =
    { facts : Callback_cleanup_data.Completion.t
    ; mutable bookkeeping : Bookkeeping.t
    }

  let create ~issuing_actor ~domain =
    { facts = Callback_cleanup_data.Completion.create ~issuer:issuing_actor ~domain
    ; bookkeeping = Unselected
    }
  ;;

  let belongs_to t ~issuing_actor ~domain =
    Callback_cleanup_data.Completion.belongs_to t.facts ~issuer:issuing_actor ~domain
  ;;

  let actual_exit t : Actual_exit.t =
    match Callback_cleanup_data.Completion.producer_exit t.facts with
    | Not_returned -> Not_returned
    | Returned (Ok ()) -> Returned Queued_callback_exit.Returned
    | Returned (Error (Protocol failure)) -> Returned (Failed failure)
    | Returned (Error (Raised (exn, backtrace))) -> Returned (Raised (exn, backtrace))
  ;;

  let latest_finish t = Callback_cleanup_data.Completion.latest_finish t.facts
  let release t = Callback_cleanup_data.Completion.release t.facts

  let record_selection t (selection : Callback_retirement_data.t) =
    ignore (Callback_cleanup_data.Completion.producer_exit t.facts);
    match t.bookkeeping with
    | Unselected -> t.bookkeeping <- Selected selection
    | Selected previous when phys_equal previous selection -> ()
    | Selected _ | Released _ ->
      invalid_arg "callback completion cannot replace its original selection"
  ;;

  let record_release t ~attempt (selection : Callback_retirement_data.t) =
    ignore (Callback_cleanup_data.Completion.producer_exit t.facts);
    match t.bookkeeping with
    | Selected previous when phys_equal previous selection ->
      Callback_cleanup_data.Completion.record_release t.facts ~attempt;
      t.bookkeeping <- Released { selection }
    | Unselected | Selected _ | Released _ ->
      invalid_arg "callback completion release differs from its original selection"
  ;;

  let record_finish t ~attempt outcome =
    Callback_cleanup_data.Completion.record_finish t.facts ~attempt outcome
  ;;
end

