(* One synchronous constructor producer retains its speculative writers and
   actual ACKs. Neither an ended Init slot nor a caller's Job DTO is a join. *)
module Constructor_model_data = struct
  type selection =
    | Cancel_queued of
        { queued : Agent_protocol.Job.t
        ; sample : Recurrence_runtime.Completion.sample
        }
    | Complete_model of
        { running : Agent_protocol.Job.t
        ; outcome : Runtime_builder.model_job_outcome
        ; sample : Recurrence_runtime.Completion.sample
        }
    | Interrupt_running of
        { running : Agent_protocol.Job.t
        ; sample : Recurrence_runtime.Completion.sample
        }

  type callback_advance =
    { borrow : queued_event_borrow
    ; selection : Callback_retirement_data.t
    ; basis : Session_state.t option
    ; attempt : Callback_retirement_data.Attempt.t option
    ; previous : Session_state.t
    ; candidate : Session_transition.t
    ; acknowledgement : Initialization_scope_data.Acknowledgement.t
    }

  type canonical =
    { previous : Session_state.t
    ; candidate : Session_transition.t
    ; job_custody : Job_custody.Update.t
    ; acknowledgement : Initialization_scope_data.Acknowledgement.t
    ; attempt : Session_commit_attempt.t
    }

  type admission =
    { queued : Agent_protocol.Job.t
    ; canonical : canonical
    }

  type claim =
    { queued : Agent_protocol.Job.t
    ; running : Agent_protocol.Job.t
    ; canonical : canonical
    }

  type terminal =
    { selection : selection
    ; terminal : Agent_protocol.Job.t
    ; canonical : canonical
    ; callback_advance : callback_advance option
    ; completion_plan : Recurrence_runtime.Completion.plan option
    }

  type control_prior =
    | Was_admitted of Agent_protocol.Job.t
    | Was_claimed of Agent_protocol.Job.t
    | Was_selected of selection

  type control =
    { prior : control_prior
    ; cancelled : Agent_protocol.Job.t
    ; canonical : canonical
    ; callback_advance : callback_advance option
    }

  type phase =
    | Admission_attempt of admission
    | Admitted of Agent_protocol.Job.t
    | Claim_attempt of claim
    | Claimed of Agent_protocol.Job.t
    | Selected of selection
    | Terminal_attempt of terminal
    | Cancel_attempt of control
    | Joined of
        { selected : selection option
        ; winner : Agent_protocol.Job.t
        }
    | Abandoned

  type completion =
    | Sample of Recurrence_runtime.Completion.sample
    | Clock_failed of exn * Stdlib.Printexc.raw_backtrace

  type producer_result =
    | Selecting of Runtime_builder.model_job_outcome option
    | Selected_result of
        { outcome : Runtime_builder.model_job_outcome option
        ; completion : completion
        }

  type capture_phase =
    | Waiting
    | Pending of call
    | Owned of call
    | No_admission

  and capture =
    { issuing_actor : unit ref
    ; domain : int
    ; scope : Initialization_scope_data.t
    ; producer : Constructor_model_producer.t
    ; mutable result : producer_result option
    ; mutable phase : capture_phase
    }

  and group =
    { issuing_actor : unit ref
    ; domain : int
    ; scope : Initialization_scope_data.t
    ; mutable ended : bool
    ; mutable calls : call list
    }

  and call =
    { group : group
    ; capture : capture
    ; mutable phase : phase
    }
end

module Constructor_model_request = struct
  type _ t =
    | Admit :
        Constructor_model_data.capture * Agent_protocol.Job.t
        -> Agent_protocol.Job.t t
    | Claim : Constructor_model_data.capture -> Agent_protocol.Job.t t
    | Complete : Constructor_model_data.capture -> Agent_protocol.Job.t t
    | Interrupt : Constructor_model_data.capture -> Agent_protocol.Job.t t
    | Drain : unit t
end

module Queued_callback_finish = struct
  type t =
    | Callback_returned of
        queued_event_borrow * Queued_callback_exit.t * Callback_completion_data.Attempt.t
    | Retry_retained
end

(* The queued claim and its exact resumed-Run loan share one durable ACK.
   Staged cleanup cannot retire a loan already installed before publication. *)
(* The queue carries an actual completed producer's existing custody. Validate
   its immutable factual association BEFORE taking a continuation. This module
   performs no source lookup or authorization and has no mutable inventory. *)
module Policy_queue_source = struct
  module P = Agent_protocol
  module Classification = Policy_standalone_source.Classification

  let invalid message = Error (P.Error.invalid_request message)

  let job ~(job : P.Job.t) ~source ~entry classification =
    match classification with
    | Classification.Unknown -> Ok Classification.Unknown
    | Standalone_unrelated descriptor ->
      let open Result.Let_syntax in
      let%bind member = Policy_native_ancestry.member_of_job job in
      let%bind () =
        match descriptor.Policy_standalone_source.subject with
        | Member actual when Policy_cause_data.Member.equal actual member -> Ok ()
        | Member _ | Root_operation _ -> invalid "Job delivery standalone subject differs"
      in
      let%bind () =
        if
          P.Id.Session.equal descriptor.session_id job.session_id
          && Int.equal descriptor.generation job.generation
          && Option.exists
               job.inference_origin
               ~f:(P.Inference_origin.equal descriptor.origin)
          && Option.exists descriptor.source.installation ~f:(P.Run_source.equal source)
          && Option.exists
               descriptor.source.observer
               ~f:(P.Invocation.equal_observer source.P.Run_source.observer)
          && Option.equal
               P.Inference_origin.equal
               (Moderator_queue.Entry.origin entry)
               job.inference_origin
        then Ok ()
        else invalid "Job delivery standalone origin or full source differs"
      in
      let%map () =
        match Moderator_queue.Entry.producer entry with
        | Some (Queue_producer.Job_completion { id; generation; attempt })
          when P.Id.Job.equal id job.id
               && Int.equal generation job.generation
               && Int.equal attempt job.attempt -> Ok ()
        | None | Some _ ->
          invalid "Job delivery queue occurrence differs from its actual attempt"
      in
      classification
  ;;

  let claim
        ~(state : Session_state.t)
        ~source
        ~entry
        ~(receipt : P.Moderator_execution.t)
        classification
    =
    match classification with
    | Classification.Unknown -> Ok Classification.Unknown
    | Standalone_unrelated descriptor ->
      let open Result.Let_syntax in
      let%bind producer =
        match Moderator_queue.Entry.producer entry with
        | Some (Queue_producer.Job_completion { id; generation; attempt }) ->
          Ok (id, generation, attempt)
        | None | Some _ -> invalid "standalone queue claim has no exact Job producer"
      in
      let id, generation, attempt = producer in
      (* The selected live queue Row was validated against this exact Job
         occurrence before its enqueue ACK. A retry may advance or prune the
         latest Job while that original occurrence remains queued. Preserve
         the Row/Entry fact rather than redirecting it through a successor. *)
      let%bind () =
        match descriptor.Policy_standalone_source.subject with
        | Member member ->
          (match Policy_cause_data.Member.kind member with
           | Model_job | Async_job ->
             if
               String.equal (Policy_cause_data.Member.id member) (P.Id.Job.to_string id)
               && Int.equal (Policy_cause_data.Member.generation member) generation
               && Int.equal descriptor.generation generation
               && P.Id.Session.equal descriptor.session_id state.identity.session_id
               && Int.equal generation state.identity.generation
               && attempt >= 0
               && Option.exists
                    descriptor.source.installation
                    ~f:(P.Run_source.equal source)
               && Option.exists
                    descriptor.source.observer
                    ~f:(P.Invocation.equal_observer source.P.Run_source.observer)
               && Option.exists
                    (Moderator_queue.Entry.origin entry)
                    ~f:(P.Inference_origin.equal descriptor.origin)
             then Ok ()
             else invalid "standalone queue claim changed its retained Job occurrence"
           | Event | Invocation ->
             invalid "standalone queue claim subject is not its retained Job")
        | Root_operation _ ->
          invalid "standalone queue claim subject is not its retained Job"
      in
      let%bind () =
        if
          P.Id.Session.equal receipt.context.session_id state.identity.session_id
          && Int.equal receipt.context.generation state.identity.generation
          && P.Invocation.equal_observer
               receipt.context.source
               source.P.Run_source.observer
          &&
          match receipt.queue_occurrence with
          | Some occurrence ->
            P.Run_source.equal
              (P.Moderator_execution.Queue_occurrence.source occurrence)
              source
            && Int64.equal
                 (P.Moderator_execution.Queue_occurrence.ordinal occurrence)
                 (Moderator_queue.Entry.ordinal entry)
            && Option.equal
                 P.Inference_origin.equal
                 (P.Moderator_execution.Queue_occurrence.origin occurrence)
                 (Moderator_queue.Entry.origin entry)
            && P.Moderator_execution.Queue_occurrence.Producer.equal
                 (P.Moderator_execution.Queue_occurrence.producer occurrence)
                 (Captured (Moderator_queue.Entry.producer entry))
          | None -> false
        then Ok ()
        else invalid "standalone queue claim differs from its consumed occurrence"
      in
      let%bind member =
        Policy_cause_data.Member.event
          receipt.context.id
          ~generation:receipt.context.generation
      in
      let%map descriptor =
        Policy_standalone_source.create
          ~session_id:receipt.context.session_id
          ~generation:receipt.context.generation
          ~subject:(Member member)
          ~origin:descriptor.origin
          ~source:descriptor.source
      in
      Classification.Standalone_unrelated descriptor
  ;;
end

module Queued_claim_acknowledgement : sig
  module Head : sig
    type t

    val capture
      :  state:Session_state.t
      -> manager:Chat_response.Moderator_manager.t option
      -> (t option, Agent_protocol.Error.t) result
  end

  type t

  val prepare
    :  ?goal_scope:Goal_continuation.runtime_scope
    -> previous:Session_state.t
    -> authorities:Run_authorities.t
    -> queue_custody:Legacy_queue_custody.t
    -> head:Head.t option
    -> resumed:Agent_protocol.Id.Run.t list
    -> candidate:Session_transition.t
    -> borrow:queued_event_borrow
    -> unit
    -> (t, Agent_protocol.Error.t) result

  val scope : t -> Run_admission.Scope.t option

  (** No policy, original-proof or clock callbacks. *)
  val check_basis
    :  t
    -> previous:Session_state.t
    -> authorities:Run_authorities.t
    -> queue_custody:Legacy_queue_custody.t
    -> manager:Chat_response.Moderator_manager.t option
    -> current_borrow:queued_event_borrow option
    -> candidate:Session_transition.t
    -> (unit, Agent_protocol.Error.t) result

  val inventory : t -> Legacy_queue_custody.t
  val install : t -> queued_event_borrow
  val discard : t -> unit
end = struct
  module P = Agent_protocol

  module Head = struct
    type t =
      { manager : Chat_response.Moderator_manager.t
      ; source : P.Run_source.t
      ; entry : Moderator_queue.Entry.t
      }

    let capture ~state ~manager =
      let open Result.Let_syntax in
      let%map metadata = Moderator_checkpoint.queue state.Session_state.moderator in
      Option.bind manager ~f:(fun manager ->
        Option.bind metadata ~f:(fun metadata ->
          Option.map
            (List.hd (Moderator_queue.entries metadata))
            ~f:(fun entry -> { manager; source = Moderator_queue.source metadata; entry })))
    ;;

    let find t inventory =
      Legacy_queue_custody.find
        inventory
        ~manager:t.manager
        ~source:t.source
        ~entry:t.entry
    ;;

    let check t ~state ~manager =
      let open Result.Let_syntax in
      let%bind current = capture ~state ~manager in
      if
        Option.exists current ~f:(fun current ->
          phys_equal t.manager current.manager
          && P.Run_source.equal t.source current.source
          && Moderator_queue.Entry.equal t.entry current.entry)
      then Ok ()
      else
        Error
          (P.Error.create
             Conflict
             ~message:"queued claim lost its exact source/head"
             ~retryable:false
             ())
    ;;
  end

  module Phase = struct
    type t =
      | Staged
      | Installed
      | Discarded
  end

  type t =
    { previous : Session_state.t
    ; candidate : Session_transition.t
    ; queue_custody : Legacy_queue_custody.t
    ; head : Head.t option
    ; selected : Legacy_queue_custody.Row.t option
    ; inventory : Legacy_queue_custody.t
    ; binding : (P.Id.Run.t * Run_authorities.binding) option
    ; borrow : queued_event_borrow
    ; goal_scope : Goal_continuation.runtime_scope option
    ; mutable phase : Phase.t
    }

  let conflict message = Error (P.Error.create Conflict ~message ~retryable:false ())

  let prepare
        ?goal_scope
        ~(previous : Session_state.t)
        ~authorities
        ~queue_custody
        ~head
        ~resumed
        ~(candidate : Session_transition.t)
        ~(borrow : queued_event_borrow)
        ()
    =
    let open Result.Let_syntax in
    let%bind binding =
      match resumed with
      | [] -> Ok None
      | [ run_id ] ->
        let%bind binding =
          Result.of_option
            (Run_authorities.find authorities run_id)
            ~error:
              (P.Error.create
                 Permission_denied
                 ~message:"run no longer has live host authority"
                 ~retryable:false
                 ())
        in
        let%bind run =
          Result.of_option
            (Option.bind candidate.Session_transition.state.run_state ~f:(fun index ->
               Run_state.find index run_id))
            ~error:(P.Error.invalid_request "queued claim lost its resumed Run")
        in
        if
          Int.equal run.source.generation borrow.receipt.context.generation
          && P.Invocation.equal_observer run.source.observer borrow.receipt.context.source
          && P.Invocation.equal_observer
               run.source.observer
               (Run_admission.Scope.observer (Run_authorities.scope binding))
          && List.exists run.owned_work ~f:(fun work ->
            match work.P.Run_work.key with
            | Retained (Moderator_execution id) ->
              P.Id.Moderator_execution.equal id borrow.receipt.context.id
            | Operation _ | Retained _ -> false)
        then Ok (Some (run_id, binding))
        else conflict "queued claim differs from its actual resumed Run"
      | _ :: _ :: _ -> conflict "queued claim has more than one resumed Run"
    in
    let%bind () =
      match goal_scope, binding with
      | None, _ -> Ok ()
      | Some (scope : Goal_continuation.runtime_scope), Some (run_id, binding)
        when Agent_protocol.Id.Run.equal
               run_id
               scope.continuation.binding.preparation.run.id
             && phys_equal binding scope.continuation.binding.preparation.binding -> Ok ()
      | Some _, (Some _ | None) ->
        conflict "Goal queue ACK lost its exact resumed binding"
    in
    let selected = Option.bind head ~f:(fun head -> Head.find head queue_custody) in
    let%bind policy_source =
      match head, selected with
      | Some head, Some row ->
        Policy_queue_source.claim
          ~state:previous
          ~source:head.Head.source
          ~entry:head.entry
          ~receipt:borrow.receipt
          (Legacy_queue_custody.Row.policy_source row)
      | None, _ | Some _, None -> Ok Policy_standalone_source.Classification.Unknown
    in
    (* A genuine resumed Run is selected independently, before any contextual
       transfer. Missing queue loans after restore do not erase that authority;
       an expired contextual loan never falls back to another admission. *)
    let%map admission =
      match binding with
      | None ->
        let%map admission =
          match selected with
          | None -> Ok None
          | Some row -> Result.map (Legacy_queue_custody.Row.transfer row) ~f:Option.some
        in
        Queued_agent_admission.Selected_queue admission
      | Some (_, binding) ->
        Ok
          (Queued_agent_admission.Resumed_run
             (Option.map
                (Run_admission.Scope.original_actor (Run_authorities.scope binding))
                ~f:(fun original ->
                  create_agent_admission (Some (create_agent_custody original)))))
    in
    { previous
    ; candidate
    ; queue_custody
    ; head
    ; selected
    ; inventory = Legacy_queue_custody.without queue_custody ~selected
    ; binding
    ; borrow =
        { borrow with
          agent_admission = admission
        ; policy_source
        ; lifecycle_owner =
            Option.map goal_scope ~f:(fun scope ->
              Lifecycle_callback_owner.Existing_goal_resume scope)
        }
    ; goal_scope
    ; phase = Staged
    }
  ;;

  let scope t =
    Option.map t.binding ~f:(fun (_, binding) -> Run_authorities.scope binding)
  ;;

  let inventory t = t.inventory

  let check_basis
        t
        ~previous
        ~authorities
        ~queue_custody
        ~manager
        ~current_borrow
        ~candidate
    =
    let open Result.Let_syntax in
    let%bind () =
      match t.phase with
      | Staged
        when phys_equal previous t.previous
             && phys_equal candidate t.candidate
             && phys_equal queue_custody t.queue_custody
             && Option.is_none current_borrow
             && Option.for_all t.binding ~f:(fun (run_id, binding) ->
               Run_authorities.is_current authorities binding ~run_id) -> Ok ()
      | Staged | Installed | Discarded ->
        conflict "queued claim custody changed before ACK"
    in
    let%bind () =
      match t.head with
      | None -> Ok ()
      | Some head ->
        let%bind () = Head.check head ~state:previous ~manager in
        if Option.equal phys_equal t.selected (Head.find head queue_custody)
        then Ok ()
        else conflict "queued claim loan changed before ACK"
    in
    match t.binding, t.selected with
    | None, Some row -> Legacy_queue_custody.Row.check row
    | Some _, (Some _ | None) | None, None -> Ok ()
  ;;

  let install t =
    t.phase <- Installed;
    Option.iter t.goal_scope ~f:(fun scope ->
      scope.callback <- Executing t.borrow.receipt.context.id;
      scope.continuation.binding.preparation.runtime_phase
      <- Handed_off (scope, Existing_execution (Queued_event t.borrow.receipt)));
    t.borrow
  ;;

  let discard t =
    match t.phase with
    | Installed | Discarded -> ()
    | Staged ->
      t.phase <- Discarded;
      Atomic.set t.borrow.authority_live false;
      Option.iter
        (Queued_agent_admission.admission t.borrow.agent_admission)
        ~f:retire_agent_admission
  ;;
end

module Callback_scope = struct
  (* Source bootstrap alone never creates a continuation. Only an actual live
     parent admission lends custody; historical absence is not legacy None. *)
  type custody =
    | Unavailable
    | Admitted of agent_admission

  type t =
    { manager : Chat_response.Moderator_manager.t
    ; constructor_scope : Initialization_scope_data.t option
    ; callback : Chat_response.Moderator_manager.Callback.t
    ; borrow : queued_event_borrow
    ; source : Agent_protocol.Run_source.t
    ; origin : Agent_protocol.Inference_origin.t option
    ; custody : custody
    ; mutable committed_checkpoint : Jsonaf.t option option
    }

  module Completion = Callback_cleanup.Completion

  let completion t = t.borrow.completion.facts
  let executing t = t.borrow.receipt
  let source t = t.source
  let origin t = t.origin
  let committed_checkpoint t = t.committed_checkpoint
end

type legacy_callback_handler =
  scope:Callback_scope.t
  -> commit:
       (snapshot:Session.Moderator_state.Identity_snapshot.t
        -> requests:Agent_protocol.Invocation.follow_up
        -> notifications:string list
        -> (unit, Agent_protocol.Error.t) result)
  -> (unit, Agent_protocol.Error.t) result

type legacy_callback_claim =
  ?capture_cleanup:(Callback_cleanup.Completion.t -> unit)
  -> callback:Chat_response.Moderator_manager.Callback.t
  -> legacy_callback_handler
  -> (bool, Agent_protocol.Error.t) result

type legacy_callback_parent =
  | Callback_operation of Agent_protocol.Id.Operation.t option
  | Callback_job of job_scope

type invocation_owner =
  | Foreground of Agent_protocol.Id.Operation.t
  | Invocation_moderator of moderator_borrow
  | Event_moderator of queued_event_borrow
  | Background_job of job_scope

(* Immutable child binding lives before the request GADT. It contains no Actor
   pointer or persistence callback; actual issuance remains in Causal_governance. *)
module Causal_governance_binding = struct
  module Data = Delegated_policy_governance_data

  type registered =
    { data : Data.Registered.t
    ; source_owner : Runtime_source_owner.t
    ; controller : Recurrence_controller.t
    ; ancestry : Delegation_authority.Checked_ancestry.t option
    }

  type source =
    | Standalone of Policy_standalone_source.t
    | Registered of registered

  type t =
    { request : Script_tool_calls.preparation
    ; source : source
    ; current : unit -> (unit, Agent_protocol.Error.t) result
    }

  let check_current t = t.current ()

  let check_request (t : t) request =
    if phys_equal t.request request
    then check_current t
    else
      Error
        (Agent_protocol.Error.create
           Conflict
           ~message:"policy governance belongs to another preparation request"
           ~retryable:false
           ())
  ;;
end

module Native_setup_data = struct
  type t =
    { issuer : unit ref
    ; domain : int
    ; reference : Agent_store.Delegation_store.Reference.t
    ; source : Runtime_builder.Source.t
    ; expected : Session_state.t
    ; mutable closed : bool
    ; current : unit -> (unit, Agent_protocol.Error.t) result
    }

  let unavailable () =
    Agent_protocol.Error.create
      Conflict
      ~message:"native resource setup is closed or displaced"
      ~retryable:false
      ()
  ;;

  let check_domain domain =
    if Int.equal domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (unavailable ())
  ;;

  let check (t : t) =
    let open Result.Let_syntax in
    let%bind () = check_domain t.domain in
    if t.closed then Error (unavailable ()) else t.current ()
  ;;

  let close (t : t) =
    if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
    then invalid_arg "native resource setup belongs to another Eio domain";
    t.closed <- true
  ;;
end

module Policy_restoration_data = struct
  (* Construction authorization is lexical. Published retains only the actual
     resource association; no previous Caller/governance can authorize its reuse. *)
  type published =
    { issuer : unit ref
    ; domain : int
    ; access : Runtime_builder.Restored_policy_access.t
    ; mutable closed : bool
    ; current : unit -> (unit, Agent_protocol.Error.t) result
    }

  type t =
    { issuer : unit ref
    ; domain : int
    ; source : Runtime_builder.Source.t
    ; basis : Policy_restore_basis.t
    ; mutable closed : bool
    ; current : unit -> (unit, Agent_protocol.Error.t) result
    }

  type selection =
    | Vacant
    | Constructing of t
    | Native_constructing of Native_setup_data.t
    | Published of published

  let unavailable () =
    Agent_protocol.Error.create
      Conflict
      ~message:"policy restoration admission is closed or displaced"
      ~retryable:false
      ()
  ;;

  let check_domain domain =
    if Int.equal domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (unavailable ())
  ;;

  let check (t : t) =
    let open Result.Let_syntax in
    let%bind () = check_domain t.domain in
    if t.closed then Error (unavailable ()) else t.current ()
  ;;

  let close (t : t) =
    if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
    then invalid_arg "policy restoration belongs to another Eio domain";
    t.closed <- true
  ;;

  module Published = struct
    type t = published

    let check (t : t) =
      let open Result.Let_syntax in
      let%bind () = check_domain t.domain in
      if t.closed then Error (unavailable ()) else t.current ()
    ;;

    let close (t : t) =
      if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
      then invalid_arg "published policy restoration belongs to another Eio domain";
      t.closed <- true
    ;;

    let product_identity t =
      Runtime_builder.Restored_policy_access.product_identity t.access
    ;;
  end

  let revoke = function
    | Vacant -> ()
    | Constructing t -> close t
    | Native_constructing t -> Native_setup_data.close t
    | Published t -> Published.close t
  ;;
end

