module Inference_usage_snapshot = struct
  type t =
    { ledger_revision : int64
    ; initials : (Inference_graph_owner.Factual_usage.t * bool) list
    ; duties : (Inference_graph_owner.Factual_usage.t * bool) list
    }

  let same_cells =
    List.equal (fun (left, left_confirmed) (right, right_confirmed) ->
      phys_equal left right && Bool.equal left_confirmed right_confirmed)
  ;;

  let same_progress before after =
    Int64.equal before.ledger_revision after.ledger_revision
    && same_cells before.initials after.initials
    && same_cells before.duties after.duties
  ;;
end

