and compaction_outcome =
  | Compacted of History_entry.t list
  | Compaction_cancelled of string
  | Compaction_failed of Agent_protocol.Error.t

and packed =
  | Pack :
      Document_schema.Document.t option * 'a request * 'a Actor_reply.t Eio.Promise.u
      -> packed

(* One election retains only its original duties and physical parents. This
   record has no executable cleanup callbacks and grants no new admission. *)
and runtime_retirement_callback_parent =
  | Ended_callback
  | Foreground_callback of Agent_protocol.Operation.t
  | Constructor_callback of Initialization_scope_data.t
  | Authored_callback of Held_authored_start.t
  | Goal_callback of Goal_continuation.runtime_scope

and runtime_retirement_callback =
  { borrow : queued_event_borrow
  ; parent : runtime_retirement_callback_parent
  ; wrapper : queued_event_borrow Delegated_policy_claim_state.t option
  }

and runtime_retirement_cleanup_attempt =
  | Idle_cleanup_attempt of
      { completion : Idle_completion_data.t
      ; attempt : Idle_completion_data.Cleanup_attempt.t
      }
  | Inherited_cleanup_attempt of
      { acknowledged : Inherited_turn.cleanup
      ; attempt : Inherited_turn.Cleanup.Attempt.t
      }
  | Descendant_cleanup_attempt of
      { slot : Descendant_admission_slot.t
      ; attempt : Descendant_admission_slot.Cleanup.Attempt.t
      }
  | Causal_cleanup_attempt of
      { plan : inherited_attempt_plan
      ; promise : unit Actor_reply.t Eio.Promise.t
      }

and runtime_retirement_selection =
  { issuing_actor : unit ref
  ; domain : int
  ; operation : Agent_protocol.Operation.t option
  ; selected_operation_completion : Operation_completion.t option
  ; constructor_calls : Constructor_model_data.call list
  ; callback : runtime_retirement_callback option
  ; selected_idle_completion : Idle_completion_data.t option
  ; idle_continuation : Idle_continuation.t option
  ; inherited_prepared : Inherited_turn.prepared option
  ; inherited_cleanup : Inherited_turn.cleanup option
  ; governed_slot : inherited_attempt_plan Governed_admission_slot.t option
  ; factual_usage : Inference_graph_owner.Factual_usage.t list
  ; cleanup_attempts : runtime_retirement_cleanup_attempt list
  }

and runtime_retirement_cleanup_constructor_attempt =
  { original_call : Constructor_model_data.call
  ; mutable completion : Retirement_cleanup_completion.t option
  }

and runtime_retirement_cleanup_target =
  | Cleanup_constructor of Constructor_model_data.call
  | Cleanup_callback of runtime_retirement_callback
  | Cleanup_idle of Idle_completion_data.t * Idle_continuation.t option
  | Cleanup_inherited of Inherited_turn.cleanup
  | Cleanup_descendant of Descendant_admission_slot.t
  | Cleanup_governed of inherited_attempt_plan
  | Cleanup_factual of Inference_graph_owner.Factual_usage.t

and runtime_retirement_cleanup_attempt_observation =
  | No_cleanup_attempt
  | Unobserved_cleanup_attempt of runtime_retirement_cleanup_attempt
  | Observed_cleanup_attempt of runtime_retirement_cleanup_attempt

and runtime_retirement_cleanup_duty =
  { selected_target : runtime_retirement_cleanup_target
  ; mutable observation : Retirement_cleanup_observation.Status.t
  ; mutable attempt_observation : runtime_retirement_cleanup_attempt_observation
  }

and runtime_retirement_cleanup =
  { original : runtime_retirement
  ; mutable duties : runtime_retirement_cleanup_duty list
  ; mutable latest : Retirement_cleanup_observation.Snapshot.t
  ; mutable reservation : Retirement_cleanup_observation.Reservation.t
  }

and failed_startup_request =
  { construction : Runtime_construction.t
  ; retirement : runtime_retirement_cleanup
  ; naming : Failed_startup_release_data.t
  }

and _ runtime_retirement_request =
  | Release_failed_startup :
      failed_startup_request
      -> Failed_startup_release_data.Receipt.t runtime_retirement_request
  | Retire_worker : bool -> Runtime_retirement.t runtime_retirement_request
  | Capture_cleanup : bool -> runtime_retirement_cleanup runtime_retirement_request
  | Advance_cleanup : 'a runtime_retirement_cleanup_step -> 'a runtime_retirement_request

and _ runtime_retirement_cleanup_step =
  | Cleanup_constructor_call :
      runtime_retirement_cleanup_constructor_attempt
      -> unit runtime_retirement_cleanup_step
  | Cleanup_ended_callback :
      queued_event_borrow * Queued_callback_exit.t
      -> unit runtime_retirement_cleanup_step
  | Cleanup_seal_descendant :
      Descendant_admission_slot.t
      -> Descendant_preparation.Closed_before_writer.t runtime_retirement_cleanup_step
  | Cleanup_read_idle :
      Idle_completion_data.t * Idle_continuation.t option
      -> Inherited_turn.Idle_retirement.t runtime_retirement_cleanup_step
  | Cleanup_retire_idle :
      Idle_completion_data.t * Idle_continuation.t option
      -> unit runtime_retirement_cleanup_step

and runtime_retirement =
  { foreground_finished : Runtime_retirement.t
  ; finish_foreground : Runtime_retirement.outcome Eio.Promise.u
  ; selection : runtime_retirement_selection
  ; mutable cleanup_holder : runtime_retirement_cleanup option
  ; mutable pending_operation : Pending_runtime_operation.t option
  ; mutable closing : bool
  }

and permission_waiter =
  { resolver : Agent_protocol.Permission.resolution Eio.Promise.u
  ; resume_observed : Agent_protocol.Session.observed_state
  }

