  ; mutable inference_owners : Inference_graph_custody.t list
  ; initialization_owner : unit ref
  ; mutable constructor_models : Constructor_model_data.group option
  ; mutable initialization_scope : Initialization_scope_data.t option
  ; mutable job_scopes : job_scope list
  ; staged_jobs : Job_custody.Fresh.t option Staged_jobs.t
  ; staged_subscriptions : Staged_subscriptions.t
  ; staged_ingress : Staged_ingress.t
  ; staged_schedules : Staged_schedules.t
  ; staged_schedule_custody : Legacy_schedule_custody.Staged.t
  ; staged_ingress_custody : Ingress_creator_custody.Staged.t
  ; staged_notifications : Staged_notifications.t
  ; mutable notification_inputs :
      (Agent_protocol.Id.Operation.t * Agent_protocol.Id.Delivery.t list) option
  ; extension_clock : Extension_clock.t
  ; invocation_gate : Chat_response.Execution_gate.t
  ; event_sequence : int64 Atomic.t
  ; mutable state : Session_state.t
  ; mutable stopped : bool
  ; recovery_window_cursor : Recovery_window_page.signer Lazy.t
  ; recovery_query_cursor : Recovery_query_cursor.t Lazy.t
  ; mutable protected_source_custody : unit ref option
  ; mutable canonical_write_in_progress : bool
    (* Synchronous share publication observes only an installed durable state. *)
  ; mutable command_audit : Document_schema.Document.t option
  }

and recurrence_target_invalidation =
  { controller_actor : t
  ; target_fact : recurrence_target_fact
  }

and recurrence_target_fact =
  | Removed_target of Agent_store.Session_store.Command_receipts.Removal.t
  | Target_source of resource_observation

and resource_observation =
  { actor : t
  ; original : Session_state.t
  ; resource_identity : Session_state.Spec.Resource_identity.t
  }

(* Actual Actor pointers stay in this narrow native request group. The pure
   route leaf receives immutable DATA only; it cannot issue these observations. *)
and inference_host_binding =
  | Physical_only of Descendant_host_data.Binding.t
  | Governed of
      { physical : Descendant_host_data.Binding.t
      ; causal : causal_driver
      }

and causal_driver =
  { prepare :
      Goal_causal_admission_custody.Preparation.t
      -> causal_reservation_set
      -> (causal_before_writer, Agent_protocol.Error.t) result
  ; close :
      causal_reservation_set
      -> causal_closed_before_writer
      -> (unit, Agent_protocol.Error.t) result
  ; confirm :
      causal_canonical_acknowledgement
      -> (causal_confirmation, Agent_protocol.Error.t) result
  ; refresh_admitted :
      causal_canonical_acknowledgement
      -> causal_confirmation
      -> (causal_admitted_views, Agent_protocol.Error.t) result
  ; correct_usage :
      causal_canonical_acknowledgement
      -> causal_confirmation
      -> ( Inference_graph_owner.Factual_usage.Correction_outcome.t
           , Agent_protocol.Error.t )
           result
  }

and causal_before_writer =
  { preparation : Goal_causal_admission_custody.Preparation.t
  ; reservations : causal_reservation_set
  ; roots : causal_root_before_writer list
  }

and causal_route_capture =
  { callee : t
  ; basis : Child_accounting_basis.t
  ; preparation : Goal_causal_admission_custody.Preparation.t
  ; reservations : causal_reservation_set
  ; calculation : Goal_causal_root_route.t
  }

and causal_route_observation =
  { captured : causal_route_capture
  ; records : Agent_store.Delegation_store.record list
  ; current : Recurrence_controller.observation
  }

and causal_root_capture =
  { root_basis : Child_accounting_basis.t
  ; observation : causal_route_observation
  }

and causal_root_observed =
  { captured_root : causal_root_capture
  ; current_root : Recurrence_controller.observation
  }

and causal_root_route =
  { root_actor : t
  ; observation : causal_route_observation
  ; native : Goal_causal_admission_custody.Route.t
  }

and causal_root_acknowledgement =
  | Causal_reserved of Goal_causal_admission_custody.Reserve_install.t
  | Causal_held of Goal_causal_admission_custody.Hold_install.t
  | Causal_terminal of
      { plan : Goal_causal_admission_custody.Terminal_install.t
      ; context : causal_terminal_context
      ; initial_install : causal_initial_install option
      }

and causal_root_write =
  { acknowledgement : causal_root_acknowledgement
  ; previous : Session_state.t
  ; candidate : Session_transition.t
  ; writer : Session_commit_attempt.t
  }

and causal_reservation_set =
  { native_set : Goal_causal_admission_custody.Set.t
  ; mutable actual_attempts : causal_reservation_attempt list
  ; mutable association : causal_route_association option
  }

and causal_route_association =
  { observation : causal_route_observation
  ; mutable bound_roots : causal_bound_root list
  }

and causal_bound_root =
  { root_actor : t
  ; root_basis : Child_accounting_basis.t
  ; retained_owner : Recurrence_controller.Retained_owner.t
  }

and causal_reservation_attempt =
  { native_attempt : Goal_causal_admission_custody.Remote.attempt
  ; route : causal_root_route
  ; mutable initial_import : causal_initial_receipt option
  }

and causal_initial_receipt =
  { operation : Goal_causal_admission_custody.Terminal_operation.t
  ; canonical : causal_canonical_acknowledgement
  ; projection : Policy_canonical_usage.Projection.t
  ; mutable installed_ack : Goal_causal_admission_custody.Remote.terminal_ack option
  }

and causal_initial_install =
  { attempt : causal_reservation_attempt
  ; native_write : Goal_causal_admission_custody.Remote.terminal_write
  ; initial_receipt : causal_initial_receipt
  ; retained : causal_initial_receipt option
  }

and causal_reservation =
  { native_reservation : Goal_causal_admission_custody.Remote.reservation
  ; actual_attempt : causal_reservation_attempt
  }

and 'outcome causal_reservation_capture =
  { reservation_basis : Child_accounting_basis.t
  ; reservation_operation : 'outcome causal_reservation_operation
  }

and 'outcome causal_reservation_observed =
  { captured_reservation : 'outcome causal_reservation_capture
  ; reservation_current : Recurrence_controller.observation
  }

and causal_reserve_result =
  | Reserved of causal_reservation
  | Blocked of Goal_admission_policy.Count_availability.t
  | Attempt_unconfirmed of causal_reservation_attempt

and causal_root_before_writer =
  { reservation : causal_reservation
  ; root_owner : Recurrence_controller.Retained_owner.t
  }

and _ causal_reservation_operation =
  | Begin_causal_reservation :
      causal_root_route * causal_reservation_set
      -> causal_reservation_attempt causal_reservation_operation
  | Commit_causal_reservation :
      causal_reservation_attempt
      -> causal_reserve_result causal_reservation_operation
  | Refresh_causal_reservation :
      causal_reservation
      -> causal_root_before_writer causal_reservation_operation

and causal_canonical_acknowledgement =
  { native_acknowledgement : Goal_causal_admission_custody.Acknowledgement.t
  ; canonical_slot : Goal_causal_admission_custody.Slot.t
  ; callee : t
  ; actual_reservations : causal_reservation_set
  ; transport : causal_factual_transport
  }

and causal_factual_transport =
  { identity : unit ref
  ; domain : int
  ; mutable initial : causal_initial_transport
  ; mutable corrections : causal_correction_transport list
  }

and causal_initial_transport =
  | Initial_unobserved
  | Initial_observed of
      { observation : causal_usage_observation
      ; imports : causal_import_acknowledgement list
      }
  | Initial_confirmed of causal_confirmation

and causal_correction_transport =
  { initial_import : causal_import_acknowledgement
  ; mutable stage : causal_correction_transport_stage
  }

and causal_correction_transport_stage =
  | Correction_idle
  | Correction_observed of causal_usage_observation
  | Correction_prepared of
      { observation : causal_usage_observation
      ; attempt : causal_root_write
      }

and causal_usage_source =
  | Canonical_causal_usage of causal_canonical_acknowledgement
  | Imported_causal_usage of
      { canonical : causal_canonical_acknowledgement
      ; stream : Policy_canonical_usage.Stream.t
      }

and causal_usage_capture =
  { source_actor : t
  ; source_basis : Child_accounting_basis.t
  ; source : causal_usage_source
  }

and causal_usage_observed =
  { source_capture : causal_usage_capture
  ; source_current : Recurrence_controller.observation
  ; source_owner : Recurrence_controller.Retained_owner.t
  }

and causal_usage_observation =
  { source_capture : causal_usage_capture
  ; projections : Policy_canonical_usage.Projection.t list
  ; source_owner : Recurrence_controller.Retained_owner.t
  }

and causal_import_acknowledgement =
  { native_import : Goal_causal_admission_custody.Remote.import_ack
  ; actual_reservation : causal_reservation
  ; canonical : causal_canonical_acknowledgement
  }

and causal_closed_before_writer =
  { native_closed : Goal_causal_admission_custody.Remote.no_writer
  ; slot : Goal_causal_admission_custody.Slot.t
  ; callee : t
  ; actual_reservations : causal_reservation_set
  }

and causal_correction_acknowledgement =
  | Correction_acknowledgement of causal_import_acknowledgement

and causal_confirmation =
  { native_confirmation : Goal_causal_admission_custody.Confirmation.t
  ; canonical : causal_canonical_acknowledgement
  ; imports : causal_import_acknowledgement list
  }

and causal_root_admitted =
  { admitted_reservation : causal_reservation
  ; admitted_acknowledgement : causal_canonical_acknowledgement
  ; admitted_confirmation : causal_confirmation
  ; admitted_owner : Recurrence_controller.Retained_owner.t
  }

and causal_admitted_views =
  { acknowledgement : causal_canonical_acknowledgement
  ; confirmation : causal_confirmation
  ; root_views : causal_root_admitted list
  }

and causal_correction_no_write =
  | Exact_duplicate
  | Superseded

and causal_correction_preparation =
  | Prepared of causal_root_write
  | No_write of causal_correction_no_write
  | Awaiting_initial_confirmation

and causal_terminal_purpose =
  | Initial_causal_import of causal_usage_observation
  | Factual_causal_correction of
      { source_acknowledgement : causal_import_acknowledgement
      ; observation : causal_usage_observation
      }
  | Causal_no_writer_close of causal_closed_before_writer

and causal_terminal_context =
  { terminal_actor : t
  ; terminal_basis : Child_accounting_basis.t
  ; terminal_owner : Recurrence_controller.Retained_owner.t
  ; terminal_reservation : causal_reservation
  ; terminal_purpose : causal_terminal_purpose
  }

and 'outcome causal_terminal_capture =
  { terminal_basis : Child_accounting_basis.t
  ; terminal_operation : 'outcome causal_terminal_operation
  }

and 'outcome causal_terminal_observed =
  { terminal_capture : 'outcome causal_terminal_capture
  ; terminal_current : Recurrence_controller.observation
  ; terminal_owner : Recurrence_controller.Retained_owner.t
  }

and _ causal_terminal_operation =
  | Import_causal_usage :
      causal_reservation * causal_usage_observation
      -> causal_import_acknowledgement causal_terminal_operation
  | Prepare_causal_correction :
      causal_import_acknowledgement * causal_usage_observation
      -> causal_correction_preparation causal_terminal_operation
  | Close_causal_pending :
      causal_reservation * causal_closed_before_writer
      -> unit causal_terminal_operation
  | Refresh_causal_admitted :
      causal_reservation * causal_canonical_acknowledgement * causal_confirmation
      -> causal_root_admitted causal_terminal_operation

and _ causal_route_request =
  | Capture_causal_routes :
      Runtime_source_owner.t
      * Goal_causal_admission_custody.Preparation.t
      * causal_reservation_set
      * Delegation_authority.Checked_ancestry.t option
      -> causal_route_capture causal_route_request
  | Consume_causal_routes :
      causal_route_observation
      -> causal_route_observation causal_route_request
  | Capture_causal_root :
      Runtime_source_owner.t * causal_route_observation
      -> causal_root_capture causal_route_request
  | Consume_causal_root :
      causal_root_observed
      -> causal_root_route list causal_route_request
  | Capture_causal_terminal :
      'outcome causal_terminal_operation
      -> 'outcome causal_terminal_capture causal_route_request
  | Consume_causal_terminal :
      'outcome causal_terminal_observed
      -> 'outcome causal_route_request
  | Commit_causal_correction :
      causal_root_write
      -> causal_correction_acknowledgement causal_route_request
  | Reconcile_causal_correction :
      causal_root_write
      -> causal_correction_acknowledgement causal_route_request
  | Retained_causal_correction :
      causal_import_acknowledgement * causal_usage_observation
      -> causal_root_write option causal_route_request
  | Abandon_causal_correction : causal_root_write -> unit causal_route_request
  | Reconcile_causal_import :
      causal_reservation * causal_usage_observation
      -> causal_import_acknowledgement causal_route_request
  | Capture_causal_usage :
      Runtime_source_owner.t * causal_usage_source
      -> causal_usage_capture causal_route_request
  | Consume_causal_usage :
      causal_usage_observed
      -> causal_usage_observation causal_route_request
  | Capture_causal_reservation :
      'outcome causal_reservation_operation
      -> 'outcome causal_reservation_capture causal_route_request
  | Consume_causal_reservation :
      'outcome causal_reservation_observed
      -> 'outcome causal_route_request

and causal_plan_arm =
  { slot : Goal_causal_admission_custody.Slot.t
  ; reservations : causal_reservation_set
  ; cause : Policy_cause_data.t
  ; host : inference_host_binding
  ; transport : causal_factual_transport
  ; mutable preview : causal_plan_preview option
  }

and causal_plan_preview =
  { selection : Policy_canonical_usage.Selection.t
  ; inline_policies : (Policy_cause_data.Goal_target.t * Goal_root_policy.t) list
  }

and governed_attempt_arms =
  | Descendant_attempt of Descendant_admission_slot.t
  | Policy_causal_attempt of causal_plan_arm
  | Combined_attempt of
      { descendant : Descendant_admission_slot.t
      ; causal : causal_plan_arm
      }

and governed_attempt_before_writer =
  | Descendant_before of Descendant_admission_data.Before_writer.t
  | Causal_before of causal_before_writer
  | Combined_before of Descendant_admission_data.Before_writer.t * causal_before_writer

and governed_attempt_ack =
  | Descendant_ack of Descendant_admission_data.Acknowledgement.t
  | Causal_ack of causal_canonical_acknowledgement
  | Combined_ack of
      Descendant_admission_data.Acknowledgement.t * causal_canonical_acknowledgement

and governed_attempt_confirmation =
  | Descendant_confirmation of Descendant_admission_data.Confirmation.t
  | Causal_confirmation of causal_confirmation
  | Combined_confirmation of
      Descendant_admission_data.Confirmation.t * causal_confirmation

and governed_attempt_views =
  | Descendant_views of Descendant_admission_data.Admitted_views.t
  | Causal_views of causal_admitted_views
  | Combined_views of Descendant_admission_data.Admitted_views.t * causal_admitted_views

and governed_attempt_closed =
  | Descendant_closed of Descendant_preparation.Closed_before_writer.t
  | Causal_closed of causal_closed_before_writer
  | Combined_closed of
      Descendant_preparation.Closed_before_writer.t * causal_closed_before_writer

and inherited_attempt_acknowledgement =
  { governed : governed_attempt_ack
  ; arms : governed_attempt_arms
  ; owner : Inference_owner.t
  ; handle : Inference_ledger.Handle.t
  ; original : Inherited_attempt_ack_original.t
  ; mutable confirmation : governed_attempt_confirmation option
  }

and inherited_attempt_plan =
  { arms : governed_attempt_arms
  ; owner : Inference_owner.t
  ; configuration : Inference.Observation.Configuration.t
  ; before : Inference_ledger.t
  ; after : Inference_ledger.t
  ; handle : Inference_ledger.Handle.t
  ; tracking : Inference_ledger.tracking
  ; original : Inherited_attempt_original.t
  ; mutable acknowledged : inherited_attempt_acknowledgement option
  }

and governed_scope_install =
  | Install_authored_graphs of Held_authored_start.t * Inference_owner.t list
  | Install_goal_graphs of Goal_continuation.runtime_scope * Inference_owner.t list
  | Install_initialization_graphs of Initialization_scope_data.t * Inference_owner.t list

and inherited_attempt_install =
  { plan : inherited_attempt_plan
  ; acknowledged : inherited_attempt_acknowledgement option
  ; causal : Goal_causal_admission_custody.Canonical_install.t option
  ; registration : Graph_owner.Prepared_registration.t
  ; scope : governed_scope_install option
  }

and inherited_attempt_prepared =
  | Ordinary of Inference_allocation.t
  | Inherited of inherited_attempt_plan

and inherited_attempt_committed =
  | Acknowledged of inherited_attempt_acknowledgement
  | Attempt_unconfirmed of inherited_attempt_plan

and _ inherited_attempt_request =
  | Capture_origin : Descendant_origin_observation.Captured.t inherited_attempt_request
  | Allocate_runtime :
      Descendant_origin_observation.Observed.t option
      * inference_execution
      * Inference_owner.t
      * Transcript.Scope.relation
      * Inference.Observation.Configuration.t
      -> inherited_attempt_prepared inherited_attempt_request
  | Prepare_legacy :
      Descendant_origin_observation.Observed.t option
      * Run_preparation.t option
      * Inference_owner.t
      * Transcript.Scope.relation
      * Agent_protocol.Id.Operation.t option
      * Agent_protocol.Id.Invocation.t option
      * Inference.Observation.Configuration.t
      -> inherited_attempt_prepared inherited_attempt_request
  | Preview :
      inherited_attempt_plan * Descendant_admission_data.Before_writer.t option
      -> unit inherited_attempt_request
  | Commit :
      inherited_attempt_plan * governed_attempt_before_writer
      -> inherited_attempt_committed inherited_attempt_request
  | Confirm :
      inherited_attempt_acknowledgement * governed_attempt_confirmation
      -> unit inherited_attempt_request
  | Refresh :
      inherited_attempt_acknowledgement
      * governed_attempt_confirmation
      * governed_attempt_views
      -> (unit -> unit) inherited_attempt_request
  | Seal : inherited_attempt_plan -> governed_attempt_closed inherited_attempt_request
  | Retire_closed :
      inherited_attempt_plan * governed_attempt_closed
      -> unit inherited_attempt_request
  | Release : inherited_attempt_acknowledgement -> unit inherited_attempt_request

module Inherited_attempt = struct
  module Original = Inherited_attempt_original

  module Acknowledgement = struct
    module Original = Inherited_attempt_ack_original

    type t = inherited_attempt_acknowledgement
  end

  module Plan = struct
    type t = inherited_attempt_plan
  end

  module Prepared = struct
    type t = inherited_attempt_prepared =
      | Ordinary of Inference_allocation.t
      | Inherited of Plan.t
  end

  module Committed = struct
    type t = inherited_attempt_committed =
      | Acknowledged of Acknowledgement.t
      | Attempt_unconfirmed of Plan.t
  end

  module Request = struct
    type 'a t = 'a inherited_attempt_request =
      | Capture_origin : Descendant_origin_observation.Captured.t t
      | Allocate_runtime :
          Descendant_origin_observation.Observed.t option
          * inference_execution
          * Inference_owner.t
          * Transcript.Scope.relation
          * Inference.Observation.Configuration.t
          -> inherited_attempt_prepared t
      | Prepare_legacy :
          Descendant_origin_observation.Observed.t option
          * Run_preparation.t option
          * Inference_owner.t
          * Transcript.Scope.relation
          * Agent_protocol.Id.Operation.t option
          * Agent_protocol.Id.Invocation.t option
          * Inference.Observation.Configuration.t
          -> inherited_attempt_prepared t
      | Preview :
          inherited_attempt_plan * Descendant_admission_data.Before_writer.t option
          -> unit t
      | Commit :
          inherited_attempt_plan * governed_attempt_before_writer
          -> inherited_attempt_committed t
      | Confirm :
          inherited_attempt_acknowledgement * governed_attempt_confirmation
          -> unit t
      | Refresh :
          inherited_attempt_acknowledgement
          * governed_attempt_confirmation
          * governed_attempt_views
          -> (unit -> unit) t
      | Seal : inherited_attempt_plan -> governed_attempt_closed t
      | Retire_closed : inherited_attempt_plan * governed_attempt_closed -> unit t
      | Release : inherited_attempt_acknowledgement -> unit t
  end
end

let error code message = Agent_protocol.Error.create code ~message ~retryable:false ()

module Resource_observation = struct
  module Resource_identity = Session_state.Spec.Resource_identity

  type actor = t
  type t = resource_observation

  let state (t : t) = t.original

  let check_actor (actor : actor) =
    if not (Int.equal actor.runtime_source_domain (Stdlib.Domain.self () :> int))
    then Error (error Conflict "resource observation belongs to another domain")
    else if actor.stopped || Option.is_some (Eio.Promise.peek actor.finished)
    then Error (error Server_shutting_down "resource observation Actor is closed")
    else if Option.is_some actor.lifecycle_fence
    then Error (error Conflict "session lifecycle is reserved")
    else if Option.is_some actor.runtime_retirement
    then Error (error Conflict "session runtime is retiring")
    else Ok ()
  ;;

  let capture actor =
    let open Result.Let_syntax in
    let%map () = check_actor actor in
    let original = actor.state in
    { actor; original; resource_identity = Resource_identity.capture original.spec }
  ;;

  let check_current (t : t) =
    let open Result.Let_syntax in
    let%bind () = check_actor t.actor in
    let current = t.actor.state in
    let original = t.original in
    let installation (state : Session_state.t) =
      Option.map state.run_state ~f:Run_state.installation
    in
    if
      Agent_protocol.Id.Session.equal
        original.identity.session_id
        current.identity.session_id
      && Int.equal original.identity.generation current.identity.generation
      && Option.equal
           Agent_protocol.Id.Principal.equal
           original.identity.creating_principal
           current.identity.creating_principal
      && Option.equal
           Run_source_installation.equal
           (installation original)
           (installation current)
      && Session_state.Runtime_initialization.equal
           original.runtime_initialization
           current.runtime_initialization
      && Bool.equal original.pending_initial_start current.pending_initial_start
      && Int64.equal
           original.counters.owner_lease_generation
           current.counters.owner_lease_generation
      && Int64.equal original.stop_epoch current.stop_epoch
      && Option.equal Int64.equal original.parent_stop_epoch current.parent_stop_epoch
      && (phys_equal original.spec current.spec
          || Resource_identity.equal
               t.resource_identity
               (Resource_identity.capture current.spec))
    then Ok current
    else Error (error Conflict "session resource observation is stale")
  ;;

  let list_recovery_windows t ~actor ~generation ~state page =
    let open Result.Let_syntax in
    let%bind current = check_current t in
    Recovery_window_page.list
      (Lazy.force t.actor.recovery_window_cursor) current ~actor ~generation ~state page
  ;;

end

module Recurrence_target_invalidation = struct
  type actor = t
  type t = recurrence_target_invalidation

  let reason t ~controller definition =
    let module P = Agent_protocol in
    let module Target = Recurrence_entry.Pause.Target in
    let open Result.Let_syntax in
    let%bind () = Resource_observation.check_actor controller in
    let%bind owner =
      Result.of_option
        controller.recurrence_controller
        ~error:(error Conflict "target evidence has no actual controller Store")
    in
    let ref_ =
      Recurrence_definition.key definition |> Recurrence_identity.Definition.controller
    in
    if
      (not (phys_equal t.controller_actor controller))
      || not (P.Session_ref.equal (Recurrence_controller.session owner) ref_)
    then Error (error Conflict "target evidence belongs to another controller")
    else (
      match Recurrence_target.view (Recurrence_definition.target definition) with
      | Fresh_child _ -> Ok None
      | Existing_session { session; source; _ } ->
        let same_target = P.Id.Session.equal (P.Session_ref.session_id session) in
        if
          not
            (P.Id.Server.equal
               (P.Session_ref.server_id ref_)
               (P.Session_ref.server_id session))
        then Ok None
        else (
          match t.target_fact with
          | Removed_target proof ->
            let removal = Agent_store.Session_store.Command_receipts.Removal.fact proof in
            Ok
              (Option.some_if
                 (Recurrence_controller.owns_removal owner proof
                  && same_target removal.session_id
                  && removal.generation >= source.generation)
                 Target.Removed)
          | Target_source observation ->
            let%map state = Resource_observation.check_current observation in
            if
              (not (same_target state.identity.session_id))
              || not
                   (Option.exists
                      observation.actor.recurrence_controller
                      ~f:(Recurrence_controller.same_store owner))
            then None
            else if state.identity.generation > source.generation
            then Some Target.Superseded
            else if state.identity.generation < source.generation
            then None
            else
              Option.bind state.run_state ~f:(fun index ->
                let installation = Run_state.installation index in
                if Int64.(installation.epoch <= source.installation_epoch)
                then None
                else (
                  match installation.source with
                  | None -> Some Target.Source_retired
                  | Some _ -> Some Target.Superseded))))
  ;;

  let observe ~controller target_fact definition =
    let t = { controller_actor = controller; target_fact } in
    Result.map (reason t ~controller definition) ~f:(Option.map ~f:(fun _ -> t))
  ;;

  let removed ~controller proof definition =
    observe ~controller (Removed_target proof) definition
  ;;

  let changed_source ~controller observation definition =
    observe ~controller (Target_source observation) definition
  ;;
end

let find_inference_graph_custody t owner =
  if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
  then None
  else
    List.find t.inference_owners ~f:(fun custody ->
      phys_equal (Inference_graph_custody.owner custody) owner)
;;

let owns_inference_graph t owner =
  Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
  && List.exists t.inference_owners ~f:(fun custody ->
    phys_equal (Inference_graph_custody.owner custody) owner)
;;

let inference_graph_owners t =
  if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
  then invalid_arg "Session_actor.inference_graph_owners: foreign domain";
  List.map t.inference_owners ~f:Inference_graph_custody.owner
;;

(* The existing Actor retains one exact prepared root writer. This is a
   negative fence, not another owner or an arbitrary persistence executor. *)
module Causal_canonical_custody = struct
  module C = Goal_causal_admission_custody

  (* This transports the original invocation; it neither elects another writer
     nor stores a second lifecycle. SAME governed occupancy retains the write. *)
  module Fence = struct
    type t =
      | Unrestricted
      | Elected of C.Slot.t * C.Canonical_write.t * Session_commit_attempt.invocation
  end

  let check_fence t ~requested fence =
    let open Result.Let_syntax in
    let actual =
      match t.governed_admission_slot with
      | Some (Policy_causal { causal; _ } | Combined { causal; _ }) -> Some causal
      | None | Some (Descendant _) -> None
    in
    match actual with
    | None ->
      (match fence with
       | Fence.Unrestricted -> Ok ()
       | Elected _ -> Error (error Conflict "canonical writer lost its SAME occupancy"))
    | Some slot ->
      let%bind () = C.Slot.check_owner slot ~issuer:t.inference_owner_identity in
      (match slot.phase, fence with
       | Writer_prepared actual, Fence.Elected (selected, write, invocation) ->
         let%bind () =
           if
             phys_equal slot selected
             && phys_equal actual write
             && phys_equal write.previous t.state
             && phys_equal write.candidate requested
           then Ok ()
           else Error (error Conflict "canonical writer lost its exact Actor/candidate")
         in
         if slot.cancellation_requested
         then Error (error Conflict "causal canonical admission was cancelled")
         else Session_commit_attempt.check_invocation write.writer invocation
       | Writer_prepared write, Unrestricted ->
         if
           (not (phys_equal write.candidate requested))
           && Session_commit_attempt.no_writer write.writer
         then Ok ()
         else Session_commit_attempt.unresolved write.writer
       | (Preparing | Acknowledged _ | Sealed _ | Released _), Unrestricted -> Ok ()
       | (Preparing | Acknowledged _ | Sealed _ | Released _), Elected _ ->
         Error (error Conflict "canonical writer changed its exact elected phase"))
  ;;
end

module Causal_root_custody = struct
  type actor = t

  module Fence = struct
    type t =
      | Unrestricted
      | First of causal_root_write * Session_commit_attempt.invocation
  end

  let check_owner (t : actor) (write : causal_root_write) =
    let module C = Goal_causal_admission_custody in
    match write.acknowledgement with
    | Causal_reserved plan ->
      C.Reserve_install.check_basis
        plan
        ~issuer:t.inference_owner_identity
        ~state:t.state
        ~candidate:write.candidate
    | Causal_held plan ->
      C.Hold_install.check_basis
        plan
        ~issuer:t.inference_owner_identity
        ~state:t.state
        ~candidate:write.candidate
    | Causal_terminal { plan; _ } ->
      C.Terminal_install.check_basis
        plan
        ~issuer:t.inference_owner_identity
        ~state:t.state
        ~candidate:write.candidate
  ;;

  let check_fence (t : actor) ~requested = function
    | Fence.Unrestricted ->
      (match t.causal_root_write with
       | None -> Ok ()
       | Some write -> Session_commit_attempt.unresolved write.writer)
    | First (write, invocation) ->
      let open Result.Let_syntax in
      let%bind () =
        if
          Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
          && Option.exists t.causal_root_write ~f:(phys_equal write)
          && phys_equal write.previous t.state
          && phys_equal write.candidate requested
        then Ok ()
        else Error (error Conflict "causal root writer lost its exact Actor/candidate")
      in
      let%bind () = check_owner t write in
      Session_commit_attempt.check_invocation write.writer invocation
  ;;

  let finish_writer = function
    | Fence.Unrestricted -> ()
    | First (write, invocation) ->
      Session_commit_attempt.finish_invocation write.writer invocation
  ;;

  let begin_writer (t : actor) ~requested =
    let open Result.Let_syntax in
    let%bind fence =
      match t.causal_root_write with
      | None -> Ok Fence.Unrestricted
      | Some write ->
        let%bind () =
          if phys_equal write.candidate requested
          then check_owner t write
          else Session_commit_attempt.unresolved write.writer
        in
        let%map invocation = Session_commit_attempt.begin_invocation write.writer in
        Fence.First (write, invocation)
    in
    match check_fence t ~requested fence with
    | Ok () -> Ok fence
    | Error failure ->
      finish_writer fence;
      Error failure
  ;;

  let install (t : actor) (write : causal_root_write) =
    let module C = Goal_causal_admission_custody in
    (match write.acknowledgement with
     | Causal_reserved plan -> C.Reserve_install.install plan
     | Causal_held plan -> C.Hold_install.install plan
     | Causal_terminal { plan; initial_install; _ } ->
       C.Terminal_install.install plan;
       (match initial_install with
        | None -> ()
        | Some prepared ->
          prepared.initial_receipt.installed_ack <- prepared.native_write.acknowledged;
          prepared.attempt.initial_import <- prepared.retained));
    t.causal_root_write <- None
  ;;
end

let check_published_policy_target t (published : Policy_restoration_data.published) =
  let open Result.Let_syntax in
  let%bind () =
    if
      phys_equal published.issuer t.inference_owner_identity
      &&
      match t.policy_restoration with
      | Published actual -> phys_equal actual published
      | Vacant | Constructing _ | Native_constructing _ -> false
    then Ok ()
    else Error (error Conflict "restored policy belongs to another Actor")
  in
  Policy_restoration_data.Published.check published
;;

module Delegated_policy_custody = struct
  module Data = Delegated_policy_claim_data
  module State = Delegated_policy_claim_state

  type actor = t

  let check_capture (t : actor) (capture : Data.t) =
    let open Result.Let_syntax in
    let%bind () =
      if Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
      then Ok ()
      else Error (error Conflict "delegated policy claim belongs to another Actor domain")
    in
    let%bind () = State.check_owner capture.state ~issuer:t.inference_owner_identity in
    if
      Int.equal capture.domain t.runtime_source_domain
      && phys_equal capture.issuer t.inference_owner_identity
    then Ok ()
    else Error (error Conflict "delegated policy claim belongs to another actual Actor")
  ;;

  let check_access (t : actor) (capture : Data.t) =
    let open Result.Let_syntax in
    let%bind () = check_capture t capture in
    match capture.access, t.state.lifecycle.desired, t.state.halted, t.state.failure with
    | Running, Running, false, None -> Ok ()
    | Policy_only access, Stopped, false, None ->
      Runtime_builder.Policy_access.check access ~expected:t.state
    | Restored_unloaded published, (Running | Stopped), false, None ->
      check_published_policy_target t published
    | (Running | Policy_only _ | Restored_unloaded _), (Running | Stopped), _, _ ->
      Error
        (error
           Conflict
           "delegated policy access no longer matches its selected lifecycle")
  ;;

  let pending (t : actor) =
    if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
    then invalid_arg "delegated policy claim: foreign Actor domain";
    Option.is_some t.delegated_policy_claim
  ;;

  let prepare_callback_ack (t : actor) borrow =
    let open Result.Let_syntax in
    match t.delegated_policy_claim with
    | None -> Ok None
    | Some capture ->
      let%bind () = check_capture t capture in
      State.Callback_acknowledgement.prepare capture.state ~borrow
      |> Result.map ~f:Option.some
  ;;

  let check_callback_ack acknowledgement =
    Option.value_map
      acknowledgement
      ~default:(Ok ())
      ~f:State.Callback_acknowledgement.check
  ;;

  module Fence = struct
    type t =
      | Unrestricted
      | First of queued_event_borrow State.attempt * Session_commit_attempt.invocation
  end

  let check_fence (t : actor) ~requested fence =
    match t.delegated_policy_claim with
    | None -> Ok ()
    | Some capture ->
      let open Result.Let_syntax in
      let%bind () = check_capture t capture in
      (match State.phase capture.state with
       | Waiting | Activated _ | Callback_acknowledged _ | Released -> Ok ()
       | Prepared attempt ->
         let writer = State.Attempt.writer attempt in
         (match fence with
          | Fence.First (selected, invocation)
            when phys_equal selected attempt
                 && phys_equal (State.Attempt.candidate attempt) requested ->
            Session_commit_attempt.check_invocation writer invocation
          | Unrestricted | First _ ->
            if
              (not (phys_equal (State.Attempt.candidate attempt) requested))
              && Session_commit_attempt.no_writer writer
            then Ok ()
            else Session_commit_attempt.unresolved writer))
  ;;

  let finish_writer = function
    | Fence.Unrestricted -> ()
    | First (attempt, invocation) ->
      Session_commit_attempt.finish_invocation (State.Attempt.writer attempt) invocation
  ;;

  let begin_writer (t : actor) ~requested =
    let open Result.Let_syntax in
    let attempt =
      Option.bind t.delegated_policy_claim ~f:(fun capture ->
        match State.phase capture.state with
        | Prepared attempt when phys_equal (State.Attempt.candidate attempt) requested ->
          Some attempt
        | Waiting | Prepared _ | Activated _ | Callback_acknowledged _ | Released -> None)
    in
    let%bind fence =
      match attempt with
      | None -> Ok Fence.Unrestricted
      | Some attempt ->
        let%map invocation =
          Session_commit_attempt.begin_invocation (State.Attempt.writer attempt)
        in
        Fence.First (attempt, invocation)
    in
    match check_fence t ~requested fence with
    | Ok () -> Ok fence
    | Error failure ->
      finish_writer fence;
      Error failure
  ;;
end

module Constructor_model_custody = struct
  module Data = Constructor_model_data

  type actor = t

  let on_domain (t : actor) =
    Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
  ;;

  let check_capture (t : actor) (capture : Data.capture) =
    if
      on_domain t
      && Int.equal capture.domain t.runtime_source_domain
      && phys_equal capture.issuing_actor t.initialization_owner
      && phys_equal capture.scope.owner t.initialization_owner
    then Ok ()
    else
      Error (error Conflict "constructor Model producer belongs to another Actor/domain")
  ;;

  let check_call (t : actor) (call : Data.call) =
    let open Result.Let_syntax in
    let%bind () = check_capture t call.capture in
    if
      Option.exists t.constructor_models ~f:(phys_equal call.group)
      && phys_equal call.group.scope call.capture.scope
      && List.exists call.group.calls ~f:(phys_equal call)
    then Ok ()
    else Error (error Conflict "constructor Model producer lost its actual Init group")
  ;;

  let pending_call (call : Data.call) =
    match call.phase with
    | Joined _ | Abandoned -> false
    | Admission_attempt _
    | Admitted _
    | Claim_attempt _
    | Claimed _
    | Selected _
    | Terminal_attempt _
    | Cancel_attempt _ -> true
  ;;

  let pending (t : actor) =
    if not (on_domain t)
    then invalid_arg "constructor Model retirement belongs to another Eio domain";
    Option.exists t.constructor_models ~f:(fun group ->
      List.exists group.calls ~f:pending_call)
  ;;

  let prune (t : actor) =
    match t.constructor_models with
    | Some group when not (List.exists group.calls ~f:pending_call) ->
      t.constructor_models <- None
    | Some _ | None -> ()
  ;;

  let canonical_of_call (call : Data.call) =
    match call.phase with
    | Admission_attempt plan -> Some plan.canonical
    | Claim_attempt plan -> Some plan.canonical
    | Terminal_attempt plan -> Some plan.canonical
    | Cancel_attempt plan -> Some plan.canonical
    | Admitted _ | Claimed _ | Selected _ | Joined _ | Abandoned -> None
  ;;

  let no_writer (canonical : Data.canonical) =
    Session_commit_attempt.no_writer canonical.attempt
  ;;

  let unresolved (canonical : Data.canonical) =
    Session_commit_attempt.unresolved canonical.attempt
  ;;

  let perform (canonical : Data.canonical) f =
    Session_commit_attempt.perform canonical.attempt f
  ;;

  let canonical t ~candidate ~job_custody ~acknowledgement =
    Data.
      { previous = t.state
      ; candidate
      ; job_custody
      ; acknowledgement
      ; attempt =
          Session_commit_attempt.create
            ~context:Constructor_model
            ~previous:t.state
            ~candidate
      }
  ;;

  let check_canonical (t : actor) (call : Data.call) canonical =
    let open Result.Let_syntax in
    let%bind () = check_call t call in
    let%bind () =
      Initialization_scope_data.Acknowledgement.check_basis canonical.Data.acknowledgement
    in
    let%bind () =
      Job_custody.Update.check_before_commit
        canonical.job_custody
        ~current:t.job_agent_custody
    in
    if
      phys_equal t.state canonical.previous
      && phys_equal canonical.acknowledgement.scope call.group.scope
    then Ok ()
    else Error (error Conflict "constructor Model canonical basis changed")
  ;;

  let retain_admission (t : actor) (capture : Data.capture) ~queued canonical =
    let open Result.Let_syntax in
    let%bind () = check_capture t capture in
    let%bind () =
      match capture.phase with
      | Waiting -> Ok ()
      | Pending _ | Owned _ | No_admission ->
        Error (error Conflict "constructor Model producer already selected an admission")
    in
    let%bind group =
      match t.constructor_models with
      | Some group when phys_equal group.scope capture.scope && not group.ended ->
        Ok group
      | Some _ ->
        Error (error Conflict "another constructor retains unsettled Model work")
      | None ->
        Ok
          Data.
            { issuing_actor = t.initialization_owner
            ; domain = t.runtime_source_domain
            ; scope = capture.scope
            ; ended = false
            ; calls = []
            }
    in
    let call = Data.{ group; capture; phase = Admission_attempt { queued; canonical } } in
    let calls = call :: group.calls in
    t.constructor_models <- Some group;
    group.calls <- calls;
    capture.phase <- Pending call;
    Ok call
  ;;

  let installed (t : actor) (call : Data.call) canonical =
    if
      (not (phys_equal t.state canonical.Data.candidate.state))
      || not (phys_equal call.group.scope.acknowledged canonical.acknowledgement.incoming)
    then invalid_arg "constructor Model phase installed without its actual State/Init ACK"
  ;;

  let abandon_admission (t : actor) (call : Data.call) canonical =
    if no_writer canonical
    then (
      Job_custody.Update.discard canonical.job_custody;
      call.phase <- Abandoned;
      call.capture.phase <- No_admission;
      prune t)
  ;;

  let restore_control (call : Data.call) (plan : Data.control) =
    call.phase
    <- (match plan.prior with
        | Was_admitted queued -> Admitted queued
        | Was_claimed running -> Claimed running
        | Was_selected selection -> Selected selection)
  ;;

  let install_callback_advance (t : actor) (plan : Data.callback_advance) =
    let attempt_unentered =
      Option.for_all plan.selection.attempt ~f:(fun attempt ->
        match
          ( Session_commit_observation.progress
              attempt.Callback_retirement_data.Attempt.observation
          , Session_commit_observation.outcome attempt.observation )
        with
        | Unobserved, Not_called | Before_writer, (Returned (Error _) | Raised _) -> true
        | ( (Unobserved | Before_writer | Writer_entered _ | Journal_acknowledged _)
          , (Not_called | In_progress | Returned _ | Raised _) ) -> false)
    in
    if
      phys_equal t.state plan.candidate.state
      && Option.exists t.queued_event_borrow ~f:(phys_equal plan.borrow)
      && Option.exists plan.borrow.terminal_selection ~f:(phys_equal plan.selection)
      && Option.equal phys_equal plan.selection.constructor_basis plan.basis
      && Option.equal phys_equal plan.selection.attempt plan.attempt
      && phys_equal plan.acknowledgement.scope.acknowledged plan.acknowledgement.incoming
      && attempt_unentered
    then (
      plan.selection.constructor_basis
      <- Some (Initialization_scope_data.Acknowledgement.expected plan.acknowledgement);
      plan.selection.attempt <- None)
    else invalid_arg "constructor Job ACK lost its exact ended callback owner"
  ;;

  let install_control (t : actor) (call : Data.call) (plan : Data.control) =
    (match call.phase with
     | Cancel_attempt actual when phys_equal actual plan -> ()
     | Admission_attempt _
     | Admitted _
     | Claim_attempt _
     | Claimed _
     | Selected _
     | Terminal_attempt _
     | Cancel_attempt _
     | Joined _
     | Abandoned -> invalid_arg "constructor cancellation lost its actual selected plan");
    installed t call plan.canonical;
    Option.iter plan.callback_advance ~f:(install_callback_advance t);
    let selected =
      match plan.prior with
      | Was_selected selection -> Some selection
      | Was_admitted _ | Was_claimed _ -> None
    in
    call.phase <- Joined { selected; winner = plan.cancelled };
    prune t
  ;;

  module Fence = struct
    type t =
      | Unrestricted
      | First of Data.canonical * Session_commit_attempt.invocation
  end

  let check_fence (t : actor) ~requested (fence : Fence.t) =
    match t.constructor_models with
    | None -> Ok ()
    | Some group ->
      List.fold_result group.calls ~init:() ~f:(fun () call ->
        match canonical_of_call call with
        | None -> Ok ()
        | Some canonical ->
          (match fence with
           | First (selected, invocation)
             when phys_equal selected canonical
                  && phys_equal canonical.candidate requested ->
             Session_commit_attempt.check_invocation canonical.attempt invocation
           | Unrestricted | First _ ->
             if (not (phys_equal canonical.candidate requested)) && no_writer canonical
             then Ok ()
             else unresolved canonical))
  ;;

  let begin_writer (t : actor) ~requested =
    let open Result.Let_syntax in
    let candidate =
      Option.bind t.constructor_models ~f:(fun group ->
        List.find_map group.calls ~f:(fun call ->
          Option.bind (canonical_of_call call) ~f:(fun canonical ->
            Option.some_if (phys_equal canonical.candidate requested) canonical)))
    in
    let%bind fence =
      match candidate with
      | None -> Ok Fence.Unrestricted
      | Some canonical ->
        let%map invocation = Session_commit_attempt.begin_invocation canonical.attempt in
        Fence.First (canonical, invocation)
    in
    match check_fence t ~requested fence with
    | Ok () -> Ok fence
    | Error failure ->
      (match fence with
       | Unrestricted -> ()
       | First (canonical, invocation) ->
         Session_commit_attempt.finish_invocation canonical.attempt invocation);
      Error failure
  ;;

  let finish_writer = function
    | Fence.Unrestricted -> ()
    | First (canonical, invocation) ->
      Session_commit_attempt.finish_invocation canonical.attempt invocation
  ;;

  let before_admission (t : actor) =
    match t.constructor_models with
    | None -> Ok ()
    | Some group ->
      (match List.find_map group.calls ~f:canonical_of_call with
       | None -> Ok ()
       | Some canonical -> unresolved canonical)
  ;;

  let before_other_writer (t : actor) (except : Data.call) =
    match t.constructor_models with
    | None -> Ok ()
    | Some group ->
      List.fold_result group.calls ~init:() ~f:(fun () call ->
        if phys_equal call except
        then Ok ()
        else (
          match canonical_of_call call with
          | Some canonical when not (no_writer canonical) -> unresolved canonical
          | Some _ | None -> Ok ()))
  ;;

  let before_callback_terminal (t : actor) scope =
    match t.constructor_models with
    | Some group when phys_equal group.scope scope ->
      (match List.find group.calls ~f:pending_call with
       | Some call ->
         (match call.capture.result with
          | Some (Selected_result { completion = Clock_failed (exn, backtrace); _ }) ->
            Exn.raise_with_original_backtrace exn backtrace
          | None | Some (Selecting _ | Selected_result { completion = Sample _; _ }) ->
            (match canonical_of_call call with
             | Some canonical -> unresolved canonical
             | None ->
               Error
                 (error
                    Conflict
                    "constructor Model producer must settle before its callback")))
       | None -> Ok ())
    | Some _ | None -> Ok ()
  ;;
end

(* Source lifetime only: native source/permission and root policy guards remain
   independent. Complete State/episode progress is not source retirement. *)
let physical_descendant_host = function
  | Physical_only physical | Governed { physical; _ } -> physical
;;

let check_descendant_host t (binding : Descendant_host_data.Binding.t) =
  if
    (not t.stopped)
    && Option.is_none (Eio.Promise.peek t.finished)
    && Option.is_none t.lifecycle_fence
    && Option.is_none t.runtime_retirement
    && Int.equal binding.domain (Stdlib.Domain.self () :> int)
    && phys_equal binding.issuing_actor t.inference_owner_identity
    && Option.exists t.runtime_source_owner ~f:(fun owner ->
      Runtime_source_owner.matches binding.source_owner owner)
    && Option.exists t.recurrence_controller ~f:(phys_equal binding.controller)
    && Option.exists t.descendant_host_binding ~f:(fun actual ->
      phys_equal (physical_descendant_host actual) binding)
    && not binding.closed
  then Ok ()
  else Error (error Conflict "descendant source binding is no longer current")
;;

let capture_descendant_host t =
  let open Result.Let_syntax in
  let%bind binding =
    Result.of_option
      (Option.map t.descendant_host_binding ~f:physical_descendant_host)
      ~error:(error Permission_denied "descendant source host is unavailable")
  in
  let%map () = check_descendant_host t binding in
  binding
;;

let require_recurrence_controller t =
  Result.of_option
    t.recurrence_controller
    ~error:(error Invalid_state "recurrence controller lifecycle owner is not installed")
;;

let inherited_turn_required (state : Session_state.t) =
  let open Inherited_turn.Origin_requirement in
  match Option.bind state.goal_descendants ~f:Goal_descendants.origin with
  | Some origin ->
    if List.is_empty (Agent_store.Delegation_goal_origin.scopes origin)
    then Ordinary
    else Scoped
  | None -> if Option.is_none state.spec.delegation then Ordinary else Need_private_origin
;;

(* Factual accounting operations require the same live Factory/Actor owner. *)
let child_accounting_owner t ~source_owner =
  let open Result.Let_syntax in
  let%bind () =
    if
      (not t.stopped)
      && Option.is_none (Eio.Promise.peek t.finished)
      && Option.is_none t.lifecycle_fence
      && Option.exists
           t.runtime_source_owner
           ~f:(Runtime_source_owner.matches source_owner)
    then Ok ()
    else Error (error Conflict "child accounting lost its actual Factory/Actor owner")
  in
  require_recurrence_controller t
;;

(* Private common basis only. Request-specific Store/record/authorization
   observations belong outside the mailbox, not in this finite capture/check. *)
let capture_child_accounting_basis t ~source_owner =
  let%map.Result controller = child_accounting_owner t ~source_owner in
  Child_accounting_basis.
    { issuing_actor = t.inference_owner_identity
    ; domain = (Stdlib.Domain.self () :> int)
    ; state = t.state
    ; controller
    ; source_owner
    }
;;

let check_child_accounting_identity t (basis : Child_accounting_basis.t) =
  let open Result.Let_syntax in
  let%bind controller = child_accounting_owner t ~source_owner:basis.source_owner in
  if
    phys_equal basis.issuing_actor t.inference_owner_identity
    && Int.equal basis.domain (Stdlib.Domain.self () :> int)
    && phys_equal basis.controller controller
  then Ok ()
  else
    Error (error Conflict "child accounting Actor/controller/State observation changed")
;;

let check_child_accounting_capture t (basis : Child_accounting_basis.t) =
  let%bind.Result () = check_child_accounting_identity t basis in
  if phys_equal basis.state t.state
  then Ok ()
  else
    Error (error Conflict "child accounting Actor/controller/State observation changed")
;;

let check_child_accounting_basis t basis ~current =
  let%bind.Result () = check_child_accounting_capture t basis in
  if Recurrence_controller.is_current current
  then Ok ()
  else Error (error Conflict "child accounting Store observation changed")
;;

(* Factual causal completion may run while the lifecycle owner joins the
   retiring runtime. It keeps the actual Factory/Controller/State basis and
   retained Handle/writer, without reopening admission or refreshing policy. *)
module Causal_factual_basis = struct
  let owner t ~source_owner =
    let open Result.Let_syntax in
    let%bind () =
      if Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
      then Ok ()
      else Error (error Conflict "causal factual basis belongs to another Actor domain")
    in
    let%bind () =
      if
        (not t.stopped)
        && Option.is_none (Eio.Promise.peek t.finished)
        && Option.exists
             t.runtime_source_owner
             ~f:(Runtime_source_owner.matches source_owner)
      then Ok ()
      else
        Error (error Conflict "causal factual basis lost its actual Factory/Actor owner")
    in
    let%bind controller = require_recurrence_controller t in
    let%map () = Recurrence_controller.check_retained_available controller in
    controller
  ;;

  let capture t ~source_owner =
    let%map.Result controller = owner t ~source_owner in
    Child_accounting_basis.
      { issuing_actor = t.inference_owner_identity
      ; domain = (Stdlib.Domain.self () :> int)
      ; state = t.state
      ; controller
      ; source_owner
      }
  ;;

  let check_capture t (basis : Child_accounting_basis.t) =
    let open Result.Let_syntax in
    let%bind controller = owner t ~source_owner:basis.source_owner in
    if
      phys_equal basis.issuing_actor t.inference_owner_identity
      && Int.equal basis.domain (Stdlib.Domain.self () :> int)
      && phys_equal basis.controller controller
      && phys_equal basis.state t.state
    then Ok ()
    else
      Error (error Conflict "causal factual Actor/controller/State observation changed")
  ;;

  let check_current t basis ~current =
    let%bind.Result () = check_capture t basis in
    if Recurrence_controller.is_current current
    then Ok ()
    else Error (error Conflict "causal factual Store observation changed")
  ;;
end

let child_origin_ancestry (state : Session_state.t) ~source_owner ~controller ancestry =
  let module D = Agent_store.Delegation_store in
  let module Origin = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  match state.spec.delegation, ancestry with
  | None, None -> Ok (Origin.unrelated, fun (_ : Session_state.t) -> Ok ())
  | None, Some _ ->
    Error (error Conflict "child origin ancestry differs from the actual root Spec")
  | Some _, None ->
    Error (error Permission_denied "child origin requires its actual private ancestry")
  | Some reference, Some ancestry ->
    let%bind () =
      if Delegation_authority.Checked_ancestry.issued_by ancestry ~source_owner
      then Ok ()
      else Error (error Conflict "child origin ancestry has a foreign Factory issuer")
    in
    let records = Delegation_authority.Checked_ancestry.records ancestry in
    let%bind record =
      match records with
      | record :: _ when D.Reference.equal (D.reference record) reference -> Ok record
      | _ :: _ | [] ->
        Error (error Conflict "child origin ancestry differs from its actual Spec")
    in
    let%bind inherited =
      Result.of_option
        record.admission.goal_origin
        ~error:
          (error
             Permission_denied
             "child origin inherited Goal ancestry is historically unknown")
    in
    let check_projection (state : Session_state.t) =
      let%bind () =
        if Option.exists state.spec.delegation ~f:(D.Reference.equal reference)
        then Ok ()
        else Error (error Conflict "child origin parent delegation changed")
      in
      let scoped = not (List.is_empty (Origin.scopes inherited)) in
      match state.goal_descendants with
      | None ->
        if scoped
        then
          Error
            (error Permission_denied "inherited child origin has no scoped accounting")
        else Ok ()
      | Some accounting ->
        if
          not
            (Agent_protocol.Session_ref.equal
               (Goal_descendants.session accounting)
               (Recurrence_controller.session controller))
        then
          Error (error Conflict "inherited child accounting belongs to another session")
        else (
          match Goal_descendants.origin accounting with
          | Some actual when Origin.equal inherited actual -> Ok ()
          | Some _ ->
            Error
              (error Conflict "child accounting origin differs from private admission")
          | None ->
            if scoped
            then
              Error
                (error Permission_denied "inherited child accounting origin is unknown")
            else Ok ())
    in
    let refresh (observed_state : Session_state.t) =
      let%bind () =
        List.fold_result records ~init:() ~f:(fun () expected ->
          let%bind actual =
            Recurrence_controller.resolve_delegation controller (D.reference expected)
          in
          if
            D.equal_record actual expected
            && Option.is_none actual.revocation
            && D.equal_stage actual.stage Linked
          then Ok ()
          else Error (error Conflict "child origin private ancestry changed"))
      in
      check_projection observed_state
    in
    let%map () = check_projection state in
    inherited, refresh
;;

let capture_descendant_origin_observation t =
  let open Result.Let_syntax in
  let%bind binding = capture_descendant_host t in
  let%map basis = capture_child_accounting_basis t ~source_owner:binding.source_owner in
  Descendant_origin_observation.Captured.{ basis; binding }
;;

let check_descendant_origin_capture
      t
      (captured : Descendant_origin_observation.Captured.t)
  =
  let%bind.Result () = check_child_accounting_capture t captured.basis in
  check_descendant_host t captured.binding
;;

let descendant_origin_leaf (captured : Descendant_origin_observation.Captured.t) ancestry =
  let module D = Agent_store.Delegation_store in
  let open Result.Let_syntax in
  let%bind () =
    if
      Delegation_authority.Checked_ancestry.issued_by
        ancestry
        ~source_owner:captured.basis.source_owner
    then Ok ()
    else Error (error Conflict "origin ancestry has a foreign Factory issuer")
  in
  match
    ( captured.basis.state.spec.delegation
    , Delegation_authority.Checked_ancestry.records ancestry )
  with
  | Some reference, record :: _ when D.Reference.equal reference (D.reference record) ->
    Ok record
  | (None | Some _), (_ :: _ | []) ->
    Error (error Conflict "origin ancestry differs from actual delegated source")
;;

let check_descendant_origin_observation
      t
      (observed : Descendant_origin_observation.Observed.t)
  =
  let module D = Agent_store.Delegation_store in
  let open Result.Let_syntax in
  let captured = observed.captured in
  let%bind () = check_descendant_origin_capture t captured in
  let%bind () = check_child_accounting_basis t captured.basis ~current:observed.current in
  let%bind leaf = descendant_origin_leaf captured observed.ancestry in
  let%bind () =
    if
      D.equal_record leaf observed.record
      && D.equal_stage observed.record.stage Linked
      && Option.is_none observed.record.revocation
    then Ok ()
    else Error (error Conflict "origin private admission changed")
  in
  let%bind origin, _ =
    child_origin_ancestry
      captured.basis.state
      ~source_owner:captured.basis.source_owner
      ~controller:captured.basis.controller
      (Some observed.ancestry)
  in
  if List.is_empty (Agent_store.Delegation_goal_origin.scopes origin)
  then Ok ()
  else
    Error
      (error Permission_denied "delegated source lacks its inherited scoped accounting")
;;

(* Shared outer Store kernel for birth and native-ACK factual sources. The
   captured immutable projection is fenced after each await before its error is
   interpreted; no filesystem observation enters a finite Actor request. *)
let observe_child_accounting_source t (basis : Child_accounting_basis.t) ~reference =
  let open Result.Let_syntax in
  let%bind () = check_child_accounting_capture t basis in
  let record = Recurrence_controller.resolve_delegation basis.controller reference in
  let%bind () = check_child_accounting_capture t basis in
  let%bind record = record in
  let observation = Recurrence_controller.observe basis.controller basis.state in
  let%bind () = check_child_accounting_capture t basis in
  let%map current = observation in
  record, current
;;

let observe_descendant_origin_external
      t
      (captured : Descendant_origin_observation.Captured.t)
  =
  let open Result.Let_syntax in
  let%bind () = check_descendant_origin_capture t captured in
  let%bind check_ancestry =
    Result.of_option
      captured.binding.check_ancestry
      ~error:
        (error Permission_denied "delegated source has no actual private ancestry guard")
  in
  let ancestry = check_ancestry () in
  let%bind () = check_descendant_origin_capture t captured in
  let%bind ancestry = ancestry in
  let%bind leaf = descendant_origin_leaf captured ancestry in
  let observation =
    observe_child_accounting_source
      t
      captured.basis
      ~reference:(Agent_store.Delegation_store.reference leaf)
  in
  let%bind () = check_descendant_origin_capture t captured in
  let%map record, current = observation in
  Descendant_origin_observation.Observed.{ captured; ancestry; record; current }
;;

(* Captures the actual native producer basis. No public constructor is exposed. *)
let capture_descendant_preparation t ~occurrence ~writer_attempted =
  let module P = Agent_protocol in
  let module O = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  let before = t.state in
  let%bind controller = require_recurrence_controller t in
  let session = Recurrence_controller.session controller in
  let%bind source_owner =
    Result.of_option
      t.runtime_source_owner
      ~error:(error Permission_denied "child preparation has no actual Factory issuer")
  in
  let%bind accounting =
    Result.of_option
      before.goal_descendants
      ~error:(error Permission_denied "child preparation inherited origin is unavailable")
  in
  let%bind origin =
    Result.of_option
      (Goal_descendants.origin accounting)
      ~error:
        (error
           Permission_denied
           "child preparation inherited origin is historical Unknown")
  in
  let frame = Goal_descendant_occurrence.frame occurrence in
  let%bind () =
    if
      (not (List.is_empty (O.scopes origin)))
      && Option.exists before.spec.delegation ~f:(fun reference ->
        P.Id.Session.equal reference.child_session_id before.identity.session_id)
      && P.Session_ref.equal (Goal_descendants.session accounting) session
      && P.Session_ref.equal (Goal_descendant_occurrence.Frame.session frame) session
      && Int.equal
           (Goal_descendant_occurrence.Frame.generation frame)
           before.identity.generation
      && (not (Int64.equal before.counters.revision Int64.max_value))
      && Int64.equal
           (Goal_descendant_occurrence.Frame.candidate_session_revision frame)
           (Int64.succ before.counters.revision)
      && not !writer_attempted
    then Ok ()
    else
      Error
        (error Conflict "child preparation requires its actual next inherited occurrence")
  in
  let issuing_actor = t.inference_owner_identity in
  let domain = t.runtime_source_domain in
  let check_owner () =
    if
      Int.equal domain (Stdlib.Domain.self () :> int)
      && phys_equal issuing_actor t.inference_owner_identity
      && (not t.stopped)
      && Option.is_none (Eio.Promise.peek t.finished)
      && Option.is_none t.lifecycle_fence
      && Option.exists
           t.runtime_source_owner
           ~f:(Runtime_source_owner.Identity.equal source_owner)
      && Option.exists t.recurrence_controller ~f:(phys_equal controller)
    then Ok ()
    else Error (error Conflict "child preparation lost its actual live owner")
  in
  let check_before () =
    if phys_equal before t.state
    then Ok ()
    else Error (error Conflict "child preparation actual before projection changed")
  in
  let%bind () = check_owner () in
  Ok
    { Descendant_preparation.issuing_actor
    ; domain
    ; source_owner
    ; before
    ; session
    ; controller
    ; origin
    ; occurrence
    ; writer_attempted
    ; phase = ref Descendant_preparation.Phase.Open
    ; reservation_set_claim = None
    ; check_owner
    ; check_before
    }
;;

let descendant_admission_slot_owner t (slot : Descendant_admission_slot.t) =
  let preparation = slot.preparation in
  if
    Descendant_preparation.on_domain preparation
    && phys_equal preparation.issuing_actor t.inference_owner_identity
  then Ok ()
  else Error (error Conflict "descendant admission slot belongs to another actual owner")
;;

let require_available_descendant_admission_slot t =
  if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
  then Error (error Conflict "descendant admission slot belongs to another domain")
  else (
    match
      t.governed_admission_slot, t.inherited_turn_prepared, t.inherited_turn_cleanup
    with
    | None, None, None -> Ok ()
    | Some _, _, _ | None, Some _, _ | None, None, Some _ ->
      Error
        (Agent_protocol.Error.create
           Conflict
           ~message:
             "another descendant admission retains the prospective occurrence or native \
              ACK"
           ~retryable:true
           ()))
;;

let prepare_descendant_admission_slot t ~occurrence ~writer_attempted =
  let open Result.Let_syntax in
  let%bind () = require_available_descendant_admission_slot t in
  let%bind binding = capture_descendant_host t in
  let%bind preparation = capture_descendant_preparation t ~occurrence ~writer_attempted in
  let%map reservations = Descendant_admission_data.Reservation_set.create preparation in
  { Descendant_admission_slot.preparation
  ; reservations
  ; binding
  ; phase = Active
  ; cleanup = Idle
  }
;;

let acquire_descendant_admission_slot t ~occurrence ~writer_attempted =
  let%map.Result slot =
    prepare_descendant_admission_slot t ~occurrence ~writer_attempted
  in
  t.governed_admission_slot <- Some (Governed_admission_slot.Descendant slot);
  slot
;;

let check_descendant_admission_slot t (slot : Descendant_admission_slot.t) =
  let open Result.Let_syntax in
  let%bind () = descendant_admission_slot_owner t slot in
  let%bind () =
    match t.governed_admission_slot, slot.phase with
    | Some actual, Active when Governed_admission_slot.contains_descendant actual slot ->
      Ok ()
    | Some _, (Active | Sealed _ | Released _ | Acknowledged _)
    | None, (Active | Sealed _ | Released _ | Acknowledged _) ->
      Error (error Conflict "descendant admission lost its exact active slot")
  in
  let%bind () = check_descendant_host t slot.binding in
  Descendant_preparation.check_basis slot.preparation
;;

let seal_descendant_admission_slot t (slot : Descendant_admission_slot.t) =
  let open Result.Let_syntax in
  let%bind () = descendant_admission_slot_owner t slot in
  match slot.phase with
  | Sealed closed -> Ok closed
  | Released closed -> Ok closed
  | Acknowledged _ ->
    Error (error Conflict "acknowledged descendant admission cannot prove no writer")
  | Active ->
    let%map closed =
      Descendant_preparation.seal_before_writer
        slot.preparation
        ~owner:t.inference_owner_identity
    in
    slot.phase <- Sealed closed;
    closed
;;

let release_closed_descendant_admission_slot
      t
      (slot : Descendant_admission_slot.t)
      ~closed
  =
  let module R = Descendant_admission_data in
  let open Result.Let_syntax in
  let%bind () = descendant_admission_slot_owner t slot in
  let%bind () =
    match slot.phase with
    | Sealed actual when phys_equal actual closed -> Ok ()
    | Released actual when phys_equal actual closed -> Ok ()
    | Active | Sealed _ | Released _ | Acknowledged _ ->
      Error (error Conflict "descendant admission release requires its exact child seal")
  in
  let%bind () =
    if
      Descendant_preparation.Closed_before_writer.belongs_to
        closed
        ~preparation:slot.preparation
    then Ok ()
    else Error (error Conflict "descendant admission release has another physical seal")
  in
  let%bind () =
    List.fold
      (R.Reservation_set.attempts slot.reservations)
      ~init:(Ok ())
      ~f:(fun result attempt ->
        let%bind () = result in
        match R.Reservation_attempt.outcome attempt with
        | Not_attempted -> Ok ()
        | Attempt_unconfirmed ->
          Error
            (error
               Conflict
               "unconfirmed root writer retains descendant admission custody")
        | Acknowledged reservation ->
          let%bind known = Root_close_acknowledgement.acknowledged reservation ~closed in
          if known
          then Ok ()
          else
            Error
              (error
                 Conflict
                 "root reservation has no positive exact close acknowledgement"))
  in
  let%bind () =
    match t.inherited_turn_prepared with
    | None -> Ok ()
    | Some (Prepared prepared) ->
      (match prepared.plan.phase with
       | Closed when phys_equal prepared.plan.slot slot -> Ok ()
       | Pending | Writer_prepared _ | Acknowledged _ | Closed ->
         Error
           (error Conflict "prepared Turn owner has not retired its exact sealed slot"))
  in
  match t.governed_admission_slot, slot.phase with
  | Some (Descendant actual), Sealed _ when phys_equal actual slot ->
    slot.phase <- Released closed;
    t.governed_admission_slot <- None;
    t.inherited_turn_prepared <- None;
    Ok ()
  | Some (Combined { descendant; _ }), Sealed _ when phys_equal descendant slot ->
    (* The single combined cleanup owner releases the occupancy only after both
       physical and causal factual closes have succeeded. *)
    slot.phase <- Released closed;
    Ok ()
  | _, Released _ -> Ok ()
  | Some _, (Active | Sealed _ | Acknowledged _)
  | None, (Active | Sealed _ | Acknowledged _) ->
    Error (error Conflict "descendant admission release cannot clear another actual slot")
;;

let prepare_descendant_admission_slot_ack t slot ~acknowledgement =
  let module R = Descendant_admission_data in
  let open Result.Let_syntax in
  let%bind () = check_descendant_admission_slot t slot in
  let%bind () = R.Acknowledgement.validate_content acknowledgement in
  let%bind () =
    if
      phys_equal acknowledgement.R.Acknowledgement.preparation slot.preparation
      && phys_equal acknowledgement.reservations slot.reservations
      && phys_equal acknowledgement.candidate.state acknowledgement.installed
    then Ok ()
    else Error (error Conflict "descendant admission ACK has another exact native owner")
  in
  (* Retain the exact pre-writer occupancy. Combined ownership survives its
     physical ACK; no fallible lookup is needed in the installed suffix. *)
  let%bind occupancy, remaining =
    match t.governed_admission_slot with
    | Some (Descendant actual as occupancy) when phys_equal actual slot ->
      Ok (occupancy, None)
    | Some (Combined { descendant; _ } as occupancy) when phys_equal descendant slot ->
      Ok (occupancy, Some occupancy)
    | None | Some (Descendant _ | Policy_causal _ | Combined _) ->
      Error (error Conflict "descendant ACK lost its exact governed occupancy")
  in
  let%map preparation =
    Descendant_preparation.Acknowledgement_plan.prepare
      slot.preparation
      ~acknowledgement:acknowledgement.identity
  in
  let native =
    { Descendant_admission_slot.Acknowledgement_plan.slot
    ; acknowledgement
    ; preparation
    ; acknowledged = Acknowledged acknowledgement.identity
    }
  in
  { Governed_admission_slot.Descendant_acknowledgement.native; occupancy; remaining }
;;

let check_descendant_admission_slot_ack
      t
      (plan : inherited_attempt_plan Governed_admission_slot.Descendant_acknowledgement.t)
      ~candidate
  =
  let open Result.Let_syntax in
  let%bind () =
    match t.governed_admission_slot with
    | Some actual when phys_equal actual plan.occupancy -> Ok ()
    | Some _ | None ->
      Error (error Conflict "descendant ACK lost its exact governed occupancy")
  in
  let%bind () = check_descendant_admission_slot t plan.native.slot in
  let%bind () =
    Descendant_admission_data.Acknowledgement.validate_content plan.native.acknowledgement
  in
  if phys_equal candidate plan.native.acknowledgement.candidate
  then Ok ()
  else Error (error Conflict "descendant admission ACK candidate changed before writer")
;;

let install_descendant_admission_slot_ack
      t
      (plan : inherited_attempt_plan Governed_admission_slot.Descendant_acknowledgement.t)
  =
  Descendant_preparation.Acknowledgement_plan.install plan.native.preparation;
  plan.native.slot.phase <- plan.native.acknowledged;
  t.governed_admission_slot <- plan.remaining
;;

let schedule_descendant_admission_cleanup_reported
      t
      (slot : Descendant_admission_slot.t)
      ~closed
  =
  let module Slot = Descendant_admission_slot in
  let open Result.Let_syntax in
  let%bind () = descendant_admission_slot_owner t slot in
  let%bind () =
    match t.governed_admission_slot with
    | Some (Combined { descendant; _ }) when phys_equal descendant slot ->
      Error
        (error Conflict "combined admission requires its single governed cleanup owner")
    | None | Some (Descendant _ | Policy_causal _ | Combined _) -> Ok ()
  in
  let%bind () =
    match slot.phase with
    | (Sealed actual | Released actual) when phys_equal actual closed -> Ok ()
    | Active | Sealed _ | Released _ | Acknowledged _ ->
      Error (error Conflict "descendant cleanup requires the same retained child seal")
  in
  match slot.cleanup, slot.phase with
  | Running attempt, (Sealed _ | Released _) ->
    Ok (Slot.Cleanup.Attempt.Scheduled attempt)
  | Idle, Released _ ->
    let promise, resolver = Eio.Promise.create () in
    Eio.Promise.resolve resolver (Ok ());
    Ok
      (Slot.Cleanup.Attempt.Scheduled
         { finished = promise
         ; outcome =
             Some
               { reply = Actor_reply.Returned (Ok ())
               ; boundary =
                   (match slot.phase with
                    | Released _ -> Retirement_cleanup_completion.Boundary.Released
                    | Active | Sealed _ | Acknowledged _ -> Before_release)
               }
         })
  | Idle, Sealed _ ->
    let promise, resolver = Eio.Promise.create () in
    let attempt : Slot.Cleanup.Attempt.t = { finished = promise; outcome = None } in
    let running = Slot.Cleanup.Running attempt in
    let finish result =
      match Eio.Promise.peek promise with
      | Some _ -> ()
      | None ->
        if Option.is_none attempt.outcome
        then
          attempt.outcome
          <- Some
               { reply = Actor_reply.Returned result
               ; boundary =
                   (match slot.phase with
                    | Released _ -> Retirement_cleanup_completion.Boundary.Released
                    | Active | Sealed _ | Acknowledged _ -> Before_release)
               };
        slot.cleanup <- Idle;
        Eio.Promise.resolve resolver result
    in
    let failed exn backtrace =
      if Option.is_none attempt.outcome
      then
        attempt.outcome
        <- Some
             { reply = Actor_reply.Raised (exn, backtrace)
             ; boundary =
                 (match slot.phase with
                  | Released _ -> Retirement_cleanup_completion.Boundary.Released
                  | Active | Sealed _ | Acknowledged _ -> Before_release)
             };
      let message =
        match exn with
        | Eio.Cancel.Cancelled _ -> "descendant sealed-slot cleanup was cancelled"
        | _ -> "descendant sealed-slot cleanup raised: " ^ Exn.to_string exn
      in
      finish (Error (error Interrupted message))
    in
    slot.cleanup <- running;
    (try
       (* Eio fork skips a cancelling switch; reject before promising a producer. *)
       Eio.Switch.check t.sw;
       Eio.Fiber.fork ~sw:t.sw (fun () ->
         match
           (* Scheduling is pure at the original call site. Host RPC starts in
              the actual Actor-switch fiber after this initial yield. *)
           Eio.Fiber.yield ();
           let%bind () = (Slot.host slot).close slot.reservations closed in
           release_closed_descendant_admission_slot t slot ~closed
         with
         | result -> finish result
         | exception exn ->
           let backtrace = Stdlib.Printexc.get_raw_backtrace () in
           failed exn backtrace;
           Exn.raise_with_original_backtrace exn backtrace);
       Ok (Slot.Cleanup.Attempt.Scheduled attempt)
     with
     | exn ->
       let backtrace = Stdlib.Printexc.get_raw_backtrace () in
       failed exn backtrace;
       Ok
         (Slot.Cleanup.Attempt.Launch_failed
            { attempt; legacy = Actor_reply.Raised (exn, backtrace) }))
  | (Idle | Running _), (Active | Acknowledged _) ->
    Error (error Conflict "descendant cleanup cannot act on an unsealed or admitted slot")
;;

let schedule_descendant_admission_cleanup t slot ~closed =
  Result.bind (schedule_descendant_admission_cleanup_reported t slot ~closed) ~f:(function
    | Descendant_admission_slot.Cleanup.Attempt.Scheduled attempt -> Ok attempt.finished
    | Launch_failed { attempt; legacy = Actor_reply.Returned (Ok ()) } ->
      Ok attempt.finished
    | Launch_failed { legacy = Actor_reply.Returned (Error failure); _ } -> Error failure
    | Launch_failed { legacy = Actor_reply.Raised (exn, backtrace); _ } ->
      Exn.raise_with_original_backtrace exn backtrace)
;;

let inherited_attempt_physical (plan : Inherited_attempt.Plan.t) =
  match plan.arms with
  | Descendant_attempt slot | Combined_attempt { descendant = slot; _ } -> Some slot
  | Policy_causal_attempt _ -> None
;;

let inherited_attempt_causal (plan : Inherited_attempt.Plan.t) =
  match plan.arms with
  | Policy_causal_attempt causal | Combined_attempt { causal; _ } -> Some causal
  | Descendant_attempt _ -> None
;;

let governed_plan_owner t (plan : inherited_attempt_plan) =
  let open Result.Let_syntax in
  match plan.arms, t.governed_admission_slot with
  | Descendant_attempt slot, Some (Descendant actual) when phys_equal slot actual ->
    descendant_admission_slot_owner t slot
  | Policy_causal_attempt arm, Some (Policy_causal actual)
    when phys_equal actual.plan plan && phys_equal actual.causal arm.slot ->
    Goal_causal_admission_custody.Slot.check_owner
      arm.slot
      ~issuer:t.inference_owner_identity
  | Combined_attempt { descendant; causal }, Some (Combined actual)
    when phys_equal actual.plan plan
         && phys_equal actual.descendant descendant
         && phys_equal actual.causal causal.slot ->
    let%bind () = descendant_admission_slot_owner t descendant in
    Goal_causal_admission_custody.Slot.check_owner
      causal.slot
      ~issuer:t.inference_owner_identity
  | ( (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _)
    , (None | Some (Descendant _ | Policy_causal _ | Combined _)) ) ->
    Error (error Conflict "governed Plan lost its SAME retained occupancy")
;;

let seal_governed_plan t (plan : inherited_attempt_plan) =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () = governed_plan_owner t plan in
  (match inherited_attempt_causal plan with
   | None -> ()
   | Some causal -> causal.slot.cancellation_requested <- true);
  let%bind () =
    match inherited_attempt_causal plan with
    | None -> Ok ()
    | Some causal ->
      (match causal.slot.phase with
       | Writer_prepared write ->
         if Session_commit_attempt.no_writer write.writer
         then Ok ()
         else Session_commit_attempt.unresolved write.writer
       | Preparing | Acknowledged _ | Sealed _ | Released _ -> Ok ())
  in
  let physical_with_causal descendant (causal : causal_plan_arm) =
    match descendant.Descendant_admission_slot.phase with
    | Sealed closed | Released closed -> Ok closed
    | Acknowledged _ ->
      Error (error Conflict "acknowledged physical edge cannot close unwritten")
    | Active ->
      (match causal.slot.phase with
       | Writer_prepared write when !(descendant.preparation.writer_attempted) ->
         let%bind closed = Session_commit_attempt.No_writer.seal write.writer in
         let%map closed =
           Descendant_preparation.seal_observed_attempt_before_writer
             descendant.preparation
             ~owner:t.inference_owner_identity
             ~slot:causal.slot.identity
             ~preparation:causal.slot.preparation.identity
             ~attempt:write.writer
             ~candidate:write.candidate
             ~canonical:write.canonical
             ~closed
         in
         descendant.phase <- Sealed closed;
         closed
       | Preparing | Writer_prepared _ | Sealed _ | Released _ ->
         seal_descendant_admission_slot t descendant
       | Acknowledged _ ->
         Error (error Conflict "acknowledged causal edge cannot close unwritten"))
  in
  let causal_closed (arm : causal_plan_arm) =
    let%map native_closed = C.Slot.seal arm.slot ~issuer:t.inference_owner_identity in
    { native_closed; slot = arm.slot; callee = t; actual_reservations = arm.reservations }
  in
  match plan.arms with
  | Descendant_attempt slot ->
    let%map closed = seal_descendant_admission_slot t slot in
    Descendant_closed closed
  | Policy_causal_attempt arm ->
    let%map closed = causal_closed arm in
    Causal_closed closed
  | Combined_attempt { descendant; causal } ->
    (* Exact same-kernel observed seal first preserves the physical finalizer;
       never reset writer_attempted or infer absence from returned Error. *)
    let%bind physical = physical_with_causal descendant causal in
    let%map policy = causal_closed causal in
    Combined_closed (physical, policy)
;;

let retire_closed_governed_plan t (plan : inherited_attempt_plan) closed =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () = governed_plan_owner t plan in
  let check_causal (arm : causal_plan_arm) (closed : causal_closed_before_writer) =
    let%bind () = C.Slot.check_owner arm.slot ~issuer:t.inference_owner_identity in
    let%bind () =
      if
        phys_equal closed.callee t
        && phys_equal closed.slot arm.slot
        && phys_equal closed.actual_reservations arm.reservations
      then Ok ()
      else Error (error Conflict "governed cleanup has another causal Set/seal")
    in
    let%bind () =
      match arm.slot.phase with
      | (Sealed actual | Released (Unwritten actual))
        when phys_equal actual closed.native_closed -> Ok ()
      | Preparing | Writer_prepared _ | Acknowledged _ | Sealed _ | Released _ ->
        Error (error Conflict "governed cleanup has no SAME actual no-writer seal")
    in
    let%map () =
      List.fold_result arm.reservations.actual_attempts ~init:() ~f:(fun () actual ->
        let attempt = actual.native_attempt in
        if not (phys_equal attempt.set_identity arm.reservations.native_set.identity)
        then
          Error (error Conflict "governed cleanup contains another actual root attempt")
        else (
          match attempt.phase with
          | Begun | Not_reserved _ -> Ok ()
          | Writer_prepared _ ->
            Error (error Conflict "unknown root writer retains causal custody")
          | Reserved reservation ->
            (match reservation.terminal with
             | Settled (No_writer_closed acknowledged)
               when phys_equal acknowledged.closed closed.native_closed -> Ok ()
             | Settled (Pending | Confirmed _ | No_writer_closed _) | Terminal_prepared _
               ->
               Error
                 (error Conflict "causal root has no exact acknowledged factual close"))))
    in
    C.Slot.Released (Unwritten closed.native_closed)
  in
  match plan.arms, closed with
  | Descendant_attempt slot, Descendant_closed closed ->
    release_closed_descendant_admission_slot t slot ~closed
  | Policy_causal_attempt causal, Causal_closed closed ->
    let%bind released = check_causal causal closed in
    causal.slot.phase <- released;
    t.governed_admission_slot <- None;
    Ok ()
  | Combined_attempt { descendant; causal }, Combined_closed (physical, policy) ->
    let%bind released = check_causal causal policy in
    let%bind () =
      release_closed_descendant_admission_slot t descendant ~closed:physical
    in
    causal.slot.phase <- released;
    t.governed_admission_slot <- None;
    Ok ()
  | ( (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _)
    , (Descendant_closed _ | Causal_closed _ | Combined_closed _) ) ->
    Error (error Conflict "governed cleanup changed its exact closed arms")
;;

module Inference_factual_failure = struct
  type t =
    | Protocol of Agent_protocol.Error.t
    | Raised of exn * Stdlib.Printexc.raw_backtrace

  let capture f =
    try Result.map_error (f ()) ~f:(fun error -> Protocol error) with
    | exn -> Error (Raised (exn, Stdlib.Printexc.get_raw_backtrace ()))
  ;;

  let resume = function
    | Ok value -> Ok value
    | Error (Protocol error) -> Error error
    | Error (Raised (exn, backtrace)) -> Exn.raise_with_original_backtrace exn backtrace
  ;;
end

let close_retained_governed_plan t (plan : inherited_attempt_plan) =
  let open Result.Let_syntax in
  match plan.acknowledged with
  | Some acknowledgement ->
    (* A genuine ACK transferred factual custody to SAME614 registration. This
       duty may reconcile initial imports; it never admits/replays the provider. *)
    let%bind registration =
      Result.of_option
        (Graph_owner.retained_registration plan.owner plan.handle)
        ~error:(error Conflict "acknowledged governed Plan lost its actual registration")
    in
    let%bind facts =
      Result.of_option
        (Inference_owner.Registration.factual_usage registration)
        ~error:(error Conflict "acknowledged governed Plan has no retained factual duty")
    in
    let%bind () = Inference_owner.Factual_usage.confirm_initial facts in
    (match acknowledgement.confirmation with
     | Some _ -> Ok ()
     | None -> Error (error Conflict "governed initial duty has no retained confirmation"))
  | None ->
    let%bind closed = seal_governed_plan t plan in
    let first = ref None in
    let run f =
      let capture () = Inference_factual_failure.capture f in
      let outcome =
        match !first with
        | None -> capture ()
        | Some _ -> Eio.Cancel.protect capture
      in
      match outcome with
      | Ok () -> ()
      | Error failure -> if Option.is_none !first then first := Some failure
    in
    let causal (arm : causal_plan_arm) closed =
      match arm.host with
      | Governed { causal; _ } -> causal.close arm.reservations closed
      | Physical_only _ ->
        Error (error Conflict "causal cleanup lost its actual governed host")
    in
    (match plan.arms, closed with
     | Policy_causal_attempt arm, Causal_closed closed ->
       run (fun () -> causal arm closed)
     | Combined_attempt { descendant; causal = arm }, Combined_closed (physical, policy)
       ->
       run (fun () ->
         (Descendant_admission_slot.host descendant).close
           descendant.reservations
           physical);
       run (fun () -> causal arm policy)
     | Descendant_attempt slot, Descendant_closed closed ->
       run (fun () ->
         (Descendant_admission_slot.host slot).close slot.reservations closed)
     | ( (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _)
       , (Descendant_closed _ | Causal_closed _ | Combined_closed _) ) ->
       run (fun () -> Error (error Conflict "governed cleanup changed closed arms")));
    (match !first with
     | Some failure -> Inference_factual_failure.resume (Error failure)
     | None -> retire_closed_governed_plan t plan closed)
;;

let schedule_governed_plan_cleanup t (plan : inherited_attempt_plan) =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () = governed_plan_owner t plan in
  let%bind slot =
    match inherited_attempt_causal plan with
    | Some causal -> Ok causal.slot
    | None -> Error (error Conflict "physical-only cleanup uses its existing election")
  in
  match slot.cleanup with
  | Running promise -> Ok promise
  | Idle ->
    let promise, resolver = Eio.Promise.create () in
    slot.cleanup <- Running promise;
    let finish result =
      Eio.Cancel.protect (fun () ->
        slot.cleanup <- Idle;
        Actor_reply.resolve resolver result)
    in
    (try
       (* Eio fork skips a cancelling switch; reject before promising a producer. *)
       Eio.Switch.check t.sw;
       Eio.Fiber.fork ~sw:t.sw (fun () ->
         match
           Inference_factual_failure.capture (fun () ->
             Eio.Fiber.yield ();
             close_retained_governed_plan t plan)
         with
         | Ok () -> finish (Ok ())
         | Error (Protocol error) -> finish (Error error)
         | Error (Raised (exn, bt)) ->
           Eio.Cancel.protect (fun () ->
             slot.cleanup <- Idle;
             Actor_reply.resolve_exception resolver exn bt));
       Ok promise
     with
     | exn ->
       let bt = Stdlib.Printexc.get_raw_backtrace () in
       Eio.Cancel.protect (fun () ->
         slot.cleanup <- Idle;
         Actor_reply.resolve_exception resolver exn bt);
       Exn.raise_with_original_backtrace exn bt)
;;

let retry_descendant_admission_cleanup t =
  if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
  then Error (error Conflict "descendant cleanup belongs to another domain")
  else (
    match t.governed_admission_slot with
    | Some (Descendant ({ phase = Sealed closed; _ } as slot)) ->
      let%bind.Result promise = schedule_descendant_admission_cleanup t slot ~closed in
      Eio.Promise.await promise
    | Some (Policy_causal { causal; plan } | Combined { causal; plan; _ }) ->
      if causal.cancellation_requested || Option.is_some plan.acknowledged
      then (
        let%bind.Result promise = schedule_governed_plan_cleanup t plan in
        Actor_reply.await promise)
      else Error (error Conflict "another actual causal admission is still active")
    | None | Some (Descendant { phase = Active | Released _ | Acknowledged _; _ }) ->
      Ok ())
;;

let retire_descendant_host t =
  Option.iter t.descendant_host_binding ~f:(fun actual ->
    Descendant_host_data.Binding.close (physical_descendant_host actual))
;;

let goal_capacity_deferred (deferred : Goal_charge_admission.deferred) =
  let message =
    match deferred.reason with
    | Reserved -> "Goal count capacity is reserved by an unconfirmed descendant admission"
    | Unknown -> "Goal count capacity requires confirmed descendant accounting"
  in
  Agent_protocol.Error.create Conflict ~message ~retryable:true ()
;;

let initial_run_preparation t = Option.bind t.run_preparation ~f:Preparation_owner.initial

let exclude_effect_deferred t reason =
  match t.effect_deferred with
  | None -> ()
  | Some (Ordinary deferred) ->
    Run_preparation.Deferred.exclude deferred ~reason;
    t.effect_deferred <- None
  | Some (Retry retry) ->
    Run_preparation.Deferred.exclude retry.deferred ~reason;
    (* Retain this negative-only phase while the captured preparation can still
       be presented through ordinary APIs. Exclusion cannot turn it executable. *)
    (match retry.phase with
     | Acknowledged _ -> ()
     | _ -> retry.phase <- Invalid)
;;

let retry_for_preparation t preparation =
  match t.effect_deferred with
  | Some (Retry retry)
    when phys_equal (Run_preparation.Deferred.preparation retry.deferred) preparation ->
    Some retry
  | Some (Ordinary _ | Retry _) | None -> None
;;

let check_retry_execution t preparation =
  match retry_for_preparation t preparation with
  | None -> Ok ()
  | Some { phase = Acknowledged (Some _, _); _ } -> Ok ()
  | Some _ -> Error (error Conflict "retry preparation requires its controller ACK")
;;

let agent_source_current t generation source =
  Int.equal generation t.state.identity.generation
  && (not t.stopped)
  && Agent_protocol.Session.equal_desired_state t.state.lifecycle.desired Running
  &&
  match Runtime_builder.moderator_snapshot_observer t.state.moderator with
  | Error _ -> false
  | Ok current -> Option.equal Agent_protocol.Invocation.equal_observer source current
;;

let moderator_untracked_data_basis t =
  let%map.Result queue = Moderator_checkpoint.queue t.state.moderator in
  Option.is_none t.moderator_manager
  && Option.is_none queue
  && Run_source_installation.equal
       Run_source_installation.initial
       (Run_state.installation (Option.value t.state.run_state ~default:Run_state.empty))
;;

let legacy_untracked_moderator_checkpoint t snapshot =
  let open Result.Let_syntax in
  let%map untracked = moderator_untracked_data_basis t in
  untracked
  && Result.is_error
       (Agent_protocol.Run_source.create
          ~observer:
            Agent_protocol.Invocation.
              { script_id = snapshot.Session.Moderator_state.Identity_snapshot.script_id
              ; source_sha256 = snapshot.script_source_hash
              }
          ~generation:t.state.identity.generation
          ~installation_epoch:1L)
;;

let observation_source_for_checkpoint t snapshot =
  let open Result.Let_syntax in
  let%bind legacy = legacy_untracked_moderator_checkpoint t snapshot in
  if legacy
  then Ok None
  else (
    let%map _, source =
      Moderator_source_installation.capture_checkpoint t.state ~checkpoint:snapshot
    in
    Some source)
;;

let observation_source t =
  let open Result.Let_syntax in
  let%bind snapshot = Moderator_checkpoint.decode t.state.moderator in
  match snapshot with
  | None -> Ok None
  | Some snapshot ->
    (* Only the legacy untracked DATA identity is unavailable. A representable
       source still projects the same epoch before and after the first index ACK;
       typed installations, Managers and queue metadata cannot take this path. *)
    observation_source_for_checkpoint t snapshot
;;

let observation_pending (invocation : Agent_protocol.Invocation.t) =
  match invocation.observation with
  | Some { status = Awaiting | Observing; _ } -> true
  | Some
      { status = Observed
      ; follow_up = Some (Pending_follow_up _ | Compaction_accepted_follow_up _)
      ; _
      } -> true
  | None
  | Some
      { status = Observed
      ; follow_up = None | Some (Applied_follow_up _ | Discarded_follow_up _)
      ; _
      }
  | Some { status = Observation_failed _; _ } -> false
;;

let retire_instruction_continuations t =
  (match t.lifecycle_agent_custody with
   | Unadmitted -> ()
   | Admitted { pending = Pending admission; _ }
   | Admitted { pending = Initial_pending { admission; _ }; _ } ->
     retire_agent_admission admission
   | Admitted { pending = Consumed; _ } -> ());
  t.lifecycle_agent_custody <- Unadmitted;
  List.iter t.intent_agent_custody ~f:(fun entry ->
    Option.iter entry.custody ~f:retire_agent_custody;
    Option.iter entry.observation ~f:Observation_continuation.retire;
    Option.iter entry.native_goal ~f:(fun native -> retire_native_goal_custody native));
  t.intent_agent_custody <- []
;;

let retain_instruction_continuations t =
  (match t.lifecycle_agent_custody with
   | Admitted { generation; source; _ }
     when not (agent_source_current t generation source) ->
     retire_instruction_continuations t
   | Unadmitted | Admitted _ -> ());
  let current_source = observation_source t in
  let current_observer = Runtime_builder.moderator_snapshot_observer t.state.moderator in
  (* This pass and its custody retirement are nonyielding, so the current State
     stays immutable throughout the filter. Reuse its observer projection rather
     than decoding and hashing the same checkpoint for every retained row. *)
  let source_current generation source =
    Int.equal generation t.state.identity.generation
    && (not t.stopped)
    && Agent_protocol.Session.equal_desired_state t.state.lifecycle.desired Running
    &&
    match current_observer with
    | Error _ -> false
    | Ok current -> Option.equal Agent_protocol.Invocation.equal_observer source current
  in
  let intent_source_current (entry : agent_intent_custody) =
    match entry.retention with
    | Ordinary -> source_current entry.generation entry.source
    | Stopped_policy { stop_epoch; source } | Restored_policy { stop_epoch; source } ->
      (* Only an actual policy claim's terminal ACK can install this provenance.
         Preserve its same original in either desired state, but never across a
         new Stop/source/generation; retention grants no automatic follow-up. *)
      Int.equal entry.generation t.state.identity.generation
      && (not t.stopped)
      && Int64.equal stop_epoch t.state.stop_epoch
      && (match current_observer with
          | Error _ -> false
          | Ok current ->
            Option.equal Agent_protocol.Invocation.equal_observer entry.source current)
      &&
        (match current_source with
        | Ok (Some current) -> Agent_protocol.Run_source.equal source current
        | Error _ | Ok None -> false)
  in
  t.intent_agent_custody
  <- List.filter_map t.intent_agent_custody ~f:(fun entry ->
       let invocation =
         match entry.key with
         | Event_intent _ -> None
         | Invocation_intent id ->
           List.find t.state.invocations ~f:(fun invocation ->
             Agent_protocol.Id.Invocation.equal invocation.context.id id)
       in
       let follow_up =
         intent_source_current entry
         &&
         match entry.key with
         | Event_intent id ->
           List.exists t.state.moderator_executions ~f:(fun receipt ->
             Agent_protocol.Id.Moderator_execution.equal receipt.context.id id
             && Observation_follow_up.pending_event receipt)
         | Invocation_intent _ ->
           Option.exists invocation ~f:Observation_follow_up.pending
       in
       let observation =
         Option.bind entry.observation ~f:(fun observation ->
           let retained =
             (not t.stopped)
             && Int.equal entry.generation t.state.identity.generation
             &&
             match current_source, current_observer, invocation with
             | Ok source, Ok observer, Some invocation ->
               Option.equal Agent_protocol.Invocation.equal_observer entry.source observer
               && observation_pending invocation
               && Observation_continuation.matches observation ~source invocation
             | (Error _ | Ok _), (Error _ | Ok _), (None | Some _) -> false
           in
           if retained
           then Some observation
           else (
             Observation_continuation.retire observation;
             None))
       in
       let native_goal =
         Option.bind entry.native_goal ~f:(fun native ->
           let retained =
             (not t.stopped)
             && source_current entry.generation entry.source
             && Option.exists invocation ~f:(native_goal_intent_retained t.state native)
           in
           if retained
           then Some native
           else (
             retire_native_goal_custody native;
             None))
       in
       if not follow_up then Option.iter entry.custody ~f:retire_agent_custody;
       if follow_up || Option.is_some observation || Option.is_some native_goal
       then
         Some
           { entry with
             custody = (if follow_up then entry.custody else None)
           ; observation
           ; native_goal
           }
       else None)
;;

(* Retention uses actual installation facts, independently of whether this
   resource is currently eligible to execute. It cannot capture a new source. *)
let retained_moderator_source (state : Session_state.t) =
  match state.run_state with
  | None -> None
  | Some index ->
    let source =
      let open Result.Let_syntax in
      let%bind observer = Moderator_checkpoint.observer state.moderator in
      let%bind source =
        Run_source_installation.captured
          (Run_state.installation index)
          ~generation:state.identity.generation
      in
      if
        Option.equal
          Agent_protocol.Invocation.equal_observer
          observer
          (Some source.observer)
      then Ok source
      else Error (error Conflict "retained moderator source differs from installation")
    in
    (match source with
     | Ok source -> Some source
     | Error _ -> None)
;;

let retained_agent_custody t =
  t.operation_completion
  <- Option.filter t.operation_completion ~f:(fun completion ->
       (not t.stopped)
       && Option.exists t.state.active_operation ~f:(fun operation ->
         Operation_completion.matches completion ~operation));
  retain_instruction_continuations t;
  let metadata =
    match Moderator_checkpoint.queue t.state.moderator with
    | Ok metadata -> metadata
    | Error _ -> None
  in
  let source = retained_moderator_source t.state in
  t.legacy_queue_custody
  <- Legacy_queue_custody.install
       t.legacy_queue_custody
       ~incoming:
         (Legacy_queue_custody.retain_facts t.legacy_queue_custody ~source ~metadata);
  t.legacy_schedule_custody
  <- Legacy_schedule_custody.install
       t.legacy_schedule_custody
       ~incoming:
         (Legacy_schedule_custody.retain_facts
            t.legacy_schedule_custody
            ~source
            ~schedules:t.state.schedules);
  t.ingress_creator_custody
  <- Ingress_creator_custody.install
       t.ingress_creator_custody
       ~incoming:
         (Ingress_creator_custody.retain
            t.ingress_creator_custody
            ~manager:t.moderator_manager
            ~source
            ~registrations:t.state.ingress_registrations
            ~subscriptions:t.state.subscriptions
            ~now:(t.services.now ()));
  let operation_current id =
    (not t.stopped)
    && Option.exists t.state.active_operation ~f:(fun operation ->
      Agent_protocol.Id.Operation.equal operation.id id
      &&
      match operation.state with
      | Starting | Running -> true
      | Cancelling | Completed | Failed _ | Cancelled | Interrupted _ -> false)
  in
  (match t.operation_agent_custody with
   | Some ({ Operation_owner.operation_id = id; _ } as owner)
     when not (operation_current id) ->
     Operation_owner.retire owner;
     t.operation_agent_custody <- None
   | Some _ | None -> ());
  t.job_agent_custody
  <- Job_custody.install_retained
       t.job_agent_custody
       ~incoming:
         (if t.stopped
          then Job_custody.empty
          else Job_custody.retain t.job_agent_custody ~jobs:t.state.jobs)
;;

let operation_agent_actor t id =
  match t.operation_agent_custody with
  | Some { Operation_owner.operation_id = owner; admission; _ }
    when Agent_protocol.Id.Operation.equal owner id ->
    (match Execution_custody.Admission.custody admission with
     | Some custody -> Result.map (Execution_custody.actor custody) ~f:Option.some
     | None -> Ok None)
  | Some _ | None -> Ok None
;;

let install_operation_agent_custody t operation custody =
  Option.iter t.operation_agent_custody ~f:Operation_owner.retire;
  let completion =
    Operation_completion.create
      ~issuer:t.initialization_owner
      ~domain:t.runtime_source_domain
      ~operation
  in
  t.operation_agent_custody
  <- Some
       { Operation_owner.operation_id = operation.Agent_protocol.Operation.id
       ; admission = create_agent_admission custody
       ; held = None
       ; descendant_guard = None
       ; completion
       };
  t.operation_completion <- Some completion
;;

let operation_descendant_guard t operation_id =
  match t.operation_agent_custody with
  | Some owner when Agent_protocol.Id.Operation.equal owner.operation_id operation_id ->
    Ok owner.descendant_guard
  | None -> Ok None
  | Some _ -> Error (error Conflict "inherited operation belongs to another owner")
;;

let check_operation_descendant t operation_id =
  let%bind.Result guard = operation_descendant_guard t operation_id in
  Option.value_map guard ~default:(Ok ()) ~f:Operation_descendant_guard.check_current
;;

let refresh_operation_descendant t operation_id =
  let open Result.Let_syntax in
  let%bind guard = operation_descendant_guard t operation_id in
  let%bind () =
    Option.value_map guard ~default:(Ok ()) ~f:Operation_descendant_guard.refresh
  in
  let%bind current = operation_descendant_guard t operation_id in
  if Option.equal phys_equal guard current
  then check_operation_descendant t operation_id
  else Error (error Conflict "inherited operation owner changed during refresh")
;;

let descendant_operation_of_execution = function
  | Inference_operation (operation, _) -> Some operation.Agent_protocol.Operation.id
  | Inference_invocation execution ->
    (match execution.owner with
     | Foreground id -> Some id
     | Invocation_moderator borrow -> borrow.operation_id
     | Event_moderator borrow -> borrow.receipt.context.operation_id
     | Background_job _ -> None)
  | Inference_moderator borrow -> borrow.operation_id
  | Inference_event borrow -> borrow.receipt.context.operation_id
  | Inference_job _
  | Inference_held_input _
  | Inference_initialization _
  | Inference_initialization_job _ -> None
;;

let check_execution_descendant t execution =
  Option.value_map
    (descendant_operation_of_execution execution)
    ~default:(Ok ())
    ~f:(check_operation_descendant t)
;;

let refresh_execution_descendant t execution =
  Option.value_map
    (descendant_operation_of_execution execution)
    ~default:(Ok ())
    ~f:(refresh_operation_descendant t)
;;

let job_scope_current t scope =
  match
    ( List.mem t.job_scopes scope ~equal:phys_equal
    , List.find t.state.jobs ~f:(fun job ->
        Agent_protocol.Id.Job.equal job.id scope.job.id) )
  with
  | true, Some job
    when Int.equal job.generation scope.job.generation
         && Int.equal job.generation t.state.identity.generation
         && Int.equal job.attempt scope.job.attempt
         && Agent_protocol.Job.equal_kind job.kind scope.job.kind
         && Jsonaf.exactly_equal job.payload scope.job.payload -> Ok job
  | _ -> Error (error Conflict "background callback no longer owns this job attempt")
;;

let job_scope_can_execute t scope =
  let open Result.Let_syntax in
  let%bind job = job_scope_current t scope in
  match job.status, t.state.lifecycle.desired, t.state.halted, t.state.failure with
  | (Running | Waiting_permission _), Running, false, None
    when scope.active
         && (not scope.cancel_requested)
         && Option.for_all scope.deadline ~f:(fun deadline ->
           Agent_protocol.Timestamp.compare (t.services.now ()) deadline < 0) -> Ok ()
  | _ -> Error (error Conflict "background job cannot admit another invocation")
;;

let job_execution_owned_by scope (execution : invocation_execution) =
  match execution.owner with
  | Background_job owner -> phys_equal owner scope
  | Event_moderator borrow -> Option.exists borrow.job_scope ~f:(phys_equal scope)
  | Invocation_moderator borrow -> Option.exists borrow.job_scope ~f:(phys_equal scope)
  | _ -> false
;;

let signal_job_scope scope =
  match Eio.Promise.peek scope.cancelled with
  | Some () -> ()
  | None -> Eio.Promise.resolve scope.cancel_signal ()
;;

let cancel_job_scope (scope : job_scope) =
  scope.cancel_requested <- true;
  Atomic.set scope.authority_live false;
  signal_job_scope scope;
  Option.iter scope.cancel ~f:(fun cancel -> cancel ())
;;

let cancel_job_moderators t scope =
  Option.iter t.moderator_borrow ~f:(fun borrow ->
    match Option.exists borrow.job_scope ~f:(phys_equal scope) with
    | false -> ()
    | true ->
      borrow.cancel_requested <- true;
      borrow.accepts_children <- false;
      Atomic.set borrow.authority_live false;
      Option.iter borrow.cancel ~f:(fun cancel -> cancel ()));
  Option.iter t.queued_event_borrow ~f:(fun borrow ->
    match Option.exists borrow.job_scope ~f:(phys_equal scope) with
    | false -> ()
    | true ->
      borrow.cancel_requested <- true;
      Option.iter borrow.cancel ~f:(fun cancel -> cancel ()))
;;

let job_has_moderator t scope =
  Option.exists t.moderator_borrow ~f:(fun borrow ->
    Option.exists borrow.job_scope ~f:(phys_equal scope))
  || Option.exists t.queued_event_borrow ~f:(fun borrow ->
    Option.exists borrow.job_scope ~f:(phys_equal scope))
;;

let cancel_job_scopes t jobs =
  List.iter t.job_scopes ~f:(fun scope ->
    match
      List.exists jobs ~f:(fun (job : Agent_protocol.Job.t) ->
        Agent_protocol.Id.Job.equal job.id scope.job.id
        && Int.equal job.generation scope.job.generation
        && Int.equal job.attempt scope.job.attempt)
    with
    | true ->
      cancel_job_scope scope;
      cancel_job_moderators t scope
    | false -> ())
;;

let moderator_is_borrowed t =
  Option.is_some t.moderator_borrow
  || Option.is_some t.queued_event_borrow
  || Delegated_policy_custody.pending t
;;

let call t ?(priority = Mailbox.Normal) ?command_audit request =
  let promise, resolver = Eio.Promise.create () in
  let open Result.Let_syntax in
  let%bind () =
    Mailbox.push t.mailbox ~priority (Pack (command_audit, request, resolver))
  in
  Actor_reply.await promise
;;

(* One retained actual ACK owns both factual cleanup legs. Expected errors
   settle the current waiter but never erase that ACK or a positive partial fact.
   A later explicit eligible call retries the same owner; no timed retry loop. *)
let schedule_inherited_turn_cleanup_reported
  : type outcome.
    t
    -> outcome Inherited_turn.Acknowledged.t
    -> (Inherited_turn.Cleanup.Attempt.issuance, Agent_protocol.Error.t) result
  =
  fun t acknowledged ->
  let open Result.Let_syntax in
  let preparation = acknowledged.native.preparation in
  let%bind () =
    if
      Descendant_preparation.on_domain preparation
      && phys_equal preparation.issuing_actor t.inference_owner_identity
      && Descendant_preparation.acknowledged_by
           preparation
           ~acknowledgement:acknowledged.native.identity
    then Ok ()
    else Error (error Conflict "inherited Turn cleanup requires its actual installed ACK")
  in
  let%bind failure =
    match acknowledged.plan.cancellation with
    | Requested failure -> Ok failure
    | Not_requested ->
      Error (error Conflict "inherited Turn cleanup has no retained cancellation request")
  in
  let%bind () =
    match t.inherited_turn_cleanup with
    | None ->
      t.inherited_turn_cleanup <- Some (Inherited_turn.Pack acknowledged);
      Ok ()
    | Some (Pack actual) when phys_equal actual.native acknowledged.native -> Ok ()
    | Some (Pack _) ->
      Error (error Conflict "another actual inherited Turn ACK still owns cleanup")
  in
  Operation_descendant_guard.retire acknowledged.guard;
  match acknowledged.cleanup_owner with
  | Running attempt -> Ok (Inherited_turn.Cleanup.Attempt.Scheduled attempt)
  | Idle ->
    let promise, resolver = Eio.Promise.create () in
    let attempt : Inherited_turn.Cleanup.Attempt.t =
      { finished = promise; outcome = None }
    in
    let finish result =
      match Eio.Promise.peek promise with
      | Some _ -> ()
      | None ->
        if Option.is_none attempt.outcome
        then
          attempt.outcome
          <- Some
               { reply = Actor_reply.Returned result
               ; boundary =
                   (match acknowledged.cleanup_progress with
                    | Done -> Retirement_cleanup_completion.Boundary.Released
                    | Needs_both | Terminal_done | Confirmed _ -> Before_release)
               };
        acknowledged.cleanup_owner <- Idle;
        (match acknowledged.cleanup_progress, t.inherited_turn_cleanup with
         | Done, Some (Pack actual) when phys_equal actual.native acknowledged.native ->
           t.inherited_turn_cleanup <- None
         | (Needs_both | Terminal_done | Confirmed _ | Done), (Some _ | None) -> ());
        Eio.Promise.resolve resolver result
    in
    let failed exn backtrace =
      if Option.is_none attempt.outcome
      then
        attempt.outcome
        <- Some
             { reply = Actor_reply.Raised (exn, backtrace)
             ; boundary =
                 (match acknowledged.cleanup_progress with
                  | Done -> Retirement_cleanup_completion.Boundary.Released
                  | Needs_both | Terminal_done | Confirmed _ -> Before_release)
             };
      let message =
        match exn with
        | Eio.Cancel.Cancelled _ -> "inherited Turn ACK cleanup was cancelled"
        | _ -> "inherited Turn ACK cleanup raised: " ^ Exn.to_string exn
      in
      finish (Error (error Interrupted message))
    in
    acknowledged.cleanup_owner <- Running attempt;
    (try
       (* Eio fork skips a cancelling switch; reject before promising a producer. *)
       Eio.Switch.check t.sw;
       Eio.Fiber.fork ~sw:t.sw (fun () ->
         match
           Eio.Fiber.yield ();
           let terminal =
             match acknowledged.cleanup_progress with
             | Needs_both | Confirmed _ ->
               let result =
                 call
                   t
                   ~priority:Priority
                   (Inherited_turn (Retire (acknowledged, failure)))
               in
               (match result, acknowledged.cleanup_progress with
                | Ok (), Needs_both -> acknowledged.cleanup_progress <- Terminal_done
                | Ok (), Confirmed _ -> acknowledged.cleanup_progress <- Done
                | (Ok () | Error _), (Needs_both | Terminal_done | Confirmed _ | Done) ->
                  ());
               result
             | Terminal_done | Done -> Ok ()
           in
           let confirmation =
             match acknowledged.cleanup_progress with
             | Needs_both | Terminal_done ->
               let host = Descendant_admission_slot.host acknowledged.plan.slot in
               let result = host.confirm acknowledged.native in
               (match result, acknowledged.cleanup_progress with
                | Ok confirmation, Needs_both ->
                  acknowledged.cleanup_progress <- Confirmed confirmation
                | Ok _, Terminal_done -> acknowledged.cleanup_progress <- Done
                | (Ok _ | Error _), (Needs_both | Terminal_done | Confirmed _ | Done) ->
                  ());
               Result.map result ~f:ignore
             | Confirmed _ | Done -> Ok ()
           in
           let%bind () = terminal in
           confirmation
         with
         | result -> finish result
         | exception exn ->
           let backtrace = Stdlib.Printexc.get_raw_backtrace () in
           failed exn backtrace;
           Exn.raise_with_original_backtrace exn backtrace);
       Ok (Inherited_turn.Cleanup.Attempt.Scheduled attempt)
     with
     | exn ->
       let backtrace = Stdlib.Printexc.get_raw_backtrace () in
       failed exn backtrace;
       Ok
         (Inherited_turn.Cleanup.Attempt.Launch_failed
            { attempt; legacy = Actor_reply.Raised (exn, backtrace) }))
;;

let schedule_inherited_turn_cleanup t acknowledged =
  Result.bind (schedule_inherited_turn_cleanup_reported t acknowledged) ~f:(function
    | Inherited_turn.Cleanup.Attempt.Scheduled attempt -> Ok attempt.finished
    | Launch_failed { attempt; legacy = Actor_reply.Returned (Ok ()) } ->
      Ok attempt.finished
    | Launch_failed { legacy = Actor_reply.Returned (Error failure); _ } -> Error failure
    | Launch_failed { legacy = Actor_reply.Raised (exn, backtrace); _ } ->
      Exn.raise_with_original_backtrace exn backtrace)
;;

let retry_inherited_turn_cleanup t =
  if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
  then Error (error Conflict "inherited Turn cleanup belongs to another domain")
  else (
    match t.inherited_turn_cleanup with
    | None -> Ok ()
    | Some (Pack acknowledged) ->
      let%bind.Result promise = schedule_inherited_turn_cleanup t acknowledged in
      Eio.Promise.await promise)
;;

let idle_completion_basis (completion : Idle_completion_data.t) =
  match completion.phase with
  | Claimed basis | Completing basis -> Some basis
  | Fresh | Retired -> None
;;

let check_idle_completion_identity t (completion : Idle_completion_data.t) =
  if
    phys_equal completion.issuing_actor t.inference_owner_identity
    && Int.equal completion.domain t.runtime_source_domain
    && Int.equal completion.domain (Stdlib.Domain.self () :> int)
  then Ok ()
  else Error (error Conflict "legacy completion belongs to another actual Actor")
;;

let check_idle_completion_owner t (completion : Idle_completion_data.t) =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_identity t completion in
  match t.idle_completion with
  | Some actual when phys_equal actual completion -> Ok ()
  | None | Some _ -> Error (error Conflict "legacy completion lost its exact claim")
;;

let check_idle_completion_source t (completion : Idle_completion_data.t) =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_owner t completion in
  let%bind basis =
    idle_completion_basis completion
    |> Result.of_option ~error:(error Conflict "legacy completion has no active claim")
  in
  let%bind source = Runtime_builder.moderator_snapshot_observer t.state.moderator in
  if
    Int.equal basis.generation t.state.identity.generation
    && Option.equal Agent_protocol.Invocation.equal_observer basis.source source
    && Option.equal phys_equal basis.worker t.operation_worker
  then Ok ()
  else Error (error Conflict "legacy completion source or exact worker changed")
;;

let idle_completion_failure (completion : Idle_completion_data.t) =
  match completion.write with
  | Some write ->
    (match Idle_completion_write.diagnostic write with
     | Some (Returned failure) -> failure
     | Some (Raised (exn, _)) ->
       error Internal_error ("legacy completion writer raised: " ^ Exn.to_string exn)
     | None ->
       Agent_protocol.Error.create
         Conflict
         ~message:"legacy completion has an unresolved actual writer attempt"
         ~retryable:true
         ())
  | None -> error Conflict "legacy completion has no retained writer diagnostic"
;;

let release_idle_completion t (completion : Idle_completion_data.t) =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_identity t completion in
  match completion.phase with
  | Retired | Fresh -> Ok ()
  | Claimed _ | Completing _ ->
    let%bind () = check_idle_completion_owner t completion in
    let%bind () =
      match completion.write with
      | Some write ->
        (match Idle_completion_write.phase write with
         | Attempted -> Error (idle_completion_failure completion)
         | Not_attempted | Installed _ -> Ok ())
      | None -> Ok ()
    in
    let%bind () =
      match completion.suffix with
      | Some (Operation { phase = Acknowledged | Terminal_acknowledged; _ }) ->
        Error (error Conflict "legacy operation ACK still owns its actual suffix")
      | Some (Stop _) ->
        Error (error Conflict "legacy stopped candidate still owns its cleanup suffix")
      | Some (Operation { phase = Prepared | Handed_off | Terminated; _ }) | None -> Ok ()
    in
    if moderator_is_borrowed t
    then Error (error Conflict "another callback owns moderator exclusion")
    else (
      (match completion.suffix with
       | Some (Operation suffix) ->
         (match suffix.phase with
          | Prepared -> Operation_owner.retire suffix.owner
          | Acknowledged | Handed_off | Terminal_acknowledged | Terminated -> ())
       | None | Some (Stop _) -> ());
      completion.phase <- Retired;
      t.idle_completion <- None;
      t.idle_moderator_borrowed <- false;
      Ok ())
;;

let prepare_idle_completion_write
      t
      (completion : Idle_completion_data.t option)
      ~kind
      ~candidate
      ~attempted
  =
  let open Result.Let_syntax in
  match completion with
  | None -> Ok None
  | Some completion ->
    let%bind () = check_idle_completion_owner t completion in
    let%bind () =
      match completion.write with
      | Some previous ->
        (match Idle_completion_write.phase previous with
         | Attempted -> Error (idle_completion_failure completion)
         | Not_attempted | Installed _ -> Ok ())
      | None -> Ok ()
    in
    let%bind write =
      Idle_completion_write.capture
        ~owner:completion.identity
        ~previous:t.state
        ~requested:candidate
        ~kind
        ~attempted
    in
    completion.write <- Some write;
    (match kind, completion.suffix with
     | (Start_ordinary_turn | Start_compaction), Some (Operation suffix) ->
       suffix.native_write <- Some write
     | (Start_ordinary_turn | Start_compaction), (None | Some (Stop _)) ->
       invalid_arg "legacy operation scope has no prepared native suffix"
     | ( ( Reconcile_foreground
         | Reconcile_terminal
         | Checkpoint
         | Suppress_automatic
         | Stop
         | Callback_failure
         | Retire_turn
         | Retire_compaction )
       , _ ) -> ());
    completion.pending_prefix
    <- (match kind, completion.prefix, completion.action with
        | Reconcile_foreground, Empty, _ -> Some (Idle_completion_data.Reconciled write)
        | Reconcile_foreground, Checkpointed checkpoint, _ ->
          Some (Checkpointed_and_reconciled { checkpoint; reconciliation = write })
        | Checkpoint, Empty, Some Compaction -> Some (Checkpointed write)
        | ( ( Reconcile_foreground
            | Reconcile_terminal
            | Checkpoint
            | Suppress_automatic
            | Stop
            | Callback_failure
            | Start_compaction
            | Start_ordinary_turn
            | Retire_turn
            | Retire_compaction )
          , (Empty | Reconciled _ | Checkpointed _ | Checkpointed_and_reconciled _)
          , _ ) -> None);
    Ok (Some (completion, write))
;;

let select_idle_completion_writer
      t
      ((completion, write) : Idle_completion_data.t * Idle_completion_write.t)
      ~candidate
      ~selected
  =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_source t completion in
  let%bind () =
    match completion.cancellation with
    | None -> Ok ()
    | Some failure ->
      (match Idle_completion_write.kind write with
       | Retire_turn | Retire_compaction | Reconcile_terminal | Callback_failure -> Ok ()
       | Reconcile_foreground
       | Checkpoint
       | Suppress_automatic
       | Stop
       | Start_compaction
       | Start_ordinary_turn -> Error failure)
  in
  let%bind () =
    match selected with
    | Idle_completion_write.Selected.Requested (Start_ordinary_turn | Start_compaction) ->
      (match completion.suffix, candidate.Session_transition.state.active_operation with
       | Some (Operation suffix), Some operation
         when Agent_protocol.Id.Operation.equal suffix.operation.id operation.id
              && Int.equal suffix.operation.generation operation.generation
              && Agent_protocol.Operation.equal_kind suffix.operation.kind operation.kind
              && Option.equal phys_equal suffix.previous_owner t.operation_agent_custody
         -> Ok ()
       | _ -> Error (error Conflict "legacy writer lost its actual operation suffix"))
    | Requested
        ( Reconcile_foreground
        | Reconcile_terminal
        | Checkpoint
        | Suppress_automatic
        | Stop
        | Callback_failure
        | Retire_turn
        | Retire_compaction )
    | Admission_hold _ -> Ok ()
  in
  Idle_completion_write.select_actual
    write
    ~owner:completion.identity
    ~state:t.state
    ~candidate
    ~selected
;;

let install_idle_completion_writer
      t
      ((completion, write) : Idle_completion_data.t * Idle_completion_write.t)
      candidate
  =
  Idle_completion_write.install
    write
    ~owner:completion.Idle_completion_data.identity
    ~candidate
    ~state:t.state;
  Option.iter completion.pending_prefix ~f:(fun prefix -> completion.prefix <- prefix);
  completion.pending_prefix <- None;
  match Idle_completion_write.phase write with
  | Installed acknowledgement ->
    (match Idle_completion_write.Acknowledgement.selected acknowledgement with
     | Requested (Start_ordinary_turn | Start_compaction) ->
       (match completion.suffix with
        | Some (Operation suffix) ->
          Option.iter suffix.previous_owner ~f:Operation_owner.retire;
          t.operation_agent_custody <- suffix.owner_slot;
          t.operation_completion <- suffix.completion_slot;
          suffix.installed := true;
          suffix.phase <- Acknowledged
        | None | Some (Stop _) -> invalid_arg "legacy operation ACK has no actual suffix")
     | Requested (Retire_turn | Retire_compaction) ->
       (match completion.suffix with
        | Some (Operation suffix) -> suffix.phase <- Terminal_acknowledged
        | None | Some (Stop _) -> invalid_arg "legacy terminal ACK has no actual suffix")
     | Requested
         ( Reconcile_foreground
         | Reconcile_terminal
         | Checkpoint
         | Suppress_automatic
         | Stop
         | Callback_failure )
     | Admission_hold _ -> ())
  | Not_attempted | Attempted ->
    invalid_arg "legacy completion State ACK was not installed"
;;

let close_inherited_run_exit : type outcome. t -> outcome Inherited_turn.Source.t -> unit =
  fun t source ->
  let close preparation exit =
    Option.iter exit ~f:(fun exit ->
      Run_preparation.Admission_exit.close exit ~owner:t.run_preparation_owner);
    match preparation, t.run_preparation with
    | Some preparation, Some (Initial actual) when phys_equal preparation actual ->
      t.run_preparation <- None
    | (Some _ | None), (Some _ | None) -> ()
  in
  match source with
  | Inherited_turn.Source.Held_input source ->
    close
      (Inherited_turn.Source.preparation (Held_input source))
      (Some source.preparation_exit)
  | Message _ | Managed _ | History _ | Idle _ -> ()
  | Goal_resume source ->
    Goal_continuation.close source.selection.scope.continuation.binding.preparation
  | Goal_subscription source ->
    Goal_continuation.close source.scope.continuation.binding.preparation
  | Run_user (source, _) -> close source.preparation source.preparation_exit
;;

let seal_inherited_turn_before_writer
  : type outcome.
    t
    -> outcome Inherited_turn.t
    -> (Descendant_preparation.Closed_before_writer.t, Agent_protocol.Error.t) result
  =
  fun t plan ->
  let open Result.Let_syntax in
  let%map closed = seal_descendant_admission_slot t plan.slot in
  (match plan.phase with
   | Writer_prepared prepared -> Operation_owner.retire prepared.owner
   | Pending | Acknowledged _ | Closed -> ());
  (match plan.source with
   | Held_input source ->
     source.selection.scope.phase <- Closed;
     if Option.exists t.held_input_scope ~f:(phys_equal source.selection.scope)
     then t.held_input_scope <- None
   | Message _
   | Managed _
   | Run_user _
   | History _
   | Goal_resume _
   | Goal_subscription _
   | Idle _ -> ());
  plan.phase <- Closed;
  Option.iter (Inherited_turn.Source.custody plan.source) ~f:retire_agent_custody;
  close_inherited_run_exit t plan.source;
  closed
;;

let read_idle_turn_continuation t (owner : Idle_completion_data.t) =
  let%bind.Result () = check_idle_completion_identity t owner in
  match t.idle_turn_continuation with
  | None -> Ok Inherited_turn.Idle_retirement.Ordinary
  | Some continuation when phys_equal continuation.Idle_continuation.owner owner ->
    (match continuation.phase with
     | Selected selected -> Ok (Inherited_turn.Idle_retirement.Selected selected)
     | Bound plan -> Ok (Inherited_turn.Idle_retirement.Bound plan))
  | Some _ -> Error (error Conflict "legacy Turn continuation belongs to another holder")
;;

let cancel_idle_turn_continuation t (owner : Idle_completion_data.t) failure =
  match t.idle_turn_continuation with
  | Some continuation when phys_equal continuation.Idle_continuation.owner owner ->
    (match continuation.phase with
     | Selected _ -> ()
     | Bound plan -> Inherited_turn.request_cancellation plan ~failure)
  | None | Some _ -> ()
;;

let cleanup_idle_turn_continuation t = function
  | Inherited_turn.Idle_retirement.Ordinary | Selected _ -> Ok ()
  | Bound plan ->
    let open Result.Let_syntax in
    (match plan.Inherited_turn.phase with
     | Pending | Writer_prepared _ ->
       let%bind closed = seal_inherited_turn_before_writer t plan in
       let%bind promise = schedule_descendant_admission_cleanup t plan.slot ~closed in
       Eio.Promise.await promise
     | Acknowledged acknowledged ->
       let%bind promise = schedule_inherited_turn_cleanup t acknowledged in
       Eio.Promise.await promise
     | Closed ->
       (* Closed is the real seal phase, but all root close ACKs must still join. *)
       let%bind closed = seal_descendant_admission_slot t plan.slot in
       let%bind promise = schedule_descendant_admission_cleanup t plan.slot ~closed in
       Eio.Promise.await promise)
;;

let resume_retirement_cleanup_reply = function
  | Some { Retirement_cleanup_completion.reply = Actor_reply.Returned result; _ } ->
    result
  | Some { Retirement_cleanup_completion.reply = Actor_reply.Raised (exn, backtrace); _ }
    -> Exn.raise_with_original_backtrace exn backtrace
  | None -> Error (error Invalid_state "actual cleanup completed without its outcome")
;;

let cleanup_captured_idle_turn_continuation t = function
  | Inherited_turn.Idle_retirement.Ordinary | Selected _ -> Ok ()
  | Bound plan ->
    let open Result.Let_syntax in
    (match plan.Inherited_turn.phase with
     | Pending | Writer_prepared _ ->
       let%bind closed = seal_inherited_turn_before_writer t plan in
       let%bind issued =
         schedule_descendant_admission_cleanup_reported t plan.slot ~closed
       in
       let attempt =
         match issued with
         | Scheduled attempt | Launch_failed { attempt; _ } -> attempt
       in
       let _ = Eio.Promise.await attempt.finished in
       resume_retirement_cleanup_reply attempt.outcome
     | Closed ->
       let%bind closed = seal_descendant_admission_slot t plan.slot in
       let%bind issued =
         schedule_descendant_admission_cleanup_reported t plan.slot ~closed
       in
       let attempt =
         match issued with
         | Scheduled attempt | Launch_failed { attempt; _ } -> attempt
       in
       let _ = Eio.Promise.await attempt.finished in
       resume_retirement_cleanup_reply attempt.outcome
     | Acknowledged acknowledged ->
       let%bind issued = schedule_inherited_turn_cleanup_reported t acknowledged in
       let attempt =
         match issued with
         | Scheduled attempt | Launch_failed { attempt; _ } -> attempt
       in
       let _ = Eio.Promise.await attempt.finished in
       resume_retirement_cleanup_reply attempt.outcome)
;;

let schedule_idle_completion_retirement_reported
      ?(source = Idle_cleanup_source.Current)
      t
      (completion : Idle_completion_data.t)
  =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_identity t completion in
  match completion.phase, completion.cleanup, source with
  | (Fresh | Claimed _ | Completing _ | Retired), Running attempt, _ ->
    Ok (Idle_completion_data.Cleanup_attempt.Scheduled attempt)
  | (Fresh | Retired), (Idle | Scheduling_failed _), Current
  | (Fresh | Retired), Idle, Captured None ->
    let promise, resolver = Eio.Promise.create () in
    Eio.Promise.resolve resolver (Ok ());
    Ok
      (Idle_completion_data.Cleanup_attempt.Scheduled
         { finished = promise
         ; outcome =
             Some
               { reply = Actor_reply.Returned (Ok ())
               ; boundary =
                   (match completion.phase with
                    | Retired -> Retirement_cleanup_completion.Boundary.Released
                    | Fresh | Claimed _ | Completing _ -> Before_release)
               }
         })
  | (Claimed _ | Completing _), Scheduling_failed (failure, _), Current
  | ( (Fresh | Claimed _ | Completing _ | Retired)
    , Scheduling_failed (failure, _)
    , Captured _ ) -> Error failure
  | (Claimed _ | Completing _), Idle, Current
  | (Fresh | Claimed _ | Completing _ | Retired), Idle, Captured _ ->
    let promise, resolver = Eio.Promise.create () in
    let attempt : Idle_completion_data.Cleanup_attempt.t =
      { finished = promise; outcome = None }
    in
    let finished result =
      match Eio.Promise.peek promise with
      | Some _ -> ()
      | None ->
        if Option.is_none attempt.outcome
        then
          attempt.outcome
          <- Some
               { reply = Actor_reply.Returned result
               ; boundary =
                   (match completion.phase with
                    | Retired -> Retirement_cleanup_completion.Boundary.Released
                    | Fresh | Claimed _ | Completing _ -> Before_release)
               };
        (match completion.cleanup with
         | Running actual when phys_equal actual attempt -> completion.cleanup <- Idle
         | Idle | Running _ | Scheduling_failed _ -> ());
        Eio.Promise.resolve resolver result
    in
    completion.cleanup <- Running attempt;
    (try
       (* Eio fork skips a cancelling switch; reject before promising a producer. *)
       Eio.Switch.check t.sw;
       Eio.Fiber.fork ~sw:t.sw (fun () ->
         match
           Eio.Fiber.yield ();
           Eio.Promise.await completion.exited;
           let open Result.Let_syntax in
           let%bind continuation =
             match source with
             | Current ->
               call
                 t
                 ~priority:Priority
                 (Inherited_turn (Read_idle_continuation completion))
             | Captured selected ->
               call
                 t
                 ~priority:Priority
                 (Runtime_retirement
                    (Advance_cleanup (Cleanup_read_idle (completion, selected))))
           in
           let%bind () =
             match source with
             | Current -> cleanup_idle_turn_continuation t continuation
             | Captured _ -> cleanup_captured_idle_turn_continuation t continuation
           in
           match source with
           | Current ->
             call
               t
               ~priority:Priority
               (Inherited_turn (Retire_idle_continuation (completion, continuation)))
           | Captured selected ->
             call
               t
               ~priority:Priority
               (Runtime_retirement
                  (Advance_cleanup (Cleanup_retire_idle (completion, selected))))
         with
         | result -> finished result
         | exception exn ->
           let backtrace = Stdlib.Printexc.get_raw_backtrace () in
           if Option.is_none attempt.outcome
           then
             attempt.outcome
             <- Some
                  { reply = Actor_reply.Raised (exn, backtrace)
                  ; boundary =
                      (match completion.phase with
                       | Retired -> Retirement_cleanup_completion.Boundary.Released
                       | Fresh | Claimed _ | Completing _ -> Before_release)
                  };
           finished
             (Error (error Interrupted "legacy completion retirement was interrupted"));
           Exn.raise_with_original_backtrace exn backtrace);
       Ok (Idle_completion_data.Cleanup_attempt.Scheduled attempt)
     with
     | exn ->
       let backtrace = Stdlib.Printexc.get_raw_backtrace () in
       if Option.is_none attempt.outcome
       then
         attempt.outcome
         <- Some
              { reply = Actor_reply.Raised (exn, backtrace)
              ; boundary =
                  (match completion.phase with
                   | Retired -> Retirement_cleanup_completion.Boundary.Released
                   | Fresh | Claimed _ | Completing _ -> Before_release)
              };
       let failure =
         error
           Interrupted
           ("legacy completion retirement could not be scheduled: " ^ Exn.to_string exn)
       in
       (* This is cleanup setup, possibly called from an original-error finally.
          Retain its exact diagnostic without replacing that original exit. *)
       completion.cleanup <- Scheduling_failed (failure, Raised (exn, backtrace));
       (match Eio.Promise.peek promise with
        | None -> Eio.Promise.resolve resolver (Error failure)
        | Some _ -> ());
       Ok
         (Idle_completion_data.Cleanup_attempt.Launch_failed
            { attempt; legacy = Actor_reply.Returned (Error failure) }))
;;

let schedule_idle_completion_retirement t (completion : Idle_completion_data.t) =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_identity t completion in
  match completion.phase with
  | Fresh | Retired ->
    (* Preserve the legacy phase shortcut; reported recovery instead joins the
       actual Running attempt through the entire final retirement suffix. *)
    let promise, resolver = Eio.Promise.create () in
    Eio.Promise.resolve resolver (Ok ());
    Ok promise
  | Claimed _ | Completing _ ->
    Result.bind (schedule_idle_completion_retirement_reported t completion) ~f:(function
      | Idle_completion_data.Cleanup_attempt.Scheduled attempt -> Ok attempt.finished
      | Launch_failed { attempt; legacy = Actor_reply.Returned (Ok ()) } ->
        Ok attempt.finished
      | Launch_failed { legacy = Actor_reply.Returned (Error failure); _ } ->
        Error failure
      | Launch_failed { legacy = Actor_reply.Raised (exn, backtrace); _ } ->
        Exn.raise_with_original_backtrace exn backtrace)
;;

let drain_idle_completion_retirement t =
  if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
  then Error (error Conflict "legacy completion drain belongs to another Actor domain")
  else (
    match t.idle_completion with
    | None -> Ok ()
    | Some completion ->
      let open Result.Let_syntax in
      let%bind () = check_idle_completion_identity t completion in
      let failure = error Interrupted "legacy completion source is retiring" in
      Idle_completion_data.request_cancellation completion failure;
      cancel_idle_turn_continuation t completion failure;
      let%bind promise = schedule_idle_completion_retirement t completion in
      Eio.Promise.await promise)
;;

let prepare_idle_operation_suffix
      t
      (completion : Idle_completion_data.t option)
      ~operation
      ~custody
      ~installed
      ~kind
  =
  match completion with
  | None -> Ok ()
  | Some completion ->
    let%bind.Result () = check_idle_completion_source t completion in
    let owner : Operation_owner.t =
      { operation_id = operation.Agent_protocol.Operation.id
      ; admission = create_agent_admission custody
      ; held = None
      ; descendant_guard = None
      ; completion =
          Operation_completion.create
            ~issuer:t.initialization_owner
            ~domain:t.runtime_source_domain
            ~operation
      }
    in
    let suffix : Idle_completion_data.operation_suffix =
      { operation
      ; owner
      ; owner_slot = Some owner
      ; completion_slot = Some owner.completion
      ; worker = t.operation_worker
      ; installed
      ; kind
      ; phase = Prepared
      ; native_write = None
      ; previous_owner = t.operation_agent_custody
      }
    in
    completion.suffix <- Some (Operation suffix);
    Ok ()
;;

let check_idle_operation_suffix t (completion : Idle_completion_data.t option) operation =
  match completion with
  | None -> Ok ()
  | Some completion ->
    let open Result.Let_syntax in
    let%bind () = check_idle_completion_source t completion in
    let%bind () =
      match completion.cancellation with
      | None -> Ok ()
      | Some failure -> Error failure
    in
    (match completion.suffix, t.state.active_operation, t.operation_agent_custody with
     | Some (Operation suffix), Some actual, Some owner
       when Idle_completion_data.equal_operation_phase suffix.phase Acknowledged
            && phys_equal owner suffix.owner
            && Option.equal phys_equal suffix.worker t.operation_worker
            && Agent_protocol.Id.Operation.equal
                 operation.Agent_protocol.Operation.id
                 actual.id
            && Agent_protocol.Id.Operation.equal actual.id suffix.operation.id
            && Int.equal actual.generation suffix.operation.generation
            && Agent_protocol.Operation.equal_kind actual.kind suffix.operation.kind ->
       Ok ()
     | _ ->
       Error (error Conflict "legacy completion cannot redirect its acknowledged worker"))
;;

let handoff_idle_operation (completion : Idle_completion_data.t option) =
  Option.iter completion ~f:(fun completion ->
    match completion.Idle_completion_data.suffix with
    | Some (Operation suffix) -> suffix.phase <- Handed_off
    | None | Some (Stop _) -> invalid_arg "legacy completion has no operation to hand off")
;;

let drain_descendant_cleanup t =
  let open Result.Let_syntax in
  let%bind () = drain_idle_completion_retirement t in
  let%bind () =
    if Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Conflict "descendant cleanup belongs to another domain")
  in
  (* Source retirement owns this explicit cancellation, not a fresh admission or
     another sender's attempt. The same retained ACK keeps partial facts. *)
  (match t.inherited_turn_cleanup with
   | None -> ()
   | Some (Pack acknowledged) ->
     Inherited_turn.request_cancellation
       acknowledged.plan
       ~failure:(error Interrupted "inherited Turn source is retiring"));
  (match t.governed_admission_slot with
   | Some (Policy_causal { causal; _ } | Combined { causal; _ }) ->
     causal.cancellation_requested <- true
   | None | Some (Descendant _) -> ());
  let acknowledged = retry_inherited_turn_cleanup t in
  let sealed = retry_descendant_admission_cleanup t in
  let%bind () = acknowledged in
  sealed
;;

let publish_durable t events =
  Eio.Mutex.use_rw ~protect:true t.subscriber_mutex (fun () ->
    List.iter events ~f:(Active_calls.finish t.active_calls);
    Map.iter !(t.subscribers) ~f:(fun subscriber ->
      List.iter events ~f:(Subscriber.publish_durable subscriber)))
;;

let broadcast_recoverable t event =
  Eio.Mutex.use_rw ~protect:true t.subscriber_mutex (fun () ->
    Active_calls.observe t.active_calls event;
    Map.iter !(t.subscribers) ~f:(fun subscriber ->
      Subscriber.publish_recoverable subscriber event))
;;

let sync_extension_clock t =
  let timers =
    t.state.schedules @ Staged_schedules.values t.staged_schedules
    |> List.filter_map ~f:(fun timer ->
      match timer.Agent_protocol.Schedule.ownership, timer.status with
      | Some _, (Scheduled | Delivering) ->
        Some (Extension_clock.Key.Schedule timer.id, timer.next_due_at)
      | _ -> None)
  in
  let subscriptions =
    t.state.subscriptions @ Staged_subscriptions.values t.staged_subscriptions
    |> List.filter_map ~f:(fun subscription ->
      match
        subscription.Agent_protocol.Subscription.context.source, subscription.result
      with
      | Some _, None ->
        Some
          ( Extension_clock.Key.Subscription subscription.context.id
          , subscription.context.deadline )
      | _ -> None)
  in
  Extension_clock.reconcile
    t.extension_clock
    ~retained:(timers @ subscriptions)
    ~wall_now:(t.services.now ())
    ~monotonic_now:(t.services.monotonic_now ())
;;

let check_held_effect continuation =
  let open Result.Let_syntax in
  let target = Admitted_activation.Continuation.target continuation in
  let%bind () = Admitted_activation.Continuation.check_basis continuation in
  let%bind () = Admitted_activation.Continuation.check_policy continuation in
  let%bind () = Admitted_activation.Continuation.check_timing continuation in
  let%bind () = Admitted_activation.Continuation.check_authority continuation in
  let%bind () = Held_run.Activation.check_basis target in
  Admitted_activation.Continuation.check_basis continuation
;;

let check_runtime_construction_effect construction =
  let open Result.Let_syntax in
  let%bind () = Runtime_construction.check_basis construction in
  let%bind () = Runtime_construction.check_policy construction in
  let%bind () = Runtime_construction.check_timing construction in
  let%bind () = Runtime_construction.check_authority construction in
  Runtime_construction.check_basis construction
;;

let held_authored_basis t (scope : Held_authored_start.t) =
  let open Result.Let_syntax in
  let activation = Admitted_activation.Continuation.target scope.continuation in
  let%bind () =
    if
      Int.equal scope.domain (Stdlib.Domain.self () :> int)
      && phys_equal scope.issuing_actor t.inference_owner_identity
      && Option.exists t.held_authored_start ~f:(phys_equal scope)
      && Option.exists t.held_activation ~f:(phys_equal activation)
      && Option.exists
           t.operation_worker
           ~f:(phys_equal (Runtime_builder.Authored_start.worker scope.startup))
      && Option.equal
           phys_equal
           t.moderator_manager
           (Runtime_builder.Authored_start.manager scope.startup)
      && Run_authorities.is_current
           t.run_authorities
           scope.binding
           ~run_id:activation.run.id
    then Ok ()
    else Error (error Conflict "held authored startup owner or runtime changed")
  in
  let%bind () =
    match scope.phase with
    | Starting | Ready | Executing _ | Completed _ -> Ok ()
    | Staged | Released | Attempt_unconfirmed | Closed ->
      Error (error Conflict "held authored startup is not live")
  in
  activation.owned_basis ()
;;

let held_authored_run t scope =
  let open Result.Let_syntax in
  let%bind () = held_authored_basis t scope in
  let activation =
    Admitted_activation.Continuation.target scope.Held_authored_start.continuation
  in
  Option.bind t.state.run_state ~f:(fun index -> Run_state.find index activation.run.id)
  |> Result.of_option ~error:(error Conflict "held authored Run is absent")
;;

let held_authored_event_basis t (borrow : queued_event_borrow) scope =
  let open Result.Let_syntax in
  let%bind () = held_authored_basis t scope in
  if
    Option.exists t.queued_event_borrow ~f:(phys_equal borrow)
    && Option.exists
         (Option.bind borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial)
         ~f:(phys_equal scope)
    && t.idle_moderator_borrowed
    && borrow.callback_active
    && Atomic.get borrow.authority_live
    && (not (borrow.committed || borrow.cancel_requested))
    && (match scope.Held_authored_start.phase with
        | Executing id ->
          Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
        | Staged
        | Starting
        | Ready
        | Completed _
        | Released
        | Attempt_unconfirmed
        | Closed -> false)
    && List.exists t.state.moderator_executions ~f:(fun retained ->
      Agent_protocol.Moderator_execution.equal_context
        retained.context
        borrow.receipt.context
      &&
      match retained.status with
      | Running -> true
      | Completed _ | Failed _ | Interrupted _ -> false)
  then Ok ()
  else Error (error Conflict "held authored Event is no longer current")
;;

(* The payload is retained by the one actual preparation phase. This predicate
   authenticates a physical runtime/callback; it grants no fresh effect right. *)
let goal_runtime_scope_basis t (scope : Goal_continuation.runtime_scope) =
  let open Result.Let_syntax in
  let preparation = scope.continuation.binding.preparation in
  let%bind () =
    if
      Int.equal preparation.domain (Stdlib.Domain.self () :> int)
      && phys_equal scope.issuing_actor t.inference_owner_identity
      && Run_preparation.Custody.belongs_to
           (Goal_continuation.custody preparation)
           ~owner:t.run_preparation_owner
      && Option.exists t.operation_worker ~f:(phys_equal scope.worker)
      && Option.equal phys_equal t.moderator_manager scope.manager
      &&
      match preparation.runtime_phase with
      | Installed current | Callback_completed current -> phys_equal current scope
      | Handed_off (current, _) | Retired current -> phys_equal current scope
      | _ -> false
    then Ok ()
    else Error (error Conflict "Goal resume runtime owner changed")
  in
  Runtime_source_preparation.validate_target scope.continuation.binding.source t.state
;;

let select_goal_runtime t continuation =
  let open Result.Let_syntax in
  let preparation = continuation.Goal_continuation.binding.preparation in
  let%bind scope =
    match preparation.runtime_phase with
    | (Installed scope | Callback_completed scope | Handed_off (scope, _) | Retired scope)
      when phys_equal scope.continuation continuation -> Ok scope
    | _ -> Error (error Conflict "Goal continuation has no exact installed runtime")
  in
  let%map () = goal_runtime_scope_basis t scope in
  scope
;;

let goal_runtime_run t (scope : Goal_continuation.runtime_scope) =
  let open Result.Let_syntax in
  let%bind () = goal_runtime_scope_basis t scope in
  Option.bind t.state.run_state ~f:(fun index ->
    Run_state.find index scope.continuation.binding.preparation.run.id)
  |> Result.of_option ~error:(error Conflict "Goal resume Run is absent")
;;

let goal_runtime_event_basis t (borrow : queued_event_borrow) scope =
  let open Result.Let_syntax in
  let%bind () = goal_runtime_scope_basis t scope in
  if
    Option.exists t.queued_event_borrow ~f:(phys_equal borrow)
    && Option.exists borrow.lifecycle_owner ~f:(function
      | Existing_goal_resume current -> phys_equal current scope
      | Initial_authored _ -> false)
    && t.idle_moderator_borrowed
    && borrow.callback_active
    && Atomic.get borrow.authority_live
    && (not (borrow.committed || borrow.cancel_requested))
    && (match scope.Goal_continuation.callback with
        | Executing id ->
          Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
        | Pending | Completed _ | Joined -> false)
    && List.exists t.state.moderator_executions ~f:(fun retained ->
      Agent_protocol.Moderator_execution.equal_context
        retained.context
        borrow.receipt.context
      &&
      match retained.status with
      | Running -> true
      | _ -> false)
  then Ok ()
  else Error (error Conflict "Goal resume Event is no longer current")
;;

let goal_wake_transferred_borrow t (preparation : Goal_continuation.Preparation.t) =
  match preparation.runtime_phase with
  | Handed_off (scope, Existing_execution (Queued_event executing)) ->
    phys_equal scope.continuation.binding.preparation preparation
    && Option.exists t.queued_event_borrow ~f:(fun borrow ->
      Agent_protocol.Moderator_execution.equal_context
        borrow.receipt.context
        executing.context
      && Result.is_ok (goal_runtime_event_basis t borrow scope))
  | Unclaimed
  | Starting_writer _
  | Starting_acknowledged
  | Running_writer _
  | Constructing
  | Installed _
  | Callback_completed _
  | Retired _
  | Closed
  | Handed_off (_, Resume _)
  | Handed_off
      ( _
      , Existing_execution
          ( Subscription_turn _
          | Claimed_job_resource _
          | Lifecycle_wait _
          | Lifecycle_settlement _ ) ) -> false
;;

let lifecycle_event_basis t borrow = function
  | Lifecycle_callback_owner.Initial_authored scope ->
    held_authored_event_basis t borrow scope
  | Existing_goal_resume scope -> goal_runtime_event_basis t borrow scope
;;

let lifecycle_event_effect t borrow owner =
  let open Result.Let_syntax in
  let%bind () = lifecycle_event_basis t borrow owner in
  let%bind () =
    match owner with
    | Lifecycle_callback_owner.Initial_authored scope ->
      check_held_effect scope.continuation
    | Existing_goal_resume scope ->
      check_runtime_construction_effect (Existing_goal scope.continuation)
  in
  lifecycle_event_basis t borrow owner
;;

let lifecycle_event_run t borrow owner =
  let open Result.Let_syntax in
  let%bind () = lifecycle_event_basis t borrow owner in
  match owner with
  | Lifecycle_callback_owner.Initial_authored scope -> held_authored_run t scope
  | Existing_goal_resume scope -> goal_runtime_run t scope
;;

let goal_runtime_of_borrow (borrow : queued_event_borrow) =
  Option.bind borrow.lifecycle_owner ~f:(function
    | Lifecycle_callback_owner.Existing_goal_resume scope -> Some scope
    | Initial_authored _ -> None)
;;

let goal_runtime_scope t =
  Option.bind t.run_preparation ~f:(function
    | Existing_goal preparation ->
      (match preparation.runtime_phase with
       | Installed scope | Callback_completed scope -> Some scope
       | _ -> None)
    | Initial _ | Delegated_load _ -> None)
;;

let goal_runtime_job t (job : Agent_protocol.Job.t) =
  Option.bind (goal_runtime_scope t) ~f:(fun scope ->
    Option.some_if
      (List.exists scope.jobs ~f:(fun owned ->
         Agent_protocol.Id.Job.equal owned.id job.id
         && Int.equal owned.generation job.generation))
      scope)
;;

let held_authored_factual_preparation t (scope : Held_authored_start.t) =
  let preparation =
    (Admitted_activation.Continuation.target scope.continuation).preparation
  in
  if
    phys_equal scope.issuing_actor t.inference_owner_identity
    && Option.exists t.held_authored_start ~f:(phys_equal scope)
    && Option.exists (initial_run_preparation t) ~f:(phys_equal preparation)
    && Result.is_ok
         (Run_preparation.check_basis
            preparation
            ~owner:t.run_preparation_owner
            ~state:t.state)
  then Some preparation
  else None
;;

let held_authored_of_borrow _t (borrow : queued_event_borrow) =
  match Option.bind borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial with
  | None -> None
  | Some scope -> Some scope
;;

let held_authored_job t (job : Agent_protocol.Job.t) =
  Option.bind t.held_authored_start ~f:(fun scope ->
    Option.some_if
      ((match scope.Held_authored_start.phase with
        | Starting | Ready | Executing _ | Completed _ -> true
        | Staged | Released | Attempt_unconfirmed | Closed -> false)
       && List.exists scope.Held_authored_start.jobs ~f:(fun admitted ->
         Agent_protocol.Id.Job.equal admitted.id job.id
         && Int.equal admitted.generation job.generation
         && Agent_protocol.Job.equal_kind admitted.kind job.kind
         && Jsonaf.exactly_equal admitted.payload job.payload
         && Option.equal
              Agent_protocol.Job.Inference_origin.equal
              admitted.inference_origin
              job.inference_origin
         && Option.equal Agent_protocol.Job.equal_launch admitted.launch job.launch))
      scope)
;;

(* Scheduled descendants stay queued until this actual startup releases its
   hold. They cannot race target Store custody during the final handoff refresh.
   Synchronous Not_required calls still execute inside the owning callback. *)
let held_authored_job_deferred t (job : Agent_protocol.Job.t) =
  match job.status, job.delivery with
  | Queued, (Pending | Delivered _) ->
    Option.exists (held_authored_job t job) ~f:(fun scope ->
      Result.is_ok (held_authored_basis t scope))
  | Queued, (Not_required | Discarded _)
  | ( ( Running
      | Waiting_permission _
      | Waiting_completion _
      | Succeeded
      | Failed _
      | Cancelled
      | Interrupted _ )
    , _ ) -> false
;;

let held_authored_job_preparation t job =
  Option.bind (held_authored_job t job) ~f:(held_authored_factual_preparation t)
;;

let held_authored_of_execution t = function
  | Inference_event borrow -> held_authored_of_borrow t borrow
  | Inference_invocation execution ->
    (match execution.owner with
     | Event_moderator borrow -> held_authored_of_borrow t borrow
     | Background_job scope -> held_authored_job t scope.job
     | Foreground _ | Invocation_moderator _ -> None)
  | Inference_job scope -> held_authored_job t scope.job
  | Inference_moderator borrow ->
    Option.bind borrow.job_scope ~f:(fun scope -> held_authored_job t scope.job)
  | Inference_operation _
  | Inference_held_input _
  | Inference_initialization _
  | Inference_initialization_job _ -> None
;;

let held_authored_handoff_acknowledged (scope : Held_authored_start.t) =
  if not (Int.equal scope.domain (Stdlib.Domain.self () :> int))
  then false
  else (
    match
      scope.phase, !((Admitted_activation.Continuation.target scope.continuation).phase)
    with
    | Released, Handed_off (Authored_start proof) ->
      phys_equal proof.binding scope.binding
    | _ -> false)
;;

let refresh_held_authored t scope =
  let open Result.Let_syntax in
  if held_authored_handoff_acknowledged scope
  then Ok ()
  else (
    let%bind () = held_authored_basis t scope in
    let%bind () =
      Admitted_activation.Continuation.refresh scope.Held_authored_start.continuation
    in
    let%bind () = check_held_effect scope.continuation in
    held_authored_basis t scope)
;;

let initialization_construction_of_execution t = function
  | Inference_initialization scope | Inference_initialization_job (scope, _) ->
    if Option.exists t.initialization_scope ~f:(phys_equal scope)
    then Initialization_scope_data.construction scope
    else None
  | Inference_event borrow ->
    Option.bind t.legacy_callback_scope ~f:(fun callback ->
      if phys_equal callback.borrow borrow
      then
        Option.bind callback.constructor_scope ~f:Initialization_scope_data.construction
      else None)
  | Inference_invocation execution ->
    (match execution.owner with
     | Event_moderator borrow ->
       Option.bind t.legacy_callback_scope ~f:(fun callback ->
         if phys_equal callback.borrow borrow
         then
           Option.bind
             callback.constructor_scope
             ~f:Initialization_scope_data.construction
         else None)
     | Foreground _ | Background_job _ | Invocation_moderator _ -> None)
  | Inference_operation _
  | Inference_held_input _
  | Inference_job _
  | Inference_moderator _ -> None
;;

let goal_runtime_of_execution t = function
  | Inference_event borrow -> goal_runtime_of_borrow borrow
  | Inference_invocation execution ->
    (match execution.owner with
     | Event_moderator borrow -> goal_runtime_of_borrow borrow
     | Background_job job -> goal_runtime_job t job.job
     | Foreground _ | Invocation_moderator _ -> None)
  | Inference_job job -> goal_runtime_job t job.job
  | Inference_moderator borrow ->
    Option.bind borrow.job_scope ~f:(fun job -> goal_runtime_job t job.job)
  | Inference_operation _
  | Inference_held_input _
  | Inference_initialization _
  | Inference_initialization_job _ -> None
;;

let refresh_held_execution t execution =
  let open Result.Let_syntax in
  let%bind () =
    Option.value_map
      (held_authored_of_execution t execution)
      ~default:(Ok ())
      ~f:(refresh_held_authored t)
  in
  let%bind () =
    Option.value_map
      (goal_runtime_of_execution t execution)
      ~default:(Ok ())
      ~f:(fun scope -> Runtime_construction.refresh (Existing_goal scope.continuation))
  in
  let%bind () =
    match initialization_construction_of_execution t execution with
    | Some ((Runtime_construction.Existing_goal _ | Delegated_load _) as construction) ->
      Runtime_construction.refresh construction
    | Some (Initial _) | None -> Ok ()
  in
  refresh_execution_descendant t execution
;;

(* The supplied key selects an existing physical execution only. The actual
   mailbox operation still validates that owner and its current effect rights;
   an unmatched/ordinary key gains no startup authority from this refresh. *)
let refresh_held_background_owner t = function
  | Agent_protocol.Job.Moderator_event id ->
    (match t.queued_event_borrow with
     | Some borrow
       when Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id ->
       refresh_held_execution t (Inference_event borrow)
     | None | Some _ -> Ok ())
  | Invocation id ->
    (match
       List.find t.invocation_executions ~f:(fun execution ->
         Agent_protocol.Id.Invocation.equal id execution.dispatched.context.id)
     with
     | Some execution -> refresh_held_execution t (Inference_invocation execution)
     | None ->
       (match t.moderator_borrow with
        | Some borrow
          when Agent_protocol.Id.Invocation.equal id borrow.invocation.context.id ->
          refresh_held_execution t (Inference_moderator borrow)
        | None | Some _ -> Ok ()))
;;

let model_job_port t execution =
  Model_job_admission.Host.create ~admit:(fun job ->
    let%bind.Result () = refresh_held_execution t execution in
    Eio.Cancel.protect (fun () -> call t (Admit_model_job (execution, job))))
;;

(* Selected only at fresh-effect writers. Negative results carrying the SAME
   preparation do not enter this authorization stage. *)
let held_startup_effect t preparation =
  let authored =
    Option.bind t.held_authored_start ~f:(fun scope ->
      let activation = Admitted_activation.Continuation.target scope.continuation in
      if Option.exists preparation ~f:(phys_equal activation.preparation)
      then
        Some
          (fun () ->
            let open Result.Let_syntax in
            let%bind () = held_authored_basis t scope in
            let%bind () = check_held_effect scope.continuation in
            held_authored_basis t scope)
      else None)
  in
  match authored with
  | Some _ -> authored
  | None ->
    Option.bind t.initialization_scope ~f:(fun scope ->
      Option.bind
        (Initialization_scope_data.initial_continuation scope)
        ~f:(fun continuation ->
          let activation = Admitted_activation.Continuation.target continuation in
          if Option.exists preparation ~f:(phys_equal activation.preparation)
          then
            Some
              (fun () ->
                let open Result.Let_syntax in
                let%bind () = check_held_effect continuation in
                if
                  Option.exists t.initialization_scope ~f:(phys_equal scope)
                  && Option.exists t.held_activation ~f:(phys_equal activation)
                then
                  Run_preparation.check_basis
                    activation.preparation
                    ~owner:t.run_preparation_owner
                    ~state:t.state
                else Error (error Conflict "held Init effect owner changed"))
          else None))
;;

let close_run_preparation t =
  Option.iter t.held_authored_start ~f:(fun scope ->
    match scope.Held_authored_start.phase with
    | Released -> ()
    | Staged | Starting | Ready | Executing _ | Completed _ | Attempt_unconfirmed | Closed
      -> scope.phase <- Closed);
  Option.iter t.held_input_scope ~f:(fun scope -> scope.Held_input_scope.phase <- Closed);
  Option.iter t.held_activation ~f:Held_run.Activation.close;
  (* Closed startup disposition survives a failed factual retirement ACK. It
     cannot authorize effects; the exact retained Run is still pending retirement. *)
  t.held_activation
  <- Option.filter t.held_activation ~f:(fun activation ->
       Option.exists t.state.run_state ~f:(fun index ->
         Option.exists (Run_state.find index activation.run.id) ~f:(fun run ->
           match run.Agent_protocol.Run.lifecycle with
           | Admitted | Active | Waiting _ -> true
           | Terminal _ -> false)));
  Option.iter t.run_source_binding ~f:Source_binding.close;
  t.run_source_binding <- None;
  Option.iter t.run_preparation ~f:Preparation_owner.close;
  t.run_preparation <- None
;;

let close_bound_run_preparation t =
  if
    Option.is_some t.run_source_binding
    || Option.is_some t.held_activation
    || Option.exists t.run_preparation ~f:(function
      | Existing_goal _ -> true
      | Initial _ | Delegated_load _ -> false)
  then close_run_preparation t
;;

let pending_initial_startup_run t =
  Option.bind t.held_activation ~f:(fun activation ->
    let retained () =
      let open Result.Let_syntax in
      let%bind () =
        Runtime_source_preparation.validate_target activation.source t.state
      in
      let%bind index =
        Result.of_option
          t.state.run_state
          ~error:(error Conflict "held startup Run index is absent")
      in
      let%bind run =
        Result.of_option
          (Run_state.find index activation.run.id)
          ~error:(error Conflict "held startup Run is absent")
      in
      let%bind admission =
        Run_state.receipt
          index
          ~principal_id:activation.admission.principal_id
          ~key:activation.admission.key
          ~request_sha256:activation.admission.request_sha256
      in
      let%bind () =
        if
          Option.exists
            admission
            ~f:(Agent_protocol.Run_receipt.equal activation.admission)
        then Ok ()
        else Error (error Conflict "held startup Admission changed")
      in
      let%bind () =
        match activation.association.issuer_policy with
        | Recurrence ->
          let%bind origin =
            Result.of_option
              (Run_state.recurrence_origin index run.id)
              ~error:(error Conflict "held startup origin is absent")
          in
          Recurrence_run_origin.validate_run origin ~run ~admission:activation.admission
        | Goal policy ->
          Goal_activation_policy.check_association
            policy
            ~state:t.state
            ~run
            ~admission:activation.admission
      in
      match run.lifecycle with
      | Admitted | Active | Waiting _ -> Ok run
      | Terminal _ -> Error (error Conflict "held startup already terminated")
    in
    match !(activation.Held_run.Activation.phase) with
    | Closed ->
      (* Negative custody only: a failed retirement write must not turn a later
         child ACK into successful completion of input that never started. *)
      Result.ok (retained ())
    | Handed_off _ -> None
    | Reserved | Constructing ->
      let exact_scope =
        match t.initialization_scope with
        | None -> true
        | Some scope ->
          Option.exists
            (Initialization_scope_data.initial_continuation scope)
            ~f:(fun continuation ->
              phys_equal activation (Admitted_activation.Continuation.target continuation))
      in
      if exact_scope && Result.is_ok (activation.owned_basis ())
      then Result.ok (retained ())
      else None)
;;

let pending_held_startup_run t =
  match pending_initial_startup_run t with
  | Some _ as run -> run
  | None ->
    Option.bind t.run_preparation ~f:(function
      | Initial _ | Delegated_load _ -> None
      | Existing_goal preparation ->
        let owns_hold =
          match preparation.runtime_phase with
          | Installed scope | Callback_completed scope ->
            Result.is_ok (goal_runtime_scope_basis t scope)
          | Constructing ->
            Option.exists t.initialization_scope ~f:(fun scope ->
              match Initialization_scope_data.construction scope with
              | Some (Existing_goal continuation) ->
                phys_equal continuation.binding.preparation preparation
              | Some (Initial _ | Delegated_load _) | None -> false)
          | Unclaimed
          | Starting_writer _
          | Starting_acknowledged
          | Running_writer _
          | Handed_off _
          | Retired _
          | Closed -> false
        in
        if owns_hold && Result.is_ok (preparation.registered_basis ())
        then
          Option.bind t.state.run_state ~f:(fun index ->
            Option.filter (Run_state.find index preparation.run.id) ~f:(fun run ->
              match run.Agent_protocol.Run.lifecycle with
              | Admitted | Active | Waiting _ -> true
              | Terminal _ -> false))
        else None)
;;

let initialization_held_run t (scope : Initialization_scope_data.t) =
  if not (Option.exists t.initialization_scope ~f:(phys_equal scope))
  then None
  else (
    match Initialization_scope_data.construction scope with
    | Some (Existing_goal continuation) ->
      let preparation = continuation.Goal_continuation.binding.preparation in
      if Result.is_ok (preparation.basis ())
      then
        Option.bind t.state.run_state ~f:(fun index ->
          Run_state.find index preparation.run.id)
      else None
    | Some (Initial continuation) ->
      let activation = continuation.Admitted_activation.Continuation.target in
      if Option.exists t.held_activation ~f:(phys_equal activation)
      then (
        match !(activation.phase) with
        | Reserved | Constructing -> pending_held_startup_run t
        | Handed_off _ | Closed -> None)
      else None
    | Some (Delegated_load _) | None -> None)
;;

let held_initialization_of_execution t = function
  | Inference_initialization scope | Inference_initialization_job (scope, _) ->
    Option.map (initialization_held_run t scope) ~f:(fun run -> scope, run)
  | Inference_event borrow ->
    Option.bind t.legacy_callback_scope ~f:(fun callback ->
      if phys_equal callback.borrow borrow
      then
        Option.bind callback.constructor_scope ~f:(fun scope ->
          Option.map (initialization_held_run t scope) ~f:(fun run -> scope, run))
      else None)
  | Inference_invocation execution ->
    (match execution.owner with
     | Event_moderator borrow ->
       Option.bind t.legacy_callback_scope ~f:(fun callback ->
         if phys_equal callback.borrow borrow
         then
           Option.bind callback.constructor_scope ~f:(fun scope ->
             Option.map (initialization_held_run t scope) ~f:(fun run -> scope, run))
         else None)
     | Foreground _ | Background_job _ | Invocation_moderator _ -> None)
  | Inference_held_input _
  | Inference_operation _
  | Inference_moderator _
  | Inference_job _ -> None
;;

let check_registered_run_preparation t preparation =
  match t.run_preparation with
  | Some (Initial active) when phys_equal active preparation ->
    Run_preparation.check preparation ~owner:t.run_preparation_owner ~state:t.state
  | Some _ | None ->
    Error (error Conflict "run preparation is not this actor's live admission")
;;

let check_run_preparation t preparation =
  let open Result.Let_syntax in
  let%bind () = check_retry_execution t preparation in
  check_registered_run_preparation t preparation
;;

let install_live_run_agent_custody t =
  match t.operation_agent_custody, t.state.active_operation, t.state.run_state with
  | None, Some operation, Some index
    when match operation.state with
         | Starting | Running -> true
         | Cancelling | Completed | Failed _ | Cancelled | Interrupted _ -> false ->
    let owners =
      List.filter (Run_state.runs index) ~f:(fun run ->
        List.exists run.owned_work ~f:(fun work ->
          Int.equal work.Agent_protocol.Run_work.generation operation.generation
          &&
          match work.key with
          | Operation id -> Agent_protocol.Id.Operation.equal operation.id id
          | Retained _ -> false))
    in
    (match owners with
     | [ run ] ->
       Option.iter (Run_authorities.find t.run_authorities run.id) ~f:(fun binding ->
         Option.iter
           (Run_admission.Scope.original_actor (Run_authorities.scope binding))
           ~f:(fun actor ->
             let completion =
               match t.operation_completion with
               | Some completion when Operation_completion.matches completion ~operation
                 -> completion
               | None ->
                 Operation_completion.create
                   ~issuer:t.initialization_owner
                   ~domain:t.runtime_source_domain
                   ~operation
               | Some _ ->
                 invalid_arg "live Run completion differs from committed operation"
             in
             t.operation_agent_custody
             <- Some
                  { Operation_owner.operation_id = operation.id
                  ; admission = create_agent_admission (Some (create_agent_custody actor))
                  ; held = None
                  ; descendant_guard = None
                  ; completion
                  };
             t.operation_completion <- Some completion))
     | [] | _ :: _ :: _ -> ())
  | Some _, _, _ | None, None, _ | None, Some _, (Some _ | None) -> ()
;;

let close_recurrence_activations t =
  List.iter t.recurrence_activations ~f:Activation_custody.close;
  t.recurrence_activations <- []
;;

let retain_recurrence_activations t state =
  t.recurrence_activations
  <- Activation_custody.retain_candidates t.recurrence_activations state
;;

let retain_goal_activation_owners t ~retained =
  Option.iter t.held_activation ~f:(fun activation ->
    if not (retained activation.Held_run.Activation.association)
    then Held_run.Activation.close activation);
  Option.iter t.operation_agent_custody ~f:(fun owner ->
    Option.iter owner.Operation_owner.held ~f:(fun held ->
      match held.Held_operation.phase with
      | Staged | Pending_first_effect ->
        if not (retained held.proof.controller.association)
        then Held_operation.retire held
      | Started | Retired -> ()))
;;

let retire_goal_activation t goal_id =
  List.iter t.descendant_policy_cells ~f:(fun policy ->
    if Agent_protocol.Id.Goal.equal (Goal_root_policy.goal_id policy) goal_id
    then Goal_root_policy.retire policy);
  retain_goal_activation_owners t ~retained:(fun association ->
    match association.Activation_association.issuer_policy with
    | Recurrence -> true
    | Goal policy ->
      not (Agent_protocol.Id.Goal.equal (Goal_activation_policy.goal_id policy) goal_id));
  Option.iter t.run_preparation ~f:(function
    | Existing_goal preparation ->
      if
        Agent_protocol.Id.Goal.equal
          (Goal_activation_policy.goal_id preparation.policy)
          goal_id
      then Goal_continuation.close preparation
    | Initial _ | Delegated_load _ -> ())
;;

let retain_goal_activations ?admission_hold t (current : Session_state.t) =
  List.iter t.descendant_policy_cells ~f:(fun policy ->
    Goal_root_policy.retain_candidate
      policy
      ~previous:t.state
      ~candidate:current
      ~admission_hold);
  let goal_state state id =
    Option.bind state.Session_state.goal_catalog ~f:(fun catalog ->
      Option.map (Goal_catalog.find catalog id) ~f:Agent_protocol.Goal.state)
  in
  retain_goal_activation_owners t ~retained:(fun association ->
    match association.Activation_association.issuer_policy with
    | Recurrence -> true
    | Goal policy ->
      let id = Goal_activation_policy.goal_id policy in
      Result.is_ok (Goal_activation_policy.check_policy policy ~state:current)
      || ((Option.exists admission_hold ~f:(Agent_protocol.Id.Goal.equal id)
           || Option.equal
                Agent_protocol.Goal.State.equal
                (goal_state t.state id)
                (goal_state current id))
          && Result.is_ok
               (Goal_activation_policy.check_admitted_policy policy ~state:t.state)
          && Result.is_ok
               (Goal_activation_policy.check_admitted_policy policy ~state:current)));
  Option.iter t.run_preparation ~f:(function
    | Initial _ | Delegated_load _ -> ()
    | Existing_goal preparation ->
      let id = Goal_activation_policy.goal_id preparation.policy in
      let compatible =
        Result.is_ok
          (Goal_activation_policy.check_admitted_policy preparation.policy ~state:current)
        && Option.exists current.run_state ~f:(fun index ->
          Option.exists (Run_state.find index preparation.run.id) ~f:(fun run ->
            (match run.Agent_protocol.Run.lifecycle with
             | Admitted | Active | Waiting _ -> true
             | Terminal _ -> false)
            && Result.is_ok
                 (Goal_activation_policy.check_association
                    preparation.policy
                    ~state:current
                    ~run
                    ~admission:preparation.admission)
            && Result.is_ok
                 (let open Result.Let_syntax in
                  let%bind captured_index, source =
                    Moderator_source_installation.capture current
                  in
                  if
                    Run_state.equal captured_index index
                    && Agent_protocol.Run_source.equal source preparation.run.source
                  then Ok ()
                  else Error (error Conflict "Goal resume source candidate changed"))))
      in
      let retained =
        compatible
        &&
        match preparation.phase with
        | Preparing | Source_bound _ | Writer_pending _ -> true
        | Ready _ | Execution_ready _ ->
          Result.is_ok
            (Goal_activation_policy.check_policy preparation.policy ~state:current)
          || Option.exists admission_hold ~f:(Agent_protocol.Id.Goal.equal id)
          || Option.equal
               Agent_protocol.Goal.State.equal
               (goal_state t.state id)
               (goal_state current id)
        | Waiting _ | Closed _ -> false
      in
      if not retained then Goal_continuation.close preparation)
;;

let invalidate_goal_inference_allocations t goal_id =
  List.iter t.inference_owners ~f:(fun custody ->
    let owner = Inference_graph_custody.owner custody in
    Graph_owner.iter_registrations owner ~f:(fun registration ->
      if
        Option.exists
          (Inference_owner.Registration.goal_id registration)
          ~f:(Agent_protocol.Id.Goal.equal goal_id)
      then Inference_owner.Registration.invalidate_policy registration))
;;

let invalidate_goal_inference_policy ?admission_hold t (current : Session_state.t) =
  let goal state id =
    Option.bind state.Session_state.goal_catalog ~f:(fun catalog ->
      Goal_catalog.find catalog id)
  in
  List.iter t.inference_owners ~f:(fun custody ->
    let owner = Inference_graph_custody.owner custody in
    Graph_owner.iter_registrations owner ~f:(fun registration ->
      Option.iter (Inference_owner.Registration.goal_id registration) ~f:(fun id ->
        let changed =
          match goal t.state id, goal current id with
          | Some before, Some after ->
            (not (Goal_admission_policy.same_allocation_policy before after))
            || ((not (Option.exists admission_hold ~f:(Agent_protocol.Id.Goal.equal id)))
                && not
                     (Agent_protocol.Goal.State.equal
                        (Agent_protocol.Goal.state before)
                        (Agent_protocol.Goal.state after)))
          | None, _ | _, None -> true
        in
        if changed then Inference_owner.Registration.invalidate_policy registration)))
;;

(* Stop retires only the actual constructor callback already held by this actor.
   This is factual terminal DATA, not an initialization acknowledgement or an
   assertion that an external native effect was rolled back. *)
module Constructor_stop_acknowledgement = struct
  type actor = t

  module Child = struct
    type t =
      { execution : invocation_execution
      ; previous : Agent_protocol.Invocation.t
      ; cancelled : Agent_protocol.Invocation.t option
      }
  end

  type t =
    { constructor : Initialization_scope_data.t
    ; callback : Callback_scope.t
    ; borrow : queued_event_borrow
    ; previous : Agent_protocol.Moderator_execution.t
    ; interrupted : Agent_protocol.Moderator_execution.t
    ; children : Child.t list
    ; previous_executions : invocation_execution list
    ; revision : int64
    }

  let owned_children (actor : actor) borrow =
    List.filter actor.invocation_executions ~f:(fun execution ->
      match execution.owner with
      | Event_moderator owner -> phys_equal owner borrow
      | Foreground _ | Invocation_moderator _ | Background_job _ -> false)
  ;;

  let check t ~(actor : actor) =
    let open Result.Let_syntax in
    let%bind _, source = Moderator_source_installation.capture actor.state in
    let%bind () =
      if
        phys_equal actor.initialization_owner t.constructor.owner
        && Option.exists actor.initialization_scope ~f:(phys_equal t.constructor)
        && Option.exists actor.legacy_callback_scope ~f:(phys_equal t.callback)
        && Option.exists t.callback.constructor_scope ~f:(phys_equal t.constructor)
        && phys_equal t.callback.borrow t.borrow
        && Option.exists actor.queued_event_borrow ~f:(phys_equal t.borrow)
        && actor.idle_moderator_borrowed
        && phys_equal actor.invocation_executions t.previous_executions
        && (not t.borrow.committed)
        && Option.is_none t.borrow.stop_retirement
        && (match t.constructor.callback with
            | Claimed id ->
              Agent_protocol.Id.Moderator_execution.equal id t.previous.context.id
            | Unclaimed | Settled _ -> false)
        && Agent_protocol.Id.Session.equal
             actor.state.identity.session_id
             t.previous.context.session_id
        && Int.equal actor.state.identity.generation t.previous.context.generation
        && Agent_protocol.Moderator_execution.equal_context
             t.previous.context
             t.borrow.receipt.context
        && Agent_protocol.Invocation.equal_observer
             t.previous.context.source
             t.callback.source.observer
        && Agent_protocol.Run_source.equal source t.callback.source
        && List.exists
             actor.state.moderator_executions
             ~f:(Agent_protocol.Moderator_execution.equal t.previous)
        && List.equal
             phys_equal
             (owned_children actor t.borrow)
             (List.map t.children ~f:(fun child -> child.Child.execution))
        && Int64.equal actor.state.counters.revision t.revision
      then Ok ()
      else Error (error Conflict "constructor Stop no longer owns its exact receipt")
    in
    if
      List.for_all t.children ~f:(fun child ->
        Agent_protocol.Invocation.equal_context
          child.Child.previous.context
          child.execution.dispatched.context
        && Option.equal
             Agent_protocol.Id.Moderator_execution.equal
             child.previous.parent_event
             child.execution.dispatched.parent_event
        && List.exists
             actor.state.invocations
             ~f:(Agent_protocol.Invocation.equal child.previous))
    then Ok ()
    else Error (error Conflict "constructor Stop native outcome changed before commit")
  ;;

  let prepare (actor : actor) =
    let open Result.Let_syntax in
    match
      actor.initialization_scope, actor.legacy_callback_scope, actor.queued_event_borrow
    with
    | Some constructor, Some callback, Some borrow
      when Option.exists callback.constructor_scope ~f:(phys_equal constructor)
           && phys_equal callback.borrow borrow
           && (not borrow.committed)
           && Option.is_none borrow.stop_retirement ->
      let%bind previous =
        List.find actor.state.moderator_executions ~f:(fun receipt ->
          Agent_protocol.Id.Moderator_execution.equal
            receipt.context.id
            borrow.receipt.context.id)
        |> Result.of_option
             ~error:(error Conflict "constructor Stop receipt is unavailable")
      in
      (match previous.status with
       | Completed _ | Failed _ | Interrupted _ -> Ok None
       | Running ->
         let%bind interrupted =
           Agent_protocol.Moderator_execution.interrupt
             previous
             ~reason:"constructor retired by Stop before checkpoint acknowledgement"
         in
         let%bind children =
           owned_children actor borrow
           |> List.map ~f:(fun execution ->
             let%bind previous =
               List.find actor.state.invocations ~f:(fun invocation ->
                 Agent_protocol.Id.Invocation.equal
                   invocation.context.id
                   execution.dispatched.context.id)
               |> Result.of_option
                    ~error:(error Conflict "constructor Stop native row is unavailable")
             in
             let%map cancelled =
               match previous.status with
               | Resolved _ | Published _ -> Ok None
               | Admitted | Dispatching ->
                 Agent_protocol.Invocation.cancel
                   previous
                   ~reason:
                     "constructor retired by Stop before native result acknowledgement"
                 |> Result.map ~f:Option.some
             in
             { Child.execution; previous; cancelled })
           |> Result.all
         in
         let acknowledgement =
           { constructor
           ; callback
           ; borrow
           ; previous
           ; interrupted
           ; children
           ; previous_executions = actor.invocation_executions
           ; revision = actor.state.counters.revision
           }
         in
         let%map () = check acknowledgement ~actor in
         Some acknowledgement)
    | (Some _ | None), (Some _ | None), (Some _ | None) -> Ok None
  ;;

  let deltas t =
    List.filter_map t.children ~f:(fun child ->
      Option.map child.Child.cancelled ~f:(fun invocation ->
        Session_delta.Invocation_changed invocation))
    @ [ Session_delta.Moderator_execution_changed t.interrupted ]
  ;;

  let install t ~(actor : actor) =
    (* Already validated before the sole writer. Assignment/retirement only;
       never mark a stopped callback as a successful Manager checkpoint. *)
    t.borrow.stop_retirement <- Some t.interrupted;
    t.borrow.callback_active <- false;
    Atomic.set t.borrow.authority_live false;
    List.iter t.children ~f:(fun child ->
      child.Child.execution.accepts_children <- false;
      Atomic.set child.execution.authority_live false);
    (* Keep these exact closed execution cells until the existing callback unwind
       aborts their Invocation-owned provisional work and releases the borrow.
       Graceful Stop does not synchronously cancel the external call. The unwind
       never persists another outcome after [stop_retirement]. *)
    t.constructor.callback <- Settled t.interrupted.context.id;
    retire_agent_admission t.constructor.agent_admission;
    (match t.callback.custody with
     | Unavailable -> ()
     | Admitted admission -> retire_agent_admission admission);
    actor.initialization_scope <- None
  ;;
end

module Inherited_turn_acknowledgement = struct
  type actor = t

  type 'outcome plan =
    { acknowledged : 'outcome Inherited_turn.Acknowledged.t
    ; acknowledged_phase : 'outcome Inherited_turn.phase
    ; retained : Inherited_turn.cleanup option
    ; operation_custody : Operation_owner.t option
    ; operation_completion : Operation_completion.t option
    ; run_authorities : Run_authorities.t option
    }

  type t = Pack : 'outcome plan -> t

  let prepare (acknowledged : _ Inherited_turn.Acknowledged.t) =
    Pack
      { acknowledged
      ; acknowledged_phase = Acknowledged acknowledged
      ; retained = Some (Inherited_turn.Pack acknowledged)
      ; operation_custody = Some acknowledged.owner
      ; operation_completion = Some acknowledged.owner.completion
      ; run_authorities =
          Option.map
            (Inherited_turn.Source.run acknowledged.plan.source)
            ~f:(fun source -> source.authorities)
      }
  ;;

  let check (Pack { acknowledged; _ }) ~(actor : actor) ~candidate =
    let plan = acknowledged.Inherited_turn.plan in
    match plan.phase with
    | Writer_prepared actual
      when phys_equal actual acknowledged
           && phys_equal actor.state plan.before
           && phys_equal candidate acknowledged.native.candidate
           && Option.exists actor.inherited_turn_prepared ~f:(fun (Prepared prepared) ->
             phys_equal prepared.native acknowledged.native
             && phys_equal prepared.plan.slot plan.slot)
           && Option.is_none actor.inherited_turn_cleanup ->
      (match Inherited_turn.Source.run plan.source with
       | None -> Ok ()
       | Some source ->
         let run = Run_admission.run source.admission in
         if
           phys_equal actor.run_authorities source.previous_authorities
           && Run_authorities.is_current source.authorities source.binding ~run_id:run.id
           && Option.exists candidate.state.run_state ~f:(fun index ->
             Option.exists (Run_state.find index run.id) ~f:(Agent_protocol.Run.equal run))
         then Ok ()
         else Error (error Conflict "inherited Run authority ACK changed before writer"))
    | Pending | Writer_prepared _ | Acknowledged _ | Closed ->
      Error (error Conflict "native inherited Turn ACK plan changed before writer")
  ;;

  let install
        (Pack
           { acknowledged
           ; acknowledged_phase
           ; retained
           ; operation_custody
           ; operation_completion
           ; run_authorities
           })
        ~(actor : actor)
    =
    Option.iter actor.operation_agent_custody ~f:Operation_owner.retire;
    actor.operation_agent_custody <- operation_custody;
    actor.operation_completion <- operation_completion;
    (* Retain every actual ACK until the exact confirmed suffix handoff. The
       direct caller is not a runtime lease; source retirement must discover
       this same Starting ACK even if its caller is still waiting. *)
    actor.inherited_turn_cleanup <- retained;
    actor.inherited_turn_prepared <- None;
    Option.iter run_authorities ~f:(fun authorities ->
      actor.run_authorities <- authorities);
    acknowledged.plan.phase <- acknowledged_phase;
    (* Exact Run binding is installed before constructor custody closes. The
       worker consumes that binding, never the preparation's mutable tracker. *)
    Option.iter (Inherited_turn.Source.run acknowledged.plan.source) ~f:(fun source ->
      Option.iter source.preparation_exit ~f:(fun exit ->
        Run_preparation.Admission_exit.close exit ~owner:actor.run_preparation_owner);
      match source.preparation, actor.run_preparation with
      | Some preparation, Some (Initial active) when phys_equal preparation active ->
        actor.run_preparation <- None
      | (Some _ | None), (Some _ | None) -> ());
    (match acknowledged.plan.source with
     | Held_input source ->
       Run_preparation.Admission_exit.close
         source.preparation_exit
         ~owner:actor.run_preparation_owner;
       (match actor.run_preparation with
        | Some (Initial actual)
          when phys_equal
                 actual
                 (Admitted_activation.Continuation.target
                    source.selection.scope.continuation)
                   .preparation -> actor.run_preparation <- None
        | Some _ | None -> ())
     | Message _
     | Managed _
     | Run_user _
     | History _
     | Goal_resume _
     | Goal_subscription _
     | Idle _ -> ());
    match acknowledged.plan.cancellation with
    | Not_requested -> ()
    | Requested _ ->
      (* Failure to fork cannot abandon the retained genuine delayed ACK. *)
      Operation_descendant_guard.retire acknowledged.guard;
      (try
         ignore
           (schedule_inherited_turn_cleanup actor acknowledged
            : ( (unit, Agent_protocol.Error.t) result Eio.Promise.t
                , Agent_protocol.Error.t )
                result)
       with
       | exn ->
         (try
            Eio.traceln "delayed inherited Turn ACK cleanup: %s" (Exn.to_string exn)
          with
          | _ -> ()))
  ;;
end

module Held_authored_acknowledgement = struct
  type actor = t

  type t =
    { previous : Session_state.t
    ; previous_authorities : Run_authorities.t
    ; candidate : Session_transition.t
    ; scope : Held_authored_start.t
    ; authorities : Run_authorities.t
    ; pending : lifecycle_agent_custody option
    ; mutable installed : bool
    }

  let check t ~(actor : actor) ~candidate =
    let open Result.Let_syntax in
    let%bind () =
      Authored_run_acknowledgement.require_unadmitted actor.lifecycle_agent_custody
    in
    if
      (not t.installed)
      && phys_equal t.previous actor.state
      && phys_equal t.previous_authorities actor.run_authorities
      && phys_equal t.candidate candidate
      && Option.is_none actor.held_authored_start
      && (match t.scope.phase with
          | Staged -> true
          | _ -> false)
      && Option.exists
           actor.operation_worker
           ~f:(phys_equal (Runtime_builder.Authored_start.worker t.scope.startup))
      && Option.equal
           phys_equal
           actor.moderator_manager
           (Runtime_builder.Authored_start.manager t.scope.startup)
    then Ok ()
    else Error (error Conflict "held authored first acknowledgement changed")
  ;;

  let install t ~(actor : actor) =
    t.installed <- true;
    actor.run_authorities <- t.authorities;
    Option.iter t.pending ~f:(fun pending -> actor.lifecycle_agent_custody <- pending);
    actor.held_authored_start <- Some t.scope;
    t.scope.phase <- Starting;
    Failed_startup_data.Authored.acknowledge_lifecycle t.scope.cleanup;
    (Admitted_activation.Continuation.target t.scope.continuation).phase := Constructing
  ;;

  let discard t =
    if not t.installed
    then
      Option.iter t.pending ~f:(function
        | Admitted { pending = Pending admission; _ }
        | Admitted { pending = Initial_pending { admission; _ }; _ } ->
          retire_agent_admission admission
        | Unadmitted | Admitted { pending = Consumed; _ } -> ())
  ;;
end

(* An owned Job result may change this callback's Run while its Event remains
   executing. Extend only that physical callback at the same acknowledged fact;
   a retained Run revision alone cannot renew or reconstruct a callback. *)
module Held_authored_callback_acknowledgement = struct
  type actor = t

  type t =
    { previous : Session_state.t
    ; candidate : Session_transition.t
    ; scope : Held_authored_start.t
    ; borrow : queued_event_borrow
    ; actions : Run_action_service.t
    ; previous_run : Agent_protocol.Run.t
    ; advance : Run_scope.Host.advance
    }

  let check t ~(actor : actor) ~candidate =
    let callback = Run_action_service.scope t.actions in
    if
      phys_equal t.previous actor.state
      && phys_equal t.candidate candidate
      && phys_equal t.scope.issuing_actor actor.inference_owner_identity
      && Option.exists actor.held_authored_start ~f:(phys_equal t.scope)
      && Option.exists actor.queued_event_borrow ~f:(phys_equal t.borrow)
      && Option.exists
           (Option.bind t.borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial)
           ~f:(phys_equal t.scope)
      && Option.exists t.borrow.run_actions ~f:(phys_equal t.actions)
      && t.borrow.callback_active
      && (not t.borrow.committed)
      && (match t.scope.phase with
          | Executing id ->
            Agent_protocol.Id.Moderator_execution.equal id t.borrow.receipt.context.id
          | Staged
          | Starting
          | Ready
          | Completed _
          | Released
          | Attempt_unconfirmed
          | Closed -> false)
      && Run_scope.is_open callback
      && Int64.equal (Run_scope.revision callback) t.previous_run.revision
    then Ok ()
    else Error (error Conflict "held callback fact acknowledgement changed")
  ;;

  let prepare (actor : actor) (scope : Held_authored_start.t) ~candidate =
    let open Result.Let_syntax in
    match scope.phase, actor.queued_event_borrow with
    | Executing id, Some borrow
      when Option.exists
             (Option.bind borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial)
             ~f:(phys_equal scope)
           && Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
           && borrow.callback_active
           && not borrow.committed ->
      (match borrow.run_actions with
       | None -> Ok None
       | Some actions ->
         let run_id = Run_scope.run_id (Run_action_service.scope actions) in
         let find state =
           Option.bind state.Session_state.run_state ~f:(fun index ->
             Run_state.find index run_id)
           |> Result.of_option
                ~error:(error Conflict "held callback fact has no retained Run")
         in
         let%bind previous_run = find actor.state in
         let%bind next = find candidate.Session_transition.state in
         if Agent_protocol.Run.equal previous_run next
         then Ok None
         else (
           let%bind advance =
             Run_scope.Host.prepare_advance
               (Run_action_service.scope actions)
               ~previous:previous_run
               ~next
               ~execution_id:borrow.receipt.context.id
           in
           let acknowledgement =
             { previous = actor.state
             ; candidate
             ; scope
             ; borrow
             ; actions
             ; previous_run
             ; advance
             }
           in
           let%map () = check acknowledgement ~actor ~candidate in
           Some acknowledgement))
    | ( ( Staged
        | Starting
        | Ready
        | Executing _
        | Completed _
        | Released
        | Attempt_unconfirmed
        | Closed )
      , (None | Some _) ) -> Ok None
  ;;

  let install t = Run_scope.Host.acknowledge_advance t.advance
end

(* A producer ACK can settle work while its actual callback remains Running.
   This bookkeeping extends only that same physical callback, never a retained
   ID, source replacement, terminal retirement or a newly admitted effect. *)
module Producer_callback_acknowledgement = struct
  type actor = t

  type t =
    { previous : Session_state.t
    ; candidate : Session_transition.t
    ; borrow : queued_event_borrow
    ; actions : Run_action_service.t
    ; previous_run : Agent_protocol.Run.t
    ; advance : Run_scope.Host.advance
    }

  let check t ~(actor : actor) ~candidate =
    if
      phys_equal t.previous actor.state
      && phys_equal t.candidate candidate
      && Option.exists actor.queued_event_borrow ~f:(phys_equal t.borrow)
      && Option.exists t.borrow.run_actions ~f:(phys_equal t.actions)
      && t.borrow.callback_active
      && (not t.borrow.committed)
      && Run_scope.is_open (Run_action_service.scope t.actions)
      && Int64.equal
           (Run_scope.revision (Run_action_service.scope t.actions))
           t.previous_run.revision
    then Ok ()
    else Error (error Conflict "producer callback fact acknowledgement changed")
  ;;

  let prepare (actor : actor) ~candidate =
    let open Result.Let_syntax in
    match actor.queued_event_borrow with
    | Some borrow when borrow.callback_active && not borrow.committed ->
      (match borrow.run_actions with
       | None -> Ok None
       | Some actions ->
         let scope = Run_action_service.scope actions in
         let find state =
           Option.bind state.Session_state.run_state ~f:(fun index ->
             Run_state.find index (Run_scope.run_id scope))
         in
         (match find actor.state, find candidate.Session_transition.state with
          | Some previous_run, Some next
            when not (Agent_protocol.Run.equal previous_run next) ->
            (match next.lifecycle with
             | Terminal _ -> Ok None
             | Admitted | Active | Waiting _ ->
               let%bind _, proofs =
                 Run_producer_settlement.capture
                   actor.state
                   ~delta:candidate.delta
                   ~run:previous_run
                   ~owned_work:next.owned_work
               in
               if List.is_empty proofs
               then Ok None
               else (
                 let%bind advance =
                   Run_scope.Host.prepare_advance
                     scope
                     ~previous:previous_run
                     ~next
                     ~execution_id:borrow.receipt.context.id
                 in
                 let acknowledgement =
                   { previous = actor.state
                   ; candidate
                   ; borrow
                   ; actions
                   ; previous_run
                   ; advance
                   }
                 in
                 let%map () = check acknowledgement ~actor ~candidate in
                 Some acknowledgement))
          | (Some _ | None), (Some _ | None) -> Ok None))
    | None | Some _ -> Ok None
  ;;

  let install t = Run_scope.Host.acknowledge_advance t.advance
end

(* A single acknowledged candidate advances the exact runtime callback owner.
   This is staged DATA; only installation after the real writer changes custody. *)
module Goal_runtime_acknowledgement = struct
  type actor = t

  type t =
    { previous : Session_state.t
    ; candidate : Session_transition.t
    ; scope : Goal_continuation.runtime_scope
    ; jobs : Agent_protocol.Job.t list
    ; callback_advance : Run_scope.Host.advance option
    }

  let check t ~(actor : actor) ~candidate =
    let open Result.Let_syntax in
    let%bind () = goal_runtime_scope_basis actor t.scope in
    if phys_equal t.previous actor.state && phys_equal t.candidate candidate
    then Ok ()
    else Error (error Conflict "Goal runtime acknowledgement candidate changed")
  ;;

  let prepare_callback_advance (actor : actor) scope ~candidate =
    match actor.queued_event_borrow with
    | Some borrow
      when Option.exists (goal_runtime_of_borrow borrow) ~f:(phys_equal scope)
           && borrow.callback_active
           && not borrow.committed ->
      (match borrow.run_actions with
       | None -> Ok None
       | Some actions ->
         let find state =
           Option.bind state.Session_state.run_state ~f:(fun index ->
             Run_state.find
               index
               scope.Goal_continuation.continuation.binding.preparation.run.id)
         in
         (match find actor.state, find candidate.Session_transition.state with
          | Some previous, Some next when not (Agent_protocol.Run.equal previous next) ->
            (match next.lifecycle with
             | Terminal _ -> Ok None
             | Admitted | Active | Waiting _ ->
               Run_scope.Host.prepare_advance
                 (Run_action_service.scope actions)
                 ~previous
                 ~next
                 ~execution_id:borrow.receipt.context.id
               |> Result.map ~f:Option.some)
          | _ -> Ok None))
    | None | Some _ -> Ok None
  ;;

  let prepare_after_basis (actor : actor) scope ~candidate ~callback_advance =
    let rec jobs = function
      | Session_delta.Batch deltas -> List.concat_map deltas ~f:jobs
      | Job_changed job -> [ job ]
      | _ -> []
    in
    Ok
      { previous = actor.state
      ; candidate
      ; scope
      ; jobs = jobs candidate.delta
      ; callback_advance
      }
  ;;

  let prepare (actor : actor) scope ~candidate =
    let open Result.Let_syntax in
    let%bind () = goal_runtime_scope_basis actor scope in
    let%bind callback_advance = prepare_callback_advance actor scope ~candidate in
    prepare_after_basis actor scope ~candidate ~callback_advance
  ;;

  let factual_scope_basis (actor : actor) (scope : Goal_continuation.runtime_scope) ~owner
    =
    let preparation = scope.continuation.binding.preparation in
    if
      Int.equal preparation.domain (Stdlib.Domain.self () :> int)
      && phys_equal scope.issuing_actor actor.inference_owner_identity
      && Run_preparation.Custody.belongs_to
           (Goal_continuation.custody preparation)
           ~owner:actor.run_preparation_owner
      && List.mem scope.graphs owner ~equal:phys_equal
      && owns_inference_graph actor owner
      && phys_equal actor.inference_owner_identity (Graph_owner.issuing_actor owner)
    then Ok ()
    else Error (error Conflict "factual Goal callback belongs to another actual graph")
  ;;

  let prepare_factual (actor : actor) scope ~owner ~candidate =
    let open Result.Let_syntax in
    let%bind () = factual_scope_basis actor scope ~owner in
    let%bind callback_advance =
      match actor.queued_event_borrow with
      | Some borrow
        when Option.exists (goal_runtime_of_borrow borrow) ~f:(phys_equal scope) ->
        (match borrow.run_actions with
         | Some actions when not (Run_scope.is_open (Run_action_service.scope actions)) ->
           Ok None
         | Some _ | None -> prepare_callback_advance actor scope ~candidate)
      | Some _ | None -> prepare_callback_advance actor scope ~candidate
    in
    prepare_after_basis actor scope ~candidate ~callback_advance
  ;;

  let check_factual t ~(actor : actor) ~owner ~candidate =
    let%bind.Result () = factual_scope_basis actor t.scope ~owner in
    if phys_equal t.previous actor.state && phys_equal t.candidate candidate
    then Ok ()
    else Error (error Conflict "factual Goal callback candidate changed")
  ;;

  let install t =
    t.scope.jobs <- t.jobs @ t.scope.jobs;
    Option.iter t.callback_advance ~f:(fun advance ->
      match Run_scope.Host.acknowledge_advance advance with
      | Ok () -> ()
      | Error error ->
        raise_s
          [%message
            "acknowledged Goal callback advance lost its exact basis"
              (error : Agent_protocol.Error.t)]);
    match t.scope.callback with
    | Executing id ->
      Option.iter
        (List.find t.candidate.state.moderator_executions ~f:(fun receipt ->
           Agent_protocol.Id.Moderator_execution.equal receipt.context.id id))
        ~f:(fun receipt ->
          match receipt.status with
          | Completed _ -> t.scope.callback <- Completed id
          | Running | Failed _ | Interrupted _ -> ())
    | Pending | Completed _ | Joined -> ()
  ;;
end

module Held_operation_acknowledgement = struct
  type actor = t

  type t =
    { input_scope : Held_input_scope.t
    ; input : Runtime_input_preparation.Prepared_input.t
    ; preparation_exit : Run_preparation.Admission_exit.t option
    ; activation : Held_run.Activation.t
    ; held : Held_operation.t
    ; owner : Operation_owner.t
    ; completion_slot : Operation_completion.t option
    ; previous : Session_state.t
    ; candidate : Session_transition.t
    }

  let check t ~(actor : actor) ~candidate =
    let open Result.Let_syntax in
    let%bind () =
      if
        phys_equal t.previous actor.state
        && phys_equal t.candidate candidate
        && Option.exists actor.held_input_scope ~f:(phys_equal t.input_scope)
        && Option.exists actor.held_activation ~f:(phys_equal t.activation)
        && Option.is_none actor.operation_agent_custody
      then Ok ()
      else Error (error Conflict "held root acknowledgement owner changed")
    in
    let recorded =
      match t.input_scope.phase, t.preparation_exit with
      | Parsed_ready input, None -> Some input
      | Admission_pending (input, actual), Some expected when phys_equal actual expected
        -> Some input
      | ( ( Parsing
          | Parsed_ready _
          | Admission_pending _
          | Consumed _
          | Root_attempt_unconfirmed
          | Closed )
        , (Some _ | None) ) -> None
    in
    match recorded, t.held.phase with
    | Some input, Staged
      when Runtime_input_preparation.Prepared_input.equal input t.input
           && phys_equal t.held.proof.controller.association t.activation.association
           && Option.exists actor.operation_worker ~f:(phys_equal t.held.proof.worker)
           && Run_authorities.is_current
                actor.run_authorities
                t.held.proof.binding
                ~run_id:t.held.proof.run.id -> Ok ()
    | (Some _ | None), _ ->
      Error (error Conflict "held root input or physical worker changed")
  ;;

  let install t ~(actor : actor) =
    t.held.proof.controller.install ();
    t.held.phase <- Pending_first_effect;
    t.input_scope.phase <- Consumed t.held.proof;
    t.activation.phase := Handed_off (User_root t.held.proof);
    actor.operation_agent_custody <- Some t.owner;
    actor.operation_completion <- t.completion_slot;
    actor.held_input_scope <- None
  ;;
end

module Goal_runtime_operation_acknowledgement = struct
  type actor = t

  type t =
    { previous : Session_state.t
    ; candidate : Session_transition.t
    ; scope : Goal_continuation.runtime_scope
    ; held : Held_operation.t
    ; owner : Operation_owner.t
    ; completion_slot : Operation_completion.t option
    ; handoff : Goal_runtime_handoff.t
    }

  let check t ~(actor : actor) ~candidate =
    let open Result.Let_syntax in
    let%bind () = goal_runtime_scope_basis actor t.scope in
    if
      phys_equal t.previous actor.state
      && phys_equal t.candidate candidate
      && Option.is_none actor.operation_agent_custody
      && Option.is_none actor.state.active_operation
      && (match t.held.phase with
          | Staged -> true
          | _ -> false)
      && (match t.scope.callback with
          | Joined -> true
          | _ -> false)
      && Run_authorities.is_current
           actor.run_authorities
           t.held.proof.binding
           ~run_id:t.held.proof.run.id
    then Ok ()
    else Error (error Conflict "Goal continuation Operation acknowledgement changed")
  ;;

  let install t ~(actor : actor) =
    t.held.proof.controller.install ();
    t.held.phase <- Pending_first_effect;
    actor.operation_agent_custody <- Some t.owner;
    actor.operation_completion <- t.completion_slot;
    t.scope.continuation.binding.preparation.runtime_phase
    <- Handed_off (t.scope, t.handoff);
    match t.handoff with
    | Goal_runtime_handoff.Resume handoff ->
      t.scope.continuation.binding.preparation.resume_outcome <- Some handoff
    | Existing_execution _ -> ()
  ;;
end

module Queue_custody_installation = struct
  type t =
    | Inventory of Legacy_queue_custody.t
    | Delivery_update of Legacy_queue_custody.Update.t
end

module Schedule_custody_installation = struct
  type t =
    | Inventory of Legacy_schedule_custody.t
    | Creators of
        { schedules : Legacy_schedule_custody.Update.t
        ; ingress : Ingress_creator_custody.Update.t
        }
end

(* Only the existing checked configuration writer prepares this factual plan.
   It is affine to the original Binding and exact transition, never a callback
   that can manufacture installation or refresh an old Caller. *)
type unmoderated_configuration_acknowledgement =
  { previous : Session_state.t
  ; candidate : Session_transition.t
  ; original : Runtime_builder.Unmoderated_source.Binding.t
  ; replacement : Runtime_builder.Unmoderated_source.Binding.t
  ; worker : Operation_worker.t
  }

let retain_unmoderated_source t =
  match t.unmoderated_source, t.operation_worker with
  | None, _ -> ()
  | Some binding, Some worker ->
    (match
       Runtime_builder.Unmoderated_source.Binding.check
         binding
         ~state:t.state
         ~worker
         ~manager:t.moderator_manager
     with
     | Ok _ -> ()
     | Error _ -> t.unmoderated_source <- None)
  | Some _, None -> t.unmoderated_source <- None
;;

let check_unmoderated_configuration
      t
      (acknowledgement : unmoderated_configuration_acknowledgement)
      candidate
  =
  let open Result.Let_syntax in
  let%bind () =
    if
      phys_equal acknowledgement.previous t.state
      && phys_equal acknowledgement.candidate candidate
      && Option.exists t.unmoderated_source ~f:(phys_equal acknowledgement.original)
      && Option.exists t.operation_worker ~f:(phys_equal acknowledgement.worker)
    then Ok ()
    else Error (error Conflict "unmoderated configuration lost its exact installation")
  in
  Runtime_builder.Unmoderated_source.Binding.check
    acknowledgement.original
    ~state:t.state
    ~worker:acknowledgement.worker
    ~manager:t.moderator_manager
  |> Result.map ~f:ignore
;;

let install_committed_transition_owned
      ?inherited_attempt_acknowledgement
      ?causal_root_acknowledgement
      ?unmoderated_configuration_acknowledgement
      ?idle_completion_write
      ?inherited_turn_acknowledgement
      ?root_reserve_acknowledgement
      ?root_close_acknowledgement
      ?descendant_admission_acknowledgement
      ?descendant_import_acknowledgement
      ?held_authored_acknowledgement
      ?goal_runtime_acknowledgement
      ?held_operation_acknowledgement
      ?goal_operation_acknowledgement
      ?queued_claim_acknowledgement
      ?authored_run_acknowledgement
      ?queue_custody_installation
      ?schedule_custody_installation
      ?retire_legacy_custody
      ~preparation_owner
      ?job_custody
      ?initialization_acknowledgement
      ?constructor_stop_acknowledgement
      ?admission_hold
      ?(explicit_goal_holds = [])
      t
      (transition : Session_transition.t)
  =
  let inference_changed =
    not
      (Int64.equal
         (Inference_ledger.revision t.state.inference_ledger)
         (Inference_ledger.revision transition.state.inference_ledger))
  in
  let stopping_jobs =
    match t.state.lifecycle.desired, transition.state.lifecycle.desired with
    | Running, Stopped -> true
    | Running, Running | Stopped, Running | Stopped, Stopped -> false
  in
  (match t.run_preparation, preparation_owner with
   | Some active, Some supplied when Preparation_owner.same active supplied ->
     (match
        Preparation_owner.advance
          active
          ~owner:t.run_preparation_owner
          ~previous:t.state
          ~current:transition.state
      with
      | Ok () -> ()
      | Error _ -> close_run_preparation t)
   | Some _, (Some _ | None) -> close_run_preparation t
   | None, (Some _ | None) -> ());
  Option.iter goal_runtime_acknowledgement ~f:Goal_runtime_acknowledgement.install;
  t.command_audit <- None;
  List.iter explicit_goal_holds ~f:(invalidate_goal_inference_allocations t);
  invalidate_goal_inference_policy ?admission_hold t transition.state;
  t.state <- transition.state;
  (* A durable source/Stop/lifecycle change revokes admission, never resource
     custody. The Owner's actual anchor still joins the same physical Product. *)
  (match t.policy_restoration with
   | Vacant -> ()
   | Native_constructing setup ->
     if not (phys_equal setup.expected t.state) then Native_setup_data.close setup
   | Constructing restoration ->
     if
       Result.is_error
         (Policy_restore_basis.check_construction restoration.basis ~state:t.state)
     then Policy_restoration_data.close restoration
   | Published published ->
     if
       Result.is_error
         (Policy_restore_basis.check_policy
            (Runtime_builder.Restored_policy_access.basis published.access)
            ~state:t.state)
     then Policy_restoration_data.Published.close published);
  (match inherited_attempt_acknowledgement with
   | None -> ()
   | Some acknowledgement ->
     (match acknowledgement.causal with
      | None -> ()
      | Some causal -> causal.slot.phase <- causal.next);
     Graph_owner.Prepared_registration.install acknowledgement.registration;
     acknowledgement.plan.acknowledged <- acknowledgement.acknowledged;
     (match acknowledgement.scope with
      | None -> ()
      | Some (Install_authored_graphs (scope, graphs)) -> scope.graphs <- graphs
      | Some (Install_goal_graphs (scope, graphs)) -> scope.graphs <- graphs
      | Some (Install_initialization_graphs (scope, graphs)) -> scope.graphs <- graphs));
  if inference_changed
  then
    List.iter t.inference_owners ~f:(fun custody ->
      let owner = Inference_graph_custody.owner custody in
      Graph_owner.iter_factual_usage owner ~f:(fun facts ->
        Inference_graph_owner.Factual_usage.Host.invalidate
          facts
          ~ledger_revision:(Inference_ledger.revision t.state.inference_ledger)));
  (match causal_root_acknowledgement with
   | None -> ()
   | Some write -> Causal_root_custody.install t write);
  (* Generic ACKs can only retain the SAME basis or clear it. Only the exact
     checked configuration plan installs its prebuilt replacement here, before
     any fallible completion/publication. Unknown writes never reach this suffix. *)
  retain_unmoderated_source t;
  Option.iter unmoderated_configuration_acknowledgement ~f:(fun acknowledgement ->
    t.unmoderated_source <- Some acknowledgement.replacement);
  Option.iter idle_completion_write ~f:(fun owned ->
    install_idle_completion_writer t owned transition);
  (match descendant_admission_acknowledgement with
   | None -> ()
   | Some acknowledgement -> install_descendant_admission_slot_ack t acknowledgement);
  Option.iter
    inherited_turn_acknowledgement
    ~f:(Inherited_turn_acknowledgement.install ~actor:t);
  Option.iter root_reserve_acknowledgement ~f:Root_reserve_acknowledgement.install;
  Option.iter root_close_acknowledgement ~f:Root_close_acknowledgement.install;
  Option.iter
    descendant_import_acknowledgement
    ~f:Descendant_import_acknowledgement.install;
  Option.iter
    held_authored_acknowledgement
    ~f:(Held_authored_acknowledgement.install ~actor:t);
  Option.iter
    held_operation_acknowledgement
    ~f:(Held_operation_acknowledgement.install ~actor:t);
  Option.iter
    goal_operation_acknowledgement
    ~f:(Goal_runtime_operation_acknowledgement.install ~actor:t);
  Option.iter
    constructor_stop_acknowledgement
    ~f:(Constructor_stop_acknowledgement.install ~actor:t);
  Option.iter authored_run_acknowledgement ~f:(fun acknowledgement ->
    let authorities, lifecycle = Authored_run_acknowledgement.install acknowledgement in
    t.run_authorities <- authorities;
    Option.iter lifecycle ~f:(fun lifecycle -> t.lifecycle_agent_custody <- lifecycle));
  Option.iter
    initialization_acknowledgement
    ~f:Initialization_scope_data.Acknowledgement.install;
  Option.iter job_custody ~f:(fun update ->
    t.job_agent_custody <- Job_custody.Update.install update);
  Option.iter queue_custody_installation ~f:(function
    | Queue_custody_installation.Inventory incoming ->
      t.legacy_queue_custody
      <- Legacy_queue_custody.install t.legacy_queue_custody ~incoming
    | Delivery_update update ->
      t.legacy_queue_custody <- Legacy_queue_custody.Update.install update);
  Option.iter schedule_custody_installation ~f:(function
    | Schedule_custody_installation.Inventory incoming ->
      t.legacy_schedule_custody
      <- Legacy_schedule_custody.install t.legacy_schedule_custody ~incoming
    | Creators { schedules; ingress } ->
      t.legacy_schedule_custody <- Legacy_schedule_custody.Update.install schedules;
      t.ingress_creator_custody <- Ingress_creator_custody.Update.install ingress);
  if stopping_jobs
  then (
    Job_custody.retire t.job_agent_custody;
    t.job_agent_custody <- Job_custody.empty);
  (* Explicit Stop also retires loans when already Stopped. An ordinary
     constructor ACK while initially Stopped is not a Stop disposition. *)
  let stopping_legacy_custody =
    match retire_legacy_custody with
    | Some () -> true
    | None -> stopping_jobs
  in
  if stopping_legacy_custody
  then (
    Legacy_queue_custody.retire t.legacy_queue_custody;
    t.legacy_queue_custody <- Legacy_queue_custody.empty;
    Legacy_schedule_custody.retire t.legacy_schedule_custody;
    t.legacy_schedule_custody <- Legacy_schedule_custody.empty;
    Ingress_creator_custody.retire t.ingress_creator_custody;
    t.ingress_creator_custody <- Ingress_creator_custody.empty);
  Recurrence_runtime.retain_committed t.recurrence_runtime t.state;
  t.run_authorities
  <- Run_authorities.retain_current
       t.run_authorities
       ~index:t.state.run_state
       ~generation:t.state.identity.generation;
  retained_agent_custody t;
  install_live_run_agent_custody t;
  Option.iter queued_claim_acknowledgement ~f:(fun acknowledgement ->
    t.legacy_queue_custody
    <- Legacy_queue_custody.install
         t.legacy_queue_custody
         ~incoming:(Queued_claim_acknowledgement.inventory acknowledgement);
    t.queued_event_borrow <- Some (Queued_claim_acknowledgement.install acknowledgement);
    t.idle_moderator_borrowed <- true);
  Atomic.set t.event_sequence t.state.counters.event_sequence;
  List.iter t.inference_owners ~f:(fun custody ->
    let owner = Inference_graph_custody.owner custody in
    Graph_owner.retain_joined owner t.state.inference_ledger)
;;

(* Initial callers retain their typed adapter; the shared ACK installation owns
   exactly one closed preparation family, never two optional mutable owners. *)
let install_committed_transition
      ?inherited_attempt_acknowledgement
      ?causal_root_acknowledgement
      ?unmoderated_configuration_acknowledgement
      ?idle_completion_write
      ?inherited_turn_acknowledgement
      ?root_reserve_acknowledgement
      ?root_close_acknowledgement
      ?descendant_admission_acknowledgement
      ?descendant_import_acknowledgement
      ?held_authored_acknowledgement
      ?goal_runtime_acknowledgement
      ?held_operation_acknowledgement
      ?goal_operation_acknowledgement
      ?queued_claim_acknowledgement
      ?authored_run_acknowledgement
      ?queue_custody_installation
      ?schedule_custody_installation
      ?retire_legacy_custody
      ?run_preparation
      ?job_custody
      ?initialization_acknowledgement
      ?constructor_stop_acknowledgement
      ?admission_hold
      ?(explicit_goal_holds = [])
      t
      transition
  =
  install_committed_transition_owned
    ?inherited_attempt_acknowledgement
    ?causal_root_acknowledgement
    ?unmoderated_configuration_acknowledgement
    ?idle_completion_write
    ?inherited_turn_acknowledgement
    ?root_reserve_acknowledgement
    ?root_close_acknowledgement
    ?descendant_admission_acknowledgement
    ?descendant_import_acknowledgement
    ?held_authored_acknowledgement
    ?goal_runtime_acknowledgement
    ?held_operation_acknowledgement
    ?goal_operation_acknowledgement
    ?queued_claim_acknowledgement
    ?authored_run_acknowledgement
    ?queue_custody_installation
    ?schedule_custody_installation
    ?retire_legacy_custody
    ?job_custody
    ?initialization_acknowledgement
    ?constructor_stop_acknowledgement
    ?admission_hold
    ~explicit_goal_holds
    ~preparation_owner:
      (match goal_runtime_acknowledgement, initialization_acknowledgement with
       | Some acknowledgement, _ ->
         Some
           (Existing_goal
              acknowledgement.Goal_runtime_acknowledgement.scope.continuation.binding
                .preparation)
       | None, Some (acknowledgement : Initialization_scope_data.Acknowledgement.t) ->
         (* This private ACK pins the authentic Init scope and its previous
            projection before the writer. Its same closed owner advances at
            ACK; it cannot substitute whichever constructor is now current. *)
         Initialization_scope_data.preparation_owner acknowledgement.scope
       | None, None ->
         Option.map run_preparation ~f:(fun preparation ->
           Preparation_owner.Initial preparation))
    t
    transition
;;

let publish_committed_transition t (transition : Session_transition.t) =
  sync_extension_clock t;
  publish_durable t transition.events;
  t.services.state_committed t.state transition.events
;;

(* Inspect only the requested typed changes while an eligible negative cell
   remains. Empty claim polls never reach this seam. Source/controller bookkeeping
   and factual terminal/release deltas do not become effects merely by committing. *)
let rec deferred_execution_delta (previous : Session_state.t) (delta : Session_delta.t) =
  match delta with
  | Batch deltas -> List.exists deltas ~f:(deferred_execution_delta previous)
  | Active_operation_changed (Some operation) ->
    not
      (Option.exists previous.active_operation ~f:(fun current ->
         Agent_protocol.Id.Operation.equal current.id operation.id))
  | Job_changed job ->
    (match job.status with
     | Running ->
       not
         (List.exists previous.jobs ~f:(fun current ->
            Agent_protocol.Id.Job.equal current.id job.id
            && Int.equal current.attempt job.attempt
            &&
            match current.status with
            | Running -> true
            | _ -> false))
     | Queued
     | Waiting_permission _
     | Waiting_completion _
     | Succeeded
     | Failed _
     | Cancelled
     | Interrupted _ -> false)
  | Schedule_changed schedule ->
    (match schedule.status with
     | Delivering ->
       not
         (List.exists previous.schedules ~f:(fun current ->
            Agent_protocol.Id.Schedule.equal current.id schedule.id
            &&
            match current.status with
            | Delivering -> true
            | _ -> false))
     | Scheduled | Delivered | Cancelled | Failed _ -> false)
  | Invocation_changed invocation ->
    let prior =
      List.find previous.invocations ~f:(fun current ->
        Agent_protocol.Id.Invocation.equal current.context.id invocation.context.id)
    in
    let dispatching (value : Agent_protocol.Invocation.t) =
      match value.status with
      | Dispatching -> true
      | Admitted | Resolved _ | Published _ -> false
    in
    let observing (value : Agent_protocol.Invocation.t) =
      Option.exists value.observation ~f:(fun observation ->
        match observation.status with
        | Observing -> true
        | Awaiting | Observed | Observation_failed _ -> false)
    in
    (dispatching invocation && not (Option.exists prior ~f:dispatching))
    || (observing invocation && not (Option.exists prior ~f:observing))
  | Moderator_lifecycle_claimed { receipt; _ } | Moderator_execution_changed receipt ->
    (match receipt.status with
     | Running ->
       not
         (List.exists previous.moderator_executions ~f:(fun current ->
            Agent_protocol.Id.Moderator_execution.equal
              current.context.id
              receipt.context.id
            &&
            match current.status with
            | Running -> true
            | _ -> false))
     | Completed _ | Failed _ | Interrupted _ -> false)
  | Created _
  | Lifecycle_changed _
  | Metadata_changed _
  | Organization_changed _
  | Initial_start_consumed
  | Stop_epoch_changed _
  | Parent_stop_epoch_changed _
  | Workspace_changed _
  | Canonical_entries_appended _
  | Canonical_history_replaced _
  | Recovery_window_expired _
  | Recovery_window_enabled _
  | Recovery_effective_prepared _
  | Recovery_effective_attempt_changed _
  | Recovery_summary_compacted _
  | Authoring_references_forgotten _
  | Authoring_publication_changed _
  | Initial_prompt_count_changed _
  | Deferred_entries_enqueued _
  | Deferred_entries_adopted
  | Pending_inputs_changed _
  | Active_operation_changed None
  | Automatic_turn_budget_enabled _
  | Automatic_turn_pauses_changed _
  | Attachment_added _
  | Attachment_removed _
  | Permission_changed _
  | Grant_changed _
  | Inference_target_captured _
  | Configuration_revision_changed _
  | Inference_target_changed _
  | Model_job_target_captured _
  | Model_job_recipe_target_captured _
  | Model_job_target_restored _
  | Inference_ledger_changed _
  | Delegated_inference_ledger_changed _
  | Child_contributions_changed _
  | Goal_descendants_changed _
  | Goal_policy_contributions_changed _
  | Policy_cause_changed _
  | Policy_inference_ledger_changed _
  | Managed_submission_admitted _
  | Managed_submission_changed _
  | Managed_stop_admitted _
  | Invocation_reconciled _
  | Moderator_execution_reconciled _
  | Subscription_changed _
  | Subscription_expired _
  | Subscription_cancelled _
  | Delivery_changed _
  | Ingress_changed _
  | Delivery_committed _
  | Delivery_wake_changed _
  | Goal_catalog_changed _
  | Goal_accounts_changed _
  | Instruction_selection_changed _
  | Recovery_note_changed _
  | Recovery_note_share_changed _
  | Recovery_rollover_changed _
  | Recovery_rollover_committed _
  | Recurrence_catalog_changed _
  | Run_state_changed _
  | Moderator_changed _
  | Shell_changed _
  | History_block_reserved _
  | Compaction_generation_changed _
  | Compaction_archived _
  | History_deleted _
  | History_edited _
  | Owner_lease_generation_changed _
  | Failure_changed _
  | Halt_changed _
  | Reset_generation _ -> false
;;

let rec deferred_admission_delta (previous : Session_state.t) (delta : Session_delta.t) =
  match delta with
  | Batch deltas -> List.exists deltas ~f:(deferred_admission_delta previous)
  | Run_state_changed index ->
    let before = Option.value previous.run_state ~default:Run_state.empty in
    List.exists (Run_state.receipts index) ~f:(fun receipt ->
      Agent_protocol.Run_receipt.Kind.equal receipt.kind Admission
      &&
      match
        Run_state.receipt
          before
          ~principal_id:receipt.principal_id
          ~key:receipt.key
          ~request_sha256:receipt.request_sha256
      with
      | Ok (Some _) -> false
      | Ok None | Error _ -> true)
  | _ -> false
;;

(* Every actual durable write passes this seam. Only real Turn starts sample
   fresh policy time; ledger/outcome/cleanup writes add no clock callback. *)
module Inference_native_finish_installation = struct
  type actor = t

  module Pending = struct
    type t =
      { custody : Inference_graph_custody.t
      ; native : Graph_owner.Native_join.t
      ; finish : Inference_native_finish.t option
      }
  end

  module Phase = struct
    type t =
      | Pending of Pending.t
      | Installed
  end

  type t =
    { domain : int
    ; mutable phase : Phase.t
    }

  let check_basis t ~(actor : actor) =
    let open Result.Let_syntax in
    let%bind () =
      if Int.equal t.domain (Stdlib.Domain.self () :> int)
      then Ok ()
      else Error (error Conflict "native finish install belongs to another domain")
    in
    match t.phase with
    | Installed -> Error (error Conflict "native finish is already installed")
    | Pending pending ->
      let%bind () = Graph_owner.Native_join.check_basis pending.native in
      if
        Int.equal actor.runtime_source_domain (Stdlib.Domain.self () :> int)
        && phys_equal
             actor.inference_owner_identity
             (Graph_owner.issuing_actor pending.custody.owner)
        && Option.exists
             (find_inference_graph_custody actor pending.custody.owner)
             ~f:(phys_equal pending.custody)
        && Option.is_none pending.custody.native_finish
      then Ok ()
      else Error (error Conflict "native finish lost its exact Actor graph custody")
  ;;

  let prepare actor ~custody ~scope ~native =
    let finish =
      Some
        { Inference_native_finish.scope
        ; acknowledgement = Graph_owner.Native_join.acknowledgement native
        }
    in
    let pending = { Pending.custody; native; finish } in
    let t = { domain = (Stdlib.Domain.self () :> int); phase = Pending pending } in
    Result.map (check_basis t ~actor) ~f:(fun () -> t)
  ;;

  let install t =
    if Int.equal t.domain (Stdlib.Domain.self () :> int)
    then (
      match t.phase with
      | Installed -> ()
      | Pending pending ->
        Graph_owner.Native_join.install pending.native;
        pending.custody.native_finish <- pending.finish;
        t.phase <- Installed)
  ;;
end

module Owned_inference_mutation = struct
  type acknowledgement =
    | Preserve
    | Acknowledge of Inference_owner.Registration.t * Inference_runtime.Attempt.t
    | Native_join of Inference_native_finish_installation.t
    | Finish

  module Scope = Inference_scope

  type t =
    { scope : Scope.t
    ; owner : Inference_owner.t
    ; acknowledgement : acknowledgement
    }
end

let input_graph_basis t (scope : Held_input_scope.t) owner =
  if
    phys_equal scope.Held_input_scope.issuing_actor t.inference_owner_identity
    && List.mem scope.graphs owner ~equal:phys_equal
    && owns_inference_graph t owner
    && phys_equal t.inference_owner_identity (Graph_owner.issuing_actor owner)
  then Ok ()
  else Error (error Conflict "inference graph does not belong to this held input")
;;

let initialization_graph_basis t (graph : Runtime_constructor_graph.t) =
  if
    phys_equal graph.scope.owner t.initialization_owner
    && List.mem graph.scope.graphs graph.owner ~equal:phys_equal
    && owns_inference_graph t graph.owner
    && phys_equal t.inference_owner_identity (Graph_owner.issuing_actor graph.owner)
    && Option.exists
         (Initialization_scope_data.construction graph.scope)
         ~f:(fun construction ->
           Preparation_owner.same
             (Runtime_construction.preparation_owner construction)
             (Runtime_construction.preparation_owner graph.construction))
  then Ok ()
  else Error (error Conflict "constructor graph belongs to another or substituted scope")
;;

let owned_graph_basis t (mutation : Owned_inference_mutation.t) =
  match mutation.scope with
  | Input scope -> input_graph_basis t scope mutation.owner
  | Registered owner ->
    let open Result.Let_syntax in
    let%bind () =
      if
        Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
        && phys_equal owner mutation.owner
        && phys_equal t.inference_owner_identity (Graph_owner.issuing_actor owner)
        && owns_inference_graph t owner
      then Ok ()
      else Error (error Conflict "factual registration belongs to another graph owner")
    in
    let checked = ref (Ok ()) in
    Graph_owner.iter_retained_registrations owner ~f:(fun registration ->
      checked
      := Result.bind !checked ~f:(fun () ->
           let handle = Inference_owner.Registration.handle registration in
           if
             Agent_protocol.Id.Session.equal
               (Inference_ledger.Handle.session_id handle)
               t.state.identity.session_id
             && Int.equal
                  (Inference_ledger.Handle.generation handle)
                  (Graph_owner.generation owner)
             && Option.exists (Graph_owner.qualified_source owner) ~f:(fun source ->
               Transcript.Source_id.equal
                 source
                 (Transcript.Scope.key (Inference_ledger.Handle.scope handle)).source)
             && Option.value_map
                  (Inference_owner.Registration.initial_preparation registration)
                  ~default:true
                  ~f:(fun preparation ->
                    Run_preparation.belongs_to preparation ~owner:t.run_preparation_owner)
           then Ok ()
           else
             Error
               (error Conflict "factual registration source or preparation owner changed")));
    !checked
  | Goal_runtime scope ->
    if
      Int.equal
        scope.continuation.binding.preparation.domain
        (Stdlib.Domain.self () :> int)
      && phys_equal scope.issuing_actor t.inference_owner_identity
      && List.mem scope.graphs mutation.owner ~equal:phys_equal
      && owns_inference_graph t mutation.owner
      && phys_equal t.inference_owner_identity (Graph_owner.issuing_actor mutation.owner)
    then Ok ()
    else Error (error Conflict "graph has another factual Goal runtime owner")
  | Initialization graph ->
    if phys_equal graph.owner mutation.owner
    then initialization_graph_basis t graph
    else Error (error Conflict "constructor graph owner was substituted")
  | Authored scope ->
    if
      phys_equal scope.issuing_actor t.inference_owner_identity
      && List.mem scope.graphs mutation.owner ~equal:phys_equal
      && owns_inference_graph t mutation.owner
      && phys_equal t.inference_owner_identity (Graph_owner.issuing_actor mutation.owner)
    then Ok ()
    else Error (error Conflict "graph does not belong to this held authored startup")
;;

let owned_graph_preparation (mutation : Owned_inference_mutation.t) =
  match mutation.scope with
  | Registered owner ->
    let selected = ref None in
    let conflicting = ref false in
    Graph_owner.iter_retained_registrations owner ~f:(fun registration ->
      let captured = Inference_owner.Registration.initial_preparation registration in
      match !selected with
      | None -> selected := Some captured
      | Some previous ->
        if not (Option.equal phys_equal previous captured) then conflicting := true);
    if !conflicting
    then None
    else
      Option.bind
        !selected
        ~f:(Option.map ~f:(fun preparation -> Preparation_owner.Initial preparation))
  | Goal_runtime scope ->
    Some (Preparation_owner.Existing_goal scope.continuation.binding.preparation)
  | Input scope -> Some (Preparation_owner.Initial scope.continuation.target.preparation)
  | Authored scope ->
    Some (Preparation_owner.Initial scope.continuation.target.preparation)
  | Initialization graph -> Initialization_scope_data.preparation_owner graph.scope
;;

module Owned_inference_persistence = struct
  type actor = t

  type t =
    { issuing_actor : unit ref
    ; domain : int
    ; previous : Session_state.t
    ; candidate : Session_transition.t
    ; mutation : Owned_inference_mutation.t
    ; preparation_owner : Preparation_owner.t option
    ; source_binding : Source_binding.t option
    }

  let check t ~(actor : actor) ~candidate =
    let open Result.Let_syntax in
    let%bind () =
      if
        Int.equal t.domain (Stdlib.Domain.self () :> int)
        && phys_equal t.issuing_actor actor.inference_owner_identity
        && phys_equal t.previous actor.state
        && phys_equal t.candidate candidate
        && Option.equal phys_equal t.source_binding actor.run_source_binding
      then Ok ()
      else Error (error Conflict "factual inference candidate owner or basis changed")
    in
    let%bind () = owned_graph_basis actor t.mutation in
    let%bind () =
      match t.preparation_owner with
      | None -> Ok ()
      | Some preparation ->
        if Option.exists actor.run_preparation ~f:(Preparation_owner.same preparation)
        then
          Preparation_owner.check_basis
            preparation
            ~owner:actor.run_preparation_owner
            ~state:actor.state
        else Error (error Conflict "factual inference preparation was displaced")
    in
    let marks ledger =
      Canonical_usage_fold.Marks.of_ledger ledger
      |> Result.map_error ~f:(fun e ->
        error Invalid_state (Sexp.to_string_hum (Canonical_usage_fold.Error.sexp_of_t e)))
    in
    let%bind before = marks actor.state.inference_ledger in
    let%bind after = marks candidate.Session_transition.state.inference_ledger in
    if
      Descendant_admission_data.metadata_only_candidate candidate
      && Canonical_usage_fold.Marks.equal before after
    then Ok ()
    else
      Error
        (error Invalid_state "factual inference candidate cannot admit canonical work")
  ;;

  let prepare (actor : actor) ~mutation ~candidate ~preparation_owner =
    let t =
      { issuing_actor = actor.inference_owner_identity
      ; domain = actor.runtime_source_domain
      ; previous = actor.state
      ; candidate
      ; mutation
      ; preparation_owner
      ; source_binding = actor.run_source_binding
      }
    in
    Result.map (check t ~actor ~candidate) ~f:(fun () -> t)
  ;;
end

module Startup_write = struct
  type t =
    | Input_root of Failed_startup_data.Input.t
    | Authored of Failed_startup_data.Authored.t * Failed_startup_data.Authored.cut

  let commit t ~requested_candidate ~previous ~candidate ~commit =
    let module Owner = Session_commit_observation.Owner in
    let observation = Owner.create ~previous ~candidate in
    match t with
    | Input_root input ->
      Failed_startup_data.Input.record_root input ~requested_candidate observation;
      Owner.commit observation ~commit
    | Authored (attempt, cut) ->
      Exn.protect
        ~finally:(fun () ->
          Failed_startup_data.Authored.record_write
            attempt
            ~cut
            ~requested_candidate
            observation)
        ~f:(fun () -> Owner.commit observation ~commit)
  ;;
end

let check_protected_source_write t ~(requested : Session_transition.t) =
  let previous = t.state in
  let next = requested.state in
  if
    Option.is_some t.protected_source_custody
    && ((not (Int.equal previous.identity.generation next.identity.generation))
        || (not (phys_equal previous.recovery_notes next.recovery_notes))
        || (not (phys_equal previous.recovery_note_shares next.recovery_note_shares))
        || (not (phys_equal previous.recovery_windows next.recovery_windows))
        || (not (phys_equal previous.moderator next.moderator))
        || (not
              (phys_equal
                 previous.conversation.canonical_history
                 next.conversation.canonical_history))
        || not
             (phys_equal
                previous.conversation.compaction_archives
                next.conversation.compaction_archives))
  then
    Error
      (Agent_protocol.Error.create
         Conflict
         ~message:"protected source is currently being disclosed"
         ~retryable:true
         ())
  else Ok ()
;;

let require_rollover_recovered t =
  if t.rollover_requires_recovery
  then Error (error Conflict "rollover outcome requires canonical journal recovery")
  else Ok ()
;;

let persist_transition
      ?(causal_canonical_fence = Causal_canonical_custody.Fence.Unrestricted)
      ?commit_observation
      ?startup_write
      ?idle_completion_write
      ?owned_inference_persistence
      ?descendant_admission_acknowledgement
      ?run_preparation
      ?admission_hold
      ?commit_attempted
      ?check_before_commit
      ?(explicit_goal_holds = [])
      t
      (candidate : Session_transition.t)
  =
  let open Result.Let_syntax in
  let%bind () = require_rollover_recovered t in
  let%bind () = check_protected_source_write t ~requested:candidate in
  let%bind () =
    Causal_canonical_custody.check_fence t ~requested:candidate causal_canonical_fence
  in
  let%bind causal_fence = Causal_root_custody.begin_writer t ~requested:candidate in
  let%bind fence =
    match Constructor_model_custody.begin_writer t ~requested:candidate with
    | Ok _ as result -> result
    | Error _ as result ->
      Causal_root_custody.finish_writer causal_fence;
      result
    | exception exn ->
      let backtrace = Stdlib.Printexc.get_raw_backtrace () in
      Causal_root_custody.finish_writer causal_fence;
      Exn.raise_with_original_backtrace exn backtrace
  in
  let delegated = ref None in
  let write_in_progress = t.canonical_write_in_progress in
  t.canonical_write_in_progress <- true;
  Exn.protect
    ~finally:(fun () ->
      t.canonical_write_in_progress <- write_in_progress;
      Option.iter !delegated ~f:Delegated_policy_custody.finish_writer;
      Constructor_model_custody.finish_writer fence;
      Causal_root_custody.finish_writer causal_fence)
    ~f:(fun () ->
      let%bind delegated_fence =
        Delegated_policy_custody.begin_writer t ~requested:candidate
      in
      delegated := Some delegated_fence;
      let revision = t.state.counters.revision in
      let%bind source_binding =
        match owned_inference_persistence with
        | Some proof ->
          let%bind () =
            if Option.is_none run_preparation
            then Ok ()
            else
              Error
                (error
                   Invalid_state
                   "factual inference proof cannot select fresh Run policy")
          in
          let%map () = Owned_inference_persistence.check proof ~actor:t ~candidate in
          None
        | None ->
          (match t.run_source_binding with
           | None -> Ok None
           | Some binding
             when Option.exists
                    run_preparation
                    ~f:(phys_equal binding.Source_binding.preparation) ->
             let%map () = Source_binding.check_current binding in
             Some binding
           | Some _ ->
             close_run_preparation t;
             Ok None)
      in
      let%bind payloads =
        List.filter_map candidate.events ~f:(fun event ->
          match event.Agent_protocol.Event.Durable.kind with
          | Operation_started ->
            Some
              (Agent_protocol.Event.Durable.Payload.of_json
                 ~kind:event.kind
                 event.payload)
          | _ -> None)
        |> Result.all
      in
      let starts_turn =
        List.exists payloads ~f:(function
          | Agent_protocol.Event.Durable.Payload.Operation_started { kind = Turn _; _ } ->
            true
          | _ -> false)
      in
      let policy_now = if starts_turn then Some (t.services.now ()) else None in
      let%bind admission =
        if starts_turn
        then (
          match check_before_commit with
          | None ->
            Error (error Invalid_state "host turn has no captured final owner check")
          | Some _ ->
            Goal_host_turn_admission.prepare
              ~previous:t.state
              ~candidate:candidate.state
              ~payloads
              ~now:(Option.value_exn policy_now))
        else Ok Goal_host_turn_admission.Allow
      in
      let%bind () =
        Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check -> check ())
      in
      let%bind () =
        if Int64.equal revision t.state.counters.revision
        then Ok ()
        else Error (error Conflict "candidate basis changed during final commit policy")
      in
      let%bind () =
        Option.value_map source_binding ~default:(Ok ()) ~f:Source_binding.check_basis
      in
      let%bind () =
        Option.value_map owned_inference_persistence ~default:(Ok ()) ~f:(fun proof ->
          Owned_inference_persistence.check proof ~actor:t ~candidate)
      in
      (* Source policy precedes the composed final guard. Only pure basis checks
     follow it, and the attempt becomes uncertain only at a real writer call. *)
      let requested = candidate in
      let commit ?admission_hold ~command_audit candidate =
        let%bind () = Constructor_model_custody.check_fence t ~requested fence in
        let%bind () = Delegated_policy_custody.check_fence t ~requested delegated_fence in
        let%bind () = Causal_root_custody.check_fence t ~requested causal_fence in
        let%bind () =
          Causal_canonical_custody.check_fence t ~requested causal_canonical_fence
        in
        (* Retire live Goal prefixes before a yielding control writer. A failed save
       cannot make a previously revoked checked view executable again. *)
        retain_goal_activations ?admission_hold t candidate.Session_transition.state;
        (* Selected fresh controls retire only here, after all original/source/ACK
       checks. Same-valued Hold must not close its own callback before those
       checks, and a failed writer must never revive this prefix. *)
        List.iter explicit_goal_holds ~f:(retire_goal_activation t);
        if Option.is_some t.effect_deferred
        then
          if
            (* Keep the requested candidate across Goal's metadata-only replacement.
         The mark belongs to the actual writer attempt, never a no-write hold. *)
            deferred_admission_delta t.state requested.delta
          then exclude_effect_deferred t Admission_attempted
          else if deferred_execution_delta t.state requested.delta
          then exclude_effect_deferred t Ordinary_execution;
        let%bind () =
          match idle_completion_write with
          | None -> Ok ()
          | Some ((_, write) as owned) ->
            let selected =
              if phys_equal candidate requested
              then
                Ok
                  (Idle_completion_write.Selected.Requested
                     (Idle_completion_write.kind write))
              else (
                match admission_hold with
                | Some goal -> Ok (Idle_completion_write.Selected.Admission_hold goal)
                | None ->
                  Error
                    (error Invalid_state "legacy writer selected an unowned candidate"))
            in
            let%bind selected = selected in
            select_idle_completion_writer t owned ~candidate ~selected
        in
        Option.iter commit_attempted ~f:(fun attempted -> attempted := true);
        (* A policy Hold may select a different metadata-only writer. Only the
       exact requested canonical candidate makes this child occurrence uncertain;
       the generic writer-attempt flag above retains its existing meaning. *)
        if phys_equal candidate requested
        then
          Option.iter
            descendant_admission_acknowledgement
            ~f:
              (fun
                (ack :
                  inherited_attempt_plan
                    Governed_admission_slot.Descendant_acknowledgement.t)
              -> ack.native.slot.preparation.writer_attempted := true);
        let persist () =
          let commit ~observation =
            t.persistence.commit ~observation ~command_audit ~previous:t.state candidate
          in
          match commit_observation, startup_write with
          | Some observation, _ ->
            Session_commit_observation.Owner.commit observation ~commit
          | None, Some write ->
            Startup_write.commit
              write
              ~requested_candidate:(phys_equal candidate requested)
              ~previous:t.state
              ~candidate
              ~commit
          | None, None -> t.persistence.commit ~command_audit ~previous:t.state candidate
        in
        match persist () with
        | Ok () -> Ok ()
        | Error failure as result ->
          Option.iter idle_completion_write ~f:(fun (_, write) ->
            Idle_completion_write.retain_failure write failure);
          result
        | exception exn ->
          let backtrace = Stdlib.Printexc.get_raw_backtrace () in
          Option.iter idle_completion_write ~f:(fun (_, write) ->
            Idle_completion_write.retain_exception write exn backtrace);
          Exn.raise_with_original_backtrace exn backtrace
      in
      match admission with
      | Deferred deferred -> Error (goal_capacity_deferred deferred)
      | Allow ->
        retain_recurrence_activations t candidate.state;
        commit ?admission_hold ~command_audit:t.command_audit candidate
      | Held { goal_id; delta } ->
        let%bind () =
          match delta with
          | None -> Ok ()
          | Some delta ->
            (* Only the actual preexisting Goal may be held. Candidate operation,
           inputs, episode and charges are discarded. Reuse sampled policy time. *)
            let%bind held =
              Session_transition.apply
                ~now:(Option.value_exn policy_now)
                t.state
                ~delta
                ~payloads:[]
            in
            retain_recurrence_activations t held.state;
            let%map () = commit ~admission_hold:goal_id ~command_audit:None held in
            install_committed_transition
              ?idle_completion_write
              ~admission_hold:goal_id
              t
              held;
            publish_committed_transition t held
        in
        Error (error Permission_denied "goal policy holds fresh host-turn admission"))
;;

let prepare_completion_plan t (transition : Session_transition.t) completion_sample =
  match completion_sample with
  | None -> Ok None
  | Some sample ->
    Recurrence_runtime.prepare_completions
      t.recurrence_runtime
      ~sample
      ~previous:t.state
      ~current:transition.state
    |> Result.map ~f:Option.some
;;

let install
      ?causal_root_acknowledgement
      ?unmoderated_configuration_acknowledgement
      ?constructor_job_control
      ?idle_completion_write
      ?inherited_turn_acknowledgement
      ?held_operation_acknowledgement
      ?goal_operation_acknowledgement
      ?root_reserve_acknowledgement
      ?root_close_acknowledgement
      ?descendant_admission_acknowledgement
      ?descendant_import_acknowledgement
      ?turn_stage
      ?held_authored_callback_acknowledgement
      ?goal_runtime_acknowledgement
      ?queued_claim_acknowledgement
      ?authored_run_acknowledgement
      ?initialization_acknowledgement
      ?constructor_stop_acknowledgement
      ?check_before_commit
      ?admission_hold
      ?retire_legacy_custody
      ?run_preparation
      ?commit_attempted
      ?queue_custody_installation
      ?job_custody
      ?completion_sample
      ?(explicit_goal_holds = [])
      t
      transition
  =
  let open Result.Let_syntax in
  let%bind () =
    match causal_root_acknowledgement, constructor_job_control with
    | None, _ -> Ok ()
    | Some write, None ->
      if
        Option.exists t.causal_root_write ~f:(phys_equal write)
        && phys_equal write.candidate transition
      then Causal_root_custody.check_owner t write
      else Error (error Conflict "causal root install lost its retained exact plan")
    | Some _, Some _ ->
      Error
        (error Conflict "one canonical candidate cannot select two native writer owners")
  in
  let%bind () =
    Option.value_map job_custody ~default:(Ok ()) ~f:(fun update ->
      Job_custody.Update.check_before_commit update ~current:t.job_agent_custody)
  in
  let%bind producer_callback_acknowledgement =
    match held_authored_callback_acknowledgement, goal_runtime_acknowledgement with
    | None, None -> Producer_callback_acknowledgement.prepare t ~candidate:transition
    | (Some _ | None), (Some _ | None) -> Ok None
  in
  let%bind completion_plan = prepare_completion_plan t transition completion_sample in
  let check_before_commit =
    match held_authored_callback_acknowledgement with
    | None -> check_before_commit
    | Some acknowledgement ->
      Some
        (fun () ->
          let%bind () =
            Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check ->
              check ())
          in
          Held_authored_callback_acknowledgement.check
            acknowledgement
            ~actor:t
            ~candidate:transition)
  in
  let final_check = check_before_commit in
  let check_before_commit =
    match goal_runtime_acknowledgement with
    | None -> final_check
    | Some acknowledgement ->
      Some
        (fun () ->
          let%bind () =
            Option.value_map final_check ~default:(Ok ()) ~f:(fun check -> check ())
          in
          Goal_runtime_acknowledgement.check
            acknowledgement
            ~actor:t
            ~candidate:transition)
  in
  let previous_check = check_before_commit in
  let check_before_commit =
    match producer_callback_acknowledgement with
    | None -> previous_check
    | Some acknowledgement ->
      Some
        (fun () ->
          let%bind () =
            Option.value_map previous_check ~default:(Ok ()) ~f:(fun f -> f ())
          in
          Producer_callback_acknowledgement.check
            acknowledgement
            ~actor:t
            ~candidate:transition)
  in
  let previous_check = check_before_commit in
  let%bind () =
    if
      Option.is_some descendant_admission_acknowledgement
      && (not (Descendant_admission_data.metadata_only_candidate transition))
      && Option.is_none previous_check
    then
      Error
        (error
           Invalid_state
           "descendant Turn ACK requires its original final owner check")
    else Ok ()
  in
  let check_before_commit =
    match
      ( previous_check
      , descendant_admission_acknowledgement
      , root_reserve_acknowledgement
      , root_close_acknowledgement
      , descendant_import_acknowledgement )
    with
    | None, None, None, None, None -> None
    | (Some _ | None), (Some _ | None), (Some _ | None), (Some _ | None), (Some _ | None)
      ->
      Some
        (fun () ->
          let%bind () =
            Option.value_map previous_check ~default:(Ok ()) ~f:(fun check -> check ())
          in
          let%bind () =
            Option.value_map
              descendant_admission_acknowledgement
              ~default:(Ok ())
              ~f:(fun acknowledgement ->
                check_descendant_admission_slot_ack
                  t
                  acknowledgement
                  ~candidate:transition)
          in
          let%bind () =
            Option.value_map
              root_reserve_acknowledgement
              ~default:(Ok ())
              ~f:(fun acknowledgement ->
                Root_reserve_acknowledgement.check_basis
                  acknowledgement
                  ~state:t.state
                  ~candidate:transition)
          in
          let%bind () =
            Option.value_map
              root_close_acknowledgement
              ~default:(Ok ())
              ~f:(fun acknowledgement ->
                Root_close_acknowledgement.check_basis
                  acknowledgement
                  ~state:t.state
                  ~candidate:transition)
          in
          Option.value_map
            descendant_import_acknowledgement
            ~default:(Ok ())
            ~f:(fun acknowledgement ->
              Descendant_import_acknowledgement.check_basis
                acknowledgement
                ~state:t.state
                ~candidate:transition))
  in
  (* An ACK option cannot manufacture the required original Turn guard. *)
  let check_before_commit =
    match check_before_commit with
    | None -> None
    | Some original ->
      Some
        (fun () ->
          let%bind () = original () in
          let%bind () =
            Option.value_map
              held_operation_acknowledgement
              ~default:(Ok ())
              ~f:(fun acknowledgement ->
                Held_operation_acknowledgement.check
                  acknowledgement
                  ~actor:t
                  ~candidate:transition)
          in
          let%bind () =
            Option.value_map
              goal_operation_acknowledgement
              ~default:(Ok ())
              ~f:(fun acknowledgement ->
                Goal_runtime_operation_acknowledgement.check
                  acknowledgement
                  ~actor:t
                  ~candidate:transition)
          in
          Option.value_map
            inherited_turn_acknowledgement
            ~default:(Ok ())
            ~f:(fun acknowledgement ->
              Inherited_turn_acknowledgement.check
                acknowledgement
                ~actor:t
                ~candidate:transition))
  in
  let previous_check = check_before_commit in
  let check_before_commit =
    match queue_custody_installation with
    | None | Some (Queue_custody_installation.Inventory _) -> previous_check
    | Some (Delivery_update update) ->
      Some
        (fun () ->
          let%bind () =
            Option.value_map previous_check ~default:(Ok ()) ~f:(fun check -> check ())
          in
          Legacy_queue_custody.Update.check_basis update ~current:t.legacy_queue_custody)
  in
  let previous_check = check_before_commit in
  let check_before_commit =
    match unmoderated_configuration_acknowledgement with
    | None -> previous_check
    | Some acknowledgement ->
      Some
        (fun () ->
          let%bind () =
            Option.value_map previous_check ~default:(Ok ()) ~f:(fun f -> f ())
          in
          check_unmoderated_configuration t acknowledgement transition)
  in
  let%bind () =
    persist_transition
      ?commit_observation:
        (match causal_root_acknowledgement, constructor_job_control with
         | Some write, None -> Some (Session_commit_attempt.observation write.writer)
         | None, Some (_, plan) ->
           Some
             (Session_commit_attempt.observation
                plan.Constructor_model_data.canonical.attempt)
         | None, None -> None
         | Some _, Some _ ->
           invalid_arg
             "one canonical candidate cannot have two distinct native writer owners")
      ?idle_completion_write
      ?descendant_admission_acknowledgement
      ?run_preparation
      ?admission_hold
      ?commit_attempted
      ?check_before_commit
      ~explicit_goal_holds
      t
      transition
  in
  (* Fresh explicit controls revoke admitted policy cells at their actual
     writer ACK, including a Hold equal to an automatic hold. Publication can
     yield or fail, so it cannot own this denial. Failed saves never reach here;
     automatic admission holds do not supply these control IDs. *)
  install_committed_transition
    ?causal_root_acknowledgement
    ?unmoderated_configuration_acknowledgement
    ?idle_completion_write
    ?held_operation_acknowledgement
    ?goal_operation_acknowledgement
    ?inherited_turn_acknowledgement
    ?root_reserve_acknowledgement
    ?root_close_acknowledgement
    ?descendant_admission_acknowledgement
    ?descendant_import_acknowledgement
    ~explicit_goal_holds
    ?goal_runtime_acknowledgement
    ?queued_claim_acknowledgement
    ?authored_run_acknowledgement
    ?initialization_acknowledgement
    ?constructor_stop_acknowledgement
    ?admission_hold
    ?retire_legacy_custody
    ?run_preparation
    ?queue_custody_installation
    ?job_custody
    t
    transition;
  Option.iter constructor_job_control ~f:(fun (call, plan) ->
    Constructor_model_custody.install_control t call plan);
  let%bind () =
    Option.value_map turn_stage ~default:(Ok ()) ~f:(fun staged ->
      Turn_admission_staging.acknowledge
        staged
        ~owner:t.run_preparation_owner
        ~state:t.state
      |> Result.map ~f:ignore)
  in
  let%bind () =
    Option.value_map
      producer_callback_acknowledgement
      ~default:(Ok ())
      ~f:Producer_callback_acknowledgement.install
  in
  let%bind () =
    Option.value_map
      held_authored_callback_acknowledgement
      ~default:(Ok ())
      ~f:Held_authored_callback_acknowledgement.install
  in
  Option.iter
    completion_plan
    ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
  publish_committed_transition t transition;
  Ok ()
;;

let current_snapshot t =
  Eio.Mutex.use_ro t.subscriber_mutex (fun () ->
    let active_tool_calls, active_agent_calls = Active_calls.snapshot t.active_calls in
    { (Session_state.snapshot ~now:(t.services.now ()) t.state) with
      active_tool_calls
    ; active_agent_calls
    })
;;

(* Every actor candidate, including audited commits and speculative staged work,
   selects source retirement before validation. Persistence and installation
   consume this exact prepared candidate without rewriting it. *)
let completion_clock_pair t =
  let wall = t.services.now () in
  let monotonic = t.services.monotonic_now () in
  wall, Recurrence_runtime.Completion.sample ~wall ~monotonic
;;

(* Only an actual selected producer transition requests this clock. Existing
   callback/Job samples retain their exact wall; no later clock replaces it. *)
let producer_completion_sample ?completion_sample t ~delta =
  match completion_sample with
  | Some _ -> completion_sample
  | None ->
    if Run_producer_settlement.requires_completion_sample t.state ~delta
    then Some (snd (completion_clock_pair t))
    else None
;;

let prepare_transition_basis ?run_preparation ?completion_sample t ~delta =
  let open Result.Let_syntax in
  let%bind () =
    match run_preparation with
    | None -> Ok ()
    | Some preparation -> check_run_preparation t preparation
  in
  let now =
    match completion_sample with
    | Some sample -> Recurrence_runtime.Completion.wall sample
    | None -> t.services.now ()
  in
  let%bind delta = Run_source_change.prepare t.state ~delta ~now in
  let%bind delta = Goal_catalog_source.prepare_change t.state ~delta in
  let%bind delta =
    Run_producer_settlement.prepare
      ?startup_run:(pending_held_startup_run t)
      t.state
      ~delta
      ~now
  in
  let%bind delta = Goal_run_settlement.prepare t.state ~delta in
  let%map delta = Recurrence_source.prepare_change t.state ~delta in
  now, delta
;;

let check_prepared_transition_capacity (prepared : Session_transition.t) =
  let open Result.Let_syntax in
  match prepared.state.run_state with
  | None -> Ok ()
  | Some index ->
    let%bind additional_bytes =
      Run_job_capacity.bookkeeping_reserve index ~jobs:prepared.state.jobs
    in
    Run_state.validate_encoded_capacity_with_reserve
      index
      ~additional_bytes
      (Run_state.to_jsonaf index)
;;

let prepare_transition ?run_preparation ?completion_sample t ~delta ~payloads =
  let open Result.Let_syntax in
  let%bind now, delta =
    prepare_transition_basis ?run_preparation ?completion_sample t ~delta
  in
  let%bind prepared = Session_transition.apply ~now t.state ~delta ~payloads in
  let%map () = check_prepared_transition_capacity prepared in
  prepared
;;

(* Retain the actual inherited edge from the same fully validated candidate.
   Source settlement and final capacity checks remain shared with ordinary turns. *)
let prepare_transition_inherited
      ?run_preparation
      ?completion_sample
      t
      ~inherited_turn
      ~delta
      ~payloads
  =
  let open Result.Let_syntax in
  let%bind now, delta =
    prepare_transition_basis ?run_preparation ?completion_sample t ~delta
  in
  let%bind prepared, edge =
    Session_transition.apply_inherited ~inherited_turn ~now t.state ~delta ~payloads
  in
  let%map () = check_prepared_transition_capacity prepared in
  prepared, edge
;;

let goal_runtime_transition
      ?admission_hold
      ?job_custody
      ?completion_sample
      ?check_before_commit
      t
      scope
      ~delta
      ~payloads
  =
  let open Result.Let_syntax in
  let completion_sample = producer_completion_sample ?completion_sample t ~delta in
  let%bind candidate = prepare_transition ?completion_sample t ~delta ~payloads in
  let%bind acknowledgement = Goal_runtime_acknowledgement.prepare t scope ~candidate in
  let%map () =
    install
      ?admission_hold
      ~goal_runtime_acknowledgement:acknowledgement
      ?job_custody
      ?completion_sample
      ?check_before_commit
      t
      candidate
  in
  Session_state.summary t.state
;;

let prepare_constructor_job_handoff ?run_preparation t ~delta ~payloads ~ids ~manager =
  let open Result.Let_syntax in
  let revision = t.state.counters.revision in
  let%bind prepared = prepare_transition ?run_preparation t ~delta ~payloads in
  let%bind index, binding = Constructor_job_handoff.prepare prepared.state ~manager in
  let source_changed =
    not (Option.equal Run_state.equal_observation prepared.state.run_state index)
  in
  let%bind prepared =
    if not source_changed
    then Ok prepared
    else (
      match index with
      | None -> Error (error Invalid_state "constructor removed its planned source index")
      | Some index ->
        let delta =
          match Session_replacement_delta.classify delta with
          | Some replacement ->
            let candidate = Session_replacement_delta.state replacement in
            Session_replacement_delta.with_state
              replacement
              { candidate with run_state = Some index }
          | None -> Session_delta.Batch [ delta; Run_state_changed index ]
        in
        prepare_transition ?run_preparation t ~delta ~payloads)
  in
  let jobs =
    List.filter_map ids ~f:(fun id ->
      List.find prepared.state.jobs ~f:(fun job -> Agent_protocol.Id.Job.equal id job.id))
  in
  let%map job_custody =
    Job_custody.prepare_constructor_handoff t.job_agent_custody ~jobs ~binding
  in
  prepared, job_custody, source_changed, revision
;;

let check_constructor_job_handoff
      t
      ~(prepared : Session_transition.t)
      ~job_custody
      ~manager
      ~revision
  =
  let open Result.Let_syntax in
  let%bind () =
    if Int64.equal revision t.state.counters.revision
    then Ok ()
    else Error (error Conflict "constructor checkpoint basis changed before commit")
  in
  let%bind _ = Constructor_job_handoff.prepare prepared.state ~manager in
  Option.value_map job_custody ~default:(Ok ()) ~f:(fun update ->
    Job_custody.Update.check_before_commit update ~current:t.job_agent_custody)
;;

let transition
      ?idle_completion_step
      ?goal_runtime_scope
      ?check_before_commit
      ?constructor_stop_acknowledgement
      ?admission_hold
      ?retire_legacy_custody
      ?run_preparation
      ?commit_attempted
      ?queue_custody_installation
      ?job_custody
      ?completion_sample
      t
      ~delta
      ~payloads
  =
  Exn.protect
    ~finally:(fun () -> Option.iter job_custody ~f:Job_custody.Update.discard)
    ~f:(fun () ->
      let open Result.Let_syntax in
      let completion_sample = producer_completion_sample ?completion_sample t ~delta in
      let%bind transition =
        prepare_transition ?completion_sample ?run_preparation t ~delta ~payloads
      in
      let commit_attempted =
        match idle_completion_step with
        | None -> commit_attempted
        | Some _ ->
          Some (Option.value_or_thunk commit_attempted ~default:(fun () -> ref false))
      in
      let%bind idle_completion_write =
        match idle_completion_step, commit_attempted with
        | None, _ -> Ok None
        | Some (completion, kind), Some attempted ->
          prepare_idle_completion_write
            t
            (Some completion)
            ~kind
            ~candidate:transition
            ~attempted
        | Some _, None -> assert false
      in
      let%bind goal_runtime_acknowledgement =
        match goal_runtime_scope with
        | None -> Ok None
        | Some scope ->
          Goal_runtime_acknowledgement.prepare t scope ~candidate:transition
          |> Result.map ~f:Option.some
      in
      let check_before_commit =
        match goal_runtime_scope with
        | None -> check_before_commit
        | Some scope ->
          Some
            (fun () ->
              let%bind () =
                Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check ->
                  check ())
              in
              check_runtime_construction_effect (Existing_goal scope.continuation))
      in
      let%map () =
        install
          ?idle_completion_write
          ?goal_runtime_acknowledgement
          ?check_before_commit
          ?constructor_stop_acknowledgement
          ?admission_hold
          ?retire_legacy_custody
          ?run_preparation
          ?commit_attempted
          ?queue_custody_installation
          ?job_custody
          ?completion_sample
          t
          transition
      in
      Agent_protocol.Session.(Session_state.summary t.state))
;;

let reconcile_recurrences_internal t =
  match t.state.recurrence_catalog with
  | None -> Ok ()
  | Some _ ->
    let open Result.Let_syntax in
    let%bind controller = require_recurrence_controller t in
    let%bind prepared = Recurrence_reconciliation.prepare t.state ~controller in
    let%bind () = Recurrence_reconciliation.check_current prepared in
    (match prepared.delta with
     | None -> Ok ()
     | Some delta ->
       let%bind candidate = prepare_transition t ~delta ~payloads:[] in
       let%bind () = Recurrence_reconciliation.check_current prepared in
       install t candidate)
;;

let inference_error _ = error Invalid_state "inference tracking admission failed"

let input_scope_basis t (scope : Held_input_scope.t) =
  let open Result.Let_syntax in
  let activation = Admitted_activation.Continuation.target scope.continuation in
  let%bind () =
    if
      phys_equal scope.issuing_actor t.inference_owner_identity
      && Option.exists t.held_input_scope ~f:(phys_equal scope)
      && Option.exists t.held_activation ~f:(phys_equal activation)
      && Option.exists (initial_run_preparation t) ~f:(phys_equal activation.preparation)
    then Ok ()
    else Error (error Conflict "held input owner was displaced")
  in
  Run_preparation.check_basis
    activation.preparation
    ~owner:t.run_preparation_owner
    ~state:t.state
;;

let select_factual_graph t owner acknowledgement =
  let scope =
    match t.held_authored_start with
    | Some scope
      when (match scope.Held_authored_start.phase with
            | Released -> false
            | Staged
            | Starting
            | Ready
            | Executing _
            | Completed _
            | Attempt_unconfirmed
            | Closed -> true)
           && List.mem scope.graphs owner ~equal:phys_equal ->
      Owned_inference_mutation.Scope.Authored scope
    | Some _ | None -> Registered owner
  in
  { Owned_inference_mutation.scope; owner; acknowledgement }
;;

let factual_graph_for_handle t handle =
  List.find_map t.inference_owners ~f:(fun custody ->
    let owner = Inference_graph_custody.owner custody in
    Option.map (Graph_owner.retained_registration owner handle) ~f:(fun _ ->
      select_factual_graph t owner Owned_inference_mutation.Preserve))
;;

let install_input_graph_acknowledgement t (mutation : Owned_inference_mutation.t) =
  match mutation.acknowledgement with
  | Preserve -> ()
  | Acknowledge (registration, attempt) ->
    Inference_owner.Registration.acknowledge registration attempt
  | Native_join installation -> Inference_native_finish_installation.install installation
  | Finish ->
    let custody = find_inference_graph_custody t mutation.owner in
    Graph_owner.finish mutation.owner;
    t.inference_owners
    <- List.filter t.inference_owners ~f:(fun custody ->
         not (phys_equal (Inference_graph_custody.owner custody) mutation.owner));
    (match mutation.scope with
     | Input scope ->
       scope.graphs
       <- List.filter scope.graphs ~f:(fun owner -> not (phys_equal owner mutation.owner))
     | Registered _ -> ()
     | Goal_runtime scope ->
       scope.graphs
       <- List.filter scope.graphs ~f:(fun owner -> not (phys_equal owner mutation.owner))
     | Authored scope ->
       scope.graphs
       <- List.filter scope.graphs ~f:(fun owner -> not (phys_equal owner mutation.owner))
     | Initialization graph ->
       graph.scope.graphs
       <- List.filter graph.scope.graphs ~f:(fun owner ->
            not (phys_equal owner mutation.owner)));
    Option.iter custody ~f:(fun custody -> custody.native_finish <- None)
;;

module Held_inference_allocation_acknowledgement = struct
  type actor = t

  module Scope = struct
    type t =
      | Authored of Held_authored_start.t
      | Goal_runtime of Goal_continuation.runtime_scope
      | Initialization of Initialization_scope_data.t
  end

  type t =
    { scope : Scope.t
    ; owner : Inference_owner.t
    ; ledger : Inference_ledger.t
    ; handle : Inference_ledger.Handle.t
    ; configuration : Inference.Observation.Configuration.t
    ; goal_id : Agent_protocol.Id.Goal.t option
    }

  let check t ~(actor : actor) ~ledger =
    let open Result.Let_syntax in
    let%bind () =
      match t.scope with
      | Authored scope -> held_authored_basis actor scope
      | Goal_runtime scope ->
        let%bind () = goal_runtime_scope_basis actor scope in
        scope.continuation.binding.preparation.registered_basis ()
      | Initialization scope ->
        let%bind () =
          if List.mem scope.graphs t.owner ~equal:phys_equal
          then Ok ()
          else Error (error Conflict "allocation is outside its actual Init graph")
        in
        if
          phys_equal scope.owner actor.initialization_owner
          && Option.exists actor.initialization_scope ~f:(phys_equal scope)
        then
          Option.value_map
            (Initialization_scope_data.preparation_owner scope)
            ~default:(Ok ())
            ~f:(fun selected ->
              if Option.exists actor.run_preparation ~f:(Preparation_owner.same selected)
              then
                Preparation_owner.check_basis
                  selected
                  ~owner:actor.run_preparation_owner
                  ~state:actor.state
              else Error (error Conflict "allocation Init preparation was displaced"))
        else Error (error Conflict "allocation Init was displaced")
    in
    if
      phys_equal t.ledger ledger
      && owns_inference_graph actor t.owner
      && phys_equal actor.inference_owner_identity (Graph_owner.issuing_actor t.owner)
      &&
      match Graph_owner.phase t.owner with
      | Open -> true
      | Sealed | Finished -> false
    then Ok ()
    else Error (error Conflict "held allocation ACK differs from its actual graph")
  ;;

  let install t =
    let initial_preparation =
      match t.scope with
      | Authored scope -> Some scope.continuation.target.preparation
      | Goal_runtime _ -> None
      | Initialization scope ->
        Option.bind
          (Initialization_scope_data.preparation_owner scope)
          ~f:Preparation_owner.initial
    in
    Graph_owner.register
      t.owner
      ~initial_preparation
      ~handle:t.handle
      ~configuration:t.configuration
      ~goal_id:t.goal_id;
    match t.scope with
    | Goal_runtime scope ->
      if not (List.mem scope.graphs t.owner ~equal:phys_equal)
      then scope.graphs <- t.owner :: scope.graphs
    | Authored scope ->
      if not (List.mem scope.graphs t.owner ~equal:phys_equal)
      then scope.graphs <- t.owner :: scope.graphs
    | Initialization scope ->
      if not (List.mem scope.graphs t.owner ~equal:phys_equal)
      then scope.graphs <- t.owner :: scope.graphs
  ;;
end

let recovery_attempt_deltas receipts =
  List.map receipts ~f:(fun receipt -> Session_delta.Recovery_effective_attempt_changed receipt)
;;

let check_recovery_admission t candidate =
  match t.canonical_persistence with
  | Some backend ->
    Canonical_backend_binding_data.check_recovery_admission
      backend
      ~command_audit:t.command_audit
      ~previous:t.state
      candidate
  | None -> Error (error Invalid_state "recovery evidence requires a bound Store profile")
;;

let prepare_inference_transition
      ?run_preparation
      t
      ~changes
      ~payloads
      ~recovery_allocation
  =
  let open Result.Let_syntax in
  let prepare changes =
    prepare_transition ?run_preparation t ~delta:(Session_delta.Batch changes) ~payloads
  in
  match recovery_allocation with
  | None -> prepare changes
  | Some receipt ->
    let%bind candidate =
      prepare (changes @ [ Session_delta.Recovery_effective_attempt_changed receipt ])
    in
    (match%bind check_recovery_admission t candidate with
     | Fits -> Ok candidate
     | Capacity_exhausted -> prepare changes)
;;

let commit_inference_ledger
      ?allocation_acknowledgement
      ?owned_graph
      ?run_preparation
      ?admission
      ?check_before_commit
      ?recovery_allocation
      ?(recovery_attempts = [])
      t
      ledger
  =
  let open Result.Let_syntax in
  let%bind () =
    match owned_graph with
    | Some mutation ->
      let%bind () = owned_graph_basis t mutation in
      Option.value_map run_preparation ~default:(Ok ()) ~f:(fun preparation ->
        if Run_preparation.belongs_to preparation ~owner:t.run_preparation_owner
        then Ok ()
        else Error (error Conflict "factual preparation belongs to another Actor"))
    | None ->
      (match run_preparation with
       | None -> Ok ()
       | Some preparation -> check_run_preparation t preparation)
  in
  let accounting_changed =
    not
      (Int64.equal
         (Inference_ledger.revision ledger)
         (Inference_ledger.revision t.state.inference_ledger))
  in
  if
    (not accounting_changed)
    && List.is_empty recovery_attempts
    && Option.is_none recovery_allocation
  then (
    let%map () =
      Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check -> check ())
    in
    Option.iter owned_graph ~f:(install_input_graph_acknowledgement t))
  else (
    let%bind changes, payloads =
      if not accounting_changed
      then Ok ([], [])
      else (
        let%map accounting =
          Canonical_usage_update.prepare
            ?policy_usage:t.state.policy_canonical_usage
            t.state.inference_ledger
            ~accounts:t.state.goal_accounts
            ~catalog:t.state.goal_catalog
            ~after:ledger
            ~delegated_usage:t.state.delegated_usage
            ~admission
        in
        let accounting_delta =
          if Canonical_usage_update.accounts_changed accounting
          then
            [ Session_delta.Goal_accounts_changed
                (Option.value_exn (Canonical_usage_update.accounts accounting))
            ]
          else []
        in
        let changes =
          Session_delta.inference_ledger_update
            ?policy_update:(Canonical_usage_update.policy_update accounting)
            ledger
            ~delegated_usage:(Canonical_usage_update.delegated_usage accounting)
          :: accounting_delta
        in
        let payloads =
          [ Agent_protocol.Event.Durable.Payload.Session_updated
              (Session_state.summary { t.state with inference_ledger = ledger })
          ]
        in
        changes, payloads)
    in
    let changes = changes @ recovery_attempt_deltas recovery_attempts in
    let prepare ?run_preparation () =
      prepare_inference_transition
        ?run_preparation
        t
        ~changes
        ~payloads
        ~recovery_allocation
    in
    match allocation_acknowledgement, owned_graph with
    | Some acknowledgement, None ->
      let%bind () =
        Held_inference_allocation_acknowledgement.check acknowledgement ~actor:t ~ledger
      in
      let%bind candidate = prepare ?run_preparation () in
      let initialization_acknowledgement =
        match acknowledgement.scope with
        | Authored _ | Goal_runtime _ -> None
        | Initialization scope ->
          Some (Initialization_scope_data.Acknowledgement.prepare scope candidate.state)
      in
      let%bind goal_runtime_acknowledgement =
        match acknowledgement.scope with
        | Goal_runtime scope ->
          Goal_runtime_acknowledgement.prepare t scope ~candidate
          |> Result.map ~f:Option.some
        | Authored _ | Initialization _ -> Ok None
      in
      let final_check () =
        let%bind () =
          Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check -> check ())
        in
        let%bind () =
          Held_inference_allocation_acknowledgement.check acknowledgement ~actor:t ~ledger
        in
        let%bind () =
          Option.value_map
            initialization_acknowledgement
            ~default:(Ok ())
            ~f:Initialization_scope_data.Acknowledgement.check_basis
        in
        Option.value_map goal_runtime_acknowledgement ~default:(Ok ()) ~f:(fun ack ->
          Goal_runtime_acknowledgement.check ack ~actor:t ~candidate)
      in
      Eio.Cancel.protect (fun () ->
        let%bind () =
          persist_transition ?run_preparation ~check_before_commit:final_check t candidate
        in
        install_committed_transition
          ?goal_runtime_acknowledgement
          ?run_preparation
          ?initialization_acknowledgement
          t
          candidate;
        Held_inference_allocation_acknowledgement.install acknowledgement;
        publish_committed_transition t candidate;
        Ok ())
    | Some _, Some _ ->
      Error (error Conflict "inference mutation has conflicting ACK ownership")
    | None, None ->
      (match recovery_allocation with
       | None ->
         transition
           ?check_before_commit
           ?run_preparation
           t
           ~delta:(Batch changes)
           ~payloads
         |> Result.map ~f:ignore
       | Some _ ->
         let%bind candidate = prepare ?run_preparation () in
         install ?check_before_commit ?run_preparation t candidate)
    | None, Some mutation ->
      let goal_scope =
        Option.filter (goal_runtime_scope t) ~f:(fun scope ->
          List.mem scope.graphs mutation.owner ~equal:phys_equal)
      in
      let selected_preparation =
        match goal_scope with
        | Some scope ->
          Some (Preparation_owner.Existing_goal scope.continuation.binding.preparation)
        | None -> owned_graph_preparation mutation
      in
      (* This selected factual path never reauthorizes a produced result. The
         exact graph and preparation are retained, and only their basis advances
         after ACK. Preparing without a preparation avoids fresh-effect policy. *)
      let revision = t.state.counters.revision in
      let%bind candidate = prepare () in
      let%bind goal_runtime_acknowledgement =
        Option.value_map goal_scope ~default:(Ok None) ~f:(fun scope ->
          Goal_runtime_acknowledgement.prepare_factual
            t
            scope
            ~owner:mutation.owner
            ~candidate
          |> Result.map ~f:Option.some)
      in
      let preparation_owner =
        Option.filter selected_preparation ~f:(fun preparation ->
          Option.exists t.run_preparation ~f:(Preparation_owner.same preparation)
          && Result.is_ok
               (Preparation_owner.check_basis
                  preparation
                  ~owner:t.run_preparation_owner
                  ~state:t.state))
      in
      let%bind owned_inference_persistence =
        Owned_inference_persistence.prepare t ~mutation ~candidate ~preparation_owner
      in
      let%bind () =
        persist_transition
          ~owned_inference_persistence
          ~check_before_commit:(fun () ->
            let%bind () =
              Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check ->
                check ())
            in
            let%bind () = owned_graph_basis t mutation in
            let%bind () =
              Option.value_map
                goal_runtime_acknowledgement
                ~default:(Ok ())
                ~f:(fun acknowledgement ->
                  Goal_runtime_acknowledgement.check_factual
                    acknowledgement
                    ~actor:t
                    ~owner:mutation.owner
                    ~candidate)
            in
            let%bind () =
              match preparation_owner with
              | None -> Ok ()
              | Some preparation ->
                if Option.exists t.run_preparation ~f:(Preparation_owner.same preparation)
                then
                  Preparation_owner.check_basis
                    preparation
                    ~owner:t.run_preparation_owner
                    ~state:t.state
                else
                  Error
                    (error Conflict "constructor factual preparation changed before ACK")
            in
            if Int64.equal revision t.state.counters.revision
            then Ok ()
            else Error (error Conflict "held input ledger basis changed before ACK"))
          t
          candidate
      in
      install_committed_transition_owned
        ?goal_runtime_acknowledgement
        ~preparation_owner
        t
        candidate;
      install_input_graph_acknowledgement t mutation;
      publish_committed_transition t candidate;
      Ok ())
;;

let validate_inference_owner t (owner : Inference_owner.t) =
  if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
  then Error (error Conflict "inference owner belongs to another Eio domain")
  else if not (phys_equal t.inference_owner_identity (Graph_owner.issuing_actor owner))
  then Error (error Conflict "inference owner belongs to another actor")
  else if not (owns_inference_graph t owner)
  then Error (error Conflict "inference graph owner is no longer active")
  else Ok ()
;;

let validate_inference_usage_owner t owner =
  let open Result.Let_syntax in
  let%bind current = Graph_owner.Native_join.current owner in
  match Graph_owner.phase owner, current with
  | Finished, Some acknowledgement ->
    if phys_equal t.inference_owner_identity (Graph_owner.issuing_actor owner)
    then Graph_owner.Native_join.check_acknowledgement owner acknowledgement
    else Error (error Conflict "finished inference graph belongs to another Actor")
  | (Open | Sealed), _ | Finished, None -> validate_inference_owner t owner
;;

let capture_inference_usage t selected =
  let open Result.Let_syntax in
  let%bind () =
    if Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Conflict "inference facts belong to another Eio domain")
  in
  let%bind owners =
    match selected with
    | None -> Ok (inference_graph_owners t)
    | Some owner ->
      let%map () = validate_inference_usage_owner t owner in
      [ owner ]
  in
  let collect owners =
    let duties = ref (Ok []) in
    List.iter owners ~f:(fun owner ->
      Graph_owner.iter_factual_usage owner ~f:(fun duty ->
        duties
        := let%bind current = !duties in
           let%map confirmed =
             Inference_graph_owner.Factual_usage.Host.initial_confirmed duty
           in
           (duty, confirmed) :: current));
    Result.map !duties ~f:List.rev
  in
  let%bind initials = collect (inference_graph_owners t) in
  let%map duties =
    match selected with
    | None -> Ok initials
    | Some _ -> collect owners
  in
  { Inference_usage_snapshot.ledger_revision =
      Inference_ledger.revision t.state.inference_ledger
  ; initials
  ; duties
  }
;;

let inference_usage_is_settled t selected =
  let open Result.Let_syntax in
  let%bind snapshot = capture_inference_usage t selected in
  let%map clean =
    List.fold_result snapshot.duties ~init:true ~f:(fun clean (duty, _) ->
      let%map pending = Inference_graph_owner.Factual_usage.Host.pending duty in
      clean && not pending)
  in
  if clean
  then (
    (* Settled absent-row Joined cells must leave before a later canonical ACK
       invalidates its conservatively retained factual registrations again. *)
    let owners =
      Option.value_map selected ~default:(inference_graph_owners t) ~f:List.return
    in
    List.iter owners ~f:(fun owner ->
      Graph_owner.retain_joined owner t.state.inference_ledger));
  clean
;;

let require_settled_inference_usage t =
  let open Result.Let_syntax in
  let%bind clean = inference_usage_is_settled t None in
  if clean
  then Ok ()
  else
    Error
      (Agent_protocol.Error.create
         Conflict
         ~message:"inference facts require initial confirmation or usage settlement"
         ~retryable:true
         ())
;;

let require_selected_execution t = t.ordinary_execution_admission ()

let require_selected_or_held_execution t preparation =
  match held_startup_effect t preparation with
  | Some check -> check ()
  | None -> require_selected_execution t
;;

let open_inference_owner t source =
  if
    List.exists t.inference_owners ~f:(fun custody ->
      let owner = Inference_graph_custody.owner custody in
      Transcript.Source_id.equal (Graph_owner.source owner) source)
  then Error (error Conflict "inference graph source is already owned")
  else
    let open Result.Let_syntax in
    let%bind qualified_source =
      Inference_ledger.qualify_source t.state.inference_ledger source
      |> Result.map_error ~f:inference_error
    in
    let owner =
      Graph_owner.create
        ~issuing_actor:t.inference_owner_identity
        ~source
        ~generation:t.state.identity.generation
        ~qualified_source
    in
    exclude_effect_deferred t Ordinary_execution;
    t.inference_owners <- Inference_graph_custody.create ~owner :: t.inference_owners;
    Ok owner
;;

let inference_registration t owner handle =
  let open Result.Let_syntax in
  let%bind () = validate_inference_owner t owner in
  match
    Graph_owner.registration owner ~ordinal:(Inference_ledger.Handle.ordinal handle)
  with
  | Some registration
    when Inference_ledger.Handle.equal
           (Inference_owner.Registration.handle registration)
           handle -> Ok registration
  | Some _ | None -> Error (error Conflict "inference handle is not owned by this graph")
;;

(* Classify only the actual immutable child Spec and retained origin. Historical
   absence in a delegated session is never an Unrelated admission. *)
let inference_requires_descendant_admission t origin_observation =
  match inherited_turn_required t.state with
  | Ordinary -> Ok false
  | Scoped -> Ok true
  | Need_private_origin ->
    let open Result.Let_syntax in
    let%bind observed =
      Result.of_option
        origin_observation
        ~error:
          (error
             Permission_denied
             "delegated inference requires actual private origin observation")
    in
    let%map () = check_descendant_origin_observation t observed in
    false
;;

let require_ordinary_inference_admission t =
  let%bind.Result inherited = inference_requires_descendant_admission t None in
  if inherited
  then
    Error
      (error
         Permission_denied
         "inherited inference requires its guard-preserving allocation port")
  else Ok ()
;;

let admit_inference
      ?run_preparation
      t
      owner
      relation
      operation_id
      invocation_id
      configuration
  =
  let open Result.Let_syntax in
  let%bind () = require_settled_inference_usage t in
  let%bind () = require_ordinary_inference_admission t in
  let%bind () = validate_inference_owner t owner in
  let%bind () =
    if
      Int.equal (Graph_owner.generation owner) t.state.identity.generation
      &&
      match Graph_owner.phase owner with
      | Open -> true
      | Sealed | Finished -> false
    then Ok ()
    else Error (error Conflict "inference graph excludes new attempts")
  in
  let%bind protected_ordinals =
    Canonical_usage_update.protected_ordinals
      ?policy_usage:t.state.policy_canonical_usage
      t.state.inference_ledger
      ~accounts:t.state.goal_accounts
      ~delegated_usage:t.state.delegated_usage
  in
  let%bind ledger, handle, _tracking =
    Inference_ledger.admit
      ~protected_ordinals
      t.state.inference_ledger
      ~source:(Graph_owner.source owner)
      ~relation
      ~operation_id
      ~invocation_id
      ~configuration
    |> Result.map_error ~f:inference_error
  in
  let%bind () = commit_inference_ledger ?run_preparation t ledger in
  Graph_owner.register
    owner
    ~initial_preparation:run_preparation
    ~handle
    ~configuration
    ~goal_id:None;
  Ok handle
;;

let validate_inference_attempt registration attempt =
  if
    Transcript.Scope.equal
      (Inference_ledger.Handle.scope (Inference_owner.Registration.handle registration))
      (Inference_runtime.Attempt.scope attempt)
    && Inference.Observation.Observation_id.equal
         (Inference_ledger.Handle.accounting_id
            (Inference_owner.Registration.handle registration))
         (Inference_runtime.Attempt.accounting_id attempt)
    && Inference.Observation.Configuration.equal
         (Inference_owner.Registration.configuration registration)
         (Inference_runtime.Attempt.configuration attempt)
  then Ok ()
  else Error (error Conflict "inference attempt differs from its admitted identity")
;;

let acknowledge_inference ?owned_graph ?run_preparation t owner handle attempt =
  let open Result.Let_syntax in
  let%bind registration = inference_registration t owner handle in
  let%bind () = validate_inference_attempt registration attempt in
  let recovery_attempts =
    Recovery_effective_receipts.acknowledge t.state handle |> Option.to_list
  in
  let%bind () =
    if
      List.is_empty recovery_attempts
      || phys_equal
           (Inference_owner.Registration.configuration registration)
           (Inference_runtime.Attempt.configuration attempt)
    then Ok ()
    else Error (error Conflict "recovery acknowledgement is from another prepared configuration")
  in
  let%bind ledger =
    Inference_ledger.set_state t.state.inference_ledger handle Running
    |> Result.map_error ~f:inference_error
  in
  let owned_graph =
    match owned_graph with
    | Some _ -> owned_graph
    | None -> Some (select_factual_graph t owner (Acknowledge (registration, attempt)))
  in
  (match owned_graph with
   | None -> Inference_owner.Registration.acknowledge registration attempt
   | Some _ -> ());
  commit_inference_ledger ?owned_graph ?run_preparation ~recovery_attempts t ledger
;;

let observe_inference ?owned_graph ?run_preparation t handle incoming =
  let open Result.Let_syntax in
  let%bind ledger, _disposition =
    Inference_ledger.observe t.state.inference_ledger handle incoming
    |> Result.map_error ~f:inference_error
  in
  let owned_graph =
    match owned_graph with
    | Some _ -> owned_graph
    | None -> factual_graph_for_handle t handle
  in
  let%bind () =
    match owned_graph with
    | None -> Ok ()
    | Some mutation ->
      if Option.is_some (Graph_owner.retained_registration mutation.owner handle)
      then Ok ()
      else Error (error Conflict "observation has no exact retained graph membership")
  in
  commit_inference_ledger ?owned_graph ?run_preparation t ledger
;;

let observe_owned_inference ?owned_graph ?run_preparation t owner incoming =
  let open Result.Let_syntax in
  let%bind () = validate_inference_owner t owner in
  let scope = Inference.Observation.scope incoming in
  let owner_matches =
    match Graph_owner.phase owner, Graph_owner.qualified_source owner with
    | (Open | Sealed), Some source ->
      Transcript.Source_id.equal source (Transcript.Scope.key scope).source
    | Finished, _ | _, None -> false
  in
  let%bind () =
    if owner_matches
    then Ok ()
    else Error (error Conflict "observation does not belong to a live inference graph")
  in
  match
    List.find (Inference_ledger.rows t.state.inference_ledger) ~f:(fun row ->
      let handle = Inference_ledger.Row.handle row in
      Int.equal (Graph_owner.generation owner) (Inference_ledger.Handle.generation handle)
      && Transcript.Scope.equal scope (Inference_ledger.Handle.scope handle))
  with
  | None -> Error (error Conflict "observation has no retained admitted scope")
  | Some row ->
    let%bind () =
      if
        Option.is_some
          (Graph_owner.retained_registration owner (Inference_ledger.Row.handle row))
      then Ok ()
      else Error (error Conflict "observation has no exact retained graph membership")
    in
    let owned_graph =
      match owned_graph with
      | Some _ -> owned_graph
      | None -> Some (select_factual_graph t owner Preserve)
    in
    observe_inference
      ?owned_graph
      ?run_preparation
      t
      (Inference_ledger.Row.handle row)
      incoming
;;

let complete_inference ?owned_graph ?run_preparation t owner handle completion =
  let open Result.Let_syntax in
  let%bind registration = inference_registration t owner handle in
  let%bind () =
    validate_inference_attempt
      registration
      (Inference_client.Completion.attempt completion)
  in
  let state =
    match Inference_client.Completion.outcome completion with
    | Returned terminal -> Inference.Observation.Attempt_record.Terminal terminal
    | Interrupted { reason; delivery } -> Interrupted { reason; delivery }
  in
  let%bind ledger =
    Inference_ledger.set_state t.state.inference_ledger handle state
    |> Result.map_error ~f:inference_error
  in
  let owned_graph =
    match owned_graph with
    | Some _ -> owned_graph
    | None -> Some (select_factual_graph t owner Preserve)
  in
  let recovery_attempts =
    Recovery_effective_receipts.complete t.state handle completion |> Option.to_list
  in
  let%bind () =
    if
      List.is_empty recovery_attempts
      || Option.exists
           (Inference_owner.Registration.attempt registration)
           ~f:(phys_equal (Inference_client.Completion.attempt completion))
    then Ok ()
    else Error (error Conflict "completion is from another actual recovery attempt")
  in
  let%map () =
    commit_inference_ledger ?owned_graph ?run_preparation ~recovery_attempts t ledger
  in
  (* A stored ordinal can be replayed as data. The live cut also requires the
     same physical attempt whose completion the graph just acknowledged. *)
  if not (List.is_empty recovery_attempts)
  then
    Option.iter t.foreground_publication ~f:(fun publication ->
      let operation = Inference_ledger.Handle.operation_id handle in
      if
        Option.equal
          Agent_protocol.Id.Operation.equal
          operation
          (Some publication.operation.id)
        && Foreground_publication.matches
             publication
             ~selected:t.foreground_publication
             ~state:t.state
      then
        publication.finished_root <- Some (Inference_client.Completion.attempt completion))
;;

let interrupt_inference_row ledger handle ~delivery =
  let interrupt fallback =
    Inference_ledger.set_state
      ledger
      handle
      (Interrupted
         { reason = Host_interrupted; delivery = Option.value delivery ~default:fallback })
    |> Result.map_error ~f:inference_error
  in
  match
    Inference_ledger.find ledger ~ordinal:(Inference_ledger.Handle.ordinal handle)
  with
  | None -> Ok ledger
  | Some row ->
    (match
       Inference.Observation.Attempt_record.state (Inference_ledger.Row.record row)
     with
     | Terminal _ | Interrupted _ -> Ok ledger
     | Prepared -> interrupt Inference.Event.Terminal.Definitely_not_submitted
     | Running -> interrupt Inference.Event.Terminal.Possibly_submitted)
;;

let release_inference ?owned_graph ?run_preparation t owner handle =
  let open Result.Let_syntax in
  let%bind registration = inference_registration t owner handle in
  let delivery =
    Option.map
      (Inference_owner.Registration.attempt registration)
      ~f:Inference_runtime.Attempt.delivery
  in
  let%bind ledger = interrupt_inference_row t.state.inference_ledger handle ~delivery in
  let recovery_attempts =
    Recovery_effective_receipts.release t.state handle ~delivery |> Option.to_list
  in
  let owned_graph =
    match owned_graph with
    | Some _ -> owned_graph
    | None -> Some (select_factual_graph t owner Preserve)
  in
  let%map () = commit_inference_ledger ?owned_graph ?run_preparation ~recovery_attempts t ledger in
  Graph_owner.release
    owner
    ~ledger:t.state.inference_ledger
    ~ordinal:(Inference_ledger.Handle.ordinal handle)
;;

let seal_inference_owner t owner =
  let open Result.Let_syntax in
  let%bind current = Graph_owner.Native_join.current owner in
  match Graph_owner.phase owner, current with
  | Finished, Some acknowledgement ->
    let%bind () = validate_inference_usage_owner t owner in
    Graph_owner.Native_join.check_acknowledgement owner acknowledgement
  | (Open | Sealed), _ | Finished, None ->
    let%map () = validate_inference_owner t owner in
    Graph_owner.seal owner
;;

let finish_inference_owner ?owned_graph ?run_preparation t owner =
  let open Result.Let_syntax in
  let%bind current = Graph_owner.Native_join.current owner in
  let%bind () =
    match Graph_owner.phase owner, current with
    | Finished, Some acknowledgement ->
      let%bind () = validate_inference_usage_owner t owner in
      Graph_owner.Native_join.check_acknowledgement owner acknowledgement
    | (Open | Sealed), _ | Finished, None ->
      let%bind () = validate_inference_owner t owner in
      Option.value_map owned_graph ~default:(Ok ()) ~f:(owned_graph_basis t)
  in
  match current with
  | Some acknowledgement -> Ok acknowledgement
  | None ->
    let%bind () =
      match Graph_owner.phase owner with
      | Open -> Error (error Conflict "inference graph must exclude calls before joining")
      | Sealed -> Ok ()
      | Finished -> Error (error Conflict "inference graph already finished")
    in
    let%bind ledger =
      List.fold_result
        (Inference_ledger.rows t.state.inference_ledger)
        ~init:t.state.inference_ledger
        ~f:(fun ledger row ->
          let handle = Inference_ledger.Row.handle row in
          match
            Graph_owner.registration
              owner
              ~ordinal:(Inference_ledger.Handle.ordinal handle)
          with
          | Some registration
            when Inference_ledger.Handle.equal
                   (Inference_owner.Registration.handle registration)
                   handle ->
            interrupt_inference_row
              ledger
              handle
              ~delivery:
                (Option.map
                   (Inference_owner.Registration.attempt registration)
                   ~f:Inference_runtime.Attempt.delivery)
          | Some _ | None -> Ok ledger)
    in
    let%bind custody =
      Result.of_option
        (find_inference_graph_custody t owner)
        ~error:(error Conflict "native finish has no exact Actor graph custody")
    in
    let mutation =
      match owned_graph with
      | Some mutation -> mutation
      | None -> select_factual_graph t owner Preserve
    in
    let%bind () = owned_graph_basis t mutation in
    let%bind native = Graph_owner.Native_join.prepare owner ~ledger_after:ledger in
    let acknowledgement = Graph_owner.Native_join.acknowledgement native in
    let%bind installation =
      Inference_native_finish_installation.prepare
        t
        ~custody
        ~scope:mutation.scope
        ~native
    in
    let mutation =
      { mutation with
        Owned_inference_mutation.acknowledgement = Native_join installation
      }
    in
    let recovery_attempts =
      if Option.is_none t.state.recovery_effective
      then []
      else (
        let receipts = ref [] in
        Graph_owner.iter_registrations owner ~f:(fun registration ->
          let handle = Inference_owner.Registration.handle registration in
          let delivery =
            Option.map (Inference_owner.Registration.attempt registration)
              ~f:Inference_runtime.Attempt.delivery
          in
          Option.iter (Recovery_effective_receipts.release t.state handle ~delivery)
            ~f:(fun receipt -> receipts := receipt :: !receipts));
        List.rev !receipts)
    in
    let%map () =
      commit_inference_ledger
        ~owned_graph:mutation
        ?run_preparation
        ~recovery_attempts
        ~check_before_commit:(fun () ->
          Inference_native_finish_installation.check_basis installation ~actor:t)
        t
        ledger
    in
    acknowledgement
;;

let clear_finished_inference_owner ?owned_graph t owner acknowledgement =
  let open Result.Let_syntax in
  let%bind () = validate_inference_usage_owner t owner in
  let%bind () = Graph_owner.Native_join.check_acknowledgement owner acknowledgement in
  match Graph_owner.phase owner with
  | Finished -> Ok ()
  | Open -> Error (error Conflict "inference graph is not sealed for final clear")
  | Sealed ->
    let%bind custody =
      Result.of_option
        (find_inference_graph_custody t owner)
        ~error:(error Conflict "finished inference lost its actual graph custody")
    in
    let%bind finish =
      Result.of_option
        custody.native_finish
        ~error:(error Conflict "finished inference has no installed scope custody")
    in
    let%bind () =
      Graph_owner.Native_join.check_acknowledgement owner finish.acknowledgement
    in
    let%bind () =
      Option.value_map owned_graph ~default:(Ok ()) ~f:(owned_graph_basis t)
    in
    let mutation =
      { Owned_inference_mutation.scope = finish.scope; owner; acknowledgement = Finish }
    in
    let%bind () = owned_graph_basis t mutation in
    let active = ref false in
    Graph_owner.iter_registrations owner ~f:(fun _ -> active := true);
    let%bind clean = inference_usage_is_settled t (Some owner) in
    if clean && not !active
    then (
      install_input_graph_acknowledgement t mutation;
      Ok ())
    else
      Error
        (Agent_protocol.Error.create
           Conflict
           ~message:"inference graph retains unjoined work or unsettled facts"
           ~retryable:true
           ())
;;

let finalize_inference_usage t =
  let open Result.Let_syntax in
  let%bind clean = inference_usage_is_settled t None in
  if not clean
  then Error (error Conflict "inference facts changed before final cleanup")
  else
    List.fold_result t.inference_owners ~init:() ~f:(fun () custody ->
      let owner = Inference_graph_custody.owner custody in
      let%bind current = Graph_owner.Native_join.current owner in
      match current with
      | None -> Ok ()
      | Some acknowledgement ->
        (* Only a previously requested native finish has this installed ACK.
           Empty registrations alone are never treated as producer join. *)
        clear_finished_inference_owner t owner acknowledgement)
;;

let input_graph_request
  : type a. t -> a Input_graph_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  let open Result.Let_syntax in
  match request with
  | Open (scope, source) ->
    let%bind () = input_scope_basis t scope in
    let%bind () = Held_input_scope.parsing scope in
    let%bind () = check_held_effect scope.continuation in
    let%bind () = input_scope_basis t scope in
    let%map owner = open_inference_owner t source in
    scope.graphs <- owner :: scope.graphs;
    owner
  | Acknowledge (scope, owner, handle, attempt) ->
    let%bind () = input_graph_basis t scope owner in
    let%bind registration = inference_registration t owner handle in
    let%bind () = validate_inference_attempt registration attempt in
    let%bind ledger =
      Inference_ledger.set_state t.state.inference_ledger handle Running
      |> Result.map_error ~f:inference_error
    in
    commit_inference_ledger
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope
          ; owner
          ; acknowledgement = Acknowledge (registration, attempt)
          }
      t
      ledger
  | Observe (scope, owner, handle, incoming) ->
    let%bind _ = inference_registration t owner handle in
    let%bind () = input_graph_basis t scope owner in
    observe_inference
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope; owner; acknowledgement = Preserve }
      t
      handle
      incoming
  | Observe_owned (scope, owner, incoming) ->
    let%bind () = input_graph_basis t scope owner in
    observe_owned_inference
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope; owner; acknowledgement = Preserve }
      t
      owner
      incoming
  | Complete (scope, owner, handle, completion) ->
    let%bind () = input_graph_basis t scope owner in
    complete_inference
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope; owner; acknowledgement = Preserve }
      t
      owner
      handle
      completion
  | Release (scope, owner, handle) ->
    let%bind () = input_graph_basis t scope owner in
    release_inference
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope; owner; acknowledgement = Preserve }
      t
      owner
      handle
  | Seal (scope, owner) ->
    let%bind () = validate_inference_usage_owner t owner in
    let%bind () =
      match Graph_owner.phase owner with
      | Finished -> Ok ()
      | Open | Sealed -> input_graph_basis t scope owner
    in
    seal_inference_owner t owner
  | Finish (scope, owner) ->
    finish_inference_owner
      ~owned_graph:
        Owned_inference_mutation.
          { scope = Input scope; owner; acknowledgement = Preserve }
      t
      owner
  | Clear_finished (scope, owner, acknowledgement) ->
    clear_finished_inference_owner
      ~owned_graph:
        Owned_inference_mutation.{ scope = Input scope; owner; acknowledgement = Finish }
      t
      owner
      acknowledgement
;;

let reconcile_inference_recovery t =
  let open Result.Let_syntax in
  let%bind () =
    if List.is_empty t.inference_owners
    then Ok ()
    else Error (error Conflict "live inference graphs must join before recovery")
  in
  let%bind ledger =
    List.fold_result
      (Inference_ledger.rows t.state.inference_ledger)
      ~init:t.state.inference_ledger
      ~f:(fun ledger row ->
        interrupt_inference_row ledger (Inference_ledger.Row.handle row) ~delivery:None)
  in
  let recovery_attempts = Recovery_effective_receipts.recover t.state in
  commit_inference_ledger ~recovery_attempts t ledger
;;

let abort_staged_work t ~owner =
  Staged_jobs.abort_owner t.staged_jobs ~owner;
  Staged_subscriptions.release_owner t.staged_subscriptions ~owner;
  Staged_ingress.release_owner t.staged_ingress ~owner;
  Staged_schedules.release_owner t.staged_schedules ~owner;
  Legacy_schedule_custody.Staged.release_owner t.staged_schedule_custody ~owner;
  Ingress_creator_custody.Staged.release_owner t.staged_ingress_custody ~owner;
  Staged_notifications.release_owner t.staged_notifications ~owner;
  sync_extension_clock t
;;

let abort_all_staged_work t =
  Staged_jobs.abort_all t.staged_jobs;
  Staged_subscriptions.abort_all t.staged_subscriptions;
  Staged_ingress.abort_all t.staged_ingress;
  Staged_schedules.abort_all t.staged_schedules;
  Legacy_schedule_custody.Staged.abort_all t.staged_schedule_custody;
  Ingress_creator_custody.Staged.abort_all t.staged_ingress_custody;
  Staged_notifications.abort_all t.staged_notifications;
  sync_extension_clock t
;;

let with_staged_transaction t owner f =
  match f () with
  | Ok _ as result ->
    Staged_jobs.commit t.staged_jobs ~owner;
    Staged_subscriptions.release_owner t.staged_subscriptions ~owner;
    Staged_ingress.release_owner t.staged_ingress ~owner;
    Staged_schedules.release_owner t.staged_schedules ~owner;
    Legacy_schedule_custody.Staged.release_owner t.staged_schedule_custody ~owner;
    Ingress_creator_custody.Staged.release_owner t.staged_ingress_custody ~owner;
    Staged_notifications.release_owner t.staged_notifications ~owner;
    sync_extension_clock t;
    result
  | Error _ as result ->
    abort_staged_work t ~owner;
    result
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    abort_staged_work t ~owner;
    Stdlib.Printexc.raise_with_backtrace exn backtrace
;;

let lookup_subscription t id =
  List.find t.state.subscriptions ~f:(fun subscription ->
    Agent_protocol.Id.Subscription.equal subscription.context.id id)
;;

let lookup_notification t id =
  List.find t.state.deliveries ~f:(fun value ->
    Agent_protocol.Id.Delivery.equal value.context.id id)
;;

let lookup_ingress t id =
  List.find t.state.ingress_registrations ~f:(fun value ->
    Agent_protocol.Id.Capability.equal value.External_ingress.context.id id)
;;

let ingress_subscription_lookup t subscriptions id epoch =
  let matches value =
    Agent_protocol.Id.Subscription.equal value.Agent_protocol.Subscription.context.id id
  in
  match
    List.find (subscriptions @ t.state.subscriptions) ~f:(fun value ->
      matches value && value.epoch = epoch)
  with
  | Some _ as result -> result
  | None -> List.find (List.rev subscriptions @ t.state.subscriptions) ~f:matches
;;

let selected_ingress t owner subscriptions =
  Staged_ingress.selected
    t.staged_ingress
    ~owner
    ~lookup:(lookup_ingress t)
    ~subscription:(ingress_subscription_lookup t subscriptions)
;;

(* The framing and lazy Context close over one immutable native prefix. No
   whole inventory Context is built for an unrelated ordinary birth. *)
let policy_native_prefix (state : Session_state.t) ~current_source =
  Policy_canonical_usage.Source.Native_prefix.create
    ~session_id:state.identity.session_id
    ~generation:state.identity.generation
    ~current_source
    ~events:state.moderator_executions
    ~invocations:state.invocations
    ~jobs:state.jobs
    ~runs:state.run_state
;;

(* These selectors read only the corresponding EXISTING physical owner.
   They issue no permission. Callers still authorize that exact native scope;
   Source then validates the complete named row, origin and full installation. *)
let policy_boundary classification make =
  match classification with
  | Policy_standalone_source.Classification.Unknown -> Ok None
  | Standalone_unrelated descriptor -> Result.map (make descriptor) ~f:Option.some
;;

let policy_job_boundary t (scope : job_scope) =
  let open Result.Let_syntax in
  let%bind job = job_scope_current t scope in
  let%bind row = Job_custody.find t.job_agent_custody ~job in
  match row with
  | None -> Ok None
  | Some row ->
    policy_boundary (Job_custody.Row.policy_source row) (fun descriptor ->
      Ok (Policy_canonical_usage_source.Standalone.Boundary.Job { job; descriptor }))
;;

let policy_invocation_row t id =
  List.find t.state.invocations ~f:(fun invocation ->
    Agent_protocol.Id.Invocation.equal invocation.context.id id)
  |> Result.of_option
       ~error:(error Conflict "policy Invocation owner lost its actual row")
;;

let policy_invocation_boundary t (execution : invocation_execution) =
  if List.mem t.invocation_executions execution ~equal:phys_equal
  then
    policy_boundary execution.policy_source (fun descriptor ->
      let%map.Result invocation =
        policy_invocation_row t execution.dispatched.context.id
      in
      Policy_canonical_usage_source.Standalone.Boundary.Invocation
        { invocation; descriptor })
  else Error (error Conflict "policy native Invocation owner has exited")
;;

let policy_moderator_boundary t (borrow : moderator_borrow) =
  if Option.exists t.moderator_borrow ~f:(phys_equal borrow)
  then
    policy_boundary borrow.policy_source (fun descriptor ->
      let%map.Result invocation = policy_invocation_row t borrow.invocation.context.id in
      Policy_canonical_usage_source.Standalone.Boundary.Invocation
        { invocation; descriptor })
  else Error (error Conflict "policy moderator Invocation owner has exited")
;;

let policy_event_boundary t (borrow : queued_event_borrow) =
  if Option.exists t.queued_event_borrow ~f:(phys_equal borrow)
  then
    policy_boundary borrow.policy_source (fun descriptor ->
      let%map.Result event =
        List.find t.state.moderator_executions ~f:(fun event ->
          Agent_protocol.Id.Moderator_execution.equal
            event.context.id
            borrow.receipt.context.id)
        |> Result.of_option
             ~error:(error Conflict "policy Event owner lost its actual row")
      in
      Policy_canonical_usage_source.Standalone.Boundary.Event { event; descriptor })
  else Error (error Conflict "policy Event owner has exited")
;;

let policy_boundary_of_invocation_owner t = function
  | Foreground _ -> Ok None
  | Invocation_moderator borrow -> policy_moderator_boundary t borrow
  | Event_moderator borrow -> policy_event_boundary t borrow
  | Background_job scope -> policy_job_boundary t scope
;;

let policy_boundary_of_execution t = function
  | Inference_operation _
  | Inference_held_input _
  | Inference_initialization _
  | Inference_initialization_job _ -> Ok None
  | Inference_invocation execution -> policy_invocation_boundary t execution
  | Inference_moderator borrow -> policy_moderator_boundary t borrow
  | Inference_event borrow -> policy_event_boundary t borrow
  | Inference_job scope -> policy_job_boundary t scope
;;

(* Caller association uses the SAME existing owner selector as births. The
   actual issuer/currentness guard remains with the Caller consumer. *)
let policy_boundary_of_caller_owner t (owner : Delegated_policy_caller_custody.Owner.t) =
  match owner with
  | Operation _ -> Ok None
  | Invocation id ->
    (match
       List.find t.invocation_executions ~f:(fun execution ->
         Agent_protocol.Id.Invocation.equal execution.dispatched.context.id id)
     with
     | Some execution -> policy_invocation_boundary t execution
     | None ->
       (match t.moderator_borrow with
        | Some borrow
          when Agent_protocol.Id.Invocation.equal borrow.invocation.context.id id ->
          policy_moderator_boundary t borrow
        | None | Some _ ->
          Error (error Conflict "policy Caller Invocation owner has exited")))
  | Moderator_event id ->
    (match t.queued_event_borrow with
     | Some borrow
       when Agent_protocol.Id.Moderator_execution.equal borrow.receipt.context.id id ->
       policy_event_boundary t borrow
     | None | Some _ -> Error (error Conflict "policy Caller Event owner has exited"))
;;

let policy_boundary_of_background_owner t = function
  | Agent_protocol.Job.Moderator_event id ->
    (match t.queued_event_borrow with
     | Some borrow
       when Agent_protocol.Id.Moderator_execution.equal borrow.receipt.context.id id ->
       policy_event_boundary t borrow
     | None | Some _ -> Error (error Conflict "policy Job Event owner has exited"))
  | Invocation id ->
    (match
       List.find t.invocation_executions ~f:(fun execution ->
         Agent_protocol.Id.Invocation.equal execution.dispatched.context.id id)
     with
     | Some execution -> policy_invocation_boundary t execution
     | None ->
       (match t.moderator_borrow with
        | Some borrow
          when Agent_protocol.Id.Invocation.equal borrow.invocation.context.id id ->
          policy_moderator_boundary t borrow
        | None | Some _ -> Error (error Conflict "policy Job Invocation owner has exited")))
;;

let policy_birth_result boundary ~ordinary ~standalone =
  match boundary with
  | None ->
    Result.map (ordinary ()) ~f:(fun update ->
      update, Policy_standalone_source.Classification.Unknown)
  | Some boundary ->
    let%map.Result birth = standalone boundary in
    ( Policy_canonical_usage_source.Standalone.Birth.update birth
    , Policy_canonical_usage_source.Standalone.Birth.classification birth )
;;

let policy_invocation_birth accounting ~prefix ~before ~boundary invocation =
  policy_birth_result
    boundary
    ~ordinary:(fun () ->
      Policy_canonical_usage.Source.invocation_birth accounting ~prefix ~before invocation)
