let policy_birth_update state ~current_source prepare row =
  let%bind.Result prefix = policy_native_prefix state ~current_source in
  prepare
    state.Session_state.policy_canonical_usage
    ~prefix
    ~before:(fun () -> Session_state.policy_context state)
    row
;;

let policy_birth_metadata t prepare row =
  let open Result.Let_syntax in
  let state = t.state in
  let%bind current_source = observation_source t in
  let%map update, classification =
    policy_birth_update state ~current_source prepare row
  in
  ( Option.to_list
      (Option.map update ~f:(fun update -> Session_delta.Policy_cause_changed update))
  , classification )
;;

(* Queue claims use the SAME retained Row/Entry before any transfer. A positive
   standalone descriptor already proves that exact producer's policy ancestry;
   a decoded/missing Row remains Unknown and cannot acquire that exception. *)
let queued_event_policy_metadata t receipt =
  let open Result.Let_syntax in
  match receipt.Agent_protocol.Moderator_execution.queue_occurrence with
  | None ->
    (* Modern external/manual receipts may have no structural queue occurrence.
       They retain their existing native framing, not a guessed queue producer. *)
    Ok []
  | Some _ ->
    let%bind _, source = Moderator_source_installation.capture t.state in
    let%bind metadata = Moderator_checkpoint.queue t.state.moderator in
    let selected =
      match metadata, t.moderator_manager with
      | Some metadata, Some manager ->
        Option.bind
          (List.hd (Moderator_queue.entries metadata))
          ~f:(fun entry ->
            Option.map
              (Legacy_queue_custody.find t.legacy_queue_custody ~manager ~source ~entry)
              ~f:(fun row -> entry, row))
      | (None | Some _), None | None, Some _ -> None
    in
    let%bind classification =
      match selected with
      | None -> Ok Policy_standalone_source.Classification.Unknown
      | Some (entry, row) ->
        Policy_queue_source.claim
          ~state:t.state
          ~source
          ~entry
          ~receipt
          (Legacy_queue_custody.Row.policy_source row)
    in
    (match classification with
     | Standalone_unrelated _ -> Ok []
     | Unknown ->
       let%bind current_source = observation_source t in
       let%bind prefix = policy_native_prefix t.state ~current_source in
       let%map update =
         Policy_canonical_usage.Source.queued_event_birth
           t.state.policy_canonical_usage
           ~prefix
           ~before:(fun () -> Session_state.policy_context t.state)
           receipt
       in
       Option.to_list
         (Option.map update ~f:(fun update -> Session_delta.Policy_cause_changed update)))
;;

let selected_job_policy_changes t owner jobs =
  let open Result.Let_syntax in
  match jobs with
  | [] -> Ok []
  | _ :: _ ->
    let%bind current_source = observation_source t in
    let%bind boundary = policy_boundary_of_background_owner t owner in
    let%map _, reversed =
      List.fold_result jobs ~init:(t.state, []) ~f:(fun (state, reversed) job ->
        let%map update, _ =
          policy_birth_update state ~current_source (policy_async_job_birth ~boundary) job
        in
        let policy_canonical_usage =
          match update with
          | None -> state.Session_state.policy_canonical_usage
          | Some update -> Some (Policy_canonical_usage.Update.candidate update)
        in
        (* Pure ordered DATA only; the independently staged Fresh loan owns the
           SAME birth classification and its exact selected Job ACK. *)
        let next = { state with jobs = job :: state.jobs; policy_canonical_usage } in
        let reversed = Session_delta.Job_changed job :: reversed in
        let reversed =
          match update with
          | None -> reversed
          | Some update -> Session_delta.Policy_cause_changed update :: reversed
        in
        next, reversed)
    in
    List.rev reversed
;;

let staged_work_changes t owner =
  let open Result.Let_syntax in
  let%bind subscriptions =
    Staged_subscriptions.selected
      t.staged_subscriptions
      ~owner
      ~lookup:(lookup_subscription t)
  in
  let%bind registrations = selected_ingress t owner subscriptions in
  let%bind () =
    List.fold_result registrations ~init:() ~f:(fun () value ->
      match lookup_ingress t value.External_ingress.context.id with
      | Some _ -> Ok ()
      | None ->
        let%bind due =
          Extension_clock.is_due
            t.extension_clock
            (Subscription value.context.subscription_id)
            ~now:(t.services.monotonic_now ())
        in
        (match
           (not due)
           && Agent_protocol.Timestamp.compare
                (t.services.now ())
                value.context.expires_at
              < 0
         with
         | true -> Ok ()
         | false ->
           Error
             (error Conflict "ingress subscription expired before registration commit")))
  in
  let%bind () =
    match
      List.exists registrations ~f:(fun value ->
        Option.is_none (lookup_ingress t value.External_ingress.context.id))
    with
    | false -> Ok ()
    | true ->
      Staged_ingress.check_capacity
        ~limits:t.services.ingress_limits
        ~generation:t.state.identity.generation
        ~now:(t.services.now ())
        ~subscriptions:(t.state.subscriptions @ subscriptions)
        ~values:(t.state.ingress_registrations @ registrations)
  in
  let%bind schedules =
    Staged_schedules.selected t.staged_schedules ~owner ~lookup:(fun id ->
      List.find t.state.schedules ~f:(fun value ->
        Agent_protocol.Id.Schedule.equal value.id id))
  in
  let%bind notifications =
    Staged_notifications.selected
      t.staged_notifications
      ~owner
      ~lookup:(lookup_notification t)
  in
  let jobs = Staged_jobs.selected t.staged_jobs ~owner in
  let%map changes = selected_job_policy_changes t owner jobs in
  ( changes
    @ Staged_ingress.ordered_changes ~subscriptions ~registrations
    @ List.map schedules ~f:(fun schedule -> Session_delta.Schedule_changed schedule)
    @ List.map notifications ~f:(fun delivery -> Session_delta.Delivery_changed delivery)
  , List.map jobs ~f:(fun job ->
      Agent_protocol.Event.Durable.Payload.Job_state_changed job)
    @ List.map schedules ~f:(fun schedule ->
      Agent_protocol.Event.Durable.Payload.Schedule_state_changed schedule) )
;;

(* The DATA stagers decide selection. These paired inventories only retain
   independent children of the actual creator, and are installed at the same
   checkpoint ACK before its transaction owner is released. *)
let prepare_creator_custody t ~owner ~changes =
  let open Result.Let_syntax in
  let schedules =
    Legacy_schedule_custody.Staged.selected
      t.staged_schedule_custody
      ~owner
      ~receipts:(Staged_schedules.selected_receipts t.staged_schedules ~owner)
  in
  let ingress =
    Ingress_creator_custody.Staged.selected
      t.staged_ingress_custody
      ~owner
      ~receipts:(Staged_ingress.selected_receipts t.staged_ingress ~owner)
  in
  (* Keep the actual validated ordered DATA chain, including a subscription
     link and any later cancellation in this same transaction. A direct edge
     from creation to the final value need not itself be a legal transition. *)
  let schedules =
    List.map schedules ~f:(fun (created, fresh) ->
      ( List.filter_map changes ~f:(function
          | Session_delta.Schedule_changed value
            when Agent_protocol.Id.Schedule.equal
                   value.id
                   created.Agent_protocol.Schedule.id -> Some value
          | _ -> None)
      , fresh ))
  in
  let ingress =
    List.map ingress ~f:(fun (created, fresh) ->
      ( List.filter_map changes ~f:(function
          | Session_delta.Ingress_changed value
            when Agent_protocol.Id.Capability.equal
                   value.External_ingress.context.id
                   created.External_ingress.context.id -> Some value
          | _ -> None)
      , fresh ))
  in
  let schedule_changes =
    List.filter_map changes ~f:(function
      | Session_delta.Schedule_changed value -> Some value
      | _ -> None)
  in
  if List.is_empty schedules && List.is_empty ingress && List.is_empty schedule_changes
  then Ok None
  else (
    let%bind schedules =
      Legacy_schedule_custody.Update.prepare_selected
        t.legacy_schedule_custody
        ~selected:schedules
        ~changes:schedule_changes
    in
    match
      Ingress_creator_custody.Update.prepare_selected
        t.ingress_creator_custody
        ~selected:ingress
    with
    | Error failure ->
      Legacy_schedule_custody.Update.discard schedules;
      Error failure
    | Ok ingress ->
      Ok (Some (Schedule_custody_installation.Creators { schedules; ingress })))
;;

let check_creator_custody t = function
  | None | Some (Schedule_custody_installation.Inventory _) -> Ok ()
  | Some (Creators { schedules; ingress }) ->
    let open Result.Let_syntax in
    let%bind _, source = Moderator_source_installation.capture t.state in
    let%bind () =
      Legacy_schedule_custody.Update.check_before_commit
        schedules
        ~current:t.legacy_schedule_custody
        ~manager:t.moderator_manager
        ~source
    in
    Ingress_creator_custody.Update.check_before_commit
      ingress
      ~current:t.ingress_creator_custody
      ~manager:t.moderator_manager
      ~source
;;

