let stage_background_job t ~job ~capacity =
  Eio.Cancel.protect (fun () ->
    let stage () =
      let%bind.Result () =
        Option.value_map job.Agent_protocol.Job.launch ~default:(Ok ()) ~f:(fun launch ->
          match Agent_protocol.Job.Birth_parent.callback_owner launch.owner with
          | Some owner -> refresh_held_background_owner t owner
          | None ->
            Error (error Invalid_request "background Job requires a callback owner"))
      in
      call t (Stage_background_job (job, capacity))
    in
    let abort_after_failure () =
      try capacity.Staged_jobs.abort () with
      | cleanup ->
        (try
           Eio.traceln
             "background Job capacity cleanup failed: %s"
             (Exn.to_string cleanup)
         with
         | _ -> ())
    in
    match stage () with
    | Ok () -> Ok ()
    | Error _ as result ->
      abort_after_failure ();
      result
    | exception exn ->
      let backtrace = Stdlib.Printexc.get_raw_backtrace () in
      abort_after_failure ();
      Exn.raise_with_original_backtrace exn backtrace)
;;

