let commit_extensions_internal t generation expected_revision changes =
  let open Result.Let_syntax in
  if
    generation <> t.state.identity.generation
    || not (Int64.equal expected_revision t.state.counters.revision)
  then
    Error
      (error Conflict "extension transaction uses a stale session revision or generation")
  else if
    (moderator_is_borrowed t || not (List.is_empty t.invocation_executions))
    && List.exists changes ~f:(function
      | Extension_change.Moderator_state _ -> moderator_is_borrowed t
      | Invocation value ->
        List.exists t.invocation_executions ~f:(fun execution ->
          Agent_protocol.Id.Invocation.compare
            value.context.id
            execution.dispatched.context.id
          = 0)
        || Option.exists t.moderator_borrow ~f:(fun borrow ->
          Agent_protocol.Id.Invocation.compare
            value.context.id
            borrow.invocation.context.id
          = 0)
      | _ -> false)
  then Error (error Conflict "invocation callback owns this state transaction")
  else if List.is_empty changes || List.length changes > 256
  then
    Error
      (error
         Resource_limit
         "extension transaction must contain between 1 and 256 changes")
  else if
    List.exists changes ~f:(function
      | Extension_change.Publish _ -> true
      | _ -> false)
    && (Option.is_some t.state.active_operation
        || t.idle_moderator_borrowed
        || t.state.halted
        || (not
              (Agent_protocol.Session.equal_desired_state
                 t.state.lifecycle.desired
                 Running))
        ||
        match t.state.lifecycle.observed with
        | Agent_protocol.Session.Idle -> false
        | _ -> true)
  then
    Error
      (error
         Invalid_state
         "notification publication requires an idle running session safe point")
  else (
    let new_jobs = Hash_set.create (module Agent_protocol.Id.Job) in
    let new_schedules = Hash_set.create (module Agent_protocol.Id.Schedule) in
    let%bind deltas =
      List.map changes ~f:(function
        | Extension_change.Invocation value -> Ok (Session_delta.Invocation_changed value)
        | Subscription value -> Ok (Session_delta.Subscription_changed value)
        | Delivery value ->
          (match value.completion_projection with
           | Some _
             when not
                    (List.exists t.state.deliveries ~f:(fun old ->
                       Agent_protocol.Id.Delivery.equal old.context.id value.context.id))
             ->
             Error
               (error
                  Permission_denied
                  "standalone delivery requires checked adapter admission")
           | _ -> Ok (Session_delta.Delivery_changed value))
        | Publish (value, entry) ->
          let%bind () =
            match value.completion_projection with
            | Some _
              when not
                     (List.exists t.state.deliveries ~f:(fun old ->
                        Agent_protocol.Id.Delivery.equal old.context.id value.context.id))
              ->
              Error
                (error
                   Permission_denied
                   "standalone delivery requires checked adapter admission")
            | _ -> Ok ()
          in
          let%map () = Notification_history.validate ~delivery:value entry in
          Session_delta.Delivery_committed (value, entry)
        | Moderator_state value -> Ok (Session_delta.Moderator_changed value)
        | Start_job job ->
          let%bind () =
            Extension_invariants.owner
              ~session_id:t.state.identity.session_id
              ~generation
              job.session_id
              job.generation
          in
          if
            Hash_set.mem new_jobs job.id
            || List.exists t.state.jobs ~f:(fun old ->
              Agent_protocol.Id.Job.compare old.id job.id = 0)
          then Error (error Conflict "extension job identity is already admitted")
          else (
            match job.status with
            | Queued ->
              Hash_set.add new_jobs job.id;
              Ok (Session_delta.Job_changed job)
            | _ -> Error (error Invalid_state "extension job must start queued"))
        | Schedule schedule ->
          let%bind () =
            Extension_invariants.owner
              ~session_id:t.state.identity.session_id
              ~generation
              schedule.session_id
              schedule.generation
          in
          if
            Hash_set.mem new_schedules schedule.id
            || List.exists t.state.schedules ~f:(fun old ->
              Agent_protocol.Id.Schedule.compare old.id schedule.id = 0)
          then Error (error Conflict "extension schedule identity is already admitted")
          else (
            match schedule.status with
            | Scheduled ->
              Hash_set.add new_schedules schedule.id;
              Ok (Session_delta.Schedule_changed schedule)
            | _ -> Error (error Invalid_state "extension schedule must start scheduled")))
      |> Result.all
    in
    let delta = Session_delta.Batch deltas in
    let%bind candidate = Session_delta.apply t.state delta in
    let old_ids = Hash_set.create (module History_entry.Id) in
    List.iter t.state.conversation.canonical_history ~f:(fun entry ->
      Hash_set.add old_ids entry.id);
    let appended =
      List.filter candidate.conversation.canonical_history ~f:(fun entry ->
        not (Hash_set.mem old_ids entry.id))
    in
    let history_payloads =
      if List.is_empty appended
      then []
      else [ Agent_protocol.Event.Durable.Payload.History_appended appended ]
    in
    let work_payloads =
      List.filter_map changes ~f:(function
        | Extension_change.Start_job job ->
          Some (Agent_protocol.Event.Durable.Payload.Job_state_changed job)
        | Schedule schedule ->
          Some (Agent_protocol.Event.Durable.Payload.Schedule_created schedule)
        | _ -> None)
    in
    transition t ~delta ~payloads:(history_payloads @ work_payloads))
;;

let replace_operation_worker t worker ~intended_manager =
  if
    match t.policy_restoration with
    | Constructing restoration -> not restoration.closed
    | Native_constructing setup -> not setup.closed
    | Vacant | Published _ -> false
  then Error (error Conflict "policy restoration owns runtime construction")
  else if
    Option.exists t.runtime_retirement ~f:(fun retirement ->
      match Eio.Promise.peek retirement.foreground_finished with
      | Some (Ok (Ok ())) ->
        Option.is_some worker
        && (retirement.closing || Option.is_some t.state.active_operation)
      | Some (Ok (Error _) | Error _) | None -> true)
  then Error (error Conflict "cannot replace a retiring runtime")
  else if Option.is_some t.idle_completion
  then Error (error Conflict "legacy idle completion still owns its runtime")
  else if moderator_is_borrowed t
  then Error (error Conflict "cannot replace a borrowed moderator runtime")
  else (
    match worker, t.state.active_operation, t.idle_moderator_borrowed with
    | None, Some _, _ -> Error (error Conflict "cannot unload an active runtime")
    | None, None, true -> Error (error Conflict "cannot unload a borrowed moderator")
    | None, None, false
      when Option.is_some t.governed_admission_slot
           || Option.is_some t.inherited_turn_prepared
           || Option.is_some t.inherited_turn_cleanup ->
      Error
        (Agent_protocol.Error.create
           Conflict
           ~message:"cannot unload runtime with outstanding descendant admission cleanup"
           ~retryable:true
           ())
    | None, None, false | Some _, _, _ ->
      (match t.lifecycle_agent_custody with
       | Admitted { pending = Initial_pending { admission; startup }; _ }
         when not
                (Initial_lifecycle_startup.matches_runtime
                   startup
                   ~worker
                   ~manager:intended_manager) ->
         retire_agent_admission admission;
         t.lifecycle_agent_custody <- Unadmitted
       | Unadmitted | Admitted _ -> ());
      if Option.is_some t.operation_worker
      then (
        close_recurrence_activations t;
        close_bound_run_preparation t);
      let job_custody =
        Job_custody.retain_runtime t.job_agent_custody ~manager:intended_manager
      in
      let queue_custody =
        Legacy_queue_custody.retain_runtime
          t.legacy_queue_custody
          ~manager:intended_manager
      in
      let schedule_custody =
        Legacy_schedule_custody.retain_runtime
          t.legacy_schedule_custody
          ~manager:intended_manager
      in
      let ingress_custody =
        Ingress_creator_custody.retain_runtime
          t.ingress_creator_custody
          ~manager:intended_manager
      in
      Policy_restoration_data.revoke t.policy_restoration;
      t.policy_restoration <- Vacant;
      t.unmoderated_source <- None;
      t.operation_worker <- worker;
      t.inference_execution <- None;
      t.job_agent_custody
      <- Job_custody.install_retained t.job_agent_custody ~incoming:job_custody;
      t.legacy_queue_custody
      <- Legacy_queue_custody.install t.legacy_queue_custody ~incoming:queue_custody;
      t.legacy_schedule_custody
      <- Legacy_schedule_custody.install
           t.legacy_schedule_custody
           ~incoming:schedule_custody;
      t.ingress_creator_custody
      <- Ingress_creator_custody.install
           t.ingress_creator_custody
           ~incoming:ingress_custody;
      t.moderator_manager <- None;
      (match worker with
       | Some _ -> t.runtime_retirement <- None
       | None ->
         (match t.runtime_retirement with
          | Some retirement when not retirement.closing -> t.runtime_retirement <- None
          | Some _ | None -> ()));
      Ok ())
;;

let set_operation_worker t worker =
  replace_operation_worker t worker ~intended_manager:None
;;

let runtime_admission_open t =
  (not t.rollover_requires_recovery)
  && Option.is_none t.runtime_retirement
  && Option.is_none t.lifecycle_fence
  &&
  match t.policy_restoration with
  | Constructing restoration -> restoration.closed
  | Native_constructing setup -> setup.closed
  | Vacant | Published _ -> true
;;

let require_runtime_admission t =
  if runtime_admission_open t
  then Ok ()
  else Error (error Conflict "session runtime is retiring")
;;

let capture_operation_completion t operation_id =
  match t.state.active_operation, t.operation_completion with
  | Some operation, Some completion
    when Agent_protocol.Id.Operation.equal operation.id operation_id
         && Operation_completion.matches completion ~operation -> Some completion
  | (Some _ | None), (Some _ | None) -> None
;;

let finish_runtime_retirement t operation_id ~completion result =
  Option.iter t.runtime_retirement ~f:(fun retirement ->
    match retirement.pending_operation with
    | Some pending
      when Agent_protocol.Id.Operation.equal pending.operation_id operation_id
           && Option.equal phys_equal pending.completion completion ->
      retirement.pending_operation <- None;
      Eio.Promise.resolve retirement.finish_foreground result
    | Some _ | None -> ())
;;

(* Select before any retirement revoke, logical clear or cancellation. No
   current-authority refresh is appropriate for these immutable associations. *)
let capture_runtime_retirement_callback t ~operation =
  Option.bind t.queued_event_borrow ~f:(fun (borrow : queued_event_borrow) ->
    let completion = borrow.completion in
    if
      not
        (Callback_completion_data.belongs_to
           completion
           ~issuing_actor:t.initialization_owner
           ~domain:t.runtime_source_domain)
    then None
    else (
      let wrapper =
        Option.bind t.delegated_policy_claim ~f:(fun captured ->
          if
            (not
               (phys_equal
                  captured.Delegated_policy_claim_data.issuer
                  t.inference_owner_identity))
            || not (Int.equal captured.domain t.runtime_source_domain)
          then None
          else (
            match Delegated_policy_claim_state.phase captured.state with
            | (Activated attempt | Callback_acknowledged attempt)
              when phys_equal (Delegated_policy_claim_state.Attempt.borrow attempt) borrow
              -> Some captured.state
            | Waiting | Prepared _ | Activated _ | Callback_acknowledged _ | Released ->
              None))
      in
      let selected parent = Some { borrow; parent; wrapper } in
      match completion.bookkeeping with
      | Released _ ->
        (* This election does not audit already released historical callbacks. *)
        None
      | Unselected | Selected _ ->
        (match
           Callback_completion_data.actual_exit completion, borrow.terminal_selection
         with
         | Returned _, _ | Not_returned, Some _ -> selected Ended_callback
         | Not_returned, None ->
           if Option.is_some borrow.job_scope
           then None
           else (
             let foreground =
               Option.filter operation ~f:(fun (operation : Agent_protocol.Operation.t) ->
                 Agent_protocol.Id.Session.equal
                   borrow.receipt.context.session_id
                   t.state.identity.session_id
                 && Int.equal borrow.receipt.context.generation operation.generation
                 && Option.exists
                      borrow.receipt.context.operation_id
                      ~f:(Agent_protocol.Id.Operation.equal operation.id))
             in
             match foreground with
             | Some operation -> selected (Foreground_callback operation)
             | None ->
               let constructor =
                 Option.bind t.legacy_callback_scope ~f:(fun callback ->
                   if phys_equal callback.Callback_scope.borrow borrow
                   then
                     Option.filter callback.constructor_scope ~f:(fun scope ->
                       phys_equal
                         scope.Initialization_scope_data.owner
                         t.initialization_owner
                       && Int.equal scope.domain t.runtime_source_domain
                       && Option.exists t.initialization_scope ~f:(phys_equal scope))
                   else None)
               in
               (match constructor with
                | Some scope -> selected (Constructor_callback scope)
                | None ->
                  (match borrow.lifecycle_owner with
                   | Some (Initial_authored scope)
                     when phys_equal scope.issuing_actor t.inference_owner_identity
                          && Int.equal scope.domain t.runtime_source_domain
                          && Option.exists t.held_authored_start ~f:(phys_equal scope) ->
                     selected (Authored_callback scope)
                   | Some (Existing_goal_resume scope) ->
                     let preparation = scope.continuation.binding.preparation in
                     let same_preparation =
                       match t.run_preparation with
                       | Some (Existing_goal actual) -> phys_equal actual preparation
                       | None | Some (Initial _ | Delegated_load _) -> false
                     in
                     let same_scope =
                       match preparation.runtime_phase with
                       | Installed actual
                       | Callback_completed actual
                       | Handed_off (actual, _)
                       | Retired actual -> phys_equal actual scope
                       | Unclaimed
                       | Starting_writer _
                       | Starting_acknowledged
                       | Running_writer _
                       | Constructing
                       | Closed -> false
                     in
                     if
                       same_preparation
                       && same_scope
                       && phys_equal scope.issuing_actor t.inference_owner_identity
                       && Int.equal preparation.domain t.runtime_source_domain
                     then selected (Goal_callback scope)
                     else None
                   | None | Some (Initial_authored _) -> None))))))
;;

let same_runtime_retirement_cleanup_attempt left right =
  match left with
  | Idle_cleanup_attempt left ->
    (match right with
     | Idle_cleanup_attempt right -> phys_equal left.attempt right.attempt
     | Inherited_cleanup_attempt _
     | Descendant_cleanup_attempt _
     | Causal_cleanup_attempt _ -> false)
  | Inherited_cleanup_attempt left ->
    (match right with
     | Inherited_cleanup_attempt right -> phys_equal left.attempt right.attempt
     | Idle_cleanup_attempt _ | Descendant_cleanup_attempt _ | Causal_cleanup_attempt _ ->
       false)
  | Descendant_cleanup_attempt left ->
    (match right with
     | Descendant_cleanup_attempt right -> phys_equal left.attempt right.attempt
     | Idle_cleanup_attempt _ | Inherited_cleanup_attempt _ | Causal_cleanup_attempt _ ->
       false)
  | Causal_cleanup_attempt left ->
    (match right with
     | Causal_cleanup_attempt right -> phys_equal left.promise right.promise
     | Idle_cleanup_attempt _ | Inherited_cleanup_attempt _ | Descendant_cleanup_attempt _
       -> false)
;;

let capture_runtime_retirement_cleanup_attempts t =
  let attempts = ref [] in
  let add attempt =
    if not (List.exists !attempts ~f:(same_runtime_retirement_cleanup_attempt attempt))
    then attempts := attempt :: !attempts
  in
  let inherited (Inherited_turn.Pack acknowledged as selected) =
    match acknowledged.cleanup_owner with
    | Idle -> ()
    | Running attempt ->
      add (Inherited_cleanup_attempt { acknowledged = selected; attempt })
  in
  let descendant (slot : Descendant_admission_slot.t) =
    match slot.cleanup with
    | Idle -> ()
    | Running attempt -> add (Descendant_cleanup_attempt { slot; attempt })
  in
  let causal (plan : inherited_attempt_plan) (slot : Goal_causal_admission_custody.Slot.t)
    =
    match slot.cleanup with
    | Idle -> ()
    | Running promise -> add (Causal_cleanup_attempt { plan; promise })
  in
  Option.iter t.idle_completion ~f:(fun completion ->
    match completion.Idle_completion_data.cleanup with
    | Idle | Scheduling_failed _ -> ()
    | Running attempt -> add (Idle_cleanup_attempt { completion; attempt }));
  Option.iter t.inherited_turn_prepared ~f:(fun (Prepared acknowledged) ->
    inherited (Pack acknowledged));
  Option.iter t.inherited_turn_cleanup ~f:inherited;
  Option.iter t.idle_turn_continuation ~f:(fun continuation ->
    match continuation.Idle_continuation.phase with
    | Selected _ -> ()
    | Bound plan ->
      descendant plan.slot;
      (match plan.phase with
       | Writer_prepared acknowledged | Acknowledged acknowledged ->
         inherited (Pack acknowledged)
       | Pending | Closed -> ()));
  Option.iter t.governed_admission_slot ~f:(function
    | Descendant slot -> descendant slot
    | Policy_causal { causal = slot; plan } -> causal plan slot
    | Combined { descendant = slot; causal = causal_slot; plan } ->
      descendant slot;
      causal plan causal_slot);
  List.rev !attempts
;;

let capture_runtime_retirement_selection t =
  let operation = t.state.active_operation in
  let operation_completion =
    Option.bind operation ~f:(fun operation ->
      capture_operation_completion t operation.Agent_protocol.Operation.id)
  in
  let constructor_calls =
    Option.value_map t.constructor_models ~default:[] ~f:(fun group -> group.calls)
  in
  let factual_usage =
    let cells = ref [] in
    List.iter (inference_graph_owners t) ~f:(fun owner ->
      Graph_owner.iter_factual_usage owner ~f:(fun cell ->
        if not (List.exists !cells ~f:(phys_equal cell)) then cells := cell :: !cells));
    List.rev !cells
  in
  { issuing_actor = t.initialization_owner
  ; domain = t.runtime_source_domain
  ; operation
  ; selected_operation_completion = operation_completion
  ; constructor_calls
  ; callback = capture_runtime_retirement_callback t ~operation
  ; selected_idle_completion = t.idle_completion
  ; idle_continuation = t.idle_turn_continuation
  ; inherited_prepared = t.inherited_turn_prepared
  ; inherited_cleanup = t.inherited_turn_cleanup
  ; governed_slot = t.governed_admission_slot
  ; factual_usage
  ; cleanup_attempts = capture_runtime_retirement_cleanup_attempts t
  }
;;

let retire_runtime_worker t ~closing =
  (* Duplicate strengthening preserves the original election. Capture on None
     before even the legacy revoke/descendant retirement prefix can clear data. *)
  let original =
    match t.runtime_retirement with
    | Some retirement -> retirement.selection
    | None -> capture_runtime_retirement_selection t
  in
  Policy_restoration_data.revoke t.policy_restoration;
  t.unmoderated_source <- None;
  retire_descendant_host t;
  match t.runtime_retirement with
  | Some retirement ->
    retirement.closing <- retirement.closing || closing;
    Ok retirement.foreground_finished
  | None ->
    let finished, finish = Eio.Promise.create () in
    let pending_operation =
      Option.map t.state.active_operation ~f:(fun operation ->
        { Pending_runtime_operation.operation_id = operation.id
        ; completion = capture_operation_completion t operation.id
        })
    in
    close_recurrence_activations t;
    close_bound_run_preparation t;
    t.runtime_retirement
    <- Some
         { foreground_finished = finished
         ; finish_foreground = finish
         ; selection = original
         ; cleanup_holder = None
         ; pending_operation
         ; closing
         };
    Legacy_queue_custody.retire t.legacy_queue_custody;
    t.legacy_queue_custody <- Legacy_queue_custody.empty;
    Legacy_schedule_custody.retire t.legacy_schedule_custody;
    t.legacy_schedule_custody <- Legacy_schedule_custody.empty;
    Ingress_creator_custody.retire t.ingress_creator_custody;
    t.ingress_creator_custody <- Ingress_creator_custody.empty;
    t.moderator_manager <- None;
    t.job_agent_custody
    <- Job_custody.install_retained
         t.job_agent_custody
         ~incoming:(Job_custody.retain_runtime t.job_agent_custody ~manager:None);
    retire_instruction_continuations t;
    Option.iter t.operation_agent_custody ~f:Operation_owner.retire;
    Option.iter t.active_cancel ~f:(fun cancel -> cancel ());
    (match pending_operation with
     | None -> Eio.Promise.resolve finish (Ok (Ok ()))
     | Some pending ->
       Option.iter pending.completion ~f:(fun completion ->
         Option.iter (Operation_completion.outcome completion) ~f:(fun result ->
           finish_runtime_retirement
             t
             pending.operation_id
             ~completion:pending.completion
             result)));
    Ok finished
;;

let same_runtime_retirement_cleanup_target left right =
  match left, right with
  | Cleanup_constructor left, Cleanup_constructor right -> phys_equal left right
  | Cleanup_callback left, Cleanup_callback right -> phys_equal left.borrow right.borrow
  | Cleanup_idle (left, _), Cleanup_idle (right, _) -> phys_equal left right
  | Cleanup_inherited (Pack left), Cleanup_inherited (Pack right) ->
    phys_equal left.native right.native
  | Cleanup_descendant left, Cleanup_descendant right -> phys_equal left right
  | Cleanup_governed left, Cleanup_governed right -> phys_equal left right
  | Cleanup_factual left, Cleanup_factual right -> phys_equal left right
  | ( ( Cleanup_constructor _
      | Cleanup_callback _
      | Cleanup_idle _
      | Cleanup_inherited _
      | Cleanup_descendant _
      | Cleanup_governed _
      | Cleanup_factual _ )
    , _ ) -> false
;;

let runtime_retirement_original_attempt (selection : runtime_retirement_selection) target =
  List.find selection.cleanup_attempts ~f:(fun attempt ->
    match target, attempt with
    | Cleanup_idle (completion, _), Idle_cleanup_attempt selected ->
      phys_equal completion selected.completion
    | Cleanup_inherited (Pack acknowledged), Inherited_cleanup_attempt selected ->
      let (Pack original) = selected.acknowledged in
      phys_equal acknowledged.native original.native
    | Cleanup_descendant slot, Descendant_cleanup_attempt selected ->
      phys_equal slot selected.slot
    | Cleanup_governed plan, Causal_cleanup_attempt selected ->
      phys_equal plan selected.plan
    | ( ( Cleanup_constructor _
        | Cleanup_callback _
        | Cleanup_idle _
        | Cleanup_inherited _
        | Cleanup_descendant _
        | Cleanup_governed _
        | Cleanup_factual _ )
      , _ ) -> false)
;;

let runtime_retirement_cleanup (retirement : runtime_retirement) =
  match retirement.cleanup_holder with
  | Some cleanup -> cleanup
  | None ->
    let selection = retirement.selection in
    let targets = ref [] in
    let add target =
      if not (List.exists !targets ~f:(same_runtime_retirement_cleanup_target target))
      then targets := target :: !targets
    in
    List.iter selection.constructor_calls ~f:(fun call -> add (Cleanup_constructor call));
    Option.iter selection.callback ~f:(fun callback -> add (Cleanup_callback callback));
    Option.iter selection.selected_idle_completion ~f:(fun completion ->
      add (Cleanup_idle (completion, selection.idle_continuation)));
    Option.iter selection.inherited_prepared ~f:(fun (Prepared acknowledged) ->
      add (Cleanup_inherited (Pack acknowledged)));
    Option.iter selection.inherited_cleanup ~f:(fun acknowledged ->
      add (Cleanup_inherited acknowledged));
    Option.iter selection.governed_slot ~f:(function
      | Descendant slot -> add (Cleanup_descendant slot)
      | Policy_causal { plan; _ } | Combined { plan; _ } -> add (Cleanup_governed plan));
    (* These owners were selected at election, including children reachable
       only through the retained idle container. Never reselect current fields. *)
    List.iter selection.cleanup_attempts ~f:(function
      | Idle_cleanup_attempt { completion; _ } ->
        add (Cleanup_idle (completion, selection.idle_continuation))
      | Inherited_cleanup_attempt { acknowledged; _ } ->
        add (Cleanup_inherited acknowledged)
      | Descendant_cleanup_attempt { slot; _ } -> add (Cleanup_descendant slot)
      | Causal_cleanup_attempt { plan; _ } -> add (Cleanup_governed plan));
    List.iter selection.factual_usage ~f:(fun facts -> add (Cleanup_factual facts));
    let duties =
      List.rev_map !targets ~f:(fun target ->
        let cleanup_attempt =
          match runtime_retirement_original_attempt selection target with
          | None -> No_cleanup_attempt
          | Some original -> Unobserved_cleanup_attempt original
        in
        { selected_target = target
        ; observation = Retirement_cleanup_observation.Status.Deferred
        ; attempt_observation = cleanup_attempt
        })
    in
    let cleanup =
      { original = retirement
      ; duties
      ; latest =
          Retirement_cleanup_observation.Snapshot.create ~progress:Pending ~failures:[]
      ; reservation = Retirement_cleanup_observation.Reservation.Available
      }
    in
    retirement.cleanup_holder <- Some cleanup;
    cleanup
;;

let retire_runtime_worker_with_cleanup_internal (t : t) ~closing =
  let open Result.Let_syntax in
  let%bind _ = retire_runtime_worker t ~closing in
  match t.runtime_retirement with
  | Some retirement -> Ok (runtime_retirement_cleanup retirement)
  | None ->
    Error (error Invalid_state "runtime retirement election lost its original owner")
;;

let record_runtime_terminal t operation_id (completion : Operation_completion.t option) f =
  Option.iter completion ~f:(fun (completion : Operation_completion.t) ->
    Callback_cleanup_data.Host.end_operation_registration completion.callback_cleanup);
  let finish result =
    let retained =
      Option.value_map completion ~default:result ~f:(fun completion ->
        Operation_completion.record completion ~outcome:result)
    in
    finish_runtime_retirement t operation_id ~completion retained
  in
  match f () with
  | result ->
    finish (Ok result);
    result
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    finish (Error (exn, backtrace));
    Exn.raise_with_original_backtrace exn backtrace
;;

let with_runtime_terminal t operation_id f =
  record_runtime_terminal t operation_id (capture_operation_completion t operation_id) f
;;

let validate_runtime_worker t worker inference moderator_manager =
  let open Result.Let_syntax in
  let%bind () =
    match worker, inference with
    | None, None -> Ok ()
    | Some _, Some _ ->
      (match t.state.runtime_initialization with
       | Ready -> Ok ()
       | Pending _ -> Error (error Invalid_state "runtime initialization is not complete"))
    | None, Some _ | Some _, None ->
      Error
        (error Invalid_request "worker and selected inference must be installed together")
  in
  let%bind () =
    match worker, moderator_manager with
    | None, Some _ ->
      Error (error Invalid_request "moderator resource requires an installed runtime")
    | Some _, _ | None, None -> Ok ()
  in
  let%bind () =
    match moderator_manager with
    | None -> Ok ()
    | Some _ ->
      Constructor_job_handoff.prepare t.state ~manager:moderator_manager
      |> Result.map ~f:ignore
  in
  Ok ()
;;

let install_runtime_worker ?unmoderated_source t worker inference moderator_manager =
  let open Result.Let_syntax in
  let%bind binding =
    match unmoderated_source, worker with
    | None, _ -> Ok None
    | Some source, Some worker ->
      Runtime_builder.Unmoderated_source.bind
        source
        ~state:t.state
        ~worker
        ~manager:moderator_manager
      |> Result.map ~f:Option.some
    | Some _, None ->
      Error (error Invalid_request "unmoderated source requires its worker")
  in
  let%map () = replace_operation_worker t worker ~intended_manager:moderator_manager in
  t.inference_execution <- inference;
  t.moderator_manager <- moderator_manager;
  t.unmoderated_source <- binding
;;

let check_retained_unmoderated_source t source ~worker ~manager =
  match source, t.unmoderated_source with
  | None, None -> Ok ()
  | Some source, Some binding ->
    Runtime_builder.Unmoderated_source.Binding.check_source
      binding
      source
      ~state:t.state
      ~worker
      ~manager
  | Some _, None | None, Some _ ->
    Error (error Conflict "retained runtime changed its unmoderated source fact")
;;

(* This is the genuine authenticated ordinary physical installation, after its
   Init released and before the same Owner exposes its runtime. Opaque startup
   DATA identifies the resources; only the actual current original admits it. *)
let prepare_initial_lifecycle_startup t original_actor startup worker moderator_manager =
  let open Result.Let_syntax in
  match startup with
  | None -> Ok None
  | Some startup ->
    let%bind original =
      Result.of_option
        original_actor
        ~error:
          (error
             Permission_denied
             "initial lifecycle requires authenticated installation")
    in
    let%bind () =
      if Operator_authorization.is_current original
      then Ok ()
      else Error (error Permission_denied "initial lifecycle authentication expired")
    in
    let%bind () =
      if
        Option.is_none t.initialization_scope
        && Option.is_none t.run_preparation
        && Option.is_none t.run_source_binding
        && Option.is_none t.held_activation
        && Option.is_none t.held_input_scope
        && Option.is_none t.held_authored_start
        && Option.is_none t.state.active_operation
        && Option.is_none t.operation_agent_custody
        && Option.is_none t.legacy_callback_scope
        && Option.is_none t.queued_event_borrow
        && Option.is_none t.moderator_borrow
        && (not t.idle_moderator_borrowed)
        && Initial_lifecycle_startup.eligible startup ~state:t.state
      then Ok ()
      else
        Error
          (error Conflict "initial lifecycle installation has another execution owner")
    in
    let%bind () =
      match t.lifecycle_agent_custody with
      | Unadmitted -> Ok ()
      | Admitted _ ->
        Error (error Conflict "initial lifecycle already has original custody")
    in
    let%bind () =
      Initial_lifecycle_startup.check_capture
        startup
        ~state:t.state
        ~worker
        ~manager:moderator_manager
    in
    let%bind () =
      if Operator_authorization.is_current original
      then Ok ()
      else Error (error Permission_denied "initial lifecycle authentication expired")
    in
    let%map source = Runtime_builder.moderator_snapshot_observer t.state.moderator in
    Some
      (Admitted
         { generation = t.state.identity.generation
         ; source
         ; pending =
             Initial_pending
               { admission = create_agent_admission (Some (create_agent_custody original))
               ; startup
               }
         })
;;

let set_runtime_worker
      ?unmoderated_source
      ?original_actor
      ?initial_startup
      t
      worker
      inference
      moderator_manager
  =
  let open Result.Let_syntax in
  let%bind () = validate_runtime_worker t worker inference moderator_manager in
  let%bind pending =
    prepare_initial_lifecycle_startup
      t
      original_actor
      initial_startup
      worker
      moderator_manager
  in
  let installed = ref false in
  Exn.protect
    ~finally:(fun () ->
      if not !installed
      then
        Option.iter pending ~f:(function
          | Admitted { pending = Initial_pending { admission; _ }; _ } ->
            retire_agent_admission admission
          | Unadmitted | Admitted { pending = Pending _ | Consumed; _ } -> ()))
    ~f:(fun () ->
      let%map () =
        install_runtime_worker ?unmoderated_source t worker inference moderator_manager
      in
      (* No yielding/fallible operation remains between physical installation and
         assigning its owned pending cell. Normal claim consumes this binding. *)
      Option.iter pending ~f:(fun pending -> t.lifecycle_agent_custody <- pending);
      installed := true)
;;

let change_moderator ?check_before_commit t moderator =
  if moderator_is_borrowed t
  then Error (error Conflict "moderator invocation owns the moderator checkpoint")
  else (
    let state = { t.state with moderator } in
    transition
      ?check_before_commit
      t
      ~delta:(Session_delta.Moderator_changed moderator)
      ~payloads:
        [ Agent_protocol.Event.Durable.Payload.Session_updated
            (Session_state.summary state)
        ])
;;

let change_workspace t workspace =
  match t.state.lifecycle.observed, t.state.active_operation with
  | Agent_protocol.Session.Stopped, None when List.is_empty t.job_scopes ->
    transition t ~delta:(Session_delta.Workspace_changed workspace) ~payloads:[]
  | ( ( Queued_for_slot
      | Starting
      | Recovering
      | Idle
      | Running_turn _
      | Compacting _
      | Waiting_for_permission _
      | Stopping
      | Failed _
      | Stopped )
    , _ ) ->
    Error (error Invalid_state "workspace replacement requires a stopped session")
;;

let lifecycle
      ?authored_run_acknowledgement
      ?run_preparation
      ?commit_attempted
      ?(extra_deltas = [])
      t
      ~desired
      ~observed
  =
  let open Result.Let_syntax in
  let%bind transition =
    let delta = Session_delta.Lifecycle_changed { desired; observed } in
    prepare_transition
      t
      ~delta:
        (Session_delta.Batch
           (extra_deltas
            @
            if t.state.pending_initial_start
            then [ Session_delta.Initial_start_consumed; delta ]
            else [ delta ]))
      ~payloads:
        [ Agent_protocol.Event.Durable.Payload.Session_state_changed
            { desired_state = desired; observed_state = observed }
        ]
  in
  let check_before_commit =
    Option.map authored_run_acknowledgement ~f:(fun acknowledgement ->
      let basis () =
        let%bind () = require_runtime_admission t in
        let%bind () =
          match run_preparation with
          | None -> Ok ()
          | Some preparation ->
            (match t.run_preparation with
             | Some (Initial current) when phys_equal current preparation ->
               Run_preparation.check_basis
                 preparation
                 ~owner:t.run_preparation_owner
                 ~state:t.state
             | Some _ | None ->
               Error (error Conflict "authored startup preparation changed"))
        in
        Authored_run_acknowledgement.check_basis
          acknowledgement
          ~previous:t.state
          ~authorities:t.run_authorities
          ~lifecycle:t.lifecycle_agent_custody
          ~candidate:transition
      in
      fun () ->
        let%bind () = basis () in
        let%bind () =
          Option.value_map run_preparation ~default:(Ok ()) ~f:(check_run_preparation t)
        in
        let scope = Authored_run_acknowledgement.scope acknowledgement in
        let%bind () = Run_admission.Scope.authorize scope t.state in
        let%bind () =
          if Run_admission.Scope.startup_pending scope
          then Ok ()
          else Error (error Conflict "authored startup callback is no longer pending")
        in
        (* Candidate preparation already sampled clocks. All policy/startup
           callbacks precede final originals, then the callback-free joint basis. *)
        let%bind () =
          Option.value_map run_preparation ~default:(Ok ()) ~f:(fun preparation ->
            Run_preparation.check_current
              preparation
              ~owner:t.run_preparation_owner
              ~state:t.state)
        in
        let%bind () = Run_admission.Scope.check_current scope in
        basis ())
  in
  let%map () =
    install
      ?authored_run_acknowledgement
      ?check_before_commit
      ?run_preparation
      ?commit_attempted
      t
      transition
  in
  Session_state.summary t.state
;;

let start_internal
      ?authored_run_acknowledgement
      ?run_preparation
      ?commit_attempted
      ?expected_parent_stop_epoch
      ?(extra_deltas = [])
      t
  =
  if not (runtime_admission_open t)
  then Error (error Conflict "session runtime is retiring")
  else if
    match t.state.runtime_initialization with
    | Pending _ -> true
    | Ready -> false
  then Error (error Invalid_state "runtime initialization must complete before start")
  else if
    Option.exists expected_parent_stop_epoch ~f:(fun epoch ->
      not (Option.equal Int64.equal t.state.parent_stop_epoch (Some epoch)))
  then Error (error Conflict "parent stopped while child start was being prepared")
  else if t.idle_moderator_borrowed
  then Error (error Conflict "cannot restart while the idle moderator is borrowed")
  else (
    match t.state.lifecycle.desired, t.state.lifecycle.observed with
    | Running, (Idle | Running_turn _ | Starting | Queued_for_slot) ->
      Ok (Session_state.summary t.state)
    | _, _ ->
      let open Result.Let_syntax in
      let%bind _ =
        lifecycle
          ?authored_run_acknowledgement
          ?run_preparation
          ?commit_attempted
          ~extra_deltas
          t
          ~desired:Running
          ~observed:Starting
      in
      lifecycle ?run_preparation ?commit_attempted t ~desired:Running ~observed:Idle)
;;

let queue_start_internal t =
  if not (runtime_admission_open t)
  then Error (error Conflict "session runtime is retiring")
  else if t.idle_moderator_borrowed
  then Error (error Conflict "cannot restart while the idle moderator is borrowed")
  else (
    match t.state.lifecycle.desired, t.state.lifecycle.observed with
    | Running, (Queued_for_slot | Starting | Idle | Running_turn _) ->
      Ok (Session_state.summary t.state)
    | _, _ -> lifecycle t ~desired:Running ~observed:Queued_for_slot)
;;

let activate_queued_start t =
  let%bind.Result () = require_selected_execution t in
  if not (runtime_admission_open t)
  then Error (error Conflict "session runtime is retiring")
  else if
    match t.state.runtime_initialization with
    | Pending _ -> true
    | Ready -> false
  then
    Error (error Invalid_state "runtime initialization must complete before activation")
  else (
    match t.state.lifecycle.desired, t.state.lifecycle.observed with
    | Running, Queued_for_slot ->
      let open Result.Let_syntax in
      let%bind _ = lifecycle t ~desired:Running ~observed:Starting in
      lifecycle t ~desired:Running ~observed:Idle
    | Running, (Starting | Idle | Running_turn _) -> Ok (Session_state.summary t.state)
    | _, _ -> Error (error Invalid_state "session has no queued start intent"))
;;

let background_terminal_result (job : Agent_protocol.Job.t) completion =
  match job.kind with
  | Async_tool -> Some (Agent_protocol.Completion.to_json completion)
  | _ -> job.result
;;

let stopped_jobs t mode =
  if Agent_protocol.Session.equal_stop_mode mode Graceful
  then []
  else
    List.filter_map t.state.jobs ~f:(fun (job : Agent_protocol.Job.t) ->
      match job.status with
      | Queued | Running | Waiting_permission _ | Waiting_completion _ ->
        Some
          { job with
            status = Cancelled
          ; result = background_terminal_result job (Cancelled "session stopped")
          ; completed_at = Some (t.services.now ())
          ; delivery =
              (match job.delivery with
               | Not_required -> Not_required
               | _ -> Pending)
          }
      | Succeeded | Failed _ | Cancelled | Interrupted _ -> None)
;;

let cancel_permission t reason (permission : Agent_protocol.Permission.t) =
  { permission with
    state = Cancelled
  ; resolution =
      Some
        { choice = Deny
        ; principal_id = None
        ; resolved_at = t.services.now ()
        ; reason = Some reason
        }
  }
;;

let resolve_cleaned_permission_waiters t permissions =
  List.iter permissions ~f:(fun permission ->
    Option.iter permission.Agent_protocol.Permission.resolution ~f:(fun resolution ->
      Option.iter (Map.find !(t.permission_waiters) permission.id) ~f:(fun waiter ->
        Eio.Promise.resolve waiter.resolver resolution));
    t.permission_waiters := Map.remove !(t.permission_waiters) permission.id)
;;

let pending_invocation_permissions t ~matches =
  List.filter t.state.permissions ~f:(fun permission ->
    Agent_protocol.Permission.equal_state permission.state Pending
    &&
    match permission.owner with
    | Invocation id -> matches id
    | Operation _ -> false)
;;

let permission_resume_observed
      t
      ~resolved
      ~(fallback : Agent_protocol.Session.observed_state)
  =
  match t.state.lifecycle.desired, t.state.active_operation with
  | Stopped, None -> Agent_protocol.Session.Stopped
  | _ ->
    (match
       List.find t.state.permissions ~f:(fun permission ->
         Agent_protocol.Permission.equal_state permission.state Pending
         && not
              (List.exists resolved ~f:(Agent_protocol.Id.Permission.equal permission.id)))
     with
     | Some permission -> Waiting_for_permission permission.id
     | None ->
       (match fallback with
        | (Running_turn id | Compacting id)
          when not
                 (Option.exists t.state.active_operation ~f:(fun operation ->
                    Agent_protocol.Id.Operation.equal operation.id id)) ->
          (match t.state.lifecycle.desired with
           | Running -> Idle
           | Stopped -> Stopped)
        | _ -> fallback))
;;

let cleanup_invocation_permissions t ids =
  let permissions =
    pending_invocation_permissions t ~matches:(fun id ->
      List.mem ids id ~equal:Agent_protocol.Id.Invocation.equal)
    |> List.map
         ~f:(cancel_permission t "invocation finished before permission resolution")
  in
  let lifecycle =
    match t.state.lifecycle.observed with
    | Waiting_for_permission id
      when List.exists permissions ~f:(fun p ->
             Agent_protocol.Id.Permission.equal p.id id) ->
      Option.map (Map.find !(t.permission_waiters) id) ~f:(fun waiter ->
        { t.state.lifecycle with
          observed =
            permission_resume_observed
              t
              ~resolved:
                (List.map permissions ~f:(fun p -> p.Agent_protocol.Permission.id))
              ~fallback:waiter.resume_observed
        })
    | _ -> None
  in
  ( permissions
  , List.map permissions ~f:(fun permission ->
      Session_delta.Permission_changed permission)
    @ Option.to_list
        (Option.map lifecycle ~f:(fun value -> Session_delta.Lifecycle_changed value))
  , List.map permissions ~f:(fun permission ->
      Agent_protocol.Event.Durable.Payload.Permission_resolved permission)
    @ Option.to_list
        (Option.map lifecycle ~f:(fun value ->
           Agent_protocol.Event.Durable.Payload.Session_state_changed
             { desired_state = value.desired; observed_state = value.observed })) )
;;

let stop_transition
      ?parent_stop_epoch
      ?managed_receipt
      t
      mode
      ~extension_work
      lifecycle
      deltas
      payloads
  =
  let open Result.Let_syntax in
  let%bind constructor_stop_acknowledgement =
    Constructor_stop_acknowledgement.prepare t
  in
  let%bind discarded =
    Observation_follow_up.discard t.state.invocations ~reason:"session stopped"
  in
  let%bind events =
    Observation_follow_up.discard_events
      t.state.moderator_executions
      ~reason:"session stopped"
  in
  let jobs = stopped_jobs t mode in
  let job_custody = Job_custody.prepare_retirement t.job_agent_custody in
  let permissions =
    pending_invocation_permissions t ~matches:(fun _ -> true)
    |> List.map ~f:(cancel_permission t "session stopped")
  in
  let%map result =
    transition
      ?constructor_stop_acknowledgement
      ~check_before_commit:(fun () ->
        Option.value_map
          constructor_stop_acknowledgement
          ~default:(Ok ())
          ~f:(Constructor_stop_acknowledgement.check ~actor:t))
      ~retire_legacy_custody:()
      ~job_custody
      t
      ~delta:
        (Session_delta.Batch
           ((if t.state.pending_initial_start
             then [ Session_delta.Initial_start_consumed ]
             else [])
            @ (Session_delta.Lifecycle_changed lifecycle :: deltas)
            @ Option.to_list
                (Option.map managed_receipt ~f:(fun receipt ->
                   Session_delta.Managed_stop_admitted receipt))
            @ Option.to_list
                (Option.map parent_stop_epoch ~f:(fun epoch ->
                   Session_delta.Parent_stop_epoch_changed epoch))
            @ Option.value_map
                constructor_stop_acknowledgement
                ~default:[]
                ~f:Constructor_stop_acknowledgement.deltas
            @ List.map discarded ~f:Observation_follow_up.delta
            @ List.map events ~f:Observation_follow_up.event_delta
            @ List.map permissions ~f:(fun permission ->
              Session_delta.Permission_changed permission)
            @ List.map jobs ~f:(fun job -> Session_delta.Job_changed job)
            @ Extension_stop.deltas extension_work))
      ~payloads:
        ((Agent_protocol.Event.Durable.Payload.Session_state_changed
            { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
          :: payloads)
         @ List.map jobs ~f:(fun job ->
           Agent_protocol.Event.Durable.Payload.Job_state_changed job)
         @ List.map permissions ~f:(fun permission ->
           Agent_protocol.Event.Durable.Payload.Permission_resolved permission)
         @ Extension_stop.payloads extension_work)
  in
  cancel_job_scopes t jobs;
  resolve_cleaned_permission_waiters t permissions;
  result
;;

let cancel_event_for_operation t operation_id =
  Option.iter t.queued_event_borrow ~f:(fun borrow ->
    if
      Option.exists
        borrow.receipt.context.operation_id
        ~f:(Agent_protocol.Id.Operation.equal operation_id)
    then (
      borrow.cancel_requested <- true;
      Option.iter borrow.cancel ~f:(fun cancel -> cancel ())))
;;

let cancel_independent_moderator t =
  Option.iter t.moderator_borrow ~f:(fun borrow ->
    match borrow.operation_id with
    | Some _ -> ()
    | None ->
      borrow.cancel_requested <- true;
      Option.iter borrow.cancel ~f:(fun cancel -> cancel ()));
  Option.iter t.queued_event_borrow ~f:(fun borrow ->
    match borrow.receipt.context.operation_id with
    | Some _ -> ()
    | None ->
      borrow.cancel_requested <- true;
      Option.iter borrow.cancel ~f:(fun cancel -> cancel ()))
;;

(* This safety disposition is durable before Stop effects. Its commit must not
   accept the original Stop audit: a later Stop failure leaves future Goal and
   recurrence work paused without claiming that external cancellation completed. The same
   serialized command restores the original audit for its final Stop commit. *)
let pause_capabilities_before_stop t =
  let open Result.Let_syntax in
  let%bind paused =
    match t.state.recurrence_catalog with
    | None -> Ok None
    | Some catalog -> Recurrence_catalog.pause_for_stop catalog
  in
  let%bind goals = Goal_control_transition.prepare_stop t.state in
  let changes =
    Option.to_list goals
    @ Option.to_list
        (Option.map paused ~f:(fun catalog ->
           Session_delta.Recurrence_catalog_changed catalog))
  in
  let goal_ids =
    Option.value_map t.state.goal_catalog ~default:[] ~f:(fun catalog ->
      List.filter_map (Goal_catalog.goals catalog) ~f:(fun goal ->
        match Agent_protocol.Goal.state goal with
        | Open (Enabled | Held _) -> Some (Agent_protocol.Goal.id goal)
        | Closed _ -> None))
  in
  let retire_startups () = List.iter goal_ids ~f:(retire_goal_activation t) in
  match changes with
  | [] ->
    (* An explicit Stop also revokes a pending startup whose Goal is already
       Held. This is monotone local revocation, not a new durable command ACK. *)
    retire_startups ();
    Ok false
  | changes ->
    let audit = t.command_audit in
    Exn.protect
      ~finally:(fun () -> t.command_audit <- audit)
      ~f:(fun () ->
        t.command_audit <- None;
        let%bind candidate =
          prepare_transition t ~delta:(Session_delta.Batch changes) ~payloads:[]
        in
        let%map () =
          install
            ~explicit_goal_holds:goal_ids
            ~check_before_commit:(fun () ->
              retire_startups ();
              Ok ())
            t
            candidate
        in
        true)
;;

let stop_internal ?parent_stop_epoch ?managed_receipt t mode =
  let open Result.Let_syntax in
  let%bind capabilities_paused = pause_capabilities_before_stop t in
  let%bind extension_work =
    Extension_stop.prepare ~state:t.state ~mode ~now:(t.services.now ())
  in
  match t.state.active_operation with
  | None ->
    let open Result.Let_syntax in
    let%map session =
      match t.state.lifecycle.desired, t.state.lifecycle.observed with
      | Stopped, Stopped
        when (not capabilities_paused)
             && (not t.state.pending_initial_start)
             && Option.for_all t.initialization_scope ~f:(fun scope ->
               match scope.Initialization_scope_data.callback with
               | Unclaimed | Settled _ -> true
               | Claimed _ -> false)
             && Option.is_none parent_stop_epoch
             && Option.is_none managed_receipt
             && List.is_empty (stopped_jobs t mode)
             && Job_custody.is_empty t.job_agent_custody
             && Legacy_queue_custody.is_empty t.legacy_queue_custody
             && Legacy_schedule_custody.is_empty t.legacy_schedule_custody
             && Ingress_creator_custody.is_empty t.ingress_creator_custody
             && Extension_stop.is_empty extension_work
             && (not
                   (Option.exists t.state.recurrence_catalog ~f:(fun catalog ->
                      List.exists (Recurrence_catalog.entries catalog) ~f:(fun entry ->
                        match Recurrence_entry.control entry with
                        | Enabled -> true
                        | Paused _ | Retired _ -> false))))
             && not
                  (List.exists t.state.invocations ~f:Observation_follow_up.pending
                   || List.exists
                        t.state.moderator_executions
                        ~f:Observation_follow_up.pending_event) ->
        Ok (Session_state.summary t.state)
      | _, _ ->
        stop_transition
          ?parent_stop_epoch
          ?managed_receipt
          t
          mode
          ~extension_work
          { desired = Stopped; observed = Stopped }
          []
          []
    in
    t.initialization_scope <- None;
    (match mode with
     | Cancel ->
       cancel_independent_moderator t;
       abort_all_staged_work t
     | Graceful -> ());
    session
  | Some operation ->
    let lifecycle =
      Session_state.Lifecycle.{ desired = Stopped; observed = t.state.lifecycle.observed }
    in
    let operation =
      match mode with
      | Agent_protocol.Session.Graceful -> operation
      | Cancel ->
        { operation with
          state = Agent_protocol.Operation.Cancelling
        ; updated_at = t.services.now ()
        }
    in
    let open Result.Let_syntax in
    let%bind session =
      stop_transition
        ?parent_stop_epoch
        ?managed_receipt
        t
        mode
        ~extension_work
        lifecycle
        [ Session_delta.Active_operation_changed (Some operation) ]
        []
    in
    t.initialization_scope <- None;
    if Agent_protocol.Session.equal_stop_mode mode Cancel
    then (
      abort_all_staged_work t;
      cancel_event_for_operation t operation.id;
      cancel_independent_moderator t;
      Option.iter t.active_cancel ~f:(fun cancel -> cancel ()));
    Ok session
;;

let stop_managed_internal t reference key mode generation max_receipts =
  let module M = Managed_stop in
  let module P = Agent_protocol in
  let module D = Agent_store.Delegation_store in
  let open Result.Let_syntax in
  let%bind () =
    match t.state.spec.delegation with
    | Some current
      when D.Reference.equal current reference
           && P.Id.Session.equal reference.child_session_id t.state.identity.session_id ->
      Ok ()
    | _ ->
      Error (error Permission_denied "delegation.stop: child relationship does not match")
  in
  match
    List.find t.state.managed_stops ~f:(fun receipt ->
      D.Reference.equal receipt.M.reference reference
      && P.Idempotency_key.equal receipt.key key)
  with
  | Some receipt ->
    (match P.Session.equal_stop_mode receipt.mode mode with
     | true -> Ok receipt
     | false -> Error (error Conflict "managed stop key was used for a different mode"))
  | None ->
    let%bind () =
      match Int.equal generation t.state.identity.generation with
      | true -> Ok ()
      | false -> Error (error Conflict "child generation changed before managed stop")
    in
    let%bind () =
      match max_receipts with
      | Some maximum when maximum < 1 || List.length t.state.managed_stops >= maximum ->
        Error (error Invalid_state "managed stop receipt capacity reached")
      | None | Some _ -> Ok ()
    in
    let%bind stop_epoch =
      match t.state.lifecycle.desired with
      | Stopped -> Ok t.state.stop_epoch
      | Running when Int64.equal t.state.stop_epoch Int64.max_value ->
        Error (error Invalid_state "stop epoch overflow")
      | Running -> Ok Int64.(t.state.stop_epoch + 1L)
    in
    let%bind receipt =
      M.create ~reference ~key ~mode ~generation ~stop_epoch ~now:(t.services.now ())
    in
    let%map _ = stop_internal ~managed_receipt:receipt t mode in
    receipt
;;

let append_history ?check_before_commit t entries =
  transition
    ?check_before_commit
    t
    ~delta:(Session_delta.Canonical_entries_appended entries)
    ~payloads:[ Agent_protocol.Event.Durable.Payload.History_appended entries ]
;;

let prepare_pending t ?(archive = None) change =
  let retention = Pending_disposition.Retention.default in
  Pending_transition.prepare
    t.state
    ~change
    ~retention
    ~archive
    ~limits:Session_delta.native_limits
;;

let eligible_pending t boundary =
  let open Result.Let_syntax in
  let%bind eligibility =
    Pending_eligibility.create
      t.state
      ~boundary
      ~runtime_admission_open:(runtime_admission_open t)
  in
  Pending_eligibility.eligible_prefix
    eligibility
    t.state.conversation.deferred_user_entries
;;

let prepare_pending_inputs t ~owner timing entries =
  let open Result.Let_syntax in
  let%bind binding =
    Agent_protocol.Pending_input.Binding.create
      timing
      ~generation:t.state.identity.generation
      ~operation:t.state.active_operation
  in
  let%bind documents =
    List.map entries ~f:(fun entry ->
      let%bind value =
        Agent_protocol.Pending_input.create
          ~entry
          ~generation:t.state.identity.generation
          ~binding
      in
      Pending_input_document.authored ~owner value ~limits:Session_delta.native_limits
      |> Result.map_error ~f:(fun error ->
        Agent_protocol.Error.invalid_request
          (Sexp.to_string_hum (Document_schema.Error.sexp_of_t error))))
    |> Result.all
  in
  prepare_pending t (Enqueue documents)
;;

let defer_history
      ?(extra_deltas = [])
      ?(owner = Pending_input_document.Owner.Host_internal)
      ?(timing = Agent_protocol.Pending_input.Timing.Safe_boundary)
      t
      entries
  =
  let open Result.Let_syntax in
  let%bind prepared = prepare_pending_inputs t ~owner timing entries in
  let payloads =
    List.map entries ~f:(fun entry ->
      Agent_protocol.Event.Durable.Payload.History_message_deferred entry)
  in
  transition
    t
    ~delta:(Session_delta.Batch (extra_deltas @ [ Pending_transition.delta prepared ]))
    ~payloads
;;

let write_attachment t attachment_id =
  Writer_attachment.require t.state ~attachment_id ~now:t.services.now
;;

let has_writer_attachment t = Writer_attachment.any t.state ~now:t.services.now

let grant_is_unexpired t grant =
  match grant.Agent_protocol.Grant.expires_at with
  | None -> true
  | Some expires_at -> Agent_protocol.Timestamp.compare expires_at (t.services.now ()) > 0
;;

let grant_identity_matches grant ~tool_name ~identity_digest =
  match grant.Agent_protocol.Grant.scope with
  | Exact_session | Durable_exact -> String.equal grant.identity_digest identity_digest
  | Prefix_session ->
    String.equal
      grant.identity_digest
      (Permission_policy.prefix_identity_digest ~tool_name)
;;

let invocation_granted t ~tool_name ~identity_digest =
  List.exists t.state.grants ~f:(fun grant ->
    Agent_protocol.Grant.equal_state grant.state Active
    && String.equal grant.tool_name tool_name
    && grant_is_unexpired t grant
    && grant_identity_matches grant ~tool_name ~identity_digest)
;;

let with_writer t attachment_id f =
  Result.bind (write_attachment t attachment_id) ~f:(fun _ -> f ())
;;

let validate_administrative_state t attachment_id expected_revision =
  let open Result.Let_syntax in
  let%bind _ = write_attachment t attachment_id in
  if not (Int64.equal expected_revision t.state.counters.revision)
  then Error (error Conflict "session revision does not match")
  else if Option.is_some t.state.active_operation
  then Error (error Conflict "session has an active foreground operation")
  else if t.idle_moderator_borrowed
  then Error (error Conflict "session moderator is processing background work")
  else if not (List.is_empty t.job_scopes)
  then Error (error Conflict "session has an active background execution scope")
  else (
    match t.state.lifecycle.observed with
    | Agent_protocol.Session.Stopped -> Ok ()
    | Queued_for_slot
    | Starting
    | Recovering
    | Idle
    | Running_turn _
    | Compacting _
    | Waiting_for_permission _
    | Stopping
    | Failed _ ->
      Error (error Invalid_state "administrative mutation requires a stopped session"))
;;

let commit_administration t attachment_id expected_revision kind candidate =
  let open Result.Let_syntax in
  let%bind () = validate_administrative_state t attachment_id expected_revision in
  let ingress_matches =
    match kind with
    | Session_state.Compaction_archive.Reset | Rebuild ->
      t.state.identity.generation < Int.max_value
      && Int.equal
           candidate.Session_state.identity.generation
           (t.state.identity.generation + 1)
      && List.is_empty candidate.ingress_registrations
    | Upgrade | Compaction | Edit | Delete | Pending_input | Rollover ->
      List.equal
        External_ingress.equal
        candidate.ingress_registrations
        t.state.ingress_registrations
  in
  let%bind () =
    if
      Agent_protocol.Id.Session.compare
        candidate.Session_state.identity.session_id
        t.state.identity.session_id
      <> 0
      || (not (Int64.equal candidate.counters.revision expected_revision))
      || (not
            (Option.equal
               Automatic_turn_budget.equal
               candidate.automatic_turn_budget
               t.state.automatic_turn_budget))
      || (not ingress_matches)
      || Int64.(
           candidate.conversation.next_history_sequence
           < t.state.conversation.next_history_sequence)
    then
      Error (error Conflict "administrative candidate does not match the captured state")
    else Session_state.validate candidate
  in
  let%bind state =
    Administration.archive
      ~archive_reference:t.persistence.archive_reference
      ~previous:t.state
      candidate
      kind
  in
  let%bind pending =
    match kind with
    | Reset | Rebuild ->
      if List.is_empty t.state.conversation.deferred_user_entries
      then Ok None
      else (
        let%bind archive =
          List.hd state.conversation.compaction_archives
          |> Result.of_option
               ~error:(error Internal_error "administrative archive missing")
        in
        let reason =
          match kind with
          | Reset -> Pending_disposition.Retirement_reason.Source_reset
          | Rebuild -> Source_replaced
          | Compaction | Upgrade | Edit | Delete | Pending_input | Rollover ->
            Canonical_history_retired
        in
        prepare_pending t ~archive:(Some archive) (Retire reason)
        |> Result.map ~f:Option.some)
    | Compaction | Upgrade | Edit | Delete | Pending_input | Rollover -> Ok None
  in
  let state =
    Option.value_map pending ~default:state ~f:(fun prepared ->
      let plan = Pending_transition.plan prepared in
      { state with
        conversation =
          { state.conversation with
            deferred_user_entries = Pending_plan.pending plan
          ; pending_revision = Pending_plan.revision plan
          ; pending_dispositions = Pending_plan.dispositions plan
          }
      })
  in
  let delta =
    match pending with
    | None -> Session_delta.Created state
    | Some prepared ->
      Session_delta.Batch
        [ Pending_transition.delta prepared; Session_delta.Created state ]
  in
  transition t ~delta ~payloads:(Administration.payloads ~previous:t.state state)
;;

let administration_basis (expected : Session_state.t) (state : Session_state.t) =
  { state with
    identity = { state.identity with updated_at = expected.identity.updated_at }
  ; counters = expected.counters
  ; inference_ledger = expected.inference_ledger
  ; policy_canonical_usage = expected.policy_canonical_usage
  }
;;

let same_administration_basis ~reconciled expected current =
  let open Result.Let_syntax in
  let document_error _ = error Invalid_state "administration basis admission failed" in
  let%bind limits =
    Persistence_codec.limits ~max_bytes:(64 * 1024 * 1024)
    |> Result.map_error ~f:document_error
  in
  let admit state =
    Session_state_document.encode (Session_state_document.authored state) ~limits
    |> Result.map_error ~f:document_error
  in
  let%bind expected_document = admit expected in
  let%map current_document =
    admit (if reconciled then administration_basis expected current else current)
  in
  String.equal
    (Jsonaf.to_string (Document_schema.Document.json expected_document))
    (Jsonaf.to_string (Document_schema.Document.json current_document))
;;

let validate_administration_basis t attachment_id expected =
  let open Result.Let_syntax in
  let%bind () =
    validate_administrative_state t attachment_id expected.Session_state.counters.revision
  in
  let%bind unchanged = same_administration_basis ~reconciled:false expected t.state in
  if unchanged
  then Ok ()
  else Error (error Conflict "administration basis changed before resource retirement")
;;

let commit_reconciled_administration t attachment_id expected kind candidate =
  let open Result.Let_syntax in
  let%bind () =
    Session_state.validate_administration_candidate candidate ~previous:expected
  in
  let%bind unchanged = same_administration_basis ~reconciled:true expected t.state in
  let%bind () =
    if unchanged
    then Ok ()
    else Error (error Conflict "administration basis changed during resource retirement")
  in
  let%bind inference_ledger =
    Inference_ledger.with_generation
      t.state.inference_ledger
      ~generation:candidate.Session_state.identity.generation
    |> Result.map_error ~f:inference_error
  in
  let%bind delegated_usage =
    match t.state.delegated_usage with
    | None -> Ok None
    | Some own ->
      Delegated_usage.reconcile
        own
        ~before:t.state.inference_ledger
        ~after:inference_ledger
      |> Result.map ~f:Option.some
  in
  let%bind policy_canonical_usage =
    Option.value_map
      t.state.policy_canonical_usage
      ~default:(Ok None)
      ~f:(fun accounting ->
        Policy_canonical_usage.reconcile_factual
          accounting
          ~before:t.state.inference_ledger
          ~after:inference_ledger
        |> Result.map ~f:Option.some)
  in
  let candidate =
    { candidate with
      inference_ledger
    ; delegated_usage
    ; policy_canonical_usage
    ; counters = t.state.counters
    }
  in
  commit_administration t attachment_id t.state.counters.revision kind candidate
;;

(* Initialization may durably admit jobs and tracking before its final local
   runtime state is available. Those records are never replaced by an earlier
   constructor snapshot. History reservations alone may also advance. *)
let initialization_basis (basis : Session_state.t) (state : Session_state.t) =
  { state with
    identity = { state.identity with updated_at = basis.identity.updated_at }
  ; counters = basis.counters
  ; inference_ledger = basis.inference_ledger
  ; policy_canonical_usage = basis.policy_canonical_usage
  ; goal_accounts = basis.goal_accounts
  ; delegated_usage = basis.delegated_usage
  ; child_contributions = basis.child_contributions
  ; jobs = basis.jobs
  ; model_job_targets = basis.model_job_targets
  ; schedules = basis.schedules
  ; shell =
      { state.shell with
        manifest_grants = basis.shell.manifest_grants
      ; approval_grants = basis.shell.approval_grants
      }
  ; conversation =
      { state.conversation with
        next_history_sequence = basis.conversation.next_history_sequence
      ; reserved_history_through = basis.conversation.reserved_history_through
      }
  }
;;

let validate_initialization_projection (expected : Session_state.t) state =
  if
    Sexp.equal
      (Session_state.sexp_of_t expected)
      (Session_state.sexp_of_t (initialization_basis expected state))
    && Document_schema.Json.equal
         (Inference.Selection.to_json expected.spec.inference_target)
         (Inference.Selection.to_json state.Session_state.spec.inference_target)
  then Ok ()
  else Error (error Conflict "initialization basis changed while resources were prepared")
;;

(* The explicit constructor scope must own the very borrow already held by this
   actor. This predicate does not call the effect/currentness guard, so Init and
   callback validation cannot recurse through each other. Existing installed
   callback claims never set [constructor_scope]. *)
let initialization_callback_is_owned t (scope : Initialization_scope_data.t) =
  match t.initialization_scope, t.legacy_callback_scope, t.queued_event_borrow with
  | Some active, Some callback, Some borrow ->
    phys_equal active scope
    && Option.exists callback.constructor_scope ~f:(phys_equal scope)
    && phys_equal callback.borrow borrow
    && (match scope.callback with
        | Claimed id ->
          Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
        | Unclaimed | Settled _ -> false)
    && t.idle_moderator_borrowed
    && borrow.callback_active
    && (not (borrow.committed || borrow.cancel_requested))
    && Atomic.get borrow.authority_live
    && Chat_response.Moderator_manager.callback_is_current
         callback.manager
         callback.callback
  | None, _, _ | _, None, _ | _, _, None -> false
;;

let validate_initialization_basis
      ?scope
      ?construction
      t
      ~purpose
      (expected : Session_state.t)
  =
  let open Result.Let_syntax in
  let%bind () =
    match purpose, expected.runtime_initialization, t.state.runtime_initialization with
    | Initialization_scope_data.Purpose.Pending_initialization, Pending _, Pending _
    | Runtime_construction, Ready, Ready -> Ok ()
    | Pending_initialization, Ready, _
    | Pending_initialization, _, Ready
    | Runtime_construction, Pending _, _
    | Runtime_construction, _, Pending _ ->
      Error (error Conflict "constructor purpose differs from its actual lifecycle basis")
  in
  if
    Option.is_some t.state.active_operation
    || (t.idle_moderator_borrowed
        && not (Option.exists scope ~f:(initialization_callback_is_owned t)))
    || not
         (List.for_all t.job_scopes ~f:(fun job ->
            Option.exists
              (Option.first_some
                 (Option.bind scope ~f:Initialization_scope_data.construction)
                 construction)
              ~f:(function
                | Existing_goal continuation ->
                  (match continuation.binding.preparation.cause with
                   | Claimed_job { owner; _ } -> phys_equal owner.scope job
                   | Resume_command _ | Pending_wake _ -> false)
                | Initial _ | Delegated_load _ -> false)))
  then Error (error Conflict "initialization basis changed while resources were prepared")
  else validate_initialization_projection expected t.state
;;

let validate_initialization_owner t (scope : Initialization_scope_data.t) =
  (* Physical identity is deliberate capability ownership, never domain equality. *)
  if phys_equal t.initialization_owner scope.owner
  then Ok ()
  else Error (error Conflict "initialization scope belongs to another actor")
;;

let validate_initialization_scope_basis t scope =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_owner t scope in
  let%bind () =
    match t.initialization_scope with
    | Some active when phys_equal active scope -> Ok ()
    | Some _ | None -> Error (error Conflict "initialization scope is no longer active")
  in
  let expected =
    Initialization_scope_data.Acknowledged.apply scope.acknowledged scope.expected
  in
  let%bind () = validate_initialization_basis ~scope t ~purpose:scope.purpose expected in
  Option.value_map
    (Initialization_scope_data.preparation_owner scope)
    ~default:(Ok ())
    ~f:(fun preparation ->
      if Option.exists t.run_preparation ~f:(Preparation_owner.same preparation)
      then
        Preparation_owner.check_basis
          preparation
          ~owner:t.run_preparation_owner
          ~state:t.state
      else Error (error Conflict "initializer preparation is no longer active"))
;;

let admitted_inference_continuation (selected : Admitted_inference.t) =
  match selected.startup with
  | Ordinary | Goal_runtime _ -> None
  | Initialization (_, Initial continuation) -> Some continuation
  | Initialization (_, (Existing_goal _ | Delegated_load _)) -> None
  | Input scope -> Some scope.continuation
  | Authored scope ->
    if held_authored_handoff_acknowledged scope then None else Some scope.continuation
;;

let admitted_goal_construction (selected : Admitted_inference.t) =
  match selected.startup with
  | Initialization (_, Existing_goal continuation) ->
    Some continuation.binding.preparation
  | Goal_runtime scope ->
    (match scope.continuation.binding.preparation.runtime_phase with
     | Handed_off (actual, _) when phys_equal actual scope -> None
     | _ -> Some scope.continuation.binding.preparation)
  | Ordinary | Initialization (_, (Initial _ | Delegated_load _)) | Input _ | Authored _
    -> None
;;

let admitted_inference_owner t (selected : Admitted_inference.t) =
  let open Result.Let_syntax in
  let%bind actual = inference_registration t selected.owner selected.handle in
  let%bind () =
    if phys_equal actual selected.registration
    then Ok ()
    else Error (error Conflict "admitted inference registration was replaced")
  in
  let%bind () =
    let ledger = t.state.inference_ledger in
    if
      Agent_protocol.Id.Session.equal
        (Inference_ledger.Handle.session_id selected.handle)
        (Inference_ledger.session_id ledger)
      && Int.equal
           (Inference_ledger.Handle.generation selected.handle)
           (Inference_ledger.generation ledger)
      &&
      match
        ( selected.tracking
        , Inference_ledger.find
            ledger
            ~ordinal:(Inference_ledger.Handle.ordinal selected.handle) )
      with
      | Tracked, Some row ->
        Inference_ledger.Handle.equal (Inference_ledger.Row.handle row) selected.handle
      | Untracked _, None -> true
      | Tracked, None | Untracked _, Some _ -> false
    then Ok ()
    else Error (error Conflict "admitted inference canonical ledger handle changed")
  in
  let%bind () =
    if Inference_owner.Registration.policy_is_current selected.registration
    then Ok ()
    else Error (error Permission_denied "goal inference policy changed")
  in
  match selected.startup with
  | Ordinary -> Ok ()
  | Goal_runtime scope ->
    let%bind () = goal_runtime_scope_basis t scope in
    (match scope.continuation.binding.preparation.runtime_phase with
     | Handed_off (actual, _) when phys_equal actual scope -> Ok ()
     | _ -> scope.continuation.binding.preparation.registered_basis ())
  | Initialization (scope, construction) ->
    let%bind () = validate_initialization_scope_basis t scope in
    let%bind () =
      if
        Option.exists (Initialization_scope_data.construction scope) ~f:(fun actual ->
          Preparation_owner.same
            (Runtime_construction.preparation_owner actual)
            (Runtime_construction.preparation_owner construction))
      then Ok ()
      else Error (error Conflict "admitted initializer owner changed")
    in
    (match construction with
     | Initial continuation ->
       if Option.exists t.held_activation ~f:(phys_equal continuation.target)
       then continuation.target.owned_basis ()
       else Error (error Conflict "admitted initializer activation changed")
     | Existing_goal continuation -> continuation.binding.preparation.registered_basis ()
     | Delegated_load load -> load.preparation.basis ())
  | Input scope ->
    let%bind () = Held_input_scope.parsing scope in
    let%bind () = input_scope_basis t scope in
    input_graph_basis t scope selected.owner
  | Authored scope ->
    if held_authored_handoff_acknowledged scope
    then Ok ()
    else held_authored_basis t scope
;;

let refresh_admitted_inference t selected =
  let open Result.Let_syntax in
  let%bind () = admitted_inference_owner t selected in
  let%bind () =
    Option.value_map
      (admitted_inference_continuation selected)
      ~default:(Ok ())
      ~f:(fun continuation -> continuation.refresh_admitted_inference ())
  in
  let%bind () =
    Option.value_map
      (admitted_goal_construction selected)
      ~default:(Ok ())
      ~f:(fun preparation -> preparation.registered_refresh ())
  in
  admitted_inference_owner t selected
;;

let observe_inference_origin t =
  match inherited_turn_required t.state with
  | Ordinary | Scoped -> Ok None
  | Need_private_origin ->
    let open Result.Let_syntax in
    let%bind captured = call t (Inherited_inference Capture_origin) in
    let%map observed = observe_descendant_origin_external t captured in
    Some observed
;;

let causal_plan_driver (causal : causal_plan_arm) =
  match causal.host with
  | Governed { causal; _ } -> causal
  | Physical_only _ ->
    (* Construction rejects this case before any slot is published. *)
    invalid_arg "causal Plan retained a physical-only host"
;;

let confirm_governed_attempt t (ack : Inherited_attempt.Acknowledgement.t) =
  let open Result.Let_syntax in
  let%bind confirmation =
    match ack.confirmation with
    | Some retained -> Ok retained
    | None ->
      (match ack.arms, ack.governed with
       | Descendant_attempt slot, Descendant_ack descendant ->
         let%map confirmation =
           (Descendant_admission_slot.host slot).confirm descendant
         in
         Descendant_confirmation confirmation
       | Policy_causal_attempt causal, Causal_ack canonical ->
         let%map confirmation = (causal_plan_driver causal).confirm canonical in
         Causal_confirmation confirmation
       | ( Combined_attempt { descendant = slot; causal }
         , Combined_ack (descendant, canonical) ) ->
         let%bind physical = (Descendant_admission_slot.host slot).confirm descendant in
         let%map policy = (causal_plan_driver causal).confirm canonical in
         Combined_confirmation (physical, policy)
       | ( (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _)
         , (Descendant_ack _ | Causal_ack _ | Combined_ack _) ) ->
         Error (error Conflict "governed inference ACK changed its closed arms"))
  in
  let%map () =
    call t ~priority:Priority (Inherited_inference (Confirm (ack, confirmation)))
  in
  confirmation
;;

let correct_governed_attempt (ack : Inherited_attempt.Acknowledgement.t) =
  match ack.arms, ack.governed, ack.confirmation with
  | Descendant_attempt _, Descendant_ack _, Some (Descendant_confirmation _) ->
    Ok Inference_owner.Factual_usage.Correction_outcome.Settled
  | ( Policy_causal_attempt causal
    , Causal_ack canonical
    , Some (Causal_confirmation confirmed) )
  | ( Combined_attempt { causal; _ }
    , Combined_ack (_, canonical)
    , Some (Combined_confirmation (_, confirmed)) ) ->
    (causal_plan_driver causal).correct_usage canonical confirmed
  | ( (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _)
    , (Descendant_ack _ | Causal_ack _ | Combined_ack _)
    , ( None
      | Some (Descendant_confirmation _ | Causal_confirmation _ | Combined_confirmation _)
        ) ) ->
    Error (error Conflict "governed inference initial confirmation remains pending")
;;

let close_unattempted_inherited_attempt t (plan : Inherited_attempt.Plan.t) =
  let open Result.Let_syntax in
  let%bind closed = call t ~priority:Priority (Inherited_inference (Seal plan)) in
  match plan.arms, closed with
  | Descendant_attempt slot, Descendant_closed closed ->
    let%map _ = schedule_descendant_admission_cleanup t slot ~closed in
    ()
  | Policy_causal_attempt _, Causal_closed _ | Combined_attempt _, Combined_closed _ ->
    let%bind promise = schedule_governed_plan_cleanup t plan in
    Actor_reply.await promise
  | ( (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _)
    , (Descendant_closed _ | Causal_closed _ | Combined_closed _) ) ->
    Error (error Conflict "governed cleanup changed its closed arms")
;;

let drive_inherited_attempt t (plan : Inherited_attempt.Plan.t) =
  let open Result.Let_syntax in
  let refresh_original () =
    match plan.original with
    | Legacy _ -> Ok ()
    | Runtime { startup = Initialization (_, (Initial _ as construction)); execution; _ }
      ->
      let%bind () = Runtime_construction.refresh construction in
      refresh_execution_descendant t execution
    | Runtime { execution; _ } -> refresh_held_execution t execution
  in
  let transferred = ref false in
  let cleanup () =
    if not !transferred
    then
      Eio.Cancel.protect (fun () ->
        ignore
          ((match plan.acknowledged with
            | None -> close_unattempted_inherited_attempt t plan
            | Some acknowledgement ->
              call t ~priority:Priority (Inherited_inference (Release acknowledgement)))
           : (unit, Agent_protocol.Error.t) result))
  in
  Exn.protect
    ~finally:(fun () ->
      try cleanup () with
      | exn ->
        (try Eio.traceln "governed Attempt cleanup failed: %s" (Exn.to_string exn) with
         | _ -> ()))
    ~f:(fun () ->
      let%bind physical =
        match inherited_attempt_physical plan with
        | None -> Ok None
        | Some slot ->
          let%bind views =
            (Descendant_admission_slot.host slot).prepare
              slot.preparation
              slot.reservations
          in
          (* A physical root can also own this held occurrence. Its reservation
             advances the Store observation that the original runtime checks. *)
          let%map () = refresh_original () in
          Some views
      in
      let%bind () = call t (Inherited_inference (Preview (plan, physical))) in
      let%bind policy =
        match inherited_attempt_causal plan with
        | None -> Ok None
        | Some causal ->
          (causal_plan_driver causal).prepare causal.slot.preparation causal.reservations
          |> Result.map ~f:Option.some
      in
      let%bind before_writer =
        match physical, policy with
        | Some physical, None -> Ok (Descendant_before physical)
        | None, Some policy -> Ok (Causal_before policy)
        | Some physical, Some policy -> Ok (Combined_before (physical, policy))
        | None, None ->
          Error (error Invalid_state "governed inference has no prewriter arm")
      in
      (* A causal reservation can advance the same owner again. Reacquire the
         original runtime's observation outside the target mailbox. *)
      let%bind () =
        match policy, plan.original with
        | Some _, _ -> refresh_original ()
        | None, Legacy _ -> Ok ()
        | None, Runtime { execution; _ } -> refresh_execution_descendant t execution
      in
      let%bind committed =
        Eio.Cancel.protect (fun () ->
          call t (Inherited_inference (Commit (plan, before_writer))))
      in
      match committed with
      | Attempt_unconfirmed _ ->
        Error (error Conflict "governed inference canonical writer remains unconfirmed")
      | Acknowledged acknowledgement ->
        let%bind registration =
          match acknowledgement.original with
          | Legacy { registration; _ } -> !registration
          | Runtime { selected; _ } ->
            Result.map !selected ~f:(fun selected ->
              selected.Admitted_inference.registration)
        in
        let%bind () =
          match Inference_owner.Registration.factual_usage registration with
          | None -> confirm_governed_attempt t acknowledgement |> Result.map ~f:ignore
          | Some facts -> Inference_owner.Factual_usage.confirm_initial facts
        in
        let%bind confirmation =
          Result.of_option
            acknowledgement.confirmation
            ~error:
              (error Conflict "governed initial duty has no exact confirmation vector")
        in
        let submission_guard =
          Inference_runtime.Submission_guard.create ~refresh:(fun () ->
            let refreshed =
              let%bind () =
                match acknowledgement.original with
                | Legacy _ -> Ok ()
                | Runtime { selected; execution; _ } ->
                  let%bind selected = !selected in
                  let%bind () = refresh_admitted_inference t selected in
                  refresh_execution_descendant t execution
              in
              let%bind views =
                match acknowledgement.arms, acknowledgement.governed, confirmation with
                | ( Descendant_attempt slot
                  , Descendant_ack descendant
                  , Descendant_confirmation confirmed ) ->
                  let%map views =
                    (Descendant_admission_slot.host slot).refresh_admitted
                      descendant
                      confirmed
                  in
                  Descendant_views views
                | ( Policy_causal_attempt causal
                  , Causal_ack canonical
                  , Causal_confirmation confirmed ) ->
                  let%map views =
                    (causal_plan_driver causal).refresh_admitted canonical confirmed
                  in
                  Causal_views views
                | ( Combined_attempt { descendant = slot; causal }
                  , Combined_ack (descendant, canonical)
                  , Combined_confirmation (physical, policy) ) ->
                  let%bind physical =
                    (Descendant_admission_slot.host slot).refresh_admitted
                      descendant
                      physical
                  in
                  let%map policy =
                    (causal_plan_driver causal).refresh_admitted canonical policy
                  in
                  Combined_views (physical, policy)
                | ( (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _)
                  , (Descendant_ack _ | Causal_ack _ | Combined_ack _)
                  , ( Descendant_confirmation _
                    | Causal_confirmation _
                    | Combined_confirmation _ ) ) ->
                  Error
                    (error Conflict "governed inference refresh changed its closed arms")
              in
              call
                t
                (Inherited_inference (Refresh (acknowledgement, confirmation, views)))
            in
            match refreshed with
            | Ok check -> check
            | Error error -> raise (Inference_allocation.Rejected error))
        in
        let allocation =
          Inference_allocation.Host.create ~handle:plan.handle ~submission_guard
        in
        transferred := true;
        Ok allocation)
;;

let finish_prepared_inference t = function
  | Inherited_attempt.Prepared.Ordinary allocation -> Ok allocation
  | Inherited plan -> drive_inherited_attempt t plan
;;

let settle_inference_usage t selected =
  let module Facts = Inference_graph_owner.Factual_usage in
  let open Result.Let_syntax in
  let sweep snapshot =
    let first = ref None in
    let deferred = ref false in
    let attempt f =
      match Inference_factual_failure.capture f with
      | Ok value -> Some value
      | Error failure ->
        if Option.is_none !first then first := Some failure;
        None
    in
    List.iter snapshot.Inference_usage_snapshot.initials ~f:(fun (facts, _) ->
      ignore (attempt (fun () -> Facts.confirm_initial facts) : unit option));
    List.iter snapshot.duties ~f:(fun (facts, _) ->
      match attempt (fun () -> Facts.settle_correction facts) with
      | Some Settled -> ()
      | Some Deferred -> deferred := true
      | None -> ());
    match !first with
    | Some failure -> Inference_factual_failure.resume (Error failure)
    | None -> Ok !deferred
  in
  let%bind before = call t (Capture_inference_usage selected) in
  let%bind deferred = sweep before in
  let%bind after = call t (Capture_inference_usage selected) in
  let%bind () =
    if deferred && not (Inference_usage_snapshot.same_progress before after)
    then Result.map (sweep after) ~f:ignore
    else Ok ()
  in
  let%bind clean = call t (Check_inference_usage selected) in
  if clean
  then (
    let%map () =
      match selected with
      | None -> call t Finalize_inference_usage
      | Some _ -> Ok ()
    in
    Facts.Drain_outcome.Settled)
  else Ok Facts.Drain_outcome.Deferred
;;

let settle_inference_owner_usage t ~owner = settle_inference_usage t (Some owner)

let finish_joined_inference_usage t owner clear =
  let%bind.Result outcome = settle_inference_owner_usage t ~owner in
  match outcome with
  | Settled -> clear ()
  | Deferred ->
    Error
      (Agent_protocol.Error.create
         Conflict
         ~message:"joined inference graph awaits actual initial confirmation"
         ~retryable:true
         ())
;;

let inference_usage_cleanup_pending t =
  if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
  then invalid_arg "Session_actor.inference_usage_cleanup_pending: foreign domain";
  let pending = ref false in
  List.iter t.inference_owners ~f:(fun custody ->
    let owner = Inference_graph_custody.owner custody in
    (match Graph_owner.Native_join.current owner with
     | Ok None -> ()
     | Ok (Some _) | Error _ -> pending := true);
    Graph_owner.iter_factual_usage owner ~f:(fun duty ->
      match Inference_graph_owner.Factual_usage.Host.pending duty with
      | Ok false -> ()
      | Ok true | Error _ -> pending := true));
  !pending
;;

let poll_inference_usage t = settle_inference_usage t None

let drain_inference_usage t =
  let open Result.Let_syntax in
  let%bind outcome = poll_inference_usage t in
  match outcome with
  | Settled -> Ok ()
  | Deferred ->
    Error
      (Agent_protocol.Error.create
         Conflict
         ~message:"inference facts await actual initial confirmation"
         ~retryable:true
         ())
;;

let inference_port t execution ~graph ~relation ~configuration =
  let open Result.Let_syntax in
  let%bind () = drain_inference_usage t in
  let%bind () = retry_descendant_admission_cleanup t in
  let%bind () = refresh_held_execution t execution in
  let%bind origin_observation = observe_inference_origin t in
  let%bind prepared =
    Eio.Cancel.protect (fun () ->
      call
        t
        (Inherited_inference
           (Allocate_runtime
              (origin_observation, execution, graph, relation, configuration))))
  in
  finish_prepared_inference t prepared
;;

let validate_initialization_scope_current t scope =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_scope_basis t scope in
  let check_runtime_owner () =
    Option.value_map
      (Initialization_scope_data.construction scope)
      ~default:(Ok ())
      ~f:(function
      | Initial continuation ->
        continuation.Admitted_activation.Continuation.target.owned_basis ()
      | Existing_goal continuation ->
        continuation.Goal_continuation.binding.preparation.basis ()
      | Delegated_load load -> load.preparation.basis ())
  in
  let%bind () = check_runtime_owner () in
  let%bind () =
    Option.value_map
      (Initialization_scope_data.preparation_owner scope)
      ~default:(Ok ())
      ~f:(fun preparation ->
        Preparation_owner.check_current
          preparation
          ~owner:t.run_preparation_owner
          ~state:t.state)
  in
  let%bind () = check_runtime_owner () in
  validate_initialization_scope_basis t scope
;;

let validate_initialization_scope t scope =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_scope_current t scope in
  match scope.Initialization_scope_data.custody with
  | Ordinary -> Ok ()
  | Prepared preparation -> check_run_preparation t preparation
  | Runtime (Initial continuation) ->
    check_run_preparation t continuation.target.preparation
  | Runtime ((Existing_goal _ | Delegated_load _) as construction) ->
    check_runtime_construction_effect construction
;;

let begin_initialization_owned
      ?construction
      ?run_preparation
      ?original_actor
      ?(purpose = Initialization_scope_data.Purpose.Pending_initialization)
      t
      (expected : Session_state.t)
  =
  let open Result.Let_syntax in
  let%bind () =
    match t.constructor_models with
    | None -> Ok ()
    | Some _ ->
      Error (error Conflict "previous constructor retains unsettled Model producers")
  in
  let%bind () =
    match t.run_preparation with
    | Some (Existing_goal preparation) ->
      (match construction with
       | Some (Runtime_construction.Existing_goal continuation)
         when phys_equal continuation.binding.preparation preparation ->
         (match preparation.runtime_phase with
          | Constructing -> check_runtime_construction_effect (Existing_goal continuation)
          | Unclaimed
          | Starting_writer _
          | Starting_acknowledged
          | Running_writer _
          | Installed _
          | Callback_completed _
          | Handed_off _
          | Retired _
          | Closed ->
            Error (error Conflict "Goal initializer has no actual cold construction ACK"))
       | Some (Initial _ | Existing_goal _ | Delegated_load _) | None ->
         Error (error Conflict "existing Goal construction requires its actual owner"))
    | Some (Delegated_load active) ->
      (match construction with
       | Some (Runtime_construction.Delegated_load load)
         when phys_equal load.preparation active ->
         check_runtime_construction_effect (Runtime_construction.Delegated_load load)
       | Some (Initial _ | Existing_goal _ | Delegated_load _) | None ->
         Error (error Conflict "delegated Init requires its exact source owner"))
    | Some (Initial _) | None ->
      Option.value_map construction ~default:(Ok ()) ~f:check_runtime_construction_effect
  in
  let%bind () =
    match construction with
    | Some (Initial _ | Existing_goal _) -> Ok ()
    | Some (Delegated_load _) | None -> require_selected_execution t
  in
  exclude_effect_deferred t Ordinary_execution;
  let%bind () = validate_initialization_basis ?construction t ~purpose expected in
  let%bind () =
    match purpose with
    | Pending_initialization -> Ok ()
    | Runtime_construction ->
      if
        Int64.equal expected.counters.revision t.state.counters.revision
        && (Option.is_some original_actor
            || Option.is_some run_preparation
            || Option.exists construction ~f:(function
              | Runtime_construction.Initial _ | Existing_goal _ -> true
              | Delegated_load _ -> false))
      then Ok ()
      else
        Error
          (error
             Permission_denied
             "Ready construction requires current original custody or its exact Run \
              preparation and CAS")
  in
  let%bind () =
    match Inference.Selection.view t.state.spec.inference_target with
    | Captured _ -> Ok ()
    | Unresolved ->
      Error (error Migration_required "initialization requires a captured target")
  in
  match t.initialization_scope with
  | Some _ -> Error (error Conflict "another initialization scope is active")
  | None ->
    let custody : Initialization_scope_data.Custody.t =
      match construction, run_preparation with
      | Some construction, _ -> Runtime construction
      | None, Some preparation -> Prepared preparation
      | None, None -> Ordinary
    in
    let identity = ref () in
    let scope =
      Initialization_scope_data.
        { owner = t.initialization_owner
        ; identity
        ; callback_cleanup =
            Callback_cleanup_data.Host.initialization
              ~issuer:t.initialization_owner
              ~domain:t.runtime_source_domain
              ~scope:identity
        ; domain = t.runtime_source_domain
        ; purpose
        ; expected
        ; source_handoff = None
        ; acknowledged = Acknowledged.capture expected
        ; jobs = []
        ; graphs = []
        ; callback = Callback.Unclaimed
        ; control = None
        ; resource = None
        ; custody
        ; agent_admission =
            create_agent_admission (Option.map original_actor ~f:create_agent_custody)
        }
    in
    t.initialization_scope <- Some scope;
    (match construction with
     | Some (Runtime_construction.Initial continuation) ->
       Failed_startup_data.record_initialization
         continuation.target.cleanup
         scope.callback_cleanup
     | Some (Existing_goal _ | Delegated_load _) | None -> ());
    Ok scope
;;

let observe_goal_callback_control t control =
  let open Result.Let_syntax in
  let%bind () = Goal_callback_control.check control t.state in
  let%bind controller = require_recurrence_controller t in
  let%bind observed = Recurrence_controller.observe controller t.state in
  let%bind () = Goal_callback_control.check control t.state in
  if
    Recurrence_controller.is_current observed
    && not (Recurrence_controller.archived observed)
  then Ok ()
  else Error (error Conflict "Goal callback control Store source changed")
;;

(* This is an association with the actual constructor, never source metadata.
   Ordinary delegated loading has no Goal lifecycle owner. *)
let construction_control_owner = function
  | Runtime_construction.Initial continuation ->
    let activation = Admitted_activation.Continuation.target continuation in
    Some activation.control_owner
  | Existing_goal continuation -> Some continuation.binding.preparation.control_owner
  | Delegated_load _ -> None
;;

let construction_control = function
  | Runtime_construction.Initial continuation ->
    (Admitted_activation.Continuation.target continuation).control
  | Existing_goal continuation -> continuation.binding.preparation.control
  | Delegated_load _ -> None
;;

let install_construction_control construction control =
  match construction with
  | Runtime_construction.Initial continuation ->
    (Admitted_activation.Continuation.target continuation).control <- Some control
  | Existing_goal continuation -> continuation.binding.preparation.control <- Some control
  | Delegated_load _ -> ()
;;

let construction_settlement = function
  | Runtime_construction.Initial continuation ->
    (Admitted_activation.Continuation.target continuation).settled_callback
  | Existing_goal continuation -> continuation.binding.preparation.settled_callback
  | Delegated_load _ -> None
;;

let install_construction_settlement construction settlement =
  match construction with
  | Runtime_construction.Initial continuation ->
    (Admitted_activation.Continuation.target continuation).settled_callback
    <- Some settlement
  | Existing_goal continuation ->
    continuation.binding.preparation.settled_callback <- Some settlement
  | Delegated_load _ -> ()
;;

let check_construction_control_owner t construction (control : Goal_callback_control.t) =
  let open Result.Let_syntax in
  let%bind () =
    if
      Preparation_owner.belongs_to
        (Runtime_construction.preparation_owner construction)
        ~owner:t.run_preparation_owner
      && Option.exists
           (construction_control_owner construction)
           ~f:(phys_equal control.owner)
      && Option.exists (construction_control construction) ~f:(phys_equal control)
      && Option.is_none t.queued_event_borrow
      && not (moderator_is_borrowed t)
    then Ok ()
    else Error (error Conflict "Goal callback control lost its actual joined owner")
  in
  match construction with
  | Initial continuation ->
    let activation = Admitted_activation.Continuation.target continuation in
    let%bind () = Runtime_source_preparation.validate_target activation.source t.state in
    Run_admission.Scope.check_current activation.scope
  | Existing_goal continuation ->
    let%bind () =
      Runtime_source_preparation.validate_target continuation.binding.source t.state
    in
    Run_admission.Scope.check_current
      (Run_authorities.scope continuation.binding.preparation.binding)
  | Delegated_load _ -> Error (error Conflict "ordinary load has no Goal callback owner")
;;

let check_construction_control t construction control =
  let open Result.Let_syntax in
  let%bind () = check_construction_control_owner t construction control in
  Goal_callback_control.check control t.state
;;

(* Releasing an actual callback startup hold may complete an already accepted
   Finish. Reuse the canonical aggregate planner and writer; no effect, retry or
   new Operation is admitted. Unfinished independent work remains admitted. *)
let goal_callback_settlement index ~episode run =
  let open Result.Let_syntax in
  let receipts =
    List.filter (Run_state.receipts index) ~f:(fun receipt ->
      Agent_protocol.Run_receipt.Kind.equal receipt.kind Terminal
      && Agent_protocol.Id.Run.equal receipt.run_id run.Agent_protocol.Run.id
      && Int64.equal receipt.run_revision run.revision)
  in
  let%bind receipt =
    match receipts with
    | [ receipt ] -> Ok receipt
    | _ ->
      Error (error Conflict "Goal callback terminal Run has no exact terminal receipt")
  in
  Agent_protocol.Goal_episode.Settlement.create episode ~run ~receipt
;;

let goal_resume_settlement index preparation run =
  goal_callback_settlement
    index
    ~episode:(Run_goal_link.episode preparation.Goal_continuation.link)
    run
;;

(* A cold Init may have completed the actual terminal writer before its partial
   runtime closes. This cache belongs only to that actual lifecycle owner. Validate
   real terminal evidence, without reinterpreting a stale control projection. *)
let observe_callback_settlement t construction control settlement =
  let open Result.Let_syntax in
  let check () =
    let%bind () = check_construction_control_owner t construction control in
    let%bind index =
      Result.of_option
        t.state.run_state
        ~error:(error Conflict "callback settlement lost its Run index")
    in
    let%bind run =
      Result.of_option
        (Run_state.find index control.Goal_callback_control.run.id)
        ~error:(error Conflict "callback settlement lost its Run")
    in
    let%bind () =
      if
        Option.exists
          (Run_state.goal_link index run.id)
          ~f:(Run_goal_link.equal control.link)
      then Ok ()
      else Error (error Conflict "callback settlement changed its episode association")
    in
    let%bind actual =
      goal_callback_settlement index ~episode:(Run_goal_link.episode control.link) run
    in
    if Agent_protocol.Goal_episode.Settlement.equal settlement actual
    then Ok (index, run)
    else Error (error Conflict "callback settlement changed its terminal receipt")
  in
  let%bind _ = check () in
  let%bind controller = require_recurrence_controller t in
  let%bind observed = Recurrence_controller.observe controller t.state in
  let%bind current = check () in
  if
    Recurrence_controller.is_current observed
    && not (Recurrence_controller.archived observed)
  then Ok current
  else Error (error Conflict "callback settlement Store source changed")
;;

let settle_controlled_callback t construction control =
  let open Result.Let_syntax in
  let check () = check_construction_control t construction control in
  let%bind () = check () in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "controlled callback lost its Run index")
  in
  let run = control.Goal_callback_control.run in
  let pending_finish =
    List.exists (Run_state.intents index) ~f:(fun intent ->
      Agent_protocol.Id.Run.equal intent.Run_intent.receipt.run_id run.id
      && Run_intent.Disposition.equal intent.disposition Pending
      &&
      match intent.action with
      | Finish _ -> true
      | Continue | Wait _ -> false)
  in
  match run.lifecycle with
  | Terminal _ -> Ok (Some (index, run))
  | Waiting _ -> Ok None
  | (Admitted | Active) when not pending_finish -> Ok None
  | Admitted | Active ->
    let now, sample = completion_clock_pair t in
    let%bind settled =
      Run_work_settlement.prepare
        index
        ~state:t.state
        ~previous:run
        ~owned_work:run.owned_work
        ~terminal_work:run.terminal_work
        ~operation_id:None
        ~now
    in
    let%bind current =
      Result.of_option
        (Run_state.find settled run.id)
        ~error:(error Conflict "controlled Finish lost its Run")
    in
    (match current.lifecycle with
     | Admitted | Active | Waiting _ -> Ok None
     | Terminal _ ->
       let%bind candidate =
         prepare_transition t ~delta:(Run_state_changed settled) ~payloads:[]
       in
       let%bind completions = prepare_completion_plan t candidate (Some sample) in
       let%bind settlement =
         goal_callback_settlement
           settled
           ~episode:(Run_goal_link.episode control.link)
           current
       in
       let revision = t.state.counters.revision in
       let%map () =
         Eio.Cancel.protect (fun () ->
           let%bind () =
             persist_transition t candidate ~check_before_commit:(fun () ->
               let%bind () = check () in
               if Int64.equal revision t.state.counters.revision
               then Ok ()
               else Error (error Conflict "controlled Finish basis changed"))
           in
           install_committed_transition t candidate;
           install_construction_settlement construction settlement;
           Option.iter
             completions
             ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
           publish_committed_transition t candidate;
           Ok ())
       in
       Some (settled, current))
;;

(* First consumption requires exact callback candidate equality. Later factual
   consumption may use only the SAME owner's independently ACKed terminal proof. *)
let complete_controlled_callback t construction control =
  let open Result.Let_syntax in
  match construction_settlement construction with
  | Some settlement ->
    let%map current = observe_callback_settlement t construction control settlement in
    Some current
  | None ->
    let%bind () = observe_goal_callback_control t control in
    let%bind settled = settle_controlled_callback t construction control in
    let%map () =
      match settled with
      | None -> Ok ()
      | Some (index, run) ->
        let%map settlement =
          goal_callback_settlement index ~episode:(Run_goal_link.episode control.link) run
        in
        install_construction_settlement construction settlement
    in
    settled
;;

let initialization_goal_completion_internal t (scope : Initialization_scope_data.t) =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_owner t scope in
  match scope.control with
  | None -> Ok None
  | Some control ->
    let%bind construction =
      Result.of_option
        (Initialization_scope_data.construction scope)
        ~error:(error Conflict "controlled Init lost its construction")
    in
    let%bind () =
      if
        Option.exists t.initialization_scope ~f:(phys_equal scope)
        && Option.is_none t.queued_event_borrow
        && (not (moderator_is_borrowed t))
        && (match scope.callback with
            | Settled id ->
              Agent_protocol.Id.Moderator_execution.equal id control.callback
            | Unclaimed | Claimed _ -> false)
        && Option.exists
             (construction_control_owner construction)
             ~f:(phys_equal control.owner)
        && Option.exists (construction_control construction) ~f:(phys_equal control)
      then Ok ()
      else Error (error Conflict "controlled Init has not joined its exact owner")
    in
    let%bind settled = complete_controlled_callback t construction control in
    let%map completion =
      match settled with
      | None -> Ok (Goal_callback_completion.Controlled control)
      | Some (index, run) ->
        let%map settlement =
          goal_callback_settlement index ~episode:(Run_goal_link.episode control.link) run
        in
        Goal_callback_completion.Settled settlement
    in
    Some completion
;;

let begin_initialization ?run_preparation ?original_actor ?purpose t expected =
  begin_initialization_owned ?run_preparation ?original_actor ?purpose t expected
;;

(* Selected keys identify only this constructor's already acknowledged rows.
   They contain no loan and cannot reconstruct an absent process-local row. *)
let retire_constructor_rows t (resource : Initialization_scope_data.Resource.t) =
  t.legacy_queue_custody
  <- Legacy_queue_custody.install
       t.legacy_queue_custody
       ~incoming:
         (Legacy_queue_custody.without_constructor
            t.legacy_queue_custody
            ~manager:resource.manager
            ~source:resource.source
            ~ordinals:resource.ordinals);
  t.legacy_schedule_custody
  <- Legacy_schedule_custody.install
       t.legacy_schedule_custody
       ~incoming:
         (Legacy_schedule_custody.without_constructor
            t.legacy_schedule_custody
            ~manager:resource.manager
            ~source:resource.source
            ~ids:resource.schedules)
;;

let retire_initialization_resource t (scope : Initialization_scope_data.t) manager =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_owner t scope in
  match scope.resource with
  | None -> Ok ()
  | Some resource when phys_equal manager resource.manager ->
    retire_constructor_rows t resource;
    Ok ()
  | Some _ -> Error (error Conflict "constructor cleanup names a different Manager")
;;

let check_constructor_callback_settled (scope : Initialization_scope_data.t) =
  match scope.callback with
  | Unclaimed | Settled _ -> Ok ()
  | Claimed _ -> Error (error Conflict "constructor callback has not settled")
;;

let prepare_constructor_resource_handoff
      t
      (scope : Initialization_scope_data.t)
      (state : Session_state.t)
      manager
  =
  let open Result.Let_syntax in
  let%bind () = check_constructor_callback_settled scope in
  match scope.resource, manager with
  | None, _ -> Ok None
  | Some resource, Some manager ->
    let%bind () =
      if
        phys_equal resource.manager manager
        && Option.equal
             Agent_protocol.Run_source.equal
             (retained_moderator_source state)
             (Some resource.source)
      then Ok ()
      else Error (error Conflict "constructor handoff resource or source changed")
    in
    let%bind () =
      Legacy_queue_custody.validate_constructor_handoff
        t.legacy_queue_custody
        ~manager
        ~source:resource.source
        ~ordinals:resource.ordinals
    in
    let%map () =
      Legacy_schedule_custody.validate_constructor_handoff
        t.legacy_schedule_custody
        ~manager
        ~source:resource.source
        ~ids:resource.schedules
    in
    Some { resource with handed_off = true }
  | Some _, None ->
    Error (error Conflict "constructor handoff requires its actual Manager")
;;

let end_initialization t scope =
  let open Result.Let_syntax in
  let%map () = validate_initialization_owner t scope in
  Callback_cleanup_data.Host.end_initialization_registration scope.callback_cleanup;
  match t.initialization_scope with
  | Some active when phys_equal active scope ->
    Option.iter active.resource ~f:(fun resource ->
      if not resource.handed_off then retire_constructor_rows t resource);
    retire_agent_admission active.agent_admission;
    Option.iter t.constructor_models ~f:(fun group ->
      if phys_equal group.scope active then group.ended <- true);
    t.initialization_scope <- None
  | Some _ | None -> ()
;;

let check_initialization_agent_actor scope =
  check_agent_admission scope.Initialization_scope_data.agent_admission
;;

let prepare_initialization_job_selection t (scope : Initialization_scope_data.t) =
  let open Result.Let_syntax in
  match Initialization_scope_data.preparation_owner scope with
  | None -> Ok (scope.jobs, None)
  | Some preparation ->
    let%map ids, selection =
      Preparation_owner.Constructor_jobs.prepare_handoff
        preparation
        ~owner:t.run_preparation_owner
        ~state:t.state
    in
    ( List.dedup_and_sort (scope.jobs @ ids) ~compare:Agent_protocol.Id.Job.compare
    , Some selection )
;;

(* All fresh constructor DATA writers use the authentic Init checkpoint and
   one actual preparation owner. The initial adapter still supplies its typed
   RP where source binding requires it; an existing Goal is never coerced. *)
let initialization_transition ?admission_hold ?job_custody t scope ~delta ~payloads =
  let open Result.Let_syntax in
  let run_preparation = Initialization_scope_data.initial_preparation scope in
  let check_owner () =
    let%bind () = validate_initialization_scope t scope in
    check_initialization_agent_actor scope
  in
  let%bind () = check_owner () in
  let completion_sample = producer_completion_sample t ~delta in
  let%bind candidate =
    prepare_transition ?completion_sample ?run_preparation t ~delta ~payloads
  in
  let acknowledgement =
    Initialization_scope_data.Acknowledgement.prepare scope candidate.state
  in
  let check_before_commit () =
    let%bind () = check_owner () in
    let%bind () =
      Option.value_map job_custody ~default:(Ok ()) ~f:(fun update ->
        Job_custody.Update.check_before_commit update ~current:t.job_agent_custody)
    in
    Initialization_scope_data.Acknowledgement.check_basis acknowledgement
  in
  install
    ?run_preparation
    ?admission_hold
    ?job_custody
    ?completion_sample
    ~initialization_acknowledgement:acknowledgement
    ~check_before_commit
    t
    candidate
;;

let complete_initialization
      t
      scope
      (candidate : Session_state.t)
      moderator_manager
      installed_originals
  =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_scope t scope in
  (* Reject before any Manager snapshot can reacquire the active callback gate. *)
  let%bind () = check_constructor_callback_settled scope in
  let%bind () =
    match scope.Initialization_scope_data.purpose with
    | Pending_initialization -> Ok ()
    | Runtime_construction ->
      Error
        (error
           Conflict
           "Ready construction cannot complete or fail Pending initialization")
  in
  let%bind () = check_initialization_agent_actor scope in
  let%bind moderator =
    Moderator_checkpoint.reuse_unchanged_snapshot
      ~previous:t.state.moderator
      ~incoming:candidate.moderator
  in
  let candidate = { candidate with moderator } in
  let expected = scope.Initialization_scope_data.expected in
  let projection =
    { candidate with
      conversation = expected.conversation
    ; moderator = expected.moderator
    ; shell = expected.shell
    }
    |> initialization_basis expected
  in
  let%bind () =
    if
      (not
         (Sexp.equal
            (Session_state.sexp_of_t expected)
            (Session_state.sexp_of_t projection)))
      || not
           (Document_schema.Json.equal
              (Inference.Selection.to_json expected.spec.inference_target)
              (Inference.Selection.to_json candidate.spec.inference_target))
    then Error (error Conflict "initialization candidate changed non-initializer fields")
    else Ok ()
  in
  let current = t.state in
  let%bind recovery_installed_originals =
    match
      ( current.recovery_installed_originals
      , installed_originals
      , Option.bind
          t.canonical_persistence
          ~f:Canonical_backend_binding_data.session_owner )
    with
    | (Some _ as previous), _, _ -> Ok previous
    | None, Some initial, Some owner
      when Recovery_installed_originals.Initial.matches_source
             initial
             ~definition:current.spec.prompt_definition_id
             ~revision:current.spec.prompt_revision_id ->
      Recovery_installed_originals.admit
        initial
        ~owner
        ~generation:current.identity.generation
        ~initial_rows:
          (List.take
             candidate.conversation.canonical_history
             candidate.conversation.initial_prompt_entry_count)
    | _ -> Ok None
  in
  let state =
    { current with
      runtime_initialization = Ready
    ; recovery_installed_originals
    ; failure = None
    ; lifecycle =
        { current.lifecycle with
          observed =
            (match current.lifecycle.observed with
             | Failed _ -> Agent_protocol.Session.Stopped
             | ( Stopped
               | Queued_for_slot
               | Starting
               | Recovering
               | Idle
               | Running_turn _
               | Compacting _
               | Waiting_for_permission _
               | Stopping ) as observed -> observed)
        }
    ; conversation =
        { current.conversation with
          canonical_history = candidate.conversation.canonical_history
        ; initial_prompt_entry_count = candidate.conversation.initial_prompt_entry_count
        ; next_history_sequence =
            Int64.max
              current.conversation.next_history_sequence
              candidate.conversation.next_history_sequence
        ; reserved_history_through =
            Int64.max
              current.conversation.reserved_history_through
              candidate.conversation.reserved_history_through
        }
    ; moderator = candidate.moderator
    ; shell =
        { current.shell with extension_snapshots = candidate.shell.extension_snapshots }
    }
  in
  let%bind () = Session_state.validate state in
  let run_preparation = Initialization_scope_data.initial_preparation scope in
  let%bind ids, selection = prepare_initialization_job_selection t scope in
  let%bind prepared, job_custody, _, revision =
    prepare_constructor_job_handoff
      ?run_preparation
      t
      ~delta:(Session_delta.Created state)
      ~payloads:
        [ Agent_protocol.Event.Durable.Payload.Session_updated
            (Session_state.summary state)
        ]
      ~ids
      ~manager:moderator_manager
  in
  Exn.protect
    ~finally:(fun () -> Option.iter job_custody ~f:Job_custody.Update.discard)
    ~f:(fun () ->
      let%bind resource =
        prepare_constructor_resource_handoff t scope prepared.state moderator_manager
      in
      let%bind before_source =
        Initialization_scope_data.Source_handoff.source scope.expected
      in
      let%bind after_source =
        Initialization_scope_data.Source_handoff.source prepared.state
      in
      let source_handoff : Initialization_scope_data.Source_handoff.t =
        { issuer = t.initialization_owner
        ; domain = t.runtime_source_domain
        ; scope = scope.identity
        ; session_id = prepared.state.identity.session_id
        ; generation = prepared.state.identity.generation
        ; spec = Session_state.Spec.Resource_identity.capture prepared.state.spec
        ; before_source
        ; after_source
        ; manager = moderator_manager
        }
      in
      let acknowledgement =
        Initialization_scope_data.Acknowledgement.prepare
          ?resource
          ~source_handoff
          scope
          prepared.state
      in
      Eio.Cancel.protect (fun () ->
        let%bind () = validate_initialization_scope t scope in
        let%bind () = check_initialization_agent_actor scope in
        let%bind () =
          Option.value_map selection ~default:(Ok ()) ~f:(fun selection ->
            Preparation_owner.Constructor_jobs.check_before_commit
              selection
              ~owner:t.run_preparation_owner
              ~state:t.state)
        in
        let%bind () =
          check_constructor_job_handoff
            t
            ~prepared
            ~job_custody
            ~manager:moderator_manager
            ~revision
        in
        let%bind _ =
          prepare_constructor_resource_handoff t scope prepared.state moderator_manager
        in
        let%bind () =
          Initialization_scope_data.Acknowledgement.check_basis acknowledgement
        in
        let%bind () = persist_transition ?run_preparation t prepared in
        install_committed_transition
          ?run_preparation
          ?job_custody
          ~initialization_acknowledgement:acknowledgement
          t
          prepared;
        Option.iter selection ~f:Preparation_owner.Constructor_jobs.acknowledge;
        publish_committed_transition t prepared;
        Ok (Session_state.summary t.state)))
;;

let checkpoint_runtime_construction t scope moderator moderator_manager =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_scope t scope in
  (* Reject before any Manager snapshot can reacquire the active callback gate. *)
  let%bind () = check_constructor_callback_settled scope in
  let%bind () =
    match scope.Initialization_scope_data.purpose with
    | Runtime_construction -> Ok ()
    | Pending_initialization ->
      Error (error Conflict "Pending construction requires initialization completion")
  in
  let%bind () = check_initialization_agent_actor scope in
  let%bind moderator =
    Moderator_checkpoint.reuse_unchanged_snapshot
      ~previous:t.state.moderator
      ~incoming:moderator
  in
  let%bind ids, selection = prepare_initialization_job_selection t scope in
  let run_preparation = Initialization_scope_data.initial_preparation scope in
  let%bind prepared, job_custody, source_changed, revision =
    prepare_constructor_job_handoff
      ?run_preparation
      t
      ~delta:(Session_delta.Moderator_changed moderator)
      ~payloads:[]
      ~ids
      ~manager:moderator_manager
  in
  Exn.protect
    ~finally:(fun () -> Option.iter job_custody ~f:Job_custody.Update.discard)
    ~f:(fun () ->
      let%bind resource =
        prepare_constructor_resource_handoff t scope prepared.state moderator_manager
      in
      let needs_handoff =
        Option.exists scope.resource ~f:(fun resource -> not resource.handed_off)
      in
      if
        (not needs_handoff)
        && Option.equal Jsonaf.exactly_equal t.state.moderator moderator
        && (not source_changed)
        && Option.is_none job_custody
      then Ok (Session_state.summary t.state)
      else (
        let acknowledgement =
          Initialization_scope_data.Acknowledgement.prepare ?resource scope prepared.state
        in
        let%bind () =
          validate_initialization_projection
            (Initialization_scope_data.Acknowledgement.expected acknowledgement)
            prepared.state
        in
        Eio.Cancel.protect (fun () ->
          let%bind () = validate_initialization_scope t scope in
          let%bind () = check_initialization_agent_actor scope in
          let%bind () =
            Option.value_map selection ~default:(Ok ()) ~f:(fun selection ->
              Preparation_owner.Constructor_jobs.check_before_commit
                selection
                ~owner:t.run_preparation_owner
                ~state:t.state)
          in
          let%bind () =
            check_constructor_job_handoff
              t
              ~prepared
              ~job_custody
              ~manager:moderator_manager
              ~revision
          in
          let%bind () =
            Initialization_scope_data.Acknowledgement.check_basis acknowledgement
          in
          let%bind _ =
            prepare_constructor_resource_handoff t scope prepared.state moderator_manager
          in
          let%bind () = persist_transition ?run_preparation t prepared in
          install_committed_transition
            ?run_preparation
            ?job_custody
            ~initialization_acknowledgement:acknowledgement
            t
            prepared;
          Option.iter selection ~f:Preparation_owner.Constructor_jobs.acknowledge;
          publish_committed_transition t prepared;
          Ok (Session_state.summary t.state))))
;;

let checkpoint_owned_moderator t preparation ~check moderator moderator_manager =
  let open Result.Let_syntax in
  let%bind () = check () in
  let%bind moderator =
    Moderator_checkpoint.reuse_unchanged_snapshot
      ~previous:t.state.moderator
      ~incoming:moderator
  in
  let%bind ids, selection =
    Preparation_owner.Constructor_jobs.prepare_handoff
      preparation
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  let%bind prepared, job_custody, source_changed, revision =
    prepare_constructor_job_handoff
      ?run_preparation:(Preparation_owner.initial preparation)
      t
      ~delta:(Session_delta.Moderator_changed moderator)
      ~payloads:[]
      ~ids
      ~manager:moderator_manager
  in
  if
    Option.equal Jsonaf.exactly_equal t.state.moderator moderator
    && (not source_changed)
    && Option.is_none job_custody
  then Ok (Session_state.summary t.state)
  else
    Exn.protect
      ~finally:(fun () -> Option.iter job_custody ~f:Job_custody.Update.discard)
      ~f:(fun () ->
        Eio.Cancel.protect (fun () ->
          let%bind () = check () in
          let%bind () =
            Preparation_owner.Constructor_jobs.check_before_commit
              selection
              ~owner:t.run_preparation_owner
              ~state:t.state
          in
          let%bind () =
            check_constructor_job_handoff
              t
              ~prepared
              ~job_custody
              ~manager:moderator_manager
              ~revision
          in
          let%bind () = persist_transition t prepared in
          install_committed_transition_owned
            ~preparation_owner:(Some preparation)
            ?job_custody
            t
            prepared;
          Preparation_owner.Constructor_jobs.acknowledge selection;
          publish_committed_transition t prepared;
          Ok (Session_state.summary t.state)))
;;

let checkpoint_run_moderator t preparation moderator moderator_manager =
  checkpoint_owned_moderator
    t
    (Preparation_owner.Initial preparation)
    ~check:(fun () -> check_run_preparation t preparation)
    moderator
    moderator_manager
;;

let fail_initialization t scope failure =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_scope t scope in
  let%bind () =
    match scope.Initialization_scope_data.purpose with
    | Pending_initialization -> Ok ()
    | Runtime_construction ->
      Error
        (error
           Conflict
           "Ready construction cannot complete or fail Pending initialization")
  in
  let lifecycle =
    { t.state.lifecycle with Session_state.Lifecycle.observed = Failed failure }
  in
  transition
    ?run_preparation:(Initialization_scope_data.initial_preparation scope)
    t
    ~delta:
      (Session_delta.Batch [ Failure_changed (Some failure); Lifecycle_changed lifecycle ])
    ~payloads:
      [ Agent_protocol.Event.Durable.Payload.Session_state_changed
          { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
      ]
;;

let reset_internal t attachment_id expected_revision options =
  let open Result.Let_syntax in
  let%bind () = validate_administrative_state t attachment_id expected_revision in
  let%bind state = Administration.reset t.state options in
  commit_administration t attachment_id expected_revision Reset state
;;

let upgrade_prompt_internal t attachment_id expected_revision target_revision =
  let open Result.Let_syntax in
  let%bind () = validate_administrative_state t attachment_id expected_revision in
  let previous_revision = t.state.spec.prompt_revision_id in
  if Agent_protocol.Id.Prompt_revision.compare previous_revision target_revision = 0
  then Ok (Session_state.summary t.state)
  else (
    let state =
      { t.state with
        spec = { t.state.spec with prompt_revision_id = target_revision }
      ; moderator = None
      ; shell = Session.Shell_state.empty
      ; failure = None
      }
    in
    transition
      t
      ~delta:(Session_delta.Created state)
      ~payloads:
        [ Agent_protocol.Event.Durable.Payload.Prompt_upgraded
            { prompt_id = Option.value_exn state.spec.prompt_definition_id
            ; previous_revision
            ; current_revision = target_revision
            }
        ; Session_updated (Session_state.summary state)
        ])
;;

let adoption_boundary t =
  match t.state.active_operation with
  | Some { Agent_protocol.Operation.kind = Turn _; id; _ } ->
    Pending_eligibility.Boundary.Worker id
  | Some { kind = Compaction; _ } | None -> Idle_start
;;

let adopt_deferred t =
  let open Result.Let_syntax in
  let%bind () = require_runtime_admission t in
  let%bind prepared =
    prepare_pending
      t
      (Adopt
         { boundary = adoption_boundary t
         ; runtime_admission_open = runtime_admission_open t
         })
  in
  let entries = Pending_plan.adopted_entries (Pending_transition.plan prepared) in
  if List.is_empty entries
  then Ok (Session_state.summary t.state)
  else (
    let%bind () = require_selected_execution t in
    transition
      t
      ~delta:(Pending_transition.delta prepared)
      ~payloads:[ Agent_protocol.Event.Durable.Payload.History_appended entries ])
;;

let reserve_history_block ?run_preparation ?check_before_commit t count =
  if count <= 0
  then Error (error Invalid_request "history reservation count must be positive")
  else if Int64.(t.state.conversation.next_history_sequence > max_value - of_int count)
  then Error (error Invalid_state "history sequence overflow")
  else (
    let first_sequence = t.state.conversation.next_history_sequence in
    let reserved_through = Int64.(first_sequence + of_int count) in
    let open Result.Let_syntax in
    let%map _ =
      transition
        ?run_preparation
        ?check_before_commit
        t
        ~delta:(Session_delta.History_block_reserved reserved_through)
        ~payloads:[]
    in
    History_id_source.{ first_sequence; reserved_through })
;;

let current_operation t operation_id =
  match t.state.active_operation with
  | Some operation when Agent_protocol.Id.Operation.compare operation.id operation_id = 0
    -> Ok operation
  | Some _ -> Error (error Conflict "a different foreground operation is active")
  | None -> Error (error Operation_not_found "foreground operation is not active")
;;

let foreground_publication_matches t publication =
  Foreground_publication.matches
    publication
    ~selected:t.foreground_publication
    ~state:t.state
;;

let check_foreground_publication t publication =
  if foreground_publication_matches t publication
  then Ok ()
  else Error (error Conflict "foreground worker no longer owns this context window")
;;

let check_live_foreground_publication t (publication : Foreground_publication.t) =
  let open Result.Let_syntax in
  let%bind () = check_foreground_publication t publication in
  let%bind operation = current_operation t publication.operation.id in
  match operation.state with
  | (Starting | Running) when Atomic.get publication.live -> Ok ()
  | Starting | Running | Cancelling | Completed | Failed _ | Cancelled | Interrupted _ ->
    Error (error Conflict "foreground worker publication has ended")
;;

let with_foreground_publication t (publication : Foreground_publication.t) f =
  let check () = check_live_foreground_publication t publication in
  let%bind.Result () = check () in
  f publication.operation.id ~check
;;

let running_operation
      ?(allow_stopping = false)
      ?(allow_waiting_permission = false)
      t
      operation_id
  =
  let open Result.Let_syntax in
  let%bind operation = current_operation t operation_id in
  match operation.state, t.state.lifecycle.desired, t.state.lifecycle.observed with
  | Agent_protocol.Operation.Running, desired, Running_turn id
    when (allow_stopping || Agent_protocol.Session.equal_desired_state desired Running)
         && Agent_protocol.Id.Operation.compare id operation_id = 0
         && not t.state.halted -> Ok operation
  | Running, desired, Waiting_for_permission _
    when allow_waiting_permission
         && (allow_stopping || Agent_protocol.Session.equal_desired_state desired Running)
         && not t.state.halted -> Ok operation
  | _ ->
    Error (error Invalid_state "foreground operation is not running at a tool safe point")
;;

(* Compaction is an inference-only owner, not a tool safe point. This private
   borrow belongs to the actual captured compaction worker; ordinary/native
   invocation admission deliberately continues to require [running_operation]. *)
let running_compaction t (expected : Agent_protocol.Operation.t) =
  let open Result.Let_syntax in
  let%bind () = require_runtime_admission t in
  let%bind current = current_operation t expected.id in
  match current.kind, current.state, t.state.lifecycle.observed with
  | Compaction, Running, Compacting id
    when Agent_protocol.Operation.equal_kind expected.kind Compaction
         && Int.equal current.generation expected.generation
         && Agent_protocol.Id.Operation.equal id expected.id
         && not t.state.halted -> Ok current
  | _ -> Error (error Conflict "compaction execution owner is no longer current")
;;

let invocation_origin t (invocation : Agent_protocol.Invocation.t) ~fallback =
  match invocation.context.parent_invocation with
  | None -> fallback ()
  | Some id ->
    (match
       List.find t.state.invocations ~f:(fun parent ->
         Agent_protocol.Id.Invocation.equal parent.context.id id)
     with
     | Some parent -> Ok parent.inference_origin
     | None -> Error (error Conflict "original parent invocation is unavailable"))
;;

let operation_invocation_origin t operation_id invocation =
  invocation_origin t invocation ~fallback:(fun () ->
    let open Result.Let_syntax in
    let%bind operation = current_operation t operation_id in
    Invocation_inference_provenance.of_operation ~runs:t.state.run_state operation
    |> Result.map ~f:Option.some)
;;

let event_inference_origin t (receipt : Agent_protocol.Moderator_execution.t) =
  let authored =
    Option.bind t.queued_event_borrow ~f:(fun borrow ->
      if Agent_protocol.Moderator_execution.equal borrow.receipt receipt
      then
        Option.map borrow.lifecycle_owner ~f:(fun owner ->
          let%map.Result run = lifecycle_event_run t borrow owner in
          Some (Agent_protocol.Inference_origin.Run run.id))
      else None)
  in
  match authored with
  | Some result -> result
  | None ->
    let held =
      Option.bind t.legacy_callback_scope ~f:(fun callback ->
        if
          Option.exists t.queued_event_borrow ~f:(phys_equal callback.borrow)
          && Agent_protocol.Moderator_execution.equal callback.borrow.receipt receipt
        then
          Option.bind callback.constructor_scope ~f:(fun scope ->
            Option.map (initialization_held_run t scope) ~f:(fun run ->
              callback.origin, run))
        else None)
    in
    (match held with
     | Some (Some (Run id), run) when Agent_protocol.Id.Run.equal id run.id ->
       Ok (Some (Agent_protocol.Inference_origin.Run id))
     | Some _ -> Error (error Conflict "held constructor origin disagrees with its Run")
     | None ->
       (match receipt.context.job with
        | Some _ ->
          Invocation_inference_provenance.of_event
            ~runs:t.state.run_state
            ~jobs:t.state.jobs
            receipt
        | None ->
          let open Result.Let_syntax in
          let%bind selected = Run_event_scope.select t.state ~executing:receipt in
          (match selected with
           | Some run -> Ok (Some (Agent_protocol.Inference_origin.Run run.id))
           | None ->
             Invocation_inference_provenance.of_event
               ~runs:t.state.run_state
               ~jobs:t.state.jobs
               receipt)))
;;

let event_invocation_origin t receipt invocation =
  invocation_origin t invocation ~fallback:(fun () -> event_inference_origin t receipt)
;;

let invocation_admission_deltas
      t
      (invocation : Agent_protocol.Invocation.t)
      ~origin
      ~boundary
  =
  let open Result.Let_syntax in
  let%bind () =
    if Option.is_none invocation.inference_origin
    then Ok ()
    else Error (error Invalid_request "invocation inference origin is actor captured")
  in
  let%bind () = Agent_protocol.Invocation.validate invocation in
  let%bind captured =
    match origin with
    | None -> Ok invocation
    | Some origin -> Agent_protocol.Invocation.capture_inference_origin invocation origin
  in
  match
    List.find t.state.invocations ~f:(fun current ->
      Agent_protocol.Id.Invocation.equal current.context.id invocation.context.id)
  with
  | None ->
    let%map policy, classification =
      policy_birth_metadata t (policy_invocation_birth ~boundary) captured
    in
    captured, Session_delta.Invocation_changed captured :: policy, classification
  | Some current
    when Agent_protocol.Invocation.equal_origin invocation.context.origin Model
         && Option.is_some invocation.context.call_entry_id
         && Agent_protocol.Invocation.equal current captured ->
    Ok (current, [], Policy_standalone_source.Classification.Unknown)
  | Some _ -> Error (error Conflict "invocation identity is already admitted")
;;

let commit_invocation_call
      t
      operation_id
      ~check
      (invocation : Agent_protocol.Invocation.t)
      entry
  =
  let open Result.Let_syntax in
  let%bind operation = current_operation t operation_id in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      invocation.context.session_id
      invocation.context.generation
  in
  let%bind () = Agent_protocol.Invocation.validate invocation in
  let%bind () =
    match
      ( invocation.status
      , invocation.context.origin
      , invocation.context.parent_job
      , invocation.context.parent_invocation
      , invocation.context.call_entry_id )
    with
    | Admitted, Model, None, None, Some id
      when History_entry.Id.equal id (History_entry.id entry) -> Ok ()
    | _ ->
      Error
        (error Invalid_request "call intent requires an admitted root model invocation")
  in
  let%bind () =
    if Option.is_none invocation.inference_origin
    then Ok ()
    else Error (error Invalid_request "call intent inference origin is actor captured")
  in
  let%bind origin =
    Invocation_inference_provenance.of_operation ~runs:t.state.run_state operation
  in
  let%bind invocation =
    Agent_protocol.Invocation.capture_inference_origin invocation origin
  in
  let encoded =
    History_codec.canonical_encoder ~previous:t.state.conversation.canonical_history entry
  in
  let%bind entries =
    match
      List.find t.state.conversation.canonical_history ~f:(fun item ->
        History_entry.Id.equal item.id encoded.id)
    with
    | None -> Ok [ encoded ]
    | Some existing when Agent_protocol.History.equal_entry existing encoded -> Ok []
    | Some _ -> Error (error Conflict "history call already has different content")
  in
  let%bind admission =
    match
      List.find t.state.invocations ~f:(fun current ->
        Agent_protocol.Id.Invocation.compare current.context.id invocation.context.id = 0)
    with
    | None -> Ok [ Session_delta.Invocation_changed invocation ]
    | Some current
      when List.is_empty entries
           && Option.equal
                Agent_protocol.Inference_origin.equal
                current.inference_origin
                invocation.inference_origin
           && Agent_protocol.Invocation.equal_context current.context invocation.context
           && Option.equal
                Agent_protocol.Invocation.equal_routing
                current.routing
                invocation.routing -> Ok []
    | Some _ -> Error (error Conflict "call intent identity has different content")
  in
  if List.is_empty entries && List.is_empty admission
  then Ok ()
  else
    transition
      ~check_before_commit:check
      t
      ~delta:
        (Session_delta.Batch
           ((if List.is_empty entries
             then []
             else [ Session_delta.Canonical_entries_appended entries ])
            @ admission))
      ~payloads:
        (if List.is_empty entries
         then []
         else [ Agent_protocol.Event.Durable.Payload.History_appended entries ])
    |> Result.map ~f:(fun _ -> ())
;;

let custody_of_admission = function
  | None -> Ok None
  | Some admission ->
    let open Result.Let_syntax in
    let%map () = check_agent_admission admission in
    Execution_custody.Admission.custody admission
;;

let job_agent_admission t scope =
  let open Result.Let_syntax in
  let%bind job = job_scope_current t scope in
  let%bind row = Job_custody.find t.job_agent_custody ~job in
  match row with
  | None -> Ok None
  | Some row -> Result.map (Job_custody.Row.admission row) ~f:Option.some
;;

let job_settlement_parent t scope =
  let open Result.Let_syntax in
  let%bind job = job_scope_current t scope in
  let%map row = Job_custody.find t.job_agent_custody ~job in
  Option.value_map
    row
    ~default:Observation_continuation.Parent.Unavailable
    ~f:Job_custody.Row.settlement_parent
;;

let job_callback_admission t scope ~manager ~source =
  let open Result.Let_syntax in
  let%bind job = job_scope_current t scope in
  let%bind row = Job_custody.find t.job_agent_custody ~job in
  match row with
  | None -> Ok None
  | Some row ->
    let%bind () =
      match Job_custody.Row.binding row with
      | Captured { source = captured; manager = Some resource }
        when Agent_protocol.Run_source.equal captured source
             && phys_equal resource manager -> Ok ()
      | No_captured_moderator | Captured _ ->
        Error
          (error Conflict "Job callback has no loan for this exact Manager and source")
    in
    Result.map (Job_custody.Row.admission row) ~f:Option.some
;;

let operation_agent_admission t id =
  match t.operation_agent_custody with
  | None -> Ok None
  | Some { Operation_owner.operation_id = owner; admission; _ } ->
    if Agent_protocol.Id.Operation.equal owner id
    then Ok (Some admission)
    else Error (error Conflict "operation admission belongs to another owner")
;;

let parent_of_admission = function
  | None -> Observation_continuation.Parent.Unavailable
  | Some admission -> Observation_continuation.Parent.Available admission
;;

let moderator_settlement_parent t (borrow : moderator_borrow) =
  match borrow.kind with
  | Observation ->
    Ok
      (Option.value_map
         borrow.observation
         ~default:Observation_continuation.Parent.Unavailable
         ~f:Observation_continuation.parent)
  | Invocation _ ->
    (match borrow.job_scope, borrow.operation_id with
     | Some scope, _ -> job_settlement_parent t scope
     | None, operation ->
       let admission =
         Option.value_map operation ~default:(Ok None) ~f:(operation_agent_admission t)
       in
       Result.map admission ~f:parent_of_admission)
;;

let moderator_agent_admission t (borrow : moderator_borrow) =
  match borrow.kind with
  | Observation ->
    (match borrow.observation with
     | Some observation ->
       Observation_continuation.admission observation |> Result.map ~f:Option.some
     | None -> Ok None)
  | Invocation _ ->
    (match borrow.job_scope, borrow.operation_id with
     | Some scope, _ -> job_agent_admission t scope
     | None, Some id -> operation_agent_admission t id
     | None, None -> Ok None)
;;

let moderator_agent_custody t borrow =
  Result.bind (moderator_agent_admission t borrow) ~f:custody_of_admission
;;

let event_agent_admission t (borrow : queued_event_borrow) =
  match borrow.agent_admission with
  | Resumed_run admission | Selected_queue admission | Delegated_policy admission ->
    Ok admission
  | Contextual admission ->
    (match t.legacy_callback_scope with
     | Some scope when phys_equal scope.borrow borrow ->
       (match scope.custody with
        | Unavailable -> Ok None
        | Admitted admission -> Ok (Some admission))
     | None | Some _ ->
       (match borrow.job_scope, borrow.receipt.context.operation_id with
        | Some scope, _ -> job_agent_admission t scope
        | None, Some id -> operation_agent_admission t id
        | None, None -> Ok admission))
;;

let execution_agent_admission t (execution : invocation_execution) =
  match execution.owner with
  | Foreground id -> operation_agent_admission t id
  | Invocation_moderator borrow -> moderator_agent_admission t borrow
  | Event_moderator borrow -> event_agent_admission t borrow
  | Background_job scope -> job_agent_admission t scope
;;

let event_settlement_parent t (borrow : queued_event_borrow) =
  match borrow.agent_admission with
  | Resumed_run admission | Selected_queue admission | Delegated_policy admission ->
    Ok (parent_of_admission admission)
  | Contextual admission ->
    (match t.legacy_callback_scope with
     | Some scope when phys_equal scope.borrow borrow ->
       Ok
         (match scope.custody with
          | Unavailable -> Observation_continuation.Parent.Unavailable
          | Admitted admission -> Observation_continuation.Parent.Available admission)
     | None | Some _ ->
       (match borrow.job_scope, borrow.receipt.context.operation_id with
        | Some scope, _ -> job_settlement_parent t scope
        | None, Some id ->
          Result.map (operation_agent_admission t id) ~f:parent_of_admission
        | None, None -> Ok (parent_of_admission admission)))
;;

let execution_settlement_parent t (execution : invocation_execution) =
  match execution.owner with
  | Invocation_moderator borrow -> moderator_settlement_parent t borrow
  | Event_moderator borrow -> event_settlement_parent t borrow
  | Background_job scope -> job_settlement_parent t scope
  | Foreground id -> Result.map (operation_agent_admission t id) ~f:parent_of_admission
;;

let settlement_custody = function
  | Observation_continuation.Parent.Available admission ->
    Execution_custody.Admission.custody admission
  | Expired | Unavailable -> None
;;

(* Both modern callback families save the actual queue carrier and source
   installation. These are facts only; loans come separately from the exact
   completed producer admission and become owned only at its checkpoint ACK. *)
let prepare_moderator_invocation_checkpoint t captured =
  let open Result.Let_syntax in
  let%bind persisted = Moderator_checkpoint.decode t.state.moderator in
  let%bind captured =
    match captured with
    | None -> Ok None
    | Some snapshot ->
      Moderator_checkpoint.decode (Some (Moderator_checkpoint.encode snapshot))
  in
  let%bind before =
    match persisted, captured with
    | Some persisted, Some captured ->
      if
        String.equal
          (Moderator_checkpoint.digest persisted)
          (Moderator_checkpoint.digest captured)
      then Ok (Some captured)
      else Error (error Conflict "captured moderator differs from persisted checkpoint")
    | Some persisted, None -> Ok (Some persisted)
    | None, Some captured -> Ok (Some captured)
    | None, None -> Ok None
  in
  let basis =
    Moderator_invocation_checkpoint.Basis.
      { checkpoint = t.state.moderator
      ; generation = t.state.identity.generation
      ; installation =
          Run_state.installation (Option.value t.state.run_state ~default:Run_state.empty)
      ; manager = t.moderator_manager
      }
  in
  match before, captured with
  | None, None ->
    let%bind untracked = moderator_untracked_data_basis t in
    if untracked
    then Ok (Moderator_invocation_checkpoint.Uncaptured_first basis)
    else
      Error (error Conflict "first moderator DATA checkpoint has tracked source custody")
  | Some before, None ->
    let%bind legacy = legacy_untracked_moderator_checkpoint t before in
    if legacy
    then Ok (Moderator_invocation_checkpoint.Legacy_untracked basis)
    else (
      let%map _ =
        Moderator_source_installation.capture_checkpoint t.state ~checkpoint:before
      in
      Moderator_invocation_checkpoint.Known_before { before; basis })
  | Some before, Some _ ->
    let%map _ =
      Moderator_source_installation.capture_checkpoint t.state ~checkpoint:before
    in
    Moderator_invocation_checkpoint.Known_before { before; basis }
  | None, Some _ -> Error (error Internal_error "captured moderator checkpoint was lost")
;;

let check_moderator_invocation_checkpoint t checkpoint =
  let basis =
    match checkpoint with
    | Moderator_invocation_checkpoint.Known_before { basis; _ }
    | Uncaptured_first basis
    | Legacy_untracked basis -> basis
  in
  if
    Int.equal basis.generation t.state.identity.generation
    && Option.equal Jsonaf.exactly_equal basis.checkpoint t.state.moderator
    && Run_source_installation.equal
         basis.installation
         (Run_state.installation
            (Option.value t.state.run_state ~default:Run_state.empty))
    && Option.equal phys_equal basis.manager t.moderator_manager
  then Ok ()
  else Error (error Conflict "moderator callback checkpoint basis changed")
;;

let capture_modern_callback_queue t ~before =
  let open Result.Let_syntax in
  let%bind index, source =
    Moderator_source_installation.capture_checkpoint t.state ~checkpoint:before
  in
  let%bind metadata = Moderator_checkpoint.queue t.state.moderator in
  let%bind metadata =
    match metadata with
    | Some metadata
      when Agent_protocol.Run_source.equal source (Moderator_queue.source metadata) ->
      Ok metadata
    | Some _ -> Error (error Conflict "callback queue source installation changed")
    | None ->
      Moderator_queue.bootstrap
        ~source
        ~queue:before.Session.Moderator_state.Identity_snapshot.queued_internal_events
  in
  Ok (index, metadata)
;;

let prepare_moderator_invocation_queue t checkpoint ~resolved ~snapshot =
  let open Result.Let_syntax in
  let%bind () = check_moderator_invocation_checkpoint t checkpoint in
  match checkpoint with
  | Moderator_invocation_checkpoint.Known_before { before; _ } ->
    let%bind index, metadata = capture_modern_callback_queue t ~before in
    let%map plan =
      Legacy_queue_checkpoint.prepare_invocation ~metadata ~before ~snapshot ~resolved
    in
    Moderator_callback_checkpoint.With_queue
      { index
      ; metadata = Legacy_queue_checkpoint.metadata plan
      ; appended = Legacy_queue_checkpoint.appended plan
      }
  | Uncaptured_first _ | Legacy_untracked _ ->
    let%bind untracked = moderator_untracked_data_basis t in
    if untracked
    then Ok Moderator_callback_checkpoint.Bare_snapshot
    else
      Error (error Conflict "untracked moderator DATA checkpoint acquired source custody")
;;

let stage_completed_callback_queue ~manager ~metadata ~entries ~parent =
  match manager, parent with
  | None, _ | Some _, Observation_continuation.Parent.Unavailable ->
    Ok Legacy_queue_custody.empty
  | Some manager, Available parent ->
    Legacy_queue_custody.stage_completed
      ~manager
      ~source:(Moderator_queue.source metadata)
      ~entries
      ~parent
  | Some manager, Expired ->
    Ok
      (Legacy_queue_custody.stage_expired
         ~manager
         ~source:(Moderator_queue.source metadata)
         ~entries)
;;

let callback_queue_inventory t ~manager ~metadata ~staged =
  match manager with
  | None ->
    Ok
      (Legacy_queue_custody.matching
         t.legacy_queue_custody
         ~manager:None
         ~metadata:(Some metadata))
  | Some manager ->
    Legacy_queue_custody.candidate t.legacy_queue_custody ~manager ~metadata ~staged
;;

let check_callback_queue_source t ~manager ~metadata =
  let open Result.Let_syntax in
  let%bind _, source = Moderator_source_installation.capture t.state in
  if
    Option.equal phys_equal manager t.moderator_manager
    && Agent_protocol.Run_source.equal source (Moderator_queue.source metadata)
  then Ok ()
  else Error (error Conflict "callback queue Manager or source changed before ACK")
;;

let execution_agent_custody t execution =
  Result.bind (execution_agent_admission t execution) ~f:custody_of_admission
;;

let job_moderator_binding t =
  let open Result.Let_syntax in
  let%bind observer = Moderator_checkpoint.observer t.state.moderator in
  match observer with
  | None -> Ok Job_custody.Moderator_binding.No_captured_moderator
  | Some _ ->
    let%map _, source = Moderator_source_installation.capture t.state in
    Job_custody.Moderator_binding.Captured { source; manager = t.moderator_manager }
;;

let check_job_moderator_binding t = function
  | Job_custody.Moderator_binding.No_captured_moderator ->
    let open Result.Let_syntax in
    let%bind observer = Moderator_checkpoint.observer t.state.moderator in
    (match observer with
     | None -> Ok ()
     | Some _ -> Error (error Conflict "Job admission acquired a different source"))
  | Captured { source; manager } ->
    let open Result.Let_syntax in
    let%bind _, current = Moderator_source_installation.capture t.state in
    if
      Agent_protocol.Run_source.equal source current
      && Option.for_all manager ~f:(fun manager ->
        Option.exists t.moderator_manager ~f:(phys_equal manager))
    then Ok ()
    else Error (error Conflict "Job admission source or resource changed")
;;

let prepare_selected_job_custody t owner =
  let open Result.Let_syntax in
  let selected =
    Staged_jobs.selected_payloads t.staged_jobs ~owner
    |> List.filter_map ~f:(fun ((job : Agent_protocol.Job.t), fresh) ->
      match job.status, fresh with
      | Queued, Some fresh -> Some (job, fresh)
      | Queued, None -> None
      | ( ( Running
          | Waiting_permission _
          | Waiting_completion _
          | Succeeded
          | Failed _
          | Cancelled
          | Interrupted _ )
        , _ ) -> None)
  in
  let%map update = Job_custody.prepare_selected t.job_agent_custody ~selected in
  update, selected
;;

let check_selected_job_custody t update selected =
  let open Result.Let_syntax in
  let%bind () =
    List.fold_result selected ~init:() ~f:(fun () (_, fresh) ->
      let binding = Job_custody.Fresh.binding fresh in
      let%bind () = check_job_moderator_binding t binding in
      match binding with
      | No_captured_moderator -> Ok ()
      | Captured { source = _; manager } ->
        if Option.equal phys_equal manager t.moderator_manager
        then Ok ()
        else Error (error Conflict "staged Job admission resource topology changed"))
  in
  Job_custody.Update.check_before_commit update ~current:t.job_agent_custody
;;

let with_selected_job_custody t owner f =
  let open Result.Let_syntax in
  let%bind update, selected = prepare_selected_job_custody t owner in
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () -> if not !acknowledged then Job_custody.Update.discard update)
    ~f:(fun () ->
      f
        ~job_custody:update
        ~check_jobs:(fun () -> check_selected_job_custody t update selected)
        ~acknowledge_jobs:(fun () ->
          acknowledged := true;
          Staged_jobs.commit t.staged_jobs ~owner))
;;

let claim_invocation t operation_id (invocation : Agent_protocol.Invocation.t) =
  let open Result.Let_syntax in
  let%bind () = check_operation_descendant t operation_id in
  let%bind () = require_selected_execution t in
  let%bind _ = running_operation t operation_id in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      invocation.context.session_id
      invocation.context.generation
  in
  let%bind () =
    if
      Option.is_some invocation.context.parent_job
      || Option.is_some invocation.parent_event
    then
      Error
        (error
           Invalid_state
           "foreground invocation cannot borrow background-job ownership")
    else Ok ()
  in
  let%bind owner =
    match invocation.context.parent_invocation with
    | None -> Ok (Foreground operation_id)
    | Some parent ->
      let owned id op =
        Agent_protocol.Id.Invocation.compare id parent = 0
        && Agent_protocol.Id.Operation.compare op operation_id = 0
      in
      (match
         List.find t.invocation_executions ~f:(fun execution ->
           execution.accepts_children
           &&
           match execution.owner with
           | Foreground op -> owned execution.dispatched.context.id op
           | Invocation_moderator borrow ->
             Option.exists borrow.operation_id ~f:(owned execution.dispatched.context.id)
             && (not (borrow.committed || borrow.cancel_requested))
             && Option.exists t.moderator_borrow ~f:(phys_equal borrow)
           | Event_moderator _ | Background_job _ -> false)
       with
       | Some execution -> Ok execution.owner
       | None ->
         (match
            Option.find t.moderator_borrow ~f:(fun borrow ->
              borrow.accepts_children
              && (not borrow.committed)
              && Option.exists borrow.operation_id ~f:(owned borrow.invocation.context.id))
          with
          | Some borrow -> Ok (Invocation_moderator borrow)
          | None ->
            Error (error Conflict "parent invocation is not executing in this operation")))
  in
  let%bind origin = operation_invocation_origin t operation_id invocation in
  let%bind boundary = policy_boundary_of_invocation_owner t owner in
  let%bind invocation, admission, policy_source =
    invocation_admission_deltas t invocation ~origin ~boundary
  in
  let%bind dispatched = Agent_protocol.Invocation.dispatch invocation in
  let%bind _ =
    transition
      t
      ~delta:(Session_delta.Batch (admission @ [ Invocation_changed dispatched ]))
      ~payloads:[]
  in
  let context_rollover_basis =
    let module P = Agent_protocol in
    let open Option.Let_syntax in
    let context = dispatched.P.Invocation.context in
    let%bind () =
      if
        String.equal context.tool_name
          (Recovery_context_service.name Recovery_context_service.New_window)
        &&
        (match context.origin with
         | Model -> Option.is_some context.call_entry_id
         | Script -> Option.is_some context.parent_invocation
         | Moderator | Delegated_agent | External_adapter -> false)
      then Some ()
      else None
    in
    let%bind target = Configuration_transition.target t.state |> Result.ok in
    let%bind preparation =
      Configuration_capture.native_window
        t.configuration_capture
        ~operation_id
        ~configuration_revision:t.state.spec.configuration_revision
        ~target
    in
    let scope = Configuration_capture.Native_window.scope preparation in
    let%map expected =
      Recovery_rollover.Expected.create scope ~revision:t.state.counters.revision
      |> Result.ok
    in
    preparation, expected
  in
  let execution =
    { owner
    ; policy_source
    ; native_goal = None
    ; context_rollover_basis
    ; dispatched
    ; accepts_children = true
    ; authority_live = Atomic.make true
    }
  in
  t.invocation_executions <- execution :: t.invocation_executions;
  Ok execution
;;

(* At most one combined process-local slot per retained Invocation or
   Moderator_execution key. The three private producers update that actual
   durable owner; only its ACK installs/replaces this slot, after committed
   retention and before publication. The complete durable owner inventories
   bound this list. An independent count quota here could reject a truthful
   native result after its effect has already run. No codec or principal lookup
   exists. Missing or mixed original proofs mint no authentication. *)
let with_intent_agent_custody ?observation t key ~retention ~pending custody f =
  if (not pending) && Option.is_none observation
  then f ~acknowledge:(fun () -> ())
  else
    let open Result.Let_syntax in
    let existing =
      List.find t.intent_agent_custody ~f:(fun entry ->
        equal_agent_intent_key entry.key key)
    in
    let%bind () =
      match existing with
      | None -> Ok ()
      | Some previous ->
        if Agent_intent_retention.equal previous.retention retention
        then Ok ()
        else Error (error Conflict "intent custody retention provenance changed")
    in
    let%bind source = Runtime_builder.moderator_snapshot_observer t.state.moderator in
    let custody =
      if not pending
      then None
      else (
        match existing, custody with
        | None, custody -> custody
        | Some { custody = Some previous; _ }, Some current
          when Execution_custody.same_origin previous current -> Some previous
        | Some _, (Some _ | None) -> None)
    in
    let staged, owned =
      match custody with
      | None -> None, false
      | Some custody ->
        (match transfer_agent_custody custody with
         | Ok child -> Some child, true
         | Error _ -> Some custody, false)
    in
    let entry : agent_intent_custody =
      { key
      ; retention
      ; generation = t.state.identity.generation
      ; source
      ; custody = staged
      ; native_goal = Option.bind existing ~f:(fun previous -> previous.native_goal)
      ; observation =
          Option.first_some
            observation
            (Option.bind existing ~f:(fun entry -> entry.observation))
      }
    in
    let acknowledged = ref false in
    (* This callback is actor-private. Every caller invokes it immediately after
       the actual committed-state install, before publication can yield. Keep
       other entries from that install's retention pass, not a stale old list. *)
    let acknowledge () =
      if not !acknowledged
      then (
        Option.iter existing ~f:(fun previous ->
          Option.iter previous.custody ~f:(fun previous ->
            if not (Option.exists staged ~f:(phys_equal previous))
            then retire_agent_custody previous));
        Option.iter existing ~f:(fun previous ->
          Option.iter previous.observation ~f:(fun previous ->
            if not (Option.exists entry.observation ~f:(phys_equal previous))
            then Observation_continuation.retire previous));
        t.intent_agent_custody
        <- entry
           :: List.filter t.intent_agent_custody ~f:(fun current ->
             not (equal_agent_intent_key current.key key));
        acknowledged := true)
    in
    Exn.protect
      ~f:(fun () -> f ~acknowledge)
      ~finally:(fun () ->
        if owned && not !acknowledged then Option.iter staged ~f:retire_agent_custody)
;;

(* The selected Job candidate is prepared against the current inventory, not
   the inventory present when each independent staged loan was captured. *)
let with_selected_intent_agent_custody
      ?observation
      t
      owner
      key
      ~retention
      ~pending
      custody
      f
  =
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () ->
      if not !acknowledged then Option.iter observation ~f:Observation_continuation.retire)
    ~f:(fun () ->
      with_selected_job_custody t owner (fun ~job_custody ~check_jobs ~acknowledge_jobs ->
        with_intent_agent_custody
          ?observation
          t
          key
          ~retention
          ~pending
          custody
          (fun ~acknowledge ->
             f ~job_custody ~check_jobs ~acknowledge:(fun () ->
               acknowledge ();
               acknowledged := true;
               acknowledge_jobs ()))))
;;

let plan_agent_custody t (plan : Observation_follow_up.t) =
  let open Result.Let_syntax in
  let accepted = function
    | Agent_protocol.Invocation.Applied_follow_up _ | Compaction_accepted_follow_up _ ->
      true
    | Pending_follow_up _ | Discarded_follow_up _ -> false
  in
  let observation_contributes (invocation : Agent_protocol.Invocation.t) =
    match invocation.observation with
    | Some { status = Observed; follow_up = Some status; _ } -> accepted status
    | None
    | Some { status = Awaiting | Observing | Observation_failed _; _ }
    | Some { status = Observed; follow_up = None; _ } -> false
  in
  let handler_contributes (invocation : Agent_protocol.Invocation.t) =
    Option.exists invocation.handler_intent ~f:(fun intent -> accepted intent.follow_up)
  in
  let keys =
    List.filter_map plan.events ~f:(fun receipt ->
      match receipt.Agent_protocol.Moderator_execution.intent with
      | Some (Applied | Waiting_compaction _) -> Some (Event_intent receipt.context.id)
      | None | Some (Pending | Discarded _) -> None)
    @ List.filter_map plan.invocations ~f:(fun invocation ->
      Option.some_if
        (handler_contributes invocation || observation_contributes invocation)
        (Invocation_intent invocation.context.id))
  in
  let find key =
    List.find t.intent_agent_custody ~f:(fun entry ->
      equal_agent_intent_key entry.key key)
  in
  let entries = List.map keys ~f:find in
  let ordinary =
    match entries with
    | [] -> None
    | Some { custody = Some first; _ } :: rest
      when List.for_all rest ~f:(function
             | Some { custody = Some other; _ } ->
               Execution_custody.same_origin first other
             | None | Some { custody = None; _ } -> false) -> Some first
    | None :: _ | Some _ :: _ -> None
  in
  let observed =
    match plan.action with
    | Checkpoint | Stop _ -> []
    | Turn | Compact -> List.filter plan.invocations ~f:observation_contributes
  in
  match observed with
  | [] -> Ok Follow_up_authority.{ custody = ordinary; observations = None }
  | _ :: _ ->
    let%bind observations =
      List.map observed ~f:(fun invocation ->
        match
          Option.bind (find (Invocation_intent invocation.context.id)) ~f:(fun entry ->
            entry.observation)
        with
        | Some observation -> Ok (invocation, observation)
        | None ->
          Error (error Permission_denied "observation follow-up admission is unavailable"))
      |> Result.all
    in
    let other_custodies =
      List.filter_map keys ~f:(fun key ->
        let observed =
          List.find observations ~f:(fun (invocation, _) ->
            equal_agent_intent_key key (Invocation_intent invocation.context.id))
        in
        match observed with
        | None -> Some (Option.bind (find key) ~f:(fun entry -> entry.custody))
        | Some (invocation, observation) ->
          if not (handler_contributes invocation)
          then None
          else (
            let custody = Option.bind (find key) ~f:(fun entry -> entry.custody) in
            (* The SAME immutable native producer's positive legacy-None loan
               also covers its own handler intent. Other absent entries do not. *)
            match custody, Observation_continuation.parent observation with
            | None, Available admission
              when Option.is_none (Execution_custody.Admission.custody admission) -> None
            | (None | Some _), (Available _ | Expired | Unavailable) -> Some custody))
    in
    let%map selection =
      Observation_continuation.Selection.create
        ~observations:(List.map observations ~f:snd)
        ~other_custodies
    in
    Follow_up_authority.
      { custody = Observation_continuation.Selection.custody selection
      ; observations = Some selection
      }
;;

let check_follow_up_authority t (authority : Follow_up_authority.t) =
  let open Result.Let_syntax in
  match authority.observations with
  | None -> Ok ()
  | Some selection ->
    let%bind () = Observation_continuation.Selection.check_current selection in
    (* All original guards precede the joint callback-free resource/source basis. *)
    let%bind () =
      match
        t.state.lifecycle.desired, t.state.lifecycle.observed, t.state.active_operation
      with
      | Running, Idle, None
        when runtime_admission_open t
             && not
                  (t.state.halted || t.idle_moderator_borrowed || moderator_is_borrowed t)
        -> Ok ()
      | (Running | Stopped), _, _ ->
        Error (error Conflict "observation follow-up no longer owns an idle actor")
    in
    let%bind source = observation_source t in
    let%bind observer = Runtime_builder.moderator_snapshot_observer t.state.moderator in
    List.fold_result
      (Observation_continuation.Selection.bindings selection)
      ~init:()
      ~f:(fun () (id, observation) ->
        match
          ( List.find t.intent_agent_custody ~f:(fun entry ->
              equal_agent_intent_key entry.key (Invocation_intent id))
          , List.find t.state.invocations ~f:(fun invocation ->
              Agent_protocol.Id.Invocation.equal invocation.context.id id) )
        with
        | Some entry, Some invocation
          when (not t.stopped)
               && Int.equal entry.generation t.state.identity.generation
               && Option.equal
                    Agent_protocol.Invocation.equal_observer
                    entry.source
                    observer
               && Option.exists entry.observation ~f:(phys_equal observation)
               && observation_pending invocation
               && Observation_continuation.matches observation ~source invocation -> Ok ()
        | (None | Some _), (None | Some _) ->
          Error (error Conflict "observation follow-up source or retained owner changed"))
;;

let event_run_preparation t (borrow : queued_event_borrow) =
  match Option.bind borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial with
  | Some scope -> held_authored_factual_preparation t scope
  | None ->
    Option.bind t.legacy_callback_scope ~f:(fun callback ->
      if phys_equal callback.borrow borrow
      then
        Option.bind callback.constructor_scope ~f:(fun scope ->
          Initialization_scope_data.initial_preparation scope)
      else None)
;;

let selected_event_run t (borrow : queued_event_borrow) =
  match borrow.lifecycle_owner with
  | Some owner -> Result.map (lifecycle_event_run t borrow owner) ~f:Option.some
  | None -> Run_event_scope.select t.state ~executing:borrow.receipt
;;

let constructor_scope_of_borrow t borrow =
  Option.bind t.legacy_callback_scope ~f:(fun scope ->
    if phys_equal scope.borrow borrow then scope.constructor_scope else None)
;;

(* Completed native results own data settlement, not new effect admission.
   Keep the immutable constructor control basis strict, then advance only the
   exact selected Invocation row at its actual ACK. This check has no caller
   policy callback and can also run after a yielding fresh-admission refresh. *)
let check_constructor_invocation_basis t (scope : Initialization_scope_data.t) =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_owner t scope in
  let%bind () =
    if initialization_callback_is_owned t scope
    then Ok ()
    else Error (error Conflict "constructor no longer owns its Invocation result")
  in
  let%bind () =
    validate_initialization_projection
      (Initialization_scope_data.Acknowledged.apply scope.acknowledged scope.expected)
      t.state
  in
  match Initialization_scope_data.initial_preparation scope with
  | None -> Ok ()
  | Some preparation ->
    Run_preparation.check_basis preparation ~owner:t.run_preparation_owner ~state:t.state
;;

let prepare_constructor_invocation_ack
      ?(permissions = [])
      ?permission_lifecycle
      t
      borrow
      ~before
      ~after
      (prepared : Session_transition.t)
  =
  let open Result.Let_syntax in
  match constructor_scope_of_borrow t borrow with
  | None -> Ok None
  | Some scope ->
    let%bind () = check_constructor_invocation_basis t scope in
    let%bind () =
      Constructor_invocation_checkpoint.validate
        ~previous:t.state
        ~incoming:prepared.state
        ~before
        ~after
    in
    let%bind permission_checkpoint =
      if List.is_empty permissions
      then Ok None
      else
        Constructor_permission_checkpoint.prepare
          ~previous:t.state
          ~incoming:prepared.state
          ~invocation_id:after.context.id
          ~permissions
          ~grant:None
          ~lifecycle:(Option.value permission_lifecycle ~default:t.state.lifecycle)
        |> Result.map ~f:Option.some
    in
    let acknowledgement =
      Initialization_scope_data.Acknowledgement.prepare
        ?permission_checkpoint
        scope
        prepared.state
    in
    let%map () =
      validate_initialization_projection
        (Initialization_scope_data.Acknowledgement.expected acknowledgement)
        prepared.state
    in
    Some acknowledgement
;;

let check_constructor_invocation_ack t borrow acknowledgement =
  let open Result.Let_syntax in
  match constructor_scope_of_borrow t borrow, acknowledgement with
  | None, None -> Ok ()
  | Some scope, Some acknowledgement
    when phys_equal scope acknowledgement.Initialization_scope_data.Acknowledgement.scope
    ->
    let%bind () = check_constructor_invocation_basis t scope in
    Initialization_scope_data.Acknowledgement.check_basis acknowledgement
  | None, Some _ | Some _, (Some _ | None) ->
    Error (error Conflict "constructor Invocation owner changed before commit")
;;

let claim_moderator_invocation
      t
      operation_id
      (invocation : Agent_protocol.Invocation.t)
      captured
  =
  let open Result.Let_syntax in
  let%bind () = require_selected_execution t in
  let%bind () =
    match invocation.parent_event with
    | None -> Ok ()
    | Some _ -> Error (error Conflict "event-owned tools require their event scope")
  in
  let%bind _ = running_operation t operation_id in
  if t.idle_moderator_borrowed || Option.is_some t.moderator_borrow
  then Error (error Conflict "moderator is already borrowed")
  else (
    let%bind () =
      Extension_invariants.owner
        ~session_id:t.state.identity.session_id
        ~generation:t.state.identity.generation
        invocation.context.session_id
        invocation.context.generation
    in
    let%bind () =
      match invocation.context.parent_invocation with
      | None when Option.is_none invocation.context.parent_job -> Ok ()
      | Some parent ->
        let parent =
          List.find t.invocation_executions ~f:(fun execution ->
            execution.accepts_children
            && Agent_protocol.Id.Invocation.equal execution.dispatched.context.id parent
            &&
            match execution.owner with
            | Foreground id -> Agent_protocol.Id.Operation.equal id operation_id
            | Invocation_moderator _ | Event_moderator _ | Background_job _ -> false)
        in
        (match invocation.context.origin, parent with
         | (Script | Delegated_agent), Some parent
           when Option.is_none invocation.context.parent_job
                && Option.is_none invocation.context.provider_call_id
                && Option.is_none invocation.context.call_entry_id ->
           (match parent.dispatched.context.deadline, invocation.context.deadline with
            | None, _ -> Ok ()
            | Some parent, Some child
              when Agent_protocol.Timestamp.compare child parent <= 0 -> Ok ()
            | _ ->
              Error (error Conflict "nested moderator cannot extend its parent deadline"))
         | _ -> Error (error Conflict "nested moderator requires an active scoped caller"))
      | None ->
        Error (error Conflict "foreground moderator cannot borrow background ownership")
    in
    let%bind checkpoint = prepare_moderator_invocation_checkpoint t captured in
    let%bind origin = operation_invocation_origin t operation_id invocation in
    let%bind invocation, admission, policy_source =
      invocation_admission_deltas t invocation ~origin ~boundary:None
    in
    let%bind dispatched = Agent_protocol.Invocation.dispatch invocation in
    let%bind _ =
      transition
        t
        ~delta:(Session_delta.Batch (admission @ [ Invocation_changed dispatched ]))
        ~payloads:[]
    in
    let borrow =
      { operation_id = Some operation_id
      ; job_scope = None
      ; kind = Invocation checkpoint
      ; observation = None
      ; policy_source
      ; invocation = dispatched
      ; committed = false
      ; accepts_children = true
      ; callback_finished = false
      ; native_goals = Goal_native_actions.create ()
      ; authority_live = Atomic.make true
      ; cancel = None
      ; cancel_requested = false
      }
    in
    t.moderator_borrow <- Some borrow;
    Ok borrow)
;;

let has_pending_permission t =
  List.exists t.state.permissions ~f:(fun permission ->
    Agent_protocol.Permission.equal_state permission.state Pending)
;;

let idle_actor_available t =
  (* A published prospective occurrence owns its exact before-State through its
     native ACK or retained confirmation/close. New idle work must wait for the
     actual occupancy release; existing callback and factual cleanup bypass this
     admission predicate. *)
  runtime_admission_open t
  && Option.is_none t.governed_admission_slot
  && (not t.idle_moderator_borrowed)
  && Option.is_none t.idle_completion
  && Option.is_none t.moderator_borrow
  && Option.is_none t.state.active_operation
  && Agent_protocol.Session.equal_desired_state t.state.lifecycle.desired Running
  && (match t.state.lifecycle.observed with
      | Agent_protocol.Session.Idle -> true
      | _ -> false)
  && (not t.state.halted)
  && Option.is_none t.state.failure
;;

let runtime_ready t =
  (not (Session_state.execution_migration_required t.state))
  &&
  match
    t.state.runtime_initialization, Inference.Selection.view t.state.spec.inference_target
  with
  | Ready, Captured _ -> true
  | Pending _, _ | Ready, Unresolved -> false
;;

let idle_moderator_eligible t =
  runtime_ready t && idle_actor_available t && not (has_pending_permission t)
;;

let check_run_binding t run_id =
  let open Result.Let_syntax in
  let%bind binding =
    Result.of_option
      (Run_authorities.find t.run_authorities run_id)
      ~error:(error Permission_denied "run no longer has live host authority")
  in
  Run_admission.Scope.authorize (Run_authorities.scope binding) t.state
;;

let claim_queued_event
      ?goal_execution
      t
      id
      operation_id
      (snapshot : Session.Moderator_state.Identity_snapshot.t)
  =
  let open Result.Let_syntax in
  let%bind goal_scope =
    match goal_execution with
    | None -> Ok None
    | Some execution ->
      let%bind scope = select_goal_runtime t execution in
      let%bind () = check_runtime_construction_effect (Existing_goal execution) in
      let%bind () =
        match scope.callback, execution.binding.preparation.runtime_phase with
        | Joined, (Installed _ | Callback_completed _) -> Ok ()
        | ( (Pending | Executing _ | Completed _ | Joined)
          , ( Unclaimed
            | Starting_writer _
            | Starting_acknowledged
            | Running_writer _
            | Constructing
            | Installed _
            | Callback_completed _
            | Handed_off _
            | Retired _
            | Closed ) ) ->
          Error (error Conflict "Goal wake callback has no unconsumed installed owner")
      in
      Ok (Some scope)
  in
  let%bind available =
    match operation_id with
    | None -> Ok (idle_moderator_eligible t)
    | Some id ->
      let%map _ = running_operation t id in
      not (t.idle_moderator_borrowed || moderator_is_borrowed t)
  in
  match available with
  | false -> Ok None
  | true ->
    let%bind () = require_selected_execution t in
    let%bind head =
      Queued_claim_acknowledgement.Head.capture
        ~state:t.state
        ~manager:t.moderator_manager
    in
    let%bind receipt, event =
      (match operation_id with
       | None -> Queued_moderator_event.claim
       | Some operation_id -> Queued_moderator_event.claim_foreground ~operation_id)
        ~state:t.state
        ~id
        ~snapshot
        ~now:(t.services.now ())
    in
    let%bind retirement_reason =
      Queued_moderator_event.delivery_retirement_reason
        ~state:t.state
        ~observer:receipt.context.source
        ~event
        ~subscription_expired:(subscription_is_due t)
    in
    let borrow =
      { kind = Queued
      ; lifecycle_owner = None
      ; job_scope = None
      ; agent_admission = Contextual None
      ; policy_source = Unknown
      ; receipt
      ; before = snapshot
      ; event
      ; retirement_reason
      ; run_actions = None
      ; callback_active = true
      ; native_goals = Goal_native_actions.create ()
      ; authority_live = Atomic.make true
      ; committed = false
      ; stop_retirement = None
      ; terminal_selection = None
      ; completion =
          Callback_completion_data.create
            ~issuing_actor:t.initialization_owner
            ~domain:t.runtime_source_domain
      ; cancel = None
      ; cancel_requested = false
      }
    in
    (match retirement_reason with
     | Some _ ->
       t.queued_event_borrow <- Some borrow;
       t.idle_moderator_borrowed <- true;
       Ok (Some borrow)
     | None ->
       let previous = t.state in
       let%bind resumed, run_deltas =
         Run_transition.claim_wake previous ~executing:receipt ~now:(t.services.now ())
       in
       let goal_runs =
         List.filter resumed ~f:(fun run_id ->
           Option.exists t.state.run_state ~f:(fun index ->
             Option.is_some (Run_state.goal_link index run_id)))
       in
       if Option.is_none goal_execution && not (List.is_empty goal_runs)
       then Ok None
       else (
         let%bind () =
           match goal_execution, goal_scope, resumed with
           | None, None, _ -> Ok ()
           | Some execution, Some _, [ run_id ]
             when Agent_protocol.Id.Run.equal run_id execution.binding.preparation.run.id
             -> Ok ()
           | (Some _ | None), (Some _ | None), _ ->
             Error
               (error Conflict "Goal queue claim differs from its exact selected wake")
         in
         let%bind policy = queued_event_policy_metadata t receipt in
         let%bind candidate =
           prepare_transition
             t
             ~delta:
               (Session_delta.Batch
                  ((Session_delta.Moderator_execution_changed receipt :: policy)
                   @ run_deltas))
             ~payloads:[]
         in
         let%bind acknowledgement =
           Queued_claim_acknowledgement.prepare
             ?goal_scope
             ~previous
             ~authorities:t.run_authorities
             ~queue_custody:t.legacy_queue_custody
             ~head
             ~resumed
             ~candidate
             ~borrow
             ()
         in
         Exn.protect
           ~finally:(fun () -> Queued_claim_acknowledgement.discard acknowledgement)
           ~f:(fun () ->
             let%bind goal_runtime_acknowledgement =
               match goal_scope with
               | None -> Ok None
               | Some scope ->
                 Goal_runtime_acknowledgement.prepare t scope ~candidate
                 |> Result.map ~f:Option.some
             in
             let check_basis () =
               let%bind available =
                 match operation_id with
                 | None -> Ok (idle_moderator_eligible t)
                 | Some id ->
                   let%map _ = running_operation t id in
                   runtime_admission_open t
                   && not (t.idle_moderator_borrowed || moderator_is_borrowed t)
               in
               if t.stopped || not available
               then Error (error Conflict "queued claim owner changed before ACK")
               else
                 Queued_claim_acknowledgement.check_basis
                   acknowledgement
                   ~previous:t.state
                   ~authorities:t.run_authorities
                   ~queue_custody:t.legacy_queue_custody
                   ~manager:t.moderator_manager
                   ~current_borrow:t.queued_event_borrow
                   ~candidate
             in
             let check_before_commit () =
               let%bind () =
                 Option.value_map goal_execution ~default:(Ok ()) ~f:(fun execution ->
                   check_runtime_construction_effect (Existing_goal execution))
               in
               let%bind () = check_basis () in
               let%bind () =
                 Option.value_map
                   (Queued_claim_acknowledgement.scope acknowledgement)
                   ~default:(Ok ())
                   ~f:(fun scope -> Run_admission.Scope.authorize scope t.state)
               in
               let%bind () =
                 Option.value_map
                   (Queued_claim_acknowledgement.scope acknowledgement)
                   ~default:(Ok ())
                   ~f:Run_admission.Scope.check_current
               in
               let%bind () =
                 Option.value_map goal_execution ~default:(Ok ()) ~f:(fun execution ->
                   let construction = Runtime_construction.Existing_goal execution in
                   let%bind () = Runtime_construction.check_timing construction in
                   Runtime_construction.check_policy construction)
               in
               check_basis ()
             in
             Eio.Cancel.protect (fun () ->
               let%map () =
                 install
                   ?goal_runtime_acknowledgement
                   ~queued_claim_acknowledgement:acknowledgement
                   ~check_before_commit
                   t
                   candidate
               in
               t.queued_event_borrow))))
;;

type lifecycle_claim_handoff =
  | Current_lifecycle_child of
      { original : agent_admission
      ; child : agent_admission
      }
  | Expired_lifecycle_original of
      { original : agent_admission
      ; child : agent_admission
      }

let stage_lifecycle_claim original =
  let expired () =
    match Execution_custody.Admission.custody original with
    | Some custody ->
      Ok
        (Expired_lifecycle_original
           { original; child = create_agent_admission (Some custody) })
    | None -> Error (error Internal_error "expired lifecycle admission lost its original")
  in
  match Execution_custody.Admission.status original with
  | Authority_expired -> expired ()
  | Closed -> Error (error Conflict "lifecycle admission has ended")
  | Current ->
    (match transfer_agent_admission original with
     | Ok child -> Ok (Current_lifecycle_child { original; child })
     | Error failure ->
       (match Execution_custody.Admission.status original with
        | Authority_expired -> expired ()
        | Current | Closed -> Error failure))
;;

let lifecycle_claim_admission = function
  | Current_lifecycle_child { child; _ } | Expired_lifecycle_original { child; _ } ->
    child
;;

let discard_lifecycle_claim = function
  | Current_lifecycle_child { child; _ } -> retire_agent_admission child
  | Expired_lifecycle_original { child; _ } -> Execution_custody.Admission.close child
;;

let check_lifecycle_claim = function
  | Current_lifecycle_child { child; _ } -> check_agent_admission child
  | Expired_lifecycle_original _ -> Ok ()
;;

let acknowledge_lifecycle_claim = function
  | Current_lifecycle_child { original; _ } | Expired_lifecycle_original { original; _ }
    -> retire_agent_admission original
;;

(* Project the exact installed checkpoint source, then persist that index and
   its new lifecycle claim in ONE actual admission ACK. Projection alone is DATA;
   historical receipt replay never calls this issuer. *)
let lifecycle_claim_delta t snapshot (receipt : Agent_protocol.Moderator_execution.t) =
  if not (Moderator_lifecycle.lifecycle_phase receipt.context.phase)
  then Ok (Session_delta.Moderator_execution_changed receipt)
  else
    let open Result.Let_syntax in
    let%bind index, source =
      Moderator_source_installation.capture_checkpoint t.state ~checkpoint:snapshot
    in
    let%map capture =
      Moderator_lifecycle.create ~source ~execution_id:receipt.context.id
    in
    Session_delta.Batch
      [ Run_state_changed index; Moderator_lifecycle_claimed { receipt; capture } ]
;;

let claim_held_authored_event t (scope : Held_authored_start.t) id snapshot event =
  let open Result.Let_syntax in
  let%bind run = held_authored_run t scope in
  let%bind () =
    match
      scope.phase, event, Runtime_builder.Authored_start.disposition scope.startup
    with
    | Ready, Chat_response.Moderation.Event.Session_start, Extension_pending
      when idle_moderator_eligible t -> Ok ()
    | _ ->
      Error
        (error
           Conflict
           "held authored lifecycle is not ready for its actual Session_start")
  in
  let%bind receipt, event =
    Queued_moderator_event.claim_ordinary
      ~state:t.state
      ~id
      ~snapshot
      ~operation_id:None
      ~event
      ~now:(t.services.now ())
  in
  let%bind handoff =
    match t.lifecycle_agent_custody with
    | Admitted { pending = Pending admission; _ } -> stage_lifecycle_claim admission
    | Unadmitted | Admitted { pending = Initial_pending _ | Consumed; _ } ->
      Error (error Conflict "held authored lifecycle has no original Pending custody")
  in
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () -> if not !acknowledged then discard_lifecycle_claim handoff)
    ~f:(fun () ->
      let%bind run_scope = Run_scope.create ~run ~execution_id:receipt.context.id in
      let borrow : queued_event_borrow =
        { kind = Ordinary
        ; lifecycle_owner = Some (Initial_authored scope)
        ; job_scope = None
        ; agent_admission = Contextual (Some (lifecycle_claim_admission handoff))
        ; policy_source = Unknown
        ; receipt
        ; before = snapshot
        ; event
        ; retirement_reason = None
        ; run_actions = Some (Run_action_service.create ~scope:run_scope)
        ; callback_active = true
        ; native_goals = Goal_native_actions.create ()
        ; authority_live = Atomic.make true
        ; committed = false
        ; stop_retirement = None
        ; terminal_selection = None
        ; completion =
            Callback_completion_data.create
              ~issuing_actor:t.initialization_owner
              ~domain:t.runtime_source_domain
        ; cancel = None
        ; cancel_requested = false
        }
      in
      let activation = Admitted_activation.Continuation.target scope.continuation in
      let%bind delta = lifecycle_claim_delta t snapshot receipt in
      let%bind prepared =
        prepare_transition ~run_preparation:activation.preparation t ~delta ~payloads:[]
      in
      let revision = t.state.counters.revision in
      let check_before_commit () =
        let%bind () = held_authored_basis t scope in
        let%bind () = check_lifecycle_claim handoff in
        let%bind () = check_held_effect scope.continuation in
        if
          Int64.equal revision t.state.counters.revision
          && Option.is_none t.queued_event_borrow
          &&
          match scope.phase with
          | Ready -> true
          | _ -> false
        then held_authored_basis t scope
        else Error (error Conflict "held authored Event claim changed before ACK")
      in
      Eio.Cancel.protect (fun () ->
        let%bind () =
          persist_transition
            ~run_preparation:activation.preparation
            ~check_before_commit
            t
            prepared
        in
        install_committed_transition ~run_preparation:activation.preparation t prepared;
        (match t.lifecycle_agent_custody with
         | Admitted previous ->
           t.lifecycle_agent_custody <- Admitted { previous with pending = Consumed }
         | Unadmitted -> ());
        acknowledge_lifecycle_claim handoff;
        t.queued_event_borrow <- Some borrow;
        t.idle_moderator_borrowed <- true;
        scope.phase <- Executing receipt.context.id;
        Failed_startup_data.Authored.install_callback
          scope.cleanup
          ~id:receipt.context.id
          borrow.completion.facts;
        acknowledged := true;
        publish_committed_transition t prepared;
        Ok (Some borrow)))
;;

let claim_ordinary_event t id operation_id snapshot event =
  let open Result.Let_syntax in
  let%bind available =
    match operation_id with
    | None ->
      (match event with
       | Chat_response.Moderation.Event.Session_start | Session_resume ->
         Ok (idle_moderator_eligible t)
       | _ -> Error (error Invalid_state "ordinary event requires an active operation"))
    | Some id ->
      let%map _ = running_operation t id in
      not (t.idle_moderator_borrowed || moderator_is_borrowed t)
  in
  match available with
  | false -> Ok None
  | true ->
    let%bind () = require_selected_execution t in
    let%bind receipt, captured_event =
      Queued_moderator_event.claim_ordinary
        ~state:t.state
        ~id
        ~snapshot
        ~operation_id
        ~event
        ~now:(t.services.now ())
    in
    let%bind handoff =
      match operation_id, t.lifecycle_agent_custody with
      | None, Admitted { pending = Pending admission; _ } ->
        Result.map (stage_lifecycle_claim admission) ~f:Option.some
      | None, Admitted { pending = Initial_pending { admission; startup }; _ } ->
        let%bind () = check_agent_admission admission in
        let%bind () =
          match event with
          | Chat_response.Moderation.Event.Session_start ->
            Initial_lifecycle_startup.check_claim
              startup
              ~state:t.state
              ~worker:t.operation_worker
              ~manager:t.moderator_manager
          | Session_resume
          | Turn_start
          | Item_appended _
          | Pre_tool_call _
          | Post_tool_response _
          | Turn_end
          | Internal_event _ ->
            Error (error Conflict "initial original belongs to its first Session_start")
        in
        Result.map (stage_lifecycle_claim admission) ~f:Option.some
      | Some _, _ | None, (Unadmitted | Admitted { pending = Consumed; _ }) -> Ok None
    in
    let agent_admission = Option.map handoff ~f:lifecycle_claim_admission in
    let acknowledged = ref false in
    Exn.protect
      ~finally:(fun () ->
        if not !acknowledged then Option.iter handoff ~f:discard_lifecycle_claim)
      ~f:(fun () ->
        let borrow =
          { kind = Ordinary
          ; lifecycle_owner = None
          ; job_scope = None
          ; agent_admission = Contextual agent_admission
          ; policy_source = Unknown
          ; receipt
          ; before = snapshot
          ; event = captured_event
          ; retirement_reason = None
          ; run_actions = None
          ; callback_active = true
          ; native_goals = Goal_native_actions.create ()
          ; authority_live = Atomic.make true
          ; committed = false
          ; stop_retirement = None
          ; terminal_selection = None
          ; completion =
              Callback_completion_data.create
                ~issuing_actor:t.initialization_owner
                ~domain:t.runtime_source_domain
          ; cancel = None
          ; cancel_requested = false
          }
        in
        let%bind delta = lifecycle_claim_delta t snapshot receipt in
        let%bind prepared = prepare_transition t ~delta ~payloads:[] in
        let%bind () =
          Option.value_map handoff ~default:(Ok ()) ~f:check_lifecycle_claim
        in
        Eio.Cancel.protect (fun () ->
          let%bind () = persist_transition t prepared in
          install_committed_transition t prepared;
          Option.iter handoff ~f:(fun handoff ->
            (match t.lifecycle_agent_custody with
             | Admitted admitted ->
               t.lifecycle_agent_custody <- Admitted { admitted with pending = Consumed }
             | Unadmitted -> ());
            acknowledge_lifecycle_claim handoff);
          t.queued_event_borrow <- Some borrow;
          t.idle_moderator_borrowed <- true;
          acknowledged := true;
          publish_committed_transition t prepared;
          Ok (Some borrow)))
;;

let prepare_delegated_intent_retention t (capture : Delegated_policy_claim_data.t) =
  let open Result.Let_syntax in
  let%bind () = Delegated_policy_custody.check_access t capture in
  match capture.access with
  | Running -> Ok Agent_intent_retention.Ordinary
  | Policy_only _ ->
    let%map _, source = Moderator_source_installation.capture t.state in
    Agent_intent_retention.Stopped_policy { stop_epoch = t.state.stop_epoch; source }
  | Restored_unloaded _ ->
    let%map _, source = Moderator_source_installation.capture t.state in
    Agent_intent_retention.Restored_policy { stop_epoch = t.state.stop_epoch; source }
;;

let callback_intent_retention t (borrow : queued_event_borrow) =
  let open Result.Let_syntax in
  match borrow.agent_admission with
  | Contextual _ | Resumed_run _ | Selected_queue _ -> Ok Agent_intent_retention.Ordinary
  | Delegated_policy _ ->
    let%bind capture =
      Result.of_option
        t.delegated_policy_claim
        ~error:(error Conflict "delegated callback lost its actual intent provenance")
    in
    let%bind () = Delegated_policy_custody.check_capture t capture in
    (match Delegated_policy_claim_state.phase capture.state with
     | Activated attempt
       when phys_equal (Delegated_policy_claim_state.Attempt.borrow attempt) borrow ->
       Result.of_option
         capture.intent_retention
         ~error:(error Conflict "delegated callback has no frozen intent provenance")
     | Waiting | Prepared _ | Activated _ | Callback_acknowledged _ | Released ->
       Error (error Conflict "delegated callback intent belongs to another claim"))
;;

(* Source-prefix DATA is prepared before the receipt birth. The parent may be a
   lawful stopped Policy_only selection; identity comes from its SAME actual
   Factory/controller, while the existing capture/access checks own effects. *)
let prepare_delegated_policy_seed
      t
      (governance : Causal_governance_binding.t)
      snapshot
      receipt
  =
  let open Result.Let_syntax in
  let%bind index, source =
    Moderator_source_installation.capture_checkpoint t.state ~checkpoint:snapshot
  in
  let%bind _, prefix_delta =
    prepare_transition_basis t ~delta:(Session_delta.Run_state_changed index)
  in
  let%bind prefix = Session_delta.apply t.state prefix_delta in
  let%bind selection =
    match governance.source with
    | Standalone descriptor -> Ok (Delegated_policy_seed.Standalone descriptor)
    | Registered registered ->
      let%bind controller =
        child_accounting_owner t ~source_owner:registered.source_owner
      in
      let%bind () =
        if Recurrence_controller.same_store controller registered.controller
        then Ok ()
        else
          Error (error Conflict "policy seed lost its actual parent Factory/controller")
      in
      let%bind ancestry =
        Result.of_option
          registered.ancestry
          ~error:(error Permission_denied "delegated policy seed has no checked ancestry")
      in
      let%bind () =
        if
          Delegation_authority.Checked_ancestry.issued_by
            ancestry
            ~source_owner:registered.source_owner
        then Ok ()
        else Error (error Conflict "policy seed ancestry has a foreign Factory issuer")
      in
      let callee = Recurrence_controller.session controller in
      let rec path reversed = function
        | [] ->
          Error (error Conflict "policy seed callee is absent from checked ancestry")
        | record :: rest ->
          let edge = Agent_store.Delegation_store.reference record in
          let reversed = edge :: reversed in
          if
            Agent_protocol.Id.Session.equal
              edge.key.parent_session_id
              (Agent_protocol.Session_ref.session_id callee)
          then Ok (List.rev reversed)
          else path reversed rest
      in
      let%map path = path [] (Delegation_authority.Checked_ancestry.records ancestry) in
      Delegated_policy_seed.Registered { data = registered.data; callee; path }
  in
  let%map seed =
    Delegated_policy_seed.prepare
      prefix
      ~selection
      ~source
      ~receipt
      ~max_inherited_scopes:
        (Goal_descendants.Profile.max_scopes t.services.goal_descendant_profile)
  in
  ( Session_delta.Batch (prefix_delta :: Delegated_policy_seed.changes seed)
  , Delegated_policy_seed.classification seed )
;;

let claim_delegated_event
      t
      (capture : Delegated_policy_claim_data.t)
      (request : Script_tool_calls.preparation)
      (governance : Causal_governance_binding.t)
      id
      (delegation : Agent_protocol.Moderator_execution.delegation)
      snapshot
      event
  =
  let module Capture = Delegated_policy_claim_state in
  let open Result.Let_syntax in
  let%bind () = Causal_governance_binding.check_request governance request in
  let%bind () = Delegated_policy_custody.check_capture t capture in
  let%bind () = Delegated_policy_custody.check_access t capture in
  let%bind caller =
    Result.of_option
      request.Script_tool_calls.caller
      ~error:(error Permission_denied "delegated policy claim has no actual child Caller")
  in
  let%bind () = Delegated_policy_caller.check_current caller in
  let%bind () =
    if
      Agent_protocol.Id.Session.equal request.session_id delegation.child_session_id
      && Int.equal request.generation delegation.child_generation
      && Agent_protocol.Id.Invocation.equal
           request.invocation_id
           delegation.child_invocation_id
    then Ok ()
    else
      Error
        (error Conflict "delegated policy claim differs from its actual child request")
  in
  let%bind () =
    match Capture.phase capture.state with
    | Waiting when not (Capture.cancellation_requested capture.state) -> Ok ()
    | Prepared attempt ->
      Session_commit_attempt.unresolved (Capture.Attempt.writer attempt)
    | Waiting | Activated _ | Callback_acknowledged _ | Released ->
      Error (error Conflict "delegated policy claim already selected or cancelled")
  in
  if t.idle_moderator_borrowed || moderator_is_borrowed t
  then Ok Delegated_unavailable
  else (
    let%bind () =
      match capture.access with
      | Running -> require_selected_execution t
      | Policy_only _ | Restored_unloaded _ -> Ok ()
    in
    let%bind claimed =
      Queued_moderator_event.claim_delegated
        ~delegation
        ~state:t.state
        ~id
        ~snapshot
        ~event
        ~now:(t.services.now ())
    in
    match claimed with
    | Replayed receipt -> Ok (Delegated_replay receipt)
    | Claimed (receipt, event) ->
      let%bind delta, policy_source =
        prepare_delegated_policy_seed t governance snapshot receipt
      in
      let%bind intent_retention = prepare_delegated_intent_retention t capture in
      let%bind original = Delegated_policy_caller_custody.Host.transfer caller in
      let published = ref false in
      Exn.protect
        ~finally:(fun () ->
          if not !published then Option.iter original ~f:retire_agent_admission)
        ~f:(fun () ->
          let borrow =
            { kind = Ordinary
            ; lifecycle_owner = None
            ; job_scope = None
            ; agent_admission = Delegated_policy original
            ; policy_source
            ; receipt
            ; before = snapshot
            ; event
            ; retirement_reason = None
            ; run_actions = None
            ; callback_active = true
            ; native_goals = Goal_native_actions.create ()
            ; authority_live = Atomic.make true
            ; committed = false
            ; stop_retirement = None
            ; terminal_selection = None
            ; completion =
                Callback_completion_data.create
                  ~issuing_actor:t.initialization_owner
                  ~domain:t.runtime_source_domain
            ; cancel = None
            ; cancel_requested = false
            }
          in
          let%bind candidate = prepare_transition t ~delta ~payloads:[] in
          let previous = t.state in
          let attempt =
            Capture.Attempt.create ~previous ~candidate ~receipt ~borrow ~original
          in
          let%bind () = Capture.prepare capture.state attempt in
          capture.intent_retention <- Some intent_retention;
          (* Publish SAME complete custody into the Actor and caller's Capture
             before the first canonical invocation. Error is never no-write. *)
          t.delegated_policy_claim <- Some capture;
          published := true;
          let check_before_commit () =
            let%bind () = Causal_governance_binding.check_request governance request in
            let%bind () = Delegated_policy_custody.check_access t capture in
            let%bind () = Delegated_policy_caller.check_current caller in
            let%bind () =
              if Capture.cancellation_requested capture.state
              then
                Error (error Conflict "delegated policy claim was cancelled before ACK")
              else Ok ()
            in
            if
              phys_equal t.state previous
              && Option.exists t.delegated_policy_claim ~f:(phys_equal capture)
              &&
              match Capture.phase capture.state with
              | Prepared current -> phys_equal current attempt
              | Waiting | Activated _ | Callback_acknowledged _ | Released -> false
            then Ok ()
            else Error (error Conflict "delegated policy claim basis changed before ACK")
          in
          let writer = Capture.Attempt.writer attempt in
          Session_commit_attempt.perform writer (fun () ->
            let%bind () = check_before_commit () in
            Eio.Cancel.protect (fun () ->
              let%bind () =
                persist_transition
                  ~commit_observation:(Session_commit_attempt.observation writer)
                  ~check_before_commit
                  t
                  candidate
              in
              install_committed_transition t candidate;
              t.queued_event_borrow <- Some borrow;
              t.idle_moderator_borrowed <- true;
              let%bind () = Capture.activate capture.state attempt in
              (* Activation is the actual State ACK, before fallible publication.
                 The captured original never falls back to the parent's operation. *)
              publish_committed_transition t candidate;
              Ok (Delegated_borrow borrow)))))
;;

let claim_job_event t scope id snapshot event =
  let open Result.Let_syntax in
  let%bind () = job_scope_can_execute t scope in
  let%bind () =
    match t.idle_moderator_borrowed, moderator_is_borrowed t with
    | false, false -> Ok ()
    | _ -> Error (error Conflict "moderator is already borrowed")
  in
  let%bind receipt, event =
    Queued_moderator_event.claim_job
      ~job:
        { job_id = scope.job.id; attempt = scope.job.attempt; deadline = scope.deadline }
      ~state:t.state
      ~id
      ~snapshot
      ~event
      ~now:(t.services.now ())
  in
  let%bind boundary = policy_job_boundary t scope in
  let%bind policy, policy_source =
    policy_birth_metadata t (policy_job_event_birth ~boundary) receipt
  in
  let%bind _ =
    transition
      t
      ~delta:
        (Session_delta.Batch (Session_delta.Moderator_execution_changed receipt :: policy))
      ~payloads:[]
  in
  let borrow =
    { kind = Ordinary
    ; lifecycle_owner = None
    ; job_scope = Some scope
    ; agent_admission = Contextual None
    ; policy_source
    ; receipt
    ; before = snapshot
    ; event
    ; retirement_reason = None
    ; run_actions = None
    ; callback_active = true
    ; native_goals = Goal_native_actions.create ()
    ; authority_live = Atomic.make true
    ; committed = false
    ; stop_retirement = None
    ; terminal_selection = None
    ; completion =
        Callback_completion_data.create
          ~issuing_actor:t.initialization_owner
          ~domain:t.runtime_source_domain
    ; cancel = None
    ; cancel_requested = false
    }
  in
  t.queued_event_borrow <- Some borrow;
  t.idle_moderator_borrowed <- true;
  Ok (Some borrow)
;;

let validate_queued_event_borrow t borrow =
  match t.queued_event_borrow with
  | Some current when phys_equal current borrow && t.idle_moderator_borrowed ->
    let open Result.Let_syntax in
    let%bind () =
      match borrow.job_scope, borrow.receipt.context.operation_id with
      | Some scope, None -> Result.map (job_scope_current t scope) ~f:ignore
      | None, Some id -> Result.map (current_operation t id) ~f:ignore
      | None, None when Option.is_some borrow.receipt.delegation -> Ok ()
      | None, None when Option.is_none t.state.active_operation -> Ok ()
      | _ -> Error (error Conflict "event no longer owns the moderator")
    in
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      borrow.receipt.context.session_id
      borrow.receipt.context.generation
  | _ -> Error (error Conflict "queued event is no longer owned by this callback")
;;

let legacy_boundary_available t parent event =
  let open Result.Let_syntax in
  let%bind () =
    match event with
    | Chat_response.Moderation.Event.Internal_event _ ->
      Error (error Invalid_request "legacy internal events require an exact queue head")
    | Session_start
    | Session_resume
    | Turn_start
    | Item_appended _
    | Pre_tool_call _
    | Post_tool_response _
    | Turn_end -> Ok ()
  in
  match parent with
  | Callback_job scope ->
    let%map () = job_scope_can_execute t scope in
    not (t.idle_moderator_borrowed || moderator_is_borrowed t)
  | Callback_operation (Some id) ->
    let%map _ = running_operation t id in
    not (t.idle_moderator_borrowed || moderator_is_borrowed t)
  | Callback_operation None ->
    (match event with
     | Session_start | Session_resume -> Ok (idle_moderator_eligible t)
     | Turn_start | Item_appended _ | Pre_tool_call _ | Post_tool_response _ | Turn_end ->
       Error (error Invalid_state "legacy boundary requires its active operation")
     | Internal_event _ ->
       Error (error Invalid_request "legacy internal events require an exact queue head"))
;;

let legacy_boundary_admission t parent ~manager ~source =
  match parent with
  | Callback_operation (Some id) ->
    Ok
      ( Option.bind
          t.operation_agent_custody
          ~f:(fun { Operation_owner.operation_id = owner; admission; _ } ->
            Option.some_if (Agent_protocol.Id.Operation.equal owner id) admission)
      , false )
  | Callback_operation None ->
    (match t.lifecycle_agent_custody with
     | Admitted { generation; source; pending = Pending admission }
       when agent_source_current t generation source -> Ok (Some admission, true)
     | Admitted { pending = Initial_pending _; _ } ->
       Error
         (error
            Conflict
            "initial extension original requires its actual queued lifecycle")
     | Admitted _ | Unadmitted -> Ok (None, false))
  | Callback_job scope ->
    (* Missing historical job custody is unavailable, not admitted legacy None.
       Fresh optional job admissions are integrated with their real producers. *)
    Result.map (job_callback_admission t scope ~manager ~source) ~f:(fun admission ->
      admission, false)
;;

let claim_initialization_callback
      t
      (constructor : Initialization_scope_data.t)
      manager
      callback
      installed
  =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_scope t constructor in
  let%bind () =
    Callback_cleanup_data.Host.check_initialization_registration
      constructor.callback_cleanup
      ~issuer:t.initialization_owner
      ~scope:constructor.identity
  in
  let%bind () = check_initialization_agent_actor constructor in
  let%bind event =
    match Chat_response.Moderator_manager.Callback.selection callback with
    | Boundary (Session_start as event) | Boundary (Session_resume as event) -> Ok event
    | Boundary
        ( Turn_start
        | Item_appended _
        | Pre_tool_call _
        | Post_tool_response _
        | Turn_end
        | Internal_event _ )
    | Queue_head ->
      Error
        (error Invalid_request "constructor admits only its startup or resume callback")
  in
  let%bind () =
    match constructor.callback with
    | Unclaimed -> Ok ()
    | Claimed _ | Settled _ ->
      Error (error Conflict "constructor callback was already claimed")
  in
  let%bind () =
    match t.moderator_manager with
    | None -> Ok ()
    | Some installed when phys_equal installed manager -> Ok ()
    | Some _ ->
      Error (error Conflict "constructor cannot borrow another installed Manager")
  in
  let revision = t.state.counters.revision in
  let%bind checkpoint =
    Constructor_callback_checkpoint.prepare t.state ~manager ~callback
  in
  let snapshot = Chat_response.Moderator_manager.Callback.snapshot callback in
  let checkpoint_state =
    { t.state with
      moderator = Some checkpoint.moderator
    ; run_state = Some checkpoint.index
    }
  in
  let%bind receipt, event =
    Queued_moderator_event.claim_ordinary
      ~state:checkpoint_state
      ~id:(Agent_protocol.Id.Moderator_execution.create ())
      ~operation_id:None
      ~snapshot
      ~event
      ~now:(t.services.now ())
  in
  let%bind origin =
    match initialization_held_run t constructor with
    | Some run -> Ok (Some (Agent_protocol.Inference_origin.Run run.id))
    | None ->
      Invocation_inference_provenance.of_event
        ~runs:checkpoint_state.run_state
        ~jobs:checkpoint_state.jobs
        receipt
  in
  let%bind admission = transfer_agent_admission constructor.agent_admission in
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () -> if not !acknowledged then retire_agent_admission admission)
    ~f:(fun () ->
      let%bind prepared =
        prepare_transition
          ?run_preparation:(Initialization_scope_data.initial_preparation constructor)
          t
          ~delta:
            (Session_delta.Batch
               [ Run_state_changed checkpoint.index
               ; Moderator_changed (Some checkpoint.moderator)
               ; Moderator_execution_changed receipt
               ])
          ~payloads:[]
      in
      let%bind resource =
        Initialization_scope_data.Resource.select
          constructor.resource
          prepared.state
          ~manager
          ~source:checkpoint.source
          ~ordinals:[]
          ~schedules:[]
      in
      let acknowledgement =
        Initialization_scope_data.Acknowledgement.prepare
          ~callback:(Claimed receipt.context.id)
          ~resource
          constructor
          prepared.state
      in
      let%bind () =
        validate_initialization_projection
          (Initialization_scope_data.Acknowledgement.expected acknowledgement)
          prepared.state
      in
      let borrow =
        { kind = Ordinary
        ; lifecycle_owner = None
        ; job_scope = None
        ; agent_admission = Contextual None
        ; policy_source = Unknown
        ; receipt
        ; before = snapshot
        ; event
        ; retirement_reason = None
        ; run_actions = None
        ; callback_active = true
        ; native_goals = Goal_native_actions.create ()
        ; authority_live = Atomic.make true
        ; committed = false
        ; stop_retirement = None
        ; terminal_selection = None
        ; completion =
            Callback_completion_data.create
              ~issuing_actor:t.initialization_owner
              ~domain:t.runtime_source_domain
        ; cancel = None
        ; cancel_requested = false
        }
      in
      let scope : Callback_scope.t =
        { manager
        ; constructor_scope = Some constructor
        ; committed_checkpoint = None
        ; callback
        ; borrow
        ; source = checkpoint.source
        ; origin
        ; custody = Admitted admission
        }
      in
      Eio.Cancel.protect (fun () ->
        let%bind () = validate_initialization_scope t constructor in
        let%bind () = check_initialization_agent_actor constructor in
        let%bind () = check_agent_admission admission in
        let%bind () =
          Initialization_scope_data.Acknowledgement.check_basis acknowledgement
        in
        let%bind current =
          Constructor_callback_checkpoint.prepare t.state ~manager ~callback
        in
        let%bind () =
          if
            Int64.equal revision t.state.counters.revision
            && Agent_protocol.Run_source.equal checkpoint.source current.source
          then Ok ()
          else Error (error Conflict "constructor callback basis changed before commit")
        in
        let%bind () =
          persist_transition
            ?run_preparation:(Initialization_scope_data.initial_preparation constructor)
            ?check_before_commit:
              (held_startup_effect
                 t
                 (Initialization_scope_data.initial_preparation constructor))
            t
            prepared
        in
        install_committed_transition
          ?run_preparation:(Initialization_scope_data.initial_preparation constructor)
          ~initialization_acknowledgement:acknowledgement
          t
          prepared;
        t.queued_event_borrow <- Some borrow;
        t.idle_moderator_borrowed <- true;
        t.legacy_callback_scope <- Some scope;
        acknowledged := true;
        Callback_cleanup_data.Host.install_initialization_callback
          constructor.callback_cleanup
          ~issuer:t.initialization_owner
          ~scope:constructor.identity
          ~manager
          borrow.completion.facts;
        installed := Some scope;
        publish_committed_transition t prepared;
        Ok (Some scope)))
;;

let claim_legacy_boundary t manager callback parent event ~parent_cleanup ~installed =
  let open Result.Let_syntax in
  let%bind available = legacy_boundary_available t parent event in
  if not available
  then Ok None
  else (
    let snapshot = Chat_response.Moderator_manager.Callback.snapshot callback in
    let id = Agent_protocol.Id.Moderator_execution.create () in
    let%bind receipt, captured_event =
      match parent with
      | Callback_operation operation_id ->
        Queued_moderator_event.claim_ordinary
          ~state:t.state
          ~id
          ~operation_id
          ~snapshot
          ~event
          ~now:(t.services.now ())
      | Callback_job scope ->
        Queued_moderator_event.claim_job
          ~job:
            { job_id = scope.job.id
            ; attempt = scope.job.attempt
            ; deadline = scope.deadline
            }
          ~state:t.state
          ~id
          ~snapshot
          ~event
          ~now:(t.services.now ())
    in
    let%bind policy, policy_source =
      match parent with
      | Callback_operation _ -> Ok ([], Policy_standalone_source.Classification.Unknown)
      | Callback_job scope ->
        let%bind boundary = policy_job_boundary t scope in
        policy_birth_metadata t (policy_job_event_birth ~boundary) receipt
    in
    let%bind index, source = Moderator_source_installation.capture t.state in
    let%bind metadata = Moderator_checkpoint.queue t.state.moderator in
    let%bind metadata =
      match metadata with
      | Some metadata -> Ok metadata
      | None -> Moderator_queue.bootstrap ~source ~queue:snapshot.queued_internal_events
    in
    let%bind moderator =
      Moderator_checkpoint.update_with_queue t.state.moderator ~snapshot ~queue:metadata
    in
    let%bind origin =
      Invocation_inference_provenance.of_event
        ~runs:t.state.run_state
        ~jobs:t.state.jobs
        receipt
    in
    let%bind parent_admission, consume_lifecycle =
      legacy_boundary_admission t parent ~manager ~source
    in
    let%bind admission =
      match parent_admission with
      | None -> Ok None
      | Some admission -> Result.map (transfer_agent_admission admission) ~f:Option.some
    in
    let acknowledged = ref false in
    Exn.protect
      ~finally:(fun () ->
        if not !acknowledged then Option.iter admission ~f:retire_agent_admission)
      ~f:(fun () ->
        let%bind prepared =
          prepare_transition
            t
            ~delta:
              (Session_delta.Batch
                 ([ Session_delta.Run_state_changed index
                  ; Moderator_changed (Some moderator)
                  ; Moderator_execution_changed receipt
                  ]
                  @ policy))
            ~payloads:[]
        in
        let%bind () =
          if
            Chat_response.Moderator_manager.callback_is_current manager callback
            && Option.exists t.moderator_manager ~f:(phys_equal manager)
          then Ok ()
          else Error (error Conflict "legacy Manager changed before boundary claim")
        in
        let%bind () =
          match parent_admission with
          | None -> Ok ()
          | Some admission -> check_agent_admission admission
        in
        let%bind available = legacy_boundary_available t parent event in
        let%bind () =
          if available
          then Ok ()
          else Error (error Conflict "legacy boundary physical owner changed")
        in
        let%bind _, current_source = Moderator_source_installation.capture t.state in
        let%bind () =
          if Agent_protocol.Run_source.equal source current_source
          then Ok ()
          else Error (error Conflict "legacy boundary source changed before claim")
        in
        Eio.Cancel.protect (fun () ->
          let%bind () = persist_transition t prepared in
          install_committed_transition t prepared;
          let borrow =
            { kind = Ordinary
            ; lifecycle_owner = None
            ; job_scope =
                (match parent with
                 | Callback_job scope -> Some scope
                 | Callback_operation _ -> None)
            ; agent_admission = Contextual None
            ; policy_source
            ; receipt
            ; before = snapshot
            ; event = captured_event
            ; retirement_reason = None
            ; callback_active = true
            ; native_goals = Goal_native_actions.create ()
            ; authority_live = Atomic.make true
            ; run_actions = None
            ; committed = false
            ; stop_retirement = None
            ; terminal_selection = None
            ; completion =
                Callback_completion_data.create
                  ~issuing_actor:t.initialization_owner
                  ~domain:t.runtime_source_domain
            ; cancel = None
            ; cancel_requested = false
            }
          in
          let scope : Callback_scope.t =
            { manager
            ; constructor_scope = None
            ; committed_checkpoint = None
            ; callback
            ; borrow
            ; source
            ; origin
            ; custody =
                (match admission with
                 | None -> Unavailable
                 | Some admission -> Admitted admission)
            }
          in
          t.queued_event_borrow <- Some borrow;
          t.idle_moderator_borrowed <- true;
          t.legacy_callback_scope <- Some scope;
          if consume_lifecycle
          then (
            match t.lifecycle_agent_custody with
            | Admitted ({ pending = Pending current; _ } as lifecycle)
              when Option.exists parent_admission ~f:(phys_equal current) ->
              t.lifecycle_agent_custody <- Admitted { lifecycle with pending = Consumed };
              retire_agent_admission current
            | Unadmitted | Admitted _ -> ());
          acknowledged := true;
          Option.iter parent_cleanup ~f:(fun (parent : Operation_completion.t) ->
            Callback_cleanup_data.Host.install_operation_callback
              parent.callback_cleanup
              ~issuer:t.initialization_owner
              ~operation:parent.operation
              ~manager
              borrow.completion.facts);
          installed := Some scope;
          publish_committed_transition t prepared;
          Ok (Some scope))))
;;

let claim_legacy_head t manager callback operation_id ~parent_cleanup ~installed =
  let open Result.Let_syntax in
  let available () =
    match operation_id with
    | None -> Ok (idle_moderator_eligible t)
    | Some id ->
      let%map _ = running_operation t id in
      not (t.idle_moderator_borrowed || moderator_is_borrowed t)
  in
  let%bind ready = available () in
  if not ready
  then Ok None
  else (
    let snapshot = Chat_response.Moderator_manager.Callback.snapshot callback in
    let%bind receipt, event =
      Queued_moderator_event.claim_legacy
        ~callback
        ~operation_id
        ~state:t.state
        ~id:(Agent_protocol.Id.Moderator_execution.create ())
        ~now:(t.services.now ())
    in
    let%bind index, source = Moderator_source_installation.capture t.state in
    let%bind metadata = Moderator_checkpoint.queue t.state.moderator in
    let%bind metadata =
      match metadata with
      | Some metadata -> Ok metadata
      | None -> Moderator_queue.bootstrap ~source ~queue:snapshot.queued_internal_events
    in
    let%bind entry =
      Result.of_option
        (List.hd (Moderator_queue.entries metadata))
        ~error:
          (error Conflict "legacy callback requires the actual structural queue head")
    in
    let original =
      Legacy_queue_custody.find t.legacy_queue_custody ~manager ~source ~entry
    in
    let%bind policy_source =
      match original with
      | None -> Ok Policy_standalone_source.Classification.Unknown
      | Some row ->
        Policy_queue_source.claim
          ~state:t.state
          ~source
          ~entry
          ~receipt
          (Legacy_queue_custody.Row.policy_source row)
    in
    let%bind admission =
      match original with
      | None -> Ok None
      | Some original ->
        Result.map (Legacy_queue_custody.Row.transfer original) ~f:Option.some
    in
    let acknowledged = ref false in
    Exn.protect
      ~finally:(fun () ->
        if not !acknowledged then Option.iter admission ~f:retire_agent_admission)
      ~f:(fun () ->
        let%bind moderator =
          Moderator_checkpoint.update_with_queue
            t.state.moderator
            ~snapshot
            ~queue:metadata
        in
        (* The installation and original queue precede the Running leaf. No
           incoming receipt can certify its own source or attribution. *)
        let%bind policy = queued_event_policy_metadata t receipt in
        let%bind prepared =
          prepare_transition
            t
            ~delta:
              (Session_delta.Batch
                 ([ Session_delta.Run_state_changed index
                  ; Moderator_changed (Some moderator)
                  ; Moderator_execution_changed receipt
                  ]
                  @ policy))
            ~payloads:[]
        in
        let%bind () =
          if
            Chat_response.Moderator_manager.callback_is_current manager callback
            && Option.exists t.moderator_manager ~f:(phys_equal manager)
          then Ok ()
          else Error (error Conflict "legacy Manager changed before queue claim")
        in
        let%bind ready = available () in
        let%bind () =
          if ready
          then Ok ()
          else Error (error Conflict "legacy queue drainer changed before claim")
        in
        let%bind _, current_source = Moderator_source_installation.capture t.state in
        let%bind () =
          if Agent_protocol.Run_source.equal source current_source
          then Ok ()
          else Error (error Conflict "legacy queue source changed before claim")
        in
        let%bind () =
          match original with
          | None -> Ok ()
          | Some row -> Legacy_queue_custody.Row.check row
        in
        let borrow =
          { kind = Queued
          ; lifecycle_owner = None
          ; job_scope = None
          ; agent_admission = Contextual None
          ; policy_source
          ; receipt
          ; before = snapshot
          ; event
          ; retirement_reason = None
          ; run_actions = None
          ; callback_active = true
          ; native_goals = Goal_native_actions.create ()
          ; authority_live = Atomic.make true
          ; committed = false
          ; stop_retirement = None
          ; terminal_selection = None
          ; completion =
              Callback_completion_data.create
                ~issuing_actor:t.initialization_owner
                ~domain:t.runtime_source_domain
          ; cancel = None
          ; cancel_requested = false
          }
        in
        let scope : Callback_scope.t =
          { manager
          ; constructor_scope = None
          ; committed_checkpoint = None
          ; callback
          ; borrow
          ; source
          ; origin = Moderator_queue.Entry.origin entry
          ; custody =
              (match admission with
               | None -> Unavailable
               | Some admission -> Admitted admission)
          }
        in
        let remaining =
          Legacy_queue_custody.without t.legacy_queue_custody ~selected:original
        in
        Eio.Cancel.protect (fun () ->
          let%bind () = persist_transition t prepared in
          install_committed_transition t prepared;
          t.legacy_queue_custody
          <- Legacy_queue_custody.install t.legacy_queue_custody ~incoming:remaining;
          t.queued_event_borrow <- Some borrow;
          t.idle_moderator_borrowed <- true;
          t.legacy_callback_scope <- Some scope;
          acknowledged := true;
          Option.iter parent_cleanup ~f:(fun (parent : Operation_completion.t) ->
            Callback_cleanup_data.Host.install_operation_callback
              parent.callback_cleanup
              ~issuer:t.initialization_owner
              ~operation:parent.operation
              ~manager
              borrow.completion.facts);
          installed := Some scope;
          publish_committed_transition t prepared;
          Ok (Some scope))))
;;

let claim_legacy_callback t callback parent installed =
  let open Result.Let_syntax in
  let%bind () = require_selected_execution t in
  let%bind manager =
    match t.moderator_manager with
    | Some manager
      when Chat_response.Moderator_manager.callback_is_current manager callback ->
      Ok manager
    | _ -> Error (error Conflict "legacy callback requires its exact installed Manager")
  in
  let%bind parent_cleanup =
    match parent with
    | Callback_job _ | Callback_operation None -> Ok None
    | Callback_operation (Some operation_id) ->
      let%bind operation = running_operation t operation_id in
      let%bind completion =
        capture_operation_completion t operation_id
        |> Result.of_option
             ~error:(error Conflict "callback has no original operation completion")
      in
      let%map () =
        Callback_cleanup_data.Host.check_operation_registration
          completion.callback_cleanup
          ~issuer:t.initialization_owner
          ~operation
      in
      Some completion
  in
  match Chat_response.Moderator_manager.Callback.selection callback with
  | Boundary event ->
    claim_legacy_boundary t manager callback parent event ~parent_cleanup ~installed
  | Queue_head ->
    let%bind operation_id =
      match parent with
      | Callback_operation id -> Ok id
      | Callback_job _ ->
        Error (error Invalid_request "job callback cannot claim an unrelated queue head")
    in
    claim_legacy_head t manager callback operation_id ~parent_cleanup ~installed
;;

let queued_retirement_available t =
  (not t.idle_moderator_borrowed)
  && (not (moderator_is_borrowed t))
  && Option.is_none t.state.active_operation
  && (not (has_pending_permission t))
  &&
  match t.state.lifecycle.desired, t.state.lifecycle.observed with
  | Running, Idle | Stopped, Stopped -> true
  | _ -> false
;;

let claim_queued_retirement t id snapshot reason =
  let open Result.Let_syntax in
  match queued_retirement_available t with
  | false -> Ok None
  | true ->
    let%bind receipt, event =
      Queued_moderator_event.claim_retirement ~state:t.state ~id ~snapshot
    in
    let%bind _ =
      Agent_protocol.Moderator_execution.retire
        receipt
        ~checkpoint_sha256:receipt.context.checkpoint_sha256
        ~reason
    in
    let borrow =
      { kind = Queued
      ; lifecycle_owner = None
      ; job_scope = None
      ; agent_admission = Contextual None
      ; policy_source = Unknown
      ; receipt
      ; before = snapshot
      ; event
      ; retirement_reason = Some reason
      ; run_actions = None
      ; callback_active = true
      ; native_goals = Goal_native_actions.create ()
      ; authority_live = Atomic.make true
      ; committed = false
      ; stop_retirement = None
      ; terminal_selection = None
      ; completion =
          Callback_completion_data.create
            ~issuing_actor:t.initialization_owner
            ~domain:t.runtime_source_domain
      ; cancel = None
      ; cancel_requested = false
      }
    in
    t.queued_event_borrow <- Some borrow;
    t.idle_moderator_borrowed <- true;
    Ok (Some borrow)
;;

let queued_event_can_commit_installed t borrow =
  let open Result.Let_syntax in
  let%bind () = validate_queued_event_borrow t borrow in
  match borrow.job_scope, borrow.receipt.context.operation_id with
  | Some scope, None ->
    let%bind () = job_scope_can_execute t scope in
    (match
       borrow.callback_active && not (borrow.committed || borrow.cancel_requested)
     with
     | true -> Ok ()
     | false -> Error (error Conflict "job event cannot commit after completion or stop"))
  | Some _, Some _ -> Error (error Conflict "job event cannot borrow a model operation")
  | None, None when Option.is_some borrow.receipt.delegation ->
    let%bind () =
      if
        borrow.callback_active
        && not (borrow.committed || borrow.cancel_requested || t.state.halted)
      then Ok ()
      else
        Error (error Conflict "delegated policy cannot commit after completion or stop")
    in
    (match t.delegated_policy_claim with
     | Some capture ->
       let%bind () = Delegated_policy_custody.check_access t capture in
       (match Delegated_policy_claim_state.phase capture.state with
        | Activated attempt
          when phys_equal (Delegated_policy_claim_state.Attempt.borrow attempt) borrow ->
          Ok ()
        | Waiting | Prepared _ | Activated _ | Callback_acknowledged _ | Released ->
          Error (error Conflict "delegated policy does not own its installed claim"))
     | None ->
       (match t.state.lifecycle.desired, t.state.failure with
        | Running, None -> Ok ()
        | (Running | Stopped), _ ->
          Error (error Conflict "delegated policy cannot commit after completion or stop")))
  | None, Some id ->
    let%bind _ = running_operation t id in
    if
      borrow.callback_active
      && not (borrow.committed || borrow.cancel_requested || t.state.halted)
    then Ok ()
    else Error (error Conflict "foreground event cannot commit after completion or stop")
  | None, None ->
    (match
       ( borrow.retirement_reason
       , t.state.lifecycle.desired
       , t.state.lifecycle.observed
       , t.state.failure )
     with
     | (Some _, Running, Idle, _ | Some _, Stopped, Stopped, _)
       when borrow.callback_active
            && (not (borrow.committed || borrow.cancel_requested))
            && Option.is_none t.state.active_operation -> Ok ()
     | None, Running, Idle, None
       when borrow.callback_active
            && (not (borrow.committed || borrow.cancel_requested || t.state.halted))
            && Option.is_none t.state.active_operation -> Ok ()
     | _ -> Error (error Conflict "queued event cannot commit after completion or stop"))
;;

(* Physical constructor checks shared by effect admission and the nonyielding
   final inference guard. Original host policy refresh is a separate phase. *)
let constructor_event_current t borrow scope =
  let open Result.Let_syntax in
  let%bind () = validate_queued_event_borrow t borrow in
  let%bind () = check_initialization_agent_actor scope in
  if initialization_callback_is_owned t scope
  then Ok ()
  else Error (error Conflict "constructor callback is no longer current")
;;

let queued_event_inference_current t (borrow : queued_event_borrow) =
  match borrow.lifecycle_owner with
  | Some (Existing_goal_resume scope as owner) ->
    let%bind.Result () = lifecycle_event_basis t borrow owner in
    scope.continuation.binding.preparation.basis ()
  | Some owner -> lifecycle_event_basis t borrow owner
  | None ->
    (match constructor_scope_of_borrow t borrow with
     | None -> queued_event_can_commit_installed t borrow
     | Some scope ->
       let open Result.Let_syntax in
       let%bind () = validate_initialization_scope_current t scope in
       constructor_event_current t borrow scope)
;;

let queued_event_can_commit t (borrow : queued_event_borrow) =
  match borrow.lifecycle_owner with
  | Some owner -> lifecycle_event_effect t borrow owner
  | None ->
    (match constructor_scope_of_borrow t borrow with
     | None -> queued_event_can_commit_installed t borrow
     | Some scope ->
       let open Result.Let_syntax in
       let%bind () = validate_initialization_scope t scope in
       constructor_event_current t borrow scope)
;;

let callback_run_preparation (scope : Callback_scope.t) =
  Option.bind scope.constructor_scope ~f:(fun constructor ->
    Initialization_scope_data.initial_preparation constructor)
;;

let check_callback_scope_current t (scope : Callback_scope.t) =
  let open Result.Let_syntax in
  let%bind () =
    match t.legacy_callback_scope, scope.constructor_scope with
    | Some current, Some constructor when phys_equal current scope ->
      (match constructor.resource with
       | Some resource
         when initialization_callback_is_owned t constructor
              && phys_equal resource.manager scope.manager
              && Agent_protocol.Run_source.equal resource.source scope.source
              && not resource.handed_off -> Ok ()
       | None | Some _ -> Error (error Conflict "constructor callback resource changed"))
    | Some current, None when phys_equal current scope ->
      (match t.moderator_manager with
       | Some manager
         when phys_equal manager scope.manager
              && Chat_response.Moderator_manager.callback_is_current
                   manager
                   scope.callback -> Ok ()
       | None | Some _ ->
         Error (error Conflict "legacy callback no longer owns the installed Manager"))
    | None, _ | Some _, _ ->
      Error (error Conflict "legacy callback no longer owns its exact borrow")
  in
  let%bind _, source = Moderator_source_installation.capture t.state in
  let%bind () =
    if Agent_protocol.Run_source.equal source scope.source
    then Ok ()
    else Error (error Conflict "legacy callback source installation changed")
  in
  let%bind () =
    match scope.borrow.job_scope with
    | None -> Ok ()
    | Some job_scope ->
      let%bind current =
        job_callback_admission t job_scope ~manager:scope.manager ~source:scope.source
      in
      (match scope.custody, current with
       | Unavailable, None | Admitted _, Some _ -> Ok ()
       | Unavailable, Some _ | Admitted _, None ->
         Error (error Conflict "Job callback admission changed before commit"))
  in
  match scope.custody with
  | Unavailable -> Ok ()
  | Admitted admission -> check_agent_admission admission
;;

let check_callback_inference_current t (scope : Callback_scope.t) =
  let open Result.Let_syntax in
  let%bind () = queued_event_inference_current t scope.borrow in
  check_callback_scope_current t scope
;;

let check_callback_current t (scope : Callback_scope.t) =
  let open Result.Let_syntax in
  let%bind () = queued_event_can_commit t scope.borrow in
  check_callback_scope_current t scope
;;

let callback_actor_after_current t ~scope =
  let open Result.Let_syntax in
  match scope.Callback_scope.custody with
  | Unavailable ->
    Error (error Permission_denied "legacy queue continuation custody is unavailable")
  | Admitted admission ->
    (match Execution_custody.Admission.custody admission with
     | None -> Ok None
     | Some custody ->
       let%map actor = Execution_custody.actor custody in
       Some
         (Operator_authorization.restrict
            actor
            ~is_current:(fun () ->
              Result.is_ok (check_callback_inference_current t scope))))
;;

let callback_agent_actor t ~scope =
  let open Result.Let_syntax in
  let%bind () = check_callback_current t scope in
  callback_actor_after_current t ~scope
;;

let callback_inference_actor t ~scope =
  let open Result.Let_syntax in
  let%bind () = check_callback_inference_current t scope in
  callback_actor_after_current t ~scope
;;

let event_execution_owned_by borrow (execution : invocation_execution) =
  match execution.owner with
  | Event_moderator owner -> phys_equal owner borrow
  | _ -> false
;;

let active_script_parent t ~owns (invocation : Agent_protocol.Invocation.t) =
  let open Result.Let_syntax in
  let%bind parent =
    match invocation.context.origin, invocation.context.parent_invocation with
    | Script, Some parent
      when Option.is_none invocation.parent_event
           && Option.is_none invocation.context.parent_job
           && Option.is_none invocation.context.provider_call_id
           && Option.is_none invocation.context.call_entry_id ->
      List.find t.invocation_executions ~f:(fun execution ->
        execution.accepts_children
        && owns execution
        && Agent_protocol.Id.Invocation.equal execution.dispatched.context.id parent)
      |> Result.of_option
           ~error:(error Conflict "script parent is not active in this owner")
    | _ -> Error (error Conflict "owned descendants require a script parent link")
  in
  let%bind () =
    Extension_invariants.owner
      ~session_id:parent.dispatched.context.session_id
      ~generation:parent.dispatched.context.generation
      invocation.context.session_id
      invocation.context.generation
  in
  match parent.dispatched.context.deadline, invocation.context.deadline with
  | None, _ -> Ok ()
  | Some parent, Some child when Agent_protocol.Timestamp.compare child parent <= 0 ->
    Ok ()
  | Some _, _ ->
    Error (error Conflict "script descendant cannot extend its parent's deadline")
;;

let compatible_script_observer observer (invocation : Agent_protocol.Invocation.t) =
  match invocation.observation with
  | None -> Ok ()
  | Some observation
    when Agent_protocol.Invocation.equal_observer observer observation.observer -> Ok ()
  | Some _ -> Error (error Conflict "script descendant has a different moderator source")
;;

let claim_event_invocation t borrow (invocation : Agent_protocol.Invocation.t) =
  let open Result.Let_syntax in
  let revision = t.state.counters.revision in
  let%bind () = queued_event_can_commit t borrow in
  let%bind () =
    match
      ( Option.bind borrow.job_scope ~f:(fun scope -> scope.deadline)
      , invocation.context.deadline )
    with
    | None, _ -> Ok ()
    | Some parent, Some child when Agent_protocol.Timestamp.compare child parent <= 0 ->
      Ok ()
    | _ -> Error (error Conflict "job event invocation cannot extend its deadline")
  in
  let%bind () =
    match borrow.retirement_reason, invocation.parent_event with
    | None, Some parent
      when Agent_protocol.Id.Moderator_execution.equal parent borrow.receipt.context.id ->
      Ok ()
    | None, None ->
      let%bind () =
        active_script_parent t ~owns:(event_execution_owned_by borrow) invocation
      in
      compatible_script_observer borrow.receipt.context.source invocation
    | _ -> Error (error Conflict "invocation does not belong to this executing event")
  in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      invocation.context.session_id
      invocation.context.generation
  in
  let%bind () =
    Extension_invariants.invocation_event_owner
      ~events:t.state.moderator_executions
      invocation
  in
  let%bind origin = event_invocation_origin t borrow.receipt invocation in
  let%bind boundary = policy_event_boundary t borrow in
  let%bind invocation, admission, policy_source =
    invocation_admission_deltas t invocation ~origin ~boundary
  in
  let%bind dispatched = Agent_protocol.Invocation.dispatch invocation in
  let run_preparation = event_run_preparation t borrow in
  let%bind prepared =
    prepare_transition
      ?run_preparation
      t
      ~delta:(Session_delta.Batch (admission @ [ Invocation_changed dispatched ]))
      ~payloads:[]
  in
  let%bind initialization_acknowledgement =
    prepare_constructor_invocation_ack t borrow ~before:None ~after:dispatched prepared
  in
  let%bind goal_runtime_acknowledgement =
    Option.value_map (goal_runtime_of_borrow borrow) ~default:(Ok None) ~f:(fun scope ->
      Goal_runtime_acknowledgement.prepare t scope ~candidate:prepared
      |> Result.map ~f:Option.some)
  in
  let execution =
    { owner = Event_moderator borrow
    ; policy_source
    ; native_goal = None
    ; context_rollover_basis = None
    ; dispatched
    ; accepts_children = true
    ; authority_live = Atomic.make true
    }
  in
  let%bind () =
    Eio.Cancel.protect (fun () ->
      let%bind () = queued_event_can_commit t borrow in
      let%bind () =
        check_constructor_invocation_ack t borrow initialization_acknowledgement
      in
      let%bind () =
        if Int64.equal revision t.state.counters.revision
        then Ok ()
        else Error (error Conflict "Invocation ACK basis changed before commit")
      in
      let%bind () =
        persist_transition
          ?run_preparation
          ~check_before_commit:(fun () ->
            let%bind () = queued_event_can_commit t borrow in
            Option.value_map goal_runtime_acknowledgement ~default:(Ok ()) ~f:(fun ack ->
              Goal_runtime_acknowledgement.check ack ~actor:t ~candidate:prepared))
          t
          prepared
      in
      install_committed_transition
        ?goal_runtime_acknowledgement
        ?run_preparation
        ?initialization_acknowledgement
        t
        prepared;
      t.invocation_executions <- execution :: t.invocation_executions;
      publish_committed_transition t prepared;
      Ok ())
  in
  Ok execution
;;

let check_run_authority t scope = check_run_binding t (Run_scope.run_id scope)

let run_turn_deltas ?work_delta ?completion_sample t operation events deliveries =
  let open Result.Let_syntax in
  let now =
    match completion_sample with
    | None -> t.services.now ()
    | Some sample -> Recurrence_runtime.Completion.wall sample
  in
  let%bind resumed, deltas =
    Run_transition.admit_turn ?work_delta t.state ~operation ~events ~deliveries ~now
  in
  let%map () =
    List.fold_result resumed ~init:() ~f:(fun () run_id -> check_run_binding t run_id)
  in
  deltas
;;

let run_actions_internal t (executing : Agent_protocol.Moderator_execution.t) =
  let open Result.Let_syntax in
  let%bind borrow =
    match t.queued_event_borrow with
    | Some borrow when Agent_protocol.Moderator_execution.equal borrow.receipt executing
      -> Ok borrow
    | Some _ | None ->
      Error (error Conflict "run actions require the exact active event borrow")
  in
  let%bind () = queued_event_can_commit t borrow in
  match t.legacy_callback_scope with
  | Some scope when phys_equal scope.borrow borrow ->
    let%map () = check_callback_current t scope in
    None
  | None | Some _ ->
    (match borrow.run_actions with
     | Some owner ->
       let%map () = check_run_authority t (Run_action_service.scope owner) in
       Some owner
     | None ->
       let%bind selected = selected_event_run t borrow in
       (match selected with
        | None -> Ok None
        | Some run ->
          let%bind scope = Run_scope.create ~run ~execution_id:executing.context.id in
          let%map () = check_run_authority t scope in
          let owner = Run_action_service.create ~scope in
          borrow.run_actions <- Some owner;
          Some owner))
;;

module Prepared_run_delta = struct
  type t =
    { deltas : Session_delta.t list
    ; completion_sample : Recurrence_runtime.Completion.sample option
    }

  let empty = { deltas = []; completion_sample = None }
end

let lifecycle_selection (borrow : queued_event_borrow) run =
  Option.bind borrow.lifecycle_owner ~f:(function
    | Lifecycle_callback_owner.Initial_authored _ ->
      Option.map run ~f:(fun run -> Run_transition.Lifecycle_selection.Authored_start run)
    | Existing_goal_resume _ ->
      (match borrow.receipt.context.phase with
       | Session_resume ->
         Option.map run ~f:(fun run -> Run_transition.Lifecycle_selection.Goal_resume run)
       | Internal_event ->
         (* Already-owned queued callbacks use their actual Run_event_scope.
            Physical Goal scope/borrow authority is validated independently. *)
         None
       | Session_start
       | Turn_start
       | Message_appended
       | Pre_tool_call
       | Post_tool_response
       | Turn_end -> None))
;;

module Native_goal_plan = struct
  type t =
    { actions : Goal_native_actions.t option
    ; plan : Goal_native_actions.Plan.t option
    ; source : Agent_protocol.Invocation.observer option
    ; entries : Goal_native_actions.Entry.t list
    ; accepted : (Agent_protocol.Invocation.t * Goal_native_actions.Entry.t) list
    }

  let fresh_holds t =
    Option.value_map t.plan ~default:[] ~f:Goal_native_actions.Plan.fresh_holds
  ;;

  let check_scheduling t ~run_id ~action ~request_turn =
    Option.value_map t.plan ~default:(Ok ()) ~f:(fun plan ->
      Goal_native_actions.Plan.check_scheduling plan ~run_id ~action ~request_turn)
  ;;

  let deltas t =
    Option.value_map t.plan ~default:[] ~f:Goal_native_actions.Plan.deltas
    @ List.map t.accepted ~f:(fun (invocation, _) ->
      Session_delta.Invocation_changed invocation)
  ;;
end

let prepare_native_goal_plan t ?actions ?completed entries =
  let open Result.Let_syntax in
  if List.is_empty entries
  then
    Ok
      Native_goal_plan.
        { actions; plan = None; source = None; entries = []; accepted = [] }
  else (
    let%bind source = Runtime_builder.moderator_snapshot_observer t.state.moderator in
    let%bind controller = require_recurrence_controller t in
    let%bind plan =
      Goal_native_actions.Plan.prepare
        entries
        ~state:t.state
        ~session:(Recurrence_controller.session controller)
        ~descendant_profile:t.services.goal_descendant_profile
        ~now:(t.services.now ())
    in
    let%map accepted =
      List.fold_result
        (Goal_native_actions.Plan.dispatches plan)
        ~init:[]
        ~f:(fun accepted_entries entry ->
          let%bind invocation =
            Option.first_some
              (Option.filter completed ~f:(fun invocation ->
                 Agent_protocol.Id.Invocation.equal
                   invocation.Agent_protocol.Invocation.context.id
                   (Goal_native_actions.Entry.invocation_id entry)))
              (List.find t.state.invocations ~f:(fun invocation ->
                 Agent_protocol.Id.Invocation.equal
                   invocation.context.id
                   (Goal_native_actions.Entry.invocation_id entry)))
            |> Result.of_option
                 ~error:
                   (error Conflict "native Goal result is absent from its actual owner")
          in
          let%bind staged, accepted =
            match Goal_native_actions.Entry.value entry with
            | Start intent ->
              let%map accepted =
                Agent_protocol.Goal_native_start_intent.accept
                  intent
                  ~now:(t.services.now ())
              in
              ( Agent_protocol.Goal_native_action_intent.Start intent
              , Agent_protocol.Goal_native_action_intent.Start accepted )
            | Resume intent ->
              let%map accepted =
                Agent_protocol.Goal_native_resume_intent.accept
                  intent
                  ~now:(t.services.now ())
              in
              ( Agent_protocol.Goal_native_action_intent.Resume intent
              , Agent_protocol.Goal_native_action_intent.Resume accepted )
            | Edit _ ->
              Error (error Internal_error "native dispatch selection changed kind")
          in
          let%bind () =
            if
              Option.exists
                invocation.native_goal_action
                ~f:(Agent_protocol.Goal_native_action_intent.equal staged)
            then Ok ()
            else Error (error Conflict "native Goal staged identity changed")
          in
          let%map invocation =
            Agent_protocol.Invocation.record_native_goal_action invocation accepted
          in
          (invocation, entry) :: accepted_entries)
    in
    Native_goal_plan.
      { actions; plan = Some plan; source; entries; accepted = List.rev accepted })
;;

let prepare_callback_native_goals t actions =
  let open Result.Let_syntax in
  let%bind entries = Goal_native_actions.for_commit actions in
  prepare_native_goal_plan t ~actions entries
;;

let check_native_goal_plan t (plan : Native_goal_plan.t) =
  let open Result.Let_syntax in
  let%bind () =
    Option.value_map plan.plan ~default:(Ok ()) ~f:(fun plan ->
      Goal_native_actions.Plan.check plan t.state)
  in
  match plan.actions with
  | None -> Ok ()
  | Some actions ->
    let%bind actual = Goal_native_actions.for_commit actions in
    if List.equal phys_equal actual plan.entries
    then Ok ()
    else Error (error Conflict "native Goal callback selection changed")
;;

let install_native_goal_plan t (plan : Native_goal_plan.t) =
  List.iter plan.entries ~f:(fun entry ->
    match Goal_native_actions.Entry.value entry with
    | Edit _ -> Goal_native_actions.Entry.discard entry
    | Start _ | Resume _ -> Goal_native_actions.Entry.retain entry);
  List.iter plan.accepted ~f:(fun (invocation, entry) ->
    let key = Invocation_intent invocation.Agent_protocol.Invocation.context.id in
    let existing =
      List.find t.intent_agent_custody ~f:(fun slot ->
        equal_agent_intent_key slot.key key)
    in
    let slot =
      { key
      ; retention = Agent_intent_retention.Ordinary
      ; generation = invocation.context.generation
      ; source = plan.source
      ; custody = Option.bind existing ~f:(fun slot -> slot.custody)
      ; observation = Option.bind existing ~f:(fun slot -> slot.observation)
      ; native_goal =
          Some { entry; dispatch_finished = false; failure = None; preparation = None }
      }
    in
    t.intent_agent_custody
    <- slot
       :: List.filter t.intent_agent_custody ~f:(fun slot ->
         not (equal_agent_intent_key slot.key key)))
;;

let prepare_callback_goal_control
      t
      (borrow : queued_event_borrow)
      (plan : Native_goal_plan.t)
      (candidate : Session_state.t)
  =
  let owner =
    match borrow.lifecycle_owner with
    | Some (Lifecycle_callback_owner.Initial_authored scope) ->
      let activation = Admitted_activation.Continuation.target scope.continuation in
      Some (activation.control_owner, activation.run.id)
    | Some (Existing_goal_resume scope) ->
      let preparation = scope.continuation.binding.preparation in
      Some (preparation.control_owner, preparation.run.id)
    | None ->
      Option.bind (constructor_scope_of_borrow t borrow) ~f:(fun scope ->
        Option.bind (Initialization_scope_data.construction scope) ~f:(fun construction ->
          Option.bind (construction_control_owner construction) ~f:(fun owner ->
            Option.map (initialization_held_run t scope) ~f:(fun run -> owner, run.id))))
  in
  let controls =
    Option.value_map plan.plan ~default:[] ~f:Goal_native_actions.Plan.fresh_controls
  in
  match owner with
  | None -> Ok None
  | Some (owner, run_id) ->
    Goal_callback_control.prepare
      ~owner
      ~run_id
      ~callback:borrow.receipt.context.id
      ~controls
      candidate
;;

let install_callback_goal_control t (borrow : queued_event_borrow) control =
  Option.iter control ~f:(fun control ->
    match borrow.lifecycle_owner with
    | Some (Lifecycle_callback_owner.Initial_authored scope) ->
      (Admitted_activation.Continuation.target scope.continuation).control <- Some control
    | Some (Existing_goal_resume scope) ->
      scope.continuation.binding.preparation.control <- Some control
    | None ->
      Option.iter (constructor_scope_of_borrow t borrow) ~f:(fun scope ->
        Option.iter (Initialization_scope_data.construction scope) ~f:(fun construction ->
          install_construction_control construction control;
          scope.control <- Some control)))
;;

let prepared_run_delta
      ?goal_plan
      t
      (borrow : queued_event_borrow)
      completed
      ~checkpoint
      requests
      job_deltas
  =
  let open Result.Let_syntax in
  let planning_state =
    Option.value_map goal_plan ~default:t.state ~f:Goal_native_actions.Plan.state
  in
  let check_scheduling run_id action =
    Option.value_map goal_plan ~default:(Ok ()) ~f:(fun plan ->
      Goal_native_actions.Plan.check_scheduling
        plan
        ~run_id
        ~action
        ~request_turn:requests.Agent_protocol.Invocation.request_turn)
  in
  match borrow.run_actions with
  | None ->
    let%bind run =
      if Option.is_some goal_plan then selected_event_run t borrow else Ok None
    in
    let%map () =
      check_scheduling (Option.map run ~f:(fun run -> run.Agent_protocol.Run.id)) None
    in
    Prepared_run_delta.empty
  | Some owner ->
    let scope = Run_action_service.scope owner in
    let%bind () = check_run_authority t scope in
    let%bind action =
      Run_action_service.prepared owner |> Result.map_error ~f:(error Conflict)
    in
    let%bind () = check_scheduling (Some (Run_scope.run_id scope)) action in
    let%bind _ =
      Run_action_service.compose_requests owner ~action ~requests
      |> Result.map_error ~f:(error Conflict)
    in
    let%bind owned_work =
      List.filter_map job_deltas ~f:(function
        | Session_delta.Job_changed job -> Some (Run_job_occurrence.work job)
        | Schedule_changed schedule ->
          Some
            (Agent_protocol.Run_work.create
               ~key:(Retained (Schedule schedule.id))
               ~generation:schedule.generation)
        | Subscription_changed subscription ->
          Some
            (Agent_protocol.Run_work.create
               ~key:(Retained (Subscription subscription.context.id))
               ~generation:subscription.context.generation)
        | Delivery_changed delivery ->
          Some
            (Agent_protocol.Run_work.create
               ~key:(Retained (Delivery delivery.context.id))
               ~generation:delivery.context.generation)
        | _ -> None)
      |> Result.all
    in
    let run =
      Option.bind t.state.run_state ~f:(fun index ->
        Run_state.find index (Run_scope.run_id scope))
    in
    let owns_callback =
      run
      |> Option.exists ~f:(fun run ->
        List.exists run.Agent_protocol.Run.owned_work ~f:(fun work ->
          match work.Agent_protocol.Run_work.key with
          | Retained (Moderator_execution id) ->
            Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
          | Operation _
          | Retained (Job _ | Schedule _ | Invocation _ | Subscription _ | Delivery _) ->
            false))
    in
    let initial_single_turn =
      Option.exists run ~f:(fun run ->
        Run_event_scope.is_initial_single_turn run borrow.receipt.context)
    in
    if
      Option.is_none action
      && List.is_empty owned_work
      && (not owns_callback)
      && (not initial_single_turn)
      && Option.is_none borrow.lifecycle_owner
    then Ok Prepared_run_delta.empty
    else (
      let%bind work_delta =
        Session_delta.capture_new_model_jobs
          planning_state
          (* Run planning validates the completed callback together with its
             actual consumed checkpoint, as the final transaction does. *)
          (Session_delta.Batch
             (job_deltas
              @ [ Moderator_execution_changed completed
                ; Moderator_changed (Some checkpoint)
                ]))
      in
      let%bind work_state = Session_delta.apply planning_state work_delta in
      let now, completion_sample = completion_clock_pair t in
      let%bind prepared =
        Run_transition.prepare
          ?lifecycle_selection:(lifecycle_selection borrow run)
          ?startup_run:(pending_held_startup_run t)
          planning_state
          ~scope
          ~executing:borrow.receipt
          ~work_delta
          ~owned_work
          ~action
          ~now
      in
      let%bind () =
        match action with
        | Some (Wait wake) ->
          (match wake.occurrence with
           | Job_completion { job_id; attempt = _ } ->
             (match
                List.find work_state.jobs ~f:(fun job ->
                  Agent_protocol.Id.Job.equal job.Agent_protocol.Job.id job_id)
              with
              | None -> Error (error Invalid_request "job wait has no retained producer")
              | Some job ->
                Run_job_capacity.validate_wait
                  job
                  ~run:(Run_transition.run prepared)
                  ~publisher:t.services.job_results)
           | Delivered_timer _ | Subscription_delivery _ -> Ok ())
        | None | Some (Continue | Finish _) -> Ok ()
      in
      let%bind goal_finish =
        Run_action_service.prepared_goal_finish owner
        |> Result.map_error ~f:(fun message -> error Conflict message)
      in
      let%map goal_deltas =
        match goal_finish with
        | None -> Ok []
        | Some intent ->
          Goal_run_transition.prepare_request planning_state ~scope ~prepared ~intent
      in
      Prepared_run_delta.
        { deltas = Run_transition.delta prepared :: goal_deltas
        ; completion_sample = Some completion_sample
        })
;;

let commit_queued_event t borrow snapshot requests decision notifications =
  let open Result.Let_syntax in
  let%bind () = queued_event_can_commit t borrow in
  let%bind () =
    match List.exists t.invocation_executions ~f:(event_execution_owned_by borrow) with
    | true -> Error (error Conflict "event native invocations still require completion")
    | false -> Ok ()
  in
  let%bind () =
    match t.legacy_callback_scope with
    | Some scope when phys_equal scope.borrow borrow -> check_callback_current t scope
    | None | Some _ -> Ok ()
  in
  let%bind () =
    match t.legacy_callback_scope with
    | Some scope when phys_equal scope.borrow borrow ->
      (match scope.custody with
       | Unavailable
         when requests.Agent_protocol.Invocation.request_turn
              || requests.request_compaction ->
         Error
           (error
              Permission_denied
              "legacy continuation custody is unavailable for turn or compaction requests")
       | Unavailable | Admitted _ -> Ok ())
    | None | Some _ -> Ok ()
  in
  let%bind receipt, admission_deltas =
    match borrow.retirement_reason, borrow.receipt.status with
    | Some reason, Running ->
      let%bind current_reason =
        Queued_moderator_event.delivery_retirement_reason
          ~state:t.state
          ~observer:borrow.receipt.context.source
          ~event:borrow.event
          ~subscription_expired:(subscription_is_due t)
      in
      let%bind () =
        match current_reason with
        | Some current when String.equal current reason -> Ok ()
        | _ ->
          Error
            (error Conflict "queued delivery retirement no longer matches its admission")
      in
      let%map interrupted =
        Agent_protocol.Moderator_execution.interrupt borrow.receipt ~reason
      in
      ( interrupted
      , [ Session_delta.Moderator_execution_changed borrow.receipt
        ; Moderator_execution_changed interrupted
        ] )
    | _ -> Ok (borrow.receipt, [])
  in
  let%bind completed =
    match borrow.receipt.delegation, decision, borrow.retirement_reason with
    | Some _, Some decision, None ->
      Queued_moderator_event.complete_delegated
        ~decision
        ~claimed:borrow.receipt
        ~before:borrow.before
        ~snapshot
        ~requests
    | Some _, _, _ | None, Some _, _ ->
      Error (error Invalid_state "delegated decision does not match event ownership")
    | None, None, None ->
      (match borrow.kind with
       | Queued -> Queued_moderator_event.complete
       | Ordinary -> Queued_moderator_event.complete_ordinary)
        ~claimed:borrow.receipt
        ~before:borrow.before
        ~snapshot
        ~requests
    | None, None, Some reason ->
      (match
         ( requests.Agent_protocol.Invocation.request_turn
         , requests.request_compaction
         , requests.end_session )
       with
       | false, false, None ->
         Queued_moderator_event.retire
           ~claimed:receipt
           ~before:borrow.before
           ~snapshot
           ~reason
       | _ ->
         Error (error Invalid_state "failed-head retirement cannot schedule new work"))
  in
  let legacy_scope =
    Option.filter t.legacy_callback_scope ~f:(fun scope -> phys_equal scope.borrow borrow)
  in
  let run_preparation =
    match Option.bind borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial with
    | Some _ -> event_run_preparation t borrow
    | None -> Option.bind legacy_scope ~f:callback_run_preparation
  in
  let manager = t.moderator_manager in
  let%bind encoded_snapshot, queue_plan, source_deltas, queue_metadata =
    match legacy_scope with
    | Some scope ->
      let%bind metadata = Moderator_checkpoint.queue t.state.moderator in
      let%bind metadata =
        Result.of_option
          metadata
          ~error:(error Internal_error "legacy callback queue metadata disappeared")
      in
      let%bind plan =
        Legacy_queue_checkpoint.prepare
          ~metadata
          ~before:borrow.before
          ~snapshot
          ~consumption:
            (match borrow.kind with
             | Ordinary -> Keep
             | Queued -> Consume_head)
          ~completed
          ~origin:scope.origin
      in
      let%map encoded =
        Moderator_checkpoint.update_with_queue
          t.state.moderator
          ~snapshot
          ~queue:(Legacy_queue_checkpoint.metadata plan)
      in
      encoded, Some plan, [], Legacy_queue_checkpoint.metadata plan
    | None ->
      let%bind index, metadata = capture_modern_callback_queue t ~before:borrow.before in
      let%bind queue_plan, metadata =
        match completed.status with
        | Completed _ ->
          let%bind origin =
            Invocation_inference_provenance.of_event
              ~runs:t.state.run_state
              ~jobs:t.state.jobs
              completed
          in
          let%map plan =
            Legacy_queue_checkpoint.prepare
              ~metadata
              ~before:borrow.before
              ~snapshot
              ~consumption:
                (match borrow.kind with
                 | Ordinary -> Keep
                 | Queued -> Consume_head)
              ~completed
              ~origin
          in
          Some plan, Legacy_queue_checkpoint.metadata plan
        | Failed _ | Interrupted _ ->
          (* The already validated retirement consumes only its exact failed
             head. It is not a successful producer and appends no new value. *)
          let%map metadata =
            Moderator_queue.advance
              metadata
              ~before:borrow.before.queued_internal_events
              ~after:snapshot.queued_internal_events
              ~consume:Consume_head
              ~appended:[]
          in
          None, metadata
        | Running ->
          Error (error Internal_error "callback completion retained Running status")
      in
      let%map encoded =
        Moderator_checkpoint.update_with_queue t.state.moderator ~snapshot ~queue:metadata
      in
      encoded, queue_plan, [ Session_delta.Run_state_changed index ], metadata
  in
  let owner = Agent_protocol.Job.Moderator_event borrow.receipt.context.id in
  let%bind job_deltas, job_payloads = staged_work_changes t owner in
  let%bind schedule_custody_installation =
    prepare_creator_custody t ~owner ~changes:job_deltas
  in
  let%bind native_goals = prepare_callback_native_goals t borrow.native_goals in
  let%bind run_change =
    prepared_run_delta
      ?goal_plan:native_goals.plan
      t
      borrow
      completed
      ~checkpoint:encoded_snapshot
      requests
      job_deltas
  in
  let%bind staged =
    match legacy_scope, queue_plan with
    | Some scope, Some plan ->
      (match scope.custody with
       | Unavailable -> Ok Legacy_queue_custody.empty
       | Admitted parent ->
         Legacy_queue_custody.stage
           ~manager:scope.manager
           ~source:scope.source
           ~entries:(Legacy_queue_checkpoint.appended plan)
           ~parent)
    | None, Some plan ->
      let%bind parent = event_settlement_parent t borrow in
      stage_completed_callback_queue
        ~manager
        ~metadata:queue_metadata
        ~entries:(Legacy_queue_checkpoint.appended plan)
        ~parent
    | None, None -> Ok Legacy_queue_custody.empty
    | Some _, None ->
      Error (error Internal_error "legacy checkpoint plan lost its physical scope")
  in
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () -> if not !acknowledged then Legacy_queue_custody.retire staged)
    ~f:(fun () ->
      let%bind inventory =
        match legacy_scope, queue_plan with
        | Some scope, Some plan ->
          Legacy_queue_custody.candidate
            t.legacy_queue_custody
            ~manager:scope.manager
            ~metadata:(Legacy_queue_checkpoint.metadata plan)
            ~staged
        | None, (Some _ | None) ->
          callback_queue_inventory t ~manager ~metadata:queue_metadata ~staged
        | Some _, None ->
          Error (error Internal_error "legacy checkpoint plan lost its physical scope")
      in
      let%bind admission = event_agent_admission t borrow in
      let custody = Option.bind admission ~f:Execution_custody.Admission.custody in
      let%bind retention = callback_intent_retention t borrow in
      with_selected_intent_agent_custody
        t
        owner
        (Event_intent completed.context.id)
        ~retention
        ~pending:(Observation_follow_up.pending_event completed)
        custody
        (fun ~job_custody ~check_jobs ~acknowledge ->
           let delta =
             Session_delta.Batch
               (source_deltas
                @ admission_deltas
                @ [ Session_delta.Moderator_execution_changed completed
                  ; Moderator_changed (Some encoded_snapshot)
                  ]
                @ Native_goal_plan.deltas native_goals
                @ job_deltas
                @ run_change.deltas)
           in
           let completion_sample =
             producer_completion_sample
               ?completion_sample:run_change.completion_sample
               t
               ~delta
           in
           let%bind prepared =
             prepare_transition
               ?run_preparation
               ?completion_sample
               t
               ~delta
               ~payloads:
                 (job_payloads
                  @ List.map notifications ~f:(fun message ->
                    Agent_protocol.Event.Durable.Payload.Moderator_notification
                      (`Object
                          [ "message", `String message
                          ; ( "moderator_execution_id"
                            , Agent_protocol.Id.Moderator_execution.to_json
                                borrow.receipt.context.id )
                          ])))
           in
           let%bind initialization_acknowledgement =
             match legacy_scope, queue_plan with
             | Some scope, Some plan ->
               (match scope.constructor_scope with
                | None -> Ok None
                | Some constructor ->
                  let%bind resource =
                    Initialization_scope_data.Resource.select
                      constructor.resource
                      prepared.state
                      ~manager:scope.manager
                      ~source:scope.source
                      ~ordinals:
                        (List.map
                           (Legacy_queue_checkpoint.appended plan)
                           ~f:Moderator_queue.Entry.ordinal)
                      ~schedules:[]
                  in
                  let selected_jobs =
                    List.filter_map job_deltas ~f:(function
                      | Session_delta.Job_changed job -> Some job.id
                      | _ -> None)
                  in
                  let jobs =
                    List.dedup_and_sort
                      (constructor.jobs @ selected_jobs)
                      ~compare:Agent_protocol.Id.Job.compare
                  in
                  let acknowledgement =
                    Initialization_scope_data.Acknowledgement.prepare
                      ?goal_plan:native_goals.plan
                      ~callback:(Settled completed.context.id)
                      ~resource
                      ~jobs
                      constructor
                      prepared.state
                  in
                  let%map () =
                    validate_initialization_projection
                      (Initialization_scope_data.Acknowledgement.expected acknowledgement)
                      prepared.state
                  in
                  Some acknowledgement)
             | None, (Some _ | None) -> Ok None
             | Some _, None ->
               Error (error Internal_error "constructor queue plan lost its callback")
           in
           let%bind goal_runtime_acknowledgement =
             match goal_runtime_of_borrow borrow with
             | None -> Ok None
             | Some scope ->
               Goal_runtime_acknowledgement.prepare t scope ~candidate:prepared
               |> Result.map ~f:Option.some
           in
           let%bind control =
             prepare_callback_goal_control t borrow native_goals prepared.state
           in
           let%bind completion_plan =
             prepare_completion_plan t prepared completion_sample
           in
           let%bind () = queued_event_can_commit t borrow in
           let%bind () =
             match legacy_scope with
             | None -> Ok ()
             | Some scope -> check_callback_current t scope
           in
           (* The checkpoint and each child loan become visible together before
             publication can yield. A post-ACK publication exception must not
             retire acknowledged children or make this callback replayable. *)
           Eio.Cancel.protect (fun () ->
             let%bind () = check_jobs () in
             let%bind () =
               Option.value_map
                 initialization_acknowledgement
                 ~default:(Ok ())
                 ~f:Initialization_scope_data.Acknowledgement.check_basis
             in
             let%bind () = check_native_goal_plan t native_goals in
             let%bind () =
               persist_transition
                 ~explicit_goal_holds:(Native_goal_plan.fresh_holds native_goals)
                 ?run_preparation
                 ~check_before_commit:(fun () ->
                   let%bind () =
                     Option.value_map
                       borrow.lifecycle_owner
                       ~default:(Ok ())
                       ~f:(fun owner -> lifecycle_event_effect t borrow owner)
                   in
                   let%bind () =
                     Option.value_map
                       goal_runtime_acknowledgement
                       ~default:(Ok ())
                       ~f:(fun ack ->
                         Goal_runtime_acknowledgement.check
                           ack
                           ~actor:t
                           ~candidate:prepared)
                   in
                   let%bind () =
                     check_callback_queue_source t ~manager ~metadata:queue_metadata
                   in
                   let%bind () = check_creator_custody t schedule_custody_installation in
                   check_native_goal_plan t native_goals)
                 t
                 prepared
             in
             install_committed_transition
               ~explicit_goal_holds:(Native_goal_plan.fresh_holds native_goals)
               ?goal_runtime_acknowledgement
               ?run_preparation
               ~job_custody
               ?schedule_custody_installation
               ~queue_custody_installation:
                 (Queue_custody_installation.Inventory inventory)
               ?initialization_acknowledgement
               t
               prepared;
             (* Installed loans are already actual custody. Later factual or
                publication failure must not retire them as speculative. *)
             acknowledged := true;
             borrow.committed <- true;
             Option.iter
               completion_plan
               ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
             install_callback_goal_control t borrow control;
             Option.iter
               (Option.bind borrow.lifecycle_owner ~f:Lifecycle_callback_owner.initial)
               ~f:(fun scope ->
                 scope.jobs
                 <- List.filter_map job_deltas ~f:(function
                      | Session_delta.Job_changed job -> Some job
                      | _ -> None)
                    @ scope.jobs;
                 scope.Held_authored_start.phase <- Completed borrow.receipt.context.id);
             Option.iter legacy_scope ~f:(fun scope ->
               scope.Callback_scope.committed_checkpoint <- Some prepared.state.moderator);
             acknowledge ();
             install_native_goal_plan t native_goals;
             publish_committed_transition t prepared;
             Ok ())))
;;

module Callback_retirement = struct
  type actor = t
  type t = Callback_retirement_data.t

  (* Terminal facts are frozen before closing Run actions or retiring execution.
   This owner is deliberately not consulted by any admission/currentness lookup. *)
  let select (t : actor) borrow exit =
    let open Result.Let_syntax in
    match borrow.terminal_selection with
    | Some selected -> Ok selected
    | None ->
      let%bind () =
        if
          Option.exists t.queued_event_borrow ~f:(phys_equal borrow)
          && t.idle_moderator_borrowed
        then
          Extension_invariants.owner
            ~session_id:t.state.identity.session_id
            ~generation:t.state.identity.generation
            borrow.receipt.context.session_id
            borrow.receipt.context.generation
        else Error (error Conflict "ended callback no longer owns its actual borrow")
      in
      let%bind terminal =
        match borrow.committed, borrow.retirement_reason, borrow.stop_retirement with
        | _, _, Some _ | true, _, None | false, Some _, None -> Ok None
        | false, None, None ->
          (if Queued_callback_exit.interrupted exit || borrow.cancel_requested
           then
             Agent_protocol.Moderator_execution.interrupt
               borrow.receipt
               ~reason:"queued moderator handler interrupted before checkpoint commit"
           else
             Agent_protocol.Moderator_execution.fail
               borrow.receipt
               { code = "event.handler_failed"
               ; message =
                   "queued moderator handler exited without committing its checkpoint"
               ; retryable = false
               ; details = `Null
               })
          |> Result.map ~f:Option.some
      in
      let children =
        List.filter t.invocation_executions ~f:(event_execution_owned_by borrow)
      in
      let%bind children =
        List.map children ~f:(fun execution ->
          Agent_protocol.Invocation.cancel
            execution.dispatched
            ~reason:"event exited before recording its native outcome")
        |> Result.all
      in
      let permissions, permission_deltas, _ =
        cleanup_invocation_permissions
          t
          (List.map children ~f:(fun invocation ->
             invocation.Agent_protocol.Invocation.context.id))
      in
      let%bind permissions =
        List.map permissions ~f:(fun cancelled ->
          let%map previous =
            Result.of_option
              (List.find t.state.permissions ~f:(fun previous ->
                 Agent_protocol.Id.Permission.equal
                   previous.id
                   cancelled.Agent_protocol.Permission.id))
              ~error:
                (error Conflict "ended callback permission disappeared before selection")
          in
          previous, cancelled)
        |> Result.all
      in
      let constructor = constructor_scope_of_borrow t borrow in
      let selected =
        Callback_retirement_data.
          { issuing_actor = t.initialization_owner
          ; domain = t.runtime_source_domain
          ; executing = borrow.receipt
          ; exit
          ; terminal
          ; run_scope = Option.map borrow.run_actions ~f:Run_action_service.scope
          ; sample = Option.map terminal ~f:(fun _ -> snd (completion_clock_pair t))
          ; constructor
          ; constructor_basis =
              Option.map constructor ~f:(fun constructor ->
                Initialization_scope_data.Acknowledged.apply
                  constructor.acknowledged
                  constructor.expected)
          ; source =
              Option.bind t.legacy_callback_scope ~f:(fun scope ->
                Option.some_if (phys_equal scope.borrow borrow) scope.source)
          ; children
          ; permissions
          ; lifecycle =
              List.find_map permission_deltas ~f:(function
                | Session_delta.Lifecycle_changed lifecycle ->
                  Some (t.state.lifecycle, lifecycle)
                | _ -> None)
          ; attempt = None
          }
      in
      Callback_completion_data.record_selection borrow.completion selected;
      borrow.terminal_selection <- Some selected;
      Ok selected
  ;;

  let check (t : actor) borrow (selected : t) =
    let open Result.Let_syntax in
    let%bind () =
      if
        Int.equal selected.domain (Stdlib.Domain.self () :> int)
        && phys_equal selected.issuing_actor t.initialization_owner
        && Option.exists t.queued_event_borrow ~f:(phys_equal borrow)
        && Option.exists borrow.terminal_selection ~f:(phys_equal selected)
        && t.idle_moderator_borrowed
        && Agent_protocol.Moderator_execution.equal selected.executing borrow.receipt
      then
        Extension_invariants.owner
          ~session_id:t.state.identity.session_id
          ~generation:t.state.identity.generation
          selected.executing.context.session_id
          selected.executing.context.generation
      else Error (error Conflict "ended callback factual owner changed")
    in
    let%bind () =
      Option.value_map selected.source ~default:(Ok ()) ~f:(fun source ->
        let%bind _, current = Moderator_source_installation.capture t.state in
        if Agent_protocol.Run_source.equal source current
        then Ok ()
        else Error (error Conflict "ended callback source installation changed"))
    in
    let%bind () =
      Option.value_map (goal_runtime_of_borrow borrow) ~default:(Ok ()) ~f:(fun scope ->
        let preparation = scope.Goal_continuation.continuation.binding.preparation in
        let%bind () =
          if
            Int.equal preparation.domain (Stdlib.Domain.self () :> int)
            && phys_equal scope.issuing_actor t.inference_owner_identity
            && Run_preparation.Custody.belongs_to
                 (Goal_continuation.custody preparation)
                 ~owner:t.run_preparation_owner
          then Ok ()
          else
            Error (error Conflict "ended Goal callback belongs to another actual owner")
        in
        (* The same closed owner/source, not whichever Manager is installed now.
         Owner retirement may already have detached its Manager and worker. *)
        Runtime_source_preparation.validate_target
          scope.continuation.binding.source
          t.state)
    in
    match selected.constructor, selected.constructor_basis with
    | None, None -> Ok ()
    | Some constructor, Some expected ->
      let%bind () = validate_initialization_owner t constructor in
      let%bind () =
        match constructor.callback, constructor_scope_of_borrow t borrow with
        | Claimed id, Some actual
          when phys_equal actual constructor
               && Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id
          -> Ok ()
        | (Unclaimed | Claimed _ | Settled _), (Some _ | None) ->
          Error (error Conflict "constructor no longer owns its selected failed receipt")
      in
      (* Factual projection only. The live Init slot and original execution
       permission may already be retired; neither is recreated or checked. *)
      validate_initialization_projection expected t.state
    | None, Some _ | Some _, None ->
      Error (error Invalid_state "ended constructor has no exact factual basis")
  ;;

  let check_retry (selected : t) =
    match selected.attempt with
    | None -> Ok ()
    | Some attempt ->
      (match
         ( Session_commit_observation.progress attempt.observation
         , Session_commit_observation.outcome attempt.observation )
       with
       | Unobserved, Not_called | Before_writer, (Returned (Error _) | Raised _) -> Ok ()
       | ( (Unobserved | Writer_entered _ | Journal_acknowledged _)
         , Returned (Error failure) ) -> Error failure
       | (Unobserved | Writer_entered _ | Journal_acknowledged _), Raised (exn, backtrace)
         -> Exn.raise_with_original_backtrace exn backtrace
       | ( (Unobserved | Before_writer | Writer_entered _ | Journal_acknowledged _)
         , (Not_called | In_progress | Returned (Ok ())) ) ->
         Error (error Conflict "ended callback persistence outcome remains unresolved"))
  ;;

  (* A retained constructor Job settles before its ended callback. This plan
     advances only the same owner's acknowledged factual projection; it cannot
     turn an uncertain callback writer into absence or renew an Init scope. *)
  module Constructor_job_acknowledgement = struct
    type t = Constructor_model_data.callback_advance

    let check_selection = check

    let check (t : t) ~(actor : actor) ~candidate =
      let open Result.Let_syntax in
      let%bind () = check_selection actor t.borrow t.selection in
      let%bind () = check_retry t.selection in
      let%bind () =
        Initialization_scope_data.Acknowledgement.check_basis t.acknowledgement
      in
      if
        phys_equal t.previous actor.state
        && phys_equal t.candidate candidate
        && Option.equal phys_equal t.selection.constructor_basis t.basis
        && Option.equal phys_equal t.selection.attempt t.attempt
        && Option.exists t.selection.constructor ~f:(phys_equal t.acknowledgement.scope)
      then Ok ()
      else Error (error Conflict "constructor Job ACK changed its ended callback basis")
    ;;

    (* The real Job retirement planner alone supplies its already validated
       SAME Init acknowledgement and complete selected Job candidate. No IDs or
       mutable-current-State allowlist can manufacture this physical relation. *)
    let prepare (actor : actor) ~acknowledgement ~candidate =
      let open Result.Let_syntax in
      match actor.queued_event_borrow with
      | Some borrow ->
        (match borrow.terminal_selection with
         | Some selection
           when Option.exists
                  selection.constructor
                  ~f:
                    (phys_equal
                       acknowledgement.Initialization_scope_data.Acknowledgement.scope) ->
           let plan : t =
             { borrow
             ; selection
             ; basis = selection.constructor_basis
             ; attempt = selection.attempt
             ; previous = actor.state
             ; candidate
             ; acknowledgement
             }
           in
           let%map () = check plan ~actor ~candidate in
           Some plan
         | Some _ | None -> Ok None)
      | None -> Ok None
    ;;

    (* Call in the same nonyielding installed suffix AFTER the actual State and
       existing Init ACK assignments. All expected failures were checked before
       writer entry. A foreign installation is an internal invariant failure. *)
    let install (t : t) ~(actor : actor) =
      Constructor_model_custody.install_callback_advance actor t
    ;;
  end

  let prepare (t : actor) (selected : t) terminal =
    let open Result.Let_syntax in
    let%bind children =
      List.map selected.children ~f:(fun cancelled ->
        let%bind current =
          Result.of_option
            (List.find t.state.invocations ~f:(fun current ->
               Agent_protocol.Id.Invocation.equal current.context.id cancelled.context.id))
            ~error:(error Conflict "ended callback child invocation disappeared")
        in
        let%bind () =
          if Agent_protocol.Invocation.equal_context current.context cancelled.context
          then Ok ()
          else Error (error Conflict "ended callback child invocation identity changed")
        in
        match current.status with
        | Resolved _ | Published _ -> Ok None
        | Admitted | Dispatching ->
          let%map () =
            Agent_protocol.Invocation.validate_transition
              ~previous:(Some current)
              cancelled
          in
          Some (Session_delta.Invocation_changed cancelled))
      |> Result.all
      |> Result.map ~f:List.filter_opt
    in
    let%bind permissions =
      List.map selected.permissions ~f:(fun (previous, cancelled) ->
        let%bind current =
          Result.of_option
            (List.find t.state.permissions ~f:(fun current ->
               Agent_protocol.Id.Permission.equal current.id previous.id))
            ~error:(error Conflict "ended callback permission disappeared")
        in
        match current.state with
        | Approved | Denied | Expired | Cancelled -> Ok None
        | Pending ->
          if
            Sexp.equal
              (Agent_protocol.Permission.sexp_of_t previous)
              (Agent_protocol.Permission.sexp_of_t current)
          then Ok (Some cancelled)
          else Error (error Conflict "ended callback pending permission changed"))
      |> Result.all
      |> Result.map ~f:List.filter_opt
    in
    let lifecycle =
      Option.bind selected.lifecycle ~f:(fun (previous, next) ->
        Option.some_if
          (Sexp.equal
             (Session_state.Lifecycle.sexp_of_t previous)
             (Session_state.Lifecycle.sexp_of_t t.state.lifecycle))
          next)
    in
    let%bind run_change =
      match selected.run_scope, selected.sample with
      | None, _ -> Ok []
      | Some scope, Some sample ->
        Run_transition.fail_callback
          t.state
          ~scope
          ~executing:selected.executing
          ~completed:terminal
          ~now:(Recurrence_runtime.Completion.wall sample)
      | Some _, None ->
        Error (error Invalid_state "ended Run callback has no selected completion sample")
    in
    let delta =
      Session_delta.Batch
        (children
         @ List.map permissions ~f:(fun permission ->
           Session_delta.Permission_changed permission)
         @ Option.to_list
             (Option.map lifecycle ~f:(fun lifecycle ->
                Session_delta.Lifecycle_changed lifecycle))
         @ [ Session_delta.Moderator_execution_changed terminal ]
         @ run_change)
    in
    let payloads =
      List.map permissions ~f:(fun permission ->
        Agent_protocol.Event.Durable.Payload.Permission_resolved permission)
      @ Option.to_list
          (Option.map lifecycle ~f:(fun lifecycle ->
             Agent_protocol.Event.Durable.Payload.Session_state_changed
               { desired_state = lifecycle.desired; observed_state = lifecycle.observed }))
    in
    let%map prepared =
      prepare_transition ?completion_sample:selected.sample t ~delta ~payloads
    in
    prepared, permissions
  ;;

  let release (t : actor) borrow delegated_acknowledgement ~completion_attempt =
    let selection = borrow.terminal_selection in
    Option.iter borrow.terminal_selection ~f:(fun selected ->
      let permissions =
        List.filter t.state.permissions ~f:(fun permission ->
          (not (Agent_protocol.Permission.equal_state permission.state Pending))
          && List.exists selected.permissions ~f:(fun (previous, _) ->
            Agent_protocol.Id.Permission.equal permission.id previous.id))
      in
      resolve_cleaned_permission_waiters t permissions);
    Option.iter
      (Queued_agent_admission.admission borrow.agent_admission)
      ~f:retire_agent_admission;
    (match t.legacy_callback_scope with
     | Some scope when phys_equal scope.borrow borrow ->
       (match scope.custody with
        | Unavailable -> ()
        | Admitted admission -> retire_agent_admission admission);
       t.legacy_callback_scope <- None
     | None | Some _ -> ());
    t.queued_event_borrow <- None;
    t.invocation_executions
    <- List.filter t.invocation_executions ~f:(fun execution ->
         not (event_execution_owned_by borrow execution));
    t.idle_moderator_borrowed <- false;
    borrow.terminal_selection <- None;
    (* All existing retirement cleanup succeeded. Remember only this exact
       terminal ACK; wrapper join remains a separate factual obligation. *)
    Option.iter
      delegated_acknowledgement
      ~f:Delegated_policy_claim_state.Callback_acknowledgement.install;
    Option.iter selection ~f:(fun selected ->
      Callback_completion_data.record_release
        borrow.completion
        ~attempt:completion_attempt
        selected)
  ;;

  let commit (t : actor) borrow selected terminal ~completion_attempt =
    let open Result.Let_syntax in
    let%bind delegated_acknowledgement =
      Delegated_policy_custody.prepare_callback_ack t borrow
    in
    let%bind () = check_retry selected in
    let%bind () = check t borrow selected in
    let%bind prepared, _permissions = prepare t selected terminal in
    let%bind completion_plan = prepare_completion_plan t prepared selected.sample in
    let%bind goal_acknowledgement =
      Option.value_map (goal_runtime_of_borrow borrow) ~default:(Ok None) ~f:(fun scope ->
        Goal_runtime_acknowledgement.prepare_after_basis
          t
          scope
          ~candidate:prepared
          ~callback_advance:None
        |> Result.map ~f:Option.some)
    in
    let initialization_acknowledgement =
      Option.map selected.constructor ~f:(fun constructor ->
        let acknowledgement =
          Initialization_scope_data.Acknowledgement.prepare
            ~callback:(Settled borrow.receipt.context.id)
            constructor
            prepared.state
        in
        (* This exact selected terminal candidate owns its cancelled permissions
         and producer settlement. Advance those factual projections only at its
         ACK; this never makes the closed constructor executable again. *)
        { acknowledgement with
          incoming =
            { acknowledgement.incoming with
              permission_basis =
                Initialization_scope_data.Acknowledged.Permission_basis.capture
                  prepared.state
            ; goal_catalog = prepared.state.goal_catalog
            }
        })
    in
    let attempt =
      Callback_retirement_data.Attempt.
        { previous = t.state
        ; candidate = prepared
        ; observation =
            Session_commit_observation.Owner.create ~previous:t.state ~candidate:prepared
        }
    in
    selected.attempt <- Some attempt;
    Eio.Cancel.protect (fun () ->
      let%bind () = check t borrow selected in
      let%bind () =
        Delegated_policy_custody.check_callback_ack delegated_acknowledgement
      in
      let%bind () =
        Option.value_map
          initialization_acknowledgement
          ~default:(Ok ())
          ~f:Initialization_scope_data.Acknowledgement.check_basis
      in
      let check_before_commit () =
        let%bind () = check t borrow selected in
        let%bind () =
          Delegated_policy_custody.check_callback_ack delegated_acknowledgement
        in
        if phys_equal attempt.previous t.state && phys_equal attempt.candidate prepared
        then
          Option.value_map
            initialization_acknowledgement
            ~default:(Ok ())
            ~f:Initialization_scope_data.Acknowledgement.check_basis
        else Error (error Conflict "ended callback candidate changed before its writer")
      in
      let%bind () =
        persist_transition
          ~commit_observation:attempt.observation
          ~check_before_commit
          t
          prepared
      in
      (* Exact successful persistence, State and factual ACK precede release.
       No external publication can leave this already installed borrow held. *)
      install_committed_transition
        ?goal_runtime_acknowledgement:goal_acknowledgement
        ?initialization_acknowledgement
        t
        prepared;
      let%bind () =
        Delegated_policy_custody.check_callback_ack delegated_acknowledgement
      in
      release t borrow delegated_acknowledgement ~completion_attempt;
      Option.iter
        completion_plan
        ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
      publish_committed_transition t prepared;
      Ok ())
  ;;

  let finish_internal (t : actor) borrow exit ~completion_attempt =
    let open Result.Let_syntax in
    let%bind selected = select t borrow exit in
    Option.iter borrow.run_actions ~f:Run_action_service.close;
    borrow.run_actions <- None;
    borrow.callback_active <- false;
    Atomic.set borrow.authority_live false;
    abort_staged_work t ~owner:(Moderator_event borrow.receipt.context.id);
    borrow.cancel <- None;
    List.iter t.invocation_executions ~f:(fun execution ->
      if event_execution_owned_by borrow execution
      then (
        execution.accepts_children <- false;
        Atomic.set execution.authority_live false;
        abort_staged_work t ~owner:(Invocation execution.dispatched.context.id)));
    let%bind () =
      Option.value_map
        selected.constructor
        ~default:(Ok ())
        ~f:(Constructor_model_custody.before_callback_terminal t)
    in
    match selected.terminal with
    | Some terminal -> commit t borrow selected terminal ~completion_attempt
    | None ->
      let%bind () =
        match borrow.stop_retirement with
        | Some terminal ->
          if
            List.exists
              t.state.moderator_executions
              ~f:(Agent_protocol.Moderator_execution.equal terminal)
          then Ok ()
          else Error (error Conflict "stopped constructor receipt changed before release")
        | None ->
          if borrow.committed || Option.is_some borrow.retirement_reason
          then Ok ()
          else Error (error Conflict "ended callback has no installed acknowledgement")
      in
      let%bind delegated_acknowledgement =
        Delegated_policy_custody.prepare_callback_ack t borrow
      in
      let%bind () =
        Delegated_policy_custody.check_callback_ack delegated_acknowledgement
      in
      release t borrow delegated_acknowledgement ~completion_attempt;
      Ok ()
  ;;

  let finish ?completion_attempt (t : actor) borrow exit =
    let completion_attempt =
      Option.value_or_thunk
        completion_attempt
        ~default:Callback_completion_data.Attempt.create
    in
    let outcome =
      Callback_completion_data.Outcome.capture (fun () ->
        finish_internal t borrow exit ~completion_attempt)
    in
    (* Foreign/stale legacy calls retain their existing return behavior. Only
       the original immutable Actor/domain may record this borrow's facts. *)
    if
      Callback_completion_data.belongs_to
        borrow.completion
        ~issuing_actor:t.initialization_owner
        ~domain:t.runtime_source_domain
    then
      Callback_completion_data.record_finish
        borrow.completion
        ~attempt:completion_attempt
        outcome;
    Callback_completion_data.Outcome.resume outcome
  ;;

  let retry_retained (t : actor) =
    match t.queued_event_borrow with
    | Some borrow when Option.is_some borrow.terminal_selection ->
      finish t borrow Queued_callback_exit.Returned
    | Some _ | None -> Ok ()
  ;;
end

let drain_delegated_policy_claim t =
  let module Capture = Delegated_policy_claim_state in
  let open Result.Let_syntax in
  match t.delegated_policy_claim with
  | None -> Ok ()
  | Some capture ->
    let%bind () = Delegated_policy_custody.check_capture t capture in
    let%bind () =
      match Capture.extent capture.state with
      | Not_started | Not_entered | Entered ->
        Error (error Conflict "delegated policy wrapper has not joined")
      | Joined_without_entry | Joined_after_entry -> Ok ()
    in
    let release () =
      match Capture.phase capture.state with
      | Waiting | Prepared _ | Released -> Capture.release_no_writer capture.state
      | Callback_acknowledged attempt ->
        Capture.release_activated capture.state ~borrow:(Capture.Attempt.borrow attempt)
      | Activated _ ->
        Error (error Conflict "delegated policy callback has no terminal ACK")
    in
    let%bind () =
      match Capture.phase capture.state with
      | Activated attempt ->
        let borrow = Capture.Attempt.borrow attempt in
        (match Capture.extent capture.state with
         | Joined_without_entry ->
           (* Actual claim ACK, but the real wrapper joined without entering its
              callback. This exact borrow alone owns the interrupted receipt. *)
           Callback_retirement.finish t borrow Queued_callback_exit.Interrupted
         | Joined_after_entry ->
           if Option.is_some borrow.terminal_selection
           then Callback_retirement.retry_retained t
           else
             Error
               (error
                  Invalid_state
                  "joined delegated callback lost its terminal selection")
         | Not_started | Not_entered | Entered ->
           Error (error Conflict "delegated policy wrapper has not joined"))
      | Waiting | Prepared _ | Callback_acknowledged _ | Released -> Ok ()
    in
    let%bind () = release () in
    if Option.exists t.delegated_policy_claim ~f:(phys_equal capture)
    then (
      t.delegated_policy_claim <- None;
      Ok ())
    else Error (error Conflict "delegated policy cleanup owner was displaced")
;;

let observation_owner_available t operation_id =
  match operation_id with
  | Some operation_id -> Result.map (running_operation t operation_id) ~f:ignore
  | None ->
    if idle_moderator_eligible t
    then Ok ()
    else Error (error Conflict "session is not available for idle observation")
;;

let validate_installed_observer t observer =
  let open Result.Let_syntax in
  let%bind installed = Runtime_builder.moderator_snapshot_observer t.state.moderator in
  match installed, observer with
  | Some installed, Some observer
    when Agent_protocol.Invocation.equal_observer installed observer -> Ok ()
  | _ -> Error (error Conflict "observation source is not the installed moderator")
;;

let claim_moderator_observation t operation_id invocation_id =
  let open Result.Let_syntax in
  let%bind () = require_selected_execution t in
  let%bind () = observation_owner_available t operation_id in
  let%bind moderator_halted =
    Runtime_builder.moderator_snapshot_is_halted t.state.moderator
  in
  let%bind () =
    match
      t.idle_moderator_borrowed, t.moderator_borrow, t.state.halted || moderator_halted
    with
    | false, None, false -> Ok ()
    | _ -> Error (error Conflict "moderator is borrowed or halted")
  in
  let%bind invocation =
    match
      List.find t.state.invocations ~f:(fun invocation ->
        Agent_protocol.Id.Invocation.equal invocation.context.id invocation_id)
    with
    | Some invocation -> Ok invocation
    | None -> Error (error Invalid_state "observation invocation is not retained")
  in
  let%bind () =
    validate_installed_observer
      t
      (Option.map invocation.observation ~f:(fun observation -> observation.observer))
  in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      invocation.context.session_id
      invocation.context.generation
  in
  let%bind () =
    match invocation.context.parent_invocation with
    | Some parent
      when List.exists t.invocation_executions ~f:(fun execution ->
             Agent_protocol.Id.Invocation.equal execution.dispatched.context.id parent) ->
      Error (error Conflict "observation parent is still executing")
    | _ -> Ok ()
  in
  let revision = t.state.counters.revision in
  let%bind source = observation_source t in
  let key = Invocation_intent invocation.context.id in
  let entry =
    List.find t.intent_agent_custody ~f:(fun entry ->
      equal_agent_intent_key entry.key key)
  in
  let%bind original =
    match Option.bind entry ~f:(fun entry -> entry.observation) with
    | Some observation -> Ok observation
    | None ->
      let%bind observation =
        Observation_continuation.stage_completed
          invocation
          ~source
          ~parent:Unavailable
          ~policy_source:Unknown
      in
      Result.of_option
        observation
        ~error:(error Internal_error "selected observation has no completed result")
  in
  let%bind observing = Agent_protocol.Invocation.claim_observation invocation in
  let%bind observation =
    Observation_continuation.stage_claim original ~source ~previous:invocation ~observing
  in
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () ->
      if not !acknowledged then Observation_continuation.retire observation)
    ~f:(fun () ->
      let%bind prepared =
        prepare_transition
          t
          ~delta:(Session_delta.Invocation_changed observing)
          ~payloads:[]
      in
      let%bind current_source = observation_source t in
      let%bind () = observation_owner_available t operation_id in
      let%bind () =
        if
          Int64.equal revision t.state.counters.revision
          && Option.equal Agent_protocol.Run_source.equal source current_source
          && List.exists
               t.state.invocations
               ~f:(Agent_protocol.Invocation.equal invocation)
          && Option.equal
               phys_equal
               entry
               (List.find t.intent_agent_custody ~f:(fun entry ->
                  equal_agent_intent_key entry.key key))
        then Ok ()
        else Error (error Conflict "observation claim basis changed before commit")
      in
      let%bind () = persist_transition t prepared in
      install_committed_transition t prepared;
      (* Only the observation component is consumed. The same result's handler
         follow-up and accepted native Goal command have independent lifetimes. *)
      t.intent_agent_custody
      <- List.filter_map t.intent_agent_custody ~f:(fun current ->
           if equal_agent_intent_key current.key key
           then (
             Option.iter current.observation ~f:Observation_continuation.retire;
             if
               Observation_follow_up.pending invocation
               || Option.is_some current.native_goal
             then Some { current with observation = None }
             else None)
           else Some current);
      let borrow =
        { operation_id
        ; job_scope = None
        ; kind = Observation
        ; observation = Some observation
        ; policy_source = Observation_continuation.policy_source observation
        ; invocation = observing
        ; committed = false
        ; accepts_children = Option.is_some operation_id
        ; callback_finished = false
        ; native_goals = Goal_native_actions.create ()
        ; authority_live = Atomic.make true
        ; cancel = None
        ; cancel_requested = false
        }
      in
      t.moderator_borrow <- Some borrow;
      t.idle_moderator_borrowed <- Option.is_none operation_id;
      acknowledged := true;
      publish_committed_transition t prepared;
      Ok borrow)
;;

let claim_next_moderator_observation t operation_id observer =
  let open Result.Let_syntax in
  let%bind () = observation_owner_available t operation_id in
  let%bind () = validate_installed_observer t (Some observer) in
  let%bind moderator_halted =
    Runtime_builder.moderator_snapshot_is_halted t.state.moderator
  in
  let%bind () =
    match t.idle_moderator_borrowed, t.moderator_borrow with
    | false, None -> Ok ()
    | _ -> Error (error Conflict "moderator is already borrowed")
  in
  let eligible (invocation : Agent_protocol.Invocation.t) =
    (not (t.state.halted || moderator_halted))
    && invocation.context.generation = t.state.identity.generation
    && Agent_protocol.Id.Session.equal
         invocation.context.session_id
         t.state.identity.session_id
    && (match invocation.observation, invocation.status with
        | Some { status = Awaiting; observer = owner }, (Resolved _ | Published _) ->
          Agent_protocol.Invocation.equal_observer owner observer
        | _ -> false)
    && not
         (Option.exists invocation.context.parent_invocation ~f:(fun parent ->
            List.exists t.invocation_executions ~f:(fun execution ->
              Agent_protocol.Id.Invocation.equal execution.dispatched.context.id parent)))
  in
  let compare (a : Agent_protocol.Invocation.t) (b : Agent_protocol.Invocation.t) =
    match Agent_protocol.Timestamp.compare a.context.created_at b.context.created_at with
    | 0 -> Agent_protocol.Id.Invocation.compare a.context.id b.context.id
    | order -> order
  in
  let selected =
    List.fold t.state.invocations ~init:None ~f:(fun selected candidate ->
      match eligible candidate, selected with
      | false, _ -> selected
      | true, None -> Some candidate
      | true, Some previous when compare candidate previous < 0 -> Some candidate
      | true, Some _ -> selected)
  in
  match selected with
  | None -> Ok None
  | Some invocation ->
    let%bind () = require_selected_execution t in
    claim_moderator_observation t operation_id invocation.context.id
    |> Result.map ~f:Option.some
;;

let claim_job_moderator t scope invocation captured =
  let open Result.Let_syntax in
  let%bind () = job_scope_can_execute t scope in
  let%bind () =
    match t.idle_moderator_borrowed, t.moderator_borrow with
    | false, None -> Ok ()
    | _ -> Error (error Conflict "moderator is already borrowed")
  in
  let%bind () = active_script_parent t ~owns:(job_execution_owned_by scope) invocation in
  let%bind checkpoint = prepare_moderator_invocation_checkpoint t captured in
  let%bind origin =
    invocation_origin t invocation ~fallback:(fun () -> Ok scope.job.inference_origin)
  in
  let%bind boundary = policy_job_boundary t scope in
  let%bind invocation, admission, policy_source =
    invocation_admission_deltas t invocation ~origin ~boundary
  in
  let%bind dispatched = Agent_protocol.Invocation.dispatch invocation in
  let%bind _ =
    transition
      t
      ~delta:(Session_delta.Batch (admission @ [ Invocation_changed dispatched ]))
      ~payloads:[]
  in
  let borrow =
    { operation_id = None
    ; job_scope = Some scope
    ; kind = Invocation checkpoint
    ; observation = None
    ; policy_source
    ; invocation = dispatched
    ; committed = false
    ; accepts_children = true
    ; callback_finished = false
    ; native_goals = Goal_native_actions.create ()
    ; authority_live = Atomic.make true
    ; cancel = None
    ; cancel_requested = false
    }
  in
  t.moderator_borrow <- Some borrow;
  t.idle_moderator_borrowed <- true;
  Ok borrow
;;

let validate_moderator_borrow t borrow =
  match t.moderator_borrow with
  | Some current when phys_equal current borrow ->
    let open Result.Let_syntax in
    let%bind () =
      match borrow.job_scope, borrow.operation_id with
      | Some scope, None -> Result.map (job_scope_current t scope) ~f:ignore
      | None, Some operation_id -> Result.map (current_operation t operation_id) ~f:ignore
      | None, None
        when t.idle_moderator_borrowed && Option.is_none t.state.active_operation -> Ok ()
      | _ -> Error (error Conflict "moderator no longer owns its execution scope")
    in
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      borrow.invocation.context.session_id
      borrow.invocation.context.generation
  | _ -> Error (error Conflict "moderator borrow is no longer owned by this callback")
;;

let invocation_execution_owned_by borrow (execution : invocation_execution) =
  match execution.owner with
  | Invocation_moderator owner -> phys_equal owner borrow
  | Foreground _ | Event_moderator _ | Background_job _ -> false
;;

let background_owner_active t owner =
  let open Result.Let_syntax in
  let moderator (borrow : moderator_borrow) =
    let%bind () = validate_moderator_borrow t borrow in
    match borrow.callback_finished || borrow.committed || borrow.cancel_requested with
    | true -> Error (error Conflict "background launch owner has finished")
    | false ->
      (match borrow.job_scope, borrow.operation_id with
       | Some scope, None -> job_scope_can_execute t scope
       | None, Some id -> Result.map (running_operation t id) ~f:ignore
       | None, None ->
         (match
            t.state.lifecycle.desired, t.state.lifecycle.observed, t.state.failure
          with
          | Running, Idle, None when not t.state.halted -> Ok ()
          | _ -> Error (error Conflict "background launch owner is not running"))
       | Some _, Some _ -> Error (error Conflict "invalid background launch scope"))
  in
  let event borrow =
    let%bind () = queued_event_can_commit t borrow in
    match borrow.retirement_reason with
    | None -> Ok ()
    | Some _ -> Error (error Conflict "event retirement cannot launch background work")
  in
  match owner with
  | Agent_protocol.Job.Moderator_event id ->
    (match t.queued_event_borrow with
     | Some borrow
       when Agent_protocol.Id.Moderator_execution.equal borrow.receipt.context.id id ->
       event borrow
     | _ -> Error (error Conflict "background launch event is not executing"))
  | Invocation id ->
    (match
       List.find t.invocation_executions ~f:(fun execution ->
         execution.accepts_children
         && Agent_protocol.Id.Invocation.equal execution.dispatched.context.id id)
     with
     | Some execution ->
       (match execution.owner with
        | Foreground id -> Result.map (running_operation t id) ~f:ignore
        | Background_job scope -> job_scope_can_execute t scope
        | Invocation_moderator borrow -> moderator borrow
        | Event_moderator borrow -> event borrow)
     | None ->
       (match t.moderator_borrow with
        | Some borrow
          when Agent_protocol.Id.Invocation.equal borrow.invocation.context.id id ->
          moderator borrow
        | _ -> Error (error Conflict "background launch invocation is not executing")))
;;

let subscription_owner_active t owner source =
  let open Result.Let_syntax in
  let%bind () = background_owner_active t owner in
  let%bind () = validate_installed_observer t (Some source) in
  match owner with
  | Agent_protocol.Job.Invocation id ->
    (match t.moderator_borrow with
     | Some borrow when Agent_protocol.Id.Invocation.equal borrow.invocation.context.id id
       ->
       Ok
         (match borrow.kind with
          | Invocation _ -> Some borrow.invocation
          | Observation -> None)
     | _ ->
       Error
         (error Permission_denied "subscription requires a moderator invocation borrow"))
  | Moderator_event id ->
    (match t.queued_event_borrow with
     | Some borrow
       when Agent_protocol.Id.Moderator_execution.equal borrow.receipt.context.id id
            && Agent_protocol.Invocation.equal_observer
                 borrow.receipt.context.source
                 source -> Ok None
     | _ ->
       Error (error Permission_denied "subscription requires its moderator event borrow"))
;;

let schedule_owned t source (schedule : Agent_protocol.Schedule.t) =
  let open Result.Let_syntax in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      schedule.session_id
      schedule.generation
  in
  match schedule.ownership with
  | Some ownership when Agent_protocol.Invocation.equal_observer ownership.source source
    -> Ok ()
  | _ ->
    Error
      (error
         Permission_denied
         "schedule belongs to a different or unbound moderator source")
;;

let provisional_schedule t owner id =
  match Staged_schedules.find t.staged_schedules ~owner ~id with
  | Some value -> Some value
  | None ->
    List.find t.state.schedules ~f:(fun value ->
      Agent_protocol.Id.Schedule.equal value.id id)
;;

let delay_within_limit ~created_at ~due_at max_delay_ms =
  let ns = Agent_protocol.Timestamp.diff_ns due_at created_at in
  (* Compare rounded-up milliseconds, without converting the policy ceiling to
     a span or overflowing the difference between valid timestamp endpoints. *)
  let milliseconds =
    Int64.((ns / 1_000_000L) + if ns % 1_000_000L = 0L then 0L else 1L)
  in
  Int64.(ns >= 0L && milliseconds <= of_int max_delay_ms)
;;

let stage_schedule_mutation_internal
      t
      owner
      source
      previous
      (next : Agent_protocol.Schedule.t)
  =
  let open Result.Let_syntax in
  let%bind _ = subscription_owner_active t owner source in
  let%bind () = schedule_owned t source next in
  let%bind () = Agent_protocol.Schedule.validate_transition ~previous next in
  let%bind () =
    match
      Option.equal
        (fun a b ->
           Jsonaf.exactly_equal
             (Agent_protocol.Schedule.to_json a)
             (Agent_protocol.Schedule.to_json b))
        previous
        (provisional_schedule t owner next.id)
    with
    | true -> Ok ()
    | false -> Error (error Conflict "schedule changed before staging")
  in
  let%bind () =
    match previous with
    | Some _ -> Ok ()
    | None ->
      let limits = t.services.schedule_limits in
      let%bind () = Staged_schedules.validate_limits limits in
      let%bind () =
        match next.ownership with
        | Some ownership
          when Agent_protocol.Job.equal_launch_owner ownership.creator owner
               && Agent_protocol.Timestamp.compare next.created_at (t.services.now ())
                  <= 0
               && delay_within_limit
                    ~created_at:next.created_at
                    ~due_at:next.next_due_at
                    limits.max_delay_ms -> Ok ()
        | _ ->
          Error
            (error
               Permission_denied
               "schedule creation has a different owner or invalid timing")
      in
      let reserved = Staged_schedules.reservations t.staged_schedules in
      let active schedule =
        match schedule.Agent_protocol.Schedule.status with
        | Scheduled | Delivering -> true
        | _ -> false
      in
      let source_active schedule =
        active schedule
        && Option.exists schedule.ownership ~f:(fun ownership ->
          Agent_protocol.Invocation.equal_observer ownership.source source)
      in
      let%bind () =
        match
          List.count t.state.schedules ~f:active + reserved < limits.max_active
          && List.count t.state.schedules ~f:source_active + reserved
             < limits.max_per_source
          && List.length t.state.schedules + reserved < limits.max_retained
        with
        | true -> Ok ()
        | false -> Error (error Resource_limit "schedule admission capacity exhausted")
      in
      Agent_protocol.Json_codec.validate_limits
        ~max_bytes:limits.max_payload_bytes
        ~max_depth:limits.max_payload_depth
        next.payload
  in
  let%map receipt = Staged_schedules.stage t.staged_schedules ~owner ~previous ~next in
  sync_extension_clock t;
  receipt
;;

let script_creator t owner observer =
  let open Result.Let_syntax in
  let%bind _, source = Moderator_source_installation.capture t.state in
  let%bind () =
    if Agent_protocol.Invocation.equal_observer source.observer observer
    then Ok ()
    else Error (error Conflict "script creator source changed before staging")
  in
  let%bind admission, origin =
    match owner with
    | Agent_protocol.Job.Moderator_event id ->
      (match t.queued_event_borrow with
       | Some borrow
         when Agent_protocol.Id.Moderator_execution.equal id borrow.receipt.context.id ->
         let%bind admission = event_agent_admission t borrow in
         let%map origin = event_inference_origin t borrow.receipt in
         admission, origin
       | Some _ | None ->
         Error (error Conflict "script creator event is no longer borrowed"))
    | Invocation id ->
      (match t.moderator_borrow with
       | Some borrow
         when Agent_protocol.Id.Invocation.equal id borrow.invocation.context.id ->
         let%map admission = moderator_agent_admission t borrow in
         admission, borrow.invocation.inference_origin
       | Some _ | None ->
         Error (error Conflict "script creator invocation is no longer borrowed"))
  in
  let%map () =
    Option.value_map admission ~default:(Ok ()) ~f:Execution_custody.Admission.check
  in
  source, admission, origin
;;

let create_script_schedule_internal t owner source delay_ms payload misfire =
  let open Result.Let_syntax in
  let%bind _ = subscription_owner_active t owner source in
  let%bind () =
    match delay_ms >= 0 && delay_ms <= t.services.schedule_limits.max_delay_ms with
    | true -> Ok ()
    | false -> Error (error Invalid_request "schedule delay exceeds host policy")
  in
  let%bind captured_source, admission, origin = script_creator t owner source in
  let%bind provenance =
    Agent_protocol.Schedule_provenance.create ~source:captured_source ~origin
  in
  let inference_provenance = Some provenance in
  let created_at = t.services.now () in
  let monotonic_created_at = t.services.monotonic_now () in
  let%bind next_due_at = Agent_protocol.Timestamp.add_ms created_at delay_ms in
  let schedule : Agent_protocol.Schedule.t =
    { id = Agent_protocol.Id.Schedule.create ()
    ; session_id = t.state.identity.session_id
    ; generation = t.state.identity.generation
    ; payload
    ; created_at
    ; next_due_at
    ; misfire
    ; status = Scheduled
    ; delivery_count = 0
    ; last_delivery_at = None
    ; inference_provenance
    ; delivery_cancellation = None
    ; ownership = Some { source; creator = owner; subscription = None }
    }
  in
  let%bind fresh =
    match t.moderator_manager, admission with
    | Some manager, Some parent ->
      Legacy_schedule_custody.Fresh.stage
        ~manager
        ~source:captured_source
        ~schedule
        ~parent
      |> Result.map ~f:Option.some
    | (Some _ | None), None | None, Some _ -> Ok None
  in
  let attached = ref false in
  Exn.protect
    ~finally:(fun () ->
      if not !attached then Option.iter fresh ~f:Legacy_schedule_custody.Fresh.discard)
    ~f:(fun () ->
      let%bind receipt = stage_schedule_mutation_internal t owner source None schedule in
      let%map () =
        Option.value_map fresh ~default:(Ok ()) ~f:(fun fresh ->
          Legacy_schedule_custody.Staged.attach
            t.staged_schedule_custody
            ~owner
            ~receipt
            ~fresh)
      in
      attached := true;
      Extension_clock.capture
        t.extension_clock
        (Schedule schedule.id)
        ~now:monotonic_created_at
        ~created_at
        ~due_at:next_due_at;
      receipt, schedule)
;;

let subscription_owned t source (subscription : Agent_protocol.Subscription.t) =
  let open Result.Let_syntax in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      subscription.context.session_id
      subscription.context.generation
  in
  match subscription.context.source with
  | Some actual when Agent_protocol.Invocation.equal_observer actual source -> Ok ()
  | _ ->
    Error
      (error
         Permission_denied
         "subscription belongs to a different or unbound moderator source")
;;

let provisional_subscription t owner id =
  match Staged_subscriptions.find t.staged_subscriptions ~owner ~id with
  | Some value -> Some value
  | None -> lookup_subscription t id
;;

let subscription_parent_job t =
  Option.bind t.moderator_borrow ~f:(fun borrow ->
    Option.map borrow.job_scope ~f:(fun scope -> scope.job.id, scope.job.attempt))
;;

let stage_subscription_mutation_internal
      ?sampled_time
      t
      owner
      source
      previous
      (next : Agent_protocol.Subscription.t)
  =
  let open Result.Let_syntax in
  let%bind originating = subscription_owner_active t owner source in
  let%bind () = subscription_owned t source next in
  let%bind () =
    match
      Option.equal
        Agent_protocol.Subscription.equal
        previous
        (provisional_subscription t owner next.context.id)
    with
    | true -> Ok ()
    | false -> Error (error Conflict "subscription changed before staging")
  in
  let%bind () = Agent_protocol.Subscription.validate_transition ~previous next in
  let now, monotonic_now =
    Option.value_or_thunk sampled_time ~default:(fun () ->
      let now = t.services.now () in
      now, t.services.monotonic_now ())
  in
  let%bind () =
    match previous with
    | Some _ -> Ok ()
    | None ->
      let%bind () =
        match originating with
        | Some invocation
          when Agent_protocol.Id.Invocation.equal
                 invocation.context.id
                 next.context.invocation_id ->
          (* Origin is established by the live borrowed invocation, not wall
             timestamp ordering across a possible clock adjustment. *)
          Ok ()
        | _ ->
          Error
            (error
               Permission_denied
               "subscription creation requires its dispatched moderator tool")
      in
      let%bind () =
        match
          Option.equal
            (fun (id, attempt) (other_id, other_attempt) ->
               Agent_protocol.Id.Job.equal id other_id && Int.equal attempt other_attempt)
            next.context.parent_job
            (subscription_parent_job t)
        with
        | true -> Ok ()
        | false ->
          Error
            (error Permission_denied "subscription has a different creating job attempt")
      in
      let limits = t.services.subscription_limits in
      let reserved = Staged_subscriptions.reservations t.staged_subscriptions in
      let active =
        List.count t.state.subscriptions ~f:(fun sub -> Option.is_none sub.result)
      in
      let%bind () =
        match
          active + reserved < limits.max_active
          && List.length t.state.subscriptions + reserved < limits.max_retained
        with
        | true -> Ok ()
        | false ->
          Error (error Resource_limit "subscription admission capacity exhausted")
      in
      (match
         Agent_protocol.Timestamp.compare next.context.created_at now <= 0
         && Agent_protocol.Timestamp.compare next.context.deadline now > 0
         && delay_within_limit
              ~created_at:next.context.created_at
              ~due_at:next.context.deadline
              limits.max_lifetime_ms
       with
       | true -> Ok ()
       | false ->
         Error (error Invalid_request "subscription lifetime exceeds host policy"))
  in
  let%bind () =
    match previous with
    | None | Some { result = Some _; _ } -> Ok ()
    | Some previous ->
      let%bind due = subscription_is_due_at t previous ~now ~monotonic_now in
      let%bind () =
        match next.result with
        | None -> Ok ()
        | Some completion ->
          let latest = subscription_terminal_time_at previous completion ~now in
          (match
             Option.exists next.completed_at ~f:(fun at ->
               Agent_protocol.Timestamp.compare at latest > 0)
           with
           | true ->
             Error (error Invalid_request "subscription completion is in the future")
           | false -> Ok ())
      in
      (match due, next.result with
       | true, Some Expired | false, (None | Some (Succeeded _ | Failed _ | Cancelled _))
         -> Ok ()
       | false, Some Expired ->
         Error (error Conflict "subscription has not reached its elapsed deadline")
       | true, _ ->
         Error (error Conflict "subscription deadline has passed; record expiry"))
  in
  let%bind () =
    match next.result, next.context.completion_schema with
    | Some (Succeeded payload), Some schema ->
      let%bind schema =
        Chatmd_shell_spec.Tool_schema.compile schema
        |> Result.map_error ~f:(fun _ ->
          error Invalid_request "invalid subscription completion schema")
      in
      Chatmd_shell_spec.Tool_schema.validate schema payload
      |> Result.map_error ~f:(fun _ ->
        error Invalid_request "subscription completion schema mismatch")
    | _ -> Ok ()
  in
  let%map receipt =
    Staged_subscriptions.stage t.staged_subscriptions ~owner ~previous ~next
  in
  sync_extension_clock t;
  receipt
;;

let create_script_subscription_internal
      t
      owner
      source
      kind
      lifetime_ms
      wake
      completion_schema
  =
  let open Result.Let_syntax in
  let%bind originating = subscription_owner_active t owner source in
  let%bind invocation =
    Result.of_option
      originating
      ~error:
        (error
           Permission_denied
           "subscription creation requires a dispatched moderator tool")
  in
  let%bind () =
    match
      lifetime_ms > 0 && lifetime_ms <= t.services.subscription_limits.max_lifetime_ms
    with
    | true -> Ok ()
    | false -> Error (error Invalid_request "subscription lifetime exceeds host policy")
  in
  let created_at = t.services.now () in
  let monotonic_created_at = t.services.monotonic_now () in
  let%bind deadline = Agent_protocol.Timestamp.add_ms created_at lifetime_ms in
  let%bind subscription =
    Agent_protocol.Subscription.create
      { id = Agent_protocol.Id.Subscription.create ()
      ; session_id = invocation.context.session_id
      ; generation = invocation.context.generation
      ; invocation_id = invocation.context.id
      ; source = Some source
      ; parent_job = subscription_parent_job t
      ; kind
      ; created_at
      ; deadline
      ; completion_schema
      ; wake
      ; ingress_capability = None
      }
  in
  let%map receipt =
    stage_subscription_mutation_internal t owner source None subscription
  in
  Extension_clock.capture
    t.extension_clock
    (Subscription subscription.context.id)
    ~now:monotonic_created_at
    ~created_at
    ~due_at:deadline;
  receipt, subscription
;;

let ingress_owned t source (value : External_ingress.t) =
  let open Result.Let_syntax in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      value.context.session_id
      value.context.generation
  in
  match Agent_protocol.Invocation.equal_observer source value.context.source with
  | true -> Ok ()
  | false ->
    Error
      (error Permission_denied "ingress registration belongs to another moderator source")
;;

let provisional_ingress t owner id =
  match Staged_ingress.find t.staged_ingress ~owner ~id with
  | Some _ as value -> value
  | None -> lookup_ingress t id
;;

let read_script_ingress_internal t owner source id =
  let open Result.Let_syntax in
  let%bind _ = subscription_owner_active t owner source in
  let%bind value =
    provisional_ingress t owner id
    |> Result.of_option
         ~error:(error Invalid_state "ingress registration is not retained")
  in
  let%map () = ingress_owned t source value in
  value
;;

let create_script_ingress_internal
      t
      owner
      source
      subscription_id
      expected_epoch
      namespace
      schema
  =
  let open Result.Let_syntax in
  let%bind _ = subscription_owner_active t owner source in
  let%bind subscription =
    provisional_subscription t owner subscription_id
    |> Result.of_option
         ~error:(error Invalid_state "ingress subscription is not retained")
  in
  let%bind () = subscription_owned t source subscription in
  let%bind () =
    match subscription.epoch = expected_epoch && Option.is_none subscription.result with
    | true -> Ok ()
    | false ->
      Error (error Conflict "ingress subscription is terminal or has a different epoch")
  in
  let%bind due = subscription_is_due t subscription in
  let%bind () =
    match due with
    | false -> Ok ()
    | true ->
      Error (error Conflict "ingress subscription has reached its elapsed deadline")
  in
  let%bind producer =
    t.state.identity.creating_principal
    |> Result.of_option
         ~error:
           (error
              Permission_denied
              "ingress registration requires a recorded creating principal")
  in
  let%bind captured_source, admission, origin = script_creator t owner source in
  let%bind inference_provenance =
    External_ingress.Provenance.create ~source:captured_source ~origin
  in
  let%bind next =
    External_ingress.create
      ~inference_provenance
      { id = Agent_protocol.Id.Capability.create ()
      ; session_id = t.state.identity.session_id
      ; generation = t.state.identity.generation
      ; subscription_id
      ; epoch = expected_epoch
      ; source
      ; producer
      ; namespace
      ; schema
      ; created_at = t.services.now ()
      ; expires_at = subscription.context.deadline
      ; limits = t.services.ingress_limits.registration
      }
      ~subscription
  in
  let%bind () =
    Staged_ingress.check_capacity
      ~limits:t.services.ingress_limits
      ~generation:t.state.identity.generation
      ~now:(t.services.now ())
      ~subscriptions:
        (t.state.subscriptions @ Staged_subscriptions.values t.staged_subscriptions)
      ~values:
        ((next :: t.state.ingress_registrations) @ Staged_ingress.values t.staged_ingress)
  in
  let%bind fresh =
    match t.moderator_manager, admission with
    | Some manager, Some parent ->
      Ingress_creator_custody.Fresh.stage
        ~manager
        ~source:captured_source
        ~registration:next
        ~parent
      |> Result.map ~f:Option.some
    | (Some _ | None), None | None, Some _ -> Ok None
  in
  let attached = ref false in
  Exn.protect
    ~finally:(fun () ->
      if not !attached then Option.iter fresh ~f:Ingress_creator_custody.Fresh.discard)
    ~f:(fun () ->
      let%bind receipt =
        Staged_ingress.stage t.staged_ingress ~owner ~previous:None ~next ~subscription
      in
      let%map () =
        Option.value_map fresh ~default:(Ok ()) ~f:(fun fresh ->
          Ingress_creator_custody.Staged.attach
            t.staged_ingress_custody
            ~owner
            ~receipt
            ~fresh)
      in
      attached := true;
      receipt, next)
;;

let revoke_script_ingress_internal t owner source id reason =
  let open Result.Let_syntax in
  let%bind previous = read_script_ingress_internal t owner source id in
  let%bind subscription =
    provisional_subscription t owner previous.context.subscription_id
    |> Result.of_option
         ~error:(error Invalid_state "ingress subscription is not retained")
  in
  let%bind next = External_ingress.revoke previous ~reason in
  let%map receipt =
    Staged_ingress.stage
      t.staged_ingress
      ~owner
      ~previous:(Some previous)
      ~next
      ~subscription
  in
  receipt, next
;;

let notification_owned t source (delivery : Agent_protocol.Delivery.t) =
  let open Result.Let_syntax in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      delivery.context.session_id
      delivery.context.generation
  in
  match delivery.context.ownership with
  | Some ownership when Agent_protocol.Invocation.equal_observer ownership.source source
    -> Ok ()
  | _ ->
    Error
      (error
         Permission_denied
         "notification belongs to a different or unbound moderator source")
;;

let provisional_notification t owner id =
  match Staged_notifications.find t.staged_notifications ~owner ~id with
  | Some value -> Some value
  | None -> lookup_notification t id
;;

let create_script_notification_internal
      t
      owner
      source
      (correlation : Chat_response.Notification_operations.correlation)
      completion
      wake
      disclosure_pins
  =
  let open Result.Let_syntax in
  let module P = Agent_protocol in
  let%bind _ = subscription_owner_active t owner source in
  let limits = t.services.notification_limits in
  let%bind () = P.Completion.validate completion in
  let%bind () =
    P.Json_codec.validate_limits
      ~max_bytes:limits.max_payload_bytes
      ~max_depth:limits.max_payload_depth
      (P.Completion.to_json completion)
  in
  let same_session session_id generation =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      session_id
      generation
  in
  let%bind () =
    match correlation.invocation_id with
    | None -> Ok ()
    | Some id ->
      let%bind invocation =
        Result.of_option
          (List.find t.state.invocations ~f:(fun invocation ->
             P.Id.Invocation.equal invocation.context.id id))
          ~error:(error Invalid_request "notification invocation is not retained")
      in
      same_session invocation.context.session_id invocation.context.generation
  in
  let%bind () =
    match correlation.work with
    | None -> Ok ()
    | Some (P.Invocation.Subscription id) ->
      let%bind subscription =
        Result.of_option
          (provisional_subscription t owner id)
          ~error:(error Invalid_request "notification subscription is not retained")
      in
      let%bind () = subscription_owned t source subscription in
      let%bind () =
        match correlation.invocation_id with
        | Some id when P.Id.Invocation.equal id subscription.context.invocation_id ->
          Ok ()
        | _ ->
          Error
            (error
               Permission_denied
               "notification must retain its subscription's invocation")
      in
      (match subscription.result with
       | Some actual when P.Completion.equal actual completion -> Ok ()
       | _ ->
         Error
           (error
              Invalid_request
              "notification differs from its terminal subscription result"))
    | Some (Job id) ->
      let%bind job =
        Result.of_option
          (List.find t.state.jobs ~f:(fun job -> P.Id.Job.equal job.id id))
          ~error:(error Invalid_request "notification job is not retained")
      in
      let%bind () = same_session job.session_id job.generation in
      let%bind result = P.Job.terminal_result job in
      let%bind result =
        Result.of_option
          result
          ~error:(error Invalid_request "notification job is not terminal")
      in
      let%bind matches = P.Stored_completion.matches result completion in
      (match matches with
       | true -> Ok ()
       | false ->
         Error (error Invalid_request "notification differs from its terminal job result"))
  in
  let retained =
    t.state.deliveries @ Staged_notifications.values t.staged_notifications
  in
  let%bind () =
    match correlation.work with
    | None -> Ok ()
    | Some work ->
      (match
         List.exists retained ~f:(fun delivery ->
           Option.exists delivery.context.work ~f:(fun actual ->
             P.Invocation.compare_work actual work = 0))
       with
       | true -> Error (error Conflict "terminal work already has a delivery owner")
       | false -> Ok ())
  in
  let pending delivery =
    match delivery.P.Delivery.status with
    | Pending -> true
    | Committed _ | Failed _ -> false
  in
  let same_source delivery =
    Option.exists delivery.P.Delivery.context.ownership ~f:(fun ownership ->
      P.Invocation.equal_observer ownership.source source)
  in
  let%bind () =
    match
      List.count retained ~f:pending < limits.max_pending
      && List.count retained ~f:(fun delivery -> pending delivery && same_source delivery)
         < limits.max_per_source
      && List.length retained < limits.max_retained
    with
    | true -> Ok ()
    | false -> Error (error Resource_limit "notification admission capacity exhausted")
  in
  let%bind subscription_binding =
    match correlation.work with
    | None | Some (Job _) -> Ok None
    | Some (Subscription id) ->
      let%bind subscription =
        Result.of_option
          (provisional_subscription t owner id)
          ~error:
            (error Invalid_state "notification subscription disappeared before admission")
      in
      P.Delivery.Subscription_binding.create ~subscription_id:id ~epoch:subscription.epoch
      |> Result.map ~f:Option.some
  in
  let%bind delivery =
    P.Delivery.create
      ?disclosure_pins
      { id = P.Id.Delivery.create ()
      ; session_id = t.state.identity.session_id
      ; generation = t.state.identity.generation
      ; invocation_id = correlation.invocation_id
      ; work = correlation.work
      ; correlation = correlation.key
      ; source = Moderator
      ; completion
      ; wake
      ; created_at = t.services.now ()
      ; ownership = Some { source; creator = owner; subscription_binding }
      }
  in
  let%map receipt =
    Staged_notifications.stage t.staged_notifications ~owner ~previous:None ~next:delivery
  in
  receipt, delivery
;;

let finish_script_subscription_internal t owner source id expected_epoch completion =
  let open Result.Let_syntax in
  let%bind _ = subscription_owner_active t owner source in
  let%bind previous =
    Result.of_option
      (provisional_subscription t owner id)
      ~error:(error Invalid_state "subscription is not retained")
  in
  let%bind () = subscription_owned t source previous in
  let now = t.services.now () in
  let monotonic_now = t.services.monotonic_now () in
  let%bind completion =
    match previous.result with
    | Some winner -> Ok winner
    | None ->
      let%map due = subscription_is_due_at t previous ~now ~monotonic_now in
      (match due with
       | true -> Agent_protocol.Completion.Expired
       | false -> completion)
  in
  let%bind next, _ =
    Agent_protocol.Subscription.finish
      previous
      ~expected_epoch
      ~now:(subscription_terminal_time_at previous completion ~now)
      completion
  in
  let%map receipt =
    stage_subscription_mutation_internal
      ~sampled_time:(now, monotonic_now)
      t
      owner
      source
      (Some previous)
      next
  in
  receipt, next
;;

let derive_background_launch t owner =
  let open Result.Let_syntax in
  let%bind () = background_owner_active t owner in
  let%bind launch =
    Job_launch.derive
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      ~invocations:t.state.invocations
      ~events:t.state.moderator_executions
      ~jobs:t.state.jobs
      ~owner
  in
  let%map moderator_source =
    let%bind observer = Runtime_builder.moderator_snapshot_observer t.state.moderator in
    match observer with
    | Some source ->
      (match subscription_owner_active t owner source with
       | Ok _ -> Ok (Some source)
       | Error _ -> Ok None)
    | None -> Ok None
  in
  { launch with moderator_source }
;;

let claim_idle_invocation t borrow (invocation : Agent_protocol.Invocation.t) =
  let open Result.Let_syntax in
  let%bind () = validate_moderator_borrow t borrow in
  let%bind () =
    match borrow.invocation.context.deadline, invocation.context.deadline with
    | None, _ -> Ok ()
    | Some parent, Some child when Agent_protocol.Timestamp.compare child parent <= 0 ->
      Ok ()
    | _ -> Error (error Conflict "moderator child cannot extend its parent's deadline")
  in
  let%bind () =
    match
      ( borrow.job_scope
      , borrow.operation_id
      , t.state.lifecycle.desired
      , t.state.lifecycle.observed )
    with
    | Some scope, None, _, _
      when borrow.accepts_children && not (borrow.committed || borrow.cancel_requested) ->
      job_scope_can_execute t scope
    | None, None, Running, Idle
      when borrow.accepts_children
           && (not (borrow.committed || borrow.cancel_requested))
           && (not t.state.halted)
           && Option.is_none t.state.failure -> Ok ()
    | _ -> Error (error Conflict "idle moderator cannot admit another invocation")
  in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      invocation.context.session_id
      invocation.context.generation
  in
  let%bind () =
    match
      ( invocation.context.origin
      , invocation.context.parent_invocation
      , invocation.context.parent_job
      , invocation.observation
      , borrow.invocation.observation )
    with
    | Moderator, Some parent, None, Some child, Some observed
      when Agent_protocol.Id.Invocation.equal parent borrow.invocation.context.id
           && Agent_protocol.Invocation.equal_observer child.observer observed.observer ->
      Ok ()
    | Script, Some _, None, _, Some observed ->
      let%bind () =
        active_script_parent t ~owns:(invocation_execution_owned_by borrow) invocation
      in
      compatible_script_observer observed.observer invocation
    | _ -> Error (error Conflict "idle invocation must belong to its observing moderator")
  in
  let%bind origin =
    invocation_origin t invocation ~fallback:(fun () ->
      Ok borrow.invocation.inference_origin)
  in
  let%bind boundary = policy_moderator_boundary t borrow in
  let%bind invocation, admission, policy_source =
    invocation_admission_deltas t invocation ~origin ~boundary
  in
  let%bind dispatched = Agent_protocol.Invocation.dispatch invocation in
  let%bind _ =
    transition
      t
      ~delta:(Session_delta.Batch (admission @ [ Invocation_changed dispatched ]))
      ~payloads:[]
  in
  let execution =
    { owner = Invocation_moderator borrow
    ; policy_source
    ; native_goal = None
    ; context_rollover_basis = None
    ; dispatched
    ; accepts_children = true
    ; authority_live = Atomic.make true
    }
  in
  t.invocation_executions <- execution :: t.invocation_executions;
  Ok execution
;;

let uncommitted_borrow_delta t (borrow : moderator_borrow) failure =
  if borrow.committed
  then Ok (Session_delta.Batch [])
  else
    let open Result.Let_syntax in
    let outcome =
      Option.value
        failure
        ~default:
          (Agent_protocol.Invocation.Fail
             { code = "invocation.unhandled"
             ; message = "moderator callback returned without committing a resolution"
             ; retryable = false
             ; details = `Null
             })
    in
    let outcome =
      match borrow.operation_id, t.state.active_operation with
      | Some id, Some { id = current; state = Cancelling; _ }
        when Agent_protocol.Id.Operation.equal id current ->
        Agent_protocol.Invocation.Cancelled "operation cancelled"
      | _ -> outcome
    in
    let%map resolved =
      match borrow.kind with
      | Invocation _ ->
        Agent_protocol.Invocation.resolve
          borrow.invocation
          ~session_id:t.state.identity.session_id
          ~generation:t.state.identity.generation
          outcome
      | Observation ->
        Agent_protocol.Invocation.fail_observation
          borrow.invocation
          ~reason:
            (match outcome with
             | Cancelled _ -> "observation handler cancelled before acknowledgement"
             | _ -> "observation handler failed before acknowledgement")
    in
    Session_delta.Invocation_changed resolved
;;

let finish_moderator_invocation t borrow failure =
  let open Result.Let_syntax in
  let%bind () = validate_moderator_borrow t borrow in
  borrow.callback_finished <- true;
  abort_staged_work t ~owner:(Invocation borrow.invocation.context.id);
  borrow.cancel <- None;
  borrow.accepts_children <- false;
  Atomic.set borrow.authority_live false;
  let was_committed = borrow.committed in
  let unfinished =
    List.filter t.invocation_executions ~f:(invocation_execution_owned_by borrow)
  in
  let permissions, permission_deltas, permission_payloads =
    cleanup_invocation_permissions
      t
      (borrow.invocation.context.id
       :: List.map unfinished ~f:(fun child -> child.dispatched.context.id))
  in
  let%bind children =
    List.map unfinished ~f:(fun execution ->
      execution.accepts_children <- false;
      Atomic.set execution.authority_live false;
      abort_staged_work t ~owner:(Invocation execution.dispatched.context.id);
      Agent_protocol.Invocation.cancel
        execution.dispatched
        ~reason:
          (match borrow.operation_id with
           | None -> "idle moderator exited before recording the invocation outcome"
           | Some _ -> "moderator exited before recording the invocation outcome")
      |> Result.map ~f:(fun invocation -> Session_delta.Invocation_changed invocation))
    |> Result.all
  in
  let%bind delta = uncommitted_borrow_delta t borrow failure in
  let%bind () =
    if was_committed && List.is_empty children && List.is_empty permission_deltas
    then Ok ()
    else
      Result.map
        (transition
           t
           ~delta:(Session_delta.Batch (children @ permission_deltas @ [ delta ]))
           ~payloads:permission_payloads)
        ~f:(fun _ -> ())
  in
  resolve_cleaned_permission_waiters t permissions;
  t.invocation_executions
  <- List.filter t.invocation_executions ~f:(fun execution ->
       not (invocation_execution_owned_by borrow execution));
  Option.iter borrow.observation ~f:Observation_continuation.retire;
  t.moderator_borrow <- None;
  (match borrow.operation_id with
   | None -> t.idle_moderator_borrowed <- false
   | Some _ -> ());
  if (not was_committed) && Option.is_none failure
  then
    Error
      (error Invalid_state "moderator callback returned without committing a resolution")
  else Ok ()
;;

let operation_state t (operation : Agent_protocol.Operation.t) state =
  { operation with state; updated_at = t.services.now () }
;;

let summary_with_operation t operation =
  Session_state.summary { t.state with active_operation = Some operation }
;;

let lifecycle_for_operation t operation_id =
  Session_state.Lifecycle.
    { desired = t.state.lifecycle.desired; observed = Running_turn operation_id }
;;

let lifecycle_for_compaction t operation_id =
  Session_state.Lifecycle.
    { desired = t.state.lifecycle.desired; observed = Compacting operation_id }
;;

let commit_worker_entry t operation_id ~check entry =
  let open Result.Let_syntax in
  let%bind _ = current_operation t operation_id in
  let protocol_entry =
    History_codec.canonical_encoder ~previous:t.state.conversation.canonical_history entry
  in
  match
    List.find t.state.conversation.canonical_history ~f:(fun existing ->
      History_entry.Id.equal existing.id protocol_entry.id)
  with
  | None ->
    let%map _ = append_history ~check_before_commit:check t [ protocol_entry ] in
    ()
  | Some existing ->
    if
      Sexp.equal
        ([%sexp_of: Agent_protocol.History.entry] existing)
        ([%sexp_of: Agent_protocol.History.entry] protocol_entry)
    then Ok ()
    else Error (error Conflict "history ID was committed with a different payload")
;;

let prepare_authoring_input t operation_id ~check materialization history effective =
  let module M = Chat_response.Authoring_materialization in
  let open Result.Let_syntax in
  let%bind _ = running_operation t operation_id in
  let%bind () =
    let committed = t.state.conversation.canonical_history in
    let supplied = History_codec.all_to_protocol ~previous:committed history in
    match List.equal equal_agent_entry committed supplied with
    | true -> Ok ()
    | false -> Error (error Conflict "authoring input uses stale canonical history")
  in
  let%bind () =
    match
      String.equal
        (M.scope materialization)
        (M.session_scope
           ~session_id:t.state.identity.session_id
           ~generation:t.state.identity.generation)
    with
    | true -> Ok ()
    | false ->
      Error (error Conflict "authoring context belongs to a different session generation")
  in
  let canonical =
    History_codec.canonical_encoder ~previous:t.state.conversation.canonical_history
  in
  let effective =
    List.map effective ~f:(fun value ->
      let module E = Chat_response.Moderation.Effective_entry in
      match value.E.provenance with
      | Canonical -> canonical value.entry
      | Moderator_inserted _ ->
        History_codec.to_protocol ~provenance:Moderator_inserted value.entry
      | Moderator_replacement { target_id; _ } ->
        { (canonical value.entry) with provenance = Moderator_replaced target_id })
  in
  let%bind references = Session_state.authoring_references t.state in
  let%bind messages =
    M.refresh
      materialization
      ~known:(Chat_response.Authoring_reference_index.receipts references)
      ~effective
  in
  let publication = Chat_response.Authoring_publication.capture materialization in
  let context_deltas =
    match
      Option.equal
        Chat_response.Authoring_publication.equal_context
        t.state.conversation.authoring_publication
        (Some publication)
    with
    | true -> []
    | false -> [ Session_delta.Authoring_publication_changed publication ]
  in
  match messages, context_deltas with
  | [], [] -> Ok []
  | _ ->
    let first =
      Int64.max
        t.state.conversation.next_history_sequence
        t.state.conversation.reserved_history_through
    in
    let count = List.length messages in
    let%bind () =
      match Int64.(first >= 0L && first <= of_int Int.(max_value - count)) with
      | true -> Ok ()
      | false -> Error (error Invalid_state "authoring history sequence overflow")
    in
    let%bind entries =
      List.mapi messages ~f:(fun index message ->
        History_entry.Id.create
          ~namespace:(Agent_protocol.Id.Session.to_string t.state.identity.session_id)
          ~sequence:(Int64.to_int_exn first + index)
        |> Result.map_error ~f:(error Invalid_state)
        |> Result.map ~f:(fun id -> M.entry message ~id))
      |> Result.all
    in
    let%bind returned = History_codec.all_of_protocol entries in
    let%map _ =
      transition
        ~check_before_commit:check
        t
        ~delta:
          (Session_delta.Batch
             (context_deltas
              @
              match entries with
              | [] -> []
              | _ ->
                [ History_block_reserved Int64.(first + of_int count)
                ; Canonical_entries_appended entries
                ]))
        ~payloads:
          (match entries with
           | [] -> []
           | _ -> [ Agent_protocol.Event.Durable.Payload.History_appended entries ])
    in
    returned
;;

let publish_invocation_output t operation_id ~check invocation_id entry =
  let open Result.Let_syntax in
  (* A completed tool may publish while a sibling waits for permission. Publishing
     its already-resolved result does not authorize or execute another tool. *)
  let%bind _ =
    running_operation ~allow_stopping:true ~allow_waiting_permission:true t operation_id
  in
  let%bind invocation =
    match
      List.find t.state.invocations ~f:(fun i ->
        Agent_protocol.Id.Invocation.compare i.context.id invocation_id = 0)
    with
    | Some i -> Ok i
    | None -> Error (error Invalid_state "invocation has not been admitted")
  in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      invocation.context.session_id
      invocation.context.generation
  in
  let%bind () = Invocation_history.validate_output invocation entry in
  let%bind published =
    Agent_protocol.Invocation.publish_with_history
      invocation
      ~output_entry_id:(History_entry.id entry)
  in
  let raw_entry =
    History_codec.canonical_encoder ~previous:t.state.conversation.canonical_history entry
  in
  let existing =
    List.find t.state.conversation.canonical_history ~f:(fun e ->
      History_entry.Id.equal e.id raw_entry.id)
  in
  let%bind protocol_entry =
    match existing with
    | Some entry ->
      let%bind () =
        Chat_response.Authoring_publication.validate_output invocation entry
      in
      (match equal_agent_entry entry { raw_entry with provenance = entry.provenance } with
       | true -> Ok entry
       | false ->
         Error (error Conflict "output occurrence has a different canonical payload"))
    | None ->
      Chat_response.Authoring_publication.encode
        ~context:t.state.conversation.authoring_publication
        invocation
        raw_entry
  in
  match invocation.status with
  | Published _ -> Ok ()
  | _ ->
    let entries = if Option.is_some existing then [] else [ protocol_entry ] in
    let payloads =
      if List.is_empty entries
      then []
      else [ Agent_protocol.Event.Durable.Payload.History_appended entries ]
    in
    let%map _ =
      transition
        ~check_before_commit:check
        t
        ~delta:
          (Session_delta.Batch
             [ Canonical_entries_appended entries; Invocation_changed published ])
        ~payloads
    in
    ()
;;

let commit_worker_moderator t operation_id ~check moderator =
  let open Result.Let_syntax in
  let%bind _ = running_operation ~allow_stopping:true t operation_id in
  if moderator_is_borrowed t
  then Error (error Conflict "moderator invocation owns the moderator checkpoint")
  else (
    match t.foreground_moderator with
    | Some (managed_operation, observer) ->
      let%bind installed =
        Runtime_builder.moderator_snapshot_observer t.state.moderator
      in
      let%bind () =
        if
          Agent_protocol.Id.Operation.equal managed_operation operation_id
          && Option.equal
               Agent_protocol.Invocation.equal_observer
               installed
               (Some observer)
        then Ok ()
        else Error (error Conflict "foreground moderator checkpoint owner changed")
      in
      (* Owned handlers already acknowledged the full checkpoint. A worker may
         confirm only its unchanged bare Manager projection or that exact full
         carrier; explicit queue/extension changes must not disappear here. *)
      let%bind acknowledged =
        Moderator_checkpoint.reuse_unchanged_snapshot
          ~previous:t.state.moderator
          ~incoming:moderator
      in
      if Option.equal Jsonaf.exactly_equal t.state.moderator acknowledged
      then Ok ()
      else
        Error
          (error Conflict "foreground moderator checkpoint differs from its Event ACK")
    | None ->
      (* Workers encode the Manager projection; an unchanged confirmation must
         retain the host-owned queue and extension carrier. *)
      let%bind acknowledged =
        Moderator_checkpoint.reuse_unchanged_snapshot
          ~previous:t.state.moderator
          ~incoming:moderator
      in
      if Option.equal Jsonaf.exactly_equal t.state.moderator acknowledged
      then Ok ()
      else
        Result.map
          (change_moderator ~check_before_commit:check t acknowledged)
          ~f:(fun _ -> ()))
;;

let configuration_view t =
  Configuration_capture.view
    t.configuration_capture
    ~generation:t.state.identity.generation
    ~revision:t.state.spec.configuration_revision
    ~selected:t.state.spec.inference_target
;;

let prepare_configuration_update t request =
  let open Result.Let_syntax in
  let%bind _ =
    write_attachment
      t
      request.Agent_protocol.Session_configuration.Update_request.attachment_id
  in
  let%bind policy =
    Result.of_option
      t.configuration_policy
      ~error:(error Invalid_state "host configuration policy is unavailable")
  in
  Configuration_update.create
    ~owner:t.configuration_update_owner
    ~policy
    ~request
    ~state:t.state
;;

let commit_configuration_update t validated =
  let open Result.Let_syntax in
  let request = Configuration_update.Validated.request validated in
  let%bind _ = write_attachment t request.attachment_id in
  let%bind policy =
    Result.of_option
      t.configuration_policy
      ~error:(error Conflict "host configuration policy changed")
  in
  let%bind () =
    Configuration_update.recheck
      validated
      ~owner:t.configuration_update_owner
      ~policy
      ~state:t.state
  in
  let proposed = Configuration_update.Validated.proposed validated in
  let revision = Int64.(t.state.spec.configuration_revision + 1L) in
  let delta =
    Session_delta.Batch
      [ Inference_target_changed proposed; Configuration_revision_changed revision ]
  in
  let%bind candidate = Session_delta.apply t.state delta in
  let%bind transition =
    prepare_transition
      t
      ~delta
      ~payloads:
        [ Agent_protocol.Event.Durable.Payload.Session_updated
            (Session_state.summary candidate)
        ]
  in
  let%bind unmoderated_configuration_acknowledgement =
    match t.unmoderated_source, t.operation_worker with
    | None, _ -> Ok None
    | Some original, Some worker ->
      let%map replacement =
        Runtime_builder.Unmoderated_source.Binding.reconfigure
          original
          ~previous:t.state
          ~candidate:transition.state
          ~worker
          ~manager:t.moderator_manager
      in
      Some { previous = t.state; candidate = transition; original; replacement; worker }
    | Some _, None -> Error (error Conflict "unmoderated configuration lost its worker")
  in
  let%bind () = install ?unmoderated_configuration_acknowledgement t transition in
  configuration_view t
;;

let context_capacity_basis t target =
  Option.bind
    (Option.bind t.canonical_persistence ~f:Canonical_backend_binding_data.session_owner)
    ~f:(fun owner ->
      Session_context_capacity.Selection.select
        t.context_capacity_host
        ~owner
        ~target
        ~opted_in:(fun () ->
          Option.exists t.state.recovery_windows ~f:(fun ledger ->
            Agent_protocol.Session_ref.equal owner (Recovery_window_ledger.owner ledger)))
      |> Option.map ~f:(fun selection ->
        Configuration_capture.Capacity_basis.capture t.state ~selection))
;;

let current_context_capacity_basis t =
  Result.ok (Configuration_transition.target t.state)
  |> Option.bind ~f:(context_capacity_basis t)
;;

let read_context_capacity t operation_id =
  let open Result.Let_syntax in
  let%bind _ = running_operation ~allow_waiting_permission:true t operation_id in
  let%map () = require_runtime_admission t in
  Configuration_capture.capacity_status
    t.configuration_capture
    ~operation_id
    ~current:(current_context_capacity_basis t)
;;

let current_recovery_preparation_scope t =
  let open Option.Let_syntax in
  let%bind storage = t.canonical_persistence in
  let%bind owner = Canonical_backend_binding_data.session_owner storage in
  let%bind windows = t.state.recovery_windows in
  if Agent_protocol.Session_ref.equal owner (Recovery_window_ledger.owner windows)
  then Some (Recovery_window_ledger.Window.scope (Recovery_window_ledger.active windows))
  else None
;;

let begin_configuration_capture t operation_id =
  let open Result.Let_syntax in
  let%bind _ = running_operation t operation_id in
  let%bind () = require_runtime_admission t in
  let%bind target = Configuration_transition.target t.state in
  let%map policy =
    Result.of_option
      t.configuration_policy
      ~error:(error Invalid_state "root configuration policy is unavailable")
  in
  Configuration_capture.begin_capture
    ?capacity:(context_capacity_basis t target)
    ?recovery_scope:(current_recovery_preparation_scope t)
    ~capture_recovery:(Recovery_effective_ledger.has_record_capacity t.state.recovery_effective)
    t.configuration_capture
    ~operation_id
    ~generation:t.state.identity.generation
    ~revision:t.state.spec.configuration_revision
    ~target
    ~policy
;;

let mark_configuration_capture t capture configuration =
  let open Result.Let_syntax in
  let%bind _ = running_operation t (Configuration_capture.Token.operation_id capture) in
  let%bind () = require_runtime_admission t in
  Configuration_capture.mark t.configuration_capture capture configuration
;;

let finish_configuration_capture t capture success =
  Configuration_capture.finish t.configuration_capture capture ~success;
  Ok ()
;;

let mark_context_capacity t capture observation =
  let open Result.Let_syntax in
  let%bind _ = running_operation t (Configuration_capture.Token.operation_id capture) in
  let%map () = require_runtime_admission t in
  Configuration_capture.mark_capacity
    t.configuration_capture
    capture
    ~current:(current_context_capacity_basis t)
    observation
;;

let capture_recovery_preparation t capture input ~configuration ~binding_is_current =
  let open Result.Let_syntax in
  let operation = Configuration_capture.Token.operation_id capture in
  let check () =
    let%bind _ = running_operation t operation in
    let%bind () = require_runtime_admission t in
    let%bind () =
      if binding_is_current ()
      then Ok ()
      else Error (error Conflict "actual prepared adapter binding is unavailable")
    in
    let%bind admission = operation_agent_admission t operation in
    let%bind () = Option.value_map admission ~default:(Ok ()) ~f:check_agent_admission in
    let%bind scope =
      Result.of_option
        (current_recovery_preparation_scope t)
        ~error:(error Conflict "actual durable recovery window is unavailable")
    in
    Configuration_capture.check_recovery t.configuration_capture capture ~scope
  in
  let%bind () = check () in
  let%bind prepared = Recovery_effective_capture.prepare t.state ~operation input in
  match prepared with
  | None -> Ok ()
  | Some record ->
    let previous = t.state in
    let run_preparation =
      Option.map t.run_source_binding ~f:(fun binding -> binding.Source_binding.preparation)
    in
    let%bind candidate =
      prepare_transition
        ?run_preparation
        t
        ~delta:(Recovery_effective_prepared record)
        ~payloads:[]
    in
    (match%bind check_recovery_admission t candidate with
     | Capacity_exhausted -> Ok ()
     | Fits ->
       let commit_observation =
         Session_commit_observation.Owner.create_guarded
           ~previous
           ~candidate
           ~check_at_writer:check
       in
       let%bind () =
         persist_transition
           ?run_preparation
           t
           candidate
           ~check_before_commit:check
           ~commit_observation
       in
       install_committed_transition ?run_preparation t candidate;
       Configuration_capture.record_recovery_binding
         t.configuration_capture
         capture
         ~configuration
         ~source_revision:(Recovery_effective_record.source_revision record);
       publish_committed_transition t candidate;
       Ok ())
;;

let root_configuration_context t operation_id =
  Configuration_capture.root_port
    ~begin_capture:(fun () -> call t (Begin_configuration_capture operation_id))
    ~publish_capacity:(fun capture observation ->
      call t (Context_request (Capacity (Publish (capture, observation)))))
    ~publish_recovery:(fun capture input ~configuration ~binding_is_current ->
      call t
        (Context_request (Recovery_effective (capture, input, configuration, binding_is_current))))
    ~mark:(fun capture configuration ->
      call t (Mark_configuration_capture (capture, configuration)))
    ~finish:(fun capture ~success ->
      call t (Finish_configuration_capture (capture, success)))
;;

let consume_deferred t operation_id ~check =
  if not (runtime_admission_open t)
  then Ok []
  else
    let open Result.Let_syntax in
    let%bind _ = current_operation t operation_id in
    let%bind prepared =
      prepare_pending
        t
        (Adopt
           { boundary = Worker operation_id
           ; runtime_admission_open = runtime_admission_open t
           })
    in
    let entries = Pending_plan.adopted_entries (Pending_transition.plan prepared) in
    let%bind decoded = History_codec.all_of_protocol entries in
    if List.is_empty entries
    then Ok []
    else (
      let%map _ =
        transition
          ~check_before_commit:check
          t
          ~delta:(Pending_transition.delta prepared)
          ~payloads:[ Agent_protocol.Event.Durable.Payload.History_appended entries ]
      in
      decoded)
;;

let admit_standalone_delivery_internal t plan =
  let open Result.Let_syntax in
  let%bind () =
    Standalone_delivery.revalidate
      ~state:t.state
      ~staged:(Staged_notifications.values t.staged_notifications)
      ~limits:t.services.notification_limits
      plan
  in
  let%map _ =
    transition t ~delta:(Session_delta.Delivery_changed plan.delivery) ~payloads:[]
  in
  ()
;;

let checked_pending_job_delivery t revision expected =
  let open Result.Let_syntax in
  let module P = Agent_protocol in
  let%bind () =
    match Int64.equal revision t.state.counters.revision with
    | true -> Ok ()
    | false -> Error (error Conflict "background delivery runtime snapshot changed")
  in
  let%bind job =
    List.find t.state.jobs ~f:(fun value -> P.Id.Job.equal value.id expected.P.Job.id)
    |> Result.of_option ~error:(error Invalid_request "background delivery job missing")
  in
  let%bind () =
    match Jsonaf.exactly_equal (P.Job.to_json expected) (P.Job.to_json job) with
    | true -> Ok ()
    | false -> Error (error Conflict "background delivery job changed")
  in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      job.session_id
      job.generation
  in
  let%bind () =
    match job.delivery with
    | Pending -> Ok ()
    | Delivered _ | Not_required | Discarded _ ->
      Error (error Already_resolved "background job delivery is resolved")
  in
  let%bind () =
    match job.status with
    | Succeeded | Failed _ | Cancelled | Interrupted _ -> Ok ()
    | Queued | Running | Waiting_permission _ | Waiting_completion _ ->
      Error (error Conflict "background job is not terminal")
  in
  let%map () = P.Job.validate_result job in
  job
;;

let retire_job_delivery t (job : Agent_protocol.Job.t) =
  let open Result.Let_syntax in
  let module P = Agent_protocol in
  let now = t.services.now () in
  let at =
    match job.completed_at with
    | Some completed when P.Timestamp.compare completed now > 0 -> completed
    | _ -> now
  in
  let job = { job with delivery = Discarded { at; reason = Authority_changed } } in
  let%map _ =
    transition
      t
      ~delta:(Session_delta.Job_changed job)
      ~payloads:[ P.Event.Durable.Payload.Job_state_changed job ]
  in
  ()
;;

let retire_obsolete_moderator_delivery_internal t revision expected =
  let open Result.Let_syntax in
  let%bind job = checked_pending_job_delivery t revision expected in
  let%bind source = Background_job_event.source ~state:t.state job in
  let%bind source =
    Result.of_option
      source
      ~error:
        (error Invalid_request "background delivery has no captured moderator source")
  in
  let%bind installed = Runtime_builder.moderator_snapshot_observer t.state.moderator in
  match Option.equal Agent_protocol.Invocation.equal_observer (Some source) installed with
  | true -> Ok false
  | false ->
    let%map () = retire_job_delivery t job in
    true
;;

let deliver_standalone_completion_internal t revision expected current_capabilities policy
  =
  let open Result.Let_syntax in
  let module P = Agent_protocol in
  let%bind job = checked_pending_job_delivery t revision expected in
  let%bind invocation =
    match
      Option.bind job.launch ~f:(fun launch ->
        P.Job.Birth_parent.callback_owner launch.owner)
    with
    | Some (Invocation id) ->
      List.find t.state.invocations ~f:(fun value ->
        P.Id.Invocation.equal value.context.id id)
      |> Result.of_option
           ~error:(error Invalid_request "standalone completion owner missing")
    | _ -> Error (error Invalid_request "standalone completion has no invocation owner")
  in
  match
    Standalone_completion_contract.authorize
      ~invocation
      ~job
      ~current_capabilities
      ~policy
  with
  | Error { code = Permission_denied; _ } -> retire_job_delivery t job
  | Error error -> Error error
  | Ok () ->
    let load_artifact =
      Option.map t.services.job_results ~f:(fun publisher ->
        Agent_store.Job_result_store.Publisher.load publisher)
    in
    let%bind completion = P.Job.terminal_completion ?load_artifact job in
    let%bind completion =
      Result.of_option
        completion
        ~error:(error Invalid_state "standalone job has no terminal result")
    in
    let now = t.services.now () in
    let%bind plan =
      Standalone_delivery.prepare
        ~state:t.state
        ~notification_limits:t.services.notification_limits
        ~invocation_id:invocation.context.id
        ~job_id:job.id
        ~completion
        ~current_capabilities
        ~delivery_id:(P.Id.Delivery.create ())
        ~now
        ~wake:Request_turn
    in
    let%bind () =
      Standalone_delivery.revalidate
        ~state:t.state
        ~staged:(Staged_notifications.values t.staged_notifications)
        ~limits:t.services.notification_limits
        plan
    in
    let job = { job with delivery = Delivered now } in
    let%map _ =
      transition
        t
        ~delta:(Session_delta.Batch [ Delivery_changed plan.delivery; Job_changed job ])
        ~payloads:[ P.Event.Durable.Payload.Job_state_changed job ]
    in
    ()
;;

let validate_notification_plan t (plan : Notification_delivery.t) =
  let open Result.Let_syntax in
  let%bind () =
    Extension_invariants.owner
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      plan.session_id
      plan.generation
  in
  let%bind installed = Runtime_builder.moderator_snapshot_observer t.state.moderator in
  match
    ( Int64.equal plan.revision t.state.counters.revision
    , installed
    , moderator_is_borrowed t )
  with
  | true, source, false
    when Option.equal Agent_protocol.Invocation.equal_observer source plan.source -> Ok ()
  | _ -> Error (error Conflict "notification snapshot or source changed")
;;

let notification_changes t (plan : Notification_delivery.t) =
  let open Result.Let_syntax in
  let%map deltas, entries, committed =
    List.fold_result
      plan.actions
      ~init:([], [], [])
      ~f:(fun (deltas, entries, committed) action ->
        match action with
        | Notification_delivery.Fail value ->
          Ok (Session_delta.Delivery_changed value :: deltas, entries, committed)
        | Publish value ->
          let%bind id =
            History_entry.Id.create
              ~namespace:
                ("notification/" ^ Agent_protocol.Id.Delivery.to_string value.context.id)
              ~sequence:0
            |> Result.map_error ~f:(error Invalid_state)
          in
          let%bind entry = Notification_history.create ~id value in
          let now = t.services.now () in
          let now =
            if Agent_protocol.Timestamp.compare now value.context.created_at < 0
            then value.context.created_at
            else now
          in
          let%map value =
            Agent_protocol.Delivery.commit ~track_wake:true value ~history_id:id ~now
          in
          ( Session_delta.Delivery_committed (value, entry) :: deltas
          , entry :: entries
          , value :: committed ))
  in
  List.rev deltas, List.rev entries, List.rev committed
;;

let notification_payloads = function
  | [] -> []
  | entries -> [ Agent_protocol.Event.Durable.Payload.History_appended entries ]
;;

let consume_notifications_internal
      ~check
      ?(wakes = [])
      ?(discarded_wakes = [])
      t
      operation_id
      plan
  =
  if not (runtime_admission_open t)
  then Ok Chat_response.In_memory_stream.Safe_point_input.empty
  else
    let open Result.Let_syntax in
    let%bind _ = running_operation ~allow_stopping:true t operation_id in
    match t.state.lifecycle.desired with
    | Stopped ->
      (* An admitted provider may finish during graceful stop. Its final safe point
       must not fail, consume retained deliveries, or request another turn. *)
      Ok Chat_response.In_memory_stream.Safe_point_input.empty
    | Running ->
      let%bind () =
        match
          List.exists t.invocation_executions ~f:(fun execution ->
            match execution.owner with
            | Foreground id -> Agent_protocol.Id.Operation.equal id operation_id
            | _ -> false)
        with
        | true ->
          Error
            (error Conflict "notification insertion waits for the foreground tool batch")
        | false -> Ok ()
      in
      let%bind () = validate_notification_plan t plan in
      let%bind deltas, entries, committed = notification_changes t plan in
      let deltas =
        deltas
        @ List.map discarded_wakes ~f:(fun value ->
          Session_delta.Delivery_wake_changed value)
      in
      let%bind selection_state =
        Session_delta.apply t.state (Session_delta.Batch deltas)
      in
      let%bind selected_wakes =
        Notification_wake_selection.select
          selection_state
          ~context:Ordinary
          (committed @ wakes)
      in
      let%bind decoded = History_codec.all_of_protocol entries in
      let%map () =
        match deltas with
        | [] -> Ok ()
        | _ ->
          transition
            ~check_before_commit:check
            t
            ~delta:(Session_delta.Batch deltas)
            ~payloads:(notification_payloads entries)
          |> Result.map ~f:ignore
      in
      let existing =
        match t.notification_inputs with
        | Some (id, ids) when Agent_protocol.Id.Operation.equal id operation_id -> ids
        | _ -> []
      in
      let ids =
        List.map selected_wakes ~f:(fun value -> value.Agent_protocol.Delivery.context.id)
      in
      t.notification_inputs <- Some (operation_id, ids @ existing);
      let wake =
        List.exists selected_wakes ~f:(fun value ->
          Agent_protocol.Completion.equal_wake value.context.wake Request_turn)
      in
      Chat_response.In_memory_stream.Safe_point_input.notification_entries
        ~request_turn:wake
        decoded
;;

let notification_wake_deltas t operation_id ~accept =
  let open Result.Let_syntax in
  let ids =
    match t.notification_inputs with
    | Some (id, ids) when Agent_protocol.Id.Operation.equal id operation_id -> ids
    | _ -> []
  in
  let candidates =
    List.filter t.state.deliveries ~f:(fun value ->
      List.mem ids value.context.id ~equal:Agent_protocol.Id.Delivery.equal
      &&
      match value.wake_disposition with
      | Some Pending_wake -> true
      | _ -> false)
  in
  let%bind selected =
    Notification_wake_selection.select t.state ~context:Ordinary candidates
  in
  List.map selected ~f:(fun value ->
    let%map value =
      match accept with
      | true -> Agent_protocol.Delivery.accept_wake value ~operation_id
      | false ->
        Agent_protocol.Delivery.discard_wake
          value
          ~reason:"foreground ended without admitting this notification wake"
    in
    Session_delta.Delivery_wake_changed value)
  |> Result.all
;;

let worker_ready ?check_before_commit t operation_id cancel =
  match t.state.active_operation with
  | None ->
    cancel ();
    Ok ()
  | Some operation when Agent_protocol.Id.Operation.compare operation.id operation_id <> 0
    ->
    cancel ();
    Ok ()
  | Some operation ->
    t.active_cancel <- Some cancel;
    if not (runtime_admission_open t)
    then (
      cancel ();
      Ok ())
    else (
      match operation.state with
      | Agent_protocol.Operation.Cancelling ->
        cancel ();
        Ok ()
      | Starting ->
        let operation = operation_state t operation Running in
        let open Result.Let_syntax in
        let%map _ =
          transition
            ?check_before_commit
            t
            ~delta:(Session_delta.Active_operation_changed (Some operation))
            ~payloads:
              [ Agent_protocol.Event.Durable.Payload.Session_updated
                  (summary_with_operation t operation)
              ]
        in
        ()
      | Running -> Ok ()
      | Completed | Failed _ | Cancelled | Interrupted _ ->
        cancel ();
        Ok ())
;;

let terminal_lifecycle t =
  Session_state.Lifecycle.
    { desired = t.state.lifecycle.desired
    ; observed =
        (match t.state.lifecycle.desired with
         | Running ->
           (match
              List.find t.state.permissions ~f:(fun permission ->
                Agent_protocol.Permission.equal_state permission.state Pending
                &&
                match permission.owner with
                | Operation _ -> false
                | Invocation id ->
                  List.exists t.invocation_executions ~f:(fun execution ->
                    Agent_protocol.Id.Invocation.equal execution.dispatched.context.id id
                    &&
                    match execution.owner with
                    | Background_job _ -> true
                    | _ -> false))
            with
            | Some permission -> Waiting_for_permission permission.id
            | None -> Idle)
         | Stopped -> Stopped)
    }
;;

let history_prefix ~prefix values =
  let equal left right =
    Sexp.equal
      ([%sexp_of: Agent_protocol.History.entry] left)
      ([%sexp_of: Agent_protocol.History.entry] right)
  in
  List.is_prefix values ~prefix ~equal
;;

let end_session_reason requests =
  List.find_map requests ~f:(function
    | Chat_response.Moderation.Runtime_request.End_session reason -> Some reason
    | Request_turn | Request_compaction -> None)
;;

let completed_lifecycle t requests =
  match end_session_reason requests with
  | None -> terminal_lifecycle t
  | Some _ ->
    Session_state.Lifecycle.
      { desired = Agent_protocol.Session.Stopped; observed = Stopped }
;;

let runtime_request_deltas summary =
  end_session_reason summary.Operation_worker.Summary.runtime_requests
  |> Option.map ~f:(fun reason -> Session_delta.Halt_changed (Some reason))
  |> Option.to_list
;;

let runtime_request_payloads summary =
  end_session_reason summary.Operation_worker.Summary.runtime_requests
  |> Option.map ~f:(fun reason ->
    Agent_protocol.Event.Durable.Payload.Moderator_notification
      (`Object [ "end_session_reason", `String reason ]))
  |> Option.to_list
;;

let release_pending_delta t (operation : Agent_protocol.Operation.t) =
  let relevant =
    List.exists t.state.conversation.deferred_user_entries ~f:(fun document ->
      match
        Agent_protocol.Pending_input.binding (Pending_input_document.value document)
      with
      | After_root { operation_id; terminal = None; _ } ->
        Agent_protocol.Id.Operation.equal operation_id operation.id
      | Safe_boundary | Await_idle | After_root { terminal = Some _; _ } -> false)
  in
  if not relevant
  then Ok None
  else
    let open Result.Let_syntax in
    let%bind proof = Agent_protocol.Pending_input.Terminal_proof.of_operation operation in
    let%map prepared = prepare_pending t (Release proof) in
    Some (Pending_transition.delta prepared)
;;

let completed_delta t operation summary =
  let final_protocol =
    History_codec.all_to_protocol
      ~previous:t.state.conversation.canonical_history
      summary.Operation_worker.Summary.final_history
  in
  let committed = t.state.conversation.canonical_history in
  if not (history_prefix ~prefix:committed final_protocol)
  then Error (error Conflict "worker final history diverges from committed history")
  else
    let open Result.Let_syntax in
    let missing = List.drop final_protocol (List.length committed) in
    let operation = operation_state t operation Agent_protocol.Operation.Completed in
    let%bind release = release_pending_delta t operation in
    let lifecycle = completed_lifecycle t summary.runtime_requests in
    let%bind moderator_snapshot =
      match t.foreground_moderator, moderator_is_borrowed t with
      | Some _, _ | _, true -> Ok t.state.moderator
      | None, false ->
        (match summary.moderator_snapshot with
         | None -> Ok t.state.moderator
         | Some _ ->
           (* A supplied bare Manager projection confirms only an unchanged
              checkpoint; omission does not select a source removal. *)
           Moderator_checkpoint.reuse_unchanged_snapshot
             ~previous:t.state.moderator
             ~incoming:summary.moderator_snapshot)
    in
    let deltas =
      [ release
      ; Option.some_if
          (not (List.is_empty missing))
          (Session_delta.Canonical_entries_appended missing)
      ; Some (Session_delta.Active_operation_changed None)
      ; Some (Session_delta.Lifecycle_changed lifecycle)
      ; Some (Session_delta.Moderator_changed moderator_snapshot)
      ]
      |> List.filter_opt
      |> fun values -> values @ runtime_request_deltas summary
    in
    let payloads =
      [ Option.some_if
          (not (List.is_empty missing))
          (Agent_protocol.Event.Durable.Payload.History_appended missing)
      ; Some (Agent_protocol.Event.Durable.Payload.Operation_completed operation)
      ; Some
          (Agent_protocol.Event.Durable.Payload.Session_state_changed
             { desired_state = lifecycle.desired; observed_state = lifecycle.observed })
      ]
      |> List.filter_opt
      |> fun values -> values @ runtime_request_payloads summary
    in
    Ok (Session_delta.Batch deltas, payloads)
;;

let terminal_delta t operation outcome =
  let open Result.Let_syntax in
  match outcome with
  | Operation_worker.Completed summary -> completed_delta t operation summary
  | Cancelled cancellation ->
    let operation = operation_state t operation Agent_protocol.Operation.Cancelled in
    let%map release = release_pending_delta t operation in
    let lifecycle = terminal_lifecycle t in
    ( Session_delta.Batch
        (Option.to_list release
         @ [ Active_operation_changed None; Lifecycle_changed lifecycle ])
    , [ Agent_protocol.Event.Durable.Payload.Operation_cancelled operation
      ; Moderator_notification
          (`Object [ "cancellation_reason", `String cancellation.reason ])
      ; Session_state_changed
          { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
      ] )
  | Failed failure ->
    let operation =
      operation_state t operation (Agent_protocol.Operation.Failed failure)
    in
    let%map release = release_pending_delta t operation in
    let lifecycle = terminal_lifecycle t in
    ( Session_delta.Batch
        (Option.to_list release
         @ [ Active_operation_changed None; Lifecycle_changed lifecycle ])
    , [ Agent_protocol.Event.Durable.Payload.Operation_failed operation
      ; Session_state_changed
          { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
      ] )
;;

let is_permission_review_job (job : Agent_protocol.Job.t) =
  match job.payload with
  | `Object fields ->
    List.Assoc.find fields "type" ~equal:String.equal
    |> Option.value_map ~default:false ~f:(function
      | `String value -> String.equal value "permission_review"
      | _ -> false)
  | _ -> false
;;

let pending_for_operation t (operation : Agent_protocol.Operation.t) permission =
  Agent_protocol.Permission.equal_state permission.Agent_protocol.Permission.state Pending
  &&
  match permission.owner with
  | Operation id -> Agent_protocol.Id.Operation.equal id operation.id
  | Invocation id ->
    List.exists t.invocation_executions ~f:(fun execution ->
      Agent_protocol.Id.Invocation.equal id execution.dispatched.context.id
      &&
      match execution.owner with
      | Foreground id -> Agent_protocol.Id.Operation.equal id operation.id
      | Background_job _ -> false
      | Event_moderator borrow ->
        Option.exists
          borrow.receipt.context.operation_id
          ~f:(Agent_protocol.Id.Operation.equal operation.id)
      | Invocation_moderator borrow ->
        Option.exists
          borrow.operation_id
          ~f:(Agent_protocol.Id.Operation.equal operation.id))
    || Option.exists t.moderator_borrow ~f:(fun borrow ->
      Agent_protocol.Id.Invocation.equal id borrow.invocation.context.id
      && Option.exists
           borrow.operation_id
           ~f:(Agent_protocol.Id.Operation.equal operation.id))
;;

let cancel_operation_permission t operation reason permission =
  if pending_for_operation t operation permission
  then Some (cancel_permission t reason permission)
  else None
;;

let interrupt_permission_review_job t reason (job : Agent_protocol.Job.t) =
  if is_permission_review_job job
  then (
    match job.status with
    | Running ->
      Some
        { job with
          status = Interrupted reason
        ; completed_at = Some (t.services.now ())
        ; delivery = Pending
        }
    | Queued ->
      Some
        { job with
          status = Cancelled
        ; completed_at = Some (t.services.now ())
        ; delivery = Pending
        }
    | Waiting_permission _
    | Waiting_completion _
    | Succeeded
    | Failed _
    | Cancelled
    | Interrupted _ -> None)
  else None
;;

(* Only genuine terminal/control writers call this helper with their exact final
   persisted records. Ordinary DTO changes remain negative-only reconciliation. *)
let prepare_terminal_job_custody t jobs =
  let open Result.Let_syntax in
  let%bind completed =
    List.map jobs ~f:(fun (terminal : Agent_protocol.Job.t) ->
      let%map previous =
        List.find t.state.jobs ~f:(fun job ->
          Agent_protocol.Id.Job.equal job.id terminal.id)
        |> Result.of_option ~error:(error Invalid_request "terminal Job was not found")
      in
      previous, terminal)
    |> Result.all
  in
  Job_custody.prepare_terminals t.job_agent_custody ~completed
;;

let operation_terminal_cleanup t operation outcome =
  let reason =
    match outcome with
    | Operation_worker.Completed _ -> None
    | Cancelled _ -> Some "operation was cancelled"
    | Failed failure -> Some ("operation failed: " ^ failure.message)
  in
  match reason with
  | None -> [], []
  | Some reason ->
    ( List.filter_map
        t.state.permissions
        ~f:(cancel_operation_permission t operation reason)
    , List.filter_map t.state.jobs ~f:(interrupt_permission_review_job t reason) )
;;

let cleanup_delta permissions jobs =
  Session_delta.Batch
    (List.map permissions ~f:(fun permission ->
       Session_delta.Permission_changed permission)
     @ List.map jobs ~f:(fun job -> Session_delta.Job_changed job))
;;

let cleanup_payloads permissions jobs =
  List.map permissions ~f:(fun permission ->
    Agent_protocol.Event.Durable.Payload.Permission_resolved permission)
  @ List.map jobs ~f:(fun job ->
    Agent_protocol.Event.Durable.Payload.Job_state_changed job)
;;

let compaction_generation t =
  if Int.equal t.state.conversation.compaction_generation Int.max_value
  then Error (error Invalid_state "compaction generation overflow")
  else Ok (t.state.conversation.compaction_generation + 1)
;;

let compaction_terminal_base_delta t operation = function
  | Compacted history ->
    let open Result.Let_syntax in
    let%bind generation = compaction_generation t in
    let%bind archive =
      t.persistence.archive_reference
        ~previous:t.state
        ~kind:Compaction
        operation.Agent_protocol.Operation.id
    in
    let history =
      History_codec.all_to_protocol
        ~previous:t.state.conversation.canonical_history
        history
    in
    let history_changes : Session_delta.t list =
      match t.state.recovery_windows with
      | None -> [ Compaction_archived archive; Canonical_history_replaced history ]
      | Some _ ->
        let capture =
          if
            Option.exists
              t.state.recovery_effective
              ~f:Recovery_effective_ledger.has_live_sources
          then `Canonical_and_effective
          else `Canonical
        in
        [ Recovery_summary_compacted (archive, history, capture) ]
    in
    let operation = operation_state t operation Agent_protocol.Operation.Completed in
    let lifecycle = terminal_lifecycle t in
    Ok
      ( Session_delta.Batch
          (history_changes
           @ [ Compaction_generation_changed generation
             ; Active_operation_changed None
             ; Lifecycle_changed lifecycle
             ])
      , [ Agent_protocol.Event.Durable.Payload.History_replaced
            (Session_state.history_window history)
        ; Operation_completed operation
        ; Session_state_changed
            { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
        ] )
  | Compaction_cancelled reason ->
    let operation = operation_state t operation Agent_protocol.Operation.Cancelled in
    let lifecycle = terminal_lifecycle t in
    Ok
      ( Session_delta.Batch [ Active_operation_changed None; Lifecycle_changed lifecycle ]
      , [ Agent_protocol.Event.Durable.Payload.Operation_cancelled operation
        ; Moderator_notification (`Object [ "cancellation_reason", `String reason ])
        ; Session_state_changed
            { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
        ] )
  | Compaction_failed failure ->
    let operation =
      operation_state t operation (Agent_protocol.Operation.Failed failure)
    in
    let lifecycle = terminal_lifecycle t in
    Ok
      ( Session_delta.Batch [ Active_operation_changed None; Lifecycle_changed lifecycle ]
      , [ Agent_protocol.Event.Durable.Payload.Operation_failed operation
        ; Session_state_changed
            { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
        ] )
;;

let compaction_terminal_delta t operation outcome =
  let open Result.Let_syntax in
  let%bind delta, payloads = compaction_terminal_base_delta t operation outcome in
  let%bind discarded =
    match outcome with
    | Compacted _ -> Ok []
    | Compaction_cancelled _ | Compaction_failed _ ->
      Observation_follow_up.discard_compaction
        t.state.invocations
        ~operation_id:operation.id
        ~reason:
          (match outcome with
           | Compaction_cancelled _ -> "compaction cancelled"
           | _ -> "compaction failed")
  in
  let%map events =
    match outcome with
    | Compacted _ -> Ok []
    | Compaction_cancelled _ | Compaction_failed _ ->
      Observation_follow_up.discard_event_compaction
        t.state.moderator_executions
        ~operation_id:operation.id
        ~reason:
          (match outcome with
           | Compaction_cancelled _ -> "compaction cancelled"
           | _ -> "compaction failed")
  in
  ( Session_delta.Batch
      (List.map discarded ~f:Observation_follow_up.delta
       @ List.map events ~f:Observation_follow_up.event_delta
       @ [ delta ])
  , payloads )
;;

let compaction_terminal ?idle_completion t operation_id outcome =
  match t.state.active_operation with
  | None -> Ok ()
  | Some operation when Agent_protocol.Id.Operation.compare operation.id operation_id <> 0
    -> Ok ()
  | Some operation ->
    let open Result.Let_syntax in
    let outcome =
      match operation.state with
      | Agent_protocol.Operation.Cancelling -> Compaction_cancelled "operation cancelled"
      | _ -> outcome
    in
    let%bind delta, payloads = compaction_terminal_delta t operation outcome in
    let%map _ =
      match
        ( transition
            ?idle_completion_step:
              (Option.map idle_completion ~f:(fun completion ->
                 completion, Idle_completion_write.Kind.Retire_compaction))
            t
            ~delta
            ~payloads
        , outcome )
      with
      | Ok session, _ -> Ok session
      | Error failure, Compacted _ ->
        let%bind delta, payloads =
          compaction_terminal_delta t operation (Compaction_failed failure)
        in
        transition
          ?idle_completion_step:
            (Option.map idle_completion ~f:(fun completion ->
               completion, Idle_completion_write.Kind.Retire_compaction))
          t
          ~delta
          ~payloads
      | Error failure, _ -> Error failure
    in
    t.active_cancel <- None
;;

let compaction_failure exn =
  let message =
    match exn with
    | Context_compaction.Summarizer.Failed No_text ->
      "history compaction failed: summarizer returned no text"
    | _ -> "history compaction failed: " ^ Exn.to_string exn
  in
  Agent_protocol.Error.create Internal_error ~message ~retryable:true ()
;;

exception Compaction_cancel_requested

let compute_compaction t operation selection port installed allocator history =
  let compute inference ~guidance ~reserved_input_tokens =
    match
      Context_compaction.Compactor.compact_entries_with_guidance
        ~guidance
        ~reserved_input_tokens
        ~inference
        ~allocator
        ~env:t.compaction_env
        ~history
    with
    | Error exn -> Error (compaction_failure exn)
    | Ok history ->
      (match History_entry.validate ~allocator history with
       | Ok () -> Ok history
       | Error message -> Error (error Conflict ("invalid compacted history: " ^ message)))
  in
  let result =
    match port, installed with
    | Some port, _ ->
      port.Compaction_inference.with_execution
        ~operation
        ~selection
        ~borrow_agent_actor:(fun () -> call t (Borrow_compaction_agent_actor operation))
        compute
    | None, Some inference ->
      let active =
        Option.value_map t.state.instruction_selection ~default:false ~f:(fun selection ->
          let status = Instruction_selection.summary selection in
          status.project_selected || status.skills > 0)
      in
      if active
      then
        Error
          (error
             Configuration_invalid
             "active instructions require an owned compaction guidance port")
      else compute inference ~guidance:None ~reserved_input_tokens:0
    | None, None ->
      Error (error Configuration_invalid "compaction requires selected runtime inference")
  in
  match result with
  | Ok history -> Compacted history
  | Error failure -> Compaction_failed failure
;;

let run_compaction t operation selection port installed allocator history =
  let operation_id = operation.Agent_protocol.Operation.id in
  try
    Eio.Switch.run (fun operation_switch ->
      let cancel () = Eio.Switch.fail operation_switch Compaction_cancel_requested in
      match call t ~priority:Priority (Worker_ready (Compaction operation_id, cancel)) with
      | Error failure -> Compaction_failed failure
      | Ok () ->
        Eio.Switch.check operation_switch;
        compute_compaction t operation selection port installed allocator history)
  with
  | Compaction_cancel_requested -> Compaction_cancelled "operation cancelled"
  | Eio.Cancel.Cancelled reason -> Compaction_cancelled (Exn.to_string reason)
  | exn -> Compaction_failed (compaction_failure exn)
;;

let launch_compaction t operation allocator history =
  let operation_id = operation.Agent_protocol.Operation.id in
  let selection = t.state.spec.inference_target in
  let port = t.compaction_inference in
  let installed = t.inference_execution in
  let admission =
    Option.bind
      t.operation_agent_custody
      ~f:(fun { Operation_owner.operation_id = owner; admission; _ } ->
        Option.some_if (Agent_protocol.Id.Operation.equal owner operation_id) admission)
  in
  Eio.Fiber.fork ~sw:t.sw (fun () ->
    let outcome =
      Exn.protect
        ~f:(fun () ->
          run_compaction t operation selection port installed allocator history)
        ~finally:(fun () -> Option.iter admission ~f:retire_agent_admission)
    in
    ignore
      (call t ~priority:Priority (Compaction_terminal (operation_id, outcome))
       : (unit, Agent_protocol.Error.t) result))
;;

let create_compaction_operation t =
  let timestamp = t.services.now () in
  Agent_protocol.Operation.
    { id = Agent_protocol.Id.Operation.create ()
    ; generation = t.state.identity.generation
    ; kind = Compaction
    ; state = Starting
    ; started_at = timestamp
    ; updated_at = timestamp
    }
;;

let int_of_history_sequence sequence =
  if Int64.(sequence > of_int Int.max_value)
  then Error (error Invalid_state "history sequence exceeds platform allocation range")
  else Ok (Int64.to_int_exn sequence)
;;

let compaction_allocator t first_sequence reserved_through =
  let open Result.Let_syntax in
  let%bind next_sequence = int_of_history_sequence first_sequence in
  let%bind limit_exclusive = int_of_history_sequence reserved_through in
  History_entry.Allocator.create_bounded
    ~namespace:(Agent_protocol.Id.Session.to_string t.state.identity.session_id)
    ~next_sequence
    ~limit_exclusive
  |> Result.map_error ~f:(fun message -> error Invalid_state message)
;;

let reconcile_foreground_invocations ?idle_completion ?(terminal = false) t =
  let open Result.Let_syntax in
  let first =
    Int64.max
      t.state.conversation.next_history_sequence
      t.state.conversation.reserved_history_through
  in
  let%bind first_sequence = int_of_history_sequence first in
  let%bind plan =
    Invocation_recovery.plan_foreground
      ~state:t.state
      ~namespace:(Agent_protocol.Id.Session.to_string t.state.identity.session_id)
      ~first_sequence
      ~reason:"foreground worker ended before recording the invocation outcome"
  in
  if List.is_empty plan.deltas
  then Ok ()
  else
    transition
      ?idle_completion_step:
        (Option.map idle_completion ~f:(fun completion ->
           ( completion
           , if terminal
             then Idle_completion_write.Kind.Reconcile_terminal
             else Reconcile_foreground )))
      t
      ~delta:
        (Session_delta.Batch
           (History_block_reserved (Int64.of_int plan.next_sequence) :: plan.deltas))
      ~payloads:
        (if List.is_empty plan.appended
         then []
         else [ Agent_protocol.Event.Durable.Payload.History_appended plan.appended ])
    |> Result.map ~f:(fun _ -> ())
;;

let retain_reconciliation_failure t failure =
  let lifecycle =
    Session_state.Lifecycle.
      { desired = t.state.lifecycle.desired; observed = Failed failure }
  in
  transition
    t
    ~delta:
      (Session_delta.Batch [ Failure_changed (Some failure); Lifecycle_changed lifecycle ])
    ~payloads:
      [ Agent_protocol.Event.Durable.Payload.Session_state_changed
          { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
      ]
  |> Result.map ~f:(fun _ -> ())
;;

let start_compaction
      ?idle_completion
      ?operation
      ?follow_up_authority
      ?agent_custody
      ?(extra_deltas : Session_delta.t list = [])
      t
  =
  let open Result.Let_syntax in
  let%bind () = require_runtime_admission t in
  let%bind () = reconcile_foreground_invocations ?idle_completion t in
  let revision = t.state.counters.revision in
  let first_sequence = t.state.conversation.next_history_sequence in
  if Int64.equal first_sequence Int64.max_value
  then Error (error Invalid_state "history sequence overflow")
  else (
    let reserved_through = Int64.(first_sequence + 1L) in
    let open Result.Let_syntax in
    let%bind allocator = compaction_allocator t first_sequence reserved_through in
    let%bind history =
      History_codec.all_of_protocol t.state.conversation.canonical_history
    in
    let operation =
      Option.value_or_thunk operation ~default:(fun () -> create_compaction_operation t)
    in
    let lifecycle = lifecycle_for_compaction t operation.id in
    let%bind child =
      match agent_custody with
      | None -> Ok None
      | Some custody -> Result.map (transfer_agent_custody custody) ~f:Option.some
    in
    let installed = ref false in
    Exn.protect
      ~f:(fun () ->
        let%bind () =
          prepare_idle_operation_suffix
            t
            idle_completion
            ~operation
            ~custody:child
            ~installed
            ~kind:(Idle_completion_data.Compaction (allocator, history))
        in
        let%bind session =
          transition
            ?idle_completion_step:
              (Option.map idle_completion ~f:(fun completion ->
                 completion, Idle_completion_write.Kind.Start_compaction))
            t
            ~check_before_commit:(fun () ->
              match follow_up_authority with
              | None -> Ok ()
              | Some authority ->
                let%bind () =
                  Option.value_map child ~default:(Ok ()) ~f:(fun custody ->
                    Execution_custody.actor custody |> Result.map ~f:ignore)
                in
                let%bind () = check_follow_up_authority t authority in
                if Int64.equal revision t.state.counters.revision
                then Ok ()
                else
                  Error
                    (error Conflict "observation compaction basis changed before commit"))
            ~delta:
              (Session_delta.Batch
                 (extra_deltas
                  @ [ Session_delta.History_block_reserved reserved_through
                    ; Active_operation_changed (Some operation)
                    ; Lifecycle_changed lifecycle
                    ]))
            ~payloads:
              [ Agent_protocol.Event.Durable.Payload.Operation_started operation
              ; Session_state_changed
                  { desired_state = lifecycle.desired
                  ; observed_state = lifecycle.observed
                  }
              ]
        in
        let%bind () = check_idle_operation_suffix t idle_completion operation in
        if Option.is_none idle_completion
        then install_operation_agent_custody t operation child;
        installed := true;
        launch_compaction t operation allocator history;
        handoff_idle_operation idle_completion;
        Ok session)
      ~finally:(fun () ->
        if not !installed then Option.iter child ~f:retire_agent_custody))
;;

let compact_internal t original_actor attachment_id expected_revision =
  let open Result.Let_syntax in
  let%bind () =
    match original_actor with
    | None -> Ok ()
    | Some actor when Operator_authorization.is_current actor -> Ok ()
    | Some _ -> Error (error Permission_denied "compaction authentication expired")
  in
  let%bind _ = write_attachment t attachment_id in
  let%bind () =
    match expected_revision with
    | None -> Ok ()
    | Some revision when Int64.equal revision t.state.counters.revision -> Ok ()
    | Some _ -> Error (error Conflict "session revision does not match")
  in
  match
    t.idle_moderator_borrowed, t.state.active_operation, t.state.lifecycle.observed
  with
  | true, _, _ -> Error (error Conflict "session moderator is processing background work")
  | false, Some _, _ -> Error (error Conflict "a foreground operation is already active")
  | false, None, (Idle | Stopped) ->
    let custody = Option.map original_actor ~f:create_agent_custody in
    Exn.protect
      ~f:(fun () -> start_compaction ?agent_custody:custody t)
      ~finally:(fun () -> Option.iter custody ~f:retire_agent_custody)
  | false, None, _ -> Error (error Invalid_state "session is not ready for compaction")
;;

let history_edit_precondition t revision =
  if not (Int64.equal revision t.state.counters.revision)
  then Error (error Conflict "session revision does not match")
  else if t.idle_moderator_borrowed || Option.is_some t.state.active_operation
  then Error (error Conflict "history cannot change during active work")
  else (
    match t.state.lifecycle.observed with
    | Idle | Stopped -> Ok ()
    | _ -> Error (error Invalid_state "session is not ready for history editing"))
;;

let history_command_precondition t session_id attachment_id generation revision =
  let open Result.Let_syntax in
  let%bind () =
    if Agent_protocol.Id.Session.equal session_id t.state.identity.session_id
    then Ok ()
    else Error (error Invalid_request "history command targets a different session")
  in
  let%bind _ = write_attachment t attachment_id in
  let%bind () =
    if Int.equal generation t.state.identity.generation
    then Ok ()
    else Error (error Conflict "session generation does not match")
  in
  let%bind () = history_edit_precondition t revision in
  if
    Option.is_some t.moderator_borrow
    || Option.is_some t.queued_event_borrow
    || Option.is_some t.initialization_scope
    || Option.is_some t.runtime_retirement
    || List.exists t.invocation_executions ~f:(fun execution ->
      match execution.owner with
      | Foreground _ | Invocation_moderator _ | Event_moderator _ -> true
      | Background_job _ -> false)
  then
    Error
      (error
         Conflict
         "history cannot change while a foreground or runtime owner is active")
  else Ok ()
;;

let outcome_requests_compaction = function
  | Operation_worker.Completed summary ->
    List.exists summary.runtime_requests ~f:(function
      | Chat_response.Moderation.Runtime_request.Request_compaction -> true
      | Request_turn | End_session _ -> false)
  | Cancelled _ | Failed _ -> false
;;

let follow_up_deltas t (plan : Observation_follow_up.t) =
  List.map plan.invocations ~f:(fun invocation ->
    match Int.equal invocation.context.generation t.state.identity.generation with
    | true -> Session_delta.Invocation_changed invocation
    | false -> Session_delta.Invocation_reconciled invocation)
  @ List.map plan.events ~f:Observation_follow_up.event_delta
;;

let managed_moderator t operation_id =
  let open Result.Let_syntax in
  let%bind observer =
    match t.foreground_moderator with
    | Some (id, observer) when Agent_protocol.Id.Operation.equal id operation_id ->
      Ok observer
    | _ -> Error (error Conflict "foreground moderator routing is not installed")
  in
  let%bind installed = Runtime_builder.moderator_snapshot_observer t.state.moderator in
  match installed with
  | Some installed when Agent_protocol.Invocation.equal_observer observer installed ->
    Ok observer
  | _ -> Error (error Conflict "foreground moderator source changed")
;;

let manage_moderator_follow_up t operation_id observer =
  let open Result.Let_syntax in
  let%bind _ = running_operation t operation_id in
  let%bind installed = Runtime_builder.moderator_snapshot_observer t.state.moderator in
  match installed with
  | Some installed when Agent_protocol.Invocation.equal_observer observer installed ->
    t.foreground_moderator <- Some (operation_id, observer);
    Ok ()
  | _ -> Error (error Conflict "foreground routing requires the installed moderator")
;;

let admit_moderator_turn t operation_id =
  let open Result.Let_syntax in
  let%bind () = require_selected_execution t in
  let%bind operation = running_operation t operation_id in
  let%bind observer = managed_moderator t operation_id in
  let%bind halted = Runtime_builder.moderator_snapshot_is_halted t.state.moderator in
  let%bind () =
    match halted, moderator_is_borrowed t with
    | true, _ -> Error (error Conflict "halted moderator cannot admit a provider request")
    | false, true ->
      Error (error Conflict "provider admission cannot interrupt a moderator event")
    | false, false -> Ok ()
  in
  let%bind plan = Observation_follow_up.admit_turn ~state:t.state ~observer in
  let%bind notifications = notification_wake_deltas t operation_id ~accept:true in
  let%bind run_deltas = run_turn_deltas t operation plan.events [] in
  match follow_up_deltas t plan @ notifications @ run_deltas with
  | [] -> Ok ()
  | deltas ->
    transition t ~delta:(Session_delta.Batch deltas) ~payloads:[] |> Result.map ~f:ignore
;;

let admit_notification_turn t operation_id =
  let open Result.Let_syntax in
  let%bind () = require_selected_execution t in
  let%bind _ = running_operation t operation_id in
  let%bind () =
    match t.state.lifecycle.desired, t.state.halted, moderator_is_borrowed t with
    | Running, false, false -> Ok ()
    | _ -> Error (error Conflict "session cannot admit a provider request")
  in
  let%bind deltas = notification_wake_deltas t operation_id ~accept:true in
  match deltas with
  | [] -> Ok ()
  | _ ->
    transition t ~delta:(Session_delta.Batch deltas) ~payloads:[] |> Result.map ~f:ignore
;;

let foreground_terminal_requests t operation_id outcome =
  let open Result.Let_syntax in
  match t.foreground_moderator with
  | None -> Ok []
  | Some _ ->
    let%bind observer = managed_moderator t operation_id in
    let end_reason, failed =
      match outcome with
      | Operation_worker.Completed summary ->
        end_session_reason summary.runtime_requests, false
      | Failed _ | Cancelled _ -> None, true
    in
    let%map plan =
      match end_reason with
      | None ->
        Observation_follow_up.finish_foreground
          ~state:t.state
          ~observer
          ~operation_id
          ~failed
      | Some _ ->
        Observation_follow_up.plan
          ~state:t.state
          ~observer:(Some observer)
          ~halted:true
          ~compaction_operation_id:(Agent_protocol.Id.Operation.create ())
    in
    follow_up_deltas t plan
;;

let worker_terminal
      ?idle_completion
      ?check_before_commit
      t
      operation_id
      outcome
      compaction_custody
  =
  match t.state.active_operation with
  | None -> Ok ()
  | Some operation when Agent_protocol.Id.Operation.compare operation.id operation_id <> 0
    -> Ok ()
  | Some operation ->
    let open Result.Let_syntax in
    let publication = t.foreground_publication in
    let belongs operation =
      Option.exists operation ~f:(Agent_protocol.Id.Operation.equal operation_id)
    in
    let borrow =
      Option.filter t.moderator_borrow ~f:(fun borrow -> belongs borrow.operation_id)
    in
    let event_borrow =
      Option.filter t.queued_event_borrow ~f:(fun borrow ->
        belongs borrow.receipt.context.operation_id)
    in
    let foreground, independent =
      List.partition_tf t.invocation_executions ~f:(fun execution ->
        match execution.owner with
        | Foreground id -> Agent_protocol.Id.Operation.equal id operation_id
        | Invocation_moderator borrow -> belongs borrow.operation_id
        | Event_moderator borrow -> belongs borrow.receipt.context.operation_id
        | Background_job _ -> false)
    in
    let%bind unfinished =
      List.map foreground ~f:(fun execution ->
        execution.accepts_children <- false;
        Atomic.set execution.authority_live false;
        abort_staged_work t ~owner:(Invocation execution.dispatched.context.id);
        Agent_protocol.Invocation.cancel
          execution.dispatched
          ~reason:"worker exited before recording the invocation outcome"
        |> Result.map ~f:(fun invocation -> Session_delta.Invocation_changed invocation))
      |> Result.all
    in
    let%bind borrow_delta =
      match borrow with
      | None -> Ok (Session_delta.Batch [])
      | Some borrow ->
        abort_staged_work t ~owner:(Invocation borrow.invocation.context.id);
        uncommitted_borrow_delta
          t
          borrow
          (Some
             (Agent_protocol.Invocation.Cancelled
                "worker exited with an active moderator borrow"))
    in
    let%bind event_delta =
      match event_borrow with
      | Some borrow when not borrow.committed ->
        abort_staged_work t ~owner:(Moderator_event borrow.receipt.context.id);
        let%map interrupted =
          Agent_protocol.Moderator_execution.interrupt
            borrow.receipt
            ~reason:"worker exited before recording its moderator event"
        in
        Session_delta.Moderator_execution_changed interrupted
      | _ -> Ok (Session_delta.Batch [])
    in
    let outcome =
      match
        ( Option.is_some borrow
          || Option.is_some event_borrow
          || not (List.is_empty unfinished)
        , outcome )
      with
      | true, Operation_worker.Completed _ ->
        Operation_worker.Failed
          (error Internal_error "worker completed with an active invocation")
      | _ -> outcome
    in
    let run_outcome : Agent_protocol.Run_work.Terminal.outcome =
      match outcome with
      | Operation_worker.Completed _ -> Succeeded
      | Cancelled _ -> Cancelled
      | Failed _ -> Failed
    in
    let now, completion_sample = completion_clock_pair t in
    let%bind run_deltas =
      Run_transition.settle_operation
        ?startup_run:(pending_held_startup_run t)
        t.state
        ~operation_id
        ~outcome:run_outcome
        ~now
    in
    let%bind delta, payloads = terminal_delta t operation outcome in
    let%bind follow_up = foreground_terminal_requests t operation_id outcome in
    let%bind notifications = notification_wake_deltas t operation_id ~accept:false in
    let permissions, jobs = operation_terminal_cleanup t operation outcome in
    let%bind job_custody = prepare_terminal_job_custody t jobs in
    let%bind _ =
      transition
        ?check_before_commit
        ?idle_completion_step:
          (Option.map idle_completion ~f:(fun completion ->
             completion, Idle_completion_write.Kind.Retire_turn))
        ~completion_sample
        ~job_custody
        t
        ~delta:
          (Session_delta.Batch
             (notifications
              @ follow_up
              @ unfinished
              @ run_deltas
              @ [ borrow_delta; event_delta; delta; cleanup_delta permissions jobs ]))
        ~payloads:(payloads @ cleanup_payloads permissions jobs)
    in
    resolve_cleaned_permission_waiters t permissions;
    Option.iter borrow ~f:(fun _ -> t.moderator_borrow <- None);
    Option.iter event_borrow ~f:(fun borrow ->
      borrow.callback_active <- false;
      Atomic.set borrow.authority_live false;
      borrow.cancel <- None);
    Option.iter event_borrow ~f:(fun _ -> t.queued_event_borrow <- None);
    t.foreground_moderator <- None;
    t.notification_inputs <- None;
    t.idle_moderator_borrowed <- Option.is_some idle_completion || moderator_is_borrowed t;
    t.invocation_executions <- independent;
    t.active_cancel <- None;
    if Option.equal phys_equal publication t.foreground_publication
    then (
      t.live_operator_rollover <- None;
      t.foreground_publication <- None);
    (match t.state.lifecycle.desired, t.state.halted with
     | Stopped, _ | _, true -> cancel_independent_moderator t
     | Running, false -> ());
    let%bind () =
      match reconcile_foreground_invocations ?idle_completion ~terminal:true t with
      | Ok () -> Ok ()
      | Error failure ->
        (match idle_completion with
         | Some _ -> Error failure
         | None ->
           let%bind () = retain_reconciliation_failure t failure in
           Error failure)
    in
    if runtime_admission_open t && outcome_requests_compaction outcome
    then
      Result.map (start_compaction ?agent_custody:compaction_custody t) ~f:(fun _ -> ())
    else Ok ()
;;

let worker_publication_terminal
      t
      (publication : Foreground_publication.t)
      outcome
      compaction_custody
  =
  let operation_id = publication.operation.id in
  if foreground_publication_matches t publication
  then (
    let cancelled =
      Option.exists t.state.active_operation ~f:(fun operation ->
        match operation.state with
        | Cancelling -> true
        | Starting | Running | Completed | Failed _ | Cancelled | Interrupted _ -> false)
    in
    let outcome =
      match cancelled, outcome with
      | true, Operation_worker.Completed _ ->
        Operation_worker.Cancelled { reason = "operation cancelled" }
      | _ -> outcome
    in
    record_runtime_terminal t operation_id publication.completion (fun () ->
      let check_before_commit () = check_foreground_publication t publication in
      worker_terminal ~check_before_commit t operation_id outcome compaction_custody))
  else (
    (* A displaced worker still owns its original factual return. In particular,
       a stale result cannot close a completion slot reused by the successor. *)
    match publication.completion with
    | Some original
      when not (Option.exists t.operation_completion ~f:(phys_equal original)) ->
      record_runtime_terminal t operation_id (Some original) (fun () -> Ok ())
    | Some _ | None -> Ok ())
;;

let cancel_operation_internal t attachment_id operation_id =
  let open Result.Let_syntax in
  let%bind _ = write_attachment t attachment_id in
  let%bind operation = current_operation t operation_id in
  match operation.state with
  | Completed | Failed _ | Cancelled | Interrupted _ ->
    Error (error Already_resolved "operation is already terminal")
  | Cancelling -> Ok (Session_state.summary t.state)
  | Starting | Running ->
    let operation = operation_state t operation Cancelling in
    let%bind session =
      transition
        t
        ~delta:(Session_delta.Active_operation_changed (Some operation))
        ~payloads:
          [ Agent_protocol.Event.Durable.Payload.Session_updated
              (summary_with_operation t operation)
          ]
    in
    cancel_event_for_operation t operation.id;
    Option.iter t.active_cancel ~f:(fun cancel -> cancel ());
    Ok session
;;

let worker_failure exn =
  Agent_protocol.Error.create
    Internal_error
    ~message:("foreground worker failed: " ^ Exn.to_string exn)
    ~retryable:true
    ()
;;

let publish_worker_live t buffer payload =
  let event =
    Live_event_buffer.publish
      buffer
      ~anchor_sequence:(Atomic.get t.event_sequence)
      ~timestamp:(t.services.now ())
      ~payload
  in
  match event with
  | Ok event -> broadcast_recoverable t event
  | Error error ->
    raise_s [%message "invalid worker transcript event" (error : Agent_protocol.Error.t)]
;;

let refresh_held_permission t (permission : Agent_protocol.Permission.t) =
  match permission.owner with
  | Operation _ -> Ok ()
  | Invocation id ->
    Option.value_map
      (List.find t.invocation_executions ~f:(fun execution ->
         Agent_protocol.Id.Invocation.equal execution.dispatched.context.id id))
      ~default:(Ok ())
      ~f:(fun execution -> refresh_held_execution t (Inference_invocation execution))
;;

let refresh_held_permission_resolution t permission_id choice =
  match choice with
  | Agent_protocol.Permission.Deny -> Ok ()
  | Approve_once | Approve_session | Approve_prefix | Durable_exact ->
    Option.value_map
      (List.find t.state.permissions ~f:(fun permission ->
         Agent_protocol.Id.Permission.equal permission.id permission_id))
      ~default:(Ok ())
      ~f:(refresh_held_permission t)
;;

let request_review_internal t ~permission ~review =
  let open Result.Let_syntax in
  let%bind () = refresh_held_permission t permission in
  let%bind response =
    call t (Open_permission (permission, None, Agent_protocol.Permission.Deny))
  in
  let choice, reason =
    match review () with
    | Ok Permission_reviewer.Decision.Allow ->
      Agent_protocol.Permission.Approve_once, None
    | Ok (Deny message) -> Agent_protocol.Permission.Deny, Some message
    | Error (error : Permission_reviewer.Error.t) ->
      Agent_protocol.Permission.Deny, Some error.message
  in
  let%bind () = refresh_held_permission_resolution t permission.id choice in
  let%bind (_ : Agent_protocol.Permission.t) =
    call
      t
      ~priority:Priority
      (Resolve_permission_system (permission.id, permission.generation, choice, reason))
  in
  Ok (Eio.Promise.await response)
;;

let review_resolution review =
  match review () with
  | Ok Permission_reviewer.Decision.Allow -> Agent_protocol.Permission.Approve_once, None
  | Ok (Deny message) -> Agent_protocol.Permission.Deny, Some message
  | Error (failure : Permission_reviewer.Error.t) ->
    Agent_protocol.Permission.Deny, Some failure.message
;;

let timeout_review t (permission : Agent_protocol.Permission.t) response seconds review =
  t.sleep seconds;
  let choice, reason = review_resolution review in
  let open Result.Let_syntax in
  let%bind () = refresh_held_permission_resolution t permission.id choice in
  let%bind (_ : Agent_protocol.Permission.t) =
    call
      t
      ~priority:Priority
      (Resolve_permission_system (permission.id, permission.generation, choice, reason))
  in
  Ok (Eio.Promise.await response)
;;

let request_permission_with_review_internal
      t
      ~permission
      ~timeout_seconds
      ~fallback
      ~review_on_timeout
  =
  let open Result.Let_syntax in
  let actor_timeout =
    if t.schedule_permission_timeouts && Option.is_none review_on_timeout
    then timeout_seconds
    else None
  in
  let%bind () = refresh_held_permission t permission in
  let%bind response = call t (Open_permission (permission, actor_timeout, fallback)) in
  match t.schedule_permission_timeouts, timeout_seconds, review_on_timeout with
  | true, Some seconds, Some review ->
    Eio.Fiber.first
      (fun () -> Ok (Eio.Promise.await response))
      (fun () -> timeout_review t permission response seconds review)
  | (false | true), _, _ -> Ok (Eio.Promise.await response)
;;

let check_invocation_effect_owner t execution invocation =
  let open Result.Let_syntax in
  let%bind () =
    if Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Conflict "invocation effect belongs to another Actor domain")
  in
  let%bind () =
    if
      Atomic.get execution.authority_live
      && List.mem t.invocation_executions execution ~equal:phys_equal
      && Agent_protocol.Invocation.equal execution.dispatched invocation
    then Ok ()
    else
      Error
        (error
           Permission_denied
           "agent authority belongs to another or expired invocation")
  in
  let%bind owner_current =
    match execution.owner with
    | Foreground id ->
      let%map _ = running_operation t id in
      fun () -> true
    | Background_job scope ->
      let%map () = job_scope_can_execute t scope in
      fun () -> Atomic.get scope.authority_live
    | Invocation_moderator borrow ->
      let%bind () = validate_moderator_borrow t borrow in
      let%map () =
        match borrow.job_scope with
        | Some scope -> job_scope_can_execute t scope
        | None ->
          (match borrow.operation_id with
           | None -> Ok ()
           | Some id -> Result.map (running_operation t id) ~f:ignore)
      in
      fun () ->
        Atomic.get borrow.authority_live
        && Option.for_all borrow.job_scope ~f:(fun scope ->
          Atomic.get scope.authority_live)
    | Event_moderator borrow ->
      let%bind () = validate_queued_event_borrow t borrow in
      let%map () =
        match borrow.job_scope with
        | Some scope -> job_scope_can_execute t scope
        | None ->
          (match borrow.receipt.context.operation_id with
           | None -> Ok ()
           | Some id -> Result.map (running_operation t id) ~f:ignore)
      in
      fun () ->
        Atomic.get borrow.authority_live
        && Option.for_all borrow.job_scope ~f:(fun scope ->
          Atomic.get scope.authority_live)
  in
  Ok owner_current
;;

let check_invocation_effect_current t execution invocation =
  let open Result.Let_syntax in
  let%bind owner_current = check_invocation_effect_owner t execution invocation in
  let%map () = check_execution_descendant t (Inference_invocation execution) in
  owner_current
;;

let refresh_invocation_effect_current t execution invocation =
  let open Result.Let_syntax in
  let%bind owner_current = check_invocation_effect_owner t execution invocation in
  let%bind () =
    if owner_current ()
    then Ok ()
    else Error (error Conflict "invocation effect owner expired before refresh")
  in
  let%bind () = refresh_execution_descendant t (Inference_invocation execution) in
  let%bind owner_current = check_invocation_effect_current t execution invocation in
  if owner_current ()
  then Ok ()
  else Error (error Conflict "invocation effect owner expired during refresh")
;;

let check_moderator_effect_owner t (borrow : moderator_borrow) invocation =
  let open Result.Let_syntax in
  let%bind () =
    if Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Conflict "moderator effect belongs to another Actor domain")
  in
  let%bind () = validate_moderator_borrow t borrow in
  if
    Agent_protocol.Invocation.equal borrow.invocation invocation
    && Atomic.get borrow.authority_live
  then Ok ()
  else Error (error Permission_denied "effect belongs to another or expired moderator")
;;

let check_moderator_effect_current t borrow invocation =
  let%bind.Result () = check_moderator_effect_owner t borrow invocation in
  check_execution_descendant t (Inference_moderator borrow)
;;

let refresh_moderator_effect_current t borrow invocation =
  let open Result.Let_syntax in
  let%bind () = check_moderator_effect_owner t borrow invocation in
  let%bind () = refresh_execution_descendant t (Inference_moderator borrow) in
  check_moderator_effect_current t borrow invocation
;;

let invocation_agent_actor t execution invocation =
  let open Result.Let_syntax in
  let%bind owner_current = check_invocation_effect_current t execution invocation in
  let%bind () =
    if execution.accepts_children
    then Ok ()
    else
      Error
        (error
           Permission_denied
           "agent authority belongs to another or expired invocation")
  in
  let%bind actor =
    let%bind custody = execution_agent_custody t execution in
    match custody with
    | None -> Ok None
    | Some custody -> Result.map (Execution_custody.actor custody) ~f:Option.some
  in
  Ok
    (Option.map actor ~f:(fun actor ->
       Operator_authorization.restrict
         actor
         ~is_current:(fun () ->
           Atomic.get execution.authority_live
           && Result.is_ok (check_execution_descendant t (Inference_invocation execution))
           && owner_current ())))
;;

(* Caller preparation is a fresh-effect boundary. Existing settlement selectors
   preserve negative facts without invoking original guards; only their actual
   Available admission may be transported as a usable original. *)
let policy_caller_admission parent =
  let open Result.Let_syntax in
  let%bind parent = parent in
  match (parent : Observation_continuation.Parent.t) with
  | Available admission -> Ok (Some admission)
  | Expired ->
    Error (error Permission_denied "delegated policy Caller original custody expired")
  | Unavailable ->
    Error
      (error Permission_denied "delegated policy Caller original custody is unavailable")
;;

(* A resumed Run with no authenticated original is independently admitted by
   the actual Run binding. Missing contextual/queue custody has no such issuer. *)
let event_policy_caller_admission t (borrow : queued_event_borrow) =
  match borrow.agent_admission with
  | Resumed_run admission | Delegated_policy admission -> Ok admission
  | Selected_queue (Some admission) -> Ok (Some admission)
  | Selected_queue None ->
    policy_caller_admission (Ok Observation_continuation.Parent.Unavailable)
  | Contextual _ -> policy_caller_admission (event_settlement_parent t borrow)
;;

let invocation_policy_caller_admission t (execution : invocation_execution) =
  match execution.owner with
  | Event_moderator borrow -> event_policy_caller_admission t borrow
  | Foreground _ | Invocation_moderator _ | Background_job _ ->
    policy_caller_admission (execution_settlement_parent t execution)
;;

module Policy_caller_governance = struct
  module Data = Delegated_policy_governance_data
  module Cause = Policy_cause_data
  module PC = Policy_canonical_usage

  type actor = t

  let inherited_origin (actor : actor) =
    match actor.state.goal_descendants with
    | Some accounting -> Goal_descendants.origin accounting
    | None ->
      if Option.is_none actor.state.spec.delegation
      then Some Agent_store.Delegation_goal_origin.unrelated
      else None
  ;;

  let local_of_run (actor : actor) run =
    let open Result.Let_syntax in
    let%bind local = Goal_work_attribution.of_run actor.state run in
    match local with
    | None -> Ok None
    | Some local ->
      Cause.Goal_target.local
        ~goal_id:(Goal_work_attribution.goal_id local)
        ~episode:(Goal_work_attribution.episode local)
      |> Result.map ~f:Option.some
  ;;

  let association_of_origin (actor : actor) ~origin ~retained =
    let open Result.Let_syntax in
    match origin, retained with
    | Some (Agent_protocol.Inference_origin.Run id), retained ->
      let%bind run =
        Option.bind actor.state.run_state ~f:(fun index -> Run_state.find index id)
        |> Result.of_option
             ~error:(error Conflict "policy Caller Run association is unavailable")
      in
      let%bind () =
        match retained with
        | None -> Ok ()
        | Some (parent : Goal_work_attribution.Retained_parent.t) ->
          if Agent_protocol.Id.Run.equal parent.run.id id
          then Ok ()
          else Error (error Conflict "policy Caller has conflicting native Run parents")
      in
      let%map local = local_of_run actor run in
      Agent_protocol.Inference_origin.Run id, local
    | Some Unbound, None -> Ok (Agent_protocol.Inference_origin.Unbound, None)
    | Some Unbound, Some _ ->
      Error (error Conflict "policy Caller unbound origin contradicts retained Run work")
    | None, (None | Some _) ->
      Error (error Permission_denied "policy Caller immutable Run origin is unavailable")
  ;;

  let association (actor : actor) (owner : Delegated_policy_caller_custody.Owner.t) =
    let open Result.Let_syntax in
    match owner with
    | Operation id ->
      let%bind work =
        Agent_protocol.Run_work.create
          ~key:(Operation id)
          ~generation:actor.state.identity.generation
      in
      let%bind run = Goal_work_attribution.run_of_work actor.state work in
      (match run with
       | None -> Ok (Agent_protocol.Inference_origin.Unbound, None)
       | Some run ->
         let%map local = local_of_run actor run in
         Agent_protocol.Inference_origin.Run run.id, local)
    | Invocation id ->
      let%bind invocation =
        List.find actor.state.invocations ~f:(fun invocation ->
          Agent_protocol.Id.Invocation.equal invocation.context.id id)
        |> Result.of_option
             ~error:(error Conflict "policy Caller Invocation is unavailable")
      in
      let%bind retained =
        Goal_work_attribution.Retained_parent.of_invocation actor.state invocation
      in
      association_of_origin actor ~origin:invocation.inference_origin ~retained
    | Moderator_event id ->
      let%bind event =
        List.find actor.state.moderator_executions ~f:(fun event ->
          Agent_protocol.Id.Moderator_execution.equal event.context.id id)
        |> Result.of_option ~error:(error Conflict "policy Caller Event is unavailable")
      in
      let%bind retained =
        Goal_work_attribution.Retained_parent.of_event actor.state event
      in
      let%bind origin = event_inference_origin actor event in
      association_of_origin actor ~origin ~retained
  ;;

  let work (owner : Delegated_policy_caller_custody.Owner.t) =
    match owner with
    | Operation id -> Data.Work.Root_operation id
    | Invocation id -> Member (Cause.Allocation_work.Invocation id)
    | Moderator_event id -> Member (Cause.Allocation_work.Event id)
  ;;

  let forwarding (actor : actor) work =
    let open Result.Let_syntax in
    match actor.state.policy_canonical_usage with
    | None -> Error (error Invalid_state "policy Caller Cause has no retained carrier")
    | Some accounting ->
      let%bind context = Session_state.policy_context actor.state in
      PC.capture_forwarding accounting ~context ~work |> Result.map ~f:Option.some
  ;;

  let incoming (actor : actor) ~owner ~source work =
    let open Result.Let_syntax in
    match work with
    | Data.Work.Root_operation _ -> Ok None
    | Member work ->
      let%bind prefix =
        PC.Source.Native_prefix.create
          ~session_id:actor.state.identity.session_id
          ~generation:actor.state.identity.generation
          ~current_source:source
          ~events:actor.state.moderator_executions
          ~invocations:actor.state.invocations
          ~jobs:actor.state.jobs
          ~runs:actor.state.run_state
      in
      let%bind member =
        Cause.Allocation_work.member work ~generation:actor.state.identity.generation
      in
      let%bind boundary = policy_boundary_of_caller_owner actor owner in
      (match boundary with
       | None ->
         let%bind cause =
           PC.Source.cause actor.state.policy_canonical_usage ~prefix ~member
         in
         (match cause with
          | None -> Ok None
          | Some _ -> forwarding actor work)
       | Some boundary ->
         let%bind resolution =
           Policy_canonical_usage_source.Standalone.resolve
             actor.state.policy_canonical_usage
             ~prefix
             ~member
             ~boundary
         in
         (match resolution with
          | Unrelated | Standalone_unrelated _ -> Ok None
          | Caused _ -> forwarding actor work))
  ;;

  let source_frame (actor : actor) =
    let open Result.Let_syntax in
    let%bind checkpoint = Moderator_checkpoint.decode actor.state.moderator in
    match checkpoint with
    | None -> Policy_standalone_source.Source.create ~observer:None ~installation:None
    | Some checkpoint ->
      let observer : Agent_protocol.Invocation.observer =
        { script_id = checkpoint.script_id
        ; source_sha256 = checkpoint.script_source_hash
        }
      in
      let%bind installation = observation_source_for_checkpoint actor checkpoint in
      Policy_standalone_source.Source.create ~observer:(Some observer) ~installation
  ;;

  let standalone_subject (actor : actor) = function
    | Data.Work.Root_operation id ->
      Ok (Policy_standalone_source.Subject.Root_operation id)
    | Member work ->
      Cause.Allocation_work.member work ~generation:actor.state.identity.generation
      |> Result.map ~f:(fun member -> Policy_standalone_source.Subject.Member member)
  ;;

  let capture (actor : actor) owner =
    let open Result.Let_syntax in
    (* The caller checks the Actor domain before any mutable Actor field is read.
       This function captures DATA only; negative results do not veto factual
       callback issuance and never become an unrelated descriptor. *)
    let%bind origin, local = association actor owner in
    let work = work owner in
    let%bind frame = source_frame actor in
    let source = frame.Policy_standalone_source.Source.installation in
    let%bind incoming = incoming actor ~owner ~source work in
    let inherited = inherited_origin actor in
    match actor.recurrence_controller with
    | None ->
      if
        Option.is_none actor.state.spec.delegation
        && Option.is_none local
        && Option.is_none actor.state.policy_canonical_usage
        && Option.exists inherited ~f:(fun origin ->
          List.is_empty (Agent_store.Delegation_goal_origin.scopes origin))
        && Option.is_none incoming
      then (
        let%bind subject = standalone_subject actor work in
        let%map descriptor =
          Policy_standalone_source.create
            ~session_id:actor.state.identity.session_id
            ~generation:actor.state.identity.generation
            ~subject
            ~origin
            ~source:frame
        in
        Data.Standalone_unrelated descriptor)
      else
        Error (error Permission_denied "governing policy Caller has no actual controller")
    | Some controller ->
      let%bind source_owner =
        Result.of_option
          actor.runtime_source_owner
          ~error:
            (error Permission_denied "policy Caller Factory source issuer is unavailable")
      in
      let%bind source =
        match source with
        | Some source -> Cause.Caller_source.installed source
        | None ->
          (match actor.unmoderated_source, actor.operation_worker with
           | Some binding, Some worker ->
             Runtime_builder.Unmoderated_source.Binding.check
               binding
               ~state:actor.state
               ~worker
               ~manager:actor.moderator_manager
           | None, _ | Some _, None ->
             Error
               (error Permission_denied "policy Caller verified source is unavailable"))
      in
      let owner = Recurrence_controller.session controller in
      let%bind () =
        if
          Agent_protocol.Id.Session.equal
            (Agent_protocol.Session_ref.session_id owner)
            actor.state.identity.session_id
        then Ok ()
        else Error (error Conflict "policy Caller controller belongs to another session")
      in
      Ok
        (Data.Registered
           { owner; source; source_owner; work; origin; local; inherited; incoming })
  ;;
end

let capture_policy_caller t ~owner ~admission ~check_current =
  let open Result.Let_syntax in
  let%bind () =
    if Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Conflict "delegated policy Caller belongs to another Actor domain")
  in
  let generation = t.state.identity.generation in
  let governance = Policy_caller_governance.capture t owner in
  let unmoderated_source =
    match governance with
    | Ok (Delegated_policy_governance_data.Registered data) ->
      (match Policy_cause_data.Caller_source.view data.source with
       | Installed _ -> None
       | Unmoderated _ -> t.unmoderated_source)
    | Ok (Standalone_unrelated _) | Error _ -> None
  in
  let current () =
    let%bind () =
      if t.stopped || not (Int.equal generation t.state.identity.generation)
      then Error (error Conflict "delegated policy Caller source lifetime ended")
      else check_current ()
    in
    match unmoderated_source with
    | None -> Ok ()
    | Some binding ->
      let%bind worker =
        match t.unmoderated_source, t.operation_worker with
        | Some current, Some worker when phys_equal current binding -> Ok worker
        | Some _, (Some _ | None) | None, (Some _ | None) ->
          Error (error Conflict "delegated policy Caller lost its exact source binding")
      in
      Runtime_builder.Unmoderated_source.Binding.check
        binding
        ~state:t.state
        ~worker
        ~manager:t.moderator_manager
      |> Result.map ~f:ignore
  in
  Delegated_policy_caller_custody.Host.capture
    ~issuer:t.inference_owner_identity
    ~domain:t.runtime_source_domain
    ~session_id:t.state.identity.session_id
    ~generation
    ~owner
    ~admission:(admission ())
    ~governance
    ~check_current:current
;;

let check_delegated_policy_caller t (request : Script_tool_calls.preparation) =
  let open Result.Let_syntax in
  let%bind () =
    if Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Conflict "delegated policy Caller belongs to another Actor domain")
  in
  match request.caller with
  | None -> Error (error Permission_denied "delegated policy Caller is unavailable")
  | Some caller ->
    let owner : Delegated_policy_caller_custody.Owner.t =
      match request.owner with
      | Model_call (operation, _) -> Operation operation
      | Native_call invocation -> Invocation invocation
      | Moderator_event event -> Moderator_event event
    in
    Delegated_policy_caller_custody.Host.check_owner
      caller
      ~issuer:t.inference_owner_identity
      ~session_id:request.session_id
      ~generation:request.generation
      ~owner
;;

module Causal_governance = struct
  type actor = t

  include Causal_governance_binding

  type captured =
    { issuer : unit ref
    ; domain : int
    ; request : Script_tool_calls.preparation
    ; state : Session_state.t
    ; owner : Delegated_policy_caller_custody.Owner.t
    ; data : Data.t
    }

  let on_domain (actor : actor) =
    if Int.equal actor.runtime_source_domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Conflict "policy governance belongs to another Actor domain")
  ;;

  let owner (request : Script_tool_calls.preparation) =
    match request.owner with
    | Model_call (operation, _) ->
      Delegated_policy_caller_custody.Owner.Operation operation
    | Native_call invocation -> Invocation invocation
    | Moderator_event event -> Moderator_event event
  ;;

  let current_data actor request expected_owner =
    let open Result.Let_syntax in
    let%bind () = on_domain actor in
    let%bind () =
      if
        (not actor.stopped)
        && Option.is_none (Eio.Promise.peek actor.finished)
        && Option.is_none actor.lifecycle_fence
        && Option.is_none actor.runtime_retirement
      then Ok ()
      else Error (error Conflict "policy governance child source is retiring")
    in
    let%bind () = check_delegated_policy_caller actor request in
    let%bind caller =
      Result.of_option
        request.caller
        ~error:(error Permission_denied "policy governance Caller is unavailable")
    in
    let%bind frozen =
      Delegated_policy_caller_custody.Host.governance
        caller
        ~issuer:actor.inference_owner_identity
        ~session_id:request.session_id
        ~generation:request.generation
        ~owner:expected_owner
    in
    let%bind actual = Policy_caller_governance.capture actor expected_owner in
    if Data.equal actual frozen
    then Ok frozen
    else
      Error (error Conflict "policy Caller source or immutable work association changed")
  ;;

  let capture (actor : actor) ~request =
    let open Result.Let_syntax in
    let expected_owner = owner request in
    let%bind data = current_data actor request expected_owner in
    Ok
      { issuer = actor.inference_owner_identity
      ; domain = actor.runtime_source_domain
      ; request
      ; state = actor.state
      ; owner = expected_owner
      ; data
      }
  ;;

  let check_capture (actor : actor) (captured : captured) =
    let open Result.Let_syntax in
    let%bind () = on_domain actor in
    let%bind () =
      if
        phys_equal actor.inference_owner_identity captured.issuer
        && Int.equal actor.runtime_source_domain captured.domain
        && phys_equal actor.state captured.state
      then Ok ()
      else Error (error Conflict "policy governance lost its exact child observation")
    in
    let%bind actual = current_data actor captured.request captured.owner in
    if Data.equal actual captured.data
    then Ok ()
    else Error (error Conflict "policy governance observation changed before binding")
  ;;

  let bind_standalone (actor : actor) (captured : captured) =
    let open Result.Let_syntax in
    let%bind () = check_capture actor captured in
    match captured.data with
    | Registered _ ->
      Error
        (error Permission_denied "registered policy governance needs private ancestry")
    | Standalone_unrelated descriptor ->
      let request = captured.request in
      let expected_owner = captured.owner in
      let current () =
        let%bind actual = current_data actor request expected_owner in
        match actual with
        | Standalone_unrelated actual ->
          if Policy_standalone_source.equal descriptor actual
          then Ok ()
          else Error (error Conflict "standalone policy association changed")
        | Registered _ -> Error (error Conflict "standalone policy source changed")
      in
      Ok { request; source = Standalone descriptor; current }
  ;;

  let bind_registered (actor : actor) (captured : captured) ~source_owner ~ancestry =
    let open Result.Let_syntax in
    let%bind () = check_capture actor captured in
    let%bind data =
      match captured.data with
      | Standalone_unrelated _ ->
        Error
          (error Permission_denied "standalone policy Caller has no registered source")
      | Registered data -> Ok data
    in
    let%bind controller = child_accounting_owner actor ~source_owner in
    let%bind () =
      if
        Runtime_source_owner.matches source_owner data.source_owner
        && Agent_protocol.Session_ref.equal
             (Recurrence_controller.session controller)
             data.owner
      then Ok ()
      else Error (error Conflict "policy governance has a foreign Factory or controller")
    in
    let%bind inherited, _refresh =
      child_origin_ancestry actor.state ~source_owner ~controller ancestry
    in
    let%bind () =
      if
        Option.exists
          data.inherited
          ~f:(Agent_store.Delegation_goal_origin.equal inherited)
      then Ok ()
      else
        Error
          (error
             Permission_denied
             "policy governance inherited origin is unavailable or changed")
    in
    let request = captured.request in
    let expected_owner = captured.owner in
    let current () =
      let%bind () = on_domain actor in
      let%bind actual_controller = child_accounting_owner actor ~source_owner in
      let%bind () =
        if phys_equal controller actual_controller
        then Ok ()
        else Error (error Conflict "policy governance controller changed")
      in
      let%bind actual = current_data actor request expected_owner in
      match actual with
      | Registered actual when Data.Registered.equal actual data -> Ok ()
      | Standalone_unrelated _ | Registered _ ->
        Error (error Conflict "policy governance source or immutable association changed")
    in
    (* The returned Store refresh closure is deliberately not retained or called
       here. Factory authenticates the private records outside Actor operations.
       Later live checks use immutable source/work facts, so their own Book ACK
       cannot invalidate the captured physical State observation. *)
    Ok
      { request
      ; source = Registered { data; source_owner; controller; ancestry }
      ; current
      }
  ;;
end

let invocation_policy_caller t execution invocation =
  let check_current () =
    let open Result.Let_syntax in
    let%bind current = check_invocation_effect_current t execution invocation in
    if execution.accepts_children && current ()
    then Ok ()
    else Error (error Conflict "delegated policy invocation owner ended")
  in
  capture_policy_caller
    t
    ~owner:(Invocation invocation.Agent_protocol.Invocation.context.id)
    ~admission:(fun () -> invocation_policy_caller_admission t execution)
    ~check_current
;;

let moderator_policy_caller t borrow invocation =
  capture_policy_caller
    t
    ~owner:(Invocation invocation.Agent_protocol.Invocation.context.id)
    ~admission:(fun () -> policy_caller_admission (moderator_settlement_parent t borrow))
    ~check_current:(fun () -> check_moderator_effect_current t borrow invocation)
;;

let event_policy_caller t borrow =
  capture_policy_caller
    t
    ~owner:(Moderator_event borrow.receipt.context.id)
    ~admission:(fun () -> event_policy_caller_admission t borrow)
    ~check_current:(fun () ->
      let%bind.Result () =
        if Atomic.get borrow.authority_live
        then Ok ()
        else Error (error Conflict "delegated policy event owner ended")
      in
      let%bind.Result () = queued_event_inference_current t borrow in
      check_execution_descendant t (Inference_event borrow))
;;

let with_invocation_claim t claim f =
  let open Result.Let_syntax in
  Eio.Fiber.yield ();
  let%bind execution = Eio.Cancel.protect (fun () -> call t claim) in
  let finish ?requests ?(commit_starts = false) ?authoring_reference outcome =
    Atomic.set execution.authority_live false;
    Eio.Cancel.protect (fun () ->
      call
        t
        (Finish_invocation
           (execution, outcome, requests, commit_starts, authoring_reference)))
  in
  let finish_after_failure outcome =
    let report message =
      try Eio.traceln "native Invocation cleanup failed: %s" message with
      | _ -> ()
    in
    match finish outcome with
    | Ok _ -> ()
    | Error failure -> report failure.message
    | exception cleanup -> report (Exn.to_string cleanup)
  in
  let capabilities =
    Invocation_capabilities.
      { refresh_effect_current =
          (fun ~invocation -> refresh_invocation_effect_current t execution invocation)
      ; check_effect_current =
          (fun ~invocation ->
            let%bind owner_current =
              check_invocation_effect_current t execution invocation
            in
            if owner_current ()
            then Ok ()
            else Error (error Conflict "invocation effect owner expired"))
      ; borrow_agent_actor =
          (fun ~invocation ->
            call t (Borrow_invocation_agent_actor (execution, invocation)))
      ; policy_caller =
          (fun ~invocation -> invocation_policy_caller t execution invocation)
      ; allocate_inference = inference_port t (Inference_invocation execution)
      ; model_jobs = model_job_port t (Inference_invocation execution)
      }
  in
  let failed =
    Agent_protocol.Invocation.Fail
      { code = "invocation.handler_failed"
      ; message = "Tool execution failed."
      ; retryable = false
      ; details = `Null
      }
  in
  let run () =
    match refresh_held_execution t (Inference_invocation execution) with
    | Error failure -> Error failure, []
    | Ok () ->
      (match execution.owner with
       | Background_job _ ->
         Chat_response.Runtime_request_scope.collect (fun () ->
           f ~dispatched:execution.dispatched ~capabilities)
       | Foreground _ | Invocation_moderator _ | Event_moderator _ ->
         f ~dispatched:execution.dispatched ~capabilities, [])
  in
  match Authoring_reference_scope.collect execution.dispatched.context run with
  | (Ok outcome, collected), references ->
    let outcome, collected, commit_starts =
      match Agent_protocol.Invocation.validate_outcome outcome with
      | Ok () -> outcome, collected, true
      | Error _ ->
        ( Agent_protocol.Invocation.Fail
            { code = "invocation.invalid_output"
            ; message = "Tool execution returned an invalid outcome."
            ; retryable = false
            ; details = `Null
            }
        , []
        , false )
    in
    let requests : Agent_protocol.Invocation.follow_up =
      { request_turn = Chat_response.Runtime_semantics.request_turn collected
      ; request_compaction = Chat_response.Runtime_semantics.request_compaction collected
      ; end_session = Chat_response.Runtime_semantics.should_end_session collected
      }
    in
    let authoring_reference =
      match outcome with
      | Complete value ->
        List.find references ~f:(fun reference ->
          Agent_protocol.Authoring_reference.matches_output reference value)
      | Fail _ | Pending _ | Cancelled _ -> None
    in
    finish ~requests ~commit_starts ?authoring_reference outcome
  | (Error failure, _), _ ->
    finish_after_failure failed;
    Error failure
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    let outcome =
      match exn with
      | Eio.Cancel.Cancelled _ ->
        Agent_protocol.Invocation.Cancelled "tool execution cancelled"
      | _ -> failed
    in
    finish_after_failure outcome;
    Stdlib.Printexc.raise_with_backtrace exn backtrace
;;

let callback_tool_executor t ~scope ~invocation callback =
  let open Result.Let_syntax in
  let%bind () = check_callback_current t scope in
  let%bind _ = callback_agent_actor t ~scope in
  with_invocation_claim
    t
    (Claim_event_invocation (scope.borrow, invocation))
    (fun ~dispatched ~capabilities ->
       let%bind () = check_callback_current t scope in
       callback ~dispatched ~capabilities)
;;

let callback_policy_caller t ~scope =
  capture_policy_caller
    t
    ~owner:(Moderator_event scope.Callback_scope.borrow.receipt.context.id)
    ~admission:(fun () ->
      match scope.borrow.agent_admission with
      | Resumed_run admission | Delegated_policy admission -> Ok admission
      | Selected_queue _ | Contextual _ ->
        policy_caller_admission
          (Ok
             (match scope.custody with
              | Unavailable -> Observation_continuation.Parent.Unavailable
              | Admitted admission -> Available admission)))
    ~check_current:(fun () -> check_callback_inference_current t scope)
;;

let callback_model_jobs t ~scope =
  let admission = model_job_port t (Inference_event scope.Callback_scope.borrow) in
  Model_job_admission.Host.create ~admit:(fun job ->
    let open Result.Let_syntax in
    let%bind () =
      match scope.constructor_scope with
      | None -> Ok ()
      | Some _ ->
        Error
          (error
             Permission_denied
             "installed callback Model admission excludes constructors")
    in
    let%bind () = check_callback_current t scope in
    Model_job_admission.admit admission job)
;;

let with_invocation t operation_id ~invocation f =
  (* A legitimate root metadata writer may have retired the cached observation.
     Refresh the SAME admitted operation outside the mailbox before its actual
     Claim repeats the pure currentness check. No new admission is issued. *)
  let%bind.Result () = refresh_operation_descendant t operation_id in
  with_invocation_claim t (Claim_invocation (operation_id, invocation)) f
;;

let with_job_scope t ~job_id ~generation ~attempt ~deadline f =
  let open Result.Let_syntax in
  let selected =
    List.find_map t.state.jobs ~f:(fun job ->
      if
        Agent_protocol.Id.Job.equal job.id job_id
        && Int.equal job.generation generation
        && Int.equal job.attempt attempt
      then held_authored_job t job
      else None)
  in
  (* The preceding actual Job claim ACK invalidates target Store custody. Refresh
     its same live startup outside the mailbox; Claim_job_scope independently
     reselects the real owner and repeats all occurrence/effect guards. *)
  let%bind () = Option.value_map selected ~default:(Ok ()) ~f:(refresh_held_authored t) in
  let%bind scope =
    Eio.Cancel.protect (fun () ->
      call t (Claim_job_scope (job_id, generation, attempt, deadline)))
  in
  let active = Atomic.make true in
  let finish () =
    Atomic.set active false;
    Eio.Cancel.protect (fun () -> call t (Finish_job_scope scope))
  in
  let execute ~invocation callback =
    match Atomic.get active with
    | false -> Error (error Conflict "background invocation scope has ended")
    | true ->
      let%bind.Result () = refresh_held_execution t (Inference_job scope) in
      with_invocation_claim
        t
        (Claim_job_invocation (scope, invocation))
        (fun ~dispatched ~capabilities ->
           match Atomic.get active with
           | false -> Error (error Conflict "background invocation scope has ended")
           | true ->
             Eio.Fiber.check ();
             (match Eio.Promise.peek scope.cancelled with
              | Some () -> raise (Eio.Cancel.Cancelled Exit)
              | None ->
                Eio.Fiber.first
                  (fun () -> callback ~dispatched ~capabilities)
                  (fun () ->
                     Eio.Promise.await scope.cancelled;
                     raise (Eio.Cancel.Cancelled Exit))))
  in
  let run () =
    Eio.Cancel.sub (fun context ->
      Exn.protect
        ~finally:(fun () ->
          Atomic.set active false;
          Exn.protect
            ~finally:(fun () -> Eio.Cancel.cancel context Exit)
            ~f:(fun () ->
              Eio.Cancel.protect (fun () ->
                ignore
                  (call t (Seal_job_scope scope) : (unit, Agent_protocol.Error.t) result))))
        ~f:(fun () ->
          let%bind () =
            call
              t
              (Set_job_scope_cancel
                 ( scope
                 , fun () ->
                     match Atomic.get active with
                     | true -> Eio.Cancel.cancel context Exit
                     | false -> () ))
          in
          f ~scope ~execute))
  in
  match run () with
  | result ->
    let%bind () = finish () in
    result
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    ignore (finish () : (unit, Agent_protocol.Error.t) result);
    Stdlib.Printexc.raise_with_backtrace exn backtrace
;;

let with_native_goal_scope t owner f =
  let open Result.Let_syntax in
  let route request =
    Result.map_error (call t (Native_goal request)) ~f:(fun error -> error.message)
  in
  let scope =
    Chat_response.Goal_native_scope.create
      { deliverable = (fun receipt -> route (Deliverable (owner, receipt)))
      ; accept = (fun receipt -> route (Accept (owner, receipt)))
      ; rollback =
          (fun receipt ->
            ignore (route (Rollback (owner, receipt)) : (unit, string) result))
      ; prepare = (fun receipts -> route (Prepare (owner, receipts)))
      }
  in
  let%bind () = call t (Native_goal (Install_scope (owner, scope))) in
  let close () =
    (* Atomic lexical revocation happens before the yielding factual mailbox
       cleanup; the receipt table itself remains single-Actor owned. *)
    Chat_response.Goal_native_scope.close scope;
    Eio.Cancel.protect (fun () -> call t (Native_goal (Close_scope owner)))
  in
  match Chat_response.Goal_native_scope.with_scope scope f with
  | Error _ as failure ->
    (try ignore (close () : (unit, Agent_protocol.Error.t) result) with
     | _ -> ());
    failure
  | Ok value ->
    let%map () = close () in
    value
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    (try ignore (close () : (unit, Agent_protocol.Error.t) result) with
     | _ -> ());
    Stdlib.Printexc.raise_with_backtrace exn backtrace
;;

let run_moderator_callback t borrow f =
  let open Result.Let_syntax in
  let commit ~resolved ~snapshot =
    Eio.Cancel.protect (fun () ->
      call t (Commit_moderator_invocation (borrow, resolved, snapshot)))
  in
  let finish failure =
    Atomic.set borrow.authority_live false;
    Exn.protect
      ~finally:(fun () ->
        Option.iter borrow.observation ~f:Observation_continuation.retire)
      ~f:(fun () ->
        Eio.Cancel.protect (fun () ->
          call t (Finish_moderator_invocation (borrow, failure))))
  in
  let capabilities =
    Invocation_capabilities.
      { refresh_effect_current =
          (fun ~invocation -> refresh_moderator_effect_current t borrow invocation)
      ; check_effect_current =
          (fun ~invocation -> check_moderator_effect_current t borrow invocation)
      ; borrow_agent_actor =
          (fun ~invocation -> call t (Borrow_moderator_agent_actor (borrow, invocation)))
      ; policy_caller = (fun ~invocation -> moderator_policy_caller t borrow invocation)
      ; allocate_inference = inference_port t (Inference_moderator borrow)
      ; model_jobs = model_job_port t (Inference_moderator borrow)
      }
  in
  let failed message =
    let message =
      if String.is_empty message || String.length message > 16_384
      then "moderator handler failed; diagnostic is outside the invocation message limit"
      else message
    in
    Agent_protocol.Invocation.Fail
      { code = "invocation.handler_failed"; message; retryable = false; details = `Null }
  in
  let run () =
    match borrow.kind with
    | Observation -> f ~dispatched:borrow.invocation ~capabilities ~commit
    | Invocation _ ->
      Authoring_reference_scope.with_scope borrow.invocation.context (fun scope ->
        let commit ~resolved ~snapshot =
          let%bind resolved = Authoring_reference_scope.annotate scope resolved in
          commit ~resolved ~snapshot
        in
        f ~dispatched:borrow.invocation ~capabilities ~commit)
  in
  match with_native_goal_scope t (Native_goal_owner.Moderator borrow) run with
  | result ->
    let failure =
      match result with
      | Ok () -> None
      | Error (failure : Agent_protocol.Error.t) -> Some (failed failure.message)
    in
    let%bind () = finish failure in
    result
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    let failure =
      match exn with
      | Eio.Cancel.Cancelled _ ->
        Agent_protocol.Invocation.Cancelled "moderator handler cancelled"
      | _ -> failed (Exn.to_string exn)
    in
    ignore (finish (Some failure) : (unit, Agent_protocol.Error.t) result);
    Stdlib.Printexc.raise_with_backtrace exn backtrace
;;

let run_moderator_borrow t (borrow : moderator_borrow) f =
  match borrow.operation_id with
  | Some _ -> run_moderator_callback t borrow f
  | None ->
    (* A protected claim can return into a cancelled parent. Enter completion
       handling before [sub], which can reject that parent before running its body. *)
    run_moderator_callback t borrow (fun ~dispatched ~capabilities ~commit ->
      Eio.Cancel.sub (fun context ->
        let active = ref true in
        (* Completion clears the actor's cancel callback after this context ends. *)
        Exn.protect
          ~finally:(fun () -> active := false)
          ~f:(fun () ->
            let open Result.Let_syntax in
            let%bind () =
              call
                t
                (Set_idle_moderator_cancel
                   (borrow, fun () -> if !active then Eio.Cancel.cancel context Exit))
            in
            f ~dispatched ~capabilities ~commit)))
;;

let with_moderator_borrow_unlocked t ~claim f =
  let open Result.Let_syntax in
  (* Once admitted, always reach protected completion even during cancellation. *)
  Eio.Fiber.yield ();
  let%bind borrow = Eio.Cancel.protect (fun () -> call t claim) in
  run_moderator_borrow t borrow f
;;

let with_moderator_gate t f =
  match Chat_response.Execution_gate.with_access t.invocation_gate f with
  | Ok result -> result
  | Error failure ->
    let code =
      match failure with
      | Chat_response.Execution_gate.Resource_limit -> Agent_protocol.Error.Resource_limit
      | Reentrant | Wait_cycle -> Conflict
    in
    Error (error code (Chat_response.Execution_gate.error_message failure))
;;

let with_moderator_checkpoint = with_moderator_gate

let check_callback_producer_domain t =
  if Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
  then Ok ()
  else Error (error Conflict "callback producer belongs to another creating domain")
;;

let run_queued_event_borrow
      ?(before_callback = fun () -> Ok ())
      t
      (borrow : queued_event_borrow)
      f
  =
  let open Result.Let_syntax in
  let facts = borrow.completion.facts in
  let finish exit =
    Eio.Cancel.protect (fun () ->
      let attempt = Callback_cleanup_data.Completion.begin_finish_call facts in
      let promise, resolver = Eio.Promise.create () in
      (* Observe the raw reply BEFORE resuming a raised handler outcome. That
         resume must not be mistaken for an independent await exception. *)
      let reply =
        match
          match
            Mailbox.push
              t.mailbox
              ~priority:Mailbox.Normal
              (Pack
                 ( None
                 , Finish_queued_event (Callback_returned (borrow, exit, attempt))
                 , resolver ))
          with
          | Error failure -> Actor_reply.Returned (Error failure)
          | Ok () -> Eio.Promise.await promise
        with
        | reply -> reply
        | exception exn ->
          let backtrace = Stdlib.Printexc.get_raw_backtrace () in
          Callback_cleanup_data.Completion.record_reply
            facts
            ~attempt
            ~origin:Await_failed
            (Error (Raised (exn, backtrace)));
          Exn.raise_with_original_backtrace exn backtrace
      in
      let outcome =
        match reply with
        | Actor_reply.Returned (Ok ()) -> Ok ()
        | Returned (Error failure) -> Error (Callback_cleanup.Failure.Protocol failure)
        | Raised (exn, backtrace) -> Error (Raised (exn, backtrace))
      in
      let origin = Callback_cleanup_data.Completion.reply_origin facts ~attempt in
      Callback_cleanup_data.Completion.record_reply facts ~attempt ~origin outcome;
      Callback_cleanup_data.Outcome.resume outcome)
  in
  let finish_after_failure exit =
    let report message =
      (* The primary callback failure remains the caller's exception/result.
         Cleanup failure is secondary evidence, never a replacement outcome. *)
      try Eio.traceln "queued moderator cleanup failed: %s" message with
      | _ -> ()
    in
    match finish exit with
    | Ok () -> ()
    | Error failure -> report failure.message
    | exception cleanup -> report (Exn.to_string cleanup)
  in
  let execute () =
    Eio.Cancel.sub (fun context ->
      let active = ref true in
      Exn.protect
        ~finally:(fun () -> active := false)
        ~f:(fun () ->
          (* The actual claim ACK rotated Store custody. Refresh outside the
             mailbox, inside the existing factual completion owner, before the
             first currentness-checked cancellation registration. *)
          let%bind () = refresh_held_execution t (Inference_event borrow) in
          let%bind () =
            call
              t
              (Set_queued_event_cancel
                 ( borrow
                 , fun () ->
                     match !active with
                     | true -> Eio.Cancel.cancel context Exit
                     | false -> () ))
          in
          f
            ~borrow
            ~event:borrow.event
            ~commit:(fun ~decision ~notifications ~snapshot ~requests ->
              let%bind () = refresh_held_execution t (Inference_event borrow) in
              Eio.Cancel.protect (fun () ->
                call
                  t
                  (Commit_queued_event
                     (borrow, snapshot, requests, decision, notifications))))))
  in
  match
    let%bind () = Eio.Cancel.protect before_callback in
    with_native_goal_scope t (Native_goal_owner.Event borrow) execute
  with
  | Error failure ->
    Callback_cleanup_data.Completion.record_producer_exit facts (Error (Protocol failure));
    finish_after_failure (Failed failure);
    Error failure
  | Ok () ->
    Callback_cleanup_data.Completion.record_producer_exit facts (Ok ());
    let%bind () = finish Returned in
    (match borrow.stop_retirement, borrow.committed with
     | Some _, _ ->
       Error
         (error
            Interrupted
            "constructor retired by Stop before checkpoint acknowledgement")
     | None, true -> Ok true
     | None, false ->
       Error (error Invalid_state "queued event returned without a checkpoint commit"))
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    Callback_cleanup_data.Completion.record_producer_exit
      facts
      (Error (Raised (exn, backtrace)));
    finish_after_failure (Raised (exn, backtrace));
    Stdlib.Printexc.raise_with_backtrace exn backtrace
;;

let with_queued_event_borrow t ~claim f =
  let open Result.Let_syntax in
  let%bind () = check_callback_producer_domain t in
  with_moderator_gate t (fun () ->
    let open Result.Let_syntax in
    Eio.Fiber.yield ();
    let%bind claim = claim () in
    let%bind claimed =
      match claim with
      | None -> Ok None
      | Some claim -> Eio.Cancel.protect (fun () -> call t claim)
    in
    match claimed with
    | None -> Ok false
    | Some borrow ->
      run_queued_event_borrow t borrow (fun ~borrow ~event ~commit ->
        f ~borrow ~event ~commit:(fun ~snapshot ~requests ->
          commit ~decision:None ~notifications:[] ~snapshot ~requests)))
;;

module Initialization_scope = struct
  type actor = t

  include Initialization_scope_data

  let callback_cleanup t = t.callback_cleanup

  module Source_handoff = struct
    include Source_handoff

    let check (t : t) ~(actor : actor) ~moderator_manager ~(expected : Session_state.t) =
      let open Result.Let_syntax in
      let%bind () =
        if
          Int.equal t.domain (Stdlib.Domain.self () :> int)
          && Int.equal actor.runtime_source_domain t.domain
        then Ok ()
        else
          Error (error Conflict "initialization source handoff belongs to another domain")
      in
      let%bind source = source expected in
      if
        phys_equal t.issuer actor.initialization_owner
        && Agent_protocol.Id.Session.equal t.session_id expected.identity.session_id
        && Int.equal t.generation expected.identity.generation
        && Session_state.Spec.Resource_identity.equal
             t.spec
             (Session_state.Spec.Resource_identity.capture expected.spec)
        && Option.equal Agent_protocol.Run_source.equal t.after_source source
        && Option.equal phys_equal t.manager moderator_manager
        &&
        match expected.runtime_initialization with
        | Ready -> true
        | Pending _ -> false
      then Ok ()
      else
        Error
          (error
             Conflict
             "initialization source handoff has another Actor/resource basis")
    ;;
  end

  let source_handoff (t : t) =
    if not (Int.equal t.domain (Stdlib.Domain.self () :> int))
    then Error (error Conflict "initialization source handoff belongs to another domain")
    else (
      match t.source_handoff with
      | Some handoff when phys_equal handoff.scope t.identity -> Ok handoff
      | Some _ | None ->
        Error (error Conflict "initialization has no actual completed source ACK"))
  ;;
end

module Native_setup = struct
  type t = Native_setup_data.t

  let check = Native_setup_data.check
  let close = Native_setup_data.close
end

module Policy_restoration = struct
  type t = Policy_restoration_data.t

  let check = Policy_restoration_data.check
  let close = Policy_restoration_data.close

  module Published = Policy_restoration_data.Published
end

module Delegated_policy_claim = struct
  type actor = t

  module Access = Delegated_policy_claim_data.Access

  module Capture = struct
    type t = Delegated_policy_claim_data.t

    type disposition =
      | Waiting
      | Retained
      | Released

    let create (actor : actor) ~(access : Access.t) =
      let open Result.Let_syntax in
      let%bind () =
        if Int.equal actor.runtime_source_domain (Stdlib.Domain.self () :> int)
        then Ok ()
        else
          Error
            (error Conflict "delegated policy capture belongs to another Actor domain")
      in
      let%map () =
        match access with
        | Restored_unloaded published -> check_published_policy_target actor published
        | Running | Policy_only _ -> Ok ()
      in
      { Delegated_policy_claim_data.issuer = actor.inference_owner_identity
      ; domain = actor.runtime_source_domain
      ; access
      ; state = Delegated_policy_claim_state.create ~issuer:actor.inference_owner_identity
      ; intent_retention = None
      }
    ;;

    let disposition (t : t) =
      let module State = Delegated_policy_claim_state in
      match State.phase t.state, State.extent t.state with
      | (Waiting | Released), (Joined_without_entry | Joined_after_entry) -> Released
      | Waiting, (Not_started | Not_entered | Entered) -> Waiting
      | (Prepared _ | Activated _ | Callback_acknowledged _ | Released), _ -> Retained
    ;;

    let check_policy_effect_current (actor : actor) (capture : t) =
      let module State = Delegated_policy_claim_state in
      let open Result.Let_syntax in
      let%bind () = Delegated_policy_custody.check_capture actor capture in
      let denied () =
        Error (error Conflict "stopped policy effect no longer owns its active claim")
      in
      let%bind () =
        match capture.access with
        | Running -> denied ()
        | Policy_only _ | Restored_unloaded _ ->
          if
            actor.stopped
            || State.cancellation_requested capture.state
            || not (Option.exists actor.delegated_policy_claim ~f:(phys_equal capture))
          then denied ()
          else Ok ()
      in
      let%bind attempt =
        match State.phase capture.state, State.extent capture.state with
        | Activated attempt, Entered -> Ok attempt
        | (Waiting | Prepared _ | Activated _ | Callback_acknowledged _ | Released), _ ->
          denied ()
      in
      let borrow = State.Attempt.borrow attempt in
      let%bind () = Delegated_policy_custody.check_access actor capture in
      let%bind () = queued_event_can_commit_installed actor borrow in
      let%bind () =
        if
          Atomic.get borrow.authority_live
          && Option.is_none borrow.retirement_reason
          && Option.is_none borrow.stop_retirement
          && Option.is_none borrow.terminal_selection
          &&
          match borrow.agent_admission with
          | Delegated_policy original ->
            Option.equal phys_equal original (State.Attempt.original attempt)
          | Contextual _ | Resumed_run _ | Selected_queue _ -> false
        then Ok ()
        else denied ()
      in
      Option.value_map
        (State.Attempt.original attempt)
        ~default:(Ok ())
        ~f:Execution_custody.Admission.check
    ;;

    let with_extent (t : t) f = Delegated_policy_claim_state.with_extent t.state f
    let cancel_waiting (t : t) = Delegated_policy_claim_state.cancel t.state
  end

  let pending = Delegated_policy_custody.pending
  let drain actor = call actor Drain_delegated_policy_claim
end

let with_delegated_moderator_event
      ?(notifications = fun () -> [])
      t
      ~(capture : Delegated_policy_claim.Capture.t)
      ~(request : Script_tool_calls.preparation)
      ~governance
      ~delegation
      ~event
      ~authorize
      ~snapshot
      f
  =
  let open Result.Let_syntax in
  let authorize () =
    let%bind () = Causal_governance.check_request governance request in
    authorize ()
  in
  let%bind () = Delegated_policy_custody.check_capture t capture in
  let%bind () =
    match Delegated_policy_claim_state.extent capture.state with
    | Not_entered -> Ok ()
    | Not_started | Entered | Joined_without_entry | Joined_after_entry ->
      Error (error Conflict "delegated policy wrapper already entered or joined")
  in
  with_moderator_gate t (fun () ->
    let%bind () = authorize () in
    let%bind snapshot = snapshot () in
    let%bind () = authorize () in
    let%bind claimed =
      Eio.Cancel.protect (fun () ->
        call
          t
          (Claim_delegated_event
             ( capture
             , request
             , governance
             , Agent_protocol.Id.Moderator_execution.create ()
             , delegation
             , snapshot
             , event )))
    in
    match claimed with
    | Delegated_unavailable -> Ok None
    | Delegated_replay previous ->
      let%map () = authorize () in
      Some previous
    | Delegated_borrow borrow ->
      let%bind () = Delegated_policy_claim_state.enter capture.state in
      let%bind _ =
        run_queued_event_borrow t borrow (fun ~borrow ~event ~commit ->
          let%bind policy_caller = event_policy_caller t borrow in
          let active = Atomic.make true in
          let check () =
            let%bind () = authorize () in
            match Atomic.get active with
            | false ->
              Error (error Conflict "delegated policy invocation scope has ended")
            | true -> Ok ()
          in
          let execute ~invocation callback =
            let%bind () = check () in
            let%bind result =
              with_invocation_claim
                t
                (Claim_event_invocation (borrow, invocation))
                (fun ~dispatched ~capabilities ->
                   let%bind () = check () in
                   callback ~dispatched ~capabilities)
            in
            (* Keep the native outcome even if the delegated caller loses access
               while it runs. Rechecking inside the callback after the effect
               would discard known results before the actor could persist them. *)
            let%map () = check () in
            result
          in
          Exn.protect
            ~finally:(fun () ->
              Atomic.set active false;
              Delegated_policy_caller.close policy_caller)
            ~f:(fun () ->
              let%bind () = check () in
              f
                ~executing:borrow.receipt
                ~policy_caller:(Some policy_caller)
                ~model_jobs:(model_job_port t (Inference_event borrow))
                ~allocate_inference:(inference_port t (Inference_event borrow))
                ~event
                ~execute
                ~commit:(fun ~decision ~snapshot ~requests ->
                  let%bind () = check () in
                  commit
                    ~decision:(Some decision)
                    ~notifications:(notifications ())
                    ~snapshot
                    ~requests)))
      in
      let%bind state = call t State in
      let%bind () = authorize () in
      List.find state.moderator_executions ~f:(fun receipt ->
        Agent_protocol.Id.Moderator_execution.equal
          receipt.context.id
          borrow.receipt.context.id)
      |> Result.of_option
           ~error:(error Internal_error "delegated policy receipt disappeared")
      |> Result.map ~f:Option.some)
;;

(* The ACK slot is filled only by the original serialized claim handler, after
   successful installation. External capture never runs inside that writer. *)
let with_claimed_legacy_callback t ?capture_cleanup ~claim f =
  let open Result.Let_syntax in
  let%bind () = check_callback_producer_domain t in
  with_moderator_gate t (fun () ->
    let installed = ref None in
    let claimed =
      match Eio.Cancel.protect (fun () -> call t (claim installed)) with
      | result -> Ok result
      | exception exn ->
        let backtrace = Stdlib.Printexc.get_raw_backtrace () in
        Error (exn, backtrace)
    in
    let resume_claim () =
      match claimed with
      | Ok result -> result
      | Error (exn, backtrace) -> Exn.raise_with_original_backtrace exn backtrace
    in
    match !installed with
    | None ->
      (match resume_claim () with
       | Error failure -> Error failure
       | Ok None -> Ok false
       | Ok (Some _) -> invalid_arg "callback reply has no installed ACK slot")
    | Some scope ->
      let before_callback () =
        let capture =
          match
            Option.iter capture_cleanup ~f:(fun capture ->
              capture (Callback_scope.completion scope))
          with
          | () -> Ok ()
          | exception exn ->
            let backtrace = Stdlib.Printexc.get_raw_backtrace () in
            Callback_cleanup_data.Completion.record_capture_failure
              scope.borrow.completion.facts
              (Raised (exn, backtrace));
            Error (exn, backtrace)
        in
        let open Result.Let_syntax in
        let%bind claimed_scope = resume_claim () in
        let%bind () =
          match claimed_scope with
          | Some original when phys_equal original scope -> Ok ()
          | None | Some _ ->
            Error (error Conflict "callback installed ACK differs from claim reply")
        in
        match capture with
        | Ok () -> Ok ()
        | Error (exn, backtrace) -> Exn.raise_with_original_backtrace exn backtrace
      in
      run_queued_event_borrow
        ~before_callback
        t
        scope.borrow
        (fun ~borrow:_ ~event:_ ~commit ->
           let open Result.Let_syntax in
           let%bind () = check_callback_current t scope in
           f ~scope ~commit:(fun ~snapshot ~requests ~notifications ->
             commit ~decision:None ~notifications ~snapshot ~requests)))
;;

let with_legacy_callback_parent t parent ?capture_cleanup ~callback f =
  with_claimed_legacy_callback
    t
    ?capture_cleanup
    ~claim:(fun installed -> Claim_legacy_callback (callback, parent, installed))
    f
;;

let with_initialization_callback t ~scope ~manager ?capture_cleanup ~callback f =
  with_claimed_legacy_callback
    t
    ?capture_cleanup
    ~claim:(fun installed ->
      Claim_initialization_callback (scope, manager, callback, installed))
    f
;;

let with_legacy_callback t ~operation_id =
  with_legacy_callback_parent t (Callback_operation operation_id)
;;

let with_legacy_queued_callback t ?capture_cleanup ~callback ~operation_id f =
  match Chat_response.Moderator_manager.Callback.selection callback with
  | Boundary _ ->
    Error (error Invalid_request "legacy queued callback requires an actual Queue_head")
  | Queue_head -> with_legacy_callback t ~operation_id ?capture_cleanup ~callback f
;;

let with_idle_queued_moderator_event t ~snapshot f =
  with_queued_event_borrow
    t
    ~claim:(fun () ->
      Ok
        (Some
           (Claim_queued_event
              (Agent_protocol.Id.Moderator_execution.create (), None, snapshot))))
    (fun ~borrow:_ ~event ~commit -> f ~event ~commit)
;;

let with_queued_moderator_retirement t ~id ~snapshot ~reason f =
  with_queued_event_borrow
    t
    ~claim:(fun () -> Ok (Some (Claim_queued_retirement (id, snapshot, reason))))
    (fun ~borrow:_ ~event ~commit ->
       f ~event ~commit:(fun ~snapshot ->
         commit
           ~snapshot
           ~requests:
             { request_turn = false; request_compaction = false; end_session = None }))
;;

let with_event_tools t ~claim f =
  with_queued_event_borrow t ~claim (fun ~borrow ~event ~commit ->
    let open Result.Let_syntax in
    let%bind policy_caller = event_policy_caller t borrow in
    let active = Atomic.make true in
    let execute ~invocation callback =
      match Atomic.get active with
      | false -> Error (error Conflict "event invocation scope has ended")
      | true ->
        let%bind.Result () = refresh_held_execution t (Inference_event borrow) in
        with_invocation_claim t (Claim_event_invocation (borrow, invocation)) callback
    in
    Exn.protect
      ~finally:(fun () ->
        Atomic.set active false;
        Delegated_policy_caller.close policy_caller)
      ~f:(fun () ->
        f
          ~executing:borrow.receipt
          ~policy_caller:(Some policy_caller)
          ~model_jobs:(model_job_port t (Inference_event borrow))
          ~allocate_inference:(inference_port t (Inference_event borrow))
          ~retirement_reason:borrow.retirement_reason
          ~event
          ~execute
          ~commit))
;;

let with_queued_moderator_event_tools t ~operation_id ~snapshot f =
  with_event_tools
    t
    ~claim:(fun () ->
      Ok
        (Some
           (Claim_queued_event
              (Agent_protocol.Id.Moderator_execution.create (), operation_id, snapshot))))
    f
;;

let with_idle_queued_moderator_event_tools t =
  with_queued_moderator_event_tools t ~operation_id:None
;;

let with_ordinary_moderator_event t ~operation_id ~snapshot ~event f =
  with_event_tools
    t
    ~claim:(fun () ->
      Ok
        (Some
           (Claim_ordinary_event
              ( Agent_protocol.Id.Moderator_execution.create ()
              , operation_id
              , snapshot
              , event ))))
    f
;;

let with_current_moderator_event t ~operation_id ~event ~snapshot f =
  with_event_tools
    t
    ~claim:(fun () ->
      Result.map (snapshot ()) ~f:(fun snapshot ->
        Some
          (Claim_ordinary_event
             ( Agent_protocol.Id.Moderator_execution.create ()
             , operation_id
             , snapshot
             , event ))))
    f
;;

type job_execution =
  { job : Agent_protocol.Job.t
  ; runtime_owner : Job_runtime_owner.t
  ; allocate_inference : Inference_allocation.Port.t
  ; model_jobs : Model_job_admission.t
  ; execute : Native_tool_invocation.executor
  ; moderator_execute : Native_tool_invocation.moderator_executor
  ; claim_event : event:Chat_response.Moderation.Event.t -> Moderator_event.claim
  ; claim_legacy_callback : legacy_callback_claim
  }

(* Runtime routing is not inference classification. Historical native Jobs
   retain their actual stored Run ancestry without acquiring Unbound inference;
   explicit inference provenance remains strict, as at the existing native gate. *)
let job_runtime_run t job = Job_runtime_owner.run_of_job t.state job

let job_execution_for_owner t (runtime_owner : Job_runtime_owner.t) =
  let scope = runtime_owner.scope in
  let claim_event ~event ~snapshot callback =
    with_event_tools
      t
      ~claim:(fun () ->
        Result.map (snapshot ()) ~f:(fun snapshot ->
          Some
            (Claim_job_event
               (scope, Agent_protocol.Id.Moderator_execution.create (), snapshot, event))))
      callback
  in
  let moderator_execute ?snapshot ~invocation callback =
    with_moderator_gate t (fun () ->
      let open Result.Let_syntax in
      let%bind captured =
        match snapshot with
        | None -> Ok None
        | Some snapshot -> Result.map (snapshot ()) ~f:Option.some
      in
      with_moderator_borrow_unlocked
        t
        ~claim:(Claim_job_moderator (scope, invocation, captured))
        callback)
  in
  let claim_legacy_callback = with_legacy_callback_parent t (Callback_job scope) in
  { job = scope.job
  ; runtime_owner
  ; allocate_inference = inference_port t (Inference_job scope)
  ; model_jobs = model_job_port t (Inference_job scope)
  ; execute = runtime_owner.execute
  ; moderator_execute
  ; claim_event
  ; claim_legacy_callback
  }
;;

let with_job_execution t ~job_id ~generation ~attempt ~deadline f =
  with_job_scope t ~job_id ~generation ~attempt ~deadline (fun ~scope ~execute ->
    let open Result.Let_syntax in
    let%bind attribution = Job_runtime_owner.classify t.state scope.job in
    let runtime_owner : Job_runtime_owner.t =
      { domain = (Stdlib.Domain.self () :> int)
      ; issuing_actor = t.inference_owner_identity
      ; scope
      ; execute
      ; attribution
      }
    in
    f (job_execution_for_owner t runtime_owner))
;;

let with_job_invocations t ~job_id ~generation ~attempt ~deadline f =
  with_job_execution t ~job_id ~generation ~attempt ~deadline (fun execution ->
    f ~job:execution.job ~execute:execution.execute)
;;

let with_current_queued_moderator_event_tools t ~operation_id ~snapshot f =
  with_event_tools
    t
    ~claim:(fun () ->
      Result.map (snapshot ()) ~f:(fun snapshot ->
        match
          snapshot.Session.Moderator_state.Identity_snapshot.queued_internal_events
        with
        | [] -> None
        | _ ->
          Some
            (Claim_queued_event
               (Agent_protocol.Id.Moderator_execution.create (), operation_id, snapshot))))
    f
;;

let reconcile_run_recovery t = call t Reconcile_run_recovery
let run_actions t executing = call t (Run_actions executing)

let with_current_idle_queued_moderator_event_tools t =
  with_current_queued_moderator_event_tools t ~operation_id:None
;;

let with_moderator_invocation t operation_id ?snapshot ~invocation f =
  with_moderator_gate t (fun () ->
    let open Result.Let_syntax in
    let%bind captured =
      match snapshot with
      | None -> Ok None
      | Some snapshot -> Result.map (snapshot ()) ~f:Option.some
    in
    with_moderator_borrow_unlocked
      t
      ~claim:(Claim_moderator_invocation (operation_id, invocation, captured))
      f)
;;

let with_moderator_observation t operation_id ~invocation_id f =
  with_moderator_gate t (fun () ->
    with_moderator_borrow_unlocked
      t
      ~claim:(Claim_moderator_observation (operation_id, invocation_id))
      (fun ~dispatched ~capabilities ~commit ->
         f ~observing:dispatched ~capabilities ~commit))
;;

let with_selected_moderator_observation t claim f =
  with_moderator_gate t (fun () ->
    let open Result.Let_syntax in
    Eio.Fiber.yield ();
    let%bind borrow = Eio.Cancel.protect (fun () -> call t claim) in
    match borrow with
    | None -> Ok false
    | Some borrow ->
      let%map () =
        run_moderator_borrow t borrow (fun ~dispatched ~capabilities ~commit ->
          f ~observing:dispatched ~capabilities ~commit)
      in
      true)
;;

let with_next_moderator_observation t operation_id ~observer f =
  with_selected_moderator_observation
    t
    (Claim_next_moderator_observation (operation_id, observer))
    f
;;

let with_idle_moderator_observation t ~observer f =
  with_selected_moderator_observation
    t
    (Claim_idle_moderator_observation (observer, false))
    f
;;

let with_idle_moderator_observation_tools t ~observer f =
  with_moderator_gate t (fun () ->
    let open Result.Let_syntax in
    Eio.Fiber.yield ();
    let%bind borrow =
      Eio.Cancel.protect (fun () ->
        call t (Claim_idle_moderator_observation (observer, true)))
    in
    match borrow with
    | None -> Ok false
    | Some borrow ->
      let active = Atomic.make true in
      let execute ~invocation callback =
        match Atomic.get active with
        | false -> Error (error Conflict "idle invocation scope has ended")
        | true ->
          with_invocation_claim t (Claim_idle_invocation (borrow, invocation)) callback
      in
      let%map () =
        run_moderator_borrow t borrow (fun ~dispatched ~capabilities ~commit ->
          Exn.protect
            ~f:(fun () -> f ~observing:dispatched ~capabilities ~execute ~commit)
            ~finally:(fun () -> Atomic.set active false))
      in
      true)
;;

let worker_capabilities t (publication : Foreground_publication.t) id_source buffer =
  let { Foreground_publication.operation; live; completion; _ } = publication in
  let operation_id = operation.Agent_protocol.Operation.id in
  Operation_worker.Capabilities.
    { id_source =
        History_id_source.as_history_entry_source
          ~committed_through:(fun () ->
            Result.map (call t State) ~f:(fun state ->
              state.conversation.reserved_history_through))
          id_source
    ; callback_cleanup =
        (fun () ->
          match completion with
          | None ->
            Error (error Conflict "worker has no original operation cleanup receipt")
          | Some (completion : Operation_completion.t) ->
            Result.map
              (Callback_cleanup.Operation.operation completion.callback_cleanup)
              ~f:(fun _ -> completion.callback_cleanup))
    ; allocate_inference = inference_port t (Inference_operation (operation, live))
    ; policy_caller =
        (fun () ->
          capture_policy_caller
            t
            ~owner:(Operation operation_id)
            ~admission:(fun () ->
              policy_caller_admission
                (Result.map
                   (operation_agent_admission t operation_id)
                   ~f:parent_of_admission))
            ~check_current:(fun () ->
              let open Result.Let_syntax in
              let%bind current = running_operation t operation_id in
              let%bind () =
                check_execution_descendant t (Inference_operation (operation, live))
              in
              if
                Atomic.get live
                && Int.equal operation.generation current.generation
                && Agent_protocol.Operation.equal_kind operation.kind current.kind
              then Ok ()
              else Error (error Conflict "delegated policy operation owner ended")))
    ; original_agent_actor =
        (fun () -> call t (Borrow_operation_agent_actor operation_id))
    ; commit_entry = (fun entry -> call t (Commit_worker_entry (publication, entry)))
    ; prepare_authoring_input =
        (fun materialization ~history ~effective ->
          Eio.Cancel.protect (fun () ->
            call
              t
              (Prepare_authoring_input (publication, materialization, history, effective))))
    ; commit_invocation_call =
        (fun ~invocation entry ->
          Eio.Cancel.protect (fun () ->
            call t (Commit_invocation_call (publication, invocation, entry))))
    ; publish_invocation_output =
        (fun ~invocation_id entry ->
          Eio.Cancel.protect (fun () ->
            call t (Publish_invocation_output (publication, invocation_id, entry))))
    ; commit_moderator =
        (fun snapshot -> call t (Commit_worker_moderator (publication, snapshot)))
    ; with_moderator_invocation = with_moderator_invocation t operation_id
    ; with_moderator_observation = with_moderator_observation t operation_id
    ; with_next_moderator_observation = with_next_moderator_observation t operation_id
    ; run_actions = (fun executing -> call t (Run_actions executing))
    ; with_moderator_event =
        (fun ~snapshot ~event ->
          with_current_moderator_event
            t
            ~operation_id:(Some operation_id)
            ~event
            ~snapshot)
    ; with_queued_moderator_event =
        with_current_queued_moderator_event_tools t ~operation_id:(Some operation_id)
    ; manage_moderator_follow_up =
        (fun ~observer -> call t (Manage_moderator_follow_up (operation_id, observer)))
    ; admit_moderator_turn = (fun () -> call t (Admit_moderator_turn operation_id))
    ; admit_notification_turn = (fun () -> call t (Admit_notification_turn operation_id))
    ; with_invocation = with_invocation t operation_id
    ; root_context =
        Option.map t.configuration_policy ~f:(fun _ ->
          root_configuration_context t operation_id)
    ; settle_tool_batch =
        Option.map (current_context_capacity_basis t) ~f:(fun _ batch ->
          call t (Context_request (Rollover (Worker_settled (publication, batch)))))
    ; consume_deferred = (fun () -> call t (Consume_deferred publication))
    ; consume_notifications =
        (fun plan ->
          Eio.Cancel.protect (fun () ->
            call t (Consume_notifications (publication, plan))))
    ; consume_initial_notifications =
        (fun plan ->
          Eio.Cancel.protect (fun () ->
            call t (Consume_initial_notifications (publication, plan))))
    ; request_permission =
        (fun ~permission ~timeout_seconds ~fallback ~review_on_timeout ->
          request_permission_with_review_internal
            t
            ~permission
            ~timeout_seconds
            ~fallback
            ~review_on_timeout)
    ; request_review =
        (fun ~permission ~review -> request_review_internal t ~permission ~review)
    ; responder_available =
        (fun () ->
          call t Has_writer_attachment |> Result.ok |> Option.value ~default:false)
    ; invocation_granted =
        (fun ~tool_name ~identity_digest ->
          call t (Invocation_granted (tool_name, identity_digest))
          |> Result.ok
          |> Option.value ~default:false)
    ; publish_live =
        (fun payload ->
          match check_live_foreground_publication t publication with
          | Ok () -> publish_worker_live t buffer payload
          | Error _ -> ())
    }
;;

(* This owner continues only the actual root ACK. Startup preparation and old
   target Current are not used after Worker_ready advances its own actor state. *)
let held_operation_basis t (held : Held_operation.t) =
  let open Result.Let_syntax in
  let proof = held.proof in
  let%bind () = require_runtime_admission t in
  let%bind () =
    match held.phase, t.operation_agent_custody, t.state.active_operation with
    | Pending_first_effect, Some owner, Some operation
      when Option.exists owner.held ~f:(phys_equal held)
           && Agent_protocol.Id.Operation.equal operation.id proof.operation.id
           && Int.equal operation.generation proof.operation.generation
           && (match operation.state with
               | Starting | Running -> true
               | Cancelling | Completed | Failed _ | Cancelled | Interrupted _ -> false)
           && Option.exists t.operation_worker ~f:(phys_equal proof.worker)
           && Run_authorities.is_current
                t.run_authorities
                proof.binding
                ~run_id:proof.run.id -> Ok ()
    | _ -> Error (error Conflict "held root first-effect owner was retired or replaced")
  in
  let%bind () = Runtime_source_preparation.validate_target proof.source t.state in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "held root Run index disappeared")
  in
  let%bind run =
    Result.of_option
      (Run_state.find index proof.run.id)
      ~error:(error Conflict "held root Run disappeared")
  in
  let%bind admission =
    Run_state.receipt
      index
      ~principal_id:proof.admission.principal_id
      ~key:proof.admission.key
      ~request_sha256:proof.admission.request_sha256
  in
  let%bind () =
    if Option.exists admission ~f:(Agent_protocol.Run_receipt.equal proof.admission)
    then Ok ()
    else Error (error Conflict "held root Admission changed")
  in
  let%bind store = require_recurrence_controller t in
  let%bind () =
    Activation_association.check_target
      proof.controller.association
      ~store
      ~state:t.state
      ~run
      ~admission:proof.admission
  in
  let%bind work =
    Agent_protocol.Run_work.create
      ~key:(Operation proof.operation.id)
      ~generation:proof.operation.generation
  in
  let%bind () =
    if
      List.mem run.owned_work work ~equal:Agent_protocol.Run_work.equal
      && not
           (List.exists run.terminal_work ~f:(fun terminal ->
              Agent_protocol.Run_work.equal
                terminal.Agent_protocol.Run_work.Terminal.work
                work))
    then Ok ()
    else Error (error Conflict "held root no longer owns its unresolved Operation")
  in
  match run.lifecycle with
  | Admitted | Active -> Ok ()
  | Waiting _ | Terminal _ -> Error (error Conflict "held root Run cannot start")
;;

let start_held_operation t held cancelled =
  let open Result.Let_syntax in
  let controller = held.Held_operation.proof.controller in
  let cancelled_check () =
    match Eio.Promise.peek cancelled with
    | None -> Ok ()
    | Some () -> Error (error Conflict "held root was cancelled before its first effect")
  in
  let pure () =
    let%bind () = cancelled_check () in
    let%bind () = held_operation_basis t held in
    let%bind () = controller.basis () in
    match held.target_current with
    | Some current when Recurrence_controller.is_current current -> Ok ()
    | Some _ | None -> Error (error Conflict "held root needs fresh target Store custody")
  in
  let%bind () = cancelled_check () in
  let%bind () = held_operation_basis t held in
  let%bind target = require_recurrence_controller t in
  let%bind current = Recurrence_controller.observe target t.state in
  held.target_current <- Some current;
  let%bind () = controller.refresh () in
  (* Store refresh above may yield. Every host policy runs again before fresh
     clocks, originals, and the joint callback-free fence. *)
  let%bind () = pure () in
  let%bind () = Run_admission.Scope.authorize held.proof.scope t.state in
  let%bind () = controller.policy () in
  let%bind () = controller.timing () in
  let%bind () = Run_admission.Scope.check_current held.proof.scope in
  let%bind () = controller.authority () in
  let%bind () = pure () in
  held.phase <- Started;
  controller.close ();
  Ok ()
;;

let run_worker_operation ?held ?descendant_guard t worker input capabilities cancelled =
  match
    Eio.Fiber.first
      (fun () ->
         Eio.Switch.run (fun sw ->
           (* The readiness acknowledgement may have cancelled a Starting
              operation. Do not dispatch its synchronous prefix before the
              competing cancellation fiber has a chance to run. *)
           match Eio.Promise.peek cancelled with
           | Some () -> `Cancelled
           | None ->
             (match
                Option.value_map held ~default:(Ok ()) ~f:(fun held ->
                  start_held_operation t held cancelled)
              with
              | Error failure -> `Finished (Operation_worker.Failed failure)
              | Ok () ->
                let checked =
                  let open Result.Let_syntax in
                  let%bind () =
                    Option.value_map
                      descendant_guard
                      ~default:(Ok ())
                      ~f:Operation_descendant_guard.refresh
                  in
                  let%bind () =
                    check_operation_descendant t input.Operation_worker.Input.operation.id
                  in
                  Option.value_map
                    descendant_guard
                    ~default:(Ok ())
                    ~f:Operation_descendant_guard.check_current
                in
                (match checked with
                 | Error failure -> `Finished (Operation_worker.Failed failure)
                 | Ok () ->
                   `Finished (Operation_worker.run worker ~sw ~input capabilities)))))
      (fun () ->
         Eio.Promise.await cancelled;
         `Cancelled)
  with
  | `Finished outcome -> outcome
  | `Cancelled -> Operation_worker.Cancelled { reason = "operation cancelled" }
;;

let run_worker
      ?held
      ?descendant_guard
      t
      worker
      (publication : Foreground_publication.t)
      history
  =
  let operation = publication.operation in
  let operation_id = operation.Agent_protocol.Operation.id in
  let id_source =
    History_id_source.create
      ~namespace:(Agent_protocol.Id.Session.to_string publication.session)
      ~block_size:64
      ~reserve:(fun ~count -> call t (Reserve_history_block (Some publication, count)))
  in
  match id_source with
  | Error failure -> Operation_worker.Failed failure
  | Ok id_source ->
    let buffer =
      Live_event_buffer.create ~capacity:2_048 ~session_id:publication.session ~operation_id
    in
    let capabilities = worker_capabilities t publication id_source buffer in
    let input =
      Operation_worker.Input.
        { session_id = publication.session
        ; session_generation = publication.generation
        ; operation
        ; history
        }
    in
    let cancelled, cancel_resolver = Eio.Promise.create () in
    let cancel () = ignore (Eio.Promise.try_resolve cancel_resolver ()) in
    (try
       match
         call t ~priority:Priority (Worker_ready (Foreground publication, cancel))
       with
       | Error failure -> Operation_worker.Failed failure
       | Ok () ->
         run_worker_operation
           ?held
           ?descendant_guard
           t
           worker
           input
           capabilities
           cancelled
     with
     | Eio.Cancel.Cancelled reason ->
       Operation_worker.Cancelled { reason = Exn.to_string reason }
     | exn -> Operation_worker.Failed (worker_failure exn))
;;

let launch_worker t operation =
  let operation_id = operation.Agent_protocol.Operation.id in
  let completion = capture_operation_completion t operation_id in
  (* Capture the physical worker's cell, not a later operation's mutable slot.
     A failed terminal save cannot extend the callback that already returned. *)
  let custody =
    Option.bind
      t.operation_agent_custody
      ~f:(fun { Operation_owner.operation_id = owner; admission; _ } ->
        if Agent_protocol.Id.Operation.equal owner operation_id
        then Some admission
        else None)
  in
  let held =
    Option.bind t.operation_agent_custody ~f:(fun owner ->
      if Agent_protocol.Id.Operation.equal owner.operation_id operation_id
      then owner.held
      else None)
  in
  (* Select synchronously: replacement after this handoff cannot redirect the
     already accepted operation to another runtime's worker. *)
  let worker =
    match held with
    | Some held -> Some held.proof.worker
    | None -> t.operation_worker
  in
  let descendant_guard =
    Option.bind t.operation_agent_custody ~f:(fun owner ->
      if Agent_protocol.Id.Operation.equal owner.operation_id operation_id
      then owner.descendant_guard
      else None)
  in
  let history =
    let open Result.Let_syntax in
    let%bind () = reconcile_foreground_invocations t in
    History_codec.all_of_protocol t.state.conversation.canonical_history
  in
  (* Select ownership alongside the actual reconciled history, before forking.
     A later launch can replace the slot but cannot rewrite this capture. *)
  let publication = Foreground_publication.capture t.state ~operation ~completion in
  t.foreground_publication <- Some publication;
  let retire_authority () =
    Atomic.set publication.live false;
    Option.iter custody ~f:retire_agent_admission;
    Option.iter held ~f:Held_operation.retire;
    Option.iter descendant_guard ~f:Operation_descendant_guard.retire
  in
  match history with
  | Error failure ->
    retire_authority ();
    Eio.Fiber.fork ~sw:t.sw (fun () ->
      ignore
        (call t ~priority:Priority (Worker_terminal (publication, Failed failure, None))
         : (unit, Agent_protocol.Error.t) result))
  | Ok history ->
    Eio.Fiber.fork ~sw:t.sw (fun () ->
      let compaction_custody = ref None in
      let outcome =
        Exn.protect ~finally:retire_authority ~f:(fun () ->
          let outcome =
            match worker with
            | Some worker ->
              run_worker ?held ?descendant_guard t worker publication history
            | None ->
              Operation_worker.Failed
                (error Invalid_state "session has no foreground operation worker")
          in
          (* This private completion handoff is staged while the exact physical
             worker remains live. Only this Completed result may consume it, and
             only after its terminal transition ACK. It is never a new borrower
             of an already-retired operation. *)
          if outcome_requests_compaction outcome
          then
            Option.iter
              (Option.bind custody ~f:(fun admission ->
                 Execution_custody.Admission.custody admission))
              ~f:(fun custody ->
                match transfer_agent_custody custody with
                | Ok child -> compaction_custody := Some child
                | Error _ ->
                  (* Preserve known-but-unavailable provenance. The parent cell
                   retires below and the actor must reject this handoff, even
                   when no instructions are currently selected. None is only
                   genuinely unbound legacy execution. *)
                  compaction_custody := Some custody);
          outcome)
      in
      Exn.protect
        ~f:(fun () ->
          ignore
            (call
               t
               ~priority:Priority
               (Worker_terminal (publication, outcome, !compaction_custody))
             : (unit, Agent_protocol.Error.t) result))
        ~finally:(fun () -> Option.iter !compaction_custody ~f:retire_agent_custody))
;;

let create_turn_operation t reason =
  let timestamp = t.services.now () in
  Agent_protocol.Operation.
    { id = Agent_protocol.Id.Operation.create ()
    ; generation = t.state.identity.generation
    ; kind = Turn reason
    ; state = Starting
    ; started_at = timestamp
    ; updated_at = timestamp
    }
;;

let prune_pending_agent_custody t =
  t.pending_agent_custody
  <- List.filter t.pending_agent_custody ~f:(fun (entry, custody) ->
       let retained =
         List.exists t.state.conversation.deferred_user_entries ~f:(fun pending ->
           equal_agent_entry entry (Pending_input_document.entry pending))
       in
       if not retained then retire_agent_custody custody;
       retained)
;;

let remember_pending_agent_actor t entry original_actor =
  prune_pending_agent_custody t;
  Option.iter original_actor ~f:(fun actor ->
    if
      List.exists t.state.conversation.deferred_user_entries ~f:(fun pending ->
        equal_agent_entry entry (Pending_input_document.entry pending))
    then
      t.pending_agent_custody
      <- (entry, create_agent_custody actor) :: t.pending_agent_custody)
;;

let pending_adoption_agent_custody t entries =
  match entries with
  | [ entry ] ->
    (match
       List.find t.pending_agent_custody ~f:(fun (pending, _) ->
         equal_agent_entry entry pending)
     with
     | None -> Ok None
     | Some (_, custody) -> Result.map (transfer_agent_custody custody) ~f:Option.some)
  | [] | _ :: _ :: _ -> Ok None
;;

let admission_agent_custody t admission =
  Turn_admission.payloads admission
  |> List.concat_map ~f:(function
    | Agent_protocol.Event.Durable.Payload.History_appended entries -> entries
    | _ -> [])
  |> pending_adoption_agent_custody t
;;

let adopted_agent_custody t entries incoming original_actor =
  match entries with
  | [ entry ] when equal_agent_entry entry incoming ->
    Ok (Option.map original_actor ~f:create_agent_custody)
  | _ -> pending_adoption_agent_custody t entries
;;

let check_turn_custody t custody =
  let open Result.Let_syntax in
  let%bind () = require_runtime_admission t in
  let%bind () =
    Option.value_map custody ~default:(Ok ()) ~f:(fun custody ->
      Execution_custody.actor custody |> Result.map ~f:ignore)
  in
  require_runtime_admission t
;;

let descendant_reservations = Goal_descendant_admission_custody.descendant_reservations

let check_descendant_before_writer =
  Goal_descendant_admission_custody.check_descendant_before_writer
;;

let prepare_descendant_before_writer =
  Goal_descendant_admission_custody.prepare_descendant_before_writer
;;

let check_descendant_admitted_views =
  Goal_descendant_admission_custody.check_descendant_admitted_views
;;

let descendant_admitted_views =
  Goal_descendant_admission_custody.descendant_admitted_views
;;

let prepare_idle_message_input ?original_actor ?operation ~owner ~timing t entry =
  let open Result.Let_syntax in
  let%bind () = require_runtime_admission t in
  let%bind () = reconcile_foreground_invocations t in
  let%bind enqueue = prepare_pending_inputs t ~owner timing [ entry ] in
  let%bind pending =
    Pending_turn.prepare
      t.state
      ~enqueue
      ~entry
      ~runtime_admission_open:(runtime_admission_open t)
  in
  let entries = Pending_turn.entries pending in
  let%bind operation_custody =
    match operation, original_actor with
    | Some _, Some actor -> Ok (Some (create_agent_custody actor))
    | Some _, None | None, _ -> adopted_agent_custody t entries entry original_actor
  in
  let%map () =
    if Option.is_some operation && not (Pending_turn.accepted pending)
    then
      Error
        (error Pending_input_conflict "run input is blocked by the pending FIFO prefix")
    else Ok ()
  in
  pending, operation_custody
;;

let idle_message_turn ?operation ~extra_deltas t pending =
  let operation =
    Option.value_or_thunk operation ~default:(fun () ->
      create_turn_operation t User_submit)
  in
  let lifecycle = lifecycle_for_operation t operation.id in
  let delta =
    Session_delta.Batch
      (extra_deltas
       @ Pending_turn.turn_deltas pending
       @ [ Session_delta.Active_operation_changed (Some operation)
         ; Lifecycle_changed lifecycle
         ])
  in
  let payloads =
    Pending_turn.deferred_payloads pending
    @ [ Agent_protocol.Event.Durable.Payload.History_appended
          (Pending_turn.entries pending)
      ; Operation_started operation
      ; Session_state_changed
          { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
      ]
  in
  operation, delta, payloads
;;

let submit_idle_message
      ?original_actor
      ?run_preparation
      ?commit_attempted
      ?(extra_deltas = [])
      ?(owner = Pending_input_document.Owner.Host_internal)
      ?(timing = Agent_protocol.Pending_input.Timing.Safe_boundary)
      ?operation
      t
      entry
  =
  let open Result.Let_syntax in
  let%bind pending, operation_custody =
    prepare_idle_message_input ?original_actor ?operation ~owner ~timing t entry
  in
  let entries = Pending_turn.entries pending in
  let accepted = Pending_turn.accepted pending in
  let deferred_payloads = Pending_turn.deferred_payloads pending in
  if List.is_empty entries
  then (
    let%map session =
      transition
        ?run_preparation
        ?commit_attempted
        t
        ~delta:
          (Session_delta.Batch (extra_deltas @ [ Pending_turn.enqueue_delta pending ]))
        ~payloads:deferred_payloads
    in
    remember_pending_agent_actor t entry original_actor;
    { session; history_id = entry.id; disposition = Deferred; operation_id = None })
  else (
    let operation, delta, payloads =
      idle_message_turn ?operation ~extra_deltas t pending
    in
    let completion_sample = producer_completion_sample t ~delta in
    let before = t.state in
    let%bind candidate =
      prepare_transition ?completion_sample ?run_preparation t ~delta ~payloads
    in
    let attempted =
      Option.value_or_thunk commit_attempted ~default:(fun () -> ref false)
    in
    let%bind staged =
      Turn_admission_staging.capture
        ~owner:t.run_preparation_owner
        ~before
        ~candidate
        ~operation
        ~remaining_audit:t.command_audit
        ~commit_attempted:attempted
        ~plan:(operation, operation_custody, entry, original_actor, accepted)
    in
    let%bind () =
      install
        ~turn_stage:staged
        ?run_preparation
        ~commit_attempted:attempted
        ?completion_sample
        ~check_before_commit:(fun () ->
          let%bind () = check_turn_custody t operation_custody in
          let%bind () =
            match run_preparation with
            | None -> Ok ()
            | Some preparation ->
              let%bind () =
                Run_preparation.check_current
                  preparation
                  ~owner:t.run_preparation_owner
                  ~state:t.state
              in
              Run_preparation.check_basis
                preparation
                ~owner:t.run_preparation_owner
                ~state:t.state
          in
          Turn_admission_staging.check_before_writer
            staged
            ~owner:t.run_preparation_owner
            ~state:t.state)
        t
        candidate
    in
    let session = Session_state.summary t.state in
    let%bind acknowledgement =
      Turn_admission_staging.acknowledge
        staged
        ~owner:t.run_preparation_owner
        ~state:t.state
    in
    let%map operation, operation_custody, entry, original_actor, accepted =
      Turn_admission_staging.finish
        acknowledgement
        ~owner:t.run_preparation_owner
        ~state:t.state
    in
    install_operation_agent_custody t operation operation_custody;
    remember_pending_agent_actor t entry original_actor;
    launch_worker t operation;
    { session
    ; history_id = entry.id
    ; disposition = (if accepted then Started else Deferred)
    ; operation_id = Option.some_if accepted operation.id
    })
;;

let capture_inherited_turn_plan
  : type outcome.
    t
    -> capture:outcome Inherited_turn.Capture.t
    -> source:outcome Inherited_turn.Source.t
    -> commit_attempted:bool ref
    -> delta:Session_delta.t
    -> payloads:Agent_protocol.Event.Durable.Payload.t list
    -> (outcome Inherited_turn.Decision.t, Agent_protocol.Error.t) result
  =
  fun t ~capture ~source ~commit_attempted ~delta ~payloads ->
  let open Result.Let_syntax in
  let before = t.state in
  let%bind accounting =
    Result.of_option
      before.goal_descendants
      ~error:(error Permission_denied "inherited Turn accounting disappeared")
  in
  let%bind () =
    if Int64.equal before.counters.revision Int64.max_value
    then Error (error Conflict "inherited Turn revision is exhausted")
    else Ok ()
  in
  let operation = Inherited_turn.Source.operation source in
  let%bind frame =
    Goal_descendant_occurrence.Frame.create
      ~session:(Goal_descendants.session accounting)
      ~generation:before.identity.generation
      ~candidate_session_revision:(Int64.succ before.counters.revision)
  in
  let%bind occurrence =
    Goal_descendant_occurrence.host_turn frame ~operation_id:operation.id
  in
  let%bind () = Inherited_turn.Capture.check_waiting capture in
  let%bind slot =
    acquire_descendant_admission_slot t ~occurrence ~writer_attempted:(ref false)
  in
  let completion_sample =
    let retained =
      match source with
      | Idle source -> (Idle_source.turn source).completion_sample
      | Goal_subscription source -> source.turn.completion_sample
      | Message _ | Managed _ | Run_user _ | History _ | Held_input _ | Goal_resume _ ->
        None
    in
    producer_completion_sample ?completion_sample:retained t ~delta
  in
  let plan =
    { Inherited_turn.slot
    ; before
    ; commit_attempted
    ; delta
    ; payloads
    ; completion_sample
    ; remaining_audit = t.command_audit
    ; source
    ; phase = Pending
    ; cancellation = Not_requested
    }
  in
  let published =
    let%bind () =
      Option.value_map (Inherited_turn.Source.run source) ~default:(Ok ()) ~f:(fun run ->
        Option.value_map run.preparation_exit ~default:(Ok ()) ~f:(fun exit ->
          Run_preparation.Admission_exit.transfer exit ~owner:t.run_preparation_owner))
    in
    let%bind () =
      match source with
      | Held_input source ->
        let%map () =
          Run_preparation.Admission_exit.transfer
            source.preparation_exit
            ~owner:t.run_preparation_owner
        in
        source.selection.scope.phase
        <- Admission_pending (source.selection.input, source.preparation_exit)
      | Message _
      | Managed _
      | Run_user _
      | History _
      | Goal_resume _
      | Goal_subscription _
      | Idle _ -> Ok ()
    in
    let%bind () =
      match source with
      | Idle (Legacy_completion source) ->
        (match t.idle_turn_continuation with
         | Some continuation
           when phys_equal continuation.Idle_continuation.owner source.owner ->
           continuation.phase <- Bound plan;
           Ok ()
         | None | Some _ ->
           Error (error Conflict "legacy Turn lost its selected continuation"))
      | Idle (Notifications _ | Follow_up _) -> Ok ()
      | Message _
      | Managed _
      | Run_user _
      | History _
      | Goal_resume _
      | Goal_subscription _
      | Held_input _ -> Ok ()
    in
    Inherited_turn.Capture.publish capture plan
  in
  match published with
  | Ok () -> Ok (Inherited_turn.Decision.Pending plan)
  | Error failure ->
    (* No yield/root attempt can occur in capture. Release the actual sealed
       Slot and its same Run exit, not an inference from an attempted writer. *)
    let%bind closed = seal_descendant_admission_slot t slot in
    let%bind () = release_closed_descendant_admission_slot t slot ~closed in
    close_inherited_run_exit t source;
    Error failure
;;

let capture_inherited_message
      ?original_actor
      t
      ~capture
      ~attachment_id
      ~submitting_principal
      ~timing
      entry
  =
  let open Result.Let_syntax in
  let%bind () = require_available_descendant_admission_slot t in
  let%bind pending, custody =
    prepare_idle_message_input
      ?original_actor
      ~owner:(Submitting_principal submitting_principal)
      ~timing
      t
      entry
  in
  if List.is_empty (Pending_turn.entries pending)
  then (
    let%map session =
      transition
        t
        ~delta:(Pending_turn.enqueue_delta pending)
        ~payloads:(Pending_turn.deferred_payloads pending)
    in
    remember_pending_agent_actor t entry original_actor;
    Inherited_turn.Decision.Completed
      { session; history_id = entry.id; disposition = Deferred; operation_id = None })
  else (
    let transferred = ref false in
    Exn.protect
      ~finally:(fun () ->
        if not !transferred then Option.iter custody ~f:retire_agent_custody)
      ~f:(fun () ->
        let operation, delta, payloads = idle_message_turn ~extra_deltas:[] t pending in
        let source =
          Inherited_turn.Source.Message
            { attachment_id
            ; submitting_principal
            ; operation
            ; custody
            ; entry
            ; original_actor
            ; accepted = Pending_turn.accepted pending
            }
        in
        let%map decision =
          capture_inherited_turn_plan
            t
            ~capture
            ~source
            ~commit_attempted:(ref false)
            ~delta
            ~payloads
        in
        transferred := true;
        decision))
;;

let check_inherited_message_admission t (source : Inherited_turn.Source.message) =
  let open Result.Let_syntax in
  let%bind () = check_turn_custody t source.custody in
  match source.original_actor with
  | None -> Ok ()
  | Some actor ->
    let principal = Operator_authorization.principal actor in
    if
      Operator_authorization.is_current actor
      && Agent_protocol.Principal.has_scope principal Send_messages
      && Agent_protocol.Id.Principal.equal principal.id source.submitting_principal
    then Ok ()
    else
      Error (error Permission_denied "inherited message original authentication expired")
;;

let check_inherited_message_source t (source : Inherited_turn.Source.message) =
  let%bind.Result _ = write_attachment t source.attachment_id in
  check_inherited_message_admission t source
;;

let check_inherited_managed_origin = function
  | Inherited_turn.Managed_origin.Trusted_host -> Ok ()
  | Native borrowed -> Native_tool_invocation.check_borrowed_effect_current borrowed
;;

let check_history_input
  : type outcome.
    t -> outcome Inherited_turn.History_input.t -> (unit, Agent_protocol.Error.t) result
  =
  fun t input ->
  let open Result.Let_syntax in
  let%bind () =
    match input with
    | Edit { request; _ } ->
      history_command_precondition
        t
        request.session_id
        request.attachment_id
        request.expected_generation
        request.expected_revision
    | Continue { request; _ } ->
      history_command_precondition
        t
        request.session_id
        request.attachment_id
        request.expected_generation
        request.expected_revision
  in
  if
    Option.exists
      t.operation_worker
      ~f:(phys_equal (Inherited_turn.History_input.worker input))
  then Ok ()
  else Error (error Conflict "history continuation runtime changed before admission")
;;

let select_held_input_source ?pending_exit t (scope : Held_input_scope.t) input =
  let open Result.Let_syntax in
  let activation = Admitted_activation.Continuation.target scope.continuation in
  let%bind () = input_scope_basis t scope in
  let%bind () =
    match scope.phase, pending_exit with
    | Parsed_ready recorded, None
      when Runtime_input_preparation.Prepared_input.equal recorded input -> Ok ()
    | Admission_pending (recorded, actual), Some expected
      when phys_equal actual expected
           && Runtime_input_preparation.Prepared_input.equal recorded input ->
      Run_preparation.Admission_exit.check actual ~owner:t.run_preparation_owner
    | ( ( Parsing
        | Parsed_ready _
        | Admission_pending _
        | Consumed _
        | Root_attempt_unconfirmed
        | Closed )
      , (Some _ | None) ) ->
      Error (error Conflict "held root requires its unconsumed recorded parsed input")
  in
  let%bind () =
    match
      t.state.lifecycle.desired, t.state.lifecycle.observed, t.state.active_operation
    with
    | Running, Idle, None
      when (not t.idle_moderator_borrowed)
           && Option.is_none t.state.failure
           && (not t.state.halted)
           && List.is_empty scope.graphs -> Ok ()
    | _ -> Error (error Conflict "held root requires an idle running target")
  in
  let%bind () = check_held_effect scope.continuation in
  let%bind worker =
    Result.of_option
      t.operation_worker
      ~error:(error Invalid_state "held root has no actual foreground worker")
  in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "held root Run index disappeared")
  in
  let%bind run =
    Result.of_option
      (Run_state.find index activation.run.id)
      ~error:(error Conflict "held root Run disappeared")
  in
  let%bind binding =
    Result.of_option
      (Run_authorities.find t.run_authorities run.id)
      ~error:(error Permission_denied "held root lost its actual Run authority")
  in
  let%bind () =
    if phys_equal (Run_authorities.scope binding) activation.scope
    then Ok ()
    else Error (error Conflict "held root Run binding was replaced")
  in
  let%bind store = require_recurrence_controller t in
  let%bind () =
    Activation_association.check_target
      activation.association
      ~store
      ~state:t.state
      ~run
      ~admission:activation.admission
  in
  let%bind original =
    Result.of_option
      (Run_admission.Scope.original_actor activation.scope)
      ~error:(error Permission_denied "held root requires its genuine original")
  in
  let%bind () =
    Runtime_input_preparation.Prepared_input.validate
      input
      ~request:scope.request
      ~id:scope.id
  in
  Ok
    ({ scope; input; worker; run; binding; original }
     : Inherited_turn.Held_input_selection.t)
;;

let check_inherited_held_source t (source : Inherited_turn.Source.held_input) =
  let open Result.Let_syntax in
  let expected = source.selection in
  let%bind current =
    select_held_input_source
      ~pending_exit:source.preparation_exit
      t
      expected.scope
      expected.input
  in
  if
    phys_equal current.worker expected.worker
    && phys_equal current.binding expected.binding
    && phys_equal current.original expected.original
    && Agent_protocol.Run.equal current.run expected.run
  then check_turn_custody t source.custody
  else Error (error Conflict "held Turn lost its exact selected source")
;;

let joined_goal_runtime_basis t (scope : Goal_continuation.runtime_scope) =
  let open Result.Let_syntax in
  let%bind () = goal_runtime_scope_basis t scope in
  let%bind () =
    match scope.callback with
    | Joined
      when Option.is_none t.queued_event_borrow
           && (not (moderator_is_borrowed t))
           && Option.is_none t.initialization_scope -> Ok ()
    | Pending | Executing _ | Completed _ | Joined ->
      Error (error Conflict "Goal lifecycle ownership has not joined")
  in
  Run_admission.Scope.check_current
    (Run_authorities.scope scope.continuation.binding.preparation.binding)
;;

let check_goal_resume_selection t (selected : Inherited_turn.Goal_resume_selection.t) =
  let open Result.Let_syntax in
  let scope = selected.scope in
  let preparation = scope.continuation.binding.preparation in
  let%bind () = joined_goal_runtime_basis t scope in
  let%bind () = check_runtime_construction_effect (Existing_goal scope.continuation) in
  let%bind current = goal_runtime_run t scope in
  if
    Option.is_none t.state.active_operation
    && Agent_protocol.Run.equal current selected.run
    && Run_authorities.is_current t.run_authorities preparation.binding ~run_id:current.id
    && Option.exists
         (Run_admission.Scope.original_actor (Run_authorities.scope preparation.binding))
         ~f:(phys_equal selected.original)
    && Agent_protocol.Goal_episode.matches_run
         (Run_goal_link.episode preparation.link)
         current
  then Ok ()
  else Error (error Conflict "Goal Resume lost its selected existing Run or source")
;;

let check_idle_turn_source t (turn : Idle_turn.t) =
  let open Result.Let_syntax in
  let%bind observer = Runtime_builder.moderator_snapshot_observer t.state.moderator in
  if
    Int.equal turn.before.identity.generation t.state.identity.generation
    && Option.equal phys_equal t.operation_worker turn.worker
    && Option.equal phys_equal t.moderator_manager turn.manager
    && Option.equal Agent_protocol.Invocation.equal_observer observer turn.observer
  then Ok ()
  else Error (error Conflict "selected idle Turn source or worker changed")
;;

let check_idle_turn_selection t source =
  let open Result.Let_syntax in
  let turn = Idle_source.turn source in
  let%bind () = check_idle_turn_source t turn in
  let%bind () =
    if phys_equal turn.before t.state
    then Ok ()
    else Error (error Conflict "selected idle Turn basis changed")
  in
  let%bind () = require_selected_execution t in
  let%bind () = require_runtime_admission t in
  let%bind () = check_turn_custody t turn.custody in
  let%bind () =
    Option.value_map
      turn.follow_up_authority
      ~default:(Ok ())
      ~f:(check_follow_up_authority t)
  in
  Option.value_map (Idle_source.legacy_owner source) ~default:(Ok ()) ~f:(fun owner ->
    let%bind () = check_idle_completion_owner t owner in
    match owner.cancellation with
    | None -> Ok ()
    | Some failure -> Error failure)
;;

let check_goal_subscription_selection
      t
      (selected : Inherited_turn.Goal_subscription_selection.t)
  =
  let open Result.Let_syntax in
  let scope = selected.scope in
  let preparation = scope.continuation.binding.preparation in
  let%bind () = joined_goal_runtime_basis t scope in
  let%bind () = check_runtime_construction_effect (Existing_goal scope.continuation) in
  let%bind current = goal_runtime_run t scope in
  let%bind wake = Goal_execution_runtime.wake scope.continuation in
  let%bind () =
    match preparation.cause, current.lifecycle, wake.occurrence with
    | Pending_wake { wake = original; _ }, Waiting retained, Subscription_delivery _
      when Agent_protocol.Run.equal current selected.run
           && Agent_protocol.Run_wake.equal wake selected.wake
           && Agent_protocol.Run_wake.equal wake original
           && Agent_protocol.Run_wake.equal wake retained
           && Run_authorities.is_current
                t.run_authorities
                preparation.binding
                ~run_id:current.id
           && Option.exists
                (Run_admission.Scope.original_actor
                   (Run_authorities.scope preparation.binding))
                ~f:(phys_equal selected.original)
           && Agent_protocol.Goal_episode.matches_run
                (Run_goal_link.episode preparation.link)
                current -> Ok ()
    | ( (Resume_command _ | Pending_wake _ | Claimed_job _)
      , (Admitted | Active | Waiting _ | Terminal _)
      , (Subscription_delivery _ | Delivered_timer _ | Job_completion _) ) ->
      Error (error Conflict "Goal subscription lost its selected Run or exact Wait")
  in
  let%bind () = check_idle_turn_source t selected.turn in
  let%bind () =
    if
      phys_equal selected.turn.before t.state
      && Option.is_none t.state.active_operation
      && Option.exists selected.turn.worker ~f:(phys_equal scope.worker)
      && Option.equal phys_equal selected.turn.manager scope.manager
    then Ok ()
    else Error (error Conflict "Goal subscription Turn selection changed")
  in
  let%bind () = require_selected_execution t in
  let%bind () = require_runtime_admission t in
  check_turn_custody t selected.turn.custody
;;

let check_inherited_turn_source
  : type outcome.
    ?refresh_policy:bool
    -> t
    -> outcome Inherited_turn.Source.t
    -> (unit, Agent_protocol.Error.t) result
  =
  fun ?(refresh_policy = false) t source ->
  let open Result.Let_syntax in
  match source with
  | Idle source -> check_idle_turn_selection t source
  | Message message -> check_inherited_message_source t message
  | Held_input source -> check_inherited_held_source t source
  | Goal_resume source -> check_goal_resume_selection t source.selection
  | Goal_subscription selected -> check_goal_subscription_selection t selected
  | History history ->
    let%bind () = check_history_input t history.input in
    let%bind () = require_selected_execution t in
    check_turn_custody t history.custody
  | Managed managed ->
    let%bind () = check_turn_custody t managed.custody in
    check_inherited_managed_origin managed.origin
  | Run_user (run, _) ->
    let%bind () = check_turn_custody t run.custody in
    let%bind () =
      if refresh_policy
      then Run_admission.Scope.authorize run.scope t.state
      else Run_admission.Scope.check_current run.scope
    in
    let%bind () =
      match run.request.caller with
      | Writer attachment -> write_attachment t attachment |> Result.map ~f:ignore
      | Headless_command ->
        Option.value_map
          run.preparation
          ~default:(Error (error Permission_denied "Run headless custody disappeared"))
          ~f:(fun preparation ->
            if refresh_policy
            then check_run_preparation t preparation
            else
              Run_preparation.check_current
                preparation
                ~owner:t.run_preparation_owner
                ~state:t.state)
      | Native_goal_start _ ->
        Error (error Permission_denied "native Start has a distinct owner")
    in
    let%bind () =
      Option.value_map run.preparation ~default:(Ok ()) ~f:(fun preparation ->
        Run_preparation.check_current
          preparation
          ~owner:t.run_preparation_owner
          ~state:t.state)
    in
    Option.value_map run.preparation_exit ~default:(Ok ()) ~f:(fun exit ->
      Run_preparation.Admission_exit.check exit ~owner:t.run_preparation_owner)
;;

module Goal_operation_phase = struct
  type t =
    | Staged
    | Installed
    | Closed
  [@@deriving equal]
end

(* Capture the real command original before source closure. Only this private
   actual-ACK installer transfers it to the existing first-prefix owner. *)
let goal_resume_operation_controller t (scope : Goal_continuation.runtime_scope) =
  let open Result.Let_syntax in
  let preparation = scope.continuation.binding.preparation in
  let old_scope = Run_authorities.scope preparation.binding in
  let%bind authorization =
    Run_preparation.Custody.capture_authorization
      (Goal_continuation.custody preparation)
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  let%bind store = require_recurrence_controller t in
  let policy = preparation.policy in
  let association : Activation_association.t =
    { issuer_policy = Goal policy
    ; check_target =
        (fun ~store:current ~state ~run ~admission ->
          if Recurrence_controller.same_store store current
          then Goal_activation_policy.check_association policy ~state ~run ~admission
          else Error (error Conflict "Goal continuation Store changed"))
    }
  in
  let phase = ref Goal_operation_phase.Staged in
  let current = ref None in
  let structural () =
    let%bind () =
      if Goal_operation_phase.equal !phase Installed
      then Ok ()
      else Error (error Conflict "Goal continuation Operation owner is not installed")
    in
    let%bind () =
      Runtime_source_preparation.validate_target scope.continuation.binding.source t.state
    in
    let%bind index =
      Result.of_option
        t.state.run_state
        ~error:(error Conflict "Goal Operation Run index is absent")
    in
    let%bind run =
      Result.of_option
        (Run_state.find index preparation.run.id)
        ~error:(error Conflict "Goal Operation Run is absent")
    in
    let%bind () =
      if Run_authorities.is_current t.run_authorities preparation.binding ~run_id:run.id
      then Ok ()
      else Error (error Permission_denied "Goal Operation lost its original binding")
    in
    Activation_association.check_target
      association
      ~store
      ~state:t.state
      ~run
      ~admission:preparation.admission
  in
  let basis () =
    let%bind () = structural () in
    match !current with
    | Some observed when Recurrence_controller.is_current observed -> Ok ()
    | Some _ | None ->
      Error (error Conflict "Goal continuation Operation requires fresh Store custody")
  in
  let originals () =
    let%bind () = Run_admission.Scope.check_current old_scope in
    Run_preparation.Authorization.check authorization t.state
  in
  let policy_check () =
    let%bind () = structural () in
    let%bind () = Run_admission.Scope.authorize old_scope t.state in
    let%bind () = Goal_activation_policy.check_admitted_policy policy ~state:t.state in
    let%bind () = originals () in
    structural ()
  in
  let refresh () =
    let%bind () = policy_check () in
    let%bind observed = Recurrence_controller.observe store t.state in
    current := Some observed;
    basis ()
  in
  let command_loan = preparation.native_command_loan in
  preparation.native_command_loan <- None;
  Ok
    Activation_controller.Operation.
      { association
      ; install =
          (fun () -> if Goal_operation_phase.equal !phase Staged then phase := Installed)
      ; close =
          (fun () ->
            phase := Closed;
            Option.iter command_loan ~f:Execution_custody.Admission.retire)
      ; refresh
      ; policy =
          (fun () ->
            let%bind () = basis () in
            let%bind () = policy_check () in
            basis ())
      ; timing =
          (fun () ->
            let%bind () = basis () in
            let%bind () =
              Goal_activation_policy.check_deadline
                policy
                ~state:t.state
                ~now:(t.services.now ())
            in
            basis ())
      ; authority =
          (fun () ->
            let%bind () = basis () in
            let%bind () = originals () in
            basis ())
      ; basis
      }
;;

let prepare_goal_operation_ack
      ?descendant_guard
      t
      (scope : Goal_continuation.runtime_scope)
      ~operation
      ~candidate
  =
  let open Result.Let_syntax in
  let continuation = scope.continuation in
  let preparation = continuation.binding.preparation in
  let%bind index =
    Result.of_option
      t.state.run_state
      ~error:(error Conflict "Goal Operation Run index is absent")
  in
  let%bind run =
    Result.of_option
      (Run_state.find index preparation.run.id)
      ~error:(error Conflict "Goal Operation Run is absent")
  in
  let%bind next =
    Option.bind candidate.Session_transition.state.run_state ~f:(fun index ->
      Run_state.find index run.id)
    |> Result.of_option ~error:(error Conflict "Goal Operation candidate lost its Run")
  in
  let%bind () =
    if
      Agent_protocol.Goal_episode.matches_run
        (Run_goal_link.episode preparation.link)
        next
      && List.exists next.owned_work ~f:(fun work ->
        match work.Agent_protocol.Run_work.key with
        | Operation id ->
          Agent_protocol.Id.Operation.equal id operation.Agent_protocol.Operation.id
        | Retained _ -> false)
    then Ok ()
    else Error (error Conflict "Goal Operation candidate lost its actual ownership")
  in
  let%bind handoff =
    match preparation.cause with
    | Resume_command _ -> Ok (Goal_runtime_handoff.Resume (Started operation))
    | Pending_wake { wake; _ } ->
      (match wake.occurrence with
       | Subscription_delivery _ ->
         Ok (Goal_runtime_handoff.Existing_execution (Subscription_turn operation))
       | Job_completion _ | Delivered_timer _ ->
         Error (error Invalid_request "queued Goal wake requires an Event claim"))
    | Claimed_job _ ->
      Error (error Invalid_request "claimed Goal Job cannot start another Operation")
  in
  let old_scope = Run_authorities.scope preparation.binding in
  let%bind original =
    Result.of_option
      (Run_admission.Scope.original_actor old_scope)
      ~error:(error Permission_denied "Goal continuation has no original Run authority")
  in
  let%bind controller = goal_resume_operation_controller t scope in
  let proof : Held_operation.Proof.t =
    { scope = old_scope
    ; run
    ; admission = preparation.admission
    ; source = continuation.binding.source
    ; operation
    ; worker = scope.worker
    ; binding = preparation.binding
    ; controller
    }
  in
  let held : Held_operation.t = { proof; phase = Staged; target_current = None } in
  let owner : Operation_owner.t =
    { operation_id = operation.id
    ; admission = create_agent_admission (Some (create_agent_custody original))
    ; held = Some held
    ; descendant_guard
    ; completion =
        Operation_completion.create
          ~issuer:t.initialization_owner
          ~domain:t.runtime_source_domain
          ~operation
    }
  in
  ({ previous = t.state
   ; candidate
   ; scope
   ; held
   ; owner
   ; completion_slot = Some owner.completion
   ; handoff
   }
   : Goal_runtime_operation_acknowledgement.t)
  |> Result.return
;;

let prepare_inherited_held_ack
      t
      (source : Inherited_turn.Source.held_input)
      ~candidate
      ~guard
  =
  let open Result.Let_syntax in
  let%bind () = check_inherited_held_source t source in
  let selection = source.selection in
  let activation = Admitted_activation.Continuation.target selection.scope.continuation in
  let%bind controller = selection.scope.continuation.controller.transfer () in
  if not (phys_equal controller.association activation.association)
  then (
    controller.close ();
    Error (error Conflict "held root transferred another admitted association"))
  else (
    let proof : Held_operation.Proof.t =
      { scope = activation.scope
      ; run = selection.run
      ; admission = activation.admission
      ; source = activation.source
      ; operation = source.operation
      ; worker = selection.worker
      ; binding = selection.binding
      ; controller
      }
    in
    let held : Held_operation.t = { proof; phase = Staged; target_current = None } in
    let owner : Operation_owner.t =
      { operation_id = source.operation.id
      ; admission = create_agent_admission source.custody
      ; held = Some held
      ; descendant_guard = Some guard
      ; completion =
          Operation_completion.create
            ~issuer:t.initialization_owner
            ~domain:t.runtime_source_domain
            ~operation:source.operation
      }
    in
    let acknowledgement : Held_operation_acknowledgement.t =
      { input_scope = selection.scope
      ; input = selection.input
      ; preparation_exit = Some source.preparation_exit
      ; activation
      ; held
      ; owner
      ; completion_slot = Some owner.completion
      ; previous = t.state
      ; candidate
      }
    in
    Ok acknowledgement)
;;

let commit_inherited_turn
  : type outcome.
    t
    -> outcome Inherited_turn.t
    -> before_writer:Descendant_admission_data.Before_writer.t
    -> (outcome Inherited_turn.Acknowledged.t, Agent_protocol.Error.t) result
  =
  fun t plan ~before_writer ->
  let module R = Descendant_admission_data in
  let open Result.Let_syntax in
  let%bind () =
    match plan.cancellation with
    | Not_requested -> Ok ()
    | Requested failure -> Error failure
  in
  let%bind () =
    match plan.phase with
    | Pending when Option.is_none t.inherited_turn_prepared -> Ok ()
    | Pending | Writer_prepared _ | Acknowledged _ | Closed ->
      Error (error Conflict "Turn writer is already prepared or attempted")
  in
  let%bind () = check_descendant_admission_slot t plan.slot in
  let%bind () = check_descendant_before_writer before_writer in
  let%bind () =
    if
      phys_equal
        before_writer.preparation
        (Descendant_admission_slot.preparation plan.slot)
      && phys_equal
           before_writer.reservations
           (Descendant_admission_slot.reservations plan.slot)
    then Ok ()
    else Error (error Conflict "Turn reservations belong to another physical plan")
  in
  let operation = Inherited_turn.Source.operation plan.source in
  let custody = Inherited_turn.Source.custody plan.source in
  let preparation_owner = Inherited_turn.Source.preparation plan.source in
  let%bind () = check_inherited_turn_source ~refresh_policy:true t plan.source in
  let receipts =
    List.map before_writer.views ~f:(fun (view : R.Root_before_writer.t) ->
      Goal_descendant_included.create view.reservation.pending)
  in
  let preparation = Descendant_admission_slot.preparation plan.slot in
  let%bind inherited_turn =
    Host_turn_tracking.Inherited.create
      ~occurrence:(Descendant_preparation.occurrence preparation)
      ~receipts
  in
  let%bind candidate, edge =
    prepare_transition_inherited
      ?completion_sample:plan.completion_sample
      ?run_preparation:preparation_owner
      t
      ~inherited_turn
      ~delta:plan.delta
      ~payloads:plan.payloads
  in
  let%bind stage =
    Turn_admission_staging.capture
      ~owner:t.run_preparation_owner
      ~before:plan.before
      ~candidate
      ~operation
      ~remaining_audit:plan.remaining_audit
      ~commit_attempted:plan.commit_attempted
      ~plan:plan.source
  in
  let staged_owner = ref None in
  Exn.protect
    ~finally:(fun () -> Option.iter !staged_owner ~f:Operation_owner.retire)
    ~f:(fun () ->
      let guard = Operation_descendant_guard.create_unconfirmed () in
      let%bind goal_runtime_acknowledgement =
        match plan.source with
        | Goal_resume source ->
          Goal_runtime_acknowledgement.prepare t source.selection.scope ~candidate
          |> Result.map ~f:Option.some
        | Goal_subscription selected ->
          Goal_runtime_acknowledgement.prepare t selected.scope ~candidate
          |> Result.map ~f:Option.some
        | Message _ | Managed _ | Run_user _ | History _ | Held_input _ | Idle _ ->
          Ok None
      in
      let prepare_goal_owner scope =
        let%map acknowledgement =
          prepare_goal_operation_ack ~descendant_guard:guard t scope ~operation ~candidate
        in
        let owner = acknowledgement.Goal_runtime_operation_acknowledgement.owner in
        staged_owner := Some owner;
        owner, None, Some acknowledgement
      in
      let%bind owner, held_operation_acknowledgement, goal_operation_acknowledgement =
        match plan.source with
        | Goal_resume source -> prepare_goal_owner source.selection.scope
        | Goal_subscription selected -> prepare_goal_owner selected.scope
        | Held_input source ->
          let%map acknowledgement =
            prepare_inherited_held_ack t source ~candidate ~guard
          in
          let owner = acknowledgement.Held_operation_acknowledgement.owner in
          staged_owner := Some owner;
          owner, Some acknowledgement, None
        | Message _ | Managed _ | Run_user _ | History _ | Idle _ ->
          let owner =
            Operation_owner.
              { operation_id = operation.id
              ; admission = create_agent_admission custody
              ; held = None
              ; descendant_guard = Some guard
              ; completion =
                  Operation_completion.create
                    ~issuer:t.initialization_owner
                    ~domain:t.runtime_source_domain
                    ~operation
              }
          in
          Ok (owner, None, None)
      in
      let native =
        R.Acknowledgement.
          { preparation
          ; identity = ref ()
          ; installed = candidate.state
          ; candidate
          ; edge = Host_turn edge
          ; receipts
          ; reservations = before_writer.reservations
          }
      in
      let acknowledged =
        ({ plan
         ; native
         ; stage
         ; owner
         ; guard
         ; consumed = false
         ; cleanup_progress = Needs_both
         ; cleanup_owner = Idle
         }
         : _ Inherited_turn.acknowledged)
      in
      let prepared = Some (Inherited_turn.Prepared acknowledged) in
      plan.phase <- Writer_prepared acknowledged;
      t.inherited_turn_prepared <- prepared;
      staged_owner := None;
      let%bind slot_acknowledgement =
        prepare_descendant_admission_slot_ack t plan.slot ~acknowledgement:native
      in
      t.command_audit <- plan.remaining_audit;
      let installed =
        install
          ?held_operation_acknowledgement
          ?goal_runtime_acknowledgement
          ?goal_operation_acknowledgement
          ~descendant_admission_acknowledgement:slot_acknowledgement
          ~inherited_turn_acknowledgement:
            (Inherited_turn_acknowledgement.prepare acknowledged)
          ~turn_stage:stage
          ?run_preparation:preparation_owner
          ~commit_attempted:plan.commit_attempted
          ?completion_sample:plan.completion_sample
          ~check_before_commit:(fun () ->
            let%bind () = check_inherited_turn_source t plan.source in
            let%bind () = check_descendant_before_writer before_writer in
            let%bind () = check_descendant_admission_slot t plan.slot in
            Turn_admission_staging.check_before_writer
              stage
              ~owner:t.run_preparation_owner
              ~state:t.state)
          t
          candidate
      in
      (* Publication errors do not erase the exact already-installed canonical ACK. *)
      match plan.phase with
      | Acknowledged actual when phys_equal actual acknowledged -> Ok acknowledged
      | Pending | Writer_prepared _ | Closed | Acknowledged _ ->
        let%bind () = installed in
        Error (error Conflict "Turn writer returned without the exact canonical ACK"))
;;

let check_inherited_turn_ack_owner
  : type outcome.
    t -> outcome Inherited_turn.Acknowledged.t -> (unit, Agent_protocol.Error.t) result
  =
  fun t acknowledged ->
  let open Result.Let_syntax in
  let%bind () =
    match acknowledged.plan.cancellation with
    | Not_requested -> Ok ()
    | Requested failure -> Error failure
  in
  let%bind () = require_runtime_admission t in
  let%bind () =
    check_descendant_host t (Descendant_admission_slot.binding acknowledged.plan.slot)
  in
  let%bind () =
    if
      Descendant_preparation.acknowledged_by
        acknowledged.native.preparation
        ~acknowledgement:acknowledged.native.identity
      && Option.exists t.operation_agent_custody ~f:(phys_equal acknowledged.owner)
      && (not t.state.halted)
      && Option.is_none t.state.failure
      && Agent_protocol.Session.equal_desired_state t.state.lifecycle.desired Running
    then Ok ()
    else Error (error Conflict "inherited Turn lost its acknowledged operation owner")
  in
  let%bind () = check_agent_admission acknowledged.owner.admission in
  let%bind () =
    match acknowledged.plan.source with
    | Held_input source ->
      let selection = source.selection in
      if
        Run_authorities.is_current
          t.run_authorities
          selection.binding
          ~run_id:selection.run.id
      then Run_admission.Scope.check_current (Run_authorities.scope selection.binding)
      else Error (error Conflict "ACKed held Turn lost its actual Run binding")
    | Goal_resume source ->
      let selected = source.selection in
      let preparation = selected.scope.continuation.binding.preparation in
      if
        Run_authorities.is_current
          t.run_authorities
          preparation.binding
          ~run_id:selected.run.id
        && Option.exists t.operation_worker ~f:(phys_equal selected.scope.worker)
        && Option.equal phys_equal t.moderator_manager selected.scope.manager
      then Run_admission.Scope.check_current (Run_authorities.scope preparation.binding)
      else Error (error Conflict "ACKed Goal Resume lost its actual Run or worker")
    | Goal_subscription selected ->
      let preparation = selected.scope.continuation.binding.preparation in
      let%bind () = check_idle_turn_source t selected.turn in
      if
        Run_authorities.is_current
          t.run_authorities
          preparation.binding
          ~run_id:selected.run.id
      then Run_admission.Scope.check_current (Run_authorities.scope preparation.binding)
      else Error (error Conflict "ACKed Goal subscription lost its actual Run binding")
    | Idle source -> check_idle_turn_source t (Idle_source.turn source)
    | Message _ | Managed _ | History _ -> Ok ()
    | Run_user (source, _) ->
      let run = Run_admission.run source.admission in
      if Run_authorities.is_current t.run_authorities source.binding ~run_id:run.id
      then Run_admission.Scope.check_current (Run_authorities.scope source.binding)
      else Error (error Conflict "inherited Run lost its actual ACKed source binding")
  in
  let operation = Inherited_turn.Source.operation acknowledged.plan.source in
  let%bind current = current_operation t operation.id in
  if
    Int.equal current.generation operation.generation
    && Agent_protocol.Operation.equal_kind current.kind operation.kind
    &&
    match current.state with
    | Starting | Running -> true
    | Cancelling | Completed | Failed _ | Cancelled | Interrupted _ -> false
  then Ok ()
  else Error (error Conflict "inherited Turn cannot launch a terminated operation")
;;

let inherited_turn_admitted_guard
  : type outcome.
    t
    -> outcome Inherited_turn.Acknowledged.t
    -> confirmation:Descendant_admission_data.Confirmation.t
    -> views:Descendant_admission_data.Admitted_views.t
    -> (Operation_descendant_guard.admitted, Agent_protocol.Error.t) result
  =
  fun t acknowledged ~confirmation ~views ->
  let module R = Descendant_admission_data in
  let open Result.Let_syntax in
  let cache = ref (Some views) in
  let latest = ref None in
  let check () =
    let%bind () = check_inherited_turn_ack_owner t acknowledged in
    let%bind current =
      Result.of_option
        !cache
        ~error:(error Conflict "inherited Turn admitted root views are unavailable")
    in
    if
      phys_equal
        current.R.Admitted_views.acknowledgement
        acknowledged.Inherited_turn.native
      && phys_equal current.confirmation confirmation
      && phys_equal confirmation.R.Confirmation.acknowledgement acknowledged.native
    then check_descendant_admitted_views current
    else Error (error Conflict "inherited Turn views belong to another canonical ACK")
  in
  let%bind () = check () in
  let refresh () =
    (* Invalidation precedes even the first yielding host check. Failed/cancelled
       newer refreshes cannot expose old policy views, and older completion
       cannot republish after a newer attempt. *)
    let attempt = ref () in
    latest := Some attempt;
    cache := None;
    let published = ref false in
    Exn.protect
      ~finally:(fun () ->
        if (not !published) && Option.exists !latest ~f:(phys_equal attempt)
        then (
          latest := None;
          cache := None))
      ~f:(fun () ->
        let refreshed =
          let%bind () = check_inherited_turn_ack_owner t acknowledged in
          let host = Descendant_admission_slot.host acknowledged.plan.slot in
          let%bind current = host.refresh_admitted acknowledged.native confirmation in
          let%bind () = check_inherited_turn_ack_owner t acknowledged in
          let%bind () =
            if Option.exists !latest ~f:(phys_equal attempt)
            then Ok ()
            else Error (error Conflict "inherited Turn root refresh was superseded")
          in
          cache := Some current;
          let%map () = check () in
          published := true
        in
        match refreshed with
        | Error failure -> raise (Inference_allocation.Rejected failure)
        | Ok () ->
          fun () ->
            (match check () with
             | Ok () -> ()
             | Error failure -> raise (Inference_allocation.Rejected failure)))
  in
  Ok
    ({ submission = Inference_runtime.Submission_guard.create ~refresh
     ; check_current = check
     }
     : Operation_descendant_guard.admitted)
;;

let consume_inherited_turn_suffix
  : type outcome.
    t
    -> outcome Inherited_turn.Acknowledged.t
    -> (outcome Inherited_turn.Source.t, Agent_protocol.Error.t) result
  =
  fun t acknowledged ->
  let open Result.Let_syntax in
  if acknowledged.consumed
  then Error (error Conflict "inherited Turn suffix was already consumed")
  else (
    let%bind actual =
      Turn_admission_staging.acknowledge
        acknowledged.stage
        ~owner:t.run_preparation_owner
        ~state:acknowledged.native.installed
    in
    let%map source =
      Turn_admission_staging.finish
        actual
        ~owner:t.run_preparation_owner
        ~state:acknowledged.native.installed
    in
    acknowledged.consumed <- true;
    source)
;;

let complete_inherited_turn_handoff t (acknowledged : _ Inherited_turn.Acknowledged.t) =
  match t.inherited_turn_cleanup with
  | Some (Pack actual) when phys_equal actual.native acknowledged.native ->
    t.inherited_turn_cleanup <- None
  | None | Some (Pack _) -> ()
;;

let finish_inherited_turn
  : type outcome.
    t
    -> outcome Inherited_turn.Acknowledged.t
    -> confirmation:Descendant_admission_data.Confirmation.t
    -> views:Descendant_admission_data.Admitted_views.t
    -> (outcome, Agent_protocol.Error.t) result
  =
  fun t acknowledged ~confirmation ~views ->
  let open Result.Let_syntax in
  let%bind () =
    match acknowledged.plan.source with
    | History source ->
      if
        Option.exists
          t.operation_worker
          ~f:(phys_equal (Inherited_turn.History_input.worker source.input))
      then Ok ()
      else
        Error
          (error Conflict "history continuation runtime changed after acknowledgement")
    | Goal_resume source ->
      if
        Option.exists t.operation_worker ~f:(phys_equal source.selection.scope.worker)
        && Option.equal phys_equal t.moderator_manager source.selection.scope.manager
      then Ok ()
      else Error (error Conflict "Goal Resume runtime changed after acknowledgement")
    | Goal_subscription selected -> check_idle_turn_source t selected.turn
    | Idle source -> check_idle_turn_source t (Idle_source.turn source)
    | Message _ | Managed _ | Run_user _ | Held_input _ -> Ok ()
  in
  let%bind admitted = inherited_turn_admitted_guard t acknowledged ~confirmation ~views in
  let%bind () = Operation_descendant_guard.admit acknowledged.guard admitted in
  let%bind source = consume_inherited_turn_suffix t acknowledged in
  match source with
  | Goal_subscription selected ->
    complete_inherited_turn_handoff t acknowledged;
    launch_worker t selected.turn.operation;
    (Ok true : (outcome, Agent_protocol.Error.t) result)
  | Idle source ->
    prune_pending_agent_custody t;
    complete_inherited_turn_handoff t acknowledged;
    launch_worker t (Idle_source.operation source);
    let%map () =
      match source with
      | Notifications _ | Follow_up _ -> Ok ()
      | Legacy_completion source ->
        source.owner.outcome <- Some (Ok ());
        let%map () = release_idle_completion t source.owner in
        t.idle_turn_continuation <- None
    in
    Idle_source.reply source
  | Message source ->
    remember_pending_agent_actor t source.entry source.original_actor;
    complete_inherited_turn_handoff t acknowledged;
    launch_worker t source.operation;
    (Ok
       { session = Session_state.summary t.state
       ; history_id = source.entry.id
       ; disposition = (if source.accepted then Started else Deferred)
       ; operation_id = Option.some_if source.accepted source.operation.id
       }
     : (outcome, Agent_protocol.Error.t) result)
  | Held_input source ->
    complete_inherited_turn_handoff t acknowledged;
    launch_worker t source.operation;
    let entry = Runtime_input_preparation.Prepared_input.entry source.selection.input in
    Ok
      { session = Session_state.summary t.state
      ; history_id = entry.id
      ; disposition = Started
      ; operation_id = Some source.operation.id
      }
  | Goal_resume source ->
    complete_inherited_turn_handoff t acknowledged;
    let continuation = source.selection.scope.continuation in
    let operation = Turn_admission.operation source.selection.turn in
    launch_worker t operation;
    Ok
      (Goal_resume_result.Resumed
         { receipt = Goal_continuation.receipt continuation
         ; continuation = Started operation
         })
  | History source ->
    complete_inherited_turn_handoff t acknowledged;
    launch_worker
      t
      (Turn_admission.operation (Inherited_turn.History_input.admission source.input));
    Ok
      (Inherited_turn.History_input.result
         source.input
         ~session:(Session_state.summary t.state))
  | Managed source ->
    let%bind receipt =
      List.find
        t.state.managed_submissions
        ~f:(Managed_submission.same_key source.receipt)
      |> Result.of_option ~error:(error Conflict "ACKed managed receipt disappeared")
    in
    let%bind () =
      if
        String.equal receipt.request_sha256 source.receipt.request_sha256
        && Agent_protocol.History.Id.equal receipt.history_id source.entry.id
      then Ok ()
      else Error (error Conflict "ACKed managed receipt identity changed")
    in
    complete_inherited_turn_handoff t acknowledged;
    launch_worker t source.operation;
    Ok receipt
  | Run_user (source, reply) ->
    complete_inherited_turn_handoff t acknowledged;
    launch_worker t source.operation;
    let receipt = Run_admission.receipt source.admission in
    Ok (Inherited_turn.Run_reply.of_receipt reply receipt)
;;

let retire_acknowledged_turn
  : type outcome.
    t
    -> outcome Inherited_turn.Acknowledged.t
    -> failure:Agent_protocol.Error.t
    -> (unit, Agent_protocol.Error.t) result
  =
  fun t acknowledged ~failure ->
  Operation_descendant_guard.retire acknowledged.guard;
  let open Result.Let_syntax in
  let%bind () =
    if acknowledged.consumed
    then Ok ()
    else Result.map (consume_inherited_turn_suffix t acknowledged) ~f:ignore
  in
  (* Factual retirement may follow a lost suffix reply. Cancel only this exact
     installed worker before terminal cleanup; never a replacement owner, and
     never wait for its unwind in the Actor mailbox. *)
  let expected_operation = Inherited_turn.Source.operation acknowledged.plan.source in
  match t.operation_agent_custody, t.state.active_operation with
  | Some owner, Some active_operation
    when phys_equal owner acknowledged.owner
         && Agent_protocol.Id.Operation.equal active_operation.id expected_operation.id
         && Int.equal active_operation.generation expected_operation.generation
         && Agent_protocol.Operation.equal_kind
              active_operation.kind
              expected_operation.kind ->
    Option.iter t.active_cancel ~f:(fun cancel -> cancel ());
    worker_terminal t expected_operation.id (Operation_worker.Failed failure) None
  | (Some _ | None), (Some _ | None) -> Ok ()
;;

let submit_deferred_message
      ?original_actor
      ?(extra_deltas = [])
      ?(owner = Pending_input_document.Owner.Host_internal)
      ?(timing = Agent_protocol.Pending_input.Timing.Safe_boundary)
      t
      entry
  =
  let open Result.Let_syntax in
  let%map session = defer_history ~extra_deltas ~owner ~timing t [ entry ] in
  remember_pending_agent_actor t entry original_actor;
  { session; history_id = entry.id; disposition = Deferred; operation_id = None }
;;

let require_submit_ready t =
  let%bind.Result () = require_selected_execution t in
  if not (runtime_admission_open t)
  then Error (error Conflict "session runtime is retiring")
  else if t.state.halted
  then Error (error Invalid_state "session is halted")
  else if Option.is_some t.state.failure
  then Error (error Invalid_state "session has failed")
  else if
    not (Agent_protocol.Session.equal_desired_state t.state.lifecycle.desired Running)
  then Error (error Invalid_state "session is not running")
  else Ok ()
;;

let submit_authorized_message
      ?original_actor
      ?(extra_deltas = [])
      ?(owner = Pending_input_document.Owner.Host_internal)
      ?(timing = Agent_protocol.Pending_input.Timing.Safe_boundary)
      t
      entry
  =
  let%bind.Result () = require_submit_ready t in
  match
    t.idle_moderator_borrowed, t.state.active_operation, t.state.lifecycle.observed
  with
  | true, _, _ ->
    submit_deferred_message ?original_actor ~extra_deltas ~owner ~timing t entry
  | false, Some _, _
  | false, None, (Running_turn _ | Compacting _ | Waiting_for_permission _) ->
    submit_deferred_message ?original_actor ~extra_deltas ~owner ~timing t entry
  | false, None, Idle when Session_delta.awaiting_settled_foreground t.state ->
    submit_deferred_message ?original_actor ~extra_deltas ~owner ~timing t entry
  | false, None, Idle ->
    submit_idle_message ?original_actor ~extra_deltas ~owner ~timing t entry
  | false, None, (Stopped | Queued_for_slot | Starting | Recovering | Stopping | Failed _)
    -> Error (error Invalid_state "session is not ready to accept a turn")
;;

let check_message_authentication original_actor ~submitting_principal =
  match original_actor with
  | None -> Ok ()
  | Some actor ->
    let principal = Operator_authorization.principal actor in
    if
      Operator_authorization.is_current actor
      && Agent_protocol.Principal.has_scope principal Send_messages
      && Agent_protocol.Id.Principal.equal principal.id submitting_principal
    then Ok ()
    else
      Error
        (error
           Permission_denied
           "message authentication expired or differs from submitter")
;;

let submit_message
      ?original_actor
      t
      attachment_id
      submitting_principal
      timing
      entry
      capture
  =
  let open Result.Let_syntax in
  let%bind _ = write_attachment t attachment_id in
  let%bind () = require_submit_ready t in
  let idle =
    match
      t.idle_moderator_borrowed, t.state.active_operation, t.state.lifecycle.observed
    with
    | false, None, Idle -> not (Session_delta.awaiting_settled_foreground t.state)
    | (true | false), (Some _ | None), _ -> false
  in
  let requirement = if idle then inherited_turn_required t.state else Ordinary in
  match requirement with
  | Need_private_origin ->
    let%bind () = Inherited_turn.Capture.check_waiting capture in
    let%map origin = capture_descendant_origin_observation t in
    Inherited_turn.Decision.Need_private_origin
      { origin
      ; input =
          Inherited_turn.Input.Message
            { original_actor; attachment_id; submitting_principal; timing; entry }
      ; capture
      ; remaining_audit = t.command_audit
      }
  | Scoped ->
    capture_inherited_message
      ?original_actor
      t
      ~capture
      ~attachment_id
      ~submitting_principal
      ~timing
      entry
  | Ordinary ->
    Result.map
      (submit_authorized_message
         ?original_actor
         ~owner:(Submitting_principal submitting_principal)
         ~timing
         t
         entry)
      ~f:(fun submission -> Inherited_turn.Decision.Completed submission)
;;

let check_run_caller ?preparation t caller =
  match caller with
  | Run_admission_request.Caller.Writer attachment_id ->
    Result.map (write_attachment t attachment_id) ~f:ignore
  | Native_goal_start _ ->
    Error (error Permission_denied "native Start requires its selected initial admission")
  | Headless_command ->
    (match preparation with
     | Some preparation -> check_run_preparation t preparation
     | None -> Error (error Permission_denied "headless admission requires actor custody"))
;;

(* Ordinary retries cannot drop the immutable Goal association of an existing
   admission. Generic Run_state receipt lookup remains factual: Goal and
   recurrence owners validate their own exact associations separately. *)
let ordinary_run_receipt t ~principal_id ~key ~request_sha256 =
  let open Result.Let_syntax in
  let index = Option.value t.state.run_state ~default:Run_state.empty in
  let%bind receipt = Run_state.receipt index ~principal_id ~key ~request_sha256 in
  match receipt with
  | Some ({ kind = Admission; run_id; _ } as admission) ->
    if Option.is_some (Run_state.goal_link index run_id)
    then Error (error Conflict "ordinary Run request omits its original Goal association")
    else Ok (Some admission)
  | Some { kind = Action | Terminal; _ } | None -> Ok receipt
;;

let begin_run_preparation_internal
      ?original_actor
      t
      ~authorize
      ~principal_id
      ~request
      ~request_sha256
  =
  let open Result.Let_syntax in
  let%bind () = authorize t.state in
  let%bind () =
    match request.Run_admission_request.caller with
    | Writer attachment_id -> Result.map (write_attachment t attachment_id) ~f:ignore
    | Headless_command -> Ok ()
    | Native_goal_start _ ->
      Error (error Permission_denied "ordinary preparation cannot issue native Start")
  in
  let%bind () =
    if Agent_protocol.Id.Session.equal request.session_id t.state.identity.session_id
    then Ok ()
    else Error (error Invalid_request "run preparation targets another session")
  in
  let%bind receipt =
    ordinary_run_receipt t ~principal_id ~key:request.key ~request_sha256
  in
  match receipt with
  | Some ({ kind = Admission; _ } as receipt) ->
    Ok (Run_preparation.Decision.Retained receipt)
  | Some { kind = Action | Terminal; _ } ->
    Error (error Conflict "run start key belongs to another action")
  | None ->
    (match t.run_preparation with
     | Some _ -> Error (error Conflict "another run admission is being prepared")
     | None ->
       exclude_effect_deferred t Displaced;
       let%map preparation =
         (match original_actor with
          | None -> Run_preparation.create_request
          | Some actor ->
            fun ~owner ~state ~principal_id:_ ~request ~request_sha256 ~authorize ->
              Run_preparation.create_authenticated_request
                ~owner
                ~state
                ~actor
                ~request
                ~request_sha256
                ~authorize)
           ~owner:t.run_preparation_owner
           ~state:t.state
           ~principal_id
           ~request
           ~request_sha256
           ~authorize
       in
       t.run_preparation <- Some (Initial preparation);
       Run_preparation.Decision.Prepare preparation)
;;

let effect_deferred_quiescent t =
  let outstanding_inference =
    List.exists t.inference_owners ~f:(fun custody ->
      let owner = Inference_graph_custody.owner custody in
      let registered = ref false in
      Graph_owner.iter_registrations owner ~f:(fun _ -> registered := true);
      !registered)
  in
  let live_runs =
    Option.exists t.state.run_state ~f:(fun index ->
      List.exists (Run_state.runs index) ~f:(fun run ->
        match run.Agent_protocol.Run.lifecycle with
        | Admitted | Active | Waiting _ -> true
        | Terminal _ -> false))
  in
  if
    (not t.stopped)
    && Option.is_none (Eio.Promise.peek t.finished)
    && Option.is_none t.lifecycle_fence
    && Option.is_none t.runtime_retirement
    && Option.is_none t.state.failure
    && Option.is_none t.state.active_operation
    && (match t.state.lifecycle.observed with
        | Idle | Stopped -> true
        | _ -> false)
    && (not t.idle_moderator_borrowed)
    && (not (moderator_is_borrowed t))
    && Option.is_none t.queued_event_borrow
    && Option.is_none t.legacy_callback_scope
    && Option.is_none t.initialization_scope
    && Option.is_none t.held_activation
    && Option.is_none t.held_input_scope
    && Option.is_none t.held_authored_start
    && List.is_empty t.invocation_executions
    (* An installed idle runtime owns its real graph before any provider call.
       Only outstanding admitted handles prevent this new deferred attempt. *)
    && (not outstanding_inference)
    && List.is_empty t.job_scopes
    && not live_runs
  then require_runtime_admission t
  else Error (error Conflict "effect-deferred issuance requires a quiescent actual actor")
;;

let begin_effect_deferred_internal t ~actor ~authorize ~request =
  let open Result.Let_syntax in
  let%bind () = Run_command_authorization.check actor ~authorize t.state in
  let%bind source_owner =
    Result.of_option
      t.runtime_source_owner
      ~error:(error Conflict "effect-deferred preparation requires its actual Factory")
  in
  let request = Run_admission_request.of_headless request in
  let%bind request_sha256 = Run_admission_request.request_sha256 request in
  let principal_id = (Operator_authorization.principal actor).id in
  let%bind retained =
    Run_state.receipt
      (Option.value t.state.run_state ~default:Run_state.empty)
      ~principal_id
      ~key:request.key
      ~request_sha256
  in
  match retained with
  | Some ({ kind = Admission; _ } as receipt) ->
    Ok (Run_preparation.Deferred.Decision.Retained receipt)
  | Some { kind = Action | Terminal; _ } ->
    Error (error Conflict "run start key belongs to another action")
  | None ->
    let%bind () = effect_deferred_quiescent t in
    let%bind () =
      if Option.is_none t.run_preparation
      then Ok ()
      else Error (error Conflict "another run admission is being prepared")
    in
    exclude_effect_deferred t Displaced;
    let%bind deferred =
      Run_preparation.Deferred.create_authenticated_request
        ~owner:t.run_preparation_owner
        ~source_owner
        ~state:t.state
        ~actor
        ~request
        ~request_sha256
        ~authorize
    in
    (* Issuance policies may execute trusted callbacks. Revalidate actual state
       and the newly selected preparation before publishing either reference. *)
    let%bind () = effect_deferred_quiescent t in
    let%bind () =
      if Option.is_none t.run_preparation
      then Ok ()
      else Error (error Conflict "preparation slot changed during deferred issuance")
    in
    let%map () =
      Run_preparation.Deferred.check_basis
        deferred
        ~owner:t.run_preparation_owner
        ~state:t.state
    in
    t.run_preparation <- Some (Initial (Run_preparation.Deferred.preparation deferred));
    t.effect_deferred <- Some (Ordinary deferred);
    Run_preparation.Deferred.Decision.Prepare deferred
;;

let close_effect_deferred_internal t deferred =
  let open Result.Let_syntax in
  let%bind closed =
    Run_preparation.Deferred.close deferred ~owner:t.run_preparation_owner ~state:t.state
  in
  let preparation = Run_preparation.Deferred.preparation deferred in
  (match t.run_preparation with
   | Some (Initial current) when phys_equal current preparation -> close_run_preparation t
   | Some _ | None -> ());
  Ok closed
;;

let observe_no_run_effects_internal t ~actor ~authorize ~completion =
  let open Result.Let_syntax in
  let preparation = Run_preparation.Source_completion.preparation completion in
  let%bind () = check_retry_execution t preparation in
  let request = Run_preparation.request preparation in
  let deferred = Run_preparation.Deferred.of_preparation preparation in
  let domain = t.runtime_source_domain in
  let owner_basis () =
    if not (Int.equal domain (Stdlib.Domain.self () :> int))
    then
      Error (error Invalid_request "no-effects observation belongs to another Eio domain")
    else if
      (not t.stopped)
      && Option.is_none (Eio.Promise.peek t.finished)
      && Option.is_none t.lifecycle_fence
      && Option.equal
           phys_equal
           (Option.map t.effect_deferred ~f:Deferred_owner.preparation)
           deferred
    then
      Run_preparation.Source_completion.check_basis
        completion
        ~owner:t.run_preparation_owner
        ~state:t.state
    else Error (error Conflict "no-effects observation lost its actual writer or attempt")
  in
  let absence () =
    let%bind retained =
      Run_state.receipt
        (Option.value t.state.run_state ~default:Run_state.empty)
        ~principal_id:(Run_preparation.principal_id preparation)
        ~key:request.key
        ~request_sha256:(Run_preparation.request_sha256 preparation)
    in
    match retained with
    | None -> Ok ()
    | Some _ -> Error (error Conflict "no-effects request already has retained evidence")
  in
  let check_read () =
    let%bind () = owner_basis () in
    Recurrence_command_admission.check_read actor ~authorize t.state
  in
  let%bind () = check_read () in
  let%bind () = absence () in
  let%bind controller = require_recurrence_controller t in
  let%bind current = Recurrence_controller.observe controller t.state in
  let basis () =
    let%bind () = owner_basis () in
    let%bind () = absence () in
    if Recurrence_controller.is_current current
    then owner_basis ()
    else Error (error Conflict "no-effects Store observation changed")
  in
  let check () =
    let%bind () = check_read () in
    basis ()
  in
  let%map () = check () in
  ({ current = check
   ; basis
   ; completion
   ; controller
   ; observed = current
   ; actor
   ; authorize
   ; revision = t.state.counters.revision
   }
   : No_effects_observation.t)
;;

let retry_owner_basis t (retry : Recurrence_retry.t) =
  if
    Int.equal retry.domain (Stdlib.Domain.self () :> int)
    && phys_equal retry.issuing_actor t.inference_owner_identity
    && phys_equal retry.owner t.run_preparation_owner
    && (not t.stopped)
    && Option.is_none (Eio.Promise.peek t.finished)
    && Option.is_none t.lifecycle_fence
    &&
    match t.effect_deferred with
    | Some (Retry current) -> phys_equal current retry
    | Some (Ordinary _) | None -> false
  then Ok ()
  else Error (error Conflict "retry lost its actual target owner")
;;

let retry_target_basis t retry =
  let open Result.Let_syntax in
  let%bind () = retry_owner_basis t retry in
  match retry.Recurrence_retry.phase with
  | Closed_before_writer completion ->
    Run_preparation.Source_completion.check_basis
      completion
      ~owner:t.run_preparation_owner
      ~state:t.state
  | Preparing_source | Selected_source _ | Writer_pending _ | Acknowledged _ ->
    let preparation = Run_preparation.Deferred.preparation retry.deferred in
    let%bind () =
      if Option.exists (initial_run_preparation t) ~f:(phys_equal preparation)
      then Ok ()
      else Error (error Conflict "retry preparation was displaced")
    in
    Run_preparation.Deferred.check_basis
      retry.deferred
      ~owner:t.run_preparation_owner
      ~state:t.state
  | Attempt_unconfirmed | Invalid -> Error (error Conflict "retry is no longer live")
;;

let derive_retry_attempt ~intent ~previous ~actor request =
  let open Result.Let_syntax in
  let%bind () = Recurrence_execution_attempt.validate previous ~intent in
  let principal_id = (Operator_authorization.principal actor).id in
  let%bind next =
    Recurrence_execution_attempt.create
      ~intent
      ~number:(Recurrence_execution_attempt.number previous + 1)
      ~principal_id
      ~expected_revision:request.Run_admission_request.Headless.expected_revision
      ~key:request.key
  in
  let%bind supplied_sha =
    Run_admission_request.request_sha256 (Run_admission_request.of_headless request)
  in
  if String.equal supplied_sha (Recurrence_execution_attempt.request_sha256 next)
  then Ok next
  else Error (error Conflict "retry changed its immutable input or target")
;;

(* Pure target-side counterpart of held admission's source installation law.
   Selecting a cold source may supply its first installation; no runtime or Run
   is created here, and an existing installation must match exactly. *)
let retry_selected_target_basis t retry binding =
  let open Result.Let_syntax in
  let preparation = binding.Source_binding.preparation in
  let%bind () = retry_target_basis t retry in
  let actual = Run_preparation.request preparation in
  let%bind actual_sha = Run_admission_request.request_sha256 actual in
  let%bind () =
    if
      Option.exists t.run_source_binding ~f:(phys_equal binding)
      && phys_equal preparation (Run_preparation.Deferred.preparation retry.deferred)
      && Agent_protocol.Session_ref.equal
           (Recurrence_controller.session retry.controller)
           (Recurrence_execution_intent.target retry.intent)
      && Run_admission_request.Caller.equal actual.caller Headless_command
      && String.equal actual_sha (Recurrence_execution_attempt.request_sha256 retry.next)
      && String.equal
           (Run_preparation.request_sha256 preparation)
           (Recurrence_execution_attempt.request_sha256 retry.next)
    then Ok ()
    else Error (error Conflict "retry selected target or immutable request changed")
  in
  let%bind () = Runtime_source_preparation.validate_target binding.source t.state in
  let%bind observer =
    match Runtime_source_preparation.moderator binding.source with
    | Legacy observer | Extension observer -> Ok observer
    | No_moderator -> Error (error Conflict "retry source has no scripted moderator")
  in
  let%bind index = Run_admission.prepare_source_index t.state ~observer in
  let%bind source =
    Run_source_installation.captured
      (Run_state.installation index)
      ~generation:t.state.identity.generation
  in
  if
    Agent_protocol.Run_source.equal
      source
      (Recurrence_execution_intent.source retry.intent)
  then Source_binding.check_basis binding
  else Error (error Conflict "retry selected source differs from immutable intent")
;;

let begin_recurrence_retry_internal
      t
      ~observation
      ~actor
      ~authorize
      ~intent
      ~previous
      ~request
  =
  let open Result.Let_syntax in
  let%bind () = No_effects_observation.check_current observation in
  let completed = observation.No_effects_observation.completion in
  let old = Run_preparation.Source_completion.preparation completed in
  let%bind old_request = Recurrence_execution_attempt.request previous ~intent in
  let%bind old_sha =
    Run_admission_request.request_sha256 (Run_admission_request.of_headless old_request)
  in
  let%bind controller = require_recurrence_controller t in
  let%bind source_owner =
    Result.of_option
      t.runtime_source_owner
      ~error:(error Conflict "retry requires its actual Factory")
  in
  let%bind () =
    if
      Run_preparation.belongs_to old ~owner:t.run_preparation_owner
      && Recurrence_controller.same_store observation.controller controller
      && Agent_protocol.Session_ref.equal
           (Recurrence_controller.session controller)
           (Recurrence_execution_intent.target intent)
      && String.equal old_sha (Run_preparation.request_sha256 old)
      && Agent_protocol.Id.Principal.equal
           (Run_preparation.principal_id old)
           (Recurrence_execution_attempt.principal_id previous)
    then Ok ()
    else Error (error Conflict "retry observation belongs to another request or target")
  in
  let%bind next = derive_retry_attempt ~intent ~previous ~actor request in
  let%bind () = effect_deferred_quiescent t in
  let%bind () =
    if Option.is_none t.run_preparation
    then Ok ()
    else Error (error Conflict "retry source lane already has a preparation")
  in
  let previous_owner = t.effect_deferred in
  let%bind replacement =
    Run_preparation.Deferred.Replacement.prepare
      completed
      ~owner:t.run_preparation_owner
      ~source_owner
      ~state:t.state
      ~actor
      ~request:(Run_admission_request.of_headless request)
      ~request_sha256:(Recurrence_execution_attempt.request_sha256 next)
      ~authorize
  in
  let%bind () = No_effects_observation.check_current observation in
  let%bind () =
    Run_preparation.Deferred.Replacement.check_current
      replacement
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  let%bind () = No_effects_observation.check_basis observation in
  let%bind () = effect_deferred_quiescent t in
  let%bind () =
    if
      Option.is_none t.run_preparation
      && Option.equal phys_equal previous_owner t.effect_deferred
    then Ok ()
    else Error (error Conflict "retry source lane changed during authorization")
  in
  let%bind deferred =
    Run_preparation.Deferred.Replacement.commit
      replacement
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  let rec retry : Recurrence_retry.t =
    { issuing_actor = t.inference_owner_identity
    ; owner = t.run_preparation_owner
    ; controller
    ; source_owner
    ; observed = observation.observed
    ; domain = t.runtime_source_domain
    ; intent
    ; previous
    ; next
    ; request
    ; resolution_revision = observation.revision
    ; read_actor = observation.actor
    ; read_authorize = observation.authorize
    ; deferred
    ; phase = Preparing_source
    ; basis = (fun () -> retry_target_basis t retry)
    ; selected_basis = (fun binding -> retry_selected_target_basis t retry binding)
    ; policy =
        (fun () ->
          let%bind () = retry_target_basis t retry in
          let%bind () =
            Recurrence_command_admission.check_read
              retry.read_actor
              ~authorize:retry.read_authorize
              t.state
          in
          let%bind () =
            check_registered_run_preparation
              t
              (Run_preparation.Deferred.preparation retry.deferred)
          in
          retry_target_basis t retry)
    ; authority =
        (fun () ->
          let%bind () = retry_target_basis t retry in
          let%bind () =
            Recurrence_command_admission.check_read
              retry.read_actor
              ~authorize:(fun _ -> Ok ())
              t.state
          in
          let%bind () =
            Run_preparation.check_current
              (Run_preparation.Deferred.preparation retry.deferred)
              ~owner:t.run_preparation_owner
              ~state:t.state
          in
          retry_target_basis t retry)
    }
  in
  t.run_preparation <- Some (Initial (Run_preparation.Deferred.preparation deferred));
  t.effect_deferred <- Some (Retry retry);
  Ok (retry, deferred)
;;

let resume_recurrence_retry_internal t ~retry ~actor ~authorize =
  let open Result.Let_syntax in
  let%bind () = Recurrence_retry.check_basis retry in
  let%bind () = retry_owner_basis t retry in
  let%bind () =
    if
      Agent_protocol.Id.Principal.equal
        (Operator_authorization.principal actor).id
        (Recurrence_execution_attempt.principal_id retry.next)
    then Ok ()
    else Error (error Permission_denied "retry resume changed its frozen next principal")
  in
  let%bind completed =
    match retry.Recurrence_retry.phase with
    | Closed_before_writer completed -> Ok completed
    | _ -> Error (error Conflict "retry source is not a joined prewriter closure")
  in
  let%bind () = effect_deferred_quiescent t in
  let%bind () =
    if Option.is_none t.run_preparation
    then Ok ()
    else Error (error Conflict "retry resume source lane is occupied")
  in
  let previous_deferred = retry.deferred in
  let%bind replacement =
    Run_preparation.Deferred.Replacement.prepare
      completed
      ~owner:t.run_preparation_owner
      ~source_owner:retry.source_owner
      ~state:t.state
      ~actor
      ~request:(Run_admission_request.of_headless retry.request)
      ~request_sha256:(Recurrence_execution_attempt.request_sha256 retry.next)
      ~authorize
  in
  let%bind () =
    Recurrence_command_admission.check_read
      retry.read_actor
      ~authorize:retry.read_authorize
      t.state
  in
  let%bind () =
    Run_preparation.Deferred.Replacement.check_current
      replacement
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  let%bind () = retry_owner_basis t retry in
  let%bind () = effect_deferred_quiescent t in
  let%bind () =
    if
      Option.is_none t.run_preparation
      && phys_equal retry.deferred previous_deferred
      && Recurrence_controller.is_current retry.observed
      &&
      match retry.phase with
      | Closed_before_writer current -> phys_equal current completed
      | _ -> false
    then Ok ()
    else Error (error Conflict "retry closed source changed during authorization")
  in
  let%bind deferred =
    Run_preparation.Deferred.Replacement.commit
      replacement
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  retry.deferred <- deferred;
  retry.phase <- Preparing_source;
  t.run_preparation <- Some (Initial (Run_preparation.Deferred.preparation deferred));
  Ok (retry, deferred)
;;

let complete_recurrence_retry_internal t ~retry ~completion =
  let open Result.Let_syntax in
  let%bind () = retry_owner_basis t retry in
  let%bind () =
    if
      phys_equal
        (Run_preparation.Source_completion.preparation completion)
        (Run_preparation.Deferred.preparation retry.Recurrence_retry.deferred)
    then Ok ()
    else Error (error Conflict "retry completion belongs to another source")
  in
  let%bind () =
    Run_preparation.Source_completion.check_basis
      completion
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  match retry.phase with
  | Preparing_source | Selected_source _ | Closed_before_writer _ ->
    retry.phase <- Closed_before_writer completion;
    Ok ()
  | Writer_pending _ | Attempt_unconfirmed | Acknowledged _ | Invalid ->
    Error (error Conflict "retry controller outcome cannot resume source preparation")
;;

let bind_run_source_internal t ~preparation ~source =
  let open Result.Let_syntax in
  let source_basis () =
    let%bind () =
      if t.stopped || Option.is_some (Eio.Promise.peek t.finished)
      then Error (error Conflict "source binding actor is closed")
      else require_runtime_admission t
    in
    let%bind () =
      Run_preparation.check_basis
        preparation
        ~owner:t.run_preparation_owner
        ~state:t.state
    in
    let%bind () =
      match
        ( t.state.active_operation
        , t.state.lifecycle.observed
        , t.idle_moderator_borrowed
        , moderator_is_borrowed t )
      with
      | None, (Idle | Stopped), false, false -> Ok ()
      | _ -> Error (error Conflict "source binding requires a quiescent target runtime")
    in
    let%bind () =
      match Run_preparation.original_actor preparation with
      | Some _ -> Ok ()
      | None ->
        Error (error Permission_denied "source binding requires original authentication")
    in
    Runtime_source_preparation.validate_target source t.state
  in
  let%bind () = source_basis () in
  match t.run_source_binding with
  | Some binding ->
    if
      phys_equal binding.Source_binding.preparation preparation
      && phys_equal binding.source source
    then Result.map (Source_binding.check_current binding) ~f:(fun () -> binding)
    else Error (error Conflict "another source is bound to this preparation")
  | None ->
    let%bind () = check_registered_run_preparation t preparation in
    let%bind () = source_basis () in
    let rec binding : Source_binding.t =
      { source
      ; preparation
      ; domain = (Stdlib.Domain.self () :> int)
      ; phase = Open Selected
      ; current = (fun () -> check_registered_run_preparation t preparation)
      ; basis =
          (fun () ->
            let%bind () = source_basis () in
            match t.run_source_binding with
            | Some current when phys_equal current binding -> Ok ()
            | Some _ | None -> Error (error Conflict "source binding was displaced"))
      }
    in
    t.run_source_binding <- Some binding;
    (match retry_for_preparation t preparation with
     | Some retry ->
       (match retry.phase with
        | Preparing_source -> retry.phase <- Selected_source binding
        | _ -> ())
     | None -> ());
    Ok binding
;;

let check_bound_source t binding =
  let open Result.Let_syntax in
  let%bind () =
    match t.run_source_binding with
    | Some current when phys_equal current binding -> Ok ()
    | Some _ | None -> Error (error Conflict "source binding belongs to another actor")
  in
  Source_binding.check_basis binding
;;

let check_bound_recurrence_request t binding ~intent ~attempt ~session =
  let open Result.Let_syntax in
  let%bind () = check_bound_source t binding in
  let preparation = binding.Source_binding.preparation in
  let%bind controller = require_recurrence_controller t in
  let actual_session = Recurrence_controller.session controller in
  let%bind () =
    if
      Agent_protocol.Session_ref.equal actual_session session
      && Agent_protocol.Session_ref.equal
           actual_session
           (Recurrence_execution_intent.target intent)
    then Ok ()
    else Error (error Conflict "held recurrence admission targets another session")
  in
  let%bind request = Recurrence_execution_attempt.request attempt ~intent in
  let request = Run_admission_request.of_headless request in
  let actual = Run_preparation.request preparation in
  let%bind () =
    if
      Run_admission_request.Caller.equal actual.caller Headless_command
      && Agent_protocol.Id.Principal.equal
           (Run_preparation.principal_id preparation)
           (Recurrence_execution_attempt.principal_id attempt)
      && Agent_protocol.Id.Session.equal actual.session_id request.session_id
      && Int.equal actual.generation request.generation
      && Int64.equal actual.expected_revision request.expected_revision
      && Agent_protocol.Run.Mode.equal actual.mode request.mode
      && Agent_protocol.Idempotency_key.equal actual.key request.key
      && Jsonaf.exactly_equal
           (Agent_protocol.Run_start.Input.to_json actual.input)
           (Agent_protocol.Run_start.Input.to_json request.input)
      && String.equal
           (Run_preparation.request_sha256 preparation)
           (Recurrence_execution_attempt.request_sha256 attempt)
    then Ok ()
    else
      Error
        (error Conflict "held admission requires the exact original occurrence request")
  in
  Ok ()
;;

let check_source_original t binding =
  let open Result.Let_syntax in
  let%bind () = check_bound_source t binding in
  match Run_preparation.original_actor binding.Source_binding.preparation with
  | None ->
    Error (error Permission_denied "source preparation lost original authentication")
  | Some actor ->
    Run_command_authorization.check actor ~authorize:(fun _ -> Ok ()) t.state
;;

let check_selected_source t binding =
  let open Result.Let_syntax in
  let%bind () = check_bound_source t binding in
  let%bind () =
    match binding.Source_binding.phase with
    | Open Selected -> Ok ()
    | Open (Admission_pending _ | Admitted _) | Closed _ ->
      Error
        (error Conflict "prepared recurrence record requires the Selected source owner")
  in
  Ok ()
;;

let check_selected_recurrence_source t binding ~intent ~attempt =
  let open Result.Let_syntax in
  let%bind () = check_selected_source t binding in
  let%bind controller = require_recurrence_controller t in
  let definition =
    Recurrence_identity.Occurrence.definition
      (Recurrence_execution_intent.occurrence intent)
  in
  let%bind () =
    if
      Agent_protocol.Session_ref.equal
        (Recurrence_controller.session controller)
        (Recurrence_identity.Definition.controller definition)
    then Ok ()
    else Error (error Conflict "prepared recurrence record belongs to another controller")
  in
  check_bound_recurrence_request
    t
    binding
    ~intent
    ~attempt
    ~session:(Recurrence_execution_intent.target intent)
;;

let held_run t binding run admission =
  let basis () =
    let open Result.Let_syntax in
    let%bind () = Source_binding.check_basis binding in
    let%bind () =
      match binding.Source_binding.phase with
      | Open (Admitted saved) when Agent_protocol.Run_receipt.equal saved admission ->
        Ok ()
      | Open (Selected | Admission_pending _ | Admitted _) | Closed _ ->
        Error (error Conflict "held Run source owner is not continuously admitted")
    in
    let%bind index =
      Result.of_option
        t.state.run_state
        ~error:(error Conflict "held Run index is unavailable")
    in
    let%bind current_source =
      Run_source_installation.captured
        (Run_state.installation index)
        ~generation:t.state.identity.generation
    in
    let%bind actual =
      Run_state.receipt
        index
        ~principal_id:admission.Agent_protocol.Run_receipt.principal_id
        ~key:admission.key
        ~request_sha256:admission.request_sha256
    in
    if
      Agent_protocol.Run_source.equal current_source run.Agent_protocol.Run.source
      && Option.exists (Run_state.find index run.id) ~f:(Agent_protocol.Run.equal run)
      && Option.exists actual ~f:(Agent_protocol.Run_receipt.equal admission)
    then Ok ()
    else Error (error Conflict "held Run or exact Admission evidence changed")
  in
  let held : Held_run.t = { admission; binding; run; basis } in
  held
;;

let admit_held_recurrence_run_internal t ~goal_guard ~binding ~intent ~attempt ~session =
  let open Result.Let_syntax in
  (* Capture before any original/policy or supplied clock callback. *)
  let previous = t.state in
  let preparation = binding.Source_binding.preparation in
  let check_basis () =
    let%bind () =
      match t.run_source_binding with
      | Some current when phys_equal current binding -> Ok ()
      | Some _ | None ->
        Error (error Conflict "held admission source belongs to another owner")
    in
    let%bind () = Source_binding.check_basis binding in
    if Int64.equal previous.counters.revision t.state.counters.revision
    then Ok ()
    else Error (error Conflict "held admission basis changed during preparation")
  in
  let%bind () = check_basis () in
  let%bind () = check_bound_recurrence_request t binding ~intent ~attempt ~session in
  let actual = Run_preparation.request preparation in
  let%bind () = Source_binding.check_current binding in
  let%bind () = check_basis () in
  let index = Option.value previous.run_state ~default:Run_state.empty in
  let%bind retained =
    Run_state.receipt
      index
      ~principal_id:(Run_preparation.principal_id preparation)
      ~key:actual.key
      ~request_sha256:(Run_preparation.request_sha256 preparation)
  in
  match retained with
  | Some admission ->
    let%bind origin =
      Result.of_option
        (Run_state.recurrence_origin index admission.run_id)
        ~error:
          (error Conflict "retained held admission lacks its exact recurrence origin")
    in
    let%bind run =
      Result.of_option
        (Run_state.find index admission.run_id)
        ~error:(error Conflict "retained held admission lost its Run")
    in
    let%bind () = Recurrence_run_origin.validate origin ~intent ~attempt in
    let%bind () = Recurrence_run_origin.validate_run origin ~run ~admission in
    let%bind () = Source_binding.check_current binding in
    let%map () = check_basis () in
    Held_run.Admission.Retained admission
  | None ->
    let module Origin = Agent_store.Delegation_goal_origin in
    let check_goal () =
      let actual = Option.bind t.state.goal_descendants ~f:Goal_descendants.origin in
      match Recurrence_execution_intent.child intent, goal_guard with
      | None, None -> Ok ()
      | Some _, None ->
        if
          Option.value_map actual ~default:false ~f:(fun origin ->
            not (List.is_empty (Origin.scopes origin)))
        then
          Error
            (error
               Permission_denied
               "scoped captured Run requires its actual controller Goal check")
        else Ok ()
      | None, Some _ ->
        Error (error Conflict "recurrence Goal check belongs to a captured child")
      | Some association, Some guard ->
        let reference = Recurrence_child_association.reference association in
        if
          Recurrence_execution_intent.equal intent guard.Recurrence_goal_run_guard.intent
          && Recurrence_execution_attempt.equal attempt guard.attempt
          && Option.exists
               t.state.spec.delegation
               ~f:(Agent_store.Delegation_store.Reference.equal reference)
          && Option.exists actual ~f:(fun origin ->
            List.mem (Origin.scopes origin) guard.scope ~equal:Origin.Scope.equal)
        then guard.check_current ()
        else
          Error
            (error
               Conflict
               "recurrence Goal check does not match the actual target and original \
                attempt")
    in
    let%bind () = check_retry_execution t preparation in
    let%bind () =
      match binding.phase with
      | Open Selected -> Ok ()
      | Open (Admission_pending _ | Admitted _) | Closed _ ->
        Error (error Conflict "source owner already attempted a held admission")
    in
    let attempted = ref false in
    let returned = ref false in
    Exn.protect
      ~finally:(fun () -> if not !returned then Source_binding.close binding)
      ~f:(fun () ->
        let prepare () =
          let now = t.services.now () in
          let%bind () = check_basis () in
          let%bind () = check_goal () in
          let%bind facts =
            Run_admission.prepare_held_from_preparation
              previous
              ~preparation
              ~owner:t.run_preparation_owner
              ~source:binding.source
              ~session
              ~run_id:(Agent_protocol.Id.Run.create ())
              ~now
          in
          let run = Run_admission.Held_plan.run facts in
          let admission = Run_admission.Held_plan.receipt facts in
          let%bind origin =
            Recurrence_run_origin.create ~intent ~attempt ~run ~admission
          in
          let%bind index =
            Run_state.commit_recurrence_admission
              (Run_admission.Held_plan.source_index facts)
              ~run
              ~receipt:admission
              ~origin
          in
          let%bind transition =
            prepare_transition
              ~run_preparation:preparation
              t
              ~delta:(Session_delta.Run_state_changed index)
              ~payloads:[]
          in
          let held = held_run t binding run admission in
          let%bind () = Source_binding.check_current binding in
          let%map () = check_basis () in
          transition, held
        in
        match prepare () with
        | Error failure -> Ok (Held_run.Admission.Rejected failure)
        | Ok (transition, held) ->
          (* The same actual attempt marker is set by the sole persistence seam
             AFTER its final preflight, immediately before the writer call.
             Closing preserves this reference until the outcome is known. *)
          binding.phase <- Open (Admission_pending attempted);
          (match
             persist_transition
               ~run_preparation:preparation
               ~commit_attempted:attempted
               ?check_before_commit:
                 (Option.map goal_guard ~f:(fun _ () ->
                    let%bind () = check_goal () in
                    check_basis ()))
               t
               transition
           with
           | Error failure ->
             Ok
               (if !attempted
                then Held_run.Admission.Uncertain failure
                else Held_run.Admission.Rejected failure)
           | Ok () ->
             install_committed_transition ~run_preparation:preparation t transition;
             let disposition = Source_binding.Admitted (Held_run.admission held) in
             binding.phase
             <- (match binding.phase with
                 | Open _ -> Open disposition
                 | Closed _ -> Closed disposition);
             (* No normal Run_authorities entry is installed. This durable Run
                stays inert; the future one-shot activation owner publishes it. *)
             publish_committed_transition t transition;
             returned := true;
             if Result.is_ok (Held_run.check_basis held)
             then Ok (Held_run.Admission.Held held)
             else Ok (Held_run.Admission.Retained (Held_run.admission held))))
;;

module Run_admission_basis = struct
  type t =
    | Retained of Agent_protocol.Run_receipt.t
    | Fresh of Agent_protocol.Operation.t option
end

let prepare_run_admission_basis t (input : Inherited_turn.Input.run_user) =
  let open Result.Let_syntax in
  let request = input.request in
  let preparation = input.preparation in
  let%bind () = Run_admission.Scope.authorize input.scope t.state in
  let%bind () =
    if
      Agent_protocol.Id.Session.equal request.session_id t.state.identity.session_id
      && Agent_protocol.Id.Session.equal
           (Agent_protocol.Session_ref.session_id input.session)
           t.state.identity.session_id
    then Ok ()
    else Error (error Invalid_request "run request does not identify this session")
  in
  let%bind () = check_run_caller ?preparation t request.caller in
  let%bind retained =
    ordinary_run_receipt
      t
      ~principal_id:(Run_admission.Scope.principal_id input.scope)
      ~key:request.key
      ~request_sha256:input.request_sha256
  in
  match retained with
  | Some receipt ->
    (match receipt.kind with
     | Admission -> Ok (Run_admission_basis.Retained receipt)
     | Action | Terminal ->
       Error (error Conflict "run start key belongs to another action"))
  | None ->
    let%bind () = require_selected_execution t in
    let%bind () =
      match request.input with
      | User_submission _ -> Ok ()
      | Authored_start ->
        Authored_run_acknowledgement.require_unadmitted t.lifecycle_agent_custody
    in
    let%bind () =
      Option.value_map preparation ~default:(Ok ()) ~f:(check_run_preparation t)
    in
    let%bind () = require_runtime_admission t in
    let%map operation =
      match request.input, input.entry with
      | User_submission _, Some _ ->
        let%bind () = reconcile_foreground_invocations t in
        (match
           ( t.state.lifecycle.desired
           , t.state.lifecycle.observed
           , t.state.active_operation
           , t.state.failure )
         with
         | Running, Idle, None, None when not (t.state.halted || t.idle_moderator_borrowed)
           -> Ok (Some (create_turn_operation t User_submit))
         | _ -> Error (error Conflict "run user input requires an available idle session"))
      | Authored_start, None -> Ok None
      | User_submission _, None | Authored_start, Some _ ->
        Error (error Invalid_request "run input does not match its host-prepared history")
    in
    Run_admission_basis.Fresh operation
;;

let prepare_actual_run_admission t (input : Inherited_turn.Input.run_user) operation =
  let run_id = Agent_protocol.Id.Run.create () in
  match input.preparation with
  | None ->
    Run_admission.prepare_request
      t.state
      ~scope:input.scope
      ~request:input.request
      ~session:input.session
      ~run_id
      ~operation
      ~request_sha256:input.request_sha256
      ~now:(t.services.now ())
  | Some preparation ->
    Run_admission.prepare_from_preparation
      t.state
      ~preparation
      ~owner:t.run_preparation_owner
      ~scope:input.scope
      ~session:input.session
      ~run_id
      ~operation
      ~now:(t.services.now ())
;;

let capture_turn_origin t ~input ~capture =
  let open Result.Let_syntax in
  let%bind () = Inherited_turn.Capture.check_waiting capture in
  let%map origin = capture_descendant_origin_observation t in
  Inherited_turn.Decision.Need_private_origin
    { origin; input; capture; remaining_audit = t.command_audit }
;;

let checked_turn_requirement ?origin_observation t =
  let open Result.Let_syntax in
  match origin_observation with
  | None -> Ok (inherited_turn_required t.state)
  | Some observed ->
    let%map () = check_descendant_origin_observation t observed in
    Inherited_turn.Origin_requirement.Ordinary
;;

let capture_inherited_run t ~input ~reply ~capture ~operation admission entry =
  let open Result.Let_syntax in
  let%bind () = require_available_descendant_admission_slot t in
  let original_actor =
    Run_admission.Scope.original_actor input.Inherited_turn.Input.scope
  in
  let%bind pending, custody =
    prepare_idle_message_input
      ?original_actor
      ~operation
      ~owner:(Submitting_principal (Run_admission.Scope.principal_id input.scope))
      ~timing:Agent_protocol.Pending_input.Timing.Safe_boundary
      t
      entry
  in
  let transferred = ref false in
  Exn.protect
    ~finally:(fun () ->
      if not !transferred then Option.iter custody ~f:retire_agent_custody)
    ~f:(fun () ->
      let run = Run_admission.run admission in
      let previous_authorities = t.run_authorities in
      let%bind authorities =
        Run_authorities.add_for_caller
          previous_authorities
          ~run
          ~scope:input.scope
          ~caller:input.request.caller
      in
      let%bind binding =
        Run_authorities.find authorities run.id
        |> Result.of_option
             ~error:(error Invalid_state "prepared Run binding disappeared")
      in
      let%bind preparation_exit =
        Option.map input.preparation ~f:(fun preparation ->
          Run_preparation.Admission_exit.capture
            preparation
            ~owner:t.run_preparation_owner)
        |> Option.value_map ~default:(Ok None) ~f:(Result.map ~f:Option.some)
      in
      let operation, delta, payloads =
        idle_message_turn
          ~operation
          ~extra_deltas:[ Run_state_changed (Run_admission.index admission) ]
          t
          pending
      in
      let source =
        Inherited_turn.Source.Run_user
          ( { scope = input.scope
            ; request = input.request
            ; admission
            ; previous_authorities
            ; authorities
            ; binding
            ; preparation = input.preparation
            ; preparation_exit
            ; operation
            ; custody
            ; entry
            }
          , reply )
      in
      let%map decision =
        capture_inherited_turn_plan
          t
          ~capture
          ~source
          ~commit_attempted:input.attempted
          ~delta
          ~payloads
      in
      transferred := true;
      decision)
;;

let admit_run
  : type outcome.
    ?origin_observation:Descendant_origin_observation.Observed.t
    -> t
    -> Inherited_turn.Input.run_user
    -> reply:outcome Inherited_turn.Run_reply.t
    -> capture:outcome Inherited_turn.Capture.t
    -> (outcome Inherited_turn.Decision.t, Agent_protocol.Error.t) result
  =
  fun ?origin_observation t input ~reply ~capture ->
  let open Result.Let_syntax in
  let%bind basis = prepare_run_admission_basis t input in
  match basis with
  | Retained receipt ->
    Ok
      (Inherited_turn.Decision.Completed
         (Inherited_turn.Run_reply.of_receipt reply receipt))
  | Fresh operation ->
    let%bind requirement =
      match operation with
      | None -> Ok Inherited_turn.Origin_requirement.Ordinary
      | Some _ -> checked_turn_requirement ?origin_observation t
    in
    (match requirement with
     | Need_private_origin ->
       capture_turn_origin
         t
         ~capture
         ~input:(Inherited_turn.Input.Run_user (input, reply))
     | Scoped | Ordinary ->
       let%bind admission = prepare_actual_run_admission t input operation in
       (match requirement, operation, input.entry with
        | Scoped, Some operation, Some entry ->
          capture_inherited_run t ~input ~reply ~capture ~operation admission entry
        | Ordinary, _, _ ->
          let run = Run_admission.run admission in
          let delta = Session_delta.Run_state_changed (Run_admission.index admission) in
          let%map () =
            match operation, input.entry with
            | Some operation, Some entry ->
              let%bind authorities =
                Run_authorities.add_for_caller
                  t.run_authorities
                  ~run
                  ~scope:input.scope
                  ~caller:input.request.caller
              in
              let outcome =
                submit_idle_message
                  ?original_actor:(Run_admission.Scope.original_actor input.scope)
                  ?run_preparation:input.preparation
                  ~commit_attempted:input.attempted
                  ~extra_deltas:[ delta ]
                  ~operation
                  ~owner:
                    (Submitting_principal (Run_admission.Scope.principal_id input.scope))
                  t
                  entry
                |> Result.map ~f:ignore
              in
              (* Existing ordinary path unchanged; governed path installs ATACK. *)
              Option.iter t.state.run_state ~f:(fun index ->
                match Run_state.find index run.id with
                | Some committed when Agent_protocol.Run.equal committed run ->
                  t.run_authorities <- authorities
                | Some _ | None -> ());
              outcome
            | None, None ->
              let%bind acknowledgement =
                Authored_run_acknowledgement.prepare
                  ~previous:t.state
                  ~authorities:t.run_authorities
                  ~lifecycle:t.lifecycle_agent_custody
                  ~scope:input.scope
                  ~request:input.request
                  ~run
                  ~receipt:(Run_admission.receipt admission)
              in
              Exn.protect
                ~finally:(fun () -> Authored_run_acknowledgement.discard acknowledgement)
                ~f:(fun () ->
                  start_internal
                    ~authored_run_acknowledgement:acknowledgement
                    ?run_preparation:input.preparation
                    ~commit_attempted:input.attempted
                    ~extra_deltas:[ delta ]
                    t
                  |> Result.map ~f:ignore)
            | Some _, None | None, Some _ ->
              Error (error Invalid_state "run admission lost its prepared owner")
          in
          Inherited_turn.Decision.Completed
            (Inherited_turn.Run_reply.of_receipt reply (Run_admission.receipt admission))
        | Scoped, (None | Some _), (None | Some _)
        | Need_private_origin, (None | Some _), (None | Some _) ->
          Error (error Invalid_state "inherited user Run lost its real Turn")))
;;

let prepared_run_outcome t (input : Inherited_turn.Input.run_user) failure =
  match input.preparation with
  | None -> Run_admission_outcome.Rejected failure
  | Some preparation ->
    let retained =
      ordinary_run_receipt
        t
        ~principal_id:(Run_preparation.principal_id preparation)
        ~key:input.request.key
        ~request_sha256:input.request_sha256
    in
    (match retained with
     | Ok (Some ({ kind = Admission; _ } as receipt)) ->
       Run_admission_outcome.Admitted receipt
     | Ok (Some { kind = Action | Terminal; _ }) | Ok None | Error _ ->
       if !(input.attempted)
       then Run_admission_outcome.Uncertain failure
       else Run_admission_outcome.Rejected failure)
;;

let close_prepared_run_handler t preparation =
  let%bind.Result closed =
    Run_preparation.Admission_exit.close_from_caller
      preparation
      ~owner:t.run_preparation_owner
  in
  match closed with
  | Retained_by_admission -> Ok ()
  | Closed ->
    (match t.run_preparation with
     | Some (Initial actual) when phys_equal actual preparation ->
       t.run_preparation <- None
     | Some _ | None -> ());
    Ok ()
;;

let close_prepared_run_from_caller t preparation =
  let%bind.Result closed =
    Run_preparation.Admission_exit.close_from_caller
      preparation
      ~owner:t.run_preparation_owner
  in
  match closed with
  | Retained_by_admission -> Ok ()
  | Closed ->
    (match t.run_preparation with
     | Some (Initial actual) when phys_equal actual preparation -> close_run_preparation t
     | Some _ | None -> ());
    Ok ()
;;

let admit_prepared_run ?origin_observation t input ~capture =
  let open Result.Let_syntax in
  let%bind preparation =
    Result.of_option
      input.Inherited_turn.Input.preparation
      ~error:(error Conflict "prepared Run input lost actual preparation")
  in
  if not (Run_preparation.belongs_to preparation ~owner:t.run_preparation_owner)
  then
    Ok
      (Inherited_turn.Decision.Completed
         (Run_admission_outcome.Rejected
            (error Conflict "run preparation belongs to another actor")))
  else (
    let awaiting_origin = ref false in
    Exn.protect
      ~finally:(fun () ->
        if not !awaiting_origin
        then
          ignore
            (close_prepared_run_handler t preparation
             : (unit, Agent_protocol.Error.t) result))
      ~f:(fun () ->
        let result =
          let%bind () = check_run_preparation t preparation in
          admit_run ?origin_observation t input ~reply:Prepared_outcome ~capture
        in
        match result with
        | Ok (Need_private_origin _ as decision) ->
          awaiting_origin := true;
          Ok decision
        | Ok ((Completed _ | Pending _) as decision) -> Ok decision
        | Ok (Need_idle_cleanup _) -> .
        | Error failure ->
          Ok (Inherited_turn.Decision.Completed (prepared_run_outcome t input failure))))
;;

let retained_managed_receipt t candidate =
  List.find t.state.managed_submissions ~f:(Managed_submission.same_key candidate)
  |> Result.of_option
       ~error:(error Invalid_state "managed send did not retain its receipt")
;;

let capture_inherited_managed t ~capture (input : Inherited_turn.Input.managed) receipt =
  let open Result.Let_syntax in
  let%bind () = require_available_descendant_admission_slot t in
  let%bind () = check_inherited_managed_origin input.origin in
  let%bind pending, custody =
    prepare_idle_message_input ~owner:Host_internal ~timing:Safe_boundary t input.entry
  in
  if List.is_empty (Pending_turn.entries pending)
  then (
    let%bind _ =
      transition
        t
        ~delta:
          (Batch
             [ Managed_submission_admitted receipt; Pending_turn.enqueue_delta pending ])
        ~payloads:(Pending_turn.deferred_payloads pending)
    in
    let%map receipt = retained_managed_receipt t receipt in
    Inherited_turn.Decision.Completed receipt)
  else (
    let transferred = ref false in
    Exn.protect
      ~finally:(fun () ->
        if not !transferred then Option.iter custody ~f:retire_agent_custody)
      ~f:(fun () ->
        let operation, delta, payloads =
          idle_message_turn
            ~extra_deltas:[ Managed_submission_admitted receipt ]
            t
            pending
        in
        let source =
          Inherited_turn.Source.Managed
            { origin = input.origin; receipt; operation; custody; entry = input.entry }
        in
        let%map decision =
          capture_inherited_turn_plan
            t
            ~capture
            ~source
            ~commit_attempted:(ref false)
            ~delta
            ~payloads
        in
        transferred := true;
        decision))
;;

let submit_managed_message
      ?origin_observation
      t
      (input : Inherited_turn.Input.managed)
      ~capture
  =
  let module M = Managed_submission in
  let open Result.Let_syntax in
  let%bind () =
    match t.state.spec.delegation with
    | Some current
      when Agent_store.Delegation_store.Reference.equal current input.reference
           && Agent_protocol.Id.Session.equal
                input.reference.child_session_id
                t.state.identity.session_id -> Ok ()
    | Some _ | None ->
      Error (error Permission_denied "delegation.send: child relationship does not match")
  in
  let%bind candidate =
    M.create
      ~reference:input.reference
      ~key:input.key
      ~request_sha256:input.request_sha256
      ~generation:input.generation
      ~history_id:input.entry.id
      ~now:(t.services.now ())
  in
  match List.find t.state.managed_submissions ~f:(M.same_key candidate) with
  | Some receipt ->
    if String.equal receipt.request_sha256 input.request_sha256
    then Ok (Inherited_turn.Decision.Completed receipt)
    else Error (error Conflict "managed send key was used for a different request")
  | None ->
    let%bind () = require_selected_execution t in
    let%bind () =
      match
        ( Int.equal input.generation t.state.identity.generation
        , input.entry.role
        , input.entry.kind
        , input.entry.provenance )
      with
      | true, User, Message, Canonical -> Ok ()
      | _ -> Error (error Conflict "managed message generation or input is invalid")
    in
    let%bind () =
      match input.max_receipts with
      | Some maximum
        when maximum < 1 || List.length t.state.managed_submissions >= maximum ->
        Error (error Invalid_state "managed submission receipt capacity reached")
      | None | Some _ -> Ok ()
    in
    let%bind () = require_submit_ready t in
    let%bind requirement =
      match
        t.idle_moderator_borrowed, t.state.active_operation, t.state.lifecycle.observed
      with
      | false, None, Idle -> checked_turn_requirement ?origin_observation t
      | (true | false), (Some _ | None), _ ->
        Ok Inherited_turn.Origin_requirement.Ordinary
    in
    (match requirement with
     | Need_private_origin ->
       capture_turn_origin t ~capture ~input:(Inherited_turn.Input.Managed input)
     | Scoped -> capture_inherited_managed t ~capture input candidate
     | Ordinary ->
       let%bind _ =
         submit_authorized_message
           t
           input.entry
           ~extra_deltas:[ Managed_submission_admitted candidate ]
       in
       let%map receipt = retained_managed_receipt t candidate in
       Inherited_turn.Decision.Completed receipt)
;;

let commit_history_transition t ~delta ~payloads ~admission =
  let open Result.Let_syntax in
  let%bind agent_custody =
    match admission with
    | None -> Ok None
    | Some admission ->
      let%bind () = require_selected_execution t in
      admission_agent_custody t admission
  in
  let before = t.state in
  let%bind prepared = prepare_transition t ~delta ~payloads in
  let attempted = ref false in
  let%bind staged =
    match admission with
    | None -> Ok None
    | Some admission ->
      Turn_admission_staging.capture
        ~owner:t.run_preparation_owner
        ~before
        ~candidate:prepared
        ~operation:(Turn_admission.operation admission)
        ~remaining_audit:t.command_audit
        ~commit_attempted:attempted
        ~plan:(admission, agent_custody)
      |> Result.map ~f:Option.some
  in
  Eio.Cancel.protect (fun () ->
    let%bind () =
      persist_transition
        ~commit_attempted:attempted
        ~check_before_commit:(fun () ->
          let%bind () = check_turn_custody t agent_custody in
          Option.value_map staged ~default:(Ok ()) ~f:(fun staged ->
            Turn_admission_staging.check_before_writer
              staged
              ~owner:t.run_preparation_owner
              ~state:t.state))
        t
        prepared
    in
    install_committed_transition t prepared;
    let%map suffix =
      match staged with
      | None -> Ok None
      | Some staged ->
        let%bind acknowledgement =
          Turn_admission_staging.acknowledge
            staged
            ~owner:t.run_preparation_owner
            ~state:t.state
        in
        Turn_admission_staging.finish
          acknowledgement
          ~owner:t.run_preparation_owner
          ~state:t.state
        |> Result.map ~f:Option.some
    in
    publish_committed_transition t prepared;
    Option.iter suffix ~f:(fun (admission, agent_custody) ->
      let operation = Turn_admission.operation admission in
      if Option.is_none t.operation_agent_custody
      then install_operation_agent_custody t operation agent_custody;
      prune_pending_agent_custody t;
      launch_worker t operation);
    Session_state.summary t.state)
;;

let history_continuation_availability t =
  match t.state.lifecycle.observed, t.operation_worker with
  | Stopped, _ -> Some Agent_protocol.History_edit.Continuation.Stopped
  | Idle, Some _ -> None
  | _ -> Some Agent_protocol.History_edit.Continuation.Runtime_unavailable
;;

let admit_history_input
  : type outcome.
    ?origin_observation:Descendant_origin_observation.Observed.t
    -> t
    -> outcome Inherited_turn.History_input.t
    -> capture:outcome Inherited_turn.Capture.t
    -> (outcome Inherited_turn.Decision.t, Agent_protocol.Error.t) result
  =
  fun ?origin_observation t input ~capture ->
  let open Result.Let_syntax in
  let%bind () = check_history_input t input in
  let%bind requirement = checked_turn_requirement ?origin_observation t in
  let admission = Inherited_turn.History_input.admission input in
  match requirement with
  | Ordinary ->
    let%map session =
      commit_history_transition
        t
        ~delta:(Inherited_turn.History_input.delta input)
        ~payloads:(Inherited_turn.History_input.payloads input)
        ~admission:(Some admission)
    in
    Inherited_turn.Decision.Completed (Inherited_turn.History_input.result input ~session)
  | Need_private_origin ->
    capture_turn_origin t ~capture ~input:(Inherited_turn.Input.History input)
  | Scoped ->
    let%bind () = require_available_descendant_admission_slot t in
    let%bind () = require_selected_execution t in
    let%bind custody = admission_agent_custody t admission in
    let transferred = ref false in
    Exn.protect
      ~finally:(fun () ->
        if not !transferred then Option.iter custody ~f:retire_agent_custody)
      ~f:(fun () ->
        let source = Inherited_turn.Source.History { input; custody } in
        let%map decision =
          capture_inherited_turn_plan
            t
            ~capture
            ~source
            ~commit_attempted:(ref false)
            ~delta:(Inherited_turn.History_input.delta input)
            ~payloads:(Inherited_turn.History_input.payloads input)
        in
        transferred := true;
        decision)
;;

let edit_history_internal
      t
      (request : Agent_protocol.History_edit.Edit_request.t)
      ~capture
  =
  let open Result.Let_syntax in
  let%bind () =
    history_command_precondition
      t
      request.session_id
      request.attachment_id
      request.expected_generation
      request.expected_revision
  in
  let%bind plan = History_edit.prepare t.state ~edit:request.edit in
  let continue =
    Agent_protocol.History_edit.Mode.equal
      (Agent_protocol.History_edit.mode request.edit)
      Edit_and_continue
  in
  let%bind () =
    if continue && not (List.is_empty t.state.conversation.deferred_user_entries)
    then
      Error
        (error
           Pending_input_conflict
           "edit-and-continue requires an empty pending-input queue")
    else Ok ()
  in
  let%bind archive =
    t.persistence.archive_reference
      ~previous:t.state
      ~kind:Edit
      (Agent_protocol.Id.Operation.create ())
  in
  let continuation =
    if not continue
    then History_edit_transition.Save_only
    else (
      match history_continuation_availability t with
      | Some reason -> History_edit_transition.Unavailable reason
      | None -> History_edit_transition.Start (create_turn_operation t Administrative))
  in
  let%bind prepared =
    History_edit_transition.create t.state ~plan ~edit:request.edit ~archive ~continuation
  in
  match History_edit_transition.admission prepared with
  | None ->
    let%map session =
      commit_history_transition
        t
        ~delta:(History_edit_transition.delta prepared)
        ~payloads:(History_edit_transition.payloads prepared)
        ~admission:None
    in
    Inherited_turn.Decision.Completed
      (Inherited_turn.History_input.edit_result prepared ~session)
  | Some admission ->
    let%bind worker =
      Result.of_option
        t.operation_worker
        ~error:(error Conflict "history continuation runtime disappeared")
    in
    let input =
      Inherited_turn.History_input.Edit { request; prepared; admission; worker }
    in
    admit_history_input t input ~capture
;;

let continue_history_internal
      t
      (request : Agent_protocol.History_edit.Continue_request.t)
      ~capture
  =
  let open Result.Let_syntax in
  let%bind () =
    history_command_precondition
      t
      request.session_id
      request.attachment_id
      request.expected_generation
      request.expected_revision
  in
  let%bind () =
    if List.is_empty t.state.conversation.deferred_user_entries
    then Ok ()
    else
      Error
        (error
           Pending_input_conflict
           "history continuation requires an empty pending-input queue")
  in
  match history_continuation_availability t with
  | Some reason ->
    Ok
      (Inherited_turn.Decision.Completed
         ({ session = Session_state.summary t.state
          ; continuation = Agent_protocol.History_edit.Continuation.Not_started reason
          }
          : History_continuation_result.t))
  | None ->
    let%bind recovery = History_continuation.prepare t.state ~retiring_history:false in
    let operation = create_turn_operation t Administrative in
    let%bind admission =
      Turn_admission.create
        t.state
        ~operation
        ~notification_wakes:[]
        ~adopt_deferred:false
    in
    let%bind worker =
      Result.of_option
        t.operation_worker
        ~error:(error Conflict "history continuation runtime disappeared")
    in
    let input =
      Inherited_turn.History_input.Continue { request; recovery; admission; worker }
    in
    admit_history_input t input ~capture
;;

let submit_held_run_input_ordinary t (selected : Inherited_turn.Held_input_selection.t) =
  let open Result.Let_syntax in
  let scope = selected.scope in
  let input = selected.input in
  let activation = Admitted_activation.Continuation.target scope.continuation in
  let worker = selected.worker in
  let run = selected.run in
  let binding = selected.binding in
  let original = selected.original in
  let entry = Runtime_input_preparation.Prepared_input.entry input in
  let%bind enqueue =
    prepare_pending_inputs t ~owner:Host_internal Safe_boundary [ entry ]
  in
  let%bind pending =
    Pending_turn.prepare
      t.state
      ~enqueue
      ~entry
      ~runtime_admission_open:(runtime_admission_open t)
  in
  let operation = create_turn_operation t User_submit in
  let%bind handoff =
    Run_input_handoff.prepare
      t.state
      ~run
      ~request:scope.request
      ~input
      ~operation
      ~pending
      ~now:operation.started_at
  in
  let lifecycle = lifecycle_for_operation t operation.id in
  let before = t.state in
  let%bind candidate =
    prepare_transition
      ~run_preparation:activation.preparation
      t
      ~delta:
        (Session_delta.Batch
           ((Run_input_handoff.delta handoff :: Pending_turn.turn_deltas pending)
            @ [ Active_operation_changed (Some operation); Lifecycle_changed lifecycle ]))
      ~payloads:
        (Pending_turn.deferred_payloads pending
         @ [ History_appended (Pending_turn.entries pending)
           ; Operation_started operation
           ; Session_state_changed
               { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
           ])
  in
  let attempted = ref false in
  let%bind staged =
    Turn_admission_staging.capture
      ~owner:t.run_preparation_owner
      ~before
      ~candidate
      ~operation
      ~remaining_audit:t.command_audit
      ~commit_attempted:attempted
      ~plan:(operation, entry)
  in
  let%bind controller = scope.continuation.controller.transfer () in
  let%bind () =
    if phys_equal controller.association activation.association
    then Ok ()
    else (
      controller.close ();
      Error (error Conflict "held root transferred another admitted association"))
  in
  let proof : Held_operation.Proof.t =
    { scope = activation.scope
    ; run
    ; admission = activation.admission
    ; source = activation.source
    ; operation
    ; worker
    ; binding
    ; controller
    }
  in
  let held : Held_operation.t = { proof; phase = Staged; target_current = None } in
  let owner : Operation_owner.t =
    { operation_id = operation.id
    ; admission = create_agent_admission (Some (create_agent_custody original))
    ; held = Some held
    ; descendant_guard = None
    ; completion =
        Operation_completion.create
          ~issuer:t.initialization_owner
          ~domain:t.runtime_source_domain
          ~operation
    }
  in
  let acknowledgement : Held_operation_acknowledgement.t =
    { input_scope = scope
    ; input
    ; preparation_exit = None
    ; activation
    ; held
    ; owner
    ; completion_slot = Some owner.completion
    ; previous = t.state
    ; candidate
    }
  in
  let persisted =
    Exn.protect
      ~finally:(fun () ->
        if !attempted
        then (
          match scope.phase with
          | Parsed_ready _ -> scope.phase <- Root_attempt_unconfirmed
          | Parsing | Admission_pending _ | Consumed _ | Root_attempt_unconfirmed | Closed
            -> ());
        match held.phase with
        | Staged ->
          if !attempted
          then retire_agent_admission owner.admission
          else Operation_owner.retire owner
        | Pending_first_effect | Started | Retired -> ())
      ~f:(fun () ->
        let%bind () =
          persist_transition
            ~run_preparation:activation.preparation
            ?startup_write:
              (Option.map t.canonical_persistence ~f:(fun _ ->
                 Startup_write.Input_root scope.cleanup))
            ~commit_attempted:attempted
            ~check_before_commit:(fun () ->
              let%bind () = check_held_effect scope.continuation in
              let%bind () =
                Held_operation_acknowledgement.check acknowledgement ~actor:t ~candidate
              in
              let%bind () = input_scope_basis t scope in
              let%bind () =
                Admitted_activation.Continuation.check_basis scope.continuation
              in
              Turn_admission_staging.check_before_writer
                staged
                ~owner:t.run_preparation_owner
                ~state:t.state)
            t
            candidate
        in
        install_committed_transition
          ~held_operation_acknowledgement:acknowledgement
          ~run_preparation:activation.preparation
          t
          candidate;
        Turn_admission_staging.acknowledge
          staged
          ~owner:t.run_preparation_owner
          ~state:t.state)
  in
  let%bind acknowledgement = persisted in
  let%bind operation, entry =
    Turn_admission_staging.finish
      acknowledgement
      ~owner:t.run_preparation_owner
      ~state:t.state
  in
  (* A failed publisher preserves the acknowledged proof but starts no worker;
     existing owner termination/recovery handles that truthful Starting row. *)
  publish_committed_transition t candidate;
  launch_worker t operation;
  Ok
    { session = Session_state.summary t.state
    ; history_id = entry.id
    ; disposition = Started
    ; operation_id = Some operation.id
    }
;;

let check_selected_held_input t (expected : Inherited_turn.Held_input_selection.t) =
  let open Result.Let_syntax in
  let%bind current = select_held_input_source t expected.scope expected.input in
  if
    phys_equal current.worker expected.worker
    && phys_equal current.binding expected.binding
    && phys_equal current.original expected.original
    && Agent_protocol.Run.equal current.run expected.run
  then Ok ()
  else Error (error Conflict "held input selection changed during external origin read")
;;

let admit_held_input_selection
      ?origin_observation
      t
      (selected : Inherited_turn.Held_input_selection.t)
      ~capture
  =
  let open Result.Let_syntax in
  let%bind requirement = checked_turn_requirement ?origin_observation t in
  match requirement with
  | Ordinary ->
    let%map result = submit_held_run_input_ordinary t selected in
    Inherited_turn.Decision.Completed result
  | Need_private_origin ->
    capture_turn_origin
      t
      ~capture
      ~input:(Inherited_turn.Input.Held_input_selected selected)
  | Scoped ->
    let%bind () = require_available_descendant_admission_slot t in
    let scope = selected.scope in
    let input = selected.input in
    let activation = Admitted_activation.Continuation.target scope.continuation in
    let entry = Runtime_input_preparation.Prepared_input.entry input in
    let%bind enqueue =
      prepare_pending_inputs t ~owner:Host_internal Safe_boundary [ entry ]
    in
    let%bind pending =
      Pending_turn.prepare
        t.state
        ~enqueue
        ~entry
        ~runtime_admission_open:(runtime_admission_open t)
    in
    let operation = create_turn_operation t User_submit in
    let%bind handoff =
      Run_input_handoff.prepare
        t.state
        ~run:selected.run
        ~request:scope.request
        ~input
        ~operation
        ~pending
        ~now:operation.started_at
    in
    let%bind preparation_exit =
      Run_preparation.Admission_exit.capture
        activation.preparation
        ~owner:t.run_preparation_owner
    in
    let custody = Some (create_agent_custody selected.original) in
    let transferred = ref false in
    Exn.protect
      ~finally:(fun () ->
        if not !transferred then Option.iter custody ~f:retire_agent_custody)
      ~f:(fun () ->
        let lifecycle = lifecycle_for_operation t operation.id in
        let source =
          Inherited_turn.Source.Held_input
            { selection = selected
            ; pending
            ; handoff
            ; operation
            ; custody
            ; preparation_exit
            }
        in
        let%map decision =
          capture_inherited_turn_plan
            t
            ~capture
            ~source
            ~commit_attempted:(ref false)
            ~delta:
              (Session_delta.Batch
                 ((Run_input_handoff.delta handoff :: Pending_turn.turn_deltas pending)
                  @ [ Active_operation_changed (Some operation)
                    ; Lifecycle_changed lifecycle
                    ]))
            ~payloads:
              (Pending_turn.deferred_payloads pending
               @ [ History_appended (Pending_turn.entries pending)
                 ; Operation_started operation
                 ; Session_state_changed
                     { desired_state = lifecycle.desired
                     ; observed_state = lifecycle.observed
                     }
                 ])
        in
        transferred := true;
        decision)
;;

let submit_held_run_input_internal t scope input ~capture =
  let open Result.Let_syntax in
  let%bind selected = select_held_input_source t scope input in
  admit_held_input_selection t selected ~capture
;;

let find_permission t permission_id =
  List.find t.state.permissions ~f:(fun permission ->
    Agent_protocol.Id.Permission.compare permission.id permission_id = 0)
  |> Result.of_option ~error:(error Invalid_request "permission request does not exist")
;;

let permission_state = function
  | Agent_protocol.Permission.Deny -> Agent_protocol.Permission.Denied
  | Approve_once | Approve_session | Approve_prefix | Durable_exact -> Approved
;;

let grant_scope = function
  | Agent_protocol.Permission.Approve_session -> Some Agent_protocol.Grant.Exact_session
  | Approve_prefix -> Some Prefix_session
  | Durable_exact -> Some Durable_exact
  | Approve_once | Deny -> None
;;

let grant_identity permission scope =
  match scope with
  | Agent_protocol.Grant.Prefix_session ->
    Ok
      (Permission_policy.prefix_identity_digest
         ~tool_name:permission.Agent_protocol.Permission.tool_name)
  | Exact_session | Durable_exact ->
    permission.runtime_identity
    |> Result.of_option
         ~error:(error Invalid_state "permission request has no runtime identity")
;;

let grant_for_resolution
      (t : t)
      (permission : Agent_protocol.Permission.t)
      principal_id
      choice
  =
  match grant_scope choice with
  | None -> Ok None
  | Some scope ->
    let open Result.Let_syntax in
    let%bind principal_id =
      principal_id
      |> Result.of_option
           ~error:(error Permission_denied "grant approval requires a principal")
    in
    let%map identity_digest = grant_identity permission scope in
    Some
      Agent_protocol.Grant.
        { id = Agent_protocol.Id.Grant.create ()
        ; session_id = t.state.identity.session_id
        ; principal_id
        ; tool_name = permission.tool_name
        ; identity_digest
        ; scope
        ; state = Active
        ; created_at = t.services.now ()
        ; expires_at = None
        ; revoked_at = None
        ; revocation_reason = None
        }
;;

let permission_owner_active t (permission : Agent_protocol.Permission.t) =
  match permission.owner with
  | Operation id ->
    (match t.state.active_operation with
     | Some operation when not (Agent_protocol.Id.Operation.equal operation.id id) ->
       Error (error Conflict "permission request belongs to another active operation")
     | _ -> Ok ())
  | Invocation id ->
    let live =
      List.exists t.invocation_executions ~f:(fun execution ->
        execution.accepts_children
        && Agent_protocol.Id.Invocation.equal id execution.dispatched.context.id
        && execution.dispatched.context.generation = permission.generation
        &&
        match execution.owner with
        | Foreground id ->
          Option.exists t.state.active_operation ~f:(fun operation ->
            Agent_protocol.Id.Operation.equal operation.id id
            &&
            match operation.state with
            | Cancelling -> false
            | _ -> true)
        | Background_job scope -> Result.is_ok (job_scope_can_execute t scope)
        | Invocation_moderator borrow ->
          (not (borrow.committed || borrow.cancel_requested))
          && Option.exists t.moderator_borrow ~f:(phys_equal borrow)
          &&
            (match borrow.job_scope, borrow.operation_id with
            | Some scope, None -> Result.is_ok (job_scope_can_execute t scope)
            | Some _, Some _ -> false
            | None, None ->
              t.idle_moderator_borrowed && Option.is_none t.state.active_operation
            | None, Some id ->
              Option.exists t.state.active_operation ~f:(fun operation ->
                Agent_protocol.Id.Operation.equal operation.id id
                &&
                match operation.state with
                | Cancelling -> false
                | _ -> true))
        | Event_moderator borrow ->
          t.idle_moderator_borrowed
          && borrow.callback_active
          && (not (borrow.committed || borrow.cancel_requested))
          && Option.exists t.queued_event_borrow ~f:(phys_equal borrow)
          &&
            (match borrow.job_scope, borrow.receipt.context.operation_id with
            | Some scope, None -> Result.is_ok (job_scope_can_execute t scope)
            | Some _, Some _ -> false
            | None, None -> Option.is_none t.state.active_operation
            | None, Some id ->
              Option.exists t.state.active_operation ~f:(fun operation ->
                Agent_protocol.Id.Operation.equal id operation.id
                &&
                match operation.state with
                | Cancelling -> false
                | _ -> true)))
      || Option.exists t.moderator_borrow ~f:(fun borrow ->
        borrow.accepts_children
        && (match borrow.kind with
            | Invocation _ -> true
            | Observation -> false)
        && (not (borrow.committed || borrow.cancel_requested))
        && Agent_protocol.Id.Invocation.equal id borrow.invocation.context.id
        && Int.equal borrow.invocation.context.generation permission.generation
        &&
        match borrow.job_scope, borrow.operation_id with
        | Some scope, None -> Result.is_ok (job_scope_can_execute t scope)
        | None, None | Some _, Some _ -> false
        | None, Some id ->
          Option.exists t.state.active_operation ~f:(fun operation ->
            Agent_protocol.Id.Operation.equal operation.id id
            &&
            match operation.state with
            | Cancelling -> false
            | _ -> true))
    in
    (match t.state.lifecycle.desired, live, t.state.halted, t.state.failure with
     | Running, true, false, None -> Ok ()
     | _ -> Error (error Conflict "permission requires a live invocation owner"))
;;

module Constructor_permission_owner = struct
  module Write = struct
    type t =
      | Admission
      | Negative_resolution
  end

  type t =
    { execution : invocation_execution
    ; borrow : queued_event_borrow
    ; scope : Initialization_scope.t
    }
end

type selected_permission_owner =
  | Initialization_permission of Constructor_permission_owner.t
  | Held_authored_permission of invocation_execution * Held_authored_start.t
  | Goal_resume_permission of invocation_execution * Goal_continuation.runtime_scope

let held_permission_basis t execution (scope : Held_authored_start.t) =
  if
    phys_equal scope.issuing_actor t.inference_owner_identity
    && Option.exists t.held_authored_start ~f:(phys_equal scope)
    && List.mem t.invocation_executions execution ~equal:phys_equal
    && execution.accepts_children
    && Atomic.get execution.authority_live
    && List.exists
         t.state.invocations
         ~f:(Agent_protocol.Invocation.equal execution.dispatched)
  then Ok ()
  else Error (error Conflict "held permission Invocation owner changed")
;;

let goal_permission_basis t (execution : invocation_execution) scope =
  let open Result.Let_syntax in
  let%bind () = goal_runtime_scope_basis t scope in
  let%bind () =
    match execution.owner with
    | Event_moderator borrow -> goal_runtime_event_basis t borrow scope
    | Background_job job ->
      if Option.exists (goal_runtime_job t job.job) ~f:(phys_equal scope)
      then Ok ()
      else Error (error Conflict "Goal permission Job belongs to another startup")
    | Foreground _ | Invocation_moderator _ ->
      Error (error Conflict "Goal permission Invocation has another owner")
  in
  if
    List.mem t.invocation_executions execution ~equal:phys_equal
    && execution.accepts_children
    && Atomic.get execution.authority_live
    && List.exists
         t.state.invocations
         ~f:(Agent_protocol.Invocation.equal execution.dispatched)
  then Ok ()
  else Error (error Conflict "Goal permission Invocation execution ended")
;;

let check_constructor_permission_owner t (owner : Constructor_permission_owner.t) =
  let open Result.Let_syntax in
  let%bind () = check_constructor_invocation_basis t owner.scope in
  if
    List.exists t.invocation_executions ~f:(phys_equal owner.execution)
    && owner.execution.accepts_children
    && Atomic.get owner.execution.authority_live
    && Option.exists
         (constructor_scope_of_borrow t owner.borrow)
         ~f:(phys_equal owner.scope)
    && List.exists t.state.invocations ~f:(fun retained ->
      Agent_protocol.Invocation.equal retained owner.execution.dispatched)
  then Ok ()
  else
    Error (error Conflict "constructor permission no longer owns its native invocation")
;;

let constructor_permission_owner t (permission : Agent_protocol.Permission.t) =
  let open Result.Let_syntax in
  match permission.owner with
  | Operation _ -> Ok None
  | Invocation id ->
    (match
       List.find t.invocation_executions ~f:(fun execution ->
         Agent_protocol.Id.Invocation.equal execution.dispatched.context.id id)
     with
     | None -> Ok None
     | Some execution ->
       (match goal_runtime_of_execution t (Inference_invocation execution) with
        | Some scope ->
          let%map () = goal_permission_basis t execution scope in
          Some (Goal_resume_permission (execution, scope))
        | None ->
          (match held_authored_of_execution t (Inference_invocation execution) with
           | Some scope ->
             let%map () = held_permission_basis t execution scope in
             Some (Held_authored_permission (execution, scope))
           | None ->
             (match execution.owner with
              | Event_moderator borrow ->
                (match constructor_scope_of_borrow t borrow with
                 | None -> Ok None
                 | Some scope ->
                   let owner : Constructor_permission_owner.t =
                     { execution; borrow; scope }
                   in
                   let%map () = check_constructor_permission_owner t owner in
                   Some (Initialization_permission owner))
              | Foreground _ | Invocation_moderator _ | Background_job _ -> Ok None))))
;;

(* The selected owner is captured before clocks/IDs are sampled. Only this
   validated DATA plan can advance the permission projection. The normal writer
   and its final currentness fence remain the sole persistence path. *)
let commit_permission_transition
      t
      owner
      ~(write : Constructor_permission_owner.Write.t)
      ~revision
      ~permissions
      ~grant
      ~lifecycle
      ~delta
      ~payloads
  =
  let open Result.Let_syntax in
  match owner with
  | None -> transition t ~delta ~payloads |> Result.map ~f:(fun _ -> ())
  | Some (Held_authored_permission (execution, scope)) ->
    let%bind () = held_permission_basis t execution scope in
    let run_preparation = held_authored_factual_preparation t scope in
    let%bind () =
      match write with
      | Admission -> held_authored_basis t scope
      | Negative_resolution ->
        if
          Option.is_none grant
          && List.for_all permissions ~f:(fun permission ->
            Option.exists
              permission.Agent_protocol.Permission.resolution
              ~f:(fun resolution ->
                Agent_protocol.Permission.equal_choice resolution.choice Deny))
        then Ok ()
        else Error (error Conflict "negative permission ACK contains approval")
    in
    let%bind candidate =
      match write with
      | Admission -> prepare_transition ?run_preparation t ~delta ~payloads
      | Negative_resolution -> prepare_transition t ~delta ~payloads
    in
    install
      ?run_preparation
      ~check_before_commit:(fun () ->
        let%bind () =
          match write with
          | Admission -> check_held_effect scope.continuation
          | Negative_resolution -> Ok ()
        in
        let%bind () = held_permission_basis t execution scope in
        if Int64.equal revision t.state.counters.revision
        then Ok ()
        else Error (error Conflict "held permission basis changed before ACK"))
      t
      candidate
  | Some (Goal_resume_permission (execution, scope)) ->
    let%bind () = goal_permission_basis t execution scope in
    let%bind () =
      match write with
      | Admission -> check_runtime_construction_effect (Existing_goal scope.continuation)
      | Negative_resolution ->
        if
          Option.is_none grant
          && List.for_all permissions ~f:(fun permission ->
            Option.exists
              permission.Agent_protocol.Permission.resolution
              ~f:(fun resolution ->
                Agent_protocol.Permission.equal_choice resolution.choice Deny))
        then Ok ()
        else Error (error Conflict "negative Goal permission ACK contains approval")
    in
    let%map _ =
      goal_runtime_transition t scope ~delta ~payloads ~check_before_commit:(fun () ->
        let%bind () =
          match write with
          | Admission ->
            check_runtime_construction_effect (Existing_goal scope.continuation)
          | Negative_resolution -> Ok ()
        in
        let%bind () = goal_permission_basis t execution scope in
        if Int64.equal revision t.state.counters.revision
        then Ok ()
        else Error (error Conflict "Goal permission basis changed before ACK"))
    in
    ()
  | Some (Initialization_permission owner) ->
    let run_preparation = Initialization_scope.initial_preparation owner.scope in
    let%bind () = check_constructor_permission_owner t owner in
    let%bind prepared =
      match write with
      | Admission -> prepare_transition ?run_preparation t ~delta ~payloads
      | Negative_resolution ->
        (* A factual denial must unblock its exact waiter even when the original
           proof expired. Keep physical/source/Run-preparation basis checks, not
           fresh-effect authorization. Install advances the SAME preparation. *)
        let%bind () =
          if
            Option.is_none grant
            && List.for_all permissions ~f:(fun permission ->
              Option.exists
                permission.Agent_protocol.Permission.resolution
                ~f:(fun resolution ->
                  Agent_protocol.Permission.equal_choice resolution.choice Deny))
          then Ok ()
          else Error (error Conflict "negative permission ACK contains approval facts")
        in
        prepare_transition t ~delta ~payloads
    in
    let%bind permission_checkpoint =
      Constructor_permission_checkpoint.prepare
        ~previous:t.state
        ~incoming:prepared.state
        ~invocation_id:owner.execution.dispatched.context.id
        ~permissions
        ~grant
        ~lifecycle
    in
    let acknowledgement =
      Initialization_scope.Acknowledgement.prepare
        ~permission_checkpoint
        owner.scope
        prepared.state
    in
    let%bind () =
      validate_initialization_projection
        (Initialization_scope.Acknowledgement.expected acknowledgement)
        prepared.state
    in
    let check_before_commit () =
      let%bind () =
        match write with
        | Admission -> validate_initialization_scope_current t owner.scope
        | Negative_resolution -> Ok ()
      in
      let%bind () = check_constructor_permission_owner t owner in
      let%bind () = Initialization_scope.Acknowledgement.check_basis acknowledgement in
      if Int64.equal revision t.state.counters.revision
      then Ok ()
      else Error (error Conflict "constructor permission basis changed before commit")
    in
    install
      ~initialization_acknowledgement:acknowledgement
      ~check_before_commit
      ?run_preparation
      t
      prepared
;;

let resolve_permission
      t
      (permission : Agent_protocol.Permission.t)
      ~principal_id
      ~choice
      ~reason
      ~resume_observed
  =
  let open Result.Let_syntax in
  let revision = t.state.counters.revision in
  let%bind owner = constructor_permission_owner t permission in
  let resolution =
    Agent_protocol.Permission.
      { choice; principal_id; resolved_at = t.services.now (); reason }
  in
  let permission =
    { permission with state = permission_state choice; resolution = Some resolution }
  in
  let open Result.Let_syntax in
  let%bind () =
    match choice with
    | Agent_protocol.Permission.Deny -> Ok ()
    | Approve_once | Approve_session | Approve_prefix | Durable_exact ->
      permission_owner_active t permission
  in
  let%bind grant = grant_for_resolution t permission principal_id choice in
  let lifecycle =
    Session_state.Lifecycle.
      { desired = t.state.lifecycle.desired
      ; observed =
          permission_resume_observed
            t
            ~resolved:[ permission.id ]
            ~fallback:resume_observed
      }
  in
  let%bind _ =
    commit_permission_transition
      t
      owner
      ~write:
        (match choice with
         | Agent_protocol.Permission.Deny -> Negative_resolution
         | Approve_once | Approve_session | Approve_prefix | Durable_exact -> Admission)
      ~revision
      ~permissions:[ permission ]
      ~grant
      ~lifecycle
      ~delta:
        (Session_delta.Batch
           ([ Session_delta.Permission_changed permission
            ; Session_delta.Lifecycle_changed lifecycle
            ]
            @ Option.to_list
                (Option.map grant ~f:(fun value -> Session_delta.Grant_changed value))))
      ~payloads:
        ([ Agent_protocol.Event.Durable.Payload.Permission_resolved permission
         ; Agent_protocol.Event.Durable.Payload.Session_state_changed
             { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
         ]
         @ Option.to_list
             (Option.map grant ~f:(fun value ->
                Agent_protocol.Event.Durable.Payload.Grant_created value)))
  in
  Option.iter (Map.find !(t.permission_waiters) permission.id) ~f:(fun waiter ->
    Eio.Promise.resolve waiter.resolver resolution);
  t.permission_waiters := Map.remove !(t.permission_waiters) permission.id;
  Ok permission
;;

let schedule_permission_expiry
      t
      (permission : Agent_protocol.Permission.t)
      timeout_seconds
      fallback
  =
  if t.schedule_permission_timeouts
  then
    Option.iter timeout_seconds ~f:(fun seconds ->
      Eio.Fiber.fork ~sw:t.sw (fun () ->
        t.sleep seconds;
        (* Preserve the actual expiry request and its result semantics on denial.
           A failed refresh grants nothing; the Actor still repeats its final guard. *)
        ignore
          (refresh_held_permission_resolution t permission.id fallback
           : (unit, Agent_protocol.Error.t) result);
        let promise, resolver = Eio.Promise.create () in
        let request =
          Expire_permission
            (permission.Agent_protocol.Permission.id, permission.generation, fallback)
        in
        match
          Mailbox.push t.mailbox ~priority:Priority (Pack (None, request, resolver))
        with
        | Error _ -> ()
        | Ok () ->
          ignore (Actor_reply.await promise : (unit, Agent_protocol.Error.t) result)))
;;

let open_permission t (permission : Agent_protocol.Permission.t) timeout_seconds fallback =
  let open Result.Let_syntax in
  let revision = t.state.counters.revision in
  let%bind owner = constructor_permission_owner t permission in
  let%bind () = permission_owner_active t permission in
  if
    Agent_protocol.Id.Session.compare permission.session_id t.state.identity.session_id
    <> 0
  then Error (error Invalid_request "permission request belongs to another session")
  else if permission.generation <> t.state.identity.generation
  then Error (error Conflict "permission request belongs to a stale session generation")
  else if not (Agent_protocol.Permission.equal_state permission.state Pending)
  then Error (error Invalid_request "new permission request must be pending")
  else if
    not
      (List.mem permission.choices fallback ~equal:Agent_protocol.Permission.equal_choice)
  then Error (error Invalid_request "permission fallback choice is not offered")
  else if
    List.exists t.state.permissions ~f:(fun previous ->
      Agent_protocol.Id.Permission.equal previous.id permission.id)
  then Error (error Conflict "permission request identity is already retained")
  else (
    let response, resolver = Eio.Promise.create () in
    let resume_observed =
      match t.state.lifecycle.observed with
      | Waiting_for_permission id ->
        Option.value_map
          (Map.find !(t.permission_waiters) id)
          ~default:t.state.lifecycle.observed
          ~f:(fun waiter -> waiter.resume_observed)
      | observed -> observed
    in
    let lifecycle =
      Session_state.Lifecycle.
        { desired = t.state.lifecycle.desired
        ; observed = Waiting_for_permission permission.id
        }
    in
    let open Result.Let_syntax in
    let%bind _ =
      commit_permission_transition
        t
        owner
        ~write:Admission
        ~revision
        ~permissions:[ permission ]
        ~grant:None
        ~lifecycle
        ~delta:
          (Session_delta.Batch
             [ Permission_changed permission; Lifecycle_changed lifecycle ])
        ~payloads:
          [ Agent_protocol.Event.Durable.Payload.Permission_requested permission
          ; Session_state_changed
              { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
          ]
    in
    t.permission_waiters
    := Map.set
         !(t.permission_waiters)
         ~key:permission.id
         ~data:{ resolver; resume_observed };
    schedule_permission_expiry t permission timeout_seconds fallback;
    Ok response)
;;

let respond_permission_internal
      t
      attachment_id
      principal_id
      permission_id
      permission_generation
      choice
      reason
  =
  let open Result.Let_syntax in
  let%bind _ = write_attachment t attachment_id in
  let%bind permission = find_permission t permission_id in
  if permission.generation <> permission_generation
  then Error (error Conflict "permission generation does not match")
  else if not (Agent_protocol.Permission.equal_state permission.state Pending)
  then Error (error Already_resolved "permission has already been resolved")
  else if
    Option.value_map permission.expires_at ~default:false ~f:(fun deadline ->
      Agent_protocol.Timestamp.compare deadline (t.services.now ()) <= 0)
  then Error (error Already_resolved "permission request has expired")
  else if
    not (List.mem permission.choices choice ~equal:Agent_protocol.Permission.equal_choice)
  then Error (error Invalid_request "permission choice is not offered")
  else (
    match Map.find !(t.permission_waiters) permission_id with
    | None -> Error (error Interrupted "permission continuation is unavailable")
    | Some waiter ->
      resolve_permission
        t
        permission
        ~principal_id
        ~choice
        ~reason
        ~resume_observed:waiter.resume_observed)
;;

let resolve_permission_system t permission_id generation choice reason =
  let open Result.Let_syntax in
  let%bind permission = find_permission t permission_id in
  if permission.generation <> generation
  then Error (error Conflict "permission generation does not match")
  else if not (Agent_protocol.Permission.equal_state permission.state Pending)
  then Error (error Already_resolved "permission has already been resolved")
  else if
    not (List.mem permission.choices choice ~equal:Agent_protocol.Permission.equal_choice)
  then Error (error Invalid_request "permission choice is not offered")
  else (
    match Map.find !(t.permission_waiters) permission_id with
    | None -> Error (error Interrupted "permission continuation is unavailable")
    | Some waiter ->
      resolve_permission
        t
        permission
        ~principal_id:None
        ~choice
        ~reason
        ~resume_observed:waiter.resume_observed)
;;

let expire_permission_internal t permission_id generation fallback =
  match
    find_permission t permission_id, Map.find !(t.permission_waiters) permission_id
  with
  | Ok permission, Some waiter
    when permission.generation = generation
         && Agent_protocol.Permission.equal_state permission.state Pending ->
    resolve_permission
      t
      permission
      ~principal_id:None
      ~choice:fallback
      ~reason:(Some "permission request timed out")
      ~resume_observed:waiter.resume_observed
    |> Result.map ~f:(fun _ -> ())
  | _ -> Ok ()
;;

let revoke_grant t attachment_id grant_id reason =
  with_writer t attachment_id (fun () ->
    let open Result.Let_syntax in
    let%bind update =
      Security_grant.revoke
        ~now:(t.services.now ())
        ~reason
        ~session_id:t.state.identity.session_id
        ~creating_principal:t.state.identity.creating_principal
        ~generic:t.state.grants
        ~shell:t.state.shell
        grant_id
    in
    let delta, grant =
      match update with
      | Security_grant.Generic grant -> Session_delta.Grant_changed grant, grant
      | Shell (shell, grant) -> Session_delta.Shell_changed shell, grant
    in
    let%map session =
      transition
        t
        ~delta
        ~payloads:[ Agent_protocol.Event.Durable.Payload.Grant_revoked grant ]
    in
    grant, session)
;;

let replace_shell_approval_grants ?run_preparation t approval_grants =
  let shell = { t.state.shell with approval_grants } in
  transition ?run_preparation t ~delta:(Session_delta.Shell_changed shell) ~payloads:[]
  |> Result.map ~f:(fun _ -> ())
;;

let replace_shell_extension_snapshots ?run_preparation t extension_snapshots =
  let shell = { t.state.shell with extension_snapshots } in
  transition ?run_preparation t ~delta:(Session_delta.Shell_changed shell) ~payloads:[]
  |> Result.map ~f:(fun _ -> ())
;;

let add_shell_manifest_grant ?run_preparation t grant =
  let manifest_grants = grant :: t.state.shell.manifest_grants in
  let shell = { t.state.shell with manifest_grants } in
  let projected =
    Security_grant.project_manifest
      ~now:(t.services.now ())
      ~session_id:t.state.identity.session_id
      ~creating_principal:t.state.identity.creating_principal
      grant
  in
  transition
    ?run_preparation
    t
    ~delta:(Session_delta.Shell_changed shell)
    ~payloads:[ Agent_protocol.Event.Durable.Payload.Grant_created projected ]
  |> Result.map ~f:(fun _ -> ())
;;

let change_job t attachment_id (job : Agent_protocol.Job.t) =
  with_writer t attachment_id (fun () ->
    match
      List.exists t.job_scopes ~f:(fun scope ->
        Agent_protocol.Id.Job.equal scope.job.id job.id)
    with
    | true -> Error (error Conflict "job execution owns its current record")
    | false ->
      transition
        t
        ~delta:(Session_delta.Job_changed job)
        ~payloads:[ Agent_protocol.Event.Durable.Payload.Job_state_changed job ])
;;

let find_job t job_id =
  List.find t.state.jobs ~f:(fun job -> Agent_protocol.Id.Job.compare job.id job_id = 0)
  |> Result.of_option ~error:(error Invalid_request "job was not found")
;;

let capture_inference_target t target limits =
  let open Result.Let_syntax in
  let%bind _ =
    Inference.Selection.capture t.state.spec.inference_target ~target ~limits
    |> Result.map_error ~f:(fun failure ->
      error
        Invalid_request
        (Sexp.to_string_hum (Inference.Request.Error.sexp_of_t failure)))
  in
  transition t ~delta:(Session_delta.Inference_target_captured target) ~payloads:[]
  |> Result.map ~f:ignore
;;

let find_model_job_target t job_id generation =
  let open Result.Let_syntax in
  let%bind job = find_job t job_id in
  let%bind () =
    if
      Int.equal job.generation generation
      && Int.equal generation t.state.identity.generation
    then Ok ()
    else Error (error Conflict "model job capture belongs to a stale generation")
  in
  let%bind () =
    match job.kind with
    | Model_call -> Ok ()
    | Nested_agent | Scheduled_event | Async_tool | Shell_process | Compaction ->
      Error
        (error Invalid_request "only an actual model job may capture an inference target")
  in
  let%map binding =
    List.find t.state.model_job_targets ~f:(fun binding ->
      Agent_protocol.Id.Job.equal (Model_job_target.job_id binding) job_id
      && Int.equal (Model_job_target.generation binding) generation)
    |> Result.of_option
         ~error:(error Invalid_request "model job target binding is absent")
  in
  job, binding
;;

let capture_model_job_source ?run_preparation t job_id generation target limits =
  let open Result.Let_syntax in
  let%bind job, binding = find_model_job_target t job_id generation in
  let run_preparation =
    match held_authored_job_preparation t job with
    | Some _ as actual -> actual
    | None -> run_preparation
  in
  let%bind captured = Model_job_target.capture_source binding ~target ~limits in
  transition
    ?check_before_commit:(held_startup_effect t run_preparation)
    ?run_preparation
    t
    ~delta:(Session_delta.Model_job_target_captured captured)
    ~payloads:[]
  |> Result.map ~f:ignore
;;

let capture_recipe_target
      ?run_preparation
      ?check_before_commit
      t
      job_id
      generation
      attempt
      target
      limits
  =
  let open Result.Let_syntax in
  let%bind job, binding = find_model_job_target t job_id generation in
  let%bind () =
    match job.status with
    | Running when Int.equal job.attempt attempt -> Ok ()
    | Running
    | Queued
    | Waiting_permission _
    | Waiting_completion _
    | Succeeded
    | Failed _
    | Cancelled
    | Interrupted _ ->
      Error (error Conflict "recipe capture is not owned by this running attempt")
  in
  let authored_preparation = held_authored_job_preparation t job in
  let run_preparation = Option.first_some authored_preparation run_preparation in
  let check_before_commit =
    match authored_preparation with
    | Some _ -> held_startup_effect t authored_preparation
    | None -> check_before_commit
  in
  let%bind captured = Model_job_target.capture_recipe binding ~target ~limits in
  (match goal_runtime_job t job with
   | Some scope ->
     goal_runtime_transition
       ~check_before_commit:(fun () ->
         check_runtime_construction_effect (Existing_goal scope.continuation))
       t
       scope
       ~delta:(Session_delta.Model_job_recipe_target_captured captured)
       ~payloads:[]
   | None ->
     transition
       ?check_before_commit
       ?run_preparation
       t
       ~delta:(Session_delta.Model_job_recipe_target_captured captured)
       ~payloads:[])
  |> Result.map ~f:ignore
;;

let job_with_progress t (job : Agent_protocol.Job.t) =
  let progress =
    List.find_map t.job_scopes ~f:(fun scope ->
      match
        scope.active
        && (not scope.cancel_requested)
        && Agent_protocol.Id.Job.equal scope.job.id job.id
        && Int.equal scope.job.generation job.generation
        && Int.equal scope.job.attempt job.attempt
      with
      | true -> Job_progress_buffer.snapshot scope.progress
      | false -> None)
  in
  { job with progress }
;;

let publish_job_progress_internal t id progress =
  match
    List.find t.invocation_executions ~f:(fun execution ->
      execution.accepts_children
      && Agent_protocol.Id.Invocation.equal execution.dispatched.context.id id)
  with
  | None -> ()
  | Some execution ->
    let scope =
      match execution.owner with
      | Background_job scope -> Some scope
      | Invocation_moderator borrow -> borrow.job_scope
      | Event_moderator borrow -> borrow.job_scope
      | Foreground _ -> None
    in
    Option.iter scope ~f:(fun scope ->
      match job_scope_can_execute t scope with
      | Ok () -> Job_progress_buffer.update scope.progress progress
      | Error _ -> ())
;;

let validate_job_generation t (job : Agent_protocol.Job.t) generation =
  if job.generation <> generation || t.state.identity.generation <> generation
  then Error (error Conflict "job belongs to a stale session generation")
  else Ok ()
;;

let install_held_authored_fact
      ?job_custody
      ?completion_sample
      t
      (scope : Held_authored_start.t)
      ~delta
      ~payloads
  =
  let open Result.Let_syntax in
  let revision = t.state.counters.revision in
  let basis () =
    if
      phys_equal scope.issuing_actor t.inference_owner_identity
      && Option.exists t.held_authored_start ~f:(phys_equal scope)
    then Ok ()
    else Error (error Conflict "held factual owner was displaced")
  in
  let%bind () = basis () in
  let run_preparation = held_authored_factual_preparation t scope in
  let completion_sample = producer_completion_sample ?completion_sample t ~delta in
  let%bind candidate = prepare_transition ?completion_sample t ~delta ~payloads in
  let%bind held_authored_callback_acknowledgement =
    Held_authored_callback_acknowledgement.prepare t scope ~candidate
  in
  let%map () =
    install
      ?held_authored_callback_acknowledgement
      ?run_preparation
      ?job_custody
      ?completion_sample
      ~check_before_commit:(fun () ->
        let%bind () = basis () in
        if Int64.equal revision t.state.counters.revision
        then Ok ()
        else Error (error Conflict "held factual writer basis changed"))
      t
      candidate
  in
  Agent_protocol.Session.(Session_state.summary t.state)
;;

let cancelled_subscription_timers t subscriptions =
  let timer_ids =
    List.filter_map subscriptions ~f:(fun next ->
      match
        next.Agent_protocol.Subscription.result, lookup_subscription t next.context.id
      with
      | Some _, Some previous -> previous.timer_id
      | _ -> None)
    |> Hash_set.of_list (module Agent_protocol.Id.Schedule)
  in
  List.filter_map t.state.schedules ~f:(fun schedule ->
    match Hash_set.mem timer_ids schedule.id, schedule.status with
    | true, (Agent_protocol.Schedule.Scheduled | Delivering) ->
      Some { schedule with status = Agent_protocol.Schedule.Cancelled }
    | _ -> None)
;;

module Constructor_job_control = struct
  module Data = Constructor_model_data
  module Custody = Constructor_model_custody

  type actor = t

  let selected_job = function
    | Data.Cancel_queued { queued; _ } -> queued
    | Complete_model { running; _ } | Interrupt_running { running; _ } -> running
  ;;

  let capture (t : actor) ~(previous : Agent_protocol.Job.t) =
    let open Result.Let_syntax in
    let call =
      Option.bind t.constructor_models ~f:(fun group ->
        List.find group.calls ~f:(fun call ->
          let expected =
            match call.Data.phase with
            | Admitted job | Claimed job -> Some job
            | Selected selection | Terminal_attempt { selection; _ } ->
              Some (selected_job selection)
            | Cancel_attempt plan -> Some plan.cancelled
            | Admission_attempt _ | Claim_attempt _ | Joined _ | Abandoned -> None
          in
          Option.exists expected ~f:(fun expected ->
            Agent_protocol.Id.Job.equal expected.id previous.id
            && Int.equal expected.generation previous.generation
            && Int.equal expected.attempt previous.attempt)))
    in
    match call with
    | None -> Ok None
    | Some call ->
      let%bind () = Custody.check_call t call in
      let%bind () = Custody.before_other_writer t call in
      let%bind prior =
        match call.phase with
        | Admitted queued -> Ok (Data.Was_admitted queued)
        | Claimed running -> Ok (Data.Was_claimed running)
        | Selected selection -> Ok (Data.Was_selected selection)
        | Terminal_attempt plan when Custody.no_writer plan.canonical ->
          Job_custody.Update.discard plan.canonical.job_custody;
          call.phase <- Selected plan.selection;
          Ok (Data.Was_selected plan.selection)
        | Terminal_attempt plan -> Custody.unresolved plan.canonical
        | Cancel_attempt plan -> Custody.unresolved plan.canonical
        | Admission_attempt _ | Claim_attempt _ | Joined _ | Abandoned ->
          Error (error Conflict "constructor cancellation has no actual active producer")
      in
      let expected =
        match prior with
        | Was_admitted job | Was_claimed job -> job
        | Was_selected selection -> selected_job selection
      in
      if
        Jsonaf.exactly_equal
          (Agent_protocol.Job.to_json expected)
          (Agent_protocol.Job.to_json previous)
      then Ok (Some (call, prior))
      else Error (error Conflict "constructor cancellation occurrence changed")
  ;;

  let install
        ?run_preparation
        ?completion_sample
        ?check_before_commit
        (t : actor)
        ~(call : Data.call)
        ~(prior : Data.control_prior)
        ~(previous : Agent_protocol.Job.t)
        ~(cancelled : Agent_protocol.Job.t)
        ~job_custody
        ~delta
        ~payloads
    =
    let open Result.Let_syntax in
    let retained = ref None in
    Exn.protect
      ~finally:(fun () ->
        match !retained with
        | None -> Job_custody.Update.discard job_custody
        | Some plan ->
          (match call.Data.phase with
           | Cancel_attempt actual
             when phys_equal actual plan && Custody.no_writer plan.canonical ->
             Job_custody.Update.discard job_custody;
             Custody.restore_control call plan
           | Admission_attempt _
           | Admitted _
           | Claim_attempt _
           | Claimed _
           | Selected _
           | Terminal_attempt _
           | Cancel_attempt _
           | Joined _
           | Abandoned -> ()))
      ~f:(fun () ->
        let%bind () = Custody.check_call t call in
        let scope = call.Data.group.scope in
        let%bind () = validate_initialization_owner t scope in
        let%bind () =
          validate_initialization_projection
            (Initialization_scope.Acknowledged.apply scope.acknowledged scope.expected)
            t.state
        in
        let%bind current = find_job t previous.Agent_protocol.Job.id in
        let%bind () =
          if
            Jsonaf.exactly_equal
              (Agent_protocol.Job.to_json previous)
              (Agent_protocol.Job.to_json current)
            && Agent_protocol.Job.equal_delivery cancelled.delivery Not_required
            &&
            match cancelled.status with
            | Cancelled -> true
            | Queued
            | Running
            | Waiting_permission _
            | Waiting_completion _
            | Succeeded
            | Failed _
            | Interrupted _ -> false
          then Ok ()
          else
            Error
              (error Conflict "constructor control did not select actual cancellation")
        in
        let completion_sample = producer_completion_sample ?completion_sample t ~delta in
        let%bind candidate =
          prepare_transition ?run_preparation ?completion_sample t ~delta ~payloads
        in
        let acknowledgement =
          Initialization_scope.Acknowledgement.prepare scope candidate.state
        in
        (* The same Job/Run candidate may factually settle its Goal. Record only
           that selected catalog at its ACK; the old basis stays strict. *)
        let acknowledgement =
          { acknowledgement with
            incoming =
              { acknowledgement.incoming with
                goal_catalog = candidate.state.goal_catalog
              }
          }
        in
        let%bind callback_advance =
          Callback_retirement.Constructor_job_acknowledgement.prepare
            t
            ~acknowledgement
            ~candidate
        in
        let canonical = Custody.canonical t ~candidate ~job_custody ~acknowledgement in
        let plan = Data.{ prior; cancelled; canonical; callback_advance } in
        call.phase <- Cancel_attempt plan;
        retained := Some plan;
        let check () =
          let%bind () =
            Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check ->
              check ())
          in
          let%bind () = Custody.check_canonical t call canonical in
          let%bind () = Custody.before_other_writer t call in
          let%bind () =
            match call.phase with
            | Cancel_attempt actual when phys_equal actual plan -> Ok ()
            | Admission_attempt _
            | Admitted _
            | Claim_attempt _
            | Claimed _
            | Selected _
            | Terminal_attempt _
            | Cancel_attempt _
            | Joined _
            | Abandoned ->
              Error (error Conflict "constructor cancellation plan changed before writer")
          in
          Option.value_map callback_advance ~default:(Ok ()) ~f:(fun advance ->
            Callback_retirement.Constructor_job_acknowledgement.check
              advance
              ~actor:t
              ~candidate)
        in
        Custody.perform canonical (fun () ->
          let%map () =
            install
              ~constructor_job_control:(call, plan)
              ~initialization_acknowledgement:acknowledgement
              ~check_before_commit:check
              ?run_preparation
              ?completion_sample
              ~job_custody
              t
              candidate
          in
          Session_state.summary t.state))
  ;;
end

let update_jobs
      ?constructor_cancel
      ?authored_scope
      ?check_before_commit
      ?initialization_scope
      ?constructor_call
      ?completion_sample
      ?run_preparation
      ?job_custody
      ?(subscriptions = [])
      ?(run_deltas = [])
      t
      jobs
  =
  let cancelled_timers = cancelled_subscription_timers t subscriptions in
  let cancelled =
    List.filter jobs ~f:(fun job ->
      match job.Agent_protocol.Job.status with
      | Cancelled | Interrupted _ -> true
      | Queued
      | Running
      | Waiting_permission _
      | Waiting_completion _
      | Succeeded
      | Failed _ -> false)
  in
  let owns (scope : job_scope) =
    List.exists cancelled ~f:(fun job ->
      Agent_protocol.Id.Job.equal scope.job.id job.Agent_protocol.Job.id
      && Int.equal scope.job.generation job.generation
      && Int.equal scope.job.attempt job.attempt)
  in
  let children =
    List.filter t.invocation_executions ~f:(fun execution ->
      List.exists t.job_scopes ~f:(fun scope ->
        job_execution_owned_by scope execution && owns scope))
  in
  let permissions, deltas, payloads =
    cleanup_invocation_permissions
      t
      (List.map children ~f:(fun child -> child.dispatched.context.id)
       @
       match t.moderator_borrow with
       | Some borrow when Option.exists borrow.job_scope ~f:owns ->
         [ borrow.invocation.context.id ]
       | _ -> [])
  in
  let open Result.Let_syntax in
  let delta =
    Session_delta.Batch
      (List.map jobs ~f:(fun job -> Session_delta.Job_changed job)
       @ List.map subscriptions ~f:(fun value -> Session_delta.Subscription_changed value)
       @ List.map cancelled_timers ~f:(fun value -> Session_delta.Schedule_changed value)
       @ deltas
       @ run_deltas)
  in
  let payloads =
    List.map jobs ~f:(fun job ->
      Agent_protocol.Event.Durable.Payload.Job_state_changed job)
    @ payloads
    @ List.map cancelled_timers ~f:(fun schedule ->
      Agent_protocol.Event.Durable.Payload.Schedule_cancelled schedule)
  in
  let%map session =
    match authored_scope, initialization_scope with
    | Some scope, None ->
      install_held_authored_fact ?job_custody ?completion_sample t scope ~delta ~payloads
    | Some _, Some _ -> Error (error Conflict "Job result has two startup owners")
    | None, None
      when List.exists jobs ~f:(fun job -> Option.is_some (goal_runtime_job t job)) ->
      let scopes = List.filter_map jobs ~f:(goal_runtime_job t) in
      let scope = List.hd_exn scopes in
      if List.for_all scopes ~f:(phys_equal scope)
      then
        goal_runtime_transition
          ?job_custody
          ?completion_sample
          ?check_before_commit
          t
          scope
          ~delta
          ~payloads
      else Error (error Conflict "Job ACK has two different runtime owners")
    | None, None ->
      let constructor_control =
        Option.bind constructor_cancel ~f:(fun (previous, cancelled, captured) ->
          Option.map captured ~f:(fun (call, prior) -> call, prior, previous, cancelled))
      in
      (match constructor_control, job_custody with
       | Some (call, prior, previous, cancelled), Some job_custody ->
         Constructor_job_control.install
           ?check_before_commit
           ?run_preparation
           ?completion_sample
           t
           ~call
           ~prior
           ~previous
           ~cancelled
           ~job_custody
           ~delta
           ~payloads
       | None, _ ->
         transition
           ?check_before_commit
           ?run_preparation
           ?job_custody
           ?completion_sample
           t
           ~delta
           ~payloads
       | Some _, None ->
         Error (error Conflict "constructor cancellation has no actual Job custody plan"))
    | None, Some scope ->
      (* Only actual owned initialization Model completion supplies this scope.
         Its immutable control projection remains strict; acknowledging a result
         does not renew original authority for subsequent provider work. *)
      let retained = ref None in
      Exn.protect
        ~finally:(fun () ->
          match !retained with
          | None -> Option.iter job_custody ~f:Job_custody.Update.discard
          | Some (call, queued, canonical) ->
            (match call.Constructor_model_data.phase with
             | Claim_attempt _ when Constructor_model_custody.no_writer canonical ->
               Job_custody.Update.discard canonical.job_custody;
               call.phase <- Admitted queued
             | Admission_attempt _
             | Admitted _
             | Claim_attempt _
             | Claimed _
             | Selected _
             | Terminal_attempt _
             | Cancel_attempt _
             | Joined _
             | Abandoned -> ()))
        ~f:(fun () ->
          let revision = t.state.counters.revision in
          let check_basis () =
            let%bind () = validate_initialization_owner t scope in
            let%bind () =
              match t.initialization_scope with
              | Some active when phys_equal active scope -> Ok ()
              | Some _ | None ->
                Error (error Conflict "initialization Model owner retired")
            in
            let%bind () =
              validate_initialization_basis
                ~scope
                t
                ~purpose:scope.purpose
                (Initialization_scope.Acknowledged.apply
                   scope.acknowledged
                   scope.expected)
            in
            Option.value_map
              (Initialization_scope.preparation_owner scope)
              ~default:(Ok ())
              ~f:(fun preparation ->
                match t.run_preparation with
                | Some active when Preparation_owner.same active preparation ->
                  Preparation_owner.check_basis
                    preparation
                    ~owner:t.run_preparation_owner
                    ~state:t.state
                | Some _ | None ->
                  Error (error Conflict "initialization preparation owner retired"))
          in
          let%bind () = check_basis () in
          let completion_sample =
            producer_completion_sample ?completion_sample t ~delta
          in
          let%bind prepared = prepare_transition ?completion_sample t ~delta ~payloads in
          let acknowledgement =
            Initialization_scope.Acknowledgement.prepare scope prepared.state
          in
          let positive_check = check_before_commit in
          let check_before_commit () =
            let%bind () =
              Option.value_map positive_check ~default:(Ok ()) ~f:(fun check -> check ())
            in
            let%bind () = check_basis () in
            let%bind () =
              Initialization_scope.Acknowledgement.check_basis acknowledgement
            in
            if Int64.equal revision t.state.counters.revision
            then Ok ()
            else Error (error Conflict "initialization Model completion basis changed")
          in
          let%bind () =
            match constructor_call with
            | None ->
              install
                ~initialization_acknowledgement:acknowledgement
                ~check_before_commit
                ?run_preparation
                ?job_custody
                ?completion_sample
                t
                prepared
            | Some call ->
              let%bind () = Constructor_model_custody.check_call t call in
              let%bind () = Constructor_model_custody.before_other_writer t call in
              let%bind queued, running, custody =
                match call.Constructor_model_data.phase, jobs, job_custody with
                | Admitted queued, [ running ], Some custody
                  when phys_equal call.group.scope scope -> Ok (queued, running, custody)
                | ( ( Admission_attempt _
                    | Admitted _
                    | Claim_attempt _
                    | Claimed _
                    | Selected _
                    | Terminal_attempt _
                    | Cancel_attempt _
                    | Joined _
                    | Abandoned )
                  , _
                  , _ ) ->
                  Error
                    (error Conflict "constructor Model claim has another actual producer")
              in
              let canonical =
                Constructor_model_custody.canonical
                  t
                  ~candidate:prepared
                  ~job_custody:custody
                  ~acknowledgement
              in
              call.phase <- Claim_attempt { queued; running; canonical };
              retained := Some (call, queued, canonical);
              Constructor_model_custody.perform canonical (fun () ->
                let%bind () = check_before_commit () in
                let%bind () =
                  Constructor_model_custody.check_canonical t call canonical
                in
                let%bind completion_plan =
                  prepare_completion_plan t prepared completion_sample
                in
                let%bind () =
                  persist_transition
                    ~commit_observation:
                      (Session_commit_attempt.observation canonical.attempt)
                    ~check_before_commit
                    ?run_preparation
                    t
                    prepared
                in
                install_committed_transition
                  ~initialization_acknowledgement:acknowledgement
                  ?run_preparation
                  ~job_custody:custody
                  t
                  prepared;
                Constructor_model_custody.installed t call canonical;
                call.phase <- Claimed running;
                Option.iter
                  completion_plan
                  ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
                publish_committed_transition t prepared;
                Ok ())
          in
          Ok (Session_state.summary t.state))
  in
  cancel_job_scopes t cancelled;
  resolve_cleaned_permission_waiters t permissions;
  session
;;

let update_job ?run_preparation ?job_custody ?check_before_commit t job =
  update_jobs ?run_preparation ?job_custody ?check_before_commit t [ job ]
;;

let validate_new_job t (job : Agent_protocol.Job.t) =
  if not (Agent_protocol.Id.Session.equal job.session_id t.state.identity.session_id)
  then Error (error Invalid_request "job belongs to another session")
  else if not (Int.equal job.generation t.state.identity.generation)
  then Error (error Conflict "job belongs to a stale session generation")
  else if
    List.exists t.state.jobs ~f:(fun existing ->
      Agent_protocol.Id.Job.equal existing.id job.id)
  then Error (error Conflict "job ID is already present")
  else Ok ()
;;

let add_job ?run_preparation t (job : Agent_protocol.Job.t) =
  let open Result.Let_syntax in
  let%bind () = validate_new_job t job in
  let%map _ = update_job ?run_preparation t job in
  job
;;

let job_is_due t (job : Agent_protocol.Job.t) =
  Option.value_map job.next_run_at ~default:true ~f:(fun next_run_at ->
    Agent_protocol.Timestamp.compare next_run_at (t.services.now ()) <= 0)
;;

let retire_unauthorized_run_job t (job : Agent_protocol.Job.t) =
  let open Result.Let_syntax in
  match t.state.run_state with
  | None -> Ok false
  | Some original ->
    let%bind work = Run_job_occurrence.work job in
    let%bind index, retired =
      List.fold_result
        (Run_state.runs original)
        ~init:(original, false)
        ~f:(fun (index, retired) run ->
          if
            not
              (List.exists
                 run.Agent_protocol.Run.owned_work
                 ~f:(Agent_protocol.Run_work.equal work))
          then Ok (index, retired)
          else (
            match run.lifecycle with
            | Terminal _ ->
              Ok
                ( index
                , retired
                  || not
                       (List.exists
                          run.relinquished_work
                          ~f:(Agent_protocol.Run_work.equal work)) )
            | Admitted | Active | Waiting _ ->
              (match check_run_binding t run.id with
               | Ok () -> Ok (index, retired)
               | Error _ ->
                 let%map index =
                   Run_retirement.interrupt_run
                     index
                     ~run_id:run.id
                     ~session_revision:(Int64.succ t.state.counters.revision)
                     ~now:(t.services.now ())
                 in
                 index, true)))
    in
    if not retired
    then Ok false
    else (
      let now = t.services.now () in
      let job =
        { job with
          status = Cancelled
        ; result =
            background_terminal_result
              job
              (Cancelled "run authority retired before dispatch")
        ; completed_at = Some now
        }
      in
      let jobs =
        match job.delivery with
        | Pending ->
          (* Discarding delivery requires an already terminal Job. Preserve both
             ordered facts in one transaction with the actual Run retirement. *)
          [ job
          ; { job with delivery = Discarded { at = now; reason = Authority_changed } }
          ]
        | Not_required | Delivered _ | Discarded _ -> [ job ]
      in
      let%map _ =
        update_jobs t jobs ~run_deltas:[ Session_delta.Run_state_changed index ]
      in
      true)
;;

let goal_runtime_job_deferred t (job : Agent_protocol.Job.t) =
  (match job.status, job.delivery with
   | Queued, (Pending | Delivered _) -> true
   | _ -> false)
  && Option.exists (goal_runtime_job t job) ~f:(fun scope ->
    Result.is_ok (goal_runtime_scope_basis t scope))
;;

let goal_job_suspended t job =
  match Job_runtime_owner.selection t.state job with
  | Ok (Goal_execution_selection.Suspended_goal _) -> true
  | Ok Eligible | Error _ -> false
;;

let check_job_claim_selection t (previous : Agent_protocol.Job.t) =
  let open Result.Let_syntax in
  let%bind run = Job_runtime_owner.run_of_job t.state previous in
  let%bind () =
    Option.value_map run ~default:(Ok ()) ~f:(fun run -> check_run_binding t run.id)
  in
  (* Original authorization may yield. Read the exact occurrence and policy
     again before the claim writer; a late refusal is not passive suspension. *)
  let%bind current = find_job t previous.id in
  let%bind () =
    if
      Jsonaf.exactly_equal
        (Agent_protocol.Job.to_json current)
        (Agent_protocol.Job.to_json previous)
    then Ok ()
    else Error (error Conflict "Job changed before execution claim")
  in
  match Job_runtime_owner.selection t.state current with
  | Ok Goal_execution_selection.Eligible -> Ok ()
  | Ok (Suspended_goal _) ->
    Error (error Conflict "Goal was held before Job execution claim")
  | Error failure -> Error failure
;;

let claim_job
      ?(purpose = Job_claim_purpose.Execute)
      ?initialization_scope
      ?constructor_call
      ?run_preparation
      ?check_before_commit
      t
      job_id
      generation
  =
  let open Result.Let_syntax in
  let%bind job = find_job t job_id in
  let%bind () = validate_job_generation t job generation in
  if held_authored_job_deferred t job || goal_runtime_job_deferred t job
  then Ok None
  else (
    match purpose with
    | Retire_only
      when Option.is_some (held_authored_job t job)
           || Option.is_some (goal_runtime_job t job) ->
      (* A private constructor/callback still owns its real Jobs, including
         the interval between its own ACK and outside-mailbox refresh. *)
      Ok None
    | Retire_only ->
      (match job.status with
       | Queued when job_is_due t job ->
         let%map _ = retire_unauthorized_run_job t job in
         None
       | Queued
       | Running
       | Waiting_permission _
       | Waiting_completion _
       | Succeeded
       | Failed _
       | Cancelled
       | Interrupted _ -> Ok None)
    | Execute ->
      let authored_preparation = held_authored_job_preparation t job in
      let run_preparation = Option.first_some authored_preparation run_preparation in
      let check_before_commit =
        match goal_runtime_job t job with
        | Some scope ->
          Some
            (fun () ->
              check_runtime_construction_effect (Existing_goal scope.continuation))
        | None ->
          (match authored_preparation with
           | Some _ -> held_startup_effect t authored_preparation
           | None -> check_before_commit)
      in
      let%bind () =
        if Session_state.execution_migration_required t.state
        then
          Error
            (error Migration_required "job execution requires explicit runtime migration")
        else Ok ()
      in
      let%bind () =
        match
          List.exists t.job_scopes ~f:(fun scope ->
            Agent_protocol.Id.Job.equal scope.job.id job_id)
        with
        | false -> Ok ()
        | true -> Error (error Conflict "job's prior execution scope has not finished")
      in
      (match job.status with
       | Agent_protocol.Job.Queued when job_is_due t job ->
         let%bind () =
           match goal_runtime_job t job with
           | Some scope ->
             check_runtime_construction_effect (Existing_goal scope.continuation)
           | None -> require_selected_or_held_execution t run_preparation
         in
         let%bind retired = retire_unauthorized_run_job t job in
         if retired
         then Ok None
         else (
           let%bind selection = Job_runtime_owner.selection t.state job in
           match selection with
           | Suspended_goal _ -> Ok None
           | Eligible ->
             if job.attempt = Int.max_value
             then Error (error Invalid_state "job attempt counter overflow")
             else (
               let previous = job in
               let job =
                 { job with
                   status = Running
                 ; attempt = job.attempt + 1
                 ; started_at = Some (t.services.now ())
                 ; next_run_at = None
                 ; result = None
                 }
               in
               let%bind row = Job_custody.find t.job_agent_custody ~job:previous in
               let%bind () =
                 Option.value_map row ~default:(Ok ()) ~f:(fun row ->
                   let%bind () =
                     check_job_moderator_binding t (Job_custody.Row.binding row)
                   in
                   let%bind admission = Job_custody.Row.admission row in
                   check_agent_admission admission)
               in
               let%bind job_custody =
                 Job_custody.prepare_claim t.job_agent_custody ~previous ~claimed:job
               in
               let check_before_commit () =
                 let%bind () =
                   Option.value_map check_before_commit ~default:(Ok ()) ~f:(fun check ->
                     check ())
                 in
                 (* Policy callbacks above may yield. Repeat the exact queued
                    occurrence and current Goal selection at the real writer. *)
                 check_job_claim_selection t previous
               in
               let%map _ =
                 update_jobs
                   ?initialization_scope
                   ?constructor_call
                   ~check_before_commit
                   ?run_preparation
                   ~job_custody
                   t
                   [ job ]
               in
               Some job))
       | Queued -> Ok None
       | Running
       | Waiting_permission _
       | Waiting_completion _
       | Succeeded
       | Failed _
       | Cancelled
       | Interrupted _ -> Ok None))
;;

let job_failure message =
  Agent_protocol.Error.create Internal_error ~message ~retryable:false ()
;;

let retry_limits = function
  | Agent_protocol.Job.Never -> None
  | Safe_retry { max_attempts; backoff_ms } | Idempotent { max_attempts; backoff_ms; _ }
    -> Some (max_attempts, backoff_ms)
;;

let retry_result message = `Object [ "last_error", `String message ]

let retry_job (job : Agent_protocol.Job.t) ~now ~message ~backoff_ms =
  let%map.Result next_run_at = Agent_protocol.Timestamp.add_ms now backoff_ms in
  { job with
    status = Queued
  ; started_at = None
  ; next_run_at = Some next_run_at
  ; completed_at = None
  ; result = Some (retry_result message)
  }
;;

let terminal_job ?now t (job : Agent_protocol.Job.t) status result =
  let delivery =
    match job.delivery with
    | Agent_protocol.Job.Not_required -> Agent_protocol.Job.Not_required
    | Pending | Delivered _ -> Pending
    | Discarded _ as delivery -> delivery
  in
  let now = Option.value_or_thunk now ~default:t.services.now in
  { job with status; result; completed_at = Some now; delivery }
;;

let validate_job_dependency t job =
  Job_dependency.validate
    ~invocations:t.state.invocations
    ~events:t.state.moderator_executions
    ~jobs:t.state.jobs
    ~subscriptions:t.state.subscriptions
    job
;;

let retained_subscription t id =
  Result.of_option
    (lookup_subscription t id)
    ~error:(error Invalid_state "subscription dependency is missing")
;;

let cancelled_work_dependencies t (parent : Agent_protocol.Job.t) =
  let rec walk seen (job : Agent_protocol.Job.t) =
    let open Result.Let_syntax in
    match job.status with
    | Waiting_completion dependency ->
      let%bind () = validate_job_dependency t job in
      (match dependency.work with
       | Subscription id ->
         let%bind subscription = retained_subscription t id in
         (match subscription.result with
          | Some _ -> Ok ([], [])
          | None ->
            let%map terminal, _ =
              Agent_protocol.Subscription.finish
                subscription
                ~expected_epoch:subscription.epoch
                ~now:
                  (subscription_terminal_time
                     t
                     subscription
                     (Cancelled "owning job stopped waiting"))
                (Cancelled "owning job stopped waiting")
            in
            [], [ terminal ])
       | Job id ->
         let key = Agent_protocol.Id.Job.to_string id in
         (match Set.mem seen key with
          | true -> Error (error Invalid_state "job dependency cycle")
          | false ->
            let%bind child = find_job t id in
            let%bind terminal = Agent_protocol.Job.terminal_result child in
            (match terminal with
             | Some _ -> Ok ([], [])
             | None ->
               let%map rest, subscriptions = walk (Set.add seen key) child in
               ( terminal_job
                   t
                   child
                   Cancelled
                   (background_terminal_result
                      child
                      (Cancelled "owning job stopped waiting"))
                 :: rest
               , subscriptions ))))
    | _ -> Ok ([], [])
  in
  walk (String.Set.singleton (Agent_protocol.Id.Job.to_string parent.id)) parent
;;

let validate_job_attempt (job : Agent_protocol.Job.t) attempt =
  match Int.equal job.attempt attempt with
  | true -> Ok ()
  | false -> Error (error Conflict "job callback belongs to a stale execution attempt")
;;

let claim_job_scope t job_id generation attempt deadline =
  let open Result.Let_syntax in
  let%bind job = find_job t job_id in
  let%bind () =
    require_selected_or_held_execution t (held_authored_job_preparation t job)
  in
  let%bind () = validate_job_generation t job generation in
  let%bind () = validate_job_attempt job attempt in
  let%bind () =
    match
      ( job.status
      , List.exists t.job_scopes ~f:(fun scope ->
          Agent_protocol.Id.Job.equal scope.job.id job_id) )
    with
    | Running, false -> Ok ()
    | _ -> Error (error Conflict "job must be running without another execution owner")
  in
  let cancelled, cancel_signal = Eio.Promise.create () in
  let scope =
    { job
    ; progress = Job_progress_buffer.create ()
    ; deadline
    ; cancelled
    ; cancel_signal
    ; active = true
    ; cancel_requested = false
    ; unfinished_on_return = false
    ; authority_live = Atomic.make true
    ; cancel = None
    }
  in
  (* Validate before exposing the scope; undo the process-local reservation on
     rejection. No durable state or runnable invocation is produced here. *)
  t.job_scopes <- scope :: t.job_scopes;
  match job_scope_can_execute t scope with
  | Ok () ->
    exclude_effect_deferred t Ordinary_execution;
    Ok scope
  | Error failure ->
    t.job_scopes
    <- List.filter t.job_scopes ~f:(fun other -> not (phys_equal scope other));
    Error failure
;;

let claim_job_invocation t scope (invocation : Agent_protocol.Invocation.t) =
  let open Result.Let_syntax in
  let%bind () = job_scope_can_execute t scope in
  let%bind () =
    match
      Agent_protocol.Id.Session.equal scope.job.session_id invocation.context.session_id
      && Int.equal scope.job.generation invocation.context.generation
    with
    | true -> Ok ()
    | false ->
      Error (error Conflict "invocation belongs to another job session or generation")
  in
  let%bind () =
    match invocation.context.parent_job with
    | Some id
      when Agent_protocol.Id.Job.equal id scope.job.id
           && Agent_protocol.Invocation.equal_origin invocation.context.origin Script
           && Option.is_none invocation.context.parent_invocation
           && Option.is_none invocation.context.provider_call_id
           && Option.is_none invocation.context.call_entry_id
           && Option.is_none invocation.parent_event -> Ok ()
    | None -> active_script_parent t ~owns:(job_execution_owned_by scope) invocation
    | Some _ -> Error (error Conflict "invocation does not belong to this job scope")
  in
  let%bind () =
    match scope.deadline, invocation.context.deadline with
    | None, _ -> Ok ()
    | Some parent, Some child when Agent_protocol.Timestamp.compare child parent <= 0 ->
      Ok ()
    | _ -> Error (error Conflict "job invocation cannot extend its execution deadline")
  in
  let%bind () =
    match invocation.context.deadline with
    | Some deadline
      when Agent_protocol.Timestamp.compare (t.services.now ()) deadline >= 0 ->
      Error (error Conflict "job invocation deadline has elapsed")
    | _ -> Ok ()
  in
  let%bind origin =
    invocation_origin t invocation ~fallback:(fun () -> Ok scope.job.inference_origin)
  in
  let%bind boundary = policy_job_boundary t scope in
  let%bind invocation, admission, policy_source =
    invocation_admission_deltas t invocation ~origin ~boundary
  in
  let%bind dispatched = Agent_protocol.Invocation.dispatch invocation in
  let%bind _ =
    transition
      ?run_preparation:(held_authored_job_preparation t scope.job)
      ?check_before_commit:
        (held_startup_effect t (held_authored_job_preparation t scope.job))
      t
      ~delta:(Session_delta.Batch (admission @ [ Invocation_changed dispatched ]))
      ~payloads:[]
  in
  let execution =
    { owner = Background_job scope
    ; policy_source
    ; native_goal = None
    ; context_rollover_basis = None
    ; dispatched
    ; accepts_children = true
    ; authority_live = Atomic.make true
    }
  in
  t.invocation_executions <- execution :: t.invocation_executions;
  Ok execution
;;

let finish_job_scope t scope =
  let open Result.Let_syntax in
  let%bind () =
    match List.mem t.job_scopes scope ~equal:phys_equal with
    | true -> Ok ()
    | false -> Error (error Conflict "background execution scope has ended")
  in
  scope.active <- false;
  Atomic.set scope.authority_live false;
  scope.cancel <- None;
  let%bind () =
    match t.moderator_borrow with
    | Some borrow
      when borrow.callback_finished
           && Option.exists borrow.job_scope ~f:(phys_equal scope) ->
      finish_moderator_invocation
        t
        borrow
        (Some
           (Agent_protocol.Invocation.Cancelled
              "background scope ended before moderator cleanup committed"))
    | _ -> Ok ()
  in
  let%bind () =
    match t.queued_event_borrow with
    | Some borrow
      when (not borrow.callback_active)
           && Option.exists borrow.job_scope ~f:(phys_equal scope) ->
      Callback_retirement.finish t borrow Queued_callback_exit.Interrupted
    | _ -> Ok ()
  in
  let%bind () =
    match job_has_moderator t scope with
    | false -> Ok ()
    | true -> Error (error Conflict "background callback left an owned moderator running")
  in
  let children = List.filter t.invocation_executions ~f:(job_execution_owned_by scope) in
  let permissions, permission_deltas, payloads =
    cleanup_invocation_permissions
      t
      (List.map children ~f:(fun child -> child.dispatched.context.id))
  in
  let%bind deltas =
    List.map children ~f:(fun execution ->
      execution.accepts_children <- false;
      Atomic.set execution.authority_live false;
      abort_staged_work t ~owner:(Invocation execution.dispatched.context.id);
      Agent_protocol.Invocation.cancel
        execution.dispatched
        ~reason:"background scope exited before recording the invocation outcome"
      |> Result.map ~f:(fun invocation -> Session_delta.Invocation_changed invocation))
    |> Result.all
  in
  let%bind () =
    match deltas @ permission_deltas with
    | [] -> Ok ()
    | deltas ->
      transition t ~delta:(Session_delta.Batch deltas) ~payloads |> Result.map ~f:ignore
  in
  resolve_cleaned_permission_waiters t permissions;
  t.invocation_executions
  <- List.filter t.invocation_executions ~f:(fun execution ->
       not (job_execution_owned_by scope execution));
  t.job_scopes <- List.filter t.job_scopes ~f:(fun other -> not (phys_equal scope other));
  match scope.unfinished_on_return || not (List.is_empty children) with
  | false -> Ok ()
  | true -> Error (error Conflict "background callback left unfinished invocations")
;;

let running_job_for_completion t job_id generation attempt =
  let open Result.Let_syntax in
  let%bind job = find_job t job_id in
  let%bind () = validate_job_generation t job generation in
  let%bind () = validate_job_attempt job attempt in
  let%bind () =
    match
      List.exists t.job_scopes ~f:(fun scope ->
        Agent_protocol.Id.Job.equal scope.job.id job_id)
    with
    | false -> Ok ()
    | true -> Error (error Conflict "job execution scope still owns its invocations")
  in
  match job.status with
  | Agent_protocol.Job.Running -> Ok job
  | Queued | Waiting_permission _ | Waiting_completion _ ->
    Error (error Conflict "job is not running")
  | Succeeded | Failed _ | Cancelled | Interrupted _ ->
    Error (error Already_resolved "job is already terminal")
;;

let complete_job
      ?initialization_scope
      ?run_preparation
      t
      job_id
      generation
      attempt
      outcome
  =
  let open Result.Let_syntax in
  let%bind previous = running_job_for_completion t job_id generation attempt in
  let authored_scope = held_authored_job t previous in
  let now, completion_sample = completion_clock_pair t in
  let terminal, job, outcome =
    match outcome with
    | Runtime_builder.Model_succeeded result ->
      let terminal = terminal_job ~now t previous Succeeded (Some result) in
      terminal, terminal, Agent_protocol.Run_work.Terminal.Succeeded
    | Model_failed message ->
      let terminal = terminal_job ~now t previous (Failed (job_failure message)) None in
      let successor =
        match retry_limits previous.retry_policy with
        | Some (max_attempts, backoff_ms) when previous.attempt < max_attempts ->
          (match retry_job previous ~now ~message ~backoff_ms with
           | Ok queued -> queued
           (* Timestamp exhaustion is retry exhaustion, not a new failed effect. *)
           | Error _ -> terminal)
        | None | Some _ -> terminal
      in
      terminal, successor, Agent_protocol.Run_work.Terminal.Failed
  in
  let%bind run_deltas =
    Run_job_completion.prepare
      ?startup_run:(pending_held_startup_run t)
      t.state
      ~running:previous
      ~terminal
      ~successor:job
      ~outcome
      ~now
  in
  let%bind job_custody =
    match job.status with
    | Queued ->
      Result.map
        (Job_custody.prepare_retry t.job_agent_custody ~previous ~queued:job)
        ~f:Option.some
    | Succeeded | Failed _ | Cancelled | Interrupted _ ->
      Result.map (prepare_terminal_job_custody t [ job ]) ~f:Option.some
    | Running | Waiting_permission _ | Waiting_completion _ ->
      Error (error Invalid_state "completed Job retained an active state")
  in
  let%map _ =
    update_jobs
      ?authored_scope
      ?initialization_scope
      ?run_preparation
      ?job_custody
      ~completion_sample
      ~run_deltas
      t
      [ job ]
  in
  job
;;

(* These are actual actor-issued constructor owners, not identity-bearing DTOs.
   A preparation's genuine legacy None is an admission only while that exact
   preparation is current; missing historical Job inventory never enters here. *)
type constructor_job_owner =
  | Initialization_job of Initialization_scope.t
  | Run_constructor_job of Run_preparation.t

let check_constructor_job_owner t = function
  | Initialization_job scope ->
    let open Result.Let_syntax in
    let%bind () = validate_initialization_scope t scope in
    check_initialization_agent_actor scope
  | Run_constructor_job preparation -> check_run_preparation t preparation
;;

let add_constructor_job t owner (job : Agent_protocol.Job.t) =
  let open Result.Let_syntax in
  let%bind () = check_constructor_job_owner t owner in
  let%bind () = validate_new_job t job in
  let run_preparation, parent, temporary =
    match owner with
    | Initialization_job scope ->
      Initialization_scope.initial_preparation scope, scope.agent_admission, false
    | Run_constructor_job preparation ->
      ( Some preparation
      , create_agent_admission
          (Option.map
             (Run_preparation.original_actor preparation)
             ~f:create_agent_custody)
      , true )
  in
  Exn.protect
    ~finally:(fun () -> if temporary then retire_agent_admission parent)
    ~f:(fun () ->
      let%bind selection =
        match owner with
        | Initialization_job _ -> Ok None
        | Run_constructor_job preparation ->
          Result.map
            (Run_preparation.Constructor_jobs.prepare_add
               preparation
               ~owner:t.run_preparation_owner
               ~state:t.state
               ~job)
            ~f:Option.some
      in
      let%bind binding = job_moderator_binding t in
      let%bind job_custody =
        Job_custody.prepare_fresh
          t.job_agent_custody
          ~job
          ~binding
          ~parent
          ~policy_source:Unknown
      in
      let acknowledged = ref false in
      Exn.protect
        ~finally:(fun () ->
          if not !acknowledged then Job_custody.Update.discard job_custody)
        ~f:(fun () ->
          let%bind prepared =
            prepare_transition
              ?run_preparation
              t
              ~delta:(Session_delta.Job_changed job)
              ~payloads:[ Agent_protocol.Event.Durable.Payload.Job_state_changed job ]
          in
          let initialization_acknowledgement =
            match owner with
            | Initialization_job scope ->
              Some
                (Initialization_scope.Acknowledgement.prepare
                   ~jobs:(job.id :: scope.jobs)
                   scope
                   prepared.state)
            | Run_constructor_job _ -> None
          in
          Eio.Cancel.protect (fun () ->
            let%bind () = check_constructor_job_owner t owner in
            let%bind () = check_job_moderator_binding t binding in
            let%bind () =
              Option.value_map selection ~default:(Ok ()) ~f:(fun selection ->
                Run_preparation.Constructor_jobs.check_before_commit
                  selection
                  ~owner:t.run_preparation_owner
                  ~state:t.state)
            in
            let%bind () =
              Job_custody.Update.check_before_commit
                job_custody
                ~current:t.job_agent_custody
            in
            let check_before_commit () =
              let%bind () = check_constructor_job_owner t owner in
              let%bind () = check_job_moderator_binding t binding in
              let%bind () =
                Job_custody.Update.check_before_commit
                  job_custody
                  ~current:t.job_agent_custody
              in
              Option.value_map
                initialization_acknowledgement
                ~default:(Ok ())
                ~f:Initialization_scope.Acknowledgement.check_basis
            in
            let%bind () =
              persist_transition ?run_preparation ~check_before_commit t prepared
            in
            install_committed_transition
              ?run_preparation
              ~job_custody
              ?initialization_acknowledgement
              t
              prepared;
            (match owner with
             | Initialization_job _ -> ()
             | Run_constructor_job _ ->
               Option.iter selection ~f:Run_preparation.Constructor_jobs.acknowledge);
            acknowledged := true;
            publish_committed_transition t prepared;
            Ok job)))
;;

let add_initialization_model_job t scope (job : Agent_protocol.Job.t) =
  let open Result.Let_syntax in
  let%bind () =
    match job.kind, job.status with
    | Model_call, Queued when Int.equal job.attempt 0 -> Ok ()
    | _ ->
      Error (error Invalid_request "initialization requires a fresh queued model job")
  in
  add_constructor_job t (Initialization_job scope) job
;;

let start_initialization_model_job t scope (job : Agent_protocol.Job.t) =
  let open Result.Let_syntax in
  let%bind () =
    match job.delivery with
    | Not_required when job_is_due t job -> Ok ()
    | Not_required | Pending | Delivered _ | Discarded _ ->
      Error
        (error
           Invalid_request
           "synchronous initialization job must be immediate and not deliverable")
  in
  let%bind job = add_initialization_model_job t scope job in
  let%bind claimed =
    claim_job
      ~initialization_scope:scope
      ?run_preparation:(Initialization_scope.initial_preparation scope)
      t
      job.id
      job.generation
  in
  Result.of_option
    claimed
    ~error:(error Conflict "initialization job could not be claimed")
;;

let claim_initialization_model_job ?constructor_call t scope job_id generation =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_scope t scope in
  let%bind job = find_job t job_id in
  let%bind () = validate_job_generation t job generation in
  let%bind () =
    if
      List.mem scope.Initialization_scope.jobs job_id ~equal:Agent_protocol.Id.Job.equal
      && Agent_protocol.Job.equal_kind job.kind Model_call
      && (match job.status with
          | Queued -> true
          | _ -> false)
      && Agent_protocol.Job.equal_delivery job.delivery Not_required
    then Ok ()
    else Error (error Permission_denied "initializer does not own this queued model call")
  in
  let%bind () = check_initialization_agent_actor scope in
  let%bind claimed =
    claim_job
      ~initialization_scope:scope
      ?constructor_call
      ?run_preparation:(Initialization_scope.initial_preparation scope)
      ?check_before_commit:
        (match Initialization_scope.construction scope with
         | Some
             ((Runtime_construction.Existing_goal _ | Delegated_load _) as construction)
           -> Some (fun () -> check_runtime_construction_effect construction)
         | Some (Initial _) | None ->
           held_startup_effect t (Initialization_scope.initial_preparation scope))
      t
      job_id
      generation
  in
  Result.of_option
    claimed
    ~error:(error Conflict "initializer model call could not be claimed")
;;

let initialization_model_job_is_owned t scope job_id generation attempt =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_owner t scope in
  match validate_initialization_scope_basis t scope with
  | Error _ -> Ok false
  | Ok () ->
    Ok
      (List.mem scope.Initialization_scope.jobs job_id ~equal:Agent_protocol.Id.Job.equal
       && List.exists t.state.jobs ~f:(fun job ->
         Agent_protocol.Id.Job.equal job.id job_id
         && Int.equal job.generation generation
         && Int.equal job.attempt attempt
         && Agent_protocol.Job.equal_kind job.kind Model_call
         &&
         match job.status with
         | Running -> true
         | Queued
         | Waiting_permission _
         | Waiting_completion _
         | Succeeded
         | Failed _
         | Cancelled
         | Interrupted _ -> false))
;;

let initialization_model_job_is_current t scope job_id generation attempt =
  let open Result.Let_syntax in
  let%map owned = initialization_model_job_is_owned t scope job_id generation attempt in
  owned
  && Result.is_ok (validate_initialization_scope t scope)
  && Result.is_ok (check_initialization_agent_actor scope)
;;

(* Cancellation observes an already claimed physical Job, not admission of
   another inference. Its own graph ACK may advance Store custody concurrently;
   only the actual effect/checkpoint ports consume a fresh Store observation. *)
let initialization_model_job_is_running t scope job_id generation attempt =
  match Initialization_scope.construction scope with
  | Some (Runtime_construction.Existing_goal continuation) ->
    let open Result.Let_syntax in
    let%bind owned =
      initialization_model_job_is_owned t scope job_id generation attempt
    in
    if not owned
    then Ok false
    else (
      let preparation = continuation.Goal_continuation.binding.preparation in
      let current () =
        let%bind () = validate_initialization_scope_basis t scope in
        let%bind () = preparation.registered_policy () in
        let%bind () =
          Goal_activation_policy.check_admitted_policy preparation.policy ~state:t.state
        in
        let%bind () =
          Goal_activation_policy.check_deadline
            preparation.policy
            ~state:t.state
            ~now:(t.services.now ())
        in
        let%bind () = preparation.registered_authority () in
        let%bind () = check_initialization_agent_actor scope in
        validate_initialization_scope_basis t scope
      in
      match current () with
      | Error _ -> Ok false
      | Ok () -> initialization_model_job_is_owned t scope job_id generation attempt)
  | Some (Runtime_construction.Delegated_load load) ->
    let open Result.Let_syntax in
    let%bind owned =
      initialization_model_job_is_owned t scope job_id generation attempt
    in
    if not owned
    then Ok false
    else (
      let current () =
        let%bind () = validate_initialization_scope_basis t scope in
        let%bind () = load.preparation.current () in
        let%bind () = check_initialization_agent_actor scope in
        validate_initialization_scope_basis t scope
      in
      match current () with
      | Error _ -> Ok false
      | Ok () -> initialization_model_job_is_owned t scope job_id generation attempt)
  | Some (Initial _) | None ->
    initialization_model_job_is_current t scope job_id generation attempt
;;

let validate_initialization_model_job t scope job_id generation attempt =
  let open Result.Let_syntax in
  let%bind active =
    initialization_model_job_is_current t scope job_id generation attempt
  in
  if active
  then Ok ()
  else Error (error Conflict "initialization does not own this running model attempt")
;;

let inference_run_binding_current t (run : Agent_protocol.Run.t) =
  let open Result.Let_syntax in
  let%bind binding =
    Run_authorities.find t.run_authorities run.id
    |> Result.of_option ~error:(error Permission_denied "inference Run authority retired")
  in
  let%bind () = Run_admission.Scope.check_current (Run_authorities.scope binding) in
  let%bind index =
    t.state.run_state
    |> Result.of_option ~error:(error Invalid_state "inference Run index is absent")
  in
  let%bind installed =
    Run_source_installation.captured
      (Run_state.installation index)
      ~generation:t.state.identity.generation
  in
  let%bind observer = Moderator_checkpoint.observer t.state.moderator in
  if
    Agent_protocol.Run_source.equal installed run.source
    && Option.equal
         Agent_protocol.Invocation.equal_observer
         observer
         (Some installed.observer)
    && Agent_protocol.Id.Principal.equal
         run.principal_id
         (Run_admission.Scope.principal_id (Run_authorities.scope binding))
    &&
    match run.lifecycle with
    | Admitted | Active | Waiting _ -> true
    | Terminal _ -> false
  then Ok binding
  else Error (error Permission_denied "inference Run binding or installed source changed")
;;

type execution_origin_lookup =
  { job :
      Agent_protocol.Job.t -> (Agent_protocol.Run.t option, Agent_protocol.Error.t) result
  ; invocation :
      Agent_protocol.Invocation.t
      -> (Agent_protocol.Run.t option, Agent_protocol.Error.t) result
  ; event :
      Callback_scope.t -> (Agent_protocol.Run.t option, Agent_protocol.Error.t) result
  }

(* Immutable captured attribution never borrows the operation which drains it.
   The caller authenticates the exact Callback_scope independently. *)
let captured_callback_run t ~allow_unavailable (scope : Callback_scope.t) =
  let open Result.Let_syntax in
  match scope.origin with
  | None ->
    if allow_unavailable
    then Ok None
    else Error (error Permission_denied "callback inference origin is unavailable")
  | Some Unbound -> Ok None
  | Some (Run id) ->
    let%bind run =
      Option.bind t.state.run_state ~f:(fun index -> Run_state.find index id)
      |> Result.of_option ~error:(error Invalid_state "callback original Run is absent")
    in
    if
      Agent_protocol.Run_source.equal run.source scope.source
      && Agent_protocol.Id.Session.equal
           (Agent_protocol.Session_ref.session_id run.session)
           t.state.identity.session_id
    then Ok (Some run)
    else Error (error Permission_denied "callback original Run source or session changed")
;;

let execution_basis ?admitted t (origins : execution_origin_lookup) execution =
  let open Result.Let_syntax in
  let%bind () = check_execution_descendant t execution in
  let initialization_current scope =
    match admitted with
    | Some selected ->
      (match selected.Admitted_inference.startup with
       | Initialization (actual, Existing_goal continuation) when phys_equal actual scope
         ->
         let%bind () = validate_initialization_scope_basis t scope in
         continuation.binding.preparation.registered_basis ()
       | Initialization (actual, Delegated_load load) when phys_equal actual scope ->
         let%bind () = validate_initialization_scope_basis t scope in
         load.preparation.current ()
       | Ordinary | Initialization _ | Input _ | Authored _ | Goal_runtime _ ->
         validate_initialization_scope_current t scope)
    | None -> validate_initialization_scope_current t scope
  in
  let registered_constructor scope =
    match admitted with
    | Some
        { Admitted_inference.startup =
            Initialization (actual, (Existing_goal _ | Delegated_load _))
        ; _
        }
      when phys_equal actual scope -> true
    | Some _ | None -> false
  in
  let event_current borrow =
    match admitted, goal_runtime_of_borrow borrow with
    | Some { Admitted_inference.startup = Goal_runtime actual; _ }, Some scope
      when phys_equal actual scope ->
      let%bind () = goal_runtime_event_basis t borrow scope in
      scope.continuation.binding.preparation.registered_basis ()
    | _ ->
      (match constructor_scope_of_borrow t borrow with
       | Some scope when registered_constructor scope ->
         let%bind () = initialization_current scope in
         constructor_event_current t borrow scope
       | Some _ | None -> queued_event_inference_current t borrow)
  in
  let callback_current (scope : Callback_scope.t) =
    match scope.constructor_scope with
    | Some constructor when registered_constructor constructor ->
      let%bind () = event_current scope.borrow in
      check_callback_scope_current t scope
    | Some _ | None -> callback_inference_actor t ~scope |> Result.map ~f:ignore
  in
  let checked_admission admission =
    let%bind admission = admission in
    Option.value_map admission ~default:(Ok ()) ~f:check_agent_admission
  in
  let operation id generation =
    let%bind work = Agent_protocol.Run_work.create ~key:(Operation id) ~generation in
    Goal_work_attribution.run_of_work t.state work
  in
  let basis ?operation_id ?invocation_id ?preparation run =
    let%map attribution =
      match run with
      | None -> Ok None
      | Some run -> Goal_work_attribution.of_run t.state run
    in
    { run; attribution; operation_id; invocation_id; preparation }
  in
  let job scope =
    let%bind () = job_scope_can_execute t scope in
    let%bind () = checked_admission (job_agent_admission t scope) in
    let%bind run = origins.job scope.job in
    let%map () =
      match run with
      | None -> Ok ()
      | Some run ->
        let%bind work = Run_job_occurrence.work scope.job in
        let live =
          match run.Agent_protocol.Run.lifecycle with
          | Admitted | Active | Waiting _ -> true
          | Terminal _ -> false
        in
        if
          live
          && List.mem run.owned_work work ~equal:Agent_protocol.Run_work.equal
          && (not
                (List.mem run.relinquished_work work ~equal:Agent_protocol.Run_work.equal))
          && not
               (List.exists run.terminal_work ~f:(fun proof ->
                  Agent_protocol.Run_work.equal proof.work work))
        then Ok ()
        else Error (error Permission_denied "Run does not own this current Job attempt")
    in
    run
  in
  let moderator (borrow : moderator_borrow) =
    let%bind () = validate_moderator_borrow t borrow in
    let%bind () =
      if
        Atomic.get borrow.authority_live
        && borrow.accepts_children
        && not (borrow.callback_finished || borrow.committed || borrow.cancel_requested)
      then Ok ()
      else Error (error Permission_denied "moderator inference owner expired")
    in
    let%bind () = checked_admission (moderator_agent_admission t borrow) in
    let%bind () =
      match borrow.job_scope, borrow.operation_id with
      | Some scope, None -> Result.map (job scope) ~f:ignore
      | None, Some id -> Result.map (running_operation t id) ~f:ignore
      | None, None -> Ok ()
      | Some _, Some _ ->
        Error (error Invalid_state "moderator inference has mixed owners")
    in
    (* The checks above authenticate the physical callback. Attribution belongs
       to its original invocation even when a later operation drains it. *)
    let%bind run = origins.invocation borrow.invocation in
    basis
      ?operation_id:borrow.operation_id
      ~invocation_id:borrow.invocation.context.id
      run
  in
  let event (borrow : queued_event_borrow) =
    let%bind () = event_current borrow in
    let%bind () =
      if Atomic.get borrow.authority_live && Option.is_none borrow.retirement_reason
      then Ok ()
      else Error (error Permission_denied "event inference owner expired")
    in
    let%bind () = checked_admission (event_agent_admission t borrow) in
    let%bind run =
      match borrow.lifecycle_owner, t.legacy_callback_scope with
      | Some (Existing_goal_resume scope), _ ->
        let%map run = goal_runtime_run t scope in
        Some run
      | Some owner, _ ->
        let%map run = lifecycle_event_run t borrow owner in
        Some run
      | None, Some scope when phys_equal scope.borrow borrow ->
        let%bind () = callback_current scope in
        origins.event scope
      | None, (None | Some _) ->
        let%bind causal =
          Run_event_ancestry.find
            (Option.value_map t.state.run_state ~default:[] ~f:Run_state.runs)
            ~executing:borrow.receipt
        in
        let fallback () =
          match borrow.job_scope, borrow.receipt.context.operation_id with
          | Some scope, None -> job scope
          | None, Some id -> operation id borrow.receipt.context.generation
          | None, None ->
            (match borrow.run_actions with
             | None -> Run_event_scope.select t.state ~executing:borrow.receipt
             | Some owner ->
               Result.map
                 (Result.of_option
                    (Option.bind t.state.run_state ~f:(fun index ->
                       Run_state.find
                         index
                         (Run_scope.run_id (Run_action_service.scope owner))))
                    ~error:(error Invalid_state "callback Run is absent"))
                 ~f:Option.some)
          | Some _, Some _ ->
            Error (error Invalid_state "event inference has mixed owners")
        in
        let%bind run =
          match causal with
          | None -> fallback ()
          | Some original ->
            let%bind selected =
              Run_event_scope.select t.state ~executing:borrow.receipt
            in
            (match selected with
             | Some selected when Agent_protocol.Id.Run.equal original.id selected.id ->
               Ok (Some selected)
             | None | Some _ ->
               Error
                 (error Permission_denied "causal callback Run is no longer executable"))
        in
        Ok run
    in
    let preparation = event_run_preparation t borrow in
    basis ?operation_id:borrow.receipt.context.operation_id ?preparation run
  in
  let%bind result =
    match execution with
    | Inference_operation (expected, live) ->
      let%bind current = running_operation t expected.id in
      let%bind () =
        if
          Atomic.get live
          && Int.equal expected.generation current.generation
          && Agent_protocol.Operation.equal_kind expected.kind current.kind
        then Ok ()
        else Error (error Permission_denied "operation inference owner expired")
      in
      let%bind () = operation_agent_actor t expected.id |> Result.map ~f:ignore in
      let%bind run = operation current.id current.generation in
      basis ~operation_id:current.id run
    | Inference_invocation current ->
      let%bind _ = invocation_agent_actor t current current.dispatched in
      let%map parent =
        match current.owner with
        | Foreground id ->
          let%bind run = operation id current.dispatched.context.generation in
          basis ~operation_id:id run
        | Background_job scope ->
          let%bind run = job scope in
          basis
            ?preparation:
              (Option.bind
                 (held_authored_job t scope.job)
                 ~f:(held_authored_factual_preparation t))
            run
        | Invocation_moderator borrow -> moderator borrow
        | Event_moderator borrow -> event borrow
      in
      { parent with invocation_id = Some current.dispatched.context.id }
    | Inference_moderator borrow -> moderator borrow
    | Inference_event borrow -> event borrow
    | Inference_job scope ->
      let%bind run = job scope in
      basis
        ?preparation:
          (Option.bind
             (held_authored_job t scope.job)
             ~f:(held_authored_factual_preparation t))
        run
    | Inference_held_input scope ->
      let%bind () = Held_input_scope.parsing scope in
      let%bind () = input_scope_basis t scope in
      let%bind () =
        match admitted with
        | Some selected ->
          (match selected.Admitted_inference.startup with
           | Input actual when phys_equal actual scope -> Ok ()
           | Ordinary | Initialization _ | Input _ | Authored _ | Goal_runtime _ ->
             Error (error Conflict "admitted inference input owner changed"))
        | None -> check_held_effect scope.continuation
      in
      let activation = Admitted_activation.Continuation.target scope.continuation in
      let%bind run =
        Option.bind t.state.run_state ~f:(fun index ->
          Run_state.find index activation.run.id)
        |> Result.of_option ~error:(error Conflict "held input Run is absent")
      in
      basis ~preparation:activation.preparation (Some run)
    | Inference_initialization_job (scope, expected) ->
      let%bind () = initialization_current scope in
      let%bind () = check_initialization_agent_actor scope in
      let%bind () =
        if
          List.mem scope.jobs expected.id ~equal:Agent_protocol.Id.Job.equal
          && List.exists t.state.jobs ~f:(fun job ->
            Agent_protocol.Id.Job.equal job.id expected.id
            && Int.equal job.generation expected.generation
            && Int.equal job.attempt expected.attempt
            && Agent_protocol.Job.equal_kind job.kind Model_call
            && Jsonaf.exactly_equal job.payload expected.payload
            &&
            match job.status with
            | Running -> true
            | _ -> false)
        then Ok ()
        else
          Error
            (error
               Permission_denied
               "initializer no longer owns this current model attempt")
      in
      basis
        ?preparation:(Initialization_scope.initial_preparation scope)
        (match admitted with
         | Some
             { Admitted_inference.startup =
                 Initialization (actual, Existing_goal continuation)
             ; _
             }
           when phys_equal actual scope ->
           Option.bind t.state.run_state ~f:(fun index ->
             Run_state.find index continuation.binding.preparation.run.id)
         | Some _ | None -> initialization_held_run t scope)
    | Inference_initialization scope ->
      let%bind () = initialization_current scope in
      let%bind () = check_initialization_agent_actor scope in
      (* A future controller episode requires a genuine reservation. Existing
         initializer identity is retained; source or auth alone cannot invent it. *)
      basis
        ?preparation:(Initialization_scope.initial_preparation scope)
        (match admitted with
         | Some
             { Admitted_inference.startup =
                 Initialization (actual, Existing_goal continuation)
             ; _
             }
           when phys_equal actual scope ->
           Option.bind t.state.run_state ~f:(fun index ->
             Run_state.find index continuation.binding.preparation.run.id)
         | Some _ | None -> initialization_held_run t scope)
  in
  let%map () =
    match result.run with
    | None -> Ok ()
    | Some run -> inference_run_binding_current t run |> Result.map ~f:ignore
  in
  result
;;

let inference_execution_basis ?admitted t execution =
  execution_basis
    ?admitted
    t
    { job = Goal_work_attribution.run_of_job t.state
    ; invocation = Goal_work_attribution.run_of_invocation t.state
    ; event = captured_callback_run t ~allow_unavailable:false
    }
    execution
;;

(* Unavailable inference classification does not erase actual retained work.
   These lookups use original Job/Invocation ancestry, never the operation which
   happens to drain a callback. They are data lookup after physical admission;
   [execution_basis] and the final guard still check the live owner and authority. *)
let check_native_parent t = function
  | None -> Ok None
  | Some ({ run; work } : Goal_work_attribution.Retained_parent.t) ->
    let open Result.Let_syntax in
    let%bind _ = inference_run_binding_current t run in
    if
      List.mem run.owned_work work ~equal:Agent_protocol.Run_work.equal
      && (not (List.mem run.relinquished_work work ~equal:Agent_protocol.Run_work.equal))
      && not
           (List.exists run.terminal_work ~f:(fun terminal ->
              Agent_protocol.Run_work.equal terminal.work work))
    then Ok (Some (run, work))
    else Error (error Permission_denied "native child lost its actual Run parent")
;;

let native_job_parent t job =
  Goal_work_attribution.Retained_parent.of_job t.state job
  |> Result.bind ~f:(check_native_parent t)
;;

let native_event_parent t event =
  Goal_work_attribution.Retained_parent.of_event t.state event
  |> Result.bind ~f:(check_native_parent t)
;;

let native_invocation_parent t invocation =
  Goal_work_attribution.Retained_parent.of_invocation t.state invocation
  |> Result.bind ~f:(check_native_parent t)
;;

let native_execution_origins t : execution_origin_lookup =
  let open Result.Let_syntax in
  { job =
      (fun job ->
        match job.Agent_protocol.Job.inference_origin with
        | Some _ -> Goal_work_attribution.run_of_job t.state job
        | None ->
          let%map parent = native_job_parent t job in
          Option.map parent ~f:fst)
  ; invocation =
      (fun invocation ->
        match invocation.Agent_protocol.Invocation.inference_origin with
        | Some _ -> Goal_work_attribution.run_of_invocation t.state invocation
        | None ->
          let%map parent = native_invocation_parent t invocation in
          Option.map parent ~f:fst)
  ; event = captured_callback_run t ~allow_unavailable:true
  }
;;

type native_child_basis =
  { execution : inference_basis
  ; classification : Agent_protocol.Inference_origin.t option
  ; parent_work : Agent_protocol.Run_work.t option
  }

let native_child_basis_of_execution t execution (basis : inference_basis) =
  let open Result.Let_syntax in
  let%bind classification, original_parent =
    let invocation (invocation : Agent_protocol.Invocation.t) =
      let%map parent =
        match invocation.inference_origin with
        | Some (Run _) -> Ok None
        | None | Some Unbound -> native_invocation_parent t invocation
      in
      invocation.inference_origin, parent
    in
    match execution with
    | Inference_invocation execution -> invocation execution.dispatched
    | Inference_moderator borrow -> invocation borrow.invocation
    | Inference_job scope ->
      let%map parent = native_job_parent t scope.job in
      scope.job.inference_origin, parent
    | Inference_event borrow ->
      let%bind classification =
        match t.legacy_callback_scope with
        | Some scope when phys_equal scope.borrow borrow -> Ok scope.origin
        | None | Some _ -> event_inference_origin t borrow.receipt
      in
      let%map parent =
        match classification with
        | None -> native_event_parent t borrow.receipt
        | Some _ -> Ok None
      in
      classification, parent
    | Inference_held_input _
    | Inference_operation _
    | Inference_initialization _
    | Inference_initialization_job _ ->
      Ok
        ( Some
            (match basis.run with
             | None -> Agent_protocol.Inference_origin.Unbound
             | Some run -> Run run.id)
        , None )
  in
  let%bind () =
    match classification, basis.run, original_parent with
    | None, None, None | Some Unbound, None, None -> Ok ()
    | Some (Run id), Some run, _ when Agent_protocol.Id.Run.equal id run.id -> Ok ()
    | None, Some run, Some (parent, _) when Agent_protocol.Id.Run.equal run.id parent.id
      -> Ok ()
    | _ -> Error (error Permission_denied "native child origin and work owner disagree")
  in
  Ok
    { execution = basis; classification; parent_work = Option.map original_parent ~f:snd }
;;

let native_child_basis t execution =
  let%bind.Result basis = execution_basis t (native_execution_origins t) execution in
  native_child_basis_of_execution t execution basis
;;

type inference_currentness =
  { basis : inference_basis
  ; check_current : unit -> (unit, Agent_protocol.Error.t) result
  }

let authorize_inference_basis t ~read_current =
  let open Result.Let_syntax in
  let%bind basis = read_current () in
  let%bind binding =
    match basis.run with
    | None -> Ok None
    | Some run ->
      let%bind binding = inference_run_binding_current t run in
      let%map () =
        Run_admission.Scope.authorize (Run_authorities.scope binding) t.state
      in
      Some binding
  in
  let%bind () =
    match basis.preparation with
    | None -> Ok ()
    | Some preparation -> check_run_preparation t preparation
  in
  let check_current () =
    let%bind current = read_current () in
    let same_run left right =
      Agent_protocol.Id.Run.equal left.Agent_protocol.Run.id right.Agent_protocol.Run.id
      && Agent_protocol.Run_source.equal left.source right.source
      && Agent_protocol.Id.Principal.equal left.principal_id right.principal_id
      && Agent_protocol.Session_ref.equal left.session right.session
    in
    let same_attribution left right =
      Agent_protocol.Id.Goal.equal
        (Goal_work_attribution.goal_id left)
        (Goal_work_attribution.goal_id right)
      && Agent_protocol.Goal_episode.equal
           (Goal_work_attribution.episode left)
           (Goal_work_attribution.episode right)
    in
    if
      Option.equal same_run basis.run current.run
      && Option.equal same_attribution basis.attribution current.attribution
      &&
      match basis.run, binding with
      | None, None -> true
      | Some run, Some binding ->
        Run_authorities.is_current t.run_authorities binding ~run_id:run.id
      | None, Some _ | Some _, None -> false
    then Ok ()
    else
      Error
        (error
           Permission_denied
           "inference physical owner or immutable origin changed after refresh")
  in
  let%map () = check_current () in
  { basis; check_current }
;;

let authorized_inference_execution_basis ?admitted t execution =
  authorize_inference_basis t ~read_current:(fun () ->
    inference_execution_basis ?admitted t execution)
;;

type native_child_currentness =
  { selected : native_child_basis
  ; check_current : unit -> (unit, Agent_protocol.Error.t) result
  }

let authorize_native_child_basis t ~read_current =
  let open Result.Let_syntax in
  let%bind (selected : native_child_basis) = read_current () in
  let%bind current =
    authorize_inference_basis t ~read_current:(fun () ->
      let%map next = read_current () in
      next.execution)
  in
  let check_current () =
    let%bind () = current.check_current () in
    let%bind next = read_current () in
    if
      Option.equal
        Agent_protocol.Inference_origin.equal
        selected.classification
        next.classification
      && Option.equal Agent_protocol.Run_work.equal selected.parent_work next.parent_work
    then Ok ()
    else Error (error Permission_denied "native child classification or parent changed")
  in
  let%map () = check_current () in
  { selected; check_current }
;;

let authorized_native_child_basis t execution =
  authorize_native_child_basis t ~read_current:(fun () -> native_child_basis t execution)
;;

(* A returned native invocation may settle only its already selected child set.
   Its native callback epoch stays closed. The underlying physical parent and
   original custody must still be live; no fresh inference or selection uses this
   path. *)
let selected_invocation_basis t (execution : invocation_execution) =
  let open Result.Let_syntax in
  let%bind () =
    if List.exists t.invocation_executions ~f:(phys_equal execution)
    then Ok ()
    else Error (error Conflict "selected work lost its invocation owner")
  in
  let%bind admission = execution_agent_admission t execution in
  let%bind () = Option.value_map admission ~default:(Ok ()) ~f:check_agent_admission in
  let origins = native_execution_origins t in
  let%bind basis =
    match execution.owner with
    | Background_job scope -> execution_basis t origins (Inference_job scope)
    | Invocation_moderator borrow ->
      execution_basis t origins (Inference_moderator borrow)
    | Event_moderator borrow -> execution_basis t origins (Inference_event borrow)
    | Foreground id ->
      let%bind current = running_operation t id in
      let%bind _ = operation_agent_actor t id in
      let%bind work =
        Agent_protocol.Run_work.create ~key:(Operation id) ~generation:current.generation
      in
      let%bind run = Goal_work_attribution.run_of_work t.state work in
      let%bind attribution =
        match run with
        | None -> Ok None
        | Some run ->
          let%bind _ = inference_run_binding_current t run in
          Goal_work_attribution.of_run t.state run
      in
      Ok
        { run
        ; attribution
        ; operation_id = Some id
        ; invocation_id = Some execution.dispatched.context.id
        ; preparation = None
        }
  in
  native_child_basis_of_execution t (Inference_invocation execution) basis
;;

let background_inference_execution t = function
  | Agent_protocol.Job.Moderator_event id ->
    (match t.queued_event_borrow with
     | Some borrow
       when Agent_protocol.Id.Moderator_execution.equal borrow.receipt.context.id id ->
       Ok (Inference_event borrow)
     | Some _ | None -> Error (error Conflict "background event owner is unavailable"))
  | Invocation id ->
    (match
       List.find t.invocation_executions ~f:(fun execution ->
         Agent_protocol.Id.Invocation.equal execution.dispatched.context.id id)
     with
     | Some execution -> Ok (Inference_invocation execution)
     | None ->
       (match t.moderator_borrow with
        | Some borrow
          when Agent_protocol.Id.Invocation.equal borrow.invocation.context.id id ->
          Ok (Inference_moderator borrow)
        | Some _ | None ->
          Error (error Conflict "background invocation owner is unavailable")))
;;

let inference_origin (basis : inference_basis) =
  match basis.run with
  | None -> Agent_protocol.Job.Inference_origin.Unbound
  | Some run -> Run run.id
;;

type child_parent =
  | Parent_work of Agent_protocol.Run_work.t
  | Parent_event of queued_event_borrow
  | Parent_observation of moderator_borrow

let child_parent t execution =
  let operation id =
    let%bind.Result current = running_operation t id in
    Agent_protocol.Run_work.create ~key:(Operation id) ~generation:current.generation
    |> Result.map ~f:(fun work -> Parent_work work)
  in
  let job (scope : job_scope) =
    Run_job_occurrence.work scope.job |> Result.map ~f:(fun work -> Parent_work work)
  in
  let moderator (borrow : moderator_borrow) =
    match borrow.kind with
    | Observation -> Ok (Parent_observation borrow)
    | Invocation _ ->
      (match borrow.job_scope, borrow.operation_id with
       | Some scope, None -> job scope
       | None, Some id -> operation id
       | None, None | Some _, Some _ ->
         Error (error Invalid_state "Run child has no unique retained parent"))
  in
  match execution with
  | Inference_operation (operation_value, _) -> operation operation_value.id
  | Inference_job scope -> job scope
  | Inference_event borrow -> Ok (Parent_event borrow)
  | Inference_moderator borrow -> moderator borrow
  | Inference_invocation execution ->
    (match execution.owner with
     | Foreground id -> operation id
     | Background_job scope -> job scope
     | Invocation_moderator borrow -> moderator borrow
     | Event_moderator borrow -> Ok (Parent_event borrow))
  | Inference_held_input _ | Inference_initialization _ | Inference_initialization_job _
    -> Error (error Invalid_state "input or initializer has no reserved Run child parent")
;;

(* The returned callback runs only after the exact Job/Run transaction ACK.
   Failed or uncertain saves leave the callback scope at its prior revision. *)
let staged_child_run_delta
      ?planning_state
      t
      execution
      ~basis
      ~classification
      ~parent_work
      job_deltas
  =
  let open Result.Let_syntax in
  (* A native control may retire a pending intent in the same checkpoint.
     Only pure child projection uses this immutable Plan state. The captured
     execution and every original/currentness callback still select actual t. *)
  let planning_state = Option.value planning_state ~default:t.state in
  let jobs =
    List.filter_map job_deltas ~f:(function
      | Session_delta.Job_changed job -> Some job
      | _ -> None)
  in
  let%bind () =
    if
      List.for_all jobs ~f:(fun job ->
        Option.equal
          Agent_protocol.Job.Inference_origin.equal
          job.inference_origin
          classification)
    then Ok ()
    else
      Error (error Permission_denied "selected Job origin differs from its live parent")
  in
  match jobs, basis.run with
  | [], _ | _, None -> Ok ([], fun () -> Ok ())
  | _, Some run ->
    let%bind children = List.map jobs ~f:Run_job_occurrence.work |> Result.all in
    let%bind work_delta =
      Session_delta.capture_new_model_jobs planning_state (Session_delta.Batch job_deltas)
    in
    let%bind work_state = Session_delta.apply planning_state work_delta in
    (match held_initialization_of_execution t execution with
     | Some (_, selected) when Agent_protocol.Run.equal selected run ->
       let%map delta =
         Run_child_work.prepare_initialization
           planning_state
           ~run
           ~work_state
           ~children:jobs
           ~now:(t.services.now ())
       in
       [ delta ], fun () -> Ok ()
     | Some _ -> Error (error Conflict "held Init selected a different actual Run")
     | None ->
       let%bind parent =
         match parent_work with
         | Some parent -> Ok (Parent_work parent)
         | None -> child_parent t execution
       in
       (match parent with
        | Parent_work parent ->
          let%map delta =
            Run_child_work.prepare
              planning_state
              ~run
              ~parent
              ~work_state
              ~children
              ~now:(t.services.now ())
          in
          [ delta ], fun () -> Ok ()
        | Parent_observation borrow ->
          let%map delta =
            Run_child_work.prepare_observation
              planning_state
              ~run
              ~observing:borrow.invocation
              ~work_state
              ~children:jobs
              ~now:(t.services.now ())
          in
          [ delta ], fun () -> Ok ()
        | Parent_event borrow ->
          (match t.legacy_callback_scope with
           | Some scope when phys_equal scope.borrow borrow ->
             let%bind _ = callback_agent_actor t ~scope in
             let%map delta =
               Run_child_work.prepare_callback
                 planning_state
                 ~run
                 ~executing:borrow.receipt
                 ~work_state
                 ~children:jobs
                 ~now:(t.services.now ())
             in
             [ delta ], fun () -> Ok ()
           | None | Some _ ->
             let%bind owner =
               run_actions_internal t borrow.receipt
               |> Result.bind ~f:(fun owner ->
                 Result.of_option
                   owner
                   ~error:(error Invalid_state "Run event owner is absent"))
             in
             let scope = Run_action_service.scope owner in
             let%bind prepared =
               Run_transition.add_owned_work
                 ?lifecycle_selection:(lifecycle_selection borrow (Some run))
                 planning_state
                 ~scope
                 ~executing:borrow.receipt
                 ~work_delta
                 ~owned_work:children
                 ~now:(t.services.now ())
             in
             let%map advance =
               Run_scope.Host.prepare_advance
                 scope
                 ~previous:run
                 ~next:(Run_transition.run prepared)
                 ~execution_id:borrow.receipt.context.id
             in
             ( [ Run_transition.delta prepared ]
             , fun () -> Run_scope.Host.acknowledge_advance advance ))))
;;

let prepare_selected_child_run ?goal_plan t execution job_deltas =
  let open Result.Let_syntax in
  if
    not
      (List.exists job_deltas ~f:(function
         | Session_delta.Job_changed _ -> true
         | _ -> false))
  then Ok ([], (fun () -> Ok ()), fun () -> Ok ())
  else (
    let%bind current =
      match execution with
      | Inference_invocation invocation ->
        authorize_native_child_basis t ~read_current:(fun () ->
          selected_invocation_basis t invocation)
      | Inference_held_input _
      | Inference_operation _
      | Inference_moderator _
      | Inference_event _
      | Inference_job _
      | Inference_initialization _
      | Inference_initialization_job _ -> authorized_native_child_basis t execution
    in
    let%bind deltas, acknowledge =
      staged_child_run_delta
        ?planning_state:(Option.map goal_plan ~f:Goal_native_actions.Plan.state)
        t
        execution
        ~basis:current.selected.execution
        ~classification:current.selected.classification
        ~parent_work:current.selected.parent_work
        job_deltas
    in
    let%map () = current.check_current () in
    deltas, current.check_current, acknowledge)
;;

let inference_agent_admission t = function
  | Inference_held_input _ ->
    Error (error Permission_denied "input scope has no callback agent admission")
  | Inference_operation (operation, _) -> operation_agent_admission t operation.id
  | Inference_invocation execution -> execution_agent_admission t execution
  | Inference_moderator borrow -> moderator_agent_admission t borrow
  | Inference_event borrow -> event_agent_admission t borrow
  | Inference_job scope -> job_agent_admission t scope
  | Inference_initialization scope | Inference_initialization_job (scope, _) ->
    Ok (Some scope.agent_admission)
;;

(* Only the actual issuing constructor or its physically registered callback
   owns constructor bookkeeping. A current Init elsewhere is never a fallback. *)
let initialization_of_inference_execution t execution =
  let open Result.Let_syntax in
  let callback borrow =
    match t.legacy_callback_scope with
    | Some callback when phys_equal callback.borrow borrow ->
      let%bind _ = callback_inference_actor t ~scope:callback in
      (match callback.constructor_scope with
       | None -> Ok None
       | Some scope ->
         let%map () = validate_initialization_scope_current t scope in
         Some scope)
    | None | Some _ -> Ok None
  in
  match execution with
  | Inference_initialization scope | Inference_initialization_job (scope, _) ->
    let%map () = validate_initialization_scope_current t scope in
    Some scope
  | Inference_event borrow -> callback borrow
  | Inference_invocation execution ->
    (match execution.owner with
     | Event_moderator borrow -> callback borrow
     | Foreground _ | Background_job _ | Invocation_moderator _ -> Ok None)
  | Inference_held_input _
  | Inference_operation _
  | Inference_job _
  | Inference_moderator _ -> Ok None
;;

let model_job_parent t execution =
  let module Member = Policy_cause_data.Member in
  let generation = t.state.identity.generation in
  match execution with
  | Inference_event borrow ->
    Member.event borrow.receipt.context.id ~generation |> Result.map ~f:Option.some
  | Inference_invocation execution ->
    Member.invocation execution.dispatched.context.id ~generation
    |> Result.map ~f:Option.some
  | Inference_moderator borrow ->
    Member.invocation borrow.invocation.context.id ~generation
    |> Result.map ~f:Option.some
  | Inference_job scope ->
    let%bind.Result current_source = observation_source t in
    let%bind.Result prefix = policy_native_prefix t.state ~current_source in
    Policy_canonical_usage.Source.Native_prefix.job_member prefix ~job_id:scope.job.id
    |> Result.map ~f:Option.some
  | Inference_held_input _
  | Inference_operation _
  | Inference_initialization _
  | Inference_initialization_job _ -> Ok None
;;

let model_job_launch t execution ~binding =
  let open Result.Let_syntax in
  let callback owner =
    let%map launch =
      Job_launch.derive
        ~session_id:t.state.identity.session_id
        ~generation:t.state.identity.generation
        ~invocations:t.state.invocations
        ~events:t.state.moderator_executions
        ~jobs:t.state.jobs
        ~owner
    in
    let moderator_source =
      match binding with
      | Job_custody.Moderator_binding.No_captured_moderator -> None
      | Captured { source; _ } -> Some source.observer
    in
    Some { launch with moderator_source }
  in
  match execution with
  | Inference_event borrow ->
    callback (Agent_protocol.Job.Moderator_event borrow.receipt.context.id)
  | Inference_invocation execution ->
    callback (Invocation execution.dispatched.context.id)
  | Inference_moderator borrow -> callback (Invocation borrow.invocation.context.id)
  | Inference_job scope ->
    Job_launch.derive_from_job
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      ~jobs:t.state.jobs
      ~job_id:scope.job.id
      ~attempt:scope.job.attempt
    |> Result.map ~f:Option.some
  | Inference_held_input _
  | Inference_operation _
  | Inference_initialization _
  | Inference_initialization_job _ -> Ok None
;;

let admit_model_job
      ?(producer : Constructor_model_data.capture option)
      t
      execution
      candidate
  =
  let open Result.Let_syntax in
  let goal_scope = goal_runtime_of_execution t execution in
  let authored = held_authored_of_execution t execution in
  let%bind current = authorized_inference_execution_basis t execution in
  let%bind constructor = initialization_of_inference_execution t execution in
  let%bind preparation =
    match constructor with
    | None -> Ok current.basis.preparation
    | Some scope ->
      if
        Option.for_all current.basis.preparation ~f:(fun existing ->
          Option.exists
            (Initialization_scope.initial_preparation scope)
            ~f:(phys_equal existing))
      then Ok (Initialization_scope.initial_preparation scope)
      else Error (error Conflict "constructor model preparation changed")
  in
  let%bind job =
    Model_job_admission.prepare
      candidate
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      ~origin:(inference_origin current.basis)
  in
  let%bind () =
    if
      List.exists t.state.jobs ~f:(fun existing ->
        Agent_protocol.Id.Job.equal existing.id job.id)
    then Error (error Conflict "model Job ID already exists")
    else Ok ()
  in
  let%bind () =
    match execution with
    | Inference_held_input _ ->
      Error (error Permission_denied "input parsing cannot admit a callback Model Job")
    | Inference_initialization _ | Inference_initialization_job _ ->
      if
        Option.is_none (held_initialization_of_execution t execution)
        && Option.exists t.state.run_state ~f:(fun index ->
          List.exists (Run_state.runs index) ~f:(fun run ->
            match run.Agent_protocol.Run.lifecycle with
            | Admitted | Active | Waiting _ -> true
            | Terminal _ -> false))
      then
        Error
          (error
             Permission_denied
             "constructor model work requires its actual originating Run reservation")
      else Ok ()
    | Inference_operation _
    | Inference_invocation _
    | Inference_moderator _
    | Inference_event _
    | Inference_job _ -> Ok ()
  in
  let%bind binding = job_moderator_binding t in
  let%bind launch = model_job_launch t execution ~binding in
  let job = { job with launch } in
  let%bind parent = model_job_parent t execution in
  let%bind boundary = policy_boundary_of_execution t execution in
  let%bind policy, policy_source =
    policy_birth_metadata t (policy_model_job_birth ~boundary ~parent) job
  in
  let job_delta = Session_delta.Job_changed job in
  let%bind run_deltas, acknowledge =
    staged_child_run_delta
      t
      execution
      ~basis:current.basis
      ~classification:(Some (inference_origin current.basis))
      ~parent_work:None
      [ job_delta ]
  in
  let%bind parent =
    inference_agent_admission t execution
    |> Result.bind ~f:(fun parent ->
      Result.of_option
        parent
        ~error:(error Permission_denied "model parent admission is unavailable"))
  in
  let%bind selection =
    match constructor, preparation with
    | Some _, Some preparation ->
      Run_preparation.Constructor_jobs.prepare_add
        preparation
        ~owner:t.run_preparation_owner
        ~state:t.state
        ~job
      |> Result.map ~f:Option.some
    | None, _ | Some _, None -> Ok None
  in
  let%bind () =
    Option.value_map constructor ~default:(Ok ()) ~f:(fun _ ->
      Constructor_model_custody.before_admission t)
  in
  let%bind job_custody =
    Job_custody.prepare_fresh t.job_agent_custody ~job ~binding ~parent ~policy_source
  in
  let acknowledged = ref false in
  let retained = ref None in
  Exn.protect
    ~finally:(fun () ->
      match !retained with
      | None -> if not !acknowledged then Job_custody.Update.discard job_custody
      | Some (call, canonical) ->
        (match call.Constructor_model_data.phase with
         | Admission_attempt _ ->
           Constructor_model_custody.abandon_admission t call canonical
         | Admitted _
         | Claim_attempt _
         | Claimed _
         | Selected _
         | Terminal_attempt _
         | Cancel_attempt _
         | Joined _
         | Abandoned -> ()))
    ~f:(fun () ->
      let revision = t.state.counters.revision in
      let%bind prepared =
        prepare_transition
          ?run_preparation:preparation
          t
          ~delta:(Session_delta.Batch (job_delta :: (policy @ run_deltas)))
          ~payloads:[ Agent_protocol.Event.Durable.Payload.Job_state_changed job ]
      in
      let initialization_acknowledgement =
        Option.map constructor ~f:(fun scope ->
          Initialization_scope.Acknowledgement.prepare
            ~jobs:(job.id :: scope.jobs)
            scope
            prepared.state)
      in
      let%bind goal_runtime_acknowledgement =
        Option.value_map goal_scope ~default:(Ok None) ~f:(fun scope ->
          Goal_runtime_acknowledgement.prepare t scope ~candidate:prepared
          |> Result.map ~f:Option.some)
      in
      let%bind retained_plan =
        match producer, constructor, initialization_acknowledgement with
        | None, _, _ -> Ok None
        | Some capture, Some scope, Some acknowledgement
          when phys_equal capture.Constructor_model_data.scope scope
               && Agent_protocol.Job.equal_delivery job.delivery Not_required
               &&
               match job.retry_policy with
               | Never -> true
               | Safe_retry _ | Idempotent _ -> false ->
          let canonical =
            Constructor_model_custody.canonical
              t
              ~candidate:prepared
              ~job_custody
              ~acknowledgement
          in
          let%map call =
            Constructor_model_custody.retain_admission t capture ~queued:job canonical
          in
          retained := Some (call, canonical);
          Some (call, canonical)
        | Some _, _, _ ->
          Error
            (error
               Conflict
               "synchronous constructor producer has another admission owner")
      in
      let perform f =
        match retained_plan with
        | None -> f ()
        | Some (_, canonical) -> Constructor_model_custody.perform canonical f
      in
      Eio.Cancel.protect (fun () ->
        perform (fun () ->
          (* This selection check may refresh host policy. All original/physical
           and immutable-basis checks below run after that refresh. *)
          let%bind () =
            Option.value_map selection ~default:(Ok ()) ~f:(fun selection ->
              Run_preparation.Constructor_jobs.check_before_commit
                selection
                ~owner:t.run_preparation_owner
                ~state:t.state)
          in
          let%bind () = current.check_current () in
          let%bind () =
            Option.value_map constructor ~default:(Ok ()) ~f:(fun scope ->
              let%bind () = validate_initialization_scope_current t scope in
              check_initialization_agent_actor scope)
          in
          let%bind () = check_job_moderator_binding t binding in
          let%bind () =
            Job_custody.Update.check_before_commit
              job_custody
              ~current:t.job_agent_custody
          in
          let%bind () =
            Option.value_map
              initialization_acknowledgement
              ~default:(Ok ())
              ~f:Initialization_scope.Acknowledgement.check_basis
          in
          let%bind () =
            Option.value_map preparation ~default:(Ok ()) ~f:(fun preparation ->
              let%bind () =
                Run_preparation.check_current
                  preparation
                  ~owner:t.run_preparation_owner
                  ~state:t.state
              in
              Run_preparation.check_basis
                preparation
                ~owner:t.run_preparation_owner
                ~state:t.state)
          in
          let%bind () =
            if Int64.equal revision t.state.counters.revision
            then Ok ()
            else Error (error Conflict "model admission basis changed before persistence")
          in
          let%bind () =
            Option.value_map retained_plan ~default:(Ok ()) ~f:(fun (call, canonical) ->
              Constructor_model_custody.check_canonical t call canonical)
          in
          let%bind () =
            persist_transition
              ?commit_observation:
                (Option.map retained_plan ~f:(fun (_, canonical) ->
                   Session_commit_attempt.observation canonical.attempt))
              ?run_preparation:preparation
              ?check_before_commit:
                (match goal_scope with
                 | Some scope ->
                   Some
                     (fun () ->
                       let%bind () =
                         check_runtime_construction_effect
                           (Existing_goal scope.continuation)
                       in
                       let%bind () = current.check_current () in
                       Option.value_map
                         goal_runtime_acknowledgement
                         ~default:(Ok ())
                         ~f:(fun ack ->
                           Goal_runtime_acknowledgement.check
                             ack
                             ~actor:t
                             ~candidate:prepared))
                 | None -> held_startup_effect t preparation)
              t
              prepared
          in
          install_committed_transition
            ?goal_runtime_acknowledgement
            ?run_preparation:preparation
            ~job_custody
            ?initialization_acknowledgement
            t
            prepared;
          acknowledged := true;
          Option.iter retained_plan ~f:(fun (call, canonical) ->
            Constructor_model_custody.installed t call canonical;
            call.phase <- Admitted job;
            call.capture.phase <- Owned call);
          Option.iter authored ~f:(fun scope ->
            scope.Held_authored_start.jobs <- job :: scope.jobs);
          Option.iter selection ~f:Run_preparation.Constructor_jobs.acknowledge;
          let%map () = acknowledge () in
          publish_committed_transition t prepared;
          job)))
;;

let prepare_background_job t owner request =
  let open Result.Let_syntax in
  let%bind launch = derive_background_launch t owner in
  let%bind execution = background_inference_execution t owner in
  let%bind current = authorized_native_child_basis t execution in
  let basis = current.selected.execution in
  let%bind () =
    match basis.run with
    | None -> Ok ()
    | Some _ ->
      let%bind parent = child_parent t execution in
      (match parent with
       | Parent_work _ | Parent_observation _ -> Ok ()
       | Parent_event borrow ->
         (* The actual event owns this scope even if its caller has not staged
            a Run action. A child cannot rely on a later optional lookup. *)
         run_actions_internal t borrow.receipt |> Result.map ~f:ignore)
  in
  let%map () = current.check_current () in
  Agent_protocol.Job.
    { id = Agent_protocol.Id.Job.create ()
    ; session_id = t.state.identity.session_id
    ; generation = t.state.identity.generation
    ; kind = Async_tool
    ; payload = Chat_response.Background_request.to_json request
    ; status = Queued
    ; retry_policy = Never
    ; attempt = 0
    ; created_at = t.services.now ()
    ; started_at = None
    ; next_run_at = None
    ; completed_at = None
    ; result = None
    ; delivery = Pending
    ; launch = Some launch
    ; inference_origin = current.selected.classification
    ; progress = None
    }
;;

let stage_background_job_internal t (job : Agent_protocol.Job.t) capacity =
  let open Result.Let_syntax in
  let result =
    let%bind launch =
      Result.of_option job.launch ~error:(error Invalid_request "job has no launch owner")
    in
    let%bind owner =
      Result.of_option
        (Agent_protocol.Job.Birth_parent.callback_owner launch.owner)
        ~error:(error Invalid_request "background Job requires a callback owner")
    in
    let%bind expected = derive_background_launch t owner in
    let%bind execution = background_inference_execution t owner in
    let%bind current = authorized_native_child_basis t execution in
    let%bind () =
      if
        Option.equal
          Agent_protocol.Inference_origin.equal
          job.inference_origin
          current.selected.classification
      then Ok ()
      else
        Error
          (error
             Permission_denied
             "background Job origin differs from its current parent")
    in
    let%bind () =
      Extension_invariants.owner
        ~session_id:t.state.identity.session_id
        ~generation:t.state.identity.generation
        job.session_id
        job.generation
    in
    let%bind () =
      match
        ( Agent_protocol.Job.equal_launch launch expected
        , job.kind
        , job.status
        , job.retry_policy
        , job.attempt
        , job.started_at
        , job.next_run_at
        , job.completed_at
        , job.result
        , job.delivery )
      with
      | true, Async_tool, Queued, Never, 0, None, None, None, None, Pending -> Ok ()
      | _ ->
        Error
          (error
             Invalid_request
             "staged launch must be a fresh job with current ancestry")
    in
    let%bind _ = Agent_protocol.Job.of_json (Agent_protocol.Job.to_json job) in
    let%bind () =
      match
        List.exists t.state.jobs ~f:(fun existing ->
          Agent_protocol.Id.Job.equal existing.id job.id)
      with
      | true -> Error (error Conflict "background job already exists")
      | false -> Ok ()
    in
    let%bind parent =
      match owner with
      | Invocation id ->
        (match
           List.find t.invocation_executions ~f:(fun execution ->
             Agent_protocol.Id.Invocation.equal execution.dispatched.context.id id)
         with
         | Some execution -> execution_agent_admission t execution
         | None ->
           (match t.moderator_borrow with
            | Some borrow
              when Agent_protocol.Id.Invocation.equal borrow.invocation.context.id id ->
              moderator_agent_admission t borrow
            | Some _ | None -> Error (error Conflict "staged Job parent is unavailable")))
      | Moderator_event id ->
        (match t.queued_event_borrow with
         | Some borrow
           when Agent_protocol.Id.Moderator_execution.equal borrow.receipt.context.id id
           -> event_agent_admission t borrow
         | Some _ | None ->
           Error (error Conflict "staged Job event parent is unavailable"))
    in
    let%bind () = current.check_current () in
    let%bind boundary = policy_boundary_of_execution t execution in
    let%bind _, policy_source =
      policy_birth_metadata t (policy_async_job_birth ~boundary) job
    in
    let%bind fresh =
      match parent with
      | None -> Ok None
      | Some parent ->
        let%bind binding = job_moderator_binding t in
        Job_custody.Fresh.stage ~job ~binding ~parent ~policy_source
        |> Result.map ~f:Option.some
    in
    let capacity =
      Staged_jobs.
        { publish = capacity.publish
        ; abort =
            (fun () ->
              Option.iter fresh ~f:Job_custody.Fresh.discard;
              capacity.abort ())
        }
    in
    let staged = ref false in
    Exn.protect
      ~finally:(fun () ->
        if not !staged then Option.iter fresh ~f:Job_custody.Fresh.discard)
      ~f:(fun () ->
        let%map () = Staged_jobs.stage t.staged_jobs ~job ~payload:fresh ~capacity in
        staged := true)
  in
  match result with
  | Ok () -> Ok ()
  | Error _ as failure ->
    Eio.Cancel.protect capacity.Staged_jobs.abort;
    failure
;;

(* A stopped session can still own the constructor callback of an admitted
   initial Goal episode. Its exact borrow, Init scope and held Run establish
   that exception; an ordinary or delegated stopped callback has no such owner.
   The caller has already checked current original/source/effect custody. *)
let check_native_goal_stopped_owner t (execution : invocation_execution) =
  match t.state.lifecycle.desired with
  | Running -> Ok ()
  | Stopped ->
    let owns_initial_goal =
      match execution.owner, t.legacy_callback_scope with
      | Event_moderator borrow, Some callback when phys_equal callback.borrow borrow ->
        (match callback.constructor_scope with
         | Some scope ->
           (match Initialization_scope.construction scope with
            | Some (Initial continuation) ->
              initialization_callback_is_owned t scope
              && Option.exists
                   t.held_activation
                   ~f:(phys_equal (Admitted_activation.Continuation.target continuation))
              && Option.exists (initialization_held_run t scope) ~f:(fun run ->
                Option.exists
                  (Option.bind t.state.run_state ~f:(fun index ->
                     Run_state.goal_link index run.id))
                  ~f:(fun link ->
                    Agent_protocol.Id.Run.equal (Run_goal_link.run_id link) run.id))
            | Some (Existing_goal _ | Delegated_load _) | None -> false)
         | None -> false)
      | Event_moderator _, (Some _ | None)
      | (Invocation_moderator _ | Foreground _ | Background_job _), _ -> false
    in
    if owns_initial_goal
    then Ok ()
    else Error (error Permission_denied "Goal metadata invoking owner changed or stopped")
;;

let native_goal_execution t admission effect_kind =
  let open Result.Let_syntax in
  let%bind () = Goal_native_admission.check_now admission t.state ~effect_kind in
  let invocation = Goal_native_admission.invocation admission in
  let%bind execution =
    List.find t.invocation_executions ~f:(fun execution ->
      Agent_protocol.Invocation.equal execution.dispatched invocation)
    |> Result.of_option
         ~error:(error Permission_denied "native Goal invocation is not executing")
  in
  let%bind () =
    if execution.accepts_children && Atomic.get execution.authority_live
    then Ok ()
    else Error (error Conflict "native Goal execution has closed")
  in
  let%bind current = authorized_native_child_basis t (Inference_invocation execution) in
  let%bind () = current.check_current () in
  let%bind () = check_native_goal_stopped_owner t execution in
  let%bind actions =
    match execution.owner with
    | Event_moderator borrow ->
      let%bind () = validate_queued_event_borrow t borrow in
      if
        Goal_native_actions.matches_scope
          borrow.native_goals
          (Goal_native_admission.callback_scope admission)
      then Ok (Some borrow.native_goals)
      else
        Error
          (error
             Permission_denied
             "native Goal callback route does not match its actual event")
    | Invocation_moderator borrow ->
      let%bind () = validate_moderator_borrow t borrow in
      if
        Goal_native_actions.matches_scope
          borrow.native_goals
          (Goal_native_admission.callback_scope admission)
      then Ok (Some borrow.native_goals)
      else
        Error
          (error
             Permission_denied
             "native Goal callback route does not match its actual borrow")
    | Foreground _ | Background_job _ ->
      (match Goal_native_admission.callback_scope admission with
       | None -> Ok None
       | Some _ ->
         Error (error Permission_denied "native Goal route escaped its callback"))
  in
  Ok (execution, actions, current)
;;

let native_goal_projection t actions =
  let open Result.Let_syntax in
  match actions with
  | None -> Ok t.state
  | Some actions ->
    let%bind entries = Goal_native_actions.recorded actions in
    let%bind controller = require_recurrence_controller t in
    let%map plan =
      Goal_native_actions.Plan.prepare
        entries
        ~state:t.state
        ~session:(Recurrence_controller.session controller)
        ~descendant_profile:t.services.goal_descendant_profile
        ~now:(t.services.now ())
    in
    Goal_native_actions.Plan.state plan
;;

let stage_native_goal t admission authorize ~effect_kind make =
  let open Result.Let_syntax in
  let%bind execution, actions, current = native_goal_execution t admission effect_kind in
  let%bind () =
    if Option.is_none execution.native_goal
    then Ok ()
    else Error (error Conflict "native Invocation already staged a Goal action")
  in
  let%bind state = native_goal_projection t actions in
  let%bind parent = execution_agent_admission t execution in
  let%bind parent =
    Result.of_option
      parent
      ~error:(error Permission_denied "native Goal action has no admitted original")
  in
  let%bind custody =
    Result.of_option
      (Execution_custody.Admission.custody parent)
      ~error:(error Permission_denied "native Goal action has no authenticated original")
  in
  let%bind actor = Execution_custody.actor custody in
  let%bind () =
    if
      Agent_protocol.Id.Principal.equal
        (Operator_authorization.principal actor).id
        (Operator_authorization.principal (Goal_native_admission.actor admission)).id
    then Goal_command_admission.check_write actor ~authorize:(authorize actor) t.state
    else
      Error (error Permission_denied "native Goal original differs from actual execution")
  in
  let%bind controller = require_recurrence_controller t in
  let%bind value = make state actor (Recurrence_controller.session controller) in
  let%bind () = Goal_native_admission.check_now admission t.state ~effect_kind in
  let%bind () = current.check_current () in
  let%bind loan = Execution_custody.Admission.transfer parent in
  let entry =
    Goal_native_actions.Entry.create
      ~invocation_id:execution.dispatched.context.id
      ~value
      ~admission:loan
      ~authorize
  in
  let installed = ref false in
  Exn.protect
    ~finally:(fun () -> if not !installed then Goal_native_actions.Entry.discard entry)
    ~f:(fun () ->
      let%bind ticket =
        match actions with
        | None -> Ok None
        | Some actions ->
          Result.map (Goal_native_actions.stage actions entry) ~f:Option.some
      in
      execution.native_goal <- Some (entry, ticket);
      installed := true;
      Ok ticket)
;;

let stage_native_goal_command t admission authorize ~effect_kind make_request =
  stage_native_goal t admission authorize ~effect_kind (fun state actor session ->
    let open Result.Let_syntax in
    let%bind request = make_request () in
    let%map _ =
      Goal_command_admission.prepare
        state
        ~actor
        ~authorize:(authorize actor)
        ~session
        ~descendant_profile:t.services.goal_descendant_profile
        ~request
        ~now:(t.services.now ())
    in
    Goal_native_actions.Value.Edit request)
;;

let stage_native_goal_edit t admission authorize edit =
  let effect_kind, mutation =
    match Agent_protocol.Goal_edit.mutation edit with
    | Revise_objective objective ->
      ( Goal_native_admission.Effect.Objective
      , Goal_command.Mutation.Revise_objective
          (Agent_protocol.Goal_edit.goal_id edit, objective) )
    | Record_progress progress ->
      ( Goal_native_admission.Effect.Progress
      , Goal_command.Mutation.Record_progress
          (Agent_protocol.Goal_edit.goal_id edit, progress) )
  in
  stage_native_goal_command t admission authorize ~effect_kind (fun () ->
    Goal_command.create
      ~session_id:t.state.identity.session_id
      ~generation:(Agent_protocol.Goal_edit.generation edit)
      ~source:(Some (Agent_protocol.Goal_edit.source edit))
      ~expected_catalog_revision:(Agent_protocol.Goal_edit.expected_catalog_revision edit)
      ~expected_goal_revision:
        (Some (Agent_protocol.Goal_edit.expected_goal_revision edit))
      ~key:(Agent_protocol.Goal_edit.key edit)
      ~mutation)
;;

let stage_native_goal_create t admission authorize request =
  let module R = Agent_protocol.Goal_native_create_request in
  stage_native_goal_command t admission authorize ~effect_kind:Create (fun () ->
    Goal_command.create
      ~session_id:t.state.identity.session_id
      ~generation:(R.generation request)
      ~source:(Some (R.source request))
      ~expected_catalog_revision:(R.expected_catalog_revision request)
      ~expected_goal_revision:None
      ~key:(R.key request)
      ~mutation:
        (Create
           { id = R.goal_id request
           ; objective = R.objective request
           ; budget = R.budget request
           }))
;;

let stage_native_goal_control t admission authorize request =
  let module R = Agent_protocol.Goal_native_control_request in
  let effect_kind, mutation =
    match R.mutation request with
    | Hold reason ->
      ( Goal_native_admission.Effect.Hold
      , Goal_command.Mutation.Hold (R.goal_id request, Needs_input reason) )
    | Abandon reason ->
      ( Goal_native_admission.Effect.Abandon
      , Goal_command.Mutation.Abandon (R.goal_id request, reason) )
  in
  stage_native_goal_command t admission authorize ~effect_kind (fun () ->
    Goal_command.create
      ~session_id:t.state.identity.session_id
      ~generation:(R.generation request)
      ~source:None
      ~expected_catalog_revision:(R.expected_catalog_revision request)
      ~expected_goal_revision:(Some (R.expected_goal_revision request))
      ~key:(R.key request)
      ~mutation)
;;

let stage_native_goal_resume t admission authorize request =
  stage_native_goal t admission authorize ~effect_kind:Resume (fun state actor session ->
    let open Result.Let_syntax in
    let%bind _ =
      Goal_resume_admission.prepare
        state
        ~request
        ~principal_id:(Operator_authorization.principal actor).id
        ~session
        ~now:(t.services.now ())
    in
    let%bind intent =
      Agent_protocol.Goal_native_resume_intent.create
        ~request
        ~principal_id:(Operator_authorization.principal actor).id
    in
    let%bind goal =
      Option.bind state.Session_state.goal_catalog ~f:(fun catalog ->
        Goal_catalog.find catalog (Goal_resume_request.goal_id request))
      |> Result.of_option
           ~error:(error Invalid_request "native Goal Resume target is absent")
    in
    let%map () =
      match Agent_protocol.Goal.state goal with
      | Open (Held Operator_pause) ->
        Error
          (error Permission_denied "native Goal Resume cannot clear an operator pause")
      | Open (Enabled | Held _) | Closed _ -> Ok ()
    in
    Goal_native_actions.Value.Resume intent)
;;

let stage_native_goal_start t admission authorize request =
  stage_native_goal t admission authorize ~effect_kind:Start (fun state actor session ->
    let open Result.Let_syntax in
    let principal_id = (Operator_authorization.principal actor).id in
    let%bind () =
      Goal_native_start_association.check_request request ~state ~session ~principal_id
    in
    let%map intent =
      Agent_protocol.Goal_native_start_intent.create ~request ~principal_id
    in
    Goal_native_actions.Value.Start intent)
;;

let native_goal_run_id (invocation : Agent_protocol.Invocation.t) =
  match invocation.inference_origin with
  | Some (Run id) -> Some id
  | None | Some Unbound -> None
;;

let pending_native_goal_turn = function
  | Agent_protocol.Invocation.Pending_follow_up requests
  | Compaction_accepted_follow_up requests -> requests.request_turn
  | Applied_follow_up _ | Discarded_follow_up _ -> false
;;

let prepare_native_goal_completion t execution outcome resolved =
  let open Result.Let_syntax in
  match execution.native_goal with
  | None ->
    let%map plan = prepare_native_goal_plan t [] in
    resolved, plan
  | Some (entry, ticket) ->
    (match outcome with
     | Agent_protocol.Invocation.Complete _ ->
       let%bind () = Goal_native_actions.Entry.check entry t.state in
       Goal_native_actions.Entry.completed entry;
       let%bind resolved =
         match Goal_native_actions.Entry.value entry with
         | Edit _ -> Ok resolved
         | Start intent -> record_native_goal_start resolved intent
         | Resume intent -> record_native_goal_resume resolved intent
       in
       (match ticket with
        | Some _ ->
          (* Native result ACK remains Staged. Only the exact selected parent
             checkpoint may accept this same entry and loan. *)
          let%map plan = prepare_native_goal_plan t [] in
          resolved, plan
        | None ->
          let%bind () = Goal_native_actions.Entry.select_completed entry in
          let%map plan = prepare_native_goal_plan t ~completed:resolved [ entry ] in
          let resolved =
            List.find_map plan.accepted ~f:(fun (accepted, _) ->
              if
                Agent_protocol.Id.Invocation.equal accepted.context.id resolved.context.id
              then Some accepted
              else None)
            |> Option.value ~default:resolved
          in
          resolved, plan)
     | Fail _ | Pending _ | Cancelled _ ->
       Goal_native_actions.Entry.discard entry;
       let%map plan = prepare_native_goal_plan t [] in
       resolved, plan)
;;

let install_descendant_host_internal
      t
      ~purpose
      ~source_owner
      ~expected
      ~check_ancestry
      ~host
      ~causal_driver
  =
  let open Result.Let_syntax in
  let%bind controller = child_accounting_owner t ~source_owner in
  let%bind () =
    let changed () =
      Error (error Conflict "descendant source selection State changed before install")
    in
    match purpose with
    | Descendant_host_installation.Ordinary_ready_reload scope ->
      let%bind () = require_runtime_admission t in
      let%bind () = require_selected_execution t in
      let unchanged = phys_equal expected t.state in
      let%bind () =
        match scope, t.initialization_scope with
        | None, None -> Ok ()
        | None, Some _ when unchanged -> Ok ()
        | ( Some
              ({ purpose = Runtime_construction
               ; custody = Ordinary
               ; callback = Unclaimed
               ; resource = None
               ; _
               } as scope)
          , Some active )
          when phys_equal scope active
               && phys_equal scope.expected expected
               && Int.equal scope.domain t.runtime_source_domain
               && Option.is_some
                    (Execution_custody.Admission.custody scope.agent_admission) ->
          let%bind () = validate_initialization_owner t scope in
          check_initialization_agent_actor scope
        | (None | Some _), (None | Some _) -> changed ()
      in
      if unchanged
      then Ok ()
      else (
        match
          ( expected.runtime_initialization
          , expected.lifecycle.desired
          , expected.lifecycle.observed
          , expected.spec.delegation
          , t.run_preparation )
        with
        | Ready, Stopped, Stopped, None, None
          when runtime_ready t
               && Session_state.same_ordinary_ready_reload_basis t.state ~expected ->
          Ok ()
        | _ -> changed ())
    | Ordinary | Restored _ -> if phys_equal expected t.state then Ok () else changed ()
  in
  let%bind () =
    match expected.spec.delegation, check_ancestry with
    | None, None | Some _, Some _ -> Ok ()
    | None, Some _ | Some _, None ->
      Error (error Conflict "descendant binding ancestry differs from actual source")
  in
  let binding : Descendant_host_data.Binding.t =
    { issuing_actor = t.inference_owner_identity
    ; domain = (Stdlib.Domain.self () :> int)
    ; source_owner
    ; controller
    ; check_ancestry
    ; host
    ; closed = false
    }
  in
  retire_descendant_host t;
  let installed =
    match causal_driver with
    | None -> Physical_only binding
    | Some causal -> Governed { physical = binding; causal }
  in
  t.descendant_host_binding <- Some installed;
  Ok binding
;;

let child_contributions_changed (state : Session_state.t) incoming =
  let open Result.Let_syntax in
  let%bind incoming = Child_contributions.to_jsonaf incoming in
  match state.child_contributions with
  | None -> Ok true
  | Some previous ->
    let%map previous = Child_contributions.to_jsonaf previous in
    not (Document_schema.Json.equal previous incoming)
;;

let observe_child_installation_internal t ~source_owner ~reference =
  let module D = Agent_store.Delegation_store in
  let open Result.Let_syntax in
  let%bind controller = child_accounting_owner t ~source_owner in
  let state = t.state in
  let association () =
    let%bind _ = child_accounting_owner t ~source_owner in
    if
      phys_equal state t.state
      && Agent_protocol.Id.Session.equal
           state.identity.session_id
           reference.D.Reference.child_session_id
      && Agent_protocol.Id.Prompt_revision.equal
           state.spec.prompt_revision_id
           reference.revision_id
      && Option.exists state.spec.delegation ~f:(D.Reference.equal reference)
    then Ok ()
    else Error (error Conflict "child installation differs from its actual Spec")
  in
  let%bind () = association () in
  let%bind record = Recurrence_controller.resolve_delegation controller reference in
  let%bind () =
    match record.stage, record.revocation with
    | (Child_installed | Linked), None -> Ok ()
    | (Reserved | Artifact_installed), None
    | (Reserved | Artifact_installed | Child_installed | Linked), Some _ ->
      Error (error Conflict "child installation is not durably installed and live")
  in
  let%bind current = Recurrence_controller.observe controller state in
  let check_current () =
    let%bind () = association () in
    if Recurrence_controller.is_current current
    then Ok ()
    else Error (error Conflict "child installation Store observation changed")
  in
  let%map () = check_current () in
  Child_installation.
    { controller
    ; source_owner = Runtime_source_owner.identity source_owner
    ; reference
    ; check_current
    }
;;

(* A native callback already owns admission. This selection adds no permission:
   it ties the DATA ACK to the SAME registered invocation and its real Init,
   existing-Goal or initial callback acknowledgement. Never select ambient Init. *)
let child_native_execution t invocation =
  let module I = Agent_protocol.Invocation in
  List.find t.invocation_executions ~f:(fun execution ->
    I.equal execution.dispatched invocation
    && execution.accepts_children
    && Atomic.get execution.authority_live)
  |> Result.of_option
       ~error:(error Conflict "child installation lost its native callback owner")
;;

let child_installation_native_execution t borrowed =
  let module N = Native_tool_invocation in
  let open Result.Let_syntax in
  let%bind _ = N.borrowed_capabilities borrowed in
  child_native_execution t (N.borrowed_invocation borrowed)
;;

let child_origin_parent_fingerprint (state : Session_state.t) =
  (* Persisted moderator identity is consistency DATA here, not evidence of an
     installed authorized source. Actual native/Factory checks retain that grant. *)
  let open Result.Let_syntax in
  let%bind moderator = Moderator_checkpoint.observer state.moderator in
  Delegation_authority.fingerprint ?moderator state
;;

let submit_goal_resume_ordinary t (selected : Inherited_turn.Goal_resume_selection.t) =
  let open Result.Let_syntax in
  let scope = selected.scope in
  let continuation = scope.continuation in
  let preparation = continuation.binding.preparation in
  let recovery = selected.recovery in
  let turn = selected.turn in
  let next = selected.next in
  let operation = Turn_admission.operation turn in
  let before = t.state in
  let%bind candidate =
    prepare_transition
      t
      ~delta:
        (Batch
           (History_continuation.deltas recovery
            @ Turn_admission.deltas turn
            @ [ Run_state_changed next ]))
      ~payloads:(History_continuation.payloads recovery @ Turn_admission.payloads turn)
  in
  let attempted = ref false in
  let%bind staged =
    Turn_admission_staging.capture
      ~owner:t.run_preparation_owner
      ~before
      ~candidate
      ~operation
      ~remaining_audit:t.command_audit
      ~commit_attempted:attempted
      ~plan:operation
  in
  let%bind fact = Goal_runtime_acknowledgement.prepare t scope ~candidate in
  let%bind ack = prepare_goal_operation_ack t scope ~operation ~candidate in
  let owner = ack.owner in
  let installed = ref false in
  Exn.protect
    ~finally:(fun () ->
      if not !installed then Operation_owner.retire owner;
      if !attempted && not !installed then Goal_continuation.close preparation)
    ~f:(fun () ->
      let%bind () =
        persist_transition
          ~commit_attempted:attempted
          ~check_before_commit:(fun () ->
            let%bind () =
              check_runtime_construction_effect (Existing_goal continuation)
            in
            let%bind () =
              Goal_runtime_operation_acknowledgement.check ack ~actor:t ~candidate
            in
            let%bind () = Goal_runtime_acknowledgement.check fact ~actor:t ~candidate in
            Turn_admission_staging.check_before_writer
              staged
              ~owner:t.run_preparation_owner
              ~state:t.state)
          t
          candidate
      in
      install_committed_transition
        ~goal_runtime_acknowledgement:fact
        ~goal_operation_acknowledgement:ack
        t
        candidate;
      installed := true;
      let%bind acknowledgement =
        Turn_admission_staging.acknowledge
          staged
          ~owner:t.run_preparation_owner
          ~state:t.state
      in
      let%bind operation =
        Turn_admission_staging.finish
          acknowledgement
          ~owner:t.run_preparation_owner
          ~state:t.state
      in
      publish_committed_transition t candidate;
      launch_worker t operation;
      Ok
        (Goal_resume_result.Resumed
           { receipt = Goal_continuation.receipt continuation
           ; continuation = Started operation
           }))
;;

let admit_goal_resume_selection ?origin_observation t selected ~capture =
  let open Result.Let_syntax in
  let%bind () = check_goal_resume_selection t selected in
  let%bind requirement = checked_turn_requirement ?origin_observation t in
  match requirement with
  | Ordinary ->
    let%map result = submit_goal_resume_ordinary t selected in
    Inherited_turn.Decision.Completed result
  | Need_private_origin ->
    capture_turn_origin
      t
      ~capture
      ~input:(Inherited_turn.Input.Goal_resume_selected selected)
  | Scoped ->
    let source = Inherited_turn.Source.Goal_resume { selection = selected } in
    capture_inherited_turn_plan
      t
      ~capture
      ~source
      ~commit_attempted:(ref false)
      ~delta:
        (Session_delta.Batch
           (History_continuation.deltas selected.recovery
            @ Turn_admission.deltas selected.turn
            @ [ Run_state_changed selected.next ]))
      ~payloads:
        (History_continuation.payloads selected.recovery
         @ Turn_admission.payloads selected.turn)
;;

(* Called only by the finite capture request. The key principal is factual lower
   allocation identity; native/ordinary callers derive it from creating_principal.
   A genuine recurrence permit may supply its retained row principal separately.
   Actual creator identity, including historical None, is fenced independently. *)
let prepare_child_origin_internal
      t
      ~source_owner
      ~principal_id
      ~inherited
      ~local_goal
      ~refresh_native
  =
  let open Result.Let_syntax in
  let%bind controller = child_accounting_owner t ~source_owner in
  let session = Recurrence_controller.session controller in
  let generation = t.state.identity.generation in
  let stop_epoch = t.state.stop_epoch in
  let creating_principal = t.state.identity.creating_principal in
  let%bind fingerprint = child_origin_parent_fingerprint t.state in
  let check_parent (observed_state : Session_state.t) =
    let%bind actual = child_accounting_owner t ~source_owner in
    let%bind () =
      if
        phys_equal controller actual
        && phys_equal observed_state t.state
        && Agent_protocol.Id.Session.equal
             (Agent_protocol.Session_ref.session_id session)
             t.state.identity.session_id
        && Int.equal generation t.state.identity.generation
        && Int64.equal stop_epoch t.state.stop_epoch
        && Option.equal
             Agent_protocol.Id.Principal.equal
             creating_principal
             t.state.identity.creating_principal
      then Ok ()
      else Error (error Conflict "child origin parent or lower key identity changed")
    in
    let%bind current_fingerprint = child_origin_parent_fingerprint observed_state in
    if String.equal fingerprint current_fingerprint
    then Ok ()
    else Error (error Conflict "child origin parent source or policy changed")
  in
  let rec preparation : Child_origin.Preparation.t =
    { issuing_actor = t.inference_owner_identity
    ; domain = (Stdlib.Domain.self () :> int)
    ; session
    ; generation
    ; principal_id
    ; inherited
    ; local_goal
    ; max_scopes = Goal_descendants.Profile.max_scopes t.services.goal_descendant_profile
    ; capture_current =
        (fun attempt ->
          let%bind observed_basis = capture_child_accounting_basis t ~source_owner in
          let observed_state = observed_basis.state in
          let%map () = check_parent observed_state in
          let rec captured : Child_origin.Captured_refresh.t =
            { preparation
            ; attempt
            ; observe =
                (fun () ->
                  (* This closure runs only in the public wrapper, outside the
                     mailbox and Owner locks. All potentially yielding reads
                     retain the exact State captured by the finite request. *)
                  let%bind () = check_parent observed_state in
                  let%bind check_native_now = refresh_native observed_state in
                  let observation =
                    Recurrence_controller.observe controller observed_state
                  in
                  (* The Store may reject a stale projection after a concurrent
                     Actor ACK. Report the changed capture before interpreting
                     that result; errors against a current basis remain intact. *)
                  let%bind () = check_parent observed_state in
                  let%bind current = observation in
                  let check_current () =
                    let%bind () = check_native_now () in
                    let%bind () = check_parent observed_state in
                    check_child_accounting_basis t observed_basis ~current
                  in
                  let%map () = check_current () in
                  Child_origin.{ captured; check_current })
            }
          in
          captured)
    ; refresh_current =
        (fun () -> Error (error Conflict "child origin preparation is not published"))
    ; refresh_attempt = None
    ; captured = None
    ; observed = None
    ; bound = None
    }
  in
  Ok preparation
;;

let child_origin_key_principal t =
  Result.of_option
    t.state.identity.creating_principal
    ~error:(error Permission_denied "child origin parent has no durable key principal")
;;

let prepare_native_child_origin_internal t ~source_owner ~admission ~binding ~ancestry =
  let module N = Native_tool_invocation in
  let module Origin = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  let%bind () = N.Admission.check_now admission ~binding in
  let%bind execution = child_native_execution t (N.Admission.invocation admission) in
  (* Selection is pure; original authorization is deferred to the external
     refresh below, rather than invoked while servicing an Actor request. *)
  let%bind selected = native_child_basis t (Inference_invocation execution) in
  let%bind controller = child_accounting_owner t ~source_owner in
  let%bind inherited, refresh_ancestry =
    child_origin_ancestry t.state ~source_owner ~controller ancestry
  in
  let basis = selected.execution in
  let%bind original_binding =
    match basis.run with
    | None -> Ok None
    | Some run -> Result.map (inference_run_binding_current t run) ~f:Option.some
  in
  let original =
    match original_binding with
    | None -> N.Admission.actor admission
    | Some binding -> Run_admission.Scope.original_actor (Run_authorities.scope binding)
  in
  let%bind () =
    if
      (Option.is_some basis.attribution || not (List.is_empty (Origin.scopes inherited)))
      && Option.is_none original
    then Error (error Permission_denied "governed child origin has no actual original")
    else Ok ()
  in
  let%bind () =
    match basis.attribution with
    | None -> Ok ()
    | Some attribution ->
      if
        Agent_protocol.Session_ref.equal
          (Agent_protocol.Goal_episode.session
             (Goal_work_attribution.episode attribution))
          (Recurrence_controller.session controller)
      then Ok ()
      else Error (error Conflict "child origin local Goal belongs to another owner")
  in
  let check_selection () =
    let%bind () = N.Admission.check_now admission ~binding in
    let%bind actual = child_native_execution t (N.Admission.invocation admission) in
    let%bind actual_basis = native_child_basis t (Inference_invocation actual) in
    let same_run left right =
      Agent_protocol.Id.Run.equal left.Agent_protocol.Run.id right.Agent_protocol.Run.id
      && Agent_protocol.Run_source.equal left.source right.source
      && Agent_protocol.Id.Principal.equal left.principal_id right.principal_id
      && Agent_protocol.Session_ref.equal left.session right.session
    in
    let same_attribution left right =
      Agent_protocol.Id.Goal.equal
        (Goal_work_attribution.goal_id left)
        (Goal_work_attribution.goal_id right)
      && Agent_protocol.Goal_episode.equal
           (Goal_work_attribution.episode left)
           (Goal_work_attribution.episode right)
    in
    let%bind () =
      if
        phys_equal execution actual
        && Option.equal same_run basis.run actual_basis.execution.run
        && Option.equal
             same_attribution
             basis.attribution
             actual_basis.execution.attribution
        && Option.equal
             Agent_protocol.Inference_origin.equal
             selected.classification
             actual_basis.classification
        && Option.equal
             Agent_protocol.Run_work.equal
             selected.parent_work
             actual_basis.parent_work
        &&
        match basis.run, original_binding with
        | None, None -> true
        | Some run, Some binding ->
          Run_authorities.is_current t.run_authorities binding ~run_id:run.id
        | None, Some _ | Some _, None -> false
      then Ok ()
      else
        Error (error Conflict "child origin native execution or immutable basis changed")
    in
    let%bind () =
      match original with
      | None -> Ok ()
      | Some original ->
        if Operator_authorization.is_current original
        then Ok ()
        else Error (error Permission_denied "child origin original authority expired")
    in
    N.Admission.check_now admission ~binding
  in
  let refresh_native observed_state =
    let%bind () = check_selection () in
    let%bind refreshed =
      authorized_native_child_basis t (Inference_invocation execution)
    in
    let%bind () = refresh_ancestry observed_state in
    let check_now () =
      let%bind () = check_selection () in
      let%bind () = refreshed.check_current () in
      N.Admission.check_now admission ~binding
    in
    let%map () = check_now () in
    check_now
  in
  let%bind principal_id = child_origin_key_principal t in
  let local_goal =
    Option.map basis.attribution ~f:(fun attribution ->
      Child_origin.
        { goal_id = Goal_work_attribution.goal_id attribution
        ; creator_episode = Goal_work_attribution.episode attribution
        })
  in
  prepare_child_origin_internal
    t
    ~source_owner
    ~principal_id
    ~inherited
    ~local_goal
    ~refresh_native
;;

let prepare_unrelated_child_origin_internal t ~source_owner =
  let%bind.Result principal_id = child_origin_key_principal t in
  prepare_child_origin_internal
    t
    ~source_owner
    ~principal_id
    ~inherited:Agent_store.Delegation_goal_origin.unrelated
    ~local_goal:None
    ~refresh_native:(fun (_ : Session_state.t) -> Ok (fun () -> Ok ()))
;;

let check_child_origin_preparation t (preparation : Child_origin.Preparation.t) =
  if
    phys_equal preparation.issuing_actor t.inference_owner_identity
    && Int.equal preparation.domain (Stdlib.Domain.self () :> int)
  then Ok ()
  else Error (error Conflict "child origin preparation belongs to another Actor/domain")
;;

let capture_child_origin_refresh_internal
      t
      (preparation : Child_origin.Preparation.t)
      attempt
  =
  let open Result.Let_syntax in
  let%bind () = check_child_origin_preparation t preparation in
  let%bind () =
    if Option.exists preparation.refresh_attempt ~f:(phys_equal attempt)
    then Ok ()
    else Error (error Conflict "child origin refresh attempt was superseded")
  in
  let%map captured = preparation.capture_current attempt in
  preparation.captured <- Some captured;
  captured
;;

let consume_child_origin_refresh_internal t (observed : Child_origin.Observed_refresh.t) =
  let open Result.Let_syntax in
  let preparation = observed.captured.preparation in
  let%bind () = check_child_origin_preparation t preparation in
  let%bind () =
    if
      Option.exists preparation.refresh_attempt ~f:(phys_equal observed.captured.attempt)
      && Option.exists preparation.captured ~f:(phys_equal observed.captured)
    then Ok ()
    else Error (error Conflict "child origin refresh was superseded or consumed")
  in
  let%map () = observed.check_current () in
  preparation.captured <- None;
  preparation.observed <- Some observed
;;

let bind_child_origin_internal
      t
      ~(preparation : Child_origin.Preparation.t)
      ~key
      ~child_session_id
      ~transaction_id
  =
  let module D = Agent_store.Delegation_store in
  let module Origin = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  let%bind () =
    if
      phys_equal preparation.issuing_actor t.inference_owner_identity
      && Int.equal preparation.domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Conflict "child origin preparation belongs to another Actor/domain")
  in
  let%bind () = Child_origin.Preparation.check_current preparation in
  let%bind () =
    Agent_store.Delegation_record.validate_key key
    |> Result.map_error ~f:Agent_store.Store_error.to_protocol_error
  in
  let%bind () =
    if
      Agent_protocol.Id.Session.equal
        key.parent_session_id
        (Agent_protocol.Session_ref.session_id preparation.session)
      && Int.equal key.parent_generation preparation.generation
      && Agent_protocol.Id.Principal.equal key.principal_id preparation.principal_id
      && not (Agent_protocol.Id.Session.equal key.parent_session_id child_session_id)
    then Ok ()
    else
      Error (error Conflict "child origin allocation differs from its actual parent key")
  in
  match preparation.bound with
  | Some bound ->
    if
      D.Key.equal key bound.key
      && Agent_protocol.Id.Session.equal child_session_id bound.child_session_id
      && Agent_protocol.Id.Transaction.equal transaction_id bound.transaction_id
    then Result.map (Child_origin.Bound.check_current bound) ~f:(fun () -> bound)
    else Error (error Conflict "child origin preparation is already bound elsewhere")
  | None ->
    let%bind scopes =
      match preparation.local_goal with
      | None -> Ok (Origin.scopes preparation.inherited)
      | Some { goal_id; creator_episode } ->
        let%bind branch =
          Origin.Anchor.create
            ~parent_session_id:key.parent_session_id
            ~parent_generation:key.parent_generation
            ~principal_id:key.principal_id
            ~key:key.idempotency_key
            ~child_session_id
            ~transaction_id
        in
        let%map scope =
          Origin.Scope.create
            ~owner:preparation.session
            ~goal_id
            ~source:(Agent_protocol.Goal_episode.admission creator_episode).source
            ~creator_episode
            ~branch
        in
        scope :: Origin.scopes preparation.inherited
    in
    let%bind origin =
      match scopes with
      | [] -> Ok Origin.unrelated
      | _ :: _ ->
        Origin.associated
          ~max_scopes:preparation.max_scopes
          (List.sort scopes ~compare:Origin.Scope.compare_root)
    in
    let bound : Child_origin.Bound.t =
      { preparation; key; child_session_id; transaction_id; origin }
    in
    let%map () = Child_origin.Bound.check_current bound in
    preparation.bound <- Some bound;
    bound
;;

let install_child_accounting_delta
      t
      ~(execution : invocation_execution option)
      ~(native_preparation : Run_preparation.t option)
      ~check
      ~delta
  =
  let open Result.Let_syntax in
  let%bind constructor =
    match execution with
    | None -> Ok None
    | Some execution ->
      initialization_of_inference_execution t (Inference_invocation execution)
  in
  let preparation =
    match constructor with
    | Some constructor -> Initialization_scope.initial_preparation constructor
    | None -> native_preparation
  in
  let%bind candidate =
    prepare_transition ?run_preparation:preparation t ~delta ~payloads:[]
  in
  let initialization_acknowledgement =
    Option.map constructor ~f:(fun scope ->
      Initialization_scope.Acknowledgement.prepare scope candidate.state)
  in
  let%bind goal_runtime_acknowledgement =
    Option.bind execution ~f:(fun execution ->
      goal_runtime_of_execution t (Inference_invocation execution))
    |> Option.value_map ~default:(Ok None) ~f:(fun scope ->
      Goal_runtime_acknowledgement.prepare t scope ~candidate |> Result.map ~f:Option.some)
  in
  let%bind held_authored_callback_acknowledgement =
    Option.bind execution ~f:(fun execution ->
      held_authored_of_execution t (Inference_invocation execution))
    |> Option.value_map ~default:(Ok None) ~f:(fun scope ->
      Held_authored_callback_acknowledgement.prepare t scope ~candidate)
  in
  install
    ?run_preparation:preparation
    ?initialization_acknowledgement
    ?goal_runtime_acknowledgement
    ?held_authored_callback_acknowledgement
    ~check_before_commit:(fun () ->
      let%bind () = check () in
      Option.value_map
        initialization_acknowledgement
        ~default:(Ok ())
        ~f:Initialization_scope.Acknowledgement.check_basis)
    t
    candidate
;;

(* A missing slot is distinct from a retained Unknown slot. Only a genuine
   private positive admission may recover the former without an old frontier. *)
let retained_child_origin_slot (state : Session_state.t) ~reference ~origin =
  let module D = Agent_store.Delegation_store in
  let module Origin = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  match state.child_contributions with
  | None -> Ok false
  | Some children ->
    let references = Child_contributions.references children in
    if List.mem references reference ~equal:D.Reference.equal
    then (
      let%bind stored = Child_contributions.origin children ~reference in
      if Option.exists stored ~f:(Origin.equal origin)
      then Ok true
      else
        Error (error Conflict "retained child frozen origin differs from its parent slot"))
    else if
      List.exists references ~f:(fun stored ->
        D.Key.equal stored.key reference.key
        || Agent_protocol.Id.Session.equal
             stored.child_session_id
             reference.child_session_id)
    then Error (error Conflict "retained child admission differs from its parent slot")
    else Ok false
;;

(* Retained lower records are factual custody, never a fresh birth selection.
   The finite retained branch relation preserves its original frozen attribution
   even when the current Goal episode/source has changed. Original execution
   authority is checked separately; no DATA recovery grants source authority. *)
let retained_associated_child_update (state : Session_state.t) ~reference ~origin =
  let module Origin = Agent_store.Delegation_goal_origin in
  let module G = Goal_descendants in
  let open Result.Let_syntax in
  let%bind accounting =
    Result.of_option
      state.goal_descendants
      ~error:(error Conflict "retained associated child has no existing descendant roots")
  in
  let%bind children =
    Result.of_option
      state.child_contributions
      ~error:(error Conflict "retained associated child has no child carrier")
  in
  match
    List.find (Origin.scopes origin) ~f:(fun scope ->
      Agent_protocol.Session_ref.equal (Origin.Scope.owner scope) (G.session accounting))
  with
  | None -> G.register_child accounting ~children ~reference ~origin
  | Some scope ->
    G.register_retained_branch accounting ~children ~scope ~reference ~origin
;;

let retained_child_frontier_complete (state : Session_state.t) ~reference ~origin =
  let module Origin = Agent_store.Delegation_goal_origin in
  let module G = Goal_descendants in
  let%map.Result registered = retained_child_origin_slot state ~reference ~origin in
  registered
  && (Origin.equal origin Origin.unrelated
      || Option.exists state.goal_descendants ~f:(fun accounting ->
        List.for_all (Origin.scopes origin) ~f:(fun scope ->
          (not
             (Agent_protocol.Session_ref.equal
                (Origin.Scope.owner scope)
                (G.session accounting)))
          || List.exists
               (G.branches accounting ~goal_id:(Origin.Scope.goal_id scope))
               ~f:(fun branch ->
                 Origin.Scope.equal scope (G.Branch.scope branch)
                 && Agent_store.Delegation_store.Reference.equal
                      reference
                      (G.Branch.reference branch)))))
;;

let check_retained_child_frontier t ~reference ~origin =
  let module Origin = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  let%bind _registered = retained_child_origin_slot t.state ~reference ~origin in
  if Origin.equal origin Origin.unrelated
  then Ok ()
  else
    Result.map (retained_associated_child_update t.state ~reference ~origin) ~f:(fun _ ->
      ())
;;

let capture_child_origin_reservation_internal
      t
      ~source_owner
      ~bound
      ~reference
      ~native_callback
  =
  let module D = Agent_store.Delegation_store in
  let open Result.Let_syntax in
  let%bind basis = capture_child_accounting_basis t ~source_owner in
  let%bind () =
    if
      Agent_protocol.Id.Session.equal
        reference.D.Reference.key.parent_session_id
        t.state.identity.session_id
      && Int.equal reference.key.parent_generation t.state.identity.generation
    then Ok ()
    else Error (error Conflict "child reservation belongs to another parent generation")
  in
  let%bind () =
    Option.value_map bound ~default:(Ok ()) ~f:(fun (bound : Child_origin.Bound.t) ->
      if
        phys_equal bound.preparation.issuing_actor t.inference_owner_identity
        && Int.equal bound.preparation.domain (Stdlib.Domain.self () :> int)
        && D.Key.equal bound.key reference.key
        && Agent_protocol.Id.Session.equal
             bound.child_session_id
             reference.child_session_id
      then Child_origin.Bound.check_current bound
      else Error (error Conflict "child reservation differs from actual birth custody"))
  in
  let%map execution =
    Option.value_map native_callback ~default:(Ok None) ~f:(fun borrowed ->
      child_installation_native_execution t borrowed |> Result.map ~f:Option.some)
  in
  Child_origin.Captured_reservation.
    { basis; reference; bound; native_callback; execution }
;;

(* Wrapper-only Store traversal: never called by a mailbox handler. The actual
   immutable State/controller came from Capture_reservation, not caller DATA. *)
let observe_child_origin_reservation_external
      t
      (captured : Child_origin.Captured_reservation.t)
  =
  let open Result.Let_syntax in
  let%bind () = check_child_accounting_capture t captured.basis in
  let native_registration =
    Option.value_map captured.execution ~default:(Ok None) ~f:(fun execution ->
      let%map current =
        authorized_native_child_basis t (Inference_invocation execution)
      in
      Some
        Child_origin.Native_registration.
          { execution
          ; preparation = current.selected.execution.preparation
          ; check_current = current.check_current
          })
  in
  let%bind () = check_child_accounting_capture t captured.basis in
  let%bind native_registration = native_registration in
  let record =
    Recurrence_controller.resolve_delegation captured.basis.controller captured.reference
  in
  let%bind () = check_child_accounting_capture t captured.basis in
  let%bind record = record in
  (* A concurrent canonical ACK can make Store selection of the captured State
     fail. Classify that stale capture before interpreting the Store result;
     unchanged captures retain the original Store error. *)
  let current =
    Recurrence_controller.observe captured.basis.controller captured.basis.state
  in
  let%bind () = check_child_accounting_capture t captured.basis in
  let%map current = current in
  Child_origin.Observed_reservation.{ captured; record; current; native_registration }
;;

let check_child_origin_reservation_observation
      t
      (observed : Child_origin.Observed_reservation.t)
  =
  let module D = Agent_store.Delegation_store in
  let module Origin = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  let captured = observed.captured in
  let%bind () = check_child_accounting_basis t captured.basis ~current:observed.current in
  let%bind () =
    if D.Reference.equal captured.reference (D.reference observed.record)
    then Ok ()
    else Error (error Conflict "child reservation lower reference changed")
  in
  let record = observed.record in
  let%bind origin =
    Result.of_option
      record.admission.goal_origin
      ~error:
        (error Conflict "historical child origin cannot be reclassified during retry")
  in
  let%bind () =
    if
      Option.is_none record.revocation
      && Agent_protocol.Id.Prompt_revision.equal
           record.admission.parent_revision_id
           t.state.spec.prompt_revision_id
    then Ok ()
    else Error (error Conflict "child reservation is revoked or parent source changed")
  in
  let%map () =
    match captured.bound with
    | None -> check_retained_child_frontier t ~reference:captured.reference ~origin
    | Some bound ->
      if
        Agent_protocol.Id.Transaction.equal
          bound.transaction_id
          record.admission.transaction_id
        && Origin.equal bound.origin origin
      then Child_origin.Bound.check_current bound
      else
        Error (error Conflict "private lower admission differs from actual birth binding")
  in
  origin
;;

let observe_child_origin_reservation_internal t observed =
  let open Result.Let_syntax in
  let%map origin = check_child_origin_reservation_observation t observed in
  let captured = observed.Child_origin.Observed_reservation.captured in
  Child_origin.Reservation.
    { issuing_actor = captured.basis.issuing_actor
    ; domain = captured.basis.domain
    ; controller = captured.basis.controller
    ; source_owner = captured.basis.source_owner
    ; reference = captured.reference
    ; origin
    ; bound = captured.bound
    }
;;

let register_child_origin_reservation_internal
      t
      ~(reservation : Child_origin.Reservation.t)
      ~(observed : Child_origin.Observed_reservation.t)
      ~native_callback
      ~check_parent
  =
  let module G = Goal_descendants in
  let module Origin = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  let source_owner = reservation.source_owner in
  let%bind controller = child_accounting_owner t ~source_owner in
  let%bind () =
    if
      phys_equal reservation.issuing_actor t.inference_owner_identity
      && Int.equal reservation.domain (Stdlib.Domain.self () :> int)
      && Recurrence_controller.same_store controller reservation.controller
    then Ok ()
    else Error (error Conflict "child reservation belongs to another Actor/Store")
  in
  let check_observation () =
    let%bind () = check_parent t.state in
    let%bind origin = check_child_origin_reservation_observation t observed in
    if
      Agent_store.Delegation_store.Reference.equal
        reservation.reference
        observed.captured.reference
      && Agent_store.Delegation_goal_origin.equal reservation.origin origin
      && Option.equal phys_equal reservation.bound observed.captured.bound
    then Ok ()
    else
      Error (error Conflict "child reservation observation differs from original custody")
  in
  let%bind () = check_observation () in
  let execution =
    Option.map observed.native_registration ~f:(fun native ->
      native.Child_origin.Native_registration.execution)
  in
  let native_preparation =
    Option.bind observed.native_registration ~f:(fun native ->
      native.Child_origin.Native_registration.preparation)
  in
  let before = t.state in
  let check () =
    let%bind () = check_observation () in
    let%bind () =
      match native_callback, execution, observed.native_registration with
      | None, None, None -> Ok ()
      | Some borrowed, Some selected, Some current ->
        let%bind actual = child_installation_native_execution t borrowed in
        if phys_equal selected actual
        then current.Child_origin.Native_registration.check_current ()
        else Error (error Conflict "child reservation native owner was replaced")
      | None, (Some _ | None), (Some _ | None) | Some _, (Some _ | None), (Some _ | None)
        -> Error (error Conflict "child reservation native selection is incomplete")
    in
    if phys_equal before t.state
    then Ok ()
    else Error (error Conflict "child reservation parent snapshot changed")
  in
  let%bind () = check () in
  let%bind already_registered =
    match reservation.bound with
    | None ->
      retained_child_frontier_complete
        before
        ~reference:reservation.reference
        ~origin:reservation.origin
    | Some _ -> Ok false
  in
  if already_registered
  then Ok ()
  else (
    let%bind update =
      match before.goal_descendants, before.child_contributions with
      | None, children ->
        if Origin.equal reservation.origin Origin.unrelated
        then
          G.register_first_unrelated_child
            ~host_profile:t.services.goal_descendant_profile
            ~session:(Recurrence_controller.session controller)
            ~reference:reservation.reference
            ~children
            ~ledger:before.inference_ledger
        else
          Error (error Conflict "associated child has no existing descendant component")
      | Some _, Some _
        when Option.is_none reservation.bound
             && not (Origin.equal reservation.origin Origin.unrelated) ->
        retained_associated_child_update
          before
          ~reference:reservation.reference
          ~origin:reservation.origin
      | Some accounting, Some children ->
        let local_scope =
          List.find (Origin.scopes reservation.origin) ~f:(fun scope ->
            Agent_protocol.Session_ref.equal
              (Origin.Scope.owner scope)
              (G.session accounting))
        in
        (match local_scope with
         | None ->
           G.register_child
             accounting
             ~children
             ~reference:reservation.reference
             ~origin:reservation.origin
         | Some scope ->
           G.register_branch
             accounting
             ~children
             ~scope
             ~reference:reservation.reference
             ~origin:reservation.origin)
      | Some _, None -> Error (error Conflict "descendant component has no child carrier")
    in
    install_child_accounting_delta
      t
      ~execution
      ~native_preparation
      ~check
      ~delta:(Session_delta.Goal_descendants_changed update))
;;

let register_child_installation_internal
      ?native_callback
      t
      ~source_owner
      ~(child : Child_installation.t)
      ~check_parent
      ~max_children
      ~max_encoded_bytes
  =
  let module D = Agent_store.Delegation_store in
  let open Result.Let_syntax in
  let%bind controller = child_accounting_owner t ~source_owner in
  let%bind () =
    if
      Runtime_source_owner.matches source_owner child.source_owner
      && Recurrence_controller.same_store controller child.controller
      && Agent_protocol.Id.Session.equal
           child.reference.key.parent_session_id
           t.state.identity.session_id
      && Int.equal child.reference.key.parent_generation t.state.identity.generation
    then Ok ()
    else Error (error Conflict "child installation belongs to another parent/Store")
  in
  let%bind () = check_parent t.state in
  let%bind () = child.check_current () in
  let%bind record = Recurrence_controller.resolve_delegation controller child.reference in
  let%bind () =
    if
      Agent_protocol.Id.Prompt_revision.equal
        record.admission.parent_revision_id
        t.state.spec.prompt_revision_id
      && Option.is_none record.revocation
      &&
      match record.stage with
      | Child_installed | Linked -> true
      | Reserved | Artifact_installed -> false
    then Ok ()
    else Error (error Conflict "child installation parent source or record changed")
  in
  let%bind execution =
    match native_callback with
    | None -> Ok None
    | Some borrowed ->
      child_installation_native_execution t borrowed |> Result.map ~f:Option.some
  in
  let%bind native_current =
    match execution with
    | None -> Ok None
    | Some execution ->
      authorized_native_child_basis t (Inference_invocation execution)
      |> Result.map ~f:Option.some
  in
  let before = t.state in
  let%bind children =
    Child_accounting.register
      before
      ~reference:child.reference
      ~max_children
      ~max_encoded_bytes
  in
  let check () =
    let%bind _ = child_accounting_owner t ~source_owner in
    let%bind () = check_parent t.state in
    let%bind () = child.check_current () in
    let%bind () =
      match native_callback, execution, native_current with
      | None, None, None -> Ok ()
      | Some borrowed, Some selected, Some current ->
        let%bind actual = child_installation_native_execution t borrowed in
        if phys_equal selected actual
        then current.check_current ()
        else Error (error Conflict "child installation native owner was replaced")
      | None, (Some _ | None), (Some _ | None) | Some _, (Some _ | None), (Some _ | None)
        -> Error (error Conflict "child installation native selection is incomplete")
    in
    if phys_equal before t.state
    then Ok ()
    else Error (error Conflict "child installation parent snapshot changed")
  in
  let%bind () = check () in
  let%bind changed = child_contributions_changed before children in
  if not changed
  then Ok ()
  else
    install_child_accounting_delta
      t
      ~execution
      ~native_preparation:
        (Option.bind native_current ~f:(fun current ->
           current.selected.execution.preparation))
      ~check
      ~delta:(Session_delta.Child_contributions_changed children)
;;

(* Authorizers are the existing current read policy. As elsewhere in the
   factual readers, these callbacks must be
   nonyielding; Store observation remains an explicit yielding phase. *)
let child_usage_original actor =
  if
    Operator_authorization.is_current actor
    && Agent_protocol.Principal.has_scope
         (Operator_authorization.principal actor)
         View_session_transcript
  then Ok ()
  else Error (error Permission_denied "child usage read authority is no longer current")
;;

let child_usage_read t ~source_owner ~actor ~authorize =
  let open Result.Let_syntax in
  let%bind _ = child_accounting_owner t ~source_owner in
  let%bind () = child_usage_original actor in
  let%bind () = authorize t.state in
  let%bind _ = child_accounting_owner t ~source_owner in
  child_usage_original actor
;;

let observe_child_usage_internal t ~source_owner ~actor ~authorize ~reference =
  let module D = Agent_store.Delegation_store in
  let open Result.Let_syntax in
  let association () =
    let%bind _ = child_accounting_owner t ~source_owner in
    if
      Agent_protocol.Id.Session.equal
        t.state.identity.session_id
        reference.D.Reference.child_session_id
      && Agent_protocol.Id.Prompt_revision.equal
           t.state.spec.prompt_revision_id
           reference.revision_id
      && Option.exists t.state.spec.delegation ~f:(D.Reference.equal reference)
    then Ok ()
    else Error (error Conflict "child usage source differs from its actual Spec")
  in
  let refresh_read () =
    let%bind () = child_usage_read t ~source_owner ~actor ~authorize in
    let%bind () = association () in
    let state = t.state in
    let%bind controller = child_accounting_owner t ~source_owner in
    let%bind _ = Recurrence_controller.resolve_delegation controller reference in
    let%bind current = Recurrence_controller.observe controller state in
    let check () =
      let%bind () = child_usage_original actor in
      let%bind () = association () in
      if phys_equal state t.state && Recurrence_controller.is_current current
      then Ok ()
      else Error (error Conflict "child usage read basis changed before import")
    in
    let%bind () = child_usage_read t ~source_owner ~actor ~authorize in
    let%map () = check () in
    check
  in
  let%bind check = refresh_read () in
  let state = t.state in
  let%bind snapshot = Child_accounting.snapshot state in
  let%bind () = check () in
  let%map controller = child_accounting_owner t ~source_owner in
  Child_usage_observation.
    { controller
    ; source_owner = Runtime_source_owner.identity source_owner
    ; reference
    ; snapshot
    ; refresh_read
    }
;;

let plan_child_usage_import (before : Session_state.t) ~children ~snapshot =
  let open Result.Let_syntax in
  match snapshot, before.goal_descendants with
  | None, _ ->
    Ok
      ( children
      , Child_usage_import.Historical_absence
      , Session_delta.Child_contributions_changed children )
  | Some snapshot, None ->
    let%map children, disposition = Child_contributions.replace children ~snapshot in
    ( children
    , Child_usage_import.Imported disposition
    , Session_delta.Child_contributions_changed children )
  | Some snapshot, Some accounting ->
    let%bind registered = child_contributions_changed before children in
    let%map update, disposition =
      Goal_descendants.import_with_disposition accounting ~children ~snapshot
    in
    let next =
      match Goal_descendants.Update.children update with
      | Preserve -> children
      | Replace next -> next
    in
    let delta = Session_delta.Goal_descendants_changed update in
    let delta =
      if registered
      then Session_delta.Batch [ Child_contributions_changed children; delta ]
      else delta
    in
    next, Child_usage_import.Imported disposition, delta
;;

let import_child_usage_internal
      t
      ~source_owner
      ~actor
      ~authorize
      ~(observation : Child_usage_observation.t)
      ~max_children
      ~max_encoded_bytes
  =
  let open Result.Let_syntax in
  let%bind () = child_usage_read t ~source_owner ~actor ~authorize in
  let%bind controller = child_accounting_owner t ~source_owner in
  let%bind () =
    if
      Runtime_source_owner.matches source_owner observation.source_owner
      && Recurrence_controller.same_store controller observation.controller
      && Agent_protocol.Id.Session.equal
           observation.reference.key.parent_session_id
           t.state.identity.session_id
      && not
           (Agent_protocol.Id.Session.equal
              observation.reference.child_session_id
              t.state.identity.session_id)
    then Ok ()
    else Error (error Conflict "child usage observation belongs to another parent/Store")
  in
  (* Refresh visibility over the SAME actual child, without changing the older
     acknowledged snapshot. This calls no other Actor mailbox and acquires no
     Registry/Owner lock; explicit Store observation remains outside their locks. *)
  let%bind child_current = observation.refresh_read () in
  let%bind _ =
    Recurrence_controller.resolve_delegation controller observation.reference
  in
  let before = t.state in
  let%bind parent_current = Recurrence_controller.observe controller before in
  let%bind children =
    Child_accounting.register
      before
      ~reference:observation.reference
      ~max_children
      ~max_encoded_bytes
  in
  let%bind children, result, delta =
    plan_child_usage_import before ~children ~snapshot:observation.snapshot
  in
  let%bind () = child_usage_read t ~source_owner ~actor ~authorize in
  let check () =
    let%bind _ = child_accounting_owner t ~source_owner in
    let%bind () = child_usage_original actor in
    let%bind () = child_current () in
    if phys_equal before t.state && Recurrence_controller.is_current parent_current
    then Ok ()
    else Error (error Conflict "child usage import parent basis changed")
  in
  let%bind () = check () in
  let%bind changed = child_contributions_changed before children in
  if not changed
  then Ok result
  else (
    let%map _ = transition ~check_before_commit:check t ~delta ~payloads:[] in
    result)
;;

(* Birth facts retain actual callback ACK custody without asking whether a
   fresh Goal count/token admission would now be eligible. *)
let child_origin_factual_native_registration t borrowed =
  let open Result.Let_syntax in
  let%bind execution = child_installation_native_execution t borrowed in
  let%bind selected = native_child_basis t (Inference_invocation execution) in
  let check_current () =
    let%bind actual = child_installation_native_execution t borrowed in
    if phys_equal actual execution
    then native_child_basis t (Inference_invocation actual) |> Result.map ~f:ignore
    else Error (error Conflict "birth usage native callback owner was replaced")
  in
  let%map () = check_current () in
  Child_origin.Native_registration.
    { execution; preparation = selected.execution.preparation; check_current }
;;

let capture_child_origin_usage_internal
      t
      ~(reservation : Child_origin.Reservation.t)
      ~native_callback
  =
  let open Result.Let_syntax in
  let%bind basis =
    capture_child_accounting_basis t ~source_owner:reservation.source_owner
  in
  let%bind () =
    if
      Int.equal reservation.domain (Stdlib.Domain.self () :> int)
      && Recurrence_controller.same_store basis.controller reservation.controller
    then Ok ()
    else Error (error Conflict "birth usage belongs to another Factory/Store/domain")
  in
  let%map native_registration =
    Option.value_map native_callback ~default:(Ok None) ~f:(fun borrowed ->
      child_origin_factual_native_registration t borrowed |> Result.map ~f:Option.some)
  in
  Child_origin_usage.{ basis; reservation; native_registration }
;;

let observe_child_origin_usage_external
      t
      (captured : Child_origin_usage.captured)
      ~child_current
  =
  let%map.Result record, current =
    observe_child_accounting_source
      t
      captured.basis
      ~reference:captured.reservation.reference
  in
  Child_origin_usage.{ captured; record; current; child_current }
;;

let check_child_origin_usage_observation t (observed : Child_origin_usage.observed) =
  let module D = Agent_store.Delegation_store in
  let module O = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  let captured = observed.captured in
  let%bind () = check_child_accounting_basis t captured.basis ~current:observed.current in
  if
    D.Reference.equal captured.reservation.reference (D.reference observed.record)
    && Option.exists
         observed.record.admission.goal_origin
         ~f:(O.equal captured.reservation.origin)
  then Ok ()
  else Error (error Conflict "birth usage private lower identity/origin changed")
;;

let check_child_origin_usage_source t (observed : Child_origin_usage.observed) =
  let module D = Agent_store.Delegation_store in
  let module O = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  let%bind () = check_child_origin_usage_observation t observed in
  let reference = observed.captured.reservation.reference in
  if
    Agent_protocol.Id.Session.equal reference.child_session_id t.state.identity.session_id
    && Agent_protocol.Id.Prompt_revision.equal
         reference.revision_id
         t.state.spec.prompt_revision_id
    && Option.exists t.state.spec.delegation ~f:(D.Reference.equal reference)
    && Option.exists t.state.goal_descendants ~f:(fun accounting ->
      Agent_protocol.Session_ref.equal
        (Goal_descendants.session accounting)
        (Recurrence_controller.session observed.captured.basis.controller)
      && Option.exists
           (Goal_descendants.origin accounting)
           ~f:(O.equal observed.captured.reservation.origin))
    && Option.is_none observed.child_current
    && Option.is_none observed.captured.native_registration
  then Ok ()
  else Error (error Conflict "birth usage differs from actual child Spec/accounting")
;;

let observe_child_origin_usage_internal t observed ~refresh_read =
  let open Result.Let_syntax in
  let%bind () = check_child_origin_usage_source t observed in
  let%bind snapshot =
    Child_accounting.snapshot observed.Child_origin_usage.captured.basis.state
  in
  let%bind () =
    if Option.is_some snapshot
    then Ok ()
    else Error (error Conflict "known child birth has no actual usage snapshot")
  in
  let%map () = check_child_origin_usage_source t observed in
  let captured = observed.captured in
  Child_usage_observation.
    { controller = captured.basis.controller
    ; source_owner = Runtime_source_owner.identity captured.basis.source_owner
    ; reference = captured.reservation.reference
    ; snapshot
    ; refresh_read
    }
;;

let import_child_origin_usage_internal
      t
      (observed : Child_origin_usage.observed)
      ~(observation : Child_usage_observation.t)
      ~check_parent
  =
  let open Result.Let_syntax in
  let captured = observed.captured in
  let reservation = captured.reservation in
  let before = t.state in
  let check () =
    let%bind () = check_child_origin_usage_observation t observed in
    let%bind () = check_parent t.state in
    let%bind () =
      if
        phys_equal reservation.issuing_actor t.inference_owner_identity
        && Agent_protocol.Id.Session.equal
             reservation.reference.key.parent_session_id
             t.state.identity.session_id
        && Runtime_source_owner.matches
             captured.basis.source_owner
             observation.source_owner
        && Recurrence_controller.same_store
             captured.basis.controller
             observation.controller
        && Agent_store.Delegation_store.Reference.equal
             reservation.reference
             observation.reference
      then Ok ()
      else Error (error Conflict "birth usage import differs from actual parent/child")
    in
    let%bind complete =
      retained_child_frontier_complete
        t.state
        ~reference:reservation.reference
        ~origin:reservation.origin
    in
    let%bind () =
      if complete
      then Ok ()
      else
        Error (error Conflict "birth usage import has no acknowledged complete frontier")
    in
    let%bind () =
      Option.value_map
        observed.child_current
        ~default:
          (Error (error Conflict "birth usage import has no actual child observation"))
        ~f:(fun check -> check ())
    in
    let%bind () =
      Option.value_map captured.native_registration ~default:(Ok ()) ~f:(fun native ->
        native.Child_origin.Native_registration.check_current ())
    in
    if phys_equal before t.state
    then Ok ()
    else Error (error Conflict "birth usage import parent State changed")
  in
  let%bind () = check () in
  let%bind children =
    Result.of_option
      before.child_contributions
      ~error:(error Conflict "birth usage import has no acknowledged child carrier")
  in
  let%bind children, result, delta =
    plan_child_usage_import before ~children ~snapshot:observation.snapshot
  in
  let%bind changed = child_contributions_changed before children in
  if not changed
  then Ok result
  else (
    let execution =
      Option.map captured.native_registration ~f:(fun native ->
        native.Child_origin.Native_registration.execution)
    in
    let native_preparation =
      Option.bind captured.native_registration ~f:(fun native ->
        native.Child_origin.Native_registration.preparation)
    in
    let%map () =
      install_child_accounting_delta t ~execution ~native_preparation ~check ~delta
    in
    result)
;;

let descendant_components (state : Session_state.t) =
  let open Result.Let_syntax in
  let%bind accounting =
    Result.of_option
      state.goal_descendants
      ~error:(error Permission_denied "actual descendant component is absent")
  in
  let%map children =
    Result.of_option
      state.child_contributions
      ~error:(error Permission_denied "actual descendant child frontier is absent")
  in
  accounting, children
;;

let descendant_route_actor t ~factual (route : Descendant_admission_data.Root_route.t) =
  let open Result.Let_syntax in
  let%bind controller = child_accounting_owner t ~source_owner:route.source_owner in
  if
    Int.equal route.domain (Stdlib.Domain.self () :> int)
    && Recurrence_controller.same_store controller route.controller
    && Agent_protocol.Session_ref.equal
         (Recurrence_controller.session controller)
         (Agent_store.Delegation_goal_origin.Scope.owner
            (Goal_descendant_root_route.scope route.association))
    && (factual || phys_equal route.root_issuer t.inference_owner_identity)
  then Ok ()
  else Error (error Conflict "descendant route differs from its actual root owner")
;;

let descendant_route_data state (route : Descendant_admission_data.Root_route.t) =
  let%bind.Result accounting, children = descendant_components state in
  Goal_descendant_root_route.validate route.association ~accounting ~children
;;

let descendant_root_account state scope =
  let open Result.Let_syntax in
  let id = Agent_store.Delegation_goal_origin.Scope.goal_id scope in
  let%bind goal =
    Option.bind state.Session_state.goal_catalog ~f:(fun catalog ->
      Goal_catalog.find catalog id)
    |> Result.of_option ~error:(error Invalid_state "actual root Goal is absent")
  in
  let%bind document =
    Option.bind state.goal_accounts ~f:(fun accounts -> Goal_accounts.find accounts id)
    |> Result.of_option ~error:(error Invalid_state "actual root account is absent")
  in
  let%map account =
    Goal_accounting_document.resolve document ~goal ~ledger:state.inference_ledger
  in
  goal, account
;;

(* Only genuinely new authenticated begin chooses/replaces current cell.
   Old reservations/refreshes never call this function. Registry is <=max_roots. *)
let descendant_policy_for_begin t ~goal_id ~now =
  let existing =
    List.find t.descendant_policy_cells ~f:(fun policy ->
      Agent_protocol.Id.Goal.equal (Goal_root_policy.goal_id policy) goal_id)
  in
  match existing with
  | Some policy when Result.is_ok (Goal_root_policy.fresh policy ~state:t.state ~now) ->
    Ok policy
  | None | Some _ ->
    Option.iter existing ~f:Goal_root_policy.retire;
    let%map.Result policy = Goal_root_policy.create t.state ~goal_id in
    t.descendant_policy_cells
    <- policy
       :: List.filter t.descendant_policy_cells ~f:(fun old ->
         not (Agent_protocol.Id.Goal.equal (Goal_root_policy.goal_id old) goal_id));
    policy
;;

let check_descendant_ack = Goal_descendant_admission_custody.check_descendant_ack

let descendant_confirmation_import =
  Goal_descendant_admission_custody.descendant_confirmation_import
;;

let check_descendant_confirmation =
  Goal_descendant_admission_custody.check_descendant_confirmation
;;

(* Current admitted ownership/policy is independent of unrelated State progress.
   It never replaces the reservation's retained cell or redoes fresh capacity. *)
let check_descendant_admitted_owner
      t
      (reservation : Descendant_admission_data.Reservation.t)
      acknowledgement
      confirmation
  =
  let open Result.Let_syntax in
  let%bind () = descendant_route_actor t ~factual:false reservation.route in
  let%bind () = descendant_route_data t.state reservation.route in
  let%bind () = Descendant_preparation.check_owner reservation.preparation in
  let%bind () = check_descendant_confirmation reservation acknowledgement confirmation in
  Goal_root_policy.admitted reservation.policy ~state:t.state ~now:(t.services.now ())
;;

let check_descendant_admitted_capture_owner
      t
      (captured :
        Descendant_admission_data.Root_admitted.t Descendant_root_request.capture)
  =
  let open Result.Let_syntax in
  let%bind () = check_child_accounting_identity t captured.basis in
  let%bind () =
    Recurrence_controller.check_retained_available captured.basis.controller
  in
  match captured.operation with
  | Refresh_admitted (reservation, acknowledgement, confirmation) ->
    check_descendant_admitted_owner t reservation acknowledgement confirmation
;;

let descendant_admitted_capture_state t captured =
  let%map.Result () = check_descendant_admitted_capture_owner t captured in
  if phys_equal captured.Descendant_root_request.basis.state t.state
  then Descendant_root_request.Admitted_refresh.Current ()
  else State_changed
;;

(* Store errors and private ancestry changes remain failures. Only a successful
   read whose actual owner/policy is still current can report State_changed. *)
let observe_descendant_admitted_root
      t
      (captured :
        Descendant_admission_data.Root_admitted.t Descendant_root_request.capture)
  =
  let module D = Agent_store.Delegation_store in
  let module Q = Descendant_root_request in
  let open Result.Let_syntax in
  let rec records = function
    | [] -> Ok (Q.Admitted_refresh.Current ())
    | expected :: rest ->
      let%bind () = check_descendant_admitted_capture_owner t captured in
      let result =
        Recurrence_controller.resolve_delegation
          captured.basis.controller
          (D.reference expected)
      in
      let%bind () = check_descendant_admitted_capture_owner t captured in
      let%bind actual = result in
      let%bind () =
        if
          D.equal_record actual expected
          && Option.is_none actual.revocation
          && D.equal_stage actual.stage Linked
        then Ok ()
        else Error (error Conflict "descendant actual private ancestry changed")
      in
      let%bind status = descendant_admitted_capture_state t captured in
      (match status with
       | State_changed -> Ok Q.Admitted_refresh.State_changed
       | Current () -> records rest)
  in
  let%bind status = records captured.records in
  match status with
  | State_changed -> Ok Q.Admitted_refresh.State_changed
  | Current () ->
    let result =
      Recurrence_controller.observe captured.basis.controller captured.basis.state
    in
    let%bind () = check_descendant_admitted_capture_owner t captured in
    let%bind current = result in
    let%bind owner =
      Recurrence_controller.retain_owner captured.basis.controller current
    in
    let%map status = descendant_admitted_capture_state t captured in
    (match status with
     | State_changed -> Q.Admitted_refresh.State_changed
     | Current () -> Q.Admitted_refresh.Current { Q.Admitted_observed.captured; owner })
;;

(* These are association/currentness checks, never an execution grant. The
   concrete native Plan remains responsible for original/effect admission. *)
let check_causal_reservation_set (set : causal_reservation_set) =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () = C.Set.check_claim set.native_set in
  if
    List.equal
      phys_equal
      set.native_set.attempts
      (List.map set.actual_attempts ~f:(fun attempt -> attempt.native_attempt))
    && List.for_all set.actual_attempts ~f:(fun attempt ->
      phys_equal attempt.native_attempt.set_identity set.native_set.identity
      && phys_equal attempt.native_attempt.route attempt.route.native
      && phys_equal attempt.route.observation.captured.reservations set)
  then Ok ()
  else Error (error Conflict "causal actual/native attempt retention differs")
;;

let causal_route_slot t preparation reservations =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () =
    C.Preparation.check_owner preparation ~issuer:t.inference_owner_identity
  in
  let%bind () = check_causal_reservation_set reservations in
  let%bind slot =
    match t.governed_admission_slot with
    | Some (Policy_causal { causal = slot; _ } | Combined { causal = slot; _ }) -> Ok slot
    | None | Some (Descendant _) ->
      Error (error Conflict "causal routes have no actual occupied canonical slot")
  in
  let%bind () = C.Slot.check_open slot ~issuer:t.inference_owner_identity in
  if
    phys_equal slot.preparation preparation
    && phys_equal slot.reservations reservations.native_set
    && phys_equal reservations.native_set.preparation preparation
  then Ok ()
  else Error (error Conflict "causal routes belong to another preparation or Set")
;;

let check_causal_route_capture (captured : causal_route_capture) =
  let open Result.Let_syntax in
  let%bind () = check_child_accounting_capture captured.callee captured.basis in
  let%bind () =
    check_child_accounting_capture captured.callee captured.preparation.basis
  in
  causal_route_slot captured.callee captured.preparation captured.reservations
;;

let check_causal_route_observation (observed : causal_route_observation) =
  let%bind.Result () = check_causal_route_capture observed.captured in
  if Recurrence_controller.is_current observed.current
  then Ok ()
  else Error (error Conflict "causal route callee lifecycle observation changed")
;;

let capture_causal_routes t ~source_owner ~preparation ~reservations ~callee_ancestry =
  let module C = Goal_causal_admission_custody in
  let module PC = Policy_canonical_usage in
  let module Cause = Policy_cause_data in
  let open Result.Let_syntax in
  let%bind () = causal_route_slot t preparation reservations in
  let%bind () = check_child_accounting_capture t preparation.C.Preparation.basis in
  let%bind basis = capture_child_accounting_basis t ~source_owner in
  let%bind () =
    if
      Runtime_source_owner.matches
        source_owner
        (Runtime_source_owner.identity preparation.basis.source_owner)
      && phys_equal basis.controller preparation.basis.controller
    then Ok ()
    else Error (error Conflict "causal route preparation has another Factory or Store")
  in
  let%bind frozen = C.Set.frozen reservations.native_set in
  let%bind current_source = observation_source t in
  let%bind prefix = policy_native_prefix t.state ~current_source in
  let%bind member =
    Cause.Allocation_work.member preparation.work ~generation:t.state.identity.generation
  in
  let%bind actual = PC.Source.cause t.state.policy_canonical_usage ~prefix ~member in
  let%bind cause =
    match actual with
    | Some cause when Cause.Key.equal (Cause.key cause) preparation.cause -> Ok cause
    | None | Some _ ->
      Error (error Conflict "causal route lost its exact actual native Cause membership")
  in
  let%bind ancestry =
    match callee_ancestry with
    | None -> Ok None
    | Some ancestry ->
      if Delegation_authority.Checked_ancestry.issued_by ancestry ~source_owner
      then Ok (Some (Delegation_authority.Checked_ancestry.records ancestry))
      else Error (error Conflict "causal route suffix has another private issuer")
  in
  let%map calculation =
    Goal_causal_root_route.capture
      cause
      ~selection:frozen.selection
      ~callee_delegation:t.state.spec.delegation
      ~callee_ancestry:ancestry
  in
  { callee = t; basis; preparation; reservations; calculation }
;;

(* No Actor/Owner/Registry lock is held while these real Controller reads yield.
   Every edge is observed, even if no target requires a remote reservation. *)
let observe_causal_route_records ~controller ~calculation ~check ~expected =
  let module D = Agent_store.Delegation_store in
  let open Result.Let_syntax in
  let%bind reversed =
    List.fold_result
      (Goal_causal_root_route.references calculation)
      ~init:[]
      ~f:(fun records reference ->
        let result = Recurrence_controller.resolve_delegation controller reference in
        let%bind () = check () in
        let%map actual = result in
        actual :: records)
  in
  let records = List.rev reversed in
  let%bind () = Goal_causal_root_route.validate_records calculation ~records in
  let%map () =
    match expected with
    | None -> Ok ()
    | Some expected ->
      if List.equal D.equal_record expected records
      then Ok ()
      else Error (error Conflict "causal route actual private records changed")
  in
  records
;;

let observe_causal_routes_external (captured : causal_route_capture) =
  let open Result.Let_syntax in
  let check () = check_causal_route_capture captured in
  let%bind () = check () in
  let%bind records =
    observe_causal_route_records
      ~controller:captured.basis.controller
      ~calculation:captured.calculation
      ~check
      ~expected:None
  in
  let result =
    Recurrence_controller.observe captured.basis.controller captured.basis.state
  in
  let%bind () = check () in
  let%bind current = result in
  let%map () = check_child_accounting_basis captured.callee captured.basis ~current in
  { captured; records; current }
;;

let causal_route_owners (observation : causal_route_observation) =
  Goal_causal_root_route.targets observation.captured.calculation
  |> List.fold ~init:[] ~f:(fun owners target ->
    let owner =
      Policy_cause_data.Goal_target.owner (Goal_causal_root_route.Target.target target)
    in
    if List.mem owners owner ~equal:Agent_protocol.Session_ref.equal
    then owners
    else owner :: owners)
  |> List.rev
;;

let consume_causal_routes t (observed : causal_route_observation) =
  let open Result.Let_syntax in
  let%bind () =
    if phys_equal t observed.captured.callee
    then Ok ()
    else Error (error Conflict "causal route observation belongs to another callee Actor")
  in
  let%bind () = check_causal_route_observation observed in
  let reservations = observed.captured.reservations in
  match reservations.association with
  | None ->
    let retained = Some { observation = observed; bound_roots = [] } in
    reservations.association <- retained;
    Ok observed
  | Some retained ->
    let%bind () = check_causal_route_observation retained.observation in
    if
      phys_equal retained.observation.captured.preparation observed.captured.preparation
      && phys_equal
           retained.observation.captured.basis.state
           observed.captured.basis.state
      && List.equal
           Agent_store.Delegation_store.equal_record
           retained.observation.records
           observed.records
    then Ok retained.observation
    else
      Error
        (error Conflict "causal Set cannot mix or replace consumed route observations")
;;

let capture_causal_root t ~source_owner (observation : causal_route_observation) =
  let open Result.Let_syntax in
  let%bind () = check_causal_route_observation observation in
  let%bind root_basis = capture_child_accounting_basis t ~source_owner in
  let%map () =
    if
      Runtime_source_owner.matches
        source_owner
        (Runtime_source_owner.identity observation.captured.basis.source_owner)
      && Recurrence_controller.same_store
           root_basis.controller
           observation.captured.basis.controller
    then Ok ()
    else Error (error Conflict "causal root has another actual Factory or Store")
  in
  { root_basis; observation }
;;

let check_causal_root_capture t (captured : causal_root_capture) =
  let open Result.Let_syntax in
  let%bind () = check_child_accounting_capture t captured.root_basis in
  check_causal_route_observation captured.observation
;;

let observe_causal_root_external t (captured : causal_root_capture) =
  let open Result.Let_syntax in
  let check () = check_causal_root_capture t captured in
  let%bind () = check () in
  let%bind _ =
    observe_causal_route_records
      ~controller:captured.root_basis.controller
      ~calculation:captured.observation.captured.calculation
      ~check
      ~expected:(Some captured.observation.records)
  in
  let result =
    Recurrence_controller.observe captured.root_basis.controller captured.root_basis.state
  in
  let%bind () = check () in
  let%bind current_root = result in
  let%map () = check_child_accounting_basis t captured.root_basis ~current:current_root in
  { captured_root = captured; current_root }
;;

let consume_causal_root t (observed : causal_root_observed) =
  let module C = Goal_causal_admission_custody in
  let module R = Goal_causal_root_route in
  let module Cause = Policy_cause_data in
  let open Result.Let_syntax in
  let captured = observed.captured_root in
  let observation = captured.observation in
  let%bind () = check_causal_root_capture t captured in
  let%bind () =
    check_child_accounting_basis t captured.root_basis ~current:observed.current_root
  in
  let session = Recurrence_controller.session captured.root_basis.controller in
  let%bind selected =
    R.select
      observation.captured.calculation
      ~records:observation.records
      ~session
      ~generation:t.state.identity.generation
      ~delegation:t.state.spec.delegation
      ~catalog:t.state.goal_catalog
      ~descendants:t.state.goal_descendants
      ~children:t.state.child_contributions
  in
  let routes =
    List.filter_map selected ~f:(fun selected ->
      let target = R.Target.target selected in
      match R.Target.coverage selected with
      | Covered_local | Covered_physical -> None
      | Causal_overlay ->
        if
          Agent_protocol.Session_ref.equal
            session
            (Recurrence_controller.session observation.captured.basis.controller)
        then None
        else (
          let evidence =
            match R.Target.evidence selected with
            | Caller_local -> C.Route.Caller_local
            | Inherited_scope scope -> Inherited_scope scope
            | Forwarded forwarding -> Forwarded forwarding
          in
          let native : C.Route.t =
            { preparation = observation.captured.preparation
            ; owner = Cause.Goal_target.owner target
            ; target
            ; evidence
            ; controller = captured.root_basis.controller
            ; root_issuer = t.inference_owner_identity
            ; source_owner = captured.root_basis.source_owner
            ; domain = captured.root_basis.domain
            ; records = observation.records
            }
          in
          Some { root_actor = t; observation; native }))
  in
  let%bind association =
    Result.of_option
      observation.captured.reservations.association
      ~error:(error Conflict "causal owner binding has no consumed route association")
  in
  let%bind () =
    if phys_equal association.observation observation
    then Ok ()
    else
      Error
        (error Conflict "causal owner binding belongs to another consumed observation")
  in
  let%bind owner =
    Recurrence_controller.retain_owner
      captured.root_basis.controller
      observed.current_root
  in
  let bound =
    { root_actor = t; root_basis = captured.root_basis; retained_owner = owner }
  in
  let expected = causal_route_owners observation in
  let existing =
    List.find association.bound_roots ~f:(fun root ->
      Agent_protocol.Session_ref.equal
        session
        (Recurrence_controller.session root.root_basis.controller))
  in
  let%bind next =
    match existing with
    | Some actual ->
      if
        phys_equal actual.root_actor t
        && phys_equal actual.root_basis.controller captured.root_basis.controller
        && phys_equal actual.root_basis.issuing_actor captured.root_basis.issuing_actor
        && Recurrence_controller.Retained_owner.is_current actual.retained_owner
      then Ok association.bound_roots
      else Error (error Conflict "causal bound owner was displaced or retired")
    | None ->
      (match List.nth expected (List.length association.bound_roots) with
       | Some next when Agent_protocol.Session_ref.equal next session ->
         Ok (association.bound_roots @ [ bound ])
       | Some _ | None ->
         Error (error Conflict "causal owner binding is not the next unique actual owner"))
  in
  association.bound_roots <- next;
  Ok routes
;;

let causal_reservation_route
  : type outcome. outcome causal_reservation_operation -> causal_root_route
  = function
  | Begin_causal_reservation (route, _) -> route
  | Commit_causal_reservation attempt -> attempt.route
  | Refresh_causal_reservation reservation -> reservation.actual_attempt.route
;;

let check_causal_root_route t (route : causal_root_route) =
  let open Result.Let_syntax in
  let%bind controller =
    child_accounting_owner t ~source_owner:route.native.source_owner
  in
  let%bind () = check_causal_route_observation route.observation in
  if
    phys_equal route.root_actor t
    && phys_equal route.native.root_issuer t.inference_owner_identity
    && Int.equal route.native.domain (Stdlib.Domain.self () :> int)
    && phys_equal route.native.controller controller
    && phys_equal route.native.preparation route.observation.captured.preparation
    && Runtime_source_owner.matches
         route.native.source_owner
         (Runtime_source_owner.identity route.observation.captured.basis.source_owner)
    && Recurrence_controller.same_store
         controller
         route.observation.captured.basis.controller
  then Ok ()
  else Error (error Conflict "causal reservation route has another actual root or Store")
;;

let capture_causal_reservation
  : type outcome.
    t
    -> outcome causal_reservation_operation
    -> (outcome causal_reservation_capture, Agent_protocol.Error.t) result
  =
  fun t operation ->
  let open Result.Let_syntax in
  let route = causal_reservation_route operation in
  let%bind () = check_causal_root_route t route in
  let%bind () =
    match operation with
    | Begin_causal_reservation (route, reservations) ->
      let%bind () = check_causal_reservation_set reservations in
      let%bind _ =
        Goal_causal_admission_custody.Set.next_request
          reservations.native_set
          route.native
      in
      if phys_equal route.observation.captured.reservations reservations
      then Ok ()
      else Error (error Conflict "causal Begin has another actual reservation Set")
    | Commit_causal_reservation attempt ->
      let%bind () =
        check_causal_reservation_set route.observation.captured.reservations
      in
      if
        List.mem
          route.observation.captured.reservations.actual_attempts
          attempt
          ~equal:phys_equal
        && phys_equal attempt.native_attempt.route route.native
        && phys_equal attempt.native_attempt.basis.state t.state
        &&
        match attempt.native_attempt.phase with
        | Begun -> true
        | Writer_prepared _ | Reserved _ | Not_reserved _ -> false
      then Ok ()
      else
        Error (error Conflict "causal commit has no same unattempted original root basis")
    | Refresh_causal_reservation reservation ->
      let attempt = reservation.actual_attempt in
      let%bind () =
        check_causal_reservation_set route.observation.captured.reservations
      in
      if
        List.mem
          route.observation.captured.reservations.actual_attempts
          attempt
          ~equal:phys_equal
        && phys_equal attempt.native_attempt.route route.native
        &&
        match attempt.native_attempt.phase with
        | Reserved actual -> phys_equal actual reservation.native_reservation
        | Begun | Writer_prepared _ | Not_reserved _ -> false
      then Ok ()
      else Error (error Conflict "causal refresh has no same installed root reservation")
  in
  let%map reservation_basis =
    capture_child_accounting_basis t ~source_owner:route.native.source_owner
  in
  { reservation_basis; reservation_operation = operation }
;;

let check_causal_reservation_capture t (captured : _ causal_reservation_capture) =
  let open Result.Let_syntax in
  let%bind () = check_child_accounting_capture t captured.reservation_basis in
  check_causal_root_route t (causal_reservation_route captured.reservation_operation)
;;

let observe_causal_reservation_external t (captured : _ causal_reservation_capture) =
  let open Result.Let_syntax in
  let check () = check_causal_reservation_capture t captured in
  let route = causal_reservation_route captured.reservation_operation in
  let%bind () = check () in
  let%bind _ =
    observe_causal_route_records
      ~controller:captured.reservation_basis.controller
      ~calculation:route.observation.captured.calculation
      ~check
      ~expected:(Some route.observation.records)
  in
  let result =
    Recurrence_controller.observe
      captured.reservation_basis.controller
      captured.reservation_basis.state
  in
  let%bind () = check () in
  let%bind reservation_current = result in
  let%map () =
    check_child_accounting_basis t captured.reservation_basis ~current:reservation_current
  in
  { captured_reservation = captured; reservation_current }
;;

let causal_attempt_owner t (attempt : causal_reservation_attempt) =
  let native = attempt.native_attempt in
  if
    Int.equal native.route.domain (Stdlib.Domain.self () :> int)
    && phys_equal attempt.route.root_actor t
    && phys_equal native.route attempt.route.native
    && phys_equal native.route.root_issuer t.inference_owner_identity
  then (
    let reservations = attempt.route.observation.captured.reservations in
    let%bind.Result () = check_causal_reservation_set reservations in
    if List.mem reservations.actual_attempts attempt ~equal:phys_equal
    then Ok ()
    else Error (error Conflict "causal reservation is not retained by its actual Set"))
  else Error (error Conflict "causal reservation belongs to another actual Actor/domain")
;;

let causal_reserved (attempt : causal_reservation_attempt) native_reservation =
  { native_reservation; actual_attempt = attempt }
;;

let causal_attempt_result t (attempt : causal_reservation_attempt) =
  let open Result.Let_syntax in
  let%bind () = causal_attempt_owner t attempt in
  match attempt.native_attempt.phase with
  | Begun -> Ok None
  | Reserved reservation -> Ok (Some (Reserved (causal_reserved attempt reservation)))
  | Writer_prepared _ -> Ok (Some (Attempt_unconfirmed attempt))
  | Not_reserved (Blocked availability) -> Ok (Some (Blocked availability))
  | Not_reserved (Rejected_before_writer (write, _)) ->
    Session_commit_attempt.unresolved write.writer
  | Not_reserved (Policy_hold_acknowledged _) ->
    Error (error Permission_denied "current root Goal policy holds causal admission")
;;

let causal_root_write_of_acknowledgement acknowledgement =
  let module C = Goal_causal_admission_custody in
  let previous, candidate, writer =
    match acknowledgement with
    | Causal_reserved plan ->
      let write = C.Reserve_install.write plan in
      write.previous, write.candidate, write.writer
    | Causal_held plan ->
      let write = C.Hold_install.write plan in
      write.previous, write.candidate, write.writer
    | Causal_terminal { plan; _ } ->
      let write = C.Terminal_install.write plan in
      write.operation.previous, write.operation.candidate, write.operation.writer
  in
  { acknowledgement; previous; candidate; writer }
;;

let settle_causal_root_no_writer t (owned : causal_root_write) =
  let module C = Goal_causal_admission_custody in
  if
    Option.exists t.causal_root_write ~f:(phys_equal owned)
    && Session_commit_attempt.no_writer owned.writer
  then (
    let result =
      match owned.acknowledgement with
      | Causal_reserved plan -> C.Reserve_install.reject_before_writer plan
      | Causal_held plan -> C.Hold_install.reject_before_writer plan
      | Causal_terminal { plan; _ } -> C.Terminal_install.reject_before_writer plan
    in
    match result with
    | Ok () -> t.causal_root_write <- None
    | Error _ -> ())
;;

(* Only an actual authenticated finite root operation constructs this closed
   plan. Existing install/persist is the sole canonical writer; no host executor. *)
let install_causal_root_write t observed ~attempt ~acknowledgement ~hold =
  let open Result.Let_syntax in
  let owned = causal_root_write_of_acknowledgement acknowledgement in
  let%bind () =
    if Option.is_none t.causal_root_write && phys_equal owned.previous t.state
    then Ok ()
    else Error (error Conflict "causal root already retains a canonical writer")
  in
  t.causal_root_write <- Some owned;
  let final () =
    let%bind () = check_causal_reservation_capture t observed.captured_reservation in
    let%bind () =
      check_child_accounting_basis
        t
        observed.captured_reservation.reservation_basis
        ~current:observed.reservation_current
    in
    let%bind () = Causal_root_custody.check_owner t owned in
    let%bind decision =
      Goal_root_policy.Causal.before_reserve
        attempt.native_attempt.policy
        ~state:t.state
        ~now:(t.services.now ())
    in
    match decision, hold with
    | Decided Allow, None -> Ok ()
    | Decided (Hold actual), Some expected
      when Agent_protocol.Goal.Hold.equal actual expected -> Ok ()
    | Decided _, _ | Deferred _, _ ->
      Error (error Permission_denied "root causal policy changed before actual writer")
  in
  match
    Session_commit_attempt.perform owned.writer (fun () ->
      install
        ~causal_root_acknowledgement:owned
        ?admission_hold:
          (Option.map hold ~f:(fun _ ->
             Goal_root_policy.goal_id attempt.native_attempt.policy))
        ~check_before_commit:final
        t
        owned.candidate)
  with
  | Ok () -> Ok ()
  | Error _ as failure ->
    settle_causal_root_no_writer t owned;
    failure
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    settle_causal_root_no_writer t owned;
    Exn.raise_with_original_backtrace exn backtrace
;;

let hold_causal_reservation t observed attempt reason =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind delta =
    Goal_charge_admission.hold_delta
      t.state
      ~goal_id:(Goal_root_policy.goal_id attempt.native_attempt.policy)
      ~reason
  in
  let%bind () =
    match delta with
    | None -> Ok ()
    | Some delta ->
      let%bind candidate = prepare_transition t ~delta ~payloads:[] in
      let%bind plan =
        C.Hold_install.prepare
          attempt.native_attempt
          ~issuer:t.inference_owner_identity
          ~previous:t.state
          ~candidate
      in
      install_causal_root_write
        t
        observed
        ~attempt
        ~acknowledgement:(Causal_held plan)
        ~hold:(Some reason)
  in
  Error (error Permission_denied "current root Goal policy holds causal admission")
;;

let commit_causal_reservation t observed attempt =
  let module C = Goal_causal_admission_custody in
  let module Book = Goal_policy_contributions in
  let open Result.Let_syntax in
  let%bind retained = causal_attempt_result t attempt in
  match retained with
  | Some retained -> Ok retained
  | None ->
    let%bind () =
      if Option.is_none t.causal_root_write
      then Ok ()
      else Error (error Conflict "root canonical writer is retained by another operation")
    in
    let%bind decision =
      Goal_root_policy.Causal.before_reserve
        attempt.native_attempt.policy
        ~state:t.state
        ~now:(t.services.now ())
    in
    (match decision with
     | Decided (Hold reason) -> hold_causal_reservation t observed attempt reason
     | Deferred reason ->
       let availability =
         match reason with
         | Goal_admission_policy.Deferred.Reserved ->
           Goal_admission_policy.Count_availability.Reserved
         | Unknown -> Unknown
       in
       attempt.native_attempt.phase <- C.Remote.Not_reserved (Blocked availability);
       Ok (Blocked availability)
     | Decided Allow ->
       let%bind reserved =
         Book.reserve
           t.state.goal_policy_contributions
           ~owner:attempt.native_attempt.route.owner
           ~request:attempt.native_attempt.request
       in
       (match reserved with
        | Already_pending _ | Busy _ ->
          attempt.native_attempt.phase <- C.Remote.Not_reserved (Blocked Reserved);
          Ok (Blocked Reserved)
        | Reserved (update, _) ->
          let%bind candidate =
            prepare_transition
              t
              ~delta:(Session_delta.Goal_policy_contributions_changed update)
              ~payloads:[]
          in
          let%bind plan =
            C.Reserve_install.prepare
              attempt.native_attempt
              ~issuer:t.inference_owner_identity
              ~previous:t.state
              ~candidate
          in
          let%bind () =
            install_causal_root_write
              t
              observed
              ~attempt
              ~acknowledgement:(Causal_reserved plan)
              ~hold:None
          in
          let%bind retained = causal_attempt_result t attempt in
          Result.of_option
            retained
            ~error:(error Invalid_state "root causal reserve ACK was not retained")))
;;

let check_causal_pending t (reservation : causal_reservation) =
  let module C = Goal_causal_admission_custody in
  let module Book = Goal_policy_contributions in
  let open Result.Let_syntax in
  let%bind () = causal_attempt_owner t reservation.actual_attempt in
  let native = reservation.native_reservation in
  let%bind () =
    match reservation.actual_attempt.native_attempt.phase with
    | C.Remote.Reserved actual when phys_equal actual native -> Ok ()
    | Begun | Writer_prepared _ | Reserved _ | Not_reserved _ ->
      Error (error Conflict "causal pending has no same installed reservation ACK")
  in
  let%bind actual =
    Book.reserve
      t.state.goal_policy_contributions
      ~owner:native.attempt.route.owner
      ~request:native.attempt.request
  in
  match actual with
  | Already_pending pending when Book.Pending.equal pending native.pending -> Ok ()
  | Already_pending _ | Busy _ | Reserved _ ->
    Error (error Conflict "causal actual pending differs from exact owned reservation")
;;

let refresh_causal_reserved t observed reservation =
  let open Result.Let_syntax in
  let%bind () = check_causal_pending t reservation in
  let%bind policy =
    Goal_root_policy.Causal.reserved_before_writer
      reservation.native_reservation.attempt.policy
      ~state:t.state
      ~now:(t.services.now ())
  in
  let%bind () =
    match policy with
    | Allow -> Ok ()
    | Hold _ ->
      Error (error Permission_denied "root policy holds reserved causal admission")
  in
  let%map root_owner =
    Recurrence_controller.retain_owner
      observed.captured_reservation.reservation_basis.controller
      observed.reservation_current
  in
  { reservation; root_owner }
;;

(* Covered/inline owners have no remote reservation, so their actual successful
   finite binding is retained on SAME Set rather than erased by request filtering. *)
let check_causal_route_association (reservations : causal_reservation_set) =
  let module R = Goal_causal_root_route in
  let open Result.Let_syntax in
  let%bind association =
    Result.of_option
      reservations.association
      ~error:(error Conflict "causal inference has no consumed route association")
  in
  let observation = association.observation in
  let captured = observation.captured in
  let%bind () = check_child_accounting_capture captured.callee captured.basis in
  let%bind () =
    check_child_accounting_capture captured.callee captured.preparation.basis
  in
  let%bind () =
    if
      phys_equal captured.reservations reservations
      && Recurrence_controller.is_current observation.current
    then Ok ()
    else
      Error
        (error Conflict "causal route association lost its SAME Set or observed owner")
  in
  let expected = causal_route_owners observation in
  let actual =
    List.map association.bound_roots ~f:(fun root ->
      Recurrence_controller.session root.root_basis.controller)
  in
  let%bind () =
    if List.equal Agent_protocol.Session_ref.equal expected actual
    then Ok ()
    else
      Error
        (error
           Conflict
           "causal inference requires all actual bound owners, including covered targets")
  in
  List.fold_result
    association.bound_roots
    ~init:()
    ~f:(fun () (root : causal_bound_root) ->
      let%bind controller =
        child_accounting_owner root.root_actor ~source_owner:root.root_basis.source_owner
      in
      let%bind () =
        if
          Int.equal root.root_basis.domain (Stdlib.Domain.self () :> int)
          && phys_equal
               root.root_basis.issuing_actor
               root.root_actor.inference_owner_identity
          && phys_equal controller root.root_basis.controller
          && Runtime_source_owner.matches
               root.root_basis.source_owner
               (Runtime_source_owner.identity captured.basis.source_owner)
          && Recurrence_controller.same_store controller captured.basis.controller
          && Recurrence_controller.Retained_owner.is_current root.retained_owner
        then Ok ()
        else
          Error
            (error Conflict "causal bound root lost its actual Factory/controller owner")
      in
      R.select
        captured.calculation
        ~records:observation.records
        ~session:(Recurrence_controller.session controller)
        ~generation:root.root_actor.state.identity.generation
        ~delegation:root.root_actor.state.spec.delegation
        ~catalog:root.root_actor.state.goal_catalog
        ~descendants:root.root_actor.state.goal_descendants
        ~children:root.root_actor.state.child_contributions
      |> Result.map ~f:ignore)
;;

(* Complete only the SAME frozen request vector. Views are issued by actual
   root refresh; this assembler cannot create a pending or reserve acknowledgement. *)
let check_causal_before_writer (before : causal_before_writer) =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () = check_causal_reservation_set before.reservations in
  let%bind () = check_causal_route_association before.reservations in
  let%bind () =
    if phys_equal before.preparation before.reservations.native_set.preparation
    then Ok ()
    else Error (error Conflict "causal prewriter belongs to another actual preparation")
  in
  let rec check
            (attempts : causal_reservation_attempt list)
            (views : causal_root_before_writer list)
    =
    match attempts, views with
    | [], [] -> Ok ()
    | attempt :: attempts, view :: views ->
      let reservation = view.reservation in
      let%bind () =
        if
          phys_equal attempt reservation.actual_attempt
          && Recurrence_controller.Retained_owner.is_current view.root_owner
        then Ok ()
        else Error (error Conflict "causal prewriter root vector is displaced or stale")
      in
      let root = attempt.route.root_actor in
      let%bind () = check_causal_pending root reservation in
      let%bind policy =
        Goal_root_policy.Causal.reserved_before_writer
          reservation.native_reservation.attempt.policy
          ~state:root.state
          ~now:(root.services.now ())
      in
      let%bind () =
        match policy with
        | Allow -> Ok ()
        | Hold _ ->
          Error (error Permission_denied "causal reserved root policy holds inference")
      in
      check attempts views
    | [], _ :: _ | _ :: _, [] ->
      Error (error Conflict "causal prewriter requires the complete ordered root vector")
  in
  let%bind () = check before.reservations.actual_attempts before.roots in
  match before.reservations.native_set.phase with
  | C.Set.Complete _ | Acquiring _ -> Ok ()
  | Unselected -> Error (error Conflict "causal prewriter has no frozen actual selection")
;;

let prepare_causal_before_writer ~preparation ~reservations ~views =
  let before = { preparation; reservations; roots = views } in
  let open Result.Let_syntax in
  let%bind () = check_causal_before_writer before in
  let%bind association =
    Result.of_option
      reservations.association
      ~error:(error Conflict "causal prewriter has no actual consumed association")
  in
  let%bind () =
    causal_route_slot association.observation.captured.callee preparation reservations
  in
  let%map () = Goal_causal_admission_custody.Set.complete reservations.native_set in
  before
;;

let consume_causal_reservation
  : type outcome.
    t -> outcome causal_reservation_observed -> (outcome, Agent_protocol.Error.t) result
  =
  fun t observed ->
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let captured = observed.captured_reservation in
  let%bind () = check_causal_reservation_capture t captured in
  let%bind () =
    check_child_accounting_basis
      t
      captured.reservation_basis
      ~current:observed.reservation_current
  in
  match captured.reservation_operation with
  | Begin_causal_reservation (route, reservations) ->
    let%bind () = check_causal_reservation_set reservations in
    let%bind request = C.Set.next_request reservations.native_set route.native in
    let%bind _ =
      Goal_causal_root_route.select
        route.observation.captured.calculation
        ~records:route.observation.records
        ~session:(Recurrence_controller.session captured.reservation_basis.controller)
        ~generation:t.state.identity.generation
        ~delegation:t.state.spec.delegation
        ~catalog:t.state.goal_catalog
        ~descendants:t.state.goal_descendants
        ~children:t.state.child_contributions
    in
    let%bind policy =
      descendant_policy_for_begin
        t
        ~goal_id:(Policy_cause_data.Goal_target.goal_id route.native.target)
        ~now:(t.services.now ())
    in
    let native_attempt : C.Remote.attempt =
      { identity = ref ()
      ; set_identity = reservations.native_set.identity
      ; route = route.native
      ; basis = captured.reservation_basis
      ; policy
      ; request
      ; phase = Begun
      }
    in
    let attempt = { native_attempt; route; initial_import = None } in
    (* Both vectors and all native checks are prepared before the first mutation.
       No allocation, check, await or reply separates these two assignments. *)
    let next_native = reservations.native_set.attempts @ [ native_attempt ] in
    let next_actual = reservations.actual_attempts @ [ attempt ] in
    reservations.native_set.attempts <- next_native;
    reservations.actual_attempts <- next_actual;
    (Ok attempt : (outcome, Agent_protocol.Error.t) result)
  | Commit_causal_reservation attempt -> commit_causal_reservation t observed attempt
  | Refresh_causal_reservation reservation ->
    refresh_causal_reserved t observed reservation
;;

(* Actual canonical ACKs remain factual source custody after their original
   runtime/permission/slot retires. Only the real State-ACK issuer constructs the
   public opaque wrapper; these checks never renew an execution original. *)
let check_causal_canonical_acknowledgement
      (acknowledgement : causal_canonical_acknowledgement)
  =
  let module C = Goal_causal_admission_custody in
  let module PC = Policy_canonical_usage in
  let open Result.Let_syntax in
  let native = acknowledgement.native_acknowledgement in
  let%bind () =
    let slot = acknowledgement.canonical_slot in
    let%bind () =
      C.Slot.check_owner slot ~issuer:acknowledgement.callee.inference_owner_identity
    in
    match slot.phase with
    | (Acknowledged actual | Released (Confirmed (actual, _)))
      when phys_equal actual native -> Ok ()
    | Preparing | Writer_prepared _ | Acknowledged _ | Sealed _ | Released _ ->
      Error (error Conflict "causal canonical acknowledgement is not actually installed")
  in
  let preparation = native.preparation in
  let%bind () = check_causal_reservation_set acknowledgement.actual_reservations in
  let%bind frozen =
    match native.reservations.phase with
    | C.Set.Complete frozen -> Ok frozen
    | Unselected | Acquiring _ ->
      Error (error Conflict "causal usage acknowledgement has an incomplete actual Set")
  in
  let%bind () =
    if
      phys_equal
        preparation.basis.issuing_actor
        acknowledgement.callee.inference_owner_identity
      && phys_equal native.reservations acknowledgement.actual_reservations.native_set
      && phys_equal preparation native.reservations.preparation
      && phys_equal native.installed native.write.candidate.state
      && PC.Selection.equal native.write.selection frozen.selection
    then Ok ()
    else
      Error (error Conflict "causal usage has no same actual canonical acknowledgement")
  in
  let%bind _ =
    match native.write.canonical with
    | Goal_descendants.Canonical.Attempt _ ->
      Goal_descendants.Canonical.check
        ~before:native.write.previous.inference_ledger
        ~after:native.write.candidate.state.inference_ledger
        ~canonical:native.write.canonical
        ~occurrence:preparation.occurrence
    | Host_turn _ ->
      Error (error Conflict "causal usage acknowledgement is not an actual Attempt")
  in
  Ok ()
;;

let causal_usage_canonical = function
  | Canonical_causal_usage canonical | Imported_causal_usage { canonical; _ } -> canonical
;;

let causal_usage_streams source =
  let module C = Goal_causal_admission_custody in
  let module PC = Policy_canonical_usage in
  let module Book = Goal_policy_contributions in
  let open Result.Let_syntax in
  let canonical = causal_usage_canonical source in
  let%bind () = check_causal_canonical_acknowledgement canonical in
  let%bind streams =
    List.map
      canonical.actual_reservations.native_set.attempts
      ~f:(fun (attempt : C.Remote.attempt) ->
        match attempt.phase with
        | Reserved reservation ->
          Ok
            ( Book.Request.stream attempt.request
            , Book.Pending.next_prefix reservation.pending )
        | Begun | Writer_prepared _ | Not_reserved _ ->
          Error (error Conflict "causal source acknowledgement lost a reserved request"))
    |> Result.all
  in
  match source with
  | Canonical_causal_usage _ -> Ok streams
  | Imported_causal_usage { stream; _ } ->
    List.find streams ~f:(fun (actual, _) -> PC.Stream.equal stream actual)
    |> Result.of_option
         ~error:
           (error
              Conflict
              "imported causal source stream was not selected by its acknowledgement")
    |> Result.map ~f:List.return
;;

let capture_causal_usage t ~source_owner source =
  let open Result.Let_syntax in
  let%bind source_basis = Causal_factual_basis.capture t ~source_owner in
  let%bind () = check_causal_canonical_acknowledgement (causal_usage_canonical source) in
  let native = (causal_usage_canonical source).native_acknowledgement in
  let original = native.preparation.basis in
  let%map () =
    if
      Runtime_source_owner.matches
        source_owner
        (Runtime_source_owner.identity original.source_owner)
      && Recurrence_controller.same_store source_basis.controller original.controller
      && Agent_protocol.Session_ref.equal
           (Recurrence_controller.session source_basis.controller)
           (Recurrence_controller.session original.controller)
      && Agent_protocol.Id.Session.equal
           source_basis.state.identity.session_id
           native.installed.identity.session_id
      && Int64.(
           source_basis.state.counters.revision >= native.installed.counters.revision)
    then Ok ()
    else Error (error Conflict "causal factual source has another Factory/Store/session")
  in
  { source_actor = t; source_basis; source }
;;

let check_causal_usage_capture (captured : causal_usage_capture) =
  let%bind.Result () =
    Causal_factual_basis.check_capture captured.source_actor captured.source_basis
  in
  check_causal_canonical_acknowledgement (causal_usage_canonical captured.source)
;;

let observe_causal_usage_external (captured : causal_usage_capture) =
  let open Result.Let_syntax in
  let%bind () = check_causal_usage_capture captured in
  let result =
    Recurrence_controller.observe
      captured.source_basis.controller
      captured.source_basis.state
  in
  let%bind () = check_causal_usage_capture captured in
  let%bind source_current = result in
  let%bind () =
    Causal_factual_basis.check_current
      captured.source_actor
      captured.source_basis
      ~current:source_current
  in
  let%map source_owner =
    Recurrence_controller.retain_owner captured.source_basis.controller source_current
  in
  { source_capture = captured; source_current; source_owner }
;;

(* A successfully consumed opaque projection is an immutable factual capsule.
   Capture/consume still require exact current State; later imports do not erase
   this genuine snapshot merely because another metadata/usage ACK occurred. *)
let check_causal_usage_observation (observation : causal_usage_observation) =
  let open Result.Let_syntax in
  let captured = observation.source_capture in
  let basis = captured.source_basis in
  let canonical = causal_usage_canonical captured.source in
  let%bind controller =
    Causal_factual_basis.owner captured.source_actor ~source_owner:basis.source_owner
  in
  let%bind () = check_causal_canonical_acknowledgement canonical in
  if
    Int.equal basis.domain (Stdlib.Domain.self () :> int)
    && phys_equal basis.issuing_actor captured.source_actor.inference_owner_identity
    && phys_equal basis.controller controller
    && phys_equal captured.source_actor canonical.callee
    && Recurrence_controller.same_store
         controller
         canonical.native_acknowledgement.preparation.basis.controller
    && Agent_protocol.Session_ref.equal
         (Recurrence_controller.session controller)
         (Recurrence_controller.session
            canonical.native_acknowledgement.preparation.basis.controller)
    && Agent_protocol.Id.Session.equal
         basis.state.identity.session_id
         canonical.native_acknowledgement.installed.identity.session_id
    && Recurrence_controller.Retained_owner.is_current observation.source_owner
  then Ok ()
  else
    Error (error Conflict "causal factual capsule lost its actual source/Store/ACK owner")
;;

let consume_causal_usage t (observed : causal_usage_observed) =
  let module PC = Policy_canonical_usage in
  let open Result.Let_syntax in
  let captured = observed.source_capture in
  let%bind () =
    if phys_equal t captured.source_actor
    then Ok ()
    else Error (error Conflict "causal usage consume has another source Actor")
  in
  let%bind () = check_causal_usage_capture captured in
  let%bind () =
    Causal_factual_basis.check_current
      t
      captured.source_basis
      ~current:observed.source_current
  in
  let%bind accounting =
    Result.of_option
      captured.source_basis.state.policy_canonical_usage
      ~error:(error Conflict "acknowledged causal source accounting is unavailable")
  in
  let%bind () =
    if
      Agent_protocol.Session_ref.equal
        (PC.callee accounting)
        (Recurrence_controller.session captured.source_basis.controller)
    then Ok ()
    else Error (error Conflict "causal factual carrier has another full source session")
  in
  let%bind projections =
    PC.projections
      accounting
      ~ledger:captured.source_basis.state.inference_ledger
      ~session_revision:captured.source_basis.state.counters.revision
  in
  let%bind streams = causal_usage_streams captured.source in
  let%bind projections =
    List.map streams ~f:(fun (stream, prefix) ->
      let%bind.Result projection =
        List.find projections ~f:(fun projection ->
          PC.Stream.equal stream (PC.Projection.stream projection))
        |> Result.of_option
             ~error:
               (error
                  Conflict
                  "acknowledged causal stream is absent from actual inventory")
      in
      if Int64.(PC.Projection.admitted_attempts projection >= prefix)
      then Ok projection
      else Error (error Conflict "actual causal stream precedes its acknowledged prefix"))
    |> Result.all
  in
  let observation =
    { source_capture = captured; projections; source_owner = observed.source_owner }
  in
  let%map () = check_causal_usage_observation observation in
  observation
;;

let check_causal_initial_import (acknowledgement : causal_import_acknowledgement) =
  let module Book = Goal_policy_contributions in
  let open Result.Let_syntax in
  let native = acknowledgement.native_import in
  let reservation = acknowledgement.actual_reservation.native_reservation in
  let operation = native.operation in
  let%bind previous =
    Result.of_option
      operation.previous.goal_policy_contributions
      ~error:(error Conflict "initial causal acknowledgement has no previous Book")
  in
  let%bind pending =
    Book.reserve
      (Some previous)
      ~owner:reservation.attempt.route.owner
      ~request:reservation.attempt.request
  in
  let%bind () =
    match pending with
    | Already_pending actual when Book.Pending.equal actual reservation.pending -> Ok ()
    | Already_pending _ | Busy _ | Reserved _ ->
      Error (error Conflict "causal acknowledgement did not consume its original pending")
  in
  let%bind expected, disposition = Book.import previous ~projection:native.projection in
  let%bind () =
    match disposition with
    | Added -> Ok ()
    | Replaced | Duplicate | Stale ->
      Error (error Conflict "factual correction cannot issue initial causal confirmation")
  in
  let%bind actual =
    Result.of_option
      operation.candidate.state.goal_policy_contributions
      ~error:(error Conflict "initial causal acknowledgement has no installed Book")
  in
  let%bind repeated, disposition = Book.import actual ~projection:native.projection in
  let%bind () =
    match disposition with
    | Duplicate -> Ok ()
    | Added | Replaced | Stale ->
      Error (error Conflict "initial causal ACK is not its complete import fixed point")
  in
  let%bind repeated = Book.to_document (Book.Update.candidate repeated) in
  let%bind expected = Book.to_document (Book.Update.candidate expected) in
  let%bind actual = Book.to_document actual in
  if
    Document_schema.Json.equal
      (Document_schema.Document.json expected)
      (Document_schema.Document.json actual)
    && Document_schema.Json.equal
         (Document_schema.Document.json repeated)
         (Document_schema.Document.json actual)
  then Ok ()
  else
    Error
      (error Conflict "initial causal acknowledgement differs from actual complete Book")
;;

let causal_imported_usage_source (acknowledgement : causal_import_acknowledgement) =
  let module Book = Goal_policy_contributions in
  let module PC = Policy_canonical_usage in
  let open Result.Let_syntax in
  let reservation = acknowledgement.actual_reservation in
  let native = acknowledgement.native_import in
  let%bind () = check_causal_initial_import acknowledgement in
  let%bind () = check_causal_canonical_acknowledgement acknowledgement.canonical in
  let%bind () =
    check_causal_reservation_set
      reservation.actual_attempt.route.observation.captured.reservations
  in
  let stream = Book.Request.stream reservation.actual_attempt.native_attempt.request in
  let%map () =
    if
      phys_equal native.reservation reservation.native_reservation
      && phys_equal native.installed native.operation.candidate.state
      && phys_equal
           acknowledgement.canonical.actual_reservations
           reservation.actual_attempt.route.observation.captured.reservations
      && phys_equal
           acknowledgement.canonical.native_acknowledgement.preparation
           reservation.actual_attempt.native_attempt.route.preparation
      && PC.Stream.equal stream (PC.Projection.stream native.projection)
      && Int64.equal
           (PC.Projection.admitted_attempts native.projection)
           (Book.Pending.next_prefix reservation.native_reservation.pending)
    then Ok ()
    else
      Error
        (error Conflict "causal imported source is not its exact initial acknowledgement")
  in
  Imported_causal_usage { canonical = acknowledgement.canonical; stream }
;;

let check_causal_confirmation_import canonical attempt acknowledgement =
  let module PC = Policy_canonical_usage in
  let module GD = Goal_descendants in
  let open Result.Let_syntax in
  let%bind _ = causal_imported_usage_source acknowledgement in
  let%bind () =
    if
      phys_equal acknowledgement.canonical canonical
      && phys_equal acknowledgement.actual_reservation.actual_attempt attempt
    then Ok ()
    else Error (error Conflict "causal confirmation has another canonical ACK/attempt")
  in
  let%bind () =
    match attempt.native_attempt.phase with
    | Goal_causal_admission_custody.Remote.Reserved actual
      when phys_equal actual acknowledgement.actual_reservation.native_reservation ->
      Ok ()
    | Reserved _ | Begun | Writer_prepared _ | Not_reserved _ ->
      Error (error Conflict "causal confirmation lost its exact native reservation")
  in
  let%bind fact =
    GD.Canonical.check
      ~before:canonical.native_acknowledgement.write.previous.inference_ledger
      ~after:canonical.native_acknowledgement.installed.inference_ledger
      ~canonical:canonical.native_acknowledgement.write.canonical
      ~occurrence:canonical.native_acknowledgement.preparation.occurrence
  in
  match PC.Projection.head acknowledgement.native_import.projection with
  | Some head
    when Document_schema.Json.equal
           (GD.Canonical.Fact.to_json fact)
           (GD.Canonical.Fact.to_json (PC.Head.canonical head)) -> Ok ()
  | Some _ | None ->
    Error (error Conflict "causal confirmation has another actual canonical head")
;;

let causal_confirmation canonical ~imports =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () = check_causal_canonical_acknowledgement canonical in
  let attempts = canonical.actual_reservations.actual_attempts in
  let%bind () =
    if Int.equal (List.length attempts) (List.length imports)
    then Ok ()
    else Error (error Conflict "causal confirmation has another ordered import vector")
  in
  let%map () =
    List.map2_exn attempts imports ~f:(fun attempt acknowledgement ->
      check_causal_confirmation_import canonical attempt acknowledgement)
    |> Result.all_unit
  in
  let native_confirmation : C.Confirmation.t =
    { canonical = canonical.native_acknowledgement
    ; imports = List.map imports ~f:(fun acknowledgement -> acknowledgement.native_import)
    }
  in
  { native_confirmation; canonical; imports }
;;

let check_causal_confirmation canonical (confirmation : causal_confirmation) =
  let open Result.Let_syntax in
  let%bind () =
    if
      phys_equal canonical confirmation.canonical
      && phys_equal
           canonical.native_acknowledgement
           confirmation.native_confirmation.canonical
      && List.equal
           phys_equal
           confirmation.native_confirmation.imports
           (List.map confirmation.imports ~f:(fun acknowledgement ->
              acknowledgement.native_import))
    then Ok ()
    else Error (error Conflict "causal confirmation has another actual ACK/vector")
  in
  causal_confirmation canonical ~imports:confirmation.imports |> Result.map ~f:ignore
;;

let causal_terminal_reservation
  : type outcome. outcome causal_terminal_operation -> causal_reservation
  = function
  | Import_causal_usage (reservation, _) -> reservation
  | Close_causal_pending (reservation, _) -> reservation
  | Refresh_causal_admitted (reservation, _, _) -> reservation
  | Prepare_causal_correction (acknowledgement, _) -> acknowledgement.actual_reservation
;;

let causal_terminal_owner t (reservation : causal_reservation) =
  let open Result.Let_syntax in
  let%bind () = causal_attempt_owner t reservation.actual_attempt in
  let attempt = reservation.actual_attempt.native_attempt in
  let%bind () =
    match attempt.phase with
    | Reserved actual when phys_equal actual reservation.native_reservation -> Ok ()
    | Begun | Writer_prepared _ | Reserved _ | Not_reserved _ ->
      Error (error Conflict "causal terminal has another installed reservation")
  in
  let%bind controller =
    Causal_factual_basis.owner t ~source_owner:attempt.route.source_owner
  in
  if phys_equal controller attempt.route.controller
  then Ok ()
  else Error (error Conflict "causal terminal has another actual root controller")
;;

let causal_terminal_projection
      (reservation : causal_reservation)
      (observation : causal_usage_observation)
  =
  let module PC = Policy_canonical_usage in
  let open Result.Let_syntax in
  let%bind () = check_causal_usage_observation observation in
  let canonical = causal_usage_canonical observation.source_capture.source in
  let%bind () =
    if
      phys_equal
        canonical.actual_reservations
        reservation.actual_attempt.route.observation.captured.reservations
      && phys_equal
           canonical.native_acknowledgement.preparation
           reservation.actual_attempt.native_attempt.route.preparation
      && Recurrence_controller.same_store
           observation.source_capture.source_basis.controller
           reservation.actual_attempt.native_attempt.route.controller
    then Ok ()
    else
      Error (error Conflict "causal terminal source has another acknowledged Set/Store")
  in
  let stream =
    Goal_policy_contributions.Request.stream
      reservation.actual_attempt.native_attempt.request
  in
  List.find observation.projections ~f:(fun projection ->
    PC.Stream.equal stream (PC.Projection.stream projection))
  |> Result.of_option
       ~error:(error Conflict "causal terminal has no exact actual stream projection")
;;

let check_causal_closed
      (reservation : causal_reservation)
      (closed : causal_closed_before_writer)
  =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () =
    C.Slot.check_owner closed.slot ~issuer:closed.callee.inference_owner_identity
  in
  let%bind () = check_causal_reservation_set closed.actual_reservations in
  let%bind () =
    if
      phys_equal closed.slot.identity closed.native_closed.slot_identity
      && phys_equal closed.slot.preparation closed.native_closed.preparation
      && phys_equal closed.slot.reservations closed.actual_reservations.native_set
      && phys_equal
           closed.actual_reservations
           reservation.actual_attempt.route.observation.captured.reservations
      && phys_equal
           closed.native_closed.preparation
           reservation.actual_attempt.native_attempt.route.preparation
    then Ok ()
    else Error (error Conflict "causal close has another actual callee slot/Set/seal")
  in
  match closed.slot.phase with
  | (C.Slot.Sealed actual | Released (Unwritten actual))
    when phys_equal actual closed.native_closed -> Ok ()
  | Preparing | Writer_prepared _ | Acknowledged _ | Sealed _ | Released _ ->
    Error (error Conflict "causal close has no retained same-slot no-future-writer seal")
;;

let check_causal_terminal_operation
  : type outcome.
    t -> outcome causal_terminal_operation -> (unit, Agent_protocol.Error.t) result
  =
  fun t operation ->
  let open Result.Let_syntax in
  let reservation = causal_terminal_reservation operation in
  let%bind () =
    match operation with
    | Refresh_causal_admitted _ ->
      child_accounting_owner
        t
        ~source_owner:reservation.actual_attempt.native_attempt.route.source_owner
      |> Result.map ~f:ignore
    | Import_causal_usage _ | Prepare_causal_correction _ | Close_causal_pending _ ->
      Ok ()
  in
  let%bind () = causal_terminal_owner t reservation in
  match operation with
  | Import_causal_usage (_, observation) ->
    causal_terminal_projection reservation observation |> Result.map ~f:ignore
  | Prepare_causal_correction (acknowledgement, observation) ->
    let%bind () = check_causal_initial_import acknowledgement in
    let%bind _ = causal_imported_usage_source acknowledgement in
    causal_terminal_projection reservation observation |> Result.map ~f:ignore
  | Close_causal_pending (_, closed) -> check_causal_closed reservation closed
  | Refresh_causal_admitted (_, acknowledgement, confirmation) ->
    let%bind () = check_causal_confirmation acknowledgement confirmation in
    if
      List.exists confirmation.imports ~f:(fun imported ->
        phys_equal
          imported.actual_reservation.native_reservation
          reservation.native_reservation
        && phys_equal
             imported.actual_reservation.actual_attempt
             reservation.actual_attempt)
    then Ok ()
    else Error (error Conflict "admitted refresh has no same initial root confirmation")
;;

let capture_causal_terminal_basis
  : type outcome.
    t
    -> outcome causal_terminal_operation
    -> (Child_accounting_basis.t, Agent_protocol.Error.t) result
  =
  fun t operation ->
  let source_owner =
    (causal_terminal_reservation operation).actual_attempt.native_attempt.route
      .source_owner
  in
  match operation with
  | Refresh_causal_admitted _ -> capture_child_accounting_basis t ~source_owner
  | Import_causal_usage _ | Prepare_causal_correction _ | Close_causal_pending _ ->
    Causal_factual_basis.capture t ~source_owner
;;

let check_causal_terminal_basis
  : type outcome.
    t -> outcome causal_terminal_capture -> (unit, Agent_protocol.Error.t) result
  =
  fun t captured ->
  match captured.terminal_operation with
  | Refresh_causal_admitted _ -> check_child_accounting_capture t captured.terminal_basis
  | Import_causal_usage _ | Prepare_causal_correction _ | Close_causal_pending _ ->
    Causal_factual_basis.check_capture t captured.terminal_basis
;;

let check_causal_terminal_current
  : type outcome.
    t
    -> outcome causal_terminal_capture
    -> current:Recurrence_controller.observation
    -> (unit, Agent_protocol.Error.t) result
  =
  fun t captured ~current ->
  match captured.terminal_operation with
  | Refresh_causal_admitted _ ->
    check_child_accounting_basis t captured.terminal_basis ~current
  | Import_causal_usage _ | Prepare_causal_correction _ | Close_causal_pending _ ->
    Causal_factual_basis.check_current t captured.terminal_basis ~current
;;

let capture_causal_terminal t operation =
  let open Result.Let_syntax in
  let%bind () = check_causal_terminal_operation t operation in
  let%map terminal_basis = capture_causal_terminal_basis t operation in
  { terminal_basis; terminal_operation = operation }
;;

let check_causal_terminal_capture t (captured : _ causal_terminal_capture) =
  let open Result.Let_syntax in
  let%bind () = check_causal_terminal_basis t captured in
  check_causal_terminal_operation t captured.terminal_operation
;;

let observe_causal_terminal_external t (captured : _ causal_terminal_capture) =
  let open Result.Let_syntax in
  let%bind () = check_causal_terminal_capture t captured in
  let result =
    Recurrence_controller.observe
      captured.terminal_basis.controller
      captured.terminal_basis.state
  in
  let%bind () = check_causal_terminal_capture t captured in
  let%bind terminal_current = result in
  let%bind () = check_causal_terminal_current t captured ~current:terminal_current in
  let%map terminal_owner =
    Recurrence_controller.retain_owner captured.terminal_basis.controller terminal_current
  in
  { terminal_capture = captured; terminal_current; terminal_owner }
;;

let check_causal_terminal_context t (context : causal_terminal_context) =
  let open Result.Let_syntax in
  let%bind () =
    if
      phys_equal t context.terminal_actor
      && Int.equal context.terminal_basis.domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Conflict "causal terminal write has another Actor/domain")
  in
  let%bind () = Causal_factual_basis.check_capture t context.terminal_basis in
  let%bind () =
    if Recurrence_controller.Retained_owner.is_current context.terminal_owner
    then Ok ()
    else Error (error Conflict "causal terminal lost its retained root owner")
  in
  let%bind () = causal_terminal_owner t context.terminal_reservation in
  match context.terminal_purpose with
  | Initial_causal_import observation ->
    causal_terminal_projection context.terminal_reservation observation
    |> Result.map ~f:ignore
  | Factual_causal_correction { source_acknowledgement; observation } ->
    let%bind _ = causal_imported_usage_source source_acknowledgement in
    causal_terminal_projection context.terminal_reservation observation
    |> Result.map ~f:ignore
  | Causal_no_writer_close closed ->
    check_causal_closed context.terminal_reservation closed
;;

let causal_terminal_write t (owned : causal_root_write) =
  let open Result.Let_syntax in
  match owned.acknowledgement with
  | Causal_terminal { plan; context; _ } ->
    let%bind () = causal_terminal_owner t context.terminal_reservation in
    let native = Goal_causal_admission_custody.Terminal_install.write plan in
    if
      phys_equal native.operation.previous owned.previous
      && phys_equal native.operation.candidate owned.candidate
      && phys_equal native.operation.writer owned.writer
      && phys_equal context.terminal_actor t
    then Ok (native, context)
    else Error (error Conflict "causal terminal receipt has another actual writer")
  | Causal_reserved _ | Causal_held _ ->
    Error (error Conflict "causal terminal requires its exact terminal operation")
;;

let prepare_causal_terminal_write t observed ~reservation ~purpose ~kind ~update =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () =
    if Option.is_none t.causal_root_write
    then Ok ()
    else Error (error Conflict "causal root already retains a canonical writer")
  in
  let%bind candidate =
    prepare_transition
      t
      ~delta:(Session_delta.Goal_policy_contributions_changed update)
      ~payloads:[]
  in
  let context =
    { terminal_actor = t
    ; terminal_basis = observed.terminal_capture.terminal_basis
    ; terminal_owner = observed.terminal_owner
    ; terminal_reservation = reservation
    ; terminal_purpose = purpose
    }
  in
  let%bind () = check_causal_terminal_context t context in
  let%bind plan =
    C.Terminal_install.prepare
      reservation.native_reservation
      ~issuer:t.inference_owner_identity
      ~previous:t.state
      ~candidate
      ~kind
  in
  let initial_install =
    match purpose, kind with
    | ( Initial_causal_import observation
      , Goal_causal_admission_custody.Remote.Import projection ) ->
      let native_write = C.Terminal_install.write plan in
      let receipt =
        { operation = native_write.operation
        ; canonical = causal_usage_canonical observation.source_capture.source
        ; projection
        ; installed_ack = None
        }
      in
      let retained = Some receipt in
      Some
        { attempt = reservation.actual_attempt
        ; native_write
        ; initial_receipt = receipt
        ; retained
        }
    | (Factual_causal_correction _ | Causal_no_writer_close _), _ -> None
    | Initial_causal_import _, (Correction _ | Close _) ->
      invalid_arg "causal initial terminal plan has another kind"
  in
  let owned =
    causal_root_write_of_acknowledgement
      (Causal_terminal { plan; context; initial_install })
  in
  (* Retain before the prepare reply or first invocation; one existing fence. *)
  t.causal_root_write <- Some owned;
  Ok owned
;;

let commit_causal_terminal_write t (owned : causal_root_write) =
  let open Result.Let_syntax in
  let%bind _, context = causal_terminal_write t owned in
  let%bind () =
    if Session_commit_attempt.no_writer owned.writer
    then Session_commit_attempt.unresolved owned.writer
    else (
      match
        Session_commit_observation.outcome
          (Session_commit_attempt.observation owned.writer)
      with
      | Not_called -> Ok ()
      | In_progress | Returned _ | Raised _ ->
        Session_commit_attempt.unresolved owned.writer)
  in
  let final () =
    let%bind () = check_causal_terminal_context t context in
    Causal_root_custody.check_owner t owned
  in
  match
    Session_commit_attempt.perform owned.writer (fun () ->
      let%bind () = final () in
      install
        ~causal_root_acknowledgement:owned
        ~check_before_commit:final
        t
        owned.candidate)
  with
  | Ok () -> Ok ()
  | Error _ as failure ->
    settle_causal_root_no_writer t owned;
    failure
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    settle_causal_root_no_writer t owned;
    Exn.raise_with_original_backtrace exn backtrace
;;

let causal_native_import
      (reservation : causal_reservation)
      (canonical : causal_canonical_acknowledgement)
      (native : Goal_causal_admission_custody.Remote.import_ack)
  =
  let acknowledgement =
    { native_import = native; actual_reservation = reservation; canonical }
  in
  let%map.Result _ = causal_imported_usage_source acknowledgement in
  acknowledgement
;;

let causal_initial_result
      t
      (reservation : causal_reservation)
      (observation : causal_usage_observation)
  =
  let open Result.Let_syntax in
  let%bind () = causal_terminal_owner t reservation in
  let canonical = causal_usage_canonical observation.source_capture.source in
  match reservation.actual_attempt.initial_import with
  | Some receipt ->
    let%bind () =
      if phys_equal canonical receipt.canonical
      then Ok ()
      else Error (error Conflict "initial reconciliation has another canonical ACK")
    in
    let stream =
      Goal_policy_contributions.Request.stream
        reservation.actual_attempt.native_attempt.request
    in
    let%bind projection =
      List.find observation.projections ~f:(fun projection ->
        Policy_canonical_usage.Stream.equal
          stream
          (Policy_canonical_usage.Projection.stream projection))
      |> Result.of_option
           ~error:(error Conflict "initial reconciliation has no same stream observation")
    in
    let%bind () =
      if
        Document_schema.Json.equal
          (Policy_canonical_usage.Projection.to_json projection)
          (Policy_canonical_usage.Projection.to_json receipt.projection)
      then Ok ()
      else
        Error (error Conflict "initial reconciliation has another complete observation")
    in
    (match receipt.installed_ack with
     | Some (Goal_causal_admission_custody.Remote.Imported native)
       when phys_equal native.operation receipt.operation
            && phys_equal native.reservation reservation.native_reservation ->
       causal_native_import reservation canonical native
     | Some (Imported _ | Close_installed _) | None ->
       Error (error Conflict "retained initial receipt has no same actual State ACK"))
  | None ->
    (match reservation.native_reservation.terminal with
     | Goal_causal_admission_custody.Remote.Terminal_prepared write ->
       Session_commit_attempt.unresolved write.operation.writer
     | Settled Pending | Settled (Confirmed _ | No_writer_closed _) ->
       Error (error Conflict "causal initial import has no retained exact State ACK"))
;;

let causal_correction_result t owned =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind write, context = causal_terminal_write t owned in
  let%bind source_acknowledgement =
    match context.terminal_purpose with
    | Factual_causal_correction { source_acknowledgement; _ } -> Ok source_acknowledgement
    | Initial_causal_import _ | Causal_no_writer_close _ ->
      Error (error Conflict "correction reconciliation has another operation purpose")
  in
  match write.kind, write.acknowledged with
  | C.Remote.Correction _, Some (Imported native) ->
    if
      phys_equal native.operation write.operation
      && phys_equal native.reservation context.terminal_reservation.native_reservation
      && phys_equal native.installed write.operation.candidate.state
    then
      Ok
        (Correction_acknowledgement
           { native_import = native
           ; actual_reservation = context.terminal_reservation
           ; canonical = source_acknowledgement.canonical
           })
    else Error (error Conflict "correction ACK has another immutable operation receipt")
  | Correction _, None -> Session_commit_attempt.unresolved write.operation.writer
  | (Import _ | Close _), _ | Correction _, Some (Close_installed _) ->
    Error (error Conflict "correction requires its actual factual State ACK")
;;

let causal_book t =
  Result.of_option
    t.state.goal_policy_contributions
    ~error:(error Conflict "actual causal root Book is unavailable")
;;

let causal_import_usage t observed reservation observation =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  match reservation.native_reservation.terminal with
  | C.Remote.Settled (Confirmed _) -> causal_initial_result t reservation observation
  | Terminal_prepared write -> Session_commit_attempt.unresolved write.operation.writer
  | Settled (No_writer_closed _) ->
    Error (error Conflict "causal pending was factually closed")
  | Settled Pending ->
    let%bind projection = causal_terminal_projection reservation observation in
    let%bind book = causal_book t in
    let%bind update, disposition = Goal_policy_contributions.import book ~projection in
    let%bind () =
      match disposition with
      | Added -> Ok ()
      | Replaced | Duplicate | Stale ->
        Error (error Conflict "initial import must consume its exact Pending once")
    in
    let%bind owned =
      prepare_causal_terminal_write
        t
        observed
        ~reservation
        ~purpose:(Initial_causal_import observation)
        ~kind:(C.Remote.Import projection)
        ~update
    in
    let%bind () = commit_causal_terminal_write t owned in
    causal_initial_result t reservation observation
;;

let causal_prepare_correction t observed acknowledgement observation =
  let module Book = Goal_policy_contributions in
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let reservation = acknowledgement.actual_reservation in
  let%bind () =
    match t.causal_root_write with
    | None -> Ok ()
    | Some owned -> Session_commit_attempt.unresolved owned.writer
  in
  let%bind projection = causal_terminal_projection reservation observation in
  let%bind book = causal_book t in
  let%bind update, disposition = Book.import book ~projection in
  let prepare () =
    let%map owned =
      prepare_causal_terminal_write
        t
        observed
        ~reservation
        ~purpose:
          (Factual_causal_correction
             { source_acknowledgement = acknowledgement; observation })
        ~kind:(C.Remote.Correction projection)
        ~update
    in
    Prepared owned
  in
  match disposition with
  | Added -> Ok Awaiting_initial_confirmation
  | Stale -> Ok (No_write Superseded)
  | Replaced -> prepare ()
  | Duplicate ->
    let%bind before = Book.to_document book in
    let%bind after = Book.to_document (Book.Update.candidate update) in
    if
      Document_schema.Json.equal
        (Document_schema.Document.json before)
        (Document_schema.Document.json after)
    then Ok (No_write Exact_duplicate)
    else prepare ()
;;

let causal_close_pending t observed reservation closed =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  match reservation.native_reservation.terminal with
  | C.Remote.Settled (No_writer_closed acknowledged)
    when phys_equal acknowledged.closed closed.native_closed -> Ok ()
  | Settled Pending ->
    let%bind book = causal_book t in
    let%bind update =
      Goal_policy_contributions.close_before_writer
        book
        ~pending:reservation.native_reservation.pending
    in
    let%bind owned =
      prepare_causal_terminal_write
        t
        observed
        ~reservation
        ~purpose:(Causal_no_writer_close closed)
        ~kind:(C.Remote.Close closed.native_closed)
        ~update
    in
    commit_causal_terminal_write t owned
  | Terminal_prepared write -> Session_commit_attempt.unresolved write.operation.writer
  | Settled (Confirmed _) | Settled (No_writer_closed _) ->
    Error (error Conflict "causal pending cannot close another acknowledged terminal")
;;

let consume_causal_terminal
  : type outcome.
    t -> outcome causal_terminal_observed -> (outcome, Agent_protocol.Error.t) result
  =
  fun t observed ->
  let open Result.Let_syntax in
  let captured = observed.terminal_capture in
  let%bind () = check_causal_terminal_capture t captured in
  let%bind () =
    check_causal_terminal_current t captured ~current:observed.terminal_current
  in
  match captured.terminal_operation with
  | Import_causal_usage (reservation, observation) ->
    (causal_import_usage t observed reservation observation
     : (outcome, Agent_protocol.Error.t) result)
  | Prepare_causal_correction (acknowledgement, observation) ->
    causal_prepare_correction t observed acknowledgement observation
  | Close_causal_pending (reservation, closed) ->
    causal_close_pending t observed reservation closed
  | Refresh_causal_admitted (reservation, acknowledgement, confirmation) ->
    let%map () =
      Goal_root_policy.admitted
        reservation.actual_attempt.native_attempt.policy
        ~state:t.state
        ~now:(t.services.now ())
    in
    { admitted_reservation = reservation
    ; admitted_acknowledgement = acknowledgement
    ; admitted_confirmation = confirmation
    ; admitted_owner = observed.terminal_owner
    }
;;

let causal_commit_correction t owned =
  let open Result.Let_syntax in
  let%bind write, _ = causal_terminal_write t owned in
  match write.acknowledged with
  | Some _ -> causal_correction_result t owned
  | None ->
    let%bind () =
      if Option.exists t.causal_root_write ~f:(phys_equal owned)
      then Ok ()
      else Session_commit_attempt.unresolved owned.writer
    in
    let%bind () = commit_causal_terminal_write t owned in
    causal_correction_result t owned
;;

let causal_retained_correction
      t
      (acknowledgement : causal_import_acknowledgement)
      (observation : causal_usage_observation)
  =
  let open Result.Let_syntax in
  let%bind () = causal_terminal_owner t acknowledgement.actual_reservation in
  let%bind _ = causal_imported_usage_source acknowledgement in
  match t.causal_root_write with
  | Some ({ acknowledgement = Causal_terminal { context; _ }; _ } as owned) ->
    (match context.terminal_purpose with
     | Factual_causal_correction actual
       when phys_equal
              actual.source_acknowledgement.native_import.operation
              acknowledgement.native_import.operation
            && phys_equal actual.observation observation -> Ok (Some owned)
     | Factual_causal_correction _ | Initial_causal_import _ | Causal_no_writer_close _ ->
       Ok None)
  | Some { acknowledgement = Causal_reserved _ | Causal_held _; _ } | None -> Ok None
;;

let causal_abandon_correction t owned =
  let open Result.Let_syntax in
  let%bind write, context = causal_terminal_write t owned in
  let%bind () =
    match context.terminal_purpose with
    | Factual_causal_correction _
      when Option.exists t.causal_root_write ~f:(phys_equal owned) -> Ok ()
    | Factual_causal_correction _ | Initial_causal_import _ | Causal_no_writer_close _ ->
      Error (error Conflict "only the exact retained correction can be refused")
  in
  let%bind () =
    match write.acknowledged with
    | Some _ -> Error (error Conflict "acknowledged correction cannot be abandoned")
    | None ->
      if Session_commit_attempt.no_writer owned.writer
      then Ok ()
      else (
        match
          Session_commit_observation.outcome
            (Session_commit_attempt.observation owned.writer)
        with
        | Not_called -> Ok ()
        | In_progress | Returned _ | Raised _ ->
          Error (error Conflict "entered correction requires factual reconciliation"))
  in
  let refused =
    error Conflict "prepared causal correction was explicitly refused before writer"
  in
  if not (Session_commit_attempt.no_writer owned.writer)
  then
    ignore
      (Session_commit_attempt.perform owned.writer (fun () -> Error refused)
       : (unit, Agent_protocol.Error.t) result);
  settle_causal_root_no_writer t owned;
  if Option.exists t.causal_root_write ~f:(phys_equal owned)
  then Session_commit_attempt.unresolved owned.writer
  else Ok ()
;;

let check_causal_admitted_views (views : causal_admitted_views) =
  let open Result.Let_syntax in
  let%bind () = check_causal_confirmation views.acknowledgement views.confirmation in
  let attempts = views.acknowledgement.actual_reservations.actual_attempts in
  let%bind () =
    if Int.equal (List.length attempts) (List.length views.root_views)
    then Ok ()
    else Error (error Conflict "causal admitted views have another ordered root vector")
  in
  List.map2_exn attempts views.root_views ~f:(fun attempt view ->
    let%bind () =
      if
        phys_equal attempt view.admitted_reservation.actual_attempt
        && phys_equal view.admitted_acknowledgement views.acknowledgement
        && phys_equal view.admitted_confirmation views.confirmation
      then Ok ()
      else
        Error (error Conflict "causal admitted view has another actual reservation/ACK")
    in
    let%bind () =
      causal_terminal_owner attempt.route.root_actor view.admitted_reservation
    in
    let%bind () =
      if Recurrence_controller.Retained_owner.is_current view.admitted_owner
      then Ok ()
      else Error (error Conflict "causal admitted view lost its retained root owner")
    in
    Goal_root_policy.admitted
      attempt.native_attempt.policy
      ~state:attempt.route.root_actor.state
      ~now:(attempt.route.root_actor.services.now ()))
  |> Result.all_unit
;;

let capture_descendant_root
  : type outcome.
    t
    -> outcome Descendant_root_request.operation
    -> (outcome Descendant_root_request.capture, Agent_protocol.Error.t) result
  =
  fun t operation ->
  let module R = Descendant_admission_data in
  let module Q = Descendant_root_request in
  let open Result.Let_syntax in
  let%bind source_owner, records =
    match operation with
    | Bind (source_owner, ancestry, preparation) ->
      let%bind controller = child_accounting_owner t ~source_owner in
      let%bind () = Descendant_preparation.check_basis preparation in
      let%bind () =
        if
          Descendant_preparation.issued_by preparation ~source_owner
          && Descendant_preparation.same_store preparation ~controller
          && Delegation_authority.Checked_ancestry.issued_by ancestry ~source_owner
        then Ok ()
        else
          Error
            (error Conflict "descendant preparation/ancestry has foreign issuer or Store")
      in
      let records = Delegation_authority.Checked_ancestry.records ancestry in
      let%bind () =
        match records with
        | leaf :: _
          when Descendant_preparation.matches_delegation
                 preparation
                 (Agent_store.Delegation_store.reference leaf)
               && Option.exists leaf.admission.goal_origin ~f:(fun origin ->
                 Agent_store.Delegation_goal_origin.equal origin preparation.origin) ->
          Ok ()
        | [] | _ :: _ ->
          Error
            (error
               Conflict
               "descendant routes require exact complete actual child origin")
      in
      Ok (source_owner, records)
    | Begin (route, reservations) ->
      let preparation = R.Reservation_set.preparation reservations in
      let%bind () =
        R.Reservation_set.check_next reservations ~scope:(R.Root_route.scope route)
      in
      let%bind () = descendant_route_actor t ~factual:false route in
      let%bind () = Descendant_preparation.check_basis preparation in
      if phys_equal route.preparation preparation
      then Ok (route.source_owner, route.records)
      else Error (error Conflict "descendant route belongs to another preparation")
    | Commit attempt ->
      let%bind () = descendant_route_actor t ~factual:false attempt.route in
      let%bind () = Descendant_preparation.check_basis attempt.preparation in
      if phys_equal attempt.basis.state t.state
      then Ok (attempt.route.source_owner, attempt.route.records)
      else Error (error Conflict "root reserve original basis changed")
    | Reconcile attempt ->
      let%map () = descendant_route_actor t ~factual:true attempt.route in
      attempt.route.source_owner, attempt.route.records
    | Refresh_reserved reservation ->
      let%bind () = descendant_route_actor t ~factual:false reservation.route in
      let%map () = Descendant_preparation.check_basis reservation.preparation in
      reservation.route.source_owner, reservation.route.records
    | Close (reservation, closed) ->
      let%bind () = descendant_route_actor t ~factual:true reservation.route in
      if
        Descendant_preparation.Closed_before_writer.belongs_to
          closed
          ~preparation:reservation.preparation
      then Ok (reservation.route.source_owner, reservation.route.records)
      else Error (error Conflict "root close has another physical child seal")
    | Import (source_owner, observation) ->
      let%bind controller = child_accounting_owner t ~source_owner in
      if
        Runtime_source_owner.matches
          source_owner
          observation.Child_usage_observation.source_owner
        && Recurrence_controller.same_store controller observation.controller
        && Agent_protocol.Id.Session.equal
             observation.reference.key.parent_session_id
             t.state.identity.session_id
      then Ok (source_owner, [])
      else Error (error Conflict "root import has another Factory/Store/parent")
    | Refresh_admitted (reservation, acknowledgement, confirmation) ->
      let%map () =
        check_descendant_admitted_owner t reservation acknowledgement confirmation
      in
      reservation.route.source_owner, reservation.route.records
  in
  let%map basis = capture_child_accounting_basis t ~source_owner in
  Q.{ basis; records; operation }
;;

(* Outer phase only, after capture reply. No Actor/Owner/Registry lock held. *)
let observe_descendant_root
  : type outcome.
    t
    -> outcome Descendant_root_request.capture
    -> (outcome Descendant_root_request.observed, Agent_protocol.Error.t) result
  =
  fun t captured ->
  let module D = Agent_store.Delegation_store in
  let open Result.Let_syntax in
  let%bind () = check_child_accounting_capture t captured.basis in
  let factual = Descendant_root_request.factual captured.operation in
  let%bind () =
    List.fold_result captured.records ~init:() ~f:(fun () expected ->
      let result =
        Recurrence_controller.resolve_delegation
          captured.basis.controller
          (D.reference expected)
      in
      let%bind () = check_child_accounting_capture t captured.basis in
      let%bind actual = result in
      if
        if factual
        then D.Reference.equal (D.reference actual) (D.reference expected)
        else
          D.equal_record actual expected
          && Option.is_none actual.revocation
          && D.equal_stage actual.stage Linked
      then Ok ()
      else Error (error Conflict "descendant actual private ancestry changed"))
  in
  let%bind child_current =
    match captured.operation with
    | Import (_, observation) ->
      let result = observation.Child_usage_observation.refresh_read () in
      let%bind () = check_child_accounting_capture t captured.basis in
      let%bind current = result in
      let result =
        Recurrence_controller.resolve_delegation
          captured.basis.controller
          observation.reference
      in
      let%bind () = check_child_accounting_capture t captured.basis in
      let%bind record = result in
      let%bind children =
        Result.of_option
          captured.basis.state.child_contributions
          ~error:(error Conflict "root import has no acknowledged child frontier")
      in
      let%bind origin =
        Child_contributions.origin children ~reference:observation.reference
      in
      if
        Option.equal
          Agent_store.Delegation_goal_origin.equal
          origin
          record.admission.goal_origin
      then Ok (Some current)
      else
        Error (error Conflict "root import lower origin differs from retained frontier")
    | Bind _
    | Begin _
    | Commit _
    | Reconcile _
    | Refresh_reserved _
    | Refresh_admitted _
    | Close _ -> Ok None
  in
  let result =
    Recurrence_controller.observe captured.basis.controller captured.basis.state
  in
  let%bind () = check_child_accounting_capture t captured.basis in
  let%bind current = result in
  let%map () = check_child_accounting_basis t captured.basis ~current in
  Descendant_root_request.{ captured; current; child_current }
;;

let descendant_observed_check t (observed : _ Descendant_root_request.observed) =
  check_child_accounting_basis t observed.captured.basis ~current:observed.current
;;

let descendant_pending state (route : Descendant_admission_data.Root_route.t) =
  let%bind.Result accounting, _ = descendant_components state in
  let scope = Goal_descendant_root_route.scope route.association in
  Goal_descendants.branches
    accounting
    ~goal_id:(Agent_store.Delegation_goal_origin.Scope.goal_id scope)
  |> List.find ~f:(fun branch ->
    Agent_store.Delegation_goal_origin.Scope.equal
      (Goal_descendants.Branch.scope branch)
      scope)
  |> Result.of_option ~error:(error Conflict "actual descendant branch is absent")
  |> Result.map ~f:Goal_descendants.Branch.pending
;;

let descendant_exact_pending state (reservation : Descendant_admission_data.Reservation.t)
  =
  let%bind.Result actual = descendant_pending state reservation.route in
  if Option.exists actual ~f:(Goal_descendant_pending.equal reservation.pending)
  then Ok ()
  else Error (error Conflict "actual root pending differs from reservation ACK")
;;

let descendant_hold t observed attempt reason =
  let module R = Descendant_admission_data in
  let open Result.Let_syntax in
  let goal_id =
    Agent_store.Delegation_goal_origin.Scope.goal_id
      (R.Root_route.scope attempt.R.Reservation_attempt.route)
  in
  let%bind delta = Goal_charge_admission.hold_delta t.state ~goal_id ~reason in
  let%bind () =
    match delta with
    | None -> Ok ()
    | Some delta ->
      let%bind candidate = prepare_transition t ~delta ~payloads:[] in
      install
        ~admission_hold:goal_id
        ~check_before_commit:(fun () ->
          let%bind () = descendant_observed_check t observed in
          let%bind () = Descendant_preparation.check_basis attempt.preparation in
          Goal_root_policy.fresh attempt.policy ~state:t.state ~now:(t.services.now ())
          |> Result.map ~f:ignore)
        t
        candidate
  in
  Error (error Permission_denied "current root Goal policy holds descendant admission")
;;

let descendant_reservation_from_pending
      (attempt : Descendant_admission_data.Reservation_attempt.t)
      pending
  =
  let reservation : Descendant_admission_data.Reservation.t =
    { attempt_identity = attempt.identity
    ; route = attempt.route
    ; preparation = attempt.preparation
    ; policy = attempt.policy
    ; pending
    ; closed = None
    }
  in
  attempt.planned_pending <- Some pending;
  attempt.acknowledged <- Some reservation;
  reservation
;;

let commit_descendant_reservation
      t
      observed
      (attempt : Descendant_admission_data.Reservation_attempt.t)
  =
  let module R = Descendant_admission_data in
  let module G = Agent_protocol.Goal in
  let open Result.Let_syntax in
  match R.Reservation_attempt.outcome attempt with
  | Acknowledged reservation -> Ok (R.Reserve_result.Reserved reservation)
  | Attempt_unconfirmed -> Ok (R.Reserve_result.Attempt_unconfirmed attempt)
  | Not_attempted ->
    let%bind () = descendant_observed_check t observed in
    let%bind () = Descendant_preparation.check_basis attempt.preparation in
    let%bind () = descendant_route_actor t ~factual:false attempt.route in
    let%bind () = descendant_route_data t.state attempt.route in
    let%bind () =
      if phys_equal attempt.basis.state t.state
      then Ok ()
      else Error (error Conflict "root reservation original basis changed")
    in
    let%bind policy =
      Goal_root_policy.fresh attempt.policy ~state:t.state ~now:(t.services.now ())
    in
    (match policy with
     | Hold reason -> descendant_hold t observed attempt reason
     | Allow ->
       let scope = R.Root_route.scope attempt.route in
       let%bind goal, account = descendant_root_account t.state scope in
       let occurrence = Descendant_preparation.occurrence attempt.preparation in
       let dimension = Goal_descendant_occurrence.dimension occurrence in
       let local_count, ceiling, count_reason =
         match dimension with
         | Attempt ->
           ( Goal_accounting.admitted_attempts account
           , G.Budget.admitted_attempts (G.budget goal)
           , G.Budget.Dimension.Admitted_attempts )
         | Host_turn ->
           ( Goal_accounting.admitted_turns account
           , G.Budget.admitted_turns (G.budget goal)
           , G.Budget.Dimension.Admitted_turns )
       in
       let%bind accounting, children = descendant_components t.state in
       let%bind reserved =
         Goal_descendants.reserve
           accounting
           ~children
           ~scope
           ~occurrence
           ~local_count
           ~ceiling
       in
       let%bind reserved =
         match reserved with
         | Reserved _ ->
           let%bind context =
             Session_state.goal_policy_context t.state ~owner:(G.session goal)
           in
           let%bind view = Goal_policy_totals.capture context ~goal_id:(G.id goal) in
           let%map available =
             Goal_policy_totals.available view ~context:Ordinary_existing ~goal ~dimension
           in
           (match available with
            | Available -> reserved
            | Reserved -> Goal_descendants.Reserve_result.Blocked Reserved
            | Exhausted -> Blocked Exhausted
            | Unknown -> Blocked Unknown)
         | Already_pending _ | Blocked _ -> Ok reserved
       in
       (match reserved with
        | Blocked Exhausted ->
          descendant_hold t observed attempt (Budget_gate count_reason)
        | Blocked ((Reserved | Unknown) as availability) ->
          Ok (R.Reserve_result.Blocked availability)
        | Blocked Available ->
          Error (error Invalid_state "root reserve returned blocked Available")
        | Already_pending _ ->
          (* DATA equality cannot authenticate the physical producer owning an
             earlier pending. Same-attempt ACK/reconciliation use their retained
             native cells; a fresh attempt cannot adopt or later close it. *)
          Ok (R.Reserve_result.Blocked Goal_descendants.Availability.Reserved)
        | Reserved (update, _) ->
          let%bind candidate =
            prepare_transition
              t
              ~delta:(Session_delta.Goal_descendants_changed update)
              ~payloads:[]
          in
          let%bind acknowledgement =
            Root_reserve_acknowledgement.prepare attempt ~previous:t.state ~candidate
          in
          let final () =
            let%bind () = descendant_observed_check t observed in
            let%bind () = Descendant_preparation.check_basis attempt.preparation in
            let%bind () =
              Root_reserve_acknowledgement.check_basis
                acknowledgement
                ~state:t.state
                ~candidate
            in
            let%bind decision =
              Goal_root_policy.fresh
                attempt.policy
                ~state:t.state
                ~now:(t.services.now ())
            in
            match decision with
            | Allow -> descendant_observed_check t observed
            | Hold _ ->
              Error
                (error
                   Permission_denied
                   "root fresh policy changed before reserve writer")
          in
          let result =
            install
              ~root_reserve_acknowledgement:acknowledgement
              ~commit_attempted:attempt.writer_attempted
              ~check_before_commit:final
              t
              candidate
          in
          (match R.Reservation_attempt.outcome attempt with
           | Acknowledged reservation -> Ok (R.Reserve_result.Reserved reservation)
           | Attempt_unconfirmed -> Ok (R.Reserve_result.Attempt_unconfirmed attempt)
           | Not_attempted ->
             Result.bind result ~f:(fun () ->
               Error (error Invalid_state "root writer returned without reservation ACK")))))
;;

let reconcile_descendant_reservation
      t
      observed
      (attempt : Descendant_admission_data.Reservation_attempt.t)
  =
  let module R = Descendant_admission_data in
  let open Result.Let_syntax in
  let%bind () = descendant_observed_check t observed in
  let%bind () = descendant_route_actor t ~factual:true attempt.route in
  let%bind () = descendant_route_data t.state attempt.route in
  match R.Reservation_attempt.outcome attempt with
  | Acknowledged reservation -> Ok (R.Reserve_result.Reserved reservation)
  | Not_attempted ->
    Error
      (error Conflict "unattempted root request has no durable reservation to reconcile")
  | Attempt_unconfirmed ->
    let%bind actual = descendant_pending t.state attempt.route in
    (match attempt.planned_pending, actual with
     | Some planned, Some actual when Goal_descendant_pending.equal planned actual ->
       Ok (R.Reserve_result.Reserved (descendant_reservation_from_pending attempt actual))
     | None, _ | Some _, _ -> Ok (R.Reserve_result.Attempt_unconfirmed attempt))
;;

(* Authenticate retained ACK custody without old owner liveness, policy or
   source callbacks. A reconstructed actual Actor may observe the same durable
   source under its genuine current Factory/Store/controller. *)
let descendant_usage_source
      (basis : Child_accounting_basis.t)
      (source : Descendant_usage.Source.t)
  =
  let open Result.Let_syntax in
  let%bind installed, controller, source_owner =
    match source with
    | Descendant_usage.Source.Acknowledged acknowledgement ->
      let%bind () = check_descendant_ack acknowledgement in
      let preparation = acknowledgement.preparation in
      let%map () =
        if
          Agent_protocol.Session_ref.equal
            preparation.session
            (Recurrence_controller.session preparation.controller)
          && Agent_protocol.Session_ref.equal
               preparation.session
               (Goal_descendant_occurrence.Frame.session
                  (Goal_descendant_occurrence.frame preparation.occurrence))
          && Option.equal
               Agent_store.Delegation_store.Reference.equal
               preparation.before.spec.delegation
               acknowledgement.installed.spec.delegation
          && Option.exists
               acknowledgement.installed.goal_descendants
               ~f:(fun accounting ->
                 Option.exists
                   (Goal_descendants.origin accounting)
                   ~f:(Agent_store.Delegation_goal_origin.equal preparation.origin))
        then Ok ()
        else Error (error Conflict "factual child ACK differs from its original source")
      in
      acknowledgement.installed, preparation.controller, preparation.source_owner
    | Imported acknowledgement ->
      Ok
        ( acknowledgement.installed
        , acknowledgement.controller
        , acknowledgement.source_owner )
  in
  let%bind () =
    if
      Runtime_source_owner.matches basis.Child_accounting_basis.source_owner source_owner
      && Recurrence_controller.same_store basis.controller controller
      && Agent_protocol.Session_ref.equal
           (Recurrence_controller.session basis.controller)
           (Recurrence_controller.session controller)
      && Agent_protocol.Id.Session.equal
           installed.identity.session_id
           basis.state.identity.session_id
    then Ok ()
    else Error (error Conflict "factual ACK source has another Factory/Store/session")
  in
  let%bind reference =
    Result.of_option
      installed.spec.delegation
      ~error:(error Conflict "factual ACK source has no own delegation reference")
  in
  let%bind accounting =
    Result.of_option
      installed.goal_descendants
      ~error:(error Conflict "factual ACK source has no descendant accounting")
  in
  let%bind origin =
    Result.of_option
      (Goal_descendants.origin accounting)
      ~error:(error Conflict "factual ACK source has historical Unknown origin")
  in
  (* Reset_generation preserves accounting. The old ACK proves a durable
     occurrence, not fresh generation eligibility; current snapshot/Included
     receipt validation decides what can actually confirm after a reset. *)
  let%map () =
    if
      Agent_protocol.Session_ref.equal
        (Goal_descendants.session accounting)
        (Recurrence_controller.session controller)
      && Agent_protocol.Id.Session.equal
           reference.child_session_id
           installed.identity.session_id
    then Ok ()
    else
      Error (error Conflict "factual ACK source differs from its full accounting session")
  in
  reference, origin
;;

let capture_descendant_usage_internal t ~source_owner ~source =
  let open Result.Let_syntax in
  let%bind basis = capture_child_accounting_basis t ~source_owner in
  let%map reference, origin = descendant_usage_source basis source in
  Descendant_usage.{ basis; source; reference; origin }
;;

let observe_descendant_usage_external t (captured : Descendant_usage.captured) =
  let%map.Result record, current =
    observe_child_accounting_source t captured.basis ~reference:captured.reference
  in
  Descendant_usage.{ captured; record; current }
;;

let check_descendant_usage_source t (observed : Descendant_usage.observed) =
  let module D = Agent_store.Delegation_store in
  let module O = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  let captured = observed.captured in
  let%bind () = check_child_accounting_basis t captured.basis ~current:observed.current in
  let%bind reference, origin = descendant_usage_source captured.basis captured.source in
  if
    D.Reference.equal reference captured.reference
    && O.equal origin captured.origin
    && D.Reference.equal reference (D.reference observed.record)
    && Option.exists observed.record.admission.goal_origin ~f:(O.equal origin)
    && Agent_protocol.Id.Session.equal
         reference.child_session_id
         t.state.identity.session_id
    && Agent_protocol.Id.Prompt_revision.equal
         reference.revision_id
         t.state.spec.prompt_revision_id
    && Option.exists t.state.spec.delegation ~f:(D.Reference.equal reference)
    && Option.exists t.state.goal_descendants ~f:(fun accounting ->
      Agent_protocol.Session_ref.equal
        (Goal_descendants.session accounting)
        (Recurrence_controller.session captured.basis.controller)
      && Option.exists (Goal_descendants.origin accounting) ~f:(O.equal origin))
  then Ok ()
  else
    Error
      (error Conflict "factual ACK source private reference/origin/accounting changed")
;;

let observe_descendant_usage_internal
      t
      (observed : Descendant_usage.observed)
      ~refresh_read
  =
  let open Result.Let_syntax in
  let%bind () = check_descendant_usage_source t observed in
  let%bind snapshot = Child_accounting.snapshot observed.captured.basis.state in
  let%bind () =
    if
      Option.exists snapshot ~f:(fun snapshot ->
        Agent_store.Delegation_store.Reference.equal
          (Child_usage_snapshot.reference snapshot)
          observed.captured.reference)
    then Ok ()
    else
      Error (error Conflict "factual ACK source has no exact initialized usage snapshot")
  in
  let%map () = check_descendant_usage_source t observed in
  let captured = observed.captured in
  Child_usage_observation.
    { controller = captured.basis.controller
    ; source_owner = Runtime_source_owner.identity captured.basis.source_owner
    ; reference = captured.reference
    ; snapshot
    ; refresh_read
    }
;;

let refresh_descendant_reserved
      t
      observed
      (reservation : Descendant_admission_data.Reservation.t)
  =
  let open Result.Let_syntax in
  let check () =
    let%bind () = descendant_observed_check t observed in
    let%bind () = descendant_route_actor t ~factual:false reservation.route in
    let%bind () = Descendant_preparation.check_basis reservation.preparation in
    let%bind () = descendant_exact_pending t.state reservation in
    let%bind policy =
      Goal_root_policy.fresh reservation.policy ~state:t.state ~now:(t.services.now ())
    in
    let%bind () =
      match policy with
      | Allow -> Ok ()
      | Hold _ ->
        Error (error Permission_denied "reserved root fresh policy currently holds work")
    in
    descendant_observed_check t observed
  in
  let%map () = check () in
  Descendant_admission_data.Root_before_writer.{ reservation; check_current = check }
;;

let refresh_descendant_admitted
      t
      (observed : Descendant_root_request.Admitted_observed.t)
      (reservation : Descendant_admission_data.Reservation.t)
      acknowledgement
      confirmation
  =
  let open Result.Let_syntax in
  let check () =
    let%bind () = check_child_accounting_identity t observed.captured.basis in
    let%bind () =
      check_descendant_admitted_owner t reservation acknowledgement confirmation
    in
    if Recurrence_controller.Retained_owner.is_current observed.owner
    then Ok ()
    else Error (error Conflict "child accounting Store observation changed")
  in
  let%map () = check () in
  Descendant_admission_data.Root_admitted.
    { reservation; acknowledgement; confirmation; check_current = check }
;;

let close_descendant_before_writer t observed reservation closed =
  let open Result.Let_syntax in
  let check () =
    let%bind () = descendant_observed_check t observed in
    let%bind () =
      descendant_route_actor
        t
        ~factual:true
        reservation.Descendant_admission_data.Reservation.route
    in
    let%bind () = descendant_route_data t.state reservation.route in
    if
      Descendant_preparation.Closed_before_writer.belongs_to
        closed
        ~preparation:reservation.preparation
    then Ok ()
    else Error (error Conflict "factual pending close has another physical child seal")
  in
  let%bind () = check () in
  let%bind accounting, children = descendant_components t.state in
  let%bind update =
    Goal_descendants.close_before_writer accounting ~children ~pending:reservation.pending
  in
  let%bind candidate =
    prepare_transition
      t
      ~delta:(Session_delta.Goal_descendants_changed update)
      ~payloads:[]
  in
  let%bind acknowledgement =
    Root_close_acknowledgement.prepare reservation ~closed ~previous:t.state ~candidate
  in
  let result =
    install
      ~root_close_acknowledgement:acknowledgement
      ~check_before_commit:check
      t
      candidate
  in
  let%bind known = Root_close_acknowledgement.acknowledged reservation ~closed in
  if known then Ok () else result
;;

(* Exact current carrier plus retained local terminal heads is positive native
   re-observation. Duplicate/Stale disposition alone never constructs this ACK.
   An older snapshot unequal to the actual retained slot cannot confirm. *)
let descendant_import_receipts state (observation : Child_usage_observation.t) =
  let module S = Child_usage_snapshot in
  let module GD = Goal_descendants in
  let module O = Agent_store.Delegation_goal_origin in
  let open Result.Let_syntax in
  let%bind accounting, children = descendant_components state in
  let%bind snapshot =
    Result.of_option
      observation.snapshot
      ~error:(error Conflict "historical absence cannot confirm descendant usage")
  in
  let%bind retained =
    Child_contributions.snapshot children ~reference:observation.reference
  in
  let%bind () =
    if
      Option.exists retained ~f:(fun actual ->
        String.equal (S.digest actual) (S.digest snapshot))
    then Ok ()
    else
      Error (error Conflict "factual import is not the exact retained child observation")
  in
  let%map scopes =
    Result.of_option
      (S.goal_scopes snapshot)
      ~error:(error Conflict "historical scoped absence cannot confirm descendant usage")
  in
  List.filter_map scopes ~f:(fun projected ->
    let scope = S.Goal_scope.scope projected in
    Option.bind (S.Goal_scope.included projected) ~f:(fun receipt ->
      if
        List.exists
          (GD.branches accounting ~goal_id:(O.Scope.goal_id scope))
          ~f:(fun branch ->
            O.Scope.equal (GD.Branch.scope branch) scope
            &&
            match GD.Branch.last branch with
            | Some (Included actual) -> Goal_descendant_included.equal actual receipt
            | Some (No_writer_closed _) | None -> false)
      then Some receipt
      else None))
;;

let import_descendant_usage t observed source_owner observation =
  let module R = Descendant_admission_data in
  let open Result.Let_syntax in
  let before = t.state in
  let check () =
    let%bind () = descendant_observed_check t observed in
    let%bind _ = child_accounting_owner t ~source_owner in
    let%bind () =
      Option.value_map
        observed.Descendant_root_request.child_current
        ~default:(Error (error Conflict "factual import has no actual child read guard"))
        ~f:(fun check -> check ())
    in
    if
      Runtime_source_owner.matches
        source_owner
        observation.Child_usage_observation.source_owner
      && Recurrence_controller.same_store
           observed.captured.basis.controller
           observation.controller
      && phys_equal before t.state
    then Ok ()
    else Error (error Conflict "factual import physical Factory/Store/basis changed")
  in
  let%bind () = check () in
  let%bind _, children = descendant_components before in
  let%bind next_children, _, delta =
    plan_child_usage_import before ~children ~snapshot:observation.snapshot
  in
  let%bind changed = child_contributions_changed before next_children in
  let make installed =
    let%map receipts = descendant_import_receipts installed observation in
    R.Import_acknowledgement.
      { issuing_actor = t.inference_owner_identity
      ; controller = observed.captured.basis.controller
      ; source_owner = Runtime_source_owner.identity source_owner
      ; observation
      ; installed
      ; included = receipts
      }
  in
  if not changed
  then (
    let%bind () = check () in
    make before)
  else (
    let%bind candidate = prepare_transition t ~delta ~payloads:[] in
    let%bind acknowledgement = make candidate.state in
    let installed = ref None in
    let acknowledgement =
      Descendant_import_acknowledgement.
        { previous = before
        ; candidate
        ; acknowledgement = Some acknowledgement
        ; installed
        }
    in
    let result =
      install
        ~descendant_import_acknowledgement:acknowledgement
        ~check_before_commit:check
        t
        candidate
    in
    match !installed with
    | Some acknowledgement -> Ok acknowledgement
    | None ->
      Result.bind result ~f:(fun () ->
        Error (error Invalid_state "factual import writer returned without ACK")))
;;

let consume_descendant_root
  : type outcome.
    t
    -> outcome Descendant_root_request.observed
    -> (outcome, Agent_protocol.Error.t) result
  =
  fun t observed ->
  let module R = Descendant_admission_data in
  let open Result.Let_syntax in
  let%bind () = descendant_observed_check t observed in
  let captured = observed.captured in
  ((match captured.operation with
    | Bind (_, _, preparation) ->
      let%bind () = Descendant_preparation.check_basis preparation in
      let%bind accounting, children = descendant_components t.state in
      let%map associations =
        Goal_descendant_root_route.select
          ~session:(Recurrence_controller.session captured.basis.controller)
          ~scopes:(Descendant_preparation.scopes preparation)
          ~records:captured.records
          ~accounting
          ~children
      in
      List.map associations ~f:(fun association ->
        R.Root_route.
          { association
          ; controller = captured.basis.controller
          ; root_issuer = t.inference_owner_identity
          ; source_owner = captured.basis.source_owner
          ; domain = captured.basis.domain
          ; preparation
          ; records = captured.records
          })
    | Begin (route, reservations) ->
      let preparation = R.Reservation_set.preparation reservations in
      let%bind () =
        R.Reservation_set.check_next reservations ~scope:(R.Root_route.scope route)
      in
      let%bind () = descendant_route_actor t ~factual:false route in
      let%bind () = descendant_route_data t.state route in
      let%bind () = Descendant_preparation.check_basis preparation in
      let%bind policy =
        descendant_policy_for_begin
          t
          ~goal_id:
            (Agent_store.Delegation_goal_origin.Scope.goal_id (R.Root_route.scope route))
          ~now:(t.services.now ())
      in
      let attempt =
        R.Reservation_attempt.
          { identity = ref ()
          ; basis = captured.basis
          ; route
          ; preparation
          ; policy
          ; writer_attempted = ref false
          ; planned_pending = None
          ; acknowledged = None
          }
      in
      let%map () = R.Reservation_set.retain_next reservations attempt in
      attempt
    | Commit attempt -> commit_descendant_reservation t observed attempt
    | Reconcile attempt -> reconcile_descendant_reservation t observed attempt
    | Refresh_reserved reservation -> refresh_descendant_reserved t observed reservation
    | Close (reservation, closed) ->
      close_descendant_before_writer t observed reservation closed
    | Import (source_owner, observation) ->
      import_descendant_usage t observed source_owner observation
    | Refresh_admitted (reservation, acknowledgement, confirmation) ->
      let%bind owner =
        Recurrence_controller.retain_owner
          observed.captured.basis.controller
          observed.current
      in
      let retained =
        { Descendant_root_request.Admitted_observed.captured = observed.captured; owner }
      in
      refresh_descendant_admitted t retained reservation acknowledgement confirmation)
   : (outcome, Agent_protocol.Error.t) result)
;;

let consume_descendant_admitted_root
      t
      (observed : Descendant_root_request.Admitted_observed.t)
  =
  let open Result.Let_syntax in
  let%bind () = check_descendant_admitted_capture_owner t observed.captured in
  let%bind () =
    if Recurrence_controller.Retained_owner.is_current observed.owner
    then Ok ()
    else Error (error Conflict "retained child accounting Store owner changed")
  in
  let%bind status = descendant_admitted_capture_state t observed.captured in
  match status with
  | Descendant_root_request.Admitted_refresh.State_changed ->
    Ok Descendant_root_request.Admitted_refresh.State_changed
  | Current () ->
    (match observed.captured.operation with
     | Refresh_admitted (reservation, acknowledgement, confirmation) ->
       let%map view =
         refresh_descendant_admitted t observed reservation acknowledgement confirmation
       in
       Descendant_root_request.Admitted_refresh.Current view)
;;

let descendant_confirmation = Goal_descendant_admission_custody.descendant_confirmation

let finish_invocation t execution outcome requests commit_starts authoring_reference =
  let open Result.Let_syntax in
  let revision = t.state.counters.revision in
  let owner = Agent_protocol.Job.Invocation execution.dispatched.context.id in
  let%bind cancelled =
    match execution.owner with
    | Foreground operation_id ->
      let%map operation = current_operation t operation_id in
      (match operation.state with
       | Cancelling -> true
       | _ -> false)
    | Invocation_moderator borrow ->
      (match t.moderator_borrow with
       | Some current when phys_equal current borrow ->
         (match borrow.operation_id with
          | None when t.idle_moderator_borrowed ->
            Ok
              (borrow.cancel_requested
               || Option.exists borrow.job_scope ~f:(fun scope -> scope.cancel_requested)
              )
          | Some id ->
            let%map operation = current_operation t id in
            borrow.cancel_requested
            ||
              (match operation.state with
              | Cancelling -> true
              | _ -> false)
          | None -> Error (error Conflict "moderator invocation scope has ended"))
       | _ -> Error (error Conflict "moderator invocation scope has ended"))
    | Event_moderator borrow ->
      (match t.queued_event_borrow with
       | Some current when phys_equal current borrow && t.idle_moderator_borrowed ->
         Ok
           (borrow.cancel_requested
            || Option.exists borrow.job_scope ~f:(fun scope -> scope.cancel_requested)
            || Option.exists t.state.active_operation ~f:(fun operation ->
              Option.exists
                borrow.receipt.context.operation_id
                ~f:(Agent_protocol.Id.Operation.equal operation.id)
              &&
              match operation.state with
              | Cancelling -> true
              | _ -> false))
       | _ -> Error (error Conflict "event invocation scope has ended"))
    | Background_job scope ->
      let%map job = job_scope_current t scope in
      scope.cancel_requested
      ||
        (match job.status with
        | Running | Waiting_permission _ -> false
        | Waiting_completion _ | Queued | Succeeded | Failed _ | Cancelled | Interrupted _
          -> true)
  in
  let%bind () =
    if List.exists t.invocation_executions ~f:(phys_equal execution)
    then Ok ()
    else Error (error Conflict "invocation callback no longer owns its result")
  in
  let outcome =
    match cancelled with
    | true ->
      Agent_protocol.Invocation.Cancelled
        (match execution.owner with
         | Foreground _ -> "operation cancelled"
         | Background_job _ -> "background job cancelled"
         | Invocation_moderator { operation_id = Some _; _ } ->
           "moderator scope cancelled"
         | Invocation_moderator { operation_id = None; _ } | Event_moderator _ ->
           "idle moderator cancelled")
    | false -> outcome
  in
  (* The callback has returned. Even when outcome persistence fails and the
     execution stays registered for cleanup, it cannot authorize new children. *)
  execution.accepts_children <- false;
  Atomic.set execution.authority_live false;
  (match commit_starts && not cancelled, outcome with
   | true, (Complete _ | Fail _ | Pending _) -> ()
   | false, _ | true, Cancelled _ -> abort_staged_work t ~owner);
  let%bind resolved =
    Agent_protocol.Invocation.resolve
      ?authoring_reference:
        (match outcome with
         | Complete _ -> authoring_reference
         | Fail _ | Pending _ | Cancelled _ -> None)
      execution.dispatched
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
      outcome
  in
  let%bind resolved =
    match requests, outcome with
    | Some requests, (Complete _ | Fail _ | Pending _) ->
      Agent_protocol.Invocation.record_handler_intent resolved ~requests
    | None, _ | Some _, Cancelled _ -> Ok resolved
  in
  let%bind resolved, native_goals =
    prepare_native_goal_completion t execution outcome resolved
  in
  let%bind () =
    Native_goal_plan.check_scheduling
      native_goals
      ~run_id:(native_goal_run_id resolved)
      ~action:None
      ~request_turn:
        (Option.exists requests ~f:(fun requests ->
           requests.Agent_protocol.Invocation.request_turn))
  in
  let permissions, permission_deltas, permission_payloads =
    cleanup_invocation_permissions t [ execution.dispatched.context.id ]
  in
  let%bind job_deltas, job_payloads = staged_work_changes t owner in
  let%bind schedule_custody_installation =
    prepare_creator_custody t ~owner ~changes:job_deltas
  in
  let%bind run_deltas, check_run, acknowledge_run =
    prepare_selected_child_run
      ?goal_plan:native_goals.plan
      t
      (Inference_invocation execution)
      job_deltas
  in
  (* Completing the selected result retains negative expiry evidence. New work
     and proof borrows separately check the Admission; this is not a renewal. *)
  let%bind parent = execution_settlement_parent t execution in
  let custody = settlement_custody parent in
  let%bind source = observation_source t in
  let%bind observation =
    Observation_continuation.stage_completed
      resolved
      ~source
      ~parent
      ~policy_source:execution.policy_source
  in
  let%bind _ =
    with_selected_intent_agent_custody
      ?observation
      t
      owner
      (Invocation_intent resolved.context.id)
      ~retention:Agent_intent_retention.Ordinary
      ~pending:(Observation_follow_up.pending resolved)
      custody
      (fun ~job_custody ~check_jobs ~acknowledge ->
         let%bind prepared =
           prepare_transition
             t
             ~delta:
               (Session_delta.Batch
                  ((Session_delta.Invocation_changed resolved :: permission_deltas)
                   @ Option.value_map
                       native_goals.plan
                       ~default:[]
                       ~f:Goal_native_actions.Plan.deltas
                   @ job_deltas
                   @ run_deltas))
             ~payloads:(permission_payloads @ job_payloads)
         in
         let constructor_borrow =
           match execution.owner with
           | Event_moderator borrow -> Some borrow
           | Foreground _ | Invocation_moderator _ | Background_job _ -> None
         in
         let%bind initialization_acknowledgement =
           match constructor_borrow with
           | None -> Ok None
           | Some borrow ->
             prepare_constructor_invocation_ack
               ~permissions
               ?permission_lifecycle:
                 (List.find_map permission_deltas ~f:(function
                    | Session_delta.Lifecycle_changed lifecycle -> Some lifecycle
                    | _ -> None))
               t
               borrow
               ~before:(Some execution.dispatched)
               ~after:resolved
               prepared
         in
         let run_preparation =
           match constructor_borrow with
           | Some borrow -> event_run_preparation t borrow
           | None ->
             Option.bind
               (held_authored_of_execution t (Inference_invocation execution))
               ~f:(held_authored_factual_preparation t)
         in
         let%bind goal_runtime_acknowledgement =
           Option.value_map
             (goal_runtime_of_execution t (Inference_invocation execution))
             ~default:(Ok None)
             ~f:(fun scope ->
               Goal_runtime_acknowledgement.prepare t scope ~candidate:prepared
               |> Result.map ~f:Option.some)
         in
         Eio.Cancel.protect (fun () ->
           let%bind () = check_jobs () in
           let%bind () = check_run () in
           let%bind () =
             Option.value_map constructor_borrow ~default:(Ok ()) ~f:(fun borrow ->
               check_constructor_invocation_ack t borrow initialization_acknowledgement)
           in
           let%bind () =
             if Int64.equal revision t.state.counters.revision
             then Ok ()
             else Error (error Conflict "Invocation ACK basis changed before commit")
           in
           let%bind () =
             persist_transition
               ~explicit_goal_holds:(Native_goal_plan.fresh_holds native_goals)
               ?run_preparation
               ~check_before_commit:(fun () ->
                 let%bind () =
                   Option.value_map
                     goal_runtime_acknowledgement
                     ~default:(Ok ())
                     ~f:(fun ack ->
                       Goal_runtime_acknowledgement.check ack ~actor:t ~candidate:prepared)
                 in
                 let%bind () = check_creator_custody t schedule_custody_installation in
                 check_native_goal_plan t native_goals)
               t
               prepared
           in
           install_committed_transition
             ~explicit_goal_holds:(Native_goal_plan.fresh_holds native_goals)
             ?goal_runtime_acknowledgement
             ~job_custody
             ?schedule_custody_installation
             ?run_preparation
             ?initialization_acknowledgement
             t
             prepared;
           acknowledge ();
           install_native_goal_plan t native_goals;
           let%bind () = acknowledge_run () in
           Option.iter
             (held_authored_of_execution t (Inference_invocation execution))
             ~f:(fun scope ->
               scope.Held_authored_start.jobs
               <- List.filter_map job_deltas ~f:(function
                    | Session_delta.Job_changed job -> Some job
                    | _ -> None)
                  @ scope.jobs);
           publish_committed_transition t prepared;
           Ok ()))
  in
  resolve_cleaned_permission_waiters t permissions;
  t.invocation_executions
  <- List.filter t.invocation_executions ~f:(fun other ->
       not (phys_equal other execution));
  Ok resolved
;;

let commit_moderator_invocation t borrow (resolved : Agent_protocol.Invocation.t) snapshot
  =
  let open Result.Let_syntax in
  let%bind () = validate_moderator_borrow t borrow in
  let%bind () =
    match borrow.callback_finished with
    | false -> Ok ()
    | true -> Error (error Conflict "moderator callback has ended")
  in
  let%bind () =
    match
      List.exists t.invocation_executions ~f:(invocation_execution_owned_by borrow)
    with
    | true ->
      Error (error Conflict "moderator child invocations still require completion")
    | false -> Ok ()
  in
  let%bind () =
    match borrow.job_scope, borrow.operation_id with
    | Some scope, None -> job_scope_can_execute t scope
    | Some _, Some _ ->
      Error (error Conflict "job moderator cannot own a model operation")
    | None, Some operation_id ->
      Result.map (running_operation ~allow_stopping:true t operation_id) ~f:ignore
    | None, None ->
      (match t.state.lifecycle.desired, t.state.lifecycle.observed, t.state.failure with
       | Running, Idle, None when not t.state.halted -> Ok ()
       | _ -> Error (error Conflict "idle observation was stopped before acknowledgement"))
  in
  let%bind () =
    if borrow.committed
    then Error (error Already_resolved "moderator invocation is already committed")
    else if
      Agent_protocol.Id.Invocation.compare
        resolved.context.id
        borrow.invocation.context.id
      <> 0
    then Error (error Conflict "resolution does not belong to this moderator borrow")
    else (
      match borrow.kind, resolved.status with
      | Invocation _, Resolved _ ->
        Agent_protocol.Invocation.validate_transition
          ~previous:(Some borrow.invocation)
          resolved
      | Observation, (Resolved _ | Published _) ->
        let%bind () =
          match resolved.observation with
          | Some { status = Observed; observer }
            when String.equal
                   observer.script_id
                   snapshot.Session.Moderator_state.Identity_snapshot.script_id
                 && String.equal observer.source_sha256 snapshot.script_source_hash ->
            Ok ()
          | _ ->
            Error
              (error
                 Conflict
                 "observation acknowledgement requires its source-bound moderator \
                  checkpoint")
        in
        Agent_protocol.Invocation.validate_transition
          ~previous:(Some borrow.invocation)
          resolved
      | _ -> Error (error Invalid_state "moderator commit requires a resolved invocation"))
  in
  let owner = Agent_protocol.Job.Invocation borrow.invocation.context.id in
  (match borrow.kind, resolved.status with
   | Invocation _, Resolved (Cancelled _) -> abort_staged_work t ~owner
   | _ -> ());
  let%bind native_goals = prepare_callback_native_goals t borrow.native_goals in
  let%bind () =
    let request_turn =
      match borrow.kind with
      | Invocation _ ->
        Option.exists resolved.handler_intent ~f:(fun intent ->
          pending_native_goal_turn intent.Agent_protocol.Invocation.follow_up)
      | Observation ->
        Option.exists resolved.observation ~f:(fun observation ->
          Option.exists
            observation.Agent_protocol.Invocation.follow_up
            ~f:pending_native_goal_turn)
    in
    Native_goal_plan.check_scheduling
      native_goals
      ~run_id:(native_goal_run_id resolved)
      ~action:None
      ~request_turn
  in
  let%bind job_deltas, job_payloads = staged_work_changes t owner in
  let%bind schedule_custody_installation =
    prepare_creator_custody t ~owner ~changes:job_deltas
  in
  let%bind run_deltas, check_run, acknowledge_run =
    prepare_selected_child_run
      ?goal_plan:native_goals.plan
      t
      (Inference_moderator borrow)
      job_deltas
  in
  let%bind parent = moderator_settlement_parent t borrow in
  let custody = settlement_custody parent in
  let manager = t.moderator_manager in
  let%bind checkpoint_plan =
    match borrow.kind with
    | Invocation checkpoint ->
      prepare_moderator_invocation_queue t checkpoint ~resolved ~snapshot
    | Observation ->
      let%bind before = Moderator_checkpoint.decode t.state.moderator in
      let%bind before =
        Result.of_option
          before
          ~error:(error Conflict "moderator callback lost its installed checkpoint")
      in
      let%bind legacy = legacy_untracked_moderator_checkpoint t before in
      if legacy
      then Ok Moderator_callback_checkpoint.Bare_snapshot
      else (
        let%bind index, metadata = capture_modern_callback_queue t ~before in
        let%map plan =
          Legacy_queue_checkpoint.prepare_invocation ~metadata ~before ~snapshot ~resolved
        in
        Moderator_callback_checkpoint.With_queue
          { index
          ; metadata = Legacy_queue_checkpoint.metadata plan
          ; appended = Legacy_queue_checkpoint.appended plan
          })
  in
  let%bind encoded_snapshot =
    match checkpoint_plan with
    | With_queue { metadata; _ } ->
      Moderator_checkpoint.update_with_queue t.state.moderator ~snapshot ~queue:metadata
    | Bare_snapshot -> Ok (Runtime_builder.encode_moderator_snapshot snapshot)
  in
  let%bind staged =
    match checkpoint_plan with
    | With_queue { metadata; appended; _ } ->
      stage_completed_callback_queue ~manager ~metadata ~entries:appended ~parent
    | Bare_snapshot -> Ok Legacy_queue_custody.empty
  in
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () -> if not !acknowledged then Legacy_queue_custody.retire staged)
    ~f:(fun () ->
      let%bind inventory =
        match checkpoint_plan with
        | With_queue { metadata; _ } ->
          callback_queue_inventory t ~manager ~metadata ~staged
        | Bare_snapshot -> Ok Legacy_queue_custody.empty
      in
      let%bind observation =
        match borrow.kind with
        | Invocation _ ->
          let%bind source =
            match checkpoint_plan with
            | With_queue { metadata; _ } -> Ok (Some (Moderator_queue.source metadata))
            | Bare_snapshot ->
              let%bind actual = Moderator_checkpoint.decode (Some encoded_snapshot) in
              (match actual with
               | None -> Error (error Internal_error "bare checkpoint was lost")
               | Some snapshot -> observation_source_for_checkpoint t snapshot)
          in
          Observation_continuation.stage_completed
            resolved
            ~source
            ~parent
            ~policy_source:borrow.policy_source
        | Observation ->
          if observation_pending resolved
          then (
            match borrow.observation with
            | Some observation ->
              Observation_continuation.stage_follow_up observation ~resolved
              |> Result.map ~f:Option.some
            | None ->
              Error
                (error Internal_error "observation borrow lost its settlement component"))
          else Ok None
      in
      let%bind _ =
        with_selected_intent_agent_custody
          ?observation
          t
          owner
          (Invocation_intent resolved.context.id)
          ~retention:Agent_intent_retention.Ordinary
          ~pending:(Observation_follow_up.pending resolved)
          custody
          (fun ~job_custody ~check_jobs ~acknowledge ->
             let%bind prepared =
               prepare_transition
                 t
                 ~delta:
                   (Session_delta.Batch
                      ((match checkpoint_plan with
                        | With_queue { index; _ } ->
                          [ Session_delta.Run_state_changed index ]
                        | Bare_snapshot -> [])
                       @ [ Session_delta.Invocation_changed resolved
                         ; Moderator_changed (Some encoded_snapshot)
                         ]
                       @ Native_goal_plan.deltas native_goals
                       @ job_deltas
                       @ run_deltas))
                 ~payloads:job_payloads
             in
             Eio.Cancel.protect (fun () ->
               let%bind () = check_jobs () in
               let%bind () = check_run () in
               let%bind () =
                 persist_transition
                   ~explicit_goal_holds:(Native_goal_plan.fresh_holds native_goals)
                   ~check_before_commit:(fun () ->
                     let%bind () =
                       match borrow.kind with
                       | Invocation checkpoint ->
                         check_moderator_invocation_checkpoint t checkpoint
                       | Observation -> Ok ()
                     in
                     let%bind () =
                       match checkpoint_plan with
                       | With_queue { metadata; _ } ->
                         let%bind before =
                           match borrow.kind with
                           | Invocation (Known_before { before; _ }) -> Ok before
                           | Observation ->
                             let%bind before =
                               Moderator_checkpoint.decode t.state.moderator
                             in
                             Result.of_option
                               before
                               ~error:(error Conflict "moderator checkpoint changed")
                           | Invocation (Uncaptured_first _ | Legacy_untracked _) ->
                             Error
                               (error
                                  Internal_error
                                  "bare moderator acquired a queue plan")
                         in
                         let%bind _, source =
                           Moderator_source_installation.capture_checkpoint
                             t.state
                             ~checkpoint:before
                         in
                         if
                           Option.equal phys_equal manager t.moderator_manager
                           && Agent_protocol.Run_source.equal
                                source
                                (Moderator_queue.source metadata)
                         then Ok ()
                         else
                           Error
                             (error
                                Conflict
                                "moderator callback source changed before ACK")
                       | Bare_snapshot ->
                         let%bind untracked = moderator_untracked_data_basis t in
                         if untracked
                         then Ok ()
                         else
                           Error
                             (error
                                Conflict
                                "untracked moderator checkpoint basis changed")
                     in
                     let%bind () =
                       check_creator_custody t schedule_custody_installation
                     in
                     check_native_goal_plan t native_goals)
                   t
                   prepared
               in
               install_committed_transition
                 ~explicit_goal_holds:(Native_goal_plan.fresh_holds native_goals)
                 ~job_custody
                 ?schedule_custody_installation
                 ~queue_custody_installation:
                   (Queue_custody_installation.Inventory inventory)
                 t
                 prepared;
               acknowledged := true;
               borrow.committed <- true;
               acknowledge ();
               install_native_goal_plan t native_goals;
               let%bind () = acknowledge_run () in
               publish_committed_transition t prepared;
               Ok ()))
      in
      Ok ())
;;

let admitted_inference_startup ?constructor ?goal_runtime t execution =
  match constructor with
  | Some scope ->
    (match Initialization_scope.construction scope with
     | Some construction -> Admitted_inference.Startup.Initialization (scope, construction)
     | None -> Ordinary)
  | None ->
    (match execution with
     | Inference_held_input scope -> Admitted_inference.Startup.Input scope
     | Inference_initialization scope | Inference_initialization_job (scope, _) ->
       (match Initialization_scope.construction scope with
        | Some construction -> Initialization (scope, construction)
        | None -> Ordinary)
     | Inference_operation _
     | Inference_invocation _
     | Inference_moderator _
     | Inference_event _
     | Inference_job _ ->
       (match held_authored_of_execution t execution with
        | Some scope -> Authored scope
        | None ->
          Option.value_map
            goal_runtime
            ~default:Admitted_inference.Startup.Ordinary
            ~f:(fun scope -> Goal_runtime scope)))
;;

let check_inference_allocation
      t
      (selected : Admitted_inference.t)
      (current : inference_currentness)
  =
  let open Result.Let_syntax in
  let same_run (left : Agent_protocol.Run.t) (right : Agent_protocol.Run.t) =
    Agent_protocol.Id.Run.equal left.id right.id
    && Agent_protocol.Id.Principal.equal left.principal_id right.principal_id
    && Agent_protocol.Session_ref.equal left.session right.session
    && Agent_protocol.Run_source.equal left.source right.source
  in
  let same_attribution left right =
    Agent_protocol.Id.Goal.equal
      (Goal_work_attribution.goal_id left)
      (Goal_work_attribution.goal_id right)
    && Agent_protocol.Goal_episode.equal
         (Goal_work_attribution.episode left)
         (Goal_work_attribution.episode right)
  in
  let check_basis () =
    let%bind () = admitted_inference_owner t selected in
    let%bind () =
      if
        Option.equal same_run selected.basis.run current.basis.run
        && Option.equal
             same_attribution
             selected.basis.attribution
             current.basis.attribution
        && Option.equal
             Agent_protocol.Id.Operation.equal
             selected.basis.operation_id
             current.basis.operation_id
        && Option.equal
             Agent_protocol.Id.Invocation.equal
             selected.basis.invocation_id
             current.basis.invocation_id
        && Option.equal
             Agent_protocol.Id.Goal.equal
             (Option.map current.basis.attribution ~f:Goal_work_attribution.goal_id)
             (Inference_owner.Registration.goal_id selected.registration)
      then Ok ()
      else Error (error Permission_denied "admitted inference immutable origin changed")
    in
    let%bind () =
      Option.value_map
        (admitted_inference_continuation selected)
        ~default:(Ok ())
        ~f:Admitted_activation.Continuation.check_basis
    in
    Option.value_map
      (admitted_goal_construction selected)
      ~default:(Ok ())
      ~f:(fun preparation ->
        let%bind () = preparation.registered_basis () in
        match preparation.observed with
        | Some current when Recurrence_controller.is_current current -> Ok ()
        | Some _ | None ->
          Error (error Conflict "admitted Goal Init Store custody changed"))
  in
  let%bind () = check_basis () in
  (* All issuer policies precede the fresh timing sample. This is the SAME
     admitted allocation, not a new count/token eligibility check. *)
  let%bind () =
    Option.value_map
      (admitted_inference_continuation selected)
      ~default:(Ok ())
      ~f:(fun continuation -> continuation.policy_admitted_inference ())
  in
  let%bind () =
    Option.value_map
      (admitted_goal_construction selected)
      ~default:(Ok ())
      ~f:(fun preparation -> preparation.registered_policy ())
  in
  let%bind deadline_sample =
    match Inference_owner.Registration.goal_id selected.registration with
    | None -> Ok None
    | Some id ->
      let%map goal =
        Option.bind t.state.goal_catalog ~f:(fun catalog -> Goal_catalog.find catalog id)
        |> Result.of_option ~error:(error Invalid_state "inference Goal is absent")
      in
      Option.map
        (Agent_protocol.Goal.Budget.deadline (Agent_protocol.Goal.budget goal))
        ~f:(fun deadline -> deadline, t.services.now ())
  in
  let%bind () =
    Option.value_map
      (admitted_inference_continuation selected)
      ~default:(Ok ())
      ~f:(fun continuation ->
        let%bind () = continuation.timing () in
        continuation.authority ())
  in
  let%bind () =
    Option.value_map
      (admitted_goal_construction selected)
      ~default:(Ok ())
      ~f:(fun preparation -> preparation.registered_authority ())
  in
  let%bind () = current.check_current () in
  let%bind () =
    match deadline_sample with
    | Some (deadline, now) when Agent_protocol.Timestamp.compare now deadline >= 0 ->
      Error (error Permission_denied "goal deadline reached before submission")
    | None | Some _ -> Ok ()
  in
  (* No reselection after trusted policy/original callbacks. *)
  check_basis ()
;;

let apply_inference_hold
      t
      ~(basis : inference_basis)
      ~constructor
      ~goal_runtime
      ~goal_id
      ~delta
  =
  let open Result.Let_syntax in
  match delta with
  | None -> Ok ()
  | Some delta ->
    (match constructor with
     | Some scope ->
       initialization_transition ~admission_hold:goal_id t scope ~delta ~payloads:[]
     | None when Option.is_some goal_runtime ->
       goal_runtime_transition
         ~admission_hold:goal_id
         t
         (Option.value_exn goal_runtime)
         ~delta
         ~payloads:[]
       |> Result.map ~f:ignore
     | None ->
       transition
         ?run_preparation:basis.preparation
         ~admission_hold:goal_id
         t
         ~delta
         ~payloads:[]
       |> Result.map ~f:ignore)
;;

(* Select only the actual executing native owner. IDs carried by an ordinary
   allocation request never issue a Cause. Direct Model and Async Job inference
   retain their actual native kind and attempt; nested native calls retain the
   separately admitted Invocation member. *)
let inference_policy_work t execution =
  let module C = Policy_cause_data in
  let open Result.Let_syntax in
  let job (job : Agent_protocol.Job.t) =
    match job.kind with
    | Model_call ->
      Ok
        (Some (C.Allocation_work.Model_job_attempt { id = job.id; attempt = job.attempt }))
    | Async_tool ->
      Ok
        (Some (C.Allocation_work.Async_job_attempt { id = job.id; attempt = job.attempt }))
    | Nested_agent | Scheduled_event | Shell_process | Compaction -> Ok None
  in
  match execution with
  | Inference_event borrow ->
    Ok (Some (C.Allocation_work.Event borrow.receipt.context.id))
  | Inference_invocation execution ->
    Ok (Some (Invocation execution.dispatched.context.id))
  | Inference_moderator borrow -> Ok (Some (Invocation borrow.invocation.context.id))
  | Inference_job scope ->
    let%bind current = job_scope_current t scope in
    job current
  | Inference_initialization_job (_, current) -> job current
  | Inference_operation _ | Inference_held_input _ | Inference_initialization _ -> Ok None
;;

let inference_policy_cause t execution =
  let module PC = Policy_canonical_usage in
  let open Result.Let_syntax in
  let%bind work = inference_policy_work t execution in
  match work with
  | None -> Ok None
  | Some work ->
    let%bind member =
      Policy_cause_data.Allocation_work.member
        work
        ~generation:t.state.identity.generation
    in
    let%bind current_source = observation_source t in
    let%bind prefix = policy_native_prefix t.state ~current_source in
    let%bind boundary =
      match execution with
      | Inference_initialization_job (_, job) ->
        let%bind row = Job_custody.find t.job_agent_custody ~job in
        (match row with
         | None -> Ok None
         | Some row ->
           policy_boundary (Job_custody.Row.policy_source row) (fun descriptor ->
             Ok
               (Policy_canonical_usage_source.Standalone.Boundary.Job { job; descriptor })))
      | Inference_operation _
      | Inference_held_input _
      | Inference_initialization _
      | Inference_invocation _
      | Inference_moderator _
      | Inference_event _
      | Inference_job _ -> policy_boundary_of_execution t execution
    in
    let%bind cause =
      match boundary with
      | None -> PC.Source.cause t.state.policy_canonical_usage ~prefix ~member
      | Some boundary ->
        let%map resolved =
          Policy_canonical_usage_source.Standalone.resolve
            t.state.policy_canonical_usage
            ~prefix
            ~member
            ~boundary
        in
        (match resolved with
         | Caused cause -> Some cause
         | Unrelated | Standalone_unrelated _ -> None)
    in
    (match cause with
     | None -> Ok None
     | Some cause ->
       (* A manual physical host is not a causal host, including a Cause with no
         remote targets. Test absence cannot become unrelated execution. *)
       let%bind () =
         match t.descendant_host_binding with
         | Some (Governed { physical; _ }) -> check_descendant_host t physical
         | None | Some (Physical_only _) ->
           Error
             (error
                Permission_denied
                "caused inference requires its actual causal Factory host")
       in
       Ok (Some (cause, work)))
;;

let prepare_inherited_attempt
      t
      ~owner
      ~configuration
      ~before
      ~after
      ~handle
      ~tracking
      ~original
      ~inherited
      ~causal
  =
  let module O = Goal_descendant_occurrence in
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () = require_available_descendant_admission_slot t in
  let%bind controller = require_recurrence_controller t in
  let%bind frame =
    if Int64.equal t.state.counters.revision Int64.max_value
    then Error (error Resource_limit "inherited inference session revision is exhausted")
    else
      O.Frame.create
        ~session:(Recurrence_controller.session controller)
        ~generation:t.state.identity.generation
        ~candidate_session_revision:(Int64.succ t.state.counters.revision)
  in
  let%bind occurrence =
    O.attempt
      frame
      ~ordinal:(Inference_ledger.Handle.ordinal handle)
      ~operation_id:(Inference_ledger.Handle.operation_id handle)
      ~invocation_id:(Inference_ledger.Handle.invocation_id handle)
  in
  let writer_attempted = ref false in
  let%bind physical =
    if inherited
    then
      prepare_descendant_admission_slot t ~occurrence ~writer_attempted
      |> Result.map ~f:Option.some
    else Ok None
  in
  let%bind causal =
    match causal with
    | None -> Ok None
    | Some (cause, work) ->
      let%bind host =
        match t.descendant_host_binding with
        | Some (Governed _ as host) -> Ok host
        | None | Some (Physical_only _) ->
          Error (error Permission_denied "causal inference host is unavailable")
      in
      let physical = physical_descendant_host host in
      let%bind () = check_descendant_host t physical in
      let%bind basis =
        capture_child_accounting_basis t ~source_owner:physical.source_owner
      in
      let preparation =
        C.Preparation.
          { identity = ref ()
          ; basis
          ; cause = Policy_cause_data.key cause
          ; work
          ; occurrence
          ; set_claim = None
          }
      in
      let%map slot = C.Slot.create preparation in
      let reservations =
        { native_set = slot.reservations; actual_attempts = []; association = None }
      in
      let transport =
        { identity = ref ()
        ; domain = (Stdlib.Domain.self () :> int)
        ; initial = Initial_unobserved
        ; corrections = []
        }
      in
      Some { slot; reservations; cause; host; transport; preview = None }
  in
  let%bind arms =
    match physical, causal with
    | Some descendant, None -> Ok (Descendant_attempt descendant)
    | None, Some causal -> Ok (Policy_causal_attempt causal)
    | Some descendant, Some causal -> Ok (Combined_attempt { descendant; causal })
    | None, None ->
      Error (error Invalid_state "governed inference has no actual governed arm")
  in
  let plan =
    { arms
    ; owner
    ; configuration
    ; before
    ; after
    ; handle
    ; tracking
    ; original
    ; acknowledged = None
    }
  in
  let occupancy =
    match arms with
    | Descendant_attempt slot -> Governed_admission_slot.Descendant slot
    | Policy_causal_attempt causal -> Policy_causal { causal = causal.slot; plan }
    | Combined_attempt { descendant; causal } ->
      Combined { descendant; causal = causal.slot; plan }
  in
  let occupied = Some occupancy in
  (* Both actual arms/Set and Plan are prebuilt before this sole publication.
     Nothing fallible or yielding follows ownership publication before return. *)
  t.governed_admission_slot <- occupied;
  Ok plan
;;

let prepare_legacy_attempt
      ?origin_observation
      ?run_preparation
      t
      owner
      relation
      operation_id
      invocation_id
      configuration
  =
  let open Result.Let_syntax in
  let%bind () = require_settled_inference_usage t in
  let%bind () = validate_inference_owner t owner in
  let%bind () =
    if
      Int.equal (Graph_owner.generation owner) t.state.identity.generation
      &&
      match Graph_owner.phase owner with
      | Open -> true
      | Sealed | Finished -> false
    then Ok ()
    else Error (error Conflict "inference graph excludes new attempts")
  in
  let%bind inherited = inference_requires_descendant_admission t origin_observation in
  let%bind () =
    if inherited then require_available_descendant_admission_slot t else Ok ()
  in
  let before = t.state.inference_ledger in
  let%bind protected_ordinals =
    Canonical_usage_update.protected_ordinals
      ?policy_usage:t.state.policy_canonical_usage
      before
      ~accounts:t.state.goal_accounts
      ~delegated_usage:t.state.delegated_usage
  in
  let%bind ledger, handle, tracking =
    Inference_ledger.admit
      ~protected_ordinals
      before
      ~source:(Graph_owner.source owner)
      ~relation
      ~operation_id
      ~invocation_id
      ~configuration
    |> Result.map_error ~f:inference_error
  in
  if inherited
  then (
    let%map plan =
      prepare_inherited_attempt
        t
        ~owner
        ~configuration
        ~before
        ~after:ledger
        ~handle
        ~tracking
        ~original:(Inherited_attempt.Original.Legacy { preparation = run_preparation })
        ~inherited:true
        ~causal:None
    in
    Inherited_attempt.Prepared.Inherited plan)
  else (
    let%map () = commit_inference_ledger ?run_preparation t ledger in
    Graph_owner.register
      owner
      ~initial_preparation:run_preparation
      ~handle
      ~configuration
      ~goal_id:None;
    Inherited_attempt.Prepared.Ordinary
      (Inference_allocation.Host.create
         ~handle
         ~submission_guard:Inference_runtime.Submission_guard.empty))
;;

let plan_recovery_attempt t execution configuration handle ~tracking =
  let open Option.Let_syntax in
  match execution, (Inference_ledger.Handle.scope handle).relation with
  | Inference_operation (operation, _), Root ->
    let%bind source_revision =
      Configuration_capture.recovery_source_revision
        t.configuration_capture
        ~operation_id:operation.id
        ~configuration
    in
    Recovery_effective_receipts.allocate
      t.state
      ~source_revision
      handle
      ~tracking
      configuration
  | _ -> None
;;

let prepare_runtime_attempt ?origin_observation t execution owner relation configuration =
  let open Result.Let_syntax in
  let%bind () = require_settled_inference_usage t in
  let%bind () =
    match execution with
    | Inference_initialization _ ->
      Error
        (error
           Permission_denied
           "initializer inference requires its exact admitted running model Job")
    | Inference_held_input _
    | Inference_initialization_job _
    | Inference_operation _
    | Inference_invocation _
    | Inference_moderator _
    | Inference_event _
    | Inference_job _ -> Ok ()
  in
  let%bind () = validate_inference_owner t owner in
  let%bind () =
    if
      Int.equal (Graph_owner.generation owner) t.state.identity.generation
      &&
      match Graph_owner.phase owner with
      | Open -> true
      | Sealed | Finished -> false
    then Ok ()
    else Error (error Conflict "inference graph excludes new attempts")
  in
  let%bind () =
    match execution with
    | Inference_held_input scope -> input_graph_basis t scope owner
    | Inference_initialization _
    | Inference_initialization_job _
    | Inference_operation _
    | Inference_invocation _
    | Inference_moderator _
    | Inference_event _
    | Inference_job _ -> Ok ()
  in
  let%bind current = authorized_inference_execution_basis t execution in
  let basis = current.basis in
  let%bind causal = inference_policy_cause t execution in
  let%bind constructor = initialization_of_inference_execution t execution in
  let goal_runtime = goal_runtime_of_execution t execution in
  let goal_constructor =
    Option.bind constructor ~f:(fun scope ->
      match Initialization_scope.construction scope with
      | Some (Runtime_construction.Existing_goal _ as construction) ->
        Some (scope, construction)
      | Some (Initial _ | Delegated_load _) | None -> None)
  in
  let%bind decision =
    Goal_charge_admission.prepare
      t.state
      ~attribution:basis.attribution
      ~now:(t.services.now ())
      ~dimension:Attempt
  in
  match decision with
  | Deferred deferred -> Error (goal_capacity_deferred deferred)
  | Held { goal_id; reason = _; delta } ->
    let%bind () =
      apply_inference_hold t ~basis ~constructor ~goal_runtime ~goal_id ~delta
    in
    Error (error Permission_denied "goal policy holds fresh inference admission")
  | (Unbound | Ready _) as decision ->
    let%bind inherited = inference_requires_descendant_admission t origin_observation in
    let%bind () =
      if inherited || Option.is_some causal
      then require_available_descendant_admission_slot t
      else Ok ()
    in
    let before = t.state.inference_ledger in
    let%bind protected_ordinals =
      Canonical_usage_update.protected_ordinals
        ?policy_usage:t.state.policy_canonical_usage
        t.state.inference_ledger
        ~accounts:t.state.goal_accounts
        ~delegated_usage:t.state.delegated_usage
    in
    let%bind ledger, handle, tracking =
      Inference_ledger.admit
        ~protected_ordinals
        t.state.inference_ledger
        ~source:(Graph_owner.source owner)
        ~relation
        ~operation_id:basis.operation_id
        ~invocation_id:basis.invocation_id
        ~configuration
      |> Result.map_error ~f:inference_error
    in
    let admission =
      match decision with
      | Unbound -> None
      | Ready ready ->
        Some
          ( Goal_charge_admission.goal_id ready
          , Goal_accounting.Admission.Attempt
              { episode = Goal_charge_admission.episode ready; handle; tracking } )
      | Held _ | Deferred _ -> assert false
    in
    let allocation_scope =
      (* Only the shared admitted constructor opens an immutable Init graph.
         Ordinary and prepared initialization keep their original graph writer. *)
      let common_constructor =
        Option.filter constructor ~f:(fun scope ->
          Option.is_some (Initialization_scope.construction scope))
      in
      match common_constructor, goal_runtime, held_authored_of_execution t execution with
      | Some scope, _, _ ->
        Some (Held_inference_allocation_acknowledgement.Scope.Initialization scope)
      | None, Some scope, _ -> Some (Goal_runtime scope)
      | None, None, Some scope -> Some (Authored scope)
      | None, None, None -> None
    in
    let allocation_acknowledgement =
      Option.map allocation_scope ~f:(fun scope ->
        { Held_inference_allocation_acknowledgement.scope
        ; owner
        ; ledger
        ; handle
        ; configuration
        ; goal_id = Option.map admission ~f:fst
        })
    in
    let original_check =
      match goal_constructor with
      | Some (scope, construction) ->
        Some
          (fun () ->
            let%bind () = check_runtime_construction_effect construction in
            let%bind () = current.check_current () in
            let%bind () = validate_initialization_scope_basis t scope in
            Runtime_construction.check_basis construction)
      | None ->
        (match goal_runtime, execution with
         | Some scope, _ ->
           Some
             (fun () ->
               let%bind () =
                 check_runtime_construction_effect (Existing_goal scope.continuation)
               in
               let%bind () = current.check_current () in
               goal_runtime_scope_basis t scope)
         | None, Inference_held_input scope ->
           Some
             (fun () ->
               let%bind () = check_held_effect scope.continuation in
               let%bind () = Held_input_scope.parsing scope in
               input_graph_basis t scope owner)
         | ( None
           , ( Inference_initialization _
             | Inference_initialization_job _
             | Inference_operation _
             | Inference_invocation _
             | Inference_moderator _
             | Inference_event _
             | Inference_job _ ) ) -> held_startup_effect t basis.preparation)
    in
    if inherited || Option.is_some causal
    then (
      let check_before () =
        let%bind () = current.check_current () in
        Option.value_map original_check ~default:(Ok ()) ~f:(fun check -> check ())
      in
      let original =
        Inherited_attempt.Original.Runtime
          { execution
          ; basis
          ; startup = admitted_inference_startup ?constructor ?goal_runtime t execution
          ; check_before
          ; admission
          }
      in
      let%map plan =
        prepare_inherited_attempt
          t
          ~owner
          ~configuration
          ~before
          ~after:ledger
          ~handle
          ~tracking
          ~original
          ~inherited
          ~causal
      in
      Inherited_attempt.Prepared.Inherited plan)
    else (
      let recovery_allocation =
        plan_recovery_attempt t execution configuration handle ~tracking
      in
      let%bind () =
        commit_inference_ledger
          ?recovery_allocation
          ?allocation_acknowledgement
          ?run_preparation:basis.preparation
          ?admission
          ?check_before_commit:original_check
          t
          ledger
      in
      (match allocation_acknowledgement with
       | Some _ -> ()
       | None ->
         Graph_owner.register
           owner
           ~initial_preparation:basis.preparation
           ~handle
           ~configuration
           ~goal_id:(Option.map admission ~f:fst));
      (* Capture the SAME actual registration and startup scope now. A failed
       invariant check is deferred to submission so graph tracking receives the
       acknowledged handle and can release it through its normal finalizer. *)
      let selected =
        let%map registration = inference_registration t owner handle in
        { Admitted_inference.execution
        ; owner
        ; registration
        ; handle
        ; tracking
        ; basis
        ; startup = admitted_inference_startup ?constructor ?goal_runtime t execution
        }
      in
      let submission_guard =
        Inference_runtime.Submission_guard.create ~refresh:(fun () ->
          let refreshed =
            let%bind selected = selected in
            let%bind () = refresh_admitted_inference t selected in
            call t (Refresh_inference selected)
          in
          match refreshed with
          | Ok check -> check
          | Error error -> raise (Inference_allocation.Rejected error))
      in
      Ok
        (Inherited_attempt.Prepared.Ordinary
           (Inference_allocation.Host.create ~handle ~submission_guard)))
;;

let inherited_attempt_preparation (plan : Inherited_attempt.Plan.t) =
  match plan.original with
  | Legacy { preparation } -> preparation
  | Runtime { basis; _ } -> basis.preparation
;;

let inherited_attempt_original_check t (plan : Inherited_attempt.Plan.t) =
  let open Result.Let_syntax in
  let%bind () = validate_inference_owner t plan.owner in
  let%bind () =
    if
      Int.equal (Graph_owner.generation plan.owner) t.state.identity.generation
      &&
      match Graph_owner.phase plan.owner with
      | Open -> true
      | Sealed | Finished -> false
    then Ok ()
    else Error (error Conflict "inherited inference graph excludes a fresh attempt")
  in
  match plan.original with
  | Legacy { preparation } ->
    let%bind () = require_selected_or_held_execution t preparation in
    Option.value_map preparation ~default:(Ok ()) ~f:(check_run_preparation t)
  | Runtime { check_before; _ } -> check_before ()
;;

let inherited_attempt_goal_decision t (plan : Inherited_attempt.Plan.t) =
  match plan.original with
  | Legacy _ -> Ok None
  | Runtime { basis; _ } ->
    Goal_charge_admission.prepare
      t.state
      ~attribution:basis.attribution
      ~now:(t.services.now ())
      ~dimension:Attempt
    |> Result.map ~f:Option.some
;;

let validate_inherited_attempt_goal
      (plan : Inherited_attempt.Plan.t)
      (decision : Goal_charge_admission.decision option)
  =
  match plan.original, decision with
  | Legacy _, None -> Ok ()
  | Runtime { admission = None; _ }, Some Unbound -> Ok ()
  | ( Runtime
        { admission = Some (goal_id, Goal_accounting.Admission.Attempt { episode; _ })
        ; _
        }
    , Some (Ready ready) )
    when Agent_protocol.Id.Goal.equal goal_id (Goal_charge_admission.goal_id ready)
         && Agent_protocol.Goal_episode.equal
              episode
              (Goal_charge_admission.episode ready) -> Ok ()
  | Runtime _, Some (Deferred deferred) -> Error (goal_capacity_deferred deferred)
  | Runtime _, Some (Held _) ->
    Error (error Permission_denied "goal policy holds fresh inference admission")
  | Legacy _, Some _ | Runtime _, None | Runtime _, Some (Unbound | Ready _) ->
    Error (error Conflict "inherited inference Goal admission changed before writer")
;;

let check_inherited_attempt_goal t plan =
  let%bind.Result decision = inherited_attempt_goal_decision t plan in
  validate_inherited_attempt_goal plan decision
;;

let prepare_inherited_attempt_goal t (plan : Inherited_attempt.Plan.t) =
  let open Result.Let_syntax in
  let%bind decision = inherited_attempt_goal_decision t plan in
  let%bind () =
    match plan.original, decision with
    | Runtime { basis; startup; _ }, Some (Held { goal_id; delta; reason = _ }) ->
      let constructor, goal_runtime =
        match startup with
        | Initialization (scope, _) -> Some scope, None
        | Goal_runtime scope -> None, Some scope
        | Ordinary | Input _ | Authored _ -> None, None
      in
      apply_inference_hold t ~basis ~constructor ~goal_runtime ~goal_id ~delta
    | (Legacy _ | Runtime _), (None | Some (Unbound | Ready _ | Deferred _)) -> Ok ()
    | Legacy _, Some (Held _) ->
      Error (error Invalid_state "legacy inference has no bound Goal hold")
  in
  validate_inherited_attempt_goal plan decision
;;

let check_causal_plan ?write t (causal : causal_plan_arm) =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () = C.Slot.check_owner causal.slot ~issuer:t.inference_owner_identity in
  let%bind () =
    if causal.slot.cancellation_requested
    then Error (error Conflict "causal canonical admission was cancelled")
    else Ok ()
  in
  let%bind () =
    match t.governed_admission_slot with
    | Some (Policy_causal { causal = actual; _ } | Combined { causal = actual; _ })
      when phys_equal actual causal.slot -> Ok ()
    | None | Some (Descendant _ | Policy_causal _ | Combined _) ->
      Error (error Conflict "causal inference lost its SAME actual occupancy")
  in
  let%bind () =
    match write, causal.slot.phase with
    | None, Preparing -> Ok ()
    | Some expected, Writer_prepared actual when phys_equal expected actual -> Ok ()
    | ( (None | Some _)
      , (Preparing | Writer_prepared _ | Acknowledged _ | Sealed _ | Released _) ) ->
      Error (error Conflict "causal inference changed its canonical writer phase")
  in
  let%bind () = check_child_accounting_capture t causal.slot.preparation.basis in
  match t.descendant_host_binding, causal.host with
  | Some actual, Governed { physical; _ } when phys_equal actual causal.host ->
    check_descendant_host t physical
  | None, (Physical_only _ | Governed _) | Some _, (Physical_only _ | Governed _) ->
    Error (error Conflict "causal inference lost its SAME actual Factory host")
;;

let inherited_attempt_included t (plan : Inherited_attempt.Plan.t) roots =
  let module R = Descendant_admission_data in
  let open Result.Let_syntax in
  match inherited_attempt_physical plan, roots with
  | None, None -> Ok None
  | Some slot, Some (roots : R.Before_writer.t) ->
    let%bind () = check_descendant_admission_slot t slot in
    let%bind () = check_descendant_before_writer roots in
    let%bind () =
      if
        phys_equal roots.preparation slot.preparation
        && phys_equal roots.reservations slot.reservations
      then Ok ()
      else Error (error Conflict "inference preview has another physical root vector")
    in
    let%bind descendants, children = descendant_components t.state in
    let%bind reservations = descendant_reservations roots.reservations in
    let receipts =
      List.map reservations ~f:(fun (reservation : R.Reservation.t) ->
        Goal_descendant_included.create reservation.pending)
    in
    let canonical = Goal_descendants.Canonical.Attempt (plan.handle, plan.tracking) in
    let%map included =
      Goal_descendants.record_included
        descendants
        ~children
        ~before:plan.before
        ~after:plan.after
        ~canonical
        ~occurrence:(Descendant_preparation.occurrence slot.preparation)
        ~receipts
    in
    Some (included, receipts)
  | None, Some _ | Some _, None ->
    Error (error Conflict "inference preview requires exactly its actual physical arm")
;;

let inherited_attempt_accounting t (plan : Inherited_attempt.Plan.t) ~included =
  let module PC = Policy_canonical_usage in
  let open Result.Let_syntax in
  let native_admission =
    match plan.original with
    | Legacy _ -> None
    | Runtime { admission; _ } -> admission
  in
  let%bind policy_admission =
    match inherited_attempt_causal plan with
    | None -> Ok None
    | Some causal ->
      let%bind () = check_causal_plan t causal in
      let%bind live_prefix = Session_state.policy_context t.state in
      let descendants_after =
        match included with
        | None -> t.state.goal_descendants
        | Some (update, _) -> Some (Goal_descendants.Update.accounting update)
      in
      PC.Admission.create
        ~cause:causal.slot.preparation.cause
        ~work:causal.slot.preparation.work
        ~live_prefix
        ~descendants_after
        ~canonical:(Goal_descendants.Canonical.Attempt (plan.handle, plan.tracking))
        ~occurrence:causal.slot.preparation.occurrence
      |> Result.map ~f:Option.some
  in
  let%map accounting =
    Canonical_usage_update.prepare
      ?policy_usage:t.state.policy_canonical_usage
      ?policy_admission
      plan.before
      ~accounts:t.state.goal_accounts
      ~catalog:t.state.goal_catalog
      ~after:plan.after
      ~delegated_usage:t.state.delegated_usage
      ~admission:native_admission
  in
  accounting, policy_admission
;;

let check_causal_inline_policies t ~admitted policies =
  let open Result.Let_syntax in
  List.fold_result policies ~init:() ~f:(fun () (target, policy) ->
    let%bind controller = require_recurrence_controller t in
    let%bind () =
      if
        Agent_protocol.Session_ref.equal
          (Policy_cause_data.Goal_target.owner target)
          (Recurrence_controller.session controller)
        && Agent_protocol.Id.Goal.equal
             (Policy_cause_data.Goal_target.goal_id target)
             (Goal_root_policy.goal_id policy)
      then Ok ()
      else Error (error Conflict "inline Goal policy belongs to another actual target")
    in
    if admitted
    then Goal_root_policy.admitted policy ~state:t.state ~now:(t.services.now ())
    else (
      let%bind decision =
        Goal_root_policy.Causal.before_reserve
          policy
          ~state:t.state
          ~now:(t.services.now ())
      in
      match decision with
      | Decided Allow -> Ok ()
      | Deferred Reserved ->
        Error
          (goal_capacity_deferred
             { Goal_charge_admission.goal_id = Goal_root_policy.goal_id policy
             ; reason = Reserved
             })
      | Deferred Unknown ->
        Error
          (goal_capacity_deferred
             { Goal_charge_admission.goal_id = Goal_root_policy.goal_id policy
             ; reason = Unknown
             })
      | Decided (Hold _) ->
        Error (error Permission_denied "inline Goal policy holds causal inference")))
;;

let prepare_causal_inline_policies t (plan : inherited_attempt_plan) policies =
  let open Result.Let_syntax in
  List.fold_result policies ~init:() ~f:(fun () (target, policy) ->
    let%bind decision =
      Goal_root_policy.Causal.before_reserve
        policy
        ~state:t.state
        ~now:(t.services.now ())
    in
    match decision with
    | Decided Allow -> Ok ()
    | Deferred Reserved ->
      Error
        (goal_capacity_deferred
           { Goal_charge_admission.goal_id = Goal_root_policy.goal_id policy
           ; reason = Reserved
           })
    | Deferred Unknown ->
      Error
        (goal_capacity_deferred
           { Goal_charge_admission.goal_id = Goal_root_policy.goal_id policy
           ; reason = Unknown
           })
    | Decided (Hold reason) ->
      let goal_id = Policy_cause_data.Goal_target.goal_id target in
      let%bind delta = Goal_charge_admission.hold_delta t.state ~goal_id ~reason in
      let%bind () =
        match plan.original with
        | Legacy _ ->
          Error (error Invalid_state "legacy inference has no causal native owner")
        | Runtime { basis; startup; _ } ->
          let constructor, goal_runtime =
            match startup with
            | Initialization (scope, _) -> Some scope, None
            | Goal_runtime scope -> None, Some scope
            | Ordinary | Input _ | Authored _ -> None, None
          in
          apply_inference_hold t ~basis ~constructor ~goal_runtime ~goal_id ~delta
      in
      Error (error Permission_denied "inline Goal policy holds causal inference"))
;;

let preview_inherited_attempt t (plan : Inherited_attempt.Plan.t) physical =
  let module PC = Policy_canonical_usage in
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () = inherited_attempt_original_check t plan in
  let%bind () =
    match inherited_attempt_causal plan with
    | None -> Ok ()
    | Some causal -> check_causal_plan t causal
  in
  let%bind () = prepare_inherited_attempt_goal t plan in
  let%bind () =
    if phys_equal plan.before t.state.inference_ledger
    then Ok ()
    else Error (error Conflict "inference preview lost its exact native ledger")
  in
  let%bind included = inherited_attempt_included t plan physical in
  match inherited_attempt_causal plan with
  | None -> Ok ()
  | Some causal ->
    let%bind accounting, _ = inherited_attempt_accounting t plan ~included in
    let%bind selection =
      Option.bind (Canonical_usage_update.policy_update accounting) ~f:PC.Update.selection
      |> Result.of_option
           ~error:
             (error
                Invalid_state
                "causal inference preview has no actual canonical selection")
    in
    (match causal.preview with
     | Some previous ->
       if PC.Selection.equal previous.selection selection
       then check_causal_inline_policies t ~admitted:false previous.inline_policies
       else
         Error (error Conflict "causal inference changed its frozen canonical selection")
     | None ->
       let%bind controller = require_recurrence_controller t in
       let%bind inline_policies =
         PC.Selection.choices selection
         |> List.filter_map ~f:(fun choice ->
           let target = PC.Choice.target choice in
           if
             Agent_protocol.Session_ref.equal
               (Policy_cause_data.Goal_target.owner target)
               (Recurrence_controller.session controller)
           then Some target
           else None)
         |> List.map ~f:(fun target ->
           let%map.Result policy =
             descendant_policy_for_begin
               t
               ~goal_id:(Policy_cause_data.Goal_target.goal_id target)
               ~now:(t.services.now ())
           in
           target, policy)
         |> Result.all
       in
       let%bind () = prepare_causal_inline_policies t plan inline_policies in
       let%bind _ =
         C.Set.freeze causal.reservations.native_set ~cause:causal.cause ~selection
       in
       let preview = Some { selection; inline_policies } in
       causal.preview <- preview;
       Ok ())
;;

let inherited_attempt_before_arms (plan : Inherited_attempt.Plan.t) before =
  match plan.arms, before with
  | Descendant_attempt _, Descendant_before physical -> Ok (Some physical, None)
  | Policy_causal_attempt _, Causal_before causal -> Ok (None, Some causal)
  | Combined_attempt _, Combined_before (physical, causal) ->
    Ok (Some physical, Some causal)
  | ( (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _)
    , (Descendant_before _ | Causal_before _ | Combined_before _) ) ->
    Error (error Conflict "governed inference changed its closed before-writer arms")
;;

let commit_inherited_attempt t (plan : Inherited_attempt.Plan.t) before_writer =
  let module R = Descendant_admission_data in
  let module C = Goal_causal_admission_custody in
  let module A = Inherited_attempt in
  let open Result.Let_syntax in
  match plan.acknowledged with
  | Some acknowledgement -> Ok (A.Committed.Acknowledged acknowledgement)
  | None ->
    let%bind () = require_settled_inference_usage t in
    let%bind physical, causal_before = inherited_attempt_before_arms plan before_writer in
    let%bind () =
      match inherited_attempt_causal plan with
      | Some causal ->
        (match causal.slot.phase with
         | Writer_prepared write -> Session_commit_attempt.unresolved write.writer
         | Acknowledged _ | Sealed _ | Released _ ->
           Error
             (error Conflict "causal canonical Plan has already been attempted or sealed")
         | Preparing -> check_causal_plan t causal)
      | None ->
        (match inherited_attempt_physical plan with
         | Some slot when !(slot.preparation.writer_attempted) ->
           Error (error Conflict "physical canonical writer remains unconfirmed")
         | Some _ -> Ok ()
         | None -> Error (error Invalid_state "governed Plan has no actual arm"))
    in
    let%bind () = inherited_attempt_original_check t plan in
    let%bind () = prepare_inherited_attempt_goal t plan in
    let%bind () =
      if phys_equal plan.before t.state.inference_ledger
      then Ok ()
      else Error (error Conflict "governed inference changed its exact native ledger")
    in
    let%bind () = preview_inherited_attempt t plan physical in
    let%bind included = inherited_attempt_included t plan physical in
    let%bind accounting, _ = inherited_attempt_accounting t plan ~included in
    let%bind () =
      match inherited_attempt_causal plan, causal_before with
      | None, None -> Ok ()
      | Some causal, Some before ->
        let%bind () = check_causal_before_writer before in
        if
          phys_equal before.preparation causal.slot.preparation
          && phys_equal before.reservations causal.reservations
        then Ok ()
        else
          Error
            (error Conflict "governed inference has another actual causal root vector")
      | None, Some _ | Some _, None ->
        Error (error Conflict "governed inference lost its causal before-writer arm")
    in
    let native_admission =
      match plan.original with
      | Legacy _ -> None
      | Runtime { admission; _ } -> admission
    in
    let accounting_deltas =
      if Canonical_usage_update.accounts_changed accounting
      then
        [ Session_delta.Goal_accounts_changed
            (Option.value_exn (Canonical_usage_update.accounts accounting))
        ]
      else []
    in
    let recovery_allocation =
      match plan.original with
      | Legacy _ -> None
      | Runtime { execution; _ } ->
        plan_recovery_attempt
          t
          execution
          plan.configuration
          plan.handle
          ~tracking:plan.tracking
    in
    let changes =
      (Session_delta.inference_ledger_update
         ?policy_update:(Canonical_usage_update.policy_update accounting)
         plan.after
         ~delegated_usage:(Canonical_usage_update.delegated_usage accounting)
       :: accounting_deltas)
      @
      match included with
      | None -> []
      | Some (update, _) -> [ Session_delta.Goal_descendants_changed update ]
    in
    let run_preparation = inherited_attempt_preparation plan in
    let previous = t.state in
    let%bind candidate =
      prepare_inference_transition
        ?run_preparation
        t
        ~changes
        ~recovery_allocation
        ~payloads:
          [ Agent_protocol.Event.Durable.Payload.Session_updated
              (Session_state.summary { t.state with inference_ledger = plan.after })
          ]
    in
    let canonical = Goal_descendants.Canonical.Attempt (plan.handle, plan.tracking) in
    let%bind physical_ack, slot_acknowledgement =
      match inherited_attempt_physical plan, physical, included with
      | None, None, None -> Ok (None, None)
      | Some slot, Some roots, Some (_, receipts) ->
        let descendant =
          { R.Acknowledgement.preparation = slot.preparation
          ; identity = ref ()
          ; installed = candidate.state
          ; candidate
          ; edge = Attempt { before = plan.before; after = plan.after; canonical }
          ; receipts
          ; reservations = roots.reservations
          }
        in
        let%map install =
          prepare_descendant_admission_slot_ack t slot ~acknowledgement:descendant
        in
        Some descendant, Some install
      | (None | Some _), (None | Some _), (None | Some _) ->
        Error (error Conflict "governed inference lost its actual physical included edge")
    in
    let%bind causal_ack, causal_install =
      match inherited_attempt_causal plan with
      | None -> Ok (None, None)
      | Some causal ->
        let%bind preview =
          Result.of_option
            causal.preview
            ~error:(error Conflict "causal canonical Plan has no frozen selection")
        in
        let%bind selection =
          Option.bind
            (Canonical_usage_update.policy_update accounting)
            ~f:Policy_canonical_usage.Update.selection
          |> Result.of_option
               ~error:
                 (error Invalid_state "causal canonical update has no actual selection")
        in
        let%bind () =
          if Policy_canonical_usage.Selection.equal preview.selection selection
          then Ok ()
          else
            Error
              (error
                 Conflict
                 "causal canonical selection changed after root reservations")
        in
        let writer =
          Session_commit_attempt.create
            ~context:
              (Causal_canonical
                 { slot = causal.slot.identity
                 ; preparation = causal.slot.preparation.identity
                 })
            ~previous
            ~candidate
        in
        let write : C.Canonical_write.t =
          { previous; candidate; canonical; selection; writer }
        in
        let native : C.Acknowledgement.t =
          { identity = causal.transport.identity
          ; preparation = causal.slot.preparation
          ; write
          ; installed = candidate.state
          ; reservations = causal.reservations.native_set
          }
        in
        let acknowledgement =
          { native_acknowledgement = native
          ; canonical_slot = causal.slot
          ; callee = t
          ; actual_reservations = causal.reservations
          ; transport = causal.transport
          }
        in
        let install : C.Canonical_install.t =
          { slot = causal.slot
          ; write
          ; acknowledgement = native
          ; next = Acknowledged native
          }
        in
        Ok (Some acknowledgement, Some install)
    in
    let%bind governed =
      match physical_ack, causal_ack with
      | Some physical, None -> Ok (Descendant_ack physical)
      | None, Some causal -> Ok (Causal_ack causal)
      | Some physical, Some causal -> Ok (Combined_ack (physical, causal))
      | None, None ->
        Error (error Invalid_state "governed inference has no canonical acknowledgement")
    in
    let scope =
      match plan.original with
      | Legacy _ -> None
      | Runtime { startup; _ } ->
        (match startup with
         | Initialization (scope, _) ->
           Some (Held_inference_allocation_acknowledgement.Scope.Initialization scope)
         | Goal_runtime scope -> Some (Goal_runtime scope)
         | Authored scope -> Some (Authored scope)
         | Ordinary | Input _ -> None)
    in
    let allocation_acknowledgement =
      Option.map scope ~f:(fun scope ->
        { Held_inference_allocation_acknowledgement.scope
        ; owner = plan.owner
        ; ledger = plan.after
        ; handle = plan.handle
        ; configuration = plan.configuration
        ; goal_id = Option.map native_admission ~f:fst
        })
    in
    let initialization_acknowledgement =
      match scope with
      | Some (Initialization scope) ->
        Some (Initialization_scope.Acknowledgement.prepare scope candidate.state)
      | Some (Authored _ | Goal_runtime _) | None -> None
    in
    let%bind goal_runtime_acknowledgement =
      match scope with
      | Some (Goal_runtime scope) ->
        Goal_runtime_acknowledgement.prepare t scope ~candidate
        |> Result.map ~f:Option.some
      | Some (Authored _ | Initialization _) | None -> Ok None
    in
    let selected =
      ref (Error (error Invalid_state "governed registration is not installed"))
    in
    let registration =
      ref (Error (error Invalid_state "governed graph registration is not installed"))
    in
    let original =
      match plan.original with
      | Legacy { preparation } ->
        A.Acknowledgement.Original.Legacy { preparation; registration }
      | Runtime { execution; basis; startup; _ } ->
        Runtime { execution; basis; startup; selected }
    in
    let acknowledgement : inherited_attempt_acknowledgement =
      { governed
      ; arms = plan.arms
      ; owner = plan.owner
      ; handle = plan.handle
      ; original
      ; confirmation = None
      }
    in
    let facts =
      Inference_owner.Factual_usage.Host.create
        ~confirm_initial:(fun () ->
          confirm_governed_attempt t acknowledgement |> Result.map ~f:ignore)
        ~correct_usage:(fun () -> correct_governed_attempt acknowledgement)
    in
    let%bind prepared_registration =
      Graph_owner.prepare_registration
        plan.owner
        ~ledger_after:plan.after
        ~initial_preparation:run_preparation
        ~handle:plan.handle
        ~configuration:plan.configuration
        ~goal_id:(Option.map native_admission ~f:fst)
        ~factual_usage:facts
    in
    let own_registration =
      Graph_owner.Prepared_registration.registration prepared_registration
    in
    let registration_success = Ok own_registration in
    let selected_success =
      match plan.original with
      | Legacy _ -> !selected
      | Runtime { execution; basis; startup; _ } ->
        Ok
          { Admitted_inference.execution
          ; owner = plan.owner
          ; registration = own_registration
          ; handle = plan.handle
          ; tracking = plan.tracking
          ; basis
          ; startup
          }
    in
    let scope_install =
      match scope with
      | None -> None
      | Some (Authored scope) ->
        Some
          (Install_authored_graphs
             ( scope
             , if List.mem scope.graphs plan.owner ~equal:phys_equal
               then scope.graphs
               else plan.owner :: scope.graphs ))
      | Some (Goal_runtime scope) ->
        Some
          (Install_goal_graphs
             ( scope
             , if List.mem scope.graphs plan.owner ~equal:phys_equal
               then scope.graphs
               else plan.owner :: scope.graphs ))
      | Some (Initialization scope) ->
        Some (Install_initialization_graphs (scope, scope.graphs))
    in
    let install =
      { plan
      ; acknowledged = Some acknowledgement
      ; causal = causal_install
      ; registration = prepared_registration
      ; scope = scope_install
      }
    in
    (* These records are private until the exact State ACK installs the same
       registration/map and Plan acknowledgement. No getter proves installation. *)
    registration := registration_success;
    selected := selected_success;
    let final_check () =
      let%bind () = require_settled_inference_usage t in
      let%bind () = inherited_attempt_original_check t plan in
      let%bind () = check_inherited_attempt_goal t plan in
      let%bind () =
        if phys_equal previous t.state && phys_equal plan.before t.state.inference_ledger
        then Ok ()
        else Error (error Conflict "governed canonical candidate lost its original State")
      in
      let%bind () =
        Option.value_map physical ~default:(Ok ()) ~f:check_descendant_before_writer
      in
      let%bind () =
        Option.value_map slot_acknowledgement ~default:(Ok ()) ~f:(fun ack ->
          check_descendant_admission_slot_ack t ack ~candidate)
      in
      let%bind () =
        match inherited_attempt_causal plan, causal_install, causal_before with
        | None, None, None -> Ok ()
        | Some causal, Some install, Some before ->
          let%bind () = check_causal_plan ~write:install.write t causal in
          let%bind () = check_causal_before_writer before in
          let%bind preview =
            Result.of_option
              causal.preview
              ~error:(error Conflict "causal preview disappeared")
          in
          check_causal_inline_policies t ~admitted:false preview.inline_policies
        | (None | Some _), (None | Some _), (None | Some _) ->
          Error (error Conflict "causal canonical phase changed")
      in
      let%bind () = Graph_owner.Prepared_registration.check_basis prepared_registration in
      let%bind () =
        Option.value_map allocation_acknowledgement ~default:(Ok ()) ~f:(fun ack ->
          Held_inference_allocation_acknowledgement.check ack ~actor:t ~ledger:plan.after)
      in
      let%bind () =
        Option.value_map
          initialization_acknowledgement
          ~default:(Ok ())
          ~f:Initialization_scope.Acknowledgement.check_basis
      in
      Option.value_map goal_runtime_acknowledgement ~default:(Ok ()) ~f:(fun ack ->
        Goal_runtime_acknowledgement.check ack ~actor:t ~candidate)
    in
    let persist ?causal_canonical_fence () =
      persist_transition
        ?causal_canonical_fence
        ?commit_observation:
          (Option.map causal_install ~f:(fun p ->
             Session_commit_attempt.observation p.write.writer))
        ?descendant_admission_acknowledgement:slot_acknowledgement
        ?run_preparation
        ~check_before_commit:final_check
        t
        candidate
    in
    let execute ?causal_canonical_fence () =
      let%bind () = persist ?causal_canonical_fence () in
      install_committed_transition
        ~inherited_attempt_acknowledgement:install
        ?descendant_admission_acknowledgement:slot_acknowledgement
        ?goal_runtime_acknowledgement
        ?run_preparation
        ?initialization_acknowledgement
        t
        candidate;
      publish_committed_transition t candidate;
      Ok (A.Committed.Acknowledged acknowledgement)
    in
    (match causal_install with
     | None -> execute ()
     | Some install ->
       let writer = install.write.writer in
       let invoke () =
         (* Publish exact write/Plan ownership before invocation or any await.
            The kernel captures every subsequent failure without replay. *)
         install.slot.phase <- Writer_prepared install.write;
         let%bind invocation = Session_commit_attempt.begin_invocation writer in
         Exn.protect
           ~finally:(fun () -> Session_commit_attempt.finish_invocation writer invocation)
           ~f:(fun () ->
             execute
               ~causal_canonical_fence:
                 (Causal_canonical_custody.Fence.Elected
                    (install.slot, install.write, invocation))
               ())
       in
       Session_commit_attempt.perform writer invoke)
;;

let refresh_inference t (selected : Admitted_inference.t) =
  let open Result.Let_syntax in
  let%bind () = admitted_inference_owner t selected in
  let%bind current =
    authorized_inference_execution_basis ~admitted:selected t selected.execution
  in
  let%map () = check_inference_allocation t selected current in
  (* Captured physical registration and scope are checked after every composed
     refresh/auth wait. This closure charges nothing and never reselects them. *)
  fun () ->
    match check_inference_allocation t selected current with
    | Ok () -> ()
    | Error error -> raise (Inference_allocation.Rejected error)
;;

let check_inherited_attempt_ack_owner t (ack : Inherited_attempt.Acknowledgement.t) =
  let open Result.Let_syntax in
  let causal_owner canonical =
    let original = canonical.native_acknowledgement.preparation.basis in
    let%bind controller =
      Causal_factual_basis.owner t ~source_owner:original.source_owner
    in
    if
      phys_equal controller original.controller
      && Recurrence_controller.same_store controller original.controller
    then check_causal_canonical_acknowledgement canonical
    else Error (error Conflict "governed factual ACK lost its actual Factory/controller")
  in
  let physical slot descendant =
    let%bind () = descendant_admission_slot_owner t slot in
    let%bind () = check_descendant_ack descendant in
    if
      phys_equal
        descendant.Descendant_admission_data.Acknowledgement.preparation
        slot.Descendant_admission_slot.preparation
      && phys_equal descendant.reservations slot.reservations
    then Ok ()
    else Error (error Conflict "physical ACK changed its actual slot/Set")
  in
  match ack.arms, ack.governed with
  | Descendant_attempt slot, Descendant_ack descendant -> physical slot descendant
  | Policy_causal_attempt causal, Causal_ack canonical ->
    let%bind () = causal_owner canonical in
    if phys_equal canonical.callee t && phys_equal canonical.canonical_slot causal.slot
    then Ok ()
    else Error (error Conflict "causal ACK changed its actual Actor/slot")
  | Combined_attempt { descendant = slot; causal }, Combined_ack (descendant, canonical)
    ->
    let%bind () = physical slot descendant in
    let%bind () = causal_owner canonical in
    if phys_equal canonical.callee t && phys_equal canonical.canonical_slot causal.slot
    then Ok ()
    else Error (error Conflict "combined ACK changed its actual Actor/slot")
  | ( (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _)
    , (Descendant_ack _ | Causal_ack _ | Combined_ack _) ) ->
    Error (error Conflict "governed ACK changed its closed arms")
;;

let confirm_inherited_inference t (ack : inherited_attempt_acknowledgement) confirmation =
  let module C = Goal_causal_admission_custody in
  let open Result.Let_syntax in
  let%bind () = check_inherited_attempt_ack_owner t ack in
  let physical descendant confirmation =
    if
      phys_equal
        confirmation.Descendant_admission_data.Confirmation.acknowledgement
        descendant
    then
      descendant_confirmation descendant ~imports:confirmation.imports
      |> Result.map ~f:ignore
    else Error (error Conflict "physical confirmation has another actual ACK")
  in
  let%bind causal =
    match ack.governed, confirmation with
    | Descendant_ack descendant, Descendant_confirmation confirmation ->
      let%map () = physical descendant confirmation in
      None
    | Causal_ack canonical, Causal_confirmation confirmation ->
      let%map () = check_causal_confirmation canonical confirmation in
      Some (canonical, confirmation)
    | Combined_ack (descendant, canonical), Combined_confirmation (first, second) ->
      let%bind () = physical descendant first in
      let%map () = check_causal_confirmation canonical second in
      Some (canonical, second)
    | ( (Descendant_ack _ | Causal_ack _ | Combined_ack _)
      , (Descendant_confirmation _ | Causal_confirmation _ | Combined_confirmation _) ) ->
      Error (error Conflict "governed confirmation changed its full closed vector")
  in
  let%bind () =
    match ack.confirmation with
    | None -> Ok ()
    | Some previous ->
      let same =
        match previous, confirmation with
        | Descendant_confirmation a, Descendant_confirmation b -> phys_equal a b
        | Causal_confirmation a, Causal_confirmation b -> phys_equal a b
        | Combined_confirmation (a, b), Combined_confirmation (c, d) ->
          phys_equal a c && phys_equal b d
        | ( (Descendant_confirmation _ | Causal_confirmation _ | Combined_confirmation _)
          , (Descendant_confirmation _ | Causal_confirmation _ | Combined_confirmation _)
          ) -> false
      in
      if same
      then Ok ()
      else
        Error (error Conflict "governed confirmation cannot replace its retained vector")
  in
  let%bind next =
    match causal with
    | None -> Ok None
    | Some (canonical, confirmation) ->
      let slot = canonical.canonical_slot in
      let%bind () =
        match slot.phase with
        | (Acknowledged actual | Released (Confirmed (actual, _)))
          when phys_equal actual canonical.native_acknowledgement -> Ok ()
        | Preparing | Writer_prepared _ | Acknowledged _ | Sealed _ | Released _ ->
          Error (error Conflict "causal confirmation lost its installed canonical slot")
      in
      Ok
        (Some
           ( slot
           , C.Slot.Released
               (Confirmed
                  ( canonical.native_acknowledgement
                  , confirmation.native_confirmation.imports )) ))
  in
  let retained = Some confirmation in
  (* All checks/list construction precede these exact finite assignments. A
     later occupancy is never cleared by a historical confirmation. *)
  let clear =
    match t.governed_admission_slot with
    | Some (Policy_causal { causal; _ } | Combined { causal; _ }) ->
      Option.exists next ~f:(fun (slot, _) -> phys_equal slot causal)
    | None | Some (Descendant _) -> false
  in
  (match next with
   | None -> ()
   | Some (slot, phase) -> slot.phase <- phase);
  ack.confirmation <- retained;
  if clear then t.governed_admission_slot <- None;
  Ok ()
;;

let check_legacy_admitted_inference
      t
      (ack : Inherited_attempt.Acknowledgement.t)
      ~preparation
      ~registration
  =
  let open Result.Let_syntax in
  let%bind () = check_inherited_attempt_ack_owner t ack in
  let%bind captured = !registration in
  let%bind current = inference_registration t ack.owner ack.handle in
  let%bind () =
    if
      phys_equal current captured
      && Inference_owner.Registration.policy_is_current captured
    then Ok ()
    else Error (error Conflict "inherited legacy inference registration changed")
  in
  Option.value_map preparation ~default:(Ok ()) ~f:(check_run_preparation t)
;;

let refresh_inherited_inference
      t
      (ack : Inherited_attempt.Acknowledgement.t)
      confirmation
      views
  =
  let open Result.Let_syntax in
  let%bind () = check_inherited_attempt_ack_owner t ack in
  let physical descendant confirmed views =
    if
      phys_equal
        confirmed.Descendant_admission_data.Confirmation.acknowledgement
        descendant
      && phys_equal
           views.Descendant_admission_data.Admitted_views.acknowledgement
           descendant
      && phys_equal views.confirmation confirmed
    then check_descendant_admitted_views views
    else Error (error Conflict "physical admitted views have another actual ACK/vector")
  in
  let causal canonical confirmed (views : causal_admitted_views) =
    if
      phys_equal views.acknowledgement canonical
      && phys_equal views.confirmation confirmed
    then check_causal_admitted_views views
    else Error (error Conflict "causal admitted views have another actual ACK/vector")
  in
  let check_roots () =
    match ack.governed, confirmation, views with
    | Descendant_ack a, Descendant_confirmation b, Descendant_views c -> physical a b c
    | Causal_ack a, Causal_confirmation b, Causal_views c -> causal a b c
    | Combined_ack (a, b), Combined_confirmation (c, d), Combined_views (e, f) ->
      let%bind () = physical a c e in
      causal b d f
    | ( (Descendant_ack _ | Causal_ack _ | Combined_ack _)
      , (Descendant_confirmation _ | Causal_confirmation _ | Combined_confirmation _)
      , (Descendant_views _ | Causal_views _ | Combined_views _) ) ->
      Error (error Conflict "governed admitted refresh changed its closed arms")
  in
  let%bind original =
    match ack.original with
    | Legacy { preparation; registration } ->
      let%map () = check_legacy_admitted_inference t ack ~preparation ~registration in
      fun () ->
        (match check_legacy_admitted_inference t ack ~preparation ~registration with
         | Ok () -> ()
         | Error e -> raise (Inference_allocation.Rejected e))
    | Runtime { selected; _ } ->
      let%bind selected = !selected in
      refresh_inference t selected
  in
  let check () =
    let%bind () = check_roots () in
    let%bind () =
      match ack.arms with
      | Descendant_attempt slot -> check_descendant_host t slot.binding
      | Policy_causal_attempt causal | Combined_attempt { causal; _ } ->
        (match t.descendant_host_binding, causal.host with
         | Some actual, Governed { physical; _ } when phys_equal actual causal.host ->
           let%bind () = check_descendant_host t physical in
           let%bind preview =
             Result.of_option
               causal.preview
               ~error:(error Conflict "causal admitted policy preview lost")
           in
           check_causal_inline_policies t ~admitted:true preview.inline_policies
         | None, (Physical_only _ | Governed _) | Some _, (Physical_only _ | Governed _)
           -> Error (error Conflict "causal admitted host was displaced"))
    in
    match ack.original with
    | Legacy _ -> Ok ()
    | Runtime { execution; _ } -> check_execution_descendant t execution
  in
  let%map () = check () in
  fun () ->
    original ();
    match check () with
    | Ok () -> ()
    | Error e -> raise (Inference_allocation.Rejected e)
;;

let release_inherited_inference t (ack : Inherited_attempt.Acknowledgement.t) =
  let open Result.Let_syntax in
  let%bind () = check_inherited_attempt_ack_owner t ack in
  match ack.original with
  | Legacy { preparation = None; _ } -> release_inference t ack.owner ack.handle
  | Legacy { preparation = Some _; _ } ->
    release_inference
      ~owned_graph:
        { Owned_inference_mutation.scope = Registered ack.owner
        ; owner = ack.owner
        ; acknowledgement = Preserve
        }
      t
      ack.owner
      ack.handle
  | Runtime { basis; startup; _ } ->
    let owned_graph =
      match startup with
      | Initialization (scope, construction) ->
        let graph : Runtime_constructor_graph.t =
          { scope; construction; owner = ack.owner }
        in
        Some
          { Owned_inference_mutation.scope = Initialization graph
          ; owner = ack.owner
          ; acknowledgement = Preserve
          }
      | Input scope ->
        Some
          { Owned_inference_mutation.scope = Input scope
          ; owner = ack.owner
          ; acknowledgement = Preserve
          }
      | Authored scope ->
        Some
          { Owned_inference_mutation.scope = Authored scope
          ; owner = ack.owner
          ; acknowledgement = Preserve
          }
      | Goal_runtime scope ->
        Some
          { Owned_inference_mutation.scope = Goal_runtime scope
          ; owner = ack.owner
          ; acknowledgement = Preserve
          }
      | Ordinary -> None
    in
    release_inference
      ?owned_graph
      ?run_preparation:basis.preparation
      t
      ack.owner
      ack.handle
;;

let handle_inherited_inference_request
  : type a. t -> a Inherited_attempt.Request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t -> function
  | Capture_origin -> capture_descendant_origin_observation t
  | Allocate_runtime (origin_observation, execution, owner, relation, configuration) ->
    prepare_runtime_attempt ?origin_observation t execution owner relation configuration
  | Prepare_legacy
      ( origin_observation
      , run_preparation
      , owner
      , relation
      , operation_id
      , invocation_id
      , configuration ) ->
    let%bind.Result () = require_selected_or_held_execution t run_preparation in
    prepare_legacy_attempt
      ?origin_observation
      ?run_preparation
      t
      owner
      relation
      operation_id
      invocation_id
      configuration
  | Preview (plan, physical) -> preview_inherited_attempt t plan physical
  | Commit (plan, roots) -> commit_inherited_attempt t plan roots
  | Confirm (ack, confirmation) -> confirm_inherited_inference t ack confirmation
  | Seal plan -> seal_governed_plan t plan
  | Retire_closed (plan, closed) -> retire_closed_governed_plan t plan closed
  | Refresh (ack, confirmation, views) ->
    refresh_inherited_inference t ack confirmation views
  | Release ack -> release_inherited_inference t ack
;;

let capture_initialization_recipe_target t scope job_id generation attempt target limits =
  let open Result.Let_syntax in
  let%bind () = validate_initialization_model_job t scope job_id generation attempt in
  let%bind _, binding = find_model_job_target t job_id generation in
  let%bind captured = Model_job_target.capture_recipe binding ~target ~limits in
  initialization_transition
    t
    scope
    ~delta:(Session_delta.Model_job_recipe_target_captured captured)
    ~payloads:[]
;;

let complete_initialization_model_job t scope job_id generation attempt outcome =
  let open Result.Let_syntax in
  (* Acknowledging an already completed attempt remains cleanup after original
     expiry. New provider admission/target capture uses the currentness guard. *)
  let%bind owned = initialization_model_job_is_owned t scope job_id generation attempt in
  let%bind () =
    if owned
    then Ok ()
    else Error (error Conflict "initialization does not own this running model attempt")
  in
  complete_job
    ~initialization_scope:scope
    ?run_preparation:(Initialization_scope.initial_preparation scope)
    t
    job_id
    generation
    attempt
    outcome
;;

module Constructor_model = struct
  module Data = Constructor_model_data
  module Custody = Constructor_model_custody

  type actor = t

  type result_selection =
    | Winner of Agent_protocol.Job.t
    | Selection of Data.selection

  let selected_job = function
    | Data.Cancel_queued { queued; _ } -> queued
    | Complete_model { running; _ } | Interrupt_running { running; _ } -> running
  ;;

  let selected_sample = function
    | Data.Cancel_queued { sample; _ }
    | Complete_model { sample; _ }
    | Interrupt_running { sample; _ } -> sample
  ;;

  let selected (call : Data.call) =
    match call.phase with
    | Selected selection | Terminal_attempt { selection; _ } -> Some selection
    | Cancel_attempt plan ->
      (match plan.prior with
       | Was_selected selection -> Some selection
       | Was_admitted _ | Was_claimed _ -> None)
    | Joined { selected; _ } -> selected
    | Admission_attempt _ | Admitted _ | Claim_attempt _ | Claimed _ | Abandoned -> None
  ;;

  let occurrence (call : Data.call) =
    match call.phase with
    | Admission_attempt { queued; _ } | Admitted queued -> queued, [ queued.attempt ]
    | Claim_attempt { queued; running; _ } -> running, [ queued.attempt; running.attempt ]
    | Claimed running -> running, [ running.attempt ]
    | Selected selection | Terminal_attempt { selection; _ } ->
      let job = selected_job selection in
      job, [ job.attempt ]
    | Cancel_attempt plan ->
      let previous =
        match plan.prior with
        | Was_admitted job | Was_claimed job -> job
        | Was_selected selection -> selected_job selection
      in
      previous, [ previous.attempt ]
    | Joined { winner; _ } -> winner, [ winner.attempt ]
    | Abandoned -> invalid_arg "abandoned constructor Model producer has no occurrence"
  ;;

  let same_creation (previous : Agent_protocol.Job.t) (current : Agent_protocol.Job.t) =
    Jsonaf.exactly_equal
      (Agent_protocol.Job.to_json
         { previous with
           status = current.status
         ; attempt = current.attempt
         ; started_at = current.started_at
         ; next_run_at = current.next_run_at
         ; completed_at = current.completed_at
         ; result = current.result
         ; delivery = current.delivery
         ; progress = current.progress
         })
      (Agent_protocol.Job.to_json current)
  ;;

  (* Only a currently installed terminal State can win. A journal ACK retained by
     an uncertain attempt is deliberately not substituted for that State. *)
  let observe_terminal (t : actor) (call : Data.call) =
    let open Result.Let_syntax in
    let%bind () = Custody.check_capture t call.capture in
    match call.phase with
    | Joined { winner; _ } -> Ok (Some winner)
    | Abandoned -> Ok None
    | Admission_attempt _
    | Admitted _
    | Claim_attempt _
    | Claimed _
    | Selected _
    | Terminal_attempt _
    | Cancel_attempt _ ->
      let%bind () = Custody.check_call t call in
      let previous, attempts = occurrence call in
      (match
         List.find t.state.jobs ~f:(fun job ->
           Agent_protocol.Id.Job.equal job.id previous.id)
       with
       | None ->
         (match call.phase with
          | Admission_attempt _ -> Ok None
          | Admitted _
          | Claim_attempt _
          | Claimed _
          | Selected _
          | Terminal_attempt _
          | Cancel_attempt _
          | Joined _
          | Abandoned -> Error (error Conflict "constructor Model Job disappeared"))
       | Some current ->
         let%bind () =
           if
             same_creation previous current
             && List.mem attempts current.attempt ~equal:Int.equal
             && Agent_protocol.Job.equal_delivery current.delivery Not_required
           then Ok ()
           else Error (error Conflict "constructor Model Job occurrence changed")
         in
         (match current.status with
          | Queued | Running | Waiting_permission _ | Waiting_completion _ -> Ok None
          | Succeeded | Failed _ | Cancelled | Interrupted _ ->
            let%bind () = Session_state.validate t.state in
            let selection = selected call in
            Option.iter (Custody.canonical_of_call call) ~f:(fun canonical ->
              Job_custody.Update.discard canonical.job_custody);
            call.phase <- Joined { selected = selection; winner = current };
            Custody.prune t;
            Ok (Some current)))
  ;;

  let check_factual (t : actor) (call : Data.call) =
    let open Result.Let_syntax in
    let%bind () = Custody.check_call t call in
    let scope = call.group.scope in
    let%bind () = validate_initialization_owner t scope in
    let%bind () =
      validate_initialization_projection
        (Initialization_scope.Acknowledged.apply scope.acknowledged scope.expected)
        t.state
    in
    let%bind () = Custody.before_other_writer t call in
    let expected, _ = occurrence call in
    let%bind current = find_job t expected.id in
    if
      Jsonaf.exactly_equal
        (Agent_protocol.Job.to_json expected)
        (Agent_protocol.Job.to_json current)
    then Ok ()
    else Error (error Conflict "constructor Model factual occurrence changed")
  ;;

  let select_result (t : actor) (call : Data.call) =
    let open Result.Let_syntax in
    let%bind () = Custody.check_capture t call.capture in
    let%bind winner = observe_terminal t call in
    match winner with
    | Some winner -> Ok (Winner winner)
    | None ->
      (match call.phase with
       | Joined { winner; _ } -> Ok (Winner winner)
       | Selected selection | Terminal_attempt { selection; _ } ->
         Ok (Selection selection)
       | Cancel_attempt plan -> Custody.unresolved plan.canonical
       | Claimed running ->
         let%bind () = Custody.check_call t call in
         let%bind outcome, sample =
           match call.capture.result with
           | None ->
             Error (error Conflict "constructor Model producer has no returned result")
           | Some (Selecting _) ->
             Error
               (error
                  Conflict
                  "constructor Model completion clock is still being selected")
           | Some (Selected_result { outcome; completion = Sample sample }) ->
             Ok (outcome, sample)
           | Some
               (Selected_result
                  { outcome = _; completion = Clock_failed (exn, backtrace) }) ->
             Exn.raise_with_original_backtrace exn backtrace
         in
         let selection =
           match outcome with
           | Some outcome -> Data.Complete_model { running; outcome; sample }
           | None -> Interrupt_running { running; sample }
         in
         call.phase <- Selected selection;
         Ok (Selection selection)
       | Admission_attempt _ | Admitted _ | Claim_attempt _ | Abandoned ->
         Error (error Conflict "constructor Model result has no actual Running claim"))
  ;;

  let select_joined (t : actor) (call : Data.call) =
    let open Result.Let_syntax in
    let%bind () = Custody.check_call t call in
    let%bind exit =
      Result.of_option
        (Constructor_model_producer.exit call.capture.producer)
        ~error:(error Conflict "constructor Model producer has not joined")
    in
    let%bind () =
      match exit.completion with
      | Selecting ->
        Error (error Conflict "constructor Model exit clock is still being selected")
      | Sample _ | Clock_failed _ -> Ok ()
    in
    let%bind () =
      match call.phase with
      | Cancel_attempt plan -> Custody.unresolved plan.canonical
      | Admission_attempt _
      | Admitted _
      | Claim_attempt _
      | Claimed _
      | Selected _
      | Terminal_attempt _
      | Joined _
      | Abandoned -> Ok ()
    in
    match call.capture.result with
    | Some _ -> select_result t call
    | None ->
      (match selected call with
       | Some selected -> Ok (Selection selected)
       | None ->
         let%bind sample =
           match exit.completion with
           | Selecting ->
             Error (error Conflict "constructor Model exit clock is still being selected")
           | Sample sample -> Ok sample
           | Clock_failed (exn, backtrace) ->
             Exn.raise_with_original_backtrace exn backtrace
         in
         let%bind selection =
           match call.phase with
           | Admitted queued -> Ok (Data.Cancel_queued { queued; sample })
           | Claimed running -> Ok (Data.Interrupt_running { running; sample })
           | Admission_attempt _
           | Claim_attempt _
           | Selected _
           | Terminal_attempt _
           | Cancel_attempt _
           | Joined _
           | Abandoned ->
             Error
               (error
                  Conflict
                  "constructor Model writer has not settled its actual phase")
         in
         call.phase <- Selected selection;
         Ok (Selection selection))
  ;;

  let prepare (t : actor) (call : Data.call) selection =
    let open Result.Let_syntax in
    let%bind () =
      match call.phase with
      | Terminal_attempt plan when Custody.no_writer plan.canonical ->
        Job_custody.Update.discard plan.canonical.job_custody;
        call.phase <- Selected plan.selection;
        Ok ()
      | Terminal_attempt plan -> Custody.unresolved plan.canonical
      | Cancel_attempt plan -> Custody.unresolved plan.canonical
      | Selected current when phys_equal current selection -> Ok ()
      | Admission_attempt _
      | Admitted _
      | Claim_attempt _
      | Claimed _
      | Selected _
      | Joined _
      | Abandoned ->
        Error (error Conflict "constructor Model has another selected result")
    in
    let%bind () = check_factual t call in
    let running = selected_job selection in
    let sample = selected_sample selection in
    let now = Recurrence_runtime.Completion.wall sample in
    let terminal, outcome =
      match selection with
      | Cancel_queued _ ->
        ( { running with status = Cancelled; completed_at = Some now }
        , Agent_protocol.Run_work.Terminal.Cancelled )
      | Complete_model { outcome = Model_succeeded result; _ } ->
        terminal_job ~now t running Succeeded (Some result), Succeeded
      | Complete_model { outcome = Model_failed message; _ } ->
        terminal_job ~now t running (Failed (job_failure message)) None, Failed
      | Interrupt_running _ ->
        ( terminal_job
            ~now
            t
            running
            (Interrupted "synchronous constructor Model producer exited")
            None
        , Interrupted )
    in
    let%bind run_deltas =
      match selection with
      | Cancel_queued _ ->
        Run_job_completion.cancel_queued
          ?startup_run:(pending_held_startup_run t)
          t.state
          ~job:running
          ~now
      | Complete_model _ | Interrupt_running _ ->
        Run_job_completion.prepare
          ?startup_run:(pending_held_startup_run t)
          t.state
          ~running
          ~terminal
          ~successor:terminal
          ~outcome
          ~now
    in
    let%bind job_custody = prepare_terminal_job_custody t [ terminal ] in
    let retained = ref false in
    Exn.protect
      ~finally:(fun () -> if not !retained then Job_custody.Update.discard job_custody)
      ~f:(fun () ->
        let%bind candidate =
          prepare_transition
            ~completion_sample:sample
            t
            ~delta:
              (Session_delta.Batch (Session_delta.Job_changed terminal :: run_deltas))
            ~payloads:[ Agent_protocol.Event.Durable.Payload.Job_state_changed terminal ]
        in
        let acknowledgement =
          Initialization_scope.Acknowledgement.prepare call.group.scope candidate.state
        in
        (* Goal_run_settlement derives this factual catalog from the exact Job/Run
           terminal candidate. Its installed ACK must precede callback retirement. *)
        let acknowledgement =
          { acknowledgement with
            incoming =
              { acknowledgement.incoming with
                goal_catalog = candidate.state.goal_catalog
              }
          }
        in
        let%bind callback_advance =
          Callback_retirement.Constructor_job_acknowledgement.prepare
            t
            ~acknowledgement
            ~candidate
        in
        let%bind completion_plan = prepare_completion_plan t candidate (Some sample) in
        let canonical = Custody.canonical t ~candidate ~job_custody ~acknowledgement in
        let plan =
          Data.{ selection; terminal; canonical; callback_advance; completion_plan }
        in
        call.phase <- Terminal_attempt plan;
        retained := true;
        Ok plan)
  ;;

  let check_before_commit (t : actor) (call : Data.call) (plan : Data.terminal) =
    let open Result.Let_syntax in
    let%bind () = check_factual t call in
    let%bind () = Custody.check_canonical t call plan.canonical in
    let%bind () =
      match call.phase with
      | Terminal_attempt actual when phys_equal actual plan -> Ok ()
      | Admission_attempt _
      | Admitted _
      | Claim_attempt _
      | Claimed _
      | Selected _
      | Terminal_attempt _
      | Cancel_attempt _
      | Joined _
      | Abandoned ->
        Error (error Conflict "constructor Model selected terminal plan changed")
    in
    Option.value_map plan.callback_advance ~default:(Ok ()) ~f:(fun advance ->
      Callback_retirement.Constructor_job_acknowledgement.check
        advance
        ~actor:t
        ~candidate:plan.canonical.candidate)
  ;;

  let commit (t : actor) (call : Data.call) (plan : Data.terminal) =
    let open Result.Let_syntax in
    Eio.Cancel.protect (fun () ->
      Custody.perform plan.canonical (fun () ->
        let%bind () = check_before_commit t call plan in
        let%bind () =
          persist_transition
            ~commit_observation:
              (Session_commit_attempt.observation plan.canonical.attempt)
            ~check_before_commit:(fun () -> check_before_commit t call plan)
            t
            plan.canonical.candidate
        in
        install_committed_transition
          ~initialization_acknowledgement:plan.canonical.acknowledgement
          ~job_custody:plan.canonical.job_custody
          t
          plan.canonical.candidate;
        Custody.installed t call plan.canonical;
        Option.iter plan.callback_advance ~f:(fun advance ->
          Callback_retirement.Constructor_job_acknowledgement.install advance ~actor:t);
        call.phase <- Joined { selected = Some plan.selection; winner = plan.terminal };
        Custody.prune t;
        Option.iter
          plan.completion_plan
          ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
        publish_committed_transition t plan.canonical.candidate;
        Ok plan.terminal))
  ;;

  let settle (t : actor) call selection =
    let open Result.Let_syntax in
    let%bind winner = observe_terminal t call in
    match winner with
    | Some winner -> Ok winner
    | None ->
      let%bind plan = prepare t call selection in
      commit t call plan
  ;;

  let capture_call (t : actor) (capture : Data.capture) =
    let open Result.Let_syntax in
    let%bind () = Custody.check_capture t capture in
    match capture.phase with
    | Owned call | Pending call -> Ok call
    | Waiting | No_admission ->
      Error (error Conflict "constructor Model producer has no admitted Job")
  ;;

  let complete (t : actor) capture =
    let open Result.Let_syntax in
    let%bind call = capture_call t capture in
    let%bind selection = select_result t call in
    match selection with
    | Winner winner -> Ok winner
    | Selection selection -> settle t call selection
  ;;

  let drain_call (t : actor) (call : Data.call) =
    let open Result.Let_syntax in
    let%bind winner = observe_terminal t call in
    match winner, call.phase with
    | Some _, _ | None, (Joined _ | Abandoned) -> Ok ()
    | None, Admission_attempt plan ->
      if Custody.no_writer plan.canonical
      then (
        Custody.abandon_admission t call plan.canonical;
        Ok ())
      else Custody.unresolved plan.canonical
    | None, Claim_attempt plan ->
      if Custody.no_writer plan.canonical
      then (
        Job_custody.Update.discard plan.canonical.job_custody;
        call.phase <- Admitted plan.queued;
        let%bind selection = select_joined t call in
        match selection with
        | Winner _ -> Ok ()
        | Selection selection -> settle t call selection |> Result.map ~f:ignore)
      else Custody.unresolved plan.canonical
    | None, Cancel_attempt plan ->
      if Custody.no_writer plan.canonical
      then (
        Job_custody.Update.discard plan.canonical.job_custody;
        Custody.restore_control call plan;
        let%bind selection = select_joined t call in
        match selection with
        | Winner _ -> Ok ()
        | Selection selection -> settle t call selection |> Result.map ~f:ignore)
      else Custody.unresolved plan.canonical
    | None, (Admitted _ | Claimed _ | Selected _ | Terminal_attempt _) ->
      let%bind selection = select_joined t call in
      (match selection with
       | Winner _ -> Ok ()
       | Selection selection -> settle t call selection |> Result.map ~f:ignore)
  ;;

  let drain (t : actor) =
    if not (Custody.on_domain t)
    then
      Error (error Conflict "constructor Model retirement belongs to another Eio domain")
    else (
      match t.constructor_models with
      | None -> Ok ()
      | Some group ->
        List.fold_result group.calls ~init:() ~f:(fun () call -> drain_call t call))
  ;;
end

let handle_constructor_model_request
  : type a. t -> a Constructor_model_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  match request with
  | Admit (capture, job) ->
    let%bind.Result () = Constructor_model_custody.check_capture t capture in
    admit_model_job ~producer:capture t (Inference_initialization capture.scope) job
  | Claim capture ->
    let open Result.Let_syntax in
    let%bind call = Constructor_model.capture_call t capture in
    (match call.phase with
     | Admitted job ->
       claim_initialization_model_job
         ~constructor_call:call
         t
         capture.scope
         job.id
         job.generation
     | Admission_attempt _
     | Claim_attempt _
     | Claimed _
     | Selected _
     | Terminal_attempt _
     | Cancel_attempt _
     | Joined _
     | Abandoned ->
       Error (error Conflict "constructor Model producer has no unclaimed queued ACK"))
  | Complete capture -> Constructor_model.complete t capture
  | Interrupt capture -> Constructor_model.complete t capture
  | Drain -> Constructor_model.drain t
;;

let finish_background_scopes t job_id generation attempt =
  List.filter t.job_scopes ~f:(fun scope ->
    (not scope.active)
    && Agent_protocol.Id.Job.equal scope.job.id job_id
    && Int.equal scope.job.generation generation
    && Int.equal scope.job.attempt attempt)
  |> List.fold_result ~init:() ~f:(fun () scope ->
    match finish_job_scope t scope with
    | Ok () -> Ok ()
    | Error failure ->
      (match List.mem t.job_scopes scope ~equal:phys_equal with
       | true -> Error failure
       | false -> Ok ()))
;;

let defer_background_job t job_id generation attempt dependency =
  let open Result.Let_syntax in
  let%bind () = finish_background_scopes t job_id generation attempt in
  let%bind job = running_job_for_completion t job_id generation attempt in
  let next = { job with status = Waiting_completion dependency; result = None } in
  let%bind () = validate_job_dependency t next in
  let%bind job_custody =
    Job_custody.prepare_defer t.job_agent_custody ~previous:job ~waiting:next
  in
  let%map _ = update_job ~job_custody t next in
  next
;;

type background_control =
  | Cancelled_control
  | Interrupted_control

let complete_background_job
      ?(waiting = false)
      ?completed_at
      ?control
      t
      job_id
      generation
      attempt
      completion
  =
  let open Result.Let_syntax in
  let%bind job = find_job t job_id in
  let%bind () = validate_job_generation t job generation in
  let%bind () = validate_job_attempt job attempt in
  let%bind () =
    match job.kind with
    | Async_tool -> Ok ()
    | _ -> Error (error Invalid_request "generic completion requires an async tool job")
  in
  let%bind () = Agent_protocol.Completion.validate completion in
  let original_completion = completion in
  let%bind completion =
    match control with
    | None -> Ok completion
    | Some (Cancelled_control | Interrupted_control) ->
      Run_job_capacity.normalize_host_control completion |> Result.map ~f:fst
  in
  let awaited = Run_job_completion.awaits t.state job in
  let%bind capacity =
    if awaited && (Option.is_none control || Option.is_some t.services.job_results)
    then
      Result.map
        (Run_job_capacity.capture job ~publisher:t.services.job_results)
        ~f:Option.some
    else Ok None
  in
  let%bind completion, delivery_limited =
    match capacity with
    | None -> Ok (completion, false)
    | Some capacity -> Run_job_capacity.normalize_completion capacity completion
  in
  let completion, storage_limited =
    match t.services.job_results with
    | Some publisher
      when Result.is_error
             (Agent_store.Job_result_store.Publisher.check_completion
                publisher
                completion) ->
      ( (match completion with
         | Cancelled _ when awaited ->
           Agent_protocol.Completion.Cancelled
             "The job was cancelled; its diagnostic exceeds the host storage limit."
         | Cancelled _ | Expired -> completion
         | Succeeded _ | Failed _ ->
           Agent_protocol.Completion.Failed
             { code = "background.result_limit"
             ; message = "The completed result exceeds the host storage limit."
             ; retryable = false
             ; details = `Null
             })
      , true )
    | _ -> completion, delivery_limited
  in
  let%bind () = finish_background_scopes t job_id generation attempt in
  let%bind job =
    match job.status, waiting, control with
    | Waiting_permission _, _, Some (Cancelled_control | Interrupted_control)
    | Waiting_completion _, true, _ -> Ok job
    | ( ( Queued
        | Running
        | Waiting_permission _
        | Waiting_completion _
        | Succeeded
        | Failed _
        | Cancelled
        | Interrupted _ )
      , _
      , _ ) -> running_job_for_completion t job_id generation attempt
  in
  let encoded = Agent_protocol.Completion.to_json completion in
  let%bind cancelled, subscriptions =
    match completion with
    | Cancelled _ | Expired -> cancelled_work_dependencies t job
    | Succeeded _ | Failed _ -> Ok ([], [])
  in
  let now, completion_sample = completion_clock_pair t in
  let terminal status =
    let terminal = terminal_job ~now t job status (Some encoded) in
    match completed_at with
    | None -> terminal
    | Some at -> { terminal with completed_at = Some at }
  in
  let running = job in
  let%bind interruption =
    match control, completion with
    | Some Interrupted_control, Failed failure -> Ok (Some failure.message)
    | Some Cancelled_control, Cancelled _
    | None, (Succeeded _ | Failed _ | Cancelled _ | Expired) -> Ok None
    | Some Interrupted_control, (Succeeded _ | Cancelled _ | Expired)
    | Some Cancelled_control, (Succeeded _ | Failed _ | Expired) ->
      Error (error Invalid_request "host control disagrees with its actual outcome")
  in
  let job =
    match interruption, completion with
    | Some reason, (Succeeded _ | Failed _ | Cancelled _ | Expired) ->
      terminal (Interrupted reason)
    | None, Agent_protocol.Completion.Succeeded _ -> terminal Succeeded
    | None, Cancelled _ -> terminal Cancelled
    | None, Expired ->
      terminal (Failed (error Resource_limit "background job deadline elapsed"))
    | None, Failed failure ->
      let retry =
        match job.status with
        | Waiting_completion _ -> None
        | _ -> retry_limits job.retry_policy
      in
      let failed () =
        terminal
          (Failed
             (Agent_protocol.Error.create
                Internal_error
                ~message:failure.message
                ~retryable:failure.retryable
                ~data:encoded
                ()))
      in
      (match failure.retryable, retry with
       | true, Some (maximum, backoff_ms) when job.attempt < maximum ->
         (match retry_job job ~now ~message:failure.message ~backoff_ms with
          | Ok queued -> { queued with result = Some encoded }
          | Error _ -> failed ())
       | _ -> failed ())
  in
  let persist stored =
    let status =
      match job.status, stored with
      | Failed failure, Agent_protocol.Stored_completion.Artifact _ ->
        Agent_protocol.Job.Failed { failure with data = `Null }
      | status, _ -> status
    in
    let job =
      { job with
        status
      ; result =
          Some
            (match status with
             | Queued -> encoded
             | Running
             | Waiting_permission _
             | Waiting_completion _
             | Succeeded
             | Failed _
             | Cancelled
             | Interrupted _ -> Agent_protocol.Stored_completion.to_json stored)
      }
    in
    let terminal_status =
      match interruption, completion with
      | Some reason, (Succeeded _ | Failed _ | Cancelled _ | Expired) ->
        Agent_protocol.Job.Interrupted reason
      | None, Succeeded _ -> Succeeded
      | None, Failed failure ->
        Failed
          (Agent_protocol.Error.create
             Internal_error
             ~message:failure.message
             ~retryable:failure.retryable
             ~data:`Null
             ())
      | None, Cancelled _ -> Cancelled
      | None, Expired -> Failed (error Resource_limit "background job deadline elapsed")
    in
    let terminal =
      terminal terminal_status
      |> fun (terminal : Agent_protocol.Job.t) ->
      { terminal with result = Some (Agent_protocol.Stored_completion.to_json stored) }
    in
    let outcome =
      match control with
      | Some Interrupted_control -> Agent_protocol.Run_work.Terminal.Interrupted
      | None | Some Cancelled_control ->
        (match original_completion with
         | Succeeded _ ->
           if storage_limited then Agent_protocol.Run_work.Terminal.Limited else Succeeded
         | Failed _ -> Failed
         | Cancelled _ -> Cancelled
         | Expired -> Limited)
    in
    let%bind run_deltas =
      let work_delta =
        Session_delta.Batch
          (List.map subscriptions ~f:(fun value ->
             Session_delta.Subscription_changed value)
           @ List.map (cancelled_subscription_timers t subscriptions) ~f:(fun value ->
             Session_delta.Schedule_changed value))
      in
      Run_job_completion.prepare
        ~work_delta
        ~cancelled_dependencies:cancelled
        t.state
        ~running
        ~terminal
        ~successor:job
        ~outcome
        ~now
    in
    let%bind job_custody =
      match job.status with
      | Queued ->
        Result.map
          (Job_custody.prepare_retry t.job_agent_custody ~previous:running ~queued:job)
          ~f:Option.some
      | Succeeded | Failed _ | Cancelled | Interrupted _ ->
        Result.map (prepare_terminal_job_custody t (job :: cancelled)) ~f:Option.some
      | Running | Waiting_permission _ | Waiting_completion _ ->
        Error (error Invalid_state "completed background Job retained an active state")
    in
    let%map _ =
      update_jobs
        ?job_custody
        ~completion_sample
        ~subscriptions
        ~run_deltas
        t
        (job :: cancelled)
    in
    job
  in
  match job.status, t.services.job_results, storage_limited, awaited with
  | Queued, _, _, false | _, None, _, _ | _, _, true, _ ->
    persist (Agent_protocol.Stored_completion.Inline completion)
  | _, Some publisher, false, _ ->
    Agent_store.Job_result_store.Publisher.publish
      publisher
      ~storage:
        (match capacity with
         | Some capacity -> Run_job_capacity.storage capacity
         | None -> Automatic)
      ~jobs:t.state.jobs
      ~job:running
      ~now
      completion
      ~persist
;;

let recover_background_results t max_count max_total_bytes =
  let open Result.Let_syntax in
  let%bind () =
    match
      t.job_scopes, t.invocation_executions, t.moderator_borrow, t.queued_event_borrow
    with
    | [], [], None, None -> Ok ()
    | _ -> Error (error Conflict "result recovery requires an idle execution host")
  in
  match t.services.job_results with
  | None -> Ok ()
  | Some publisher ->
    let%bind restored =
      Agent_store.Job_result_store.Publisher.restore
        publisher
        ~jobs:t.state.jobs
        ~generation:t.state.identity.generation
        ~max_count
        ~max_total_bytes
    in
    List.fold_result restored ~init:() ~f:(fun () (previous, completion, completed_at) ->
      let%bind job = find_job t previous.id in
      match job.status with
      | Running | Waiting_completion _ ->
        let%bind () = validate_job_dependency t job in
        complete_background_job
          ~waiting:true
          ~completed_at
          t
          job.id
          job.generation
          job.attempt
          completion
        |> Result.map ~f:ignore
      | _ -> Ok ())
;;

let refresh_background_job t job_id generation attempt =
  let open Result.Let_syntax in
  let%bind job = find_job t job_id in
  let%bind () = validate_job_generation t job generation in
  let%bind () = validate_job_attempt job attempt in
  match job.status with
  | Waiting_completion dependency ->
    let%bind () = validate_job_dependency t job in
    let selected =
      Option.bind t.services.job_results ~f:(fun publisher ->
        Agent_store.Job_result_store.Publisher.pending_completion publisher ~job)
    in
    (match selected with
     | Some completion ->
       complete_background_job ~waiting:true t job_id generation attempt completion
     | None ->
       let%bind completion, completed_at =
         match dependency.work with
         | Subscription id ->
           let%map target = retained_subscription t id in
           target.result, target.completed_at
         | Job id ->
           let%bind target = find_job t id in
           let load_artifact =
             Option.map t.services.job_results ~f:(fun publisher ->
               Agent_store.Job_result_store.Publisher.load publisher)
           in
           let%map completion =
             match Agent_protocol.Job.terminal_completion ?load_artifact target with
             | Ok completion -> Ok completion
             | Error failure when not failure.retryable ->
               Ok
                 (Some
                    (Agent_protocol.Completion.Failed
                       { code = "background.artifact_unavailable"
                       ; message =
                           "The saved background result is unavailable or failed \
                            verification."
                       ; retryable = false
                       ; details = `Null
                       }))
             | Error _
               when Agent_protocol.Timestamp.compare
                      (t.services.now ())
                      dependency.deadline
                    >= 0 -> Ok (Some Agent_protocol.Completion.Expired)
             | Error _ as failure -> failure
           in
           completion, target.completed_at
       in
       (match completion with
        | Some completion ->
          let completion =
            match completed_at with
            | Some at when Agent_protocol.Timestamp.compare at dependency.deadline <= 0 ->
              completion
            | _ -> Agent_protocol.Completion.Expired
          in
          let%bind completion = Job_dependency.completion dependency completion in
          complete_background_job ~waiting:true t job_id generation attempt completion
        | None
          when Agent_protocol.Timestamp.compare (t.services.now ()) dependency.deadline
               >= 0 ->
          complete_background_job ~waiting:true t job_id generation attempt Expired
        | None -> Ok job))
  | _ -> Ok job
;;

let check_expected_moderator_checkpoint t = function
  | None -> Ok ()
  | Some expected ->
    let open Result.Let_syntax in
    let%bind () = Moderator_checkpoint.validate_encoded_capacity t.state.moderator in
    let%bind installed = Moderator_checkpoint.decode t.state.moderator in
    if
      Option.exists installed ~f:(fun installed ->
        Sexp.equal
          (Session.Moderator_state.Identity_snapshot.sexp_of_t installed)
          (Session.Moderator_state.Identity_snapshot.sexp_of_t expected))
    then Ok ()
    else Error (error Conflict "moderator checkpoint changed before external delivery")
;;

let external_delivery_source_deltas plan =
  Option.to_list
    (Option.map (External_delivery_checkpoint.initial_source_index plan) ~f:(fun index ->
       Session_delta.Run_state_changed index))
;;

(* A source-free Job never acquires whichever Manager was installed later.
   Only the exact previously captured physical Manager/full-source loan can
   transfer into a queue occurrence. Missing custody remains missing. *)
let validate_job_delivery_policy_source ~row ~job ~source ~entry =
  match row with
  | None -> Ok Policy_standalone_source.Classification.Unknown
  | Some row ->
    Policy_queue_source.job ~job ~source ~entry (Job_custody.Row.policy_source row)
;;

let prepare_external_job_queue_update t plan job =
  let open Result.Let_syntax in
  let%bind row = Job_custody.find t.job_agent_custody ~job in
  let%bind owner =
    match row with
    | None -> Ok None
    | Some row ->
      (match Job_custody.Row.binding row with
       | No_captured_moderator -> Ok None
       | Captured { source; manager = None }
         when Agent_protocol.Run_source.equal
                source
                (External_delivery_checkpoint.source plan) ->
         (* Persist the completed fact without acquiring a physical queue loan.
            A genuine source-only creator never owned a Manager to transfer. *)
         Ok None
       | Captured { source; manager = Some manager }
         when Agent_protocol.Run_source.equal
                source
                (External_delivery_checkpoint.source plan)
              && Option.exists t.moderator_manager ~f:(phys_equal manager) ->
         Ok (Some manager)
       | Captured _ ->
         Error (error Conflict "Job delivery lost its original Manager or source"))
  in
  match owner with
  | None -> Ok None
  | Some manager ->
    let source = External_delivery_checkpoint.source plan in
    let%bind policy_source =
      validate_job_delivery_policy_source
        ~row
        ~job
        ~source
        ~entry:(External_delivery_checkpoint.entry plan)
    in
    let%bind continuation =
      Job_custody.transfer_delivery t.job_agent_custody ~manager ~source ~job
    in
    let staged =
      Option.value_map
        continuation
        ~default:Legacy_queue_custody.empty
        ~f:(fun continuation ->
          Legacy_queue_custody.stage_delivery
            ~manager
            ~source
            ~entry:(External_delivery_checkpoint.entry plan)
            ~continuation
            ~policy_source)
    in
    Legacy_queue_custody.Update.prepare
      t.legacy_queue_custody
      ~manager
      ~metadata:(External_delivery_checkpoint.metadata plan)
      ~staged
    |> Result.map ~f:Option.some
;;

let prepare_creator_delivery_queue t plan ~manager ~continuation =
  let source = External_delivery_checkpoint.source plan in
  let staged =
    Option.value_map
      continuation
      ~default:Legacy_queue_custody.empty
      ~f:(fun continuation ->
        Legacy_queue_custody.stage_delivery
          ~manager
          ~source
          ~entry:(External_delivery_checkpoint.entry plan)
          ~continuation
          ~policy_source:Unknown)
  in
  Legacy_queue_custody.Update.prepare
    t.legacy_queue_custody
    ~manager
    ~metadata:(External_delivery_checkpoint.metadata plan)
    ~staged
  |> Result.map ~f:Option.some
;;

let prepare_ingress_delivery_queue t plan registration =
  let open Result.Let_syntax in
  match t.moderator_manager with
  | None -> Ok None
  | Some manager ->
    let%bind continuation =
      Ingress_creator_custody.transfer_delivery
        t.ingress_creator_custody
        ~manager
        ~source:(External_delivery_checkpoint.source plan)
        ~registration
    in
    prepare_creator_delivery_queue t plan ~manager ~continuation
;;

let prepare_schedule_delivery_queue t plan schedule =
  let open Result.Let_syntax in
  match t.moderator_manager with
  | None -> Ok None
  | Some manager ->
    let%bind continuation =
      Legacy_schedule_custody.transfer_delivery
        t.legacy_schedule_custody
        ~manager
        ~source:(External_delivery_checkpoint.source plan)
        ~schedule
    in
    prepare_creator_delivery_queue t plan ~manager ~continuation
;;

let prepare_run_job_enqueue t ~frame =
  let open Result.Let_syntax in
  match t.state.run_state with
  | None -> Ok []
  | Some index ->
    (match
       List.find (Run_state.job_deliveries index) ~f:(fun delivery ->
         Chat_response.Background_delivery.equal (Run_job_delivery.frame delivery) frame)
     with
     | None -> Ok []
     | Some delivery ->
       let%bind () = check_run_binding t (Run_job_delivery.run_id delivery) in
       let%bind delivery = Run_job_delivery.enqueue delivery ~at:(t.services.now ()) in
       let%map index = Run_state.replace_job_delivery index delivery in
       [ Session_delta.Run_state_changed index ])
;;

let enqueue_run_job_delivery ?goal_runtime_scope t expected before after =
  let open Result.Let_syntax in
  let%bind () = check_expected_moderator_checkpoint t (Some before) in
  let%bind () =
    if moderator_is_borrowed t
    then Error (error Conflict "moderator callback owns the checkpoint")
    else Ok ()
  in
  let%bind index =
    Result.of_option t.state.run_state ~error:(error Conflict "run index is absent")
  in
  let%bind retained =
    Result.of_option
      (Run_state.find_job_delivery index (Run_job_delivery.key expected))
      ~error:(error Conflict "run delivery is absent")
  in
  let%bind () =
    if Run_job_delivery.equal retained expected
    then Ok ()
    else Error (error Conflict "run delivery changed before enqueue")
  in
  let%bind () =
    match Run_job_delivery.disposition retained with
    | Pending -> Ok ()
    | Enqueued _ | Claimed _ | Retired _ ->
      Error (error Already_resolved "run delivery is no longer pending")
  in
  let frame = Run_job_delivery.frame retained in
  let observer : Agent_protocol.Invocation.observer =
    { script_id = before.script_id; source_sha256 = before.script_source_hash }
  in
  let%bind () =
    if Agent_protocol.Invocation.equal_observer observer frame.source
    then Ok ()
    else Error (error Conflict "run delivery source differs from moderator")
  in
  let%bind () =
    match check_run_binding t (Run_job_delivery.run_id retained) with
    | Ok () -> Ok ()
    | Error denied ->
      let%bind index =
        Run_retirement.interrupt_run
          index
          ~run_id:(Run_job_delivery.run_id retained)
          ~session_revision:(Int64.succ t.state.counters.revision)
          ~now:(t.services.now ())
      in
      let%bind _ =
        transition t ~delta:(Session_delta.Run_state_changed index) ~payloads:[]
      in
      Error denied
  in
  let%bind plan =
    External_delivery_checkpoint.prepare
      t.state
      ~producer:(Run_job_completion retained)
      ~before
      ~snapshot:(Encoded after)
  in
  let%bind deltas = prepare_run_job_enqueue t ~frame in
  let job_deltas, payloads, delivered_job =
    match
      List.find t.state.jobs ~f:(fun job ->
        Agent_protocol.Id.Job.equal job.id frame.job_id)
    with
    | None -> [], [], None
    | Some job ->
      (match job.delivery, Background_job_event.frame ~state:t.state ~observer job with
       | Pending, Ok current when Chat_response.Background_delivery.equal current frame ->
         let job = { job with delivery = Delivered (t.services.now ()) } in
         ( [ Session_delta.Job_changed job ]
         , [ Agent_protocol.Event.Durable.Payload.Job_state_changed job ]
         , Some { job with delivery = Pending } )
       | (Not_required | Pending | Delivered _ | Discarded _), (Ok _ | Error _) ->
         [], [], None)
  in
  let%bind update =
    match delivered_job with
    | None -> Ok None
    | Some job -> prepare_external_job_queue_update t plan job
  in
  Exn.protect
    ~finally:(fun () -> Option.iter update ~f:Legacy_queue_custody.Update.discard)
    ~f:(fun () ->
      let%map _ =
        transition
          ?goal_runtime_scope
          ?queue_custody_installation:
            (Option.map update ~f:(fun update ->
               Queue_custody_installation.Delivery_update update))
          t
          ~delta:
            (Session_delta.Batch
               (external_delivery_source_deltas plan
                @ deltas
                @ job_deltas
                @ [ Moderator_changed
                      (Some (External_delivery_checkpoint.checkpoint plan))
                  ]))
          ~payloads
      in
      ())
;;

let deliver_job_without_legacy
      ?goal_runtime_scope
      ?model_completion_format
      t
      job_id
      generation
      expected
      expected_job
      moderator_snapshot
  =
  let open Result.Let_syntax in
  let%bind () = check_expected_moderator_checkpoint t expected in
  let%bind () =
    match moderator_is_borrowed t with
    | true -> Error (error Conflict "moderator callback owns the checkpoint")
    | false -> Ok ()
  in
  let%bind job = find_job t job_id in
  let%bind () =
    match expected_job with
    | None -> Ok ()
    | Some expected_job ->
      if
        Jsonaf.exactly_equal
          (Agent_protocol.Job.to_json expected_job)
          (Agent_protocol.Job.to_json job)
      then Ok ()
      else Error (error Conflict "job changed before completion delivery")
  in
  let%bind () = validate_job_generation t job generation in
  match job.status, job.delivery with
  | (Succeeded | Failed _ | Cancelled | Interrupted _), Agent_protocol.Job.Pending ->
    let%bind plan =
      match expected, moderator_snapshot with
      | Some before, Some after ->
        let model_completion_format =
          Option.value_or_thunk model_completion_format ~default:(fun () ->
            Option.value_map
              t.moderator_manager
              ~default:Model_job_event.Format.Legacy
              ~f:Model_job_event.Format.of_manager)
        in
        External_delivery_checkpoint.prepare
          ~model_completion_format
          t.state
          ~producer:(Job_completion job)
          ~before
          ~snapshot:(Encoded after)
        |> Result.map ~f:Option.some
      | (Some _ | None), (Some _ | None) ->
        (match job.kind, job.launch with
         | Async_tool, Some _ ->
           Error
             (error Conflict "background delivery requires an exact moderator checkpoint")
         | ( ( Model_call
             | Nested_agent
             | Scheduled_event
             | Async_tool
             | Shell_process
             | Compaction )
           , _ ) -> Ok None)
    in
    let%bind run_deltas =
      match job.kind, job.launch, expected with
      | Async_tool, Some _, Some before ->
        let observer : Agent_protocol.Invocation.observer =
          { script_id = before.script_id; source_sha256 = before.script_source_hash }
        in
        let%bind frame = Background_job_event.frame ~state:t.state ~observer job in
        prepare_run_job_enqueue t ~frame
      | ( ( Model_call
          | Nested_agent
          | Scheduled_event
          | Async_tool
          | Shell_process
          | Compaction )
        , _
        , _ ) -> Ok []
    in
    let%bind update =
      match plan with
      | None -> Ok None
      | Some plan -> prepare_external_job_queue_update t plan job
    in
    let source_deltas =
      Option.value_map plan ~default:[] ~f:external_delivery_source_deltas
    in
    let moderator_snapshot =
      Option.value_map plan ~default:moderator_snapshot ~f:(fun plan ->
        Some (External_delivery_checkpoint.checkpoint plan))
    in
    let job = { job with delivery = Delivered (t.services.now ()) } in
    Exn.protect
      ~finally:(fun () -> Option.iter update ~f:Legacy_queue_custody.Update.discard)
      ~f:(fun () ->
        let%map _ =
          transition
            ?goal_runtime_scope
            ?queue_custody_installation:
              (Option.map update ~f:(fun update ->
                 Queue_custody_installation.Delivery_update update))
            t
            ~delta:
              (Session_delta.Batch
                 (source_deltas
                  @ run_deltas
                  @ [ Job_changed job; Moderator_changed moderator_snapshot ]))
            ~payloads:[ Agent_protocol.Event.Durable.Payload.Job_state_changed job ]
        in
        job)
  | (Queued | Running | Waiting_permission _ | Waiting_completion _), _ ->
    Error (error Conflict "job is not terminal")
  | _, (Not_required | Delivered _ | Discarded _) ->
    Error (error Already_resolved "job delivery is resolved")
;;

let complete_legacy_job t manager job expected expected_job moderator_snapshot =
  let open Result.Let_syntax in
  let current_source () =
    let%bind () = require_runtime_admission t in
    let%bind () =
      if Option.exists t.moderator_manager ~f:(phys_equal manager)
      then Ok ()
      else Error (error Conflict "legacy Job Manager changed before delivery")
    in
    Moderator_source_installation.capture t.state
  in
  let%bind () =
    if Option.is_some expected_job
    then Ok ()
    else Error (error Conflict "legacy Job delivery requires its exact saved record")
  in
  let%bind before =
    Result.of_option
      expected
      ~error:(error Conflict "legacy Job delivery requires its previous checkpoint")
  in
  let%bind _, source = current_source () in
  let%bind named_run =
    match job.Agent_protocol.Job.inference_origin with
    | Some (Run id) ->
      (match Option.bind t.state.run_state ~f:(fun index -> Run_state.find index id) with
       | Some run
         when Agent_protocol.Id.Session.equal
                (Agent_protocol.Session_ref.session_id run.session)
                job.session_id
              && Agent_protocol.Run_source.equal run.source source -> Ok true
       | Some _ | None ->
         Error (error Conflict "legacy Job original Run source is unavailable or changed"))
    | Some Unbound | None -> Ok false
  in
  let%bind row = Job_custody.find t.job_agent_custody ~job in
  let%bind capture =
    if Option.is_some row || named_run
    then
      Moderator_queue.Capture.create
        ~producer:
          (Job_completion
             { id = job.id; generation = job.generation; attempt = job.attempt })
        ~origin:job.inference_origin
    else Ok Moderator_queue.Capture.unavailable
  in
  let%bind plan =
    Legacy_job_delivery.prepare t.state ~job ~before ~snapshot:moderator_snapshot ~capture
  in
  let%bind policy_source =
    validate_job_delivery_policy_source
      ~row
      ~job
      ~source
      ~entry:(Legacy_job_delivery.entry plan)
  in
  let%bind continuation =
    Job_custody.transfer_delivery t.job_agent_custody ~manager ~source ~job
  in
  let staged =
    match continuation with
    | None -> Legacy_queue_custody.empty
    | Some continuation ->
      Legacy_queue_custody.stage_delivery
        ~manager
        ~source
        ~entry:(Legacy_job_delivery.entry plan)
        ~continuation
        ~policy_source
  in
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () -> if not !acknowledged then Legacy_queue_custody.retire staged)
    ~f:(fun () ->
      let%bind inventory =
        Legacy_queue_custody.candidate
          t.legacy_queue_custody
          ~manager
          ~metadata:(Legacy_job_delivery.metadata plan)
          ~staged
      in
      let delivered = { job with delivery = Delivered (t.services.now ()) } in
      let%bind prepared =
        prepare_transition
          t
          ~delta:
            (Session_delta.Batch
               [ Run_state_changed (Legacy_job_delivery.index plan)
               ; Job_changed delivered
               ; Moderator_changed (Some (Legacy_job_delivery.checkpoint plan))
               ])
          ~payloads:[ Agent_protocol.Event.Durable.Payload.Job_state_changed delivered ]
      in
      let%bind _, final_source = current_source () in
      let%bind () =
        if Agent_protocol.Run_source.equal source final_source
        then Ok ()
        else Error (error Conflict "legacy Job source changed before delivery ACK")
      in
      (* Completed facts remain truthful after original authority expiry. The
         typed expired continuation cannot authorize the later queued callback. *)
      Eio.Cancel.protect (fun () ->
        let%bind () = persist_transition t prepared in
        install_committed_transition t prepared;
        t.legacy_queue_custody
        <- Legacy_queue_custody.install t.legacy_queue_custody ~incoming:inventory;
        acknowledged := true;
        publish_committed_transition t prepared;
        Ok delivered))
;;

let deliver_job t job_id generation expected expected_job moderator_snapshot manager =
  let open Result.Let_syntax in
  let%bind () =
    match manager with
    | Some manager when not (Option.exists t.moderator_manager ~f:(phys_equal manager)) ->
      Error (error Conflict "Job delivery requires its actual installed Manager")
    | Some _ | None -> Ok ()
  in
  match manager with
  | Some manager
    when Option.is_none (Chat_response.Moderator_manager.invocation_observer manager) ->
    let%bind () =
      if moderator_is_borrowed t
      then Error (error Conflict "moderator callback owns the checkpoint")
      else Ok ()
    in
    let%bind job = find_job t job_id in
    let%bind () = validate_job_generation t job generation in
    let%bind () =
      match expected_job with
      | Some expected_job
        when Jsonaf.exactly_equal
               (Agent_protocol.Job.to_json expected_job)
               (Agent_protocol.Job.to_json job) -> Ok ()
      | Some _ | None ->
        Error (error Conflict "Job changed before legacy completion delivery")
    in
    complete_legacy_job t manager job expected expected_job moderator_snapshot
  | Some _ | None ->
    let%bind () =
      match t.moderator_manager with
      | Some installed
        when Option.is_none
               (Chat_response.Moderator_manager.invocation_observer installed) ->
        let%bind job = find_job t job_id in
        let%bind row = Job_custody.find t.job_agent_custody ~job in
        if
          Option.is_some row
          || Option.is_some job.inference_origin
          || Option.exists job.launch ~f:(fun launch ->
            Option.is_some launch.moderator_source)
        then
          Error
            (error Conflict "captured legacy Job delivery requires its actual Manager")
        else Ok ()
      | None ->
        let%bind job = find_job t job_id in
        let%bind row = Job_custody.find t.job_agent_custody ~job in
        if Option.is_some row || Option.is_some job.inference_origin
        then Error (error Conflict "captured Job delivery requires its actual Manager")
        else Ok ()
      | Some _ -> Ok ()
    in
    deliver_job_without_legacy
      t
      job_id
      generation
      expected
      expected_job
      moderator_snapshot
;;

let cancel_job_internal t job_id =
  let open Result.Let_syntax in
  let%bind job = find_job t job_id in
  let%bind job =
    match job.status with
    | Waiting_completion _ -> refresh_background_job t job_id job.generation job.attempt
    | _ -> Ok job
  in
  let owned = Run_job_completion.owns t.state job in
  match job.status, job.delivery with
  | _, Agent_protocol.Job.Discarded _ -> Ok job
  | Interrupted _, _ when Agent_protocol.Job.equal_kind job.kind Model_call ->
    (* A factual interrupted Model attempt is already an immutable winner. *)
    Ok job
  | (Running | Waiting_permission _ | Waiting_completion _), _
    when owned && Agent_protocol.Job.equal_kind job.kind Async_tool ->
    let waiting =
      match job.status with
      | Waiting_completion _ -> true
      | Queued
      | Running
      | Waiting_permission _
      | Succeeded
      | Failed _
      | Cancelled
      | Interrupted _ -> false
    in
    complete_background_job
      ~waiting
      ~control:Cancelled_control
      t
      job.id
      job.generation
      job.attempt
      (Cancelled "job cancelled")
  | (Queued | Running | Waiting_permission _ | Waiting_completion _ | Interrupted _), _ ->
    let%bind cancelled, subscriptions = cancelled_work_dependencies t job in
    let running = job in
    let%bind constructor_control = Constructor_job_control.capture t ~previous:running in
    let model_owned = owned && Agent_protocol.Job.equal_kind running.kind Model_call in
    let now, completion_sample =
      if model_owned
      then (
        let now, sample = completion_clock_pair t in
        now, Some sample)
      else t.services.now (), None
    in
    let job =
      { job with
        status = Cancelled
      ; result = background_terminal_result job (Cancelled "job cancelled")
      ; completed_at = Some now
      ; delivery =
          (match job.delivery with
           | Not_required -> Not_required
           | _ -> Pending)
      }
    in
    let%bind run_deltas =
      match running.status with
      | Queued
        when owned
             && (Agent_protocol.Job.equal_kind running.kind Async_tool || model_owned) ->
        Run_job_completion.cancel_queued
          ?startup_run:(pending_held_startup_run t)
          t.state
          ~job:running
          ~now
      | (Running | Waiting_permission _ | Waiting_completion _) when model_owned ->
        Run_job_completion.prepare
          ?startup_run:(pending_held_startup_run t)
          t.state
          ~running
          ~terminal:job
          ~successor:job
          ~outcome:Cancelled
          ~now
      | Queued
      | Running
      | Waiting_permission _
      | Waiting_completion _
      | Succeeded
      | Failed _
      | Cancelled
      | Interrupted _ -> Ok []
    in
    let%bind job_custody = prepare_terminal_job_custody t (job :: cancelled) in
    let%map _ =
      update_jobs
        ~constructor_cancel:(running, job, constructor_control)
        ?completion_sample
        ~job_custody
        ~subscriptions
        ~run_deltas
        t
        (job :: cancelled)
    in
    job
  | (Succeeded | Failed _ | Cancelled), _ -> Ok job
;;

let interrupt_job
      ?initialization_scope
      ?run_preparation
      t
      job_id
      generation
      attempt
      reason
  =
  let open Result.Let_syntax in
  let%bind job = find_job t job_id in
  let%bind () = validate_job_generation t job generation in
  let%bind () = validate_job_attempt job attempt in
  match job.status with
  | Agent_protocol.Job.Running
    when Agent_protocol.Job.equal_kind job.kind Async_tool
         && Run_job_completion.owns t.state job ->
    complete_background_job
      ~control:Interrupted_control
      t
      job.id
      job.generation
      job.attempt
      (Failed
         { code = "background.interrupted"
         ; message = reason
         ; retryable = false
         ; details = `Null
         })
  | Agent_protocol.Job.Running ->
    let running = job in
    let model_owned =
      Agent_protocol.Job.equal_kind running.kind Model_call
      && Run_job_completion.owns t.state running
    in
    let now, completion_sample =
      if model_owned
      then (
        let now, sample = completion_clock_pair t in
        now, Some sample)
      else t.services.now (), None
    in
    let job =
      { job with
        status = Interrupted reason
      ; result =
          background_terminal_result
            job
            (Failed
               { code = "background.interrupted"
               ; message = reason
               ; retryable = false
               ; details = `Null
               })
      ; completed_at = Some now
      ; delivery =
          (match job.delivery with
           | Not_required -> Not_required
           | _ -> Pending)
      }
    in
    let%bind run_deltas =
      if model_owned
      then
        Run_job_completion.prepare
          ?startup_run:(pending_held_startup_run t)
          t.state
          ~running
          ~terminal:job
          ~successor:job
          ~outcome:Interrupted
          ~now
      else Ok []
    in
    let%bind job_custody = prepare_terminal_job_custody t [ job ] in
    let%map _ =
      update_jobs
        ?initialization_scope
        ?run_preparation
        ?completion_sample
        ~job_custody
        ~run_deltas
        t
        [ job ]
    in
    job
  | Queued
  | Waiting_permission _
  | Waiting_completion _
  | Succeeded
  | Failed _
  | Cancelled
  | Interrupted _ -> Ok job
;;

let change_schedule t attachment_id event schedule =
  let payload =
    match event with
    | `Created -> Agent_protocol.Event.Durable.Payload.Schedule_created schedule
    | `Cancelled -> Schedule_cancelled schedule
  in
  with_writer t attachment_id (fun () ->
    transition t ~delta:(Session_delta.Schedule_changed schedule) ~payloads:[ payload ])
;;

let add_schedule ?initialization_scope ?run_preparation t schedule =
  if
    Agent_protocol.Id.Session.compare
      schedule.Agent_protocol.Schedule.session_id
      t.state.identity.session_id
    <> 0
  then Error (error Invalid_request "schedule belongs to another session")
  else if schedule.generation <> t.state.identity.generation
  then Error (error Conflict "schedule belongs to a stale session generation")
  else if
    List.exists t.state.schedules ~f:(fun existing ->
      Agent_protocol.Id.Schedule.compare existing.id schedule.id = 0)
  then Error (error Conflict "schedule ID is already present")
  else
    let open Result.Let_syntax in
    let%map _ =
      match initialization_scope with
      | None ->
        transition
          ?run_preparation
          t
          ~delta:(Session_delta.Schedule_changed schedule)
          ~payloads:[ Agent_protocol.Event.Durable.Payload.Schedule_created schedule ]
        |> Result.map ~f:ignore
      | Some scope ->
        initialization_transition
          t
          scope
          ~delta:(Session_delta.Schedule_changed schedule)
          ~payloads:[ Agent_protocol.Event.Durable.Payload.Schedule_created schedule ]
    in
    schedule
;;

let find_schedule t schedule_id =
  List.find t.state.schedules ~f:(fun schedule ->
    Agent_protocol.Id.Schedule.compare schedule.id schedule_id = 0)
  |> Result.of_option ~error:(error Invalid_request "schedule was not found")
;;

let validate_schedule_generation t schedule generation =
  if
    schedule.Agent_protocol.Schedule.generation <> generation
    || t.state.identity.generation <> generation
  then Error (error Conflict "schedule belongs to a stale session generation")
  else Ok ()
;;

let update_schedule ?goal_runtime_scope ?run_preparation t schedule =
  transition
    ?goal_runtime_scope
    ?run_preparation
    t
    ~delta:(Session_delta.Schedule_changed schedule)
    ~payloads:[ Agent_protocol.Event.Durable.Payload.Schedule_state_changed schedule ]
;;

let schedule_is_due t (schedule : Agent_protocol.Schedule.t) =
  match schedule.ownership with
  | None ->
    Ok (Agent_protocol.Timestamp.compare schedule.next_due_at (t.services.now ()) <= 0)
  | Some _ ->
    Extension_clock.is_due
      t.extension_clock
      (Schedule schedule.id)
      ~now:(t.services.monotonic_now ())
;;

let due_schedules t =
  if not (runtime_ready t)
  then Ok (t.state.lifecycle.observed, [])
  else
    let open Result.Let_syntax in
    let%map schedules =
      List.filter_map t.state.schedules ~f:(fun schedule ->
        match schedule.Agent_protocol.Schedule.status with
        | Scheduled when Int.equal schedule.generation t.state.identity.generation ->
          Some
            (schedule_is_due t schedule
             |> Result.map ~f:(fun due -> Option.some_if due schedule))
        | _ -> None)
      |> Result.all
      |> Result.map ~f:List.filter_opt
    in
    t.state.lifecycle.observed, schedules
;;

let claim_schedule ?goal_runtime_scope t schedule_id generation =
  let open Result.Let_syntax in
  let%bind schedule = find_schedule t schedule_id in
  let%bind () = validate_schedule_generation t schedule generation in
  let%bind () =
    if Session_state.execution_migration_required t.state
    then
      Error
        (error
           Migration_required
           "schedule execution requires explicit runtime migration")
    else Ok ()
  in
  match schedule.status with
  | Agent_protocol.Schedule.Scheduled ->
    let%bind due = schedule_is_due t schedule in
    (match due with
     | false -> Ok None
     | true ->
       let%bind () = require_selected_execution t in
       let schedule = { schedule with status = Delivering } in
       let%map _ = update_schedule ?goal_runtime_scope t schedule in
       Some schedule)
  | Delivering | Delivered | Cancelled | Failed _ -> Ok None
;;

let retry_schedule t schedule_id generation =
  let open Result.Let_syntax in
  let%bind schedule = find_schedule t schedule_id in
  let%bind () = validate_schedule_generation t schedule generation in
  match schedule.status with
  | Agent_protocol.Schedule.Delivering ->
    let schedule = { schedule with status = Scheduled } in
    let%map _ = update_schedule t schedule in
    schedule
  | Scheduled -> Ok schedule
  | Delivered | Cancelled | Failed _ ->
    Error (error Already_resolved "schedule is already terminal")
;;

let ingress_enqueue_available t =
  match
    moderator_is_borrowed t || t.idle_moderator_borrowed, t.state.halted, t.state.failure
  with
  | true, _, _ -> Error (error Conflict "moderator callback owns the ingress checkpoint")
  | _, true, _ | _, _, Some _ ->
    Error (error Invalid_state "moderator cannot accept external data")
  | false, false, None -> Ok ()
;;

let ingress_new_admission t candidate =
  let open Result.Let_syntax in
  let%bind subscription =
    lookup_subscription t candidate.External_ingress.context.subscription_id
    |> Result.of_option
         ~error:(error Invalid_state "ingress subscription is not retained")
  in
  let%bind due = subscription_is_due t subscription in
  let%bind () =
    match due with
    | true ->
      Error (error Invalid_state "ingress subscription has reached its elapsed deadline")
    | false -> Ok ()
  in
  Staged_ingress.check_capacity
    ~limits:t.services.ingress_limits
    ~generation:t.state.identity.generation
    ~now:(t.services.now ())
    ~subscriptions:
      (t.state.subscriptions @ Staged_subscriptions.values t.staged_subscriptions)
    ~values:
      ((candidate :: t.state.ingress_registrations)
       @ Staged_ingress.values t.staged_ingress)
;;

let prepare_ingress_submission_internal
      t
      source
      producer
      registration_id
      namespace
      key
      payload
  =
  let open Result.Let_syntax in
  let%bind () = validate_installed_observer t (Some source) in
  let%bind decision =
    Ingress_submission.prepare
      ~state:t.state
      ~source
      ~producer
      ~registration_id
      ~namespace
      ~key
      ~payload
      ~now:(t.services.now ())
      ~create_event_id:Agent_protocol.Id.Ingress_event.create
  in
  match decision with
  | Duplicate _ -> Ok decision
  | Enqueue proposal ->
    let%bind () = ingress_enqueue_available t in
    let%map () = ingress_new_admission t proposal.candidate in
    decision
;;

let commit_ingress_submission_internal t proposal before snapshot =
  let open Result.Let_syntax in
  let%bind () = ingress_enqueue_available t in
  let%bind () = validate_installed_observer t (Some proposal.Ingress_submission.source) in
  let%bind () = check_expected_moderator_checkpoint t (Some before) in
  let%bind next, receipt =
    Ingress_submission.revalidate ~state:t.state ~now:(t.services.now ()) proposal
  in
  let%bind () = ingress_new_admission t next in
  let%bind plan =
    External_delivery_checkpoint.prepare
      t.state
      ~producer:(Ingress { registration = next; receipt })
      ~before
      ~snapshot:(Known snapshot)
  in
  let%bind queue_update = prepare_ingress_delivery_queue t plan next in
  Exn.protect
    ~finally:(fun () -> Option.iter queue_update ~f:Legacy_queue_custody.Update.discard)
    ~f:(fun () ->
      let%map _ =
        transition
          ?queue_custody_installation:
            (Option.map queue_update ~f:(fun update ->
               Queue_custody_installation.Delivery_update update))
          t
          ~payloads:[]
          ~delta:
            (Session_delta.Batch
               (external_delivery_source_deltas plan
                @ [ Ingress_changed next
                  ; Moderator_changed
                      (Some (External_delivery_checkpoint.checkpoint plan))
                  ]))
      in
      receipt)
;;

let complete_legacy_schedule
      t
      manager
      expected_schedule
      (before : Session.Moderator_state.Identity_snapshot.t option)
      moderator_snapshot
      schedule
  =
  let open Result.Let_syntax in
  let current_source () =
    let%bind () = require_runtime_admission t in
    let%bind () =
      if Option.exists t.moderator_manager ~f:(phys_equal manager)
      then Ok ()
      else Error (error Conflict "legacy timer Manager changed before delivery")
    in
    Moderator_source_installation.capture t.state
  in
  let%bind () =
    if Option.is_some expected_schedule
    then Ok ()
    else Error (error Conflict "legacy timer delivery requires its exact saved record")
  in
  let%bind before =
    Result.of_option
      before
      ~error:(error Conflict "legacy timer delivery requires its previous checkpoint")
  in
  (* The Manager's known snapshot has no persistence metadata. Compare against
     the original installed checkpoint, while validating the complete retained
     queue child independently. Never compare a rewritten candidate to itself. *)
  let%bind () = Moderator_checkpoint.validate_encoded_capacity t.state.moderator in
  let%bind installed = Moderator_checkpoint.decode t.state.moderator in
  let%bind () =
    if
      Option.exists installed ~f:(fun installed ->
        Sexp.equal
          (Session.Moderator_state.Identity_snapshot.sexp_of_t installed)
          (Session.Moderator_state.Identity_snapshot.sexp_of_t before))
    then Ok ()
    else Error (error Conflict "legacy timer checkpoint changed before delivery")
  in
  let%bind snapshot = Moderator_checkpoint.decode moderator_snapshot in
  let%bind snapshot =
    Result.of_option
      snapshot
      ~error:(error Conflict "legacy timer delivery requires its prospective checkpoint")
  in
  let%bind index, source = current_source () in
  let%bind () =
    match schedule.Agent_protocol.Schedule.inference_provenance with
    | None -> Ok ()
    | Some provenance ->
      if
        Agent_protocol.Run_source.equal
          source
          (Agent_protocol.Schedule_provenance.source provenance)
      then Ok ()
      else Error (error Conflict "legacy timer original source is no longer installed")
  in
  let%bind metadata = Moderator_checkpoint.queue t.state.moderator in
  let%bind metadata =
    match metadata with
    | None -> Moderator_queue.bootstrap ~source ~queue:before.queued_internal_events
    | Some metadata ->
      if Agent_protocol.Run_source.equal source (Moderator_queue.source metadata)
      then Ok metadata
      else Error (error Conflict "legacy timer queue lifetime changed")
  in
  let%bind payload =
    Session.Snapshot.of_jsonaf schedule.payload
    |> Result.map_error ~f:Agent_protocol.Error.invalid_request
  in
  let expected_snapshot =
    { before with queued_internal_events = before.queued_internal_events @ [ payload ] }
  in
  let%bind () =
    if
      Sexp.equal
        (Session.Moderator_state.Identity_snapshot.sexp_of_t expected_snapshot)
        (Session.Moderator_state.Identity_snapshot.sexp_of_t snapshot)
    then Ok ()
    else Error (error Conflict "legacy timer delivery must append its exact raw payload")
  in
  let%bind capture =
    match schedule.inference_provenance with
    | None -> Ok Moderator_queue.Capture.unavailable
    | Some provenance ->
      Moderator_queue.Capture.create
        ~producer:
          (Schedule_delivery
             { id = schedule.id
             ; generation = schedule.generation
             ; delivery_count = schedule.delivery_count
             })
        ~origin:(Agent_protocol.Schedule_provenance.origin provenance)
  in
  let%bind plan =
    Legacy_queue_checkpoint.append_delivery ~metadata ~before ~snapshot ~capture
  in
  let%bind encoded =
    Moderator_checkpoint.update_with_queue
      t.state.moderator
      ~snapshot
      ~queue:(Legacy_queue_checkpoint.metadata plan)
  in
  (* Stage while the Delivering timer's actual loan still exists. Installing
     Delivered will retire that phase, so no later lookup may reconstruct it. *)
  let%bind continuation =
    Legacy_schedule_custody.transfer_delivery
      t.legacy_schedule_custody
      ~manager
      ~source
      ~schedule
  in
  let staged =
    match continuation with
    | None -> Legacy_queue_custody.empty
    | Some continuation ->
      Legacy_queue_custody.stage_delivery
        ~manager
        ~source
        ~entry:(List.hd_exn (Legacy_queue_checkpoint.appended plan))
        ~continuation
        ~policy_source:Unknown
  in
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () -> if not !acknowledged then Legacy_queue_custody.retire staged)
    ~f:(fun () ->
      let%bind inventory =
        Legacy_queue_custody.candidate
          t.legacy_queue_custody
          ~manager
          ~metadata:(Legacy_queue_checkpoint.metadata plan)
          ~staged
      in
      let delta =
        Session_delta.Batch
          [ Run_state_changed index
          ; Schedule_changed schedule
          ; Moderator_changed (Some encoded)
          ]
      in
      let completion_sample = producer_completion_sample t ~delta in
      let%bind prepared =
        prepare_transition
          ?completion_sample
          t
          ~delta
          ~payloads:
            [ Agent_protocol.Event.Durable.Payload.Schedule_state_changed schedule ]
      in
      let%bind completion_plan = prepare_completion_plan t prepared completion_sample in
      let%bind _, final_source = current_source () in
      let%bind () =
        if Agent_protocol.Run_source.equal source final_source
        then Ok ()
        else Error (error Conflict "legacy timer source changed before delivery ACK")
      in
      (* This is a truthful completed-fact write, not a new effect admission.
         Known expiry is carried into the queue and must not erase Delivered. *)
      Eio.Cancel.protect (fun () ->
        let%bind () = persist_transition t prepared in
        install_committed_transition t prepared;
        t.legacy_queue_custody
        <- Legacy_queue_custody.install t.legacy_queue_custody ~incoming:inventory;
        acknowledged := true;
        Option.iter
          completion_plan
          ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
        publish_committed_transition t prepared;
        Ok schedule))
;;

let complete_schedule
      ?goal_runtime_scope
      t
      schedule_id
      generation
      expected
      expected_schedule
      moderator_snapshot
      moderator_manager
  =
  let open Result.Let_syntax in
  let%bind () =
    match moderator_is_borrowed t with
    | true -> Error (error Conflict "moderator callback owns the checkpoint")
    | false -> Ok ()
  in
  let%bind schedule = find_schedule t schedule_id in
  let%bind () =
    match schedule.ownership, moderator_manager with
    | None, Some manager
      when Option.is_none (Chat_response.Moderator_manager.invocation_observer manager) ->
      (* The actual legacy helper below performs known comparison together
         with its resource/source/queue validation. Owned v1 uses the full
         carrier planner below. *)
      Ok ()
    | (Some _ | None), _ -> check_expected_moderator_checkpoint t expected
  in
  let%bind () =
    match expected_schedule with
    | None -> Ok ()
    | Some expected_schedule ->
      if
        Jsonaf.exactly_equal
          (Agent_protocol.Schedule.to_json expected_schedule)
          (Agent_protocol.Schedule.to_json schedule)
      then Ok ()
      else Error (error Conflict "schedule changed before event delivery")
  in
  let%bind () = validate_schedule_generation t schedule generation in
  match schedule.status with
  | Agent_protocol.Schedule.Delivering ->
    let%bind plan =
      match schedule.ownership, expected, moderator_snapshot with
      | Some _, Some before, Some after ->
        External_delivery_checkpoint.prepare
          t.state
          ~producer:(Owned_schedule schedule)
          ~before
          ~snapshot:(Encoded after)
        |> Result.map ~f:Option.some
      | Some _, (Some _ | None), (Some _ | None) ->
        Error (error Conflict "owned timer delivery requires its installed checkpoint")
      | None, _, _ -> Ok None
    in
    if schedule.delivery_count = Int.max_value
    then Error (error Invalid_state "schedule delivery count overflow")
    else (
      let schedule =
        { schedule with
          status = Delivered
        ; delivery_count = schedule.delivery_count + 1
        ; last_delivery_at =
            Some
              (match schedule.ownership with
               | None -> t.services.now ()
               | Some _ ->
                 let now = t.services.now () in
                 (match Agent_protocol.Timestamp.compare now schedule.created_at < 0 with
                  | true -> schedule.created_at
                  | false -> now))
        }
      in
      let%bind metadata = Moderator_checkpoint.queue t.state.moderator in
      match schedule.ownership, moderator_manager with
      | None, Some manager
        when Option.is_none (Chat_response.Moderator_manager.invocation_observer manager)
        ->
        let%bind () =
          match goal_runtime_scope with
          | None -> Ok ()
          | Some _ ->
            Error
              (error
                 Permission_denied
                 "Goal wake cannot restore a retired legacy Manager loan")
        in
        complete_legacy_schedule
          t
          manager
          expected_schedule
          expected
          moderator_snapshot
          schedule
      | None, _
        when Option.is_some schedule.inference_provenance || Option.is_some metadata ->
        Error
          (error Conflict "captured legacy timer delivery requires its actual Manager")
      | (Some _ | None), _ ->
        let%bind queue_update =
          Option.value_map plan ~default:(Ok None) ~f:(fun plan ->
            prepare_schedule_delivery_queue t plan schedule)
        in
        Exn.protect
          ~finally:(fun () ->
            Option.iter queue_update ~f:Legacy_queue_custody.Update.discard)
          ~f:(fun () ->
            let%map _ =
              transition
                ?queue_custody_installation:
                  (Option.map queue_update ~f:(fun update ->
                     Queue_custody_installation.Delivery_update update))
                ?goal_runtime_scope
                t
                ~delta:
                  (Session_delta.Batch
                     (Option.value_map plan ~default:[] ~f:external_delivery_source_deltas
                      @ [ Schedule_changed schedule
                        ; Moderator_changed
                            (Option.value_map
                               plan
                               ~default:moderator_snapshot
                               ~f:(fun plan ->
                                 Some (External_delivery_checkpoint.checkpoint plan)))
                        ]))
                ~payloads:
                  [ Agent_protocol.Event.Durable.Payload.Schedule_state_changed schedule ]
            in
            schedule))
  | Scheduled -> Error (error Conflict "schedule delivery was not claimed")
  | Delivered | Cancelled | Failed _ ->
    Error (error Already_resolved "schedule is already terminal")
;;

let fail_schedule t schedule_id generation failure =
  let open Result.Let_syntax in
  let%bind schedule = find_schedule t schedule_id in
  let%bind () = validate_schedule_generation t schedule generation in
  match schedule.status with
  | Agent_protocol.Schedule.Scheduled | Delivering ->
    let schedule = { schedule with status = Failed failure } in
    let%map _ = update_schedule t schedule in
    schedule
  | Delivered | Cancelled | Failed _ ->
    Error (error Already_resolved "schedule is already terminal")
;;

let skip_schedule t schedule_id generation =
  let open Result.Let_syntax in
  let%bind schedule = find_schedule t schedule_id in
  let%bind () = validate_schedule_generation t schedule generation in
  match schedule.status with
  | Agent_protocol.Schedule.Scheduled ->
    let schedule = { schedule with status = Delivered } in
    let%map _ = update_schedule t schedule in
    schedule
  | Delivering -> Error (error Conflict "schedule delivery is already claimed")
  | Delivered | Cancelled | Failed _ ->
    Error (error Already_resolved "schedule is already terminal")
;;

let cancel_schedule_internal ?initialization_scope ?run_preparation t schedule_id =
  let open Result.Let_syntax in
  let%bind schedule = find_schedule t schedule_id in
  match schedule.status with
  | Agent_protocol.Schedule.Scheduled ->
    let schedule = { schedule with status = Cancelled } in
    let%map _ =
      match initialization_scope with
      | None ->
        transition
          ?run_preparation
          t
          ~delta:(Session_delta.Schedule_changed schedule)
          ~payloads:[ Agent_protocol.Event.Durable.Payload.Schedule_cancelled schedule ]
        |> Result.map ~f:ignore
      | Some scope ->
        initialization_transition
          t
          scope
          ~delta:(Session_delta.Schedule_changed schedule)
          ~payloads:[ Agent_protocol.Event.Durable.Payload.Schedule_cancelled schedule ]
    in
    schedule
  | Delivering | Delivered | Cancelled | Failed _ ->
    Error (error Already_resolved "schedule is already terminal")
;;

let callback_schedule_admission t (scope : Callback_scope.t) =
  let open Result.Let_syntax in
  let%bind () = require_runtime_admission t in
  let%bind () = check_callback_current t scope in
  match scope.custody with
  | Admitted admission -> Ok admission
  | Unavailable ->
    Error (error Permission_denied "legacy Schedule continuation custody is unavailable")
;;

let callback_schedule_after_ms t (scope : Callback_scope.t) delay_ms payload =
  let open Result.Let_syntax in
  let%bind parent = callback_schedule_admission t scope in
  let created_at = t.services.now () in
  (* Preserve immediate legacy wall-clock semantics. Timestamp.add_ms performs
     the existing nonnegative and representable-endpoint checks. *)
  let%bind next_due_at = Agent_protocol.Timestamp.add_ms created_at delay_ms in
  let%bind provenance =
    Agent_protocol.Schedule_provenance.create ~source:scope.source ~origin:scope.origin
  in
  let schedule : Agent_protocol.Schedule.t =
    { id = Agent_protocol.Id.Schedule.create ()
    ; session_id = t.state.identity.session_id
    ; generation = t.state.identity.generation
    ; payload
    ; created_at
    ; next_due_at
    ; misfire = Deliver_once_immediately
    ; status = Scheduled
    ; delivery_count = 0
    ; last_delivery_at = None
    ; inference_provenance = Some provenance
    ; delivery_cancellation = None
    ; ownership = None
    }
  in
  let%bind staged =
    Legacy_schedule_custody.stage
      ~manager:scope.manager
      ~source:scope.source
      ~schedule
      ~parent
  in
  let acknowledged = ref false in
  Exn.protect
    ~finally:(fun () -> if not !acknowledged then Legacy_schedule_custody.retire staged)
    ~f:(fun () ->
      let%bind inventory =
        Legacy_schedule_custody.candidate t.legacy_schedule_custody ~staged
      in
      let%bind prepared =
        prepare_transition
          ?run_preparation:(callback_run_preparation scope)
          t
          ~delta:(Session_delta.Schedule_changed schedule)
          ~payloads:[ Agent_protocol.Event.Durable.Payload.Schedule_created schedule ]
      in
      let%bind initialization_acknowledgement =
        match scope.constructor_scope with
        | None -> Ok None
        | Some constructor ->
          let%map resource =
            Initialization_scope.Resource.select
              constructor.resource
              prepared.state
              ~manager:scope.manager
              ~source:scope.source
              ~ordinals:[]
              ~schedules:[ schedule.id ]
          in
          Some
            (Initialization_scope.Acknowledgement.prepare
               ~resource
               constructor
               prepared.state)
      in
      let%bind _ = callback_schedule_admission t scope in
      Eio.Cancel.protect (fun () ->
        let%bind () =
          Option.value_map
            initialization_acknowledgement
            ~default:(Ok ())
            ~f:Initialization_scope.Acknowledgement.check_basis
        in
        let%bind () = persist_transition t prepared in
        install_committed_transition
          ?run_preparation:(callback_run_preparation scope)
          ~schedule_custody_installation:
            (Schedule_custody_installation.Inventory inventory)
          ?initialization_acknowledgement
          t
          prepared;
        acknowledged := true;
        publish_committed_transition t prepared;
        Ok schedule))
;;

let callback_schedule_cancel t scope schedule_id =
  let open Result.Let_syntax in
  let%bind _ = callback_schedule_admission t scope in
  let%bind schedule = find_schedule t schedule_id in
  match schedule.status with
  | Scheduled ->
    (* The genuine caller is checked, not the target timer's provenance. Keep
       legacy cancellation of any retained Scheduled ID, including old timers. *)
    let schedule = { schedule with status = Agent_protocol.Schedule.Cancelled } in
    let delta = Session_delta.Schedule_changed schedule in
    let completion_sample = producer_completion_sample t ~delta in
    let%bind prepared =
      prepare_transition
        ?completion_sample
        ?run_preparation:(callback_run_preparation scope)
        t
        ~delta
        ~payloads:[ Agent_protocol.Event.Durable.Payload.Schedule_cancelled schedule ]
    in
    let%bind completion_plan = prepare_completion_plan t prepared completion_sample in
    let%bind callback_acknowledgement =
      Producer_callback_acknowledgement.prepare t ~candidate:prepared
    in
    let initialization_acknowledgement =
      Option.map scope.constructor_scope ~f:(fun constructor ->
        Initialization_scope.Acknowledgement.prepare constructor prepared.state)
    in
    let%bind _ = callback_schedule_admission t scope in
    Eio.Cancel.protect (fun () ->
      let%bind () =
        persist_transition t prepared ~check_before_commit:(fun () ->
          let%bind _ = callback_schedule_admission t scope in
          let%bind () =
            Option.value_map
              initialization_acknowledgement
              ~default:(Ok ())
              ~f:Initialization_scope.Acknowledgement.check_basis
          in
          Option.value_map callback_acknowledgement ~default:(Ok ()) ~f:(fun ack ->
            Producer_callback_acknowledgement.check ack ~actor:t ~candidate:prepared))
      in
      (* The ordinary installation retention pass closes a matching timer loan
         before publication. Historical targets need not have a loan. *)
      install_committed_transition
        ?run_preparation:(callback_run_preparation scope)
        ?initialization_acknowledgement
        t
        prepared;
      let%bind () =
        Option.value_map
          callback_acknowledgement
          ~default:(Ok ())
          ~f:Producer_callback_acknowledgement.install
      in
      Option.iter
        completion_plan
        ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
      publish_committed_transition t prepared;
      Ok schedule)
  | Delivering | Delivered | Cancelled | Failed _ ->
    Error (error Already_resolved "schedule is already terminal")
;;

let claim_idle_moderator t =
  if not (idle_moderator_eligible t)
  then Ok None
  else (
    let%bind.Result () = require_selected_execution t in
    History_codec.all_of_protocol t.state.conversation.canonical_history
    |> Result.map ~f:(fun history ->
      exclude_effect_deferred t Ordinary_execution;
      t.idle_moderator_borrowed <- true;
      Some history))
;;

let notification_payload message =
  Agent_protocol.Event.Durable.Payload.Moderator_notification
    (`Object [ "message", `String message ])
;;

let drain_payloads (drain : Runtime_builder.moderator_drain) =
  List.map drain.Runtime_builder.notifications ~f:notification_payload
;;

let install_idle_turn_selection ?idle_completion ?goal_runtime_scope t selection =
  let { Idle_turn.operation
      ; custody = agent_custody
      ; deltas
      ; payloads
      ; completion_sample
      ; follow_up_authority
      ; _
      }
    =
    selection
  in
  let open Result.Let_syntax in
  let installed = ref false in
  Exn.protect
    ~f:(fun () ->
      let final_check () =
        let%bind () = check_turn_custody t agent_custody in
        Option.value_map
          follow_up_authority
          ~default:(Ok ())
          ~f:(check_follow_up_authority t)
      in
      let completion_sample =
        match goal_runtime_scope with
        | None ->
          producer_completion_sample
            ?completion_sample
            t
            ~delta:(Session_delta.Batch deltas)
        | Some _ -> completion_sample
      in
      let before = t.state in
      let%bind candidate =
        prepare_transition
          ?completion_sample
          t
          ~delta:(Session_delta.Batch deltas)
          ~payloads
      in
      let attempted = ref false in
      let%bind staged =
        Turn_admission_staging.capture
          ~owner:t.run_preparation_owner
          ~before
          ~candidate
          ~operation
          ~remaining_audit:t.command_audit
          ~commit_attempted:attempted
          ~plan:(operation, agent_custody)
      in
      let%bind () =
        prepare_idle_operation_suffix
          t
          idle_completion
          ~operation
          ~custody:agent_custody
          ~installed
          ~kind:(Idle_completion_data.Turn staged)
      in
      let%bind idle_completion_write =
        prepare_idle_completion_write
          t
          idle_completion
          ~kind:Idle_completion_write.Kind.Start_ordinary_turn
          ~candidate
          ~attempted
      in
      let checked_final () =
        let%bind () = final_check () in
        Turn_admission_staging.check_before_writer
          staged
          ~owner:t.run_preparation_owner
          ~state:t.state
      in
      let%bind () =
        match goal_runtime_scope with
        | None ->
          install
            ?idle_completion_write
            ~turn_stage:staged
            ?completion_sample
            ~commit_attempted:attempted
            ~check_before_commit:checked_final
            t
            candidate
        | Some scope ->
          let%bind completion_plan =
            prepare_completion_plan t candidate completion_sample
          in
          let%bind ack = prepare_goal_operation_ack t scope ~operation ~candidate in
          let%bind fact = Goal_runtime_acknowledgement.prepare t scope ~candidate in
          let accepted = ref false in
          Exn.protect
            ~finally:(fun () ->
              if not !accepted
              then (
                retire_agent_admission ack.owner.admission;
                ack.held.proof.controller.close ()))
            ~f:(fun () ->
              let%bind () =
                persist_transition
                  ~commit_attempted:attempted
                  t
                  candidate
                  ~check_before_commit:(fun () ->
                    let%bind () = checked_final () in
                    let%bind () =
                      check_runtime_construction_effect (Existing_goal scope.continuation)
                    in
                    let%bind () =
                      Goal_runtime_operation_acknowledgement.check ack ~actor:t ~candidate
                    in
                    Goal_runtime_acknowledgement.check fact ~actor:t ~candidate)
              in
              install_committed_transition
                ~goal_runtime_acknowledgement:fact
                ~goal_operation_acknowledgement:ack
                t
                candidate;
              accepted := true;
              installed := true;
              let%bind _ =
                Turn_admission_staging.acknowledge
                  staged
                  ~owner:t.run_preparation_owner
                  ~state:t.state
              in
              Option.iter
                completion_plan
                ~f:(Recurrence_runtime.install_completions t.recurrence_runtime);
              publish_committed_transition t candidate;
              Ok ())
      in
      let%bind acknowledgement =
        Turn_admission_staging.acknowledge
          staged
          ~owner:t.run_preparation_owner
          ~state:t.state
      in
      let%bind operation, agent_custody =
        Turn_admission_staging.finish
          acknowledgement
          ~owner:t.run_preparation_owner
          ~state:t.state
      in
      let%bind () = check_idle_operation_suffix t idle_completion operation in
      if Option.is_none t.operation_agent_custody
      then (
        install_operation_agent_custody t operation agent_custody;
        installed := true);
      prune_pending_agent_custody t;
      launch_worker t operation;
      handoff_idle_operation idle_completion;
      Ok ())
    ~finally:(fun () ->
      if not !installed then Option.iter agent_custody ~f:retire_agent_custody)
;;

let start_idle_turn_unchecked
      ?idle_completion
      ?idle_capture
      ?goal_runtime_scope
      ?continuation_custody
      ?follow_up_authority
      ?(extra_deltas = [])
      ?(extra_payloads = [])
      ?(notification_wakes = [])
      t
      (drain : Runtime_builder.moderator_drain)
      ~reason
      ~adopt_deferred
  =
  let open Result.Let_syntax in
  let%bind () = require_selected_execution t in
  let%bind () = require_runtime_admission t in
  let%bind () = reconcile_foreground_invocations ?idle_completion t in
  let operation = create_turn_operation t reason in
  let%bind admission =
    let retention = Pending_disposition.Retention.default in
    Turn_admission.create
      ~pending_retention:(Some retention)
      ~runtime_admission_open:(runtime_admission_open t)
      t.state
      ~operation
      ~notification_wakes
      ~adopt_deferred
  in
  let%bind agent_custody = admission_agent_custody t admission in
  let%bind agent_custody =
    let has_input =
      List.exists (Turn_admission.payloads admission) ~f:(function
        | Agent_protocol.Event.Durable.Payload.History_appended entries ->
          not (List.is_empty entries)
        | _ -> false)
    in
    match agent_custody, continuation_custody with
    | None, Some custody when (not has_input) && List.is_empty notification_wakes ->
      Result.map (transfer_agent_custody custody) ~f:Option.some
    | custody, (None | Some _) -> Ok custody
  in
  let handed_off = ref false in
  Exn.protect
    ~finally:(fun () ->
      if not !handed_off then Option.iter agent_custody ~f:retire_agent_custody)
    ~f:(fun () ->
      let leading_deltas, turn_deltas =
        match Turn_admission.deltas admission with
        | (Pending_inputs_changed _ as delta) :: rest -> [ delta ], rest
        | deltas -> [], deltas
      in
      let leading_payloads, turn_payloads =
        match Turn_admission.payloads admission with
        | History_appended entries :: rest ->
          [ Agent_protocol.Event.Durable.Payload.History_appended entries ], rest
        | payloads -> [], payloads
      in
      let events =
        List.filter_map extra_deltas ~f:(function
          | Session_delta.Moderator_lifecycle_claimed { receipt = event; _ }
          | Session_delta.Moderator_execution_changed event -> Some event
          | _ -> None)
      in
      let companion_deltas =
        leading_deltas
        @ extra_deltas
        @ [ Session_delta.Moderator_changed drain.Runtime_builder.moderator_snapshot ]
        @ turn_deltas
      in
      let work_delta = Session_delta.Batch companion_deltas in
      let completion_sample = producer_completion_sample t ~delta:work_delta in
      let%bind run_deltas =
        run_turn_deltas
          ~work_delta
          ?completion_sample
          t
          operation
          events
          notification_wakes
      in
      let deltas = run_deltas @ companion_deltas in
      let payloads =
        drain_payloads drain @ leading_payloads @ extra_payloads @ turn_payloads
      in
      let worker = t.operation_worker in
      let%bind observer = Runtime_builder.moderator_snapshot_observer t.state.moderator in
      let selection : Idle_turn.t =
        { before = t.state
        ; operation
        ; custody = agent_custody
        ; deltas
        ; payloads
        ; completion_sample
        ; worker
        ; manager = t.moderator_manager
        ; observer
        ; follow_up_authority
        }
      in
      match idle_capture, goal_runtime_scope, inherited_turn_required t.state with
      | Some capture, scope, (Scoped | Need_private_origin) ->
        let%map _ =
          Result.of_option
            worker
            ~error:
              (error Invalid_state "inherited idle Turn requires an installed worker")
        in
        capture.Idle_turn.Capture.selected
        <- Some
             (match scope with
              | None -> Ordinary selection
              | Some scope -> Goal_subscription { turn = selection; scope });
        handed_off := true
      | (None | Some _), (None | Some _), (Ordinary | Scoped | Need_private_origin) ->
        handed_off := true;
        install_idle_turn_selection ?idle_completion ?goal_runtime_scope t selection)
;;

let control_pending_internal
      t
      principal
      project
      (request : Agent_protocol.Pending_control.Cancel_request.t)
      replacement
  =
  with_writer t request.attachment_id (fun () ->
    let open Result.Let_syntax in
    let%bind () =
      if
        (not
           (Agent_protocol.Id.Session.equal
              request.session_id
              t.state.identity.session_id))
        || not (Int.equal request.expected_generation t.state.identity.generation)
      then Error (error Conflict "pending control session or generation differs")
      else Ok ()
    in
    let%bind () =
      Pending_inspection.authorize_control
        t.state
        ~history_id:request.history_id
        ~principal
    in
    let%bind outcome =
      Pending_inspection.lookup t.state ~history_id:request.history_id ~project
    in
    let%bind () =
      match outcome with
      | Pending _ ->
        if
          Agent_protocol.Pending_input.Revision.equal
            request.expected_pending_revision
            t.state.conversation.pending_revision
        then Ok ()
        else Error (error Conflict "pending queue revision differs")
      | Adopted _ | Cancelled _ | Retired _ | Unavailable _ -> Ok ()
    in
    let%bind () =
      match outcome with
      | Adopted _ | Cancelled _ | Retired _ | Unavailable _ -> Ok ()
      | Pending _ ->
        let change =
          match replacement with
          | None ->
            Pending_plan.Change.Cancel
              { history_id = request.history_id
              ; expected_content_revision = request.expected_content_revision
              }
          | Some text ->
            Replace_text
              { history_id = request.history_id
              ; expected_content_revision = request.expected_content_revision
              ; text
              }
        in
        let retention = Pending_disposition.Retention.default in
        let%bind _ =
          Pending_plan.prepare
            t.state
            ~expected_pending_revision:request.expected_pending_revision
            ~change
            ~retention
            ~limits:Session_delta.native_limits
        in
        let%bind archive =
          t.persistence.archive_reference
            ~previous:t.state
            ~kind:Pending_input
            (Agent_protocol.Id.Operation.create ())
        in
        let%bind prepared = prepare_pending t ~archive:(Some archive) change in
        let%bind candidate =
          Pending_plan.apply (Pending_transition.plan prepared) t.state
        in
        let%map _ =
          transition
            t
            ~delta:(Pending_transition.delta prepared)
            ~payloads:
              [ Agent_protocol.Event.Durable.Payload.Session_updated
                  (Session_state.summary candidate)
              ]
        in
        ()
    in
    let%map outcome =
      Pending_inspection.lookup t.state ~history_id:request.history_id ~project
    in
    Agent_protocol.Pending_control.Result.
      { pending_revision = t.state.conversation.pending_revision
      ; outcome
      ; mutation =
          { revision = t.state.counters.revision
          ; latest_event_sequence = t.state.counters.event_sequence
          }
      })
;;

let delete_history_internal t attachment_id revision history_id =
  let open Result.Let_syntax in
  let%bind () =
    history_command_precondition
      t
      t.state.identity.session_id
      attachment_id
      t.state.identity.generation
      revision
  in
  let%bind plan = History_deletion.prepare t.state ~history_id in
  let%bind archive =
    t.persistence.archive_reference
      ~previous:t.state
      ~kind:Delete
      (Agent_protocol.Id.Operation.create ())
  in
  commit_history_transition
    t
    ~delta:(Session_delta.History_deleted (history_id, archive))
    ~payloads:
      [ Agent_protocol.Event.Durable.Payload.History_replaced
          (Session_state.history_window (History_deletion.canonical_history plan))
      ]
    ~admission:None
;;

let suppress_follow_up_deltas t deltas ~reason =
  let open Result.Let_syntax in
  List.map deltas ~f:(function
    | (Session_delta.Invocation_changed next | Invocation_reconciled next) as delta ->
      let%bind original =
        List.find t.state.invocations ~f:(fun value ->
          Agent_protocol.Id.Invocation.equal value.context.id next.context.id)
        |> Result.of_option
             ~error:(error Invalid_state "automatic-turn invocation is missing")
      in
      let%map values = Observation_follow_up.discard [ original ] ~reason in
      (match values with
       | [] -> delta
       | value :: _ -> Observation_follow_up.delta value)
    | Moderator_lifecycle_claimed _ ->
      Error
        (error
           Invalid_state
           "a new lifecycle claim cannot be discarded as automatic-turn follow-up")
    | (Moderator_execution_changed next | Moderator_execution_reconciled next) as delta ->
      let%bind original =
        List.find t.state.moderator_executions ~f:(fun value ->
          Agent_protocol.Id.Moderator_execution.equal value.context.id next.context.id)
        |> Result.of_option ~error:(error Invalid_state "automatic-turn event is missing")
      in
      let%map values = Observation_follow_up.discard_events [ original ] ~reason in
      (match values with
       | [] -> delta
       | value :: _ -> Observation_follow_up.event_delta value)
    | delta -> Ok delta)
  |> Result.all
;;

let start_idle_turn
      ?idle_completion
      ?idle_capture
      ?goal_runtime_scope
      ?continuation_custody
      ?follow_up_authority
      ?(extra_deltas = [])
      ?(extra_payloads = [])
      ?(notification_wakes = [])
      t
      (drain : Runtime_builder.moderator_drain)
      ~reason
      ~adopt_deferred
  =
  let open Result.Let_syntax in
  let%bind eligible = if adopt_deferred then eligible_pending t Idle_start else Ok [] in
  let adopt_deferred = not (List.is_empty eligible) in
  let reason = if adopt_deferred then Agent_protocol.Operation.User_submit else reason in
  let decision =
    match reason, t.state.automatic_turn_budget with
    | (Agent_protocol.Operation.User_submit | Administrative | Recovery_retry), _
    | _, None -> Chat_response.Automatic_turn_policy.Allow_automatic_turn
    | (Moderator_request | Idle_followup), Some budget ->
      (match budget.policy.honor_request_turn with
       | true -> Automatic_turn_budget.decide budget ~now:(t.services.now ())
       | false ->
         Suppress_automatic_turn
           { notice_key = "budget:request-turn-disabled"
           ; notice_text = "Automatic follow-up turns are disabled by runtime policy."
           })
  in
  match decision with
  | Allow_automatic_turn ->
    start_idle_turn_unchecked
      ?idle_capture
      ?idle_completion
      ?goal_runtime_scope
      ?continuation_custody
      ?follow_up_authority
      ~extra_deltas
      ~extra_payloads
      ~notification_wakes
      t
      drain
      ~reason
      ~adopt_deferred
  | Suppress_automatic_turn { notice_key; notice_text } ->
    let open Result.Let_syntax in
    let%bind extra_deltas =
      suppress_follow_up_deltas t extra_deltas ~reason:notice_text
    in
    let%bind wake_deltas =
      List.map notification_wakes ~f:(fun value ->
        Agent_protocol.Delivery.discard_wake value ~reason:notice_text
        |> Result.map ~f:(fun value -> Session_delta.Delivery_wake_changed value))
      |> Result.all
    in
    transition
      ?idle_completion_step:
        (Option.map idle_completion ~f:(fun completion ->
           completion, Idle_completion_write.Kind.Suppress_automatic))
      t
      ~delta:
        (Session_delta.Batch
           (extra_deltas @ wake_deltas @ [ Moderator_changed drain.moderator_snapshot ]))
      ~payloads:
        (extra_payloads
         @ drain_payloads drain
         @ [ Agent_protocol.Event.Durable.Payload.Moderator_notification
               (`Object [ "key", `String notice_key; "message", `String notice_text ])
           ])
    |> Result.map ~f:ignore
;;

let stop_from_idle_moderator
      ?idle_completion
      ?(extra_deltas : Session_delta.t list = [])
      t
      (drain : Runtime_builder.moderator_drain)
      reason
  =
  let open Result.Let_syntax in
  let jobs = stopped_jobs t Cancel in
  let job_custody = Job_custody.prepare_retirement t.job_agent_custody in
  let permissions =
    pending_invocation_permissions t ~matches:(fun _ -> true)
    |> List.map ~f:(cancel_permission t "session ended")
  in
  let changed invocation =
    List.exists extra_deltas ~f:(function
      | Session_delta.Invocation_changed updated | Invocation_reconciled updated ->
        Agent_protocol.Id.Invocation.equal
          updated.context.id
          invocation.Agent_protocol.Invocation.context.id
      | _ -> false)
  in
  let%bind discarded =
    Observation_follow_up.discard
      (List.filter t.state.invocations ~f:(fun invocation -> not (changed invocation)))
      ~reason:"moderator ended session"
  in
  let%bind events =
    Observation_follow_up.discard_events
      (List.filter t.state.moderator_executions ~f:(fun event ->
         not
           (List.exists extra_deltas ~f:(function
              | Session_delta.Moderator_lifecycle_claimed { receipt = updated; _ }
              | Session_delta.Moderator_execution_changed updated
              | Moderator_execution_reconciled updated ->
                Agent_protocol.Id.Moderator_execution.equal
                  event.context.id
                  updated.context.id
              | _ -> false))))
      ~reason:"moderator ended session"
  in
  let extra_deltas =
    extra_deltas
    @ List.map discarded ~f:Observation_follow_up.delta
    @ List.map events ~f:Observation_follow_up.event_delta
    @ List.map jobs ~f:(fun job -> Session_delta.Job_changed job)
    @ List.map permissions ~f:(fun permission ->
      Session_delta.Permission_changed permission)
  in
  let lifecycle = Session_state.Lifecycle.{ desired = Stopped; observed = Stopped } in
  let payloads =
    drain_payloads drain
    @ List.map jobs ~f:(fun job ->
      Agent_protocol.Event.Durable.Payload.Job_state_changed job)
    @ List.map permissions ~f:(fun permission ->
      Agent_protocol.Event.Durable.Payload.Permission_resolved permission)
    @ [ Agent_protocol.Event.Durable.Payload.Moderator_notification
          (`Object [ "end_session_reason", `String reason ])
      ; Session_state_changed
          { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
      ]
  in
  Option.iter idle_completion ~f:(fun completion ->
    completion.Idle_completion_data.suffix <- Some (Stop (jobs, permissions)));
  let%map _ =
    transition
      ?idle_completion_step:
        (Option.map idle_completion ~f:(fun completion ->
           completion, Idle_completion_write.Kind.Stop))
      ~retire_legacy_custody:()
      ~job_custody
      t
      ~delta:
        (Session_delta.Batch
           (extra_deltas
            @ [ Session_delta.Moderator_changed drain.moderator_snapshot
              ; Halt_changed (Some reason)
              ; Lifecycle_changed lifecycle
              ]))
      ~payloads
  in
  cancel_job_scopes t jobs;
  resolve_cleaned_permission_waiters t permissions;
  Option.iter idle_completion ~f:(fun completion ->
    completion.Idle_completion_data.suffix <- None)
;;

let deliver_idle_notifications_internal
      ?idle_capture
      ?goal_execution
      t
      (proposal : Notification_delivery.idle)
  =
  let open Result.Let_syntax in
  let%bind goal_runtime_scope =
    match goal_execution with
    | None -> Ok None
    | Some execution ->
      let%bind scope = select_goal_runtime t execution in
      let%bind () = check_runtime_construction_effect (Existing_goal execution) in
      let%bind () =
        match execution.binding.preparation.cause, scope.callback with
        | Pending_wake { wake; _ }, Joined ->
          (match wake.occurrence with
           | Subscription_delivery _ -> Ok ()
           | Job_completion _ | Delivered_timer _ ->
             Error (error Invalid_request "Goal queue wake requires Event admission"))
        | (Resume_command _ | Pending_wake _ | Claimed_job _), _ ->
          Error (error Conflict "Goal subscription lifecycle has not joined")
      in
      Ok (Some scope)
  in
  match idle_moderator_eligible t with
  | false -> Ok false
  | true ->
    let%bind () = validate_notification_plan t proposal.pending in
    let%bind halted = Runtime_builder.moderator_snapshot_is_halted t.state.moderator in
    (match halted with
     | true -> Ok false
     | false ->
       let%bind follow_up =
         Observation_follow_up.plan
           ~state:t.state
           ~observer:proposal.pending.source
           ~halted:false
           ~compaction_operation_id:(Agent_protocol.Id.Operation.create ())
       in
       (match follow_up.action with
        | Stop _ | Compact -> Ok false
        | Checkpoint | Turn ->
          let%bind deltas, entries, committed = notification_changes t proposal.pending in
          let deltas =
            deltas
            @ List.map proposal.discarded_wakes ~f:(fun value ->
              Session_delta.Delivery_wake_changed value)
          in
          let notification_wakes =
            proposal.wakes
            @ List.filter committed ~f:(fun value ->
              match value.wake_disposition with
              | Some Pending_wake -> true
              | _ -> false)
          in
          let%bind selection_state =
            Session_delta.apply t.state (Session_delta.Batch deltas)
          in
          let%bind wake_context =
            match goal_runtime_scope with
            | None -> Ok Notification_wake_selection.Context.Ordinary
            | Some scope ->
              (* The actual scope was authenticated above. This projection is
                 only routing DATA for that same unconsumed occurrence. *)
              let%map wake = Goal_execution_runtime.wake scope.continuation in
              Notification_wake_selection.Context.Goal_wake wake
          in
          let%bind notification_wakes =
            Notification_wake_selection.select
              selection_state
              ~context:wake_context
              notification_wakes
          in
          (match deltas, notification_wakes with
           | [], [] -> Ok false
           | _ ->
             let extra_deltas =
               match goal_runtime_scope with
               | None -> deltas @ follow_up_deltas t follow_up
               | Some _ -> deltas
             in
             let extra_payloads = notification_payloads entries in
             let drain : Runtime_builder.moderator_drain =
               { moderator_snapshot = t.state.moderator
               ; runtime_requests = []
               ; notifications = []
               ; remaining_events = false
               }
             in
             let%bind eligible = eligible_pending t Idle_start in
             let adopt_deferred =
               Option.is_none goal_runtime_scope && not (List.is_empty eligible)
             in
             let needs_turn =
               adopt_deferred
               || (not (List.is_empty notification_wakes))
               ||
               match goal_runtime_scope, follow_up.action with
               | None, Turn -> true
               | (Some _ | None), (Stop _ | Compact | Checkpoint | Turn) -> false
             in
             let%map () =
               match needs_turn, t.operation_worker with
               | false, _ ->
                 transition
                   t
                   ~delta:(Session_delta.Batch extra_deltas)
                   ~payloads:extra_payloads
                 |> Result.map ~f:ignore
               | true, None ->
                 Error
                   (error Invalid_state "notification wake requires an installed worker")
               | true, Some _ ->
                 start_idle_turn
                   ?idle_capture
                   ?goal_runtime_scope
                   ~extra_deltas
                   ~extra_payloads
                   ~notification_wakes
                   t
                   drain
                   ~reason:Idle_followup
                   ~adopt_deferred
             in
             true)))
;;

let admit_goal_subscription_selection
      ?origin_observation
      t
      (selected : Inherited_turn.Goal_subscription_selection.t)
      ~capture
  =
  let open Result.Let_syntax in
  let%bind () = check_goal_subscription_selection t selected in
  let%bind () =
    Inherited_turn.Capture.retain_goal_subscription_selection capture selected
  in
  let%bind requirement = checked_turn_requirement ?origin_observation t in
  match requirement with
  | Ordinary ->
    (* The actual native ordinary installer now owns this exact Turn custody,
       including its attempted writer; capture cancellation cannot retire it. *)
    let%bind () =
      Inherited_turn.Capture.take_goal_subscription_selection capture selected
    in
    let%map () =
      install_idle_turn_selection ~goal_runtime_scope:selected.scope t selected.turn
    in
    Inherited_turn.Decision.Completed true
  | Need_private_origin ->
    capture_turn_origin
      t
      ~capture
      ~input:(Inherited_turn.Input.Goal_subscription_selected selected)
  | Scoped ->
    capture_inherited_turn_plan
      t
      ~capture
      ~source:(Inherited_turn.Source.Goal_subscription selected)
      ~commit_attempted:(ref false)
      ~delta:(Session_delta.Batch selected.turn.deltas)
      ~payloads:selected.turn.payloads
;;

let submit_goal_subscription_input t execution proposal ~capture =
  let open Result.Let_syntax in
  (* Check the actual Actor/domain native owner before touching the private
     capture. A cancelled queued request cannot start even metadata-only work. *)
  let%bind _ = select_goal_runtime t execution in
  let%bind () = Inherited_turn.Capture.check_waiting capture in
  let sink = Idle_turn.Capture.create () in
  let%bind reply =
    deliver_idle_notifications_internal
      ~idle_capture:sink
      ~goal_execution:execution
      t
      proposal
  in
  match sink.selected with
  | None -> Ok (Inherited_turn.Decision.Completed reply)
  | Some (Ordinary _) ->
    Error (error Invalid_state "Goal subscription selected an ordinary idle Turn")
  | Some (Goal_subscription { turn; scope }) ->
    let captured = ref false in
    Exn.protect
      ~finally:(fun () ->
        if not !captured then Option.iter turn.custody ~f:retire_agent_custody)
      ~f:(fun () ->
        let%bind run = goal_runtime_run t scope in
        let%bind wake = Goal_execution_runtime.wake scope.continuation in
        let%bind original =
          Result.of_option
            (Run_admission.Scope.original_actor
               (Run_authorities.scope scope.continuation.binding.preparation.binding))
            ~error:(error Permission_denied "Goal subscription lost its genuine original")
        in
        let selected : Inherited_turn.Goal_subscription_selection.t =
          { scope; run; wake; turn; original }
        in
        let%bind () =
          Inherited_turn.Capture.retain_goal_subscription_selection capture selected
        in
        captured := true;
        admit_goal_subscription_selection t selected ~capture)
;;

let apply_observation_follow_up ?idle_capture t =
  if not (idle_actor_available t)
  then Ok false
  else
    let open Result.Let_syntax in
    let%bind observer = Runtime_builder.moderator_snapshot_observer t.state.moderator in
    let%bind halted = Runtime_builder.moderator_snapshot_is_halted t.state.moderator in
    let compaction = create_compaction_operation t in
    let%bind plan =
      Observation_follow_up.plan
        ~state:t.state
        ~observer
        ~halted
        ~compaction_operation_id:compaction.id
    in
    let%bind authority = plan_agent_custody t plan in
    let continuation_custody = authority.Follow_up_authority.custody in
    let follow_up_authority = Option.map authority.observations ~f:(fun _ -> authority) in
    let extra_deltas = follow_up_deltas t plan in
    let drain : Runtime_builder.moderator_drain =
      { moderator_snapshot = t.state.moderator
      ; runtime_requests = []
      ; notifications = []
      ; remaining_events = false
      }
    in
    let%bind eligible = eligible_pending t Idle_start in
    let resume_deferred = (not halted) && not (List.is_empty eligible) in
    let%map () =
      match plan.action, extra_deltas with
      | Checkpoint, _ when resume_deferred && Option.is_none t.operation_worker ->
        Error (error Invalid_state "deferred user turn requires an installed worker")
      | Checkpoint, _ when resume_deferred ->
        (* Queued/background callbacks can defer a user submission without
           requesting a moderator turn. Resume it once the callback releases
           its borrow; no notification or later event should be required. *)
        start_idle_turn
          ?idle_capture
          ~extra_deltas
          t
          drain
          ~reason:User_submit
          ~adopt_deferred:true
      | Checkpoint, [] -> Ok ()
      | Checkpoint, _ ->
        transition t ~delta:(Session_delta.Batch extra_deltas) ~payloads:[]
        |> Result.map ~f:ignore
      | Stop reason, _ -> stop_from_idle_moderator ~extra_deltas t drain reason
      | Compact, _ ->
        start_compaction
          ?agent_custody:continuation_custody
          ?follow_up_authority
          ~operation:compaction
          ~extra_deltas
          t
        |> Result.map ~f:ignore
      | Turn, _ when Option.is_none t.operation_worker ->
        Error (error Invalid_state "follow-up turn requires an installed worker")
      | Turn, _ ->
        start_idle_turn
          ?idle_capture
          ?continuation_custody
          ?follow_up_authority
          ~extra_deltas
          t
          drain
          ~reason:Moderator_request
          ~adopt_deferred:(not (List.is_empty eligible))
    in
    resume_deferred || not (List.is_empty extra_deltas)
;;

let checkpoint_idle_moderator ?idle_completion t (drain : Runtime_builder.moderator_drain)
  =
  transition
    ?idle_completion_step:
      (Option.map idle_completion ~f:(fun completion ->
         completion, Idle_completion_write.Kind.Checkpoint))
    t
    ~delta:(Session_delta.Moderator_changed drain.Runtime_builder.moderator_snapshot)
    ~payloads:(drain_payloads drain)
  |> Result.map ~f:(fun _ -> ())
;;

let complete_running_idle_moderator
      ?idle_completion
      ?idle_capture
      t
      (drain : Runtime_builder.moderator_drain)
  =
  let open Result.Let_syntax in
  let requests = drain.Runtime_builder.runtime_requests in
  let%bind eligible = eligible_pending t Idle_start in
  Option.iter idle_completion ~f:(fun completion ->
    completion.Idle_completion_data.action
    <- Some
         (match eligible with
          | _ :: _ -> Turn
          | [] when Chat_response.Runtime_semantics.request_compaction requests ->
            Compaction
          | [] when Chat_response.Runtime_semantics.request_turn requests -> Turn
          | [] -> Checkpoint));
  match eligible with
  | _ :: _ ->
    start_idle_turn
      ?idle_completion
      ?idle_capture
      t
      drain
      ~reason:User_submit
      ~adopt_deferred:true
  | [] when Chat_response.Runtime_semantics.request_compaction requests ->
    let open Result.Let_syntax in
    let%bind () = checkpoint_idle_moderator ?idle_completion t drain in
    Result.map (start_compaction ?idle_completion t) ~f:(fun _ -> ())
  | [] when Chat_response.Runtime_semantics.request_turn requests ->
    start_idle_turn
      ?idle_capture
      ?idle_completion
      t
      drain
      ~reason:Moderator_request
      ~adopt_deferred:false
  | [] -> checkpoint_idle_moderator ?idle_completion t drain
;;

let complete_idle_moderator t (drain : Runtime_builder.moderator_drain) =
  if
    Option.is_some t.idle_completion
    || (not t.idle_moderator_borrowed)
    || moderator_is_borrowed t
  then Error (error Conflict "session moderator is not borrowed for idle work")
  else (
    let result =
      match Chat_response.Runtime_semantics.should_end_session drain.runtime_requests with
      | Some reason -> stop_from_idle_moderator t drain reason
      | None
        when runtime_admission_open t
             && Agent_protocol.Session.equal_desired_state
                  t.state.lifecycle.desired
                  Running -> complete_running_idle_moderator t drain
      | None -> checkpoint_idle_moderator t drain
    in
    t.idle_moderator_borrowed <- false;
    result)
;;

let fail_idle_moderator t failure =
  if Option.is_some t.idle_completion || moderator_is_borrowed t
  then Error (error Conflict "observation callback owns the idle moderator")
  else (
    t.idle_moderator_borrowed <- false;
    let lifecycle =
      Session_state.Lifecycle.
        { desired = t.state.lifecycle.desired
        ; observed = Agent_protocol.Session.Failed failure
        }
    in
    transition
      t
      ~delta:
        (Session_delta.Batch
           [ Failure_changed (Some failure); Lifecycle_changed lifecycle ])
      ~payloads:
        [ Agent_protocol.Event.Durable.Payload.Session_state_changed
            { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
        ]
    |> Result.map ~f:(fun _ -> ()))
;;

let claim_paired_idle_completion t (completion : Idle_completion_data.t) =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_identity t completion in
  let%bind () =
    match
      completion.phase, completion.cancellation, Eio.Promise.peek completion.exited
    with
    | Fresh, None, None -> Ok ()
    | (Fresh | Claimed _ | Completing _ | Retired), _, _ ->
      Error (error Conflict "legacy capture is already closed or claimed")
  in
  let%bind source = Runtime_builder.moderator_snapshot_observer t.state.moderator in
  let basis : Idle_completion_data.basis =
    { generation = t.state.identity.generation; source; worker = t.operation_worker }
  in
  let slot = Some completion in
  let%map history = claim_idle_moderator t in
  match history with
  | None -> None
  | Some _ ->
    completion.phase <- Claimed basis;
    t.idle_completion <- slot;
    history
;;

let remember_idle_completion_result t (completion : Idle_completion_data.t) result =
  completion.Idle_completion_data.outcome <- Some result;
  (match result with
   | Ok () -> ()
   | Error failure ->
     Option.iter completion.write ~f:(fun write ->
       Idle_completion_write.retain_failure write failure);
     Idle_completion_data.request_cancellation completion failure);
  let released = release_idle_completion t completion in
  match result, released with
  | Ok (), Ok () -> Ok ()
  | Error failure, (Ok () | Error _) -> Error failure
  | Ok (), Error failure ->
    Idle_completion_data.request_cancellation completion failure;
    completion.outcome <- Some (Error failure);
    Error failure
;;

let capture_paired_idle_completion
      t
      (completion : Idle_completion_data.t)
      (drain : Runtime_builder.moderator_drain)
  =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_owner t completion in
  let%bind basis =
    match completion.phase with
    | Claimed basis -> Ok basis
    | Fresh | Completing _ | Retired ->
      Error (error Conflict "legacy callback result was already captured")
  in
  completion.phase <- Completing basis;
  completion.drain <- Some drain;
  let sink = Idle_turn.Capture.create () in
  match
    let result =
      match Chat_response.Runtime_semantics.should_end_session drain.runtime_requests with
      | Some reason ->
        completion.action <- Some Stop;
        stop_from_idle_moderator ~idle_completion:completion t drain reason
      | None
        when runtime_admission_open t
             && Agent_protocol.Session.equal_desired_state
                  t.state.lifecycle.desired
                  Running ->
        complete_running_idle_moderator
          ~idle_completion:completion
          ~idle_capture:sink
          t
          drain
      | None ->
        completion.action <- Some Checkpoint;
        checkpoint_idle_moderator ~idle_completion:completion t drain
    in
    match result, sink.selected with
    | Error _, (None | Some _) | Ok (), None ->
      remember_idle_completion_result t completion result
    | Ok (), Some (Goal_subscription _) ->
      Error (error Invalid_state "legacy completion selected a native Goal Turn")
    | Ok (), Some (Ordinary turn) ->
      let%bind () =
        match t.idle_turn_continuation with
        | None -> Ok ()
        | Some _ ->
          Error (error Conflict "legacy Turn already has a selected continuation")
      in
      let source =
        Idle_source.Legacy_completion
          { selection = { turn; reply = () }; owner = completion }
      in
      t.idle_turn_continuation
      <- Some
           { Idle_continuation.owner = completion
           ; phase = Selected (Idle_source.Selected.create source)
           ; finish = Not_started
           };
      Ok ()
  with
  | result -> result
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    Option.iter completion.write ~f:(fun write ->
      Idle_completion_write.retain_exception write exn backtrace);
    Idle_completion_data.request_cancellation
      completion
      (error Interrupted "legacy completion raised before its handoff");
    Exn.raise_with_original_backtrace exn backtrace
;;

let fail_paired_idle_completion t (completion : Idle_completion_data.t) failure =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_owner t completion in
  let%bind basis =
    match completion.phase with
    | Claimed basis -> Ok basis
    | Fresh | Completing _ | Retired ->
      Error (error Conflict "legacy callback failure followed capture")
  in
  completion.phase <- Completing basis;
  completion.action <- Some Callback_failure;
  let lifecycle =
    Session_state.Lifecycle.
      { desired = t.state.lifecycle.desired; observed = Failed failure }
  in
  let result =
    transition
      ~idle_completion_step:(completion, Idle_completion_write.Kind.Callback_failure)
      t
      ~delta:
        (Session_delta.Batch
           [ Failure_changed (Some failure); Lifecycle_changed lifecycle ])
      ~payloads:
        [ Agent_protocol.Event.Durable.Payload.Session_state_changed
            { desired_state = lifecycle.desired; observed_state = lifecycle.observed }
        ]
    |> Result.map ~f:ignore
  in
  completion.outcome <- Some (Error failure);
  match result with
  | Ok () -> release_idle_completion t completion
  | Error diagnostic ->
    Option.iter completion.write ~f:(fun write ->
      Idle_completion_write.retain_failure write diagnostic);
    Idle_completion_data.request_cancellation completion failure;
    Error diagnostic
;;

let idle_operation_matches suffix (actual : Agent_protocol.Operation.t) =
  Agent_protocol.Id.Operation.equal suffix.Idle_completion_data.operation.id actual.id
  && Int.equal suffix.operation.generation actual.generation
  && Agent_protocol.Operation.equal_kind suffix.operation.kind actual.kind
;;

let retire_paired_idle_completion t (completion : Idle_completion_data.t) =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_identity t completion in
  match completion.phase with
  | Fresh | Retired -> Ok ()
  | Claimed _ | Completing _ ->
    let%bind () = check_idle_completion_owner t completion in
    let%bind () =
      match Eio.Promise.peek completion.exited with
      | Some () -> Ok ()
      | None -> Error (error Conflict "legacy callback has not left its actual capture")
    in
    let%bind () =
      match completion.write with
      | Some write ->
        (match Idle_completion_write.phase write with
         | Attempted -> Error (idle_completion_failure completion)
         | Installed _ | Not_attempted -> Ok ())
      | None -> Ok ()
    in
    let%bind () =
      match completion.suffix with
      | None -> Ok ()
      | Some (Stop (jobs, permissions)) ->
        (match completion.write with
         | Some write ->
           (match Idle_completion_write.phase write with
            | Installed _ ->
              cancel_job_scopes t jobs;
              resolve_cleaned_permission_waiters t permissions;
              completion.suffix <- None;
              Ok ()
            | Not_attempted ->
              completion.suffix <- None;
              Ok ()
            | Attempted -> Error (idle_completion_failure completion))
         | None ->
           completion.suffix <- None;
           Ok ())
      | Some (Operation suffix) ->
        (match suffix.phase with
         | Prepared | Handed_off | Terminated -> Ok ()
         | Terminal_acknowledged -> Error (idle_completion_failure completion)
         | Acknowledged ->
           let%bind () =
             match suffix.native_write with
             | Some write ->
               (match Idle_completion_write.phase write with
                | Installed acknowledgement ->
                  (match
                     Idle_completion_write.Acknowledgement.selected acknowledgement
                   with
                   | Requested (Start_ordinary_turn | Start_compaction) -> Ok ()
                   | Requested _ | Admission_hold _ ->
                     Error (error Conflict "legacy operation lacks its actual native ACK"))
                | Attempted | Not_attempted ->
                  Error (error Conflict "legacy operation writer is not acknowledged"))
             | None ->
               Error (error Conflict "legacy operation has no actual writer owner")
           in
           let%bind () =
             match t.state.active_operation, t.operation_agent_custody with
             | Some actual, Some owner
               when idle_operation_matches suffix actual && phys_equal suffix.owner owner
               -> Ok ()
             | _ ->
               Error
                 (error
                    Conflict
                    "legacy operation retirement lost its exact acknowledged owner")
           in
           let failure =
             Option.value
               completion.cancellation
               ~default:(error Interrupted "legacy completion source retired")
           in
           let%bind () =
             match
               with_runtime_terminal t suffix.operation.id (fun () ->
                 match suffix.kind with
                 | Turn _ ->
                   worker_terminal
                     ~idle_completion:completion
                     t
                     suffix.operation.id
                     (Failed failure)
                     None
                 | Compaction _ ->
                   compaction_terminal
                     ~idle_completion:completion
                     t
                     suffix.operation.id
                     (Compaction_cancelled failure.message))
             with
             | Ok () -> Ok ()
             | Error diagnostic ->
               Option.iter completion.write ~f:(fun write ->
                 Idle_completion_write.retain_failure write diagnostic);
               Error diagnostic
             | exception exn ->
               let backtrace = Stdlib.Printexc.get_raw_backtrace () in
               Option.iter completion.write ~f:(fun write ->
                 Idle_completion_write.retain_exception write exn backtrace);
               Exn.raise_with_original_backtrace exn backtrace
           in
           (match suffix.phase with
            | Terminal_acknowledged ->
              suffix.phase <- Terminated;
              Ok ()
            | Prepared | Acknowledged | Handed_off | Terminated ->
              Error (error Conflict "legacy operation terminal has no actual State ACK")))
    in
    release_idle_completion t completion
;;

let retire_idle_turn_continuation t owner continuation =
  let open Result.Let_syntax in
  let%bind actual = read_idle_turn_continuation t owner in
  let%bind () =
    match continuation, actual with
    | Inherited_turn.Idle_retirement.Ordinary, Ordinary ->
      retire_paired_idle_completion t owner
    | Selected expected, Selected actual when phys_equal expected actual ->
      Idle_source.Selected.retire actual;
      (* A historical ordinary resume may already own a real metadata/operation
         writer. Its existing attempted/ACK retirement remains authoritative. *)
      retire_paired_idle_completion t owner
    | Bound expected, Bound actual when phys_equal expected actual ->
      let%bind () =
        match actual.phase with
        | Closed ->
          (match actual.slot.phase with
           | Released _ -> Ok ()
           | Active | Sealed _ | Acknowledged _ ->
             Error
               (error Conflict "legacy Turn root close acknowledgements remain pending"))
        | Acknowledged acknowledged ->
          (match acknowledged.cleanup_progress with
           | Done -> Ok ()
           | Needs_both | Terminal_done | Confirmed _ ->
             Error (error Conflict "legacy Turn factual cleanup remains pending"))
        | Pending | Writer_prepared _ ->
          Error (error Conflict "legacy Turn has no positive retirement fact")
      in
      release_idle_completion t owner
    | (Ordinary | Selected _ | Bound _), (Ordinary | Selected _ | Bound _) ->
      Error (error Conflict "legacy Turn retirement continuation changed")
  in
  (match continuation with
   | Ordinary -> ()
   | Selected _ | Bound _ ->
     if Option.is_none owner.Idle_completion_data.outcome
     then
       owner.outcome
       <- Some
            (Error
               (Option.value
                  owner.cancellation
                  ~default:(error Interrupted "legacy Turn source was retired")));
     t.idle_turn_continuation <- None);
  Ok ()
;;

let admit_selected_idle_turn
  : type outcome.
    ?origin_observation:Descendant_origin_observation.Observed.t
    -> ?cleanup_ready:bool
    -> t
    -> outcome Idle_source.Selected.t
    -> capture:outcome Inherited_turn.Capture.t
    -> (outcome Inherited_turn.Decision.t, Agent_protocol.Error.t) result
  =
  fun ?origin_observation ?(cleanup_ready = false) t selected ~capture ->
  let open Result.Let_syntax in
  let source = selected.Idle_source.Selected.source in
  let%bind () = Inherited_turn.Capture.retain_idle_selection capture selected in
  let%bind () = check_idle_turn_selection t source in
  let%bind requirement = checked_turn_requirement ?origin_observation t in
  match requirement with
  | Need_private_origin ->
    capture_turn_origin t ~capture ~input:(Inherited_turn.Input.Idle_selected selected)
  | Ordinary ->
    selected.ownership <- Ordinary_consumed;
    let result =
      install_idle_turn_selection
        ?idle_completion:(Idle_source.legacy_owner source)
        t
        (Idle_source.turn source)
    in
    let%map () =
      match source with
      | Notifications _ | Follow_up _ -> result
      | Legacy_completion source ->
        let result = remember_idle_completion_result t source.owner result in
        if Result.is_ok result then t.idle_turn_continuation <- None;
        result
    in
    Inherited_turn.Decision.Completed (Idle_source.reply source)
  | Scoped ->
    (match require_available_descendant_admission_slot t with
     | Error _ when not cleanup_ready ->
       Ok (Inherited_turn.Decision.Need_idle_cleanup selected)
     | Error failure -> Error failure
     | Ok () ->
       let turn = Idle_source.turn source in
       let%map decision =
         capture_inherited_turn_plan
           t
           ~capture
           ~source:(Idle source)
           ~commit_attempted:(ref false)
           ~delta:(Session_delta.Batch turn.deltas)
           ~payloads:turn.payloads
       in
       selected.ownership <- Bound;
       decision)
;;

let submit_idle_input
  : type outcome.
    t
    -> outcome Idle_input.t
    -> capture:outcome Inherited_turn.Capture.t
    -> (outcome Inherited_turn.Decision.t, Agent_protocol.Error.t) result
  =
  fun t input ~capture ->
  let open Result.Let_syntax in
  let sink = Idle_turn.Capture.create () in
  let result : (outcome, Agent_protocol.Error.t) result =
    match input with
    | Notifications proposal ->
      deliver_idle_notifications_internal ~idle_capture:sink t proposal
    | Follow_up -> apply_observation_follow_up ~idle_capture:sink t
  in
  let%bind reply = result in
  match sink.selected with
  | None -> Ok (Inherited_turn.Decision.Completed reply)
  | Some (Goal_subscription _) ->
    Error (error Invalid_state "ordinary idle input selected a native Goal Turn")
  | Some (Ordinary turn) ->
    let source : outcome Idle_source.t =
      match input with
      | Notifications _ -> Notifications { turn; reply }
      | Follow_up -> Follow_up { turn; reply }
    in
    let selected = Idle_source.Selected.create source in
    let retained = ref false in
    Exn.protect
      ~finally:(fun () -> if not !retained then Idle_source.Selected.retire selected)
      ~f:(fun () ->
        let%map decision = admit_selected_idle_turn t selected ~capture in
        retained := true;
        decision)
;;

let submit_observed_turn_origin
  : type outcome.
    t
    -> outcome Inherited_turn.Origin_observation.t
    -> (outcome Inherited_turn.Decision.t, Agent_protocol.Error.t) result
  =
  fun t observed ->
  let open Result.Let_syntax in
  let captured = observed.captured in
  let%bind () = Inherited_turn.Capture.check_waiting captured.capture in
  let%bind () = check_descendant_origin_observation t observed.origin in
  t.command_audit <- captured.remaining_audit;
  ((match captured.input with
    | Message input ->
      let%bind () =
        check_message_authentication
          input.original_actor
          ~submitting_principal:input.submitting_principal
      in
      let%bind _ = write_attachment t input.attachment_id in
      let%bind () = require_submit_ready t in
      let%map result =
        submit_authorized_message
          ?original_actor:input.original_actor
          ~owner:(Submitting_principal input.submitting_principal)
          ~timing:input.timing
          t
          input.entry
      in
      Inherited_turn.Decision.Completed result
    | Held_input_selected selected ->
      let%bind () = check_selected_held_input t selected in
      admit_held_input_selection
        ~origin_observation:observed.origin
        t
        selected
        ~capture:captured.capture
    | Goal_resume_selected selected ->
      admit_goal_resume_selection
        ~origin_observation:observed.origin
        t
        selected
        ~capture:captured.capture
    | Goal_subscription_selected selected ->
      admit_goal_subscription_selection
        ~origin_observation:observed.origin
        t
        selected
        ~capture:captured.capture
    | Idle_selected selected ->
      admit_selected_idle_turn
        ~origin_observation:observed.origin
        t
        selected
        ~capture:captured.capture
    | Idle _ ->
      Error (error Invalid_state "internal idle origin continuation has unselected input")
    | Goal_resume _ | Goal_subscription _ ->
      Error (error Invalid_state "internal Goal origin continuation has unselected input")
    | Held_input _ ->
      Error (error Invalid_state "internal held origin continuation has unselected input")
    | History input ->
      admit_history_input
        ~origin_observation:observed.origin
        t
        input
        ~capture:captured.capture
    | Edit_history _ | Continue_history _ ->
      Error
        (error Invalid_state "internal history origin continuation has unprepared input")
    | Managed input ->
      submit_managed_message
        ~origin_observation:observed.origin
        t
        input
        ~capture:captured.capture
    | Run_user (input, Receipt) ->
      admit_run
        ~origin_observation:observed.origin
        t
        input
        ~reply:Receipt
        ~capture:captured.capture
    | Run_user (input, Prepared_outcome) ->
      admit_prepared_run
        ~origin_observation:observed.origin
        t
        input
        ~capture:captured.capture)
   : (outcome Inherited_turn.Decision.t, Agent_protocol.Error.t) result)
;;

let handle_idle_completion_request
  : type outcome.
    t
    -> outcome Idle_completion_data.Request.t
    -> (outcome, Agent_protocol.Error.t) result
  =
  fun t request ->
  match request with
  | Claim -> claim_idle_moderator t
  | Complete drain -> complete_idle_moderator t drain
  | Fail failure -> fail_idle_moderator t failure
  | Claim_paired completion -> claim_paired_idle_completion t completion
  | Capture_paired (completion, drain) ->
    capture_paired_idle_completion t completion drain
  | Fail_paired (completion, failure) -> fail_paired_idle_completion t completion failure
  | Retire_paired completion -> retire_paired_idle_completion t completion
;;

let lease_generation t = Int64.(t.state.counters.owner_lease_generation + 1L)

let reclaim_token_sha256 token =
  Digestif.SHA256.digest_string token |> Digestif.SHA256.to_hex
;;

let reclaim_token_matches lease token =
  match lease.Agent_protocol.Session.Owner_lease.reclaim_token_sha256 with
  | None -> false
  | Some expected ->
    Option.value_map
      (Digestif.SHA256.of_hex_opt expected)
      ~default:false
      ~f:(fun expected ->
        Digestif.SHA256.equal expected (Digestif.SHA256.digest_string token))
;;

let owner_principal_matches t lease principal_id =
  let expected =
    Option.first_some
      lease.Agent_protocol.Session.Owner_lease.principal_id
      t.state.identity.creating_principal
  in
  Option.both expected principal_id
  |> Option.exists ~f:(fun (expected, actual) ->
    Agent_protocol.Id.Principal.compare expected actual = 0)
;;

let owner_lease t generation ~principal_id ~reclaim_token =
  match t.state.spec.protocol.liveness with
  | Agent_protocol.Session.Owner_bound _ ->
    let now = t.services.now () |> Agent_protocol.Timestamp.to_time_ns in
    let span = Time_ns.Span.of_ms (Float.of_int t.owner_lease_duration_ms) in
    let expires_at = Time_ns.add now span |> Agent_protocol.Timestamp.of_time_ns in
    Some
      Agent_protocol.Session.Owner_lease.
        { generation
        ; expires_at
        ; disconnect_grace_until = None
        ; principal_id
        ; reclaim_token_sha256 = Option.map reclaim_token ~f:reclaim_token_sha256
        }
  | Detached | Process_bound -> None
;;

let owner_attachment t =
  List.find t.state.attachments ~f:(fun attachment ->
    Agent_protocol.Session.equal_attachment_mode attachment.mode Owner_read_write)
;;

let lease_deadline lease =
  Option.value
    lease.Agent_protocol.Session.Owner_lease.disconnect_grace_until
    ~default:lease.expires_at
;;

let schedule_owner_expiry_at t generation deadline =
  Option.iter t.owner_timer_cancel ~f:(fun resolver -> Eio.Promise.resolve resolver ());
  let cancelled, cancel = Eio.Promise.create () in
  t.owner_timer_cancel <- Some cancel;
  let now = t.services.now () |> Agent_protocol.Timestamp.to_time_ns in
  let deadline = Agent_protocol.Timestamp.to_time_ns deadline in
  let delay = Time_ns.diff deadline now |> Time_ns.Span.to_sec |> Float.max 0. in
  Eio.Fiber.fork ~sw:t.sw (fun () ->
    let expired =
      Eio.Fiber.first
        (fun () ->
           t.sleep delay;
           true)
        (fun () ->
           Eio.Promise.await cancelled;
           false)
    in
    if expired
    then (
      let promise, resolver = Eio.Promise.create () in
      let packed = Pack (None, Owner_expired generation, resolver) in
      match Mailbox.push t.mailbox ~priority:Priority packed with
      | Error _ -> ()
      | Ok () ->
        ignore (Actor_reply.await promise : (unit, Agent_protocol.Error.t) result)))
;;

let schedule_owner_lease t lease =
  schedule_owner_expiry_at
    t
    lease.Agent_protocol.Session.Owner_lease.generation
    (lease_deadline lease)
;;

let disconnect_grace_deadline t disconnect_grace_ms =
  let now = t.services.now () |> Agent_protocol.Timestamp.to_time_ns in
  Time_ns.add now (Time_ns.Span.of_ms (Float.of_int disconnect_grace_ms))
  |> Agent_protocol.Timestamp.of_time_ns
;;

let mark_owner_disconnected t attachment disconnect_grace_ms =
  let open Result.Let_syntax in
  let%bind lease =
    attachment.Agent_protocol.Session.Attachment.owner_lease
    |> Result.of_option ~error:(error Invalid_state "owner attachment has no lease")
  in
  let lease =
    let grace = disconnect_grace_deadline t disconnect_grace_ms in
    let disconnect_grace_until =
      if Agent_protocol.Timestamp.compare grace lease.expires_at <= 0
      then grace
      else lease.expires_at
    in
    { lease with disconnect_grace_until = Some disconnect_grace_until }
  in
  let attachment = { attachment with owner_lease = Some lease } in
  let%map _ =
    transition
      t
      ~delta:(Session_delta.Attachment_added attachment)
      ~payloads:[ Agent_protocol.Event.Durable.Payload.Attachment_owner_changed None ]
  in
  schedule_owner_lease t lease
;;

let owner_expired t generation =
  t.owner_timer_cancel <- None;
  match owner_attachment t with
  | None -> Ok ()
  | Some attachment ->
    (match attachment.owner_lease with
     | None -> Ok ()
     | Some lease when not (Int64.equal lease.generation generation) -> Ok ()
     | Some lease ->
       let now = t.services.now () in
       let deadline = lease_deadline lease in
       if Agent_protocol.Timestamp.compare deadline now > 0
       then (
         schedule_owner_expiry_at t generation deadline;
         Ok ())
       else (
         match lease.disconnect_grace_until, t.state.spec.protocol.liveness with
         | None, Owner_bound { disconnect_grace_ms; _ } ->
           mark_owner_disconnected t attachment disconnect_grace_ms
         | Some _, Owner_bound { stop_mode; _ } ->
           let open Result.Let_syntax in
           let%bind _ =
             transition
               t
               ~delta:(Session_delta.Attachment_removed attachment.id)
               ~payloads:
                 [ Agent_protocol.Event.Durable.Payload.Attachment_owner_changed None ]
           in
           Result.map (stop_internal t stop_mode) ~f:(fun _ -> ())
         | _, (Detached | Process_bound) -> Ok ()))
;;

let renew_owner t attachment_id expected_generation =
  let open Result.Let_syntax in
  let%bind attachment = write_attachment t attachment_id in
  match attachment.mode, attachment.owner_lease with
  | Owner_read_write, Some lease ->
    if not (Int64.equal lease.generation expected_generation)
    then Error (error Lease_stale "owner lease generation does not match")
    else if Option.is_some lease.disconnect_grace_until
    then Error (error Lease_stale "disconnected owner lease must be reclaimed")
    else if Agent_protocol.Timestamp.compare lease.expires_at (t.services.now ()) <= 0
    then Error (error Lease_stale "owner lease has expired")
    else (
      let generation = lease_generation t in
      let%bind owner_lease =
        owner_lease t generation ~principal_id:lease.principal_id ~reclaim_token:None
        |> Result.of_option ~error:(error Invalid_state "owner lease is unavailable")
      in
      let owner_lease =
        { owner_lease with reclaim_token_sha256 = lease.reclaim_token_sha256 }
      in
      let attachment = { attachment with owner_lease = Some owner_lease } in
      let%map session =
        transition
          t
          ~delta:
            (Session_delta.Batch
               [ Attachment_added attachment; Owner_lease_generation_changed generation ])
          ~payloads:
            [ Agent_protocol.Event.Durable.Payload.Attachment_owner_changed
                (Some attachment)
            ]
      in
      schedule_owner_lease t owner_lease;
      owner_lease, session)
  | Owner_read_write, None -> Error (error Invalid_state "owner attachment has no lease")
  | (Read_write | Read_only), _ ->
    Error (error Permission_denied "attachment does not own the session")
;;

let owner_reclaim_authorized t lease ~principal_id ~reclaim_token =
  owner_principal_matches t lease principal_id
  || Option.exists reclaim_token ~f:(reclaim_token_matches lease)
;;

let install_subscriber t attachment_id subscribe =
  let subscriber =
    Option.some_if subscribe (Subscriber.create ~capacity:t.subscriber_capacity)
  in
  Option.iter subscriber ~f:(fun value ->
    Eio.Mutex.use_rw ~protect:true t.subscriber_mutex (fun () ->
      t.subscribers := Map.set !(t.subscribers) ~key:attachment_id ~data:value));
  subscriber
;;

let validate_attachment_capacity t ~replacing =
  if replacing || List.length t.state.attachments < t.max_attachments
  then Ok ()
  else Error (error Resource_limit "session attachment limit reached")
;;

let attach_owner t subscribe ~principal_id ~reclaim_token =
  let open Result.Let_syntax in
  let%bind () =
    match owner_attachment t with
    | Some { owner_lease = Some lease; _ }
      when Agent_protocol.Timestamp.compare (lease_deadline lease) (t.services.now ())
           <= 0 -> owner_expired t lease.generation
    | _ -> Ok ()
  in
  let previous = owner_attachment t in
  let%bind () = validate_attachment_capacity t ~replacing:(Option.is_some previous) in
  let%bind () =
    match previous with
    | None -> Ok ()
    | Some { owner_lease = None; _ } ->
      Error (error Conflict "session already has an owner attachment")
    | Some { owner_lease = Some lease; _ } ->
      (match lease.disconnect_grace_until with
       | None -> Error (error Conflict "session already has an active owner attachment")
       | Some _ ->
         if owner_reclaim_authorized t lease ~principal_id ~reclaim_token
         then Ok ()
         else Error (error Permission_denied "owner reclaim credential is invalid"))
  in
  let issued_reclaim_token = t.services.create_reclaim_token () in
  let%bind () =
    if String.is_empty issued_reclaim_token
    then
      Error (error Invalid_state "owner reclaim token generator returned an empty token")
    else Ok ()
  in
  let generation = lease_generation t in
  let%bind lease =
    owner_lease t generation ~principal_id ~reclaim_token:(Some issued_reclaim_token)
    |> Result.of_option ~error:(error Invalid_state "owner lease is unavailable")
  in
  let attachment_id = t.services.create_attachment_id () in
  let attachment =
    Agent_protocol.Session.Attachment.
      { id = attachment_id
      ; session_id = t.state.identity.session_id
      ; mode = Owner_read_write
      ; owner_lease = Some lease
      }
  in
  let deltas =
    Option.to_list
      (Option.map previous ~f:(fun previous ->
         Session_delta.Attachment_removed previous.id))
    @ [ Session_delta.Attachment_added attachment
      ; Session_delta.Owner_lease_generation_changed generation
      ]
  in
  let%bind _ =
    transition
      t
      ~delta:(Session_delta.Batch deltas)
      ~payloads:
        [ Agent_protocol.Event.Durable.Payload.Attachment_owner_changed (Some attachment)
        ]
  in
  schedule_owner_lease t lease;
  let subscriber = install_subscriber t attachment_id subscribe in
  Ok (attachment, subscriber, current_snapshot t, Some issued_reclaim_token)
;;

(* Nonowner membership changes preserve only an already installed startup's
   factual preparation. They do not borrow or renew its original authority;
   owner-control changes and pre-activation source bindings keep ordinary
   preparation retirement. *)
let held_authored_attachment_scope t mode : Held_authored_start.t option =
  match mode with
  | Agent_protocol.Session.Owner_read_write -> None
  | Read_only | Read_write ->
    (match t.held_authored_start, t.run_source_binding with
     | Some scope, None ->
       Option.some_if
         (Result.is_ok (held_authored_basis t scope)
          && Option.is_some (held_authored_factual_preparation t scope))
         scope
     | None, _ | Some _, Some _ -> None)
;;

let attach_nonowner t mode subscribe =
  let open Result.Let_syntax in
  let%bind () = validate_attachment_capacity t ~replacing:false in
  let attachment_id = t.services.create_attachment_id () in
  let attachment =
    Agent_protocol.Session.Attachment.
      { id = attachment_id
      ; session_id = t.state.identity.session_id
      ; mode
      ; owner_lease = None
      }
  in
  let%bind _ =
    let delta = Session_delta.Attachment_added attachment in
    match held_authored_attachment_scope t mode with
    | Some scope -> install_held_authored_fact t scope ~delta ~payloads:[]
    | None -> transition t ~delta ~payloads:[]
  in
  let subscriber = install_subscriber t attachment_id subscribe in
  Ok (attachment, subscriber, current_snapshot t, None)
;;

let attach t mode subscribe principal_id reclaim_token =
  match mode, t.state.spec.protocol.liveness with
  | Agent_protocol.Session.Owner_read_write, Agent_protocol.Session.Owner_bound _ ->
    attach_owner t subscribe ~principal_id ~reclaim_token
  | Owner_read_write, (Detached | Process_bound) -> attach_nonowner t mode subscribe
  | (Read_write | Read_only), _ -> attach_nonowner t mode subscribe
;;

let detach t attachment_id =
  match
    List.find t.state.attachments ~f:(fun value ->
      Agent_protocol.Id.Attachment.compare value.id attachment_id = 0)
  with
  | None -> Error (error Invalid_request "attachment is not active")
  | Some attachment ->
    Eio.Mutex.use_rw ~protect:true t.subscriber_mutex (fun () ->
      Option.iter (Map.find !(t.subscribers) attachment_id) ~f:Subscriber.close;
      t.subscribers := Map.remove !(t.subscribers) attachment_id);
    (match attachment.mode, t.state.spec.protocol.liveness with
     | Owner_read_write, Owner_bound { disconnect_grace_ms; _ } ->
       mark_owner_disconnected t attachment disconnect_grace_ms
     | Owner_read_write, (Detached | Process_bound)
     | (Read_write | Read_only), (Detached | Process_bound | Owner_bound _) ->
       Result.map
         (let delta = Session_delta.Attachment_removed attachment_id in
          match held_authored_attachment_scope t attachment.mode with
          | Some scope -> install_held_authored_fact t scope ~delta ~payloads:[]
          | None -> transition t ~delta ~payloads:[])
         ~f:(fun _ -> ()))
;;

let enable_automatic_turn_budget ?check_before_commit ?run_preparation t policy =
  let open Result.Let_syntax in
  let%bind () =
    match run_preparation with
    | None -> Ok ()
    | Some preparation -> check_run_preparation t preparation
  in
  match
    t.state.automatic_turn_budget, t.state.active_operation, moderator_is_borrowed t
  with
  | Some budget, _, _
    when Chat_response.Runtime_semantics.equal_policy budget.policy policy -> Ok ()
  | _, None, false ->
    transition
      ?check_before_commit
      ?run_preparation
      t
      ~delta:(Session_delta.Automatic_turn_budget_enabled policy)
      ~payloads:[]
    |> Result.map ~f:ignore
  | _ ->
    Error (error Conflict "cannot enable automatic-turn accounting during active work")
;;

(* The terminal refresh is an execution grant, unlike import/close/correction.
   Both phases of an outside-mailbox observation retain this closed distinction. *)
let read_retirement_idle_continuation
      (t : t)
      (completion : Idle_completion_data.t)
      selected
  =
  let open Result.Let_syntax in
  let%bind () = check_idle_completion_identity t completion in
  match selected with
  | None -> Ok Inherited_turn.Idle_retirement.Ordinary
  | Some continuation ->
    if not (phys_equal continuation.Idle_continuation.owner completion)
    then Error (error Conflict "selected idle continuation belongs to another completion")
    else
      Ok
        (match continuation.phase with
         | Selected selected -> Inherited_turn.Idle_retirement.Selected selected
         | Bound plan -> Bound plan)
;;

let retire_retirement_idle_continuation
      (t : t)
      (completion : Idle_completion_data.t)
      selected
  =
  let open Result.Let_syntax in
  let%bind original = read_retirement_idle_continuation t completion selected in
  let%bind () =
    match t.idle_turn_continuation, selected with
    | Some actual, Some expected when phys_equal actual expected -> Ok ()
    | None, (Some _ | None) -> Ok ()
    | Some _, (Some _ | None) ->
      Error (error Conflict "selected idle continuation was displaced")
  in
  (* Current None is only an exclusion observation. The original container and
     its own factual close/ACK still have to prove completion. *)
  let%bind () =
    match original with
    | Ordinary -> retire_paired_idle_completion t completion
    | Selected selected ->
      Idle_source.Selected.retire selected;
      retire_paired_idle_completion t completion
    | Bound plan ->
      let%bind () =
        match plan.phase with
        | Closed ->
          (match plan.slot.phase with
           | Released _ -> Ok ()
           | Active | Sealed _ | Acknowledged _ ->
             Error (error Conflict "selected idle root close remains pending"))
        | Acknowledged acknowledged ->
          (match acknowledged.cleanup_progress with
           | Done -> Ok ()
           | Needs_both | Terminal_done | Confirmed _ ->
             Error (error Conflict "selected idle ACK cleanup remains pending"))
        | Pending | Writer_prepared _ ->
          Error (error Conflict "selected idle plan has no positive retirement fact")
      in
      release_idle_completion t completion
  in
  (match original with
   | Ordinary -> ()
   | Selected _ | Bound _ ->
     if Option.is_none completion.Idle_completion_data.outcome
     then
       completion.outcome
       <- Some
            (Error
               (Option.value
                  completion.cancellation
                  ~default:(error Interrupted "selected idle source was retired")));
     (match t.idle_turn_continuation, selected with
      | Some actual, Some expected when phys_equal actual expected ->
        t.idle_turn_continuation <- None
      | (Some _ | None), (Some _ | None) -> ()));
  Ok ()
;;

let runtime_retirement_cleanup_step
  : type a. t -> a runtime_retirement_cleanup_step -> (a, Agent_protocol.Error.t) result
  =
  fun t step ->
  match step with
  | Cleanup_constructor_call attempt ->
    let boundary () =
      match attempt.original_call.phase with
      | Joined _ | Abandoned -> Retirement_cleanup_completion.Boundary.Released
      | Admission_attempt _
      | Admitted _
      | Claim_attempt _
      | Claimed _
      | Selected _
      | Terminal_attempt _
      | Cancel_attempt _ -> Before_release
    in
    let record reply =
      if Option.is_none attempt.completion
      then attempt.completion <- Some { reply; boundary = boundary () }
    in
    (match Constructor_model.drain_call t attempt.original_call with
     | result ->
       record (Actor_reply.Returned result);
       result
     | exception exn ->
       let backtrace = Stdlib.Printexc.get_raw_backtrace () in
       record (Actor_reply.Raised (exn, backtrace));
       Exn.raise_with_original_backtrace exn backtrace)
  | Cleanup_ended_callback (borrow, exit) -> Callback_retirement.finish t borrow exit
  | Cleanup_seal_descendant slot -> seal_descendant_admission_slot t slot
  | Cleanup_read_idle (completion, selected) ->
    read_retirement_idle_continuation t completion selected
  | Cleanup_retire_idle (completion, selected) ->
    retire_retirement_idle_continuation t completion selected
;;

let causal_terminal_lifecycle_allowed : type a. a causal_terminal_operation -> bool =
  function
  | Import_causal_usage _ | Close_causal_pending _ | Prepare_causal_correction _ -> true
  | Refresh_causal_admitted _ -> false
;;

let causal_route_lifecycle_allowed : type a. a causal_route_request -> bool = function
  | Capture_causal_terminal operation -> causal_terminal_lifecycle_allowed operation
  | Consume_causal_terminal observed ->
    causal_terminal_lifecycle_allowed observed.terminal_capture.terminal_operation
  | Capture_causal_usage _
  | Consume_causal_usage _
  | Commit_causal_correction _
  | Reconcile_causal_correction _
  | Retained_causal_correction _
  | Abandon_causal_correction _
  | Reconcile_causal_import _ -> true
  | Capture_causal_routes _
  | Consume_causal_routes _
  | Capture_causal_root _
  | Consume_causal_root _
  | Capture_causal_reservation _
  | Consume_causal_reservation _ -> false
;;

let lifecycle_request_allowed : type a. a request -> bool = function
  | Policy_restoration (End _ | End_native _) -> true
  | Policy_restoration
      ( Begin _
      | Publish _
      | Reserve_history _
      | Open_graph _
      | Begin_native _
      | Open_native_graph _ ) -> false
  | Constructor_model (Complete _ | Interrupt _ | Drain) -> true
  | Constructor_model (Admit _ | Claim _) -> false
  | Idle_completion request ->
    (match request with
     | Claim | Claim_paired _ -> false
     | Complete _ | Fail _ | Capture_paired _ | Fail_paired _ | Retire_paired _ -> true)
  | Inherited_turn request -> Inherited_turn.Request.lifecycle_allowed request
  | Descendant_root request -> Descendant_root_request.lifecycle_allowed request
  | Causal_route request -> causal_route_lifecycle_allowed request
  | Native_goal (Close_scope _ | Rollback _ | Finish_start_dispatch _) -> true
  | Native_goal
      ( Start_receipt _
      | Start_status _
      | Select_action
      | Begin_start _
      | Observe_start_dispatch _
      | Stage_start _
      | Resume_receipt _
      | Resume_status _
      | Select_resume
      | Begin_resume _
      | Observe_dispatch _
      | Stage_create _
      | Stage_control _
      | Stage_edit _
      | Stage_resume _
      | Read _
      | Install_scope _
      | Deliverable _
      | Accept _
      | Prepare _ ) -> false
  | Set_operation_worker None
  | Set_runtime_worker (_, _, None, _, _, _, _)
  | Set_compaction_inference None -> true
  | Set_operation_worker (Some _)
  | Set_runtime_worker (_, _, Some _, _, _, _, _)
  | Set_compaction_inference (Some _) -> false
  | Acknowledge_inference _
  | Observe_inference _
  | Observe_owned_inference _
  | Complete_inference _
  | Release_inference _
  | Inherited_inference (Release _ | Confirm _ | Seal _ | Retire_closed _)
  | Capture_inference_usage _
  | Check_inference_usage _
  | Finalize_inference_usage
  | Clear_finished_inference_owner _
  | Seal_inference_owner _
  | Finish_inference_owner _
  | Close_run_preparation _
  | Held_startup (Effect_deferred (Exclude | Close _))
  | Held_startup
      (Input_graph
         ( Acknowledge _
         | Observe _
         | Observe_owned _
         | Complete _
         | Release _
         | Seal _
         | Finish _
         | Clear_finished _ ))
  | Held_startup
      (Construction
         (Mutate
            ( Acknowledge _
            | Observe _
            | Observe_owned _
            | Complete _
            | Release _
            | Seal _
            | Finish _
            | Clear_finished _ )))
  | Held_startup (Close_input _)
  | Held_startup (End_held_activation _)
  | Held_startup (Construction (End _ | Finish_resume _ | Load (End _)))
  | Release_recurrence_due _ | Run_start_receipt _
