let handle_child_accounting_request
  : type a. t -> a Child_accounting_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  match request with
  | Prepare_native_origin (source_owner, admission, binding, ancestry) ->
    prepare_native_child_origin_internal t ~source_owner ~admission ~binding ~ancestry
  | Prepare_unrelated_origin source_owner ->
    prepare_unrelated_child_origin_internal t ~source_owner
  | Capture_origin_refresh (preparation, attempt) ->
    capture_child_origin_refresh_internal t preparation attempt
  | Consume_origin_refresh observed -> consume_child_origin_refresh_internal t observed
  | Bind_origin (preparation, key, child_session_id, transaction_id) ->
    bind_child_origin_internal t ~preparation ~key ~child_session_id ~transaction_id
  | Prepare_recurrence_origin (source_owner, permit, ancestry) ->
    prepare_recurrence_child_origin_internal t ~source_owner ~permit ~ancestry
  | Capture_reservation (source_owner, bound, reference, native_callback) ->
    capture_child_origin_reservation_internal
      t
      ~source_owner
      ~bound
      ~reference
      ~native_callback
  | Observe_reservation observed -> observe_child_origin_reservation_internal t observed
  | Register_reservation (reservation, observed, native_callback, check_parent) ->
    register_child_origin_reservation_internal
      t
      ~reservation
      ~observed
      ~native_callback
      ~check_parent
  | Capture_descendant_usage (source_owner, source) ->
    capture_descendant_usage_internal t ~source_owner ~source
  | Observe_descendant_usage (observed, refresh_read) ->
    observe_descendant_usage_internal t observed ~refresh_read
  | Capture_origin_usage reservation ->
    capture_child_origin_usage_internal t ~reservation ~native_callback:None
  | Observe_origin_usage (observed, refresh_read) ->
    observe_child_origin_usage_internal t observed ~refresh_read
  | Capture_origin_import (reservation, native_callback) ->
    capture_child_origin_usage_internal t ~reservation ~native_callback
  | Import_origin_usage (observed, observation, check_parent) ->
    import_child_origin_usage_internal t observed ~observation ~check_parent
  | Observe_installation (source_owner, reference) ->
    observe_child_installation_internal t ~source_owner ~reference
  | Register_installation
      (native_callback, source_owner, child, check_parent, max_children, max_encoded_bytes)
    ->
    register_child_installation_internal
      ?native_callback
      t
      ~source_owner
      ~child
      ~check_parent
      ~max_children
      ~max_encoded_bytes
  | Observe_usage (source_owner, actor, authorize, reference) ->
    observe_child_usage_internal t ~source_owner ~actor ~authorize ~reference
  | Import_usage
      (source_owner, actor, authorize, observation, max_children, max_encoded_bytes) ->
    import_child_usage_internal
      t
      ~source_owner
      ~actor
      ~authorize
      ~observation
      ~max_children
      ~max_encoded_bytes
;;

let policy_restoration_unloaded t =
  (not t.stopped)
  && Option.is_none (Eio.Promise.peek t.finished)
  && Option.is_none t.lifecycle_fence
  && Option.is_none t.operation_worker
  && Option.is_none t.inference_execution
  && Option.is_none t.moderator_manager
;;

let policy_restoration_available t =
  policy_restoration_unloaded t
  && Option.is_none t.state.active_operation
  && Option.is_none t.runtime_retirement
  && Option.is_none t.initialization_scope
  && Option.is_none t.run_preparation
  && Option.is_none t.run_source_binding
  && Option.is_none t.held_activation
  && Option.is_none t.held_input_scope
  && Option.is_none t.held_authored_start
  && Option.is_none t.idle_completion
  && Option.is_none t.inherited_turn_prepared
  && Option.is_none t.inherited_turn_cleanup
  && Option.is_none t.governed_admission_slot
  && Option.is_none t.moderator_borrow
  && Option.is_none t.queued_event_borrow
  && Option.is_none t.delegated_policy_claim
  && (not t.idle_moderator_borrowed)
  && List.is_empty t.invocation_executions
  && List.is_empty t.job_scopes
  && Staged_jobs.is_empty t.staged_jobs
  && Staged_subscriptions.is_empty t.staged_subscriptions
  && Staged_ingress.is_empty t.staged_ingress
  && Staged_schedules.is_empty t.staged_schedules
  && Staged_notifications.is_empty t.staged_notifications
  &&
  match Active_calls.snapshot t.active_calls with
  | [], [] -> true
  | _ -> false
;;

let begin_native_setup_internal t source_owner reference source expected =
  let open Result.Let_syntax in
  let%bind () =
    if Option.exists t.runtime_source_owner ~f:(Runtime_source_owner.matches source_owner)
    then Ok ()
    else Error (error Permission_denied "native setup has a foreign Factory")
  in
  let%bind () = Runtime_builder.Source.validate_target source t.state in
  let%bind () =
    if phys_equal expected t.state && policy_restoration_available t
    then Ok ()
    else Error (error Conflict "native setup requires its exact idle unloaded Actor")
  in
  let%bind () =
    match t.policy_restoration with
    | Vacant -> Ok ()
    | Constructing actual when actual.closed -> Ok ()
    | Native_constructing actual when actual.closed -> Ok ()
    | Published actual when actual.closed -> Ok ()
    | Constructing _ | Native_constructing _ | Published _ ->
      Error (error Conflict "resource construction is already owned")
  in
  let rec setup : Native_setup_data.t =
    { issuer = t.inference_owner_identity
    ; domain = t.runtime_source_domain
    ; reference
    ; source
    ; expected
    ; closed = false
    ; current =
        (fun () ->
          let%bind () =
            if
              policy_restoration_available t
              && phys_equal setup.issuer t.inference_owner_identity
              && phys_equal setup.expected t.state
              &&
              match t.policy_restoration with
              | Native_constructing actual -> phys_equal actual setup
              | Vacant | Constructing _ | Published _ -> false
            then Ok ()
            else Error (Native_setup_data.unavailable ())
          in
          Runtime_builder.Source.validate_target setup.source t.state)
    }
  in
  t.policy_restoration <- Native_constructing setup;
  Ok setup
;;

let check_native_setup_target t (setup : Native_setup_data.t) =
  let open Result.Let_syntax in
  let%bind () = Native_setup_data.check_domain t.runtime_source_domain in
  let%bind () = Native_setup_data.check_domain setup.domain in
  let%bind () =
    if
      phys_equal setup.issuer t.inference_owner_identity
      &&
      match t.policy_restoration with
      | Native_constructing actual -> phys_equal actual setup
      | Vacant | Constructing _ | Published _ -> false
    then Ok ()
    else Error (error Conflict "native setup belongs to another Actor")
  in
  Native_setup_data.check setup
;;

let end_native_setup_internal t (setup : Native_setup_data.t) =
  let open Result.Let_syntax in
  let%bind () = Native_setup_data.check_domain t.runtime_source_domain in
  let%bind () = Native_setup_data.check_domain setup.domain in
  if not (phys_equal setup.issuer t.inference_owner_identity)
  then Error (error Conflict "native setup belongs to another Actor")
  else (
    match t.policy_restoration with
    | Native_constructing actual when phys_equal actual setup ->
      Native_setup_data.close setup;
      t.policy_restoration <- Vacant;
      Ok ()
    | Vacant when setup.closed -> Ok ()
    | Vacant | Native_constructing _ | Constructing _ | Published _ ->
      Error
        (error Conflict "native setup is no longer this Actor's registered construction"))
;;

let begin_policy_restoration_internal t source_owner source basis request governance =
  let open Result.Let_syntax in
  let%bind () =
    if Option.exists t.runtime_source_owner ~f:(Runtime_source_owner.matches source_owner)
    then Ok ()
    else Error (error Permission_denied "policy restoration has a foreign Factory")
  in
  let%bind () = Causal_governance_binding.check_request governance request in
  let%bind () =
    match governance.Causal_governance_binding.source with
    | Standalone _ -> Ok ()
    | Registered registered ->
      if
        Runtime_source_owner.Identity.equal
          (Runtime_source_owner.identity registered.source_owner)
          (Runtime_source_owner.identity source_owner)
      then Ok ()
      else
        Error
          (error Permission_denied "policy restoration governance has a foreign Factory")
  in
  let%bind () =
    match request.Script_tool_calls.caller with
    | Some caller -> Delegated_policy_caller.check_current caller
    | None ->
      Error (error Permission_denied "policy restoration requires its actual Caller")
  in
  let%bind () = Runtime_builder.Source.validate_target source t.state in
  let%bind () = Policy_restore_basis.check_construction basis ~state:t.state in
  let%bind () =
    if policy_restoration_available t
    then Ok ()
    else Error (error Conflict "policy restoration requires an idle unloaded Actor")
  in
  let%bind () =
    match t.policy_restoration with
    | Vacant -> Ok ()
    | Constructing actual when actual.closed -> Ok ()
    | Published actual when actual.closed -> Ok ()
    | Native_constructing actual when actual.closed -> Ok ()
    | Constructing _ | Published _ | Native_constructing _ ->
      Error (error Conflict "policy restoration is already owned")
  in
  let rec restoration : Policy_restoration_data.t =
    { issuer = t.inference_owner_identity
    ; domain = t.runtime_source_domain
    ; source
    ; basis
    ; closed = false
    ; current =
        (fun () ->
          let%bind () =
            if
              policy_restoration_available t
              && phys_equal restoration.issuer t.inference_owner_identity
              &&
              match t.policy_restoration with
              | Constructing actual -> phys_equal actual restoration
              | Vacant | Published _ | Native_constructing _ -> false
            then Ok ()
            else Error (Policy_restoration_data.unavailable ())
          in
          let%bind () = Causal_governance_binding.check_request governance request in
          let%bind () =
            match request.Script_tool_calls.caller with
            | Some caller -> Delegated_policy_caller.check_current caller
            | None ->
              Error (error Permission_denied "policy restoration lost its actual Caller")
          in
          let%bind () =
            Runtime_builder.Source.validate_target restoration.source t.state
          in
          Policy_restore_basis.check_construction restoration.basis ~state:t.state)
    }
  in
  t.policy_restoration <- Constructing restoration;
  Ok restoration
;;

let check_policy_restoration_target t (restoration : Policy_restoration_data.t) =
  let open Result.Let_syntax in
  let%bind () =
    if
      phys_equal restoration.issuer t.inference_owner_identity
      &&
      match t.policy_restoration with
      | Constructing actual -> phys_equal actual restoration
      | Vacant | Published _ | Native_constructing _ -> false
    then Ok ()
    else Error (error Conflict "policy restoration belongs to another Actor")
  in
  Policy_restoration_data.check restoration
;;

let publish_policy_restoration_internal t restoration access =
  let open Result.Let_syntax in
  let%bind () = check_policy_restoration_target t restoration in
  let%bind () = Runtime_builder.Restored_policy_access.check access ~expected:t.state in
  let%bind () =
    Policy_restore_basis.check_construction
      (Runtime_builder.Restored_policy_access.basis access)
      ~state:t.state
  in
  let rec published : Policy_restoration_data.published =
    { issuer = t.inference_owner_identity
    ; domain = t.runtime_source_domain
    ; access
    ; closed = false
    ; current =
        (fun () ->
          let%bind () =
            if
              policy_restoration_unloaded t
              && phys_equal published.issuer t.inference_owner_identity
              &&
              match t.policy_restoration with
              | Published actual -> phys_equal actual published
              | Vacant | Constructing _ | Native_constructing _ -> false
            then Ok ()
            else Error (Policy_restoration_data.unavailable ())
          in
          Runtime_builder.Restored_policy_access.check access ~expected:t.state)
    }
  in
  (* No previous request, governance or authorize closure enters Published. *)
  Policy_restoration_data.close restoration;
  t.policy_restoration <- Published published;
  Ok published
;;

let end_policy_restoration_internal t restoration =
  let open Result.Let_syntax in
  let%bind () =
    Policy_restoration_data.check_domain restoration.Policy_restoration_data.domain
  in
  if not (phys_equal restoration.issuer t.inference_owner_identity)
  then Error (error Conflict "policy restoration belongs to another Actor")
  else (
    Policy_restoration_data.close restoration;
    (match t.policy_restoration with
     | Constructing actual when phys_equal actual restoration ->
       t.policy_restoration <- Vacant
     | Vacant | Constructing _ | Native_constructing _ | Published _ -> ());
    Ok ())
;;

let policy_restoration_request
  : type a. t -> a Policy_restoration_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  let open Result.Let_syntax in
  match request with
  | Begin_native (source_owner, reference, source, expected) ->
    begin_native_setup_internal t source_owner reference source expected
  | End_native setup -> end_native_setup_internal t setup
  | Open_native_graph (setup, source) ->
    let%bind () = check_native_setup_target t setup in
    open_inference_owner t source
  | Begin (source_owner, source, basis, request, governance) ->
    begin_policy_restoration_internal t source_owner source basis request governance
  | Publish (restoration, access) ->
    publish_policy_restoration_internal t restoration access
  | End restoration -> end_policy_restoration_internal t restoration
  | Reserve_history (restoration, count) ->
    let%bind () = check_policy_restoration_target t restoration in
    reserve_history_block t count
  | Open_graph (restoration, source) ->
    let%bind () = check_policy_restoration_target t restoration in
    open_inference_owner t source
;;

let policy_restoration_request_allowed : type a. a request -> bool = function
  | Quiescent_checkpoint _ -> false
  | Policy_restoration _
  | Install_descendant_host (Restored _, _, _, _, _, _)
  | Stop _
  | Stop_managed _
  | Stop_delegated _
  | Stop_delegated_at_epoch _
  | Shutdown
  | Runtime_retirement _ -> true
  | request -> lifecycle_request_allowed request
;;

let native_setup_request_allowed : type a. a request -> bool = function
  | Quiescent_checkpoint _ -> false
  | Policy_restoration (Begin_native _ | End_native _ | Open_native_graph _) -> true
  | Policy_restoration (Begin _ | Publish _ | End _ | Reserve_history _ | Open_graph _) ->
    false
  | Stop _
  | Stop_managed _
  | Stop_delegated _
  | Stop_delegated_at_epoch _
  | Shutdown
  | Runtime_retirement _ -> true
  | request -> lifecycle_request_allowed request
;;

(* The exact permanent election and original startup facts are checked here,
   before the only new custody mutation. No callback, mailbox request, IO, End
   invocation or State/Run change occurs inside this nonyielding handler. *)
let failed_startup_request_basis (t : t) (request : failed_startup_request) =
  let open Result.Let_syntax in
  let%bind continuation =
    match request.construction with
    | Runtime_construction.Initial continuation -> Ok continuation
    | Existing_goal _ | Delegated_load _ ->
      Error
        (error
           Conflict
           "failed startup release requires the original Initial construction")
  in
  let activation = Admitted_activation.Continuation.target continuation in
  if
    Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
    && Int.equal activation.domain t.runtime_source_domain
    && Run_preparation.belongs_to activation.preparation ~owner:t.run_preparation_owner
    && Failed_startup_release_data.belongs_to
         request.naming
         ~issuer:t.initialization_owner
         ~startup:activation.cleanup
    && phys_equal
         request.retirement.original.selection.issuing_actor
         t.initialization_owner
    && Int.equal request.retirement.original.selection.domain t.runtime_source_domain
  then Ok continuation
  else Error (error Conflict "failed startup request belongs to another Actor or domain")
;;

let failed_startup_callbacks_joined startup =
  let open Result.Let_syntax in
  match Failed_startup_data.initialization startup with
  | Unseen | Ambiguous -> Ok false
  | One parent ->
    let%map snapshot = Callback_cleanup_data.Initialization.snapshot parent in
    Callback_cleanup_data.Cleanup_snapshot.registration_closed snapshot
    && List.for_all
         (Callback_cleanup_data.Cleanup_snapshot.completions snapshot)
         ~f:(fun completion ->
           match
             ( Callback_cleanup_data.Completion_snapshot.producer_exit completion
             , Callback_cleanup_data.Completion_snapshot.finish_call completion
             , Callback_cleanup_data.Completion_snapshot.release completion )
           with
           | Returned _, Completed _, Completed _ ->
             Callback_cleanup_data.Completion_snapshot.original_finish_settled completion
           | _ -> false)
;;

let failed_startup_retirement_joined (t : t) (request : failed_startup_request) =
  let cleanup = request.retirement in
  Option.exists t.runtime_retirement ~f:(fun actual ->
    phys_equal actual cleanup.original
    && actual.closing
    && Option.exists actual.cleanup_holder ~f:(phys_equal cleanup)
    && Option.is_none actual.selection.operation
    &&
    match Eio.Promise.peek actual.foreground_finished with
    | Some (Ok (Ok ())) -> true
    | None | Some (Ok (Error _) | Error _) -> false)
  && (match cleanup.reservation with
      | Available -> true
      | Advancing -> false)
  &&
  match Retirement_cleanup_observation.Snapshot.progress cleanup.latest with
  | Joined -> true
  | Pending | Retryable | Terminal -> false
;;

let failed_startup_actor_quiescent (t : t) =
  Option.is_none t.state.active_operation
  && Option.is_none t.active_cancel
  && Option.is_none t.operation_worker
  && Option.is_none t.inference_execution
  && List.is_empty t.invocation_executions
  && List.is_empty t.job_scopes
  && List.is_empty t.inference_owners
  && Option.is_none t.constructor_models
  && Option.is_none t.initialization_scope
  && Option.is_none t.moderator_borrow
  && Option.is_none t.queued_event_borrow
  && Option.is_none t.delegated_policy_claim
  && Option.is_none t.moderator_manager
  && (match t.policy_restoration with
      | Vacant -> true
      | Constructing _ | Native_constructing _ | Published _ -> false)
  && Option.is_none t.legacy_callback_scope
  && Option.is_none t.foreground_moderator
  && (not t.idle_moderator_borrowed)
  && Option.is_none t.idle_completion
  && Option.is_none t.idle_turn_continuation
  && Option.is_none t.inherited_turn_prepared
  && Option.is_none t.inherited_turn_cleanup
  && Option.is_none t.governed_admission_slot
  && Option.is_none t.causal_root_write
  && Option.is_none t.held_input_scope
  && Option.is_none t.run_preparation
  && Option.is_none t.run_source_binding
  && Option.is_none t.lifecycle_fence
  && Staged_jobs.is_empty t.staged_jobs
  && Staged_subscriptions.is_empty t.staged_subscriptions
  && Staged_ingress.is_empty t.staged_ingress
  && Staged_schedules.is_empty t.staged_schedules
  && Staged_notifications.is_empty t.staged_notifications
  &&
  match Active_calls.snapshot t.active_calls with
  | [], [] -> true
  | _ -> false
;;

let unsupported_startup_release () =
  error Conflict "original failed startup custody is live, unknown or unsupported"
;;

let failed_startup_original_scope t continuation =
  let activation = Admitted_activation.Continuation.target continuation in
  let request = Run_preparation.request activation.preparation in
  match request.input with
  | User_submission _
    when Option.is_none t.held_authored_start
         && Failed_startup_release_data.original_input_joined activation.cleanup ->
    Ok None
  | User_submission _ -> Error (unsupported_startup_release ())
  | Authored_start ->
    let open Result.Let_syntax in
    let%bind original =
      Failed_startup_release_data.original_authored_joined activation.cleanup
    in
    (match original, t.held_authored_start with
     | Some (First_lifecycle _), None -> Ok None
     | Some (Final_aggregate (attempt, lifecycle)), Some ({ phase = Closed; _ } as scope)
       when phys_equal scope.cleanup attempt
            && phys_equal scope.continuation continuation
            && phys_equal scope.issuing_actor t.inference_owner_identity
            && Int.equal scope.domain t.runtime_source_domain
            &&
            match lifecycle, Runtime_builder.Authored_start.disposition scope.startup with
            | Legacy, Legacy_acknowledged | Extension _, Extension_pending -> true
            | (Legacy | Extension _), _ -> false ->
       (* Permanent retirement closes the exact scope without erasing its
          original, acknowledged lifecycle and historical graph ownership. *)
       let%bind graphs_joined =
         Failed_startup_release_data.authored_graphs_joined
           scope.graphs
           ~issuer:t.inference_owner_identity
           ~generation:activation.run.source.generation
       in
       if graphs_joined then Ok (Some scope) else Error (unsupported_startup_release ())
     | (None | Some (First_lifecycle _ | Final_aggregate _)), _ ->
       Error (unsupported_startup_release ()))
;;

let release_failed_startup_custody_internal (t : t) (request : failed_startup_request) =
  let open Result.Let_syntax in
  let%bind continuation = failed_startup_request_basis t request in
  let activation = Admitted_activation.Continuation.target continuation in
  let%bind () =
    if Failed_startup_release_data.Gate.allows t.startup_disposal request.naming
    then Ok ()
    else Error (error Conflict "another failed startup request owns disposal-only Actor")
  in
  match Failed_startup_release_data.released request.naming with
  | Error _ as result -> result
  | Ok (Some receipt) -> Ok receipt
  | Ok None ->
    let%bind callbacks_joined = failed_startup_callbacks_joined activation.cleanup in
    let supported =
      Option.exists
        t.canonical_persistence
        ~f:Canonical_backend_binding_data.requires_recovery
      && Option.exists t.held_activation ~f:(phys_equal activation)
      && (match !(activation.phase) with
          | Closed -> true
          | Reserved | Constructing | Handed_off _ -> false)
      && Option.is_none activation.control
      && (match !(activation.input_attempt) with
          | Claimed -> true
          | Available -> false)
      && callbacks_joined
      && failed_startup_retirement_joined t request
      && failed_startup_actor_quiescent t
      && not t.stopped
    in
    if not supported
    then Error (unsupported_startup_release ())
    else (
      let%bind authored = failed_startup_original_scope t continuation in
      let%bind receipt =
        Failed_startup_release_data.Gate.release
          t.startup_disposal
          request.naming
          ~issuer:t.initialization_owner
          ~startup:activation.cleanup
      in
      (* Request receipt and monotonic gate are already installed. Only exact
         retained process-local startup bookkeeping is now dropped. Durable Run,
         original End and all callback/commit observations remain unchanged. *)
      Option.iter authored ~f:(fun scope ->
        scope.phase <- Closed;
        t.held_authored_start <- None);
      t.held_activation <- None;
      Ok receipt)
;;

let startup_disposal_request_allowed : type a. t -> a request -> bool =
  fun t request ->
  if not (Failed_startup_release_data.Gate.is_closed t.startup_disposal)
  then true
  else (
    match request with
    | State | Shutdown -> true
    | Runtime_retirement (Release_failed_startup selected) ->
      Failed_startup_release_data.Gate.allows t.startup_disposal selected.naming
    | _ -> false)
;;

let recovery_note_access t ~access ~effect_kind =
  let open Result.Let_syntax in
  let%bind owner =
    Option.bind
      t.canonical_persistence
      ~f:Canonical_backend_binding_data.recovery_note_owner
    |> Result.of_option
         ~error:(error Invalid_state "durable recovery notes are unavailable")
  in
  let%bind () = Recovery_note_session.check_owner t.state.recovery_notes ~owner in
  let%bind checked = Recovery_note_access.check_now access t.state ~owner ~effect_kind in
  match checked with
  | Operator { principal; attachment_id } ->
    Ok (owner, Recovery_note_request.Operator { principal; attachment_id })
  | Native invocation ->
    let%bind execution =
      List.find t.invocation_executions ~f:(fun execution ->
        Agent_protocol.Invocation.equal execution.dispatched invocation)
      |> Result.of_option
           ~error:(error Permission_denied "recovery note invocation is not executing")
    in
    let%bind () =
      if Atomic.get execution.authority_live
      then Ok ()
      else Error (error Permission_denied "recovery note invocation authority is closed")
    in
    let%bind operation_id =
      match execution.owner, invocation.context.origin with
      | Foreground operation_id, (Model | Script) ->
        running_operation t operation_id |> Result.map ~f:(fun _ -> operation_id)
      | _ ->
        Error
          (error Permission_denied "recovery notes require a live foreground invocation")
    in
    let%bind current = authorized_native_child_basis t (Inference_invocation execution) in
    let%map () = current.check_current () in
    owner, Recovery_note_request.Native (invocation, operation_id)
;;

let recovery_note_mutation_identity t ~access ~effect_kind route =
  let open Result.Let_syntax in
  let%bind owner, checked = recovery_note_access t ~access ~effect_kind in
  let%map identity =
    match route, checked with
    | ( Recovery_note_request.Operator_key key
      , Operator { principal; attachment_id = Some attachment_id } ) ->
      let%bind attachment = write_attachment t attachment_id in
      let lease_principal =
        Option.bind attachment.owner_lease ~f:(fun lease -> lease.principal_id)
      in
      if
        Option.exists lease_principal ~f:(fun id ->
          not (Agent_protocol.Id.Principal.equal id principal))
      then
        Error
          (error
             Permission_denied
             "recovery note writer attachment belongs to another principal")
      else Ok (Recovery_notes.Catalog.Mutation_identity.Client { principal; key })
    | Native_invocation, Native (invocation, _) ->
      Ok (Recovery_notes.Catalog.Mutation_identity.Native invocation.context.id)
    | Operator_key _, (Operator { attachment_id = None; _ } | Native _)
    | Native_invocation, Operator _ ->
      Error
        (error
           Permission_denied
           "recovery note mutation requires its original writer route")
  in
  owner, identity
;;

let require_recovery_owner_writer t ~principal ~attachment_id =
  Writer_attachment.require_recovery_owner
    t.state ~principal ~attachment_id ~now:t.services.now
;;

let enable_recovery_windows_internal t actor attachment_id authorize =
  let module P = Agent_protocol in
  let open Result.Let_syntax in
  let scope ledger = Recovery_window_ledger.(Window.scope (active ledger)) in
  let%bind owner =
    Option.bind t.canonical_persistence ~f:Canonical_backend_binding_data.session_owner
    |> Result.of_option
         ~error:(error Invalid_state "durable recovery window storage is unavailable")
  in
  let check () =
    let principal = Operator_authorization.principal actor in
    let%bind () =
      if
        Operator_authorization.is_current actor
        && P.Principal.has_scope principal Send_messages
      then authorize t.state
      else Error (error Permission_denied "recovery window writer authority expired")
    in
    require_recovery_owner_writer t ~principal:principal.id ~attachment_id
  in
  let%bind () = check () in
  match t.state.recovery_windows with
  | Some ledger when P.Session_ref.equal owner (Recovery_window_ledger.owner ledger) ->
    Ok (scope ledger)
  | Some _ -> Error (error Invalid_state "recovery window owner differs from this host")
  | None ->
    let%bind () =
      match t.state.runtime_initialization, t.state.active_operation with
      | Ready, None -> Ok ()
      | Pending _, _ | Ready, Some _ ->
        Error (error Conflict "recovery window enablement requires settled history")
    in
    let previous = t.state in
    let window = P.Id.Context_window.create () in
    let run_preparation =
      Option.map t.run_source_binding ~f:(fun binding ->
        binding.Source_binding.preparation)
    in
    let%bind candidate =
      prepare_transition
        ?run_preparation
        t
        ~delta:(Recovery_window_enabled (owner, window))
        ~payloads:[]
    in
    let%bind ledger =
      Result.of_option
        candidate.state.recovery_windows
        ~error:(error Internal_error "recovery window candidate has no ledger")
    in
    let commit_observation =
      Session_commit_observation.Owner.create_guarded
        ~previous
        ~candidate
        ~check_at_writer:check
    in
    let%bind () =
      persist_transition
        ?run_preparation
        t
        candidate
        ~check_before_commit:check
        ~commit_observation
    in
    install_committed_transition ?run_preparation t candidate;
    publish_committed_transition t candidate;
    Ok (scope ledger)
;;

let persist_recovery_delta
      ?(rollover = false)
      ?(payloads = [])
      ?(after_install = fun () -> ())
      t
      ~delta
      ~check_before_commit
  =
  let open Result.Let_syntax in
  let previous = t.state in
  let run_preparation =
    Option.map t.run_source_binding ~f:(fun binding -> binding.Source_binding.preparation)
  in
  let%bind candidate = prepare_transition ?run_preparation t ~delta ~payloads in
  let commit_observation =
    Session_commit_observation.Owner.create_guarded
      ~previous
      ~candidate
      ~check_at_writer:check_before_commit
  in
  let persist () =
    persist_transition
      ?run_preparation
      t
      candidate
      ~check_before_commit
      ~commit_observation
  in
  let%bind () =
    if not rollover
    then persist ()
    else
      Exn.protect ~f:persist ~finally:(fun () ->
        match Session_commit_observation.outcome commit_observation with
        | Not_called | Returned (Ok ()) -> ()
        | In_progress | Returned (Error _) | Raised _ ->
          (match Session_commit_observation.progress commit_observation with
           | Before_writer -> ()
           | Unobserved | Writer_entered _ | Journal_acknowledged _ ->
             t.rollover_requires_recovery <- true))
  in
  install_committed_transition ?run_preparation t candidate;
  after_install ();
  publish_committed_transition t candidate;
  Ok ()
;;

let prepare_recovery_note_delivery t ~source ~(invocation : Agent_protocol.Invocation.t) catalog query =
  let module P = Agent_protocol in
  let open Result.Let_syntax in
  let unavailable () = Error (error Invalid_state "recovery note disclosure is unavailable") in
  let%bind original = Result.of_option t.operation_agent_custody ~error:(error Invalid_state "recovery note has no live operation") in
  let generation = invocation.context.generation in
  let observe () =
    if
      t.stopped
      || t.canonical_write_in_progress
      || Option.is_some t.lifecycle_fence
      || not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
      || not (Option.exists t.operation_agent_custody ~f:(phys_equal original))
    then unavailable ()
    else (
      let%bind binding =
        Result.of_option t.canonical_persistence
          ~error:(error Invalid_state "durable recovery notes are unavailable")
      in
      let%bind operation = running_operation t original.operation_id in
      let%bind () =
        if
          Canonical_backend_binding_data.is_available binding
          && Option.exists (Canonical_backend_binding_data.session_owner binding)
               ~f:(P.Session_ref.equal source)
          && Int.equal operation.generation generation
          && Int.equal operation.generation t.state.identity.generation
        then check_agent_admission original.admission
        else unavailable ()
      in
      let%bind actor = operation_agent_actor t original.operation_id in
      match actor with
      | Some actor
        when Operator_authorization.is_current actor
             && P.Principal.has_scope
                  (Operator_authorization.principal actor)
                  View_session_transcript ->
        Recovery_note_session.for_owner t.state.recovery_notes ~owner:source
      | Some _ | None -> unavailable ())
  in
  match invocation.context.origin, invocation.context.call_entry_id with
  | Model, Some _ ->
    let%bind _ = observe () in
    let%map plan = Recovery_note_query.prepare query catalog in
    { source
    ; materialize = (fun () -> Result.bind (observe ()) ~f:(Recovery_note_query.render plan))
    ; check_current = (fun () -> (match observe () with
       | Ok catalog -> Recovery_note_query.current plan catalog
       | Error _ -> false))
    }
  | (Model | Moderator | Script | Delegated_agent | External_adapter), _ -> unavailable ()
;;

let active_rollover_window t =
  let module P = Agent_protocol in
  let module L = Recovery_window_ledger in
  let open Option.Let_syntax in
  let%bind storage = t.canonical_persistence in
  let%bind owner = Canonical_backend_binding_data.session_owner storage in
  let%bind ledger = t.state.recovery_windows in
  if
    Canonical_backend_binding_data.is_available storage
    && P.Session_ref.equal owner (L.owner ledger)
  then Some (L.Window.scope (L.active ledger))
  else None
;;

let admit_recovery_rollover
      ?(check_basis = fun () -> Ok ())
      ?(after_admit = fun _ -> ())
      t
      ~check
      ~expected
  =
  let module R = Recovery_rollover in
  let module P = Agent_protocol in
  let open Result.Let_syntax in
  let%bind requester = check () in
  let%bind () = require_rollover_recovered t in
  let%bind retained = R.previous t.state.recovery_rollover ~requester ~expected in
  match retained with
  | Some receipt -> Ok receipt
  | None ->
    let check_policy () =
      let%bind () =
        if Session_delta.awaiting_settled_foreground t.state
        then Error (error Conflict "the active window has a pending continuation")
        else Ok ()
      in
      let%bind _ =
        Result.of_option (current_context_capacity_basis t)
          ~error:(error Invalid_state "local context mode is disabled")
      in
      let%map _ =
        Result.of_option (active_rollover_window t)
          ~error:(error Invalid_state "recovery window ledger is unavailable")
      in
      ()
    in
    let%bind () = check_policy () in
    let%bind () = check_basis () in
    let id = P.Id.Operation.create () in
    let intent =
      R.Intent.create ~id ~expected ~requester ~admitted_at:(t.services.now ())
    in
    let check_before_commit () =
      let%bind () = check_policy () in
      let%bind () = check_basis () in
      let%bind current = check () in
      if R.Requester.equal current requester
      then Ok ()
      else Error (error Permission_denied "rollover requester authority changed")
    in
    let%bind () =
      persist_recovery_delta t
        ~rollover:true
        ~delta:(Recovery_rollover_changed (Admit intent))
        ~after_install:(fun () -> after_admit intent)
        ~check_before_commit
    in
    Option.bind t.state.recovery_rollover ~f:(fun ledger -> R.find ledger ~id)
    |> Result.of_option ~error:(error Internal_error "durable rollover receipt missing")
;;

let context_native_execution t ~access ~effect_kind =
  let module P = Agent_protocol in
  let open Result.Let_syntax in
  let%bind principal, invocation =
    Recovery_context_service.check_now access t.state ~effect_kind
  in
  let%bind execution =
    List.find t.invocation_executions ~f:(fun execution ->
      P.Invocation.equal execution.dispatched invocation)
    |> Result.of_option ~error:(error Permission_denied "context invocation is not active")
  in
  let%bind operation_id =
    match execution.owner with
    | Foreground operation_id when Atomic.get execution.authority_live -> Ok operation_id
    | _ -> Error (error Permission_denied "context tools require a live foreground invocation")
  in
  let%bind current = authorized_native_child_basis t (Inference_invocation execution) in
  let%map () = current.check_current () in
  principal, execution, operation_id
;;

let rollover_operator t actor ~attachment_id ~authorize =
  let module P = Agent_protocol in
  let open Result.Let_syntax in
  let principal = Operator_authorization.principal actor in
  let%bind () =
    if
      Operator_authorization.is_current actor
      && P.Principal.has_scope principal Send_messages
    then authorize t.state
    else Error (error Permission_denied "rollover operator authority expired")
  in
  let%bind () =
    if Operator_authorization.is_current actor
    then require_recovery_owner_writer t ~principal:principal.id ~attachment_id
    else Error (error Permission_denied "rollover operator authority expired")
  in
  Ok principal
;;

let check_rollover_cut t ~previous ~(expected : Recovery_rollover.Expected.t) ~check =
  let open Result.Let_syntax in
  let%bind _ = check () in
  let%bind () = require_runtime_admission t in
  match active_rollover_window t, t.state.lifecycle.observed with
  | Some scope, (Idle | Stopped)
    when phys_equal previous t.state
         && Agent_protocol.Recovery_window.Scope.equal scope expected.scope
         && Int64.equal t.state.counters.revision expected.revision
         && Option.is_none t.state.active_operation
         && List.is_empty t.invocation_executions
         && (not t.idle_moderator_borrowed)
         && not (moderator_is_borrowed t) -> Ok ()
  | _ -> Error (error Conflict "rollover cut or runtime authority changed")
;;

let record_context_checkpoint_internal t ~check expected notes =
  let module P = Agent_protocol in
  let module R = Recovery_rollover in
  let open Result.Let_syntax in
  let prior = t.state in
  let%bind (principal : P.Principal.t) = check () in
  let%bind () =
    if P.Principal.has_scope principal View_session_transcript
    then Ok ()
    else Error (error Permission_denied "checkpoint requires transcript authority")
  in
  let check_before_commit () =
    let%bind () = check_rollover_cut t ~previous:prior ~expected ~check in
    if Option.is_some (current_context_capacity_basis t)
    then Ok ()
    else Error (error Invalid_state "local context mode is disabled")
  in
  let%bind () = check_before_commit () in
  let%bind checkpoint =
    R.Checkpoint.capture
      expected
      ~history:prior.conversation.canonical_history
      ~catalog:prior.recovery_notes
      ~notes
      ~recipe:(Owner_selection principal.id)
  in
  let%map () =
    persist_recovery_delta
      t
      ~rollover:true
      ~delta:(Recovery_rollover_changed (Record_checkpoint checkpoint))
      ~check_before_commit
  in
  checkpoint
;;

let settle_context_rollover_internal
      ?batch
      ?checkpoint_history
      ?check_live_cut
      ?after_commit_install
      t
      ~check
      ~authorize_force
      ~id
      (expected : Recovery_rollover.Expected.t)
      (settlement : Recovery_rollover.Settlement.t)
  =
  let module P = Agent_protocol in
  let module R = Recovery_rollover in
  let module Scope = P.Recovery_window.Scope in
  let open Result.Let_syntax in
  let%bind principal = check () in
  let%bind () = require_rollover_recovered t in
  let find () =
    Option.bind t.state.recovery_rollover ~f:(fun ledger -> R.find ledger ~id)
    |> Result.of_option ~error:(error Conflict "rollover intent is unavailable")
  in
  let%bind receipt = find () in
  match receipt.status with
  | Terminal _ -> Ok receipt
  | Pending ->
    let previous = t.state in
    let check_cut () =
      match check_live_cut with
      | None -> check_rollover_cut t ~previous ~expected ~check
      | Some validate ->
        let%bind _ = check () in
        let%bind () = require_runtime_admission t in
        if phys_equal previous t.state
        then validate ()
        else Error (error Conflict "settled rollover prestate changed")
    in
    let%bind () = check_cut () in
    let persist ?(payloads = []) ?after_install delta ~check_before_commit =
      let%bind () =
        persist_recovery_delta
          t
          ~rollover:true
          ~payloads
          ?after_install
          ~delta
          ~check_before_commit
      in
      find ()
    in
    let supersede reason =
      persist
        (Recovery_rollover_changed (Settle { id; terminal = Superseded reason }))
        ~check_before_commit:check_cut
    in
    if not (Scope.equal receipt.intent.expected.scope expected.scope)
    then supersede Basis_changed
    else (
      match settlement with
      | Cancel -> supersede Cancelled
      | Publish { checkpoint; retain } ->
        let%bind basis =
          Result.of_option
            (current_context_capacity_basis t)
            ~error:(error Invalid_state "local context mode is disabled")
        in
        let%bind quality =
          match checkpoint with
          | None -> Ok (Error R.Receipt.Checkpoint_missing)
          | Some checkpoint when P.Principal.has_scope principal View_session_transcript
            ->
            let stored = Option.value_exn previous.recovery_rollover in
            (match
               R.check_checkpoint
                 ?checkpoint_history
                 stored
                 checkpoint
                 ~expected
                 ~history:previous.conversation.canonical_history
                 ~catalog:previous.recovery_notes
             with
             | Ok () -> Ok (Ok (R.Receipt.Checkpointed checkpoint))
             | Error _ -> Ok (Error R.Receipt.Checkpoint_unavailable))
          | Some _ ->
            Error (error Permission_denied "checkpoint requires transcript authority")
        in
        let check_force () =
          match receipt.intent.requester, authorize_force with
          | Operator { force = true; _ }, Some authorized -> authorized t.state
          | _ ->
            Error
              (error
                 Permission_denied
                 "archive-only rollover requires current force authority")
        in
        let commit quality =
          let check_before_commit () =
            let%bind () = check_cut () in
            let%bind () =
              if
                Option.exists
                  (current_context_capacity_basis t)
                  ~f:(Configuration_capture.Capacity_basis.equal basis)
              then Ok ()
              else Error (error Conflict "rollover target or policy changed")
            in
            match quality with
            | R.Receipt.Archive_only _ ->
              let%bind () = check_force () in
              Option.value_map check_live_cut ~default:(Ok ()) ~f:(fun validate ->
                if phys_equal previous t.state
                then validate ()
                else Error (error Conflict "settled rollover prestate changed"))
            | Checkpointed _ ->
              (* The checked immutable checkpoint and note revisions are still at [previous]. *)
              Ok ()
          in
          let%bind () = check_before_commit () in
          let%bind archive =
            t.persistence.archive_reference ~previous ~kind:Rollover id
          in
          let%bind archive =
            Chatml_source.Digest.of_hex archive.sha256
            |> Result.map_error ~f:(fun _ ->
              error Persistence_error "rollover archive digest is invalid")
          in
          let%bind successor =
            Scope.create
              ~session:(Scope.session expected.scope)
              ~generation:(Scope.generation expected.scope)
              ~window:(P.Id.Context_window.create ())
          in
          let%bind change =
            R.Commit.create
              ?batch
              receipt.intent
              ~expected
              ~successor
              ~archive
              ~checkpoint:quality
              ~retain
          in
          let%bind retained = Session_delta.rollover_retained_history previous change in
          let payloads =
            [ P.Event.Durable.Payload.History_replaced
                (Session_state.history_window retained)
            ]
            @ Option.to_list
                (Option.map batch ~f:(fun _ ->
                   P.Event.Durable.Payload.Session_state_changed
                     { desired_state = previous.lifecycle.desired; observed_state = Idle }))
          in
          persist
            (Recovery_rollover_committed change)
            ~payloads
            ?after_install:after_commit_install
            ~check_before_commit
        in
        (match quality, receipt.intent.requester with
         | Ok quality, _ -> commit quality
         | Error reason, Operator { force = true; _ } -> commit (Archive_only reason)
         | Error _, (Operator _ | Native _) -> supersede Checkpoint_required))
;;

let settled_rollover_authority t publication (intent : Recovery_rollover.Intent.t) =
  let module P = Agent_protocol in
  let open Result.Let_syntax in
  let operation = publication.Foreground_publication.operation.id in
  match intent.requester with
  | Operator _ ->
    Option.bind t.live_operator_rollover ~f:(fun selected ->
      Option.some_if
        (P.Id.Operation.equal intent.id selected.id
         && phys_equal selected.publication publication)
        (selected.check, selected.authorize_force))
  | Native requester when P.Id.Operation.equal requester.operation operation ->
    let check () =
      let%bind () = check_operation_descendant t operation in
      let%bind admission = operation_agent_admission t operation in
      let%bind admission =
        Result.of_option
          admission
          ~error:(error Permission_denied "rollover requester is unavailable")
      in
      let%bind () = Execution_custody.Admission.check admission in
      let%bind custody =
        Execution_custody.Admission.custody admission
        |> Result.of_option
             ~error:
               (error Permission_denied "rollover requester has no current authority")
      in
      let%bind actor = Execution_custody.actor custody in
      let principal = Operator_authorization.principal actor in
      if
        P.Id.Principal.equal principal.id requester.principal
        && P.Principal.has_scope principal Send_messages
      then Ok principal
      else Error (error Permission_denied "rollover requester authority changed")
    in
    Some (check, None)
  | Native _ -> None
;;

let settle_foreground_tool_batch t (publication : Foreground_publication.t) live =
  let module P = Agent_protocol in
  let module R = Recovery_rollover in
  let module B = Recovery_rollover_batch_cut in
  let module S = Chat_response.Settled_tool_batch in
  let open Result.Let_syntax in
  let operation = publication.operation.id in
  let admission =
    let open Option.Let_syntax in
    let%bind intent = Option.bind t.state.recovery_rollover ~f:R.pending in
    let%map check, force = settled_rollover_authority t publication intent in
    intent, check, force
  in
  match admission with
  | _ when not (foreground_publication_matches t publication) -> Ok S.Retire
  | None -> Ok S.Continue
  | Some (intent, check, authorize_force) ->
    let%bind () = check_live_foreground_publication t publication in
    let%bind scope =
      Result.of_option
        (active_rollover_window t)
        ~error:(error Conflict "settled batch window is unavailable")
    in
    let%bind () =
      if P.Recovery_window.Scope.equal scope intent.expected.scope
      then Ok ()
      else Error (error Conflict "settled batch window changed")
    in
    let exact_attempt () =
      if Option.exists publication.finished_root ~f:(phys_equal (S.attempt live))
      then Ok ()
      else Error (error Conflict "settled batch is not the worker's acknowledged attempt")
    in
    let%bind () =
      match publication.finished_root with
      | Some _ -> exact_attempt ()
      | None -> Ok ()
    in
    (match B.capture t.state ~scope ~operation live with
     | Error _ -> Ok S.Continue
     | Ok batch ->
       let%bind () = exact_attempt () in
       let%bind checkpoint_history =
         B.validate t.state ~scope ~requester:intent.requester batch
       in
       let check_live_cut () =
         let%bind () = check_live_foreground_publication t publication in
         let%bind () = exact_attempt () in
         let%bind status = read_context_capacity t operation in
         match status with
         | Current _
           when List.is_empty t.invocation_executions
                && (not (moderator_is_borrowed t))
                && (not t.idle_moderator_borrowed)
                && not t.state.halted -> Ok ()
         | Current _ | Disabled | Stale_preparation _ | Awaiting_preparation _ ->
           Error
             (error
                Conflict
                "settled batch has active ownership or its selected policy changed")
       in
       let%bind expected = R.Expected.create scope ~revision:t.state.counters.revision in
       let checkpoint = Option.bind t.state.recovery_rollover ~f:R.checkpoint in
       let retain =
         List.take
           t.state.conversation.canonical_history
           t.state.conversation.initial_prompt_entry_count
         |> List.map ~f:(fun entry -> entry.P.History.id)
       in
       let after_commit_install () =
         if Option.exists t.foreground_publication ~f:(phys_equal publication)
         then (
           t.live_operator_rollover <- None;
           t.foreground_publication <- None;
           t.foreground_moderator <- None;
           t.notification_inputs <- None;
           t.active_cancel <- None)
       in
       let%map receipt =
         settle_context_rollover_internal
           ~batch
           ~after_commit_install
           ?checkpoint_history
           ~check_live_cut
           t
           ~check
           ~authorize_force
           ~id:intent.id
           expected
           (Publish { checkpoint; retain })
       in
       (match receipt.status with
        | Terminal (Committed _) -> S.Retire
        | Terminal (Superseded _) ->
          t.live_operator_rollover <- None;
          S.Continue
        | Pending -> S.Continue))
;;

let handle_recovery_rollover
  : type a. t -> a Recovery_rollover_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  let module P = Agent_protocol in
  let module R = Recovery_rollover in
  let open Result.Let_syntax in
  match request with
  | Native_remaining access ->
    let%bind _, _, operation_id = context_native_execution t ~access ~effect_kind:Remaining in
    let%map capacity = read_context_capacity t operation_id in
    Recovery_context_service.
      { window = active_rollover_window t; revision = t.state.counters.revision; capacity }
  | Native_new_window (access, window) ->
    let%bind _, execution, operation_id =
      context_native_execution t ~access ~effect_kind:New_window
    in
    let%bind preparation, expected =
      Result.of_option execution.context_rollover_basis
        ~error:(error Conflict "rollover has no captured foreground window")
    in
    let%bind () =
      if P.Id.Context_window.equal window (P.Recovery_window.Scope.window expected.scope)
      then Ok ()
      else Error (error Conflict "expected recovery window changed")
    in
    let check () =
      let%bind principal, current, operation =
        context_native_execution t ~access ~effect_kind:New_window
      in
      if phys_equal execution current
      then
        Ok (R.Requester.Native { principal; operation; invocation = current.dispatched.context.id })
      else Error (error Permission_denied "rollover invocation authority changed")
    in
    let check_basis () =
      let changed () = Error (error Conflict "rollover prepared window changed") in
      let%bind capacity = read_context_capacity t operation_id in
      match capacity with
      | Current _ ->
        let%bind target = Configuration_transition.target t.state in
        let current =
          Configuration_capture.native_window
            t.configuration_capture
            ~operation_id
            ~configuration_revision:t.state.spec.configuration_revision
            ~target
        in
        if
          Option.exists current
            ~f:(Configuration_capture.Native_window.same_preparation preparation)
          && Int64.equal t.state.counters.revision expected.revision
        then Ok ()
        else changed ()
      | Disabled | Stale_preparation _ | Awaiting_preparation _ -> changed ()
    in
    admit_recovery_rollover t ~check ~check_basis ~expected
  | Worker_settled (publication, live) -> settle_foreground_tool_batch t publication live
  | Operator_request (actor, attachment_id, authorize, force, key, expected) ->
    let operator () = rollover_operator t actor ~attachment_id ~authorize in
    let authorize_force =
      Option.map force ~f:(fun authorize_force state ->
        let%bind () = authorize_force state in
        let principal = Operator_authorization.principal actor in
        if Operator_authorization.is_current actor
        then require_recovery_owner_writer t ~principal:principal.id ~attachment_id
        else Error (error Permission_denied "rollover force authority expired"))
    in
    let check () =
      let%bind principal = operator () in
      let%map () =
        Option.value_map authorize_force ~default:(Ok ()) ~f:(fun check -> check t.state)
      in
      R.Requester.Operator { principal = principal.id; key; force = Option.is_some force }
    in
    let publication = t.foreground_publication in
    let after_admit (intent : R.Intent.t) =
      Option.iter publication ~f:(fun publication ->
        if foreground_publication_matches t publication
        then
          t.live_operator_rollover
          <- Some { id = intent.id; publication; check = operator; authorize_force })
    in
    admit_recovery_rollover ~after_admit t ~check ~expected
  | Operator_settle (actor, attachment_id, authorize, authorize_force, id, expected, settlement) ->
    let check () = rollover_operator t actor ~attachment_id ~authorize in
    let%map receipt =
      settle_context_rollover_internal t ~check ~authorize_force ~id expected settlement
    in
    (match receipt.status, t.live_operator_rollover with
     | Terminal _, Some owner when Agent_protocol.Id.Operation.equal owner.id id ->
       t.live_operator_rollover <- None
     | _ -> ());
    receipt
  | Operator_checkpoint (actor, attachment_id, authorize, expected, notes) ->
    let check () = rollover_operator t actor ~attachment_id ~authorize in
    record_context_checkpoint_internal t ~check expected notes
;;

let expire_recovery_window_internal t actor attachment_id authorize scope =
  let module P = Agent_protocol in
  let module L = Recovery_window_ledger in
  let open Result.Let_syntax in
  let check () =
    let principal = Operator_authorization.principal actor in
    let%bind () =
      if
        Operator_authorization.is_current actor
        && P.Principal.has_scope principal Manage_grants
        && P.Principal.has_scope principal Send_messages
      then authorize t.state
      else
        Error
          (error Permission_denied "recovery expiry requires a current source manager")
    in
    let%bind () =
      require_recovery_owner_writer t ~principal:principal.id ~attachment_id
    in
    let owner =
      Option.bind t.canonical_persistence ~f:(fun binding ->
        if Canonical_backend_binding_data.is_available binding
        then Canonical_backend_binding_data.session_owner binding
        else None)
    in
    if
      Option.exists owner ~f:(P.Session_ref.equal (P.Recovery_window.Scope.session scope))
      && Int.equal t.state.identity.generation (P.Recovery_window.Scope.generation scope)
    then Ok ()
    else Error (error Invalid_state "recovery expiry source is unavailable")
  in
  let%bind () = check () in
  let%bind ledger =
    Result.of_option
      t.state.recovery_windows
      ~error:(error Invalid_state "recovery windows are disabled")
  in
  let%bind window =
    List.find (L.windows ledger) ~f:(fun window ->
      P.Recovery_window.Scope.equal (L.Window.scope window) scope)
    |> Result.of_option ~error:(error Invalid_state "recovery window is unavailable")
  in
  match L.Window.state window with
  | Open -> Error (error Conflict "the active recovery window cannot expire")
  | Expired -> Ok ()
  | Sealed ->
    persist_recovery_delta
      t
      ~delta:(Recovery_window_expired scope)
      ~check_before_commit:check
;;

let handle_recovery_note
  : type a. t -> a Recovery_note_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  let module C = Recovery_notes.Catalog in
  let open Result.Let_syntax in
  let catalog ~access ~effect_kind =
    let%bind owner, _ = recovery_note_access t ~access ~effect_kind in
    Recovery_note_session.for_owner t.state.recovery_notes ~owner
  in
  match request with
  | Read (access, selection) ->
    let%bind catalog = catalog ~access ~effect_kind:Read in
    (match C.read catalog selection with
     | Ok content -> Ok content
     | Error Note_not_found -> Error (error Conflict "recovery note is unavailable")
     | Error (Stale_note_revision _) ->
       Error (error Conflict "recovery note revision changed"))
  | List access ->
    let%map catalog = catalog ~access ~effect_kind:List in
    C.revision catalog, C.list catalog
  | Query (access, query) ->
    let effect_kind = Recovery_note_access.Effect.of_query query in
    let%bind source, checked = recovery_note_access t ~access ~effect_kind in
    (match checked with
     | Operator _ ->
       Error
         (error Permission_denied "recovery note delivery requires a model invocation")
     | Native (invocation, _) ->
       let%bind catalog =
         Recovery_note_session.for_owner t.state.recovery_notes ~owner:source
       in
       prepare_recovery_note_delivery t ~source ~invocation catalog query)
  | Shared_operation access ->
    let%bind recipient, checked = recovery_note_access t ~access ~effect_kind:Read in
    (match checked with
     | Native
         ({ context = { origin = Model; call_entry_id = Some _; _ }; _ }, operation_id) ->
       Ok (recipient, operation_id)
     | Operator _ | Native _ -> Error (Recovery_note_share.unavailable ()))
  | Mutate (access, route, operation) ->
    let effect_kind = Recovery_note_access.Effect.of_mutation operation in
    let check () = recovery_note_mutation_identity t ~access ~effect_kind route in
    let%bind owner, identity = check () in
    let change = Recovery_note_change.create ~owner ~identity operation in
    let previous = t.state in
    let%bind outcome =
      Recovery_note_change.evaluate
        change
        ~previous:previous.recovery_notes
        ~session_id:previous.identity.session_id
    in
    (match outcome with
     | Replayed receipt -> Ok receipt
     | Applied (_, receipt) ->
       let check_before_commit () = Result.map (check ()) ~f:ignore in
       let%map () =
         persist_recovery_delta
           t
           ~delta:(Recovery_note_changed change)
           ~check_before_commit
       in
       receipt)
;;

let recovery_share_owner t ~check_owner ~publication =
  let module P = Agent_protocol in
  let open Result.Let_syntax in
  let unavailable () = Error (Recovery_note_share.unavailable ()) in
  if
    (not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)))
    || t.stopped
    || (publication && t.canonical_write_in_progress)
    || Option.is_some t.lifecycle_fence
    || Failed_startup_release_data.Gate.is_closed t.startup_disposal
  then unavailable ()
  else (
    let%bind () = check_owner () in
    let%bind binding =
      Result.of_option t.canonical_persistence ~error:(Recovery_note_share.unavailable ())
    in
    let%bind owner =
      if Canonical_backend_binding_data.is_available binding
      then
        Result.of_option
          (Canonical_backend_binding_data.session_owner binding)
          ~error:(Recovery_note_share.unavailable ())
      else unavailable ()
    in
    let%bind () = Recovery_note_session.check_owner t.state.recovery_notes ~owner in
    if
      Option.for_all t.state.recovery_note_shares ~f:(fun ledger ->
        P.Session_ref.equal owner (Recovery_note_share.owner ledger))
    then Ok owner
    else unavailable ())
;;

let recovery_share_incarnation t ~check_owner =
  let open Result.Let_syntax in
  let%bind _ = recovery_share_owner t ~check_owner ~publication:true in
  let%bind ledger =
    Result.of_option
      t.state.recovery_note_shares
      ~error:(Recovery_note_share.unavailable ())
  in
  Recovery_note_share.incarnation ledger ~generation:t.state.identity.generation
;;

let recovery_share_unavailable result =
  Result.map_error result ~f:(fun _ -> Recovery_note_share.unavailable ())
;;

let recovery_share_witness observe =
  let open Result.Let_syntax in
  let%map incarnation = observe () in
  let check_current () =
    let%bind current = observe () in
    if Recovery_note_share.Incarnation.equal incarnation current
    then Ok ()
    else Error (Recovery_note_share.unavailable ())
  in
  Recovery_note_share_request.{ incarnation; check_current }
;;

let recovery_share_management t ~access ~check_owner =
  let open Result.Let_syntax in
  let%bind owner = recovery_share_owner t ~check_owner ~publication:false in
  let%bind principal, attachment_id =
    Recovery_note_access.check_management access t.state ~owner
  in
  let%map () = require_recovery_owner_writer t ~principal ~attachment_id in
  owner, principal
;;

let recovery_share_new_ledger t ~owner =
  let nonce = Agent_protocol.Id.Session_incarnation.create () in
  let change = Recovery_note_share_change.establish ~owner ~nonce in
  let%map.Result ledger =
    Recovery_note_share_change.apply
      change
      ~previous:None
      ~catalog:t.state.recovery_notes
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
  in
  ledger, Session_delta.Recovery_note_share_changed change
;;

let recovery_share_mutate t ~access ~check_owner ~check_target ~check_fresh make_change =
  let module S = Recovery_note_share in
  let module Change = Recovery_note_share_change in
  let open Result.Let_syntax in
  let check () =
    let%bind owner, principal = recovery_share_management t ~access ~check_owner in
    let%map () = check_target () in
    owner, principal
  in
  let%bind owner, principal = check () in
  let%bind ledger, establishment =
    match t.state.recovery_note_shares with
    | Some ledger -> Ok (ledger, None)
    | None ->
      let%map ledger, delta = recovery_share_new_ledger t ~owner in
      ledger, Some delta
  in
  let%bind source = S.incarnation ledger ~generation:t.state.identity.generation in
  let change = make_change ~source ~principal ~now:(t.services.now ()) in
  let%bind outcome =
    Change.evaluate
      change
      ~previous:(Some ledger)
      ~catalog:t.state.recovery_notes
      ~session_id:t.state.identity.session_id
      ~generation:t.state.identity.generation
  in
  match outcome with
  | Established _ -> Error (error Invalid_state "invalid recovery note share transition")
  | Replayed receipt -> Ok receipt
  | Applied (_, receipt) ->
    let delta = Session_delta.Recovery_note_share_changed change in
    let delta =
      Option.value_map establishment ~default:delta ~f:(fun establish ->
        Session_delta.Batch [ establish; delta ])
    in
    let check_before_commit () =
      let%bind _ = check () in
      check_fresh ()
    in
    let%map () = persist_recovery_delta t ~delta ~check_before_commit in
    receipt
;;

let recovery_share_selection t ~check_owner ~reader ~reference =
  let module S = Recovery_note_share in
  let open Result.Let_syntax in
  let unavailable () = S.unavailable () in
  let%bind _ = recovery_share_owner t ~check_owner ~publication:true in
  let%bind () = reader.Recovery_note_share_request.check_current () in
  let%bind ledger =
    Result.of_option t.state.recovery_note_shares ~error:(unavailable ())
  in
  let%bind catalog = Result.of_option t.state.recovery_notes ~error:(unavailable ()) in
  let%map selection =
    S.resolve
      ledger
      ~source_generation:t.state.identity.generation
      ~recipient:reader.incarnation
      ~reference
      ~now:(t.services.now ())
  in
  catalog, selection
;;

let select_recovery_share t ~check_owner ~reader reference =
  let module C = Recovery_notes.Catalog in
  let open Result.Let_syntax in
  let resolve () =
    recovery_share_selection t ~check_owner ~reader ~reference
    |> recovery_share_unavailable
  in
  let%bind catalog, selection = resolve () in
  let%map _ = C.read catalog selection |> recovery_share_unavailable in
  let materialize () =
    let%bind catalog, selected = resolve () in
    if
      C.Note_id.equal selection.id selected.id
      && C.Note_revision.equal selection.revision selected.revision
    then C.read catalog selected |> recovery_share_unavailable
    else Error (Recovery_note_share.unavailable ())
  in
  Recovery_note_share_request.Disclosure materialize
;;

let handle_recovery_note_share
  : type a. t -> a Recovery_note_share_request.t -> (a, Agent_protocol.Error.t) result
  =
  fun t request ->
  let module S = Recovery_note_share in
  let open Result.Let_syntax in
  match request with
  | Management_revision (access, check_owner) ->
    let%map _ = recovery_share_management t ~access ~check_owner in
    Option.value_map
      t.state.recovery_note_shares
      ~default:S.Revision.initial
      ~f:S.revision
  | Establish_target check_owner ->
    let observe () = recovery_share_incarnation t ~check_owner in
    let%bind owner = recovery_share_owner t ~check_owner ~publication:false in
    let%bind () =
      match t.state.recovery_note_shares with
      | Some _ -> Ok ()
      | None ->
        let%bind _, delta = recovery_share_new_ledger t ~owner in
        let check_before_commit () =
          Result.map (recovery_share_owner t ~check_owner ~publication:false) ~f:ignore
        in
        persist_recovery_delta t ~delta ~check_before_commit
    in
    let%map witness = recovery_share_witness observe in
    Recovery_note_share_request.Target witness
  | Select (check_owner, Reader reader, reference) ->
    select_recovery_share t ~check_owner ~reader reference
  | Create (access, check_owner, Target target, key, request) ->
    let check_fresh () =
      if Agent_protocol.Timestamp.compare (t.services.now ()) request.expires_at < 0
      then Ok ()
      else Error (error Invalid_request "recovery note share expiry elapsed")
    in
    recovery_share_mutate
      t
      ~access
      ~check_owner
      ~check_target:target.check_current
      ~check_fresh
      (fun ~source ~principal ~now ->
         Recovery_note_share_change.create
           ~source
           ~recipient:target.incarnation
           ~principal
           ~key
           ~now
           request)
  | Revoke (access, check_owner, key, request) ->
    recovery_share_mutate
      t
      ~access
      ~check_owner
      ~check_target:(fun () -> Ok ())
      ~check_fresh:(fun () -> Ok ())
      (fun ~source ~principal ~now ->
         Recovery_note_share_change.revoke ~source ~principal ~key ~now request)
;;

let handle : type a. t -> a request -> (a, Agent_protocol.Error.t) result =
  fun t request ->
  if not (startup_disposal_request_allowed t request)
  then Error (error Conflict "failed startup Actor permits disposal only")
  else if
    match t.policy_restoration with
    | Native_constructing setup ->
      (not setup.closed) && not (native_setup_request_allowed request)
    | Constructing restoration ->
      (not restoration.closed) && not (policy_restoration_request_allowed request)
    | Vacant | Published _ -> false
  then Error (error Conflict "policy restoration owns runtime construction")
  else if Option.is_some t.lifecycle_fence && not (lifecycle_request_allowed request)
  then Error (error Conflict "session lifecycle is reserved")
  else (
    exclude_ordinary_deferred_ingress t request;
    match request with
    | Policy_restoration request -> policy_restoration_request t request
    | Native_goal request -> native_goal_request t request
    | Begin_lifecycle (attachment_id, generation, revision) ->
      begin_lifecycle t attachment_id generation revision
    | Lifecycle_state fence ->
      Result.map (check_lifecycle_fence t fence) ~f:(fun () -> t.state)
    | Retire_lifecycle fence ->
      Result.map (check_lifecycle_fence t fence) ~f:(fun () -> fence.phase <- Retiring)
    | Abort_lifecycle fence ->
      let open Result.Let_syntax in
      let%bind () = check_lifecycle_fence t fence in
      (match fence.phase with
       | Retiring -> Error (error Conflict "retired lifecycle owner cannot reopen")
       | Reserved ->
         t.lifecycle_fence <- None;
         Ok ())
    | Manage_moderator_follow_up (operation_id, observer) ->
      manage_moderator_follow_up t operation_id observer
    | Admit_moderator_turn operation_id -> admit_moderator_turn t operation_id
    | Admit_notification_turn operation_id -> admit_notification_turn t operation_id
    | Claim_delegated_event (capture, request, governance, id, delegation, snapshot, event)
      -> claim_delegated_event t capture request governance id delegation snapshot event
    | Claim_job_event (scope, id, snapshot, event) ->
      claim_job_event t scope id snapshot event
    | Claim_job_moderator (scope, invocation, captured) ->
      claim_job_moderator t scope invocation captured
    | Claim_ordinary_event (id, operation_id, snapshot, event) ->
      claim_ordinary_event t id operation_id snapshot event
    | Claim_queued_event (id, operation_id, snapshot) ->
      claim_queued_event t id operation_id snapshot
    | Claim_legacy_callback (callback, operation_id, installed) ->
      claim_legacy_callback t callback operation_id installed
    | Claim_initialization_callback (scope, manager, callback, installed) ->
      claim_initialization_callback t scope manager callback installed
    | Retire_initialization_resource (scope, manager) ->
      retire_initialization_resource t scope manager
    | Claim_queued_retirement (id, snapshot, reason) ->
      claim_queued_retirement t id snapshot reason
    | Commit_queued_event (borrow, snapshot, requests, decision, notifications) ->
      let open Result.Let_syntax in
      let%bind () = validate_queued_event_borrow t borrow in
      with_staged_transaction t (Moderator_event borrow.receipt.context.id) (fun () ->
        commit_queued_event t borrow snapshot requests decision notifications)
    | Reconcile_run_recovery ->
      let open Result.Let_syntax in
      let%bind delta =
        Goal_catalog_source.recovery_delta t.state ~now:(t.services.now ())
      in
      (match delta with
       | None -> Ok ()
       | Some delta -> transition t ~delta ~payloads:[] |> Result.map ~f:ignore)
    | Run_actions executing -> run_actions_internal t executing
    | Drain_delegated_policy_claim -> drain_delegated_policy_claim t
    | Finish_queued_event (Callback_returned (borrow, exit, completion_attempt)) ->
      Callback_retirement.finish ~completion_attempt t borrow exit
    | Finish_queued_event Retry_retained -> Callback_retirement.retry_retained t
    | Set_queued_event_cancel (borrow, cancel) ->
      Result.map (queued_event_can_commit t borrow) ~f:(fun () ->
        borrow.cancel <- Some cancel)
    | Commit_invocation_call (publication, invocation, entry) ->
      with_foreground_publication t publication (fun operation_id ~check ->
        commit_invocation_call t operation_id ~check invocation entry)
    | Claim_invocation (operation_id, invocation) ->
      claim_invocation t operation_id invocation
    | Claim_idle_invocation (borrow, invocation) ->
      claim_idle_invocation t borrow invocation
    | Claim_event_invocation (borrow, invocation) ->
      claim_event_invocation t borrow invocation
    | Claim_job_scope (id, generation, attempt, deadline) ->
      claim_job_scope t id generation attempt deadline
    | Claim_job_invocation (scope, invocation) ->
      (match t.moderator_borrow with
       | Some borrow
         when Option.exists borrow.job_scope ~f:(phys_equal scope)
              && Option.exists invocation.context.parent_invocation ~f:(fun parent ->
                Agent_protocol.Id.Invocation.equal parent borrow.invocation.context.id
                || List.exists t.invocation_executions ~f:(fun execution ->
                  invocation_execution_owned_by borrow execution
                  && Agent_protocol.Id.Invocation.equal
                       parent
                       execution.dispatched.context.id)) ->
         claim_idle_invocation t borrow invocation
       | _ -> claim_job_invocation t scope invocation)
    | Finish_job_scope scope -> finish_job_scope t scope
    | Seal_job_scope scope ->
      (match List.mem t.job_scopes scope ~equal:phys_equal with
       | false -> Error (error Conflict "background execution scope has ended")
       | true ->
         scope.active <- false;
         Atomic.set scope.authority_live false;
         scope.unfinished_on_return
         <- job_has_moderator t scope
            || List.exists t.invocation_executions ~f:(job_execution_owned_by scope);
         signal_job_scope scope;
         cancel_job_moderators t scope;
         Ok ())
    | Set_job_scope_cancel (scope, cancel) ->
      let open Result.Let_syntax in
      let%map () = job_scope_can_execute t scope in
      scope.cancel <- Some cancel
    | Finish_invocation (execution, outcome, requests, commit_starts, authoring_reference)
      ->
      let open Result.Let_syntax in
      let%bind () =
        match List.mem t.invocation_executions execution ~equal:phys_equal with
        | true -> Ok ()
        | false -> Error (error Conflict "invocation callback no longer owns its result")
      in
      with_staged_transaction t (Invocation execution.dispatched.context.id) (fun () ->
        match
          finish_invocation t execution outcome requests commit_starts authoring_reference
        with
        | Ok _ as result -> result
        | Error _ as failure ->
          Option.iter execution.native_goal ~f:(fun (entry, _) ->
            Goal_native_actions.Entry.discard_speculative entry);
          failure
        | exception exn ->
          let backtrace = Stdlib.Printexc.get_raw_backtrace () in
          Option.iter execution.native_goal ~f:(fun (entry, _) ->
            Goal_native_actions.Entry.discard_speculative entry);
          Stdlib.Printexc.raise_with_backtrace exn backtrace)
    | Claim_moderator_invocation (operation_id, invocation, captured) ->
      claim_moderator_invocation t operation_id invocation captured
    | Claim_moderator_observation (operation_id, invocation_id) ->
      claim_moderator_observation t (Some operation_id) invocation_id
    | Claim_next_moderator_observation (operation_id, observer) ->
      claim_next_moderator_observation t (Some operation_id) observer
    | Claim_idle_moderator_observation (observer, tools) ->
      if idle_moderator_eligible t
      then
        Result.map (claim_next_moderator_observation t None observer) ~f:(fun borrow ->
          Option.iter borrow ~f:(fun borrow -> borrow.accepts_children <- tools);
          borrow)
      else Ok None
    | Commit_moderator_invocation (borrow, resolved, snapshot) ->
      let open Result.Let_syntax in
      let%bind () = validate_moderator_borrow t borrow in
      with_staged_transaction t (Invocation borrow.invocation.context.id) (fun () ->
        commit_moderator_invocation t borrow resolved snapshot)
    | Finish_moderator_invocation (borrow, failure) ->
      finish_moderator_invocation t borrow failure
    | Set_idle_moderator_cancel (borrow, cancel) ->
      let open Result.Let_syntax in
      let%bind () = validate_moderator_borrow t borrow in
      (match
         ( borrow.job_scope
         , borrow.operation_id
         , t.state.lifecycle.desired
         , t.state.lifecycle.observed )
       with
       | Some scope, None, _, _ ->
         let%map () = job_scope_can_execute t scope in
         borrow.cancel <- Some cancel
       | None, None, Running, Idle ->
         borrow.cancel <- Some cancel;
         Ok ()
       | _ ->
         Error (error Conflict "idle observation was stopped before callback execution"))
    | Commit_extensions (generation, revision, changes) ->
      commit_extensions_internal t generation revision changes
    | State -> Ok t.state
    | Observe_resource_state -> Resource_observation.capture t
    | Prepare_ingress_submission
        (source, producer, registration_id, namespace, key, payload) ->
      prepare_ingress_submission_internal
        t
        source
        producer
        registration_id
        namespace
        key
        payload
    | Commit_ingress_submission (proposal, before, snapshot) ->
      commit_ingress_submission_internal t proposal before snapshot
    | Due_schedules -> due_schedules t
    | Read_job id -> Result.map (find_job t id) ~f:(job_with_progress t)
    | Publish_job_progress (id, progress) ->
      publish_job_progress_internal t id progress;
      Ok ()
    | Prepare_background_job (owner, request) -> prepare_background_job t owner request
    | Stage_background_job (job, capacity) -> stage_background_job_internal t job capacity
    | Stage_subscription_mutation (owner, source, previous, next) ->
      stage_subscription_mutation_internal t owner source previous next
    | Create_script_subscription
        (owner, source, kind, lifetime_ms, wake, completion_schema) ->
      create_script_subscription_internal
        t
        owner
        source
        kind
        lifetime_ms
        wake
        completion_schema
    | Select_subscription_mutations (owner, source, receipts) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      Staged_subscriptions.select
        t.staged_subscriptions
        ~owner
        ~receipts
        ~lookup:(lookup_subscription t)
    | Abort_subscription_mutation (owner, receipt) ->
      let open Result.Let_syntax in
      let%map () = Staged_subscriptions.abort t.staged_subscriptions ~owner ~receipt in
      sync_extension_clock t
    | Finish_script_subscription (owner, source, id, expected_epoch, completion) ->
      finish_script_subscription_internal t owner source id expected_epoch completion
    | Read_script_subscription (owner, source, id) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      let%bind subscription =
        Result.of_option
          (provisional_subscription t owner id)
          ~error:(error Invalid_state "subscription is not retained")
      in
      let%map () = subscription_owned t source subscription in
      subscription
    | Expire_subscriptions -> expire_subscriptions_internal t
    | Create_script_ingress (owner, source, id, epoch, namespace, schema) ->
      create_script_ingress_internal t owner source id epoch namespace schema
    | Revoke_script_ingress (owner, source, id, reason) ->
      revoke_script_ingress_internal t owner source id reason
    | Read_script_ingress (owner, source, id) ->
      read_script_ingress_internal t owner source id
    | Abort_ingress_mutation (owner, receipt) ->
      let open Result.Let_syntax in
      let%map () = Staged_ingress.abort t.staged_ingress ~owner ~receipt in
      Ingress_creator_custody.Staged.abort t.staged_ingress_custody ~owner ~receipt
    | Select_ingress_mutations (owner, source, receipts) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      Staged_ingress.select
        t.staged_ingress
        ~owner
        ~receipts
        ~lookup:(lookup_ingress t)
        ~subscription:
          (ingress_subscription_lookup
             t
             (Staged_subscriptions.values t.staged_subscriptions))
    | Create_script_notification
        (owner, source, correlation, completion, wake, disclosure_pins) ->
      create_script_notification_internal
        t
        owner
        source
        correlation
        completion
        wake
        disclosure_pins
    | Read_script_notification (owner, source, id) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      let%bind value =
        Result.of_option
          (provisional_notification t owner id)
          ~error:(error Invalid_state "notification is not retained")
      in
      let%map () = notification_owned t source value in
      value
    | Select_notification_mutations (owner, source, receipts) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      Staged_notifications.select
        t.staged_notifications
        ~owner
        ~receipts
        ~lookup:(lookup_notification t)
    | Abort_notification_mutation (owner, receipt) ->
      Staged_notifications.abort t.staged_notifications ~owner ~receipt
    | Stage_schedule_mutation (owner, source, previous, next) ->
      stage_schedule_mutation_internal t owner source previous next
    | Create_script_schedule (owner, source, delay_ms, payload, misfire) ->
      create_script_schedule_internal t owner source delay_ms payload misfire
    | Select_schedule_mutations (owner, source, receipts) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      Staged_schedules.select t.staged_schedules ~owner ~receipts ~lookup:(fun id ->
        List.find t.state.schedules ~f:(fun value ->
          Agent_protocol.Id.Schedule.equal value.id id))
    | Abort_schedule_mutation (owner, receipt) ->
      let open Result.Let_syntax in
      let%map () = Staged_schedules.abort t.staged_schedules ~owner ~receipt in
      Legacy_schedule_custody.Staged.abort t.staged_schedule_custody ~owner ~receipt;
      sync_extension_clock t
    | Read_script_schedule (owner, source, id) ->
      let open Result.Let_syntax in
      let%bind _ = subscription_owner_active t owner source in
      let%bind value =
        Result.of_option
          (provisional_schedule t owner id)
          ~error:(error Invalid_state "schedule is not retained")
      in
      let%map () = schedule_owned t source value in
      value
    | Select_background_jobs (owner, ids) ->
      let open Result.Let_syntax in
      let%bind () = background_owner_active t owner in
      Staged_jobs.select t.staged_jobs ~owner ~ids
    | Abort_background_job (owner, id) -> Staged_jobs.abort t.staged_jobs ~owner ~id
    | Has_staged_background_job (owner, id) ->
      let open Result.Let_syntax in
      let%map () = background_owner_active t owner in
      Staged_jobs.contains t.staged_jobs ~owner ~id
    | Read_script_job (owner, id) ->
      let open Result.Let_syntax in
      let%bind () = background_owner_active t owner in
      let%bind staged = Staged_jobs.find t.staged_jobs ~owner ~id in
      (match staged with
       | Some job -> Ok job
       | None ->
         let%bind job = find_job t id in
         let%map () = validate_job_generation t job t.state.identity.generation in
         job_with_progress t job)
    | Read_script_job_result (owner, expected) ->
      let open Result.Let_syntax in
      let%bind () = background_owner_active t owner in
      let%bind job = find_job t expected.id in
      let%bind () = validate_job_generation t job t.state.identity.generation in
      let%bind () =
        match
          Jsonaf.exactly_equal
            (Agent_protocol.Job.to_json job)
            (Agent_protocol.Job.to_json expected)
        with
        | true -> Ok ()
        | false -> Error (error Conflict "job changed before artifact materialization")
      in
      let load_artifact =
        Option.map t.services.job_results ~f:(fun publisher ->
          Agent_store.Job_result_store.Publisher.load publisher)
      in
      let%bind completion = Agent_protocol.Job.terminal_completion ?load_artifact job in
      Result.of_option
        completion
        ~error:(error Invalid_state "job has no terminal completion")
    | Cancel_script_job (owner, id) ->
      let open Result.Let_syntax in
      let%bind () = background_owner_active t owner in
      let%bind staged =
        Staged_jobs.cancel t.staged_jobs ~owner ~id ~now:(t.services.now ())
      in
      (match staged with
       | Some _ -> Ok ()
       | None ->
         let%bind job = find_job t id in
         let%bind () = validate_job_generation t job t.state.identity.generation in
         Result.map (cancel_job_internal t id) ~f:ignore)
    | Configuration -> configuration_view t
    | Set_organization_admission admission ->
      t.organization_admission <- Some admission;
      Ok ()
    | Set_configuration_policy policy ->
      t.configuration_policy <- Some policy;
      Ok ()
    | Context_request (Capacity (Set_host host)) ->
      t.context_capacity_host <- host;
      Ok ()
    | Context_request (Capacity (Read operation_id)) ->
      read_context_capacity t operation_id
    | Prepare_configuration_update request -> prepare_configuration_update t request
    | Commit_configuration_update validated -> commit_configuration_update t validated
    | Begin_configuration_capture operation_id ->
      begin_configuration_capture t operation_id
    | Mark_configuration_capture (capture, configuration) ->
      mark_configuration_capture t capture configuration
    | Context_request (Capacity (Publish (capture, observation))) ->
      mark_context_capacity t capture observation
    | Context_request (Recovery_effective (capture, input, configuration, binding_is_current)) ->
      capture_recovery_preparation t capture input ~configuration ~binding_is_current
    | Finish_configuration_capture (capture, success) ->
      finish_configuration_capture t capture success
    | Snapshot -> Ok (current_snapshot t)
    | Observe -> Ok (t.state, current_snapshot t)
    | Set_operation_worker worker ->
      let%bind.Result () =
        Option.value_map worker ~default:(Ok ()) ~f:(fun _ ->
          require_selected_execution t)
      in
      set_operation_worker t worker
    | Set_runtime_worker
        ( original_actor
        , initial_startup
        , worker
        , inference
        , moderator_manager
        , expected_ordinary
        , unmoderated_source ) ->
      let open Result.Let_syntax in
      let%bind () =
        Option.value_map worker ~default:(Ok ()) ~f:(fun _ ->
          require_selected_execution t)
      in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor when Operator_authorization.is_current actor -> Ok ()
        | Some _ ->
          Error (error Permission_denied "runtime installation authentication expired")
      in
      let%bind () =
        Option.value_map expected_ordinary ~default:(Ok ()) ~f:(fun expected ->
          let%bind () = require_runtime_admission t in
          Ordinary_runtime_basis.check expected t.state)
      in
      set_runtime_worker
        ?unmoderated_source
        ?original_actor
        ?initial_startup
        t
        worker
        inference
        moderator_manager
    | Check_runtime_admission continuation ->
      let open Result.Let_syntax in
      let%bind () = require_runtime_admission t in
      (match continuation with
       | None -> require_selected_execution t
       | Some continuation -> held_runtime_installation_basis t continuation)
    | Runtime_retirement (Release_failed_startup request) ->
      release_failed_startup_custody_internal t request
    | Runtime_retirement (Retire_worker closing) -> retire_runtime_worker t ~closing
    | Runtime_retirement (Capture_cleanup closing) ->
      retire_runtime_worker_with_cleanup_internal t ~closing
    | Runtime_retirement (Advance_cleanup step) -> runtime_retirement_cleanup_step t step
    | Set_compaction_inference port ->
      t.compaction_inference <- port;
      Ok ()
    | Enable_automatic_turn_budget (original_actor, policy) ->
      let open Result.Let_syntax in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor when Operator_authorization.is_current actor -> Ok ()
        | Some _ -> Error (error Permission_denied "turn budget authentication expired")
      in
      enable_automatic_turn_budget t policy
    | Enable_run_constructor_turn_budget (preparation, policy) ->
      enable_automatic_turn_budget ~run_preparation:preparation t policy
    | Set_automatic_turn_pauses conditions ->
      (match
         t.state.active_operation, moderator_is_borrowed t, t.idle_moderator_borrowed
       with
       | None, false, false ->
         let open Result.Let_syntax in
         let%bind budget =
           t.state.automatic_turn_budget
           |> Result.of_option
                ~error:(error Invalid_state "automatic-turn policy is not enabled")
         in
         let next = Automatic_turn_budget.with_pauses budget conditions in
         (match Automatic_turn_budget.equal budget next with
          | true -> Ok ()
          | false ->
            transition
              t
              ~delta:
                (Session_delta.Automatic_turn_pauses_changed
                   next.policy.budget.pause_conditions)
              ~payloads:[]
            |> Result.map ~f:ignore)
       | _ ->
         Error
           (error Conflict "pause changes wait for active moderator or foreground work"))
    | Change_moderator (original_actor, moderator) ->
      let open Result.Let_syntax in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor when Operator_authorization.is_current actor -> Ok ()
        | Some _ ->
          Error (error Permission_denied "moderator checkpoint authentication expired")
      in
      change_moderator t moderator
    | Change_workspace workspace -> change_workspace t workspace
    | Shell_approval_grants -> Ok t.state.shell.approval_grants
    | Replace_shell_approval_grants (run_preparation, approval_grants) ->
      replace_shell_approval_grants ?run_preparation t approval_grants
    | Replace_shell_extension_snapshots (run_preparation, extension_snapshots) ->
      replace_shell_extension_snapshots ?run_preparation t extension_snapshots
    | Shell_manifest_grants -> Ok t.state.shell.manifest_grants
    | Add_shell_manifest_grant (run_preparation, grant) ->
      add_shell_manifest_grant ?run_preparation t grant
    | Reset (attachment_id, expected_revision, options) ->
      reset_internal t attachment_id expected_revision options
    | Upgrade_prompt (attachment_id, expected_revision, target_revision) ->
      upgrade_prompt_internal t attachment_id expected_revision target_revision
    | Commit_administration (attachment_id, expected_revision, kind, state) ->
      commit_administration t attachment_id expected_revision kind state
    | Validate_administration_basis (attachment_id, expected) ->
      validate_administration_basis t attachment_id expected
    | Commit_reconciled_administration (attachment_id, expected, kind, candidate) ->
      commit_reconciled_administration t attachment_id expected kind candidate
    | Begin_initialization (purpose, original_actor, expected) ->
      let open Result.Let_syntax in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor ->
          if Operator_authorization.is_current actor
          then Ok ()
          else Error (error Permission_denied "initialization authentication expired")
      in
      begin_initialization ?original_actor ~purpose t expected
    | Borrow_initialization_agent_actor scope ->
      let open Result.Let_syntax in
      let%bind () = validate_initialization_scope t scope in
      let%bind custody = custody_of_admission (Some scope.agent_admission) in
      (match custody with
       | None -> Ok None
       | Some custody -> Result.map (Execution_custody.actor custody) ~f:Option.some)
    | Borrow_operation_agent_actor id ->
      let open Result.Let_syntax in
      let%bind _ = running_operation t id in
      operation_agent_actor t id
    | Borrow_compaction_agent_actor operation ->
      let open Result.Let_syntax in
      let%bind _ = running_compaction t operation in
      operation_agent_actor t operation.id
    | Borrow_invocation_agent_actor (execution, invocation) ->
      invocation_agent_actor t execution invocation
    | Borrow_moderator_agent_actor (borrow, invocation) ->
      let open Result.Let_syntax in
      let%bind () = check_moderator_effect_current t borrow invocation in
      let%bind custody = moderator_agent_custody t borrow in
      (match custody with
       | None -> Ok None
       | Some custody ->
         Result.map (Execution_custody.actor custody) ~f:(fun actor ->
           Some
             (Operator_authorization.restrict
                actor
                ~is_current:(fun () ->
                  Result.is_ok (check_moderator_effect_current t borrow invocation)))))
    | Begin_run_initialization (purpose, preparation, expected) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      begin_initialization
        ~run_preparation:preparation
        ?original_actor:(Run_preparation.original_actor preparation)
        ~purpose
        t
        expected
    | End_initialization scope -> end_initialization t scope
    | Goal_request (Initialization_completion scope) ->
      initialization_goal_completion_internal t scope
    | Complete_initialization (scope, candidate, moderator_manager, installed_originals)
      -> complete_initialization t scope candidate moderator_manager installed_originals
    | Checkpoint_runtime_construction (scope, moderator, moderator_manager) ->
      checkpoint_runtime_construction t scope moderator moderator_manager
    | Fail_initialization (scope, failure) -> fail_initialization t scope failure
    | Start (original_actor, attachment_id, expected_parent_stop_epoch) ->
      let open Result.Let_syntax in
      let%bind () =
        match original_actor with
        | None -> Ok ()
        | Some actor when Operator_authorization.is_current actor -> Ok ()
        | Some _ -> Error (error Permission_denied "start authentication expired")
      in
      with_writer t attachment_id (fun () ->
        let%bind source = Runtime_builder.moderator_snapshot_observer t.state.moderator in
        let%map summary = start_internal ?expected_parent_stop_epoch t in
        (match t.lifecycle_agent_custody with
         | Admitted _ -> ()
         | Unadmitted ->
           t.lifecycle_agent_custody
           <- Admitted
                { generation = t.state.identity.generation
                ; source
                ; pending =
                    Pending
                      (create_agent_admission
                         (Option.map original_actor ~f:create_agent_custody))
                });
        summary)
    | Start_initial_delegated (reference, expected_parent_stop_epoch) ->
      (match t.state.spec.delegation with
       | Some current
         when Agent_store.Delegation_store.Reference.equal current reference
              && Agent_protocol.Id.Session.equal
                   reference.child_session_id
                   t.state.identity.session_id ->
         (match t.state.pending_initial_start with
          | true -> start_internal ?expected_parent_stop_epoch t
          | false -> Ok (Session_state.summary t.state))
       | _ ->
         Error
           (error Permission_denied "delegation.start: child relationship does not match"))
    | Fail_initial_delegated (reference, failure) ->
      (match t.state.spec.delegation with
       | Some current
         when Agent_store.Delegation_store.Reference.equal current reference
              && Agent_protocol.Id.Session.equal
                   reference.child_session_id
                   t.state.identity.session_id ->
         (match t.state.pending_initial_start with
          | false -> Ok (Session_state.summary t.state)
          | true ->
            let open Result.Let_syntax in
            let%map _ =
              transition
                t
                ~delta:
                  (Batch
                     [ Initial_start_consumed
                     ; Lifecycle_changed { desired = Stopped; observed = Failed failure }
                     ; Failure_changed (Some failure)
                     ])
                ~payloads:
                  [ Session_state_changed
                      { desired_state = Stopped; observed_state = Failed failure }
                  ]
            in
            Session_state.summary t.state)
       | _ ->
         Error
           (error Permission_denied "delegation.start: child relationship does not match"))
    | Queue_start attachment_id ->
      with_writer t attachment_id (fun () -> queue_start_internal t)
    | Activate_queued_start -> activate_queued_start t
    | Update_organization (principal, request) ->
      with_writer t request.attachment_id (fun () ->
        let open Result.Let_syntax in
        let%bind admission =
          Result.of_option
            t.organization_admission
            ~error:(error Invalid_state "organization admission is not configured")
        in
        let%bind plan =
          Session_organization_transition.create
            t.state
            ~expected_metadata_revision:request.expected_metadata_revision
            ~patch:request.patch
        in
        let delta = Session_organization_transition.delta plan in
        let%bind candidate = Session_delta.apply t.state delta in
        let payloads =
          if Session_organization_transition.changed plan
          then
            [ Agent_protocol.Event.Durable.Payload.Session_updated
                (Session_state.summary candidate)
            ]
          else []
        in
        let%bind transition = prepare_transition t ~delta ~payloads in
        let%bind () =
          Eio.Cancel.protect (fun () ->
            let%map () =
              Session_organization_admission.persist
                admission
                ~principal
                ~host_id:request.host_id
                ~additions:(Session_organization_transition.additions plan)
                ~commit:(fun () -> persist_transition t transition)
            in
            install_committed_transition t transition;
            publish_committed_transition t transition)
        in
        Ok (Session_state.summary t.state))
    | Set_recurrence_controller controller ->
      if
        not
          (Agent_protocol.Id.Session.equal
             (Agent_protocol.Session_ref.session_id
                (Recurrence_controller.session controller))
             t.state.identity.session_id)
      then Error (error Invalid_request "recurrence controller belongs to another actor")
      else (
        match t.recurrence_controller with
        | Some _ -> Error (error Conflict "recurrence controller is already installed")
        | None ->
          t.recurrence_controller <- Some controller;
          Ok ())
    | Pause_invalid_recurrence_target
        (actor, authorize, definition, expected_control_revision, evidence) ->
      pause_invalid_recurrence_target_internal
        t
        ~actor
        ~authorize
        ~definition
        ~expected_control_revision
        ~evidence
    | Reserve_recurrence_child (actor, authorize, occurrence, expected_control_revision)
      ->
      let open Result.Let_syntax in
      let%bind () = require_runtime_admission t in
      let%bind controller = require_recurrence_controller t in
      let prepare () =
        Recurrence_creation_admission.prepare
          t.state
          ~controller
          ~actor
          ~authorize
          ~occurrence
          ~expected_control_revision
      in
      let%bind prepared = prepare () in
      let%bind () = check_recurrence_creation_admission t prepared in
      let catalog =
        Option.value t.state.recurrence_catalog ~default:Recurrence_catalog.empty
      in
      let child_session_id, transaction_id =
        match Recurrence_creation_admission.reservation prepared with
        | Some row ->
          ( Recurrence_child_reservation.child_session_id row
          , Recurrence_child_reservation.transaction_id row )
        | None ->
          Agent_protocol.Id.Session.create (), Agent_protocol.Id.Transaction.create ()
      in
      let%bind next, reservation =
        Recurrence_catalog.reserve_child
          catalog
          ~recurrence_id:
            (Recurrence_entry.id (Recurrence_creation_admission.entry prepared))
          ~principal_id:(Operator_authorization.principal actor).id
          ~child_session_id
          ~transaction_id
          ~occurrence
      in
      let%bind () =
        if
          Int64.equal
            (Recurrence_catalog.revision next)
            (Recurrence_catalog.revision catalog)
        then Ok ()
        else (
          let%bind candidate =
            prepare_transition
              t
              ~delta:(Session_delta.Recurrence_catalog_changed next)
              ~payloads:[]
          in
          let%bind () = check_recurrence_creation_admission t prepared in
          let definition =
            Recurrence_entry.current (Recurrence_creation_admission.entry prepared)
          in
          let check_before_commit =
            match Recurrence_definition.goal_binding definition with
            | Unbound -> None
            | Controller_goal _ ->
              Some (fun () -> check_recurrence_creation_admission t prepared)
          in
          let%bind () = persist_transition ?check_before_commit t candidate in
          install_committed_transition t candidate;
          publish_committed_transition t candidate;
          Ok ())
      in
      let%bind refreshed = prepare () in
      let%bind () = check_recurrence_creation_admission t refreshed in
      let%bind () =
        match Recurrence_creation_admission.reservation refreshed with
        | Some row when Recurrence_child_reservation.equal row reservation -> Ok ()
        | None | Some _ ->
          Error (error Conflict "committed creation reservation changed before permit")
      in
      let permit : Recurrence_creation.t =
        { owner = t.recurrence_creation_owner; actor; authorize; reservation }
      in
      Ok permit
    | Recurrence_check (Creation permit) -> refresh_recurrence_creation t permit
    | Record_recurrence_execution (actor, authorize, intent, attempt) ->
      record_recurrence_execution_internal t ~actor ~authorize ~intent ~attempt
    | Record_prepared_recurrence_execution (binding, actor, authorize, intent, attempt) ->
      record_recurrence_execution_internal ~binding t ~actor ~authorize ~intent ~attempt
    | Observe_recurrence_run (actor, authorize, intent, attempt) ->
      observe_recurrence_run_internal t ~actor ~authorize ~intent ~attempt
    | Import_recurrence_execution (actor, authorize, automatic_policy, observation) ->
      import_recurrence_execution_internal
        t
        ~actor
        ~authorize
        ~automatic_policy
        ~observation
    | Import_held_recurrence_execution
        (held, actor, authorize, automatic_policy, observation) ->
      import_recurrence_execution_internal
        ~held
        t
        ~actor
        ~authorize
        ~automatic_policy
        ~observation
    | Acquire_recurrence_activation (actor, authorize, observation) ->
      acquire_recurrence_activation_internal t ~actor ~authorize ~observation
    | Recurrence_check (Activation (custody, observation)) ->
      check_recurrence_activation_internal t custody observation
    | Release_recurrence_activation custody ->
      if Activation_custody.belongs_to custody ~owner:t.recurrence_activation_owner
      then (
        Activation_custody.release_original custody;
        t.recurrence_activations
        <- List.filter t.recurrence_activations ~f:Activation_custody.is_live;
        Ok ())
      else Error (error Conflict "activation custody belongs to another actor")
    | Verify_recurrence_child reservation -> observe_recurrence_child t reservation
    | Link_recurrence_child (permit, child, max_children, max_encoded_bytes) ->
      let open Result.Let_syntax in
      let%bind checked = refresh_recurrence_creation t permit in
      let%bind controller = require_recurrence_controller t in
      let%bind () =
        if
          Recurrence_controller.same_store
            controller
            child.Recurrence_child_link.controller
        then Ok ()
        else Error (error Conflict "recurrence child belongs to another Store")
      in
      let association = child.Recurrence_child_link.association in
      let%bind () =
        Recurrence_child_association.validate
          association
          ~reservation:permit.Recurrence_creation.reservation
      in
      let%bind catalog =
        Result.of_option
          t.state.recurrence_catalog
          ~error:(error Conflict "recurrence parent lost its catalog")
      in
      let%bind next = Recurrence_catalog.link_child catalog association in
      let%bind children =
        Child_accounting.register
          t.state
          ~reference:(Recurrence_child_association.reference association)
          ~max_children
          ~max_encoded_bytes
      in
      let%bind children_changed = child_contributions_changed t.state children in
      let catalog_changed =
        not
          (Int64.equal
             (Recurrence_catalog.revision next)
             (Recurrence_catalog.revision catalog))
      in
      let check () =
        let%bind () = Recurrence_creation.Checked.check_current checked in
        let%bind () = child.check_current () in
        Recurrence_creation.Checked.check_current checked
      in
      let%bind () = check () in
      let%bind () =
        if (not catalog_changed) && not children_changed
        then Ok ()
        else (
          let delta =
            Session_delta.Batch
              ((if catalog_changed
                then [ Session_delta.Recurrence_catalog_changed next ]
                else [])
               @
               if children_changed
               then [ Session_delta.Child_contributions_changed children ]
               else [])
          in
          let%bind transition = prepare_transition t ~delta ~payloads:[] in
          let%bind () = check () in
          let%bind () = persist_transition t transition in
          install_committed_transition t transition;
          publish_committed_transition t transition;
          Ok ())
      in
      Ok association
    | Recurrence_read (Definitions (actor, authorize)) ->
      let open Result.Let_syntax in
      let%bind controller = require_recurrence_controller t in
      Recurrence_command_admission.read t.state ~controller ~actor ~authorize
    | Recurrence_read (Query (actor, authorize, request)) ->
      let open Result.Let_syntax in
      let%bind () = Recurrence_command_admission.check_read actor ~authorize t.state in
      let%bind controller = require_recurrence_controller t in
      let%bind planning =
        Recurrence_runtime.status t.recurrence_runtime ~state:t.state ~controller
      in
      let%map snapshot =
        Recurrence_query.read t.state ~controller ~actor ~authorize ~planning ~request
      in
      t.state, snapshot
    | Recurrence_read (Planning (actor, authorize)) ->
      let open Result.Let_syntax in
      let%bind () = Recurrence_command_admission.check_read actor ~authorize t.state in
      let%bind controller = require_recurrence_controller t in
      let%bind planning =
        Recurrence_runtime.status t.recurrence_runtime ~state:t.state ~controller
      in
      (* Status observation may yield. The existing metadata reader repeats the
         original read policy and genuine Current checks before disclosure. *)
      let%map entries =
        Recurrence_command_admission.read t.state ~controller ~actor ~authorize
      in
      Recurrence_planning_read.{ entries; planning }
    | Set_recurrence_planning_host host ->
      let open Result.Let_syntax in
      let%bind (_ : Recurrence_controller.t) = require_recurrence_controller t in
      Recurrence_runtime.set_host t.recurrence_runtime host
    | Recurrence_due_ids ->
      if runtime_admission_open t then Ok (Recurrence_runtime.ids t.state) else Ok []
    | Begin_recurrence_due recurrence_id ->
      let open Result.Let_syntax in
      if not (runtime_admission_open t)
      then Error (error Conflict "recurrence runtime admission is closed")
      else (
        let%bind controller = require_recurrence_controller t in
        let%bind () = reconcile_recurrences_internal t in
        let%bind snapshot =
          Recurrence_runtime.snapshot
            t.recurrence_runtime
            ~wall:(t.services.now ())
            ~monotonic:(t.services.monotonic_now ())
        in
        Recurrence_runtime.begin_due
          t.recurrence_runtime
          ~state:t.state
          ~controller
          ~recurrence_id
          ~snapshot)
    | Finish_recurrence_due prepared ->
      let open Result.Let_syntax in
      if not (runtime_admission_open t)
      then Error (error Conflict "recurrence runtime admission is closed")
      else (
        let%bind controller = require_recurrence_controller t in
        let%bind validation =
          Recurrence_runtime.validate
            t.recurrence_runtime
            prepared
            ~state:t.state
            ~controller
        in
        let%bind candidate =
          match Recurrence_runtime.delta validation with
          | None -> Ok None
          | Some delta ->
            prepare_transition t ~delta ~payloads:[] |> Result.map ~f:Option.some
        in
        let%bind () =
          Recurrence_runtime.check_current t.recurrence_runtime validation ~state:t.state
        in
        let%bind () =
          if runtime_admission_open t
          then Ok ()
          else Error (error Conflict "recurrence runtime admission closed before commit")
        in
        match candidate with
        | None ->
          Recurrence_runtime.install_phase t.recurrence_runtime validation ~state:t.state;
          Ok ()
        | Some candidate ->
          let%bind () = persist_transition t candidate in
          install_committed_transition t candidate;
          Recurrence_runtime.install_phase t.recurrence_runtime validation ~state:t.state;
          publish_committed_transition t candidate;
          Ok ())
    | Release_recurrence_due preparation ->
      Recurrence_runtime.release t.recurrence_runtime preparation;
      Ok ()
    | Apply_recurrence_command (actor, authorize, request, native) ->
      let open Result.Let_syntax in
      let authorize state =
        let%bind () =
          Option.value_map native ~default:(Ok ()) ~f:(fun native ->
            Recurrence_native_admission.check_now
              native.Recurrence_native_publication.admission
              state
              ~effect_kind:(Recurrence_native_admission.effect_kind native.admission))
        in
        authorize state
      in
      let%bind () = Recurrence_command_admission.check_write actor ~authorize t.state in
      let%bind controller = require_recurrence_controller t in
      (* Reconciliation is an independently durable safety change. If it changes
         CAS, the original command must be retried with fresh expectations. *)
      let%bind () =
        let retained =
          Option.bind t.state.recurrence_catalog ~f:(fun catalog ->
            Recurrence_catalog.find_receipt
              catalog
              ~principal_id:(Operator_authorization.principal actor).id
              ~key:request.key)
        in
        if
          Recurrence_command.Mutation.needs_source request.mutation
          && Option.is_none retained
        then reconcile_recurrences_internal t
        else Ok ()
      in
      let basis = t.state in
      let native_selection =
        Option.map native ~f:(fun native () ->
          match native.Recurrence_native_publication.selection with
          | Some selection -> selection ()
          | None ->
            Error (error Conflict "fresh native recurrence lacks its original selection"))
      in
      let run_preparation =
        Option.bind native ~f:(fun native ->
          native.Recurrence_native_publication.preparation)
      in
      let%bind prepared =
        Recurrence_command_admission.prepare
          ?native:native_selection
          basis
          ~controller
          ~actor
          ~authorize
          ~request
          ~now:(t.services.now ())
      in
      let%bind () = Recurrence_command_admission.check_write actor ~authorize t.state in
      let%bind () = Recurrence_command_admission.check_current prepared in
      let check_before_commit () =
        let now = t.services.now () in
        let%bind () =
          if not (phys_equal basis t.state)
          then Error (error Conflict "recurrence command basis changed")
          else if
            Recurrence_command_admission.checks_goal prepared || Option.is_some native
          then require_runtime_admission t
          else Ok ()
        in
        let%bind () =
          Option.value_map
            (Option.bind native ~f:(fun native ->
               native.Recurrence_native_publication.selection))
            ~default:(Ok ())
            ~f:(fun select -> Result.map (select ()) ~f:ignore)
        in
        let%bind () = Recurrence_command_admission.check_goal prepared t.state ~now in
        let%bind () = Recurrence_command_admission.check_write actor ~authorize t.state in
        Recurrence_command_admission.check_current prepared
      in
      let%map () =
        match Recurrence_command_admission.delta prepared with
        | None -> Ok ()
        | Some delta ->
          let%bind candidate =
            prepare_transition ?run_preparation t ~delta ~payloads:[]
          in
          let previous = t.state in
          let%bind adoption =
            if Recurrence_runtime.needs_adoption ~previous ~current:candidate.state
            then
              Recurrence_runtime.snapshot
                t.recurrence_runtime
                ~wall:(t.services.now ())
                ~monotonic:(t.services.monotonic_now ())
              |> Result.map ~f:Option.some
            else Ok None
          in
          let%bind () =
            Recurrence_command_admission.check_write actor ~authorize t.state
          in
          let%bind () = Recurrence_command_admission.check_current prepared in
          let%bind () =
            persist_transition ?run_preparation ~check_before_commit t candidate
          in
          install_committed_transition ?run_preparation t candidate;
          Option.iter adoption ~f:(fun snapshot ->
            Recurrence_runtime.adopt_control
              t.recurrence_runtime
              ~previous
              ~current:t.state
              ~snapshot);
          publish_committed_transition t candidate;
          Ok ()
      in
      Recurrence_command_admission.receipt prepared
    | Goal_request (Read (actor, authorize)) ->
      Goal_command_admission.read t.state ~actor ~authorize
    | Context_request (Rollover request) -> handle_recovery_rollover t request
    | Context_request (Recovery_note request) -> handle_recovery_note t request
    | Context_request (Recovery_note_share request) ->
      handle_recovery_note_share t request
    | Context_request (Expire_recovery_window (actor, attachment_id, authorize, scope)) ->
      expire_recovery_window_internal t actor attachment_id authorize scope
    | Context_request (Enable_recovery_windows (actor, attachment_id, authorize)) ->
      enable_recovery_windows_internal t actor attachment_id authorize
    | Context_request (Instruction_command (admission, source, request)) ->
      let open Result.Let_syntax in
      let%bind decision =
        Instruction_command_admission.prepare_admitted
          t.state
          ~admission
          ~authorize_writer:(fun attachment_id ->
            with_writer t attachment_id (fun () -> Ok ()))
          ~source
          ~request
          ~now:(t.services.now ())
      in
      (match decision with
       | Retained receipt -> Ok receipt
       | Prepared { selection; receipt } ->
         let%bind candidate =
           prepare_transition
             t
             ~delta:(Instruction_selection_changed selection)
             ~payloads:[]
         in
         let%bind () =
           Instruction_command_admission.check_now_admitted
             t.state
             ~admission
             ~authorize_writer:(fun attachment_id ->
               with_writer t attachment_id (fun () -> Ok ()))
             ~source
             ~request
         in
         let%map () = install t candidate in
         receipt)
    | Goal_request (Apply (actor, authorize, session, request)) ->
      let open Result.Let_syntax in
      let%bind prepared =
        Goal_command_admission.prepare
          t.state
          ~actor
          ~authorize
          ~session
          ~descendant_profile:t.services.goal_descendant_profile
          ~request
          ~now:(t.services.now ())
      in
      let%map () =
        match prepared.delta with
        | None -> Ok ()
        | Some delta ->
          let%bind delta =
            match request.Goal_command.mutation with
            | Hold (goal_id, _) ->
              Goal_control_transition.prepare_hold t.state ~goal_id ~delta
            | Abandon (goal_id, _) ->
              Goal_control_transition.prepare_abandon t.state ~goal_id ~delta
            | Create _
            | Revise_objective _
            | Record_progress _
            | Change_budget _
            | Adopt_source _ -> Ok delta
          in
          let%bind transition = prepare_transition t ~delta ~payloads:[] in
          let check_before_commit () =
            Goal_command_admission.check_write actor ~authorize t.state
          in
          let%bind () = check_before_commit () in
          let explicit_goal_holds =
            match request.Goal_command.mutation with
            | Hold (id, _) -> [ id ]
            | Create _
            | Revise_objective _
            | Record_progress _
            | Change_budget _
            | Adopt_source _
            | Abandon _ -> []
          in
          install ~check_before_commit ~explicit_goal_holds t transition
      in
      prepared.receipt
    | Update_metadata (attachment_id, expected_metadata_revision, patch) ->
      with_writer t attachment_id (fun () ->
        let open Result.Let_syntax in
        let%bind delta =
          Session_metadata_transition.apply t.state ~expected_metadata_revision ~patch
        in
        match delta with
        | None -> transition t ~delta:(Session_delta.Batch []) ~payloads:[]
        | Some delta ->
          let%bind candidate = Session_delta.apply t.state delta in
          transition
            t
            ~delta
            ~payloads:
              [ Agent_protocol.Event.Durable.Payload.Session_updated
                  (Session_state.summary candidate)
              ])
    | Stop (attachment_id, mode) ->
      with_writer t attachment_id (fun () -> stop_internal t mode)
    | Stop_delegated (reference, mode) ->
      (match t.state.spec.delegation with
       | Some current
         when Agent_store.Delegation_store.Reference.equal current reference
              && Agent_protocol.Id.Session.equal
                   reference.child_session_id
                   t.state.identity.session_id -> stop_internal t mode
       | _ ->
         Error
           (error Permission_denied "delegation.stop: child relationship does not match"))
    | Stop_managed (reference, key, mode, generation, max_receipts) ->
      stop_managed_internal t reference key mode generation max_receipts
    | Append_history (attachment_id, entries) ->
      with_writer t attachment_id (fun () -> append_history t entries)
    | Stop_delegated_at_epoch (reference, epoch, force) ->
      (match t.state.spec.delegation with
       | Some current
         when Agent_store.Delegation_store.Reference.equal current reference
              && Agent_protocol.Id.Session.equal
                   reference.child_session_id
                   t.state.identity.session_id ->
         (match t.state.parent_stop_epoch with
          | Some previous when (not force) && Int64.(epoch <= previous) ->
            Ok (Session_state.summary t.state)
          | _ -> stop_internal ~parent_stop_epoch:epoch t Cancel)
       | _ ->
         Error
           (error Permission_denied "delegation.stop: child relationship does not match"))
    | Defer_history (attachment_id, entries) ->
      with_writer t attachment_id (fun () -> defer_history t entries)
    | Inherited_turn request ->
      (match request with
       | Submit_idle (input, capture) -> submit_idle_input t input ~capture
       | Resume_idle (selected, capture) ->
         admit_selected_idle_turn
           ~cleanup_ready:selected.cleanup_started
           t
           selected
           ~capture
       | Read_idle_continuation owner -> read_idle_turn_continuation t owner
       | Retire_idle_continuation (owner, continuation) ->
         retire_idle_turn_continuation t owner continuation
       | Submit_message
           (original_actor, attachment_id, submitting_principal, timing, entry, capture)
         ->
         let open Result.Let_syntax in
         let%bind () =
           check_message_authentication original_actor ~submitting_principal
         in
         submit_message
           ?original_actor
           t
           attachment_id
           submitting_principal
           timing
           entry
           capture
       | Submit_goal_subscription (execution, proposal, capture) ->
         submit_goal_subscription_input t execution proposal ~capture
       | Submit_goal_resume (continuation, capture) ->
         continue_goal_episode_internal t continuation ~capture
       | Submit_held_input (scope, input, capture) ->
         submit_held_run_input_internal t scope input ~capture
       | Edit_history (request, capture) -> edit_history_internal t request ~capture
       | Continue_history (request, capture) ->
         continue_history_internal t request ~capture
       | Submit_managed (input, capture) -> submit_managed_message t input ~capture
       | Admit_run (input, Receipt, capture) -> admit_run t input ~reply:Receipt ~capture
       | Admit_run (input, Prepared_outcome, capture) ->
         admit_prepared_run t input ~capture
       | Resolve_prepared_outcome (input, failure) ->
         (match input.preparation with
          | Some preparation
            when Run_preparation.belongs_to preparation ~owner:t.run_preparation_owner ->
            Ok (prepared_run_outcome t input failure)
          | Some _ | None ->
            Error (error Conflict "prepared outcome belongs to another actor"))
       | Submit_observed_origin observed -> submit_observed_turn_origin t observed
       | Commit (plan, before_writer) -> commit_inherited_turn t plan ~before_writer
       | Finish (acknowledged, confirmation, views) ->
         finish_inherited_turn t acknowledged ~confirmation ~views
       | Retire (acknowledged, failure) ->
         with_runtime_terminal t acknowledged.owner.operation_id (fun () ->
           retire_acknowledged_turn t acknowledged ~failure))
    | Control_pending (principal, project, request, replacement) ->
      control_pending_internal t principal project request replacement
    | Capture_run_constructor_model_source
        (preparation, job_id, generation, target, limits) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      capture_model_job_source
        ~run_preparation:preparation
        t
        job_id
        generation
        target
        limits
    | Capture_run_constructor_recipe_target
        (preparation, job_id, generation, attempt, target, limits) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      capture_recipe_target
        ~run_preparation:preparation
        t
        job_id
        generation
        attempt
        target
        limits
    | Start_run_constructor_model_job (preparation, job) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      let%bind job = add_constructor_job t (Run_constructor_job preparation) job in
      let%bind claimed = claim_job ~run_preparation:preparation t job.id job.generation in
      Result.of_option
        claimed
        ~error:(error Conflict "constructor model call could not claim its durable job")
    | Complete_run_constructor_model_job
        (preparation, job_id, generation, attempt, outcome) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      complete_job ~run_preparation:preparation t job_id generation attempt outcome
    | Interrupt_run_constructor_job (preparation, job_id, generation, attempt, reason) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      interrupt_job ~run_preparation:preparation t job_id generation attempt reason
    | Add_run_constructor_job (preparation, job) ->
      add_constructor_job t (Run_constructor_job preparation) job
    | Add_run_constructor_schedule (preparation, schedule) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      add_schedule ~run_preparation:preparation t schedule
    | Cancel_run_constructor_schedule (preparation, id) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      cancel_schedule_internal ~run_preparation:preparation t id
    | Reserve_run_history_block (preparation, count) ->
      let open Result.Let_syntax in
      let%bind () = check_run_preparation t preparation in
      reserve_history_block ~run_preparation:preparation t count
    | Checkpoint_run_moderator (preparation, moderator, moderator_manager) ->
      checkpoint_run_moderator t preparation moderator moderator_manager
    | Begin_run_preparation
        (original_actor, authorize, principal_id, request, request_sha256) ->
      begin_run_preparation_internal
        ?original_actor
        t
        ~authorize
        ~principal_id
        ~request:(Run_admission_request.of_writer request)
        ~request_sha256
    | Begin_headless_run_preparation (actor, authorize, request) ->
      let open Result.Let_syntax in
      let authorize = Run_command_authorization.check actor ~authorize in
      let principal_id = (Operator_authorization.principal actor).id in
      let request = Run_admission_request.of_headless request in
      let%bind request_sha256 = Run_admission_request.request_sha256 request in
      begin_run_preparation_internal
        ~original_actor:actor
        t
        ~authorize
        ~principal_id
        ~request
        ~request_sha256
    | Bind_run_source (preparation, source) ->
      bind_run_source_internal t ~preparation ~source
    | Held_startup request ->
      (match request with
       | Goal_continuation request ->
         (match request with
          | Receipt (writer, actor, authorize, session, request) ->
            goal_resume_receipt_internal ?writer t ~actor ~authorize ~session ~request
          | Begin (actor, authorize, session, request) ->
            begin_goal_resume_preparation_internal t ~actor ~authorize ~session ~request
          | Bind (preparation, source) ->
            bind_goal_continuation_source_internal t ~preparation ~source
          | Admit (writer, binding) -> admit_goal_resume_internal t ~writer binding
          | Close preparation -> end_goal_continuation_preparation_internal t preparation
          | Select_execution_wake request -> select_goal_runtime_wake_internal t request
          | Reconcile_wake_authority request ->
            reconcile_goal_wake_authority_internal t request
          | Begin_wake wake -> begin_goal_wake_preparation_internal t wake
          | Begin_job owner -> begin_goal_job_runtime_preparation_internal t owner
          | Bind_execution (preparation, source) ->
            bind_goal_continuation_source_internal t ~preparation ~source
          | Prepare_execution binding -> prepare_goal_execution_runtime_internal t binding
          | Close_execution preparation ->
            end_goal_continuation_preparation_internal t preparation
          | Check_job_owner owner -> check_job_runtime_owner_internal t owner
          | Acknowledge_job_resource execution ->
            acknowledge_goal_job_runtime_internal t execution
          | Job_resource (owner, worker, inference, manager) ->
            job_runtime_resource_internal t owner worker inference manager
          | Claim_wake_event (execution, id, snapshot) ->
            claim_queued_event ~goal_execution:execution t id None snapshot
          | Enqueue_wake_job (execution, delivery, before, after) ->
            enqueue_goal_wake_job_internal t execution delivery before after
          | Claim_wake_schedule (execution, schedule) ->
            claim_goal_wake_schedule_internal t execution schedule
          | Complete_wake_schedule (execution, schedule, before, manager, after) ->
            complete_goal_wake_schedule_internal t execution schedule before manager after
          | Deliver_wake_job (execution, job, before, after) ->
            deliver_goal_wake_job_internal t execution job before after
          | Finish_wake execution -> finish_goal_wake_runtime_internal t execution)
       | Effect_deferred request -> effect_deferred_request t request
       | Input_graph request -> input_graph_request t request
       | Begin_authored (continuation, startup, cleanup, snapshot) ->
         begin_held_authored_internal t continuation startup cleanup snapshot
       | Ready_authored scope -> ready_held_authored_internal t scope
       | Claim_authored (scope, id, snapshot, event) ->
         claim_held_authored_event t scope id snapshot event
       | Finish_authored scope -> finish_held_authored_internal t scope
       | Authored_resource (continuation, owner) ->
         held_authored_resource_internal t continuation owner
       | Begin_input continuation -> begin_held_input_internal t continuation
       | Ready_input (scope, input) -> ready_held_input_internal t scope input
       | Close_input scope -> close_held_input_internal t scope
       | End_held_activation activation -> end_held_activation_internal t activation
       | Enable_turn_budget (continuation, policy) ->
         enable_held_turn_budget_internal t continuation policy
       | Install_runtime (continuation, worker, inference, manager, unmoderated_source) ->
         install_held_runtime_internal
           ?unmoderated_source
           t
           continuation
           worker
           inference
           manager
       | Goal request ->
         (match request with
          | Receipt (writer, actor, authorize, request, session) ->
            goal_run_receipt_internal ?writer t ~actor ~authorize ~request ~session
          | Admit (writer, binding, intent, session) ->
            admit_held_goal_run_internal t ~writer ~binding ~intent ~session)
       | Begin_held_activation (binding, held, checked) ->
         begin_held_activation_internal t binding held checked
       | Construction request ->
         (match request with
          | Load request -> delegated_load_request t request
          | Mutate mutation -> runtime_constructor_mutation_request t mutation
          | Check_admission construction ->
            check_runtime_construction_admission_internal t construction
          | Begin_goal (construction, step) ->
            begin_goal_runtime_construction_internal t construction step
          | Begin_initialization (construction, purpose, expected) ->
            (match construction with
             | Initial continuation ->
               begin_held_initialization_internal t continuation purpose expected
             | Existing_goal _ | Delegated_load _ ->
               begin_runtime_initialization_internal t construction purpose expected)
          | Reserve_history (construction, count) ->
            reserve_runtime_history_block_internal t construction count
          | Add_model (scope, job) -> add_initialization_model_job t scope job
          | Model_running (scope, job_id, generation, attempt) ->
            initialization_model_job_is_running t scope job_id generation attempt
          | Enable_budget (construction, policy) ->
            enable_runtime_turn_budget_internal t construction policy
          | Install
              ( construction
              , worker
              , inference
              , manager
              , retained_lifecycle
              , unmoderated_source ) ->
            install_runtime_construction_internal
              ?unmoderated_source
              t
              construction
              worker
              inference
              manager
              retained_lifecycle
          | Begin_resume (continuation, resume) ->
            begin_goal_resume_callback_internal t continuation resume
          | Claim_resume (scope, id, snapshot, event) ->
            claim_goal_resume_event t scope id snapshot event
          | Finish_resume scope -> finish_goal_resume_callback_internal t scope
          | Resource (construction, owner) ->
            runtime_construction_resource_internal t construction owner
          | End construction -> end_runtime_construction_internal t construction))
    | Recurrence_check (Goal_run_guard (actor, authorize, intent, attempt)) ->
      capture_recurrence_goal_run_guard_internal t ~actor ~authorize ~intent ~attempt
    | Admit_held_recurrence_run (goal_guard, binding, intent, attempt, session) ->
      admit_held_recurrence_run_internal t ~goal_guard ~binding ~intent ~attempt ~session
    | Close_run_preparation preparation -> close_prepared_run_from_caller t preparation
    | Run_start_receipt (authorize, principal_id, request, request_sha256) ->
      let open Result.Let_syntax in
      let%bind () = authorize t.state in
      let%bind _ = write_attachment t request.attachment_id in
      let%bind () =
        if Agent_protocol.Id.Session.equal request.session_id t.state.identity.session_id
        then Ok ()
        else Error (error Invalid_request "run receipt targets another session")
      in
      let%bind retained =
        ordinary_run_receipt t ~principal_id ~key:request.key ~request_sha256
      in
      (match retained with
       | None -> Ok None
       | Some ({ kind = Admission; _ } as receipt) -> Ok (Some receipt)
       | Some { kind = Action | Terminal; _ } ->
         Error (error Conflict "run start key belongs to another action"))
    | Compact (original_actor, attachment_id, expected_revision) ->
      let%bind.Result () = require_selected_execution t in
      compact_internal t original_actor attachment_id expected_revision
    | Delete_history (attachment_id, revision, history_id) ->
      delete_history_internal t attachment_id revision history_id
    | Adopt_deferred -> adopt_deferred t
    | Reserve_history_block (None, count) -> reserve_history_block t count
    | Reserve_history_block (Some publication, count) ->
      with_foreground_publication t publication (fun _ ~check ->
        reserve_history_block ~check_before_commit:check t count)
    | Commit_worker_entry (publication, entry) ->
      with_foreground_publication t publication (fun operation_id ~check ->
        commit_worker_entry t operation_id ~check entry)
    | Prepare_authoring_input (publication, materialization, history, effective) ->
      with_foreground_publication t publication (fun operation_id ~check ->
        prepare_authoring_input t operation_id ~check materialization history effective)
    | Publish_invocation_output (publication, invocation_id, entry) ->
      with_foreground_publication t publication (fun operation_id ~check ->
        publish_invocation_output t operation_id ~check invocation_id entry)
    | Consume_deferred publication ->
      with_foreground_publication t publication (consume_deferred t)
    | Consume_notifications (publication, plan) ->
      with_foreground_publication t publication (fun operation_id ~check ->
        consume_notifications_internal ~check t operation_id plan)
    | Admit_standalone_delivery plan -> admit_standalone_delivery_internal t plan
    | Retire_obsolete_moderator_delivery (revision, job) ->
      retire_obsolete_moderator_delivery_internal t revision job
    | Deliver_standalone_completion (revision, job, capabilities, policy) ->
      deliver_standalone_completion_internal t revision job capabilities policy
    | Consume_initial_notifications (publication, proposal) ->
      with_foreground_publication t publication (fun operation_id ~check ->
        consume_notifications_internal
          ~check
          ~wakes:proposal.wakes
          ~discarded_wakes:proposal.discarded_wakes
          t
          operation_id
          proposal.pending)
    | Commit_worker_moderator (publication, snapshot) ->
      with_foreground_publication t publication (fun operation_id ~check ->
        commit_worker_moderator t operation_id ~check snapshot)
    | Has_writer_attachment -> Ok (has_writer_attachment t)
    | Authorize_writer attachment_id -> with_writer t attachment_id (fun () -> Ok ())
    | Invocation_granted (tool_name, identity_digest) ->
      Ok (invocation_granted t ~tool_name ~identity_digest)
    | Worker_ready (Compaction operation_id, cancel) -> worker_ready t operation_id cancel
    | Worker_ready (Foreground publication, cancel) ->
      if foreground_publication_matches t publication
      then
        worker_ready
          t
          publication.operation.id
          ~check_before_commit:(fun () -> check_live_foreground_publication t publication)
          cancel
      else (
        cancel ();
        Ok ())
    | Worker_terminal (publication, outcome, compaction_custody) ->
      worker_publication_terminal t publication outcome compaction_custody
    | Compaction_terminal (operation_id, outcome) ->
      with_runtime_terminal t operation_id (fun () ->
        compaction_terminal t operation_id outcome)
    | Cancel_operation (attachment_id, operation_id) ->
      cancel_operation_internal t attachment_id operation_id
    | Open_permission (permission, timeout_seconds, fallback) ->
      open_permission t permission timeout_seconds fallback
    | Respond_permission
        (attachment_id, principal_id, permission_id, generation, choice, reason) ->
      respond_permission_internal
        t
        attachment_id
        principal_id
        permission_id
        generation
        choice
        reason
    | Resolve_permission_system (permission_id, generation, choice, reason) ->
      resolve_permission_system t permission_id generation choice reason
    | Expire_permission (permission_id, generation, fallback) ->
      expire_permission_internal t permission_id generation fallback
    | Revoke_grant (attachment_id, grant_id, reason) ->
      revoke_grant t attachment_id grant_id reason
    | Change_job (attachment_id, job) -> change_job t attachment_id job
    | Capture_inference_target (target, limits) ->
      capture_inference_target t target limits
    | Capture_model_job_source (job_id, generation, target, limits) ->
      capture_model_job_source t job_id generation target limits
    | Capture_recipe_target (job_id, generation, attempt, target, limits) ->
      capture_recipe_target t job_id generation attempt target limits
    | Add_initialization_model_job (scope, job) ->
      add_initialization_model_job t scope job
    | Start_initialization_model_job (scope, job) ->
      start_initialization_model_job t scope job
    | Claim_initialization_model_job (scope, job_id, generation) ->
      claim_initialization_model_job t scope job_id generation
    | Initialization_model_job_is_current (scope, job_id, generation, attempt) ->
      initialization_model_job_is_current t scope job_id generation attempt
    | Capture_initialization_recipe_target
        (scope, job_id, generation, attempt, target, limits) ->
      capture_initialization_recipe_target t scope job_id generation attempt target limits
    | Complete_initialization_model_job (scope, job_id, generation, attempt, outcome) ->
      complete_initialization_model_job t scope job_id generation attempt outcome
    | Add_job job -> add_job t job
    | Claim_job (purpose, job_id, generation) -> claim_job ~purpose t job_id generation
    | Complete_job (job_id, generation, attempt, outcome) ->
      complete_job t job_id generation attempt outcome
    | Complete_background_job (job_id, generation, attempt, outcome) ->
      complete_background_job t job_id generation attempt outcome
    | Defer_background_job (job_id, generation, attempt, dependency) ->
      defer_background_job t job_id generation attempt dependency
    | Refresh_background_job (job_id, generation, attempt) ->
      refresh_background_job t job_id generation attempt
    | Recover_background_results (max_count, max_total_bytes) ->
      recover_background_results t max_count max_total_bytes
    | Enqueue_run_job_delivery (delivery, before, after) ->
      enqueue_run_job_delivery t delivery before after
    | Deliver_job (job_id, generation, expected, expected_job, moderator_snapshot, manager)
      -> deliver_job t job_id generation expected expected_job moderator_snapshot manager
    | Cancel_job_internal job_id -> cancel_job_internal t job_id
    | Cancel_job (attachment_id, job_id, expected_generation, expected_attempt) ->
      with_writer t attachment_id (fun () ->
        let open Result.Let_syntax in
        let%bind job = find_job t job_id in
        let%bind () =
          match expected_generation, expected_attempt with
          | None, None -> Ok ()
          | Some generation, Some attempt ->
            if
              Int.equal generation t.state.identity.generation
              && Int.equal generation job.generation
              && Int.equal attempt job.attempt
            then Ok ()
            else Error (error Conflict "job occurrence has changed")
          | Some _, None | None, Some _ ->
            Error (error Invalid_request "job occurrence requires generation and attempt")
        in
        cancel_job_internal t job_id)
    | Interrupt_job (job_id, generation, attempt, reason) ->
      interrupt_job t job_id generation attempt reason
    | Change_schedule (attachment_id, event, schedule) ->
      change_schedule t attachment_id event schedule
    | Add_schedule schedule -> add_schedule t schedule
    | Callback_schedule_after_ms (scope, delay_ms, payload) ->
      callback_schedule_after_ms t scope delay_ms payload
    | Callback_schedule_cancel (scope, schedule_id) ->
      callback_schedule_cancel t scope schedule_id
    | Cancel_schedule (attachment_id, schedule_id, expected_generation) ->
      with_writer t attachment_id (fun () ->
        let open Result.Let_syntax in
        let%bind schedule = find_schedule t schedule_id in
        let%bind () =
          match expected_generation with
          | None -> Ok ()
          | Some generation ->
            if
              Int.equal generation t.state.identity.generation
              && Int.equal generation schedule.generation
            then Ok ()
            else Error (error Conflict "schedule occurrence has changed")
        in
        cancel_schedule_internal t schedule_id)
    | Cancel_schedule_internal schedule_id -> cancel_schedule_internal t schedule_id
    | Claim_schedule (schedule_id, generation) -> claim_schedule t schedule_id generation
    | Retry_schedule (schedule_id, generation) -> retry_schedule t schedule_id generation
    | Complete_schedule
        ( schedule_id
        , generation
        , expected
        , expected_schedule
        , moderator_snapshot
        , moderator_manager ) ->
      complete_schedule
        t
        schedule_id
        generation
        expected
        expected_schedule
        moderator_snapshot
        moderator_manager
    | Fail_schedule (schedule_id, generation, failure) ->
      fail_schedule t schedule_id generation failure
    | Skip_schedule (schedule_id, generation) -> skip_schedule t schedule_id generation
    | Idle_completion request -> handle_idle_completion_request t request
    | Attach (mode, subscribe, principal_id, reclaim_token) ->
      attach t mode subscribe principal_id reclaim_token
    | Detach attachment_id -> detach t attachment_id
    | Renew_owner (attachment_id, generation) -> renew_owner t attachment_id generation
    | Owner_expired generation -> owner_expired t generation
    | Causal_route
        (Capture_causal_routes (source_owner, preparation, reservations, ancestry)) ->
      capture_causal_routes
        t
        ~source_owner
        ~preparation
        ~reservations
        ~callee_ancestry:ancestry
    | Causal_route (Consume_causal_routes observed) -> consume_causal_routes t observed
    | Causal_route (Capture_causal_root (source_owner, observation)) ->
      capture_causal_root t ~source_owner observation
    | Causal_route (Consume_causal_root observed) -> consume_causal_root t observed
    | Causal_route (Capture_causal_terminal operation) ->
      capture_causal_terminal t operation
    | Causal_route (Consume_causal_terminal observed) ->
      consume_causal_terminal t observed
    | Causal_route (Commit_causal_correction owned) -> causal_commit_correction t owned
    | Causal_route (Reconcile_causal_correction owned) -> causal_correction_result t owned
    | Causal_route (Retained_causal_correction (acknowledgement, observation)) ->
      causal_retained_correction t acknowledgement observation
    | Causal_route (Abandon_causal_correction owned) -> causal_abandon_correction t owned
    | Causal_route (Reconcile_causal_import (reservation, observation)) ->
      causal_initial_result t reservation observation
    | Causal_route (Capture_causal_usage (source_owner, source)) ->
      capture_causal_usage t ~source_owner source
    | Causal_route (Consume_causal_usage observed) -> consume_causal_usage t observed
    | Causal_route (Capture_causal_reservation operation) ->
      capture_causal_reservation t operation
    | Causal_route (Consume_causal_reservation observed) ->
      consume_causal_reservation t observed
    | Descendant_root (Capture operation) -> capture_descendant_root t operation
    | Descendant_root (Consume observed) -> consume_descendant_root t observed
    | Descendant_root (Consume_admitted observed) ->
      consume_descendant_admitted_root t observed
    | Install_descendant_host
        (purpose, source_owner, expected, check_ancestry, host, causal_driver) ->
      let open Result.Let_syntax in
      let%bind () =
        match purpose with
        | Descendant_host_installation.Ordinary | Ordinary_ready_reload _ -> Ok ()
        | Restored restoration -> check_policy_restoration_target t restoration
      in
      install_descendant_host_internal
        t
        ~purpose
        ~source_owner
        ~expected
        ~check_ancestry
        ~host
        ~causal_driver
    | Child_accounting request -> handle_child_accounting_request t request
    | Checkpoint persist -> persist t.state
    | Quiescent_checkpoint inspect ->
      (match
         ( t.state.active_operation
         , t.active_cancel
         , t.invocation_executions
         , t.job_scopes
         , t.moderator_borrow
         , t.queued_event_borrow
         , t.foreground_moderator
         , t.idle_moderator_borrowed
         , Staged_jobs.is_empty t.staged_jobs
           && Staged_subscriptions.is_empty t.staged_subscriptions
           && Staged_ingress.is_empty t.staged_ingress
           && Staged_schedules.is_empty t.staged_schedules
           && Staged_notifications.is_empty t.staged_notifications
         , Active_calls.snapshot t.active_calls )
       with
       | None, None, [], [], None, None, None, false, true, ([], []) ->
         Result.map (inspect t.state) ~f:Option.some
       | _ -> Ok None)
    | Open_inference_owner (preparation, source) ->
      let%bind.Result () =
        match preparation with
        | None -> require_selected_execution t
        | Some preparation ->
          let%bind.Result () = check_run_preparation t preparation in
          require_selected_or_held_execution t (Some preparation)
      in
      open_inference_owner t source
    | Admit_inference
        (run_preparation, owner, relation, operation_id, invocation_id, configuration) ->
      let%bind.Result () = require_selected_or_held_execution t run_preparation in
      admit_inference
        ?run_preparation
        t
        owner
        relation
        operation_id
        invocation_id
        configuration
    | Inherited_inference request -> handle_inherited_inference_request t request
    | Constructor_model request -> handle_constructor_model_request t request
    | Admit_model_job (execution, job) -> admit_model_job t execution job
    | Refresh_inference selected -> refresh_inference t selected
    | Acknowledge_inference (run_preparation, owner, handle, attempt) ->
      acknowledge_inference ?run_preparation t owner handle attempt
    | Observe_inference (run_preparation, handle, incoming) ->
      observe_inference ?run_preparation t handle incoming
    | Observe_owned_inference (run_preparation, owner, incoming) ->
      observe_owned_inference ?run_preparation t owner incoming
    | Complete_inference (run_preparation, owner, handle, completion) ->
      complete_inference ?run_preparation t owner handle completion
    | Release_inference (run_preparation, owner, handle) ->
      release_inference ?run_preparation t owner handle
    | Capture_inference_usage selected -> capture_inference_usage t selected
    | Check_inference_usage selected -> inference_usage_is_settled t selected
    | Finalize_inference_usage -> finalize_inference_usage t
    | Seal_inference_owner owner -> seal_inference_owner t owner
    | Finish_inference_owner (run_preparation, owner) ->
      finish_inference_owner ?run_preparation t owner
    | Clear_finished_inference_owner (owner, acknowledgement) ->
      clear_finished_inference_owner t owner acknowledgement
    | Reconcile_inference_recovery -> reconcile_inference_recovery t
    | Shutdown ->
      retire_execution_custody t;
      abort_all_staged_work t;
      Option.iter t.owner_timer_cancel ~f:(fun resolver ->
        Eio.Promise.resolve resolver ());
      t.owner_timer_cancel <- None;
      Option.iter t.active_cancel ~f:(fun cancel -> cancel ());
      List.iter t.job_scopes ~f:cancel_job_scope;
      Option.iter t.queued_event_borrow ~f:(fun borrow ->
        borrow.callback_active <- false;
        Atomic.set borrow.authority_live false;
        borrow.cancel_requested <- true;
        Option.iter borrow.cancel ~f:(fun cancel -> cancel ()));
      Eio.Mutex.use_rw ~protect:true t.subscriber_mutex (fun () ->
        Map.iter !(t.subscribers) ~f:Subscriber.close;
        t.subscribers := Map.Poly.empty);
      Map.iter !(t.permission_waiters) ~f:(fun waiter ->
        Eio.Promise.resolve
          waiter.resolver
          Agent_protocol.Permission.
            { choice = Deny
            ; principal_id = None
            ; resolved_at = t.services.now ()
            ; reason = Some "session actor shut down"
            });
      t.permission_waiters := Map.Poly.empty;
      t.stopped <- true;
      Ok ())
;;

let rec reject_pending mailbox =
  match Mailbox.pop mailbox with
  | None -> ()
  | Some (Pack (_, _, resolver)) ->
    Actor_reply.resolve
      resolver
      (Error
         (Agent_protocol.Error.create
            Server_shutting_down
            ~message:"session actor is shut down"
            ~retryable:true
            ()));
    reject_pending mailbox
;;

let close_owner t =
  t.stopped <- true;
  t.command_audit <- None;
  retire_execution_custody t;
  Mailbox.close t.mailbox
;;

let rec run t =
  match Mailbox.pop t.mailbox with
  | None -> ()
  | Some (Pack (command_audit, request, resolver)) ->
    t.command_audit <- command_audit;
    (match handle t request with
     | result ->
       t.command_audit <- None;
       if t.stopped then Mailbox.close t.mailbox;
       Actor_reply.resolve resolver result;
       if not t.stopped then run t
     | exception exn ->
       let backtrace = Stdlib.Printexc.get_raw_backtrace () in
       Eio.Cancel.protect (fun () ->
         close_owner t;
         Actor_reply.resolve_exception resolver exn backtrace);
       Exn.raise_with_original_backtrace exn backtrace)
;;

let create_internal
      ~canonical_persistence
      ~runtime_source_owner
      ~ordinary_execution_admission
      ~schedule_permission_timeouts
      ~sw
      ~clock
      ~mailbox_capacity
      ~owner_lease_duration_ms
      ~max_attachments
      ~subscriber_capacity
      ~compaction_env
      ~(initial_state : Session_state.t)
      ~persistence
      ~operation_worker
      ~services
  =
  if max_attachments <= 0 then invalid_arg "max_attachments must be positive";
  if subscriber_capacity <= 0 then invalid_arg "subscriber_capacity must be positive";
  (match Staged_subscriptions.validate_limits services.subscription_limits with
   | Ok () -> ()
   | Error error -> invalid_arg error.message);
  (match Staged_ingress.validate_limits services.ingress_limits with
   | Ok () -> ()
   | Error error -> invalid_arg error.message);
  (match Staged_schedules.validate_limits services.schedule_limits with
   | Ok () -> ()
   | Error error -> invalid_arg error.message);
  (match Staged_notifications.validate_limits services.notification_limits with
   | Ok () -> ()
   | Error error -> invalid_arg error.message);
  let finished, finish = Eio.Promise.create () in
  let t =
    { sw
    ; sleep = (fun seconds -> Eio.Time.sleep clock seconds)
    ; mailbox = Mailbox.create ~capacity:mailbox_capacity
    ; finished
    ; persistence
    ; canonical_persistence
    ; startup_disposal = Failed_startup_release_data.Gate.create ()
    ; services
    ; subscriber_mutex = Eio.Mutex.create ()
    ; active_calls = Active_calls.create ()
    ; subscribers = ref Map.Poly.empty
    ; permission_waiters = ref Map.Poly.empty
    ; organization_admission = None
    ; configuration_policy = None
    ; context_capacity_host = Session_context_capacity.Host.off
    ; rollover_requires_recovery = false
    ; live_operator_rollover = None
    ; recurrence_controller = None
    ; recurrence_runtime = Recurrence_runtime.create ~origin:(services.monotonic_now ())
    ; recurrence_creation_owner = ref ()
    ; recurrence_activation_owner = Activation_custody.Owner.create ()
    ; recurrence_activations = []
    ; descendant_policy_cells = []
    ; descendant_host_binding = None
    ; governed_admission_slot = None
    ; causal_root_write = None
    ; idle_completion = None
    ; idle_turn_continuation = None
    ; inherited_turn_prepared = None
    ; inherited_turn_cleanup = None
    ; configuration_update_owner = Configuration_update.Owner.create ()
    ; configuration_capture = Configuration_capture.create ()
    ; unmoderated_source = None
    ; operation_worker
    ; compaction_inference = None
    ; inference_execution = None
    ; moderator_manager = None
    ; compaction_env
    ; owner_lease_duration_ms
    ; max_attachments
    ; subscriber_capacity
    ; schedule_permission_timeouts
    ; owner_timer_cancel = None
    ; foreground_publication = None
    ; active_cancel = None
    ; lifecycle_owner = ref ()
    ; lifecycle_fence = None
    ; runtime_retirement = None
    ; idle_moderator_borrowed = false
    ; moderator_borrow = None
    ; queued_event_borrow = None
    ; delegated_policy_claim = None
    ; policy_restoration = Vacant
    ; legacy_callback_scope = None
    ; legacy_queue_custody = Legacy_queue_custody.empty
    ; legacy_schedule_custody = Legacy_schedule_custody.empty
    ; ingress_creator_custody = Ingress_creator_custody.empty
    ; operation_agent_custody = None
    ; operation_completion = None
    ; lifecycle_agent_custody = Unadmitted
    ; intent_agent_custody = []
    ; pending_agent_custody = []
    ; job_agent_custody = Job_custody.empty
    ; run_authorities = Run_authorities.empty
    ; runtime_source_owner
    ; ordinary_execution_admission
    ; runtime_source_domain = (Stdlib.Domain.self () :> int)
    ; run_preparation_owner = Run_preparation.Owner.create ()
    ; run_preparation = None
    ; effect_deferred = None
    ; run_source_binding = None
    ; held_activation = None
    ; held_input_scope = None
    ; held_authored_start = None
    ; foreground_moderator = None
    ; invocation_executions = []
    ; inference_owner_identity = ref ()
    ; inference_owners = []
    ; initialization_owner = ref ()
    ; constructor_models = None
    ; initialization_scope = None
    ; job_scopes = []
    ; staged_jobs = Staged_jobs.create ()
    ; staged_subscriptions = Staged_subscriptions.create ()
    ; staged_ingress = Staged_ingress.create ()
    ; staged_schedules = Staged_schedules.create ()
    ; staged_schedule_custody = Legacy_schedule_custody.Staged.create ()
    ; staged_ingress_custody = Ingress_creator_custody.Staged.create ()
    ; staged_notifications = Staged_notifications.create ()
    ; notification_inputs = None
    ; extension_clock = Extension_clock.create ()
    ; invocation_gate = Chat_response.Execution_gate.create ()
    ; event_sequence = Atomic.make initial_state.counters.event_sequence
    ; state = initial_state
    ; stopped = false
    ; recovery_window_cursor = lazy (Recovery_window_page.create ())
    ; recovery_query_cursor = lazy (Recovery_query_cursor.create ())
    ; protected_source_custody = None
    ; canonical_write_in_progress = false
    ; command_audit = None
    }
  in
  Option.iter t.canonical_persistence ~f:(fun binding ->
    Canonical_backend_binding_data.validate_exn
      binding
      ~session_id:t.state.identity.session_id
      ~commit:t.persistence.commit);
  Option.iter t.state.recovery_windows ~f:(fun ledger ->
    let owner =
      Option.bind t.canonical_persistence ~f:Canonical_backend_binding_data.session_owner
    in
    if
      not
        (Option.exists
           owner
           ~f:(Agent_protocol.Session_ref.equal (Recovery_window_ledger.owner ledger)))
    then invalid_arg "recovery window state belongs to another canonical writer owner");
  sync_extension_clock t;
  (* A persisted actor outlives the tool/script that created it. Its future
     operations acquire their own budgets and delegated authority; inheriting
     this caller's lexical ChatML frame would poison them after creation ends. *)
  Chatml_execution.without_ambient_context (fun () ->
    Eio.Fiber.fork ~sw (fun () ->
      Exn.protect
        ~f:(fun () -> run t)
        ~finally:(fun () ->
          Eio.Cancel.protect (fun () ->
            Exn.protect
              ~f:(fun () ->
                close_owner t;
                reject_pending t.mailbox)
              ~finally:(fun () -> Eio.Promise.resolve finish ())))));
  Option.iter (owner_attachment t) ~f:(fun attachment ->
    Option.iter attachment.owner_lease ~f:(schedule_owner_lease t));
  t
;;

