module Retirement_cleanup = struct
  type actor = t
  type t = runtime_retirement_cleanup

  module Failure = Retirement_cleanup_observation.Failure
  module Snapshot = Retirement_cleanup_observation.Snapshot
  module Status = Retirement_cleanup_observation.Status

  let retirement (t : t) = t.original.foreground_finished

  let on_domain (t : t) =
    Int.equal t.original.selection.domain (Stdlib.Domain.self () :> int)
  ;;

  let snapshot (t : t) =
    if on_domain t
    then Ok t.latest
    else Error (error Conflict "retirement cleanup belongs to another Eio domain")
  ;;

  let callback_producer_finished (selected : runtime_retirement_callback) =
    match Callback_completion_data.actual_exit selected.borrow.completion with
    | Returned _ -> true
    | Not_returned ->
      Option.exists selected.wrapper ~f:(fun wrapper ->
        match Delegated_policy_claim_state.extent wrapper with
        | Joined_without_entry -> true
        | Not_started | Not_entered | Entered | Joined_after_entry -> false)
  ;;

  let callback_status (selected : runtime_retirement_callback) =
    let completion = selected.borrow.completion in
    match completion.bookkeeping, Callback_completion_data.release completion with
    | Released _, Completed (Error failure) ->
      Status.Terminal
        [ (match failure with
           | Protocol error -> Failure.Protocol error
           | Raised (exn, backtrace) -> Raised (exn, backtrace))
        ]
    | Released _, Finishing -> Status.Pending []
    | Released _, Completed (Ok ()) ->
      if callback_producer_finished selected then Status.Joined else Status.Pending []
    | (Unselected | Selected _), Not_released ->
      if not (callback_producer_finished selected)
      then (
        let failures =
          match Callback_completion_data.latest_finish completion with
          | None | Some (Ok ()) -> []
          | Some (Error (Protocol failure)) -> [ Failure.Protocol failure ]
          | Some (Error (Raised (exn, backtrace))) -> [ Failure.Raised (exn, backtrace) ]
        in
        Status.Pending failures)
      else (
        match Callback_completion_data.latest_finish completion with
        | None | Some (Ok ()) -> Status.Deferred
        | Some (Error failure) ->
          Retryable
            [ (match failure with
               | Protocol error -> Failure.Protocol error
               | Raised (exn, backtrace) -> Raised (exn, backtrace))
            ])
    | Released _, Not_released | (Unselected | Selected _), (Finishing | Completed _) ->
      invalid_arg "callback bookkeeping differs from its actual release"
  ;;

  let constructor_finished (call : Constructor_model_data.call) =
    match Constructor_model_producer.exit call.capture.producer with
    | None | Some { completion = Selecting; _ } -> false
    | Some { completion = Sample _ | Clock_failed _; _ } ->
      (match call.phase with
       | Joined _ | Abandoned -> true
       | Admission_attempt _
       | Admitted _
       | Claim_attempt _
       | Claimed _
       | Selected _
       | Terminal_attempt _
       | Cancel_attempt _ -> false)
  ;;

  let target_terminal (t : t) target =
    List.exists t.duties ~f:(fun duty ->
      same_runtime_retirement_cleanup_target target duty.selected_target
      &&
      match duty.observation with
      | Status.Terminal _ -> true
      | Deferred | Pending _ | Retryable _ | Joined -> false)
  ;;

  let parent_cutoff (t : t) =
    Runtime_retirement.is_finished (retirement t)
    && List.for_all t.original.selection.constructor_calls ~f:(fun call ->
      constructor_finished call
      || (target_terminal t (Cleanup_constructor call)
          &&
          match Constructor_model_producer.exit call.capture.producer with
          | Some { completion = Sample _ | Clock_failed _; _ } -> true
          | None | Some { completion = Selecting; _ } -> false))
    && Option.for_all t.original.selection.callback ~f:(fun selected ->
      callback_producer_finished selected
      &&
      match Callback_completion_data.release selected.borrow.completion with
      | Completed _ -> true
      | Not_released | Finishing ->
        target_terminal t (Cleanup_callback selected)
        && Option.is_some
             (Callback_completion_data.latest_finish selected.borrow.completion))
    && Option.for_all t.original.selection.selected_idle_completion ~f:(fun completion ->
      match completion.Idle_completion_data.phase with
      | Fresh -> true
      | Retired -> Option.is_some (Eio.Promise.peek completion.exited)
      | Claimed _ | Completing _ ->
        target_terminal
          t
          (Cleanup_idle (completion, t.original.selection.idle_continuation))
        && Option.is_some (Eio.Promise.peek completion.exited))
  ;;

  let attempt_reply = function
    | Idle_cleanup_attempt { attempt; _ } ->
      Option.map attempt.outcome ~f:(fun completion ->
        completion.Retirement_cleanup_completion.reply)
    | Inherited_cleanup_attempt { attempt; _ } ->
      Option.map attempt.outcome ~f:(fun completion ->
        completion.Retirement_cleanup_completion.reply)
    | Descendant_cleanup_attempt { attempt; _ } ->
      Option.map attempt.outcome ~f:(fun completion ->
        completion.Retirement_cleanup_completion.reply)
    | Causal_cleanup_attempt { promise; _ } -> Eio.Promise.peek promise
  ;;

  let attempt_finished = function
    | Idle_cleanup_attempt { attempt; _ } ->
      Option.is_some (Eio.Promise.peek attempt.finished)
    | Inherited_cleanup_attempt { attempt; _ } ->
      Option.is_some (Eio.Promise.peek attempt.finished)
    | Descendant_cleanup_attempt { attempt; _ } ->
      Option.is_some (Eio.Promise.peek attempt.finished)
    | Causal_cleanup_attempt { promise; _ } -> Option.is_some (Eio.Promise.peek promise)
  ;;

  let released_attempt = function
    | Idle_cleanup_attempt { attempt; _ } ->
      Option.exists attempt.outcome ~f:(fun completion ->
        match completion.Retirement_cleanup_completion.boundary with
        | Released -> true
        | Before_release -> false)
    | Inherited_cleanup_attempt { attempt; _ } ->
      Option.exists attempt.outcome ~f:(fun completion ->
        match completion.Retirement_cleanup_completion.boundary with
        | Released -> true
        | Before_release -> false)
    | Descendant_cleanup_attempt { attempt; _ } ->
      Option.exists attempt.outcome ~f:(fun completion ->
        match completion.Retirement_cleanup_completion.boundary with
        | Released -> true
        | Before_release -> false)
    | Causal_cleanup_attempt _ -> false
  ;;

  let completed_status (completion : Retirement_cleanup_completion.t) =
    match Failure.of_reply completion.reply with
    | Ok () -> Status.Joined
    | Error failure ->
      (match completion.boundary with
       | Released -> Status.Terminal [ failure ]
       | Before_release -> Status.Retryable [ failure ])
  ;;

  let observe_attempt (duty : runtime_retirement_cleanup_duty) original =
    let terminal =
      match duty.observation with
      | Status.Terminal failures -> Some failures
      | Deferred | Pending _ | Retryable _ | Joined -> None
    in
    if not (attempt_finished original)
    then (if Option.is_none terminal then duty.observation <- Status.Pending [])
    else (
      duty.attempt_observation <- Observed_cleanup_attempt original;
      duty.observation
      <- (match terminal, attempt_reply original with
          | Some failures, Some outcome ->
            (match Failure.of_reply outcome with
             | Ok () -> Status.Terminal failures
             | Error earlier -> Status.Terminal (earlier :: failures))
          | Some failures, None -> Status.Terminal failures
          | None, None -> Status.Pending []
          | None, Some outcome ->
            (match Failure.of_reply outcome with
             | Ok () -> Status.Joined
             | Error failure ->
               if released_attempt original
               then Status.Terminal [ failure ]
               else Status.Retryable [ failure ])))
  ;;

  let observe_terminal (duty : runtime_retirement_cleanup_duty) =
    match duty.observation with
    | Status.Terminal _ -> ()
    | Deferred | Pending _ | Retryable _ | Joined ->
      (match duty.selected_target with
       | Cleanup_callback selected ->
         (match duty.observation, callback_status selected with
          | Status.Terminal _, _ -> ()
          | _, status -> duty.observation <- status)
       | Cleanup_constructor selected_call ->
         (match Constructor_model_producer.exit selected_call.capture.producer with
          | Some { completion = Clock_failed (exn, backtrace); _ } ->
            duty.observation <- Status.Terminal [ Failure.Raised (exn, backtrace) ]
          | None | Some { completion = Selecting | Sample _; _ } -> ())
       | Cleanup_idle (completion, _) ->
         (match completion.cleanup with
          | Scheduling_failed (_, Raised (exn, backtrace)) ->
            duty.observation <- Status.Terminal [ Failure.Raised (exn, backtrace) ]
          | Scheduling_failed (failure, Returned _) ->
            duty.observation <- Status.Terminal [ Failure.Protocol failure ]
          | Idle | Running _ -> ())
       | Cleanup_inherited _
       | Cleanup_descendant _
       | Cleanup_governed _
       | Cleanup_factual _ -> ())
  ;;

  let same_plan_arms left right =
    match left, right with
    | Descendant_attempt left, Descendant_attempt right -> phys_equal left right
    | Policy_causal_attempt left, Policy_causal_attempt right -> phys_equal left right
    | Combined_attempt left, Combined_attempt right ->
      phys_equal left.descendant right.descendant && phys_equal left.causal right.causal
    | (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _), _ -> false
  ;;

  let exact_plan_facts (actor : actor) (plan : inherited_attempt_plan) =
    let open Result.Let_syntax in
    match plan.acknowledged with
    | None -> Ok None
    | Some acknowledgement ->
      let%bind () =
        if
          phys_equal acknowledgement.owner plan.owner
          && Inference_ledger.Handle.equal acknowledgement.handle plan.handle
          && same_plan_arms acknowledgement.arms plan.arms
          && Int.equal actor.runtime_source_domain (Stdlib.Domain.self () :> int)
          && phys_equal
               (Graph_owner.issuing_actor plan.owner)
               actor.inference_owner_identity
        then Ok ()
        else
          Error (error Conflict "selected governed ACK changed its actual owner/handle")
      in
      let%bind registration =
        match acknowledgement.original with
        | Runtime { selected; _ } ->
          Result.map !selected ~f:(fun selected ->
            selected.Admitted_inference.registration)
        | Legacy { registration; _ } -> !registration
      in
      let%bind () =
        if
          Inference_ledger.Handle.equal
            (Inference_owner.Registration.handle registration)
            plan.handle
        then Ok ()
        else
          Error (error Conflict "selected governed ACK changed its actual registration")
      in
      let%map facts =
        Result.of_option
          (Inference_owner.Registration.factual_usage registration)
          ~error:
            (error Invalid_state "installed selected ACK has no factual usage receipt")
      in
      Some facts
  ;;

  let add_plan_facts (t : t) (actor : actor) =
    List.iter t.duties ~f:(fun duty ->
      match duty.selected_target with
      | Cleanup_governed plan ->
        (match Failure.capture (fun () -> exact_plan_facts actor plan) with
         | Ok None -> ()
         | Ok (Some facts) ->
           let target = Cleanup_factual facts in
           if
             not
               (List.exists t.duties ~f:(fun existing ->
                  same_runtime_retirement_cleanup_target target existing.selected_target))
           then
             t.duties
             <- t.duties
                @ [ { selected_target = target
                    ; observation = Status.Deferred
                    ; attempt_observation = No_cleanup_attempt
                    }
                  ]
         | Error failure ->
           (match duty.observation with
            | Status.Terminal _ -> ()
            | Joined -> duty.observation <- Status.Terminal [ failure ]
            | Deferred | Pending _ | Retryable _ ->
              duty.observation <- Status.Retryable [ failure ]))
      | Cleanup_constructor _
      | Cleanup_callback _
      | Cleanup_idle _
      | Cleanup_inherited _
      | Cleanup_descendant _
      | Cleanup_factual _ -> ())
  ;;

  let store_attempt (duty : runtime_retirement_cleanup_duty) receipt =
    duty.attempt_observation <- Observed_cleanup_attempt receipt;
    receipt
  ;;

  let await_attempt (duty : runtime_retirement_cleanup_duty) receipt =
    let receipt = store_attempt duty receipt in
    (match receipt with
     | Idle_cleanup_attempt { attempt; _ } -> ignore (Eio.Promise.await attempt.finished)
     | Inherited_cleanup_attempt { attempt; _ } ->
       ignore (Eio.Promise.await attempt.finished)
     | Descendant_cleanup_attempt { attempt; _ } ->
       ignore (Eio.Promise.await attempt.finished)
     | Causal_cleanup_attempt { promise; _ } -> ignore (Eio.Promise.await promise));
    observe_attempt duty receipt
  ;;

  let drive_descendant (actor : actor) (duty : runtime_retirement_cleanup_duty) slot =
    let open Result.Let_syntax in
    let%bind closed =
      call
        actor
        ~priority:Priority
        (Runtime_retirement (Advance_cleanup (Cleanup_seal_descendant slot)))
    in
    let%map issued = schedule_descendant_admission_cleanup_reported actor slot ~closed in
    let attempt =
      match issued with
      | Scheduled attempt | Launch_failed { attempt; _ } -> attempt
    in
    await_attempt duty (Descendant_cleanup_attempt { slot; attempt })
  ;;

  let drive (actor : actor) (duty : runtime_retirement_cleanup_duty) =
    let open Result.Let_syntax in
    match duty.selected_target with
    | Cleanup_constructor selected_call ->
      (match Constructor_model_producer.exit selected_call.capture.producer with
       | None | Some { completion = Selecting; _ } ->
         duty.observation <- Status.Pending [];
         Ok ()
       | Some { completion = Sample _ | Clock_failed _; _ } ->
         let attempt = { original_call = selected_call; completion = None } in
         let observed =
           Failure.capture (fun () ->
             call
               actor
               ~priority:Priority
               (Runtime_retirement (Advance_cleanup (Cleanup_constructor_call attempt))))
         in
         (match attempt.completion with
          | Some completion ->
            duty.observation <- completed_status completion;
            Ok ()
          | None ->
            (match observed with
             | Ok () ->
               Error
                 (error
                    Invalid_state
                    "constructor cleanup returned without its actual invocation receipt")
             | Error (Protocol failure) -> Error failure
             | Error (Raised (exn, backtrace)) ->
               Exn.raise_with_original_backtrace exn backtrace)))
    | Cleanup_callback selected ->
      (match callback_status selected with
       | (Status.Pending _ | Joined | Terminal _) as status ->
         duty.observation <- status;
         Ok ()
       | Deferred | Retryable _ ->
         let exit =
           match
             ( selected.borrow.completion.bookkeeping
             , Callback_completion_data.actual_exit selected.borrow.completion )
           with
           | Selected original, _ -> original.exit
           | Unselected, Returned exit -> exit
           | Unselected, Not_returned -> Queued_callback_exit.Interrupted
           | Released _, (Not_returned | Returned _) -> Queued_callback_exit.Returned
         in
         let%map () =
           call
             actor
             ~priority:Priority
             (Runtime_retirement
                (Advance_cleanup (Cleanup_ended_callback (selected.borrow, exit))))
         in
         duty.observation <- callback_status selected)
    | Cleanup_idle (completion, selected) ->
      if
        (not (Option.is_some (Eio.Promise.peek completion.exited)))
        &&
        match completion.phase with
        | Fresh -> false
        | Claimed _ | Completing _ | Retired -> true
      then (
        duty.observation <- Status.Pending [];
        Ok ())
      else (
        let%map issued =
          schedule_idle_completion_retirement_reported
            ~source:(Idle_cleanup_source.Captured selected)
            actor
            completion
        in
        let attempt =
          match issued with
          | Scheduled attempt | Launch_failed { attempt; _ } -> attempt
        in
        await_attempt duty (Idle_cleanup_attempt { completion; attempt }))
    | Cleanup_inherited (Pack acknowledged as selected) ->
      Inherited_turn.request_cancellation
        acknowledged.plan
        ~failure:(error Interrupted "selected inherited Turn source is retiring");
      let%map issued = schedule_inherited_turn_cleanup_reported actor acknowledged in
      let attempt =
        match issued with
        | Scheduled attempt | Launch_failed { attempt; _ } -> attempt
      in
      await_attempt duty (Inherited_cleanup_attempt { acknowledged = selected; attempt })
    | Cleanup_descendant slot -> drive_descendant actor duty slot
    | Cleanup_governed plan ->
      (match plan.acknowledged with
       | Some acknowledgement ->
         let%bind facts = exact_plan_facts actor plan in
         let%bind facts =
           Result.of_option
             facts
             ~error:
               (error Invalid_state "selected installed Plan lost its factual receipt")
         in
         let%bind () = Inference_owner.Factual_usage.confirm_initial facts in
         let%map () =
           match acknowledgement.confirmation with
           | Some _ -> Ok ()
           | None ->
             Error (error Conflict "selected installed Plan confirmation remains pending")
         in
         duty.observation <- Status.Joined
       | None ->
         let%bind closed =
           call actor ~priority:Priority (Inherited_inference (Seal plan))
         in
         (match plan.arms, closed with
          | Descendant_attempt slot, Descendant_closed closed ->
            let%map issued =
              schedule_descendant_admission_cleanup_reported actor slot ~closed
            in
            let attempt =
              match issued with
              | Scheduled attempt | Launch_failed { attempt; _ } -> attempt
            in
            await_attempt duty (Descendant_cleanup_attempt { slot; attempt })
          | ( (Policy_causal_attempt _ | Combined_attempt _)
            , (Causal_closed _ | Combined_closed _) ) ->
            let%map promise = schedule_governed_plan_cleanup actor plan in
            await_attempt duty (Causal_cleanup_attempt { plan; promise })
          | (Descendant_attempt _ | Policy_causal_attempt _ | Combined_attempt _), _ ->
            Error (error Conflict "selected governed Plan changed its actual closed arms")))
    | Cleanup_factual facts ->
      let%bind () = Inference_owner.Factual_usage.confirm_initial facts in
      let%map result = Inference_owner.Factual_usage.settle_correction facts in
      duty.observation
      <- (match result with
          | Settled -> Status.Joined
          | Deferred -> Status.Retryable [])
  ;;

  let publish (t : t) ~(actor : actor) =
    let statuses = List.map t.duties ~f:(fun duty -> duty.observation) in
    let failures = List.concat_map statuses ~f:Status.failures in
    let terminal =
      List.exists statuses ~f:(function
        | Status.Terminal _ -> true
        | Deferred | Pending _ | Retryable _ | Joined -> false)
    in
    let actual_pending =
      List.exists statuses ~f:(function
        | Status.Pending _ -> true
        | Deferred | Retryable _ | Terminal _ | Joined -> false)
      || List.exists t.duties ~f:(fun duty ->
        match duty.attempt_observation with
        | Unobserved_cleanup_attempt attempt -> not (attempt_finished attempt)
        | No_cleanup_attempt | Observed_cleanup_attempt _ -> false)
    in
    let rec permitted = function
      | [] -> false
      | Status.Terminal _ :: _ -> false
      | (Status.Deferred | Retryable _) :: _ -> true
      | (Status.Pending _ | Joined) :: tail -> permitted tail
    in
    let next_operation =
      (not (terminal && Option.is_some (Eio.Promise.peek actor.finished)))
      && permitted statuses
    in
    let progress =
      if next_operation
      then Snapshot.Retryable
      else if (not (parent_cutoff t)) || actual_pending
      then Pending
      else if terminal
      then Terminal
      else Joined
    in
    let latest = Snapshot.create ~progress ~failures in
    t.latest <- latest;
    latest
  ;;

  let advance (t : t) ~(actor : actor) ~after =
    let open Result.Let_syntax in
    let%bind () =
      if not (on_domain t)
      then Error (error Conflict "retirement cleanup belongs to another Eio domain")
      else if
        not (phys_equal t.original.selection.issuing_actor actor.initialization_owner)
      then Error (error Conflict "retirement cleanup belongs to another actual Actor")
      else if not (Snapshot.same after t.latest)
      then Error (error Conflict "retirement cleanup snapshot is stale")
      else (
        match t.reservation with
        | Advancing ->
          Error (error Conflict "retirement cleanup already has an admitted advance")
        | Available -> Ok ())
    in
    if Snapshot.equal_progress (Snapshot.progress t.latest) Joined
    then Ok t.latest
    else (
      t.reservation <- Advancing;
      Exn.protect
        ~finally:(fun () -> t.reservation <- Available)
        ~f:(fun () ->
          Eio.Cancel.protect (fun () ->
            List.iter t.duties ~f:observe_terminal;
            if Option.is_some (Eio.Promise.peek actor.finished)
            then
              List.iter t.duties ~f:(fun duty ->
                match duty.selected_target, duty.observation with
                | Cleanup_callback _, Status.Retryable failures ->
                  duty.observation <- Status.Terminal failures
                | ( ( Cleanup_constructor _
                    | Cleanup_callback _
                    | Cleanup_idle _
                    | Cleanup_inherited _
                    | Cleanup_descendant _
                    | Cleanup_governed _
                    | Cleanup_factual _ )
                  , _ ) -> ());
            add_plan_facts t actor;
            let known_dead_terminal =
              Option.is_some (Eio.Promise.peek actor.finished)
              && List.exists t.duties ~f:(fun duty ->
                match duty.observation with
                | Terminal _ -> true
                | Deferred | Pending _ | Retryable _ | Joined -> false)
            in
            let blocked = ref false in
            List.iter t.duties ~f:(fun duty ->
              let defer_drive =
                match duty.attempt_observation with
                | Unobserved_cleanup_attempt original ->
                  (* A Turn ACK or sealed descendant Slot can still finish its
                     factual ancestor writes after the same foreground ends.
                     Join that selected producer before projecting retirement. *)
                  (match original with
                   | (Inherited_cleanup_attempt _ | Descendant_cleanup_attempt _)
                     when Runtime_retirement.is_finished (retirement t) ->
                     await_attempt duty original
                   | Inherited_cleanup_attempt _
                   | Idle_cleanup_attempt _
                   | Descendant_cleanup_attempt _
                   | Causal_cleanup_attempt _ -> observe_attempt duty original);
                  (match duty.selected_target, duty.observation with
                   | Cleanup_idle _, Status.Joined ->
                     (* Observing the older retirement attempt does not drive
                        the captured idle cutoff. Continue that same selection
                        now that its actual predecessor has joined. *)
                     duty.observation <- Status.Deferred;
                     false
                   | _ -> true)
                | No_cleanup_attempt | Observed_cleanup_attempt _ -> false
              in
              let factual =
                match duty.selected_target with
                | Cleanup_factual _ -> true
                | Cleanup_constructor _
                | Cleanup_callback _
                | Cleanup_idle _
                | Cleanup_inherited _
                | Cleanup_descendant _
                | Cleanup_governed _ -> false
              in
              let can_drive =
                (not known_dead_terminal)
                && (not !blocked)
                && (not defer_drive)
                &&
                match duty.observation with
                | Terminal _ -> false
                | Joined -> factual
                | Deferred | Pending _ | Retryable _ -> true
              in
              if can_drive
              then (
                match Failure.capture (fun () -> drive actor duty) with
                | Ok () -> ()
                | Error failure ->
                  (* Refusal/exception before a producer receipt is retained cannot
                     acquire a release fact by inspecting a later mutable phase. *)
                  duty.observation <- Status.Retryable [ failure ];
                  observe_terminal duty);
              match duty.observation with
              | Retryable _ | Terminal _ -> blocked := true
              | Deferred | Pending _ | Joined -> ());
            (* All final factual observations refer only to retained SAME cells.
             A positive before selected-parent completion remains provisional. *)
            if parent_cutoff t
            then
              List.iter t.duties ~f:(fun duty ->
                match duty.selected_target, duty.observation with
                | Cleanup_factual facts, Status.Joined ->
                  (match
                     Failure.capture (fun () ->
                       Inference_owner.Factual_usage.Host.pending facts)
                   with
                   | Ok false -> ()
                   | Ok true -> duty.observation <- Status.Retryable []
                   | Error failure -> duty.observation <- Status.Retryable [ failure ])
                | ( ( Cleanup_constructor _
                    | Cleanup_callback _
                    | Cleanup_idle _
                    | Cleanup_inherited _
                    | Cleanup_descendant _
                    | Cleanup_governed _
                    | Cleanup_factual _ )
                  , _ ) -> ());
            Ok (publish t ~actor))))
  ;;
end

module Failed_startup_disposal = struct
  type t = Failed_startup_release_data.Receipt.t

  let same_construction t ~construction =
    Failed_startup_release_data.Receipt.check_domain_exn t;
    match construction with
    | Runtime_construction.Initial continuation ->
      Failed_startup_release_data.Receipt.same_startup t continuation.target.cleanup
    | Existing_goal _ | Delegated_load _ -> false
  ;;
end

module Failed_startup_request = struct
  type actor = t
  type t = failed_startup_request

  let create (actor : actor) ~construction ~retirement =
    let open Result.Let_syntax in
    let%bind activation =
      match construction with
      | Runtime_construction.Initial continuation -> Ok continuation.target
      | Existing_goal _ | Delegated_load _ ->
        Error (error Conflict "failed startup request requires original Initial input")
    in
    let%bind () =
      if
        Int.equal actor.runtime_source_domain (Stdlib.Domain.self () :> int)
        && Int.equal activation.domain actor.runtime_source_domain
        && (not actor.stopped)
        && Option.is_some actor.canonical_persistence
        && not (Failed_startup_release_data.Gate.is_closed actor.startup_disposal)
      then Ok ()
      else Error (error Conflict "failed startup request has no supported live Actor")
    in
    let request =
      { construction
      ; retirement
      ; naming =
          Failed_startup_release_data.create
            ~issuer:actor.initialization_owner
            ~domain:actor.runtime_source_domain
            ~startup:activation.cleanup
      }
    in
    let%map _ = failed_startup_request_basis actor request in
    request
  ;;

  let released t = Failed_startup_release_data.released t.naming
end

let release_failed_startup_custody t ~request =
  let open Result.Let_syntax in
  let%bind _ = failed_startup_request_basis t request in
  call t ~priority:Priority (Runtime_retirement (Release_failed_startup request))
;;

let is_startup_disposal_only t =
  if not (Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int))
  then invalid_arg "failed startup Actor belongs to another domain";
  Failed_startup_release_data.Gate.is_closed t.startup_disposal
;;

let retire_runtime_worker_with_cleanup t ~closing =
  call t ~priority:Priority (Runtime_retirement (Capture_cleanup closing))
;;

let retire_runtime_worker t ~closing =
  call t ~priority:Priority (Runtime_retirement (Retire_worker closing))
;;

let set_compaction_inference t port =
  call t ~priority:Priority (Set_compaction_inference port)
;;

let change_moderator ?actor t moderator = call t (Change_moderator (actor, moderator))
let shell_approval_grants t = call t Shell_approval_grants

let replace_shell_approval_grants t approval_grants =
  call t (Replace_shell_approval_grants (None, approval_grants))
;;

let replace_shell_extension_snapshots t extension_snapshots =
  call t (Replace_shell_extension_snapshots (None, extension_snapshots))
;;

let shell_manifest_grants t = call t Shell_manifest_grants
let add_shell_manifest_grant t grant = call t (Add_shell_manifest_grant (None, grant))

let commit_administration t ~command_audit ~attachment_id ~expected_revision ~kind state =
  call
    t
    ?command_audit
    (Commit_administration (attachment_id, expected_revision, kind, state))
;;

let validate_administration_basis t ~attachment_id ~expected =
  call t (Validate_administration_basis (attachment_id, expected))
;;

let commit_reconciled_administration
      t
      ~command_audit
      ~attachment_id
      ~expected
      ~kind
      candidate
  =
  call
    t
    ?command_audit
    (Commit_reconciled_administration (attachment_id, expected, kind, candidate))
;;

let open_inference_owner t ~source = call t (Open_inference_owner (None, source))

let open_prepared_inference_owner t ~preparation ~source =
  call t (Open_inference_owner (Some preparation, source))
;;

let admit_inference t ~owner ~relation ~operation_id ~invocation_id ~configuration =
  call
    t
    (Admit_inference (None, owner, relation, operation_id, invocation_id, configuration))
;;

let admit_inference_allocation
      t
      ~owner
      ~relation
      ~operation_id
      ~invocation_id
      ~configuration
  =
  let open Result.Let_syntax in
  let%bind () = drain_inference_usage t in
  let%bind () = retry_descendant_admission_cleanup t in
  let%bind origin_observation = observe_inference_origin t in
  let%bind prepared =
    Eio.Cancel.protect (fun () ->
      call
        t
        (Inherited_inference
           (Prepare_legacy
              ( origin_observation
              , None
              , owner
              , relation
              , operation_id
              , invocation_id
              , configuration ))))
  in
  finish_prepared_inference t prepared
;;

let acknowledge_inference t ~owner ~handle attempt =
  call t (Acknowledge_inference (None, owner, handle, attempt))
;;

let observe_inference t ~handle incoming =
  call t (Observe_inference (None, handle, incoming))
;;

let observe_owned_inference t ~owner incoming =
  call t (Observe_owned_inference (None, owner, incoming))
;;

let complete_inference t ~owner ~handle completion =
  call t (Complete_inference (None, owner, handle, completion))
;;

let release_inference t ~owner ~handle = call t (Release_inference (None, owner, handle))
let seal_inference_owner t ~owner = call t (Seal_inference_owner owner)

let finish_inference_owner t ~owner =
  let%bind.Result acknowledgement = call t (Finish_inference_owner (None, owner)) in
  finish_joined_inference_usage t owner (fun () ->
    call t (Clear_finished_inference_owner (owner, acknowledgement)))
;;

module Input_graph = struct
  let open_owner t ~scope ~source =
    call t (Held_startup (Input_graph (Open (scope, source))))
  ;;

  let acknowledge_inference t ~scope ~owner ~handle attempt =
    call t (Held_startup (Input_graph (Acknowledge (scope, owner, handle, attempt))))
  ;;

  let observe_inference t ~scope ~owner ~handle incoming =
    call t (Held_startup (Input_graph (Observe (scope, owner, handle, incoming))))
  ;;

  let observe_owned_inference t ~scope ~owner incoming =
    call t (Held_startup (Input_graph (Observe_owned (scope, owner, incoming))))
  ;;

  let complete_inference t ~scope ~owner ~handle completion =
    call t (Held_startup (Input_graph (Complete (scope, owner, handle, completion))))
  ;;

  let release_inference t ~scope ~owner ~handle =
    call t (Held_startup (Input_graph (Release (scope, owner, handle))))
  ;;

  let seal_inference_owner t ~scope ~owner =
    call t (Held_startup (Input_graph (Seal (scope, owner))))
  ;;

  let finish_inference_owner t ~scope ~owner =
    let%bind.Result acknowledgement =
      call t (Held_startup (Input_graph (Finish (scope, owner))))
    in
    finish_joined_inference_usage t owner (fun () ->
      call t (Held_startup (Input_graph (Clear_finished (scope, owner, acknowledgement)))))
  ;;
end

module Constructor_mutations = struct
  let admit_inference
        t
        ~preparation
        ~owner
        ~relation
        ~operation_id
        ~invocation_id
        ~configuration
    =
    call
      t
      (Admit_inference
         (Some preparation, owner, relation, operation_id, invocation_id, configuration))
  ;;

  let admit_inference_allocation
        t
        ~preparation
        ~owner
        ~relation
        ~operation_id
        ~invocation_id
        ~configuration
    =
    let open Result.Let_syntax in
    let%bind () = drain_inference_usage t in
    let%bind () = retry_descendant_admission_cleanup t in
    let%bind origin_observation = observe_inference_origin t in
    let%bind prepared =
      Eio.Cancel.protect (fun () ->
        call
          t
          (Inherited_inference
             (Prepare_legacy
                ( origin_observation
                , Some preparation
                , owner
                , relation
                , operation_id
                , invocation_id
                , configuration ))))
    in
    finish_prepared_inference t prepared
  ;;

  let acknowledge_inference t ~preparation ~owner ~handle attempt =
    call t (Acknowledge_inference (Some preparation, owner, handle, attempt))
  ;;

  let observe_inference t ~preparation ~handle incoming =
    call t (Observe_inference (Some preparation, handle, incoming))
  ;;

  let observe_owned_inference t ~preparation ~owner incoming =
    call t (Observe_owned_inference (Some preparation, owner, incoming))
  ;;

  let complete_inference t ~preparation ~owner ~handle completion =
    call t (Complete_inference (Some preparation, owner, handle, completion))
  ;;

  let release_inference t ~preparation ~owner ~handle =
    call t (Release_inference (Some preparation, owner, handle))
  ;;

  let finish_inference_owner t ~preparation ~owner =
    let%bind.Result acknowledgement =
      call t (Finish_inference_owner (Some preparation, owner))
    in
    finish_joined_inference_usage t owner (fun () ->
      call t (Clear_finished_inference_owner (owner, acknowledgement)))
  ;;

  let replace_shell_approval_grants t ~preparation approval_grants =
    call t (Replace_shell_approval_grants (Some preparation, approval_grants))
  ;;

  let replace_shell_extension_snapshots t ~preparation extension_snapshots =
    call t (Replace_shell_extension_snapshots (Some preparation, extension_snapshots))
  ;;

  let add_shell_manifest_grant t ~preparation grant =
    call t (Add_shell_manifest_grant (Some preparation, grant))
  ;;
end

module Runtime_constructor_mutations = struct
  let call t request = call t (Held_startup (Construction (Mutate request)))

  let fresh t construction request =
    let%bind.Result () = Runtime_construction.refresh construction in
    call t request
  ;;

  let open_inference_owner t ~construction ~source =
    fresh t construction (Open_graph (construction, source))
  ;;

  let acknowledge_inference t ~graph ~handle attempt =
    call t (Acknowledge (graph, handle, attempt))
  ;;

  let observe_inference t ~graph ~handle incoming =
    call t (Observe (graph, handle, incoming))
  ;;

  let observe_owned_inference t ~graph incoming = call t (Observe_owned (graph, incoming))

  let complete_inference t ~graph ~handle completion =
    call t (Complete (graph, handle, completion))
  ;;

  let release_inference t ~graph ~handle = call t (Release (graph, handle))
  let seal_inference_owner t ~graph = call t (Seal graph)

  let finish_inference_owner t ~graph =
    let%bind.Result acknowledgement = call t (Finish graph) in
    finish_joined_inference_usage t graph.owner (fun () ->
      call t (Clear_finished (graph, acknowledgement)))
  ;;

  let replace_shell_approval_grants t ~construction values =
    fresh t construction (Shell_approvals (construction, values))
  ;;

  let replace_shell_extension_snapshots t ~construction values =
    fresh t construction (Shell_snapshots (construction, values))
  ;;

  let add_shell_manifest_grant t ~construction grant =
    fresh t construction (Shell_manifest (construction, grant))
  ;;

  let add_job t ~construction job = fresh t construction (Add_job (construction, job))

  let add_schedule t ~construction schedule =
    fresh t construction (Add_schedule (construction, schedule))
  ;;

  let cancel_schedule t ~construction ~schedule_id =
    fresh t construction (Cancel_schedule (construction, schedule_id))
  ;;

  let capture_model_source t ~construction ~job_id ~generation ~target ~limits =
    let open Result.Let_syntax in
    let%bind () =
      fresh
        t
        construction
        (Capture_source (construction, job_id, generation, target, limits))
    in
    Runtime_construction.refresh construction
  ;;

  let capture_recipe_target t ~construction ~job_id ~generation ~attempt ~target ~limits =
    let open Result.Let_syntax in
    let%bind () =
      fresh
        t
        construction
        (Capture_recipe (construction, job_id, generation, attempt, target, limits))
    in
    Runtime_construction.refresh construction
  ;;

  let complete_model_job t ~construction ~job_id ~generation ~attempt outcome =
    call t (Complete_model (construction, job_id, generation, attempt, outcome))
  ;;

  let interrupt_model_job t ~construction ~job_id ~generation ~attempt ~reason =
    call t (Interrupt_model (construction, job_id, generation, attempt, reason))
  ;;

  let checkpoint_moderator ?moderator_manager t ~construction moderator =
    fresh t construction (Checkpoint (construction, moderator, moderator_manager))
  ;;
end

