  model_job_port t (Inference_initialization scope)
;;

type initialization_model_producer =
  { actor : t
  ; capture : Constructor_model_data.capture
  }

let with_initialization_model_producer t ~scope ~f =
  if
    (not (Constructor_model_custody.on_domain t))
    || not (phys_equal scope.Initialization_scope.owner t.initialization_owner)
  then invalid_arg "constructor Model producer belongs to another Actor/domain";
  let producer =
    Constructor_model_producer.create ~sample:(fun () -> snd (completion_clock_pair t))
  in
  let capture =
    Constructor_model_data.
      { issuing_actor = t.initialization_owner
      ; domain = t.runtime_source_domain
      ; scope
      ; producer
      ; result = None
      ; phase = Waiting
      }
  in
  Constructor_model_producer.with_extent producer (fun () -> f { actor = t; capture })
;;

let initialization_model_producer_admission producer =
  Model_job_admission.Host.create ~admit:(fun job ->
    let open Result.Let_syntax in
    let%bind () =
      Constructor_model_custody.check_capture producer.actor producer.capture
    in
    let%bind () =
      refresh_held_execution
        producer.actor
        (Inference_initialization producer.capture.scope)
    in
    Eio.Cancel.protect (fun () ->
      call producer.actor (Constructor_model (Admit (producer.capture, job)))))
;;

let claim_initialization_model_call t producer =
  let open Result.Let_syntax in
  let%bind () = Constructor_model_custody.check_capture t producer.capture in
  Eio.Cancel.protect (fun () ->
    let%bind () =
      match Initialization_scope.construction producer.capture.scope with
      | Some ((Runtime_construction.Existing_goal _ | Delegated_load _) as construction)
        -> Runtime_construction.refresh construction
      | Some (Initial _) | None -> Ok ()
    in
    call t (Constructor_model (Claim producer.capture)))
;;

(* The actual result is owned before the first clock or mailbox suspension.
   A lost reply cannot replace it with a generic producer-exit interruption. *)
let select_initialization_model_result t producer outcome =
  let open Result.Let_syntax in
  let%map () = Constructor_model_custody.check_capture t producer.capture in
  match producer.capture.result with
  | Some _ -> ()
  | None ->
    producer.capture.result <- Some (Selecting outcome);
    let completion =
      try Constructor_model_data.Sample (snd (completion_clock_pair t)) with
      | exn -> Clock_failed (exn, Stdlib.Printexc.get_raw_backtrace ())
    in
    producer.capture.result <- Some (Selected_result { outcome; completion })
;;

let retain_initialization_model_call_result t producer outcome =
  select_initialization_model_result t producer (Some outcome)
;;

let complete_initialization_model_call t producer outcome =
  let%bind.Result () = select_initialization_model_result t producer (Some outcome) in
  call t ~priority:Priority (Constructor_model (Complete producer.capture))
;;

let interrupt_initialization_model_call t producer =
  let%bind.Result () = select_initialization_model_result t producer None in
  call t ~priority:Priority (Constructor_model (Interrupt producer.capture))
;;

