let drive_selected_idle_turn t selected =
  let capture = Inherited_turn.Capture.create () in
  Exn.protect
    ~finally:(fun () ->
      Option.iter (Inherited_turn.Capture.cancel capture) ~f:(fun plan ->
        try close_unattempted_inherited_turn t plan with
        | cleanup ->
          (try
             Eio.traceln
               "legacy inherited capture cleanup failed: %s"
               (Exn.to_string cleanup)
           with
           | _ -> ())))
    ~f:(fun () ->
      let open Result.Let_syntax in
      let%bind decision =
        Eio.Cancel.protect (fun () ->
          call t ~priority:Priority (Inherited_turn (Resume_idle (selected, capture))))
      in
      let%bind decision =
        match decision with
        | Need_private_origin captured ->
          let%bind origin = observe_descendant_origin_external t captured.origin in
          Eio.Cancel.protect (fun () ->
            call
              t
              ~priority:Priority
              (Inherited_turn (Submit_observed_origin { captured; origin })))
        | Completed _ | Pending _ | Need_idle_cleanup _ -> Ok decision
      in
      let%bind decision =
        match decision with
        | Need_idle_cleanup selected ->
          let%bind () = Idle_source.Selected.begin_cleanup selected in
          let%bind () = retry_inherited_turn_cleanup t in
          let%bind () = retry_descendant_admission_cleanup t in
          Eio.Cancel.protect (fun () ->
            call t ~priority:Priority (Inherited_turn (Resume_idle (selected, capture))))
        | Completed _ | Pending _ | Need_private_origin _ -> Ok decision
      in
      match decision with
      | Completed () -> Ok ()
      | Pending plan ->
        let%bind () = Inherited_turn.Capture.transfer capture plan in
        drive_inherited_turn t plan
      | Need_private_origin _ | Need_idle_cleanup _ ->
        Error (error Conflict "legacy Turn continuation did not settle"))
;;

module Idle_moderator_completion = struct
  type actor = t

  type t =
    { actor : actor
    ; completion : Idle_completion_data.t
    ; mutable continuation : Idle_continuation.t option
    }

  let create (actor : actor) =
    let exited, exit = Eio.Promise.create () in
    let completion : Idle_completion_data.t =
      { issuing_actor = actor.inference_owner_identity
      ; identity = ref ()
      ; domain = actor.runtime_source_domain
      ; exited
      ; exit
      ; phase = Fresh
      ; action = None
      ; prefix = Empty
      ; pending_prefix = None
      ; write = None
      ; suffix = None
      ; drain = None
      ; outcome = None
      ; cancellation = None
      ; cleanup = Idle
      }
    in
    { actor; completion; continuation = None }
  ;;

  let check (t : t) = check_idle_completion_identity t.actor t.completion

  let claim t =
    let%bind.Result () = check t in
    call t.actor (Idle_completion (Claim_paired t.completion))
  ;;

  let capture t drain =
    let%bind.Result () = check t in
    call
      t.actor
      ~priority:Priority
      (Idle_completion (Capture_paired (t.completion, drain)))
  ;;

  let fail_callback t ~failure =
    let%bind.Result () = check t in
    call
      t.actor
      ~priority:Priority
      (Idle_completion (Fail_paired (t.completion, failure)))
  ;;

  let leave_capture t =
    match check t with
    | Error _ -> ()
    | Ok () ->
      (match Eio.Promise.peek t.completion.exited with
       | None -> Eio.Promise.resolve t.completion.exit ()
       | Some () -> ())
  ;;

  let finish t =
    let%bind.Result () = check t in
    let continuation =
      match t.continuation with
      | Some actual -> Some actual
      | None ->
        (match t.actor.idle_turn_continuation with
         | Some actual when phys_equal actual.Idle_continuation.owner t.completion ->
           t.continuation <- Some actual;
           Some actual
         | None | Some _ -> None)
    in
    match continuation with
    | None ->
      (match t.completion.outcome with
       | Some result -> result
       | None -> Error (error Conflict "legacy callback has no captured outcome"))
    | Some continuation ->
      (match continuation.finish with
       | Settled promise | Running promise -> Actor_reply.await promise
       | Not_started ->
         let promise, resolver = Eio.Promise.create () in
         continuation.finish <- Running promise;
         let settle result =
           continuation.finish <- Settled promise;
           Actor_reply.resolve resolver result
         in
         let settle_exception exn backtrace =
           continuation.finish <- Settled promise;
           Actor_reply.resolve_exception resolver exn backtrace
         in
         let retire failure =
           Idle_completion_data.request_cancellation t.completion failure;
           cancel_idle_turn_continuation t.actor t.completion failure;
           try
             match schedule_idle_completion_retirement t.actor t.completion with
             | Ok _ | Error _ -> ()
           with
           | cleanup ->
             (try
                Eio.traceln
                  "legacy Turn retirement setup failed: %s"
                  (Exn.to_string cleanup)
              with
              | _ -> ())
         in
         (match
            match continuation.phase with
            | Selected selected -> drive_selected_idle_turn t.actor selected
            | Bound _ -> Error (error Conflict "legacy Turn already has a common driver")
          with
          | result ->
            (match result with
             | Ok () -> ()
             | Error failure -> retire failure);
            settle result;
            result
          | exception exn ->
            let backtrace = Stdlib.Printexc.get_raw_backtrace () in
            retire (error Interrupted "legacy Turn finish was interrupted");
            settle_exception exn backtrace;
            Exn.raise_with_original_backtrace exn backtrace))
  ;;

  let cancel t ~failure =
    match check t with
    | Error _ -> ()
    | Ok () ->
      Idle_completion_data.request_cancellation t.completion failure;
      cancel_idle_turn_continuation t.actor t.completion failure;
      (match schedule_idle_completion_retirement t.actor t.completion with
       | Ok _ | Error _ -> ())
  ;;

  let join_retirement t =
    let%bind.Result () = check t in
    let%bind.Result promise = schedule_idle_completion_retirement t.actor t.completion in
    Eio.Promise.await promise
  ;;
end

