let recurrence_native_command t ~admission ~authorize ~refresh ~request =
  let module N = Recurrence_native_admission in
  let module C = Recurrence_command in
  let open Result.Let_syntax in
  let effect_kind : N.Effect.t =
    match request.C.mutation with
    | Create _ -> Create
    | Edit _ -> Edit
    | Enable _ -> Resume
    | Pause _ -> Pause
    | Retire _ -> Cancel
  in
  let%bind () =
    if Int.equal t.runtime_source_domain (Stdlib.Domain.self () :> int)
    then Ok ()
    else Error (error Conflict "recurrence native original belongs to another Eio domain")
  in
  let check_now () = N.check_now admission t.state ~effect_kind in
  let%bind () = check_now () in
  let actor = N.actor admission in
  let catalog =
    Option.value t.state.recurrence_catalog ~default:Recurrence_catalog.empty
  in
  let principal_id = (Operator_authorization.principal actor).id in
  let retained = Recurrence_catalog.find_receipt catalog ~principal_id ~key:request.key in
  let needs_selection =
    Option.is_none retained
    &&
    match request.mutation with
    | Create (_, capture) ->
      (match Recurrence_target.view capture.target with
       | Fresh_child _ -> true
       | Existing_session _ -> false)
    | Edit (id, _) ->
      Option.exists (Recurrence_catalog.find catalog id) ~f:(fun entry ->
        match Recurrence_definition.goal_binding (Recurrence_entry.current entry) with
        | Controller_goal _ -> true
        | Unbound -> false)
    | Enable _ | Pause _ | Retire _ -> false
  in
  let%bind selection, preparation =
    if not needs_selection
    then Ok (None, None)
    else (
      let invocation = N.invocation admission in
      let current_execution () =
        List.find t.invocation_executions ~f:(fun execution ->
          Agent_protocol.Invocation.equal execution.dispatched invocation
          && Atomic.get execution.authority_live)
        |> Result.of_option
             ~error:(error Conflict "recurrence native dispatch owner changed")
      in
      let%bind execution = current_execution () in
      let%bind selected =
        authorized_native_child_basis t (Inference_invocation execution)
      in
      let select () =
        let%bind () = check_now () in
        let%bind actual = current_execution () in
        let%bind () =
          if phys_equal actual execution
          then Ok ()
          else Error (error Conflict "recurrence native execution was replaced")
        in
        let%bind () = selected.check_current () in
        let basis = selected.selected.execution in
        match basis.attribution, inherited_turn_required t.state with
        | (Some _ as attribution), _ -> Ok attribution
        | None, Ordinary -> Ok None
        | None, (Scoped | Need_private_origin) ->
          Error
            (error
               Permission_denied
               "recurrence native creation requires a supported local Goal or known \
                unrelated origin")
      in
      let%map _ = select () in
      Some select, selected.selected.execution.preparation)
  in
  (* All inherited/host checks yield here, on the original caller fiber.
     The actual writer only uses the finite local captured checks. *)
  let%bind () = refresh () in
  let%bind () = check_now () in
  let native : Recurrence_native_publication.t = { admission; selection; preparation } in
  call t (Apply_recurrence_command (actor, authorize, request, Some native))
;;

