(* Only recurrence acquisition/cleanup mask caller cancellation. Every sweep
   request observes owner exit, since the scheduler may outlive that actor.
   [Fiber.first] cancels and joins the losing waiter; termination grants no ACK. *)
let recurrence_call t ?(priority = Mailbox.Normal) request =
  let unavailable () =
    Error (error Server_shutting_down "recurrence actor has terminated")
  in
  match Eio.Promise.peek t.finished with
  | Some () -> unavailable ()
  | None ->
    Eio.Fiber.first
      (fun () -> call t ~priority request)
      (fun () ->
         Eio.Promise.await t.finished;
         unavailable ())
;;

(* Call only from outer driver/Factory; all actual private Store observations
   finish before the finite consume request enters the Actor. No cancellation
   mask encloses the remote operation. Host already owns each attempt/set. *)
let descendant_root_call t operation =
  let open Result.Let_syntax in
  let%bind captured = recurrence_call t (Descendant_root (Capture operation)) in
  let%bind observed = observe_descendant_root t captured in
  recurrence_call t (Descendant_root (Consume observed))
;;

(* Exactly one read-only recapture is allowed. Errors, policy/authority changes,
   Store failures and cancellation are never retry signals. *)
let refresh_descendant_admitted_root t ~reservation ~acknowledgement ~confirmation =
  let module Q = Descendant_root_request in
  let open Result.Let_syntax in
  let attempt () =
    let%bind captured =
      recurrence_call
        t
        (Descendant_root
           (Capture (Refresh_admitted (reservation, acknowledgement, confirmation))))
    in
    let%bind observed = observe_descendant_admitted_root t captured in
    match observed with
    | Q.Admitted_refresh.State_changed -> Ok Q.Admitted_refresh.State_changed
    | Current observed -> recurrence_call t (Descendant_root (Consume_admitted observed))
  in
  let%bind first = attempt () in
  match first with
  | Q.Admitted_refresh.Current view -> Ok view
  | State_changed ->
    Eio.Fiber.yield ();
    let%bind second = attempt () in
    (match second with
     | Current view -> Ok view
     | State_changed ->
       Error
         (Agent_protocol.Error.create
            Conflict
            ~message:"admitted root observation changed during both bounded attempts"
            ~retryable:true
            ()))
;;

let refresh_descendant_usage t ~source_owner ~source =
  let open Result.Let_syntax in
  let%bind captured =
    recurrence_call t (Child_accounting (Capture_descendant_usage (source_owner, source)))
  in
  let%bind observed = observe_descendant_usage_external t captured in
  let check () = check_descendant_usage_source t observed in
  let%map () = check () in
  observed, check
;;

let observe_descendant_usage t ~source_owner ~source =
  let open Result.Let_syntax in
  let refresh_read () =
    let%map _, check = refresh_descendant_usage t ~source_owner ~source in
    check
  in
  let%bind observed, _ = refresh_descendant_usage t ~source_owner ~source in
  recurrence_call t (Child_accounting (Observe_descendant_usage (observed, refresh_read)))
;;

module Descendant_admission = struct
  module R = Descendant_admission_data
  module Preparation = R.Preparation
  module Root_route = R.Root_route
  module Reservation = R.Reservation
  module Reservation_attempt = R.Reservation_attempt
  module Reservation_set = R.Reservation_set
  module Reserve_result = R.Reserve_result
  module Root_before_writer = R.Root_before_writer
  module Closed_before_writer = Descendant_preparation.Closed_before_writer

  module Before_writer = struct
    include R.Before_writer

    let check_current = check_descendant_before_writer
  end

  module Acknowledgement = struct
    include R.Acknowledgement

    let reservations t = t.reservations
  end

  module Import_acknowledgement = R.Import_acknowledgement

  let observe_acknowledged_usage t ~source_owner ~acknowledgement =
    observe_descendant_usage
      t
      ~source_owner
      ~source:(Descendant_usage.Source.Acknowledged acknowledgement)
  ;;

  let observe_imported_usage t ~source_owner ~acknowledgement =
    observe_descendant_usage
      t
      ~source_owner
      ~source:(Descendant_usage.Source.Imported acknowledgement)
  ;;

  module Confirmation = R.Confirmation
  module Root_admitted = R.Root_admitted

  module Admitted_views = struct
    include R.Admitted_views

    let check_current = check_descendant_admitted_views
  end

  let bind_root_routes t ~source_owner ~ancestry ~preparation =
    descendant_root_call t (Bind (source_owner, ancestry, preparation))
  ;;

  let begin_reservation t ~route ~reservations =
    descendant_root_call t (Begin (route, reservations))
  ;;

  let commit_reservation t ~attempt =
    (* Physically attempted/unknown never re-enters Capture, planner or writer,
       even if current State/child owner changed while publication was pending. *)
    if
      not
        (Int.equal
           attempt.R.Reservation_attempt.basis.domain
           (Stdlib.Domain.self () :> int))
    then Error (error Conflict "root attempt belongs to another domain")
    else (
      match Reservation_attempt.outcome attempt with
      | Acknowledged reservation -> Ok (Reserve_result.Reserved reservation)
      | Attempt_unconfirmed -> Ok (Reserve_result.Attempt_unconfirmed attempt)
      | Not_attempted -> descendant_root_call t (Commit attempt))
  ;;

  let reconcile_reservation t ~attempt = descendant_root_call t (Reconcile attempt)

  let refresh_reserved t ~reservation =
    descendant_root_call t (Refresh_reserved reservation)
  ;;

  let prepare_before_writer = prepare_descendant_before_writer

  let close_before_writer t ~reservation ~closed =
    let open Result.Let_syntax in
    let%bind known = Root_close_acknowledgement.acknowledged reservation ~closed in
    if known
    then Ok ()
    else (
      let result = descendant_root_call t (Close (reservation, closed)) in
      let%bind known = Root_close_acknowledgement.acknowledged reservation ~closed in
      if known then Ok () else result)
  ;;

  let import_usage t ~source_owner ~observation =
    descendant_root_call t (Import (source_owner, observation))
  ;;

  let confirmation = descendant_confirmation

  let refresh_admitted_root t ~reservation ~acknowledgement ~confirmation =
    refresh_descendant_admitted_root t ~reservation ~acknowledgement ~confirmation
  ;;

  let admitted_views = descendant_admitted_views
end

(* Opaque facade: these aliases expose no private constructors or Actor fields. *)
module Causal_admission = struct
  module Preparation = struct
    type t = Goal_causal_admission_custody.Preparation.t

    let session t =
      Recurrence_controller.session
        t.Goal_causal_admission_custody.Preparation.basis.controller
    ;;
  end

  module Reservation = struct
    type t = causal_reservation

    let owner t = t.native_reservation.attempt.route.owner
  end

  module Reservation_attempt = struct
    type t = causal_reservation_attempt

    let owner t = t.native_attempt.route.owner

    let check_domain t =
      if
        Int.equal t.native_attempt.route.domain (Stdlib.Domain.self () :> int)
        && Goal_causal_admission_custody.Preparation.on_domain
             t.native_attempt.route.preparation
      then ()
      else invalid_arg "causal reservation factual read belongs to another domain"
    ;;

    let acknowledged t =
      check_domain t;
      match t.native_attempt.phase with
      | Goal_causal_admission_custody.Remote.Reserved reservation ->
        Some (causal_reserved t reservation)
      | Begun | Writer_prepared _ | Not_reserved _ -> None
    ;;

    type outcome =
      | Not_attempted
      | Known_not_reserved
      | Acknowledged of Reservation.t
      | Attempt_unconfirmed

    let outcome t =
      check_domain t;
      match t.native_attempt.phase with
      | Goal_causal_admission_custody.Remote.Begun -> Not_attempted
      | Not_reserved _ -> Known_not_reserved
      | Reserved reservation -> Acknowledged (causal_reserved t reservation)
      | Writer_prepared _ -> Attempt_unconfirmed
    ;;
  end

  module Root_before_writer = struct
    type t = causal_root_before_writer
  end

  module Before_writer = struct
    type t = causal_before_writer
  end

  let prepare_before_writer = prepare_causal_before_writer

  module Reserve_result = struct
    type t = causal_reserve_result =
      | Reserved of Reservation.t
      | Blocked of Goal_admission_policy.Count_availability.t
      | Attempt_unconfirmed of Reservation_attempt.t
  end

  module Reservation_set = struct
    type t = causal_reservation_set

    let preparation t = t.native_set.Goal_causal_admission_custody.Set.preparation

    let attempts t =
      if
        not (Goal_causal_admission_custody.Preparation.on_domain t.native_set.preparation)
      then invalid_arg "causal Set factual read belongs to another domain";
      t.actual_attempts
    ;;

    let requests t =
      let%bind.Result () = check_causal_reservation_set t in
      Goal_causal_admission_custody.Set.frozen t.native_set
      |> Result.map ~f:(fun frozen ->
        frozen.Goal_causal_admission_custody.Frozen_routes.requests)
    ;;
  end

  module Acknowledgement = struct
    type t = causal_canonical_acknowledgement

    let reservations t = t.actual_reservations
  end

  module Usage_observation = struct
    type t = causal_usage_observation
  end

  module Import_acknowledgement = struct
    type t = causal_import_acknowledgement

    let reservation t = t.actual_reservation
  end

  module Closed_before_writer = struct
    type t = causal_closed_before_writer
  end

  module Confirmation = struct
    type t = causal_confirmation

    let imports t = t.imports
  end

  module Root_admitted = struct
    type t = causal_root_admitted
  end

  module Admitted_views = struct
    type t = causal_admitted_views

    let check_current = check_causal_admitted_views
  end

  module Correction_attempt = struct
    type t = causal_root_write
  end

  module Correction_acknowledgement = struct
    type t = causal_correction_acknowledgement
  end

  module No_write = struct
    type t = causal_correction_no_write =
      | Exact_duplicate
      | Superseded
  end

  module Correction_preparation = struct
    type t = causal_correction_preparation =
      | Prepared of Correction_attempt.t
      | No_write of No_write.t
      | Awaiting_initial_confirmation
  end

  let terminal t operation =
    let open Result.Let_syntax in
    let%bind captured =
      recurrence_call t (Causal_route (Capture_causal_terminal operation))
    in
    let%bind observed = observe_causal_terminal_external t captured in
    recurrence_call t (Causal_route (Consume_causal_terminal observed))
  ;;

  let import_usage t ~reservation ~observation =
    terminal t (Import_causal_usage (reservation, observation))
  ;;

  let prepare_correction t ~acknowledgement ~observation =
    terminal t (Prepare_causal_correction (acknowledgement, observation))
  ;;

  let commit_correction t ~attempt =
    recurrence_call t (Causal_route (Commit_causal_correction attempt))
  ;;

  let reconcile_correction t ~attempt =
    recurrence_call t (Causal_route (Reconcile_causal_correction attempt))
  ;;

  let retained_correction t ~acknowledgement ~observation =
    recurrence_call
      t
      (Causal_route (Retained_causal_correction (acknowledgement, observation)))
  ;;

  let abandon_correction t ~attempt =
    recurrence_call t (Causal_route (Abandon_causal_correction attempt))
  ;;

  let reconcile_usage t ~reservation ~observation =
    recurrence_call t (Causal_route (Reconcile_causal_import (reservation, observation)))
  ;;

  let close_before_writer t ~reservation ~closed =
    terminal t (Close_causal_pending (reservation, closed))
  ;;

  let confirmation = causal_confirmation

  let refresh_admitted_root t ~reservation ~acknowledgement ~confirmation =
    terminal t (Refresh_causal_admitted (reservation, acknowledgement, confirmation))
  ;;

  let admitted_views ~acknowledgement ~confirmation ~views =
    let admitted = { acknowledgement; confirmation; root_views = views } in
    let%map.Result () = check_causal_admitted_views admitted in
    admitted
  ;;

  module Route_observation = struct
    type t = causal_route_observation

    let owners = causal_route_owners
  end

  module Root_route = struct
    type t = causal_root_route

    let owner t = t.native.Goal_causal_admission_custody.Route.owner
    let target t = t.native.Goal_causal_admission_custody.Route.target
  end

  let observe_usage t ~source_owner source =
    let open Result.Let_syntax in
    let%bind captured =
      recurrence_call t (Causal_route (Capture_causal_usage (source_owner, source)))
    in
    let%bind observed = observe_causal_usage_external captured in
    recurrence_call t (Causal_route (Consume_causal_usage observed))
  ;;

  let observe_acknowledged_usage t ~source_owner ~acknowledgement =
    observe_usage t ~source_owner (Canonical_causal_usage acknowledgement)
  ;;

  let observe_imported_usage t ~source_owner ~acknowledgement =
    let%bind.Result source = causal_imported_usage_source acknowledgement in
    observe_usage t ~source_owner source
  ;;

  let observe_routes t ~source_owner ~preparation ~reservations ~callee_ancestry =
    let open Result.Let_syntax in
    let%bind captured =
      recurrence_call
        t
        (Causal_route
           (Capture_causal_routes
              (source_owner, preparation, reservations, callee_ancestry)))
    in
    let%bind observed = observe_causal_routes_external captured in
    recurrence_call t (Causal_route (Consume_causal_routes observed))
  ;;

  let bind_root_routes t ~source_owner ~observation =
    let open Result.Let_syntax in
    let%bind captured =
      recurrence_call t (Causal_route (Capture_causal_root (source_owner, observation)))
    in
    let%bind observed = observe_causal_root_external t captured in
    recurrence_call t (Causal_route (Consume_causal_root observed))
  ;;

  let begin_reservation t ~route ~reservations =
    let open Result.Let_syntax in
    let%bind captured =
      recurrence_call
        t
        (Causal_route
           (Capture_causal_reservation (Begin_causal_reservation (route, reservations))))
    in
    let%bind observed = observe_causal_reservation_external t captured in
    recurrence_call t (Causal_route (Consume_causal_reservation observed))
  ;;

  let commit_reservation t ~attempt =
    let open Result.Let_syntax in
    let%bind retained = causal_attempt_result t attempt in
    match retained with
    | Some retained -> Ok retained
    | None ->
      let%bind captured =
        recurrence_call
          t
          (Causal_route (Capture_causal_reservation (Commit_causal_reservation attempt)))
      in
      let%bind observed = observe_causal_reservation_external t captured in
      recurrence_call t (Causal_route (Consume_causal_reservation observed))
  ;;

  let reconcile_reservation t ~attempt =
    let open Result.Let_syntax in
    let%bind retained = causal_attempt_result t attempt in
    match retained with
    | Some retained -> Ok retained
    | None -> Error (error Conflict "causal reservation writer has not been invoked")
  ;;

  let refresh_reserved t ~reservation =
    let open Result.Let_syntax in
    let%bind () = causal_attempt_owner t reservation.actual_attempt in
    let%bind captured =
      recurrence_call
        t
        (Causal_route
           (Capture_causal_reservation (Refresh_causal_reservation reservation)))
    in
    let%bind observed = observe_causal_reservation_external t captured in
    recurrence_call t (Causal_route (Consume_causal_reservation observed))
  ;;

  (* SAME614 cell elects these callbacks. The cursor retains only immutable
     observations and exact operations; it contains no election or IO callback. *)
  let transport (acknowledgement : Acknowledgement.t) =
    let open Result.Let_syntax in
    let%bind () = check_causal_canonical_acknowledgement acknowledgement in
    let transport = acknowledgement.transport in
    let original = acknowledgement.native_acknowledgement.preparation.basis in
    let%bind controller =
      Causal_factual_basis.owner
        acknowledgement.callee
        ~source_owner:original.source_owner
    in
    if
      Int.equal transport.domain (Stdlib.Domain.self () :> int)
      && phys_equal transport.identity acknowledgement.native_acknowledgement.identity
      && phys_equal controller original.controller
      && Agent_protocol.Session_ref.equal
           (Recurrence_controller.session controller)
           (Recurrence_controller.session original.controller)
    then Ok transport
    else
      Error
        (error
           Conflict
           "causal factual transport has another actual ACK/domain/Store owner")
  ;;

  let check_transport_source actor ~source_owner acknowledgement =
    let open Result.Let_syntax in
    let%bind transport = transport acknowledgement in
    let original = acknowledgement.native_acknowledgement.preparation.basis in
    let%bind controller = Causal_factual_basis.owner actor ~source_owner in
    if
      phys_equal actor acknowledgement.callee
      && Runtime_source_owner.matches
           source_owner
           (Runtime_source_owner.identity original.source_owner)
      && phys_equal controller original.controller
      && Agent_protocol.Session_ref.equal
           (Recurrence_controller.session controller)
           (Recurrence_controller.session original.controller)
    then Ok transport
    else Error (error Conflict "causal transport has another actual source Actor/Store")
  ;;

  let initial_usage actor ~source_owner ~acknowledgement =
    let open Result.Let_syntax in
    let%bind cursor = check_transport_source actor ~source_owner acknowledgement in
    match cursor.initial with
    | Initial_observed { observation; _ } ->
      let%map () = check_causal_usage_observation observation in
      observation
    | Initial_confirmed _ ->
      Error (error Conflict "causal initial usage is already fully confirmed")
    | Initial_unobserved ->
      let%bind observation =
        observe_acknowledged_usage actor ~source_owner ~acknowledgement
      in
      let%bind () = check_causal_usage_observation observation in
      let retained = Initial_observed { observation; imports = [] } in
      cursor.initial <- retained;
      Ok observation
  ;;

  let initial_imports acknowledgement =
    let%map.Result cursor = transport acknowledgement in
    match cursor.initial with
    | Initial_unobserved -> []
    | Initial_observed { imports; _ } -> imports
    | Initial_confirmed confirmation -> confirmation.imports
  ;;

  let initial_confirmation acknowledgement =
    let%map.Result cursor = transport acknowledgement in
    match cursor.initial with
    | Initial_confirmed confirmation -> Some confirmation
    | Initial_unobserved | Initial_observed _ -> None
  ;;

  let retain_initial_import acknowledgement ~observation ~imported =
    let open Result.Let_syntax in
    let%bind cursor = transport acknowledgement in
    match cursor.initial with
    | Initial_unobserved ->
      Error (error Conflict "causal initial import has no retained observation")
    | Initial_confirmed _ ->
      Error (error Conflict "causal initial confirmation cannot be overwritten")
    | Initial_observed previous ->
      let%bind () =
        if phys_equal observation previous.observation
        then Ok ()
        else Error (error Conflict "causal initial import changed its exact observation")
      in
      let index = List.length previous.imports in
      let%bind attempt =
        List.nth acknowledgement.actual_reservations.actual_attempts index
        |> Result.of_option
             ~error:(error Conflict "causal initial import exceeds the frozen vector")
      in
      let%bind () = check_causal_confirmation_import acknowledgement attempt imported in
      let%bind projection =
        causal_terminal_projection imported.actual_reservation observation
      in
      let%bind () =
        if
          Document_schema.Json.equal
            (Policy_canonical_usage.Projection.to_json projection)
            (Policy_canonical_usage.Projection.to_json imported.native_import.projection)
        then Ok ()
        else
          Error
            (error
               Conflict
               "causal initial import differs from retained complete observation")
      in
      let retained =
        Initial_observed { observation; imports = previous.imports @ [ imported ] }
      in
      cursor.initial <- retained;
      Ok ()
  ;;

  let retain_initial_confirmation acknowledgement confirmation =
    let open Result.Let_syntax in
    let%bind cursor = transport acknowledgement in
    let%bind () = check_causal_confirmation acknowledgement confirmation in
    match cursor.initial with
    | Initial_confirmed actual ->
      if phys_equal actual confirmation
      then Ok ()
      else Error (error Conflict "causal initial confirmation is already retained")
    | Initial_unobserved ->
      (* Zero remote requests still have a genuine canonical ACK/complete Set;
         do not infer standalone or skip the actual route validation. *)
      if List.is_empty confirmation.imports
      then (
        let retained = Initial_confirmed confirmation in
        cursor.initial <- retained;
        Ok ())
      else
        Error (error Conflict "causal initial confirmation has no retained import prefix")
    | Initial_observed previous ->
      if List.equal phys_equal previous.imports confirmation.imports
      then (
        let corrections =
          List.map confirmation.imports ~f:(fun initial_import ->
            { initial_import; stage = Correction_idle })
        in
        let retained = Initial_confirmed confirmation in
        cursor.corrections <- corrections;
        cursor.initial <- retained;
        Ok ())
      else
        Error
          (error Conflict "causal confirmation differs from SAME retained initial vector")
  ;;

  let correct_imported_usage actor ~source_owner ~acknowledgement ~imported =
    let module F = Inference_graph_owner.Factual_usage in
    let open Result.Let_syntax in
    let%bind cursor = check_transport_source actor ~source_owner acknowledgement in
    let%bind () =
      match cursor.initial with
      | Initial_confirmed confirmation ->
        check_causal_confirmation acknowledgement confirmation
      | Initial_unobserved | Initial_observed _ ->
        Error (error Conflict "causal corrections require the exact full initial vector")
    in
    let%bind entry =
      List.find cursor.corrections ~f:(fun entry ->
        phys_equal entry.initial_import imported)
      |> Result.of_option
           ~error:
             (error Conflict "causal correction has another retained initial receipt")
    in
    let root = imported.actual_reservation.actual_attempt.route.root_actor in
    let%bind observation =
      match entry.stage with
      | Correction_observed observation | Correction_prepared { observation; _ } ->
        Ok observation
      | Correction_idle ->
        let%bind observation =
          observe_imported_usage actor ~source_owner ~acknowledgement:imported
        in
        let retained = Correction_observed observation in
        entry.stage <- retained;
        Ok observation
    in
    let%bind prepared =
      match entry.stage with
      | Correction_prepared { attempt; _ } -> Ok (Correction_preparation.Prepared attempt)
      | Correction_observed _ ->
        let%bind retained =
          retained_correction root ~acknowledgement:imported ~observation
        in
        (match retained with
         | Some attempt -> Ok (Correction_preparation.Prepared attempt)
         | None -> prepare_correction root ~acknowledgement:imported ~observation)
      | Correction_idle ->
        Error (error Invalid_state "causal correction observation was displaced")
    in
    match prepared with
    | Correction_preparation.No_write _ ->
      entry.stage <- Correction_idle;
      Ok F.Correction_outcome.Settled
    | Awaiting_initial_confirmation ->
      Ok F.Correction_outcome.Awaiting_initial_confirmation
    | Prepared attempt ->
      let retained = Correction_prepared { observation; attempt } in
      entry.stage <- retained;
      let retain_failure () =
        (* Only this SAME failed operation's genuine monotone seal can restore
           observed retry state. Entered/unknown remains Prepared forever until
           actual reconciliation, never another writer invocation. *)
        match Session_commit_attempt.No_writer.seal attempt.writer with
        | Error _ -> ()
        | Ok token ->
          (match attempt.acknowledgement with
           | Causal_terminal { context; plan; _ } ->
             let write = Goal_causal_admission_custody.Terminal_install.write plan in
             if
               Session_commit_attempt.No_writer.matches_terminal
                 token
                 ~attempt:attempt.writer
                 ~operation:write.operation.identity
                 ~reservation:
                   context.terminal_reservation.actual_attempt.native_attempt.identity
                 ~previous:attempt.previous
                 ~candidate:attempt.candidate
             then entry.stage <- Correction_observed observation
           | Causal_reserved _ | Causal_held _ -> ())
      in
      (match commit_correction root ~attempt with
       | Ok _ ->
         entry.stage <- Correction_idle;
         Ok F.Correction_outcome.Settled
       | Error failure ->
         retain_failure ();
         Error failure
       | exception exn ->
         let backtrace = Stdlib.Printexc.get_raw_backtrace () in
         retain_failure ();
         Exn.raise_with_original_backtrace exn backtrace)
  ;;
end

module Descendant_host = struct
  include Descendant_host_data

  module Causal_driver = struct
    type t = causal_driver =
      { prepare :
          Causal_admission.Preparation.t
          -> Causal_admission.Reservation_set.t
          -> (Causal_admission.Before_writer.t, Agent_protocol.Error.t) result
      ; close :
          Causal_admission.Reservation_set.t
          -> Causal_admission.Closed_before_writer.t
          -> (unit, Agent_protocol.Error.t) result
      ; confirm :
          Causal_admission.Acknowledgement.t
          -> (Causal_admission.Confirmation.t, Agent_protocol.Error.t) result
      ; refresh_admitted :
          Causal_admission.Acknowledgement.t
          -> Causal_admission.Confirmation.t
          -> (Causal_admission.Admitted_views.t, Agent_protocol.Error.t) result
      ; correct_usage :
          Causal_admission.Acknowledgement.t
          -> Causal_admission.Confirmation.t
          -> ( Inference_graph_owner.Factual_usage.Correction_outcome.t
               , Agent_protocol.Error.t )
               result
      }
  end
end

let install_descendant_host_for
      purpose
      ?causal_driver
      t
      ~source_owner
      ~expected
      ~check_ancestry
      ~host
  =
  (* Only finite local ownership transfer is protected. The Factory retains the
     returned exact binding before any cancellation/build/Store await. *)
  Eio.Cancel.protect (fun () ->
    recurrence_call
      t
      (Install_descendant_host
         (purpose, source_owner, expected, check_ancestry, host, causal_driver)))
;;

let install_descendant_host ?policy_restoration =
  let purpose =
    match policy_restoration with
    | None -> Descendant_host_installation.Ordinary
    | Some restoration -> Restored restoration
  in
  install_descendant_host_for purpose
;;

let install_ordinary_ready_descendant_host
      ?initialization_scope
      ?causal_driver
      t
      ~source_owner
      ~expected
      ~host
  =
  install_descendant_host_for
    (Ordinary_ready_reload initialization_scope)
    ?causal_driver
    t
    ~source_owner
    ~expected
    ~check_ancestry:None
    ~host
;;

(* Closed refresh protocol: only capture/consume enter the Actor; private Store
   reads and original authorization run in the caller without Owner locks. *)
let refresh_child_origin_preparation t (preparation : Child_origin.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = check_child_origin_preparation t preparation in
  (* Invalidate before the first mailbox wait too. Attempt identity orders even
     captures whose callers cancel while queued; no older completion can renew
     the cache after a newer failed/cancelled refresh. *)
  let attempt = ref () in
  preparation.refresh_attempt <- Some attempt;
  preparation.observed <- None;
  preparation.captured <- None;
  let consumed = ref false in
  Exn.protect
    ~f:(fun () ->
      let%bind captured =
        recurrence_call
          t
          (Child_accounting (Capture_origin_refresh (preparation, attempt)))
      in
      let%bind observed = Child_origin.Captured_refresh.observe captured in
      let%map () =
        recurrence_call t (Child_accounting (Consume_origin_refresh observed))
      in
      consumed := true)
    ~finally:(fun () ->
      (* A cancelled queued Consume must not publish after its caller exits.
         Cleanup is pure and scoped to this exact attempt, so an older failure
         cannot clear a newer refresh's successful observation. *)
      if
        (not !consumed)
        && Option.exists preparation.refresh_attempt ~f:(phys_equal attempt)
      then (
        preparation.refresh_attempt <- None;
        preparation.captured <- None;
        preparation.observed <- None))
;;

let publish_child_origin_preparation t (preparation : Child_origin.Preparation.t) =
  let open Result.Let_syntax in
  let%bind () = check_child_origin_preparation t preparation in
  (* Installed once before publishing this otherwise private preparation. It is
     never accepted from a caller and always routes back to this actual Actor. *)
  preparation.refresh_current
  <- (fun () -> refresh_child_origin_preparation t preparation);
  let%map () = Child_origin.Preparation.refresh_current preparation in
  preparation
;;

