let install_held_runtime
      ?unmoderated_source
      ?automatic_turn_policy
      ?moderator_manager
      t
      ~continuation
      ~worker
      ~inference
  =
  let open Result.Let_syntax in
  let%bind () = held_runtime_installation_basis t continuation in
  let%bind () = Admitted_activation.Continuation.refresh continuation in
  Eio.Cancel.protect (fun () ->
    let%bind () =
      match automatic_turn_policy with
      | None -> Ok ()
      | Some policy ->
        let%bind () = call t (Held_startup (Enable_turn_budget (continuation, policy))) in
        (* The factual policy ACK can rotate target/controller Store custody.
           Refresh outside the mailbox before physical installation. *)
        Admitted_activation.Continuation.refresh continuation
    in
    call
      t
      (Held_startup
         (Install_runtime
            (continuation, worker, inference, moderator_manager, unmoderated_source))))
;;

let submit_held_run_input t ~scope ~input =
  let open Result.Let_syntax in
  let%bind () =
    if
      Int.equal scope.Held_input_scope.domain (Stdlib.Domain.self () :> int)
      && phys_equal scope.issuing_actor t.inference_owner_identity
    then Ok ()
    else Error (error Conflict "held input belongs to another actor or domain")
  in
  let%bind () =
    match scope.phase with
    | Parsed_ready recorded
      when Runtime_input_preparation.Prepared_input.equal recorded input -> Ok ()
    | Parsing
    | Parsed_ready _
    | Admission_pending _
    | Consumed _
    | Root_attempt_unconfirmed
    | Closed ->
      Error
        (error Conflict "held root input has already been submitted or is unavailable")
  in
  let%bind () = Admitted_activation.Continuation.refresh scope.continuation in
  let%bind () =
    match inherited_turn_required t.state with
    | Scoped ->
      let%bind () = retry_inherited_turn_cleanup t in
      retry_descendant_admission_cleanup t
    | Ordinary | Need_private_origin -> Ok ()
  in
  submit_turn_input t (Inherited_turn.Input.Held_input (scope, input))
;;

let held_authored_resource t ~continuation ~owner =
  let%bind.Result () = Admitted_activation.Continuation.refresh continuation in
  call t (Held_startup (Authored_resource (continuation, owner)))
;;

let start_held_authored_run t ~continuation ~startup =
  let module Cleanup = Failed_startup_data.Authored in
  let cleanup = Cleanup.create () in
  let start () =
    let open Result.Let_syntax in
    let%bind () = Admitted_activation.Continuation.refresh continuation in
    let%bind snapshot =
      match Runtime_builder.Authored_start.manager startup with
      | None -> Ok None
      | Some manager ->
        Chat_response.Moderator_manager.identity_snapshot manager
        |> Result.map_error ~f:(error Invalid_state)
        |> Result.map ~f:Option.some
    in
    let%bind () = Admitted_activation.Continuation.refresh continuation in
    let%bind scope =
      Eio.Cancel.protect (fun () ->
        call t (Held_startup (Begin_authored (continuation, startup, cleanup, snapshot))))
    in
    let%bind () = refresh_held_authored t scope in
    let%bind () =
      Eio.Cancel.protect (fun () -> call t (Held_startup (Ready_authored scope)))
    in
    let claim ~event ~snapshot callback =
      with_event_tools
        t
        ~claim:(fun () ->
          let%bind snapshot = snapshot () in
          let%map () = refresh_held_authored t scope in
          Some
            (Held_startup
               (Claim_authored
                  (scope, Agent_protocol.Id.Moderator_execution.create (), snapshot, event))))
        callback
    in
    let%bind () = Runtime_builder.Authored_start.run startup ~claim in
    (match Runtime_builder.Authored_start.disposition startup with
     | Legacy_acknowledged -> Cleanup.record_legacy_acknowledgement cleanup
     | Extension_pending | No_callback -> ());
    let%bind () =
      match (Admitted_activation.Continuation.target scope.continuation).control with
      | Some _ -> Ok ()
      | None -> refresh_held_authored t scope
    in
    Eio.Cancel.protect (fun () -> call t (Held_startup (Finish_authored scope)))
  in
  match start () with
  | result ->
    Cleanup.record_producer_exit cleanup (Returned (Result.map result ~f:ignore));
    result
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    Cleanup.record_producer_exit cleanup (Raised (exn, backtrace));
    Exn.raise_with_original_backtrace exn backtrace
;;

let with_held_input t ~continuation ~prepare f =
  let open Result.Let_syntax in
  let%bind scope =
    Eio.Cancel.protect (fun () -> call t (Held_startup (Begin_input continuation)))
  in
  let final_check () =
    let%bind () = Held_input_scope.parsing scope in
    let%bind () = check_held_effect continuation in
    let%bind () = input_scope_basis t scope in
    Admitted_activation.Continuation.check_basis continuation
  in
  let refresh () =
    let%bind () = Held_input_scope.parsing scope in
    let%bind () = Admitted_activation.Continuation.refresh continuation in
    let%map () = final_check () in
    final_check
  in
  let checkpoint () =
    let%bind check = refresh () in
    check ()
  in
  let allocate_inference ~graph ~relation ~configuration =
    let%bind () = checkpoint () in
    (* The canonical allocation guard captures this actual Parsing scope and
       registration. Do not compose a second fresh-work gate after admission. *)
    inference_port t (Inference_held_input scope) ~graph ~relation ~configuration
  in
  let execution : Runtime_input_preparation.Execution.t =
    { request = scope.request; id = scope.id; checkpoint; refresh; allocate_inference }
  in
  scope.issued_execution <- Some execution;
  let cleanup () =
    (match scope.phase with
     | Parsing | Parsed_ready _ -> scope.phase <- Closed
     | Admission_pending _ | Consumed _ | Root_attempt_unconfirmed | Closed -> ());
    Eio.Cancel.protect (fun () -> call t (Held_startup (Close_input scope)))
  in
  let run () =
    let%bind () = checkpoint () in
    let%bind input = prepare ~scope execution in
    let%bind () = checkpoint () in
    let%bind () = call t (Held_startup (Ready_input (scope, input))) in
    f ~scope ~input
  in
  let record_producer_exit outcome =
    if Int.equal scope.domain (Stdlib.Domain.self () :> int)
    then Failed_startup_data.Input.record_producer_exit scope.cleanup outcome
  in
  match run () with
  | Ok value ->
    record_producer_exit (Actor_reply.Returned (Ok ()));
    let%map () = cleanup () in
    value
  | Error error as result ->
    record_producer_exit (Actor_reply.Returned (Error error));
    (try ignore (cleanup () : (unit, Agent_protocol.Error.t) result) with
     | _ -> ());
    result
  | exception exn ->
    let backtrace = Stdlib.Printexc.get_raw_backtrace () in
    record_producer_exit (Actor_reply.Raised (exn, backtrace));
    (try ignore (cleanup () : (unit, Agent_protocol.Error.t) result) with
     | _ -> ());
    Exn.raise_with_original_backtrace exn backtrace
;;

let install_runtime_construction
      ?unmoderated_source
      ?retained_lifecycle
      ?automatic_turn_policy
      ?moderator_manager
      t
      ~construction
      ~worker
      ~inference
  =
  let open Result.Let_syntax in
  let%bind () = check_retained_lifecycle_route construction retained_lifecycle in
  match construction with
  | Runtime_construction.Initial continuation ->
    install_held_runtime
      ?unmoderated_source
      ?automatic_turn_policy
      ?moderator_manager
      t
      ~continuation
      ~worker
      ~inference
  | Existing_goal _ | Delegated_load _ ->
    let open Result.Let_syntax in
    let%bind () = Runtime_construction.refresh construction in
    Eio.Cancel.protect (fun () ->
      let%bind () =
        match automatic_turn_policy with
        | None -> Ok ()
        | Some policy ->
          let%bind () =
            call t (Held_startup (Construction (Enable_budget (construction, policy))))
          in
          Runtime_construction.refresh construction
      in
      call
        t
        (Held_startup
           (Construction
              (Install
                 ( construction
                 , worker
                 , inference
                 , moderator_manager
                 , retained_lifecycle
                 , unmoderated_source )))))
;;

let run_goal_runtime_resume t ~continuation ~resume =
  let open Result.Let_syntax in
  let construction = Runtime_construction.Existing_goal continuation in
  let%bind () = Runtime_construction.refresh construction in
  let%bind scope =
    Eio.Cancel.protect (fun () ->
      call t (Held_startup (Construction (Begin_resume (continuation, resume)))))
  in
  let claim ~event ~snapshot callback =
    with_event_tools
      t
      ~claim:(fun () ->
        let%bind snapshot = snapshot () in
        let%map () = Runtime_construction.refresh construction in
        Some
          (Held_startup
             (Construction
                (Claim_resume
                   ( scope
                   , Agent_protocol.Id.Moderator_execution.create ()
                   , snapshot
                   , event )))))
      callback
  in
  let%bind () = Runtime_builder.Runtime_resume.run resume ~claim in
  Eio.Cancel.protect (fun () ->
    call t (Held_startup (Construction (Finish_resume scope))))
;;

let run_goal_execution_runtime_resume t ~execution ~resume =
  run_goal_runtime_resume t ~continuation:execution ~resume
;;

let acknowledge_goal_job_runtime t ~execution =
  let%bind.Result () =
    execution.Existing_goal_preparation.binding.preparation.registered_refresh ()
  in
  Eio.Cancel.protect (fun () ->
    call t (Held_startup (Goal_continuation (Acknowledge_job_resource execution))))
;;

let goal_job_runtime_services t ~execution =
  let open Result.Let_syntax in
  let%bind owner =
    match execution.Existing_goal_preparation.binding.preparation.cause with
    | Claimed_job { owner; _ } -> Ok owner
    | Resume_command _ | Pending_wake _ ->
      Error (error Invalid_request "runtime has no claimed Job services")
  in
  let%map () = check_job_runtime_owner t ~owner in
  job_execution_for_owner t owner
;;

let continue_goal_episode t ~continuation =
  let open Result.Let_syntax in
  let preparation = continuation.Goal_continuation.binding.preparation in
  let%bind () =
    match preparation.control, preparation.runtime_phase with
    | Some _, _ | None, (Retired _ | Handed_off _) -> Ok ()
    | None, _ -> Runtime_construction.refresh (Existing_goal continuation)
  in
  match submit_turn_input t (Inherited_turn.Input.Goal_resume continuation) with
  | Ok result -> Ok result
  | Error error ->
    Ok
      (Goal_resume_result.Resume_failed
         { receipt = Goal_continuation.receipt continuation; error })
;;

let runtime_construction_resource t ~construction ~owner =
  let%bind.Result () = Runtime_construction.refresh construction in
  call t (Held_startup (Construction (Resource (construction, owner))))
;;

let job_runtime_resource t ~owner ~worker ~inference ~moderator_manager =
  let open Result.Let_syntax in
  let%bind resource, scope =
    call
      t
      (Held_startup
         (Goal_continuation (Job_resource (owner, worker, inference, moderator_manager))))
  in
  (* Original callbacks/deadline sampling stay outside Owner and Actor mutexes.
     The final pure resource basis is not fresh execution permission. *)
  let%bind () = check_job_runtime_owner t ~owner in
  let%bind () = Run_admission.Scope.authorize scope t.state in
  let%bind () = Run_admission.Scope.check_current scope in
  (* Original authorization may yield past this Job scope's deadline. Resample
     after all callbacks, outside either mutex; the retained Owner basis stays
     callback- and clock-free. *)
  let%bind () = check_job_runtime_owner_internal t owner in
  let%map () = Runtime_construction_resource.check_basis resource in
  resource
;;

let end_runtime_construction t ~construction =
  call t ~priority:Priority (Held_startup (Construction (End construction)))
;;

let refresh_goal_wake execution = Runtime_construction.refresh (Existing_goal execution)

let enqueue_goal_wake_job_delivery t ~execution ~delivery ~before ~after =
  let%bind.Result () = refresh_goal_wake execution in
  call
    t
    (Held_startup
       (Goal_continuation (Enqueue_wake_job (execution, delivery, before, after))))
;;

let claim_goal_wake_schedule t ~execution ~schedule =
  let%bind.Result () = refresh_goal_wake execution in
  call t (Held_startup (Goal_continuation (Claim_wake_schedule (execution, schedule))))
;;

let complete_goal_wake_schedule
      t
      ~execution
      ~expected
      ~expected_schedule
      ~moderator_manager
      ~moderator_snapshot
  =
  let%bind.Result () = refresh_goal_wake execution in
  call
    t
    (Held_startup
       (Goal_continuation
          (Complete_wake_schedule
             ( execution
             , expected_schedule
             , expected
             , moderator_manager
             , moderator_snapshot ))))
;;

let deliver_goal_wake_job t ~execution ~job ~before ~after =
  let%bind.Result () = refresh_goal_wake execution in
  call
    t
    (Held_startup (Goal_continuation (Deliver_wake_job (execution, job, before, after))))
;;

let with_current_goal_wake_queued_event_tools t ~execution ~snapshot f =
  let%bind.Result () = refresh_goal_wake execution in
  with_event_tools
    t
    ~claim:(fun () ->
      let open Result.Let_syntax in
      let%bind snapshot = snapshot () in
      let%map () = refresh_goal_wake execution in
      match snapshot.Session.Moderator_state.Identity_snapshot.queued_internal_events with
      | [] -> None
      | _ :: _ ->
        Some
          (Held_startup
             (Goal_continuation
                (Claim_wake_event
                   (execution, Agent_protocol.Id.Moderator_execution.create (), snapshot)))))
    f
;;

let deliver_goal_wake_notifications t ~execution proposal =
  let%bind.Result () = refresh_goal_wake execution in
  submit_turn_input t (Inherited_turn.Input.Goal_subscription (execution, proposal))
;;

let finish_goal_wake_runtime t ~execution =
  call t (Held_startup (Goal_continuation (Finish_wake execution)))
;;

let reconcile_goal_wake_authority t ~request =
  call t (Held_startup (Goal_continuation (Reconcile_wake_authority request)))
;;
